'use client';

import { useState, useEffect } from 'react';
import { MainLayout } from '@/components/layout';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { authFetch } from '@/lib/auth-fetch';

interface ProfitRow {
  productId: number | string;
  revenue: number;
  directCost: number;
  overhead: number;
  grossMargin: number;
  netMargin: number;
}

export default function CostAnalysisPage() {
  const [_activeTab, _setActiveTab] = useState('profit');
  const [profitData, setProfitData] = useState<ProfitRow[]>([]);
  const [abcData, setAbcData] = useState<{ A: number[]; B: number[]; C: number[] }>({
    A: [],
    B: [],
    C: [],
  });

  useEffect(() => {
    authFetch('/api/advanced/cost-analysis', {
      method: 'POST',
      body: JSON.stringify({ action: 'profit-analysis' }),
    }).then(async (res) => {
      const data = await res.json();
      if (data.success) setProfitData(data.data);
    });
    authFetch('/api/advanced/cost-analysis', {
      method: 'POST',
      body: JSON.stringify({ action: 'abc-classification' }),
    }).then(async (res) => {
      const data = await res.json();
      if (data.success) setAbcData(data.data);
    });
  }, []);

  return (
    <MainLayout title="成本分析中心">
      <div className="space-y-6">
        <div className="grid grid-cols-3 gap-4">
          <Card>
            <CardHeader>
              <CardTitle>A 类物料</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{abcData.A.length}</div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader>
              <CardTitle>B 类物料</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{abcData.B.length}</div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader>
              <CardTitle>C 类物料</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{abcData.C.length}</div>
            </CardContent>
          </Card>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>产品利润分析</CardTitle>
          </CardHeader>
          <CardContent>
            <table className="w-full">
              <thead>
                <tr className="border-b">
                  <th className="text-left p-2">产品ID</th>
                  <th className="text-right p-2">收入</th>
                  <th className="text-right p-2">直接成本</th>
                  <th className="text-right p-2">间接费用</th>
                  <th className="text-right p-2">毛利率</th>
                  <th className="text-right p-2">净利率</th>
                </tr>
              </thead>
              <tbody>
                {profitData.map((p: ProfitRow) => (
                  <tr key={p.productId} className="border-b">
                    <td className="p-2">#{p.productId}</td>
                    <td className="text-right p-2">¥{Number(p.revenue).toLocaleString()}</td>
                    <td className="text-right p-2">¥{Number(p.directCost).toLocaleString()}</td>
                    <td className="text-right p-2">¥{Number(p.overhead).toLocaleString()}</td>
                    <td
                      className={`text-right p-2 ${p.grossMargin < 20 ? 'text-red-500' : 'text-green-500'}`}
                    >
                      {p.grossMargin.toFixed(1)}%
                    </td>
                    <td
                      className={`text-right p-2 ${p.netMargin < 10 ? 'text-red-500' : 'text-green-500'}`}
                    >
                      {p.netMargin.toFixed(1)}%
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </CardContent>
        </Card>
      </div>
    </MainLayout>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { MainLayout } from '@/components/layout';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { AlertCircle, AlertTriangle, Info } from 'lucide-react';
import { authFetch } from '@/lib/auth-fetch';

export default function AdvancedDashboardPage() {
  const [data, setData] = useState<{
    currentMonth: Record<string, number>;
    trend: Array<{ month: string; value: number }>;
    alerts: Array<{ level: 'critical' | 'warning' | 'info'; message: string }>;
  }>({ currentMonth: {}, trend: [], alerts: [] });

  useEffect(() => {
    authFetch('/api/advanced/dashboard').then(async (res) => {
      const result = await res.json();
      if (result.success) setData(result.data);
    });
  }, []);

  const alertIcons = { critical: AlertCircle, warning: AlertTriangle, info: Info };
  const alertVariants = {
    critical: 'destructive' as const,
    warning: 'default' as const,
    info: 'default' as const,
  };

  return (
    <MainLayout title="决策支持中心">
      <div className="space-y-6">
        {data.alerts.map((alert, idx) => {
          const Icon = alertIcons[alert.level];
          return (
            <Alert key={idx} variant={alertVariants[alert.level]}>
              <Icon className="h-4 w-4" />
              <AlertTitle>
                {alert.level === 'critical' ? '紧急' : alert.level === 'warning' ? '预警' : '提示'}
              </AlertTitle>
              <AlertDescription>{alert.message}</AlertDescription>
            </Alert>
          );
        })}

        <div className="grid grid-cols-4 gap-4">
          <Card>
            <CardHeader>
              <CardTitle className="text-sm">月销售收入</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                ¥{Number(data.currentMonth.revenue || 0).toLocaleString()}
              </div>
              <p className="text-xs text-muted-foreground">
                {data.currentMonth.orders || 0} 个订单
              </p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader>
              <CardTitle className="text-sm">订单完成率</CardTitle>
            </CardHeader>
            <CardContent>
              <div
                className={`text-2xl font-bold ${(data.currentMonth.fulfillmentRate || 0) < 95 ? 'text-red-500' : 'text-green-500'}`}
              >
                {Number(data.currentMonth.fulfillmentRate || 0).toFixed(1)}%
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader>
              <CardTitle className="text-sm">库存周转率</CardTitle>
            </CardHeader>
            <CardContent>
              <div
                className={`text-2xl font-bold ${(data.currentMonth.turnoverRate || 0) < 4 ? 'text-yellow-500' : 'text-green-500'}`}
              >
                {Number(data.currentMonth.turnoverRate || 0).toFixed(1)}x
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader>
              <CardTitle className="text-sm">库存价值</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                ¥{Number(data.currentMonth.inventoryValue || 0).toLocaleString()}
              </div>
            </CardContent>
          </Card>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>6 个月收入趋势</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {data.trend.map((item) => (
                <div key={item.month} className="flex items-center gap-4">
                  <span className="w-20 text-sm">{item.month}</span>
                  <div className="flex-1 h-6 bg-secondary rounded-full overflow-hidden">
                    <div
                      className="h-full bg-primary rounded-full transition-all"
                      style={{
                        width: `${Math.min(100, (Number(item.value) / Math.max(...data.trend.map((t) => Number(t.value)))) * 100)}%`,
                      }}
                    />
                  </div>
                  <span className="w-24 text-right text-sm">
                    ¥{Number(item.value).toLocaleString()}
                  </span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>智能建议</CardTitle>
          </CardHeader>
          <CardContent className="space-y-2 text-sm">
            {data.alerts.length === 0 && <p>当前无预警，运行状态良好</p>}
            {data.alerts.map((alert, idx) => (
              <div key={idx} className="flex items-start gap-2">
                <span className="mt-1">•</span>
                <span>{alert.message}</span>
              </div>
            ))}
          </CardContent>
        </Card>
      </div>
    </MainLayout>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { ScrollArea } from '@/components/ui/scroll-area';
import { useTranslations } from 'next-intl';

/* eslint-disable @next/next/no-img-element */

interface TableInfo {
  name: string;
  comment: string;
  rows: number;
}

interface Relation {
  fromTable: string;
  fromColumn: string;
  toTable: string;
  toColumn: string;
  type: string;
  constraint?: string;
}

interface ModuleData {
  [key: string]: TableInfo[];
}

interface DbRelations {
  tables: TableInfo[];
  foreignKeys: Relation[];
  logicalRelations: Relation[];
  modules: ModuleData;
}

export default function DbRelationsPage() {
  // 翻译钩子
  const tc = useTranslations('Common');

  const moduleColors: Record<string, string> = {
    system: 'bg-blue-500',
    order: 'bg-green-500',
    product: 'bg-yellow-500',
    partner: 'bg-purple-500',
    production: 'bg-cyan-500',
    inventory: 'bg-orange-500',
    finance: 'bg-pink-500',
    sample: 'bg-lime-500',
    other: 'bg-gray-500',
  };

  const moduleLabels: Record<string, string> = {
    system: '系统管理',
    order: '订单管理',
    product: '产品管理',
    partner: '合作伙伴',
    production: '生产管理',
    inventory: '库存管理',
    finance: '财务管理',
    sample: '样品管理',
    other: '其他',
  };

  const [data, setData] = useState<DbRelations | null>(null);
  const [loading, setLoading] = useState(true);
  const [selectedModule, setSelectedModule] = useState<string | null>(null);

  useEffect(() => {
    fetch('/api/db-relations')
      .then((res) => res.json())
      .then((data) => {
        setData(data);
        setLoading(false);
      })
      .catch((_err) => {
        setLoading(false);
      });
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">{tc('analysisLoading')}</p>
        </div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <p className="text-destructive">{tc('analysisLoadFailed')}</p>
      </div>
    );
  }

  const totalTables = data.tables.length;
  const totalForeignKeys = data.foreignKeys.length;
  const totalLogicalRelations = data.logicalRelations.length;

  return (
    <div className="container mx-auto py-6 space-y-6">
      {/* 页面标题 */}
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight">{tc('analysisPageTitle')}</h1>
        <p className="text-muted-foreground">
          {tc('analysisPageDescPrefix')}
          {totalTables}
          {tc('analysisPageDescSuffix')}
        </p>
      </div>

      {/* 统计卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">{tc('analysisTotalTables')}</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalTables}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">{tc('analysisFkTitle')}</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-red-500">{totalForeignKeys}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">{tc('analysisLogicalCardTitle')}</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-blue-500">{totalLogicalRelations}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">{tc('analysisModuleCount')}</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-500">
              {Object.keys(data.modules).length}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* 图表展示 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* 模块分布饼图 */}
        <Card>
          <CardHeader>
            <CardTitle>{tc('analysisModuleDistribution')}</CardTitle>
            <CardDescription>{tc('analysisModuleDistDesc')}</CardDescription>
          </CardHeader>
          <CardContent>
            <img
              src="https://mdn.alipayobjects.com/one_clip/afts/img/AW7BSbaam-gAAAAARSAAAAgAoEACAQFr/original"
              alt={tc('analysisModulePieAlt')}
              className="w-full h-auto"
            />
          </CardContent>
        </Card>

        {/* 关联数量柱状图 */}
        <Card>
          <CardHeader>
            <CardTitle>{tc('analysisTop20Relations')}</CardTitle>
            <CardDescription>{tc('analysisTopRelDesc')}</CardDescription>
          </CardHeader>
          <CardContent>
            <img
              src="https://mdn.alipayobjects.com/one_clip/afts/img/GnogTL6uYV8AAAAAQ0AAAAgAoEACAQFr/original"
              alt={tc('analysisRelBarAlt')}
              className="w-full h-auto"
            />
          </CardContent>
        </Card>
      </div>

      {/* 详细信息标签页 */}
      <Tabs defaultValue="modules" className="w-full">
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="modules">{tc('analysisModulesTab')}</TabsTrigger>
          <TabsTrigger value="tables">{tc('analysisAllTablesTab')}</TabsTrigger>
          <TabsTrigger value="foreignkeys">{tc('analysisFkTab')}</TabsTrigger>
          <TabsTrigger value="logical">{tc('analysisLogicalTab')}</TabsTrigger>
        </TabsList>

        {/* 模块分组 */}
        <TabsContent value="modules">
          <Card>
            <CardHeader>
              <CardTitle>{tc('analysisModulesTab')}</CardTitle>
              <CardDescription>{tc('analysisModuleGroupDesc')}</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {Object.entries(data.modules).map(([module, tables]) => (
                  <Card
                    key={module}
                    className={`cursor-pointer transition-all hover:shadow-lg ${selectedModule === module ? 'ring-2 ring-primary' : ''}`}
                    onClick={() => setSelectedModule(selectedModule === module ? null : module)}
                  >
                    <CardHeader className="pb-2">
                      <div className="flex items-center justify-between">
                        <CardTitle className="text-lg flex items-center gap-2">
                          <Badge className={moduleColors[module]}>
                            {moduleLabels[module] || module}
                          </Badge>
                        </CardTitle>
                        <Badge variant="outline">
                          {tables.length}
                          {tc('analysisTablesUnit')}
                        </Badge>
                      </div>
                    </CardHeader>
                    <CardContent>
                      <ScrollArea className="h-[200px]">
                        <div className="space-y-2">
                          {tables.map((table) => (
                            <div
                              key={table.name}
                              className="flex items-center justify-between p-2 rounded-lg hover:bg-muted"
                            >
                              <div className="flex-1 min-w-0">
                                <p className="font-medium truncate">{table.name}</p>
                                <p className="text-xs text-muted-foreground truncate">
                                  {table.comment || tc('analysisNoComment')}
                                </p>
                              </div>
                              <Badge variant="secondary" className="ml-2">
                                {table.rows}
                                {tc('analysisRowsSuffix')}
                              </Badge>
                            </div>
                          ))}
                        </div>
                      </ScrollArea>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* 所有表 */}
        <TabsContent value="tables">
          <Card>
            <CardHeader>
              <CardTitle>{tc('analysisAllTables')}</CardTitle>
              <CardDescription>
                {tc('analysisTotalPrefix')}
                {totalTables}
                {tc('analysisTableCount')}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{tc('analysisTableName')}</TableHead>
                    <TableHead>{tc('analysisTableComment')}</TableHead>
                    <TableHead>{tc('analysisRowCount')}</TableHead>
                    <TableHead>{tc('analysisTableModule')}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {data.tables.map((table) => {
                    const moduleName =
                      Object.entries(data.modules).find(([, tables]) =>
                        tables.some((t) => t.name === table.name)
                      )?.[0] || 'other';

                    return (
                      <TableRow key={table.name}>
                        <TableCell className="font-medium">{table.name}</TableCell>
                        <TableCell>{table.comment || '-'}</TableCell>
                        <TableCell>{table.rows}</TableCell>
                        <TableCell>
                          <Badge className={moduleColors[moduleName]}>
                            {moduleLabels[moduleName] || moduleName}
                          </Badge>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        {/* 外键关系 */}
        <TabsContent value="foreignkeys">
          <Card>
            <CardHeader>
              <CardTitle>{tc('analysisFkTitle')}</CardTitle>
              <CardDescription>
                {tc('analysisTotalPrefix')}
                {totalForeignKeys}
                {tc('analysisFkCount')}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {totalForeignKeys === 0 ? (
                <p className="text-muted-foreground text-center py-8">{tc('analysisNoFk')}</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>{tc('analysisFromTable')}</TableHead>
                      <TableHead>{tc('analysisFromColumn')}</TableHead>
                      <TableHead>{tc('analysisToTable')}</TableHead>
                      <TableHead>{tc('analysisToColumn')}</TableHead>
                      <TableHead>{tc('analysisConstraint')}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {data.foreignKeys.map((fk, index) => (
                      <TableRow key={index}>
                        <TableCell className="font-medium">{fk.fromTable}</TableCell>
                        <TableCell>{fk.fromColumn}</TableCell>
                        <TableCell className="font-medium text-red-500">{fk.toTable}</TableCell>
                        <TableCell>{fk.toColumn}</TableCell>
                        <TableCell>
                          <Badge variant="outline">{fk.constraint}</Badge>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* 逻辑关联 */}
        <TabsContent value="logical">
          <Card>
            <CardHeader>
              <CardTitle>{tc('analysisLogicalTitle')}</CardTitle>
              <CardDescription>
                {tc('analysisLogicalDesc')}
                {totalLogicalRelations}个
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{tc('analysisFromTable')}</TableHead>
                    <TableHead>{tc('analysisLogicalFromColumn')}</TableHead>
                    <TableHead>{tc('analysisToTable')}</TableHead>
                    <TableHead>{tc('analysisToColumn')}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {data.logicalRelations.map((rel, index) => (
                    <TableRow key={index}>
                      <TableCell className="font-medium">{rel.fromTable}</TableCell>
                      <TableCell>
                        <Badge variant="secondary">{rel.fromColumn}</Badge>
                      </TableCell>
                      <TableCell className="font-medium text-blue-500">{rel.toTable}</TableCell>
                      <TableCell>{rel.toColumn}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

