function Sparkline({
  data,
  color = C.cyan,
  height = 60,
}: {
  data: number[];
  color?: string;
  height?: number;
}) {
  if (data.length < 2)
    return (
      <div className="flex items-center justify-center text-white/20 text-xs" style={{ height }}>
        —
      </div>
    );
  const max = Math.max(...data, 1);
  const min = Math.min(...data, 0);
  const range = max - min || 1;
  const w = 100;
  const pts = data
    .map(
      (v, i) => `${(i / (data.length - 1)) * w},${height - ((v - min) / range) * (height - 8) - 4}`
    )
    .join(' ');
  return (
    <svg viewBox={`0 0 ${w} ${height}`} className="w-full" style={{ height }}>
      <polygon points={`0,${height} ${pts} ${w},${height}`} fill={color} opacity={0.08} />
      <polyline
        points={pts}
        fill="none"
        stroke={color}
        strokeWidth={1.5}
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  );
}

/* ═══ 环形进度 ═══ */
function RingProgress({
  value,
  label,
  color = C.cyan,
  size = 72,
}: {
  value: number;
  label: string;
  color?: string;
  size?: number;
}) {
  const r = size / 2 - 5;
  const circ = 2 * Math.PI * r;
  const offset = circ - (value / 100) * circ;
  return (
    <div className="flex flex-col items-center gap-1">
      <div className="relative" style={{ width: size, height: size }}>
        <svg width={size} height={size} className="-rotate-90">
          <circle
            cx={size / 2}
            cy={size / 2}
            r={r}
            fill="none"
            stroke="rgba(255,255,255,0.06)"
            strokeWidth={5}
          />
          <circle
            cx={size / 2}
            cy={size / 2}
            r={r}
            fill="none"
            stroke={color}
            strokeWidth={5}
            strokeDasharray={circ}
            strokeDashoffset={offset}
            strokeLinecap="round"
            style={{
              filter: `drop-shadow(0 0 4px ${color}88)`,
              transition: 'stroke-dashoffset 1s ease',
            }}
          />
        </svg>
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-lg font-bold" style={{ color }}>
            {value}%
          </span>
        </div>
      </div>
      <span className="text-xs" style={{ color: C.silver + '88' }}>
        {label}
      </span>
    </div>
  );
}

/* ═══ 滚动预警条 ═══ */
function AlertTicker({ alerts }: { alerts: { level: string; msg: string }[] }) {
  const list =
    alerts.length > 0
      ? alerts
      : [
          { level: 'info', msg: '系统运行正常，所有产线在线' },
          { level: 'warning', msg: '原材料仓库 B-3 区油墨库存偏低，建议补货' },
          { level: 'info', msg: '今日已完成 3 批次出货，合计 12,500 PCS' },
          { level: 'warning', msg: '设备 SP-003 计划保养倒计时 2 天' },
          { level: 'success', msg: '客户「深圳电子」追加订单已确认，交期 7/28' },
        ];
  return (
    <div
      className="flex items-center gap-2 overflow-hidden"
      style={{
        background: 'rgba(10,30,61,0.9)',
        border: `1px solid ${C.silver}11`,
        borderRadius: '8px',
