'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useEffect, useState, useRef } from 'react';
import { MainLayout } from '@/components/layout';
import { useCompanyName } from '@/hooks/useCompanyName';
import GlassGauge from '@/components/GlassGauge';
import {
  TrendingUp,
  TrendingDown,
  CheckCircle,
  AlertTriangle,
  PlayCircle,
  BarChart3,
  Activity,
  Users,
  Package,
  Settings,
  Maximize,
  Minimize,
  Target,
} from 'lucide-react';
import { useTranslations, useLocale } from 'next-intl';

interface ProductionData {
  overview: {
    totalOrders: number;
    activeOrders: number;
    completedToday: number;
    efficiency: number;
    oee: number;
    qualityRate: number;
  };
  equipmentStatus: {
    id: string;
    name: string;
    type: string;
    status: string;
    efficiency: number;
    currentOrder: string;
    operator: string;
    runtime: number;
  }[];
  productionProgress: {
    orderNo: string;
    customer: string;
    productName: string;
    process: string;
    progress: number;
    planQty: number;
    completedQty: number;
    status: string;
    priority: string;
    estimatedComplete: string;
  }[];
  efficiencyTrend: { time: string; efficiency: number; target: number }[];
  alerts: { id: string; type: string; message: string; severity: string; timestamp: string }[];
  staffStatus: { total: number; onDuty: number; onLeave: number; attendance: number };
}

const STATUS_MAP: Record<string, { labelKey: string; className: string }> = {
  running: {
    labelKey: 'running',
    className: 'bg-green-500/20 text-green-300 border border-green-500/30',
  },
  idle: {
    labelKey: 'standby',
    className: 'bg-amber-500/20 text-amber-300 border border-amber-500/30',
  },
  maintenance: {
    labelKey: 'underMaintenance',
    className: 'bg-blue-500/20 text-blue-300 border border-blue-500/30',
  },
  error: { labelKey: 'fault', className: 'bg-red-500/20 text-red-300 border border-red-500/30' },
};

const PRIORITY_MAP: Record<string, { labelKey: string; className: string }> = {
  high: { labelKey: 'high', className: 'bg-red-500/20 text-red-300 border border-red-500/30' },
  medium: {
    labelKey: 'medium',
    className: 'bg-amber-500/20 text-amber-300 border border-amber-500/30',
  },
  low: { labelKey: 'low', className: 'bg-blue-500/20 text-blue-300 border border-blue-500/30' },
};

function AutoScroll({
  children,
  maxHeight = 320,
  _speed = 50,
}: {
  children: React.ReactNode;
  maxHeight?: number;
  _speed?: number;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const innerRef = useRef<HTMLDivElement>(null);
  const [isPaused, setIsPaused] = useState(false);

  useEffect(() => {
    const container = containerRef.current;
    const inner = innerRef.current;
    if (!container || !inner) return;

    let animId: number;
    let scrollPos = 0;
    const contentHeight = inner.scrollHeight / 2;
    const viewportHeight = maxHeight;

    if (contentHeight <= viewportHeight) return;

    const step = () => {
      if (!isPaused) {
        scrollPos += 0.3;
        if (scrollPos >= contentHeight) {
          scrollPos = 0;
        }
        container.scrollTop = scrollPos;
      }
      animId = requestAnimationFrame(step);
    };

    animId = requestAnimationFrame(step);
    return () => cancelAnimationFrame(animId);
  }, [isPaused, maxHeight, children]);

  return (
    <div
      ref={containerRef}
      className="overflow-hidden"
      style={{ maxHeight: `${maxHeight}px` }}
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      <div ref={innerRef}>
        {children}
        {children}
      </div>
    </div>
  );
}

