'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useEffect, useState, useRef } from 'react';
import { MainLayout } from '@/components/layout';
import { useCompanyName } from '@/hooks/useCompanyName';
import {
  FileText,
  DollarSign,
  Users,
  Package,
  TrendingUp,
  ShoppingCart,
  BarChart3,
  Maximize,
  Minimize,
  PieChart,
} from 'lucide-react';
import { useTranslations, useLocale } from 'next-intl';

interface SalesData {
  overview: {
    totalOrders: number;
    todayOrders: number;
    monthRevenue: number;
    pendingDelivery: number;
    completedOrders: number;
    orderChange: number;
  };
  orderTrend: { date: string; count: number; amount: number }[];
  topCustomers: { customer_name: string; order_count: number; total_amount: number }[];
  topProducts: { product_name: string; total_qty: number; total_amount: number }[];
  recentOrders: {
    id: number;
    order_no: string;
    customer_name: string;
    total_amount: number;
    status: number;
    delivery_date: string;
    create_time: string;
  }[];
  statusDistribution: { status: number; count: number }[];
}

interface ChartDataItem {
  [key: string]: string | number;
}

function LineChart({
  data,
  width = 400,
  height = 150,
}: {
  data: { date: string; count: number; amount: number }[];
  width?: number;
  height?: number;
}) {
  if (data.length === 0) return null;
  const padding = { top: 20, right: 20, bottom: 30, left: 40 };
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;
  const maxVal = Math.max(...data.map((d) => d.count), 1);
  const getX = (i: number) => padding.left + (i / (data.length - 1 || 1)) * chartWidth;
  const getY = (val: number) => padding.top + chartHeight - (val / maxVal) * chartHeight;
  const path = data.map((d, i) => `${i === 0 ? 'M' : 'L'} ${getX(i)} ${getY(d.count)}`).join(' ');
  const areaPath = `${padding.left},${chartHeight + padding.top} ${path} ${getX(data.length - 1)},${chartHeight + padding.top}`;

  return (
    <svg width={width} height={height} className="w-full">
      <defs>
        <linearGradient id="salesAreaGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#06b6d4" stopOpacity="0.3" />
          <stop offset="100%" stopColor="#06b6d4" stopOpacity="0" />
        </linearGradient>
      </defs>
      {[0, 0.25, 0.5, 0.75, 1].map((ratio, i) => (
        <g key={i}>
          <line
            x1={padding.left}
            y1={padding.top + chartHeight * ratio}
            x2={width - padding.right}
            y2={padding.top + chartHeight * ratio}
            stroke="rgba(255,255,255,0.1)"
            strokeDasharray="4 4"
          />
          <text
            x={padding.left - 5}
            y={padding.top + chartHeight * ratio + 4}
            textAnchor="end"
            fill="rgba(255,255,255,0.5)"
            fontSize="10"
          >
            {Math.round(maxVal * (1 - ratio))}
          </text>
        </g>
      ))}
      {data
        .filter((_, i) => i % Math.ceil(data.length / 6) === 0 || i === data.length - 1)
        .map((d, i) => {
          const idx = data.indexOf(d);
          return (
            <text
              key={i}
              x={getX(idx)}
              y={height - 5}
              textAnchor="middle"
              fill="rgba(255,255,255,0.5)"
              fontSize="10"
            >
              {d.date?.substring(5)}
            </text>
          );
        })}
      <polygon points={areaPath} fill="url(#salesAreaGrad)" />
      <path d={path} fill="none" stroke="#06b6d4" strokeWidth="2" strokeLinecap="round" />
      {data.map((d, i) => (
        <circle key={i} cx={getX(i)} cy={getY(d.count)} r="3" fill="#06b6d4" />
      ))}
    </svg>
  );
}

function HorizontalBarChart({
  data,
  valueKey,
  labelKey,
  unknownText,
}: {
  data: ChartDataItem[];
  valueKey: string;
  labelKey: string;
  unknownText: string;
}) {
  if (data.length === 0) return null;
  const maxVal = Math.max(...data.map((d) => Number(d[valueKey]) || 0), 1);
  return (
    <div className="space-y-3">
      {data.slice(0, 5).map((d, i) => (
        <div key={i} className="flex items-center gap-3">
          <span className="text-xs w-24 text-right text-cyan-300 truncate">
            {d[labelKey] || unknownText}
          </span>
          <div className="flex-1 bg-white/10 rounded-full h-5 relative overflow-hidden">
            <div
              className="h-full rounded-full transition-all duration-500"
              style={{
                width: `${(Number(d[valueKey]) / maxVal) * 100}%`,
                background: 'linear-gradient(90deg, #06b6d4, #3b82f6)',
              }}
            />
            <span className="absolute inset-0 flex items-center justify-center text-xs font-medium text-white">
              {typeof d[valueKey] === 'number' ? d[valueKey].toLocaleString() : d[valueKey]}
            </span>
          </div>
        </div>
      ))}
    </div>
  );
}

const STATUS_MAP: Record<number, { labelKey: string; className: string }> = {
  0: { labelKey: 'draft', className: 'bg-gray-500/20 text-gray-300 border border-gray-500/30' },
  1: { labelKey: 'confirmed', className: 'bg-blue-500/20 text-blue-300 border border-blue-500/30' },
  2: {
    labelKey: 'inProduction',
    className: 'bg-orange-500/20 text-orange-300 border border-orange-500/30',
  },
  3: {
    labelKey: 'completed',
    className: 'bg-green-500/20 text-green-300 border border-green-500/30',
  },
  4: { labelKey: 'cancelled', className: 'bg-red-500/20 text-red-300 border border-red-500/30' },
};

export default function SalesDashboard() {
  // 翻译钩子
  const t = useTranslations('Dashboard');
  const tc = useTranslations('Common');
  const locale = useLocale();

  const { companyName } = useCompanyName();
  const [data, setData] = useState<SalesData>({
    overview: {
      totalOrders: 0,
      todayOrders: 0,
      monthRevenue: 0,
      pendingDelivery: 0,
      completedOrders: 0,
      orderChange: 0,
    },
    orderTrend: [],
    topCustomers: [],
    topProducts: [],
    recentOrders: [],
    statusDistribution: [],
  });
  const [loading, setLoading] = useState(true);
  const [currentTime, setCurrentTime] = useState<Date | null>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const dashboardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const res = await authFetch('/api/dashboard/sales');
        const result = await res.json();
        if (result.success && result.data) setData(result.data);
      } catch {
      } finally {
        setLoading(false);
      }
    };
    fetchData();
    setCurrentTime(new Date());
    const timer1 = setInterval(fetchData, 60000);
    const timer2 = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => {
      clearInterval(timer1);
      clearInterval(timer2);
    };
  }, []);

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      dashboardRef.current?.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  useEffect(() => {
    const handleFullscreenChange = () => setIsFullscreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const formatTime = (date: Date) =>
    date.toLocaleString(locale, {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
    });
  const formatMoney = (v: number) =>
    '¥' + (v / 100).toLocaleString(locale, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return (
    <MainLayout>
      <div
        ref={dashboardRef}
        className="min-h-screen text-white p-4 relative overflow-hidden"
        style={{ background: 'linear-gradient(135deg, #091637 0%, #010205 100%)' }}
      >
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          <div className="absolute top-0 left-0 w-96 h-96 bg-cyan-500/5 rounded-full blur-3xl animate-blob" />
          <div className="absolute bottom-0 right-0 w-96 h-96 bg-blue-500/5 rounded-full blur-3xl animate-blob animation-delay-2000" />
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/5 rounded-full blur-3xl animate-blob animation-delay-4000" />
        </div>
        <div className="absolute inset-0 tech-grid-bg pointer-events-none" />

        <div className="relative z-10 flex flex-col items-center mb-3">
          <div className="tech-title-wrapper">
            <div className="tech-title-row">
              <div className="tech-title-line-left" />
              <div>
                <h1 className="text-lg font-bold tracking-wider bg-gradient-to-r from-cyan-300 via-blue-400 to-cyan-300 bg-clip-text text-transparent">
                  {companyName}
                </h1>
                <p className="text-[10px] text-white/50">{t('salesBoard')}</p>
              </div>
              <div className="tech-title-line-right" />
            </div>
            <div className="tech-title-bottom-line" />
          </div>
          <div className="flex items-center gap-3 mt-1.5">
            <div className="text-sm font-mono font-bold text-cyan-400">
              {currentTime && formatTime(currentTime)}
            </div>
            <button
              onClick={toggleFullscreen}
              className="p-1.5 rounded-lg bg-white/10 hover:bg-white/20 transition-colors"
              title={isFullscreen ? t('exitFullscreen') : t('fullscreen')}
            >
              {isFullscreen ? (
                <Minimize className="h-3.5 w-3.5 text-cyan-400" />
              ) : (
                <Maximize className="h-3.5 w-3.5 text-cyan-400" />
              )}
            </button>
            <div className="px-2 py-0.5 rounded-full bg-cyan-500/20 border border-cyan-500/30 text-[10px] text-cyan-300">
              {loading ? tc('loading') : '● ' + t('realtime')}
            </div>
          </div>
        </div>

        <div className="relative z-10 grid grid-cols-2 md:grid-cols-5 gap-4 mb-6">
          {[
            {
              title: t('totalOrders'),
              value: data.overview.totalOrders,
              icon: FileText,
              color: 'from-cyan-500 to-blue-500',
            },
            {
              title: t('todayOrders'),
              value: data.overview.todayOrders,
              icon: ShoppingCart,
              color: 'from-green-500 to-emerald-500',
            },
            {
              title: t('monthlyRevenue'),
              value: formatMoney(data.overview.monthRevenue),
              icon: DollarSign,
              color: 'from-emerald-500 to-teal-500',
            },
            {
              title: t('pendingDelivery'),
              value: data.overview.pendingDelivery,
              icon: Package,
              color: 'from-orange-500 to-amber-500',
            },
            {
              title: tc('completed'),
              value: data.overview.completedOrders,
              icon: TrendingUp,
              color: 'from-purple-500 to-pink-500',
            },
          ].map((s, i) => (
            <div key={i} className={`tech-card tech-glow tech-card-delay-${i + 1} p-4`}>
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-xs text-white/60">{s.title}</p>
                  <p className="text-xl font-bold mt-1 bg-gradient-to-r from-cyan-300 to-blue-300 bg-clip-text text-transparent">
                    {s.value}
                  </p>
                </div>
                <div className={`p-3 rounded-lg bg-gradient-to-br ${s.color}`}>
                  <s.icon className="h-5 w-5 text-white" />
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="relative z-10 grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
          <div className="tech-card tech-glow p-5">
            <h3 className="text-sm font-semibold text-cyan-300 mb-4 flex items-center gap-2">
              <BarChart3 className="h-4 w-4" />
              {t('orderTrend')}
            </h3>
            {data.orderTrend.length === 0 ? (
              <p className="text-white/40 text-center py-8">{tc('noData')}</p>
            ) : (
              <LineChart data={data.orderTrend} width={600} height={200} />
            )}
          </div>

          <div className="tech-card tech-glow p-5">
            <h3 className="text-sm font-semibold text-cyan-300 mb-4 flex items-center gap-2">
              <PieChart className="h-4 w-4" />
              {t('orderStatusDistribution')}
            </h3>
            {data.statusDistribution.length === 0 ? (
              <p className="text-white/40 text-center py-8">{tc('noData')}</p>
            ) : (
              <div className="space-y-4">
                {data.statusDistribution.map((s, i) => {
                  const total = data.statusDistribution.reduce((a, b) => a + b.count, 0);
                  const pct = total > 0 ? Math.round((s.count / total) * 100) : 0;
                  const cfg = STATUS_MAP[s.status] || {
                    labelKey: 'unknown',
                    className: 'bg-gray-500/20 text-gray-300 border border-gray-500/30',
                  };
                  return (
                    <div key={i}>
                      <div className="flex justify-between text-sm mb-1">
                        <span className={`px-2 py-0.5 rounded text-xs ${cfg.className}`}>
                          {tc(cfg.labelKey)}
                        </span>
                        <span className="text-white/50">
                          {s.count}
                          {tc('percentSign')}
                          {pct}%)
                        </span>
                      </div>
                      <div className="bg-white/10 rounded-full h-3 relative overflow-hidden">
                        <div
                          className="h-full rounded-full transition-all"
                          style={{
                            width: `${pct}%`,
                            background: 'linear-gradient(90deg, #06b6d4, #3b82f6)',
                          }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        <div className="relative z-10 grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
          <div className="tech-card tech-glow p-5">
            <h3 className="text-sm font-semibold text-cyan-300 mb-4 flex items-center gap-2">
              <Users className="h-4 w-4" />
              {t('customerTop5')}
            </h3>
            {data.topCustomers.length === 0 ? (
              <p className="text-white/40 text-center py-8">{tc('noData')}</p>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-white/10">
                      <th className="text-left py-2 px-3 text-white/60 font-medium">
                        {tc('rank')}
                      </th>
                      <th className="text-left py-2 px-3 text-white/60 font-medium">
                        {tc('customerName')}
                      </th>
                      <th className="text-left py-2 px-3 text-white/60 font-medium">
                        {tc('orderCount')}
                      </th>
                      <th className="text-left py-2 px-3 text-white/60 font-medium">
                        {tc('totalAmount')}
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.topCustomers.map((c, i) => (
                      <tr
                        key={i}
                        className="border-b border-white/5 hover:bg-white/5 transition-colors"
                      >
                        <td className="py-2 px-3 text-cyan-400 font-bold text-xs">{i + 1}</td>
                        <td className="py-2 px-3 text-white/80 text-xs">{c.customer_name}</td>
                        <td className="py-2 px-3 text-white/60 text-xs">{c.order_count}</td>
                        <td className="py-2 px-3 text-cyan-300 font-medium text-xs">
                          {formatMoney(c.total_amount)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          <div className="tech-card tech-glow p-5">
            <h3 className="text-sm font-semibold text-cyan-300 mb-4 flex items-center gap-2">
              <Package className="h-4 w-4" />
              {t('productTop5')}
            </h3>
            {data.topProducts.length === 0 ? (
              <p className="text-white/40 text-center py-8">{tc('noData')}</p>
            ) : (
              <HorizontalBarChart
                data={data.topProducts}
                valueKey="total_qty"
                labelKey="product_name"
                unknownText={tc('unknown')}
              />
            )}
          </div>
        </div>

        <div className="relative z-10 tech-card tech-glow p-5">
          <h3 className="text-sm font-semibold text-cyan-300 mb-4 flex items-center gap-2">
            <FileText className="h-4 w-4" />
            {t('recentOrders')}
          </h3>
          {data.recentOrders.length === 0 ? (
            <p className="text-white/40 text-center py-8">{tc('noRecords')}</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-white/10">
                    <th className="text-left py-2 px-3 text-white/60 font-medium">
                      {tc('orderNo')}
                    </th>
                    <th className="text-left py-2 px-3 text-white/60 font-medium">
                      {tc('customerName')}
                    </th>
                    <th className="text-left py-2 px-3 text-white/60 font-medium">
                      {tc('amount')}
                    </th>
                    <th className="text-left py-2 px-3 text-white/60 font-medium">
                      {tc('status')}
                    </th>
                    <th className="text-left py-2 px-3 text-white/60 font-medium">
                      {tc('deliveryDate')}
                    </th>
                    <th className="text-left py-2 px-3 text-white/60 font-medium">
                      {tc('createdAt')}
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {data.recentOrders.map((o, i) => {
                    const cfg = STATUS_MAP[o.status] || {
                      labelKey: 'unknown',
                      className: 'bg-gray-500/20 text-gray-300 border border-gray-500/30',
                    };
                    return (
                      <tr
                        key={i}
                        className="border-b border-white/5 hover:bg-white/5 transition-colors"
                      >
                        <td className="py-2 px-3 font-mono text-cyan-300 text-xs">{o.order_no}</td>
                        <td className="py-2 px-3 text-white/80 text-xs">{o.customer_name}</td>
                        <td className="py-2 px-3 text-cyan-300 font-medium text-xs">
                          {formatMoney(o.total_amount)}
                        </td>
                        <td className="py-2 px-3">
                          <span className={`px-2 py-0.5 rounded text-xs ${cfg.className}`}>
                            {tc(cfg.labelKey)}
                          </span>
                        </td>
                        <td className="py-2 px-3 text-white/50 text-xs">
                          {o.delivery_date?.substring(0, 10) || '-'}
                        </td>
                        <td className="py-2 px-3 text-white/50 text-xs">
                          {o.create_time?.substring(5, 16)}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </MainLayout>
  );
}

