'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useEffect, useState } from 'react';
import { MainLayout } from '@/components/layout';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Plus, Search, Edit, Trash2, History, Activity } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { useTranslations } from 'next-intl';

interface ScreenPlate {
  id: number;
  plate_code: string;
  plate_name: string;
  plate_type: number;
  mesh_count: string;
  mesh_material: string;
  size: string;
  tension_value: number;
  frame_type: string;
  customer_id: number;
  customer_name: string;
  max_use_count: number;
  life_count: number;
  remaining_count: number;
  reclaim_count: number;
  status: number;
  warehouse_name: string;
  location_name: string;
  storage_location: string;
  scrap_reason: string;
  exposure_date: string;
  last_used_date: string;
  last_clean_date: string;
  last_reclaim_date: string;
  tension_date: string;
  remark: string;
  create_time: string;
}

interface HistoryRecord {
  id: number;
  screen_plate_id: number;
  action: string;
  tension_value: number;
  life_increment: number;
  remark: string;
  operator_name: string;
  created_at: string;
}

const typeMap: Record<number, string> = {
  1: '丝网版',
  2: '胶印版',
  3: '柔版',
  4: '凹版',
};
const statusMap: Record<
  number,
  { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline' }
> = {
  1: { label: '新制', variant: 'default' },
  2: { label: '可用', variant: 'default' },
  3: { label: '已曝光', variant: 'secondary' },
  4: { label: '生产中', variant: 'default' },
  5: { label: '清洗中', variant: 'outline' },
  6: { label: '已再生', variant: 'secondary' },
  7: { label: '损坏', variant: 'destructive' },
  8: { label: '已报废', variant: 'destructive' },
};
const actionMap: Record<string, string> = {
  Created: '创建',
  Exposed: '曝光',
  Printed: '印刷',
  Cleaned: '清洗',
  Reclaimed: '再生',
  Scrapped: '报废',
  TensionAdjusted: '张力调整',
};

export default function ScreenPlatePage() {
  // 翻译钩子
  const tc = useTranslations('Common');

  const { toast } = useToast();
  const [list, setList] = useState<ScreenPlate[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [searchCode, setSearchCode] = useState('');
  const [searchStatus, setSearchStatus] = useState('');
  const [showDialog, setShowDialog] = useState(false);
  const [showHistoryDialog, setShowHistoryDialog] = useState(false);
  const [editItem, setEditItem] = useState<Partial<ScreenPlate>>({});
  const [historyList, setHistoryList] = useState<HistoryRecord[]>([]);
  const [currentPlateId, setCurrentPlateId] = useState<number | null>(null);
  const [lifeAction, setLifeAction] = useState('');
  const [lifeRemark, setLifeRemark] = useState('');
  const [lifeTension, setLifeTension] = useState('');
  const [lifeIncrement, setLifeIncrement] = useState('');

  const fetchData = async () => {
    try {
      const params = new URLSearchParams({ page: String(page), pageSize: '20' });
      if (searchCode) params.set('plateCode', searchCode);
      if (searchStatus) params.set('status', searchStatus);
      const res = await authFetch('/api/screen-plates?' + params);
      const result = await res.json();
      if (result.success) {
        setList(result.data.list || []);
        setTotal(result.data.total || 0);
      }
    } catch {}
  };

  useEffect(() => {
    fetchData();
  }, [page]);

  const fetchHistory = async (plateId: number) => {
    try {
      const res = await authFetch(`/api/screen-plates/history?plateId=${plateId}`);
      const result = await res.json();
      if (result.success) {
        setHistoryList(result.data || []);
      }
    } catch {}
  };

  const handleSave = async () => {
    try {
      const method = editItem.id ? 'PUT' : 'POST';
      const res = await authFetch('/api/screen-plates', {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...editItem, operatorName: '系统' }),
      });
      const result = await res.json();
      if (result.success) {
        toast({ title: editItem.id ? '更新成功' : '创建成功' });
        setShowDialog(false);
        fetchData();
      } else {
        toast({ title: '失败', description: result.message, variant: 'destructive' });
      }
    } catch {
      toast({ title: '失败', variant: 'destructive' });
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm('确定删除？')) return;
    try {
      const res = await authFetch('/api/screen-plates?id=' + id, { method: 'DELETE' });
      const result = await res.json();
      if (result.success) {
        toast({ title: '删除成功' });
        fetchData();
      }
    } catch {
      toast({ title: '失败', variant: 'destructive' });
    }
  };

  const handleViewHistory = async (id: number) => {
    setCurrentPlateId(id);
    await fetchHistory(id);
    setShowHistoryDialog(true);
  };

  const handleAddLifeRecord = async () => {
    if (!currentPlateId || !lifeAction) {
      toast({ title: '请选择操作类型', variant: 'destructive' });
      return;
    }
    try {
      const res = await authFetch('/api/screen-plates/history', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          plateId: currentPlateId,
          action: lifeAction,
          tensionValue: lifeTension ? parseFloat(lifeTension) : undefined,
          lifeIncrement: lifeIncrement ? parseInt(lifeIncrement) : 0,
          remark: lifeRemark,
          operatorName: '系统',
        }),
      });
      const result = await res.json();
      if (result.success) {
        toast({ title: '记录成功' });
        setLifeAction('');
        setLifeRemark('');
        setLifeTension('');
        setLifeIncrement('');
        fetchHistory(currentPlateId);
        fetchData();
      } else {
        toast({ title: '失败', description: result.message, variant: 'destructive' });
      }
    } catch {
      toast({ title: '失败', variant: 'destructive' });
    }
  };

  return (
    <MainLayout>
      <div className="p-6 space-y-6">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold">网版管理</h1>
          <div className="flex gap-2">
            <div className="flex items-center gap-2">
              <Input
                placeholder={tc('code')}
                value={searchCode}
                onChange={(e) => setSearchCode(e.target.value)}
                className="w-28 h-8 text-sm"
              />
              <Select value={searchStatus} onValueChange={setSearchStatus}>
                <SelectTrigger className="w-24 h-8 text-sm">
                  <SelectValue placeholder={tc('status')} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">{tc('all')}</SelectItem>
                  {Object.entries(statusMap).map(([k, v]) => (
                    <SelectItem key={k} value={k}>
                      {v.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button size="sm" variant="outline" onClick={fetchData}>
                <Search className="h-3 w-3" />
              </Button>
            </div>
            <Button
              size="sm"
              onClick={() => {
                setEditItem({});
                setShowDialog(true);
              }}
            >
              <Plus className="h-3 w-3 mr-1" />
              新增网版
            </Button>
          </div>
        </div>

        <Card>
          <CardContent className="p-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-xs">网版编码</TableHead>
                  <TableHead className="text-xs">网版名称</TableHead>
                  <TableHead className="text-xs">{tc('type')}</TableHead>
                  <TableHead className="text-xs">目数</TableHead>
                  <TableHead className="text-xs">{tc('size')}</TableHead>
                  <TableHead className="text-xs">{tc('customer')}</TableHead>
                  <TableHead className="text-xs">{tc('dcLifeCountHead')}</TableHead>
                  <TableHead className="text-xs">{tc('dcReclaimCountHead')}</TableHead>
                  <TableHead className="text-xs">{tc('dcTensionHead')}</TableHead>
                  <TableHead className="text-xs">{tc('status')}</TableHead>
                  <TableHead className="text-xs">{tc('actions')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {list.map((item) => {
                  const st = statusMap[item.status] || statusMap[1];
                  const warn = item.remaining_count <= item.max_use_count * 0.2;
                  return (
                    <TableRow key={item.id}>
                      <TableCell className="text-xs font-mono">{item.plate_code}</TableCell>
                      <TableCell className="text-xs">{item.plate_name}</TableCell>
                      <TableCell className="text-xs">{typeMap[item.plate_type] || '-'}</TableCell>
                      <TableCell className="text-xs">{item.mesh_count || '-'}</TableCell>
                      <TableCell className="text-xs">{item.size || '-'}</TableCell>
                      <TableCell className="text-xs">{item.customer_name || '-'}</TableCell>
                      <TableCell className="text-xs">
                        {warn ? (
                          <span className="text-red-500 font-bold">
                            {item.life_count}/{item.max_use_count}
                          </span>
                        ) : (
                          `${item.life_count}/${item.max_use_count}`
                        )}
                      </TableCell>
                      <TableCell className="text-xs">{item.reclaim_count || 0}</TableCell>
                      <TableCell className="text-xs">
                        {item.tension_value ? `${item.tension_value} N/cm` : '-'}
                      </TableCell>
                      <TableCell>
                        <Badge variant={st.variant} className="text-xs">
                          {st.label}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-6 w-6 p-0"
                            onClick={() => {
                              setEditItem(item);
                              setShowDialog(true);
                            }}
                            title={tc('edit')}
                          >
                            <Edit className="h-3 w-3" />
                          </Button>
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-6 w-6 p-0"
                            onClick={() => handleViewHistory(item.id)}
                            title="生命周期"
                          >
                            <History className="h-3 w-3" />
                          </Button>
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-6 w-6 p-0 text-red-600"
                            onClick={() => handleDelete(item.id)}
                            title={tc('delete')}
                          >
                            <Trash2 className="h-3 w-3" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
                {list.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={11} className="text-center text-gray-400 py-8">
                      暂无记录
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>

        <div className="flex items-center justify-between">
          <span className="text-sm text-gray-500">共{total}条</span>
          <div className="flex gap-2">
            <Button
              size="sm"
              variant="outline"
              disabled={page <= 1}
              onClick={() => setPage((p) => p - 1)}
            >
              上一页
            </Button>
            <Button
              size="sm"
              variant="outline"
              disabled={page * 20 >= total}
              onClick={() => setPage((p) => p + 1)}
            >
              下一页
            </Button>
          </div>
        </div>

        <Dialog open={showDialog} onOpenChange={setShowDialog}>
          <DialogContent className="max-w-2xl" resizable>
            <DialogHeader>
              <DialogTitle>{editItem.id ? '编辑网版' : '新增网版'}</DialogTitle>
            </DialogHeader>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>网版编码</Label>
                <Input
                  value={editItem.plate_code || ''}
                  onChange={(e) => setEditItem({ ...editItem, plate_code: e.target.value })}
                />
              </div>
              <div>
                <Label>网版名称</Label>
                <Input
                  value={editItem.plate_name || ''}
                  onChange={(e) => setEditItem({ ...editItem, plate_name: e.target.value })}
                />
              </div>
              <div>
                <Label>{tc('type')}</Label>
                <Select
                  value={String(editItem.plate_type || 1)}
                  onValueChange={(v) => setEditItem({ ...editItem, plate_type: Number(v) })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="1">丝网版</SelectItem>
                    <SelectItem value="2">胶印版</SelectItem>
                    <SelectItem value="3">柔版</SelectItem>
                    <SelectItem value="4">凹版</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>目数</Label>
                <Input
                  value={editItem.mesh_count || ''}
                  onChange={(e) => setEditItem({ ...editItem, mesh_count: e.target.value })}
                />
