              <Button onClick={handleSave}>{tc('save')}</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        <Dialog open={showHistoryDialog} onOpenChange={setShowHistoryDialog}>
          <DialogContent className="max-w-4xl" resizable>
            <DialogHeader>
              <DialogTitle>网版生命周期记录</DialogTitle>
            </DialogHeader>
            <Tabs defaultValue="list">
              <TabsList>
                <TabsTrigger value="list">历史记录</TabsTrigger>
                <TabsTrigger value="add">{tc('dcAddRecordTab')}</TabsTrigger>
              </TabsList>
              <TabsContent value="list">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-xs">操作类型</TableHead>
                      <TableHead className="text-xs">{tc('dcTensionHead2')}</TableHead>
                      <TableHead className="text-xs">{tc('dcLifeIncHead')}</TableHead>
                      <TableHead className="text-xs">{tc('remark')}</TableHead>
                      <TableHead className="text-xs">操作人</TableHead>
                      <TableHead className="text-xs">{tc('time')}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {historyList.map((h) => (
                      <TableRow key={h.id}>
                        <TableCell className="text-xs">
                          <Badge variant="outline">{actionMap[h.action] || h.action}</Badge>
                        </TableCell>
                        <TableCell className="text-xs">
                          {h.tension_value ? `${h.tension_value} N/cm` : '-'}
                        </TableCell>
                        <TableCell className="text-xs">
                          {h.life_increment > 0 ? h.life_increment : '-'}
                        </TableCell>
                        <TableCell className="text-xs">{h.remark || '-'}</TableCell>
                        <TableCell className="text-xs">{h.operator_name || '-'}</TableCell>
                        <TableCell className="text-xs">{h.created_at}</TableCell>
                      </TableRow>
                    ))}
                    {historyList.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={6} className="text-center text-gray-400 py-8">
                          暂无记录
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TabsContent>
              <TabsContent value="add">
                <div className="space-y-4">
                  <div>
                    <Label>操作类型</Label>
                    <Select value={lifeAction} onValueChange={setLifeAction}>
                      <SelectTrigger>
                        <SelectValue placeholder={tc('pleaseSelect')} />
                      </SelectTrigger>
                      <SelectContent>
                        {Object.entries(actionMap).map(([k, v]) => (
                          <SelectItem key={k} value={k}>
                            {v}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <Label>{tc('dcTensionLabel')}</Label>
                    <Input
                      type="number"
                      value={lifeTension}
                      onChange={(e) => setLifeTension(e.target.value)}
                    />
                  </div>
                  <div>
                    <Label>{tc('dcLifeIncLabel')}</Label>
                    <Input
                      type="number"
                      value={lifeIncrement}
                      onChange={(e) => setLifeIncrement(e.target.value)}
                    />
                  </div>
                  <div>
                    <Label>{tc('remark')}</Label>
                    <Textarea value={lifeRemark} onChange={(e) => setLifeRemark(e.target.value)} />
                  </div>
                  <Button onClick={handleAddLifeRecord}>
                    <Activity className="h-3 w-3 mr-1" />
                    提交记录
                  </Button>
                </div>
              </TabsContent>
            </Tabs>
          </DialogContent>
        </Dialog>
      </div>
    </MainLayout>
  );
}

