'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useState, useRef, useEffect } from 'react';
import { MainLayout } from '@/components/layout';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { QrCode, Search, Printer, CheckCircle, AlertCircle, RefreshCw } from 'lucide-react';
import { useTranslations } from 'next-intl';

// 追溯结果类型
interface TraceResult {
  traceNo: string;
  card: {
    cardNo: string;
    workOrderNo: string;
    productCode?: string;
    productName?: string;
  };
  mainMaterial: {
    labelNo: string;
    materialCode?: string;
    materialName?: string;
    specification?: string;
    batchNo?: string;
    supplierName?: string;
    receiveDate?: string;
  };
  materials: {
    labelNo: string;
    materialType: string;
    materialCode?: string;
    materialName?: string;
    specification?: string;
    batchNo?: string;
    supplierName?: string;
    receiveDate?: string;
    quantity?: number;
    unit?: string;
  }[];
}

// 追溯记录类型
interface TraceRecord {
  id: number;
  traceNo: string;
  cardNo?: string;
  workOrderNo?: string;
  productCode?: string;
  traceType: string;
  operatorName?: string;
  traceTime?: string;
}

export default function TracePage() {
  // 翻译钩子
  const tc = useTranslations('Common');

  const [qrCode, setQrCode] = useState('');
  const [traceResult, setTraceResult] = useState<TraceResult | null>(null);
  const [records, setRecords] = useState<TraceRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const qrInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchRecords();
    qrInputRef.current?.focus();
  }, []);

  const fetchRecords = async () => {
    try {
      const response = await authFetch('/api/dcprint/trace');
      const result = await response.json();
      if (result.success) {
        setRecords(result.data.list || []);
      }
    } catch {}
  };

  const handleScanQRCode = async () => {
    if (!qrCode.trim()) return;

    setError('');
    setSuccess('');
    setLoading(true);

    try {
      // 解析二维码内容
      let qrData: Loose;
      try {
        qrData = JSON.parse(qrCode);
      } catch {
        qrData = { ID: qrCode, TYPE: '4' };
      }

      // 执行追溯查询
      const response = await authFetch('/api/dcprint/trace', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          cardNo: qrData.ID,
          traceType: 'forward',
          operatorId: 1,
          operatorName: '操作员',
        }),
      });

      const result = await response.json();

      if (result.success) {
        setTraceResult(result.data);
        setSuccess('追溯查询成功！');
        fetchRecords();
      } else {
        setError(result.message || '追溯查询失败');
        setTraceResult(null);
      }
    } catch {
      setError('追溯查询失败');
      setTraceResult(null);
    } finally {
      setLoading(false);
      setQrCode('');
      qrInputRef.current?.focus();
    }
  };

  const handleReset = () => {
    setQrCode('');
    setTraceResult(null);
    setError('');
    setSuccess('');
    qrInputRef.current?.focus();
  };

  const handlePrint = () => {
    // TODO: 实现打印功能
    alert('打印功能待实现');
  };

  return (
    <MainLayout title="物料追溯">
      <div className="space-y-6">
        {/* 扫码追溯区域 */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <QrCode className="h-5 w-5" />
              扫码追溯
            </CardTitle>
            <CardDescription>{tc('dcTraceScanDesc')}</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {/* 二维码输入 */}
              <div className="flex gap-4">
                <div className="flex-1">
                  <label className="text-sm font-medium mb-2 block">{tc('dcQrInputLabel')}</label>
                  <Input
                    ref={qrInputRef}
                    placeholder="请扫描流程卡二维码..."
                    value={qrCode}
                    onChange={(e) => setQrCode(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleScanQRCode()}
                    disabled={loading}
                  />
                </div>
                <div className="flex items-end gap-2">
                  <Button variant="outline" onClick={handleReset}>
                    <RefreshCw className="h-4 w-4 mr-2" />
                    重置
                  </Button>
                  <Button onClick={handleScanQRCode} disabled={loading}>
                    <Search className="h-4 w-4 mr-2" />
                    追溯
                  </Button>
                </div>
              </div>

              {/* 提示信息 */}
              {error && (
                <Alert variant="destructive">
                  <AlertCircle className="h-4 w-4" />
                  <AlertDescription>{error}</AlertDescription>
                </Alert>
              )}
              {success && (
                <Alert className="bg-green-50 border-green-200">
                  <CheckCircle className="h-4 w-4 text-green-600" />
                  <AlertDescription className="text-green-700">{success}</AlertDescription>
                </Alert>
              )}
            </div>
          </CardContent>
        </Card>

        {/* 追溯结果 */}
        {traceResult && (
          <div className="space-y-6">
            {/* 追溯单信息 */}
            <Card>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div>
                    <CardTitle>追溯结果</CardTitle>
                    <CardDescription>
                      {tc('dcTraceNoPrefix')}
                      {traceResult.traceNo}
                    </CardDescription>
                  </div>
                  <Button onClick={handlePrint}>
                    <Printer className="h-4 w-4 mr-2" />
                    打印追溯单
                  </Button>
                </div>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {/* 流程卡信息 */}
                  <Card>
                    <CardHeader className="pb-3">
                      <CardTitle className="text-sm">流程卡信息</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="space-y-2">
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">流程卡卡号</span>
                          <span className="font-medium">{traceResult.card.cardNo}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">工单号</span>
                          <span className="font-medium">{traceResult.card.workOrderNo}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">成品料号</span>
                          <span className="font-medium">{traceResult.card.productCode}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">成品名称</span>
                          <span className="font-medium">{traceResult.card.productName}</span>
                        </div>
                      </div>
                    </CardContent>
                  </Card>

                  {/* 主材信息 */}
                  <Card className="border-green-200">
                    <CardHeader className="pb-3">
                      <CardTitle className="text-sm">主材信息</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="space-y-2">
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">标签编号</span>
                          <span className="font-medium">{traceResult.mainMaterial.labelNo}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">物料代号</span>
                          <span className="font-medium">
                            {traceResult.mainMaterial.materialCode}
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">物料名称</span>
                          <span className="font-medium">
                            {traceResult.mainMaterial.materialName}
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">{tc('specification')}</span>
                          <span className="font-medium">
                            {traceResult.mainMaterial.specification}
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">批号</span>
                          <span className="font-medium">{traceResult.mainMaterial.batchNo}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">{tc('supplier')}</span>
                          <span className="font-medium">
                            {traceResult.mainMaterial.supplierName}
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">进料日期</span>
                          <span className="font-medium">
                            {traceResult.mainMaterial.receiveDate}
                          </span>
                        </div>
                      </div>
                    </CardContent>
                  </Card>

                  {/* 统计信息 */}
                  <Card>
                    <CardHeader className="pb-3">
                      <CardTitle className="text-sm">{tc('dcStatsTitle')}</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="space-y-4">
                        <div className="bg-muted p-3 rounded-lg">
                          <div className="text-sm text-muted-foreground">{tc('dcMainCount')}</div>
                          <div className="text-2xl font-bold text-green-600">
                            {traceResult.materials.filter((m) => m.materialType === 'main').length}
                          </div>
                        </div>
                        <div className="bg-muted p-3 rounded-lg">
                          <div className="text-sm text-muted-foreground">{tc('dcAuxCount')}</div>
                          <div className="text-2xl font-bold text-blue-600">
                            {
                              traceResult.materials.filter((m) => m.materialType === 'auxiliary')
                                .length
                            }
                          </div>
                        </div>
                        <div className="bg-muted p-3 rounded-lg">
                          <div className="text-sm text-muted-foreground">物料总数</div>
                          <div className="text-2xl font-bold">{traceResult.materials.length}</div>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                </div>
              </CardContent>
            </Card>

            {/* 物料明细 */}
            <Card>
              <CardHeader>
                <CardTitle>物料明细</CardTitle>
                <CardDescription>{tc('dcMaterialDetailDesc')}</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="border rounded-lg">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>标签编号</TableHead>
                        <TableHead>{tc('type')}</TableHead>
                        <TableHead>物料代号</TableHead>
                        <TableHead>物料名称</TableHead>
                        <TableHead>{tc('specification')}</TableHead>
                        <TableHead>批号</TableHead>
                        <TableHead>{tc('supplier')}</TableHead>
                        <TableHead>进料日期</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {traceResult.materials.length === 0 ? (
                        <TableRow>
                          <TableCell colSpan={8} className="text-center py-8">
                            暂无物料数据
                          </TableCell>
                        </TableRow>
                      ) : (
                        traceResult.materials.map((material, index) => (
                          <TableRow key={index}>
                            <TableCell className="font-medium">{material.labelNo}</TableCell>
                            <TableCell>
                              {material.materialType === 'main' ? (
                                <Badge className="bg-green-100 text-green-700">主材</Badge>
                              ) : (
                                <Badge className="bg-blue-100 text-blue-700">辅料</Badge>
                              )}
                            </TableCell>
                            <TableCell>{material.materialCode}</TableCell>
                            <TableCell>{material.materialName}</TableCell>
                            <TableCell>{material.specification}</TableCell>
                            <TableCell>{material.batchNo}</TableCell>
                            <TableCell>{material.supplierName}</TableCell>
                            <TableCell>{material.receiveDate}</TableCell>
                          </TableRow>
                        ))
                      )}
                    </TableBody>
                  </Table>
                </div>
              </CardContent>
            </Card>
          </div>
        )}

        {/* 追溯记录列表 */}
        <Card>
          <CardHeader>
            <CardTitle>追溯记录</CardTitle>
            <CardDescription>{tc('dcTraceRecordDesc')}</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="border rounded-lg">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{tc('dcTraceNoHead')}</TableHead>
                    <TableHead>流程卡卡号</TableHead>
                    <TableHead>工单号</TableHead>
                    <TableHead>成品料号</TableHead>
                    <TableHead>{tc('dcTraceTypeHead')}</TableHead>
                    <TableHead>操作员</TableHead>
                    <TableHead>追溯时间</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {records.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={7} className="text-center py-8">
                        暂无数据
                      </TableCell>
                    </TableRow>
                  ) : (
                    records.map((record) => (
                      <TableRow key={record.id}>
                        <TableCell className="font-medium">{record.traceNo}</TableCell>
                        <TableCell>{record.cardNo}</TableCell>
                        <TableCell>{record.workOrderNo}</TableCell>
                        <TableCell>{record.productCode}</TableCell>
                        <TableCell>
                          {record.traceType === 'forward' ? (
                            <Badge className="bg-blue-100 text-blue-700">正向追溯</Badge>
                          ) : (
                            <Badge className="bg-purple-100 text-purple-700">反向追溯</Badge>
                          )}
                        </TableCell>
                        <TableCell>{record.operatorName}</TableCell>
                        <TableCell>{record.traceTime}</TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </div>
          </CardContent>
        </Card>
      </div>
    </MainLayout>
  );
}

'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useState } from 'react';
import { useRouter } from '@/i18n/navigation';
import { MainLayout } from '@/components/layout';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { ArrowLeft, Save, Car } from 'lucide-react';
import { toast } from 'sonner';
import { useTranslations } from 'next-intl';

interface VehicleForm {
  vehicle_no: string;
  vehicle_type: string;
  brand: string;
  model: string;
  color: string;
  engine_no: string;
  frame_no: string;
  buy_date: string;
  mileage: number;
  fuel_type: string;
  capacity: number;
  status: number;
  driver_name: string;
  driver_phone: string;
  insurance_expire: string;
  annual_inspect_expire: string;
  remark: string;
}

const initialForm: VehicleForm = {
  vehicle_no: '',
  vehicle_type: '',
  brand: '',
  model: '',
  color: '',
  engine_no: '',
  frame_no: '',
  buy_date: '',
  mileage: 0,
  fuel_type: '',
  capacity: 0,
  status: 1,
  driver_name: '',
  driver_phone: '',
  insurance_expire: '',
  annual_inspect_expire: '',
  remark: '',
};

export default function NewVehiclePage() {
  // 翻译钩子
  const t = useTranslations('Delivery');
  const tc = useTranslations('Common');

  const router = useRouter();
  const [formData, setFormData] = useState<VehicleForm>(initialForm);
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.vehicle_no) {
      toast.error(t('inputPlateNo'));
      return;
    }

    try {
      setSaving(true);
      const response = await authFetch('/api/delivery/vehicles', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      const result = await response.json();

      if (result.success) {
        toast.success(t('createSuccess'));
        router.push('/delivery/vehicles');
      } else {
        toast.error(result.message || t('createFailed'));
      }
    } catch {
      toast.error(t('createFailed'));
    } finally {
      setSaving(false);
    }
  };

  const updateField = (field: keyof VehicleForm, value: Loose) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  return (
    <MainLayout>
      <div className="container mx-auto py-6 max-w-4xl">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-4">
            <Button variant="outline" size="icon" onClick={() => router.back()}>
              <ArrowLeft className="h-4 w-4" />
            </Button>
            <div>
              <h1 className="text-2xl font-bold flex items-center gap-2">
                <Car className="h-6 w-6" />
                {t('addVehicle')}
              </h1>
              <p className="text-sm text-muted-foreground">{t('newVehicleDesc')}</p>
            </div>
          </div>
          <Button onClick={handleSubmit} disabled={saving}>
            <Save className="h-4 w-4 mr-2" />
            {saving ? t('saving') : tc('save')}
          </Button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>{t('basicInfo')}</CardTitle>
            </CardHeader>
            <CardContent className="grid grid-cols-2 md:grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label htmlFor="vehicle_no">
                  {t('plateNo')} <span className="text-red-500">*</span>
                </Label>
                <Input
                  id="vehicle_no"
                  value={formData.vehicle_no}
                  onChange={(e) => updateField('vehicle_no', e.target.value)}
                  placeholder={t('plateNoPlaceholder')}
                />
              </div>
              <div className="space-y-2">
                <Label>{t('vehicleType')}</Label>
                <Select
                  value={formData.vehicle_type}
                  onValueChange={(v) => updateField('vehicle_type', v)}
                >
                  <SelectTrigger>
                    <SelectValue placeholder={t('selectType')} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="truck">{t('truck')}</SelectItem>
                    <SelectItem value="van">{t('van')}</SelectItem>
                    <SelectItem value="sedan">{t('sedan')}</SelectItem>
                    <SelectItem value="pickup">{t('pickup')}</SelectItem>
                    <SelectItem value="other">{t('otherType')}</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>{tc('status')}</Label>
                <Select
                  value={formData.status.toString()}
                  onValueChange={(v) => updateField('status', parseInt(v))}
                >
                  <SelectTrigger>
                    <SelectValue placeholder={t('selectStatus')} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="1">{tc('enabled')}</SelectItem>
                    <SelectItem value="2">{t('underRepair')}</SelectItem>
                    <SelectItem value="0">{tc('disabled')}</SelectItem>
                    <SelectItem value="3">{t('scrapped')}</SelectItem>
                  </SelectContent>
                </Select>
              </div>
