                <Label>
                  设备编码
                  <span className="text-red-500">*</span>
                </Label>
                <Input
                  value={form.equipment_code || ''}
                  onChange={(e) => setForm({ ...form, equipment_code: e.target.value })}
                  placeholder="如: EQP001"
                  disabled={editing}
                />
              </div>
              <div className="space-y-2">
                <Label>
                  设备名称
                  <span className="text-red-500">*</span>
                </Label>
                <Input
                  value={form.equipment_name || ''}
                  onChange={(e) => setForm({ ...form, equipment_name: e.target.value })}
                  placeholder="请输入设备名称"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>设备类型</Label>
                <Select
                  value={String(form.equipment_type ?? 1)}
                  onValueChange={(v) => setForm({ ...form, equipment_type: parseInt(v) })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {Object.entries(EQUIPMENT_TYPES).map(([k, v]) => (
                      <SelectItem key={k} value={k}>
                        {v}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>{tc('brand')}</Label>
                <Input
                  value={form.brand || ''}
                  onChange={(e) => setForm({ ...form, brand: e.target.value })}
                  placeholder={tc('brand')}
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>型号</Label>
                <Input
                  value={form.model || ''}
                  onChange={(e) => setForm({ ...form, model: e.target.value })}
                  placeholder="型号"
                />
              </div>
              <div className="space-y-2">
                <Label>安装位置</Label>
                <Input
                  value={form.location || ''}
                  onChange={(e) => setForm({ ...form, location: e.target.value })}
                  placeholder="位置"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>额定产能</Label>
                <Input
                  type="number"
                  value={form.rated_capacity || ''}
                  onChange={(e) =>
                    setForm({ ...form, rated_capacity: parseFloat(e.target.value) || 0 })
                  }
                  placeholder="产能/小时"
                />
              </div>
              <div className="space-y-2">
                <Label>运行状态</Label>
                <Select
                  value={String(form.current_status ?? 1)}
                  onValueChange={(v) => setForm({ ...form, current_status: parseInt(v) })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {Object.entries(CURRENT_STATUS).map(([k, v]) => (
                      <SelectItem key={k} value={k}>
                        {v.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="space-y-2">
              <Label>{tc('remark')}</Label>
              <Textarea
                value={form.remark || ''}
                onChange={(e) => setForm({ ...form, remark: e.target.value })}
                placeholder={tc('remark')}
                rows={2}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              取消
            </Button>
            <Button onClick={saveEquipment} className="bg-blue-600 hover:bg-blue-700">
              保存
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </MainLayout>
  );
}

