  payable_no: string;
  source_type: number;
  source_no: string;
  supplier_id: number;
  supplier_name: string;
  amount: number;
  paid_amount: number;
  balance: number;
  due_date: string;
  status: number;
  remark: string;
  create_time: string;
}

interface ReceiptRecord {
