interface ReportItem {
  id: number;
  period: string;
  type: string;
  category: string;
  revenue: number;
  cost: number;
  profit: number;
  profit_rate: number;
}

export default function FinanceReportPage() {
  // 翻译钩子
  const t = useTranslations('Finance');
  const tc = useTranslations('Common');

  const [list, setList] = useState<ReportItem[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [periodType, setPeriodType] = useState('month');
  const [summary, setSummary] = useState({
    total_revenue: 0,
    total_cost: 0,
    total_profit: 0,
    profit_rate: 0,
  });

  const fetchData = useCallback(async () => {
    try {
      const params = new URLSearchParams({
        page: String(page),
        pageSize: '20',
        period_type: periodType,
      });
      const res = await authFetch('/api/finance/report?' + params);
      const result = await res.json();
      if (result.success) {
        setList(result.data?.list || []);
        setTotal(result.data?.total || 0);
      }
    } catch {}
  }, [page, periodType]);

  const fetchSummary = useCallback(async () => {
    try {
      const res = await authFetch('/api/finance/stats');
      const result = await res.json();
      if (result.success && result.data) {
        const d = result.data;
        setSummary({
          total_revenue: d.total_revenue || 0,
          total_cost: d.total_cost || 0,
          total_profit: d.total_profit || 0,
          profit_rate: d.profit_rate || 0,
