                    label: tc('revenue'),
                    width: 12,
                    formatter: (v) => Number(v || 0).toFixed(2),
                  },
                  {
                    key: 'cost',
                    label: tc('cost'),
                    width: 12,
                    formatter: (v) => Number(v || 0).toFixed(2),
                  },
                  {
                    key: 'profit',
                    label: tc('profit'),
                    width: 12,
                    formatter: (v) => Number(v || 0).toFixed(2),
