'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useEffect, useState } from 'react';
import { MainLayout } from '@/components/layout';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Plus, Search, Edit, Trash2, AlertTriangle } from 'lucide-react';
import { toast } from 'sonner';
import { useTranslations } from 'next-intl';

interface Certificate {
  id: number;
  employee_id: number;
  employee_name: string;
  cert_name: string;
  cert_code: string;
  cert_type: string;
  issue_authority: string;
  issue_date: string;
  expiry_date: string;
  status: string;
  remind_days: number;
  file_url: string;
  remark: string;
}

const certTypeMap: Record<string, string> = {
  operation: 'certTypeOperation',
  safety: 'certTypeSafety',
  quality: 'certTypeQuality',
  skill: 'certTypeSkill',
};

const certTypeOptions = [
  { value: 'all', label: 'allTypes' },
  { value: 'operation', label: 'certTypeOperation' },
  { value: 'safety', label: 'certTypeSafety' },
  { value: 'quality', label: 'certTypeQuality' },
  { value: 'skill', label: 'certTypeSkill' },
];

const statusOptions = [
  { value: 'all', label: 'allStatus' },
  { value: 'active', label: 'valid' },
  { value: 'expired', label: 'expired' },
];

const formatDate = (dateStr: string) => {
  if (!dateStr) return '-';
  return dateStr.slice(0, 10);
};

const getDaysUntilExpiry = (expiryDate: string) => {
  if (!expiryDate) return Infinity;
  const now = new Date();
  now.setHours(0, 0, 0, 0);
  const expiry = new Date(expiryDate);
  expiry.setHours(0, 0, 0, 0);
  return Math.ceil((expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
};

export default function CertificatesPage() {
  const [list, setList] = useState<Certificate[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [pageSize] = useState(20);
  const [employeeId, setEmployeeId] = useState('');
  const [certType, setCertType] = useState('all');
  const [status, setStatus] = useState('all');
  const [showDialog, setShowDialog] = useState(false);
  const [showDetail, setShowDetail] = useState(false);
  const [editItem, setEditItem] = useState<Partial<Certificate>>({});
  const [detailItem, setDetailItem] = useState<Certificate | null>(null);

  const t = useTranslations('Hr');
  const tc = useTranslations('Common');

  const fetchData = async () => {
    try {
      const params = new URLSearchParams({
        page: String(page),
        pageSize: String(pageSize),
      });
      if (employeeId) params.append('employeeId', employeeId);
      if (certType) params.append('certType', certType);
      if (status) params.append('status', status);

      const res = await authFetch(`/api/hr/certificates?${params}`);
      const json = await res.json();
      if (json.code === 200) {
        setList(json.data.list || []);
        setTotal(json.data.total || 0);
      }
    } catch {
      toast.error(tc('fetchFailed'));
    }
  };

  useEffect(() => {
    fetchData();
  }, [page]);

  const handleSave = async () => {
    try {
      const isEdit = !!editItem.id;
      const res = await authFetch('/api/hr/certificates', {
        method: isEdit ? 'PUT' : 'POST',
        body: JSON.stringify(editItem),
      });
      const json = await res.json();
      if (json.code === 200) {
        toast.success(isEdit ? tc('updateSuccess') : tc('createSuccess'));
        setShowDialog(false);
        fetchData();
      } else {
        toast.error(json.message || tc('error'));
      }
    } catch {
      toast.error(tc('error'));
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm(tc('confirmDelete'))) return;
    try {
      const res = await authFetch(`/api/hr/certificates?id=${id}`, { method: 'DELETE' });
      const json = await res.json();
      if (json.code === 200) {
        toast.success(tc('deleteSuccess'));
        fetchData();
      } else {
        toast.error(json.message || tc('deleteFailed'));
      }
    } catch {
      toast.error(tc('deleteFailed'));
    }
  };

  const handleRowClick = (item: Certificate) => {
    setDetailItem(item);
    setShowDetail(true);
  };

  const totalPages = Math.ceil(total / pageSize);

  return (
    <MainLayout title={t('certificateManage')}>
      <div className="p-6 space-y-6">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold">{t('certificateManage')}</h1>
          <div className="flex gap-2">
            <div className="flex items-center gap-2">
              <Input
                placeholder="员工ID"
                value={employeeId}
                onChange={(e) => setEmployeeId(e.target.value)}
                className="w-28 h-8 text-sm"
              />
              <Select value={certType} onValueChange={setCertType}>
                <SelectTrigger className="w-28 h-8 text-sm">
                  <SelectValue placeholder={t('certType')} />
                </SelectTrigger>
                <SelectContent>
                  {certTypeOptions.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>
                      {t(opt.label)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={status} onValueChange={setStatus}>
                <SelectTrigger className="w-28 h-8 text-sm">
                  <SelectValue placeholder={tc('status')} />
                </SelectTrigger>
                <SelectContent>
                  {statusOptions.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>
                      {t(opt.label)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button size="sm" variant="outline" onClick={fetchData}>
                <Search className="h-3 w-3" />
              </Button>
            </div>
            <Button
              size="sm"
              onClick={() => {
                setEditItem({});
                setShowDialog(true);
              }}
            >
              <Plus className="h-3 w-3 mr-1" />
              {tc('add')}
            </Button>
          </div>
        </div>

        <Card>
          <CardContent className="p-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-xs">{t('certName')}</TableHead>
                  <TableHead className="text-xs">{t('certCode')}</TableHead>
                  <TableHead className="text-xs">{t('certType')}</TableHead>
                  <TableHead className="text-xs">{t('issueAuthority')}</TableHead>
                  <TableHead className="text-xs">{t('issueDate')}</TableHead>
                  <TableHead className="text-xs">{t('expiryDate')}</TableHead>
                  <TableHead className="text-xs">{tc('status')}</TableHead>
                  <TableHead className="text-xs">{t('remindDays')}</TableHead>
                  <TableHead className="text-xs w-20">{tc('operation')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {list.map((item) => {
                  const daysLeft = getDaysUntilExpiry(item.expiry_date);
                  const isExpiring = daysLeft <= 30 && daysLeft > 0;
                  return (
                    <TableRow
                      key={item.id}
                      className="cursor-pointer"
                      onClick={() => handleRowClick(item)}
                    >
                      <TableCell className="text-xs font-medium">{item.cert_name}</TableCell>
                      <TableCell className="text-xs font-mono">{item.cert_code}</TableCell>
                      <TableCell className="text-xs">
                        {t(certTypeMap[item.cert_type] || item.cert_type)}
                      </TableCell>
                      <TableCell className="text-xs">{item.issue_authority || '-'}</TableCell>
                      <TableCell className="text-xs">{formatDate(item.issue_date)}</TableCell>
                      <TableCell className="text-xs">{formatDate(item.expiry_date)}</TableCell>
                      <TableCell className="text-xs">
                        {item.status === 'active' ? (
                          <Badge className="bg-green-100 text-green-700 text-xs border-0">{tc('active')}</Badge>
                        ) : (
                          <Badge className="bg-red-100 text-red-700 text-xs border-0">{tc('expired')}</Badge>
                        )}
                      </TableCell>
                      <TableCell className="text-xs">
                        {isExpiring ? (
                          <Badge className="bg-red-100 text-red-700 text-xs border-0 whitespace-nowrap">
                            <AlertTriangle className="h-3 w-3 mr-1" />
                            {daysLeft}
                          </Badge>
                        ) : (
                          <span className="text-muted-foreground">-</span>
                        )}
                      </TableCell>
                      <TableCell onClick={(e) => e.stopPropagation()}>
                        <div className="flex gap-1">
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-6 w-6 p-0"
                            onClick={() => {
                              setEditItem(item);
                              setShowDialog(true);
                            }}
                          >
                            <Edit className="h-3 w-3" />
                          </Button>
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-6 w-6 p-0 text-red-600"
                            onClick={() => handleDelete(item.id)}
                          >
                            <Trash2 className="h-3 w-3" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
                {list.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={9} className="text-center text-muted-foreground py-8">
                      {tc('noData')}
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>

        <div className="flex items-center justify-between">
          <span className="text-sm text-muted-foreground">{t('totalRecords', { count: total })}</span>
          <div className="flex gap-2">
            <Button
              size="sm"
              variant="outline"
              disabled={page <= 1}
              onClick={() => setPage((p) => p - 1)}
            >
              {tc('prevPage')}
            </Button>
            <span className="flex items-center text-sm text-muted-foreground px-2">
              {page} / {totalPages || 1}
            </span>
            <Button
              size="sm"
              variant="outline"
              disabled={page >= totalPages}
              onClick={() => setPage((p) => p + 1)}
            >
              {tc('nextPage')}
            </Button>
          </div>
        </div>

        <Dialog open={showDialog} onOpenChange={setShowDialog}>
          <DialogContent className="max-w-lg" resizable>
            <DialogHeader>
              <DialogTitle>{editItem.id ? tc('edit') : tc('add')}</DialogTitle>
            </DialogHeader>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>{t('employeeNo')}</Label>
                <Input
                  type="number"
                  value={editItem.employee_id || ''}
                  onChange={(e) => setEditItem({ ...editItem, employee_id: Number(e.target.value) })}
                />
              </div>
              <div className="space-y-2">
                <Label>{t('certName')}</Label>
                <Input
                  value={editItem.cert_name || ''}
                  onChange={(e) => setEditItem({ ...editItem, cert_name: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <Label>{t('certCode')}</Label>
                <Input
                  value={editItem.cert_code || ''}
                  onChange={(e) => setEditItem({ ...editItem, cert_code: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <Label>{t('certType')}</Label>
                <Select
                  value={editItem.cert_type || ''}
                  onValueChange={(v) => setEditItem({ ...editItem, cert_type: v })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder={tc('select')} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="operation">{t('certTypeOperation')}</SelectItem>
                    <SelectItem value="safety">{t('certTypeSafety')}</SelectItem>
                    <SelectItem value="quality">{t('certTypeQuality')}</SelectItem>
                    <SelectItem value="skill">{t('certTypeSkill')}</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>{t('issueAuthority')}</Label>
                <Input
                  value={editItem.issue_authority || ''}
                  onChange={(e) => setEditItem({ ...editItem, issue_authority: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <Label>{t('remindDays')}</Label>
                <Input
                  type="number"
                  value={editItem.remind_days ?? 30}
                  onChange={(e) => setEditItem({ ...editItem, remind_days: Number(e.target.value) })}
                />
              </div>
              <div className="space-y-2">
                <Label>{t('issueDate')}</Label>
                <Input
                  type="date"
                  value={editItem.issue_date || ''}
                  onChange={(e) => setEditItem({ ...editItem, issue_date: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <Label>{t('expiryDate')}</Label>
                <Input
                  type="date"
                  value={editItem.expiry_date || ''}
                  onChange={(e) => setEditItem({ ...editItem, expiry_date: e.target.value })}
                />
              </div>
              <div className="space-y-2 col-span-2">
                <Label>{t('attachmentUrl')}</Label>
                <Input
                  value={editItem.file_url || ''}
                  onChange={(e) => setEditItem({ ...editItem, file_url: e.target.value })}
                  placeholder={t('urlPlaceholder')}
                />
              </div>
              <div className="space-y-2 col-span-2">
                <Label>{tc('remark')}</Label>
                <Textarea
                  value={editItem.remark || ''}
                  onChange={(e) => setEditItem({ ...editItem, remark: e.target.value })}
                  rows={3}
                />
              </div>
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={() => setShowDialog(false)}>
                {tc('cancel')}
              </Button>
              <Button onClick={handleSave}>{tc('save')}</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        <Dialog open={showDetail} onOpenChange={setShowDetail}>
          <DialogContent className="max-w-md" resizable>
            <DialogHeader>
              <DialogTitle>{tc('detail')}</DialogTitle>
              <DialogDescription>{tc('view')}</DialogDescription>
            </DialogHeader>
            {detailItem && (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-3 text-sm">
                  <div>
                    <span className="text-muted-foreground">{t('certName')}：</span>
                    <span className="font-medium">{detailItem.cert_name}</span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">{t('certCode')}：</span>
                    <span className="font-mono">{detailItem.cert_code}</span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">{t('employeeName')}：</span>
                    <span>{detailItem.employee_name}</span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">{t('certType')}：</span>
                    <span>{certTypeMap[detailItem.cert_type] || detailItem.cert_type}</span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">{t('issueAuthority')}：</span>
                    <span>{detailItem.issue_authority || '-'}</span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">{t('issueDate')}：</span>
                    <span>{formatDate(detailItem.issue_date)}</span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">{t('expiryDate')}：</span>
                    <span>{formatDate(detailItem.expiry_date)}</span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">{t('remindDays')}：</span>
                    <span>{detailItem.remind_days || 30}</span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">{tc('status')}：</span>
                    {detailItem.status === 'active' ? (
                      <Badge className="bg-green-100 text-green-700 text-xs border-0">{tc('active')}</Badge>
                    ) : (
                      <Badge className="bg-red-100 text-red-700 text-xs border-0">{tc('expired')}</Badge>
                    )}
                  </div>
                </div>
                {detailItem.remark && (
                  <div className="text-sm">
                    <span className="text-muted-foreground">{tc('remark')}：</span>
                    <p className="mt-1 bg-gray-50 p-2 rounded text-sm">{detailItem.remark}</p>
                  </div>
                )}
                {detailItem.file_url && (
                  <div className="text-sm">
                    <span className="text-muted-foreground">附件：</span>
                    <a
                      href={detailItem.file_url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-blue-600 underline ml-2"
                    >
                      {tc('view')}
                    </a>
                  </div>
                )}
              </div>
            )}
            <DialogFooter>
              <Button variant="outline" onClick={() => setShowDetail(false)}>
                {tc('close')}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    </MainLayout>
  );
}

'use client';

import { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Printer, UserCircle } from 'lucide-react';
import { useTranslations } from 'next-intl';
import QRCode from 'qrcode';
import type { Employee } from '../../types';

// 批量打印卡片组件
function BatchPrintCard({ employee, index }: { employee: Employee; index: number }) {
  const tc = useTranslations('Common');
  const [qrUrl, setQrUrl] = useState('');

  useEffect(() => {
    const generateQR = async () => {
      const queryUrl = `${window.location.origin}/hr/employee/query?id=${employee.id}`;
      const url = await QRCode.toDataURL(queryUrl, { width: 100, margin: 1 });
      setQrUrl(url);
    };
    generateQR();
  }, [employee.id]);

  return (
    <div className="border rounded-lg p-4 bg-card">
      <div className="flex items-start gap-4">
        <span className="text-sm text-muted-foreground">
          {tc('serialNo')} {index + 1}
        </span>
        <span className="font-medium">{employee.name}</span>
      </div>
      <div className="flex gap-4">
        <div className="w-20 h-24 bg-muted rounded flex items-center justify-center overflow-hidden">
          {employee.photo ? (
            <img src={employee.photo} alt={employee.name} className="w-full h-full object-cover" />
          ) : (
            <UserCircle className="w-10 h-10 text-muted-foreground" />
          )}
        </div>
        <div className="flex-1 text-sm space-y-1">
          <div>
            {tc('employeeNo')}: {employee.employee_no}
          </div>
          <div>
            {tc('department')}: {employee.dept_name}
          </div>
          <div>
            {tc('position')}: {employee.position || '-'}
          </div>
        </div>
        {qrUrl && (
          <div className="w-16 h-16">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={qrUrl} alt={tc('qrCode')} className="w-full h-full" />
          </div>
        )}
      </div>
    </div>
  );
}

interface BatchPrintDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  employees: Employee[];
  selectedEmployees: number[];
  onPrintAll: () => void;
}

export function BatchPrintDialog({
  open,
  onOpenChange,
  employees,
  selectedEmployees,
  onPrintAll,
}: BatchPrintDialogProps) {
  const tc = useTranslations('Common');

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-auto" resizable>
        <DialogHeader>
          <DialogTitle>{tc('batchPrintTitle')}</DialogTitle>
          <DialogDescription>
            {tc('batchPrintDesc', { count: selectedEmployees.length })}
          </DialogDescription>
        </DialogHeader>
        <div className="py-4">
          <div className="grid grid-cols-2 gap-4">
            {employees
              .filter((emp) => selectedEmployees.includes(emp.id))
              .map((emp, index) => (
                <BatchPrintCard key={emp.id} employee={emp} index={index} />
              ))}
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            {tc('cancel')}
          </Button>
          <Button onClick={onPrintAll} className="bg-blue-600 hover:bg-blue-700">
            <Printer className="w-4 h-4 mr-2" />
            {tc('printAll')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Upload, X, RefreshCw } from 'lucide-react';
import { useTranslations } from 'next-intl';
import type { Employee, Department, Role } from '../../types';

interface EmployeeFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editing: boolean;
  form: Partial<Employee>;
  setForm: React.Dispatch<React.SetStateAction<Partial<Employee>>>;
  departments: Department[];
  roles: Role[];
  uploadingPhoto: boolean;
  fileInputRef: React.RefObject<HTMLInputElement | null>;
  onPhotoUpload: (event: React.ChangeEvent<HTMLInputElement>) => Promise<void>;
  onRemovePhoto: () => void;
  onSave: () => Promise<void>;
}

export function EmployeeFormDialog({
  open,
  onOpenChange,
  editing,
  form,
  setForm,
  departments,
  roles,
  uploadingPhoto,
  fileInputRef,
  onPhotoUpload,
  onRemovePhoto,
  onSave,
}: EmployeeFormDialogProps) {
  const t = useTranslations('Hr');
  const tc = useTranslations('Common');

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto" resizable>
        <DialogHeader>
          <DialogTitle>{editing ? t('editEmployee') : t('addEmployeeTitle')}</DialogTitle>
          <DialogDescription>
            {editing ? t('editEmployeeDesc') : t('addEmployeeDesc')}
          </DialogDescription>
        </DialogHeader>
        <div className="grid grid-cols-3 gap-4 py-4">
          {/* 照片上传区域 */}
          <div className="col-span-1 row-span-4">
            <Label className="mb-2 block">{tc('employeePhoto')}</Label>
            <div className="relative">
              <input
                type="file"
                ref={fileInputRef}
                accept="image/*"
                onChange={onPhotoUpload}
                className="hidden"
              />
              {form.photo ? (
                <div className="relative w-full aspect-[3/4] rounded-lg overflow-hidden border-2 border-gray-200 dark:border-gray-600">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img
                    src={form.photo}
                    alt={tc('employeePhoto')}
                    className="w-full h-full object-cover"
                  />
                  <button
                    onClick={onRemovePhoto}
                    className="absolute top-2 right-2 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center hover:bg-red-600 transition-colors"
                    title={tc('deletePhoto')}
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => fileInputRef.current?.click()}
                  disabled={uploadingPhoto}
                  className="w-full aspect-[3/4] border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg flex flex-col items-center justify-center gap-2 hover:border-blue-400 dark:hover:border-blue-300 hover:bg-blue-50 dark:hover:bg-blue-950 transition-colors disabled:opacity-50"
                >
                  {uploadingPhoto ? (
                    <RefreshCw className="w-8 h-8 text-gray-400 animate-spin" />
                  ) : (
                    <>
                      <Upload className="w-8 h-8 text-gray-400" />
                      <span className="text-sm text-gray-500">{tc('uploadPhoto')}</span>
                      <span className="text-xs text-gray-400">{tc('supportJpgPng')}</span>
                    </>
                  )}
                </button>
              )}
            </div>
          </div>
          <div className="space-y-2">
            <Label>{tc('employeeNo')}</Label>
            <Input
              value={form.employee_no || ''}
              onChange={(e) => setForm({ ...form, employee_no: e.target.value })}
              placeholder={tc('autoGenerate')}
              readOnly={!editing}
            />
          </div>
          <div className="space-y-2">
            <Label>
              {tc('name')} <span className="text-red-500">*</span>
            </Label>
            <Input
              value={form.name || ''}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
              placeholder={tc('enterName')}
            />
          </div>
          <div className="space-y-2">
            <Label>
              {tc('gender')} <span className="text-gray-400 text-xs">{tc('idCardAuto')}</span>
            </Label>
            <Select
              value={form.gender?.toString() || '1'}
              onValueChange={(v) => setForm({ ...form, gender: parseInt(v) })}
            >
              <SelectTrigger>
                <SelectValue placeholder={tc('selectGender')} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="1">{tc('maleShort')}</SelectItem>
                <SelectItem value="2">{tc('femaleShort')}</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>{tc('contact')}</Label>
            <Input
              value={form.phone || ''}
              onChange={(e) => setForm({ ...form, phone: e.target.value })}
              placeholder={tc('enterPhone')}
            />
          </div>
          <div className="space-y-2">
            <Label>{tc('email')}</Label>
            <Input
              value={form.email || ''}
              onChange={(e) => setForm({ ...form, email: e.target.value })}
              placeholder={tc('enterEmail')}
            />
          </div>
          <div className="space-y-2">
            <Label>{tc('department')}</Label>
            <Select
              value={form.dept_id?.toString() || ''}
              onValueChange={(v) => setForm({ ...form, dept_id: parseInt(v) })}
            >
              <SelectTrigger>
                <SelectValue placeholder={tc('selectDepartment')} />
              </SelectTrigger>
              <SelectContent>
                {departments.map((dept) => (
                  <SelectItem key={dept.id} value={dept.id.toString()}>
                    {dept.dept_name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>{tc('position')}</Label>
            <Input
              value={form.position || ''}
              onChange={(e) => setForm({ ...form, position: e.target.value })}
              placeholder={tc('enterPosition')}
            />
          </div>
          <div className="space-y-2">
            <Label>{tc('role')}</Label>
            <Select
              value={form.role_id?.toString() || ''}
              onValueChange={(v) => setForm({ ...form, role_id: parseInt(v) })}
            >
              <SelectTrigger>
                <SelectValue placeholder={tc('selectRole')} />
              </SelectTrigger>
              <SelectContent>
                {roles.map((role) => (
                  <SelectItem key={role.id} value={role.id.toString()}>
                    {role.role_name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>{tc('entryDate')}</Label>
            <Input
              type="date"
              value={form.entry_date || ''}
              onChange={(e) => setForm({ ...form, entry_date: e.target.value })}
            />
          </div>
          <div className="space-y-2">
            <Label>{tc('status')}</Label>
            <Select
              value={form.status?.toString() || '1'}
              onValueChange={(v) => setForm({ ...form, status: parseInt(v) })}
            >
              <SelectTrigger>
                <SelectValue placeholder={tc('selectStatus')} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="1">{tc('statusActive')}</SelectItem>
                <SelectItem value="2">{tc('statusProbation')}</SelectItem>
                <SelectItem value="3">{tc('statusResigned')}</SelectItem>
                <SelectItem value="0">{tc('statusInactive')}</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>
              {tc('age')} <span className="text-gray-400 text-xs">{tc('autoCalculate')}</span>
            </Label>
            <Input
              type="number"
              value={form.age || ''}
              readOnly
              className="bg-gray-50"
              placeholder={tc('autoCalculate')}
            />
          </div>
          <div className="space-y-2">
            <Label>{tc('section')}</Label>
            <Input
              value={form.section || ''}
              onChange={(e) => setForm({ ...form, section: e.target.value })}
              placeholder={tc('enterSection')}
            />
          </div>
          <div className="space-y-2">
            <Label>
              {tc('birthDate')} <span className="text-gray-400 text-xs">{tc('autoCalculate')}</span>
            </Label>
            <Input type="date" value={form.birth_date || ''} readOnly className="bg-gray-50" />
          </div>
          <div className="space-y-2">
            <Label>{tc('idCard')}</Label>
            <Input
              value={form.id_card || ''}
              onChange={(e) => {
                const idCard = e.target.value.replace(/[^0-9Xx]/g, '');
                let birthDate = '';
                let age = undefined;
                let gender = form.gender;
                if (idCard.length === 18) {
                  const year = idCard.substring(6, 10);
                  const month = idCard.substring(10, 12);
                  const day = idCard.substring(12, 14);
                  birthDate = `${year}-${month}-${day}`;
                  const birthYear = parseInt(year);
                  const currentYear = new Date().getFullYear();
                  age = currentYear - birthYear;
                  const genderDigit = parseInt(idCard.substring(16, 17));
                  gender = genderDigit % 2 === 1 ? 1 : 2;
                } else if (idCard.length === 15) {
                  const year = '19' + idCard.substring(6, 8);
                  const month = idCard.substring(8, 10);
                  const day = idCard.substring(10, 12);
                  birthDate = `${year}-${month}-${day}`;
                  const birthYear = parseInt(year);
                  const currentYear = new Date().getFullYear();
                  age = currentYear - birthYear;
                  const genderDigit = parseInt(idCard.substring(14, 15));
                  gender = genderDigit % 2 === 1 ? 1 : 2;
                }
                setForm({
                  ...form,
                  id_card: idCard,
                  birth_date: birthDate || form.birth_date,
                  age: age || form.age,
                  gender: gender,
                });
              }}
              placeholder={tc('enterIdCard')}
            />
          </div>
          <div className="space-y-2">
            <Label>{tc('nativePlace')}</Label>
            <Input
              value={form.native_place || ''}
              onChange={(e) => setForm({ ...form, native_place: e.target.value })}
              placeholder={tc('enterNativePlace')}
            />
          </div>
          <div className="space-y-2">
            <Label>{tc('education')}</Label>
            <Select
              value={form.education || ''}
              onValueChange={(v) => setForm({ ...form, education: v })}
            >
              <SelectTrigger>
                <SelectValue placeholder={tc('selectEducation')} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="初中">{tc('juniorHigh')}</SelectItem>
                <SelectItem value="中专">{tc('technical')}</SelectItem>
                <SelectItem value="高中">{tc('highSchool')}</SelectItem>
                <SelectItem value="大专">{tc('associate')}</SelectItem>
                <SelectItem value="本科">{tc('bachelor')}</SelectItem>
                <SelectItem value="硕士">{tc('master')}</SelectItem>
                <SelectItem value="博士">{tc('doctor')}</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>{tc('homeAddress')}</Label>
            <Input
              value={form.home_address || ''}
              onChange={(e) => setForm({ ...form, home_address: e.target.value })}
              placeholder={tc('enterHomeAddress')}
            />
          </div>
          <div className="space-y-2">
            <Label>{tc('currentAddress')}</Label>
            <Input
              value={form.current_address || ''}
              onChange={(e) => setForm({ ...form, current_address: e.target.value })}
              placeholder={tc('enterCurrentAddress')}
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            {tc('cancel')}
