      logger.warn({ module: 'Hr', action: 'exportToExcel' }, '没有数据可导出');
      toast.error(t('noDataToExport'));
      return;
    }

    // 创建CSV内容
    const headers = [
      t('employeeNo'),
      t('name'),
      t('gender'),
      t('age'),
      t('department'),
      t('section'),
      t('position'),
      t('education'),
      t('entryDate'),
      t('nativePlace'),
      t('contact'),
      tc('status'),
    ];
