      emp.employee_no,
      emp.name,
      emp.gender === 1 ? tc('maleShort') : tc('femaleShort'),
      emp.age || '',
      emp.dept_name,
      emp.section || '',
      emp.position,
      emp.education || '',
      emp.entry_date,
      emp.native_place || '',
      emp.phone,
      emp.status === 1
        ? t('statusActive')
        : emp.status === 2
          ? t('statusProbation')
          : emp.status === 3
            ? t('statusResigned')
            : t('statusInactive'),
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map((row) => row.map((cell) => `"${cell}"`).join(',')),
    ].join('\n');

