'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useState, useEffect, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  UserCircle,
  Building2,
  Briefcase,
  Phone,
  Mail,
  Calendar,
  ArrowLeft,
  Loader2,
} from 'lucide-react';
import Link from 'next/link';
import { useTranslations } from 'next-intl';

// 员工接口
interface Employee {
  id: number;
  employee_no: string;
  name: string;
  gender: number;
  phone: string;
  email: string;
  dept_id: number;
  dept_name: string;
  role_id: number;
  role_name: string;
  position: string;
  entry_date: string;
  status: number;
  remark?: string;
}

function EmployeeQueryContent() {
  const tc = useTranslations('Common');

  const searchParams = useSearchParams();
  const employeeId = searchParams.get('id');

  const [employee, setEmployee] = useState<Employee | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (employeeId) {
      fetchEmployee(parseInt(employeeId));
    } else {
      setError(tc('invalidEmployeeId'));
      setLoading(false);
    }
  }, [employeeId]);

  const fetchEmployee = async (id: number) => {
    try {
      const response = await authFetch(`/api/organization/employee?id=${id}`);
      const result = await response.json();
      if (result.success && result.data) {
        setEmployee(result.data);
      } else {
        setError(tc('employeeNotExist'));
      }
    } catch {
      setError(tc('fetchEmployeeFailed'));
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status: number) => {
    const styles: Record<number, string> = {
      1: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
      0: 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200',
      2: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300',
      3: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300',
    };
    const labels: Record<number, string> = {
      1: tc('statusActive'),
      0: tc('statusInactive'),
      2: tc('statusProbation'),
      3: tc('statusResigned'),
    };
    return (
      <Badge className={styles[status] || 'bg-gray-100'}>{labels[status] || tc('unknown')}</Badge>
    );
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="w-10 h-10 animate-spin text-blue-600" />
          <p className="text-gray-600">{tc('loading')}</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100 p-4">
        <Card className="max-w-md w-full">
          <CardContent className="pt-6 text-center">
            <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <UserCircle className="w-8 h-8 text-red-500" />
            </div>
            <h2 className="text-xl font-semibold text-gray-900 mb-2">{tc('queryFailed')}</h2>
            <p className="text-gray-600 mb-6">{error}</p>
            <Link href="/hr/employee">
              <Button className="w-full">
                <ArrowLeft className="w-4 h-4 mr-2" />
                {tc('backToEmployeeList')}
              </Button>
            </Link>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!employee) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100 p-4">
        <Card className="max-w-md w-full">
          <CardContent className="pt-6 text-center">
            <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <UserCircle className="w-8 h-8 text-gray-500" />
            </div>
            <h2 className="text-xl font-semibold text-gray-900 mb-2">{tc('queryFailed')}</h2>
            <p className="text-gray-600 mb-6">{tc('employeeNotExistDesc')}</p>
            <Link href="/hr/employee">
              <Button className="w-full">
                <ArrowLeft className="w-4 h-4 mr-2" />
                {tc('backToEmployeeList')}
              </Button>
            </Link>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-4 md:p-8">
      <div className="max-w-2xl mx-auto">
        {/* 头部 */}
        <div className="mb-6 flex items-center justify-between">
          <Link href="/hr/employee">
            <Button variant="outline" className="bg-white/80 backdrop-blur">
              <ArrowLeft className="w-4 h-4 mr-2" />
              {tc('backToEmployeeList')}
            </Button>
          </Link>
          <div className="text-sm text-gray-500">
            {tc('employeeNoLabel')}
            {employee.employee_no}
          </div>
        </div>

        {/* 员工信息卡片 */}
        <Card className="overflow-hidden shadow-xl border-0">
          {/* 卡片头部 - 渐变色背景 */}
          <div className="bg-gradient-to-r from-blue-600 to-purple-600 p-8 text-white">
            <div className="flex flex-col md:flex-row items-center gap-6">
              {/* 头像区域 */}
