                      formatter: (v) => Number(v || 0),
                    },
                    {
                      key: 'personal_tax',
                      label: t('personalTax'),
                      width: 10,
                      formatter: (v) => Number(v || 0),
                    },
                    {
                      key: 'other_deduction',
                      label: t('otherDeduction'),
                      width: 10,
                      formatter: (v) => Number(v || 0),
                    },
                    {
                      key: 'actual_salary',
                      label: t('actualSalary'),
                      width: 12,
                      formatter: (v) => Number(v || 0),
