                />
              </div>
            </div>
          </CardContent>
        </Card>

        {/* 薪资列表 */}
        <Card>
          <CardContent className="p-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-12 text-center">
                    <Checkbox
                      checked={
                        selectedIds.length === filteredSalaries.length &&
                        filteredSalaries.length > 0
