                  <SortableHeader field="actual_salary" className="text-right">
                    {tc('netSalary')}
                  </SortableHeader>
                  <TableHead>{tc('status')}</TableHead>
                  <TableHead>{tc('actions')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {sortedSalaries.map((salary, index) => (
                  <TableRow key={salary.id}>
                    <TableCell className="text-center">
                      <Checkbox
