                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col">
                        <span>{salary.dept_name}</span>
                        <span className="text-xs text-muted-foreground">{salary.position}</span>
                      </div>
                    </TableCell>
                    <TableCell className="text-right">
