                        </TableRow>
                        <TableRow>
                          <TableCell className="font-medium text-red-600">
                            {t('socialSecurity')}
                          </TableCell>
                          <TableCell className="text-right text-red-600">
                            -¥{(selectedSalary.social_security || 0).toLocaleString()}
