'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useEffect, useState } from 'react';
import { MainLayout } from '@/components/layout';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Plus, Search, Edit, Trash2 } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { useTranslations } from 'next-intl';

interface Item {
  id: number;
  training_no: string;
  training_name: string;
  training_type: number;
  training_date: string;
  training_hours: number;
  trainer: string;
  training_place: string;
  status: number;
}
const typeMap: Record<number, string> = {
  1: 'safetyTraining',
  2: 'skillTraining',
  3: 'qualityTraining',
  4: 'managementTraining',
  5: 'newEmployeeTraining',
};
const statusMap: Record<
  number,
  { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline' }
> = {
  0: { label: 'pending', variant: 'outline' },
  1: { label: 'inProgress', variant: 'default' },
  2: { label: 'completed', variant: 'secondary' },
  3: { label: 'cancelled', variant: 'destructive' },
};

const formatDate = (dateStr: string) => {
  if (!dateStr) return '-';
  return dateStr.slice(0, 10);
};

export default function TrainingPage() {
  // 翻译钩子
  const t = useTranslations('Hr');
  const tc = useTranslations('Common');

  const { toast } = useToast();
  const [list, setList] = useState<Item[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [searchName, setSearchName] = useState('');
  const [showDialog, setShowDialog] = useState(false);
  const [editItem, setEditItem] = useState<Partial<Item>>({});

  const fetchData = async () => {
    try {
      const params = new URLSearchParams({
        page: String(page),
        pageSize: '20',
        trainingName: searchName,
      });
      const res = await authFetch('/api/hr/training?' + params);
      const result = await res.json();
      if (result.success) {
        setList(result.data.list || []);
        setTotal(result.data.total || 0);
      }
    } catch {}
  };
  useEffect(() => {
    fetchData();
  }, [page]);

  const handleSave = async () => {
    try {
      const res = await fetch('/api/hr/training', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(editItem),
      });
      const result = await res.json();
      if (result.success) {
        toast({ title: t('createSuccess') });
        setShowDialog(false);
        fetchData();
      } else {
        toast({ title: t('operationFailed'), description: result.message, variant: 'destructive' });
      }
    } catch {
      toast({ title: t('operationFailed'), variant: 'destructive' });
    }
  };
  const handleStatusChange = async (id: number, status: number) => {
    try {
      const res = await authFetch('/api/hr/training', {
        method: 'PUT',
        body: JSON.stringify({ id, status }),
      });
      const result = await res.json();
      if (result.success) {
        toast({ title: t('updateSuccess') });
        fetchData();
      }
    } catch {
      toast({ title: t('operationFailed'), variant: 'destructive' });
    }
  };
  const handleDelete = async (id: number) => {
    if (!confirm(t('confirmDelete'))) return;
    try {
      const res = await fetch('/api/hr/training?id=' + id, { method: 'DELETE' });
      const result = await res.json();
      if (result.success) {
        toast({ title: t('deleteSuccess') });
        fetchData();
      }
    } catch {
      toast({ title: t('operationFailed'), variant: 'destructive' });
    }
  };

  return (
    <MainLayout title={t('trainingManagement')}>
      <div className="p-6 space-y-6">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold">{t('trainingManagement')}</h1>
          <div className="flex gap-2">
            <div className="flex items-center gap-2">
              <Input
                placeholder={tc('searchTrainingPlaceholder')}
                value={searchName}
                onChange={(e) => setSearchName(e.target.value)}
                className="w-36 h-8 text-sm"
              />
              <Button size="sm" variant="outline" onClick={fetchData}>
                <Search className="h-3 w-3" />
              </Button>
            </div>
            <Button
              size="sm"
              onClick={() => {
                setEditItem({});
                setShowDialog(true);
              }}
            >
              <Plus className="h-3 w-3 mr-1" />
              {t('newTraining')}
            </Button>
          </div>
        </div>
        <Card>
          <CardContent className="p-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-xs w-12 text-center">{tc('serialNo')}</TableHead>
                  <TableHead className="text-xs">{tc('trainingNo')}</TableHead>
                  <TableHead className="text-xs">{tc('trainingName')}</TableHead>
                  <TableHead className="text-xs">{tc('trainingType')}</TableHead>
                  <TableHead className="text-xs">{tc('trainingDate')}</TableHead>
                  <TableHead className="text-xs">{tc('hours')}</TableHead>
                  <TableHead className="text-xs">{tc('trainer')}</TableHead>
                  <TableHead className="text-xs">{tc('location')}</TableHead>
                  <TableHead className="text-xs">{tc('status')}</TableHead>
                  <TableHead className="text-xs">{tc('actions')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {list.map((item, index) => {
                  const st = statusMap[item.status] || statusMap[1];
                  return (
                    <TableRow key={item.id}>
                      <TableCell className="text-xs text-center text-muted-foreground">
                        {(page - 1) * 20 + index + 1}
                      </TableCell>
                      <TableCell className="text-xs font-mono">{item.training_no}</TableCell>
                      <TableCell className="text-xs">{item.training_name}</TableCell>
                      <TableCell className="text-xs">
                        {t(typeMap[item.training_type] || 'unknown')}
                      </TableCell>
                      <TableCell className="text-xs">{formatDate(item.training_date)}</TableCell>
                      <TableCell className="text-xs">{item.training_hours || '-'}h</TableCell>
                      <TableCell className="text-xs">{item.trainer || '-'}</TableCell>
                      <TableCell className="text-xs">{item.training_place || '-'}</TableCell>
                      <TableCell>
                        <Badge variant={st.variant} className="text-xs">
                          {st.label}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          {item.status === 1 && (
                            <Button
                              size="sm"
                              variant="ghost"
                              className="h-6 text-xs px-2"
                              onClick={() => handleStatusChange(item.id, 2)}
                            >
                              {tc('start')}
                            </Button>
                          )}
                          {item.status === 2 && (
                            <Button
                              size="sm"
                              variant="ghost"
                              className="h-6 text-xs px-2"
                              onClick={() => handleStatusChange(item.id, 3)}
                            >
                              {tc('complete')}
                            </Button>
                          )}
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-6 w-6 p-0"
                            onClick={() => {
                              setEditItem(item);
                              setShowDialog(true);
                            }}
                          >
                            <Edit className="h-3 w-3" />
                          </Button>
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-6 w-6 p-0 text-red-600"
                            onClick={() => handleDelete(item.id)}
                          >
                            <Trash2 className="h-3 w-3" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
                {list.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={10} className="text-center text-muted-foreground py-8">
                      {tc('noRecords')}
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
        <div className="flex items-center justify-between">
          <span className="text-sm text-muted-foreground">
            {tc('totalRecords', { count: total })}
          </span>
          <div className="flex gap-2">
            <Button
              size="sm"
              variant="outline"
              disabled={page <= 1}
              onClick={() => setPage((p) => p - 1)}
            >
              {tc('prevPage')}
            </Button>
            <Button
              size="sm"
              variant="outline"
              disabled={page * 20 >= total}
              onClick={() => setPage((p) => p + 1)}
            >
              {tc('nextPage')}
            </Button>
          </div>
        </div>
        <Dialog open={showDialog} onOpenChange={setShowDialog}>
          <DialogContent className="max-w-lg" resizable>
            <DialogHeader>
              <DialogTitle>{t('addTrainingTitle')}</DialogTitle>
            </DialogHeader>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>{tc('trainingName')}</Label>
                <Input
                  value={editItem.training_name || ''}
                  onChange={(e) => setEditItem({ ...editItem, training_name: e.target.value })}
                />
              </div>
              <div>
                <Label>{tc('trainingType')}</Label>
                <Select
                  value={String(editItem.training_type || 1)}
                  onValueChange={(v) => setEditItem({ ...editItem, training_type: Number(v) })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="1">{tc('safetyTraining')}</SelectItem>
                    <SelectItem value="2">{tc('skillTraining')}</SelectItem>
                    <SelectItem value="3">{tc('qualityTraining')}</SelectItem>
                    <SelectItem value="4">{tc('managementTraining')}</SelectItem>
                    <SelectItem value="5">{tc('newEmployeeTraining')}</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>{tc('trainingDate')}</Label>
                <Input
                  type="date"
                  value={editItem.training_date || ''}
                  onChange={(e) => setEditItem({ ...editItem, training_date: e.target.value })}
                />
              </div>
              <div>
                <Label>{tc('hours')}</Label>
                <Input
                  type="number"
                  value={editItem.training_hours ?? ''}
                  onChange={(e) =>
                    setEditItem({ ...editItem, training_hours: Number(e.target.value) })
                  }
                />
              </div>
              <div>
                <Label>{tc('trainer')}</Label>
                <Input
                  value={editItem.trainer || ''}
                  onChange={(e) => setEditItem({ ...editItem, trainer: e.target.value })}
                />
              </div>
              <div>
                <Label>{tc('location')}</Label>
                <Input
                  value={editItem.training_place || ''}
                  onChange={(e) => setEditItem({ ...editItem, training_place: e.target.value })}
                />
              </div>
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={() => setShowDialog(false)}>
                {tc('cancel')}
              </Button>
              <Button onClick={handleSave}>{tc('save')}</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    </MainLayout>
  );
}

import type { Metadata } from 'next';
import { getMessages } from 'next-intl/server';
import { cookies } from 'next/headers';
import { IntlProvider } from '@/components/IntlProvider';
import { notFound } from 'next/navigation';
import { locales, type Locale } from '@/i18n/locales';
import { AuthProvider, type InitialAuthData } from '@/contexts/AuthContext';
import { ToastProviderComponent } from '@/components/ui/toast';
import { SnowAdminThemeProvider } from '@/hooks/useSnowAdminTheme';
import SystemConfigInitializer from '@/components/SystemConfigInitializer';
import { HtmlLangSetter } from '@/components/HtmlLangSetter';
import { query } from '@/lib/db';
import { getMenusByToken } from '@/lib/menu-service';

let cachedCompanyName: string | null = null;
let cacheTimestamp: number = 0;
const CACHE_TTL = 5 * 60 * 1000;

async function getMessagesByLocale(locale: string) {
  try {
    return (await import(`../../../messages/${locale}.json`)).default;
  } catch {
    return (await import(`../../../messages/zh-CN.json`)).default;
  }
}

async function getCompanyName(locale: string): Promise<string> {
  const now = Date.now();
  if (cachedCompanyName && now - cacheTimestamp < CACHE_TTL) {
    return cachedCompanyName;
  }
  try {
    const rows = await query<{ config_value: string }>(
      `SELECT config_value FROM sys_config WHERE config_key IN ('company_name', 'company_short_name') ORDER BY FIELD(config_key, 'company_name', 'company_short_name') LIMIT 1`
    );
    if (Array.isArray(rows) && rows.length > 0 && rows[0]?.config_value) {
      cachedCompanyName = rows[0].config_value;
      cacheTimestamp = now;
      return cachedCompanyName!;
    }
  } catch {
    if (cachedCompanyName) return cachedCompanyName;
  }
  const messages = await getMessagesByLocale(locale);
  return messages?.Common?.companyName || '公司名称';
}

/**
 * 服务端预取菜单数据。
 *
 * 读取 access_token cookie，若存在则轻量级校验 JWT 并查询菜单。
 * 任何失败（无 cookie / token 过期 / DB 异常）均返回 null，
 * AuthProvider 会降级到客户端 fetch + localStorage 缓存。
 *
 * 注意：服务端不能 HTTP 自调 /api/auth/menus，必须直接调用菜单服务函数。
 */
async function prefetchMenus(): Promise<InitialAuthData | null> {
  try {
    const cookieStore = await cookies();
    const token = cookieStore.get('access_token')?.value;
    if (!token) return null;

    const result = await getMenusByToken(token);
    if (!result) return null;

    return {
      menus: result.menus,
      permissions: result.permissions,
    };
  } catch {
    // SSR 预取失败时静默降级，不影响页面渲染
    return null;
  }
}

export function generateStaticParams() {
  return locales.map((locale) => ({ locale }));
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ locale: string }>;
}): Promise<Metadata> {
  const { locale: rawLocale } = await params;
  const locale = (locales as readonly string[]).includes(rawLocale)
    ? (rawLocale as Locale)
    : 'zh-CN';

  const messages = await getMessagesByLocale(locale);

  const title = messages?.Common?.appTitle || 'VNERP';
  const description = messages?.Common?.appDescription || 'VNERP ERP系统';

  return {
    title,
    description,
  };
}

export default async function LocaleLayout({
  children,
  params,
}: {
  children: React.ReactNode;
  params: Promise<{ locale: string }>;
}) {
  const { locale: rawLocale } = await params;
  const locale = (locales as readonly string[]).includes(rawLocale)
    ? (rawLocale as Locale)
    : 'zh-CN';

  if (!locales.includes(locale)) {
    notFound();
  }

  const messages = await getMessages();
  const _companyName = await getCompanyName(locale);
  const initialAuth = await prefetchMenus();

  return (
    <>
      <HtmlLangSetter locale={locale} />
      <IntlProvider locale={locale} messages={messages}>
        <SnowAdminThemeProvider>
          <AuthProvider initialAuth={initialAuth}>
            <SystemConfigInitializer />
            <ToastProviderComponent>{children}</ToastProviderComponent>
          </AuthProvider>
        </SnowAdminThemeProvider>
      </IntlProvider>
    </>
  );
}

