  useEffect(() => {
    const scheduleBlink = () => {
      const timeout = setTimeout(
        () => {
          setIsPurpleBlinking(true);
          setTimeout(() => {
            setIsPurpleBlinking(false);
            scheduleBlink();
          }, 150);
        },
        Math.random() * 4000 + 3000
      );
      return timeout;
    };
    const timeout = scheduleBlink();
    return () => clearTimeout(timeout);
  }, []);

  useEffect(() => {
    const scheduleBlink = () => {
      const timeout = setTimeout(
        () => {
          setIsBlackBlinking(true);
          setTimeout(() => {
            setIsBlackBlinking(false);
            scheduleBlink();
          }, 150);
        },
        Math.random() * 4000 + 3000
      );
      return timeout;
    };
    const timeout = scheduleBlink();
    return () => clearTimeout(timeout);
  }, []);

