      return () => clearTimeout(timer);
    } else {
      setIsLookingAtEachOther(false);
    }
  }, [isTyping]);

  useEffect(() => {
    if (loginForm.password.length > 0 && showPassword) {
      const schedulePeek = () => {
        const peekInterval = setTimeout(
          () => {
            setIsPurplePeeking(true);
            setTimeout(() => {
              setIsPurplePeeking(false);
            }, 800);
          },
          Math.random() * 3000 + 2000
        );
        return peekInterval;
      };
      const firstPeek = schedulePeek();
      return () => clearTimeout(firstPeek);
    } else {
      setIsPurplePeeking(false);
    }
  }, [loginForm.password, showPassword, isPurplePeeking]);

  const calculatePosition = (ref: React.RefObject<HTMLDivElement | null>) => {
    if (!ref.current) return { faceX: 0, faceY: 0, bodySkew: 0 };
    const rect = ref.current.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 3;
    const deltaX = mouseX - centerX;
    const deltaY = mouseY - centerY;
    const faceX = Math.max(-15, Math.min(15, deltaX / 20));
    const faceY = Math.max(-10, Math.min(10, deltaY / 30));
    const bodySkew = Math.max(-6, Math.min(6, -deltaX / 120));
    return { faceX, faceY, bodySkew };
  };

  const purplePos = calculatePosition(purpleRef);
  const blackPos = calculatePosition(blackRef);
  const yellowPos = calculatePosition(yellowRef);
  const orangePos = calculatePosition(orangeRef);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const result = await login(loginForm.username, loginForm.password, loginForm.rememberMe);

      if (result.success) {
        const userStr = localStorage.getItem('user') || sessionStorage.getItem('user');
        if (userStr) {
          const user = JSON.parse(userStr);
          if (user.firstLogin) {
            setLoggedInUserId(user.id);
            setShowChangePwd(true);
            setLoading(false);
            return;
          }
        }
        toast.success(t('loginSuccess'));
        router.replace('/dashboard');
      } else {
        setError(result.message || t('loginFailed'));
      }
    } catch {
      setError(t('loginFailed'));
    } finally {
      setLoading(false);
    }
  };

  const handleChangePwd = async () => {
    if (!changePwdForm.newPassword || changePwdForm.newPassword.length < 6) {
      toast.error(t('passwordMismatch'));
      return;
    }
    if (changePwdForm.newPassword !== changePwdForm.confirmPassword) {
      toast.error(t('passwordMismatch'));
      return;
    }
    setChangePwdLoading(true);
    try {
      const res = await fetch('/api/auth/change-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: loggedInUserId,
          oldPassword: changePwdForm.oldPassword,
          newPassword: changePwdForm.newPassword,
        }),
      });
      const result = await res.json();
      if (result.success) {
        toast.success(t('changePassword') + ' - OK');
        setShowChangePwd(false);
        const userStr = localStorage.getItem('user') || sessionStorage.getItem('user');
        if (userStr) {
          const user = JSON.parse(userStr);
          user.firstLogin = false;
          (localStorage.getItem('user') ? localStorage : sessionStorage).setItem(
            'user',
            JSON.stringify(user)
          );
        }
        router.replace('/dashboard');
      } else {
        toast.error(result.message || '修改失败');
      }
    } catch {
      toast.error(t('changePassword') + ' - ' + tc('error'));
    } finally {
      setChangePwdLoading(false);
    }
  };

