            <Button
              type="submit"
              className="w-full h-12 text-base font-medium"
              size="lg"
              disabled={loading}
              data-testid="login-submit"
            >
              {loading ? (
                <div className="flex items-center justify-center">
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  {t('login')}...
