'use client';

import React, { useState } from 'react';
import { useRouter } from '@/i18n/navigation';
import { Save, X, Plus, Trash2, Search, Package } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { useToastContext } from '@/components/ui/toast';
import { MainLayout } from '@/components/layout/main-layout';
import { authFetch } from '@/lib/auth-fetch';
import { useTranslations } from 'next-intl';

interface BOMLine {
  id?: number;
  material_id: number;
  material_code: string;
  material_name: string;
  material_spec: string;
  unit: string;
  consumption_qty: number;
  loss_rate: number;
  unit_cost: number;
  material_type: string;
  is_key_material: boolean;
  position_no: string;
  process_seq: number | null;
  process_name: string;
  remark: string;
}

const materialTypes = [
  { value: 'RAW', labelKey: 'materialTypeRaw' },
  { value: 'SEMI', labelKey: 'materialTypeSemi' },
  { value: 'PACK', labelKey: 'materialTypePack' },
  { value: 'TOOL', labelKey: 'materialTypeTool' },
  { value: 'OTHER', labelKey: 'materialTypeOther' },
];

const units = [
  { value: '件', labelKey: 'unitPiece' },
  { value: '个', labelKey: 'unitItem' },
  { value: '套', labelKey: 'unitSet' },
  { value: '米', labelKey: 'unitMeter' },
  { value: '千克', labelKey: 'unitKg' },
  { value: '克', labelKey: 'unitGram' },
  { value: '毫升', labelKey: 'unitMl' },
  { value: '升', labelKey: 'unitLiter' },
];

export default function CreateBOMPage() {
  // 翻译钩子
  const t = useTranslations('Orders');
  const tc = useTranslations('Common');

  const router = useRouter();
  const { addToast: toast } = useToastContext();

  const [formData, setFormData] = useState({
    product_id: 0,
    product_code: '',
    product_name: '',
    product_spec: '',
    version: 'V1.0',
    base_qty: 1,
    unit: '件',
    remark: '',
  });

  const [lines, setLines] = useState<BOMLine[]>([]);
  const [materialDialogOpen, setMaterialDialogOpen] = useState(false);
  const [currentLineIndex, setCurrentLineIndex] = useState<number>(-1);
  const [searchKeyword, setSearchKeyword] = useState('');
  const [materials, setMaterials] = useState<Loose[]>([]);
  const [loading, setLoading] = useState(false);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleNumberChange = (name: string, value: string) => {
    const numValue = value === '' ? 0 : parseFloat(value);
    setFormData((prev) => ({
      ...prev,
      [name]: numValue,
    }));
  };

  const addNewLine = () => {
    const newLine: BOMLine = {
      material_id: 0,
      material_code: '',
      material_name: '',
      material_spec: '',
      unit: '件',
      consumption_qty: 1,
      loss_rate: 0,
      unit_cost: 0,
      material_type: 'RAW',
      is_key_material: false,
      position_no: '',
      process_seq: null,
      process_name: '',
      remark: '',
    };
    setLines((prev) => [...prev, newLine]);
  };

  const removeLine = (index: number) => {
    setLines((prev) => prev.filter((_, i) => i !== index));
  };

  const updateLine = (index: number, field: keyof BOMLine, value: Loose) => {
    setLines((prev) => {
      const newLines = [...prev];
      newLines[index] = {
        ...newLines[index],
        [field]: value,
      };
      return newLines;
    });
  };

  const openMaterialDialog = (lineIndex: number) => {
    setCurrentLineIndex(lineIndex);
    setSearchKeyword('');
    setMaterials([]);
    setMaterialDialogOpen(true);
  };

  const fetchMaterials = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (searchKeyword) params.append('keyword', searchKeyword);

      const res = await authFetch(`/api/orders/bom/materials?${params}`);
      const data = await res.json();

      if (data.success) {
        setMaterials(data.data || []);
      } else {
        toast({
          title: tc('error'),
          description: data.message || t('fetchMaterialsFailed'),
          variant: 'destructive',
        });
      }
    } catch {
      toast({
        title: tc('error'),
        description: t('fetchMaterialsFailed'),
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const selectMaterial = (material: Loose) => {
    if (currentLineIndex < 0) return;
    updateLine(currentLineIndex, 'material_id', material.id);
    updateLine(currentLineIndex, 'material_code', material.material_code);
    updateLine(currentLineIndex, 'material_name', material.material_name);
    updateLine(currentLineIndex, 'material_spec', material.material_spec);
    updateLine(currentLineIndex, 'unit', material.unit);
    updateLine(currentLineIndex, 'unit_cost', parseFloat(String(material.unit_cost || 0)));
    updateLine(currentLineIndex, 'material_type', material.material_type);
    setMaterialDialogOpen(false);
    setCurrentLineIndex(-1);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.product_code || !formData.product_name) {
      toast({
        title: tc('error'),
        description: t('productCodeNameRequired'),
        variant: 'destructive',
      });
      return;
    }

    if (lines.length === 0) {
      toast({
        title: tc('error'),
        description: t('bomDetailsRequired'),
        variant: 'destructive',
      });
      return;
    }

    const hasEmptyMaterial = lines.some((l) => !l.material_code || !l.material_name);
    if (hasEmptyMaterial) {
      toast({
        title: tc('error'),
        description: t('materialRequired'),
        variant: 'destructive',
      });
      return;
    }

    try {
      setLoading(true);

      const response = await authFetch('/api/orders/bom', {
        method: 'POST',
        body: JSON.stringify({
          ...formData,
          lines,
        }),
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: tc('success'),
          description: t('bomCreateSuccess'),
        });
        router.push('/orders/bom');
      } else {
        toast({
          title: tc('error'),
          description: data.message || t('bomCreateFailed'),
          variant: 'destructive',
        });
      }
    } catch {
      toast({
        title: tc('error'),
        description: t('bomCreateFailed'),
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <MainLayout title={t('createBom')}>
      <div className="container mx-auto px-4 py-8">
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">{t('createBom')}</h1>
          <Button onClick={() => router.back()} variant="secondary">
            <X className="h-4 w-4 mr-2" />
            {tc('back')}
          </Button>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>{t('basicInfo')}</CardTitle>
            <CardDescription>{t('basicInfoDesc')}</CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <Label htmlFor="product_code">{t('productCode')}</Label>
                  <Input
                    id="product_code"
                    name="product_code"
                    value={formData.product_code}
                    onChange={handleInputChange}
                    placeholder={t('productCodePlaceholder')}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="product_name">{t('productName')}</Label>
                  <Input
                    id="product_name"
                    name="product_name"
                    value={formData.product_name}
                    onChange={handleInputChange}
                    placeholder={t('productNamePlaceholder')}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="product_spec">{t('productSpec')}</Label>
                  <Input
                    id="product_spec"
                    name="product_spec"
                    value={formData.product_spec}
                    onChange={handleInputChange}
                    placeholder={t('productSpecPlaceholder')}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="version">{t('versionNo')}</Label>
                  <Input
                    id="version"
                    name="version"
                    value={formData.version}
                    onChange={handleInputChange}
                    placeholder={t('versionNoPlaceholder')}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="base_qty">{t('baseQty')}</Label>
                  <Input
                    id="base_qty"
                    name="base_qty"
                    type="number"
                    min="1"
                    step="0.001"
                    value={formData.base_qty}
                    onChange={(e) => handleNumberChange('base_qty', e.target.value)}
                    placeholder={t('baseQtyPlaceholder')}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="unit">{t('unit')}</Label>
                  <Select
                    value={formData.unit}
                    onValueChange={(value) => setFormData((prev) => ({ ...prev, unit: value }))}
                  >
                    <SelectTrigger id="unit">
                      <SelectValue placeholder={t('unitPlaceholder')} />
                    </SelectTrigger>
                    <SelectContent>
                      {units.map((unit) => (
                        <SelectItem key={unit.value} value={unit.value}>
                          {t(unit.labelKey)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="remark">{tc('remark')}</Label>
                <Textarea
                  id="remark"
                  name="remark"
                  value={formData.remark}
                  onChange={handleInputChange}
                  placeholder={t('remarkPlaceholder')}
                  rows={3}
                />
              </div>

              <div className="border-t pt-6">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-lg font-semibold">{t('bomDetails')}</h2>
                  <Button onClick={addNewLine} type="button">
                    <Plus className="h-4 w-4 mr-2" />
                    {t('addMaterial')}
                  </Button>
                </div>

                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-12">{t('sequence')}</TableHead>
                      <TableHead>{t('materialCode')}</TableHead>
                      <TableHead>{t('materialName')}</TableHead>
                      <TableHead>{t('spec')}</TableHead>
                      <TableHead>{t('unit')}</TableHead>
                      <TableHead>{t('consumptionQty')}</TableHead>
                      <TableHead>{t('lossRatePercent')}</TableHead>
                      <TableHead>{t('unitPrice')}</TableHead>
                      <TableHead>{t('materialType')}</TableHead>
                      <TableHead>{t('keyMaterial')}</TableHead>
                      <TableHead className="text-right">{tc('operation')}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {lines.map((line, index) => (
                      <TableRow key={index}>
                        <TableCell>{index + 1}</TableCell>
                        <TableCell>
                          <div className="flex items-center space-x-2">
                            <Input
                              value={line.material_code}
                              onChange={(e) => updateLine(index, 'material_code', e.target.value)}
                              placeholder={tc('code')}
                              className="w-32"
                            />
                            <Button
                              variant="ghost"
                              size="sm"
                              type="button"
                              onClick={() => openMaterialDialog(index)}
                            >
                              <Search className="h-4 w-4" />
                            </Button>
                          </div>
                        </TableCell>
                        <TableCell>
                          <Input
                            value={line.material_name}
                            onChange={(e) => updateLine(index, 'material_name', e.target.value)}
                            placeholder={tc('name')}
                          />
                        </TableCell>
                        <TableCell>
                          <Input
                            value={line.material_spec}
                            onChange={(e) => updateLine(index, 'material_spec', e.target.value)}
                            placeholder={t('placeholderSpec')}
                          />
                        </TableCell>
                        <TableCell>
                          <Select
                            value={line.unit}
                            onValueChange={(value) => updateLine(index, 'unit', value)}
                          >
                            <SelectTrigger className="w-20">
                              <SelectValue placeholder={t('placeholderUnit')} />
                            </SelectTrigger>
                            <SelectContent>
                              {units.map((unit) => (
                                <SelectItem key={unit.value} value={unit.value}>
                                  {t(unit.labelKey)}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </TableCell>
                        <TableCell>
                          <Input
                            type="number"
                            min="0.001"
                            step="0.001"
                            value={line.consumption_qty}
                            onChange={(e) =>
                              updateLine(index, 'consumption_qty', parseFloat(e.target.value) || 0)
                            }
                            placeholder={t('placeholderQty')}
                            className="w-24"
                          />
                        </TableCell>
                        <TableCell>
                          <Input
                            type="number"
                            min="0"
                            step="0.1"
                            value={line.loss_rate}
                            onChange={(e) =>
                              updateLine(index, 'loss_rate', parseFloat(e.target.value) || 0)
                            }
                            placeholder={t('placeholderLossRate')}
                            className="w-24"
                          />
                        </TableCell>
                        <TableCell>
                          <Input
                            type="number"
                            min="0"
                            step="0.01"
                            value={line.unit_cost}
                            onChange={(e) =>
                              updateLine(index, 'unit_cost', parseFloat(e.target.value) || 0)
                            }
                            placeholder={t('placeholderUnitPrice')}
                            className="w-24"
                          />
                        </TableCell>
                        <TableCell>
                          <Select
                            value={line.material_type}
                            onValueChange={(value) => updateLine(index, 'material_type', value)}
                          >
                            <SelectTrigger className="w-32">
                              <SelectValue placeholder={tc('type')} />
                            </SelectTrigger>
                            <SelectContent>
                              {materialTypes.map((type) => (
                                <SelectItem key={type.value} value={type.value}>
                                  {t(type.labelKey)}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </TableCell>
                        <TableCell>
                          <input
                            type="checkbox"
                            checked={line.is_key_material}
                            onChange={(e) => updateLine(index, 'is_key_material', e.target.checked)}
                          />
                        </TableCell>
                        <TableCell className="text-right">
                          <Button
                            variant="destructive"
                            size="sm"
                            type="button"
                            onClick={() => removeLine(index)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>

                {lines.length === 0 && (
                  <div className="text-center py-8 text-gray-500">
                    <Package className="h-12 w-12 mx-auto mb-2 opacity-50" />
                    <p>{t('noBomLines')}</p>
                  </div>
                )}
              </div>

              <CardFooter className="flex justify-end space-x-4">
                <Button variant="secondary" onClick={() => router.back()} type="button">
                  {tc('cancel')}
                </Button>
                <Button type="submit" loading={loading}>
                  <Save className="h-4 w-4 mr-2" />
                  {tc('save')}
                </Button>
              </CardFooter>
            </form>
          </CardContent>
        </Card>
      </div>

      <Dialog open={materialDialogOpen} onOpenChange={setMaterialDialogOpen}>
        <DialogContent className="sm:max-w-2xl" resizable>
          <DialogHeader>
            <DialogTitle>{t('selectMaterialTitle', { row: currentLineIndex + 1 })}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div className="flex space-x-2">
              <Input
                value={searchKeyword}
                onChange={(e) => setSearchKeyword(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && fetchMaterials()}
                placeholder={t('searchMaterialPlaceholder')}
              />
              <Button onClick={fetchMaterials} loading={loading} type="button">
                <Search className="h-4 w-4 mr-2" />
                {tc('search')}
              </Button>
            </div>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>{t('materialCode')}</TableHead>
                  <TableHead>{t('materialName')}</TableHead>
                  <TableHead>{t('spec')}</TableHead>
                  <TableHead>{t('unit')}</TableHead>
                  <TableHead>{t('unitPrice')}</TableHead>
                  <TableHead>{tc('operation')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {materials.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={6} className="text-center py-4 text-gray-500">
                      {t('searchMaterialHint')}
                    </TableCell>
                  </TableRow>
                ) : (
                  materials.map((material) => (
                    <TableRow key={material.id}>
                      <TableCell>{material.material_code}</TableCell>
                      <TableCell>{material.material_name}</TableCell>
                      <TableCell>{material.material_spec}</TableCell>
                      <TableCell>{material.unit}</TableCell>
                      <TableCell>{material.unit_cost}</TableCell>
                      <TableCell>
                        <Button size="sm" type="button" onClick={() => selectMaterial(material)}>
                          {t('select')}
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>
        </DialogContent>
      </Dialog>
    </MainLayout>
  );
}

'use client';

import { authFetch } from '@/lib/auth-fetch';
import React, { useState, useEffect } from 'react';
import { useRouter } from '@/i18n/navigation';
import {
  Search,
  Plus,
  Edit,
  Trash2,
  Eye,
  FileText,
  CheckCircle,
  XCircle,
  Package,
  Layers,
  MoreHorizontal,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { useToastContext } from '@/components/ui/toast';
import { MainLayout } from '@/components/layout/main-layout';
import { useTranslations } from 'next-intl';

interface BOMItem {
  id: number;
  bom_no: string;
  product_code: string;
  product_name: string;
  product_spec: string;
  version: string;
  is_default: number;
  status: number;
  status_name: string;
  unit: string;
  base_qty: number;
  total_material_count: number;
  total_cost: number;
  remark: string;
  create_time: string;
  update_time: string;
}

const statusMap: Record<number, { labelKey: string; color: string }> = {
  10: { labelKey: 'draft', color: 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200' },
  20: {
    labelKey: 'approved',
    color: 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200',
  },
  30: {
    labelKey: 'published',
    color: 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200',
  },
  90: { labelKey: 'disabled', color: 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200' },
};

const getStatusLabel = (status: number, t: (k: string) => string, tc: (k: string) => string) => {
  const key = statusMap[status]?.labelKey;
  if (!key) return tc('unknown');
  if (key === 'draft' || key === 'approved' || key === 'disabled') return tc(key);
  return t(key);
};

export default function BOMPage() {
  const t = useTranslations('Orders');
  const tc = useTranslations('Common');

  const router = useRouter();
  const { addToast: toast } = useToastContext();
  const [bomList, setBomList] = useState<BOMItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchKeyword, setSearchKeyword] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [detailDialogOpen, setDetailDialogOpen] = useState(false);
  const [bomDetail, setBomDetail] = useState<Loose>(null);

  const fetchBOMList = async (overridePage?: number) => {
    try {
      setLoading(true);
      const pageToUse = overridePage ?? currentPage;
      const params = new URLSearchParams({
        page: pageToUse.toString(),
        pageSize: '20',
      });
      if (searchKeyword) params.append('keyword', searchKeyword);

      const res = await authFetch(`/api/orders/bom?${params}`);
      const data = await res.json();

      if (data.success) {
        const bomList = Array.isArray(data.data) ? data.data : data.data?.list || [];
        setBomList(bomList);
        const total = data.data?.total || 0;
        setTotalPages(Math.ceil(total / 20) || 1);
      } else {
        toast({
          title: tc('error'),
          description: data.message || t('fetchBomFailed'),
          variant: 'destructive',
        });
      }
    } catch {
      toast({
        title: tc('error'),
        description: t('fetchBomFailed'),
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchBOMDetail = async (id: number) => {
    try {
      const res = await authFetch(`/api/orders/bom/${id}`);
      const data = await res.json();

      if (data.success) {
        setBomDetail(data.data);
        setDetailDialogOpen(true);
      } else {
        toast({
          title: tc('error'),
          description: data.message || t('fetchBomDetailFailed'),
          variant: 'destructive',
        });
      }
    } catch {
      toast({
        title: tc('error'),
        description: t('fetchBomDetailFailed'),
        variant: 'destructive',
      });
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm(t('confirmDeleteBom'))) return;

    try {
      const res = await authFetch(`/api/orders/bom?id=${id}`, {
        method: 'DELETE',
      });
      const data = await res.json();

      if (data.success) {
        toast({
          title: tc('success'),
          description: t('deleteBomSuccess'),
        });
        fetchBOMList();
      } else {
        toast({
          title: tc('error'),
          description: data.message || t('deleteFailed'),
          variant: 'destructive',
        });
      }
    } catch {
      toast({
        title: tc('error'),
        description: t('deleteFailed'),
        variant: 'destructive',
      });
    }
  };

  const handleStatusChange = async (id: number, action: string) => {
    try {
      const res = await authFetch('/api/orders/bom', {
        method: 'PUT',
        body: JSON.stringify({ id, action }),
      });
      const data = await res.json();

      if (data.success) {
        toast({
          title: tc('success'),
          description:
            action === 'audit'
              ? t('auditSuccess')
              : action === 'publish'
                ? t('publishSuccess')
                : t('disableSuccess'),
        });
        fetchBOMList();
      } else {
        toast({
          title: '错误',
          description: data.message || tc('error'),
          variant: 'destructive',
        });
      }
    } catch {
      toast({
        title: '错误',
        description: tc('error'),
        variant: 'destructive',
      });
    }
  };

  const handleSearch = () => {
    setCurrentPage(1);
    fetchBOMList(1);
  };

  useEffect(() => {
    fetchBOMList();
  }, [currentPage]);

  return (
    <MainLayout title={t('bomManagement')}>
      <div className="p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Layers className="w-8 h-8 text-blue-600 dark:text-blue-400" />
            <div>
              <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
                {t('bomManagement')}
              </h1>
              <p className="text-sm text-gray-500 dark:text-gray-400">{t('bomListManagement')}</p>
            </div>
          </div>
          <Button onClick={() => router.push('/orders/bom/create')}>
            <Plus className="w-4 h-4 mr-2" />
            {t('newBom')}
          </Button>
        </div>

        <div className="flex gap-4">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <Input
              placeholder={t('searchBom')}
              value={searchKeyword}
              onChange={(e) => setSearchKeyword(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
              className="pl-10"
            />
          </div>
          <Button variant="outline" onClick={handleSearch}>
            <Search className="w-4 h-4 mr-2" />
            {tc('search')}
          </Button>
        </div>

        <div className="rounded-lg border shadow-sm bg-card">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>{t('bomNo')}</TableHead>
                <TableHead>{t('productInfo')}</TableHead>
                <TableHead>{t('version')}</TableHead>
                <TableHead>{tc('status')}</TableHead>
                <TableHead>{t('materialCount')}</TableHead>
                <TableHead>{t('totalCost')}</TableHead>
                <TableHead>{tc('createTime')}</TableHead>
                <TableHead className="text-right">{tc('operation')}</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={8} className="text-center py-8">
                    {tc('loading')}
                  </TableCell>
                </TableRow>
              ) : bomList.length === 0 ? (
                <TableRow>
                  <TableCell
                    colSpan={8}
                    className="text-center py-8 text-gray-500 dark:text-gray-400"
                  >
                    {t('noBomData')}
                  </TableCell>
                </TableRow>
              ) : (
                bomList.map((bom) => (
                  <TableRow key={bom.id}>
                    <TableCell className="font-medium">{bom.bom_no}</TableCell>
                    <TableCell>
                      <div>
                        <div className="font-medium">{bom.product_name}</div>
                        <div className="text-sm text-gray-500 dark:text-gray-400">
                          {bom.product_code}
                        </div>
                        {bom.product_spec && (
                          <div className="text-xs text-gray-400 dark:text-gray-500">
                            {bom.product_spec}
                          </div>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <span>{bom.version}</span>
                        {bom.is_default === 1 && (
                          <Badge variant="default" className="text-xs">
                            {t('default')}
                          </Badge>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge
                        className={statusMap[bom.status]?.color || 'bg-gray-100 dark:bg-gray-700'}
                      >
                        {getStatusLabel(bom.status, t, tc)}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      {bom.total_material_count} {t('itemsUnit')}
                    </TableCell>
                    <TableCell>¥{Number(bom.total_cost || 0).toFixed(4)}</TableCell>
                    <TableCell>{new Date(bom.create_time).toLocaleDateString()}</TableCell>
                    <TableCell className="text-right">
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="sm">
                            <MoreHorizontal className="w-4 h-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => fetchBOMDetail(bom.id)}>
                            <Eye className="w-4 h-4 mr-2" />
                            {t('viewDetail')}
                          </DropdownMenuItem>
                          {bom.status === 10 && (
                            <DropdownMenuItem onClick={() => handleStatusChange(bom.id, 'audit')}>
                              <CheckCircle className="w-4 h-4 mr-2" />
                              {t('audit')}
                            </DropdownMenuItem>
                          )}
                          {bom.status === 20 && (
                            <DropdownMenuItem onClick={() => handleStatusChange(bom.id, 'publish')}>
                              <FileText className="w-4 h-4 mr-2" />
                              {t('publish')}
                            </DropdownMenuItem>
                          )}
                          {bom.status === 30 && (
                            <DropdownMenuItem onClick={() => handleStatusChange(bom.id, 'disable')}>
                              <XCircle className="w-4 h-4 mr-2" />
                              {t('disable')}
                            </DropdownMenuItem>
                          )}
                          {bom.status < 30 && (
                            <DropdownMenuItem
                              onClick={() => router.push(`/orders/bom/edit/${bom.id}`)}
                            >
                              <Edit className="w-4 h-4 mr-2" />
                              {tc('edit')}
                            </DropdownMenuItem>
                          )}
                          {bom.status < 30 && (
                            <DropdownMenuItem
                              onClick={() => handleDelete(bom.id)}
                              className="text-red-600 dark:text-red-400"
                            >
                              <Trash2 className="w-4 h-4 mr-2" />
                              {tc('delete')}
                            </DropdownMenuItem>
                          )}
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>

        {totalPages > 1 && (
          <div className="flex justify-center gap-2">
            <Button
              variant="outline"
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              disabled={currentPage === 1}
            >
              {tc('prevPage')}
            </Button>
            <span className="flex items-center px-4">
              {currentPage} / {totalPages}
            </span>
            <Button
              variant="outline"
              onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
              disabled={currentPage === totalPages}
            >
              {tc('nextPage')}
            </Button>
          </div>
        )}

        <Dialog open={detailDialogOpen} onOpenChange={setDetailDialogOpen}>
          <DialogContent className="max-w-6xl w-[90vw] max-h-[90vh] overflow-y-auto" resizable>
            <DialogHeader>
              <DialogTitle>{t('bomDetail')}</DialogTitle>
            </DialogHeader>
            {bomDetail && (
              <div className="space-y-6">
                <div className="grid grid-cols-2 gap-4 p-4 bg-gray-50 dark:bg-slate-700 rounded-lg">
                  <div>
                    <label className="text-sm text-gray-500 dark:text-gray-400">{t('bomNo')}</label>
                    <div className="font-medium">{bomDetail.header.bom_no}</div>
                  </div>
                  <div>
                    <label className="text-sm text-gray-500 dark:text-gray-400">
                      {t('version')}
                    </label>
                    <div className="font-medium">{bomDetail.header.version}</div>
                  </div>
                  <div>
                    <label className="text-sm text-gray-500 dark:text-gray-400">
                      {t('productName')}
                    </label>
                    <div className="font-medium">{bomDetail.header.product_name}</div>
                  </div>
                  <div>
                    <label className="text-sm text-gray-500 dark:text-gray-400">
                      {t('productCode')}
                    </label>
                    <div className="font-medium">{bomDetail.header.product_code}</div>
                  </div>
                  <div>
                    <label className="text-sm text-gray-500 dark:text-gray-400">
                      {tc('status')}
                    </label>
                    <div>
                      <Badge className={statusMap[bomDetail.header.status]?.color}>
                        {bomDetail.header.status_name}
                      </Badge>
                    </div>
                  </div>
                  <div>
                    <label className="text-sm text-gray-500 dark:text-gray-400">
                      {t('totalCost')}
                    </label>
                    <div className="font-medium text-blue-600 dark:text-blue-400">
                      ¥{parseFloat(bomDetail.header.total_cost || 0).toFixed(4)}
                    </div>
                  </div>
                </div>

                <div>
                  <h3 className="font-semibold mb-3 flex items-center gap-2">
                    <Package className="w-5 h-5" />
                    {t('bomDetailInfo', { count: bomDetail.lines?.length || 0 })}
                  </h3>
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>{t('lineNo')}</TableHead>
                        <TableHead>{t('materialCode')}</TableHead>
                        <TableHead>{t('materialName')}</TableHead>
                        <TableHead>{t('spec')}</TableHead>
                        <TableHead>{t('consumption')}</TableHead>
                        <TableHead>{t('lossRate')}</TableHead>
                        <TableHead>{t('actualUsage')}</TableHead>
                        <TableHead>{t('cost')}</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {bomDetail.lines?.map((line: Loose) => (
                        <TableRow key={line.id}>
                          <TableCell>{line.line_no}</TableCell>
                          <TableCell>{line.material_code}</TableCell>
                          <TableCell>{line.material_name}</TableCell>
                          <TableCell className="text-sm text-gray-500 dark:text-gray-400">
                            {line.material_spec}
                          </TableCell>
                          <TableCell>
                            {line.consumption_qty} {line.unit}
                          </TableCell>
                          <TableCell>{line.loss_rate}%</TableCell>
                          <TableCell>
                            {parseFloat(String(line.actual_qty || 0)).toFixed(4)}
                          </TableCell>
                          <TableCell>
                            ¥{parseFloat(String(line.total_cost || 0)).toFixed(4)}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </div>
            )}
          </DialogContent>
        </Dialog>
