'use client';

import { MainLayout } from '@/components/layout';
import {
  FileText,
  Factory,
  AlertTriangle,
  CheckCircle,
  Activity,
  Loader2,
  Maximize,
  Minimize,
  Clock,
  TrendingUp,
  ArrowUpRight,
  ArrowDownRight,
} from 'lucide-react';
import { useState, useEffect, useRef } from 'react';
import { useCompanyName } from '@/hooks/useCompanyName';
import { useTranslations } from 'next-intl';

interface DashboardStats {
  todayOrders: number;
  pendingWorkOrders: number;
  inventoryWarnings: number;
  todayCompleted: number;
  pendingOrderCount: number;
  producingCount: number;
  completedCount: number;
  totalValue: number;
}

interface RecentOrder {
  id: string;
  customer: string;
  product: string;
  quantity: number;
  status: string;
  statusClass: string;
  delivery: string;
}

interface RecentWorkOrder {
  id: string;
  product: string;
  quantity: number;
  status: string;
  statusClass: string;
  date: string;
}

const STATUS_MAP: Record<string, { labelKey: string; className: string }> = {
  1: {
    labelKey: 'statusPending',
    className: 'bg-gray-500/20 text-gray-300 border border-gray-500/30',
  },
  2: {
    labelKey: 'statusConfirmed',
    className: 'bg-blue-500/20 text-blue-300 border border-blue-500/30',
  },
  3: {
    labelKey: 'statusPartialShip',
    className: 'bg-orange-500/20 text-orange-300 border border-orange-500/30',
  },
  4: {
    labelKey: 'statusCompleted',
    className: 'bg-green-500/20 text-green-300 border border-green-500/30',
  },
  5: {
    labelKey: 'statusCancelled',
    className: 'bg-red-500/20 text-red-300 border border-red-500/30',
  },
};

const WORK_ORDER_STATUS_MAP: Record<string, { labelKey: string; className: string }> = {
  1: {
    labelKey: 'statusDraft',
    className: 'bg-gray-500/20 text-gray-300 border border-gray-500/30',
  },
  2: {
    labelKey: 'statusConfirmed',
    className: 'bg-blue-500/20 text-blue-300 border border-blue-500/30',
  },
  3: {
    labelKey: 'statusInProduction',
    className: 'bg-orange-500/20 text-orange-300 border border-orange-500/30',
  },
  4: {
    labelKey: 'statusCompleted',
    className: 'bg-green-500/20 text-green-300 border border-green-500/30',
  },
  5: {
    labelKey: 'statusCancelled',
    className: 'bg-red-500/20 text-red-300 border border-red-500/30',
  },
};

export default function DashboardPage() {
  const { companyName } = useCompanyName();
  const t = useTranslations('Dashboard');
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [recentOrders, setRecentOrders] = useState<RecentOrder[]>([]);
  const [recentWorkOrders, setRecentWorkOrders] = useState<RecentWorkOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentTime, setCurrentTime] = useState<Date | null>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const dashboardRef = useRef<HTMLDivElement>(null);
  const orderScrollRef = useRef<HTMLDivElement>(null);
  const workOrderScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        setLoading(true);

        const salesRes = await fetch('/api/orders/sales?pageSize=20');
        const salesData = await salesRes.json();

        if (salesData.success) {
          const orders = salesData.data?.list || salesData.data || [];

          const today = new Date().toISOString().split('T')[0];
          const todayOrders = orders.filter((o: Loose) => o.order_date?.startsWith(today)).length;
          const pendingOrderCount = orders.filter(
            (o: Loose) => o.status === 1 || o.status === 2
          ).length;
          const producingCount = orders.filter((o: Loose) => o.status === 3).length;
          const completedCount = orders.filter((o: Loose) => o.status === 4).length;
          const totalValue = orders.reduce(
            (sum: number, o: Loose) => sum + (o.total_amount || 0),
            0
          );

          setRecentOrders(
            orders.slice(0, 20).map((o: Loose) => ({
              id: o.order_no,
              customer: o.customer_name,
              product: o.items?.[0]?.material_name || '-',
              quantity:
                o.items?.reduce((sum: number, item: Loose) => sum + (item.quantity || 0), 0) || 0,
              status: STATUS_MAP[o.status]?.labelKey
                ? t(STATUS_MAP[o.status].labelKey)
                : t('unknown'),
              statusClass: STATUS_MAP[o.status]?.className || '',
              delivery: o.delivery_date || '-',
            }))
          );

          const inventoryRes = await fetch('/api/warehouse/inventory?pageSize=100');
          const inventoryData = await inventoryRes.json();
          let inventoryWarnings = 0;
          if (inventoryData.success) {
            const inventoryList = inventoryData.data?.list || inventoryData.data || [];
            inventoryWarnings = inventoryList.filter(
              (item: Loose) => (item.quantity || 0) < (item.min_quantity || 0)
            ).length;
          }

          const workOrdersRes = await fetch('/api/production/orders?pageSize=20');
          const workOrdersData = await workOrdersRes.json();
          let pendingWorkOrders = 0;
          if (workOrdersData.success) {
            const workOrders = workOrdersData.data?.list || workOrdersData.data || [];
            pendingWorkOrders = workOrders.filter(
              (wo: Loose) => wo.status === 1 || wo.status === 2
            ).length;

            setRecentWorkOrders(
              workOrders.slice(0, 20).map((wo: Loose) => ({
                id: wo.work_order_no,
                product: wo.product_name || '-',
                quantity: wo.quantity || 0,
                status: WORK_ORDER_STATUS_MAP[wo.status]?.labelKey
                  ? t(WORK_ORDER_STATUS_MAP[wo.status].labelKey)
                  : t('unknown'),
                statusClass: WORK_ORDER_STATUS_MAP[wo.status]?.className || '',
                date: wo.create_time?.substring(0, 10) || '-',
              }))
            );
          }

          setStats({
            todayOrders,
            pendingWorkOrders,
            inventoryWarnings,
            todayCompleted: completedCount,
            pendingOrderCount,
            producingCount,
            completedCount,
            totalValue,
          });
        }
      } catch {
      } finally {
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, []);

  useEffect(() => {
    setCurrentTime(new Date());
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const scrollElement = (ref: React.RefObject<HTMLDivElement | null>, dataLength: number) => {
      if (!ref.current || dataLength <= 5) return;
      const el = ref.current;
      let scrollAmount = 0;
      const timer = setInterval(() => {
        scrollAmount += 0.5;
        if (scrollAmount >= el.scrollHeight / 2) {
          scrollAmount = 0;
          el.scrollTop = 0;
        } else {
          el.scrollTop = scrollAmount;
        }
      }, 50);
      return () => clearInterval(timer);
    };

    const cleanup1 = scrollElement(orderScrollRef, recentOrders.length);
    const cleanup2 = scrollElement(workOrderScrollRef, recentWorkOrders.length);

    return () => {
      cleanup1?.();
      cleanup2?.();
    };
  }, [recentOrders.length, recentWorkOrders.length]);

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      dashboardRef.current?.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const formatTime = (date: Date) => {
    return date.toLocaleString('zh-CN', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
