'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useEffect, useState } from 'react';
import { MainLayout } from '@/components/layout';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Plus, Search, Edit, Trash2, FileText } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { UserSelect } from '@/components/ui/user-select';
import { useTranslations } from 'next-intl';

interface EcoRecord {
  id?: number;
  eco_no: string;
  eco_type: string;
  product_id?: number;
  product_code: string;
  product_name: string;
  old_version: string;
  new_version: string;
  change_reason: string;
  change_content: string;
  impact_analysis: string;
  status: number;
  applicant: string;
  apply_time: string;
  approver: string;
  approve_time: string;
  remark: string;
  create_time: string;
}

export default function EcoPage() {

  const t = useTranslations('Engineering');
  const tc = useTranslations('Common');

  const ecoTypeMap: Record<string, string> = {
    bom: t('bomChange'),
    process: t('processChange'),
    material: t('materialChange'),
    design: t('designChange'),
  };

  const ecoStatusMap: Record<
    number,
    { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline' }
  > = {
    1: { label: tc('draft'), variant: 'outline' },
    2: { label: t('pendingReview'), variant: 'secondary' },
    3: { label: t('approved'), variant: 'default' },
    4: { label: t('executed'), variant: 'default' },
    5: { label: tc('closed'), variant: 'secondary' },
    6: { label: t('rejected'), variant: 'destructive' },
  };

  const { toast } = useToast();
  const [records, setRecords] = useState<EcoRecord[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [_loading, setLoading] = useState(false);
  const [searchEcoNo, setSearchEcoNo] = useState('');
  const [searchType, setSearchType] = useState('');
  const [searchStatus, setSearchStatus] = useState('');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editRecord, setEditRecord] = useState<EcoRecord | null>(null);
  const [form, setForm] = useState<Partial<EcoRecord>>({
    eco_type: 'bom',
    product_code: '',
    product_name: '',
    old_version: '',
    new_version: '',
    change_reason: '',
    change_content: '',
    impact_analysis: '',
    applicant: '',
    remark: '',
  });

  const fetchData = async () => {
    setLoading(true);
    try {
