                                      : node.is_leaf
                                        ? ''
                                        : 'bg-blue-50/50 dark:bg-blue-950/20'
                                  }
                                >
                                  <TableCell>
                                    <div
                                      className="flex items-center gap-1"
                                      style={{ paddingLeft: `${node.indent * 20}px` }}
                                    >
                                      {node.level > 0 && (
                                        <ChevronRight className="h-3 w-3 text-muted-foreground flex-shrink-0" />
                                      )}
                                      <span className="text-xs text-muted-foreground">
                                        L{node.level}
                                      </span>
                                    </div>
                                  </TableCell>
                                  <TableCell className="font-mono text-sm">
                                    {node.material_code}
                                  </TableCell>
                                  <TableCell className={node.is_leaf ? '' : 'font-medium'}>
                                    {node.material_name}
                                  </TableCell>
                                  <TableCell className="text-right">
                                    {node.quantity.toLocaleString(locale)}
                                  </TableCell>
                                  <TableCell>{node.unit}</TableCell>
                                  <TableCell className="text-right">
                                    {node.scrap_rate > 0
                                      ? `${(node.scrap_rate * 100).toFixed(1)}%`
                                      : '-'}
                                  </TableCell>
                                  <TableCell className="text-right">
                                    {node.lead_time_days}
                                  </TableCell>
                                  <TableCell>
                                    {node.level === 0 ? (
                                      <Badge variant="outline">{t('finishedProduct')}</Badge>
                                    ) : node.is_leaf ? (
                                      <Badge className="bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400">
                                        {t('rawMaterial')}
                                      </Badge>
                                    ) : (
                                      <Badge className="bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400">
                                        {t('semiFinished')}
                                      </Badge>
                                    )}
                                  </TableCell>
                                </TableRow>
                              ))}
                            </TableBody>
                          </Table>
                        </div>
                      </CardContent>
                    </Card>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </TabsContent>

          <TabsContent value="time-bucket">
            <div className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <Clock className="h-5 w-5" />
                    {t('timeBucketAnalysis')}
                  </CardTitle>
                  <CardDescription>{t('timeBucketDesc')}</CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="grid grid-cols-1 md:grid-cols-6 gap-4 items-end">
                    <div className="space-y-2">
                      <Label>{t('material')}</Label>
                      <Select value={bucketMaterialId} onValueChange={setBucketMaterialId}>
                        <SelectTrigger>
                          <SelectValue placeholder={t('selectMaterial')} />
                        </SelectTrigger>
                        <SelectContent>
                          {materials.map((m) => (
                            <SelectItem key={m.id} value={String(m.id)}>
                              {m.material_code} - {m.material_name}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="space-y-2">
                      <Label>{tc('warehouse')}</Label>
                      <WarehouseSelect
                        value={bucketWarehouseId}
                        onChange={setBucketWarehouseId}
                        placeholder={t('selectWarehouse')}
                      />
                    </div>
                    <div className="space-y-2">
                      <Label>{t('startDate')}</Label>
                      <Input
                        type="date"
                        value={bucketStartDate}
                        onChange={(e) => setBucketStartDate(e.target.value)}
                      />
                    </div>
                    <div className="space-y-2">
                      <Label>{t('endDate')}</Label>
                      <Input
                        type="date"
                        value={bucketEndDate}
                        onChange={(e) => setBucketEndDate(e.target.value)}
                      />
                    </div>
                    <div className="space-y-2">
                      <Label>{t('bucketSize')}</Label>
                      <Select value={bucketSize} onValueChange={setBucketSize}>
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="day">{t('byDay')}</SelectItem>
                          <SelectItem value="week">{t('byWeek')}</SelectItem>
                          <SelectItem value="month">{t('byMonth')}</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="space-y-2">
                      <Button
                        onClick={handleCalculateBuckets}
                        disabled={bucketLoading || !bucketMaterialId || !bucketWarehouseId}
                        className="w-full"
                      >
                        {bucketLoading ? (
                          <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                        ) : (
                          <BarChart3 className="h-4 w-4 mr-2" />
                        )}
                        {t('calculate')}
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>

              <AnimatePresence>
                {timeBuckets.length > 0 && (
                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -20 }}
                    className="space-y-6"
                  >
                    <Card>
                      <CardHeader>
                        <CardTitle>{t('timeBucketChart')}</CardTitle>
                      </CardHeader>
                      <CardContent>
                        <div className="h-[400px]">
                          <ResponsiveContainer width="100%" height="100%">
                            <ComposedChart
                              data={timeBuckets}
                              margin={{ top: 20, right: 30, left: 20, bottom: 5 }}
                            >
                              <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
                              <XAxis
                                dataKey="date"
                                tick={{ fontSize: 12 }}
                                className="text-muted-foreground"
                              />
                              <YAxis
                                yAxisId="left"
                                tick={{ fontSize: 12 }}
                                className="text-muted-foreground"
                              />
                              <YAxis
                                yAxisId="right"
                                orientation="right"
                                tick={{ fontSize: 12 }}
                                className="text-muted-foreground"
                              />
                              <Tooltip
                                contentStyle={{
                                  backgroundColor: 'hsl(var(--card))',
                                  border: '1px solid hsl(var(--border))',
                                  borderRadius: '8px',
                                }}
                              />
                              <Legend />
                              <Bar
                                yAxisId="left"
                                dataKey="gross_requirement"
                                name={t('grossRequirement')}
                                fill="hsl(220, 70%, 55%)"
                                radius={[2, 2, 0, 0]}
                              />
                              <Bar
                                yAxisId="left"
                                dataKey="scheduled_receipt"
                                name={t('scheduledReceipt')}
                                fill="hsl(142, 70%, 45%)"
                                radius={[2, 2, 0, 0]}
                              />
                              <Bar
                                yAxisId="left"
                                dataKey="net_requirement"
                                name={t('netRequirement')}
                                fill="hsl(0, 70%, 55%)"
                                radius={[2, 2, 0, 0]}
                              />
                              <Line
                                yAxisId="right"
                                type="monotone"
                                dataKey="on_hand"
                                name={t('onHand')}
                                stroke="hsl(38, 90%, 50%)"
                                strokeWidth={2}
                                dot={{ r: 3 }}
                              />
                            </ComposedChart>
                          </ResponsiveContainer>
                        </div>
                      </CardContent>
                    </Card>

                    <Card>
                      <CardHeader>
                        <CardTitle>{t('timeBucketDetail')}</CardTitle>
                      </CardHeader>
                      <CardContent className="p-0">
                        <div className="overflow-x-auto">
                          <Table>
                            <TableHeader>
                              <TableRow>
                                <TableHead>{t('date')}</TableHead>
                                <TableHead className="text-right">
                                  {t('grossRequirement')}
                                </TableHead>
                                <TableHead className="text-right">
                                  {t('scheduledReceipt')}
                                </TableHead>
                                <TableHead className="text-right">{t('onHand')}</TableHead>
                                <TableHead className="text-right">{t('netRequirement')}</TableHead>
                                <TableHead className="text-right">
                                  {t('plannedOrderRelease')}
                                </TableHead>
                                <TableHead className="text-right">
                                  {t('plannedOrderReceipt')}
                                </TableHead>
                              </TableRow>
                            </TableHeader>
                            <TableBody>
                              {timeBuckets.map((bucket, idx) => (
                                <TableRow
                                  key={idx}
                                  className={
                                    bucket.net_requirement > 0 ? 'bg-red-50 dark:bg-red-950/20' : ''
                                  }
                                >
                                  <TableCell className="font-medium">{bucket.date}</TableCell>
                                  <TableCell className="text-right">
                                    {bucket.gross_requirement.toLocaleString(locale)}
                                  </TableCell>
                                  <TableCell className="text-right">
                                    {bucket.scheduled_receipt.toLocaleString(locale)}
                                  </TableCell>
                                  <TableCell className="text-right">
                                    {bucket.on_hand.toLocaleString(locale)}
                                  </TableCell>
                                  <TableCell className="text-right font-semibold">
                                    {bucket.net_requirement > 0
                                      ? bucket.net_requirement.toLocaleString(locale)
                                      : '-'}
                                  </TableCell>
                                  <TableCell className="text-right">
                                    {bucket.planned_order_release > 0
                                      ? bucket.planned_order_release.toLocaleString(locale)
                                      : '-'}
                                  </TableCell>
                                  <TableCell className="text-right">
                                    {bucket.planned_order_receipt > 0
                                      ? bucket.planned_order_receipt.toLocaleString(locale)
                                      : '-'}
                                  </TableCell>
                                </TableRow>
                              ))}
                            </TableBody>
                          </Table>
                        </div>
                      </CardContent>
                    </Card>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </TabsContent>
        </Tabs>
      </div>
    </MainLayout>
  );
}

