'use client';

import { useTranslations } from 'next-intl';
import { MainLayout } from '@/components/layout';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { SearchInput } from '@/components/ui/search-input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Plus,
  MoreHorizontal,
  Eye,
  Trash2,
  ShoppingCart,
  Send,
  FileText,
  RefreshCw,
  ChevronDown,
  ChevronRight,
  Printer,
  ArrowUpDown,
  ArrowUp,
  ArrowDown,
} from 'lucide-react';
import { useState, useEffect, useCallback, useMemo, Fragment } from 'react';
import { useToastContext } from '@/components/ui/toast';
import { useDebounce } from '@/hooks/use-debounce';
import { useCompanyName } from '@/hooks/useCompanyName';
import ApiClient from '@/lib/api-client';
import { logger } from '@/lib/logger';
import { mockPurchaseOrders, mockSuppliers, USE_MOCK } from '@/lib/mock-data';
import { GlobalExportToolbar } from '@/components/ui/global-export-toolbar';
import { MoneyDisplay } from '@/components/ui/money-display';
import { CurrencySelect } from '@/components/ui/currency-select';

interface PurchaseOrder {
  id: number;
  po_no: string;
  supplier_id: number;
  supplier_name: string;
  supplier_code: string;
  order_date: string;
  delivery_date: string;
  currency: string;
  total_amount: number;
  total_quantity: number;
  tax_rate: number;
  tax_amount: number;
  grand_total: number;
  base_currency?: string;
  base_total_amount?: number;
  base_tax_amount?: number;
  base_grand_total?: number;
  status: number;
  over_receipt_tolerance: number;
  payment_terms: string;
  remark: string;
  create_time: string;
  update_time: string;
  audit_time: string | null;
  lines?: OrderItem[];
  [key: string]: unknown;
}

interface Supplier {
  id: number;
  supplier_code: string;
  supplier_name: string;
  short_name: string;
  grade: string;
  status: string;
}

interface OrderItem {
  id: number;
  material_code: string;
  material_name: string;
  quantity: number;
  unit: string;
  unit_price: number;
  base_unit_price?: number;
  base_amount?: number;
  base_tax_amount?: number;
  base_line_total?: number;
}

const PO_STATUS = {
  DRAFT: 10,
  PENDING_APPROVAL: 20,
  APPROVED: 30,
  PARTIALLY_RECEIVED: 40,
  COMPLETED: 50,
  CLOSED: 90,
} as const;

const formatDate = (dateStr: string | null | undefined) => {
  if (!dateStr) return '-';
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return dateStr;
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  } catch {
    return dateStr;
  }
};

export default function PurchaseOrdersPage() {
  // 翻译钩子
  const t = useTranslations('Purchase');
  const tc = useTranslations('Common');

  const STATUS_MAP: Record<number, { label: string; className: string }> = {
    10: {
      label: tc('draft'),
      className: 'bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-200',
    },
    20: {
      label: tc('pending'),
      className: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900 dark:text-yellow-200',
    },
    30: {
      label: tc('approved'),
      className: 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200',
    },
    40: {
      label: t('partialReceived'),
      className: 'bg-orange-100 text-orange-700 dark:bg-orange-900 dark:text-orange-200',
    },
    50: {
      label: t('completed'),
      className: 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-200',
    },
    90: {
      label: tc('closed'),
      className: 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200',
    },
  };

  const getStatusBadge = (status: number) => {
    const config = STATUS_MAP[status] || {
      label: `${tc('unknown')}(${status})`,
      className: 'bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-200',
    };
    return <Badge className={config.className}>{config.label}</Badge>;
  };

  const { companyName } = useCompanyName();
  const { addToast: toast } = useToastContext();
  const [orders, setOrders] = useState<PurchaseOrder[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [pageSize] = useState(20);
  const [keyword, setKeyword] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');

  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<PurchaseOrder | null>(null);
  const [detailItems, setDetailItems] = useState<Loose[]>([]);
  const [expandedRows, setExpandedRows] = useState<Set<number>>(new Set());
  const [selectedOrders, setSelectedOrders] = useState<number[]>([]);
  const [sortField, setSortField] = useState<string | null>(null);
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc' | null>(null);

  const [newOrder, setNewOrder] = useState({
    supplier_id: '',
    delivery_date: '',
    remark: '',
    currency: '',
  });
  const [orderItems, setOrderItems] = useState<OrderItem[]>([
    { id: 1, material_code: '', material_name: '', quantity: 1, unit: '件', unit_price: 0 },
  ]);

  const fetchOrders = useCallback(
    async (searchKeyword?: string) => {
      logger.info({ module: 'Purchase', action: 'fetchOrders' }, '开始获取采购单列表', {
        page,
        pageSize,
        statusFilter,
        searchKeyword,
      });
      try {
        setLoading(true);

        if (USE_MOCK) {
          logger.info({ module: 'Purchase', action: 'fetchOrders' }, '使用 mock 数据');
          const filtered = searchKeyword
            ? mockPurchaseOrders.filter(
                (o) => o.po_no?.includes(searchKeyword) || o.supplier_name?.includes(searchKeyword)
              )
            : mockPurchaseOrders;
          const statusFiltered =
            statusFilter !== 'all'
              ? filtered.filter((o) => String(o.status) === statusFilter)
              : filtered;
          setOrders(statusFiltered);
          setTotal(statusFiltered.length);
          setSelectedOrders([]);
          return;
        }

        const data = await ApiClient.get('/api/purchase/orders', {
          page,
          pageSize,
          keyword: searchKeyword,
          status: statusFilter !== 'all' ? statusFilter : undefined,
        });

        if (data.success) {
          const ordersList = Array.isArray(data.data) ? data.data : data.data?.list || [];
          setOrders(ordersList);
          setTotal(data.pagination?.total || 0);
          setSelectedOrders([]);
          logger.info({ module: 'Purchase', action: 'fetchOrders' }, '采购单列表获取成功', {
            count: ordersList.length,
          });
        } else {
          logger.warn({ module: 'Purchase', action: 'fetchOrders' }, 'API返回失败', {
            message: data.message,
          });
        }
      } catch (error) {
        logger.error({ module: 'Purchase', action: 'fetchOrders' }, '获取采购单列表失败', {
          error: (error as Error).message,
        });
      } finally {
        setLoading(false);
      }
    },
    [page, pageSize, statusFilter]
  );

  const fetchSuppliers = useCallback(async () => {
    logger.info({ module: 'Purchase', action: 'fetchSuppliers' }, '开始获取供应商列表');
    try {
      if (USE_MOCK) {
        logger.info({ module: 'Purchase', action: 'fetchSuppliers' }, '使用 mock 数据');
        setSuppliers(mockSuppliers);
        return;
      }

      const data = await ApiClient.get('/api/purchase/suppliers');
      if (data.success) {
        setSuppliers(data.data?.list || data.data || []);
        logger.info({ module: 'Purchase', action: 'fetchSuppliers' }, '供应商列表获取成功', {
          count: (data.data?.list || []).length,
        });
      }
    } catch (error) {
      logger.error({ module: 'Purchase', action: 'fetchSuppliers' }, '获取供应商列表失败', {
        error: (error as Error).message,
      });
    }
  }, []);

  useEffect(() => {
    fetchOrders();
  }, []);

  const debouncedKeyword = useDebounce(keyword, 300);

  useEffect(() => {
    fetchOrders(debouncedKeyword);
  }, [debouncedKeyword, statusFilter, fetchOrders]);

  useEffect(() => {
    fetchSuppliers();
  }, [fetchSuppliers]);

  const handleViewDetail = (order: PurchaseOrder) => {
    setSelectedOrder(order);
    setDetailItems(order.lines || []);
    setIsDetailOpen(true);
  };

  const toggleRowExpand = (order: PurchaseOrder) => {
    const newExpanded = new Set(expandedRows);
    if (newExpanded.has(order.id)) {
      newExpanded.delete(order.id);
    } else {
      newExpanded.add(order.id);
    }
    setExpandedRows(newExpanded);
  };

  const handleCreateOrder = async () => {
    if (!newOrder.supplier_id) {
      toast({ title: '错误', description: '请选择供应商', variant: 'destructive' });
      return;
    }

    const validItems = orderItems.filter((item) => item.material_code && item.quantity > 0);
    if (validItems.length === 0) {
      toast({ title: '错误', description: '请添加至少一项采购物料', variant: 'destructive' });
      return;
    }

    const selectedSupplier = suppliers.find((s) => s.id === parseInt(newOrder.supplier_id));

    try {
      setLoading(true);
      const data = await ApiClient.post('/api/purchase/orders', {
        supplier_id: parseInt(newOrder.supplier_id),
        supplier_name: selectedSupplier?.supplier_name || '',
        supplier_code: selectedSupplier?.supplier_code || '',
        delivery_date: newOrder.delivery_date || null,
        remark: newOrder.remark,
        currency: newOrder.currency || undefined,
        lines: validItems.map((item) => ({
          material_code: item.material_code,
          material_name: item.material_name,
          order_qty: item.quantity,
          unit: item.unit,
          unit_price: item.unit_price,
        })),
      });
      if (data.success) {
        toast({ title: '成功', description: '采购单创建成功' });
        setIsCreateOpen(false);
        setNewOrder({ supplier_id: '', delivery_date: '', remark: '', currency: '' });
        setOrderItems([
          { id: 1, material_code: '', material_name: '', quantity: 1, unit: '件', unit_price: 0 },
        ]);
        fetchOrders();
      } else {
        toast({ title: '错误', description: data.message || '创建失败', variant: 'destructive' });
      }
    } catch {
      toast({ title: '错误', description: '创建采购单失败', variant: 'destructive' });
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (order: PurchaseOrder) => {
    if (!confirm(tc('confirmDeletePrefix', { name: order.po_no }))) return;

    try {
      const data = await ApiClient.delete('/api/purchase/orders', { id: order.id });
      if (data.success) {
        toast({ title: tc('success'), description: tc('deleteSuccess') });
        fetchOrders();
      } else {
        toast({
          title: tc('error'),
          description: data.message || tc('deleteFailed'),
          variant: 'destructive',
        });
      }
    } catch {
      toast({ title: tc('error'), description: tc('deleteFailed'), variant: 'destructive' });
    }
  };

  const handleBatchDelete = async () => {
    if (!selectedOrders.length) return;

    const selectedOrderInfo = orders.filter((o) => selectedOrders.includes(o.id));
    const orderNumbers = selectedOrderInfo.map((o) => o.po_no).join(', ');

    if (!confirm(tc('confirmBatchDelete', { count: selectedOrders.length, orderNumbers }))) return;

    try {
      setLoading(true);

      // 逐个删除采购单
      let successCount = 0;
      for (const orderId of selectedOrders) {
        const data = await ApiClient.delete('/api/purchase/orders', { id: orderId });
        if (data.success) {
          successCount++;
        }
      }

      if (successCount > 0) {
        toast({ title: '成功', description: `成功删除 ${successCount} 个采购单` });
        fetchOrders();
      } else {
        toast({ title: '错误', description: '删除失败', variant: 'destructive' });
      }
    } catch {
      toast({ title: '错误', description: '删除失败', variant: 'destructive' });
    } finally {
      setLoading(false);
    }
  };

  const handleStatusChange = async (orderId: number, action: string) => {
    let _newStatus = 0;
    if (action === 'submit') _newStatus = PO_STATUS.PENDING_APPROVAL;
    else if (action === 'approve') _newStatus = PO_STATUS.APPROVED;
    else return;

    try {
      const data = await ApiClient.put('/api/purchase/orders', { id: orderId, action });
      if (data.success) {
        toast({ title: tc('success'), description: tc('statusUpdateSuccess') });
        fetchOrders();
      } else {
        toast({
          title: tc('error'),
          description: data.message || tc('statusUpdateFailed'),
          variant: 'destructive',
        });
      }
    } catch {
      toast({ title: tc('error'), description: tc('statusUpdateFailed'), variant: 'destructive' });
    }
  };

  const handleSearch = () => {
    setPage(1);
    fetchOrders(keyword);
  };

  const _handleExport = (format: string) => {
    const statusMap: Record<number, string> = {
      10: tc('draft'),
      20: tc('pending'),
      30: tc('approved'),
      40: t('partialReceived'),
      50: t('completed'),
      90: tc('closed'),
    };
    const data = orders.map((o) => ({
      [t('poNo')]: o.po_no,
      [t('supplier')]: o.supplier_name,
      [t('orderDate')]: formatDate(o.order_date),
      [t('expectedDelivery')]: formatDate(o.delivery_date),
      [t('totalQty')]: o.total_quantity,
      [t('totalAmount')]: Number(o.grand_total || o.total_amount || 0).toFixed(2),
      [tc('status')]: statusMap[o.status] || `${tc('unknown')}(${o.status})`,
      [tc('remark')]: o.remark || '',
    }));

    if (format === 'xls' || format === 'excel') {
      const headers = Object.keys(data[0] || {});
      const csvContent = [
        headers.join('\t'),
        ...data.map((row) =>
          headers.map((h) => (row as Record<string, unknown>)[h] ?? '').join('\t')
        ),
      ].join('\n');
      const bom = '\uFEFF';
      const blob = new Blob([bom + csvContent], { type: 'application/vnd.ms-excel;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `采购订单_${new Date().toISOString().slice(0, 10)}.xls`;
      a.click();
      URL.revokeObjectURL(url);
      toast({ title: '导出成功', description: '已导出为 Excel 文件' });
    } else if (format === 'pdf') {
      const printWindow = window.open('', '_blank');
      if (!printWindow) return;
      const headers = Object.keys(data[0] || {});
      const thCells = headers.map((h) => `<th>${h}</th>`).join('');
      const rows = data
        .map(
          (row) =>
            '<tr>' +
            headers.map((h) => `<td>${(row as Record<string, unknown>)[h] ?? ''}</td>`).join('') +
            '</tr>'
        )
        .join('');
      printWindow.document.write(`<!DOCTYPE html><html><head><title>采购订单导出</title>
<style>
  body{font-family:"Microsoft YaHei",sans-serif;padding:20px}
  h1{text-align:center;font-size:18px;margin-bottom:4px}
  p.sub{text-align:center;color:#666;font-size:12px;margin-bottom:16px}
  table{width:100%;border-collapse:collapse;font-size:12px}
  th,td{border:1px solid #333;padding:6px 8px;text-align:center}
  th{background:#f0f0f0;font-weight:bold}
  @media print{body{padding:0}}
</style></head><body>
<h1>采购订单列表</h1>
<p class="sub">导出时间：${new Date().toLocaleString()} | 共 ${data.length} 条</p>
<table><thead><tr>${thCells}</tr></thead><tbody>${rows}</tbody></table>
<script>window.onload=function(){window.print()}</script>
</body></html>`);
      printWindow.document.close();
      toast({ title: '导出成功', description: '已导出为 PDF（打印保存）' });
    } else if (format === 'word') {
      const headers = Object.keys(data[0] || {});
      const thCells = headers
        .map((h) => `<th style="border:1px solid #333;padding:6px;background:#f0f0f0">${h}</th>`)
        .join('');
      const rows = data
        .map(
          (row) =>
            '<tr>' +
            headers
              .map(
                (h) =>
                  `<td style="border:1px solid #333;padding:6px">${(row as Record<string, unknown>)[h] ?? ''}</td>`
              )
              .join('') +
            '</tr>'
        )
        .join('');
      const htmlContent = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
<head><meta charset="utf-8"><title>采购订单</title></head>
<body style="font-family:'Microsoft YaHei',sans-serif;padding:20px">
<h1 style="text-align:center">采购订单列表</h1>
<p style="text-align:center;color:#666;font-size:12px">导出时间：${new Date().toLocaleString()}</p>
<table style="width:100%;border-collapse:collapse;font-size:12px">
<thead><tr>${thCells}</tr></thead><tbody>${rows}</tbody></table>
</body></html>`;
      const blob = new Blob(['\ufeff', htmlContent], { type: 'application/msword' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `采购订单_${new Date().toISOString().slice(0, 10)}.doc`;
      a.click();
      URL.revokeObjectURL(url);
      toast({ title: '导出成功', description: '已导出为 Word 文件' });
    }
  };

  const toggleSelectAll = () => {
    if (selectedOrders.length === orders.length) {
      setSelectedOrders([]);
    } else {
      setSelectedOrders(orders.map((o) => o.id));
    }
  };

  const toggleSelect = (id: number) => {
    setSelectedOrders((prev) => (prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]));
  };

  const handleSort = (field: string) => {
    if (sortField === field) {
      if (sortOrder === 'asc') {
        setSortOrder('desc');
      } else if (sortOrder === 'desc') {
        setSortField(null);
        setSortOrder(null);
      }
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
  };

  const getSortIcon = (field: string) => {
    if (sortField !== field) return <ArrowUpDown className="ml-1 h-3 w-3 opacity-50" />;
    if (sortOrder === 'asc') return <ArrowUp className="ml-1 h-3 w-3" />;
    return <ArrowDown className="ml-1 h-3 w-3" />;
  };

  const sortedOrders = useMemo(() => {
    if (!sortField || !sortOrder) return orders;
    return [...orders].sort((a, b) => {
      let aVal: string | number = (a as Record<string, unknown>)[sortField] as string | number;
      let bVal: string | number = (b as Record<string, unknown>)[sortField] as string | number;
      if (
        sortField === 'total_amount' ||
        sortField === 'grand_total' ||
        sortField === 'total_quantity' ||
        sortField === 'status'
      ) {
        aVal = Number(aVal) || 0;
        bVal = Number(bVal) || 0;
      } else {
        aVal = String(aVal || '').toLowerCase();
        bVal = String(bVal || '').toLowerCase();
      }
      if (aVal < bVal) return sortOrder === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortOrder === 'asc' ? 1 : -1;
      return 0;
    });
  }, [orders, sortField, sortOrder]);

  const handlePrintList = () => {
    const dataToPrint =
      selectedOrders.length > 0 ? orders.filter((o) => selectedOrders.includes(o.id)) : orders;

    if (dataToPrint.length === 0) {
      toast({ title: tc('info'), description: tc('noDataToPrint'), variant: 'destructive' });
      return;
    }

    const statusLabels: Record<number, string> = {
      10: tc('draft'),
      20: tc('pending'),
      30: tc('approved'),
      40: t('partialReceived'),
      50: t('completed'),
      90: tc('closed'),
    };

    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      toast({
        title: tc('error'),
        description: tc('printWindowBlocked'),
        variant: 'destructive',
      });
      return;
    }

    const orderSections = dataToPrint
      .map((o, _orderIndex) => {
        const lines = o.lines || [];
        const lineRows =
          lines.length > 0
            ? lines
                .map(
                  (item: Loose, idx: number) => `
          <tr>
            <td>${idx + 1}</td>
            <td>${item.material_code || '-'}</td>
            <td>${item.material_name || '-'}</td>
            <td>${item.material_spec || item.specification || '-'}</td>
            <td class="num">${item.order_qty ?? item.quantity ?? 0}</td>
            <td>${item.unit || '-'}</td>
            <td class="num">${Number(item.unit_price || 0).toFixed(2)}</td>
            <td class="num">${Number(item.amount || (item.order_qty || item.quantity) * (item.unit_price || 0)).toFixed(2)}</td>
            <td class="num">${item.received_qty ?? 0}</td>
          </tr>`
                )
                .join('')
            : '<tr><td colspan="9" style="color:#999;text-align:center;padding:8px;">暂无明细数据</td></tr>';

        return `
        <div class="order-block">
          <div class="order-header">
            <span class="order-no">${o.po_no}</span>
            <span class="order-info">供应商：${o.supplier_name} | 下单日期：${formatDate(o.order_date)} | 期望到货：${formatDate(o.delivery_date)} | 状态：${statusLabels[o.status] || tc('unknown')}</span>
          </div>
          <table>
            <thead><tr><th>{tc("serialNo")}</th><th>物料编码</th><th>物料名称</th><th>规格型号</th><th>{tc("quantity")}</th><th>{tc("unit")}</th><th>单价</th><th>{tc("amount")}</th><th>已收数量</th></tr></thead>
            <tbody>${lineRows}</tbody>
            <tfoot>
              <tr>
                <td colspan="4" style="text-align:right;font-weight:bold;">{tc("total")}</td>
                <td class="num" style="font-weight:bold;">${o.total_quantity || 0}</td>
                <td></td>
                <td></td>
                <td class="num" style="font-weight:bold;">¥${Number(o.grand_total || o.total_amount || 0).toLocaleString()}</td>
                <td></td>
              </tr>
            </tfoot>
          </table>
          ${o.remark ? `<div class="remark">备注：${o.remark}</div>` : ''}
        </div>`;
      })
      .join('');

    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>采购订单打印</title>
      <style>
        @page { size: A4; margin: 10mm; }
        body { font-family: "Microsoft YaHei", Arial, sans-serif; padding: 20px; color: #333; font-size: 12px; }
        h1 { text-align: center; border-bottom: 2px solid #1a56db; padding-bottom: 10px; color: #1a56db; font-size: 20px; margin-bottom: 5px; }
        .info { text-align: center; color: #666; margin-bottom: 15px; font-size: 13px; }
        .order-block { margin-bottom: 20px; page-break-inside: avoid; }
        .order-header { background: #f0f4ff; padding: 8px 12px; border: 1px solid #c8d6f0; border-bottom: none; border-radius: 4px 4px 0 0; display: flex; justify-content: space-between; align-items: center; }
        .order-no { font-weight: bold; font-size: 14px; color: #1a56db; }
        .order-info { color: #555; font-size: 11px; }
        table { width: 100%; border-collapse: collapse; font-size: 11px; }
        th, td { border: 1px solid #999; padding: 4px 6px; text-align: center; }
        th { background-color: #f0f4ff; font-weight: bold; color: #1a56db; }
        tfoot td { background-color: #f8f9fa; }
        .num { text-align: right; }
        .remark { padding: 4px 12px; color: #666; font-size: 11px; border: 1px solid #c8d6f0; border-top: none; border-radius: 0 0 4px 4px; }
        .footer { margin-top: 20px; text-align: right; color: #999; font-size: 11px; }
        @media print { body { padding: 0; } .order-block { page-break-inside: avoid; } }
      </style></head>
      <body>
        <h1>采购订单</h1>
        <div class="info">打印时间：${new Date().toLocaleString('zh-CN')} | 共 ${dataToPrint.length} 条采购订单</div>
        ${orderSections}
        <div class="footer">${companyName}</div>
        <script>window.onload=function(){window.print();}</script>
      </body></html>`;
    printWindow.document.write(html);
    printWindow.document.close();
    toast({ title: tc('print'), description: `正在打印 ${dataToPrint.length} 条采购订单` });
  };

  const addItem = () => {
    setOrderItems((prev) => [
      ...prev,
      {
        id: Date.now(),
        material_code: '',
        material_name: '',
        quantity: 1,
        unit: '件',
        unit_price: 0,
      },
    ]);
  };

  const removeItem = (id: number) => {
    if (orderItems.length <= 1) return;
    setOrderItems((prev) => prev.filter((item) => item.id !== id));
  };

  const updateItem = (id: number, field: keyof OrderItem, value: Loose) => {
    setOrderItems((prev) =>
      prev.map((item) => {
        if (item.id === id) {
          return { ...item, [field]: value };
        }
        return item;
      })
    );
  };

  return (
    <MainLayout title={t('purchaseOrder')}>
      <div className="space-y-6">
        <Card>
          <CardContent className="p-4">
            <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
              <div className="flex flex-1 gap-4 items-center w-full md:w-auto">
                <SearchInput
                  placeholder={t('searchOrderPlaceholder')}
                  value={keyword}
                  onChange={setKeyword}
                  onSearch={(kw) => {
                    setPage(1);
                    fetchOrders(kw);
                  }}
                  className="flex-1 max-w-sm"
                />
                <Select
                  value={statusFilter}
                  onValueChange={(v) => {
                    setStatusFilter(v);
                    setPage(1);
                  }}
                >
                  <SelectTrigger className="w-[140px]">
                    <SelectValue placeholder={tc('orderStatus')} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">{tc('allStatus')}</SelectItem>
                    <SelectItem value="10">{tc('draft')}</SelectItem>
                    <SelectItem value="20">{tc('pending')}</SelectItem>
                    <SelectItem value="30">{tc('approved')}</SelectItem>
                    <SelectItem value="40">{t('partialReceived')}</SelectItem>
                    <SelectItem value="50">{tc('completed')}</SelectItem>
                    <SelectItem value="90">{tc('closed')}</SelectItem>
                  </SelectContent>
                </Select>
                <Button variant="outline" size="icon" onClick={handleSearch}>
                  <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
                </Button>
              </div>
              <div className="flex gap-2">
                <Button variant="outline" onClick={handlePrintList}>
                  <Printer className="h-4 w-4 mr-2" />
                  {tc('print')}
                  {selectedOrders.length > 0 ? `(${selectedOrders.length})` : ''}
                </Button>
                {selectedOrders.length > 0 && (
                  <Button variant="destructive" onClick={handleBatchDelete}>
                    <Trash2 className="h-4 w-4 mr-2" />
                    {tc('delete')}({selectedOrders.length})
                  </Button>
                )}
                <GlobalExportToolbar
                  filename="采购订单"
                  title="采购订单列表"
                  landscape
                  columns={[
                    { key: 'po_no', label: t('poNo'), width: 18 },
                    { key: 'supplier_name', label: t('supplier'), width: 20 },
                    {
                      key: 'order_date',
                      label: t('orderDate'),
                      width: 12,
                      formatter: (v) => formatDate(v),
                    },
                    {
                      key: 'delivery_date',
                      label: t('expectedDelivery'),
                      width: 12,
                      formatter: (v) => formatDate(v),
                    },
                    { key: 'total_quantity', label: t('totalQty'), width: 10 },
                    {
                      key: 'grand_total',
                      label: tc('amount'),
                      width: 12,
                      formatter: (_v, row) =>
                        Number(row.grand_total || row.total_amount || 0).toFixed(2),
                    },
                    {
                      key: 'status',
                      label: tc('status'),
                      width: 10,
                      formatter: (v) => {
                        const m: Record<number, string> = {
                          10: tc('draft'),
                          20: tc('pending'),
                          30: tc('approved'),
                          40: t('partialReceived'),
                          50: t('completed'),
                          90: tc('closed'),
                        };
                        return m[v] || `${tc('unknown')}(${v})`;
                      },
                    },
                    { key: 'remark', label: tc('remark'), width: 20 },
                  ]}
                  data={
                    selectedOrders.length > 0
                      ? orders.filter((o) => selectedOrders.includes(o.id))
                      : sortedOrders
                  }
                />
                <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
                  <DialogTrigger asChild>
                    <Button>
                      <Plus className="h-4 w-4 mr-2" />
                      {t('newPurchaseOrder')}
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="max-w-5xl max-h-[90vh] overflow-y-auto" resizable>
                    <DialogHeader>
                      <DialogTitle>{t('createPurchaseOrder')}</DialogTitle>
                      <DialogDescription>{tc('create')}</DialogDescription>
                    </DialogHeader>
                    <div className="grid gap-4 py-4">
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                          <Label>{t('supplier')} *</Label>
                          <Select
                            value={newOrder.supplier_id}
                            onValueChange={(v) =>
                              setNewOrder((prev) => ({ ...prev, supplier_id: v }))
                            }
                          >
                            <SelectTrigger className="w-full">
                              <SelectValue placeholder={tc('select') + t('supplier')} />
                            </SelectTrigger>
                            <SelectContent>
                              {suppliers
                                .filter((s) => Number(s.status) === 1)
                                .map((s) => (
                                  <SelectItem key={s.id} value={s.id.toString()}>
                                    {s.supplier_name}
                                  </SelectItem>
                                ))}
                            </SelectContent>
                          </Select>
                        </div>
                        <div className="space-y-2">
                          <Label>{t('expectedDate')}</Label>
                          <Input
                            type="date"
                            value={newOrder.delivery_date}
                            onChange={(e) =>
                              setNewOrder((prev) => ({ ...prev, delivery_date: e.target.value }))
                            }
                          />
                        </div>
                        <div className="space-y-2">
                          <Label>{tc('currency')}</Label>
                          <CurrencySelect
                            value={newOrder.currency}
                            onChange={(v) => setNewOrder((prev) => ({ ...prev, currency: v }))}
                            placeholder={tc('selectCurrency')}
                          />
                        </div>
                      </div>

                      <div className="space-y-2">
                        <Label>{t('purchaseDetails')}</Label>
                        <div className="overflow-x-auto">
                          <Table>
                            <TableHeader>
                              <TableRow>
                                <TableHead className="min-w-[140px]">{t('materialCode')}</TableHead>
                                <TableHead className="min-w-[140px]">{t('materialName')}</TableHead>
                                <TableHead className="min-w-[100px]">{tc('quantity')}</TableHead>
                                <TableHead className="min-w-[80px]">{tc('unit')}</TableHead>
                                <TableHead className="min-w-[100px]">{t('unitPrice')}</TableHead>
                                <TableHead className="min-w-[100px]">{tc('amount')}</TableHead>
                                <TableHead className="w-[60px]"></TableHead>
                              </TableRow>
                            </TableHeader>
                            <TableBody>
                              {orderItems.map((item) => (
                                <TableRow key={item.id}>
                                  <TableCell>
                                    <Input
                                      value={item.material_code}
                                      onChange={(e) =>
                                        updateItem(item.id, 'material_code', e.target.value)
                                      }
                                      placeholder={t('materialCode')}
                                    />
                                  </TableCell>
                                  <TableCell>
                                    <Input
                                      value={item.material_name}
                                      onChange={(e) =>
                                        updateItem(item.id, 'material_name', e.target.value)
                                      }
                                      placeholder={t('materialName')}
                                    />
                                  </TableCell>
                                  <TableCell>
                                    <Input
                                      type="number"
                                      min="1"
                                      value={item.quantity || ''}
                                      onChange={(e) =>
                                        updateItem(
                                          item.id,
                                          'quantity',
                                          parseFloat(e.target.value) || 0
                                        )
                                      }
                                    />
                                  </TableCell>
                                  <TableCell>
                                    <Input
                                      value={item.unit}
                                      onChange={(e) => updateItem(item.id, 'unit', e.target.value)}
                                      className="w-20"
                                    />
                                  </TableCell>
                                  <TableCell>
