                          <TableCell className="text-right">{order.total_quantity}</TableCell>
                          <TableCell className="text-right">
                            <MoneyDisplay
                              amount={Number(order.grand_total || order.total_amount || 0)}
                              currency={order.currency || 'CNY'}
