                          <TableCell>{order.currency || 'CNY'}</TableCell>
                          <TableCell>{getStatusBadge(order.status)}</TableCell>
                          <TableCell className="text-right">
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                <Button variant="ghost" size="icon">
                                  <MoreHorizontal className="h-4 w-4" />
                                </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end">
                                <DropdownMenuItem onClick={() => handleViewDetail(order)}>
                                  <Eye className="h-4 w-4 mr-2" />
                                  {t('viewDetail')}
                                </DropdownMenuItem>
                                {order.status === 10 && (
                                  <DropdownMenuItem
                                    onClick={() => handleStatusChange(order.id, 'submit')}
                                  >
                                    <Send className="h-4 w-4 mr-2" />
                                    {t('submitApproval')}
                                  </DropdownMenuItem>
                                )}
                                {order.status === 20 && (
                                  <DropdownMenuItem
                                    onClick={() => handleStatusChange(order.id, 'approve')}
                                  >
                                    <FileText className="h-4 w-4 mr-2" />
                                    {t('approve')}
                                  </DropdownMenuItem>
                                )}
                                {order.status < 30 && (
                                  <DropdownMenuItem
                                    className="text-destructive"
                                    onClick={() => handleDelete(order)}
                                  >
                                    <Trash2 className="h-4 w-4 mr-2" />
                                    {tc('delete')}
                                  </DropdownMenuItem>
                                )}
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </TableCell>
                        </TableRow>
                        {isExpanded && (
                          <TableRow key={`${order.id}-detail`}>
                            <TableCell colSpan={12} className="p-0">
                              <div className="bg-slate-50 dark:bg-slate-800 border-t dark:border-slate-700">
                                <Table>
                                  <TableHeader>
                                    <TableRow className="bg-slate-100/50 dark:bg-slate-700/50 hover:bg-slate-100/50 dark:hover:bg-slate-700/50">
                                      <TableHead className="pl-8 text-xs font-normal text-muted-foreground">
                                        {t('materialCode')}
                                      </TableHead>
                                      <TableHead className="text-xs font-normal text-muted-foreground">
                                        {t('materialName')}
                                      </TableHead>
                                      <TableHead className="text-xs font-normal text-muted-foreground">
                                        {t('specification')}
                                      </TableHead>
                                      <TableHead className="text-xs font-normal text-muted-foreground text-right">
                                        {tc('quantity')}
                                      </TableHead>
                                      <TableHead className="text-xs font-normal text-muted-foreground">
                                        {tc('unit')}
                                      </TableHead>
                                      <TableHead className="text-xs font-normal text-muted-foreground text-right">
                                        {t('unitPrice')}
                                      </TableHead>
                                      <TableHead className="text-xs font-normal text-muted-foreground text-right">
                                        {tc('amount')}
                                      </TableHead>
                                      <TableHead className="text-xs font-normal text-muted-foreground text-right">
                                        {tc('baseCurrencyAmount')}
                                      </TableHead>
                                      <TableHead className="text-xs font-normal text-muted-foreground">
                                        {t('receivedQty')}
                                      </TableHead>
                                    </TableRow>
                                  </TableHeader>
                                  <TableBody>
                                    {lines.length > 0 ? (
                                      lines.map((item: Loose, idx: number) => (
                                        <TableRow
                                          key={idx}
                                          className="bg-transparent hover:bg-white/60 dark:hover:bg-slate-700/60"
                                        >
                                          <TableCell className="pl-8 font-mono text-sm">
                                            {item.material_code || '-'}
                                          </TableCell>
                                          <TableCell className="text-sm">
                                            {item.material_name || '-'}
                                          </TableCell>
                                          <TableCell className="text-sm">
                                            {item.material_spec || item.specification || '-'}
                                          </TableCell>
                                          <TableCell className="text-sm text-right">
                                            {item.order_qty ?? item.quantity ?? 0}
                                          </TableCell>
                                          <TableCell className="text-sm">
                                            {item.unit || '-'}
                                          </TableCell>
                                          <TableCell className="text-sm text-right">
                                            {Number(item.unit_price || 0).toFixed(2)}
                                          </TableCell>
                                          <TableCell className="text-sm text-right font-medium">
                                            {Number(
                                              item.amount ||
                                                (item.order_qty || item.quantity) *
                                                  (item.unit_price || 0)
                                            ).toFixed(2)}
                                          </TableCell>
                                          <TableCell className="text-sm text-right">
                                            {item.base_amount !== undefined ? (
                                              <span className="font-medium">
                                                {Number(item.base_amount).toLocaleString('zh-CN', {
                                                  minimumFractionDigits: 2,
                                                  maximumFractionDigits: 2,
                                                })}
                                                <span className="text-xs text-muted-foreground ml-1">
                                                  {order.base_currency || 'CNY'}
                                                </span>
                                              </span>
                                            ) : (
                                              '-'
                                            )}
                                          </TableCell>
                                          <TableCell className="text-sm">
                                            {item.received_qty ?? 0}
                                          </TableCell>
                                        </TableRow>
                                      ))
                                    ) : (
                                      <TableRow>
                                        <TableCell
                                          colSpan={9}
                                          className="text-center py-3 text-muted-foreground text-sm"
                                        >
                                          {t('noDetailData')}
                                        </TableCell>
                                      </TableRow>
                                    )}
                                  </TableBody>
                                </Table>
                              </div>
                            </TableCell>
                          </TableRow>
                        )}
                      </Fragment>
                    );
                  })}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>

        <Dialog open={isDetailOpen} onOpenChange={setIsDetailOpen}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>{tc('purchaseOrderDetailTitle')}</DialogTitle>
            </DialogHeader>
            {selectedOrder && (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label className="text-muted-foreground">采购单号</Label>
                    <p className="font-mono">{selectedOrder.po_no}</p>
                  </div>
                  <div>
                    <Label className="text-muted-foreground">{tc('supplier')}</Label>
                    <p>{selectedOrder.supplier_name}</p>
                  </div>
                  <div>
                    <Label className="text-muted-foreground">{tc('orderDateLabel')}</Label>
                    <p>{formatDate(selectedOrder.order_date)}</p>
                  </div>
                  <div>
                    <Label className="text-muted-foreground">{tc('expectedArrivalLabel')}</Label>
                    <p>{formatDate(selectedOrder.delivery_date)}</p>
                  </div>
                  <div>
                    <Label className="text-muted-foreground">{tc('totalQuantity')}</Label>
                    <p>{selectedOrder.total_quantity}</p>
                  </div>
                  <div>
                    <Label className="text-muted-foreground">{tc('currency')}</Label>
                    <p className="font-medium">{selectedOrder.currency || 'CNY'}</p>
                  </div>
                  <div>
                    <Label className="text-muted-foreground">{tc('amount')}</Label>
                    <p className="font-medium">
                      <MoneyDisplay
                        amount={Number(
                          selectedOrder.grand_total || selectedOrder.total_amount || 0
                        )}
                        currency={selectedOrder.currency || 'CNY'}
                        baseAmount={selectedOrder.base_grand_total}
                        baseCurrency={selectedOrder.base_currency}
                        showSymbol
                      />
                    </p>
                  </div>
                  <div>
                    <Label className="text-muted-foreground">{tc('status')}</Label>
                    <p>{getStatusBadge(selectedOrder.status)}</p>
                  </div>
                  {selectedOrder.remark && (
                    <div className="col-span-2">
                      <Label className="text-muted-foreground">{tc('remark')}</Label>
                      <p>{selectedOrder.remark}</p>
                    </div>
                  )}
                </div>
                {detailItems.length > 0 && (
                  <div>
                    <Label className="text-muted-foreground mb-2 block">{tc('returnItems')}</Label>
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>物料编码</TableHead>
                          <TableHead>物料名称</TableHead>
                          <TableHead>{tc('quantity')}</TableHead>
                          <TableHead>{tc('unit')}</TableHead>
                          <TableHead>单价</TableHead>
                          <TableHead>{tc('amount')}</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {detailItems.map((item: Loose, idx: number) => (
                          <TableRow key={idx}>
                            <TableCell>{item.material_code}</TableCell>
                            <TableCell>{item.material_name}</TableCell>
                            <TableCell>{item.order_qty || item.quantity}</TableCell>
                            <TableCell>{item.unit}</TableCell>
                            <TableCell>{item.unit_price}</TableCell>
                            <TableCell>
                              {item.total_price ||
                                ((item.order_qty || item.quantity) * item.unit_price).toFixed(2)}
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </div>
                )}
              </div>
            )}
          </DialogContent>
        </Dialog>
      </div>
    </MainLayout>
  );
}

