                                strokeDasharray="3 3"
                                label={{ value: 'CL', position: 'right', fontSize: 11 }}
                              />
                              <ReferenceLine
                                y={xbarResult.r_limits.lcl}
                                stroke="hsl(0, 70%, 50%)"
                                strokeDasharray="5 5"
                                label={{ value: 'LCL', position: 'right', fontSize: 11 }}
                              />
                              <Line
                                type="monotone"
                                dataKey="range"
                                name="极差R"
                                stroke="hsl(142, 70%, 40%)"
