                                        fill="hsl(0, 70%, 50%)"
                                        stroke="hsl(0, 70%, 50%)"
                                        strokeWidth={2}
                                      />
                                    );
                                  }
                                  return (
                                    <circle
                                      key={`normal-r-${payload.subgroup}`}
                                      cx={cx}
                                      cy={cy}
                                      r={3}
                                      fill="hsl(142, 70%, 40%)"
                                      stroke="hsl(142, 70%, 40%)"
                                      strokeWidth={1}
                                    />
                                  );
                                }}
                              />
                            </ComposedChart>
                          </ResponsiveContainer>
                        </div>
                      </CardContent>
