'use client';

import { authFetch } from '@/lib/auth-fetch';
import { MainLayout } from '@/components/layout';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Plus,
  Search,
  MoreHorizontal,
  Edit,
  Trash2,
  FileText,
  CheckCircle2,
  Loader2,
  ArrowUpDown,
  ArrowUp,
  ArrowDown,
} from 'lucide-react';
import { useState, useEffect, useCallback, useMemo } from 'react';
import { useToast } from '@/hooks/use-toast';
import { useDebounce } from '@/hooks/use-debounce';
import { formatDate } from '@/lib/date-utils';
import { GlobalExportToolbar } from '@/components/ui/global-export-toolbar';
import { useTranslations } from 'next-intl';

interface SampleOrder {
  id: number;
  order_no: string;
  notify_date: string;
  customer_name: string;
  product_name: string;
  material_no: string;
  version: string;
  size_spec: string;
  material_spec: string;
  quantity: number;
  customer_require_date: string;
  actual_delivery_date: string | null;
  delivery_status: string;
  status: string;
  remark: string;
  create_time: string;
  update_time: string;
}

const lifecycleStatusMap: Record<string, { label: string; color: string }> = {
  draft: { label: 'draft', color: 'bg-gray-100 text-gray-700' },
  pending: { label: 'pending', color: 'bg-yellow-100 text-yellow-700' },
  in_progress: { label: 'inProgress', color: 'bg-blue-100 text-blue-700' },
  completed: { label: 'completed', color: 'bg-green-100 text-green-700' },
  confirmed: { label: 'confirmed', color: 'bg-emerald-100 text-emerald-700' },
  converted: { label: 'converted', color: 'bg-black text-white' },
  cancelled: { label: 'cancelled', color: 'bg-red-100 text-red-700' },
};

export default function SampleOrdersPage() {
  // 翻译钩子
  const t = useTranslations('SampleOrders');
  const tc = useTranslations('Common');

  const { toast } = useToast();
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [isEditOpen, setIsEditOpen] = useState(false);
  const [editingOrder, setEditingOrder] = useState<SampleOrder | null>(null);
  const [orders, setOrders] = useState<SampleOrder[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchKeyword, setSearchKeyword] = useState('');
  const debouncedKeyword = useDebounce(searchKeyword, 300);
  const [selectedStatus, setSelectedStatus] = useState('all');
  const [selectedCustomer, setSelectedCustomer] = useState('all');
  const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set());
  const [sortField, setSortField] = useState<string | null>(null);
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc' | null>(null);
  const [pagination, setPagination] = useState({
    page: 1,
    pageSize: 20,
    total: 0,
    totalPages: 0,
  });

  const [formData, setFormData] = useState({
    notify_date: '',
    customer_name: '',
    product_name: '',
    material_no: '',
    version: 'A',
    size_spec: '',
    material_spec: '',
    quantity: '',
    customer_require_date: '',
    remark: '',
  });

  const handleSort = (field: string) => {
    if (sortField === field) {
      if (sortOrder === 'asc') setSortOrder('desc');
      else if (sortOrder === 'desc') {
        setSortField(null);
        setSortOrder(null);
      }
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
  };

  const getSortIcon = (field: string) => {
    if (sortField !== field) return <ArrowUpDown className="ml-1 h-3 w-3 opacity-50" />;
    return sortOrder === 'asc' ? (
      <ArrowUp className="ml-1 h-3 w-3" />
    ) : (
      <ArrowDown className="ml-1 h-3 w-3" />
    );
  };

  const sortedOrders = useMemo(() => {
    if (!sortField || !sortOrder) return orders;
    return [...orders].sort((a, b) => {
      const aVal = String((a as Loose)[sortField] ?? '').toLowerCase();
      const bVal = String((b as Loose)[sortField] ?? '').toLowerCase();
      if (aVal < bVal) return sortOrder === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortOrder === 'asc' ? 1 : -1;
      return 0;
    });
  }, [orders, sortField, sortOrder]);

  const fetchOrders = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        page: pagination.page.toString(),
        pageSize: pagination.pageSize.toString(),
        keyword: debouncedKeyword,
      });
      if (selectedStatus && selectedStatus !== 'all') {
        params.append('status', selectedStatus);
      }
      if (selectedCustomer && selectedCustomer !== 'all') {
        params.append('customerName', selectedCustomer);
      }
      const response = await authFetch(`/api/sample/orders?${params}`);
      const result = await response.json();
      if (result.success) {
        const orderList = Array.isArray(result.data) ? result.data : result.data?.list || [];
        setOrders(orderList);
        const total = result.pagination?.total || result.data?.total || orderList.length;
        setPagination((prev) => ({
          ...prev,
          total: total,
          totalPages: Math.ceil(total / prev.pageSize) || 1,
        }));
      }
    } catch {
      toast({ title: t('fetchOrdersFailed'), variant: 'destructive' });
    } finally {
      setLoading(false);
    }
  }, [
    pagination.page,
    pagination.pageSize,
    debouncedKeyword,
    selectedStatus,
    selectedCustomer,
    toast,
  ]);

  useEffect(() => {
    fetchOrders();
  }, [fetchOrders]);

  const handleCreate = async () => {
    try {
      const response = await authFetch('/api/sample/orders', {
        method: 'POST',
        body: JSON.stringify({ ...formData, quantity: parseInt(formData.quantity) || 0 }),
      });
      const result = await response.json();
      if (result.success) {
        toast({ title: t('orderCreated', { orderNo: result.data.order_no }) });
        setIsCreateOpen(false);
        resetForm();
        fetchOrders();
      } else {
        toast({ title: result.message || tc('createFailed'), variant: 'destructive' });
      }
    } catch {
      toast({ title: tc('createFailed'), variant: 'destructive' });
    }
  };

  const handleUpdate = async () => {
    if (!editingOrder) return;
    try {
      const response = await authFetch('/api/sample/orders', {
        method: 'PUT',
        body: JSON.stringify({
          id: editingOrder.id,
          ...formData,
          quantity: parseInt(formData.quantity) || 0,
        }),
      });
      const result = await response.json();
      if (result.success) {
        toast({ title: tc('updateSuccess') });
        setIsEditOpen(false);
        setEditingOrder(null);
        resetForm();
        fetchOrders();
      } else {
        toast({ title: result.message || tc('updateFailed'), variant: 'destructive' });
      }
    } catch {
      toast({ title: tc('updateFailed'), variant: 'destructive' });
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm(t('confirmDelete'))) return;
    try {
      const response = await authFetch(`/api/sample/orders?id=${id}`, { method: 'DELETE' });
      const result = await response.json();
      if (result.success) {
        toast({ title: tc('deleteSuccess') });
        fetchOrders();
      } else {
        toast({ title: result.message || tc('deleteFailed'), variant: 'destructive' });
      }
    } catch {
      toast({ title: tc('deleteFailed'), variant: 'destructive' });
    }
  };

  const handleDeliveryAction = async (id: number, action: 'deliver' | 'sign') => {
    try {
      const response = await authFetch('/api/sample/orders/linkage', {
        method: 'PUT',
        body: JSON.stringify({
          sample_order_id: id,
          action,
          actual_delivery_date: new Date().toISOString().split('T')[0],
        }),
      });
      const result = await response.json();
      if (result.success) {
        toast({ title: result.message || t('statusUpdated', { status: action }) });
        fetchOrders();
      } else {
        toast({ title: result.message || t('statusUpdateFailed'), variant: 'destructive' });
      }
    } catch {
      toast({ title: t('statusUpdateFailed'), variant: 'destructive' });
    }
  };

  const handleLifecycleAction = async (id: number, action: string) => {
    try {
      const response = await authFetch('/api/sample/orders/status', {
        method: 'PUT',
        body: JSON.stringify({ id, action }),
      });
      const result = await response.json();
      if (result.success) {
        toast({ title: result.message || t('statusUpdated', { status: action }) });
        fetchOrders();
      } else {
        toast({ title: result.message || t('statusUpdateFailed'), variant: 'destructive' });
      }
    } catch {
      toast({ title: t('statusUpdateFailed'), variant: 'destructive' });
    }
  };

  const openEditDialog = (order: SampleOrder) => {
    setEditingOrder(order);
    setFormData({
      notify_date: (order.notify_date || '').slice(0, 10),
      customer_name: order.customer_name,
      product_name: order.product_name,
      material_no: order.material_no,
      version: order.version,
      size_spec: order.size_spec,
      material_spec: order.material_spec,
      quantity: order.quantity.toString(),
      customer_require_date: (order.customer_require_date || '').slice(0, 10),
      remark: order.remark,
    });
    setIsEditOpen(true);
  };

  const resetForm = () => {
    setFormData({
      notify_date: '',
      customer_name: '',
      product_name: '',
      material_no: '',
      version: 'A',
      size_spec: '',
      material_spec: '',
      quantity: '',
      customer_require_date: '',
      remark: '',
    });
  };

  const getLifecycleStatusBadge = (status: string) => {
    const config = lifecycleStatusMap[status];
    if (!config) return <Badge variant="secondary">{status}</Badge>;
    return <Badge className={config.color}>{t(config.label)}</Badge>;
  };

  const customers = Array.from(new Set(orders.map((o) => o.customer_name)));

  const handleInputChange = (field: string, value: string) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const toggleSelect = (id: number) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };
  const toggleSelectAll = () => {
    if (selectedIds.size === sortedOrders.length) setSelectedIds(new Set());
    else setSelectedIds(new Set(sortedOrders.map((o) => o.id)));
  };

  const _exportColumns = [
    { key: 'notify_date', header: t('notifyDate') },
    { key: 'customer_name', header: tc('customer') },
    { key: 'product_name', header: t('productName') },
    { key: 'material_no', header: t('materialNo') },
    { key: 'version', header: tc('version') },
    { key: 'size_spec', header: tc('size') },
    { key: 'quantity', header: tc('quantity') },
    { key: 'customer_require_date', header: t('requireDate') },
    { key: 'status', header: tc('status') },
  ];
  const _getExportData = () =>
    sortedOrders.map((s, i) => ({
      [tc('serialNo')]: i + 1,
      [t('notifyDate')]: formatDate(s.notify_date),
      [tc('customer')]: s.customer_name,
      [t('productName')]: s.product_name,
      [t('materialNo')]: s.material_no,
      [tc('version')]: s.version,
      [tc('size')]: s.size_spec,
      [tc('quantity')]: s.quantity,
      [t('requireDate')]: formatDate(s.customer_require_date),
      [tc('status')]: t(lifecycleStatusMap[s.status]?.label || s.status),
    }));

  const _handlePrint = () => {
    const items =
      selectedIds.size > 0 ? sortedOrders.filter((o) => selectedIds.has(o.id)) : sortedOrders;
    if (items.length === 0) {
      toast({ title: t('noDataToPrint'), variant: 'destructive' });
      return;
    }
    const printWindow = window.open('', '_blank', 'width=900,height=600');
    if (!printWindow) return;
    printWindow.document.write(`<html><head><title>${t('sampleOrderList')}</title>
      <style>
        body { font-family: 'Microsoft YaHei', sans-serif; margin: 20px; }
        h2 { text-align: center; margin-bottom: 10px; }
        table { width: 100%; border-collapse: collapse; font-size: 12px; }
        th, td { border: 1px solid #333; padding: 6px 8px; text-align: center; }
        th { background: #f0f0f0; font-weight: bold; }
        .right { text-align: right; }
      </style></head><body>
      <h2>${t('sampleOrderList')}</h2>
      <table><thead><tr>
        <th>${tc('serialNo')}</th><th>${t('notifyDate')}</th><th>${tc('customer')}</th><th>${t('productName')}</th><th>${t('materialNo')}</th><th>${tc('version')}</th><th>${tc('size')}</th><th>${tc('quantity')}</th><th>${t('requireDate')}</th><th>${tc('status')}</th>
      </tr></thead><tbody>`);
    items.forEach((o, i) => {
      printWindow.document.write(`<tr>
        <td>${i + 1}</td><td>${formatDate(o.notify_date)}</td><td>${o.customer_name}</td>
        <td>${o.product_name}</td><td>${o.material_no}</td><td>${o.version}</td>
        <td>${o.size_spec || '-'}</td><td>${o.quantity}</td><td>${formatDate(o.customer_require_date)}</td>
        <td>${t(lifecycleStatusMap[o.status]?.label || o.status)}</td>
      </tr>`);
    });
    printWindow.document.write(`</tbody></table></body></html>`);
    printWindow.document.close();
    printWindow.focus();
    setTimeout(() => {
      printWindow.print();
      printWindow.close();
    }, 300);
  };

  const sortableHeader = (field: string, label: string) => (
    <th
      className="h-12 px-4 text-left align-middle font-medium cursor-pointer select-none hover:bg-muted/80 transition-colors"
      onClick={() => handleSort(field)}
    >
      <span className="inline-flex items-center">
        {label}
        {getSortIcon(field)}
      </span>
    </th>
  );

  const formFields = (
    <div className="grid grid-cols-2 gap-4 py-4">
      <div className="space-y-2">
        <Label>
          {t('notifyDate')} <span className="text-red-500">*</span>
        </Label>
        <Input
          type="date"
          value={formData.notify_date}
          onChange={(e) => handleInputChange('notify_date', e.target.value)}
        />
      </div>
      <div className="space-y-2">
        <Label>
          {tc('customer')} <span className="text-red-500">*</span>
        </Label>
        <Input
          placeholder={tc('customer')}
          value={formData.customer_name}
          onChange={(e) => handleInputChange('customer_name', e.target.value)}
        />
      </div>
      <div className="space-y-2">
        <Label>
          {t('productName')} <span className="text-red-500">*</span>
        </Label>
        <Input
          placeholder={t('productName')}
          value={formData.product_name}
          onChange={(e) => handleInputChange('product_name', e.target.value)}
        />
      </div>
      <div className="space-y-2">
        <Label>
          {t('materialNo')} <span className="text-red-500">*</span>
        </Label>
        <Input
          placeholder={t('materialNo')}
          value={formData.material_no}
          onChange={(e) => handleInputChange('material_no', e.target.value)}
        />
      </div>
      <div className="space-y-2">
        <Label>{tc('version')}</Label>
        <Input
          placeholder={tc('version')}
          value={formData.version}
          onChange={(e) => handleInputChange('version', e.target.value)}
        />
      </div>
      <div className="space-y-2">
        <Label>{tc('quantity')}</Label>
        <Input
          type="number"
          placeholder={tc('quantity')}
          value={formData.quantity}
          onChange={(e) => handleInputChange('quantity', e.target.value)}
        />
      </div>
      <div className="space-y-2">
        <Label>{t('sizeSpec')}</Label>
        <Input
          placeholder={t('sizeSpec')}
          value={formData.size_spec}
          onChange={(e) => handleInputChange('size_spec', e.target.value)}
        />
      </div>
      <div className="space-y-2">
        <Label>{t('requireDate')}</Label>
        <Input
          type="date"
          value={formData.customer_require_date}
          onChange={(e) => handleInputChange('customer_require_date', e.target.value)}
        />
      </div>
      <div className="col-span-2 space-y-2">
        <Label>{t('materialSpec')}</Label>
        <Input
          placeholder={t('materialSpec')}
          value={formData.material_spec}
          onChange={(e) => handleInputChange('material_spec', e.target.value)}
        />
      </div>
      <div className="col-span-2 space-y-2">
        <Label>{tc('remark')}</Label>
        <Input
          placeholder={tc('remark')}
          value={formData.remark}
          onChange={(e) => handleInputChange('remark', e.target.value)}
        />
      </div>
    </div>
  );

  return (
    <MainLayout title={t('sampleOrderManagement')}>
      <div className="space-y-6">
        <Card>
          <CardContent className="p-4">
            <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
              <div className="flex flex-1 gap-4 items-center w-full md:w-auto flex-wrap">
                <div className="relative flex-1 max-w-sm">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    placeholder={t('searchPlaceholder')}
                    className="pl-10"
                    value={searchKeyword}
                    onChange={(e) => setSearchKeyword(e.target.value)}
                  />
                </div>
                <Select value={selectedCustomer} onValueChange={setSelectedCustomer}>
                  <SelectTrigger className="w-[140px]">
                    <SelectValue placeholder={t('customerFilter')} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">{t('allCustomers')}</SelectItem>
                    {customers.map((customer) => (
                      <SelectItem key={customer} value={customer}>
                        {customer}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Select value={selectedStatus} onValueChange={setSelectedStatus}>
                  <SelectTrigger className="w-[140px]">
                    <SelectValue placeholder={t('statusFilter')} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">{tc('all')}</SelectItem>
                    <SelectItem value="draft">{t('draft')}</SelectItem>
                    <SelectItem value="pending">{t('pending')}</SelectItem>
                    <SelectItem value="in_progress">{t('inProgress')}</SelectItem>
                    <SelectItem value="completed">{t('completed')}</SelectItem>
                    <SelectItem value="confirmed">{t('confirmed')}</SelectItem>
                    <SelectItem value="converted">{t('converted')}</SelectItem>
                    <SelectItem value="cancelled">{t('cancelled')}</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="flex gap-2 items-center">
                <GlobalExportToolbar
                  filename="样品订单列表"
                  title="样品订单列表"
                  columns={[
                    {
                      key: 'notify_date',
                      label: t('notifyDate'),
                      width: 12,
                      formatter: (v) => formatDate(v),
                    },
                    { key: 'customer_name', label: tc('customer'), width: 18 },
                    { key: 'product_name', label: t('productName'), width: 22 },
                    { key: 'material_no', label: t('materialNo'), width: 12 },
                    { key: 'version', label: tc('version'), width: 8 },
                    { key: 'size_spec', label: tc('size'), width: 12 },
                    { key: 'quantity', label: tc('quantity'), width: 8 },
                    {
                      key: 'customer_require_date',
                      label: t('requireDate'),
                      width: 12,
                      formatter: (v) => formatDate(v),
                    },
                    {
                      key: 'status',
                      label: tc('status'),
                      width: 12,
                      formatter: (v) => t(lifecycleStatusMap[v]?.label || v),
                    },
                  ]}
                  data={
                    selectedIds.size > 0
                      ? sortedOrders.filter((o) => selectedIds.has(o.id))
                      : sortedOrders
                  }
                />
                <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
                  <DialogTrigger asChild>
                    <Button>
                      <Plus className="h-4 w-4 mr-2" />
                      {t('createSampleOrder')}
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto" resizable>
                    <DialogHeader>
                      <DialogTitle>{t('createSampleOrder')}</DialogTitle>
                      <DialogDescription>{t('fillSampleOrderInfo')}</DialogDescription>
                    </DialogHeader>
                    {formFields}
                    <div className="flex justify-end gap-2">
                      <Button
                        variant="outline"
                        onClick={() => {
                          setIsCreateOpen(false);
                          resetForm();
                        }}
                      >
                        {tc('cancel')}
                      </Button>
                      <Button onClick={handleCreate}>{tc('save')}</Button>
                    </div>
                  </DialogContent>
                </Dialog>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>{t('sampleOrderList')}</CardTitle>
            <CardDescription>
              {t('totalOrders', { total: pagination.total })}
              {selectedIds.size > 0 ? `，${t('selectedItems', { count: selectedIds.size })}` : ''}
            </CardDescription>
          </CardHeader>
          <CardContent>
            {loading ? (
              <div className="flex justify-center items-center py-8">
                <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
              </div>
            ) : sortedOrders.length === 0 ? (
              <div className="text-center py-12 text-muted-foreground">
                {t('noSampleOrderData')}
              </div>
            ) : (
              <div className="rounded-md border overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="border-b bg-muted/50">
                      <th className="h-12 px-4 text-left align-middle font-medium w-[40px]">
                        <Checkbox
                          checked={selectedIds.size > 0 && selectedIds.size === sortedOrders.length}
                          onCheckedChange={toggleSelectAll}
                        />
                      </th>
                      <th className="h-12 px-4 text-left align-middle font-medium w-[60px]">
                        {tc('sequence')}
                      </th>
                      {sortableHeader('order_no', t('orderNo'))}
                      {sortableHeader('notify_date', t('notifyDate'))}
                      {sortableHeader('customer_name', tc('customer'))}
                      {sortableHeader('product_name', t('productName'))}
                      {sortableHeader('material_no', t('materialNo'))}
                      {sortableHeader('version', tc('version'))}
                      {sortableHeader('size_spec', tc('size'))}
                      {sortableHeader('quantity', tc('quantity'))}
                      {sortableHeader('customer_require_date', t('requireDate'))}
                      <th className="h-12 px-4 text-left align-middle font-medium">
                        {tc('status')}
                      </th>
                      <th className="h-12 px-4 text-right align-middle font-medium">
                        {tc('actions')}
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {sortedOrders.map((order, index) => (
                      <tr
                        key={order.id}
                        className={`border-b transition-colors hover:bg-muted/50 ${selectedIds.has(order.id) ? 'bg-primary/5' : ''}`}
                      >
                        <td className="p-4">
                          <Checkbox
                            checked={selectedIds.has(order.id)}
                            onCheckedChange={() => toggleSelect(order.id)}
                          />
                        </td>
                        <td className="p-4 text-sm text-muted-foreground">
                          {(pagination.page - 1) * pagination.pageSize + index + 1}
                        </td>
                        <td className="p-4 font-mono text-sm">{order.order_no}</td>
                        <td className="p-4">{formatDate(order.notify_date)}</td>
                        <td className="p-4 font-medium">{order.customer_name}</td>
                        <td className="p-4">{order.product_name}</td>
                        <td className="p-4 font-mono text-xs">{order.material_no}</td>
                        <td className="p-4">{order.version}</td>
                        <td className="p-4 text-xs">{order.size_spec || '-'}</td>
                        <td className="p-4">{order.quantity}</td>
                        <td className="p-4">{formatDate(order.customer_require_date)}</td>
                        <td className="p-4">{getLifecycleStatusBadge(order.status)}</td>
                        <td className="p-4 text-right">
                          <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                              <Button variant="ghost" size="sm">
                                <MoreHorizontal className="h-4 w-4" />
                              </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end">
                              {order.status === 'draft' && (
                                <DropdownMenuItem
                                  onClick={() => handleLifecycleAction(order.id, 'submit')}
                                >
                                  <FileText className="h-4 w-4 mr-2" />
                                  {t('submit')}
                                </DropdownMenuItem>
                              )}
                              {order.status === 'pending' && (
                                <DropdownMenuItem
                                  onClick={() => handleLifecycleAction(order.id, 'startProduction')}
                                >
                                  <FileText className="h-4 w-4 mr-2" />
                                  {t('startProduction')}
                                </DropdownMenuItem>
                              )}
                              {order.status === 'in_progress' && (
                                <DropdownMenuItem
                                  onClick={() => handleLifecycleAction(order.id, 'complete')}
                                >
                                  <CheckCircle2 className="h-4 w-4 mr-2" />
                                  {t('complete')}
                                </DropdownMenuItem>
                              )}
                              {order.status === 'completed' && (
                                <DropdownMenuItem
                                  onClick={() => handleLifecycleAction(order.id, 'confirm')}
                                >
                                  <CheckCircle2 className="h-4 w-4 mr-2" />
                                  {t('confirm')}
                                </DropdownMenuItem>
                              )}
                              {order.delivery_status === 'pending' &&
                                order.status === 'completed' && (
                                  <DropdownMenuItem
                                    onClick={() => handleDeliveryAction(order.id, 'deliver')}
                                  >
                                    <FileText className="h-4 w-4 mr-2" />
                                    {t('markDelivered')}
                                  </DropdownMenuItem>
                                )}
                              {order.delivery_status === 'delivered' && (
                                <DropdownMenuItem
                                  onClick={() => handleDeliveryAction(order.id, 'sign')}
                                >
                                  <CheckCircle2 className="h-4 w-4 mr-2" />
                                  {t('markSigned')}
                                </DropdownMenuItem>
                              )}
                              <DropdownMenuItem onClick={() => openEditDialog(order)}>
                                <Edit className="h-4 w-4 mr-2" />
                                {tc('edit')}
                              </DropdownMenuItem>
                              <DropdownMenuItem
                                className="text-destructive"
                                onClick={() => handleDelete(order.id)}
                              >
                                <Trash2 className="h-4 w-4 mr-2" />
                                {tc('delete')}
                              </DropdownMenuItem>
                            </DropdownMenuContent>
                          </DropdownMenu>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

            {pagination.totalPages > 1 && (
              <div className="flex items-center justify-between mt-4">
                <span className="text-sm text-muted-foreground">
                  {t('paginationInfo', {
                    total: pagination.total,
                    page: pagination.page,
                    totalPages: pagination.totalPages,
                  })}
                </span>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    disabled={pagination.page === 1}
                    onClick={() => setPagination((p) => ({ ...p, page: p.page - 1 }))}
                  >
                    {tc('prevPage')}
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    disabled={pagination.page === pagination.totalPages}
                    onClick={() => setPagination((p) => ({ ...p, page: p.page + 1 }))}
                  >
                    {tc('nextPage')}
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      <Dialog open={isEditOpen} onOpenChange={setIsEditOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto" resizable>
          <DialogHeader>
            <DialogTitle>{t('editSampleOrder')}</DialogTitle>
            <DialogDescription>{t('modifySampleOrderInfo')}</DialogDescription>
          </DialogHeader>
          {formFields}
          <div className="flex justify-end gap-2">
            <Button
              variant="outline"
              onClick={() => {
                setIsEditOpen(false);
                setEditingOrder(null);
                resetForm();
              }}
            >
              {tc('cancel')}
            </Button>
            <Button onClick={handleUpdate}>{tc('save')}</Button>
          </div>
        </DialogContent>
      </Dialog>
    </MainLayout>
  );
}

'use client';

import { useRef } from 'react';
import { useRouter } from '@/i18n/navigation';
import { Button } from '@/components/ui/button';
import { ArrowLeft, Save, Printer } from 'lucide-react';
import { useCompanyName } from '@/hooks/useCompanyName';
import { useTranslations } from 'next-intl';
import { useStandardCardForm } from '@/hooks/useStandardCardForm';

const EditableCell = ({
  value,
  onChange,
  placeholder = '',
  className = '',
  type = 'text',
}: {
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
  type?: string;
}) => (
  <input
    type={type}
    value={value}
    onChange={(e) => onChange(e.target.value)}
    placeholder={placeholder}
    className={`w-full min-h-[20px] px-1 py-0.5 text-xs text-black dark:text-gray-200 bg-transparent border-none outline-none focus:bg-blue-50 dark:focus:bg-blue-900/30 focus:ring-1 focus:ring-blue-400 rounded-sm ${className}`}
  />
);

const EditableTextarea = ({
  value,
  onChange,
  placeholder = '',
  className = '',
  rows = 2,
}: {
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
  rows?: number;
}) => (
  <textarea
    value={value}
    onChange={(e) => onChange(e.target.value)}
    placeholder={placeholder}
    rows={rows}
    className={`w-full px-1 py-0.5 text-xs text-black dark:text-gray-200 bg-transparent border-none outline-none focus:bg-blue-50 dark:focus:bg-blue-900/30 focus:ring-1 focus:ring-blue-400 rounded-sm resize-none ${className}`}
  />
);

// A4 表格式录入组件（不含 MainLayout 包装，由父页面统一提供）
export function InputCardForm() {
  const { companyName } = useCompanyName();
  const router = useRouter();
  const tc = useTranslations('Common');
  const t = useTranslations('StandardCard');
  const printRef = useRef<HTMLDivElement>(null);

  const {
    data,
    loading,
    saving,
    error,
    customers: _customers,
    customerSearch,
    setCustomerSearch,
    showCustomerDropdown,
    setShowCustomerDropdown,
    filteredCustomers,
    updateField,
    updateSequence,
    handleToggleMultiValue,
    handleSelectCustomer,
    handleSave,
    handleSaveAndPreview,
    isEditMode,
  } = useStandardCardForm({ mode: 'card' });

  const coreTypes = data.coreType?.split(',').filter(Boolean) || [];
  const printTypes = data.printType?.split(',').filter(Boolean) || [];
  const processMethods = data.processMethod?.split(',').filter(Boolean) || [];

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-background">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-background gap-4">
        <p className="text-destructive">
          {t('loadError')}: {error}
        </p>
        <Button onClick={() => router.push('/sample/standard-card?mode=list')}>
          <ArrowLeft className="h-4 w-4 mr-2" />
          {t('backToList')}
        </Button>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 dark:bg-gray-900 p-4">
      {/* A4 横向表格录入区 */}
      <div
        ref={printRef}
        className="bg-white dark:bg-gray-800 mx-auto shadow-lg flex flex-col"
        style={{
          width: '297mm',
          minHeight: '210mm',
          padding: '3mm',
          boxSizing: 'border-box',
        }}
      >
        <style
          dangerouslySetInnerHTML={{
            __html: `
              table { width: 100%; border-collapse: collapse; font-size: 12px; font-family: Arial, sans-serif; }
              table td { padding: 1px 2px !important; vertical-align: middle; text-align: center; border: 1px solid #333 !important; font-size: 12px !important; font-weight: normal !important; line-height: 1.4 !important; }
              .dark table td { border-color: rgba(255,255,255,0.2) !important; }
              .border-none { border: none !important; }
              .border-bottom { border: none !important; border-bottom: 1px solid #000 !important; }
              .dark .border-bottom { border-bottom-color: rgba(255,255,255,0.3) !important; }
              input[type="text"], textarea { background: transparent; }
              input[type="checkbox"], input[type="radio"] { cursor: pointer; }
            `,
          }}
        />

        <table
          className="w-full border-collapse text-xs"
          style={{ tableLayout: 'fixed', height: 'calc(210mm - 6mm)' }}
        >
          <tbody>
            {/* 标题行 */}
            <tr>
              <td colSpan={16} className="text-center border-none">
                <input
                  type="text"
                  value={companyName}
                  readOnly
                  className="w-full text-center text-2xl font-bold text-[#1a3c7a] dark:text-blue-300 bg-transparent border-none outline-none"
                />
              </td>
              <td colSpan={3} className="py-1 border-none">
                <div className="flex items-center w-full h-full">
                  <span className="font-bold text-sm mr-1">NO:</span>
                  <EditableCell
                    value={data.cardNo}
                    onChange={(v) => updateField('cardNo', v)}
                    className="flex-1 min-w-[120px] h-6 text-base font-bold text-[#1a3c7a] dark:text-blue-300 text-center border-b border-black dark:border-gray-400"
                  />
                </div>
              </td>
            </tr>

            {/* 客户/版次/日期行 */}
            <tr>
              <td className="font-bold pr-2 border-none">{t('cardCustomer')}：</td>
              <td colSpan={4} className="font-bold border-none">
                <div className="customer-dropdown-container relative">
                  <input
                    type="text"
                    value={showCustomerDropdown ? customerSearch : data.customer}
                    onChange={(e) => {
                      setCustomerSearch(e.target.value);
                      updateField('customer', e.target.value);
                      setShowCustomerDropdown(true);
                    }}
                    onFocus={() => {
                      setCustomerSearch(data.customer);
                      setShowCustomerDropdown(true);
                    }}
                    placeholder={t('cardSelectCustomer')}
                    className="w-full px-1 py-0.5 text-xs font-bold bg-transparent border-none outline-none focus:bg-blue-50 dark:focus:bg-blue-900/30 rounded-sm"
                  />
                  {showCustomerDropdown && filteredCustomers.length > 0 && (
                    <div className="absolute z-50 left-0 top-full mt-1 w-64 max-h-48 overflow-y-auto bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded shadow-lg">
                      {filteredCustomers.slice(0, 20).map((c) => (
                        <div
                          key={c.id}
                          onClick={() => handleSelectCustomer(c)}
                          className="px-2 py-1 text-xs hover:bg-blue-100 dark:hover:bg-blue-900 cursor-pointer text-left"
                        >
                          <span className="font-mono text-gray-500 mr-2">{c.customerCode}</span>
                          {c.customerName}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </td>
              <td className="font-bold px-2 border-none">{t('cardVersion')}:</td>
              <td className="font-bold border-none">
                <EditableCell value={data.version} onChange={(v) => updateField('version', v)} />
              </td>
              <td colSpan={4} className="text-center text-xl font-bold border-none">
                {t('cardFormTitle')}
              </td>
              <td colSpan={4} className="text-center border-none">
                <span className="bg-[#1a3c7a] dark:bg-blue-700 text-white px-3 py-1 rounded font-bold">
                  HSF
                </span>
              </td>
              <td colSpan={2} className="font-bold text-right px-2 border-none">
                {t('cardDate')}：
              </td>
              <td colSpan={2} className="font-bold border-none">
                <EditableCell
                  type="date"
                  value={data.date}
                  onChange={(v) => updateField('date', v)}
                />
              </td>
            </tr>

            <tr>
              <td colSpan={19} className="h-2 border-none"></td>
            </tr>

            {/* 品名/客户料号/成品尺寸/公差 */}
            <tr>
              <td className="border font-bold text-center w-[4%]">{t('cardProductName')}</td>
              <td colSpan={4} className="border font-bold">
                <EditableCell
                  value={data.productName}
                  onChange={(v) => updateField('productName', v)}
                  placeholder={t('cardInputProductName')}
                />
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center w-[8%]">
                {t('cardCustomerCode')}
              </td>
              <td colSpan={3} className="border">
                <EditableCell
                  value={data.customerCode}
                  onChange={(v) => updateField('customerCode', v)}
                />
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center w-[8%]">
                {t('cardFinishedSize')}
              </td>
              <td colSpan={4} className="border">
                <EditableCell
                  value={data.finishedSize}
                  onChange={(v) => updateField('finishedSize', v)}
                />
              </td>
              <td className="border w-[4%]">m/m</td>
              <td colSpan={2} className="border font-bold">
                {t('cardTolerance')}
              </td>
              <td className="border">
                <EditableCell
                  value={data.tolerance}
                  onChange={(v) => updateField('tolerance', v)}
                />
              </td>
              <td className="border w-[4%]">mm</td>
            </tr>

            {/* 材料名称/排版方式/间距/片料规格/标准用量 */}
            <tr>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardMaterialName')}
              </td>
              <td colSpan={4} className="border font-bold">
                <EditableCell
                  value={data.materialName}
                  onChange={(v) => updateField('materialName', v)}
                />
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardLayoutType')}
              </td>
              <td className="border">
                <EditableCell
                  value={data.layoutType}
                  onChange={(v) => updateField('layoutType', v)}
                />
              </td>
              <td rowSpan={2} className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardSpacing')}
              </td>
              <td className="border">
                <EditableCell value={data.spacing} onChange={(v) => updateField('spacing', v)} />
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardSheetSpecs')}
              </td>
              <td className="border">
                <EditableCell
                  value={data.sheetSpecs.width}
                  onChange={(v) => updateField('sheetSpecs', { ...data.sheetSpecs, width: v })}
                />
              </td>
              <td colSpan={2} className="border">
                m/m宽x
              </td>
              <td className="border">
                <EditableCell
                  value={data.sheetSpecs.length}
                  onChange={(v) => updateField('sheetSpecs', { ...data.sheetSpecs, length: v })}
                />
              </td>
              <td className="border">m/m长</td>
              <td colSpan={2} className="border font-bold">
                {t('cardStandardUsage')}
              </td>
              <td className="border">
                <EditableCell
                  value={data.standardUsage}
                  onChange={(v) => updateField('standardUsage', v)}
                />
              </td>
              <td className="border w-[4%]">c㎡/PCS</td>
            </tr>

            {/* 纸芯类型/出纸方向/卷料宽度/纸边/跳距 */}
            <tr>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardCoreType')}
              </td>
              <td colSpan={4} className="border font-bold">
                <div className="flex justify-center gap-3">
                  {['3#', '2#', '1#'].map((num) => (
                    <label key={num} className="flex items-center gap-1 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={coreTypes.includes(num)}
                        onChange={() => handleToggleMultiValue('coreType', num)}
                        className="w-4 h-4"
                      />
                      <span className="text-sm">{num}</span>
                    </label>
                  ))}
                </div>
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardPaperDirection')}
              </td>
              <td className="border">
                <EditableCell
                  value={data.paperDirection}
                  onChange={(v) => updateField('paperDirection', v)}
                />
              </td>
              <td className="border">
                <EditableCell
                  value={data.spacingValue}
                  onChange={(v) => updateField('spacingValue', v)}
                />
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardRollWidth')}
              </td>
              <td className="border">
                <EditableCell
                  value={data.rollWidth}
                  onChange={(v) => updateField('rollWidth', v)}
                />
              </td>
              <td className="border">mm</td>
              <td className="border">{t('cardPaperEdge')}</td>
              <td className="border">
                <EditableCell
                  value={data.paperEdge}
                  onChange={(v) => updateField('paperEdge', v)}
                />
              </td>
              <td className="border">mm</td>
              <td colSpan={2} className="border font-bold">
                {t('cardJumpDistance')}
              </td>
              <td className="border">
                <EditableCell
                  value={data.jumpDistance}
                  onChange={(v) => updateField('jumpDistance', v)}
                />
              </td>
              <td className="border">mm</td>
            </tr>

            {/* 工艺流程 */}
            <tr>
              <td rowSpan={2} className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {tc('craft')}
                <br />
                {tc('process')}
              </td>
              <td colSpan={18} className="border">
                <EditableCell
                  value={data.processFlow1}
                  onChange={(v) => updateField('processFlow1', v)}
                  placeholder={t('cardProcessFlow1')}
                />
              </td>
            </tr>
            <tr>
              <td colSpan={18} className="border">
                <EditableCell
                  value={data.processFlow2}
                  onChange={(v) => updateField('processFlow2', v)}
                  placeholder={t('cardProcessFlow2')}
                />
              </td>
            </tr>

            {/* 印刷方式/第一跳距/覆膜/成型/MYLAR */}
            <tr>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardPrintType')}
              </td>
              <td colSpan={6} className="border">
                <div className="flex justify-center gap-3">
                  {[
                    t('cardOffsetPrint'),
                    t('cardRollScreenPrint'),
                    t('cardSheetScreenPrint'),
                    t('cardRotaryPrint'),
                  ].map((type) => (
                    <label key={type} className="flex items-center gap-1 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={printTypes.includes(type)}
                        onChange={() => handleToggleMultiValue('printType', type)}
                        className="w-4 h-4"
                      />
                      <span className="text-sm">{type}</span>
                    </label>
                  ))}
                </div>
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardFirstJumpDistance')}
              </td>
              <td className="border">
                <EditableCell
                  value={data.firstJumpDistance}
                  onChange={(v) => updateField('firstJumpDistance', v)}
                />
              </td>
              <td colSpan={2} className="border font-bold text-center">
                {t('cardLaminating')}
              </td>
              <td colSpan={4} className="border font-bold text-center">
                {t('cardForming')}
              </td>
              <td colSpan={4} className="border font-bold text-center">
                MYLAR
              </td>
            </tr>

            {/* 印序表头行 */}
            <tr>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardPrintSequence')}
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardPrintColor')}
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardInkCode')}
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardFilmCode')}
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardStorageLocation')}
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardPlateCode')}
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardMesh')}
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardStorageLocation')}
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardPrintSide')}
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardCategory')}
              </td>
              <td className="border">
                <EditableCell value={data.moldType} onChange={(v) => updateField('moldType', v)} />
              </td>
              <td colSpan={4} className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                <div className="flex justify-center gap-3">
                  {[t('cardDieCut'), t('cardStamping')].map((type) => (
                    <label key={type} className="flex items-center gap-1 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={processMethods.includes(type)}
                        onChange={() => handleToggleMultiValue('processMethod', type)}
                        className="w-4 h-4"
                      />
                      <span className="text-sm">{type}</span>
                    </label>
                  ))}
                </div>
              </td>
              <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                {t('cardMaterial')}
              </td>
              <td colSpan={3} className="border">
                <EditableCell
                  value={data.materialType}
                  onChange={(v) => updateField('materialType', v)}
                />
              </td>
            </tr>

            {/* 印序数据行 1-7 */}
            {data.sequences.map((seq, index) => (
              <tr key={seq.id} style={{ height: '28px' }}>
                <td className="border text-center font-bold">{seq.id}</td>
                <td className="border">
                  <EditableCell
                    value={seq.color}
                    onChange={(v) => updateSequence(index, 'color', v)}
                  />
                </td>
                <td className="border">
                  <EditableCell
                    value={seq.inkCode}
                    onChange={(v) => updateSequence(index, 'inkCode', v)}
                  />
                </td>
                <td className="border">
                  <EditableCell
                    value={seq.linCode}
                    onChange={(v) => updateSequence(index, 'linCode', v)}
                  />
                </td>
                <td className="border">
                  <EditableCell
                    value={seq.storageLocation}
                    onChange={(v) => updateSequence(index, 'storageLocation', v)}
                  />
                </td>
                <td className="border">
                  <EditableCell
                    value={seq.plateCode}
                    onChange={(v) => updateSequence(index, 'plateCode', v)}
                  />
                </td>
                <td className="border">
                  <EditableCell
                    value={seq.mesh}
                    onChange={(v) => updateSequence(index, 'mesh', v)}
                  />
                </td>
                <td className="border">
                  <EditableCell
                    value={seq.plateStorage}
                    onChange={(v) => updateSequence(index, 'plateStorage', v)}
                  />
                </td>
                <td className="border">
                  <EditableCell
                    value={seq.printSide}
                    onChange={(v) => updateSequence(index, 'printSide', v)}
                  />
                </td>
                {index === 0 ? (
                  <>
                    <td className="border">{t('cardManufacturer')}</td>
                    <td className="border">
                      <EditableCell
                        value={data.filmManufacturer}
                        onChange={(v) => updateField('filmManufacturer', v)}
                      />
                    </td>
                    <td colSpan={2} className="border">
                      {t('cardStampingMethod')}
                    </td>
                    <td colSpan={2} className="border">
                      <EditableCell
                        value={data.stampingMethod}
                        onChange={(v) => updateField('stampingMethod', v)}
                      />
                    </td>
                    <td className="border">{tc('specification')}</td>
                    <td colSpan={2} className="border">
                      <EditableCell
                        value={data.mylarSpecs}
                        onChange={(v) => updateField('mylarSpecs', v)}
                      />
                    </td>
                    <td className="border">MM</td>
                  </>
                ) : index === 1 ? (
                  <>
                    <td className="border">{t('cardNumber')}</td>
                    <td className="border">
                      <EditableCell
                        value={data.moldCode}
                        onChange={(v) => updateField('moldCode', v)}
                      />
                    </td>
                    <td colSpan={2} className="border">
                      {t('cardMoldCode')}
                    </td>
                    <td colSpan={2} className="border">
                      <EditableCell
                        value={data.backMoldCode}
                        onChange={(v) => updateField('backMoldCode', v)}
                      />
                    </td>
                    <td className="border">{t('cardLayoutMold')}</td>
                    <td colSpan={3} className="border">
                      <EditableCell
                        value={data.layoutMethod}
                        onChange={(v) => updateField('layoutMethod', v)}
                      />
                    </td>
                  </>
                ) : index === 2 ? (
                  <>
                    <td className="border">{tc('size')}</td>
                    <td className="border">
                      <EditableCell
                        value={data.adhesiveSize}
                        onChange={(v) => updateField('adhesiveSize', v)}
                      />
                    </td>
                    <td colSpan={2} className="border">
                      {t('cardLayoutMethod')}
                    </td>
                    <td colSpan={2} className="border">
                      <EditableCell
                        value={data.backMylarMold}
                        onChange={(v) => updateField('backMylarMold', v)}
                      />
                    </td>
                    <td className="border">{t('cardJumpDistance')}</td>
                    <td colSpan={2} className="border">
                      <EditableCell
                        value={data.jumpDistance2}
                        onChange={(v) => updateField('jumpDistance2', v)}
                      />
                    </td>
                    <td className="border">MM</td>
                  </>
                ) : index === 3 ? (
                  <>
                    <td colSpan={2} className="border">
                      {t('cardAdhesive')}
                    </td>
                    <td colSpan={2} className="border">
                      {t('cardDashedKnife')}
                    </td>
                    <td colSpan={2} className="border">
                      <div className="flex justify-center gap-4">
                        <label className="flex items-center gap-1 text-xs cursor-pointer">
                          <input
                            type="radio"
                            name="dashedKnife"
                            checked={data.dashedKnife === true}
                            onChange={() => updateField('dashedKnife', true)}
                            className="w-3 h-3"
                          />{' '}
                          {t('yes')}
                        </label>
                        <label className="flex items-center gap-1 text-xs cursor-pointer">
                          <input
                            type="radio"
                            name="dashedKnife"
                            checked={data.dashedKnife === false}
                            onChange={() => updateField('dashedKnife', false)}
                            className="w-3 h-3"
                          />{' '}
                          {t('no')}
                        </label>
                      </div>
                    </td>
                    <td colSpan={4} className="border">
                      {t('cardPacking')}
                    </td>
                  </>
                ) : index === 4 ? (
                  <>
                    <td className="border">{t('cardCategory')}</td>
                    <td className="border">
                      <EditableCell
                        value={data.adhesiveType}
                        onChange={(v) => updateField('adhesiveType', v)}
                      />
                    </td>
                    <td rowSpan={3} colSpan={2} className="border font-bold">
                      {t('cardSliceMethod')}
                    </td>
                    <td className="border">
                      <EditableCell
                        value={data.slicePerRow}
                        onChange={(v) => updateField('slicePerRow', v)}
                      />
                    </td>
                    <td className="border">{t('cardPcsPerRow')}</td>
                    <td colSpan={2} className="border">
                      <EditableCell
                        value={data.slicePerRoll}
                        onChange={(v) => updateField('slicePerRoll', v)}
                      />
                    </td>
                    <td colSpan={2} className="border">
                      {t('cardPcsPerRoll')}
                    </td>
                  </>
                ) : index === 5 ? (
                  <>
                    <td className="border">{t('cardManufacturer')}</td>
                    <td className="border">
                      <EditableCell
                        value={data.adhesiveManufacturer}
                        onChange={(v) => updateField('adhesiveManufacturer', v)}
                      />
                    </td>
                    <td className="border">
                      <EditableCell
                        value={data.slicePerBundle}
                        onChange={(v) => updateField('slicePerBundle', v)}
                      />
                    </td>
                    <td className="border">{t('cardPcsPerBag')}</td>
                    <td colSpan={2} className="border">
                      <EditableCell
                        value={data.slicePerBag}
                        onChange={(v) => updateField('slicePerBag', v)}
                      />
                    </td>
                    <td colSpan={2} className="border">
                      {t('cardPcsPerBundle')}
                    </td>
                  </>
                ) : (
                  <>
                    <td className="border">{tc('specification')}</td>
                    <td className="border">
                      <EditableCell
                        value={data.adhesiveSpecs}
                        onChange={(v) => updateField('adhesiveSpecs', v)}
                      />
                    </td>
                    <td className="border">
                      <EditableCell
                        value={data.slicePerBox}
                        onChange={(v) => updateField('slicePerBox', v)}
                      />
                    </td>
                    <td className="border">{t('cardPcsPerBox')}</td>
                    <td colSpan={2} className="border">
                      <EditableCell
                        value={data.packingQty}
                        onChange={(v) => updateField('packingQty', v)}
                      />
                    </td>
                    <td colSpan={2} className="border">
                      {t('cardPcsPerBag')}
                    </td>
                  </>
                )}
              </tr>
            ))}

            {/* 专色配比/离型纸/刀模行 */}
            <tr>
              <td rowSpan={3} className="border text-center font-bold">
                {t('cardSpecialColorRatio')}
              </td>
              <td rowSpan={3} colSpan={8} className="border">
                <EditableTextarea
                  value={data.colorFormula}
                  onChange={(v) => updateField('colorFormula', v)}
                  placeholder={t('cardSpecialColorRatio')}
                />
              </td>
              <td colSpan={2} className="border">
                {t('cardReleasePaper')}
              </td>
              <td colSpan={2} className="border">
                {t('cardBackKnifeMold')}
              </td>
              <td colSpan={2} className="border">
                <EditableCell
                  value={data.backKnifeMold}
                  onChange={(v) => updateField('backKnifeMold', v)}
