import { ScrollArea } from '@/components/ui/scroll-area';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Save,
  Printer,
  ArrowLeft,
  Sparkles,
  FileText,
  Palette,
  Settings,
  Package,
