                        placeholder="如：±0.1mm"
                      />
                    </div>
                  </CardContent>
                </Card>
              </div>

              <div className="flex justify-end">
                <Button onClick={() => setActiveTab('material')}>下一步：材料规格</Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* 材料规格 */}
