'use client';

import { useEffect, useState, useRef, Suspense, useCallback } from 'react';
import { useSearchParams } from 'next/navigation';
import { useRouter } from '@/i18n/navigation';
import { authFetch } from '@/lib/auth-fetch';
import { MainLayout } from '@/components/layout';
import { Button } from '@/components/ui/button';
import { ArrowLeft } from 'lucide-react';
import { useCompanyName } from '@/hooks/useCompanyName';
import { useTranslations } from 'next-intl';
import { useToast } from '@/hooks/use-toast';
import {
  type CardData,
  type PrintSequence,
  createEmptyData,
  toggleMultiValue,
  mapCardDataToApiPayload,
  mapApiDataToCardData,
} from './utils';

interface Customer {
  id: number;
  customerCode: string;
  customerName: string;
  shortName: string;
}

const EditableCell = ({
  value,
  onChange,
  placeholder = '',
  className = '',
  type = 'text',
}: {
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
  type?: string;
}) => (
  <input
    type={type}
    value={value}
    onChange={(e) => onChange(e.target.value)}
    placeholder={placeholder}
    className={`w-full min-h-[20px] px-1 py-0.5 text-xs text-black dark:text-gray-200 bg-transparent border-none outline-none focus:bg-blue-50 dark:focus:bg-blue-900/30 focus:ring-1 focus:ring-blue-400 rounded-sm ${className}`}
  />
);

const EditableTextarea = ({
  value,
  onChange,
  placeholder = '',
  className = '',
  rows = 2,
}: {
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
  rows?: number;
}) => (
  <textarea
    value={value}
    onChange={(e) => onChange(e.target.value)}
    placeholder={placeholder}
    rows={rows}
    className={`w-full px-1 py-0.5 text-xs text-black dark:text-gray-200 bg-transparent border-none outline-none focus:bg-blue-50 dark:focus:bg-blue-900/30 focus:ring-1 focus:ring-blue-400 rounded-sm resize-none ${className}`}
  />
);

function InputCardPageContent() {
  const { companyName } = useCompanyName();
  const router = useRouter();
  const searchParams = useSearchParams();
  const tc = useTranslations('Common');
  const { toast } = useToast();
  const printRef = useRef<HTMLDivElement>(null);

  const editId = searchParams.get('id');
  const isEditMode = !!editId;

  const [data, setData] = useState<CardData>(createEmptyData);
  const [loading, setLoading] = useState(isEditMode);
  const [_saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [customers, setCustomers] = useState<Customer[]>([]);
  const [customerSearch, setCustomerSearch] = useState('');
  const [showCustomerDropdown, setShowCustomerDropdown] = useState(false);

  const loadData = useCallback(async (id: string) => {
    try {
      setLoading(true);
      const response = await authFetch(`/api/standard-cards?id=${id}`);
      const result = await response.json();
      if (result.success && result.data) {
        setData(mapApiDataToCardData(result.data));
      } else {
        console.error('[StandardCard:Load] API返回失败:', result.message);
        setError(result.message || '加载失败');
      }
    } catch (e) {
      console.error('[StandardCard:Load] 异常:', e instanceof Error ? e.message : e, e);
      setError(e instanceof Error ? e.message : '加载数据失败');
    } finally {
      setLoading(false);
    }
  }, []);

  const fetchCustomers = useCallback(async () => {
    try {
      const response = await authFetch('/api/customers?page=1&pageSize=999');
      const result = await response.json();
      if (result.success && Array.isArray(result.data)) {
        const formatted: Customer[] = result.data.map((item: Record<string, unknown>) => ({
          id: item.id as number,
          customerCode: (item.customer_code as string) || '',
          customerName: (item.customer_name as string) || '',
          shortName: (item.short_name as string) || '',
        }));
        setCustomers(formatted);
      } else if (result.success && result.data?.list && Array.isArray(result.data.list)) {
        const formatted: Customer[] = result.data.list.map((item: Record<string, unknown>) => ({
          id: item.id as number,
          customerCode: (item.customer_code as string) || '',
          customerName: (item.customer_name as string) || '',
          shortName: (item.short_name as string) || '',
        }));
        setCustomers(formatted);
      }
    } catch {
      // ignore
    }
  }, []);

  useEffect(() => {
    fetchCustomers();
    if (editId) {
      loadData(editId);
    }
  }, [editId, loadData, fetchCustomers]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (!target.closest('.customer-dropdown-container')) {
        setShowCustomerDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const updateField = <K extends keyof CardData>(field: K, value: CardData[K]) => {
    setData((prev) => ({ ...prev, [field]: value }));
  };

  const updateSequence = (index: number, field: keyof PrintSequence, value: string) => {
    setData((prev) => ({
      ...prev,
      sequences: prev.sequences.map((seq, i) => (i === index ? { ...seq, [field]: value } : seq)),
    }));
  };

  const handleToggleMultiValue = (
    field: 'coreType' | 'printType' | 'processMethod',
    value: string
  ) => {
    setData((prev) => ({ ...prev, [field]: toggleMultiValue(prev[field], value) }));
  };

  const handleSelectCustomer = (customer: Customer) => {
    updateField('customer', customer.customerName);
    updateField('customerCode', customer.customerCode);
    setCustomerSearch('');
    setShowCustomerDropdown(false);
  };

  const filteredCustomers = customers.filter(
    (c) =>
      c.customerName.toLowerCase().includes(customerSearch.toLowerCase()) ||
      c.customerCode.toLowerCase().includes(customerSearch.toLowerCase())
  );

  const handleSave = async () => {
    if (!data.customer) {
      console.warn('[StandardCard:Save] 校验失败: 客户为空');
      toast({ title: '请选择客户', variant: 'destructive' });
      return;
    }
    if (!data.productName) {
      console.warn('[StandardCard:Save] 校验失败: 品名为空');
      toast({ title: '请输入品名', variant: 'destructive' });
      return;
    }

    try {
      setSaving(true);
      const saveData = mapCardDataToApiPayload(data, isEditMode, editId || undefined);

      const url = '/api/standard-cards';
      const method = isEditMode ? 'PUT' : 'POST';

      const response = await authFetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(saveData),
      });

      const result = await response.json();

      if (!result.success) {
        console.error('[StandardCard:Save] API返回失败:', result.message, result);
        toast({ title: result.message || '保存失败', variant: 'destructive' });
        return;
      }

      const newId = result.data?.id || parseInt(editId || '0');
      toast({ title: isEditMode ? '标准卡更新成功' : '标准卡保存成功' });

      if (!isEditMode && newId) {
        router.push(`/sample/standard-card/input-card?id=${newId}`);
      }
    } catch (e) {
      console.error('[StandardCard:Save] 异常:', e instanceof Error ? e.message : e, e);
      toast({ title: '保存失败，请检查网络连接', variant: 'destructive' });
    } finally {
      setSaving(false);
    }
  };

  const _handleSaveAndPreview = async () => {
    await handleSave();
    const id = searchParams.get('id');
    if (id) {
      router.push(`/sample/standard-card/print?id=${id}`);
    }
  };

  const coreTypes = data.coreType?.split(',').filter(Boolean) || [];
  const printTypes = data.printType?.split(',').filter(Boolean) || [];
  const processMethods = data.processMethod?.split(',').filter(Boolean) || [];

  if (loading) {
    return (
      <MainLayout>
        <div className="flex items-center justify-center min-h-screen bg-background">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
        </div>
      </MainLayout>
    );
  }

  if (error) {
    return (
      <MainLayout>
        <div className="flex flex-col items-center justify-center min-h-screen bg-background gap-4">
          <p className="text-destructive">加载错误: {error}</p>
          <Button onClick={() => router.push('/sample/standard-card')}>
            <ArrowLeft className="h-4 w-4 mr-2" />
            返回列表
          </Button>
        </div>
      </MainLayout>
    );
  }

  return (
    <MainLayout>
      <div className="min-h-screen bg-gray-100 dark:bg-gray-900 p-4">
        {/* A4 横向表格录入区 */}
        <div
          ref={printRef}
          className="bg-white dark:bg-gray-800 mx-auto shadow-lg flex flex-col"
          style={{
            width: '297mm',
            minHeight: '210mm',
            padding: '3mm',
            boxSizing: 'border-box',
          }}
        >
          <style
            dangerouslySetInnerHTML={{
              __html: `
                table { width: 100%; border-collapse: collapse; font-size: 12px; font-family: Arial, sans-serif; }
                table td { padding: 1px 2px !important; vertical-align: middle; text-align: center; border: 1px solid #333 !important; font-size: 12px !important; font-weight: normal !important; line-height: 1.4 !important; }
                .dark table td { border-color: rgba(255,255,255,0.2) !important; }
                .border-none { border: none !important; }
                .border-bottom { border: none !important; border-bottom: 1px solid #000 !important; }
                .dark .border-bottom { border-bottom-color: rgba(255,255,255,0.3) !important; }
                input[type="text"], textarea { background: transparent; }
                input[type="checkbox"], input[type="radio"] { cursor: pointer; }
              `,
            }}
          />

          <table
            className="w-full border-collapse text-xs"
            style={{ tableLayout: 'fixed', height: 'calc(210mm - 6mm)' }}
          >
            <tbody>
              {/* 标题行 */}
              <tr>
                <td colSpan={16} className="text-center border-none">
                  <input
                    type="text"
                    value={companyName}
                    readOnly
                    className="w-full text-center text-2xl font-bold text-[#1a3c7a] dark:text-blue-300 bg-transparent border-none outline-none"
                  />
                </td>
                <td colSpan={3} className="py-1 border-none">
                  <div className="flex items-center w-full h-full">
                    <span className="font-bold text-sm mr-1">NO:</span>
                    <EditableCell
                      value={data.cardNo}
                      onChange={(v) => updateField('cardNo', v)}
                      className="flex-1 min-w-[120px] h-6 text-base font-bold text-[#1a3c7a] dark:text-blue-300 text-center border-b border-black dark:border-gray-400"
                    />
                  </div>
                </td>
              </tr>

              {/* 客户/版次/日期行 */}
              <tr>
                <td className="font-bold pr-2 border-none">客户：</td>
                <td colSpan={4} className="font-bold border-none">
                  <div className="customer-dropdown-container relative">
                    <input
                      type="text"
                      value={showCustomerDropdown ? customerSearch : data.customer}
                      onChange={(e) => {
                        setCustomerSearch(e.target.value);
                        updateField('customer', e.target.value);
                        setShowCustomerDropdown(true);
                      }}
                      onFocus={() => {
                        setCustomerSearch(data.customer);
                        setShowCustomerDropdown(true);
                      }}
                      placeholder="选择或输入客户"
                      className="w-full px-1 py-0.5 text-xs font-bold bg-transparent border-none outline-none focus:bg-blue-50 dark:focus:bg-blue-900/30 rounded-sm"
                    />
                    {showCustomerDropdown && filteredCustomers.length > 0 && (
                      <div className="absolute z-50 left-0 top-full mt-1 w-64 max-h-48 overflow-y-auto bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded shadow-lg">
                        {filteredCustomers.slice(0, 20).map((c) => (
                          <div
                            key={c.id}
                            onClick={() => handleSelectCustomer(c)}
                            className="px-2 py-1 text-xs hover:bg-blue-100 dark:hover:bg-blue-900 cursor-pointer text-left"
                          >
                            <span className="font-mono text-gray-500 mr-2">{c.customerCode}</span>
                            {c.customerName}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </td>
                <td className="font-bold px-2 border-none">版次:</td>
                <td className="font-bold border-none">
                  <EditableCell value={data.version} onChange={(v) => updateField('version', v)} />
                </td>
                <td colSpan={4} className="text-center text-xl font-bold border-none">
                  标准卡（流程卡）
                </td>
                <td colSpan={4} className="text-center border-none">
                  <span className="bg-[#1a3c7a] dark:bg-blue-700 text-white px-3 py-1 rounded font-bold">
                    HSF
                  </span>
                </td>
                <td colSpan={2} className="font-bold text-right px-2 border-none">
                  日期：
                </td>
                <td colSpan={2} className="font-bold border-none">
                  <EditableCell
                    type="date"
                    value={data.date}
                    onChange={(v) => updateField('date', v)}
                  />
                </td>
              </tr>

              <tr>
                <td colSpan={19} className="h-2 border-none"></td>
              </tr>

              {/* 品名/客户料号/成品尺寸/公差 */}
              <tr>
                <td className="border font-bold text-center w-[4%]">品名</td>
                <td colSpan={4} className="border font-bold">
                  <EditableCell
                    value={data.productName}
                    onChange={(v) => updateField('productName', v)}
                    placeholder="输入品名"
                  />
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center w-[8%]">
                  客户料号
                </td>
                <td colSpan={3} className="border">
                  <EditableCell
                    value={data.customerCode}
                    onChange={(v) => updateField('customerCode', v)}
                  />
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center w-[8%]">
                  成品尺寸
                </td>
                <td colSpan={4} className="border">
                  <EditableCell
                    value={data.finishedSize}
                    onChange={(v) => updateField('finishedSize', v)}
                  />
                </td>
                <td className="border w-[4%]">m/m</td>
                <td colSpan={2} className="border font-bold">
                  公差+
                </td>
                <td className="border">
                  <EditableCell
                    value={data.tolerance}
                    onChange={(v) => updateField('tolerance', v)}
                  />
                </td>
                <td className="border w-[4%]">mm</td>
              </tr>

              {/* 材料名称/排版方式/间距/片料规格/标准用量 */}
              <tr>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  材料名称
                </td>
                <td colSpan={4} className="border font-bold">
                  <EditableCell
                    value={data.materialName}
                    onChange={(v) => updateField('materialName', v)}
                  />
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  排版方式
                </td>
                <td className="border">
                  <EditableCell
                    value={data.layoutType}
                    onChange={(v) => updateField('layoutType', v)}
                  />
                </td>
                <td
                  rowSpan={2}
                  className="border bg-gray-50 dark:bg-gray-700 font-bold text-center"
                >
                  间距
                </td>
                <td className="border">
                  <EditableCell value={data.spacing} onChange={(v) => updateField('spacing', v)} />
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  片料规格
                </td>
                <td className="border">
                  <EditableCell
                    value={data.sheetSpecs.width}
                    onChange={(v) => updateField('sheetSpecs', { ...data.sheetSpecs, width: v })}
                  />
                </td>
                <td colSpan={2} className="border">
                  m/m宽x
                </td>
                <td className="border">
                  <EditableCell
                    value={data.sheetSpecs.length}
                    onChange={(v) => updateField('sheetSpecs', { ...data.sheetSpecs, length: v })}
                  />
                </td>
                <td className="border">m/m长</td>
                <td colSpan={2} className="border font-bold">
                  标准用量
                </td>
                <td className="border">
                  <EditableCell
                    value={data.standardUsage}
                    onChange={(v) => updateField('standardUsage', v)}
                  />
                </td>
                <td className="border w-[4%]">c㎡/PCS</td>
              </tr>

              {/* 纸芯类型/出纸方向/卷料宽度/纸边/跳距 */}
              <tr>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  纸芯类型
                </td>
                <td colSpan={4} className="border font-bold">
                  <div className="flex justify-center gap-3">
                    {['3#', '2#', '1#'].map((num) => (
                      <label key={num} className="flex items-center gap-1 cursor-pointer">
                        <input
                          type="checkbox"
                          checked={coreTypes.includes(num)}
                          onChange={() => handleToggleMultiValue('coreType', num)}
                          className="w-4 h-4"
                        />
                        <span className="text-sm">{num}</span>
                      </label>
                    ))}
                  </div>
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  出纸方向
                </td>
                <td className="border">
                  <EditableCell
                    value={data.paperDirection}
                    onChange={(v) => updateField('paperDirection', v)}
                  />
                </td>
                <td className="border">
                  <EditableCell
                    value={data.spacingValue}
                    onChange={(v) => updateField('spacingValue', v)}
                  />
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  卷料宽度
                </td>
                <td className="border">
                  <EditableCell
                    value={data.rollWidth}
                    onChange={(v) => updateField('rollWidth', v)}
                  />
                </td>
                <td className="border">mm</td>
                <td className="border">纸边</td>
                <td className="border">
                  <EditableCell
                    value={data.paperEdge}
                    onChange={(v) => updateField('paperEdge', v)}
                  />
                </td>
                <td className="border">mm</td>
                <td colSpan={2} className="border font-bold">
                  跳距
                </td>
                <td className="border">
                  <EditableCell
                    value={data.jumpDistance}
                    onChange={(v) => updateField('jumpDistance', v)}
                  />
                </td>
                <td className="border">mm</td>
              </tr>

              {/* 工艺流程 */}
              <tr>
                <td
                  rowSpan={2}
                  className="border bg-gray-50 dark:bg-gray-700 font-bold text-center"
                >
                  {tc('craft')}
                  <br />
                  {tc('process')}
                </td>
                <td colSpan={18} className="border">
                  <EditableCell
                    value={data.processFlow1}
                    onChange={(v) => updateField('processFlow1', v)}
                    placeholder="工艺流程1"
                  />
                </td>
              </tr>
              <tr>
                <td colSpan={18} className="border">
                  <EditableCell
                    value={data.processFlow2}
                    onChange={(v) => updateField('processFlow2', v)}
                    placeholder="工艺流程2"
                  />
                </td>
              </tr>

              {/* 印刷方式/第一跳距/覆膜/成型/MYLAR */}
              <tr>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  印刷方式
                </td>
                <td colSpan={6} className="border">
                  <div className="flex justify-center gap-3">
                    {['胶印', '卷料丝印', '片料丝印', '轮转印'].map((type) => (
                      <label key={type} className="flex items-center gap-1 cursor-pointer">
                        <input
                          type="checkbox"
                          checked={printTypes.includes(type)}
                          onChange={() => handleToggleMultiValue('printType', type)}
                          className="w-4 h-4"
                        />
                        <span className="text-sm">{type}</span>
                      </label>
                    ))}
                  </div>
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  第一跳距
                </td>
                <td className="border">
                  <EditableCell
                    value={data.firstJumpDistance}
                    onChange={(v) => updateField('firstJumpDistance', v)}
                  />
                </td>
                <td colSpan={2} className="border font-bold text-center">
                  覆 膜
                </td>
                <td colSpan={4} className="border font-bold text-center">
                  成 型
                </td>
                <td colSpan={4} className="border font-bold text-center">
                  MYLAR
                </td>
              </tr>

              {/* 印序表头行 */}
              <tr>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">印序</td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">印色</td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  油墨编号
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  菲林编号
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  存放位置
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  印版编号
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">网目</td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  存放位置
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">印面</td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">种类</td>
                <td className="border">
                  <EditableCell
                    value={data.moldType}
                    onChange={(v) => updateField('moldType', v)}
                  />
                </td>
                <td
                  colSpan={4}
                  className="border bg-gray-50 dark:bg-gray-700 font-bold text-center"
                >
                  <div className="flex justify-center gap-3">
                    {['模切', '冲压'].map((type) => (
                      <label key={type} className="flex items-center gap-1 cursor-pointer">
                        <input
                          type="checkbox"
                          checked={processMethods.includes(type)}
                          onChange={() => handleToggleMultiValue('processMethod', type)}
                          className="w-4 h-4"
                        />
                        <span className="text-sm">{type}</span>
                      </label>
                    ))}
                  </div>
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">材料</td>
                <td colSpan={3} className="border">
                  <EditableCell
                    value={data.materialType}
                    onChange={(v) => updateField('materialType', v)}
                  />
                </td>
              </tr>

              {/* 印序数据行 1-7 */}
              {data.sequences.map((seq, index) => (
                <tr key={seq.id} style={{ height: '28px' }}>
                  <td className="border text-center font-bold">{seq.id}</td>
                  <td className="border">
                    <EditableCell
                      value={seq.color}
                      onChange={(v) => updateSequence(index, 'color', v)}
                    />
                  </td>
                  <td className="border">
                    <EditableCell
                      value={seq.inkCode}
                      onChange={(v) => updateSequence(index, 'inkCode', v)}
                    />
                  </td>
                  <td className="border">
                    <EditableCell
                      value={seq.linCode}
                      onChange={(v) => updateSequence(index, 'linCode', v)}
                    />
                  </td>
                  <td className="border">
                    <EditableCell
                      value={seq.storageLocation}
                      onChange={(v) => updateSequence(index, 'storageLocation', v)}
                    />
                  </td>
                  <td className="border">
                    <EditableCell
                      value={seq.plateCode}
                      onChange={(v) => updateSequence(index, 'plateCode', v)}
                    />
                  </td>
                  <td className="border">
                    <EditableCell
                      value={seq.mesh}
                      onChange={(v) => updateSequence(index, 'mesh', v)}
                    />
                  </td>
                  <td className="border">
                    <EditableCell
                      value={seq.plateStorage}
                      onChange={(v) => updateSequence(index, 'plateStorage', v)}
                    />
                  </td>
                  <td className="border">
                    <EditableCell
                      value={seq.printSide}
                      onChange={(v) => updateSequence(index, 'printSide', v)}
                    />
                  </td>
                  {index === 0 ? (
                    <>
                      <td className="border">厂商</td>
                      <td className="border">
                        <EditableCell
                          value={data.filmManufacturer}
                          onChange={(v) => updateField('filmManufacturer', v)}
                        />
                      </td>
                      <td colSpan={2} className="border">
                        冲压方法
                      </td>
                      <td colSpan={2} className="border">
                        <EditableCell
                          value={data.stampingMethod}
                          onChange={(v) => updateField('stampingMethod', v)}
                        />
                      </td>
                      <td className="border">{tc('specification')}</td>
                      <td colSpan={2} className="border">
                        <EditableCell
                          value={data.mylarSpecs}
                          onChange={(v) => updateField('mylarSpecs', v)}
                        />
                      </td>
                      <td className="border">MM</td>
                    </>
                  ) : index === 1 ? (
                    <>
                      <td className="border">编号</td>
                      <td className="border">
                        <EditableCell
                          value={data.moldCode}
                          onChange={(v) => updateField('moldCode', v)}
                        />
                      </td>
                      <td colSpan={2} className="border">
                        模具编号
                      </td>
                      <td colSpan={2} className="border">
                        <EditableCell
                          value={data.backMoldCode}
                          onChange={(v) => updateField('backMoldCode', v)}
                        />
                      </td>
                      <td className="border">排模</td>
                      <td colSpan={3} className="border">
                        <EditableCell
                          value={data.layoutMethod}
                          onChange={(v) => updateField('layoutMethod', v)}
                        />
                      </td>
                    </>
                  ) : index === 2 ? (
                    <>
                      <td className="border">{tc('size')}</td>
                      <td className="border">
                        <EditableCell
                          value={data.adhesiveSize}
                          onChange={(v) => updateField('adhesiveSize', v)}
                        />
                      </td>
                      <td colSpan={2} className="border">
                        排模方法
                      </td>
                      <td colSpan={2} className="border">
                        <EditableCell
                          value={data.backMylarMold}
                          onChange={(v) => updateField('backMylarMold', v)}
                        />
                      </td>
                      <td className="border">跳距</td>
                      <td colSpan={2} className="border">
                        <EditableCell
                          value={data.jumpDistance2}
                          onChange={(v) => updateField('jumpDistance2', v)}
                        />
                      </td>
                      <td className="border">MM</td>
                    </>
                  ) : index === 3 ? (
                    <>
                      <td colSpan={2} className="border">
                        背胶
                      </td>
                      <td colSpan={2} className="border">
                        加虚线刀
                      </td>
                      <td colSpan={2} className="border">
                        <div className="flex justify-center gap-4">
                          <label className="flex items-center gap-1 text-xs cursor-pointer">
                            <input
                              type="radio"
                              name="dashedKnife"
                              checked={data.dashedKnife === true}
                              onChange={() => updateField('dashedKnife', true)}
                              className="w-3 h-3"
                            />{' '}
                            是
                          </label>
                          <label className="flex items-center gap-1 text-xs cursor-pointer">
                            <input
                              type="radio"
                              name="dashedKnife"
                              checked={data.dashedKnife === false}
                              onChange={() => updateField('dashedKnife', false)}
                              className="w-3 h-3"
                            />{' '}
                            否
                          </label>
                        </div>
                      </td>
                      <td colSpan={4} className="border">
                        包装
                      </td>
                    </>
                  ) : index === 4 ? (
                    <>
                      <td className="border">种类</td>
                      <td className="border">
                        <EditableCell
                          value={data.adhesiveType}
                          onChange={(v) => updateField('adhesiveType', v)}
                        />
                      </td>
                      <td rowSpan={3} colSpan={2} className="border font-bold">
                        切片方式
                      </td>
                      <td className="border">
                        <EditableCell
                          value={data.slicePerRow}
                          onChange={(v) => updateField('slicePerRow', v)}
                        />
                      </td>
                      <td className="border">PCS/排</td>
                      <td colSpan={2} className="border">
                        <EditableCell
                          value={data.slicePerRoll}
                          onChange={(v) => updateField('slicePerRoll', v)}
                        />
                      </td>
                      <td colSpan={2} className="border">
                        PCS/卷
                      </td>
                    </>
                  ) : index === 5 ? (
                    <>
                      <td className="border">厂商</td>
                      <td className="border">
                        <EditableCell
                          value={data.adhesiveManufacturer}
                          onChange={(v) => updateField('adhesiveManufacturer', v)}
                        />
                      </td>
                      <td className="border">
                        <EditableCell
                          value={data.slicePerBundle}
                          onChange={(v) => updateField('slicePerBundle', v)}
                        />
                      </td>
                      <td className="border">PCS/袋</td>
                      <td colSpan={2} className="border">
                        <EditableCell
                          value={data.slicePerBag}
                          onChange={(v) => updateField('slicePerBag', v)}
                        />
                      </td>
                      <td colSpan={2} className="border">
                        PCS/扎
                      </td>
                    </>
                  ) : (
                    <>
                      <td className="border">{tc('specification')}</td>
                      <td className="border">
                        <EditableCell
                          value={data.adhesiveSpecs}
                          onChange={(v) => updateField('adhesiveSpecs', v)}
                        />
                      </td>
                      <td className="border">
                        <EditableCell
                          value={data.slicePerBox}
                          onChange={(v) => updateField('slicePerBox', v)}
                        />
                      </td>
                      <td className="border">PCS/箱</td>
                      <td colSpan={2} className="border">
                        <EditableCell
                          value={data.packingQty}
                          onChange={(v) => updateField('packingQty', v)}
                        />
                      </td>
                      <td colSpan={2} className="border">
                        PCS/袋
                      </td>
                    </>
                  )}
                </tr>
              ))}

              {/* 专色配比/离型纸/刀模行 */}
              <tr>
                <td rowSpan={3} className="border text-center font-bold">
                  专色配比
                </td>
                <td rowSpan={3} colSpan={8} className="border">
                  <EditableTextarea
                    value={data.colorFormula}
                    onChange={(v) => updateField('colorFormula', v)}
                    placeholder="专色配比"
                  />
                </td>
                <td colSpan={2} className="border">
                  离型纸
                </td>
                <td colSpan={2} className="border">
                  背刀刀模
                </td>
                <td colSpan={2} className="border">
                  <EditableCell
                    value={data.backKnifeMold}
                    onChange={(v) => updateField('backKnifeMold', v)}
                  />
                </td>
                <td colSpan={2} className="border">
                  <EditableCell
                    value={data.releasePaperCategory}
                    onChange={(v) => updateField('releasePaperCategory', v)}
                  />
                </td>
                <td colSpan={2} className="border">
                  PCS/箱
                </td>
              </tr>
              <tr>
                <td className="border">种类</td>
                <td className="border">
                  <EditableCell
                    value={data.releasePaperType}
                    onChange={(v) => updateField('releasePaperType', v)}
                  />
                </td>
                <td colSpan={2} className="border">
                  腐蚀刀模
                </td>
                <td colSpan={2} className="border">
                  <EditableCell
                    value={data.etchMold}
                    onChange={(v) => updateField('etchMold', v)}
                  />
                </td>
                <td colSpan={2} className="border">
                  垫纸材料
                </td>
                <td colSpan={2} className="border">
                  <EditableCell
                    value={data.paddingMaterial}
                    onChange={(v) => updateField('paddingMaterial', v)}
                  />
                </td>
              </tr>
              <tr>
                <td className="border">{tc('specification')}</td>
                <td className="border">
                  <EditableCell
                    value={data.releasePaperSpecs}
                    onChange={(v) => updateField('releasePaperSpecs', v)}
                  />
                </td>
                <td colSpan={2} className="border">
                  腐蚀刀模
                </td>
                <td colSpan={2} className="border">
                  <EditableCell
                    value={data.extraField}
                    onChange={(v) => updateField('extraField', v)}
                  />
                </td>
                <td colSpan={2} className="border">
                  打包材料
                </td>
                <td colSpan={2} className="border">
                  <EditableCell
                    value={data.packingMaterial}
                    onChange={(v) => updateField('packingMaterial', v)}
                  />
                </td>
              </tr>

              {/* 电脑图档/样品/注意事项 */}
              <tr>
                <td colSpan={3} className="border">
                  电脑图档存储路径
                </td>
                <td colSpan={8} className="border">
                  <EditableCell
                    value={data.filePath}
                    onChange={(v) => updateField('filePath', v)}
                  />
                </td>
                <td rowSpan={2} colSpan={8} className="border align-top">
                  <div className="text-left p-1">
                    <span className="font-bold text-xs">注意事项：</span>
                    <EditableTextarea
                      value={data.notes}
                      onChange={(v) => updateField('notes', v)}
                      placeholder="输入注意事项"
                      className="mt-1"
                      rows={3}
                    />
                  </div>
                </td>
              </tr>
              <tr>
                <td className="border text-center font-bold">样品</td>
                <td colSpan={10} className="border">
                  <EditableCell
                    value={data.sampleInfo}
                    onChange={(v) => updateField('sampleInfo', v)}
                  />
                </td>
              </tr>

              {/* 审批行 */}
              <tr>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">制表</td>
                <td colSpan={2} className="border font-bold text-center">
                  <EditableCell value={data.creator} onChange={(v) => updateField('creator', v)} />
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">
                  {tc('review')}
                </td>
                <td className="border">
                  <EditableCell
                    value={data.reviewer}
                    onChange={(v) => updateField('reviewer', v)}
                  />
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">厂务</td>
                <td colSpan={2} className="border font-bold text-center">
                  <EditableCell
                    value={data.factoryManager}
                    onChange={(v) => updateField('factoryManager', v)}
                  />
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">品管</td>
                <td colSpan={2} className="border font-bold text-center">
                  <EditableCell
                    value={data.qualityManager}
                    onChange={(v) => updateField('qualityManager', v)}
                  />
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">业务</td>
                <td colSpan={3} className="border font-bold text-center">
                  <EditableCell value={data.sales} onChange={(v) => updateField('sales', v)} />
                </td>
                <td className="border bg-gray-50 dark:bg-gray-700 font-bold text-center">核准</td>
                <td colSpan={3} className="border font-bold text-center">
                  <EditableCell
                    value={data.approver}
                    onChange={(v) => updateField('approver', v)}
                  />
                </td>
              </tr>
            </tbody>
          </table>
        </div>

        {/* 底部编号 — 移至页面最底部 */}
        <div className="mt-2 flex items-center">
          <span className="font-bold text-sm mr-2">编号：</span>
          <EditableCell
            value={data.documentCode}
            onChange={(v) => updateField('documentCode', v)}
            className="flex-1 border-b border-black dark:border-gray-400 min-w-[200px]"
          />
        </div>
      </div>
    </MainLayout>
  );
}

function Loading() {
  return (
    <MainLayout>
      <div className="flex items-center justify-center min-h-screen bg-background">
        <div className="flex flex-col items-center gap-4">
          <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin" />
          <p className="text-muted-foreground">加载中...</p>
        </div>
      </div>
    </MainLayout>
  );
}

export default function InputCardPage() {
  return (
    <Suspense fallback={<Loading />}>
      <InputCardPageContent />
    </Suspense>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { authFetch } from '@/lib/auth-fetch';
import { MainLayout } from '@/components/layout';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { SAMPLE_CARD_STATUS_LABEL } from '@/lib/status-labels';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogAction,
  AlertDialogCancel,
} from '@/components/ui/alert-dialog';
import {
  Plus,
  Trash2,
  Save,
  Send,
  ArrowLeft,
  DollarSign,
  Clock,
  Wrench,
  Package,
  Image as ImageIcon,
  Library,
} from 'lucide-react';
import { useSampleProcessForm } from '@/hooks/useSampleProcessForm';
import { useToast } from '@/hooks/use-toast';

interface Customer {
  id: number;
  customer_code: string;
  customer_name: string;
}
interface Material {
  id: number;
  material_code: string;
  material_name: string;
  specification: string;
  unit: string;
  cost_price: number;
}
interface InkColor {
  id: number;
  color_code: string;
  color_name: string;
}
interface Tool {
  id: number;
  tool_code: string;
  tool_name: string;
  tool_type: number;
  status: number;
  total_life: number;
  remain_life: number;
}
interface ProcessStep {
  id: number;
  step_name: string;
  standard_time: number;
}

const STATUS_MAP: Record<
  number,
  { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline' }
> = {
  1: { label: SAMPLE_CARD_STATUS_LABEL[1], variant: 'secondary' },
  2: { label: SAMPLE_CARD_STATUS_LABEL[2], variant: 'default' },
  3: { label: SAMPLE_CARD_STATUS_LABEL[3], variant: 'default' },
  4: { label: SAMPLE_CARD_STATUS_LABEL[4], variant: 'outline' },
};

export default function SampleCardInputV2Page() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const cardId = searchParams.get('id') ? Number(searchParams.get('id')) : undefined;
  const form = useSampleProcessForm(cardId);

  const [customers, setCustomers] = useState<Customer[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [inkColors, setInkColors] = useState<InkColor[]>([]);
  const [tools, setTools] = useState<Tool[]>([]);
  const [processSteps, setProcessSteps] = useState<ProcessStep[]>([]);
  const [materialSearch, setMaterialSearch] = useState<Record<number, string>>({});
  const [pendingTool, setPendingTool] = useState<{
    field: 'die_tool_id' | 'screen_plate_id';
    toolId: number;
    toolName: string;
    remainLife: number;
    totalLife: number;
  } | null>(null);

  const { toast } = useToast();
  const [templateDialogOpen, setTemplateDialogOpen] = useState(false);
  const [templates, setTemplates] = useState<
    Array<{
      id: number;
      template_no: string;
      template_name: string;
      category: string | null;
      total_cost: number;
    }>
  >([]);
  const [templateLoading, setTemplateLoading] = useState(false);

  const fetchTemplates = useCallback(async () => {
    setTemplateLoading(true);
    try {
      const res = await authFetch('/api/dcprint/sample-card/template?page=1&pageSize=50');
      const result = await res.json();
      if (result.success) {
        setTemplates(result.data.list || []);
      }
    } catch {
      // ignore
    } finally {
      setTemplateLoading(false);
    }
  }, []);

  const handleOpenTemplateDialog = () => {
    fetchTemplates();
    setTemplateDialogOpen(true);
  };

  const handleImportFromTemplate = async (templateId: number) => {
    if (!confirm('导入将覆盖当前表单内容，确定继续？')) return;
    try {
      await form.importFromTemplate(templateId);
      toast({ title: '模板已导入', description: '表单内容已更新' });
      setTemplateDialogOpen(false);
    } catch {
      toast({ title: '导入失败', variant: 'destructive' });
    }
  };

  // 加载参考数据
  useEffect(() => {
    (async () => {
      try {
        const [custRes, matRes, inkRes, toolRes, procRes] = await Promise.all([
          authFetch('/api/customers?page=1&pageSize=999'),
          authFetch('/api/inventory/materials?page=1&pageSize=999'),
          authFetch('/api/dcprint/formula/color?page=1&pageSize=999'),
          authFetch('/api/dcprint/tool?page=1&pageSize=999'),
          authFetch('/api/production/process-route?page=1&pageSize=999'),
        ]);
        const [cust, mat, ink, tool, proc] = await Promise.all([
          custRes.json(),
          matRes.json(),
          inkRes.json(),
          toolRes.json(),
          procRes.json(),
        ]);
        if (cust.success) setCustomers(cust.data.list || []);
        if (mat.success) setMaterials(mat.data.list || []);
        if (ink.success) setInkColors(ink.data.list || []);
        if (tool.success) setTools(tool.data.list || []);
        if (proc.success) setProcessSteps(proc.data.list || []);
      } catch {
        // ignore
      }
    })();
  }, []);

  // 客户选择
  const handleCustomerChange = useCallback(
    (value: string) => {
      const customer = customers.find((c) => c.id === Number(value));
      if (customer) {
        form.updateField('customer_id', customer.id);
        form.updateField('customer_name', customer.customer_name);
      }
    },
    [customers, form]
  );

  // 基材选择
  const handleSubstrateChange = useCallback(
    (value: string) => {
      const mat = materials.find((m) => m.id === Number(value));
      if (mat) {
        form.updateField('substrate_material_id', mat.id);
        form.updateField('substrate_material_name', mat.material_name);
        form.updateField('spec', mat.specification || '');
      }
    },
    [materials, form]
  );

  // 物料搜索
  const handleMaterialSearch = useCallback((index: number, keyword: string) => {
    setMaterialSearch((prev) => ({ ...prev, [index]: keyword }));
  }, []);

  const handleMaterialSelect = useCallback(
    (index: number, material: Material) => {
      form.updateItem(index, {
        material_id: material.id,
        material_code: material.material_code,
        material_name: material.material_name,
        specification: material.specification || '',
        unit: material.unit || '',
        unit_cost: material.cost_price || 0,
      });
      setMaterialSearch((prev) => ({ ...prev, [index]: '' }));
    },
    [form]
  );

  // 工序选择
  const handleProcessSelect = useCallback(
    (index: number, value: string) => {
      const step = processSteps.find((s) => s.id === Number(value));
      if (step) {
        form.updateStep(index, {
          process_id: step.id,
          process_name: step.step_name,
          work_hour: step.standard_time || 0,
        });
      }
    },
    [processSteps, form]
  );

  // 保存
  const handleSave = async () => {
    const id = await form.saveDraft();
    if (id && !cardId) {
      router.push(`/sample/standard-card/input-v2?id=${id}`);
    }
  };

  // 提交
  const handleSubmit = async () => {
    const result = await form.submit();
    if (result.success) {
      router.push('/sample/standard-card');
    }
  };

  const dieTools = tools.filter((t) => t.tool_type === 1 && [2, 4].includes(t.status));
  const screenTools = tools.filter((t) => t.tool_type === 2 && [2, 4].includes(t.status));

  const isRedWarning = (t: Tool) =>
    t.status === 4 && t.total_life > 0 && t.remain_life <= t.total_life * 0.05;

  const handleToolSelect = (field: 'die_tool_id' | 'screen_plate_id', toolId: number) => {
    const tool = tools.find((t) => t.id === toolId);
    if (!tool) return;
    if (isRedWarning(tool)) {
      setPendingTool({
        field,
        toolId,
        toolName: `${tool.tool_code} - ${tool.tool_name}`,
        remainLife: tool.remain_life,
        totalLife: tool.total_life,
      });
      return;
    }
    form.updateField(field, toolId);
  };

  const confirmPendingTool = () => {
    if (!pendingTool) return;
    form.updateField(pendingTool.field, pendingTool.toolId);
    toast({
      title: '已引用红色预警工装',
      description: `${pendingTool.toolName}（剩余寿命 ${pendingTool.remainLife}/${pendingTool.totalLife}）`,
      variant: 'destructive',
    });
    setPendingTool(null);
  };
  const filteredMaterials = (keyword: string) =>
    !keyword
      ? materials.slice(0, 10)
      : materials
          .filter(
            (m) =>
              m.material_code.toLowerCase().includes(keyword.toLowerCase()) ||
              m.material_name.toLowerCase().includes(keyword.toLowerCase())
          )
          .slice(0, 10);

  const isReadonly = !!(form.formData.status && form.formData.status > 1);

  return (
    <MainLayout>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={() => router.push('/sample/standard-card')}>
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <h1 className="text-xl font-bold">
            {isReadonly ? '查看工艺卡' : cardId ? '编辑工艺卡' : '新建工艺卡'}
          </h1>
          {form.formData.sample_no && <Badge variant="outline">{form.formData.sample_no}</Badge>}
          {form.formData.status && STATUS_MAP[form.formData.status] && (
            <Badge variant={STATUS_MAP[form.formData.status].variant}>
              {STATUS_MAP[form.formData.status].label}
            </Badge>
          )}
        </div>
        <div className="flex gap-2">
          {!isReadonly && (
            <>
              <Button variant="outline" onClick={handleOpenTemplateDialog}>
                <Library className="h-4 w-4 mr-1" />
                从模板导入
              </Button>
              <Button variant="outline" onClick={handleSave} disabled={form.saving}>
                <Save className="h-4 w-4 mr-1" />
                保存草稿
              </Button>
              <Button onClick={handleSubmit} disabled={form.saving}>
                <Send className="h-4 w-4 mr-1" />
                提交
              </Button>
            </>
          )}
        </div>
      </div>

      {form.validationErrors.length > 0 && (
        <Card className="mb-4 border-red-300 bg-red-50">
          <CardContent className="py-3">
            <p className="font-semibold text-red-700 mb-1">{'填写须知'}</p>
            <ul className="text-sm text-red-600 list-disc list-inside">
              {form.validationErrors.map((err, i) => (
                <li key={i}>{err}</li>
              ))}
            </ul>
          </CardContent>
        </Card>
      )}

      <div className="flex gap-4">
        {/* 左侧表单区 */}
        <div className="flex-1 space-y-4">
          {/* 基础信息 */}
          <Card>
            <CardHeader>
              <CardTitle>基础信息</CardTitle>
            </CardHeader>
            <CardContent className="grid grid-cols-3 gap-4">
              <div className="space-y-1">
                <Label>
                  {'工艺卡名称'}
                  <span className="text-red-500">*</span>
                </Label>
                <Input
                  value={form.formData.sample_name || ''}
                  onChange={(e) => form.updateField('sample_name', e.target.value)}
                  disabled={isReadonly}
                />
              </div>
              <div className="space-y-1">
                <Label>客户</Label>
                <Select
                  value={form.formData.customer_id ? String(form.formData.customer_id) : ''}
                  onValueChange={handleCustomerChange}
                  disabled={isReadonly}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="选择客户" />
                  </SelectTrigger>
                  <SelectContent>
                    {customers.map((c) => (
                      <SelectItem key={c.id} value={String(c.id)}>
                        {c.customer_name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <Label>产品名称</Label>
                <Input
                  value={form.formData.product_name || ''}
                  onChange={(e) => form.updateField('product_name', e.target.value)}
                  disabled={isReadonly}
                />
              </div>
              <div className="space-y-1">
                <Label>基材</Label>
                <Select
                  value={
                    form.formData.substrate_material_id
                      ? String(form.formData.substrate_material_id)
                      : ''
                  }
                  onValueChange={handleSubstrateChange}
                  disabled={isReadonly}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="选择基材" />
                  </SelectTrigger>
                  <SelectContent>
                    {materials.map((m) => (
                      <SelectItem key={m.id} value={String(m.id)}>
                        {m.material_name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <Label>规格</Label>
                <Input
                  value={form.formData.spec || ''}
                  onChange={(e) => form.updateField('spec', e.target.value)}
                  disabled={isReadonly}
                />
              </div>
              <div className="space-y-1">
                <Label>印刷颜色</Label>
                <Input
                  value={form.formData.print_color || ''}
                  onChange={(e) => form.updateField('print_color', e.target.value)}
                  disabled={isReadonly}
                />
              </div>
              <div className="space-y-1">
                <Label>油墨色号</Label>
                <Select
                  value={form.formData.ink_color_id ? String(form.formData.ink_color_id) : ''}
                  onValueChange={(v) => form.updateField('ink_color_id', Number(v))}
                  disabled={isReadonly}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="选择色号" />
                  </SelectTrigger>
                  <SelectContent>
                    {inkColors.map((c) => (
                      <SelectItem key={c.id} value={String(c.id)}>
                        {c.color_code} - {c.color_name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <Label>刀模</Label>
                <Select
                  value={form.formData.die_tool_id ? String(form.formData.die_tool_id) : ''}
                  onValueChange={(v) => handleToolSelect('die_tool_id', Number(v))}
                  disabled={isReadonly}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="选择刀模" />
                  </SelectTrigger>
                  <SelectContent>
                    {dieTools.map((t) => (
                      <SelectItem key={t.id} value={String(t.id)}>
                        {t.tool_code} - {t.tool_name}
                        {t.status === 4 && (
                          <span
                            className={
                              isRedWarning(t) ? 'text-red-600 font-bold' : 'text-yellow-600'
                            }
                          >
                            {isRedWarning(t) ? ' 红色预警' : ' 预警'}（剩余 {t.remain_life}/
                            {t.total_life}）
                          </span>
                        )}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <Label>网版</Label>
                <Select
                  value={form.formData.screen_plate_id ? String(form.formData.screen_plate_id) : ''}
                  onValueChange={(v) => handleToolSelect('screen_plate_id', Number(v))}
                  disabled={isReadonly}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="选择网版" />
                  </SelectTrigger>
                  <SelectContent>
                    {screenTools.map((t) => (
                      <SelectItem key={t.id} value={String(t.id)}>
                        {t.tool_code} - {t.tool_name}
                        {t.status === 4 && (
                          <span
                            className={
                              isRedWarning(t) ? 'text-red-600 font-bold' : 'text-yellow-600'
                            }
                          >
                            {isRedWarning(t) ? ' 红色预警' : ' 预警'}（剩余 {t.remain_life}/
                            {t.total_life}）
                          </span>
                        )}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <Label>损耗率(%)</Label>
                <Input
                  type="number"
                  value={form.formData.material_loss_rate ?? 5}
                  onChange={(e) => form.updateField('material_loss_rate', Number(e.target.value))}
                  disabled={isReadonly}
                />
              </div>
              <div className="space-y-1">
                <Label>预估工时</Label>
                <Input
                  type="number"
                  value={form.formData.estimated_hour ?? ''}
                  onChange={(e) =>
                    form.updateField(
                      'estimated_hour',
                      e.target.value ? Number(e.target.value) : undefined
                    )
                  }
                  disabled={isReadonly}
                />
              </div>
              <div className="space-y-1">
                <Label>版本号</Label>
                <Input value={form.formData.version_no || 'V1.0'} disabled />
              </div>
            </CardContent>
          </Card>

          {/* 工艺图示（图文混排） */}
          <Card>
            <CardHeader>
              <CardTitle>工艺图示</CardTitle>
            </CardHeader>
            <CardContent>
              {form.formData.diagram_url ? (
                <div className="space-y-2">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img
                    src={form.formData.diagram_url}
                    alt="工艺图示"
                    className="max-w-md rounded border"
                  />
                  {!isReadonly && (
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => form.updateField('diagram_url', '')}
                    >
                      <Trash2 className="h-4 w-4 mr-1" />
                      移除图示
                    </Button>
                  )}
                </div>
              ) : (
                !isReadonly && (
                  <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-dashed border-gray-300 rounded cursor-pointer hover:bg-gray-50">
                    <div className="flex flex-col items-center gap-2 text-gray-500">
                      <ImageIcon className="h-8 w-8" />
                      <span className="text-sm">点击上传工艺简图</span>
                      <span className="text-xs text-gray-400">
                        支持 jpg/png/gif/webp/svg，最大 10MB
                      </span>
                    </div>
                    <input
                      type="file"
                      className="hidden"
                      accept="image/jpeg,image/png,image/gif,image/webp,image/svg+xml"
                      onChange={async (e) => {
                        const file = e.target.files?.[0];
                        if (file) await form.uploadDiagram(file);
                      }}
                    />
                  </label>
                )
              )}
            </CardContent>
          </Card>

          {/* 物料明细 */}
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle>物料明细</CardTitle>
                {!isReadonly && (
                  <Button size="sm" variant="outline" onClick={form.addItem}>
                    <Plus className="h-4 w-4 mr-1" />
                    {'添加物料'}
                  </Button>
                )}
              </div>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="w-16">类型</TableHead>
                    <TableHead>物料编码</TableHead>
                    <TableHead>物料名称</TableHead>
                    <TableHead className="w-20">单耗</TableHead>
                    <TableHead className="w-20">单位</TableHead>
                    <TableHead className="w-24">单价</TableHead>
                    <TableHead className="w-24">{'金额'}</TableHead>
                    {!isReadonly && <TableHead className="w-12"></TableHead>}
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {form.formData.items.map((item, index) => (
                    <TableRow key={index}>
                      <TableCell>
                        <Select
                          value={String(item.item_type || 1)}
                          onValueChange={(v) => form.updateItem(index, { item_type: Number(v) })}
                          disabled={isReadonly}
                        >
                          <SelectTrigger className="h-8">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="1">主料</SelectItem>
                            <SelectItem value="2">油墨</SelectItem>
                            <SelectItem value="3">辅料</SelectItem>
                          </SelectContent>
                        </Select>
                      </TableCell>
                      <TableCell>
                        <div className="relative">
                          <Input
                            className="h-8"
                            placeholder="搜索物料..."
                            value={materialSearch[index] ?? item.material_code}
                            onChange={(e) => {
                              handleMaterialSearch(index, e.target.value);
                              form.updateItem(index, { material_code: e.target.value });
                            }}
                            disabled={isReadonly}
                          />
                          {materialSearch[index] &&
                            filteredMaterials(materialSearch[index]).length > 0 && (
                              <div className="absolute z-50 mt-1 w-full bg-white border rounded shadow-lg max-h-48 overflow-auto">
                                {filteredMaterials(materialSearch[index]).map((m) => (
                                  <button
                                    key={m.id}
                                    className="w-full text-left px-2 py-1 hover:bg-gray-100 text-sm"
                                    onClick={() => handleMaterialSelect(index, m)}
                                  >
                                    {m.material_code} - {m.material_name} (¥{m.cost_price}/{m.unit})
                                  </button>
                                ))}
                              </div>
                            )}
                        </div>
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          value={item.material_name || ''}
                          onChange={(e) =>
                            form.updateItem(index, { material_name: e.target.value })
                          }
                          disabled={isReadonly}
                        />
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          type="number"
                          value={item.unit_dosage || 0}
                          onChange={(e) =>
                            form.updateItem(index, { unit_dosage: Number(e.target.value) })
                          }
                          disabled={isReadonly}
                        />
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          value={item.unit || ''}
                          onChange={(e) => form.updateItem(index, { unit: e.target.value })}
                          disabled={isReadonly}
                        />
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          type="number"
                          value={item.unit_cost || 0}
                          onChange={(e) =>
                            form.updateItem(index, { unit_cost: Number(e.target.value) })
                          }
                          disabled={isReadonly}
                        />
                      </TableCell>
                      <TableCell className="font-mono text-sm">
                        ¥{(item.line_cost || 0).toFixed(2)}
                      </TableCell>
                      {!isReadonly && (
                        <TableCell>
                          <Button
                            size="icon"
                            variant="ghost"
                            onClick={() => form.removeItem(index)}
                          >
                            <Trash2 className="h-3 w-3 text-red-500" />
                          </Button>
                        </TableCell>
                      )}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>

          {/* 工序路线 */}
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle>工序路线</CardTitle>
                {!isReadonly && (
                  <Button size="sm" variant="outline" onClick={form.addStep}>
                    <Plus className="h-4 w-4 mr-1" />
                    添加工序
                  </Button>
                )}
              </div>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="w-16">序号</TableHead>
                    <TableHead>工序名称</TableHead>
                    <TableHead className="w-24">工时</TableHead>
                    <TableHead className="w-24">{'时薪'}</TableHead>
                    <TableHead className="w-24">{'金额'}</TableHead>
                    <TableHead>{'备注'}</TableHead>
                    {!isReadonly && <TableHead className="w-12"></TableHead>}
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {form.formData.steps.map((step, index) => (
                    <TableRow key={index}>
                      <TableCell className="text-center">{index + 1}</TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          <Select
                            value={step.process_id ? String(step.process_id) : ''}
                            onValueChange={(v) => handleProcessSelect(index, v)}
                            disabled={isReadonly}
                          >
                            <SelectTrigger className="h-8 w-40">
                              <SelectValue placeholder="选择标准工序" />
                            </SelectTrigger>
                            <SelectContent>
                              {processSteps.map((s) => (
                                <SelectItem key={s.id} value={String(s.id)}>
                                  {s.step_name}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                          <Input
                            className="h-8 flex-1"
                            value={step.process_name || ''}
                            onChange={(e) =>
                              form.updateStep(index, { process_name: e.target.value })
                            }
                            disabled={isReadonly}
                          />
                        </div>
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          type="number"
                          value={step.work_hour || 0}
                          onChange={(e) =>
                            form.updateStep(index, { work_hour: Number(e.target.value) })
                          }
                          disabled={isReadonly}
                        />
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          type="number"
                          value={step.hourly_rate || 0}
                          onChange={(e) =>
                            form.updateStep(index, { hourly_rate: Number(e.target.value) })
                          }
                          disabled={isReadonly}
                        />
                      </TableCell>
                      <TableCell className="font-mono text-sm">
                        ¥{(step.line_cost || 0).toFixed(2)}
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          value={step.process_param || ''}
                          onChange={(e) =>
                            form.updateStep(index, { process_param: e.target.value })
                          }
                          disabled={isReadonly}
                        />
                      </TableCell>
                      {!isReadonly && (
                        <TableCell>
                          <Button
                            size="icon"
                            variant="ghost"
                            onClick={() => form.removeStep(index)}
                          >
                            <Trash2 className="h-3 w-3 text-red-500" />
                          </Button>
                        </TableCell>
                      )}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>

          {/* 备注 */}
          <Card>
            <CardHeader>
              <CardTitle>备注</CardTitle>
            </CardHeader>
            <CardContent>
              <Textarea
                value={form.formData.remark || ''}
                onChange={(e) => form.updateField('remark', e.target.value)}
                rows={3}
                disabled={isReadonly}
              />
            </CardContent>
          </Card>
        </div>

        {/* 右侧实时成本栏 */}
        <div className="w-72 shrink-0">
          <div className="sticky top-4 space-y-3">
            <Card>
              <CardHeader>
                <CardTitle className="text-base">{'工艺路线'}</CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-gray-600 flex items-center gap-1">
                    <Package className="h-4 w-4" />
                    物料成本
                  </span>
                  <span className="font-mono">¥{form.cost.materialCost.toFixed(2)}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm text-gray-600 flex items-center gap-1">
                    <Clock className="h-4 w-4" />
                    人工成本
                  </span>
                  <span className="font-mono">¥{form.cost.laborCost.toFixed(2)}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm text-gray-600 flex items-center gap-1">
                    <Wrench className="h-4 w-4" />
                    工装成本
                  </span>
                  <span className="font-mono">¥{form.cost.toolCost.toFixed(2)}</span>
                </div>
                <div className="border-t pt-3">
                  <div className="flex items-center justify-between">
                    <span className="font-semibold flex items-center gap-1">
                      <DollarSign className="h-5 w-5" />
                      总成本
                    </span>
                    <span className="font-mono text-xl font-bold text-blue-600">
                      ¥{form.cost.totalCost.toFixed(2)}
                    </span>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>

      <Dialog open={templateDialogOpen} onOpenChange={setTemplateDialogOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>从模板导入</DialogTitle>
          </DialogHeader>
          <div className="max-h-96 overflow-y-auto">
            {templateLoading ? (
              <p className="text-center text-gray-400 py-8">加载中...</p>
            ) : templates.length === 0 ? (
              <p className="text-center text-gray-400 py-8">
                暂无模板，请先在已确认工艺卡中「存为模板」
              </p>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>模板编号</TableHead>
                    <TableHead>模板名称</TableHead>
                    <TableHead>分类</TableHead>
                    <TableHead className="text-right">总成本</TableHead>
                    <TableHead className="text-center">操作</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {templates.map((t) => (
                    <TableRow key={t.id}>
                      <TableCell className="font-mono text-sm">{t.template_no}</TableCell>
                      <TableCell className="font-medium">{t.template_name}</TableCell>
                      <TableCell>{t.category || '-'}</TableCell>
                      <TableCell className="text-right font-mono">
                        ¥{(t.total_cost || 0).toFixed(2)}
                      </TableCell>
                      <TableCell className="text-center">
                        <Button size="sm" onClick={() => handleImportFromTemplate(t.id)}>
                          选用
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setTemplateDialogOpen(false)}>
              取消
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog
        open={pendingTool !== null}
        onOpenChange={(open) => {
          if (!open) setPendingTool(null);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>红色预警工装引用确认</AlertDialogTitle>
            <AlertDialogDescription>
              {pendingTool && (
                <>
                  工装 <strong>{pendingTool.toolName}</strong> 已进入红色预警状态， 剩余寿命仅{' '}
                  {pendingTool.remainLife} / {pendingTool.totalLife} 次。
                  <br />
                  继续引用可能导致生产中断或质量风险，请确认是否仍要引用此工装。
                </>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setPendingTool(null)}>取消</AlertDialogCancel>
            <AlertDialogAction onClick={confirmPendingTool}>确认引用</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </MainLayout>
  );
}

'use client';

/**
 * 打样工艺卡 — 经典向导式录入页（4 步）
 *
 * 与 input-v2（高效版）共用 useSampleProcessForm Hook 与 Zod 校验 Schema，
 * 保证数据模型、字段、参考数据加载、保存/提交逻辑 100% 一致。
 *
 * 步骤：
 *   1. 基础信息
 *   2. 物料明细
 *   3. 工序路线
 *   4. 成本确认与提交
 */
import { useEffect, useState, useCallback } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { authFetch } from '@/lib/auth-fetch';
import { MainLayout } from '@/components/layout';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { SAMPLE_CARD_STATUS_LABEL } from '@/lib/status-labels';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogAction,
  AlertDialogCancel,
} from '@/components/ui/alert-dialog';
import {
  Plus,
  Trash2,
  Save,
  Send,
  ArrowLeft,
  ArrowRight,
  DollarSign,
  Clock,
  Wrench,
  Package,
  Check,
  Image as ImageIcon,
  Library,
} from 'lucide-react';
import { useSampleProcessForm } from '@/hooks/useSampleProcessForm';
import { useToast } from '@/hooks/use-toast';

interface Customer {
  id: number;
  customer_code: string;
  customer_name: string;
}
interface Material {
  id: number;
  material_code: string;
  material_name: string;
  specification: string;
  unit: string;
  cost_price: number;
}
interface InkColor {
  id: number;
  color_code: string;
  color_name: string;
}
interface Tool {
  id: number;
  tool_code: string;
  tool_name: string;
  tool_type: number;
  status: number;
  total_life: number;
  remain_life: number;
}
interface ProcessStep {
  id: number;
  step_name: string;
  standard_time: number;
}

const STATUS_MAP: Record<
  number,
  { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline' }
> = {
  1: { label: SAMPLE_CARD_STATUS_LABEL[1], variant: 'secondary' },
  2: { label: SAMPLE_CARD_STATUS_LABEL[2], variant: 'default' },
  3: { label: SAMPLE_CARD_STATUS_LABEL[3], variant: 'default' },
  4: { label: SAMPLE_CARD_STATUS_LABEL[4], variant: 'outline' },
};

const STEPS = [
  { id: 1, label: '基础信息' },
  { id: 2, label: '物料明细' },
  { id: 3, label: '工序路线' },
  { id: 4, label: '成本确认与提交' },
];

export default function SampleCardInputPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const cardId = searchParams.get('id') ? Number(searchParams.get('id')) : undefined;
  const form = useSampleProcessForm(cardId);

  const [currentStep, setCurrentStep] = useState(1);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [inkColors, setInkColors] = useState<InkColor[]>([]);
  const [tools, setTools] = useState<Tool[]>([]);
  const [processSteps, setProcessSteps] = useState<ProcessStep[]>([]);
  const [stepErrors, setStepErrors] = useState<Record<string, string>>({});
  const [pendingTool, setPendingTool] = useState<{
    field: 'die_tool_id' | 'screen_plate_id';
    toolId: number;
    toolName: string;
    remainLife: number;
    totalLife: number;
  } | null>(null);

  const { toast } = useToast();
  const [templateDialogOpen, setTemplateDialogOpen] = useState(false);
  const [templates, setTemplates] = useState<
    Array<{
      id: number;
      template_no: string;
      template_name: string;
      category: string | null;
      total_cost: number;
    }>
  >([]);
  const [templateLoading, setTemplateLoading] = useState(false);

  const fetchTemplates = useCallback(async () => {
    setTemplateLoading(true);
    try {
      const res = await authFetch('/api/dcprint/sample-card/template?page=1&pageSize=50');
      const result = await res.json();
      if (result.success) {
        setTemplates(result.data.list || []);
      }
    } catch {
      // ignore
    } finally {
      setTemplateLoading(false);
    }
  }, []);

  const handleOpenTemplateDialog = () => {
    fetchTemplates();
    setTemplateDialogOpen(true);
  };

  const handleImportFromTemplate = async (templateId: number) => {
    if (!confirm('导入将覆盖当前表单内容，确定继续？')) return;
    try {
      await form.importFromTemplate(templateId);
      toast({ title: '模板已导入', description: '表单内容已更新' });
      setTemplateDialogOpen(false);
    } catch {
      toast({ title: '导入失败', variant: 'destructive' });
    }
  };

  // 只读模式：状态 > 1（打样中/已确认/已作废）时所有字段禁用
  const isReadonly = !!(form.formData.status && form.formData.status > 1);

  // 加载参考数据（与 v2 一致）
  useEffect(() => {
    (async () => {
      try {
        const [custRes, matRes, inkRes, toolRes, procRes] = await Promise.all([
          authFetch('/api/customers?page=1&pageSize=999'),
          authFetch('/api/inventory/materials?page=1&pageSize=999'),
          authFetch('/api/dcprint/formula/color?page=1&pageSize=999'),
          authFetch('/api/dcprint/tool?page=1&pageSize=999'),
          authFetch('/api/production/process-route?page=1&pageSize=999'),
        ]);
        const [cust, mat, ink, tool, proc] = await Promise.all([
          custRes.json(),
          matRes.json(),
          inkRes.json(),
          toolRes.json(),
          procRes.json(),
        ]);
        if (cust.success) setCustomers(cust.data.list || []);
        if (mat.success) setMaterials(mat.data.list || []);
        if (ink.success) setInkColors(ink.data.list || []);
        if (tool.success) setTools(tool.data.list || []);
        if (proc.success) setProcessSteps(proc.data.list || []);
      } catch {
        // ignore
      }
    })();
  }, []);

  // 客户选择
  const handleCustomerChange = useCallback(
    (value: string) => {
      const customer = customers.find((c) => c.id === Number(value));
      if (customer) {
        form.updateField('customer_id', customer.id);
        form.updateField('customer_name', customer.customer_name);
      }
    },
    [customers, form]
  );

  // 基材选择
  const handleSubstrateChange = useCallback(
    (value: string) => {
      const mat = materials.find((m) => m.id === Number(value));
      if (mat) {
        form.updateField('substrate_material_id', mat.id);
        form.updateField('substrate_material_name', mat.material_name);
        form.updateField('spec', mat.specification || '');
      }
    },
    [materials, form]
  );

  // 物料选择（经典版：使用 Select 而非搜索下拉）
  const handleMaterialSelect = useCallback(
    (index: number, value: string) => {
      const mat = materials.find((m) => m.id === Number(value));
      if (mat) {
        form.updateItem(index, {
          material_id: mat.id,
          material_code: mat.material_code,
          material_name: mat.material_name,
          specification: mat.specification || '',
          unit: mat.unit || '',
          unit_cost: mat.cost_price || 0,
        });
      } else {
        form.updateItem(index, {
          material_id: undefined,
          material_code: '',
          material_name: '',
          specification: '',
          unit: '',
          unit_cost: 0,
        });
      }
    },
    [materials, form]
  );

  // 工序选择
  const handleProcessSelect = useCallback(
    (index: number, value: string) => {
      const step = processSteps.find((s) => s.id === Number(value));
      if (step) {
        form.updateStep(index, {
          process_id: step.id,
          process_name: step.step_name,
          work_hour: step.standard_time || 0,
        });
      }
    },
    [processSteps, form]
  );

  // 当前步骤的轻量逐字段校验
  const validateStep = useCallback(
    (step: number): boolean => {
      const errors: Record<string, string> = {};
      if (step === 1) {
        if (!form.formData.sample_name?.trim()) errors.sample_name = '打样名称不能为空';
      } else if (step === 2) {
        form.formData.items.forEach((item, i) => {
          if (!item.material_name?.trim()) errors[`items.${i}.material_name`] = '物料名称不能为空';
          if (!item.material_code?.trim()) errors[`items.${i}.material_code`] = '物料编码不能为空';
          if (!item.unit_dosage || item.unit_dosage <= 0)
            errors[`items.${i}.unit_dosage`] = '单耗必须大于0';
        });
      } else if (step === 3) {
        form.formData.steps.forEach((s, i) => {
          if (!s.process_name?.trim()) errors[`steps.${i}.process_name`] = '工序名称不能为空';
          if (!s.work_hour || s.work_hour <= 0) errors[`steps.${i}.work_hour`] = '工时必须大于0';
        });
      }
      setStepErrors(errors);
      return Object.keys(errors).length === 0;
    },
    [form.formData]
  );

  // 下一步：执行全量校验（刷新 validationErrors 用于展示）+ 当前步骤轻量校验作为闸门
  const handleNext = useCallback(() => {
    if (isReadonly) {
      setCurrentStep((s) => Math.min(s + 1, STEPS.length));
      return;
    }
    form.validate();
    if (validateStep(currentStep)) {
      setStepErrors({});
      setCurrentStep((s) => Math.min(s + 1, STEPS.length));
    }
  }, [currentStep, form, validateStep, isReadonly]);

  // 上一步：始终可用
  const handleBack = useCallback(() => {
    setStepErrors({});
    setCurrentStep((s) => Math.max(s - 1, 1));
  }, []);

  // 保存草稿
  const handleSave = async () => {
    const id = await form.saveDraft();
    if (id && !cardId) {
      router.push(`/sample/standard-card/input?id=${id}`);
    }
  };

  // 提交
  const handleSubmit = async () => {
    if (!form.validate()) return;
    const result = await form.submit();
    if (result.success) {
      router.push('/sample/standard-card');
    }
  };

  const dieTools = tools.filter((t) => t.tool_type === 1 && [2, 4].includes(t.status));
  const screenTools = tools.filter((t) => t.tool_type === 2 && [2, 4].includes(t.status));

  const isRedWarning = (t: Tool) =>
    t.status === 4 && t.total_life > 0 && t.remain_life <= t.total_life * 0.05;

  const handleToolSelect = (field: 'die_tool_id' | 'screen_plate_id', toolId: number) => {
    const tool = tools.find((t) => t.id === toolId);
    if (!tool) return;
    if (isRedWarning(tool)) {
      setPendingTool({
        field,
        toolId,
        toolName: `${tool.tool_code} - ${tool.tool_name}`,
        remainLife: tool.remain_life,
        totalLife: tool.total_life,
      });
      return;
    }
    form.updateField(field, toolId);
  };

  const confirmPendingTool = () => {
    if (!pendingTool) return;
    form.updateField(pendingTool.field, pendingTool.toolId);
    toast({
      title: '已引用红色预警工装',
      description: `${pendingTool.toolName}（剩余寿命 ${pendingTool.remainLife}/${pendingTool.totalLife}）`,
      variant: 'destructive',
    });
    setPendingTool(null);
  };
  const isLastStep = currentStep === STEPS.length;

  // 只读摘要辅助显示
  const customerName =
    form.formData.customer_name ||
    customers.find((c) => c.id === form.formData.customer_id)?.customer_name ||
    '-';
  const substrateName =
    form.formData.substrate_material_name ||
    materials.find((m) => m.id === form.formData.substrate_material_id)?.material_name ||
    '-';
  const inkColor = inkColors.find((c) => c.id === form.formData.ink_color_id);
  const dieTool = dieTools.find((t) => t.id === form.formData.die_tool_id);
  const screenTool = screenTools.find((t) => t.id === form.formData.screen_plate_id);

  return (
    <MainLayout>
      {/* 顶部标题栏 */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={() => router.push('/sample/standard-card')}>
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <h1 className="text-xl font-bold">
            {isReadonly ? '查看工艺卡' : cardId ? '编辑工艺卡' : '新建工艺卡'}
          </h1>
          {form.formData.sample_no && <Badge variant="outline">{form.formData.sample_no}</Badge>}
          {form.formData.status && STATUS_MAP[form.formData.status] && (
            <Badge variant={STATUS_MAP[form.formData.status].variant}>
              {STATUS_MAP[form.formData.status].label}
            </Badge>
          )}
        </div>
        <div className="flex gap-2">
          {!isReadonly && (
            <>
              <Button variant="outline" onClick={handleOpenTemplateDialog}>
                <Library className="h-4 w-4 mr-1" />
                从模板导入
              </Button>
              <Button variant="outline" onClick={handleSave} disabled={form.saving}>
                <Save className="h-4 w-4 mr-1" />
                保存草稿
              </Button>
            </>
          )}
        </div>
      </div>

      {/* 步骤进度条 */}
      <Card className="mb-6">
        <CardContent className="py-4">
          <div className="flex items-center justify-between">
            {STEPS.map((step, idx) => {
              const isCompleted = currentStep > step.id;
              const isCurrent = currentStep === step.id;
              return (
                <div key={step.id} className="flex items-center flex-1 last:flex-none">
                  <div className="flex flex-col items-center gap-1">
                    <div
                      className={`flex h-10 w-10 items-center justify-center rounded-full border-2 transition-colors ${
                        isCompleted
                          ? 'bg-blue-600 border-blue-600 text-white'
                          : isCurrent
                            ? 'border-blue-600 text-blue-600 bg-white'
                            : 'border-gray-300 text-gray-400 bg-white'
                      }`}
                    >
                      {isCompleted ? <Check className="h-5 w-5" /> : step.id}
                    </div>
                    <div
                      className={`text-sm font-medium ${
                        isCurrent
                          ? 'text-blue-600'
                          : isCompleted
                            ? 'text-gray-700'
                            : 'text-gray-400'
                      }`}
                    >
                      {step.label}
                    </div>
                  </div>
                  {idx < STEPS.length - 1 && (
                    <div
                      className={`h-0.5 flex-1 mx-2 mb-5 ${
                        currentStep > step.id ? 'bg-blue-600' : 'bg-gray-200'
                      }`}
                    />
                  )}
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* 全量校验错误展示 */}
      {form.validationErrors.length > 0 && (
        <Card className="mb-4 border-red-300 bg-red-50">
          <CardContent className="py-3">
            <p className="font-semibold text-red-700 mb-1">{'填写须知'}</p>
            <ul className="text-sm text-red-600 list-disc list-inside">
              {form.validationErrors.map((err, i) => (
                <li key={i}>{err}</li>
              ))}
            </ul>
          </CardContent>
        </Card>
      )}

      {/* ============ 步骤 1：基础信息 ============ */}
      {currentStep === 1 && (
        <Card>
          <CardHeader>
            <CardTitle>{'基本信息'}</CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-3 gap-4">
            <div className="space-y-1">
              <Label>
                {'工艺卡名称'}
                <span className="text-red-500">*</span>
              </Label>
              <Input
                value={form.formData.sample_name || ''}
                onChange={(e) => form.updateField('sample_name', e.target.value)}
                disabled={isReadonly}
              />
              {stepErrors.sample_name && (
                <p className="text-xs text-red-500">{stepErrors.sample_name}</p>
              )}
            </div>
            <div className="space-y-1">
              <Label>客户</Label>
              <Select
                value={form.formData.customer_id ? String(form.formData.customer_id) : ''}
                onValueChange={handleCustomerChange}
                disabled={isReadonly}
              >
                <SelectTrigger>
                  <SelectValue placeholder="选择客户" />
                </SelectTrigger>
                <SelectContent>
                  {customers.map((c) => (
                    <SelectItem key={c.id} value={String(c.id)}>
                      {c.customer_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1">
              <Label>产品名称</Label>
              <Input
                value={form.formData.product_name || ''}
                onChange={(e) => form.updateField('product_name', e.target.value)}
                disabled={isReadonly}
              />
            </div>
            <div className="space-y-1">
              <Label>基材</Label>
              <Select
                value={
                  form.formData.substrate_material_id
                    ? String(form.formData.substrate_material_id)
                    : ''
                }
                onValueChange={handleSubstrateChange}
                disabled={isReadonly}
              >
                <SelectTrigger>
                  <SelectValue placeholder="选择基材" />
                </SelectTrigger>
                <SelectContent>
                  {materials.map((m) => (
                    <SelectItem key={m.id} value={String(m.id)}>
                      {m.material_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1">
              <Label>规格</Label>
              <Input
                value={form.formData.spec || ''}
                onChange={(e) => form.updateField('spec', e.target.value)}
                disabled={isReadonly}
              />
            </div>
            <div className="space-y-1">
              <Label>印刷颜色</Label>
              <Input
                value={form.formData.print_color || ''}
                onChange={(e) => form.updateField('print_color', e.target.value)}
                disabled={isReadonly}
              />
            </div>
            <div className="space-y-1">
              <Label>油墨色号</Label>
              <Select
                value={form.formData.ink_color_id ? String(form.formData.ink_color_id) : ''}
                onValueChange={(v) => form.updateField('ink_color_id', Number(v))}
                disabled={isReadonly}
              >
                <SelectTrigger>
                  <SelectValue placeholder="选择色号" />
                </SelectTrigger>
                <SelectContent>
                  {inkColors.map((c) => (
                    <SelectItem key={c.id} value={String(c.id)}>
                      {c.color_code} - {c.color_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1">
              <Label>刀模</Label>
              <Select
                value={form.formData.die_tool_id ? String(form.formData.die_tool_id) : ''}
                onValueChange={(v) => handleToolSelect('die_tool_id', Number(v))}
                disabled={isReadonly}
              >
                <SelectTrigger>
                  <SelectValue placeholder="选择刀模" />
                </SelectTrigger>
                <SelectContent>
                  {dieTools.map((t) => (
                    <SelectItem key={t.id} value={String(t.id)}>
                      {t.tool_code} - {t.tool_name}
                      {t.status === 4 && (
                        <span
                          className={isRedWarning(t) ? 'text-red-600 font-bold' : 'text-yellow-600'}
                        >
                          {isRedWarning(t) ? ' 红色预警' : ' 预警'}（剩余 {t.remain_life}/
                          {t.total_life}）
                        </span>
                      )}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1">
              <Label>网版</Label>
              <Select
                value={form.formData.screen_plate_id ? String(form.formData.screen_plate_id) : ''}
                onValueChange={(v) => handleToolSelect('screen_plate_id', Number(v))}
                disabled={isReadonly}
              >
                <SelectTrigger>
                  <SelectValue placeholder="选择网版" />
                </SelectTrigger>
                <SelectContent>
                  {screenTools.map((t) => (
                    <SelectItem key={t.id} value={String(t.id)}>
                      {t.tool_code} - {t.tool_name}
                      {t.status === 4 && (
                        <span
                          className={isRedWarning(t) ? 'text-red-600 font-bold' : 'text-yellow-600'}
                        >
                          {isRedWarning(t) ? ' 红色预警' : ' 预警'}（剩余 {t.remain_life}/
                          {t.total_life}）
                        </span>
                      )}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1">
              <Label>损耗率(%)</Label>
              <Input
                type="number"
                value={form.formData.material_loss_rate ?? 5}
                onChange={(e) => form.updateField('material_loss_rate', Number(e.target.value))}
                disabled={isReadonly}
              />
            </div>
            <div className="space-y-1">
              <Label>预估工时</Label>
              <Input
                type="number"
                value={form.formData.estimated_hour ?? ''}
                onChange={(e) =>
                  form.updateField(
                    'estimated_hour',
                    e.target.value ? Number(e.target.value) : undefined
                  )
                }
                disabled={isReadonly}
              />
            </div>
            <div className="space-y-1">
              <Label>版本号</Label>
              <Input value={form.formData.version_no || 'V1.0'} disabled />
            </div>
            <div className="col-span-3 space-y-1">
              <Label>备注</Label>
              <Textarea
                value={form.formData.remark || ''}
                onChange={(e) => form.updateField('remark', e.target.value)}
                rows={2}
                disabled={isReadonly}
              />
            </div>
          </CardContent>
        </Card>
      )}

      {/* ============ 步骤 1：工艺图示 ============ */}
      {currentStep === 1 && (
        <Card className="mt-4">
          <CardHeader>
            <CardTitle>工艺图示</CardTitle>
          </CardHeader>
          <CardContent>
            {form.formData.diagram_url ? (
              <div className="space-y-2">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  src={form.formData.diagram_url}
                  alt="工艺图示"
                  className="max-w-md rounded border"
                />
                {!isReadonly && (
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => form.updateField('diagram_url', '')}
                  >
                    <Trash2 className="h-4 w-4 mr-1" />
                    移除图示
                  </Button>
                )}
              </div>
            ) : (
              !isReadonly && (
                <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-dashed border-gray-300 rounded cursor-pointer hover:bg-gray-50">
                  <div className="flex flex-col items-center gap-2 text-gray-500">
                    <ImageIcon className="h-8 w-8" />
                    <span className="text-sm">点击上传工艺简图</span>
                    <span className="text-xs text-gray-400">
                      支持 jpg/png/gif/webp/svg，最大 10MB
                    </span>
                  </div>
                  <input
                    type="file"
                    className="hidden"
                    accept="image/jpeg,image/png,image/gif,image/webp,image/svg+xml"
                    onChange={async (e) => {
                      const file = e.target.files?.[0];
                      if (file) await form.uploadDiagram(file);
                    }}
                  />
                </label>
              )
            )}
          </CardContent>
        </Card>
      )}

      {/* ============ 步骤 2：物料明细 ============ */}
      {currentStep === 2 && (
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle>{'物料清单'}</CardTitle>
              {!isReadonly && (
                <Button size="sm" variant="outline" onClick={form.addItem}>
                  <Plus className="h-4 w-4 mr-1" />
                  {'添加物料'}
                </Button>
              )}
            </div>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-16">类型</TableHead>
                  <TableHead className="w-56">选择物料</TableHead>
                  <TableHead>物料编码</TableHead>
                  <TableHead>物料名称</TableHead>
                  <TableHead className="w-20">单耗</TableHead>
                  <TableHead className="w-20">单位</TableHead>
                  <TableHead className="w-24">单价</TableHead>
                  <TableHead className="w-24">{'金额'}</TableHead>
                  {!isReadonly && <TableHead className="w-12"></TableHead>}
                </TableRow>
              </TableHeader>
              <TableBody>
                {form.formData.items.map((item, index) => {
                  const itemTypeErr =
                    stepErrors[`items.${index}.material_name`] ||
                    stepErrors[`items.${index}.material_code`];
                  const dosageErr = stepErrors[`items.${index}.unit_dosage`];
                  return (
                    <TableRow key={index}>
                      <TableCell>
                        <Select
                          value={String(item.item_type || 1)}
                          onValueChange={(v) => form.updateItem(index, { item_type: Number(v) })}
                          disabled={isReadonly}
                        >
                          <SelectTrigger className="h-8">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="1">主料</SelectItem>
                            <SelectItem value="2">油墨</SelectItem>
                            <SelectItem value="3">辅料</SelectItem>
                          </SelectContent>
                        </Select>
                      </TableCell>
                      <TableCell>
                        <Select
                          value={item.material_id ? String(item.material_id) : ''}
                          onValueChange={(v) => handleMaterialSelect(index, v)}
                          disabled={isReadonly}
                        >
                          <SelectTrigger className="h-8">
                            <SelectValue placeholder="选择物料" />
                          </SelectTrigger>
                          <SelectContent>
                            {materials.map((m) => (
                              <SelectItem key={m.id} value={String(m.id)}>
                                {m.material_code} - {m.material_name}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          value={item.material_code || ''}
                          onChange={(e) =>
                            form.updateItem(index, { material_code: e.target.value })
                          }
                          disabled={isReadonly}
                        />
                        {itemTypeErr && <p className="text-xs text-red-500 mt-1">{itemTypeErr}</p>}
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          value={item.material_name || ''}
                          onChange={(e) =>
                            form.updateItem(index, { material_name: e.target.value })
                          }
                          disabled={isReadonly}
                        />
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          type="number"
                          value={item.unit_dosage || 0}
                          onChange={(e) =>
                            form.updateItem(index, { unit_dosage: Number(e.target.value) })
                          }
                          disabled={isReadonly}
                        />
                        {dosageErr && <p className="text-xs text-red-500 mt-1">{dosageErr}</p>}
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          value={item.unit || ''}
                          onChange={(e) => form.updateItem(index, { unit: e.target.value })}
                          disabled={isReadonly}
                        />
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          type="number"
                          value={item.unit_cost || 0}
                          onChange={(e) =>
                            form.updateItem(index, { unit_cost: Number(e.target.value) })
                          }
                          disabled={isReadonly}
                        />
                      </TableCell>
                      <TableCell className="font-mono text-sm">
                        ¥{(item.line_cost || 0).toFixed(2)}
                      </TableCell>
                      {!isReadonly && (
                        <TableCell>
                          <Button
                            size="icon"
                            variant="ghost"
                            onClick={() => form.removeItem(index)}
                          >
                            <Trash2 className="h-3 w-3 text-red-500" />
                          </Button>
                        </TableCell>
                      )}
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}

      {/* ============ 步骤 3：工序路线 ============ */}
      {currentStep === 3 && (
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle>{'工序清单'}</CardTitle>
              {!isReadonly && (
                <Button size="sm" variant="outline" onClick={form.addStep}>
                  <Plus className="h-4 w-4 mr-1" />
                  添加工序
                </Button>
              )}
            </div>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-16">序号</TableHead>
                  <TableHead>工序名称</TableHead>
                  <TableHead className="w-24">工时</TableHead>
                  <TableHead className="w-24">{'时薪'}</TableHead>
                  <TableHead className="w-24">{'金额'}</TableHead>
                  <TableHead>{'备注'}</TableHead>
                  {!isReadonly && <TableHead className="w-12"></TableHead>}
                </TableRow>
              </TableHeader>
              <TableBody>
                {form.formData.steps.map((step, index) => {
                  const nameErr = stepErrors[`steps.${index}.process_name`];
                  const hourErr = stepErrors[`steps.${index}.work_hour`];
                  return (
                    <TableRow key={index}>
                      <TableCell className="text-center">{index + 1}</TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          <Select
                            value={step.process_id ? String(step.process_id) : ''}
                            onValueChange={(v) => handleProcessSelect(index, v)}
                            disabled={isReadonly}
                          >
                            <SelectTrigger className="h-8 w-40">
                              <SelectValue placeholder="选择标准工序" />
                            </SelectTrigger>
                            <SelectContent>
                              {processSteps.map((s) => (
                                <SelectItem key={s.id} value={String(s.id)}>
                                  {s.step_name}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                          <Input
                            className="h-8 flex-1"
                            value={step.process_name || ''}
                            onChange={(e) =>
                              form.updateStep(index, { process_name: e.target.value })
                            }
                            disabled={isReadonly}
                          />
                        </div>
                        {nameErr && <p className="text-xs text-red-500 mt-1">{nameErr}</p>}
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          type="number"
                          value={step.work_hour || 0}
                          onChange={(e) =>
                            form.updateStep(index, { work_hour: Number(e.target.value) })
                          }
                          disabled={isReadonly}
                        />
                        {hourErr && <p className="text-xs text-red-500 mt-1">{hourErr}</p>}
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          type="number"
                          value={step.hourly_rate || 0}
                          onChange={(e) =>
                            form.updateStep(index, { hourly_rate: Number(e.target.value) })
                          }
                          disabled={isReadonly}
                        />
                      </TableCell>
                      <TableCell className="font-mono text-sm">
                        ¥{(step.line_cost || 0).toFixed(2)}
                      </TableCell>
                      <TableCell>
                        <Input
                          className="h-8"
                          value={step.process_param || ''}
                          onChange={(e) =>
                            form.updateStep(index, { process_param: e.target.value })
                          }
                          disabled={isReadonly}
                        />
                      </TableCell>
                      {!isReadonly && (
                        <TableCell>
                          <Button
                            size="icon"
                            variant="ghost"
                            onClick={() => form.removeStep(index)}
                          >
                            <Trash2 className="h-3 w-3 text-red-500" />
                          </Button>
                        </TableCell>
                      )}
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}

      {/* ============ 步骤 4：成本确认与提交 ============ */}
      {currentStep === 4 && (
        <div className="space-y-4">
          {/* 成本汇总 */}
          <Card>
            <CardHeader>
              <CardTitle>成本汇总</CardTitle>
            </CardHeader>
            <CardContent className="grid grid-cols-4 gap-4">
              <div className="flex items-center justify-between p-3 bg-gray-50 rounded-md">
                <span className="text-sm text-gray-600 flex items-center gap-1">
                  <Package className="h-4 w-4" />
                  物料成本
                </span>
                <span className="font-mono">¥{form.cost.materialCost.toFixed(2)}</span>
              </div>
              <div className="flex items-center justify-between p-3 bg-gray-50 rounded-md">
                <span className="text-sm text-gray-600 flex items-center gap-1">
                  <Clock className="h-4 w-4" />
                  人工成本
                </span>
                <span className="font-mono">¥{form.cost.laborCost.toFixed(2)}</span>
              </div>
              <div className="flex items-center justify-between p-3 bg-gray-50 rounded-md">
                <span className="text-sm text-gray-600 flex items-center gap-1">
                  <Wrench className="h-4 w-4" />
                  工装成本
                </span>
                <span className="font-mono">¥{form.cost.toolCost.toFixed(2)}</span>
              </div>
              <div className="flex items-center justify-between p-3 bg-blue-50 rounded-md">
                <span className="font-semibold flex items-center gap-1">
                  <DollarSign className="h-5 w-5" />
                  总成本
                </span>
                <span className="font-mono text-lg font-bold text-blue-600">
                  ¥{form.cost.totalCost.toFixed(2)}
                </span>
              </div>
            </CardContent>
          </Card>

          {/* 只读数据汇总 */}
          <Card>
            <CardHeader>
              <CardTitle>{'工艺卡预览'}</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {/* 基础信息汇总 */}
              <div>
                <h4 className="font-medium mb-2 text-gray-700">基础信息</h4>
                <div className="grid grid-cols-3 gap-3 text-sm">
                  <div>
                    <span className="text-gray-500">工艺卡名称</span>
                    {form.formData.sample_name || '-'}
                  </div>
                  <div>
                    <span className="text-gray-500">客户：</span>
                    {customerName}
                  </div>
                  <div>
                    <span className="text-gray-500">{'产品名称'}</span>
                    {form.formData.product_name || '-'}
                  </div>
                  <div>
                    <span className="text-gray-500">{'基材'}</span>
                    {substrateName}
                  </div>
                  <div>
                    <span className="text-gray-500">规格：</span>
                    {form.formData.spec || '-'}
                  </div>
                  <div>
                    <span className="text-gray-500">{'印刷颜色'}</span>
                    {form.formData.print_color || '-'}
                  </div>
                  <div>
                    <span className="text-gray-500">{'油墨色号'}</span>
                    {inkColor ? `${inkColor.color_code} - ${inkColor.color_name}` : '-'}
                  </div>
                  <div>
                    <span className="text-gray-500">刀模</span>
                    {dieTool ? `${dieTool.tool_code} - ${dieTool.tool_name}` : '-'}
                  </div>
                  <div>
                    <span className="text-gray-500">网版</span>
                    {screenTool ? `${screenTool.tool_code} - ${screenTool.tool_name}` : '-'}
                  </div>
                  <div>
                    <span className="text-gray-500">{'损耗率'}</span>
                    {form.formData.material_loss_rate ?? 0}%
                  </div>
                  <div>
                    <span className="text-gray-500">{'预计工时'}</span>
                    {form.formData.estimated_hour ?? '-'}
                  </div>
                  <div>
                    <span className="text-gray-500">{'版本号'}</span>
                    {form.formData.version_no || '-'}
                  </div>
                </div>
                {form.formData.remark && (
                  <div className="mt-2 text-sm">
                    <span className="text-gray-500">备注：</span>
                    {form.formData.remark}
                  </div>
                )}
              </div>

              {/* 物料明细汇总 */}
              <div>
                <h4 className="font-medium mb-2 text-gray-700">
                  {'物料明细'}
                  {form.formData.items.length}
                  {'项'}
                </h4>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-12">序号</TableHead>
                      <TableHead className="w-16">类型</TableHead>
                      <TableHead>物料编码</TableHead>
                      <TableHead>物料名称</TableHead>
                      <TableHead className="w-20">单耗</TableHead>
                      <TableHead className="w-16">单位</TableHead>
                      <TableHead className="w-24">单价</TableHead>
                      <TableHead className="w-24">{'金额'}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {form.formData.items.map((item, i) => (
                      <TableRow key={i}>
                        <TableCell>{i + 1}</TableCell>
                        <TableCell>
                          {item.item_type === 1 ? '主料' : item.item_type === 2 ? '油墨' : '辅料'}
                        </TableCell>
                        <TableCell>{item.material_code || '-'}</TableCell>
                        <TableCell>{item.material_name || '-'}</TableCell>
                        <TableCell className="font-mono">{item.unit_dosage ?? 0}</TableCell>
                        <TableCell>{item.unit || '-'}</TableCell>
                        <TableCell className="font-mono">
                          ¥{(item.unit_cost || 0).toFixed(2)}
                        </TableCell>
                        <TableCell className="font-mono">
                          ¥{(item.line_cost || 0).toFixed(2)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>

              {/* 工序路线汇总 */}
              <div>
                <h4 className="font-medium mb-2 text-gray-700">
                  {'工序明细'}
                  {form.formData.steps.length}
                  {'项'}
                </h4>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-12">序号</TableHead>
                      <TableHead>工序名称</TableHead>
                      <TableHead className="w-24">工时</TableHead>
                      <TableHead className="w-24">{'时薪'}</TableHead>
                      <TableHead className="w-24">{'金额'}</TableHead>
                      <TableHead>{'备注'}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {form.formData.steps.map((step, i) => (
                      <TableRow key={i}>
                        <TableCell>{i + 1}</TableCell>
                        <TableCell>{step.process_name || '-'}</TableCell>
                        <TableCell className="font-mono">{step.work_hour ?? 0}</TableCell>
                        <TableCell className="font-mono">
                          ¥{(step.hourly_rate || 0).toFixed(2)}
                        </TableCell>
                        <TableCell className="font-mono">
                          ¥{(step.line_cost || 0).toFixed(2)}
                        </TableCell>
                        <TableCell>{step.process_param || '-'}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* 底部步骤导航 */}
      <div className="flex items-center justify-between mt-6">
        <Button variant="outline" onClick={handleBack} disabled={currentStep === 1}>
          <ArrowLeft className="h-4 w-4 mr-1" />
          {'上一步'}
        </Button>
        <div className="flex gap-2">
          {!isReadonly && (
            <Button variant="outline" onClick={handleSave} disabled={form.saving}>
              <Save className="h-4 w-4 mr-1" />
              保存草稿
            </Button>
          )}
          {!isLastStep ? (
            <Button onClick={handleNext}>
              {'下一步'}
              <ArrowRight className="h-4 w-4 ml-1" />
            </Button>
          ) : (
            !isReadonly && (
              <Button onClick={handleSubmit} disabled={form.saving}>
                <Send className="h-4 w-4 mr-1" />
                提交
              </Button>
            )
          )}
        </div>
      </div>

      <Dialog open={templateDialogOpen} onOpenChange={setTemplateDialogOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>从模板导入</DialogTitle>
          </DialogHeader>
          <div className="max-h-96 overflow-y-auto">
            {templateLoading ? (
              <p className="text-center text-gray-400 py-8">加载中...</p>
            ) : templates.length === 0 ? (
              <p className="text-center text-gray-400 py-8">
                暂无模板，请先在已确认工艺卡中「存为模板」
              </p>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>模板编号</TableHead>
                    <TableHead>模板名称</TableHead>
                    <TableHead>分类</TableHead>
                    <TableHead className="text-right">总成本</TableHead>
                    <TableHead className="text-center">操作</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {templates.map((t) => (
                    <TableRow key={t.id}>
                      <TableCell className="font-mono text-sm">{t.template_no}</TableCell>
                      <TableCell className="font-medium">{t.template_name}</TableCell>
                      <TableCell>{t.category || '-'}</TableCell>
                      <TableCell className="text-right font-mono">
                        ¥{(t.total_cost || 0).toFixed(2)}
                      </TableCell>
                      <TableCell className="text-center">
                        <Button size="sm" onClick={() => handleImportFromTemplate(t.id)}>
                          选用
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setTemplateDialogOpen(false)}>
              取消
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog
        open={pendingTool !== null}
        onOpenChange={(open) => {
          if (!open) setPendingTool(null);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>红色预警工装引用确认</AlertDialogTitle>
            <AlertDialogDescription>
              {pendingTool && (
                <>
                  工装 <strong>{pendingTool.toolName}</strong> 已进入红色预警状态， 剩余寿命仅{' '}
                  {pendingTool.remainLife} / {pendingTool.totalLife} 次。
                  <br />
                  继续引用可能导致生产中断或质量风险，请确认是否仍要引用此工装。
                </>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setPendingTool(null)}>取消</AlertDialogCancel>
            <AlertDialogAction onClick={confirmPendingTool}>确认引用</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </MainLayout>
  );
}

