'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useEffect, useState, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { MainLayout } from '@/components/layout';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Megaphone, Plus, RefreshCw, Eye, Send, Trash2 } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';

interface Announcement {
  id: number;
  title: string;
  content: string;
  type: string;
  status: string;
  priority: number;
  is_top: number;
  publish_time: string | null;
  expire_time: string | null;
  creator_name: string;
  read_count: number;
  is_read: number;
  create_time: string;
}

export default function AnnouncementPage() {
  const t = useTranslations('System');
  const tc = useTranslations('Common');
  const { toast } = useToast();

  const [list, setList] = useState<Announcement[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);
  const [viewOpen, setViewOpen] = useState(false);
  const [currentItem, setCurrentItem] = useState<Announcement | null>(null);
  const [form, setForm] = useState({
    title: '',
    content: '',
    type: 'info',
    priority: 0,
    is_top: false,
    expire_time: '',
    status: 'draft' as 'draft' | 'published',
  });

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await authFetch(`/api/system/announcement?type=all&page=${page}&pageSize=20`);
      const result = await res.json();
      if (result.success) {
        setList(result.data?.list || []);
        setTotal(result.data?.total || 0);
      }
    } catch {
    } finally {
      setLoading(false);
    }
  }, [page]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleCreate = async () => {
    if (!form.title || !form.content) {
      toast({ title: tc('titleContentRequired'), variant: 'destructive' });
      return;
    }
    try {
      const res = await authFetch('/api/system/announcement', {
        method: 'POST',
        body: JSON.stringify(form),
      });
      const result = await res.json();
      if (result.success) {
        toast({ title: tc('announcementCreated') });
        setCreateOpen(false);
        setForm({
          title: '',
          content: '',
          type: 'info',
          priority: 0,
          is_top: false,
          expire_time: '',
          status: 'draft',
        });
        fetchData();
      } else {
        toast({ title: result.message || '创建失败', variant: 'destructive' });
      }
    } catch {
      toast({ title: tc('createFailed'), variant: 'destructive' });
    }
  };

  const handlePublish = async (id: number) => {
    try {
      const res = await authFetch('/api/system/announcement', {
        method: 'PUT',
        body: JSON.stringify({ id, action: 'publish' }),
      });
      const result = await res.json();
      if (result.success) {
        toast({ title: tc('announcementPublished') });
        fetchData();
      }
    } catch {
      toast({ title: tc('error'), variant: 'destructive' });
    }
  };

  const handleDelete = async (id: number) => {
    if (!window.confirm(tc('confirmDeleteAnnouncement'))) return;
    try {
      const res = await authFetch(`/api/system/announcement?id=${id}`, { method: 'DELETE' });
      const result = await res.json();
      if (result.success) {
        toast({ title: tc('announcementDeleted') });
        fetchData();
      }
    } catch {
      toast({ title: tc('deleteFailed'), variant: 'destructive' });
    }
  };

  const viewDetail = (item: Announcement) => {
    setCurrentItem(item);
    setViewOpen(true);
    // 标记已读
    authFetch('/api/system/announcement', {
      method: 'PUT',
      body: JSON.stringify({ id: item.id, action: 'read' }),
    });
  };

  const typeMap: Record<string, { label: string; color: string }> = {
    info: { label: '通知', color: 'bg-blue-100 text-blue-700 dark:bg-blue-950 dark:text-blue-300' },
    warning: {
      label: '警告',
      color: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-950 dark:text-yellow-300',
    },
    important: {
      label: '重要',
      color: 'bg-red-100 text-red-700 dark:bg-red-950 dark:text-red-300',
    },
  };

  return (
    <MainLayout>
      <div className="p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2">
              <Megaphone className="w-6 h-6" />
              {t('announcementManagement')}
            </h1>
            <p className="text-sm text-muted-foreground mt-1">{t('announcementManagementDesc')}</p>
          </div>
          <div className="flex items-center gap-2">
            <Button size="sm" variant="outline" onClick={fetchData}>
              <RefreshCw className="h-3 w-3 mr-1" />
              {tc('refresh')}
            </Button>
            <Button size="sm" onClick={() => setCreateOpen(true)}>
              <Plus className="h-3 w-3 mr-1" />
              {tc('add')}
            </Button>
          </div>
        </div>

        <Card>
          <CardContent className="p-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-[40%]">{tc('title') || '标题'}</TableHead>
                  <TableHead>{tc('type')}</TableHead>
                  <TableHead>{tc('status')}</TableHead>
                  <TableHead>{tc('annTop')}</TableHead>
                  <TableHead>{tc('annReadCount')}</TableHead>
                  <TableHead>发布时间</TableHead>
                  <TableHead className="text-right">{tc('actions')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={7} className="text-center py-8">
                      <RefreshCw className="w-5 h-5 animate-spin mx-auto" />
                    </TableCell>
                  </TableRow>
                ) : list.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={7} className="text-center text-muted-foreground py-8">
                      {tc('noData')}
                    </TableCell>
                  </TableRow>
                ) : (
                  list.map((item) => (
                    <TableRow key={item.id}>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          {!item.is_read && <span className="w-2 h-2 rounded-full bg-blue-500" />}
                          <span className="font-medium text-sm">{item.title}</span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <Badge className={typeMap[item.type]?.color || typeMap['info'].color}>
                          {typeMap[item.type]?.label || item.type}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        {item.status === 'published' ? (
                          <Badge className="bg-green-100 text-green-700 dark:bg-green-950 dark:text-green-300">
                            已发布
                          </Badge>
                        ) : (
                          <Badge variant="secondary">{tc('draft')}</Badge>
                        )}
                      </TableCell>
                      <TableCell>{item.is_top ? '是' : '-'}</TableCell>
                      <TableCell className="text-sm">{item.read_count}</TableCell>
                      <TableCell className="text-xs">{item.publish_time || '-'}</TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-7"
                            onClick={() => viewDetail(item)}
                          >
                            <Eye className="h-3 w-3 mr-1" />
                            查看
                          </Button>
                          {item.status === 'draft' && (
                            <Button
                              size="sm"
                              variant="ghost"
                              className="h-7 text-green-600"
                              onClick={() => handlePublish(item.id)}
                            >
                              <Send className="h-3 w-3 mr-1" />
                              发布
                            </Button>
                          )}
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-7 text-red-600"
                            onClick={() => handleDelete(item.id)}
                          >
                            <Trash2 className="h-3 w-3" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>

        <div className="flex items-center justify-between">
          <span className="text-sm text-muted-foreground">
            {tc('total')} {total}
