          <DialogHeader>
            <DialogTitle>{tc('createAnnouncementTitle')}</DialogTitle>
            <DialogDescription>{tc('createAnnouncementDesc')}</DialogDescription>
          </DialogHeader>
          <div className="space-y-3">
            <div className="space-y-1">
              <Label>{tc('annTitleLabel')}</Label>
              <Input
                value={form.title}
                onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))}
              />
            </div>
            <div className="space-y-1">
              <Label>{tc('annContentLabel')}</Label>
              <Textarea
                rows={5}
                value={form.content}
                onChange={(e) => setForm((f) => ({ ...f, content: e.target.value }))}
              />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <Label>{tc('type')}</Label>
                <Select
                  value={form.type}
                  onValueChange={(v) => setForm((f) => ({ ...f, type: v }))}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="info">{tc('notice')}</SelectItem>
                    <SelectItem value="warning">警告</SelectItem>
                    <SelectItem value="important">重要</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <Label>{tc('priority')}</Label>
                <Input
                  type="number"
                  value={form.priority}
                  onChange={(e) => setForm((f) => ({ ...f, priority: Number(e.target.value) }))}
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <Label>过期时间</Label>
                <Input
                  type="datetime-local"
                  value={form.expire_time}
                  onChange={(e) => setForm((f) => ({ ...f, expire_time: e.target.value }))}
                />
              </div>
              <div className="space-y-1">
                <Label>{tc('actions')}</Label>
                <Select
                  value={form.status}
                  onValueChange={(v: Loose) => setForm((f) => ({ ...f, status: v }))}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="draft">{tc('annDraft')}</SelectItem>
                    <SelectItem value="published">{tc('annPublished')}</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setCreateOpen(false)}>
              {tc('cancel')}
            </Button>
            <Button onClick={handleCreate}>{tc('confirm')}</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* 查看公告对话框 */}
      <Dialog open={viewOpen} onOpenChange={setViewOpen}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{currentItem?.title}</DialogTitle>
            <DialogDescription>
              {currentItem?.creator_name} · {currentItem?.publish_time || currentItem?.create_time}
            </DialogDescription>
          </DialogHeader>
          <div className="text-sm whitespace-pre-wrap">{currentItem?.content}</div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setViewOpen(false)}>
              {tc('close')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </MainLayout>
  );
}

