        description: '负责仓库和物料管理',
      },
      {
        id: 6,
        dept_code: 'DEPT006',
        dept_name: '采购部',
        parent_id: 0,
        leader_name: '孙丽',
        sort_order: 6,
        status: 1,
        description: '负责原材料和设备采购',
      },
      {
        id: 7,
        dept_code: 'DEPT007',
        dept_name: '品质部',
        parent_id: 0,
        leader_name: '周杰',
        sort_order: 7,
        status: 1,
        description: '负责质量检查和品质控制',
      },
      {
        id: 8,
