'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useEffect, useState, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { MainLayout } from '@/components/layout';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Clock, RefreshCw, Play, Pause, Plus, Eye } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';

interface TaskItem {
  id: number;
  task_name: string;
  task_type: string;
  task_group: string;
  cron_expression: string | null;
  description: string | null;
  config: string | null;
  status: string;
  last_execute_time: string | null;
  last_result: string | null;
  create_by: number | null;
  create_time: string;
}

export default function SchedulerPage() {
  const t = useTranslations('System');
  const tc = useTranslations('Common');
  const { toast } = useToast();

  const [list, setList] = useState<TaskItem[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);
  const [logOpen, setLogOpen] = useState(false);
  const [logs, setLogs] = useState<Loose[]>([]);
  const [form, setForm] = useState({
    task_name: '',
    task_type: 'inventory_alert',
    task_group: 'default',
    cron_expression: '',
    description: '',
    config: '',
  });

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await authFetch(`/api/system/scheduler?page=${page}&pageSize=20`);
      const result = await res.json();
      if (result.success) {
        setList(result.data?.list || []);
        setTotal(result.data?.total || 0);
      }
    } catch {
    } finally {
      setLoading(false);
    }
  }, [page]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleCreate = async () => {
    if (!form.task_name || !form.task_type) {
      toast({ title: tc('taskNameTypeRequired'), variant: 'destructive' });
      return;
    }
    try {
      const res = await authFetch('/api/system/scheduler', {
        method: 'POST',
        body: JSON.stringify(form),
      });
      const result = await res.json();
      if (result.success) {
        toast({ title: tc('taskCreated') });
        setCreateOpen(false);
        setForm({
          task_name: '',
          task_type: 'inventory_alert',
          task_group: 'default',
          cron_expression: '',
          description: '',
          config: '',
        });
        fetchData();
      } else {
        toast({ title: result.message || '创建失败', variant: 'destructive' });
      }
    } catch {
      toast({ title: tc('createFailed'), variant: 'destructive' });
    }
  };

  const handleAction = async (id: number, action: string) => {
    try {
      const res = await authFetch('/api/system/scheduler', {
        method: 'PUT',
        body: JSON.stringify({ id, action }),
      });
      const result = await res.json();
      if (result.success) {
        toast({ title: result.message || '操作成功' });
        fetchData();
      } else {
        toast({ title: result.message || '操作失败', variant: 'destructive' });
      }
    } catch {
      toast({ title: tc('error'), variant: 'destructive' });
    }
  };

  const viewLogs = async (taskId: number) => {
    try {
      const res = await authFetch(`/api/system/scheduler?taskId=${taskId}&type=logs`);
      const result = await res.json();
      if (result.success) {
        setLogs(result.data?.logs || []);
        setLogOpen(true);
      }
    } catch {}
  };

  const taskTypeMap: Record<string, string> = {
    inventory_alert: '库存预警',
    data_cleanup: '数据清理',
    report_generation: '报表生成',
  };

  return (
    <MainLayout>
      <div className="p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2">
              <Clock className="w-6 h-6" />
              {t('schedulerManagement')}
            </h1>
            <p className="text-sm text-muted-foreground mt-1">{t('schedulerManagementDesc')}</p>
          </div>
          <div className="flex items-center gap-2">
            <Button size="sm" variant="outline" onClick={fetchData}>
              <RefreshCw className="h-3 w-3 mr-1" />
              {tc('refresh')}
            </Button>
            <Button size="sm" onClick={() => setCreateOpen(true)}>
              <Plus className="h-3 w-3 mr-1" />
              {tc('add')}
            </Button>
          </div>
        </div>

        <Card>
          <CardContent className="p-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>{t('taskName')}</TableHead>
                  <TableHead>{t('taskType')}</TableHead>
                  <TableHead>{t('taskGroup')}</TableHead>
                  <TableHead>Cron</TableHead>
                  <TableHead>{tc('status')}</TableHead>
                  <TableHead>{t('lastExecuteTime')}</TableHead>
                  <TableHead>{t('lastResult')}</TableHead>
                  <TableHead className="text-right">{tc('actions')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={8} className="text-center py-8">
                      <RefreshCw className="w-5 h-5 animate-spin mx-auto" />
                    </TableCell>
                  </TableRow>
                ) : list.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={8} className="text-center text-muted-foreground py-8">
                      {tc('noData')}
                    </TableCell>
                  </TableRow>
                ) : (
                  list.map((item) => (
                    <TableRow key={item.id}>
                      <TableCell className="font-medium text-sm">{item.task_name}</TableCell>
                      <TableCell>
                        <Badge variant="outline">
                          {taskTypeMap[item.task_type] || item.task_type}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-sm">{item.task_group || '-'}</TableCell>
                      <TableCell className="font-mono text-xs">
                        {item.cron_expression || '-'}
                      </TableCell>
                      <TableCell>
                        {item.status === 'active' ? (
                          <Badge className="bg-green-100 text-green-700 dark:bg-green-950 dark:text-green-300">
                            {t('active')}
                          </Badge>
                        ) : (
                          <Badge variant="secondary">{t('paused')}</Badge>
                        )}
                      </TableCell>
                      <TableCell className="text-xs">{item.last_execute_time || '-'}</TableCell>
                      <TableCell className="text-xs max-w-[200px] truncate">
                        {item.last_result || '-'}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-7"
                            onClick={() => handleAction(item.id, 'execute')}
                          >
                            <Play className="h-3 w-3 mr-1" />
                            {t('execute')}
                          </Button>
                          {item.status === 'active' ? (
                            <Button
                              size="sm"
                              variant="ghost"
                              className="h-7 text-yellow-600"
                              onClick={() => handleAction(item.id, 'pause')}
                            >
                              <Pause className="h-3 w-3 mr-1" />
                              {t('pause')}
                            </Button>
                          ) : (
                            <Button
                              size="sm"
                              variant="ghost"
                              className="h-7 text-green-600"
                              onClick={() => handleAction(item.id, 'resume')}
                            >
                              <Play className="h-3 w-3 mr-1" />
                              {t('resume')}
                            </Button>
                          )}
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-7"
                            onClick={() => viewLogs(item.id)}
                          >
                            <Eye className="h-3 w-3 mr-1" />
                            {t('logs')}
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>

        <div className="flex items-center justify-between">
          <span className="text-sm text-muted-foreground">
            {tc('total')} {total}
          </span>
          <div className="flex gap-2">
            <Button
              size="sm"
              variant="outline"
              disabled={page <= 1}
              onClick={() => setPage((p) => p - 1)}
            >
              {tc('prevPage') || '上一页'}
            </Button>
            <Button
              size="sm"
              variant="outline"
              disabled={page * 20 >= total}
              onClick={() => setPage((p) => p + 1)}
            >
              {tc('nextPage') || '下一页'}
            </Button>
          </div>
        </div>
      </div>

      {/* 创建任务对话框 */}
      <Dialog open={createOpen} onOpenChange={setCreateOpen}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{t('createTask')}</DialogTitle>
            <DialogDescription>{t('createTaskDesc')}</DialogDescription>
          </DialogHeader>
          <div className="space-y-3">
            <div className="space-y-1">
              <Label>{t('taskName')} *</Label>
              <Input
                value={form.task_name}
                onChange={(e) => setForm((f) => ({ ...f, task_name: e.target.value }))}
              />
            </div>
            <div className="space-y-1">
              <Label>{t('taskType')} *</Label>
              <Select
                value={form.task_type}
                onValueChange={(v) => setForm((f) => ({ ...f, task_type: v }))}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="inventory_alert">{taskTypeMap['inventory_alert']}</SelectItem>
                  <SelectItem value="data_cleanup">{taskTypeMap['data_cleanup']}</SelectItem>
                  <SelectItem value="report_generation">
                    {taskTypeMap['report_generation']}
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1">
              <Label>Cron {t('expression')}</Label>
              <Input
                value={form.cron_expression}
                onChange={(e) => setForm((f) => ({ ...f, cron_expression: e.target.value }))}
                placeholder="0 0 * * *"
              />
            </div>
            <div className="space-y-1">
              <Label>{tc('remark')}</Label>
              <Textarea
                value={form.description}
                onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setCreateOpen(false)}>
              {tc('cancel')}
            </Button>
            <Button onClick={handleCreate}>{tc('confirm')}</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* 执行日志对话框 */}
      <Dialog open={logOpen} onOpenChange={setLogOpen}>
        <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{t('executionLogs')}</DialogTitle>
            <DialogDescription>{t('executionLogsDesc')}</DialogDescription>
          </DialogHeader>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="text-xs">{t('startTime')}</TableHead>
                <TableHead className="text-xs">{t('endTime')}</TableHead>
                <TableHead className="text-xs">{tc('status')}</TableHead>
                <TableHead className="text-xs">{t('result')}</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {logs.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={4} className="text-center text-muted-foreground py-4">
                    {tc('noData')}
                  </TableCell>
                </TableRow>
              ) : (
                logs.map((log: Loose, idx: number) => (
                  <TableRow key={idx}>
                    <TableCell className="text-xs">{log.start_time || '-'}</TableCell>
                    <TableCell className="text-xs">{log.end_time || '-'}</TableCell>
                    <TableCell>
                      {log.status === 'success' ? (
                        <Badge className="bg-green-100 text-green-700 dark:bg-green-950 dark:text-green-300 text-xs">
                          成功
                        </Badge>
                      ) : log.status === 'failed' ? (
                        <Badge variant="destructive" className="text-xs">
                          失败
                        </Badge>
                      ) : (
                        <Badge variant="secondary" className="text-xs">
                          运行中
                        </Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-xs max-w-[300px] truncate">
                      {log.result || '-'}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
          <DialogFooter>
            <Button variant="outline" onClick={() => setLogOpen(false)}>
              {tc('close')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </MainLayout>
  );
}

'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useState } from 'react';
import { MainLayout } from '@/components/layout';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import {
  Database,
  RefreshCw,
  CheckCircle,
  XCircle,
  AlertTriangle,
  Package,
  Users,
  ClipboardList,
} from 'lucide-react';
import { useTranslations } from 'next-intl';

interface SeedStats {
  [key: string]: number;
}

export default function SeedDataPage() {
  const tc = useTranslations('Common');
  // 翻译钩子

  const [systemLoading, setSystemLoading] = useState(false);
  const [businessLoading, setBusinessLoading] = useState(false);
  const [systemStats, setSystemStats] = useState<SeedStats | null>(null);
  const [businessStats, setBusinessStats] = useState<SeedStats | null>(null);
  const [error, setError] = useState<string | null>(null);

  const runSystemSeedData = async () => {
    setSystemLoading(true);
    setError(null);
    setSystemStats(null);

    try {
      const response = await authFetch('/api/init/settings-seed', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      const result = await response.json();

      if (result.success) {
        setSystemStats(result.data);
        toast.success(tc('seedSystemSuccess'));
      } else {
        setError(result.message || '初始化失败');
        toast.error(result.message || '初始化失败');
      }
    } catch (e) {
      setError((e as Error).message || '网络错误');
      toast.error('初始化失败: ' + (e as Error).message);
    } finally {
      setSystemLoading(false);
    }
  };

  const runBusinessSeedData = async () => {
    setBusinessLoading(true);
    setError(null);
    setBusinessStats(null);

    try {
      const response = await authFetch('/api/init/business-seed', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      const result = await response.json();

      if (result.success) {
        setBusinessStats(result.data);
        toast.success(tc('seedBusinessSuccess'));
      } else {
        setError(result.message || '初始化失败');
        toast.error(result.message || '初始化失败');
      }
    } catch (e) {
      setError((e as Error).message || '网络错误');
      toast.error('初始化失败: ' + (e as Error).message);
    } finally {
      setBusinessLoading(false);
    }
  };

  return (
    <MainLayout title="数据种子管理">
      <div className="container mx-auto py-6 space-y-6">
        {error && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-4">
            <div className="flex items-start gap-3">
              <XCircle className="w-5 h-5 text-red-600 mt-0.5" />
              <div className="flex-1">
                <h4 className="font-medium text-red-800">初始化失败</h4>
                <p className="mt-1 text-sm text-red-700">{error}</p>
              </div>
            </div>
          </div>
        )}

        {/* 系统数据种子 */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Database className="w-5 h-5" />
              系统数据种子初始化
            </CardTitle>
            <CardDescription>
              初始化系统基础数据，包括部门、角色、用户、仓库分类、物料分类、字典配置等。
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="bg-amber-50 border border-amber-200 rounded-lg p-4">
              <div className="flex items-start gap-3">
                <AlertTriangle className="w-5 h-5 text-amber-600 mt-0.5" />
                <div className="flex-1">
                  <h4 className="font-medium text-amber-800">注意事项</h4>
                  <ul className="mt-2 text-sm text-amber-700 space-y-1">
                    <li>• 此操作会清空系统设置相关表的数据</li>
                    <li>• 建议在首次部署或需要重置系统配置时使用</li>
                    <li>• 初始化后默认管理员账号：admin，密码：admin123</li>
                  </ul>
                </div>
              </div>
            </div>

            <Button
              onClick={runSystemSeedData}
              disabled={systemLoading}
              className="w-full bg-blue-600 hover:bg-blue-700"
              size="lg"
            >
              {systemLoading ? (
                <>
                  <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                  初始化中...
                </>
              ) : (
                <>
                  <Database className="w-4 h-4 mr-2" />
                  初始化系统数据
                </>
              )}
            </Button>

            {systemStats && (
              <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                <div className="flex items-start gap-3">
                  <CheckCircle className="w-5 h-5 text-green-600 mt-0.5" />
                  <div className="flex-1">
                    <h4 className="font-medium text-green-800">系统数据初始化成功</h4>
                    <div className="mt-3 grid grid-cols-2 md:grid-cols-3 gap-3">
                      {Object.entries(systemStats).map(([key, value]) => (
                        <div
                          key={key}
                          className="flex items-center justify-between p-2 bg-white rounded"
                        >
                          <span className="text-sm text-gray-600">{key}</span>
                          <Badge variant="secondary">{value} 条</Badge>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            )}
          </CardContent>
        </Card>

        {/* 业务数据种子 */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Package className="w-5 h-5" />
              业务数据种子初始化
            </CardTitle>
            <CardDescription>
              初始化业务数据，包括客户、销售订单、生产工单、入库单、物料标签、库存、质量检验记录等。
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="bg-amber-50 border border-amber-200 rounded-lg p-4">
              <div className="flex items-start gap-3">
                <AlertTriangle className="w-5 h-5 text-amber-600 mt-0.5" />
                <div className="flex-1">
                  <h4 className="font-medium text-amber-800">注意事项</h4>
                  <ul className="mt-2 text-sm text-amber-700 space-y-1">
                    <li>• 此操作会清空业务相关表的数据</li>
                    <li>• 建议在需要重置业务数据时使用</li>
                    <li>• 包含演示用的真实业务场景数据</li>
                  </ul>
                </div>
              </div>
            </div>

            <Button
              onClick={runBusinessSeedData}
              disabled={businessLoading}
              className="w-full bg-green-600 hover:bg-green-700"
              size="lg"
            >
              {businessLoading ? (
                <>
                  <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                  初始化中...
                </>
              ) : (
                <>
                  <Package className="w-4 h-4 mr-2" />
                  初始化业务数据
                </>
              )}
            </Button>

            {businessStats && (
