'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useTranslations } from 'next-intl';
import { useEffect, useState, useCallback } from 'react';
import { MainLayout } from '@/components/layout';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog';
import { Calculator, RefreshCw, Eye, TrendingUp, DollarSign } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';

interface CostItem {
  material_id: number;
  material_name: string;
  material_code: string;
  material_spec: string;
  unit: string;
  total_quantity: number;
  total_cost_amount: number;
  avg_cost_price: number;
  min_cost_price: number;
  max_cost_price: number;
  warehouse_count: number;
}

export default function CostPage() {
  const tc = useTranslations('Common');
  const t = useTranslations('Warehouse');
  const { toast } = useToast();
  const [list, setList] = useState<CostItem[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [detailOpen, setDetailOpen] = useState(false);
  const [detailData, setDetailData] = useState<Loose>(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await authFetch(`/api/warehouse/cost?page=${page}&pageSize=20`);
      const result = await res.json();
      if (result.success) {
        setList(result.data?.list || []);
        setTotal(result.data?.total || 0);
      }
    } catch {
    } finally {
      setLoading(false);
    }
  }, [page]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const viewDetail = async (materialId: number) => {
    try {
      const res = await authFetch(`/api/warehouse/cost?materialId=${materialId}`);
      const result = await res.json();
      if (result.success) {
        setDetailData(result.data);
        setDetailOpen(true);
      }
    } catch {}
  };

  const recalculate = async (materialId: number) => {
    if (!confirm('确定重新计算该物料的成本？')) return;
    try {
      const res = await authFetch('/api/warehouse/cost', {
        method: 'POST',
        body: JSON.stringify({ materialId }),
      });
      const result = await res.json();
      if (result.success) {
        toast({ title: t('costRecalculated', { price: result.data.costPrice.toFixed(4) }) });
        fetchData();
      } else {
        toast({ title: result.message || t('recalculateFailed'), variant: 'destructive' });
      }
    } catch {
      toast({ title: t('recalculateFailed'), variant: 'destructive' });
    }
  };

  const totalCostAmount = list.reduce((sum, item) => sum + (item.total_cost_amount || 0), 0);

  return (
    <MainLayout>
      <div className="p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2">
              <Calculator className="w-6 h-6" />
              成本核算管理
            </h1>
            <p className="text-sm text-muted-foreground mt-1">
              移动加权平均法成本核算，支持成本重算和成本分析
            </p>
          </div>
          <Button size="sm" variant="outline" onClick={fetchData}>
            <RefreshCw className="h-3 w-3 mr-1" />
            刷新
          </Button>
        </div>

        {/* 汇总卡片 */}
        <div className="grid grid-cols-3 gap-4">
          <Card>
            <CardContent className="pt-4">
              <div className="flex items-center gap-2">
                <DollarSign className="w-5 h-5 text-green-600" />
                <div>
                  <div className="text-sm text-muted-foreground">{tc('totalCostAmount')}</div>
                  <div className="text-2xl font-bold">
                    ¥
                    {totalCostAmount.toLocaleString(undefined, {
                      minimumFractionDigits: 2,
                      maximumFractionDigits: 2,
                    })}
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="pt-4">
              <div className="flex items-center gap-2">
                <TrendingUp className="w-5 h-5 text-blue-600" />
                <div>
                  <div className="text-sm text-muted-foreground">{tc('materialTypeCount')}</div>
                  <div className="text-2xl font-bold">{total}</div>
                </div>
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="pt-4">
              <div className="flex items-center gap-2">
                <Calculator className="w-5 h-5 text-orange-600" />
                <div>
                  <div className="text-sm text-muted-foreground">{tc('costMethod')}</div>
                  <div className="text-2xl font-bold">移动加权平均</div>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        <Card>
          <CardContent className="p-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>物料编码</TableHead>
                  <TableHead>物料名称</TableHead>
                  <TableHead>{tc('specification')}</TableHead>
                  <TableHead>{tc('unit')}</TableHead>
                  <TableHead>{tc('totalQuantity')}</TableHead>
                  <TableHead>{tc('avgCostPrice')}</TableHead>
                  <TableHead>{tc('costAmount')}</TableHead>
                  <TableHead>{tc('warehouseCount')}</TableHead>
                  <TableHead className="text-right">{tc('actions')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={9} className="text-center py-8">
                      <RefreshCw className="w-5 h-5 animate-spin mx-auto" />
                    </TableCell>
                  </TableRow>
                ) : list.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={9} className="text-center text-muted-foreground py-8">
                      暂无成本数据
                    </TableCell>
                  </TableRow>
                ) : (
                  list.map((item) => (
                    <TableRow key={item.material_id}>
                      <TableCell className="font-mono text-sm">{item.material_code}</TableCell>
                      <TableCell className="text-sm font-medium">{item.material_name}</TableCell>
                      <TableCell className="text-sm text-muted-foreground">
                        {item.material_spec || '-'}
                      </TableCell>
                      <TableCell className="text-sm">{item.unit}</TableCell>
                      <TableCell className="text-sm font-mono">
                        {Number(item.total_quantity).toLocaleString()}
                      </TableCell>
                      <TableCell className="text-sm font-mono">
                        ¥{Number(item.avg_cost_price).toFixed(4)}
                      </TableCell>
                      <TableCell className="text-sm font-mono font-medium">
                        ¥
                        {Number(item.total_cost_amount).toLocaleString(undefined, {
                          minimumFractionDigits: 2,
                        })}
                      </TableCell>
                      <TableCell>
                        <Badge variant="outline" className="text-xs">
                          {item.warehouse_count}
                          {tc('warehouseUnitSuffix')}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-7"
                            onClick={() => viewDetail(item.material_id)}
                          >
                            <Eye className="h-3 w-3 mr-1" />
                            详情
                          </Button>
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-7 text-orange-600"
                            onClick={() => recalculate(item.material_id)}
                          >
                            <Calculator className="h-3 w-3 mr-1" />
                            重算
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>

        <div className="flex items-center justify-between">
          <span className="text-sm text-muted-foreground">
            共{total}
            {tc('costRecordUnit')}
          </span>
          <div className="flex gap-2">
            <Button
              size="sm"
              variant="outline"
              disabled={page <= 1}
              onClick={() => setPage((p) => p - 1)}
            >
              上一页
            </Button>
            <Button
              size="sm"
              variant="outline"
              disabled={page * 20 >= total}
              onClick={() => setPage((p) => p + 1)}
            >
              下一页
            </Button>
          </div>
        </div>
      </div>

      {/* 成本详情对话框 */}
      <Dialog open={detailOpen} onOpenChange={setDetailOpen}>
        <DialogContent className="max-w-3xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{tc('materialCostDetail')}</DialogTitle>
            <DialogDescription>{tc('materialCostDetailDesc')}</DialogDescription>
          </DialogHeader>
          {detailData && (
            <div className="space-y-4">
              {/* 各仓库成本 */}
              <div>
                <h4 className="font-medium mb-2">各仓库成本</h4>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-xs">{tc('warehouse')}</TableHead>
                      <TableHead className="text-xs">{tc('quantity')}</TableHead>
                      <TableHead className="text-xs">成本价</TableHead>
                      <TableHead className="text-xs">{tc('costAmount')}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {(detailData.stock || []).map((s: Loose, idx: number) => (
                      <TableRow key={idx}>
                        <TableCell className="text-sm">
                          {s.warehouse_name || `仓库${s.warehouse_id}`}
                        </TableCell>
                        <TableCell className="text-sm font-mono">
                          {Number(s.quantity).toLocaleString()}
                        </TableCell>
                        <TableCell className="text-sm font-mono">
                          ¥{Number(s.cost_price || 0).toFixed(4)}
                        </TableCell>
                        <TableCell className="text-sm font-mono">
                          ¥{(Number(s.quantity) * Number(s.cost_price || 0)).toFixed(2)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>

              {/* 成本变动历史 */}
              <div>
                <h4 className="font-medium mb-2">{tc('costChangeHistory')}</h4>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-xs">{tc('time')}</TableHead>
                      <TableHead className="text-xs">{tc('type')}</TableHead>
                      <TableHead className="text-xs">{tc('quantity')}</TableHead>
                      <TableHead className="text-xs">单价</TableHead>
                      <TableHead className="text-xs">{tc('amount')}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {(detailData.costHistory || []).map((h: Loose, idx: number) => (
                      <TableRow key={idx}>
                        <TableCell className="text-xs">{h.create_time}</TableCell>
                        <TableCell className="text-xs">{h.movement_type}</TableCell>
                        <TableCell className="text-xs font-mono">
                          {Number(h.quantity).toLocaleString()}
                        </TableCell>
                        <TableCell className="text-xs font-mono">
                          ¥{Number(h.unit_price || 0).toFixed(4)}
                        </TableCell>
                        <TableCell className="text-xs font-mono">
                          ¥{(Number(h.quantity) * Number(h.unit_price || 0)).toFixed(2)}
                        </TableCell>
                      </TableRow>
                    ))}
                    {(detailData.costHistory || []).length === 0 && (
                      <TableRow>
                        <TableCell
                          colSpan={5}
                          className="text-center text-muted-foreground text-sm py-4"
                        >
                          暂无入库记录
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setDetailOpen(false)}>
              {tc('close')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </MainLayout>
  );
}

'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useState, useEffect } from 'react';
import { MainLayout } from '@/components/layout';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { useTranslations } from 'next-intl';

interface InboundRecord {
  id: number;
  order_no: string;
  inbound_date: string;
  supplier_name: string;
  total_quantity: number;
  status: string;
  items?: Loose[];
}

export default function SimpleInboundPage() {
  // 翻译钩子
  const t = useTranslations('Warehouse');
  const tc = useTranslations('Common');

  const [records, setRecords] = useState<InboundRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await authFetch('/api/warehouse/inbound?page=1&pageSize=100');
        const result = await response.json();

        if (result.success) {
          const list = result.data?.list || result.data || [];
          setRecords(list);
        } else {
          setError(result.message);
        }
      } catch (e) {
        setError((e as Error).message);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const statusLabels: Record<string, string> = {
    draft: tc('draft'),
    pending: tc('pending'),
    approved: tc('approved'),
    completed: tc('completed'),
    cancelled: tc('cancelled'),
  };

  const statusColors: Record<string, string> = {
    draft: 'bg-yellow-100 text-yellow-700',
    pending: 'bg-blue-100 text-blue-700',
    approved: 'bg-green-100 text-green-700',
    completed: 'bg-green-100 text-green-700',
    cancelled: 'bg-gray-100 text-gray-700',
  };

  return (
    <MainLayout title={t('inboundSimpleTitle')}>
      <div className="container mx-auto py-6 space-y-6">
        <Card>
          <CardHeader>
            <CardTitle>{t('inboundSimpleRecords')}</CardTitle>
          </CardHeader>
          <CardContent>
            {loading && <p>{t('loading')}</p>}
            {error && (
              <p className="text-red-600">
                {tc('error')}: {error}
              </p>
            )}

            {!loading && !error && (
              <>
                <p className="mb-4">{t('inboundRecordsCount', { count: records.length })}</p>
                <div className="space-y-4">
                  {records.length === 0 ? (
                    <p className="text-gray-500">{t('noData')}</p>
                  ) : (
                    records.map((record) => (
                      <div
                        key={record.id}
                        className="border p-4 rounded-lg flex items-center justify-between"
                      >
                        <div>
                          <p className="font-medium">{record.order_no}</p>
                          <p className="text-sm text-gray-500">
                            {record.supplier_name} | {record.total_quantity}件
                          </p>
                          <p className="text-sm text-gray-400">{record.inbound_date}</p>
                        </div>
                        <Badge className={statusColors[record.status] || 'bg-gray-100'}>
                          {statusLabels[record.status] || record.status}
                        </Badge>
                      </div>
                    ))
                  )}
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </div>
    </MainLayout>
  );
}

'use client';

import { motion } from 'framer-motion';
import {
  Plus,
  RefreshCw,
  RotateCcw,
  Printer,
  Barcode,
  Beaker,
  ScanLine,
  Scissors,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { toast } from 'sonner';
import { useTranslations } from 'next-intl';
import type { InboundRecord, PrintLabel } from '../types';
import { mapRecordsToLabels, filterApprovedRecords } from '../utils/mapRecordsToLabels';

interface InboundToolbarProps {
  isLoading: boolean;
  inboundRecords: InboundRecord[];
  selectedRecords: (string | number)[];
  onRefresh: () => void;
  onResetSearch: () => void;
  onOpenAddDialog: () => void;
  onOpenMixedAddDialog: () => void;
  onOpenGenerateDialog: () => void;
  onOpenQRScanDialog: () => void;
  onOpenSourceLabelQuery: () => void;
  onPrintLabels: (labels: PrintLabel[]) => void;
  onOpenPrintPreview: () => void;
}

export function InboundToolbar({
  isLoading,
  inboundRecords,
  selectedRecords,
  onRefresh,
  onResetSearch,
  onOpenAddDialog,
  onOpenMixedAddDialog,
  onOpenGenerateDialog,
  onOpenQRScanDialog,
  onOpenSourceLabelQuery,
  onPrintLabels,
  onOpenPrintPreview,
}: InboundToolbarProps) {
  const t = useTranslations('Warehouse');
  const tc = useTranslations('Common');

  const handlePrintAll = () => {
    const approvedRecords = filterApprovedRecords(inboundRecords);
    if (approvedRecords.length === 0) {
      toast.error(t('noApprovedForPrint'));
      return;
    }
    const labels = mapRecordsToLabels(approvedRecords);
    if (selectedRecords.length > 0) {
      const selectedLabels = labels.filter((l) => selectedRecords.includes(l.record.id));
      onPrintLabels(selectedLabels.length > 0 ? selectedLabels : labels);
    } else {
      onPrintLabels(labels);
    }
    onOpenPrintPreview();
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: 0.05 }}
      className="flex flex-wrap items-center gap-3 bg-card p-4 rounded-xl shadow-sm border"
    >
      <Button onClick={onOpenAddDialog} className="gap-2 bg-green-600 hover:bg-green-700">
        <Plus className="w-4 h-4" />
        {tc('add')}
      </Button>
      <Button onClick={onOpenMixedAddDialog} variant="outline" className="gap-2">
        <Beaker className="w-4 h-4" />
        {t('mixedMaterialAdd')}
      </Button>
      <Button onClick={onOpenGenerateDialog} variant="outline" className="gap-2">
        <Barcode className="w-4 h-4" />
        {t('generateLabel')}
      </Button>
      <Button onClick={onOpenQRScanDialog} variant="outline" className="gap-2">
        <ScanLine className="w-4 h-4" />
        {t('qrCodeQuery')}
      </Button>
      <Button
        onClick={onOpenSourceLabelQuery}
        variant="outline"
        className="gap-2 text-orange-600 border-orange-200 hover:bg-orange-50"
      >
        <Scissors className="w-4 h-4" />
        {t('materialCutting')}
      </Button>
      <div className="w-px h-8 bg-slate-200 dark:bg-slate-600 mx-2" />
      <Button onClick={handlePrintAll} className="gap-2 bg-blue-600 hover:bg-blue-700">
        <Printer className="w-4 h-4" />
        {t('printQRCode')}
      </Button>
      <div className="w-px h-8 bg-slate-200 dark:bg-slate-600 mx-2" />
      <Button onClick={onRefresh} variant="outline" className="gap-2" disabled={isLoading}>
        <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
        {tc('refresh')}
      </Button>
      <Button onClick={onResetSearch} variant="outline" className="gap-2">
        <RotateCcw className="w-4 h-4" />
        {tc('reset')}
      </Button>
    </motion.div>
  );
}

'use client';

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { RefreshCw } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { toast } from 'sonner';
import { authFetch } from '@/lib/auth-fetch';
import { WarehouseSelect } from '@/components/ui/warehouse-select';
import { CurrencySelect } from '@/components/ui/currency-select';
import type { InboundFormData, Supplier, PurchaseOrder } from '../../types';
import { INITIAL_FORM_DATA } from '../../types';

interface AddDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  formData: InboundFormData;
  setFormData: React.Dispatch<React.SetStateAction<InboundFormData>>;
  suppliers: Supplier[];
  poSearchResults: PurchaseOrder[];
  poSearchLoading: boolean;
  poDropdownVisible: boolean;
  setPoDropdownVisible: React.Dispatch<React.SetStateAction<boolean>>;
  handlePoSearchChange: (value: string) => void;
  handlePoSelect: (po: Loose) => void;
  onSuccess: () => void;
}

export function AddDialog({
  open,
  onOpenChange,
  formData,
  setFormData,
  suppliers,
  poSearchResults,
  poSearchLoading,
  poDropdownVisible,
  setPoDropdownVisible,
  handlePoSearchChange,
  handlePoSelect,
  onSuccess,
}: AddDialogProps) {
  const t = useTranslations('Warehouse');
  const tc = useTranslations('Common');

  const resetForm = () => setFormData({ ...INITIAL_FORM_DATA });

  const handleCancel = () => {
    onOpenChange(false);
    resetForm();
  };

  const handleSubmit = async () => {
    if (!formData.materialName || !formData.quantity) {
      toast.error(t('materialNameRequired'));
      return;
    }
    try {
      const response = await authFetch('/api/warehouse/inbound', {
        method: 'POST',
        body: JSON.stringify({
          warehouse_id: formData.warehouse || null,
          supplier_name: formData.supplier,
          inbound_date: new Date().toISOString().split('T')[0],
          currency: formData.currency,
          remark: formData.remark,
          items: [
            {
              material_id: formData.materialCode || 0,
              material_name: formData.materialName,
              material_spec: formData.specification,
              batch_no: formData.batchNo,
              quantity: parseFloat(formData.quantity),
              unit: formData.unit || '卷',
              unit_price: 0,
            },
          ],
        }),
      });
      const result = await response.json();
      if (result.success) {
        toast.success(t('inboundOrderCreated'));
        onOpenChange(false);
        resetForm();
        onSuccess();
      } else {
        toast.error(result.message || t('createInboundFailed'));
      }
    } catch {
      toast.error(t('createInboundFailed'));
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto" resizable>
        <DialogHeader>
          <DialogTitle>{t('addInboundOrder')}</DialogTitle>
          <DialogDescription>{t('enterInboundInfo')}</DialogDescription>
        </DialogHeader>
        <div className="space-y-4 py-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="add-materialCode">{tc('materialCode')}</Label>
              <Input
                id="add-materialCode"
                value={formData.materialCode}
                onChange={(e) => setFormData((prev) => ({ ...prev, materialCode: e.target.value }))}
                placeholder={t('enterMaterialCode')}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="add-materialName">{tc('materialName')}</Label>
              <Input
                id="add-materialName"
                value={formData.materialName}
                onChange={(e) => setFormData((prev) => ({ ...prev, materialName: e.target.value }))}
                placeholder={t('enterMaterialName')}
              />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="add-specification">{tc('specification')}</Label>
              <Input
                id="add-specification"
                value={formData.specification}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, specification: e.target.value }))
                }
                placeholder={t('specExample2')}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="add-quantity">{tc('quantity')}</Label>
              <Input
                id="add-quantity"
                type="number"
                value={formData.quantity}
                onChange={(e) => setFormData((prev) => ({ ...prev, quantity: e.target.value }))}
                placeholder={t('enterQuantity')}
              />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="add-unit">{tc('unit')}</Label>
              <Select
                value={formData.unit}
                onValueChange={(value) => setFormData((prev) => ({ ...prev, unit: value }))}
              >
                <SelectTrigger id="add-unit">
                  <SelectValue placeholder={t('selectUnit')} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="卷">{t('unitRoll')}</SelectItem>
                  <SelectItem value="张">{t('unitSheet')}</SelectItem>
                  <SelectItem value="个">{t('unitPiece')}</SelectItem>
                  <SelectItem value="箱">{t('unitBox')}</SelectItem>
                  <SelectItem value="kg">{t('unitKg')}</SelectItem>
                  <SelectItem value="㎡">{t('unitSqm')}</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="add-supplier">{tc('supplier')}</Label>
              <Select
                value={formData.supplier}
                onValueChange={(value) => setFormData((prev) => ({ ...prev, supplier: value }))}
              >
                <SelectTrigger id="add-supplier">
                  <SelectValue placeholder={t('selectSupplier')} />
                </SelectTrigger>
                <SelectContent>
                  {suppliers
                    .filter((s: Loose) => s.status !== 0 && s.status !== 'inactive')
                    .map((s: Loose) => (
                      <SelectItem key={s.id} value={s.name || s.supplier_name}>
                        {s.name || s.supplier_name}
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="add-warehouse">{tc('warehouse')}</Label>
              <WarehouseSelect
                value={formData.warehouse}
                onChange={(warehouseId) =>
                  setFormData((prev) => ({ ...prev, warehouse: warehouseId }))
                }
                placeholder={t('selectWarehouse')}
                className="w-full"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="add-purchaseOrderNo">{t('purchaseOrderNo')}</Label>
              <div className="relative">
                <Input
                  id="add-purchaseOrderNo"
                  value={formData.purchaseOrderNo}
                  onChange={(e) => handlePoSearchChange(e.target.value)}
                  onFocus={() => {
                    if (poSearchResults.length > 0) setPoDropdownVisible(true);
                  }}
                  onBlur={() => {
                    setTimeout(() => setPoDropdownVisible(false), 200);
                  }}
                  placeholder={t('searchPurchaseOrderNo')}
                  autoComplete="off"
                />
                {poSearchLoading && (
                  <div className="absolute right-3 top-1/2 -translate-y-1/2">
                    <RefreshCw className="h-4 w-4 animate-spin text-gray-400" />
                  </div>
                )}
                {poDropdownVisible && poSearchResults.length > 0 && (
                  <div className="absolute z-50 w-full mt-1 bg-card border rounded-md shadow-lg max-h-60 overflow-y-auto">
                    {poSearchResults.map((po: Loose) => (
                      <div
                        key={po.id}
                        className="px-3 py-2 hover:bg-blue-50 dark:hover:bg-slate-700 cursor-pointer border-b last:border-b-0 transition-colors dark:border-slate-700"
                        onMouseDown={() => handlePoSelect(po)}
                      >
                        <div className="flex items-center justify-between">
                          <span className="font-mono text-sm font-medium text-blue-600">
                            {po.po_no}
                          </span>
                          <span className="text-xs text-gray-400">{po.order_date || ''}</span>
                        </div>
                        <div className="flex items-center gap-3 mt-1">
                          <span className="text-xs text-gray-500">
                            {tc('supplier')}: {po.supplier_name || '-'}
                          </span>
                          <span className="text-xs text-gray-500">
                            {tc('quantity')}: {po.total_quantity || 0}
                          </span>
                          <span className="text-xs text-gray-500">
                            {tc('amount')}: ¥{Number(po.grand_total || 0).toFixed(2)}
                          </span>
                        </div>
                        {po.lines && po.lines.length > 0 && (
                          <div className="mt-1 text-xs text-gray-400">
                            {po.lines.slice(0, 2).map((line: Loose, idx: number) => (
                              <span key={idx} className="mr-2">
                                {line.material_name || line.material_code}
                                {line.order_qty ? ` ×${line.order_qty}${line.unit || ''}` : ''}
                              </span>
                            ))}
                            {po.lines.length > 2 && (
                              <span>{t('andMoreItems', { count: po.lines.length })}</span>
                            )}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="add-batchNo">{tc('batchNo')}</Label>
              <Input
                id="add-batchNo"
                value={formData.batchNo}
                onChange={(e) => setFormData((prev) => ({ ...prev, batchNo: e.target.value }))}
                placeholder={t('enterBatchNo')}
              />
            </div>
            <div className="space-y-2">
              <Label>{tc('currency')}</Label>
              <CurrencySelect
                value={formData.currency}
                onChange={(value) => setFormData((prev) => ({ ...prev, currency: value }))}
              />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="add-remark">{tc('remark')}</Label>
              <Input
                id="add-remark"
                value={formData.remark}
                onChange={(e) => setFormData((prev) => ({ ...prev, remark: e.target.value }))}
                placeholder={t('remarkPlaceholder')}
              />
            </div>
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={handleCancel}>
            {tc('cancel')}
          </Button>
          <Button onClick={handleSubmit}>{t('confirmInbound')}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';
import { useTranslations } from 'next-intl';
import { toast } from 'sonner';
import { authFetch } from '@/lib/auth-fetch';
import type { InboundRecord } from '../../types';

interface AuditDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  currentRecord: InboundRecord | null;
  onSuccess: () => void;
}

export function AuditDialog({ open, onOpenChange, currentRecord, onSuccess }: AuditDialogProps) {
  const t = useTranslations('Warehouse');
  const tc = useTranslations('Common');
  const [generateQr, setGenerateQr] = useState(true);

  const handleReject = async () => {
    if (!currentRecord) return;
    try {
      const response = await authFetch('/api/warehouse/inbound', {
        method: 'PUT',
        body: JSON.stringify({ id: currentRecord.id, status: 'rejected' }),
      });
      const result = await response.json();
      if (result.success) {
        toast.success(t('auditRejected'));
        onOpenChange(false);
        onSuccess();
      } else {
        toast.error(result.message || tc('error'));
      }
    } catch {
      toast.error(tc('error'));
    }
  };

  const handleApprove = async () => {
    if (!currentRecord) return;
    try {
      const response = await authFetch('/api/warehouse/inbound', {
        method: 'PUT',
        body: JSON.stringify({ id: currentRecord.id, status: 'approved' }),
      });
      const result = await response.json();
      if (result.success) {
        toast.success(t('auditApproved'));
        onOpenChange(false);
        onSuccess();

        if (generateQr && currentRecord.items?.length) {
          try {
            const qrRes = await authFetch('/api/trace/qr/generate', {
              method: 'POST',
              body: JSON.stringify({
                items: currentRecord.items.map((item: Loose) => ({
                  materialId: item.material_id,
                  materialName: item.material_name,
                  batchNo: item.batch_no || '',
                  quantity: item.quantity || 0,
                  count: 1,
                })),
                operator: currentRecord.operator_name || '系统管理员',
              }),
            });
            const qrResult = await qrRes.json();
            if (qrResult.success) {
              toast.success(t('qrCodeGenerated'));
            }
          } catch {
            toast.error(t('qrCodeGenerateFailed'));
          }
        }
      } else {
        toast.error(result.message || tc('error'));
      }
    } catch {
      toast.error(tc('error'));
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md" resizable>
        <DialogHeader>
          <DialogTitle>{t('auditInboundOrder')}</DialogTitle>
          <DialogDescription>
            {t('confirmAuditOrder', { orderNo: currentRecord?.order_no || '' })}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4 py-4">
          {currentRecord && (
            <div className="space-y-3 text-sm">
              <div className="flex justify-between">
                <span className="text-gray-500">{tc('material')}：</span>
                <span>{currentRecord.items?.[0]?.material_name || '-'}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-500">{tc('specification')}：</span>
                <span>{currentRecord.items?.[0]?.material_spec || '-'}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-500">{tc('quantity')}：</span>
                <span>
                  {currentRecord.total_quantity} {t('pieces')}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-500">{tc('supplier')}：</span>
                <span>{currentRecord.supplier_name}</span>
              </div>
            </div>
          )}
        </div>
        <div className="flex items-center gap-2 py-2">
          <Checkbox
            id="generateQr"
            checked={generateQr}
            onCheckedChange={(v) => setGenerateQr(!!v)}
          />
          <Label htmlFor="generateQr" className="text-sm cursor-pointer">
            {t('generateQrOnApprove')}
          </Label>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            {tc('cancel')}
          </Button>
          <Button variant="destructive" onClick={handleReject}>
            {tc('reject')}
