              <Input
                value={formData.specification}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, specification: e.target.value }))
                }
              />
            </div>
            <div className="space-y-2">
              <Label>{tc('quantity')}</Label>
              <Input
                type="number"
