'use client';

import { useState, useEffect } from 'react';
import QRCode from 'qrcode';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Printer, Loader2, QrCode } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { toast } from 'sonner';
import type { PrintLabel } from '../../types';

interface PrintPreviewDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  printLabels: PrintLabel[];
}

export function PrintPreviewDialog({ open, onOpenChange, printLabels }: PrintPreviewDialogProps) {
  const t = useTranslations('Warehouse');
  const tc = useTranslations('Common');
  const [isGenerating, setIsGenerating] = useState(false);
  const [qrDataUrls, setQrDataUrls] = useState<Record<string, string>>({});
  const [qrLoading, setQrLoading] = useState(false);

  useEffect(() => {
    if (!open) {
      setQrDataUrls({});
      return;
    }
    let cancelled = false;
    setQrLoading(true);
    (async () => {
      const map: Record<string, string> = {};
      for (const label of printLabels) {
        if (cancelled) return;
        const key = label.id || label.labelNo;
        if (map[key]) continue;
        try {
          const qrContent = `${label.labelNo || label.orderNo}@001:type:IN`;
          map[key] = await QRCode.toDataURL(qrContent, { width: 120, margin: 1 });
        } catch {
          /* ignore */
        }
      }
      if (!cancelled) {
        setQrDataUrls(map);
        setQrLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [open, printLabels]);

  const handlePrint = async () => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      toast.error(t('printWindowBlocked'));
      return;
    }
    setIsGenerating(true);
    try {
      const labelsHtml = await Promise.all(
        printLabels.map(async (label) => {
          const qrContent = `${label.labelNo || label.orderNo}@001:type:IN`;
          let qrDataUrl = '';
          try {
            qrDataUrl = await QRCode.toDataURL(qrContent, { width: 100, margin: 1 });
          } catch {
            // ignore
          }

          return `
                    <div class="label-card">
                      <div class="label-header">
                        <div class="label-title">
                          <div class="label-no">${label.labelNo}</div>
                          <div class="material-name">${label.materialName}</div>
                        </div>
                        <div class="status-badge">已入库</div>
                      </div>
                      <div class="label-info">
                        <div class="info-row"><span class="info-label">入库单号：</span><span class="info-value">${label.orderNo}</span></div>
                        <div class="info-row"><span class="info-label">规格：</span><span class="info-value">${label.specification || '-'}</span></div>
                        <div class="info-row"><span class="info-label">数量/单位：</span><span class="info-value">${label.quantity || label.item?.quantity || 0} ${label.unit || label.item?.unit || ''}</span></div>
                        <div class="info-row"><span class="info-label">供应商：</span><span class="info-value">${label.supplier || '-'}</span></div>
                        <div class="info-row"><span class="info-label">入库时间：</span><span class="info-value">${label.inboundTime ? new Date(label.inboundTime).toLocaleString('zh-CN') : '-'}</span></div>
                      </div>
                      <div class="qr-area">
                        ${qrDataUrl ? `<img src="${qrDataUrl}" alt="QR" style="width:80px;height:80px;" />` : ''}
                      </div>
                    </div>
                  `;
        })
      );

      const html = `<!DOCTYPE html>
<html>
<head>
  <title>二维码标签打印</title>
  <style>
    @page { size: A4; margin: 8mm; }
    body { font-family: 'Microsoft YaHei', Arial, sans-serif; margin: 0; padding: 0; }
    .label-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6mm; }
    .label-card {
      border: 2px solid #333; border-radius: 6px; padding: 4mm;
      page-break-inside: avoid; min-height: 55mm; display: flex; flex-direction: column;
    }
    .label-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 2mm; }
    .label-title { flex: 1; }
    .label-no { font-size: 13px; font-weight: bold; color: #111; }
    .material-name { font-size: 11px; font-weight: 600; color: #333; margin-top: 1mm; }
    .status-badge {
      background: #d1fae5; color: #065f46; font-size: 8px; font-weight: bold;
      padding: 1px 5px; border-radius: 8px; white-space: nowrap; margin-left: 2mm;
    }
    .label-info { flex: 1; }
    .info-row { display: flex; justify-content: space-between; font-size: 9px; color: #555; margin: 0.5mm 0; }
    .info-label { color: #888; }
    .info-value { font-weight: 500; color: #333; }
    .qr-area { text-align: center; margin-top: 2mm; }
  </style>
</head>
<body>
  <div class="label-grid">
    ${labelsHtml.join('')}
  </div>
  <script>
    window.onload = function() { window.print(); }
  </script>
</body>
</html>`;
      printWindow.document.write(html);
      printWindow.document.close();
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-4xl max-h-[90vh] overflow-y-auto" resizable>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Printer className="h-5 w-5" />
            {t('qrCodeLabelPrintPreview')}
          </DialogTitle>
          <DialogDescription>{t('labelsToPrint', { count: printLabels.length })}</DialogDescription>
        </DialogHeader>
        <div id="print-area" className="py-4">
          <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
            {printLabels.map((label, index) => {
              return (
                <div
                  key={label.id || index}
                  className="border-2 border-gray-800 rounded-lg p-3 print-label-card"
                  style={{ minHeight: '180px' }}
                >
                  <div className="flex items-start justify-between mb-2">
                    <div className="flex-1">
                      <h3 className="font-bold text-base text-gray-900 dark:text-gray-100">
                        {label.labelNo}
                      </h3>
                      <p className="text-sm font-medium text-gray-800 dark:text-gray-200 mt-1">
                        {label.materialName}
                      </p>
                    </div>
                    <Badge className="bg-green-100 text-green-700 text-xs shrink-0 ml-2">
                      {tc('stockedIn')}
                    </Badge>
                  </div>
                  <div className="space-y-1 text-xs text-gray-600">
                    <div className="flex justify-between">
                      <span>{t('inboundNo')}：</span>
                      <span className="font-medium">{label.orderNo}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>{tc('specification')}：</span>
                      <span>{label.specification || '-'}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>{t('qtyUnit')}：</span>
                      <span className="font-medium">
                        {label.quantity || label.item?.quantity || 0}{' '}
                        {label.unit || label.item?.unit || ''}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span>{tc('supplier')}：</span>
                      <span>{label.supplier || '-'}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>{t('inboundTime')}：</span>
                      <span>
                        {label.inboundTime
                          ? new Date(label.inboundTime).toLocaleString('zh-CN')
                          : '-'}
                      </span>
                    </div>
                  </div>
                  <div className="mt-2 flex justify-center">
                    {qrLoading ? (
                      <Loader2 className="h-12 w-12 animate-spin text-muted-foreground" />
                    ) : qrDataUrls[label.id || label.labelNo] ? (
                      <img
                        src={qrDataUrls[label.id || label.labelNo]}
                        alt="QR"
                        className="w-16 h-16"
                      />
                    ) : (
                      <QrCode className="h-12 w-12 text-muted-foreground/40" />
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
        <DialogFooter className="flex gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            {tc('cancel')}
          </Button>
          <Button
            className="gap-2 bg-blue-600 hover:bg-blue-700"
            onClick={handlePrint}
            disabled={isGenerating}
          >
            <Printer className="w-4 h-4" />
            {tc('print')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Scissors, Search, Package, CheckCircle2, AlertCircle } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { authFetch } from '@/lib/auth-fetch';
import type { SourceLabelData } from '../../types';

interface SourceLabelQueryDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onLabelFound: (label: SourceLabelData) => void;
}

export function SourceLabelQueryDialog({
  open,
  onOpenChange,
  onLabelFound,
}: SourceLabelQueryDialogProps) {
  const t = useTranslations('Warehouse');
  const tc = useTranslations('Common');

  const [labelCode, setLabelCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [foundLabel, setFoundLabel] = useState<SourceLabelData | null>(null);
  const [error, setError] = useState('');

  const handleQuery = async () => {
    const code = labelCode.trim();
    if (!code) {
      setError('请输入或扫描标签编号');
      return;
    }

    setLoading(true);
    setError('');
    setFoundLabel(null);

    try {
      const response = await authFetch(
        `/api/warehouse/inbound/cutting?labelNo=${encodeURIComponent(code)}`
      );
      const result = await response.json();

      if (result.success) {
        setFoundLabel(result.data);
      } else {
        setError(result.message || '查询失败');
      }
    } catch {
      setError('网络错误，请重试');
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleQuery();
    }
  };

  const handleNext = () => {
    if (foundLabel) {
      onLabelFound(foundLabel);
      setLabelCode('');
      setFoundLabel(null);
      setError('');
    }
  };

  const handleClose = () => {
    setLabelCode('');
    setFoundLabel(null);
    setError('');
    onOpenChange(false);
  };

  const parsedWidth = foundLabel?.specification
    ? (() => {
        const match = foundLabel.specification.match(
          /^(\d+(?:\.\d+)?)\s*[×xX*]\s*(\d+(?:\.\d+)?)\s*(mm|m)?$/i
        );
        return match ? match[1] : null;
      })()
    : null;

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Scissors className="h-5 w-5" />
            {t('materialCutting')}
          </DialogTitle>
          <DialogDescription>
            {'请输入或扫描母材标签编号，系统将自动校验是否可分切'}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <Label>{t('sourceLabelNo')}</Label>
            <div className="flex gap-2">
              <Input
                placeholder="输入标签编号或扫码"
                value={labelCode}
                onChange={(e) => setLabelCode(e.target.value)}
                onKeyDown={handleKeyDown}
                autoFocus
              />
              <Button onClick={handleQuery} disabled={loading} className="shrink-0 gap-2">
                <Search className="h-4 w-4" />
                {tc('search')}
              </Button>
            </div>
          </div>

          {loading && (
            <div className="flex items-center justify-center py-6">
              <div
                className="h-6 w-6 animate-spin rounded-full border-2"
                style={{ borderColor: 'rgba(6,182,212,0.2)', borderTopColor: 'rgba(6,182,212,1)' }}
              />
            </div>
          )}

          {error && (
            <div className="flex items-start gap-3 rounded-lg border border-red-200 bg-red-50 p-4">
              <AlertCircle className="h-5 w-5 shrink-0 text-red-500" />
              <div>
                <p className="text-sm font-medium text-red-700">{t('queryFailed')}</p>
                <p className="text-sm text-red-600 mt-1">{error}</p>
              </div>
            </div>
          )}

          {foundLabel && (
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <CheckCircle2 className="h-5 w-5 text-green-500" />
                <span className="text-sm font-medium text-green-700">{'校验通过'}</span>
              </div>
              <div className="rounded-lg border border-green-200 bg-green-50 p-4 space-y-2">
                <div className="flex items-center gap-2 mb-2">
                  <Package className="h-4 w-4 text-blue-600" />
                  <span className="font-medium">{t('sourceLabelInfo')}</span>
                </div>
                <div className="grid grid-cols-2 gap-2 text-sm">
                  <div className="flex items-center gap-1">
                    <span className="text-gray-500">{t('labelNo')}：</span>
                    <span className="font-mono font-medium">{foundLabel.labelNo}</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <span className="text-gray-500">{tc('materialName')}：</span>
                    <span className="font-medium">{foundLabel.materialName}</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <span className="text-gray-500">{tc('specification')}：</span>
                    <span className="font-medium">{foundLabel.specification || '-'}</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <span className="text-gray-500">{t('originalWidth')}：</span>
                    <span className="font-medium">
                      {parsedWidth ? `${parsedWidth}mm` : t('notParsed')}
                    </span>
                  </div>
                  <div className="flex items-center gap-1">
                    <span className="text-gray-500">{tc('quantity')}：</span>
                    <span className="font-medium">
                      {foundLabel.quantity} {foundLabel.unit || ''}
                    </span>
                  </div>
                  <div className="flex items-center gap-1">
                    <span className="text-gray-500">{tc('supplier')}：</span>
                    <span className="font-medium">{foundLabel.supplierName || '-'}</span>
                  </div>
                </div>
              </div>
              <Badge className="bg-green-100 text-green-700 border-0">
                <CheckCircle2 className="h-3 w-3 mr-1" />
                {'可分切'}
              </Badge>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose}>
            {tc('cancel')}
          </Button>
          <Button
            onClick={handleNext}
            disabled={!foundLabel}
            className="bg-blue-600 hover:bg-blue-700 gap-2"
          >
            <Scissors className="h-4 w-4" />
            {'下一步分切'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { authFetch } from '@/lib/auth-fetch';
import { useState, useEffect } from 'react';
import { MainLayout } from '@/components/layout';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Search, RefreshCw, Trash2, Scissors } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { Checkbox } from '@/components/ui/checkbox';
import { useTranslations } from 'next-intl';
import { GlobalExportToolbar } from '@/components/ui/global-export-toolbar';

// 分切记录类型
interface CuttingRecord {
  id: number;
  recordNo: string;
  sourceLabelId: number;
  sourceLabelNo: string;
  cutWidthStr: string;
  originalWidth: number;
  cutTotalWidth: number;
  remainWidth: number;
  operatorId: number;
  operatorName: string;
  cutTime: string;
  remark: string;
  status: string;
  createTime: string;
  materialCode: string;
  materialName: string;
  specification: string;
}

export default function CuttingRecordsPage() {
  // 翻译钩子
  const t = useTranslations('Warehouse');
  const tc = useTranslations('Common');

  // 状态徽章
  const getStatusBadge = (status: string) => {
    const statusMap: Record<string, { label: string; className: string }> = {
      active: {
        label: tc('normal'),
        className: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300',
      },
      frozen: {
        label: tc('frozen'),
        className: 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-300',
      },
      disabled: {
        label: tc('disabled'),
        className: 'bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-200',
      },
    };
    const config = statusMap[status] || {
      label: status,
      className: 'bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-200',
    };
    return <Badge className={config.className}>{config.label}</Badge>;
  };

  const { user: _user } = useAuth();
  const [records, setRecords] = useState<CuttingRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [keyword, setKeyword] = useState('');
  const [sourceLabelNo, setSourceLabelNo] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize] = useState(20);
  const [total, setTotal] = useState(0);
  const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set());

  const _exportColumns = [
    { key: 'recordNo', header: t('recordNoCol') },
    { key: 'sourceLabelNo', header: t('sourceLabelNoCol') },
    { key: 'materialName', header: t('materialName') },
    { key: 'materialCode', header: t('materialCode') },
    { key: 'specification', header: t('specification') },
    { key: 'originalWidth', header: t('originalWidthMM') },
    { key: 'cutWidth', header: t('cutWidthMM') },
    { key: 'cutTotal', header: t('cutTotalMM') },
    { key: 'remainWidth', header: t('remainWidthMM') },
    { key: 'operator', header: t('operator') },
    { key: 'cutTime', header: t('cutTime') },
    { key: tc('status'), header: tc('status') },
  ];
  const _getExportData = () =>
    records.map((r) => ({
      recordNo: r.recordNo,
      sourceLabelNo: r.sourceLabelNo,
      materialName: r.materialName,
      materialCode: r.materialCode,
      specification: r.specification,
      originalWidth: r.originalWidth,
      cutWidth: r.cutWidthStr,
      cutTotal: r.cutTotalWidth,
      remainWidth: r.remainWidth,
      operator: r.operatorName,
      cutTime: new Date(r.cutTime).toLocaleString(),
      status:
        r.status === 'active'
          ? tc('normal')
          : r.status === 'frozen'
            ? tc('frozen')
            : tc('disabled'),
    }));

  useEffect(() => {
    const controller = new AbortController();

    const fetchData = async () => {
      try {
        setLoading(true);
        const params = new URLSearchParams();
        if (keyword) params.append('keyword', keyword);
        if (sourceLabelNo) params.append('sourceLabelNo', sourceLabelNo);
        params.append('page', page.toString());
        params.append('pageSize', pageSize.toString());

        const response = await authFetch(`/api/warehouse/inbound/cutting?${params}`, {
          signal: controller.signal,
        });

        if (!response.ok) {
          throw new Error(`API 响应错误: ${response.status}`);
        }

        const result = await response.json();

        if (result.success) {
          setRecords(result.data?.list || []);
          setTotal(result.data?.pagination?.total || 0);
        }
      } catch (error) {
        if ((error as Error).name !== 'AbortError') {
        }
      } finally {
        setLoading(false);
      }
    };

    fetchData();

    return () => controller.abort();
  }, [page, keyword, sourceLabelNo]);

  const handleSearch = () => {
    setPage(1);
  };

  const handleReset = () => {
    setKeyword('');
    setSourceLabelNo('');
    setPage(1);
  };

  return (
    <MainLayout title={t('cuttingRecordManagement')}>
      <div className="space-y-6">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Scissors className="h-5 w-5" />
              {t('cuttingRecordQuery')}
            </CardTitle>
            <CardDescription>{t('cuttingRecordQueryDesc')}</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex flex-wrap gap-4 items-end">
              <div className="flex-1 min-w-[200px]">
                <label className="text-sm font-medium mb-2 block">{t('keyword')}</label>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    placeholder={t('keywordPlaceholder')}
                    className="pl-10"
                    value={keyword}
                    onChange={(e) => setKeyword(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                  />
                </div>
              </div>
              <div className="flex-1 min-w-[200px]">
                <label className="text-sm font-medium mb-2 block">{t('sourceLabelNo')}</label>
                <Input
                  placeholder={t('inputSourceLabelNo')}
                  value={sourceLabelNo}
                  onChange={(e) => setSourceLabelNo(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                />
              </div>
              <div className="flex gap-2">
                <Button variant="outline" onClick={handleReset}>
                  <Trash2 className="h-4 w-4 mr-2" />
                  {t('reset')}
                </Button>
                <Button onClick={handleSearch}>
                  <Search className="h-4 w-4 mr-2" />
                  {t('query')}
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <div>
                <CardTitle>{t('cuttingRecords')}</CardTitle>
                <CardDescription>{t('recordCount', { count: total })}</CardDescription>
              </div>
              <div className="flex gap-2">
                <GlobalExportToolbar
                  filename="分切记录"
                  title="分切记录"
                  landscape
                  columns={[
                    { key: 'recordNo', label: t('recordNoCol'), width: 15 },
                    { key: 'sourceLabelNo', label: t('sourceLabelNoCol'), width: 15 },
                    { key: 'materialName', label: t('materialName'), width: 18 },
                    { key: 'materialCode', label: t('materialCode'), width: 15 },
                    { key: 'specification', label: t('specification'), width: 12 },
                    { key: 'originalWidth', label: t('originalWidthMM'), width: 12 },
                    { key: 'cutWidthStr', label: t('cutWidthMM'), width: 12 },
                    { key: 'cutTotalWidth', label: t('cutTotalMM'), width: 12 },
                    { key: 'remainWidth', label: t('remainWidthMM'), width: 12 },
                    { key: 'operatorName', label: t('operator'), width: 10 },
                    {
                      key: 'cutTime',
                      label: t('cutTime'),
                      width: 18,
                      formatter: (v) => new Date(v).toLocaleString(),
                    },
                    {
                      key: 'status',
                      label: tc('status'),
                      width: 10,
                      formatter: (v) =>
                        v === 'active'
                          ? tc('normal')
                          : v === 'frozen'
                            ? tc('frozen')
                            : tc('disabled'),
                    },
                  ]}
                  data={
                    selectedIds.size > 0 ? records.filter((r) => selectedIds.has(r.id)) : records
                  }
                />
                <Button variant="outline" onClick={() => setPage((prevPage) => prevPage)}>
                  <RefreshCw className="h-4 w-4 mr-2" />
                  {t('refresh')}
                </Button>
              </div>
            </div>
          </CardHeader>
          <CardContent>
            <div className="border rounded-lg">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="w-[40px]">
                      <Checkbox
                        checked={selectedIds.size > 0 && selectedIds.size === records.length}
                        onCheckedChange={(checked) => {
                          if (checked) setSelectedIds(new Set(records.map((r) => r.id)));
                          else setSelectedIds(new Set());
                        }}
                      />
                    </TableHead>
                    <TableHead>{t('recordNoCol')}</TableHead>
                    <TableHead>{t('sourceLabelNoCol')}</TableHead>
                    <TableHead>{t('materialInfo')}</TableHead>
                    <TableHead>{t('originalWidthMM')}</TableHead>
                    <TableHead>{t('cutWidthMM')}</TableHead>
                    <TableHead>{t('cutTotalMM')}</TableHead>
                    <TableHead>{t('remainWidthMM')}</TableHead>
                    <TableHead>{t('operator')}</TableHead>
                    <TableHead>{t('cutTime')}</TableHead>
                    <TableHead>{tc('status')}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {loading ? (
                    <TableRow>
                      <TableCell colSpan={11} className="text-center py-8">
                        {t('loading')}
                      </TableCell>
                    </TableRow>
                  ) : records.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={11} className="text-center py-8">
                        {t('noData')}
                      </TableCell>
                    </TableRow>
                  ) : (
                    records.map((record) => (
                      <TableRow key={record.id}>
                        <TableCell>
                          <Checkbox
                            checked={selectedIds.has(record.id)}
                            onCheckedChange={(checked) => {
                              const next = new Set(selectedIds);
                              if (checked) next.add(record.id);
                              else next.delete(record.id);
                              setSelectedIds(next);
                            }}
                          />
                        </TableCell>
                        <TableCell className="font-medium">{record.recordNo}</TableCell>
                        <TableCell>{record.sourceLabelNo}</TableCell>
                        <TableCell>
                          <div className="space-y-1">
                            <div className="font-medium">{record.materialName}</div>
                            <div className="text-sm text-muted-foreground">
                              {record.materialCode}
                            </div>
                            <div className="text-sm text-muted-foreground">
                              {record.specification}
                            </div>
                          </div>
                        </TableCell>
                        <TableCell>{record.originalWidth}mm</TableCell>
                        <TableCell>{record.cutWidthStr}mm</TableCell>
                        <TableCell>{record.cutTotalWidth}mm</TableCell>
                        <TableCell>{record.remainWidth}mm</TableCell>
                        <TableCell>{record.operatorName}</TableCell>
                        <TableCell>{new Date(record.cutTime).toLocaleString()}</TableCell>
                        <TableCell>{getStatusBadge(record.status)}</TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </div>

            {/* 分页 */}
            {total > pageSize && (
              <div className="flex items-center justify-between mt-4">
                <div className="text-sm text-muted-foreground">
                  {t('pageOf', { page, pages: Math.ceil(total / pageSize) })}
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setPage((p) => Math.max(1, p - 1))}
                    disabled={page === 1}
                  >
                    {tc('prevPage')}
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setPage((p) => p + 1)}
                    disabled={page * pageSize >= total}
                  >
                    {tc('nextPage')}
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </MainLayout>
  );
}

'use client';

import { useState, useCallback } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import { toast } from 'sonner';
import { useTranslations } from 'next-intl';
import { authFetch } from '@/lib/auth-fetch';
import { logger } from '@/lib/logger';
import type { CuttingFormData, PrintLabel } from '../types';
import { isCuttableMaterial, parseSpecWidth, calcCutSpec } from '../types';

interface UseCuttingDeps {
  currentLabel: PrintLabel | null;
  user: { id?: string | number; realName?: string; username?: string } | null;
  fetchInboundRecords: () => Promise<void>;
  setPrintLabels: Dispatch<SetStateAction<PrintLabel[]>>;
  setIsCuttingResultOpen: Dispatch<SetStateAction<boolean>>;
  setIsCuttingDialogOpen: Dispatch<SetStateAction<boolean>>;
}

export function useCutting(deps: UseCuttingDeps) {
  const t = useTranslations('Warehouse');
  const {
    currentLabel,
    user,
    fetchInboundRecords,
    setPrintLabels,
    setIsCuttingResultOpen,
    setIsCuttingDialogOpen,
  } = deps;

  const [cuttingForm, setCuttingForm] = useState<CuttingFormData>({
    sourceLabelId: '',
    cutWidths: '',
    operatorId: user?.id || '',
    operatorName: user?.realName || user?.username || '',
    remark: '',
  });

  const handleCutting = useCallback(async () => {
    const ctx = { module: 'Warehouse', action: 'handleCutting' };
    logger.stepStart(ctx, 'handleCutting', {
      labelId: currentLabel?.id,
      labelNo: currentLabel?.labelNo,
      cutWidths: cuttingForm.cutWidths,
      operatorId: cuttingForm.operatorId,
    });

    // 校验分支1: 是否选中标签
    if (!currentLabel) {
      logger.branch(ctx, 'validate', 'currentLabel != null', false);
      toast.error(t('selectCutLabel'));
      return;
    }
    logger.branch(ctx, 'validate', 'currentLabel != null', true, {
      materialName: currentLabel.materialName,
      specification: currentLabel.specification,
    });

    // 校验分支2: 物料是否可分切
    const materialNameForCheck = currentLabel.materialName || '';
    if (!isCuttableMaterial(materialNameForCheck)) {
      logger.branch(ctx, 'validate', 'isCuttableMaterial', false, {
        materialName: materialNameForCheck,
      });
      toast.error(t('materialNotCuttable'));
      return;
    }
    logger.branch(ctx, 'validate', 'isCuttableMaterial', true);

    // 校验分支3: 是否填写分切宽度
    if (!cuttingForm.cutWidths.trim()) {
      logger.branch(ctx, 'validate', 'cutWidths not empty', false);
      toast.error(t('inputCutWidth'));
      return;
    }
    logger.branch(ctx, 'validate', 'cutWidths not empty', true, {
      cutWidths: cuttingForm.cutWidths,
    });

    try {
      // 解析分切宽度
      const widths = cuttingForm.cutWidths.split('+').map(Number);
      const hasInvalid = widths.some((w) => isNaN(w) || w <= 0);
      logger.info(ctx, '分切宽度解析', { widths, hasInvalid });
      if (hasInvalid) {
        logger.warn(ctx, '存在无效宽度值，将跳过规格校验', { widths });
      }

      // 规格宽度解析与校验
      const spec = currentLabel.specification || currentLabel.materialSpec || '';
      const specWidth = parseSpecWidth(spec);
      logger.info(ctx, '规格宽度解析', { spec, specWidth });
      if (specWidth !== null) {
        const totalCutWidth = widths.reduce((sum, w) => sum + w, 0);
        logger.branch(ctx, 'specCheck', 'totalCutWidth <= specWidth', totalCutWidth <= specWidth, {
          totalCutWidth,
          specWidth,
        });
        if (totalCutWidth > specWidth) {
          toast.error(t('specParseFailed'));
          return;
        }
      } else {
        logger.warn(ctx, '未能解析规格宽度，跳过总量校验', { spec });
      }

      // 组装请求数据
      const materialName =
        currentLabel.materialName ||
        currentLabel.material_name ||
        currentLabel.item?.material_name ||
        '';
      const recordId = currentLabel.record?.id || currentLabel.id;
      const itemIdx = currentLabel.item?.idx ?? currentLabel.itemIdx ?? 0;
      const numericRecordId =
        typeof recordId === 'string' ? parseInt(recordId.split('-')[0], 10) : recordId;
      const operatorId = cuttingForm.operatorId || user?.id || '1';
      const operatorName =
        cuttingForm.operatorName || user?.realName || user?.username || '系统管理员';

      const requestBody = {
        sourceLabelId: numericRecordId || null,
        sourceLabelNo: `${currentLabel.order_no || currentLabel.labelNo}-${itemIdx + 1}`,
        cutWidthStr: cuttingForm.cutWidths,
        operatorId: operatorId,
        operatorName: operatorName,
        remark: cuttingForm.remark,
        materialCode: currentLabel.material_code || currentLabel.item?.material_code || '',
        materialName: materialName,
        specification: currentLabel.material_spec || currentLabel.specification || '',
        quantity: currentLabel.quantity || currentLabel.item?.quantity || 0,
        unit: currentLabel.unit || currentLabel.item?.unit || '',
        supplierName: currentLabel.supplier_name || currentLabel.supplier || '',
        batchNo: currentLabel.batch_no || currentLabel.item?.batch_no || '',
        orderNo: currentLabel.order_no || currentLabel.orderNo || '',
        originalWidth: specWidth,
      };
      logger.info(ctx, '发送分切请求', {
        url: '/api/warehouse/inbound/cutting',
        sourceLabelId: requestBody.sourceLabelId,
        sourceLabelNo: requestBody.sourceLabelNo,
        cutWidthStr: requestBody.cutWidthStr,
        materialName: requestBody.materialName,
        originalWidth: requestBody.originalWidth,
      });

      const response = await authFetch('/api/warehouse/inbound/cutting', {
        method: 'POST',
        body: JSON.stringify(requestBody),
      });
      logger.info(ctx, '分切API响应', { status: response.status, ok: response.ok });

      const result = await response.json();
      if (result.success) {
        const newLabelCount = result.data?.newLabels?.length || 0;
        logger.stepEnd(ctx, 'handleCutting', {
          success: true,
          newLabelCount,
          newLabels: result.data?.newLabels,
        });
        toast.success(t('cutSuccess', { count: newLabelCount }));
        setIsCuttingDialogOpen(false);
        setCuttingForm((prev) => ({ ...prev, cutWidths: '', remark: '' }));

        // 生成子 QR 码
        try {
          const parentQrContent = currentLabel.batch_no || currentLabel.labelNo || '';
          const splits = result.data?.newLabels?.map((nl: Loose, i: number) => ({
            materialId: currentLabel.material_id || 0,
            materialName: currentLabel.materialName || currentLabel.material_name || '',
            batchNo: nl.batch_no || currentLabel.batch_no || '',
            quantity: nl.cutQty || nl.quantity || 0,
            splitIndex: i + 1,
          })) || [];
          if (splits.length > 0 && parentQrContent) {
            await authFetch('/api/trace/qr/split', {
              method: 'POST',
              body: JSON.stringify({
                parentQrContent,
                splits,
                operator: cuttingForm.operatorName || '系统管理员',
              }),
            });
            logger.info(ctx, '子QR码生成完成', { splitCount: splits.length });
          }
        } catch (qrErr) {
          logger.warn(ctx, '子QR码生成失败(不影响主流程)', { error: (qrErr as Error).message });
        }

        // 刷新入库单列表
        logger.info(ctx, '开始刷新入库单列表');
        await fetchInboundRecords();
        logger.info(ctx, '入库单列表刷新完成');

        // 映射新标签到 PrintLabel
        if (result.data?.newLabels && result.data.newLabels.length > 0) {
          logger.info(ctx, '开始映射分切结果到打印标签', { count: result.data.newLabels.length });
          const newPrintLabels = result.data.newLabels.map((nl: Loose, idx: number) => ({
            id: nl.id || `cut-${idx}`,
            labelNo:
              nl.labelNo ||
              nl.label_no ||
              `${currentLabel.order_no || currentLabel.labelNo}-C${idx + 1}`,
            orderNo: currentLabel.order_no || currentLabel.orderNo || currentLabel.labelNo || '',
            materialName: nl.isRemainder
              ? `${t('remainderMaterial')}${currentLabel.material_name || currentLabel.materialName || ''}`
              : currentLabel.material_name || currentLabel.materialName || '',
            specification:
              nl.newSpec ||
              nl.specification ||
              calcCutSpec(
                currentLabel.material_spec || currentLabel.specification || '',
                nl.cutWidth || nl.width || 0
              ),
            supplier: currentLabel.supplier_name || currentLabel.supplier || '',
            inboundTime: new Date().toISOString(),
            quantity: nl.cutQty || nl.quantity || 0,
            unit: currentLabel.unit || currentLabel.item?.unit || '',
            batchNo: currentLabel.batch_no || currentLabel.item?.batch_no || '',
            isCutLabel: true,
            cutWidth: nl.cutWidth || nl.width || 0,
            isRemainder: nl.isRemainder || false,
            sourceLabelNo: `${currentLabel.order_no || currentLabel.labelNo}-${(currentLabel.item?.idx ?? currentLabel.itemIdx ?? 0) + 1}`,
          }));
          logger.info(ctx, '分切结果映射完成', {
            mappedCount: newPrintLabels.length,
            labels: newPrintLabels.map((p: PrintLabel) => ({
              id: p.id,
              labelNo: p.labelNo,
              isRemainder: p.isRemainder,
              cutWidth: p.cutWidth,
              quantity: p.quantity,
            })),
          });
          setPrintLabels(newPrintLabels);
          setIsCuttingResultOpen(true);
          logger.info(ctx, '已打开分切结果对话框');
        } else {
          logger.warn(ctx, 'API返回成功但无新标签数据', { data: result.data });
        }
      } else {
        logger.error(ctx, '分切API返回失败', { message: result.message, code: result.code });
        toast.error(result.message || t('cutFailed'));
      }
    } catch (error) {
      logger.error(ctx, '分切过程异常', {
        error: (error as Error).message,
        stack: (error as Error).stack,
      });
      toast.error(t('cutFailed'));
    }
  }, [
    currentLabel,
    cuttingForm,
    user,
    t,
    fetchInboundRecords,
    setIsCuttingDialogOpen,
    setPrintLabels,
    setIsCuttingResultOpen,
  ]);

  return {
    cuttingForm,
    setCuttingForm,
    handleCutting,
  };
}

