          onOpenQRScanDialog={() => setIsQRScanDialogOpen(true)}
          onOpenSourceLabelQuery={() => setIsSourceLabelQueryOpen(true)}
          onPrintLabels={setPrintLabels}
          onOpenPrintPreview={() => setIsPrintPreviewOpen(true)}
