                                  supplier_name: label.supplier,
                                  order_no: label.orderNo,
                                  quantity: label.item?.quantity || 0,
                                  unit: label.item?.unit || '',
                                  batch_no: label.item?.batch_no || '',
                                  material_code: label.item?.material_code || '',
                                });
