import { NextRequest, NextResponse } from 'next/server';
import { query, execute } from '@/lib/db';
import { errorResponse, successResponse, commonErrors } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { checkRateLimit, getClientIP } from '@/lib/rate-limit';
import bcrypt from 'bcryptjs';

export const POST = withPermission(
  async (request: NextRequest, userInfo) => {
    // 限流：每 IP 15 分钟最多 10 次密码修改，防暴力篡改
    const clientIP = getClientIP(request);
    const rateResult = await checkRateLimit(clientIP, {
      windowMs: 15 * 60 * 1000,
      maxRequests: 10,
      keyPrefix: 'pwd-change',
    });
    if (!rateResult.allowed) {
      return NextResponse.json(
        {
          success: false,
          message: `操作过于频繁，请${Math.ceil(rateResult.retryAfterMs / 60000)}分钟后再试`,
        },
        {
          status: 429,
          headers: { 'Retry-After': String(Math.ceil(rateResult.retryAfterMs / 1000)) },
        }
      );
    }

    const body = await request.json();
    const { oldPassword, newPassword, targetUserId } = body;

    if (!oldPassword || !newPassword) {
      return errorResponse('缺少必填字段: oldPassword, newPassword', 400, 400);
    }

    // 默认改自己的密码；仅 admin 可指定 targetUserId 改他人密码
    const isAdmin = userInfo.roles.includes('admin') || userInfo.roles.includes('super_admin');
    const effectiveUserId = isAdmin && targetUserId ? Number(targetUserId) : userInfo.userId;

    if (!Number.isFinite(effectiveUserId)) {
      return errorResponse('targetUserId 必须为数字', 400, 400);
    }

    // 从系统配置读取密码策略
    let minLength = 6;
    let requireSpecialChar = false;
    let requireUpperCase = false;
    let _passwordExpireDays = 0;
    try {
      const configs: Loose = await query(
        'SELECT config_key, config_value FROM sys_config WHERE config_key IN (?, ?, ?, ?)',
        [
          'system.password_min_length',
          'system.password_require_special',
          'system.password_require_uppercase',
          'system.password_expire_days',
        ]
      );
      for (const cfg of configs) {
        if (cfg.config_key === 'system.password_min_length')
          minLength = parseInt(cfg.config_value) || 6;
        if (cfg.config_key === 'system.password_require_special')
          requireSpecialChar = cfg.config_value === 'true';
        if (cfg.config_key === 'system.password_require_uppercase')
          requireUpperCase = cfg.config_value === 'true';
        if (cfg.config_key === 'system.password_expire_days')
          _passwordExpireDays = parseInt(cfg.config_value) || 0;
      }
    } catch {
      // 使用默认值
    }

    if (newPassword.length < minLength) {
      return errorResponse(`新密码长度不能少于${minLength}位`, 400, 400);
    }

    if (!/[A-Za-z]/.test(newPassword) || !/[0-9]/.test(newPassword)) {
      return errorResponse('新密码必须包含字母和数字', 400, 400);
    }

    if (requireUpperCase && !/[A-Z]/.test(newPassword)) {
      return errorResponse('新密码必须包含大写字母', 400, 400);
    }

    if (requireSpecialChar && !/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(newPassword)) {
      return errorResponse('新密码必须包含特殊字符', 400, 400);
    }

    const users: Loose = await query(
      'SELECT id, password, username FROM sys_user WHERE id = ? AND deleted = 0',
      [effectiveUserId]
    );

    if (!users || users.length === 0) {
      return commonErrors.notFound('用户不存在');
    }

    const user = users[0];
    const isValid = await bcrypt.compare(oldPassword, user.password);
    if (!isValid) {
      return errorResponse('原密码错误', 400, 400);
    }

    const isSamePassword = await bcrypt.compare(newPassword, user.password);
    if (isSamePassword) {
      return errorResponse('新密码不能与旧密码相同', 400, 400);
    }

    const hashedPassword = await bcrypt.hash(newPassword, 10);
    await execute(
      'UPDATE sys_user SET password = ?, first_login = 0, pwd_update_time = NOW() WHERE id = ?',
      [hashedPassword, effectiveUserId]
    );

    try {
      await execute(
        `INSERT INTO sys_operation_log (title, oper_name, oper_url, request_method, oper_ip, oper_time, status)
         VALUES (?, ?, ?, ?, ?, NOW(), ?)`,
        ['修改密码', user.username, '/api/auth/change-password', 'POST', '', 1]
      );
    } catch {}

    return successResponse(null, '密码修改成功');
  },
  { logTitle: '修改密码', logType: 'auth' }
);

import { NextRequest, NextResponse } from 'next/server';
import { query, execute } from '@/lib/db';
import { SignJWT } from 'jose';
import bcrypt from 'bcryptjs';
import crypto from 'crypto';
import { checkRateLimit } from '@/lib/rate-limit';
import { storeRefreshToken } from '@/lib/token-blacklist';
import { logger, generateTraceId } from '@/lib/logger';
import { generateCsrfToken, setCsrfCookie } from '@/lib/csrf';
import { getSecretKey } from '@/lib/auth';

const MAX_LOGIN_ATTEMPTS = 5;
const LOCKOUT_MINUTES = Number(process.env.LOGIN_LOCKOUT_MINUTES || 15);

const ACCESS_TOKEN_TTL = process.env.JWT_ACCESS_TOKEN_TTL || '24h';
const REFRESH_TOKEN_TTL_SECONDS = Number(
  process.env.JWT_REFRESH_COOKIE_MAX_AGE || 7 * 24 * 60 * 60
);

function parseTtlToSeconds(ttl: string): number {
  const match = ttl.match(/^(\d+)([smhd])$/);
  if (!match) return 24 * 60 * 60;
  const value = parseInt(match[1], 10);
  const multipliers: Record<string, number> = { s: 1, m: 60, h: 3600, d: 86400 };
  return value * (multipliers[match[2]] || 3600);
}

const ACCESS_COOKIE_MAX_AGE = parseTtlToSeconds(ACCESS_TOKEN_TTL);

interface LoginUserRow {
  id: number;
  username: string;
  password: string;
  real_name: string;
  avatar: string | null;
  email: string | null;
  phone: string | null;
  department_id: number | null;
  status: number;
  first_login: number;
  login_fail_count: number;
  lock_time: string | Date | null;
  pwd_update_time?: string | Date | null;
}

interface UserRoleRow {
  id: number;
  role_code: string;
  role_name: string;
  data_scope: string;
}

interface PermissionRow {
  permission: string;
}

interface ConfigRow {
  config_value: string;
}

async function verifyPassword(password: string, hashedPassword: string): Promise<boolean> {
  return await bcrypt.compare(password, hashedPassword);
}

function getClientIP(request: NextRequest): string {
  const xff = request.headers.get('x-forwarded-for');
  if (xff) {
    const ips = xff.split(',').map((ip) => ip.trim());
    return ips[0] || '127.0.0.1';
  }
  return request.headers.get('x-real-ip') || '127.0.0.1';
}

export async function POST(request: NextRequest) {
  const traceId = generateTraceId();
  const ctx = { module: 'auth', action: 'login', traceId };

  try {
    const clientIP = getClientIP(request);
    logger.stepStart(ctx, '用户登录', { clientIP });

    const rateResult = await checkRateLimit(clientIP, {
      windowMs: Number(process.env.LOGIN_RATE_LIMIT_WINDOW_MS || 15 * 60 * 1000),
      maxRequests: Number(process.env.LOGIN_RATE_LIMIT_MAX || 20),
      keyPrefix: 'login',
    });

    if (!rateResult.allowed) {
      logger.branch(ctx, '限流检查', '请求频率超限', true, {
        retryAfterMs: rateResult.retryAfterMs,
      });
      return NextResponse.json(
        {
          success: false,
          message: `请求过于频繁，请${Math.ceil(rateResult.retryAfterMs / 60000)}分钟后再试`,
        },
        {
          status: 429,
          headers: {
            'Retry-After': String(Math.ceil(rateResult.retryAfterMs / 1000)),
            'X-RateLimit-Remaining': '0',
            'X-RateLimit-Reset': String(Math.ceil(rateResult.resetTime / 1000)),
          },
        }
      );
    }

    const body = await request.json();
    const { username, password } = body;

    if (!username || !password) {
      logger.branch(ctx, '参数校验', '用户名密码非空', false);
      return NextResponse.json(
        {
          success: false,
          message: '用户名和密码不能为空',
        },
        { status: 400 }
      );
    }

    let users: LoginUserRow[];
    try {
      users = await query<LoginUserRow>(
        'SELECT id, username, password, real_name, avatar, email, phone, department_id, status, first_login, login_fail_count, lock_time FROM sys_user WHERE username = ? AND deleted = 0',
        [username]
      );
    } catch (e: unknown) {
      if ((e as { code?: string }).code === 'ER_BAD_FIELD_ERROR') {
        users = await query<LoginUserRow>(
          'SELECT id, username, password, real_name, avatar, email, phone, department_id, status, 1 as first_login, 0 as login_fail_count, NULL as lock_time FROM sys_user WHERE username = ? AND deleted = 0',
          [username]
        );
      } else {
        throw e;
      }
    }

    if (users.length === 0) {
      logger.branch(ctx, '用户查找', '用户存在', false, { username });
      await logLogin(username, request, false, '用户名或密码错误');
      return NextResponse.json(
        {
          success: false,
          message: '用户名或密码错误',
        },
        { status: 401 }
      );
    }

    const user = users[0];

    if (user.status === 0) {
      logger.branch(ctx, '账号状态', '账号启用', false, { userId: user.id });
      await logLogin(username, request, false, '账号已被禁用');
      return NextResponse.json(
        {
          success: false,
          message: '账号已被禁用，请联系管理员',
        },
        { status: 403 }
      );
    }

    if (user.lock_time) {
      const lockTime = new Date(user.lock_time);
      const now = new Date();
      const diffMinutes = (now.getTime() - lockTime.getTime()) / (1000 * 60);
      if (diffMinutes < LOCKOUT_MINUTES) {
        const remaining = Math.ceil(LOCKOUT_MINUTES - diffMinutes);
        await logLogin(username, request, false, `账号已锁定，请${remaining}分钟后再试`);
        return NextResponse.json(
          {
            success: false,
            message: `账号已锁定，请${remaining}分钟后再试`,
          },
          { status: 429 }
        );
      } else {
        await execute('UPDATE sys_user SET login_fail_count = 0, lock_time = NULL WHERE id = ?', [
          user.id,
        ]);
        user.login_fail_count = 0;
      }
    }

    if (process.env.NEXT_PUBLIC_DEMO_MODE === 'true' || process.env.DEMO_MODE === 'true') {
      // SECURITY: 生产环境（含 Vercel 部署）一律禁止 demo 模式跳过密码验证。
      if (process.env.NODE_ENV === 'production') {
        logger.branch(ctx, '演示模式', '生产环境禁止演示模式', true);
        return NextResponse.json(
          { code: 403, msg: 'Demo mode is not allowed in production' },
          { status: 403 }
        );
      }
      logger.branch(ctx, '演示模式', '非生产环境-跳过密码验证', false);
    } else {
      const isPasswordValid = await verifyPassword(password, user.password);
      if (!isPasswordValid) {
        logger.branch(ctx, '密码验证', '密码正确', false, { userId: user.id });
        const failCount = (user.login_fail_count || 0) + 1;
        if (failCount >= MAX_LOGIN_ATTEMPTS) {
          logger.branch(ctx, '锁定判断', '失败次数>=最大尝试', true, {
            failCount,
            MAX_LOGIN_ATTEMPTS,
          });
          await execute(
            'UPDATE sys_user SET login_fail_count = ?, lock_time = NOW() WHERE id = ?',
            [failCount, user.id]
          );
          await logLogin(
            username,
            request,
            false,
            `密码错误次数过多，账号已锁定${LOCKOUT_MINUTES}分钟`
          );
          return NextResponse.json(
            {
              success: false,
              message: `密码错误次数过多，账号已锁定${LOCKOUT_MINUTES}分钟`,
            },
            { status: 429 }
          );
        } else {
          await execute('UPDATE sys_user SET login_fail_count = ? WHERE id = ?', [
            failCount,
            user.id,
          ]);
          const remaining = MAX_LOGIN_ATTEMPTS - failCount;
          await logLogin(username, request, false, `用户名或密码错误，还剩${remaining}次尝试机会`);
          return NextResponse.json(
            {
              success: false,
              message: `用户名或密码错误，还剩${remaining}次尝试机会`,
            },
            { status: 401 }
          );
        }
      }
    }

    // 检查异地登录
    let _isAbnormalLogin = false;
    logger.branch(ctx, '密码验证', '密码正确', true, { userId: user.id });
    try {
      const lastLogin = await query<{ last_login_ip: string }>(
        'SELECT last_login_ip FROM sys_user WHERE id = ? AND last_login_ip IS NOT NULL',
        [user.id]
      );
      if (lastLogin.length > 0 && lastLogin[0].last_login_ip) {
        const lastIP = lastLogin[0].last_login_ip;
        const currentIP = getClientIP(request);
        if (lastIP !== currentIP && currentIP !== '127.0.0.1') {
          _isAbnormalLogin = true;
          logger.branch(ctx, '异地登录', 'IP地址变化', true, { lastIP, currentIP });
          // 记录异地登录告警
          await execute(
            `INSERT INTO sys_notification (type, title, content, user_id, is_read, create_time)
             VALUES ('security', '异地登录提醒', ?, ?, 0, NOW())`,
            [
              `您的账号 ${username} 在新IP地址 ${currentIP} 登录，上次登录IP为 ${lastIP}。如非本人操作，请立即修改密码。`,
              user.id,
            ]
          );
        }
      }
    } catch {
      // 忽略异地登录检查错误
    }

    await execute(
      'UPDATE sys_user SET login_fail_count = 0, lock_time = NULL, last_login_ip = ?, last_login_time = NOW() WHERE id = ?',
      [getClientIP(request), user.id]
    );

    const userRoles = await query<UserRoleRow>(
      `SELECT r.id, r.role_code, r.role_name, r.data_scope
       FROM sys_user_role ur
       JOIN sys_role r ON ur.role_id = r.id
       WHERE ur.user_id = ? AND r.status = 1`,
      [user.id]
    );

    let departmentName: string | null = null;
    if (user.department_id) {
      try {
        const deptResult = await query<{ dept_name: string }>(
          'SELECT dept_name FROM sys_department WHERE id = ?',
          [user.department_id]
        );
        if (deptResult.length > 0) {
          departmentName = deptResult[0].dept_name;
        }
      } catch {}
    }

    let permissions: string[] = [];
    if (userRoles.length > 0) {
      const roleIds = userRoles.map((r) => r.id);
      const placeholders = roleIds.map(() => '?').join(',');
      const perms = await query<PermissionRow>(
        `SELECT DISTINCT m.permission
         FROM sys_menu m
         JOIN sys_role_menu rm ON m.id = rm.menu_id
         WHERE rm.role_id IN (${placeholders})
         AND m.permission IS NOT NULL AND m.permission != ''`,
        roleIds
      );
      permissions = perms.map((p) => p.permission).filter(Boolean);
    }

    const token = await new SignJWT({
      userId: user.id,
      username: user.username,
      realName: user.real_name,
      roles: userRoles.map((r) => r.role_code),
    })
      .setProtectedHeader({ alg: 'HS256' })
      .setIssuedAt()
      .setExpirationTime(ACCESS_TOKEN_TTL)
      .sign(new TextEncoder().encode(getSecretKey()));

    const userInfo = {
      id: user.id,
      username: user.username,
      realName: user.real_name,
      avatar: user.avatar,
      email: user.email,
      phone: user.phone,
      departmentId: user.department_id,
      departmentName,
      roles: userRoles.map((r) => ({
        id: r.id,
        role_code: r.role_code,
        role_name: r.role_name,
      })),
      permissions: [...new Set(permissions)],
      firstLogin: Number(user.first_login || 0) === 1,
      passwordExpired: false,
    };

    // 检查密码是否过期
    try {
      const pwdExpireConfigs = await query<ConfigRow>(
        "SELECT config_value FROM sys_config WHERE config_key = 'system.password_expire_days'"
      );
      const expireDays =
        pwdExpireConfigs.length > 0 ? parseInt(pwdExpireConfigs[0].config_value) || 0 : 0;
      if (expireDays > 0 && user.pwd_update_time) {
        const pwdUpdateTime = new Date(user.pwd_update_time);
        const now = new Date();
        const diffDays = (now.getTime() - pwdUpdateTime.getTime()) / (1000 * 60 * 60 * 24);
        if (diffDays > expireDays) {
          userInfo.passwordExpired = true;
        }
      }
    } catch {
      // 忽略配置查询错误
    }

    // 检查是否强制修改初始密码
    try {
      const forceChangeConfig = await query<ConfigRow>(
        "SELECT config_value FROM sys_config WHERE config_key = 'system.force_change_password'"
      );
      if (
        forceChangeConfig.length > 0 &&
        forceChangeConfig[0].config_value === 'true' &&
        Number(user.first_login || 0) === 1
      ) {
        userInfo.passwordExpired = true;
      }
    } catch {
      // 忽略
    }

    await logLogin(username, request, true, '登录成功');

    // 生成 refresh token
    const refreshToken = crypto.randomUUID();
    const refreshExpiresAt = Date.now() + REFRESH_TOKEN_TTL_SECONDS * 1000;
    await storeRefreshToken(refreshToken, user.id, refreshExpiresAt);

    const response = NextResponse.json({
      success: true,
      message: '登录成功',
      data: {
        token,
        refreshToken,
        user: userInfo,
      },
    });

    // 写入 httpOnly cookie：供 middleware 鉴权和 SSR 服务端预取菜单使用。
    // access_token 用于 SSR 预取 + middleware 拦截；refresh_token 用于服务端无感刷新。
    // 保留 JSON 返回的 token：客户端仍需要它做 Authorization header。
    response.cookies.set('access_token', token, {
      httpOnly: true,
      secure: process.env.COOKIE_SECURE
        ? process.env.COOKIE_SECURE === 'true'
        : process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/',
      maxAge: ACCESS_COOKIE_MAX_AGE,
    });
    response.cookies.set('refresh_token', refreshToken, {
      httpOnly: true,
      secure: process.env.COOKIE_SECURE
        ? process.env.COOKIE_SECURE === 'true'
        : process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/',
      maxAge: REFRESH_TOKEN_TTL_SECONDS,
    });

    // 登录成功后下发 CSRF token cookie
    const csrfToken = generateCsrfToken();
    setCsrfCookie(response, csrfToken);

    return response;
  } catch (error) {
    logger.error({ ctx, error }, `[auth.login] 登录异常: ${(error as Error).message}`);
    return NextResponse.json(
      {
        success: false,
        message: '登录失败，请稍后重试',
      },
      { status: 500 }
    );
  }
}

async function logLogin(username: string, request: NextRequest, success: boolean, message: string) {
  try {
    const ip = getClientIP(request);
    const userAgent = request.headers.get('user-agent') || '';
    await execute(
      `INSERT INTO sys_login_log (username, ip, user_agent, status, error_msg)
       VALUES (?, ?, ?, ?, ?)`,
      [username, ip, userAgent, success ? 1 : 0, success ? '' : message]
    );
  } catch {}
}

function _parseBrowser(ua: string): string {
  if (ua.includes('Edg/')) return 'Edge';
  if (ua.includes('Chrome/')) return 'Chrome';
  if (ua.includes('Firefox/')) return 'Firefox';
  if (ua.includes('Safari/')) return 'Safari';
  return 'Unknown';
}

function _parseOS(ua: string): string {
  if (ua.includes('Windows')) return 'Windows';
  if (ua.includes('Mac OS')) return 'macOS';
  if (ua.includes('Linux')) return 'Linux';
  if (ua.includes('Android')) return 'Android';
  if (ua.includes('iPhone') || ua.includes('iPad')) return 'iOS';
  return 'Unknown';
}

import { NextRequest, NextResponse } from 'next/server';
import { successResponse } from '@/lib/api-response';
import { extractToken, verifyToken, UserInfo } from '@/lib/auth';
import { revokeToken, removeRefreshToken } from '@/lib/token-blacklist';

/**
 * 清除 httpOnly cookie 的辅助函数。
 * 即使 token 验证失败，登出接口也必须清除 cookie，否则用户无法退出登录。
 */
function clearAuthCookies(response: NextResponse): void {
  response.cookies.set('access_token', '', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
  });
  response.cookies.set('refresh_token', '', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
  });
}

export async function POST(request: NextRequest): Promise<NextResponse> {
  // 登出接口不要求有效 token：即使用户 token 已过期或无效，也必须能登出。
  // 这是修复"退不出登录"问题的关键设计：
  //   - 旧实现使用 withPermission 装饰，token 过期时返回 401，cookie 永远不会被清除
  //   - 现在：尽量撤销 token（加入黑名单），但无论如何都清除 cookie 并返回成功
  try {
    const token = extractToken(request);

    if (token) {
      // 尝试验证 token 并加入黑名单（验证失败也忽略，继续登出）
      const userInfo: UserInfo | null = await verifyToken(token);
      if (userInfo) {
        const expiresAt = Date.now() + 24 * 60 * 60 * 1000;
        await revokeToken(`token:${userInfo.userId}:${token.slice(-20)}`, expiresAt);
      }
    }

    // 删除 refresh token（如果请求体中提供）
    try {
      const body = await request.json();
      if (body.refreshToken) {
        await removeRefreshToken(body.refreshToken);
      }
    } catch {
      // 请求体可能为空，忽略
    }
  } catch (error) {
    console.error('[Logout API] Error during token revocation:', error);
    // 不影响登出流程，继续清除 cookie
  }

  const response = successResponse(null, '登出成功');

  // 清除 httpOnly cookie：access_token + refresh_token
  // 通过 maxAge=0 立即过期，确保后续 SSR 和 middleware 不再识别为登录态
  clearAuthCookies(response);

  return response;
}

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import {
  getCachedPermissions,
  setCachedPermissions,
  clearCachedPermissions,
} from '@/lib/auth-cache';
import { buildMenuTree, extractPermissions } from '@/lib/menu-tree';

let isVisibleColumnExists: boolean | null = null;

async function checkIsVisibleColumn(): Promise<boolean> {
  if (isVisibleColumnExists !== null) return isVisibleColumnExists;
  try {
    const colCheck: Loose = await query(
      `SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'sys_menu' AND COLUMN_NAME = 'is_visible'`
    );
    isVisibleColumnExists = colCheck.length > 0;
  } catch {
    isVisibleColumnExists = false;
  }
  return isVisibleColumnExists;
}

export const GET = withPermission(async (request: NextRequest, userInfo) => {
  const cached = getCachedPermissions(userInfo.userId);
  if (cached) {
    return successResponse(
      {
        menus: cached.menus,
        permissions: cached.permissions,
      },
      '获取成功（缓存）'
    );
  }

  const userRoles = await query(
    `SELECT r.id, r.role_code, r.role_name, r.data_scope
     FROM sys_user_role ur
     JOIN sys_role r ON ur.role_id = r.id
     WHERE ur.user_id = ? AND r.status = 1`,
    [userInfo.userId]
  );

  if (userRoles.length === 0) {
    return successResponse({
      menus: [],
      permissions: [],
      roles: [],
    });
  }

  const roleIds = (userRoles as Loose[]).map((r) => r.id);

  const hasIsVisible = await checkIsVisibleColumn();
  const visibleCondition = hasIsVisible ? 'AND m.is_visible = 1' : '';

  const placeholders = roleIds.map(() => '?').join(',');
  const menus = await query(
    `SELECT DISTINCT m.id, m.menu_name, m.menu_code, m.menu_type, m.icon, m.path,
            m.component, m.permission, m.sort_order, m.parent_id, m.status
     FROM sys_menu m
     JOIN sys_role_menu rm ON m.id = rm.menu_id
     WHERE rm.role_id IN (${placeholders})
     AND m.status = 1
     ${visibleCondition}
     ORDER BY m.sort_order ASC, m.id ASC`,
    roleIds
  );

  const menuTree = buildMenuTree(menus as Loose[]);

  const permissions = extractPermissions(menus as Loose[]);

  setCachedPermissions(userInfo.userId, permissions, menuTree);

  return successResponse({
    menus: menuTree,
    permissions,
    roles: userRoles,
  });
});

export const DELETE = withPermission(async (request: NextRequest, userInfo) => {
  clearCachedPermissions(userInfo.userId);
  return successResponse(null, '缓存已清除');
});

import { NextRequest, NextResponse } from 'next/server';
import { SignJWT } from 'jose';
import { successResponse, errorResponse } from '@/lib/api-response';
import { verifyRefreshToken, storeRefreshToken, removeRefreshToken } from '@/lib/token-blacklist';
import { query } from '@/lib/db';
import { getRedisClientIfAvailable, getCacheManager } from '@/infrastructure/cache/CacheManager';
import { getSecretKey } from '@/lib/auth';

const REFRESH_LOCK_TTL_SEC = 5;

async function acquireRefreshLock(refreshToken: string): Promise<boolean> {
  const lockKey = `refresh_lock:${refreshToken}`;
  const redis = getRedisClientIfAvailable();
  if (redis) {
    const result = await redis.set(lockKey, '1', 'EX', REFRESH_LOCK_TTL_SEC, 'NX');
    return result === 'OK';
  }
  const cm = getCacheManager();
  const existing = await cm.get(lockKey);
  if (existing !== null) return false;
  await cm.set(lockKey, '1', REFRESH_LOCK_TTL_SEC);
  return true;
}

async function releaseRefreshLock(refreshToken: string): Promise<void> {
  const lockKey = `refresh_lock:${refreshToken}`;
  const redis = getRedisClientIfAvailable();
  if (redis) {
    await redis.del(lockKey);
    return;
  }
  await getCacheManager().delete(lockKey);
}

interface RefreshUserRow {
  id: number;
  username: string;
  real_name: string;
  status: number;
}

interface RefreshRoleRow {
  role_code: string;
}

export async function POST(request: NextRequest): Promise<NextResponse> {
  try {
    const body = await request.json();
    const { refreshToken, userId } = body;

    if (!refreshToken || !userId) {
      return errorResponse('缺少 refreshToken 或 userId', 400);
    }

    const locked = await acquireRefreshLock(refreshToken);
    if (!locked) {
      return errorResponse('正在刷新，请稍后重试', 429);
    }

    try {
      // 验证 refresh token
      if (!(await verifyRefreshToken(refreshToken, userId))) {
        return errorResponse('refresh token 无效或已过期', 401);
      }

      // 查询用户信息
      const users = await query<RefreshUserRow>(
        `SELECT id, username, real_name, status FROM sys_user WHERE id = ? AND deleted = 0 AND status = 1`,
        [userId]
      );

      if (!users || users.length === 0) {
        return errorResponse('用户不存在或已禁用', 401);
      }

      const user = users[0];

      // 查询用户角色
      const roles = await query<RefreshRoleRow>(
        `SELECT r.role_code FROM sys_role r
         JOIN sys_user_role ur ON r.id = ur.role_id
         WHERE ur.user_id = ? AND r.status = 1`,
        [userId]
      );

      // 生成新的 access token
      const newToken = await new SignJWT({
        userId: user.id,
        username: user.username,
        realName: user.real_name,
        roles: roles.map((r) => r.role_code),
      })
        .setProtectedHeader({ alg: 'HS256' })
        .setIssuedAt()
        .setExpirationTime('24h')
        .sign(new TextEncoder().encode(getSecretKey()));

      // 生成新的 refresh token
      const newRefreshToken = crypto.randomUUID();
      const refreshExpiresAt = Date.now() + 7 * 24 * 60 * 60 * 1000; // 7天
      await storeRefreshToken(newRefreshToken, userId, refreshExpiresAt);

      // 删除旧的 refresh token
      await removeRefreshToken(refreshToken);

      const response = successResponse(
        {
          token: newToken,
          refreshToken: newRefreshToken,
        },
        'Token 刷新成功'
      );

      // 同步刷新 httpOnly cookie：access_token + refresh_token
      // 与 login 路由保持一致，确保 SSR 预取和 middleware 鉴权使用最新 token
      response.cookies.set('access_token', newToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        path: '/',
        maxAge: 24 * 60 * 60, // 24h
      });
      response.cookies.set('refresh_token', newRefreshToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        path: '/',
        maxAge: 7 * 24 * 60 * 60, // 7d
      });

      return response;
    } finally {
      await releaseRefreshLock(refreshToken);
    }
  } catch (error) {
    console.error('[Refresh API] Error:', error);
    return errorResponse('Token 刷新失败', 500);
  }
}

﻿import { NextRequest, NextResponse } from 'next/server';
import { queryOne, transaction } from '@/lib/db';
import {
  successResponse,
  errorResponse,
  validateRequestBody,
  logOperation,
} from '@/lib/api-response';
import { checkRateLimit, getClientIP } from '@/lib/rate-limit';
import bcrypt from 'bcryptjs';

import { withPermission } from '@/lib/api-permissions';

// 注册接口允许自助绑定的角色编码白名单（P1-9 安全修复）
// 仅开放前端一线非特权角色，禁止通过 role_id 自绑管理员/财务/业务等特权角色，防止越权提权。
// 特权角色的分配必须在 /api/system/user 中由具备 SYSTEM_USER 权限的管理员完成。
const ALLOWED_SELF_REGISTER_ROLES: string[] = [
  'operator', // 操作工
  'sales', // 业务员
  'clerk', // 文员
  'inspector', // 质检员
  'warehouse_keeper', // 仓管员
];

// 用户注册数据接口
interface RegisterData {
  username: string;
  password: string;
  real_name?: string;
  email?: string;
  phone?: string;
  department_id?: number;
  role_id?: number;
}

// 密码加密
async function hashPassword(password: string): Promise<string> {
  return await bcrypt.hash(password, 10);
}

// 验证用户名格式
function validateUsername(username: string): boolean {
  return /^[a-zA-Z0-9_]{4,20}$/.test(username);
}

// 验证密码强度
function validatePassword(password: string): boolean {
  return password.length >= 6;
}

// 验证邮箱格式
function validateEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

// POST - 用户注册
export const POST = withPermission(
  async (request: NextRequest) => {
    // 限流：每 IP 15 分钟最多 5 次注册，防批量注册
    const clientIP = getClientIP(request);
    const rateResult = await checkRateLimit(clientIP, {
      windowMs: 15 * 60 * 1000,
      maxRequests: 5,
      keyPrefix: 'register',
    });
    if (!rateResult.allowed) {
      return NextResponse.json(
        {
          success: false,
          message: `注册请求过于频繁，请${Math.ceil(rateResult.retryAfterMs / 60000)}分钟后再试`,
        },
        {
          status: 429,
          headers: { 'Retry-After': String(Math.ceil(rateResult.retryAfterMs / 1000)) },
        }
      );
    }

    const body: RegisterData = await request.json();

    // 验证必填字段
    const validation = validateRequestBody(body, ['username', 'password']);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    const { username, password, real_name, email, phone, department_id, role_id } = body;

    // 验证用户名格式
    if (!validateUsername(username)) {
      return errorResponse('用户名只能包含字母、数字和下划线，长度4-20位', 400, 400);
    }

    // 验证密码强度
    if (!validatePassword(password)) {
      return errorResponse('密码长度不能少于6位', 400, 400);
    }

    // 验证邮箱格式
    if (email && !validateEmail(email)) {
      return errorResponse('邮箱格式不正确', 400, 400);
    }

    // 检查用户名是否已存在
    const existingUser = await queryOne<{ id: number }>(
      'SELECT id FROM sys_user WHERE username = ? AND deleted = 0',
      [username]
    );

    if (existingUser) {
      return errorResponse('用户名已存在', 409, 409);
    }

    // 检查邮箱是否已存在
    if (email) {
      const existingEmail = await queryOne<{ id: number }>(
        'SELECT id FROM sys_user WHERE email = ? AND deleted = 0',
        [email]
      );
      if (existingEmail) {
        return errorResponse('邮箱已被注册', 409, 409);
      }
    }

    // 检查手机号是否已存在
    if (phone) {
      if (!/^1[3-9]\d{9}$/.test(phone)) {
        return errorResponse('手机号格式不正确', 400, 400);
      }
      const existingPhone = await queryOne<{ id: number }>(
        'SELECT id FROM sys_user WHERE phone = ? AND deleted = 0',
        [phone]
      );
      if (existingPhone) {
        return errorResponse('手机号已被注册', 409, 409);
      }
    }

    if (department_id) {
      const deptExists = await queryOne<{ id: number }>(
        'SELECT id FROM sys_department WHERE id = ? AND deleted = 0',
        [department_id]
      );
      if (!deptExists) {
        return errorResponse('指定的部门不存在', 400, 400);
      }
    }

    // 安全：注册接口角色白名单校验，防止低权限用户通过 role_id 自绑管理员等特权角色（越权提权）
    // 仅允许自助绑定前端一线非特权角色；管理员/财务/业务等特权角色必须在 /api/system/user 中由管理员分配。
    let resolvedRoleId: number | null = null;
    if (role_id) {
      const roleRow = await queryOne<{ id: number; role_code: string }>(
        'SELECT id, role_code FROM sys_role WHERE id = ? AND deleted = 0',
        [role_id]
      );
      if (!roleRow) {
        return errorResponse('指定的角色不存在', 400, 400);
      }
      if (!ALLOWED_SELF_REGISTER_ROLES.includes(roleRow.role_code)) {
        return errorResponse('无权限注册为该角色，请联系管理员在用户管理中分配', 403, 403);
      }
      resolvedRoleId = roleRow.id;
    }

    // 加密密码
    const hashedPassword = await hashPassword(password);

    // 使用事务创建用户和绑定角色
    const userId = await transaction<number>(async (connection) => {
      // 创建用户
      const [result]: Loose = await connection.execute(
        `INSERT INTO sys_user (username, password, real_name, email, phone, department_id, status, first_login, create_time)
       VALUES (?, ?, ?, ?, ?, ?, 1, 1, NOW())`,
        [
          username,
          hashedPassword,
          real_name || null,
          email || null,
          phone || null,
          department_id || null,
        ]
      );

      const newUserId = result.insertId;

      let roleBound = false;

      if (resolvedRoleId) {
        await connection.execute('INSERT INTO sys_user_role (user_id, role_id) VALUES (?, ?)', [
          newUserId,
          resolvedRoleId,
        ]);
        roleBound = true;
      } else {
        const [defaultRole]: Loose = await connection.execute(
          "SELECT id FROM sys_role WHERE role_code = 'operator' AND deleted = 0 LIMIT 1"
        );
        if (defaultRole.length > 0) {
          await connection.execute('INSERT INTO sys_user_role (user_id, role_id) VALUES (?, ?)', [
            newUserId,
            defaultRole[0].id,
          ]);
          roleBound = true;
        }
      }

      if (!roleBound) {
        throw new Error('无法绑定角色，请确认系统已配置默认角色（operator）');
      }

      return newUserId;
    });

    await logOperation({
      title: '用户注册',
      oper_name: username,
      oper_type: 'auth',
      oper_method: 'POST',
      oper_url: '/api/auth/register',
      oper_param: JSON.stringify({
        username,
        real_name: real_name || '',
        email: email || '',
        phone: phone || '',
      }),
      oper_result: `用户 ${username} 注册成功`,
      status: 1,
    });

    return successResponse({ userId }, '注册成功');
  },
  { errorMessage: '注册失败' }
);

import { NextRequest, NextResponse } from 'next/server';
import { execute } from '@/lib/db';

export async function POST(request: NextRequest) {
  if (process.env.NODE_ENV === 'production') {
    return NextResponse.json(
      { success: false, message: 'Not available in production' },
      { status: 403 }
    );
  }

  try {
    const body = await request.json();
    const { username } = body;

    if (!username) {
      return NextResponse.json({ success: false, message: 'Username required' }, { status: 400 });
    }

    await execute('UPDATE sys_user SET login_fail_count = 0, lock_time = NULL WHERE username = ?', [
      username,
    ]);

    return NextResponse.json({ success: true, message: `Lock reset for ${username}` });
  } catch (error) {
    return NextResponse.json(
      { success: false, message: (error as Error).message },
      { status: 500 }
    );
  }
}

