﻿import { NextRequest } from 'next/server';
import { execute, queryOne, transaction, queryPaginated } from '@/lib/db';
import {
  successResponse,
  paginatedResponse,
  errorResponse,
  commonErrors,
  validateRequestBody,
} from '@/lib/api-response';
import { invalidateCache } from '@/lib/api-cache';
import { withPermission } from '@/lib/api-permissions';

// 客户数据接口
interface Customer {
  id?: number;
  customer_code: string;
  customer_name: string;
  short_name?: string;
  customer_type: number;
  industry?: string;
  scale?: string;
  credit_level?: string;
  province?: string;
  city?: string;
  district?: string;
  address?: string;
  contact_name?: string;
  contact_phone?: string;
  contact_email?: string;
  fax?: string;
  website?: string;
  business_license?: string;
  tax_number?: string;
  bank_name?: string;
  bank_account?: string;
  salesman_id?: number;
  follow_up_status?: number;
  status: number;
  remark?: string;
  create_time?: string;
  update_time?: string;
}

// 构建查询条件
function buildQueryConditions(params: {
  status?: string;
  customerType?: string;
  followUpStatus?: string;
  keyword?: string;
}): { sql: string; countSql: string; values: Loose[] } {
  let sql = `
    SELECT
      id, customer_code, customer_name, short_name, customer_type,
      industry, scale, credit_level, province, city, district, address,
      contact_name, contact_phone, contact_email, fax, website,
      business_license, tax_number, bank_name, bank_account,
      salesman_id, follow_up_status, status, remark, create_time, update_time
    FROM crm_customer
    WHERE deleted = 0
  `;
  let countSql = 'SELECT COUNT(*) as total FROM crm_customer WHERE deleted = 0';
  const values: Loose[] = [];

  if (params.status && params.status !== 'all') {
    const condition = ' AND status = ?';
    sql += condition;
    countSql += condition;
    values.push(parseInt(params.status));
  }

  if (params.customerType && params.customerType !== 'all') {
    const condition = ' AND customer_type = ?';
    sql += condition;
    countSql += condition;
    values.push(parseInt(params.customerType));
  }

  if (params.followUpStatus && params.followUpStatus !== 'all') {
    const condition = ' AND follow_up_status = ?';
    sql += condition;
    countSql += condition;
    values.push(parseInt(params.followUpStatus));
  }

  if (params.keyword) {
    const condition =
      ' AND (customer_code LIKE ? OR customer_name LIKE ? OR contact_name LIKE ? OR contact_phone LIKE ?)';
    sql += condition;
    countSql += condition;
    const likeKeyword = `%${params.keyword}%`;
    values.push(likeKeyword, likeKeyword, likeKeyword, likeKeyword);
  }

  sql += ' ORDER BY create_time DESC';

  return { sql, countSql, values };
}

// GET - 获取客户列表或单个客户
export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');
  const status = searchParams.get('status');
  const keyword = searchParams.get('keyword');
  const customerType = searchParams.get('customerType');
  const followUpStatus = searchParams.get('followUpStatus');
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '10');

  // 查询单个客户
  if (id) {
    const customer = await queryOne<Customer>(
      `SELECT
        id, customer_code, customer_name, short_name, customer_type,
        industry, scale, credit_level, province, city, district, address,
        contact_name, contact_phone, contact_email, fax, website,
        business_license, tax_number, bank_name, bank_account,
        salesman_id, follow_up_status, status, remark, create_time, update_time
      FROM crm_customer
      WHERE id = ? AND deleted = 0`,
      [parseInt(id)]
    );

    if (!customer) {
      return commonErrors.notFound('客户不存在');
    }

    return successResponse(customer);
  }

  // 构建查询条件
  const { sql, countSql, values } = buildQueryConditions({
    status: status ?? undefined,
    customerType: customerType ?? undefined,
    followUpStatus: followUpStatus ?? undefined,
    keyword: keyword ?? undefined,
  });

  // 使用分页查询工具
  const result = await queryPaginated<Customer>(sql, countSql, values, {
    page,
    pageSize,
  });

  return paginatedResponse(result.data, result.pagination);
});

// POST - 创建新客户
export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body: Customer = await request.json();

    // 验证必填字段
    const validation = validateRequestBody(body, [
      'customer_code',
      'customer_name',
      'customer_type',
    ]);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    // 检查客户编码是否已存在
    const existingCustomer = await queryOne<{ id: number }>(
      'SELECT id FROM crm_customer WHERE customer_code = ? AND deleted = 0',
      [body.customer_code]
    );

    if (existingCustomer) {
      return errorResponse('客户编码已存在', 409, 409);
    }

    const result = await execute(
      `INSERT INTO crm_customer (
        customer_code, customer_name, short_name, customer_type,
        industry, scale, credit_level, province, city, district, address,
        contact_name, contact_phone, contact_email, fax, website,
        business_license, tax_number, bank_name, bank_account,
        salesman_id, follow_up_status, status, remark
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        body.customer_code,
        body.customer_name,
        body.short_name,
        body.customer_type,
        body.industry,
        body.scale,
        body.credit_level,
        body.province,
        body.city,
        body.district,
        body.address,
        body.contact_name,
        body.contact_phone,
        body.contact_email,
        body.fax,
        body.website,
        body.business_license,
        body.tax_number,
        body.bank_name,
        body.bank_account,
        body.salesman_id,
        body.follow_up_status || 1,
        body.status ?? 1,
        body.remark,
      ]
    );

    await invalidateCache('api:customers');
    return successResponse({ id: result.insertId }, '客户创建成功');
  },
  { logTitle: '创建客户', logType: 'business' }
);

// PUT - 更新客户
export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return commonErrors.badRequest('缺少客户ID');
    }

    const customerId = parseInt(id);
    const body: Customer = await request.json();

    // 检查客户是否存在
    const existingCustomer = await queryOne<{ id: number }>(
      'SELECT id FROM crm_customer WHERE id = ? AND deleted = 0',
      [customerId]
    );

    if (!existingCustomer) {
      return commonErrors.notFound('客户不存在或已被删除');
    }

    // 如果修改了客户编码，检查是否与其他客户冲突
    if (body.customer_code) {
      const codeExists = await queryOne<{ id: number }>(
        'SELECT id FROM crm_customer WHERE customer_code = ? AND id != ? AND deleted = 0',
        [body.customer_code, customerId]
      );

      if (codeExists) {
        return errorResponse('客户编码已存在', 409, 409);
      }
    }

    const result = await execute(
      `UPDATE crm_customer SET
        customer_code = ?, customer_name = ?, short_name = ?, customer_type = ?,
        industry = ?, scale = ?, credit_level = ?, province = ?, city = ?, district = ?, address = ?,
        contact_name = ?, contact_phone = ?, contact_email = ?, fax = ?, website = ?,
        business_license = ?, tax_number = ?, bank_name = ?, bank_account = ?,
        salesman_id = ?, follow_up_status = ?, status = ?, remark = ?
      WHERE id = ? AND deleted = 0`,
      [
        body.customer_code,
        body.customer_name,
        body.short_name,
        body.customer_type,
        body.industry,
        body.scale,
        body.credit_level,
        body.province,
        body.city,
        body.district,
        body.address,
        body.contact_name,
        body.contact_phone,
        body.contact_email,
        body.fax,
        body.website,
        body.business_license,
        body.tax_number,
        body.bank_name,
        body.bank_account,
        body.salesman_id,
        body.follow_up_status,
        body.status,
        body.remark,
        customerId,
      ]
    );

    if (result.affectedRows === 0) {
      return commonErrors.notFound('客户不存在或已被删除');
    }

    await invalidateCache('api:customers');
    return successResponse(null, '客户更新成功');
  },
  { logTitle: '更新客户', logType: 'business' }
);

// DELETE - 删除客户（软删除）
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return commonErrors.badRequest('缺少客户ID');
    }

    const customerId = parseInt(id);

    // 检查客户是否存在
    const existingCustomer = await queryOne<{ id: number }>(
      'SELECT id FROM crm_customer WHERE id = ? AND deleted = 0',
      [customerId]
    );

    if (!existingCustomer) {
      return commonErrors.notFound('客户不存在或已被删除');
    }

    // 使用事务软删除
    await transaction(async (connection) => {
      await connection.execute('UPDATE crm_customer SET deleted = 1 WHERE id = ?', [customerId]);
    });

    await invalidateCache('api:customers');
    return successResponse(null, '客户删除成功');
  },
  { logTitle: '删除客户', logType: 'business' }
);

import { NextRequest, NextResponse } from 'next/server';
import { query } from '@/lib/db';
import { getConfig } from '@/lib/global-config';
import { withPermission } from '@/lib/api-permissions';
import { logger } from '@/lib/logger';

export const GET = withPermission(async (_request: NextRequest, _userInfo) => {
  try {
    const dashboardDays = Number(getConfig('dashboard_trend_days') || 30);

    const overview: Loose = {
      todayOrders: 0,
      todayProduction: 0,
      todayDelivery: 0,
      inventoryValue: 0,
      orderChange: 0,
      productionChange: 0,
      deliveryChange: 0,
      inventoryChange: 0,
    };
    try {
      const rows: Loose = await query(
        `SELECT COUNT(*) as total FROM prd_process_card WHERE deleted = 0 AND DATE(create_time) = CURDATE()`
      );
      if (Array.isArray(rows) && rows.length > 0) overview.todayOrders = Number(rows[0].total || 0);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const rows: Loose = await query(
        `SELECT COUNT(*) as total FROM sal_order WHERE deleted = 0 AND DATE(create_time) = CURDATE()`
      );
      if (Array.isArray(rows) && rows.length > 0) overview.todayOrders = Number(rows[0].total || 0);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const rows: Loose = await query(
        `SELECT COALESCE(SUM(plan_qty), 0) as total FROM prd_process_card WHERE deleted = 0 AND DATE(create_time) = CURDATE()`
      );
      if (Array.isArray(rows) && rows.length > 0)
        overview.todayProduction = Number(rows[0].total || 0);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const rows: Loose = await query(
        `SELECT COUNT(*) as total FROM inv_outbound_order WHERE deleted = 0 AND DATE(create_time) = CURDATE()`
      );
      if (Array.isArray(rows) && rows.length > 0)
        overview.todayDelivery = Number(rows[0].total || 0);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const rows: Loose = await query(
        `SELECT COALESCE(SUM(i.available_qty * m.purchase_price), 0) as total 
         FROM inv_material m 
         LEFT JOIN inv_inventory i ON m.id = i.material_id
         WHERE m.deleted = 0 AND m.status = 1 AND i.deleted = 0`
      );
      if (Array.isArray(rows) && rows.length > 0)
        overview.inventoryValue = Number(rows[0].total || 0);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    const production: Loose = {
      efficiency: 0,
      activeOrders: 0,
      completedToday: 0,
      warningCount: 0,
      equipmentStatus: [],
    };
    try {
      const rows: Loose = await query(`
        SELECT
          COUNT(*) as total,
          SUM(CASE WHEN burdening_status IN (1,2) THEN 1 ELSE 0 END) as active,
          SUM(CASE WHEN burdening_status = 3 AND DATE(update_time) = CURDATE() THEN 1 ELSE 0 END) as completed
        FROM prd_process_card WHERE deleted = 0
      `);
      if (Array.isArray(rows) && rows.length > 0) {
        production.activeOrders = Number(rows[0].active || 0);
        production.completedToday = Number(rows[0].completed || 0);
      }
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const woRows: Loose = await query(`
        SELECT work_order_no, product_name, customer_name, status, priority
        FROM prod_work_order WHERE deleted = 0 AND status IN ('pending','producing')
        ORDER BY update_time DESC LIMIT 20
      `);
      production.activeWorkOrders = Array.isArray(woRows)
        ? woRows.map((r: Loose) => ({
            work_order_no: r.work_order_no || '',
            product_name: r.product_name || '',
            customer_name: r.customer_name || '',
            status: r.status,
            priority: r.priority,
          }))
        : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const rows: Loose = await query(`
        SELECT equipment_code as name, current_status as status, oee as efficiency
        FROM eqp_equipment WHERE deleted = 0 AND status = 1 ORDER BY equipment_code
      `);
      production.equipmentStatus = Array.isArray(rows)
        ? rows.map((r: Loose) => ({
            name: r.name,
            status:
              r.status === 1
                ? 'running'
                : r.status === 2
                  ? 'idle'
                  : r.status === 3
                    ? 'maintenance'
                    : 'error',
            efficiency: Number(r.efficiency || 0),
          }))
        : [];
      const running = production.equipmentStatus.filter(
        (e: Loose) => e.status === 'running'
      ).length;
      production.efficiency =
        production.equipmentStatus.length > 0
          ? Math.round((running / production.equipmentStatus.length) * 100)
          : 0;
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const rows: Loose = await query(`
        SELECT COUNT(*) as total FROM prod_work_order WHERE deleted = 0 AND status IN ('pending','producing')
        AND (plan_end_date < CURDATE() OR priority = 'urgent')
      `);
      if (Array.isArray(rows) && rows.length > 0)
        production.warningCount = Number(rows[0].total || 0);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    const quality: Loose = {
      passRate: 0,
      totalInspections: 0,
      passedInspections: 0,
      failedInspections: 0,
      recentDefects: [],
    };
    try {
      const rows: Loose = await query(
        `SELECT COUNT(*) as total FROM qc_inspection WHERE deleted = 0`
      );
      if (Array.isArray(rows) && rows.length > 0)
        quality.totalInspections = Number(rows[0].total || 0);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const rows: Loose = await query(`
        SELECT 
          COUNT(*) as total,
          SUM(CASE WHEN inspection_result = 1 THEN 1 ELSE 0 END) as passed,
          SUM(CASE WHEN inspection_result = 2 THEN 1 ELSE 0 END) as failed
        FROM qc_inspection WHERE deleted = 0
      `);
      if (Array.isArray(rows) && rows.length > 0) {
        quality.totalInspections = Number(rows[0].total || 0);
        quality.passedInspections = Number(rows[0].passed || 0);
        quality.failedInspections = Number(rows[0].failed || 0);
        quality.passRate =
          quality.totalInspections > 0
            ? Math.round((quality.passedInspections / quality.totalInspections) * 1000) / 10
            : 0;
      }
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    const finance: Loose = {
      totalReceivable: 0,
      totalPayable: 0,
      monthRevenue: 0,
      monthExpense: 0,
      revenueChange: 0,
      expenseChange: 0,
    };
    try {
      const recRows: Loose = await query(
        `SELECT COALESCE(SUM(amount), 0) as total FROM fin_receivable WHERE deleted = 0 AND status = 1`
      );
      const payRows: Loose = await query(
        `SELECT COALESCE(SUM(amount), 0) as total FROM fin_payable WHERE deleted = 0 AND status = 1`
      );
      if (Array.isArray(recRows) && recRows.length > 0)
        finance.totalReceivable = Number(recRows[0].total || 0);
      if (Array.isArray(payRows) && payRows.length > 0)
        finance.totalPayable = Number(payRows[0].total || 0);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const revRows: Loose = await query(
        `SELECT COALESCE(SUM(amount), 0) as total FROM fin_receivable WHERE deleted = 0 AND DATE(create_time) >= DATE_FORMAT(CURDATE(), '%Y-%m-01')`
      );
      const expRows: Loose = await query(
        `SELECT COALESCE(SUM(amount), 0) as total FROM fin_payable WHERE deleted = 0 AND DATE(create_time) >= DATE_FORMAT(CURDATE(), '%Y-%m-01')`
      );
      if (Array.isArray(revRows) && revRows.length > 0)
        finance.monthRevenue = Number(revRows[0].total || 0);
      if (Array.isArray(expRows) && expRows.length > 0)
        finance.monthExpense = Number(expRows[0].total || 0);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    const inventory: Loose = { totalItems: 0, lowStock: 0, totalValue: 0, warehouseUtilization: 0 };
    try {
      const rows: Loose = await query(`
        SELECT m.id, COALESCE(SUM(i.available_qty), 0) as total_qty, COALESCE(m.min_stock, m.safety_stock, 0) as threshold
        FROM inv_material m
        LEFT JOIN inv_inventory i ON m.id = i.material_id AND i.deleted = 0
        WHERE m.deleted = 0 AND m.status = 1
        GROUP BY m.id, m.min_stock, m.safety_stock
      `);
      if (Array.isArray(rows) && rows.length > 0) {
        inventory.totalItems = rows.length;
        inventory.lowStock = rows.filter((r: Loose) => {
          const qty = Number(r.total_qty || 0);
          const threshold = Number(r.threshold || 0);
          return threshold > 0 && qty <= threshold;
        }).length;
      }
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const rows: Loose = await query(
        `SELECT COALESCE(SUM(i.available_qty * m.purchase_price), 0) as total 
         FROM inv_material m 
         LEFT JOIN inv_inventory i ON m.id = i.material_id AND i.deleted = 0
         WHERE m.deleted = 0 AND m.status = 1`
      );
      if (Array.isArray(rows) && rows.length > 0) inventory.totalValue = Number(rows[0].total || 0);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const rows: Loose = await query(`
        SELECT COUNT(*) as total FROM inv_warehouse WHERE deleted = 0
      `);
      if (Array.isArray(rows) && rows.length > 0) {
        inventory.warehouseUtilization = Math.min(100, Number(rows[0].total || 0) * 5);
      }
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    let orderTrend: Loose[] = [];
    try {
      const rows: Loose = await query(`
        SELECT DATE(create_time) as date, COUNT(*) as count
        FROM sal_order WHERE deleted = 0 AND create_time >= DATE_SUB(CURDATE(), INTERVAL ${dashboardDays} DAY)
        GROUP BY DATE(create_time) ORDER BY date
      `);
      orderTrend = Array.isArray(rows) ? rows : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    let topProducts: Loose[] = [];
    try {
      const rows: Loose = await query(`
        SELECT product_name, SUM(plan_qty) as total_qty
        FROM prd_process_card WHERE deleted = 0 AND burdening_status = 3
        GROUP BY product_name ORDER BY total_qty DESC LIMIT 5
      `);
      topProducts = Array.isArray(rows) ? rows : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    let workshopDaily: Loose[] = [];
    try {
      const rows: Loose = await query(`
        SELECT product_name, SUM(plan_qty) as total_qty
        FROM prd_process_card WHERE deleted = 0 AND DATE(create_time) = CURDATE()
        GROUP BY product_name ORDER BY total_qty DESC
      `);
      workshopDaily = Array.isArray(rows)
        ? rows.map((r: Loose) => ({
            name: r.product_name || '',
            total: Number(r.total_qty || 0),
            completed: Number(r.total_qty || 0),
          }))
        : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    let materialConsumption: Loose[] = [];
    try {
      const rows: Loose = await query(`
        SELECT material_name, SUM(order_qty) as total_qty
        FROM pur_purchase_order_line WHERE DATE(create_time) = CURDATE()
        GROUP BY material_name ORDER BY total_qty DESC LIMIT 5
      `);
      materialConsumption = Array.isArray(rows)
        ? rows.map((r: Loose) => ({
            name: r.material_name || '',
            qty: Number(r.total_qty || 0),
          }))
        : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    let monthlyMaterialConsumption: Loose[] = [];
    try {
      const rows: Loose = await query(`
        SELECT material_name, SUM(order_qty) as total_qty
        FROM pur_purchase_order_line WHERE create_time >= DATE_FORMAT(CURDATE(), '%Y-%m-01')
        GROUP BY material_name ORDER BY total_qty DESC LIMIT 5
      `);
      monthlyMaterialConsumption = Array.isArray(rows)
        ? rows.map((r: Loose) => ({
            name: r.material_name || '',
            qty: Number(r.total_qty || 0),
          }))
        : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    let workshopHistory: Loose[] = [];
    try {
      const rows: Loose = await query(`
        SELECT YEAR(create_time) as year, SUM(plan_qty) as total_qty
        FROM prd_process_card WHERE deleted = 0 AND create_time >= DATE_SUB(CURDATE(), INTERVAL 4 YEAR)
        GROUP BY YEAR(create_time) ORDER BY year DESC
      `);
      workshopHistory = Array.isArray(rows)
        ? rows.map((r: Loose) => ({
            year: Number(r.year || 0),
            total: Number(r.total_qty || 0),
          }))
        : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    const shiftData: Loose = {
      dayShift: { plan: 0, actual: 0, rate: 0 },
      middleShift: { plan: 0, actual: 0, rate: 0 },
      nightShift: { plan: 0, actual: 0, rate: 0 },
    };
    try {
      const dayRows: Loose = await query(
        `SELECT COALESCE(SUM(plan_qty), 0) as plan, COALESCE(SUM(plan_qty), 0) as actual FROM prd_process_card WHERE deleted = 0 AND DATE(create_time) = CURDATE() AND HOUR(create_time) BETWEEN 8 AND 15`
      );
      const midRows: Loose = await query(
        `SELECT COALESCE(SUM(plan_qty), 0) as plan, COALESCE(SUM(plan_qty), 0) as actual FROM prd_process_card WHERE deleted = 0 AND DATE(create_time) = CURDATE() AND HOUR(create_time) BETWEEN 16 AND 23`
      );
      const nightRows: Loose = await query(
        `SELECT COALESCE(SUM(plan_qty), 0) as plan, COALESCE(SUM(plan_qty), 0) as actual FROM prd_process_card WHERE deleted = 0 AND DATE(create_time) = CURDATE() AND (HOUR(create_time) < 8 OR HOUR(create_time) > 23)`
      );
      if (Array.isArray(dayRows) && dayRows.length > 0) {
        shiftData.dayShift.plan = Number(dayRows[0].plan || 0);
        shiftData.dayShift.actual = Number(dayRows[0].actual || 0);
        shiftData.dayShift.rate =
          shiftData.dayShift.plan > 0
            ? Math.round((shiftData.dayShift.actual / shiftData.dayShift.plan) * 100)
            : 0;
      }
      if (Array.isArray(midRows) && midRows.length > 0) {
        shiftData.middleShift.plan = Number(midRows[0].plan || 0);
        shiftData.middleShift.actual = Number(midRows[0].actual || 0);
        shiftData.middleShift.rate =
          shiftData.middleShift.plan > 0
            ? Math.round((shiftData.middleShift.actual / shiftData.middleShift.plan) * 100)
            : 0;
      }
      if (Array.isArray(nightRows) && nightRows.length > 0) {
        shiftData.nightShift.plan = Number(nightRows[0].plan || 0);
        shiftData.nightShift.actual = Number(nightRows[0].actual || 0);
        shiftData.nightShift.rate =
          shiftData.nightShift.plan > 0
            ? Math.round((shiftData.nightShift.actual / shiftData.nightShift.plan) * 100)
            : 0;
      }
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    const powerConsumption: Loose[] = [];

    const materialUsage: Loose[] = [];

    let processRelations: Loose[] = [];
    try {
      const rows: Loose = await query(`
        SELECT DISTINCT product_name
        FROM prd_process_card WHERE deleted = 0 AND product_name IS NOT NULL AND product_name != ''
        ORDER BY product_name
      `);
      processRelations = Array.isArray(rows) ? rows.map((r: Loose) => r.product_name) : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'ceo' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    return NextResponse.json({
      success: true,
      data: {
        overview,
        production,
        quality,
        finance,
        inventory,
        orderTrend,
        topProducts,
        workshopDaily,
        materialConsumption,
        monthlyMaterialConsumption,
        workshopHistory,
        shiftData,
        powerConsumption,
        materialUsage,
        processRelations,
      },
    });
  } catch {
    return NextResponse.json({ success: false, message: '获取CEO看板数据失败' }, { status: 500 });
  }
});

import { NextRequest, NextResponse } from 'next/server';
import { query } from '@/lib/db';
import { getConfig } from '@/lib/global-config';
import { withPermission } from '@/lib/api-permissions';
import { logger } from '@/lib/logger';

export const GET = withPermission(async (_request: NextRequest, _userInfo) => {
  try {
    const dashboardDays = Number(getConfig('dashboard_trend_days') || 30);
    const aging30Days = Number(getConfig('aging_30_days') || 30);
    const aging60Days = Number(getConfig('aging_60_days') || 60);
    const aging90Days = Number(getConfig('aging_90_days') || 90);

    const overview: Loose = {
      totalReceivable: 0,
      totalPayable: 0,
      monthRevenue: 0,
      monthExpense: 0,
      revenueChange: 0,
      expenseChange: 0,
      netProfit: 0,
    };
    try {
      const recRows: Loose = await query(
        `SELECT COALESCE(SUM(amount), 0) as total FROM fin_receivable WHERE deleted = 0 AND status = 1`
      );
      const payRows: Loose = await query(
        `SELECT COALESCE(SUM(amount), 0) as total FROM fin_payable WHERE deleted = 0 AND status = 1`
      );
      if (Array.isArray(recRows) && recRows.length > 0)
        overview.totalReceivable = Number(recRows[0].total || 0);
      if (Array.isArray(payRows) && payRows.length > 0)
        overview.totalPayable = Number(payRows[0].total || 0);
      overview.netProfit = overview.totalReceivable - overview.totalPayable;
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'finance' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    try {
      const revRows: Loose = await query(
        `SELECT COALESCE(SUM(amount), 0) as total FROM fin_receipt_record WHERE deleted = 0 AND DATE(receipt_date) >= DATE_SUB(CURDATE(), INTERVAL ${dashboardDays} DAY)`
      );
      const expRows: Loose = await query(
        `SELECT COALESCE(SUM(amount), 0) as total FROM fin_payment_record WHERE deleted = 0 AND DATE(payment_date) >= DATE_SUB(CURDATE(), INTERVAL ${dashboardDays} DAY)`
      );
      if (Array.isArray(revRows) && revRows.length > 0)
        overview.monthRevenue = Number(revRows[0].total || 0);
      if (Array.isArray(expRows) && expRows.length > 0)
        overview.monthExpense = Number(expRows[0].total || 0);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'finance' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    let revenueTrend: Loose[] = [];
    try {
      const rows: Loose = await query(`
        SELECT DATE(receipt_date) as date, COALESCE(SUM(amount), 0) as amount
        FROM fin_receipt_record WHERE deleted = 0 AND receipt_date >= DATE_SUB(CURDATE(), INTERVAL ${dashboardDays} DAY)
        GROUP BY DATE(receipt_date) ORDER BY date
      `);
      revenueTrend = Array.isArray(rows) ? rows : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'finance' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    let expenseTrend: Loose[] = [];
    try {
      const rows: Loose = await query(`
        SELECT DATE(payment_date) as date, COALESCE(SUM(amount), 0) as amount
        FROM fin_payment_record WHERE deleted = 0 AND payment_date >= DATE_SUB(CURDATE(), INTERVAL ${dashboardDays} DAY)
        GROUP BY DATE(payment_date) ORDER BY date
      `);
      expenseTrend = Array.isArray(rows) ? rows : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'finance' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    let receivableAging: Loose[] = [];
    try {
      const rows: Loose = await query(`
        SELECT
          CASE
            WHEN DATEDIFF(CURDATE(), create_time) <= ${aging30Days} THEN '0-${aging30Days}天'
            WHEN DATEDIFF(CURDATE(), create_time) <= ${aging60Days} THEN '${aging30Days + 1}-${aging60Days}天'
            WHEN DATEDIFF(CURDATE(), create_time) <= ${aging90Days} THEN '${aging60Days + 1}-${aging90Days}天'
            ELSE '${aging90Days}天以上'
          END as aging,
          COUNT(*) as count,
          COALESCE(SUM(amount), 0) as total
        FROM fin_receivable WHERE deleted = 0 AND status = 1 GROUP BY aging
      `);
      receivableAging = Array.isArray(rows) ? rows : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'finance' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    let recentTransactions: Loose[] = [];
    try {
      const recRows: Loose = await query(`
        SELECT 'receipt' as type, id, amount, receipt_date as date, remark FROM fin_receipt_record WHERE deleted = 0 ORDER BY receipt_date DESC LIMIT 5
      `);
      const payRows: Loose = await query(`
        SELECT 'payment' as type, id, amount, payment_date as date, remark FROM fin_payment_record WHERE deleted = 0 ORDER BY payment_date DESC LIMIT 5
      `);
      const receipts = Array.isArray(recRows) ? recRows : [];
      const payments = Array.isArray(payRows) ? payRows : [];
      recentTransactions = [...receipts, ...payments]
        .sort((a: Loose, b: Loose) => new Date(b.date).getTime() - new Date(a.date).getTime())
        .slice(0, 10);
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'finance' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    let topPayables: Loose[] = [];
    try {
      const rows: Loose = await query(`
        SELECT s.supplier_name, COALESCE(SUM(p.amount), 0) as total, COUNT(*) as count
        FROM fin_payable p
        LEFT JOIN pur_supplier s ON p.supplier_id = s.id
        WHERE p.deleted = 0 AND p.status = 1 GROUP BY s.supplier_name ORDER BY total DESC LIMIT 5
      `);
      topPayables = Array.isArray(rows) ? rows : [];
    } catch (e) {
      logger.error({ module: 'dashboard', action: 'finance' }, 'Dashboard query failed', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    return NextResponse.json({
      success: true,
      data: {
        overview,
        revenueTrend,
        expenseTrend,
        receivableAging,
        recentTransactions,
        topPayables,
      },
    });
  } catch {
    return NextResponse.json({ success: false, message: '获取财务看板数据失败' }, { status: 500 });
  }
});

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { logger } from '@/lib/logger';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const period = searchParams.get('period') || 'month';
  const startDate = searchParams.get('startDate') || '';
  const endDate = searchParams.get('endDate') || '';

  let dateFilter = '';
  const params: Loose[] = [];

  if (startDate && endDate) {
    dateFilter = 'AND create_time BETWEEN ? AND ?';
    params.push(startDate, endDate);
  } else if (period === 'week') {
    dateFilter = 'AND create_time >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)';
  } else if (period === 'month') {
    dateFilter = 'AND create_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)';
  } else if (period === 'quarter') {
    dateFilter = 'AND create_time >= DATE_SUB(CURDATE(), INTERVAL 90 DAY)';
  } else if (period === 'year') {
    dateFilter = 'AND create_time >= DATE_SUB(CURDATE(), INTERVAL 365 DAY)';
  }

  // ========================================
  // 1. OTD (On-Time Delivery) 准时交付率
  //    公式: 准时交付订单数 / 总应交付订单数 × 100%
  //    数据来源: sal_order.delivery_date vs 实际出库时间
  // ========================================
  const otd: Loose = { rate: 0, totalOrders: 0, onTimeOrders: 0, lateOrders: 0, details: [] };
  try {
    const otdRows: Loose = await query(
      `
      SELECT
        COUNT(*) as total_orders,
        SUM(CASE WHEN so.status >= 40 THEN 1 ELSE 0 END) as delivered_orders,
        SUM(CASE WHEN so.status >= 40 AND EXISTS (
          SELECT 1 FROM inv_sales_outbound iso
          WHERE iso.order_id = so.id AND iso.deleted = 0 AND iso.status = 3
          AND DATE(iso.create_time) <= so.delivery_date
        ) THEN 1 ELSE 0 END) as on_time_orders
      FROM sal_order so
      WHERE so.deleted = 0 AND so.status >= 20 ${dateFilter}
    `,
      params
    );

    if (Array.isArray(otdRows) && otdRows.length > 0) {
      otd.totalOrders = Number(otdRows[0].total_orders || 0);
      otd.onTimeOrders = Number(otdRows[0].on_time_orders || 0);
      otd.lateOrders = Number(otdRows[0].delivered_orders || 0) - otd.onTimeOrders;
      otd.rate =
        otd.totalOrders > 0 ? Math.round((otd.onTimeOrders / otd.totalOrders) * 10000) / 100 : 0;
    }
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 2. 库存周转率 (Inventory Turnover)
  //    公式: 销售成本 / 平均库存价值
  //    数据来源: fin_voucher(出库成本) / inv_inventory_batch(库存价值)
  // ========================================
  const inventoryTurnover: Loose = { rate: 0, costOfGoods: 0, avgInventoryValue: 0, daysOnHand: 0 };
  try {
    const costRows: Loose = await query(
      `
      SELECT COALESCE(SUM(amount), 0) as total_cost
      FROM fin_voucher
      WHERE deleted = 0 AND credit_account = '成品库存' ${dateFilter.replace('create_time', 'voucher_date')}
    `,
      params
    );

    const invValueRows: Loose = await query(`
      SELECT COALESCE(SUM(available_qty * unit_price), 0) as total_value
      FROM inv_inventory_batch
      WHERE deleted = 0 AND status = 'normal'
    `);

    inventoryTurnover.costOfGoods = Number(costRows[0]?.total_cost || 0);
    inventoryTurnover.avgInventoryValue = Number(invValueRows[0]?.total_value || 0);
    inventoryTurnover.rate =
      inventoryTurnover.avgInventoryValue > 0
        ? Math.round((inventoryTurnover.costOfGoods / inventoryTurnover.avgInventoryValue) * 100) /
          100
        : 0;
    inventoryTurnover.daysOnHand =
      inventoryTurnover.rate > 0 ? Math.round(365 / inventoryTurnover.rate) : 0;
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 3. OEE (Overall Equipment Effectiveness) 设备综合效率
  //    公式: OEE = 可用率(A) × 表现率(P) × 质量率(Q)
  //    数据来源: eqp_equipment + 生产报工 + 质检记录
  // ========================================
  const oee: Loose = {
    overall: 0,
    availability: 0,
    performance: 0,
    quality: 0,
    equipmentDetails: [],
  };
  try {
    const oeeRows: Loose = await query(`
      SELECT
        id, equipment_code, equipment_name,
        COALESCE(oee_availability, 0) as availability,
        COALESCE(oee_performance, 0) as performance,
        COALESCE(oee_quality, 0) as quality,
        COALESCE(oee_overall, 0) as overall
      FROM eqp_equipment
      WHERE deleted = 0 AND status = 1
    `);

    if (Array.isArray(oeeRows) && oeeRows.length > 0) {
      oee.equipmentDetails = oeeRows.map((r: Loose) => ({
        id: r.id,
        code: r.equipment_code,
        name: r.equipment_name,
        availability: Number(r.availability),
        performance: Number(r.performance),
        quality: Number(r.quality),
        overall: Number(r.overall),
      }));

      const count = oeeRows.length;
      oee.availability =
        Math.round(
          (oeeRows.reduce((s: number, r: Loose) => s + Number(r.availability), 0) / count) * 100
        ) / 100;
      oee.performance =
        Math.round(
          (oeeRows.reduce((s: number, r: Loose) => s + Number(r.performance), 0) / count) * 100
        ) / 100;
      oee.quality =
        Math.round(
          (oeeRows.reduce((s: number, r: Loose) => s + Number(r.quality), 0) / count) * 100
        ) / 100;
      oee.overall =
        Math.round(((oee.availability * oee.performance * oee.quality) / 10000) * 100) / 100;
    }
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 4. 质量合格率 (Quality Pass Rate)
  //    公式: 合格批次数 / 总检验批次数 × 100%
  //    数据来源: qc_incoming_inspection + qc_process_inspection + qc_final_inspection
  // ========================================
  const qualityRate: Loose = {
    overall: 0,
    incoming: 0,
    process: 0,
    final: 0,
    incomingTotal: 0,
    incomingPassed: 0,
    processTotal: 0,
    processPassed: 0,
    finalTotal: 0,
    finalPassed: 0,
  };
  try {
    const incomingRows: Loose = await query(
      `
      SELECT
        COUNT(*) as total,
        SUM(CASE WHEN inspection_result IN ('qualified', '合格') THEN 1 ELSE 0 END) as passed
      FROM qc_incoming_inspection WHERE deleted = 0 ${dateFilter}
    `,
      params
    );

    qualityRate.incomingTotal = Number(incomingRows[0]?.total || 0);
    qualityRate.incomingPassed = Number(incomingRows[0]?.passed || 0);
    qualityRate.incoming =
      qualityRate.incomingTotal > 0
        ? Math.round((qualityRate.incomingPassed / qualityRate.incomingTotal) * 10000) / 100
        : 0;
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  try {
    const processRows: Loose = await query(
      `
      SELECT
        COUNT(*) as total,
        SUM(CASE WHEN inspection_result IN ('qualified', '合格', 'pass') THEN 1 ELSE 0 END) as passed
      FROM qc_process_inspection WHERE deleted = 0 ${dateFilter}
    `,
      params
    );

    qualityRate.processTotal = Number(processRows[0]?.total || 0);
    qualityRate.processPassed = Number(processRows[0]?.passed || 0);
    qualityRate.process =
      qualityRate.processTotal > 0
        ? Math.round((qualityRate.processPassed / qualityRate.processTotal) * 10000) / 100
        : 0;
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  try {
    const finalRows: Loose = await query(
      `
      SELECT
        COUNT(*) as total,
        SUM(CASE WHEN inspection_result IN ('qualified', '合格', 'pass') THEN 1 ELSE 0 END) as passed
      FROM qc_final_inspection WHERE deleted = 0 ${dateFilter}
    `,
      params
    );

    qualityRate.finalTotal = Number(finalRows[0]?.total || 0);
    qualityRate.finalPassed = Number(finalRows[0]?.passed || 0);
    qualityRate.final =
      qualityRate.finalTotal > 0
        ? Math.round((qualityRate.finalPassed / qualityRate.finalTotal) * 10000) / 100
        : 0;
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  const totalInspections =
    qualityRate.incomingTotal + qualityRate.processTotal + qualityRate.finalTotal;
  const totalPassed =
    qualityRate.incomingPassed + qualityRate.processPassed + qualityRate.finalPassed;
  qualityRate.overall =
    totalInspections > 0 ? Math.round((totalPassed / totalInspections) * 10000) / 100 : 0;

  // ========================================
  // 5. 供应商评分 (Supplier Score)
  //    公式: 质量40% + 交付30% + 价格30%
  //    数据来源: pur_supplier + 质检/交付/采购数据
  // ========================================
  let supplierScores: Loose[] = [];
  try {
    const supplierRows: Loose = await query(`
      SELECT
        ps.id, ps.supplier_name,
        COALESCE(ps.quality_score, 0) as quality_score,
        COALESCE(ps.delivery_score, 0) as delivery_score,
        COALESCE(ps.price_score, 0) as price_score,
        COALESCE(ps.overall_score, 0) as overall_score
      FROM pur_supplier ps
      WHERE ps.deleted = 0 AND ps.status = 1
      ORDER BY ps.overall_score DESC
      LIMIT 10
    `);

    if (Array.isArray(supplierRows)) {
      supplierScores = supplierRows.map((s: Loose) => {
        const q = Number(s.quality_score);
        const d = Number(s.delivery_score);
        const p = Number(s.price_score);
        const overall =
          q > 0 || d > 0 || p > 0 ? Math.round((q * 0.4 + d * 0.3 + p * 0.3) * 100) / 100 : 0;
        return {
          id: s.id,
          name: s.supplier_name,
          qualityScore: q,
          deliveryScore: d,
          priceScore: p,
          overallScore: overall,
        };
      });
    }
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 6. 客户信用额度使用率
  //    数据来源: crm_customer + sal_order
  // ========================================
  let customerCredit: Loose[] = [];
  try {
    const creditRows: Loose = await query(`
      SELECT
        cc.id, cc.customer_name,
        COALESCE(cc.credit_limit, 0) as credit_limit,
        COALESCE(cc.credit_used, 0) as credit_used,
        CASE WHEN COALESCE(cc.credit_limit, 0) > 0
          THEN ROUND(COALESCE(cc.credit_used, 0) / cc.credit_limit * 100, 2)
          ELSE 0 END as usage_rate
      FROM crm_customer cc
      WHERE cc.deleted = 0 AND COALESCE(cc.credit_limit, 0) > 0
      ORDER BY usage_rate DESC
      LIMIT 10
    `);

    if (Array.isArray(creditRows)) {
      customerCredit = creditRows.map((c: Loose) => ({
        id: c.id,
        name: c.customer_name,
        creditLimit: Number(c.credit_limit),
        creditUsed: Number(c.credit_used),
        usageRate: Number(c.usage_rate),
      }));
    }
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 7. FIFO合规率
  //    公式: 遵循FIFO的出库次数 / 总出库次数 × 100%
  //    数据来源: inv_fifo_override_log
  // ========================================
  const fifoCompliance: Loose = {
    rate: 0,
    totalOutbound: 0,
    fifoFollowed: 0,
    overrides: 0,
    pendingApprovals: 0,
  };
  try {
    const fifoRows: Loose = await query(
      `
      SELECT
        COUNT(*) as total_overrides,
        SUM(CASE WHEN approval_status = 0 THEN 1 ELSE 0 END) as pending
      FROM inv_fifo_override_log
      WHERE 1=1 ${dateFilter}
    `,
      params
    );

    const outboundRows: Loose = await query(
      `
      SELECT COUNT(*) as total
      FROM inv_inventory_transaction
      WHERE trans_type = 'out' AND deleted = 0 ${dateFilter}
    `,
      params
    );

    fifoCompliance.overrides = Number(fifoRows[0]?.total_overrides || 0);
    fifoCompliance.pendingApprovals = Number(fifoRows[0]?.pending || 0);
    fifoCompliance.totalOutbound = Number(outboundRows[0]?.total || 0);
    fifoCompliance.fifoFollowed = fifoCompliance.totalOutbound - fifoCompliance.overrides;
    fifoCompliance.rate =
      fifoCompliance.totalOutbound > 0
        ? Math.round((fifoCompliance.fifoFollowed / fifoCompliance.totalOutbound) * 10000) / 100
        : 100;
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 8. 部门协作效率
  //    数据来源: 合同评审耗时 / 打样转量产耗时
  // ========================================
  const departmentEfficiency: Loose = {
    contractReviewAvgDays: 0,
    sampleToMassAvgDays: 0,
    reviewCount: 0,
    conversionCount: 0,
  };
  try {
    const reviewRows: Loose = await query(
      `
      SELECT
        COUNT(*) as total,
        AVG(DATEDIFF(COALESCE(update_time, NOW()), create_time)) as avg_days
      FROM biz_contract_review
      WHERE deleted = 0 AND status = 3 ${dateFilter}
    `,
      params
    );

    departmentEfficiency.reviewCount = Number(reviewRows[0]?.total || 0);
    departmentEfficiency.contractReviewAvgDays =
      Math.round(Number(reviewRows[0]?.avg_days || 0) * 100) / 100;
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  try {
    const conversionRows: Loose = await query(
      `
      SELECT
        COUNT(*) as total,
        AVG(DATEDIFF(COALESCE(conversion_date, NOW()), create_time)) as avg_days
      FROM eng_sample_to_mass
      WHERE deleted = 0 AND status = 3 ${dateFilter}
    `,
      params
    );

    departmentEfficiency.conversionCount = Number(conversionRows[0]?.total || 0);
    departmentEfficiency.sampleToMassAvgDays =
      Math.round(Number(conversionRows[0]?.avg_days || 0) * 100) / 100;
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 9. 墨耗率 (Ink Consumption Rate)
  //    公式: 实际油墨消耗量 / 理论消耗量 × 100%
  //    数据来源: dcprint_ink_usage + 配方理论用量
  // ========================================
  const inkConsumptionRate: Loose = {
    rate: 0,
    actualUsage: 0,
    theoreticalUsage: 0,
    wasteRate: 0,
    byWorkOrder: [],
  };
  try {
    const inkUsageRows: Loose = await query(
      `
      SELECT
        COALESCE(SUM(actual_weight), 0) as actual_usage,
        COALESCE(SUM(theoretical_weight), 0) as theoretical_usage
      FROM dcprint_ink_usage
      WHERE deleted = 0 ${dateFilter}
    `,
      params
    );

    inkConsumptionRate.actualUsage = Number(inkUsageRows[0]?.actual_usage || 0);
    inkConsumptionRate.theoreticalUsage = Number(inkUsageRows[0]?.theoretical_usage || 0);
    if (inkConsumptionRate.theoreticalUsage > 0) {
      inkConsumptionRate.rate =
        Math.round((inkConsumptionRate.actualUsage / inkConsumptionRate.theoreticalUsage) * 10000) /
        100;
      inkConsumptionRate.wasteRate =
        Math.round(
          (1 - inkConsumptionRate.theoreticalUsage / inkConsumptionRate.actualUsage) * 10000
        ) / 100;
    }
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  try {
    const inkByWO: Loose = await query(
      `
      SELECT
        iu.work_order_no,
        SUM(iu.actual_weight) as actual_usage,
        SUM(iu.theoretical_weight) as theoretical_usage,
        CASE WHEN SUM(iu.theoretical_weight) > 0
          THEN ROUND(SUM(iu.actual_weight) / SUM(iu.theoretical_weight) * 100, 2)
          ELSE 0 END as consumption_rate
      FROM dcprint_ink_usage iu
      WHERE iu.deleted = 0 ${dateFilter}
      GROUP BY iu.work_order_no
      ORDER BY consumption_rate DESC
      LIMIT 10
    `,
      params
    );
    inkConsumptionRate.byWorkOrder = Array.isArray(inkByWO) ? inkByWO : [];
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 10. 纸张利用率 (Paper Utilization Rate)
  //     公式: 合格品数量 / 投入纸张数量 × 100%
  //     数据来源: prd_work_report + 物料出库
  // ========================================
  const paperUtilizationRate: Loose = {
    rate: 0,
    inputQty: 0,
    outputQty: 0,
    scrapQty: 0,
    byProcess: [],
  };
  try {
    const paperRows: Loose = await query(
      `
      SELECT
        COALESCE(SUM(completed_qty), 0) as total_completed,
        COALESCE(SUM(qualified_qty), 0) as total_qualified,
        COALESCE(SUM(scrap_qty), 0) as total_scrap
      FROM prd_work_report
      WHERE deleted = 0 ${dateFilter}
    `,
      params
    );

    paperUtilizationRate.outputQty = Number(paperRows[0]?.total_qualified || 0);
    paperUtilizationRate.scrapQty = Number(paperRows[0]?.total_scrap || 0);
    paperUtilizationRate.inputQty =
      Number(paperRows[0]?.total_completed || 0) + paperUtilizationRate.scrapQty;

    if (paperUtilizationRate.inputQty > 0) {
      paperUtilizationRate.rate =
        Math.round((paperUtilizationRate.outputQty / paperUtilizationRate.inputQty) * 10000) / 100;
    }
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  try {
    const paperByProcess: Loose = await query(
      `
      SELECT
        process_name,
        SUM(completed_qty) as total_completed,
        SUM(qualified_qty) as total_qualified,
        SUM(scrap_qty) as total_scrap,
        CASE WHEN SUM(completed_qty) + SUM(scrap_qty) > 0
          THEN ROUND(SUM(qualified_qty) / (SUM(completed_qty) + SUM(scrap_qty)) * 100, 2)
          ELSE 0 END as utilization_rate
      FROM prd_work_report
      WHERE deleted = 0 ${dateFilter}
      GROUP BY process_name
      ORDER BY utilization_rate ASC
    `,
      params
    );
    paperUtilizationRate.byProcess = Array.isArray(paperByProcess) ? paperByProcess : [];
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 11. 余墨再利用率 (Surplus Ink Reuse Rate)
  //     公式: 再利用余墨量 / 总余墨退回量 × 100%
  //     数据来源: dcprint_ink_surplus + ink_dispatch
  // ========================================
  const surplusInkReuseRate: Loose = {
    rate: 0,
    totalReturned: 0,
    totalReused: 0,
    totalDiscarded: 0,
    pendingReuse: 0,
  };
  try {
    const surplusRows: Loose = await query(
      `
      SELECT
        COALESCE(SUM(current_weight), 0) as total_surplus,
        COALESCE(SUM(CASE WHEN status = 'reused' THEN current_weight ELSE 0 END), 0) as total_reused,
        COALESCE(SUM(CASE WHEN status = 'discarded' THEN current_weight ELSE 0 END), 0) as total_discarded,
        COALESCE(SUM(CASE WHEN status = 'available' THEN current_weight ELSE 0 END), 0) as pending_reuse
      FROM dcprint_ink_surplus
      WHERE deleted = 0 ${dateFilter}
    `,
      params
    );

    surplusInkReuseRate.totalReturned = Number(surplusRows[0]?.total_surplus || 0);
    surplusInkReuseRate.totalReused = Number(surplusRows[0]?.total_reused || 0);
    surplusInkReuseRate.totalDiscarded = Number(surplusRows[0]?.total_discarded || 0);
    surplusInkReuseRate.pendingReuse = Number(surplusRows[0]?.pending_reuse || 0);

    if (surplusInkReuseRate.totalReturned > 0) {
      surplusInkReuseRate.rate =
        Math.round((surplusInkReuseRate.totalReused / surplusInkReuseRate.totalReturned) * 10000) /
        100;
    }
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 12. 换版时间 (Setup/Changeover Time)
  //     公式: 平均换版时间 = 总换版时间 / 换版次数
  //     数据来源: prd_work_report (工序间隔) + 设备状态
  // ========================================
  const setupTime: Loose = {
    avgMinutes: 0,
    totalSetups: 0,
    totalMinutes: 0,
    byEquipment: [],
    trend: [],
  };
  try {
    const setupRows: Loose = await query(
      `
      SELECT
        e.equipment_name,
        e.equipment_code,
        COUNT(DISTINCT wr.work_order_id) as setup_count,
        AVG(
          TIMESTAMPDIFF(MINUTE,
            LAG(wr.end_time) OVER (PARTITION BY wr.equipment_id ORDER BY wr.start_time),
            wr.start_time
          )
        ) as avg_setup_minutes
      FROM prd_work_report wr
      JOIN eqp_equipment e ON wr.equipment_id = e.id
      WHERE wr.deleted = 0 AND wr.start_time IS NOT NULL AND wr.end_time IS NOT NULL ${dateFilter}
      GROUP BY wr.equipment_id, e.equipment_name, e.equipment_code
      HAVING setup_count > 1
      ORDER BY avg_setup_minutes DESC
    `,
      params
    );

    if (Array.isArray(setupRows) && setupRows.length > 0) {
      setupTime.byEquipment = setupRows.map((r: Loose) => ({
        equipmentCode: r.equipment_code,
        equipmentName: r.equipment_name,
        setupCount: Number(r.setup_count),
        avgSetupMinutes: Math.round(Number(r.avg_setup_minutes || 0) * 100) / 100,
      }));
      setupTime.totalSetups = setupTime.byEquipment.reduce(
        (s: number, r: Loose) => s + r.setupCount,
        0
      );
      setupTime.totalMinutes = setupTime.byEquipment.reduce(
        (s: number, r: Loose) => s + r.avgSetupMinutes * r.setupCount,
        0
      );
      setupTime.avgMinutes =
        setupTime.totalSetups > 0
          ? Math.round((setupTime.totalMinutes / setupTime.totalSetups) * 100) / 100
          : 0;
    }
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 13. 首次通过率 FTQ (First Time Quality)
  //     公式: 首检合格次数 / 总首检次数 × 100%
  //     数据来源: prd_work_report (is_first_piece + first_piece_status)
  // ========================================
  const ftq: Loose = { rate: 0, totalFirstPiece: 0, passedFirstPiece: 0, failedFirstPiece: 0 };
  try {
    const ftqRows: Loose = await query(
      `
      SELECT
        COUNT(*) as total,
        SUM(CASE WHEN first_piece_status IN ('qualified', '合格', 'pass', '1') THEN 1 ELSE 0 END) as passed
      FROM prd_work_report
      WHERE deleted = 0 AND is_first_piece = 1 ${dateFilter}
    `,
      params
    );

    ftq.totalFirstPiece = Number(ftqRows[0]?.total || 0);
    ftq.passedFirstPiece = Number(ftqRows[0]?.passed || 0);
    ftq.failedFirstPiece = ftq.totalFirstPiece - ftq.passedFirstPiece;
    ftq.rate =
      ftq.totalFirstPiece > 0
        ? Math.round((ftq.passedFirstPiece / ftq.totalFirstPiece) * 10000) / 100
        : 0;
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 14. 呆滞库存率 (Stale Inventory Rate)
  //     公式: 过期/冻结批次价值 / 总库存价值 × 100%
  //     数据来源: inv_inventory_batch
  // ========================================
  const staleInventoryRate: Loose = {
    rate: 0,
    totalInventoryValue: 0,
    staleValue: 0,
    expiredValue: 0,
    frozenValue: 0,
    nearExpiryValue: 0,
  };
  try {
    const staleRows: Loose = await query(`
      SELECT
        COALESCE(SUM(available_qty * unit_price), 0) as total_value,
        COALESCE(SUM(CASE WHEN status = 'expired' OR (expire_date IS NOT NULL AND expire_date < CURDATE()) THEN available_qty * unit_price ELSE 0 END), 0) as expired_value,
        COALESCE(SUM(CASE WHEN status = 'frozen' THEN available_qty * unit_price ELSE 0 END), 0) as frozen_value,
        COALESCE(SUM(CASE WHEN expire_date IS NOT NULL AND DATEDIFF(expire_date, CURDATE()) BETWEEN 0 AND 30 AND status = 'normal' THEN available_qty * unit_price ELSE 0 END), 0) as near_expiry_value
      FROM inv_inventory_batch
      WHERE deleted = 0
    `);

    staleInventoryRate.totalInventoryValue = Number(staleRows[0]?.total_value || 0);
    staleInventoryRate.expiredValue = Number(staleRows[0]?.expired_value || 0);
    staleInventoryRate.frozenValue = Number(staleRows[0]?.frozen_value || 0);
    staleInventoryRate.nearExpiryValue = Number(staleRows[0]?.near_expiry_value || 0);
    staleInventoryRate.staleValue =
      staleInventoryRate.expiredValue + staleInventoryRate.frozenValue;
    staleInventoryRate.rate =
      staleInventoryRate.totalInventoryValue > 0
        ? Math.round(
            (staleInventoryRate.staleValue / staleInventoryRate.totalInventoryValue) * 10000
          ) / 100
        : 0;
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  // ========================================
  // 15. OEE 六大损失分类
  //     数据来源: 设备故障/设置调整/闲置/小停机/速度损失/废品
  // ========================================
  const oeeLossAnalysis: Loose = {
    breakdownLoss: 0,
    setupLoss: 0,
    idleLoss: 0,
    minorStopLoss: 0,
    speedLoss: 0,
    defectLoss: 0,
  };
  try {
    const lossRows: Loose = await query(
      `
      SELECT
        COALESCE(SUM(CASE WHEN current_status = 4 THEN 1 ELSE 0 END), 0) as breakdown_count,
        COUNT(DISTINCT CASE WHEN process_name IN ('模切', '丝印印刷') THEN work_order_id END) as setup_count,
        COALESCE(SUM(CASE WHEN current_status = 2 THEN 1 ELSE 0 END), 0) as idle_count
      FROM prd_work_report wr
      LEFT JOIN eqp_equipment e ON 1=1
      WHERE wr.deleted = 0 ${dateFilter}
    `,
      params
    );

    oeeLossAnalysis.breakdownLoss = Number(lossRows[0]?.breakdown_count || 0);
    oeeLossAnalysis.setupLoss = Number(lossRows[0]?.setup_count || 0);
    oeeLossAnalysis.idleLoss = Number(lossRows[0]?.idle_count || 0);
  } catch (e) {
    logger.error({ module: 'dashboard', action: 'kpi' }, 'Dashboard query failed', {
