);

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { logger } from '@/lib/logger';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const workorderNo = searchParams.get('workorderNo') || '';
  const period = searchParams.get('period') || 'month';
  const startDate = searchParams.get('startDate') || '';
  const endDate = searchParams.get('endDate') || '';

  let dateFilter = '';
  const params: Loose[] = [];

  if (workorderNo) {
    dateFilter = 'AND u.workorder_no = ?';
    params.push(workorderNo);
  } else if (startDate && endDate) {
    dateFilter = 'AND u.usage_time BETWEEN ? AND ?';
    params.push(startDate, endDate);
  } else if (period === 'week') {
    dateFilter = 'AND u.usage_time >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)';
  } else if (period === 'month') {
    dateFilter = 'AND u.usage_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)';
  } else if (period === 'quarter') {
    dateFilter = 'AND u.usage_time >= DATE_SUB(CURDATE(), INTERVAL 90 DAY)';
  }

  let workorderAnalysis: Loose[] = [];
  try {
    workorderAnalysis = await query(
      `
      SELECT
        u.workorder_no,
        d.color_name,
        d.pantone_code,
        d.total_weight as formula_weight,
        d.net_weight as actual_dispatch_weight,
        COALESCE(SUM(CASE WHEN u.usage_type = 'consumption' THEN u.weight ELSE 0 END), 0) as total_consumed,
        COALESCE(SUM(CASE WHEN u.usage_type = 'return' THEN u.weight ELSE 0 END), 0) as total_returned,
        COALESCE(SUM(CASE WHEN u.usage_type = 'scrap' THEN u.weight ELSE 0 END), 0) as total_scraped,
        d.total_weight - COALESCE(SUM(CASE WHEN u.usage_type = 'consumption' THEN u.weight ELSE 0 END), 0) as waste_amount,
        CASE WHEN d.total_weight > 0
          THEN ROUND((d.total_weight - COALESCE(SUM(CASE WHEN u.usage_type = 'consumption' THEN u.weight ELSE 0 END), 0)) / d.total_weight * 100, 2)
          ELSE 0 END as waste_rate,
        COUNT(DISTINCT u.id) as usage_count
      FROM ink_dispatch d
      LEFT JOIN ink_usage u ON u.batch_no = d.batch_no AND u.deleted = 0 ${dateFilter.replace('u.', 'u.')}
      WHERE d.deleted = 0 AND d.workorder_no IS NOT NULL
      GROUP BY d.batch_no, d.workorder_no, d.color_name, d.pantone_code, d.total_weight, d.net_weight
      ORDER BY waste_rate DESC
    `,
      params
    );
  } catch (e) {
    logger.error({ module: 'dcprint', action: 'ink-consumption' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  let inkTypeSummary: Loose[] = [];
  try {
    inkTypeSummary = await query(
      `
      SELECT
        f.ink_type,
        COUNT(DISTINCT d.id) as dispatch_count,
        SUM(d.total_weight) as total_formula_weight,
        SUM(d.net_weight) as total_actual_weight,
        COALESCE(SUM(CASE WHEN u.usage_type = 'consumption' THEN u.weight ELSE 0 END), 0) as total_consumed,
        COALESCE(SUM(CASE WHEN u.usage_type = 'return' THEN u.weight ELSE 0 END), 0) as total_returned,
        COALESCE(SUM(CASE WHEN u.usage_type = 'scrap' THEN u.weight ELSE 0 END), 0) as total_scraped
      FROM ink_dispatch d
      LEFT JOIN ink_formula f ON d.formula_id = f.id
      LEFT JOIN ink_usage u ON u.batch_no = d.batch_no AND u.deleted = 0 ${dateFilter.replace('u.', 'u.')}
      WHERE d.deleted = 0
      GROUP BY f.ink_type
    `,
      params
    );
  } catch (e) {
    logger.error({ module: 'dcprint', action: 'ink-consumption' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  let topWasteItems: Loose[] = [];
  try {
    topWasteItems = await query(
      `
      SELECT
        di.ink_name,
        di.brand,
        SUM(di.formula_weight) as total_formula,
        SUM(di.actual_weight) as total_actual,
        SUM(di.actual_weight) - SUM(di.formula_weight) as overage,
        CASE WHEN SUM(di.formula_weight) > 0
          THEN ROUND((SUM(di.actual_weight) - SUM(di.formula_weight)) / SUM(di.formula_weight) * 100, 2)
          ELSE 0 END as overage_rate
      FROM ink_dispatch_item di
      INNER JOIN ink_dispatch d ON di.dispatch_id = d.id
      WHERE di.deleted = 0 AND d.deleted = 0 ${dateFilter.replace('u.', 'd.')}
      GROUP BY di.ink_name, di.brand
      HAVING overage > 0
      ORDER BY overage DESC
      LIMIT 10
    `,
      params
    );
  } catch (e) {
    logger.error({ module: 'dcprint', action: 'ink-consumption' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  let dailyTrend: Loose[] = [];
  try {
    dailyTrend = await query(
      `
      SELECT
        DATE(u.usage_time) as date,
        SUM(CASE WHEN u.usage_type = 'consumption' THEN u.weight ELSE 0 END) as consumed,
        SUM(CASE WHEN u.usage_type = 'return' THEN u.weight ELSE 0 END) as returned,
        SUM(CASE WHEN u.usage_type = 'scrap' THEN u.weight ELSE 0 END) as scraped,
        COUNT(*) as usage_count
      FROM ink_usage u
      WHERE u.deleted = 0 ${dateFilter}
      GROUP BY DATE(u.usage_time)
      ORDER BY date
    `,
      params
    );
  } catch (e) {
    logger.error({ module: 'dcprint', action: 'ink-consumption' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  const summary: Loose = {
    total_dispatch: 0,
    total_consumed: 0,
    total_returned: 0,
    total_scraped: 0,
    overall_waste_rate: 0,
    avg_per_workorder: 0,
  };
  try {
    const summaryRows: Loose = await query(
      `
      SELECT
        COALESCE(SUM(d.total_weight), 0) as total_dispatch,
        COALESCE(SUM(CASE WHEN u.usage_type = 'consumption' THEN u.weight ELSE 0 END), 0) as total_consumed,
        COALESCE(SUM(CASE WHEN u.usage_type = 'return' THEN u.weight ELSE 0 END), 0) as total_returned,
        COALESCE(SUM(CASE WHEN u.usage_type = 'scrap' THEN u.weight ELSE 0 END), 0) as total_scraped,
        COUNT(DISTINCT d.id) as dispatch_count
      FROM ink_dispatch d
      LEFT JOIN ink_usage u ON u.batch_no = d.batch_no AND u.deleted = 0 ${dateFilter.replace('u.', 'u.')}
      WHERE d.deleted = 0
    `,
      params
    );

    if (summaryRows.length > 0) {
      const s = summaryRows[0];
      summary.total_dispatch = Number(s.total_dispatch || 0);
      summary.total_consumed = Number(s.total_consumed || 0);
      summary.total_returned = Number(s.total_returned || 0);
      summary.total_scraped = Number(s.total_scraped || 0);
      summary.overall_waste_rate =
        summary.total_dispatch > 0
          ? Math.round(
              ((summary.total_dispatch - summary.total_consumed) / summary.total_dispatch) * 10000
            ) / 100
          : 0;
      summary.avg_per_workorder =
        Number(s.dispatch_count || 0) > 0
          ? Math.round((summary.total_consumed / Number(s.dispatch_count)) * 100) / 100
          : 0;
    }
  } catch (e) {
    logger.error({ module: 'dcprint', action: 'ink-consumption' }, 'Dashboard query failed', {
      error: e instanceof Error ? e.message : String(e),
    });
  }

  return successResponse({
    summary,
    workorderAnalysis,
    inkTypeSummary,
    topWasteItems,
    dailyTrend,
    period,
  });
});

import { NextRequest } from 'next/server';
import { query, execute, transaction } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { randomUUID } from 'crypto';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const keyword = searchParams.get('keyword') || '';
  const status = searchParams.get('status') || '';
  const workorderNo = searchParams.get('workorderNo') || '';

  let where = 'WHERE d.deleted = 0';
  const params: Loose[] = [];

  if (keyword) {
    where += ' AND (d.dispatch_no LIKE ? OR d.color_name LIKE ?)';
    const like = `%${keyword}%`;
    params.push(like, like);
  }
  if (status) {
    where += ' AND d.status = ?';
    params.push(Number(status));
  }
  if (workorderNo) {
    where += ' AND d.workorder_no = ?';
    params.push(workorderNo);
  }

  const totalRows: Loose = await query(
    `SELECT COUNT(*) as total FROM ink_dispatch d ${where}`,
    params
  );
  const total = totalRows[0]?.total || 0;

  const rows: Loose = await query(
    `SELECT d.* FROM ink_dispatch d ${where} ORDER BY d.create_time DESC LIMIT ? OFFSET ?`,
    [...params, pageSize, (page - 1) * pageSize]
  );

  for (const row of rows) {
    const items: Loose = await query(
      'SELECT * FROM ink_dispatch_item WHERE dispatch_id = ? AND deleted = 0 ORDER BY sort_order',
      [row.id]
    );
    row.items = items;
  }

  return successResponse({ list: rows, total, page, pageSize });
});

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const {
      workorder_id,
      workorder_no,
      formula_id,
      formula_no,
      color_name,
      color_code,
      pantone_code,
      total_weight,
      unit,
      operator_id,
      operator_name,
      machine_id,
      machine_name,
      items,
      tare_weight,
      net_weight,
      gross_weight,
      remark,
    } = body;

    if (!workorder_no || !items || !Array.isArray(items) || items.length === 0) {
      return errorResponse('缺少必填字段: workorder_no, items', 400, 400);
    }

    const result = await transaction(async (conn) => {
      const now = new Date();
      const dispatchNo =
        'DS' +
        now.getFullYear() +
        String(now.getMonth() + 1).padStart(2, '0') +
        String(now.getDate()).padStart(2, '0') +
        String(Math.floor(Math.random() * 10000)).padStart(4, '0');

      const batchNo = `INK${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}${String(Math.floor(Math.random() * 10000)).padStart(4, '0')}`;

      const [insertResult]: Loose = await conn.execute(
        `INSERT INTO ink_dispatch (dispatch_no, batch_no, workorder_id, workorder_no, formula_id, formula_no, color_name, color_code, pantone_code, total_weight, unit, tare_weight, net_weight, gross_weight, operator_id, operator_name, machine_id, machine_name, status, remark)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)`,
        [
          dispatchNo,
          batchNo,
          workorder_id || null,
          workorder_no,
          formula_id || null,
          formula_no || null,
          color_name || null,
          color_code || null,
          pantone_code || null,
          total_weight || null,
          unit || 'kg',
          tare_weight || 0,
          net_weight || null,
          gross_weight || null,
          operator_id || null,
          operator_name || null,
          machine_id || null,
          machine_name || null,
          remark || null,
        ]
      );
      const dispatchId = insertResult.insertId;

      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        const isSurplus = item.source_type === 'surplus';
        const sourceBatchNo = item.source_batch_no || null;

        if (sourceBatchNo && Number(item.actual_weight || 0) > 0) {
          const [batchRows]: Loose = await conn.execute(
            'SELECT id, available_qty, material_name FROM inv_inventory_batch WHERE batch_no = ? AND deleted = 0 FOR UPDATE',
            [sourceBatchNo]
          );

          if (batchRows.length > 0) {
            const batch = batchRows[0];
            if (Number(batch.available_qty) < Number(item.actual_weight || 0)) {
              throw new Error(
                `原墨 ${batch.material_name} 批次 ${sourceBatchNo} 库存不足: 可用 ${batch.available_qty}, 需用 ${item.actual_weight}`
              );
            }

            await conn.execute(
              'UPDATE inv_inventory_batch SET available_qty = available_qty - ? WHERE id = ?',
              [item.actual_weight, batch.id]
            );
          }
        }

        await conn.execute(
          `INSERT INTO ink_dispatch_item (dispatch_id, sort_order, source_type, source_batch_no, source_label_no, ink_id, ink_code, ink_name, ink_type, brand, formula_weight, actual_weight, unit, is_surplus)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          [
            dispatchId,
            i + 1,
            item.source_type || 'fresh',
            sourceBatchNo,
            item.source_label_no || null,
            item.ink_id || null,
            item.ink_code || null,
            item.ink_name || '',
            item.ink_type || null,
            item.brand || null,
            item.formula_weight || 0,
            item.actual_weight || 0,
            item.unit || 'kg',
            isSurplus ? 1 : 0,
          ]
        );
      }

      const qrCode = 'IK-' + randomUUID().replace(/-/g, '').substring(0, 16);
      await conn.execute(
        `INSERT INTO qrcode_record (qr_code, qr_type, ref_id, ref_no, batch_no, material_id, material_code, material_name, quantity, unit, warehouse_id, expiry_date, status, extra_data)
       VALUES (?, 'ink_dispatch', ?, ?, ?, NULL, NULL, ?, ?, ?, NULL, ?, 1, ?)`,
        [
          qrCode,
          dispatchId,
          dispatchNo,
          batchNo,
          color_name || `专色墨-${batchNo}`,
          net_weight || total_weight || 0,
          unit || 'kg',
          null,
          JSON.stringify({
            dispatch_no: dispatchNo,
            batch_no: batchNo,
            workorder_no,
            formula_no: formula_no || '',
            color_name: color_name || '',
            pantone_code: pantone_code || '',
            tare_weight: tare_weight || 0,
            net_weight: net_weight || total_weight || 0,
            gross_weight: gross_weight || 0,
            operator_name: operator_name || '',
            item_count: items.length,
          }),
        ]
      );

      const [whRows]: Loose = await conn.execute(
        "SELECT id FROM inv_warehouse WHERE warehouse_name LIKE '%调色%' AND deleted = 0 LIMIT 1"
      );
      const warehouseId = whRows.length > 0 ? whRows[0].id : null;

      if (warehouseId && (net_weight || total_weight)) {
        await conn.execute(
          `INSERT INTO inv_inventory_batch (batch_no, material_id, material_code, material_name, warehouse_id, available_qty, quantity, unit_price, inbound_date, status, produce_date, create_time)
         VALUES (?, NULL, ?, ?, ?, ?, ?, 0, ?, 'normal', ?, NOW())`,
          [
            batchNo,
            `INK-${batchNo}`,
            color_name || `专色墨-${batchNo}`,
            warehouseId,
            net_weight || total_weight,
            net_weight || total_weight,
            now.toISOString().slice(0, 10),
            now.toISOString().slice(0, 10),
          ]
        );
      }

      return { id: dispatchId, dispatch_no: dispatchNo, batch_no: batchNo, qr_code: qrCode };
    });

    return successResponse(result, '调色配料记录创建成功');
  },
  { logTitle: '调色配料', logType: 'business' }
);

export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { id, action, status, tare_weight, net_weight, gross_weight, remark } = body;

    if (!id) {
      return errorResponse('配料记录ID不能为空', 400, 400);
    }

    if (action === 'weigh') {
      await transaction(async (conn) => {
        await conn.execute(
          `UPDATE ink_dispatch SET tare_weight = ?, net_weight = ?, gross_weight = ?, status = 2 WHERE id = ?`,
          [tare_weight || 0, net_weight || 0, gross_weight || 0, id]
        );

        const [dispatchRows]: Loose = await conn.execute(
          'SELECT batch_no, net_weight, total_weight FROM ink_dispatch WHERE id = ?',
          [id]
        );

        if (dispatchRows.length > 0 && dispatchRows[0].batch_no) {
          const actualWeight = net_weight || dispatchRows[0].total_weight || 0;
          await conn.execute(
            'UPDATE inv_inventory_batch SET available_qty = ?, quantity = ? WHERE batch_no = ? AND deleted = 0',
            [actualWeight, actualWeight, dispatchRows[0].batch_no]
          );
        }
      });
      return successResponse(null, '称重赋码完成');
    }

    if (action === 'confirm') {
      await execute('UPDATE ink_dispatch SET status = 3 WHERE id = ?', [id]);
      return successResponse(null, '配料确认完成');
    }

    if (status !== undefined) {
      await execute('UPDATE ink_dispatch SET status = ? WHERE id = ?', [status, id]);
    }
    if (remark !== undefined) {
      await execute('UPDATE ink_dispatch SET remark = ? WHERE id = ?', [remark, id]);
    }

    return successResponse(null, '更新成功');
  },
  { logTitle: '更新调色配料', logType: 'business' }
);

import { NextRequest } from 'next/server';
import { query, execute, transaction } from '@/lib/db';
