import { NextRequest } from 'next/server';
import { query, execute, queryOne, transaction } from '@/lib/db';
import {
  successResponse,
  errorResponse,
  commonErrors,
  validateRequestBody,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { randomUUID } from 'crypto';
import { isInkUnopenedShelfLife, getInkOpenedShelfLife } from '@/lib/global-config';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');
  const keyword = searchParams.get('keyword') || '';
  const status = searchParams.get('status');
  const ink_type = searchParams.get('ink_type');
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '20');

  if (id) {
    const record = await queryOne('SELECT * FROM ink_opening_record WHERE id = ? AND deleted = 0', [
      parseInt(id),
    ]);
    if (!record) return commonErrors.notFound('油墨开罐记录不存在');
    return successResponse(record);
  }

  let sql = `SELECT * FROM ink_opening_record WHERE deleted = 0`;
  const values: Loose[] = [];

  if (keyword) {
    sql += ` AND (record_no LIKE ? OR material_code LIKE ? OR material_name LIKE ? OR batch_no LIKE ?)`;
    const like = `%${keyword}%`;
    values.push(like, like, like, like);
  }
  if (status) {
    sql += ' AND status = ?';
    values.push(parseInt(status));
  }
  if (ink_type) {
    sql += ' AND ink_type = ?';
    values.push(ink_type);
  }

  sql += ' ORDER BY open_time DESC LIMIT ? OFFSET ?';
  values.push(pageSize, (page - 1) * pageSize);

  const list = await query(sql, values);

  const countSql = `SELECT COUNT(*) as total FROM ink_opening_record WHERE deleted = 0`;
  const countResult = (await queryOne(countSql)) as Loose;

  const summarySql = `SELECT
    COUNT(*) as total_count,
    COALESCE(SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END), 0) as using_count,
    COALESCE(SUM(CASE WHEN status = 2 THEN 1 ELSE 0 END), 0) as expired_count,
    COALESCE(SUM(CASE WHEN status = 3 THEN 1 ELSE 0 END), 0) as scrapped_count,
    COALESCE(SUM(CASE WHEN status = 1 AND expire_time < NOW() THEN 1 ELSE 0 END), 0) as overdue_using_count
  FROM ink_opening_record WHERE deleted = 0`;
  const summary = (await queryOne(summarySql)) as Loose;

  const overdueSql = `SELECT * FROM ink_opening_record
    WHERE deleted = 0 AND status = 1 AND expire_time < NOW()
    ORDER BY expire_time ASC LIMIT 10`;
  const overdueList = await query(overdueSql);

  return successResponse({
    list,
    total: countResult?.total || 0,
    page,
    pageSize,
    summary: {
      total_count: parseInt(summary?.total_count || 0),
      using_count: parseInt(summary?.using_count || 0),
      expired_count: parseInt(summary?.expired_count || 0),
      scrapped_count: parseInt(summary?.scrapped_count || 0),
      overdue_using_count: parseInt(summary?.overdue_using_count || 0),
    },
    overdue_list: overdueList,
  });
});

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const validation = validateRequestBody(body, ['material_id', 'open_time', 'expire_hours']);
    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    const {
      material_id,
      material_code,
      material_name,
      batch_no,
      label_id,
      ink_type,
      open_time,
      expire_hours,
      remaining_qty,
      unit,
      operator_id,
      operator_name,
      remark,
      workorder_id,
      workorder_no,
    } = body;

    if (batch_no) {
      const expiredOpening: Loose = await queryOne(
        `SELECT id, record_no, expire_time FROM ink_opening_record
       WHERE batch_no = ? AND material_id = ? AND status = 1 AND deleted = 0 AND expire_time < NOW()
       ORDER BY expire_time DESC LIMIT 1`,
        [batch_no, material_id]
      );
      if (expiredOpening) {
        return errorResponse(
          `该批次油墨已有过期开盖记录(${expiredOpening.record_no}，过期时间: ${expiredOpening.expire_time})，请先报废后再重新开盖`,
          400,
          400
        );
      }

      const activeOpening: Loose = await queryOne(
        `SELECT id, record_no, expire_time FROM ink_opening_record
       WHERE batch_no = ? AND material_id = ? AND status = 1 AND deleted = 0 AND expire_time >= NOW()
       ORDER BY expire_time DESC LIMIT 1`,
        [batch_no, material_id]
      );
      if (activeOpening) {
        return errorResponse(
          `该批次油墨已有生效中的开盖记录(${activeOpening.record_no}，过期时间: ${activeOpening.expire_time})，请勿重复开盖`,
          409,
          409
        );
      }
    }

    const INK_SHELF_LIFE: Record<string, number> = {
      solvent: isInkUnopenedShelfLife(),
      uv: isInkUnopenedShelfLife() * 4,
      water: getInkOpenedShelfLife(),
    };

    const result = await transaction(async (conn) => {
      const recordNo = `INK${Date.now()}`;

      let actualExpireHours = expire_hours;
      if (!actualExpireHours && ink_type) {
        actualExpireHours = INK_SHELF_LIFE[ink_type] || isInkUnopenedShelfLife();
      } else if (!actualExpireHours) {
        actualExpireHours = isInkUnopenedShelfLife();
      }

      const expireTime = new Date(new Date(open_time).getTime() + actualExpireHours * 3600000)
        .toISOString()
        .slice(0, 19)
        .replace('T', ' ');

      let finalExpireTime = expireTime;
      if (batch_no) {
        const [batchRows]: Loose = await conn.execute(
          'SELECT expire_date FROM inv_inventory_batch WHERE batch_no = ? AND deleted = 0',
          [batch_no]
        );
        if (batchRows.length > 0 && batchRows[0].expire_date) {
          const batchExpire = new Date(batchRows[0].expire_date);
          const calculatedExpire = new Date(expireTime);
          if (batchExpire < calculatedExpire) {
            finalExpireTime = batchExpire.toISOString().slice(0, 19).replace('T', ' ');
          }
        }
      }

      const [insertResult]: Loose = await conn.execute(
        `INSERT INTO ink_opening_record (record_no, material_id, material_code, material_name, batch_no, label_id, ink_type, open_time, expire_hours, expire_time, remaining_qty, unit, status, operator_id, operator_name, remark)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?)`,
        [
          recordNo,
          material_id,
          material_code || null,
          material_name || null,
          batch_no || null,
          label_id || null,
          ink_type || null,
          open_time,
          actualExpireHours,
          finalExpireTime,
          remaining_qty || null,
          unit || null,
          operator_id || null,
          operator_name || null,
          remark || null,
        ]
      );
      const insertId = insertResult.insertId;

      if (workorder_id || workorder_no) {
        try {
          await conn.execute(
            `INSERT INTO ink_usage (usage_no, usage_type, batch_no, workorder_id, workorder_no, color_name, weight, unit, operator_id, operator_name, status, remark)
           VALUES (?, 'requisition', ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)`,
            [
              'IU' + Date.now(),
              batch_no || recordNo,
              workorder_id || null,
              workorder_no || null,
              material_name || '',
              remaining_qty || 0,
              unit || 'kg',
              operator_id || null,
              operator_name || null,
              `开罐领用 - ${recordNo}`,
            ]
          );
        } catch {}
      }

      if (batch_no) {
        await conn.execute(
          `UPDATE inv_inventory_batch SET expire_date = ?, status = CASE WHEN ? < NOW() THEN 'expired' ELSE status END WHERE batch_no = ? AND deleted = 0`,
          [finalExpireTime, finalExpireTime, batch_no]
        );
      }

      const qrCode = 'IK-' + randomUUID().replace(/-/g, '').substring(0, 16);
      await conn.execute(
        `INSERT INTO qrcode_record (qr_code, qr_type, ref_id, ref_no, material_id, material_code, material_name, batch_no, quantity, unit, expiry_date, status, extra_data)
       VALUES (?, 'ink_open', ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)`,
        [
          qrCode,
          insertId,
          recordNo,
          material_id,
          material_code || null,
          material_name || null,
          batch_no || null,
          remaining_qty || 0,
          unit || null,
          finalExpireTime,
          JSON.stringify({
            ink_type,
            open_time,
            expire_hours: actualExpireHours,
            workorder_no: workorder_no || null,
          }),
        ]
      );

      return { id: insertId, record_no: recordNo, expire_time: finalExpireTime, qr_code: qrCode };
    });

    return successResponse(result, '油墨开罐记录创建成功');
  },
  { logTitle: '油墨开罐', logType: 'business' }
);

export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    if (!body.id) return commonErrors.badRequest('记录ID不能为空');

    const existing = await queryOne(
      'SELECT id, status FROM ink_opening_record WHERE id = ? AND deleted = 0',
      [body.id]
    );
    if (!existing) return commonErrors.notFound('油墨开罐记录不存在');

    if (body.status !== undefined) {
      const allowedStatus = [1, 2, 3];
      if (!allowedStatus.includes(body.status)) {
        return errorResponse('无效的状态值', 400, 400);
      }
      await execute('UPDATE ink_opening_record SET status = ? WHERE id = ?', [
        body.status,
        body.id,
      ]);
      return successResponse(null, '状态更新成功');
    }

    const fields: string[] = [];
    const values: Loose[] = [];
    const allowedFields = ['remaining_qty', 'remark'];
    for (const field of allowedFields) {
      if (body[field] !== undefined) {
        fields.push(`${field} = ?`);
        values.push(body[field]);
      }
    }
    if (fields.length > 0) {
      values.push(body.id);
      await execute(`UPDATE ink_opening_record SET ${fields.join(', ')} WHERE id = ?`, values);
    }

    return successResponse(null, '油墨开罐记录更新成功');
  },
  { logTitle: '更新油墨开罐记录', logType: 'business' }
);

export const DELETE = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    if (!id) return commonErrors.badRequest('记录ID不能为空');

    const existing = await queryOne(
      'SELECT id, status FROM ink_opening_record WHERE id = ? AND deleted = 0',
      [parseInt(id)]
    );
    if (!existing) return commonErrors.notFound('油墨开罐记录不存在');

    await execute('UPDATE ink_opening_record SET deleted = 1 WHERE id = ?', [parseInt(id)]);
    return successResponse(null, '油墨开罐记录删除成功');
  },
  { logTitle: '删除油墨开罐记录', logType: 'business' }
);

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const qrCode = searchParams.get('qrCode') || '';
  const batchNo = searchParams.get('batchNo') || '';
  const queryType = searchParams.get('queryType') || 'all';

  if (!qrCode && !batchNo) {
    return errorResponse('请提供qrCode或batchNo', 400, 400);
  }

  let actualBatchNo = batchNo;

  if (qrCode && !batchNo) {
    const qrRows: Loose = await query(
      'SELECT batch_no, qr_type, ref_id, ref_no, extra_data FROM qrcode_record WHERE qr_code = ? AND deleted = 0',
      [qrCode]
    );
    if (qrRows.length === 0) {
      return errorResponse('二维码不存在', 404, 404);
    }
    actualBatchNo = qrRows[0].batch_no;
  }

  if (!actualBatchNo) {
    return errorResponse('无法确定批次号', 400, 400);
  }

  const result: Loose = {};

  if (queryType === 'all' || queryType === 'formula') {
    result.formula = await queryFormulaTrace(actualBatchNo);
  }

  if (queryType === 'all' || queryType === 'process') {
    result.process = await queryProcessGuide(actualBatchNo);
  }

  if (queryType === 'all' || queryType === 'quality') {
    result.quality = await queryQualityTrace(actualBatchNo);
  }

  if (queryType === 'all' || queryType === 'inventory') {
    result.inventory = await queryInventoryExpiry(actualBatchNo);
  }

  return successResponse(result);
});

async function queryFormulaTrace(batchNo: string) {
  const trace: Loose = { batch_no: batchNo, formula: null, raw_inks: [], dispatch: null };

  const dispatchRows: Loose = await query(
    'SELECT * FROM ink_dispatch WHERE batch_no = ? AND deleted = 0',
    [batchNo]
  );

  if (dispatchRows.length > 0) {
    const dispatch = dispatchRows[0];
    trace.dispatch = {
      dispatch_no: dispatch.dispatch_no,
      workorder_no: dispatch.workorder_no,
      color_name: dispatch.color_name,
      pantone_code: dispatch.pantone_code,
      total_weight: dispatch.total_weight,
      net_weight: dispatch.net_weight,
      operator_name: dispatch.operator_name,
      create_time: dispatch.create_time,
    };

    if (dispatch.formula_id) {
      const formulaRows: Loose = await query(
        'SELECT * FROM ink_formula WHERE id = ? AND deleted = 0',
        [dispatch.formula_id]
      );
      if (formulaRows.length > 0) {
        const formula = formulaRows[0];
        const items: Loose = await query(
          'SELECT * FROM ink_formula_item WHERE formula_id = ? AND deleted = 0 ORDER BY sort_order',
          [formula.id]
        );

        trace.formula = {
          formula_no: formula.formula_no,
          formula_name: formula.formula_name,
          pantone_code: formula.pantone_code,
          color_name: formula.color_name,
          ink_type: formula.ink_type,
          total_weight: formula.total_weight,
          shelf_life_hours: formula.shelf_life_hours,
          items: items.map((item: Loose) => ({
            ink_name: item.ink_name,
            ink_code: item.ink_code,
            brand: item.brand,
            ratio_percent: item.ratio_percent,
            weight: item.weight,
            is_base: item.is_base,
          })),
        };
      }
    }

    const dispatchItems: Loose = await query(
      'SELECT * FROM ink_dispatch_item WHERE dispatch_id = ? AND deleted = 0 ORDER BY sort_order',
      [dispatch.id]
    );

    trace.raw_inks = dispatchItems.map((item: Loose) => ({
      ink_name: item.ink_name,
      ink_code: item.ink_code,
      brand: item.brand,
      formula_weight: item.formula_weight,
      actual_weight: item.actual_weight,
      source_type: item.source_type,
      source_batch_no: item.source_batch_no,
      is_surplus: item.is_surplus,
    }));
  }

  const mixedRows: Loose = await query(
    'SELECT * FROM ink_mixed_record WHERE record_no = ? AND deleted = 0',
    [batchNo]
  );

  if (mixedRows.length > 0 && !trace.dispatch) {
    const mixed = mixedRows[0];
    trace.dispatch = {
      record_no: mixed.record_no,
      color_name: mixed.color_name,
      color_code: mixed.color_code,
      quantity: mixed.quantity,
      operator_name: mixed.operator_name,
      mix_time: mixed.mix_time,
    };
    trace.raw_inks = mixed.mix_ratio ? [{ description: mixed.mix_ratio }] : [];
  }

  return trace;
}

async function queryProcessGuide(batchNo: string) {
  const guide: Loose = { batch_no: batchNo, workorder: null, sop: null, process_card: null };

  const dispatchRows: Loose = await query(
