    );

    if (woRows.length > 0) {
      const wo = woRows[0];
      guide.workorder = {
        order_no: wo.order_no,
        product_name: wo.product_name,
        plan_qty: wo.plan_qty,
        status: wo.status,
        plan_start_date: wo.plan_start_date,
