async function queryQualityTrace(batchNo: string) {
  const trace: Loose = { batch_no: batchNo, inspection: null, usage_history: [], supplier: null };

  const batchRows: Loose = await query(
    'SELECT * FROM inv_inventory_batch WHERE batch_no = ? AND deleted = 0',
    [batchNo]
  );

  if (batchRows.length > 0) {
    const batch = batchRows[0];

    if (batch.inspection_id) {
      const inspRows: Loose = await query(
        'SELECT * FROM qc_incoming_inspection WHERE id = ? AND deleted = 0',
        [batch.inspection_id]
      );
      if (inspRows.length > 0) {
        trace.inspection = {
          inspection_no: inspRows[0].inspection_no,
          inspection_result: inspRows[0].inspection_result,
          inspector_name: inspRows[0].inspector_name,
          inspection_date: inspRows[0].inspection_date,
        };
      }
    }

    const usageRows: Loose = await query(
      `SELECT usage_type, workorder_no, weight, operator_name, machine_name, usage_time
       FROM ink_usage WHERE batch_no = ? AND deleted = 0 ORDER BY usage_time DESC`,
      [batchNo]
    );
    trace.usage_history = usageRows;

    const dispatchRows: Loose = await query(
      'SELECT id FROM ink_dispatch WHERE batch_no = ? AND deleted = 0',
      [batchNo]
    );

    if (dispatchRows.length > 0) {
      const dispatchItems: Loose = await query(
        'SELECT source_batch_no, ink_name, brand FROM ink_dispatch_item WHERE dispatch_id = ? AND deleted = 0',
        [dispatchRows[0].id]
      );

      for (const item of dispatchItems) {
        if (item.source_batch_no) {
          const sourceBatch: Loose = await query(
            'SELECT supplier_name FROM inv_inventory_batch WHERE batch_no = ? AND deleted = 0',
            [item.source_batch_no]
          );
          if (sourceBatch.length > 0 && sourceBatch[0].supplier_name) {
            trace.supplier = {
              name: sourceBatch[0].supplier_name,
              source_batch: item.source_batch_no,
              ink_name: item.ink_name,
              brand: item.brand,
            };
            break;
          }
        }
      }
    }
  }

  return trace;
}

async function queryInventoryExpiry(batchNo: string) {
  const info: Loose = { batch_no: batchNo, inventory: null, expiry: null, opening: null };

  const batchRows: Loose = await query(
    `SELECT ib.*, w.warehouse_name
     FROM inv_inventory_batch ib
     LEFT JOIN inv_warehouse w ON ib.warehouse_id = w.id
     WHERE ib.batch_no = ? AND ib.deleted = 0`,
    [batchNo]
  );

  if (batchRows.length > 0) {
    const batch = batchRows[0];
    const now = new Date();
    const isExpired = batch.expire_date && new Date(batch.expire_date) < now;
    const daysUntilExpiry = batch.expire_date
      ? Math.ceil((new Date(batch.expire_date).getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
      : null;

    info.inventory = {
      warehouse_name: batch.warehouse_name,
      available_qty: batch.available_qty,
      quantity: batch.quantity,
      unit_price: batch.unit_price,
      inbound_date: batch.inbound_date,
      status: batch.status,
      freeze_reason: batch.freeze_reason,
    };

    info.expiry = {
      expire_date: batch.expire_date,
      is_expired: isExpired,
      days_until_expiry: daysUntilExpiry,
      warning_level:
        daysUntilExpiry !== null
          ? daysUntilExpiry <= 0
            ? 'expired'
            : daysUntilExpiry <= 7
              ? 'critical'
              : daysUntilExpiry <= 30
                ? 'warning'
                : 'normal'
          : 'no_expiry',
    };
  }

  const openingRows: Loose = await query(
    'SELECT * FROM ink_opening_record WHERE batch_no = ? AND deleted = 0 ORDER BY open_time DESC LIMIT 1',
    [batchNo]
  );

  if (openingRows.length > 0) {
    const opening = openingRows[0];
    info.opening = {
      record_no: opening.record_no,
      open_time: opening.open_time,
      expire_hours: opening.expire_hours,
      expire_time: opening.expire_time,
      remaining_qty: opening.remaining_qty,
      status: opening.status,
      ink_type: opening.ink_type,
    };
  }

  return info;
}

import { NextRequest } from 'next/server';
import { query, transaction } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const action = searchParams.get('action') || 'list';
  const colorName = searchParams.get('colorName') || '';
  const pantoneCode = searchParams.get('pantoneCode') || '';
  const minWeight = searchParams.get('minWeight') || '0';
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);

  if (action === 'recommend') {
    return await recommendSurplus(pantoneCode, colorName);
  }

  if (action === 'detail') {
    const batchNo = searchParams.get('batchNo') || '';
    if (!batchNo) return errorResponse('缺少batchNo', 400, 400);
    return await getSurplusDetail(batchNo);
  }

  let where = `WHERE ib.deleted = 0 AND ib.available_qty > 0 AND ib.status = 'normal'
    AND (ib.material_name LIKE '%专色%' OR ib.material_name LIKE '%调色%' OR ib.material_name LIKE '%余墨%' OR ib.batch_no LIKE 'INK%' OR ib.batch_no LIKE 'MIX%')`;
  const params: Loose[] = [];

  if (colorName) {
    where += ' AND ib.material_name LIKE ?';
    params.push(`%${colorName}%`);
  }
  if (Number(minWeight) > 0) {
    where += ' AND ib.available_qty >= ?';
    params.push(Number(minWeight));
  }

  const totalRows: Loose = await query(
    `SELECT COUNT(*) as total FROM inv_inventory_batch ib ${where}`,
    params
  );
  const total = totalRows[0]?.total || 0;

  const rows: Loose = await query(
    `SELECT ib.*, w.warehouse_name,
      CASE
        WHEN ib.expire_date IS NOT NULL AND ib.expire_date < CURDATE() THEN 'EXPIRED'
        WHEN ib.expire_date IS NOT NULL AND DATEDIFF(ib.expire_date, CURDATE()) <= 7 THEN 'CRITICAL'
        WHEN ib.expire_date IS NOT NULL AND DATEDIFF(ib.expire_date, CURDATE()) <= 30 THEN 'WARNING'
        ELSE 'NORMAL'
      END as expiry_status,
      DATEDIFF(ib.expire_date, CURDATE()) as days_until_expiry
    FROM inv_inventory_batch ib
    LEFT JOIN inv_warehouse w ON ib.warehouse_id = w.id
    ${where}
    ORDER BY ib.inbound_date ASC
    LIMIT ? OFFSET ?`,
    [...params, pageSize, (page - 1) * pageSize]
  );

  for (const row of rows) {
    const usageHistory: Loose = await query(
      `SELECT usage_type, workorder_no, weight, operator_name, machine_name, usage_time
       FROM ink_usage WHERE batch_no = ? AND deleted = 0 ORDER BY usage_time DESC LIMIT 10`,
      [row.batch_no]
    );
    row.usage_history = usageHistory;

    const dispatchRows: Loose = await query(
      `SELECT d.workorder_no, d.color_name, d.pantone_code, d.formula_no
       FROM ink_dispatch d
       WHERE d.batch_no = ? AND d.deleted = 0`,
      [row.batch_no]
    );
    row.dispatch_info = dispatchRows.length > 0 ? dispatchRows[0] : null;
  }

  return successResponse({ list: rows, total, page, pageSize });
});

async function recommendSurplus(pantoneCode: string, colorName: string) {
  const recommendations: Loose[] = [];

  const surplusInks: Loose = await query(`
    SELECT
      ib.batch_no,
      ib.material_name,
      ib.available_qty,
      ib.unit_price,
      ib.expire_date,
      ib.inbound_date,
      ib.warehouse_id,
      w.warehouse_name,
      DATEDIFF(ib.expire_date, CURDATE()) as days_until_expiry,
      d.pantone_code,
      d.color_name as dispatch_color_name,
      d.formula_no,
      d.workorder_no as original_workorder
    FROM inv_inventory_batch ib
    LEFT JOIN inv_warehouse w ON ib.warehouse_id = w.id
    LEFT JOIN ink_dispatch d ON d.batch_no = ib.batch_no AND d.deleted = 0
    WHERE ib.deleted = 0 AND ib.available_qty > 0 AND ib.status = 'normal'
      AND (ib.expire_date IS NULL OR ib.expire_date >= CURDATE())
      AND (ib.material_name LIKE '%专色%' OR ib.material_name LIKE '%调色%' OR ib.material_name LIKE '%余墨%'
        OR ib.batch_no LIKE 'INK%' OR ib.batch_no LIKE 'MIX%')
    ORDER BY ib.inbound_date ASC
  `);

  for (const ink of surplusInks) {
    let matchScore = 0;
    const matchReasons: string[] = [];

    if (pantoneCode && ink.pantone_code) {
      if (ink.pantone_code === pantoneCode) {
        matchScore += 50;
        matchReasons.push('Pantone色号完全匹配');
      } else if (ink.pantone_code.substring(0, 3) === pantoneCode.substring(0, 3)) {
        matchScore += 30;
        matchReasons.push('Pantone色号相近');
      }
    }

    if (colorName && ink.dispatch_color_name) {
      if (
        ink.dispatch_color_name.includes(colorName) ||
        colorName.includes(ink.dispatch_color_name)
      ) {
        matchScore += 30;
        matchReasons.push('颜色名称匹配');
      }
    }

    if (ink.available_qty >= 5) {
      matchScore += 10;
      matchReasons.push('可用量充足');
    }

    if (ink.days_until_expiry && ink.days_until_expiry > 30) {
      matchScore += 10;
      matchReasons.push('有效期充裕');
    } else if (ink.days_until_expiry && ink.days_until_expiry > 7) {
      matchScore += 5;
      matchReasons.push('有效期即将到期，优先使用');
    }

    if (matchScore > 0) {
      recommendations.push({
        ...ink,
        match_score: matchScore,
        match_reasons: matchReasons,
        recommended_usage: Math.min(Number(ink.available_qty), 20),
      });
    }
  }

  recommendations.sort((a, b) => b.match_score - a.match_score);

  const totalAvailable = surplusInks.reduce(
    (sum: number, ink: Loose) => sum + Number(ink.available_qty || 0),
    0
  );
  const potentialSaving = totalAvailable * (surplusInks[0]?.unit_price || 50);

  return successResponse({
    recommendations: recommendations.slice(0, 20),
    total_surplus_count: surplusInks.length,
    total_available_weight: totalAvailable,
    potential_cost_saving: potentialSaving,
    query: { pantoneCode, colorName },
  });
}

async function getSurplusDetail(batchNo: string) {
  const batchRows: Loose = await query(
    `
    SELECT ib.*, w.warehouse_name
    FROM inv_inventory_batch ib
    LEFT JOIN inv_warehouse w ON ib.warehouse_id = w.id
    WHERE ib.batch_no = ? AND ib.deleted = 0
  `,
    [batchNo]
  );

  if (batchRows.length === 0) {
    return errorResponse('批次不存在', 404, 404);
  }

  const batch = batchRows[0];

  const dispatchRows: Loose = await query(
    'SELECT * FROM ink_dispatch WHERE batch_no = ? AND deleted = 0',
    [batchNo]
  );

  let formulaInfo = null;
  let rawInks: Loose[] = [];

  if (dispatchRows.length > 0) {
    const dispatch = dispatchRows[0];
    const formulaRows: Loose = await query(
      'SELECT * FROM ink_formula WHERE id = ? AND deleted = 0',
      [dispatch.formula_id]
    );
    if (formulaRows.length > 0) {
      formulaInfo = formulaRows[0];
      const items: Loose = await query(
        'SELECT * FROM ink_formula_item WHERE formula_id = ? AND deleted = 0 ORDER BY sort_order',
        [formulaInfo.id]
      );
      rawInks = items;
    }
  }

  const usageHistory: Loose = await query(
    `SELECT * FROM ink_usage WHERE batch_no = ? AND deleted = 0 ORDER BY usage_time DESC`,
    [batchNo]
  );

  const openingRows: Loose = await query(
    'SELECT * FROM ink_opening_record WHERE batch_no = ? AND deleted = 0 ORDER BY open_time DESC LIMIT 1',
    [batchNo]
  );

  return successResponse({
    batch,
    dispatch: dispatchRows.length > 0 ? dispatchRows[0] : null,
    formula: formulaInfo,
    raw_inks: rawInks,
    usage_history: usageHistory,
    opening_record: openingRows.length > 0 ? openingRows[0] : null,
  });
}

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const {
      batch_no,
      return_weight,
      unit,
      workorder_no,
      operator_id,
      operator_name,
      location_id,
      location_name,
      remark,
    } = body;

    if (!batch_no || !return_weight || Number(return_weight) <= 0) {
      return errorResponse('缺少必填字段: batch_no, return_weight', 400, 400);
    }

    const result = await transaction(async (conn) => {
      const [batchRows]: Loose = await conn.execute(
        'SELECT id, available_qty, material_name, status, expire_date FROM inv_inventory_batch WHERE batch_no = ? AND deleted = 0 FOR UPDATE',
        [batch_no]
      );

      if (batchRows.length === 0) {
        throw new Error(`油墨批次 ${batch_no} 不存在`);
      }

      const batch = batchRows[0];

      if (batch.expire_date && new Date(batch.expire_date) < new Date()) {
        throw new Error(`油墨批次 ${batch_no} 已过期，不能退回`);
      }

      await conn.execute(
        'UPDATE inv_inventory_batch SET available_qty = available_qty + ? WHERE id = ?',
        [return_weight, batch.id]
      );

      const now = new Date();
      const usageNo =
        'IU' +
        now.getFullYear() +
        String(now.getMonth() + 1).padStart(2, '0') +
        String(now.getDate()).padStart(2, '0') +
        String(Math.floor(Math.random() * 10000)).padStart(4, '0');

      const [insertResult]: Loose = await conn.execute(
        `INSERT INTO ink_usage (usage_no, usage_type, batch_no, workorder_no, color_name, weight, unit, operator_id, operator_name, location_id, location_name, status, remark)
       VALUES (?, 'return', ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)`,
        [
          usageNo,
          batch_no,
          workorder_no || null,
          batch.material_name || '',
          return_weight,
          unit || 'kg',
          operator_id || null,
          operator_name || null,
          location_id || null,
          location_name || null,
          remark || '余墨退回',
        ]
      );

      return { id: insertResult.insertId, usage_no: usageNo, batch_no, return_weight };
    });

    return successResponse(result, '余墨退回成功');
  },
  { logTitle: '余墨退回', logType: 'business' }
);

import { NextRequest } from 'next/server';
import { query, execute, transaction } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const keyword = searchParams.get('keyword') || '';
  const usageType = searchParams.get('usageType') || '';
  const workorderNo = searchParams.get('workorderNo') || '';
  const startDate = searchParams.get('startDate') || '';
  const endDate = searchParams.get('endDate') || '';

  let where = 'WHERE u.deleted = 0';
  const params: Loose[] = [];

  if (keyword) {
    where += ' AND (u.usage_no LIKE ? OR u.batch_no LIKE ? OR u.color_name LIKE ?)';
    const like = `%${keyword}%`;
    params.push(like, like, like);
  }
  if (usageType) {
    where += ' AND u.usage_type = ?';
    params.push(usageType);
  }
  if (workorderNo) {
    where += ' AND u.workorder_no = ?';
    params.push(workorderNo);
  }
  if (startDate) {
    where += ' AND u.usage_date >= ?';
    params.push(startDate);
  }
  if (endDate) {
    where += ' AND u.usage_date <= ?';
    params.push(endDate);
  }

  const totalRows: Loose = await query(
    `SELECT COUNT(*) as total FROM ink_usage u ${where}`,
    params
  );
  const total = totalRows[0]?.total || 0;

  const rows: Loose = await query(
    `SELECT u.* FROM ink_usage u ${where} ORDER BY u.usage_date DESC LIMIT ? OFFSET ?`,
    [...params, pageSize, (page - 1) * pageSize]
  );

  return successResponse({ list: rows, total, page, pageSize });
});

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const {
      usage_type,
      batch_no,
      qr_code,
      workorder_id,
      workorder_no,
      formula_id,
      formula_no,
      color_name,
      weight,
      unit,
      operator_id,
      operator_name,
      machine_id,
      machine_name,
      location_id,
      location_name,
      remark,
    } = body;

    if (!usage_type || !weight || Number(weight) <= 0) {
      return errorResponse('缺少必填字段: usage_type, weight', 400, 400);
    }

    const validTypes = ['requisition', 'machine_load', 'consumption', 'return', 'scrap'];
    if (!validTypes.includes(usage_type)) {
      return errorResponse(`无效的使用类型: ${usage_type}`, 400, 400);
    }

    const result = await transaction(async (conn) => {
      const now = new Date();
      const usageNo =
        'IU' +
        now.getFullYear() +
        String(now.getMonth() + 1).padStart(2, '0') +
        String(now.getDate()).padStart(2, '0') +
        String(Math.floor(Math.random() * 10000)).padStart(4, '0');

      let actualBatchNo = batch_no;
      if (qr_code && !batch_no) {
        const [qrRows]: Loose = await conn.execute(
          "SELECT batch_no, extra_data FROM qrcode_record WHERE qr_code = ? AND qr_type IN ('ink_dispatch', 'ink_mixed', 'ink_open') AND deleted = 0",
          [qr_code]
        );
        if (qrRows.length > 0) {
          actualBatchNo = qrRows[0].batch_no;
        }
      }

      if (!actualBatchNo) {
        throw new Error('无法确定油墨批次号，请提供batch_no或qr_code');
      }

      const [batchRows]: Loose = await conn.execute(
        'SELECT id, available_qty, material_name, warehouse_id, status, expire_date FROM inv_inventory_batch WHERE batch_no = ? AND deleted = 0 FOR UPDATE',
        [actualBatchNo]
      );

      if (batchRows.length === 0) {
        throw new Error(`油墨批次 ${actualBatchNo} 不存在`);
      }

      const batch = batchRows[0];

      if (batch.status === 'frozen') {
        throw new Error(`油墨批次 ${actualBatchNo} 已冻结，不能使用`);
      }

      if (batch.expire_date && new Date(batch.expire_date) < now) {
        throw new Error(`油墨批次 ${actualBatchNo} 已过期，不能使用`);
      }

      if (
        usage_type === 'requisition' ||
        usage_type === 'machine_load' ||
        usage_type === 'consumption'
      ) {
        if (Number(batch.available_qty) < Number(weight)) {
          throw new Error(
            `油墨 ${batch.material_name} 批次 ${actualBatchNo} 库存不足: 可用 ${batch.available_qty}, 需用 ${weight}`
          );
        }

        await conn.execute(
          'UPDATE inv_inventory_batch SET available_qty = available_qty - ? WHERE id = ?',
          [weight, batch.id]
        );
      }

      if (usage_type === 'return') {
        await conn.execute(
          'UPDATE inv_inventory_batch SET available_qty = available_qty + ? WHERE id = ?',
          [weight, batch.id]
        );
      }

      if (usage_type === 'machine_load' && workorder_no) {
        const [dispatchRows]: Loose = await conn.execute(
          'SELECT id, formula_no, color_name, pantone_code FROM ink_dispatch WHERE workorder_no = ? AND batch_no = ? AND deleted = 0',
          [workorder_no, actualBatchNo]
        );

        if (dispatchRows.length > 0) {
          const dispatch = dispatchRows[0];
          const [formulaRows]: Loose = await conn.execute(
            'SELECT id, formula_name, pantone_code FROM ink_formula WHERE formula_no = ? AND deleted = 0',
            [dispatch.formula_no || formula_no]
          );

          if (formulaRows.length > 0 && workorder_no) {
            const [woFormulaRows]: Loose = await conn.execute(
              'SELECT formula_id FROM ink_formula_workorder WHERE workorder_no = ? AND deleted = 0',
              [workorder_no]
            );

            if (woFormulaRows.length > 0 && woFormulaRows[0].formula_id !== formulaRows[0].id) {
              throw new Error(
                `配方不匹配: 工单 ${workorder_no} 要求配方ID ${woFormulaRows[0].formula_id}, 当前油墨配方ID ${formulaRows[0].id}`
              );
            }
          }
        }
      }

      const [insertResult]: Loose = await conn.execute(
        `INSERT INTO ink_usage (usage_no, usage_type, batch_no, qr_code, workorder_id, workorder_no, formula_id, formula_no, color_name, weight, unit, operator_id, operator_name, machine_id, machine_name, location_id, location_name, status, remark)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)`,
        [
          usageNo,
          usage_type,
          actualBatchNo,
          qr_code || null,
          workorder_id || null,
          workorder_no || null,
          formula_id || null,
          formula_no || null,
          color_name || batch.material_name || null,
          weight,
          unit || 'kg',
          operator_id || null,
          operator_name || null,
          machine_id || null,
          machine_name || null,
          location_id || null,
          location_name || null,
          remark || null,
        ]
      );

      try {
        await conn.execute(
          `INSERT INTO inv_scan_log (scan_type, qr_content, qr_type, sn, batch_no, material_name, workorder_no, operator_id, operator_name, scan_time, scan_result, result_message)
         VALUES (?, ?, 'ink', ?, ?, ?, ?, ?, ?, NOW(), 'success', ?)`,
          [
            `ink_${usage_type}`,
            qr_code || actualBatchNo,
            actualBatchNo,
            actualBatchNo,
            batch.material_name || '',
            workorder_no || '',
            operator_id || null,
            operator_name || '',
            `${usage_type} ${weight}${unit || 'kg'} 批次${actualBatchNo}`,
          ]
        );
      } catch {}

      return { id: insertResult.insertId, usage_no: usageNo, batch_no: actualBatchNo };
    });

    return successResponse(result, '油墨使用记录创建成功');
  },
  { logTitle: '油墨使用记录', logType: 'business' }
);

export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { id, status, remark } = body;

    if (!id) {
