import { NextRequest } from 'next/server';
import { escapeId } from 'mysql2';
import { successResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';
import { query } from '@/lib/db';

/**
 * 往来账龄分析 API
 *
 * 按账龄区间统计应收/应付款，识别坏账风险
 */

export const GET = withPermission(async (request: NextRequest, _userInfo: UserInfo) => {
  const { searchParams } = new URL(request.url);
  const type = searchParams.get('type') || 'receivable';
  const asOfDate = searchParams.get('asOfDate') || new Date().toISOString().slice(0, 10);

  const isReceivable = type === 'receivable';
  const tableName = isReceivable ? 'fin_receivable' : 'fin_payable';
  const partnerTable = isReceivable ? 'crm_customer' : 'pur_supplier';
  const partnerIdCol = isReceivable ? 'customer_id' : 'supplier_id';
  const partnerNameCol = isReceivable ? 'customer_name' : 'supplier_name';
  const docNoCol = isReceivable ? 'receivable_no' : 'payable_no';

  const escTable = escapeId(tableName);
  const escPartnerTable = escapeId(partnerTable);
  const escPartnerIdCol = escapeId(partnerIdCol);
  const escPartnerNameCol = escapeId(partnerNameCol);
  const escDocNoCol = escapeId(docNoCol);

  // 账龄区间
  const ageBuckets = [
    { label: '未到期', min: -9999, max: 0 },
    { label: '1-30天', min: 1, max: 30 },
    { label: '31-60天', min: 31, max: 60 },
    { label: '61-90天', min: 61, max: 90 },
    { label: '91-180天', min: 91, max: 180 },
    { label: '181-365天', min: 181, max: 365 },
    { label: '365天以上', min: 366, max: 9999 },
  ];

  const rows: Loose = await query(
    `SELECT r.id, r.${escDocNoCol} as doc_no, r.${escPartnerIdCol} as partner_id, r.amount, r.balance,
              r.due_date, r.status,
              DATEDIFF(?, r.due_date) as age_days,
              p.${escPartnerNameCol} as partner_name
       FROM ${escTable} r
       LEFT JOIN ${escPartnerTable} p ON r.${escPartnerIdCol} = p.id
       WHERE r.status != 3 AND r.balance > 0 AND r.deleted = 0
       ORDER BY r.due_date ASC`,
    [asOfDate]
  );

  const partnerSummary: Record<string, Loose> = {};

  for (const row of rows) {
    const partnerId = row.partner_id || 0;
    const partnerName = row.partner_name || '未知';

    if (!partnerSummary[partnerId]) {
      partnerSummary[partnerId] = {
        partner_id: partnerId,
        partner_name: partnerName,
        total_amount: 0,
        remaining_amount: 0,
        buckets: ageBuckets.map((b) => ({ ...b, amount: 0, count: 0 })),
      };
    }

    const ageDays = Number(row.age_days || 0);
    const remaining = Number(row.balance || 0);

    partnerSummary[partnerId].total_amount += Number(row.amount || 0);
    partnerSummary[partnerId].remaining_amount += remaining;

    for (const bucket of partnerSummary[partnerId].buckets) {
      if (ageDays >= bucket.min && ageDays <= bucket.max) {
        bucket.amount += remaining;
        bucket.count += 1;
        break;
      }
    }
  }

  // 总计
  const totalSummary = {
    total_amount: 0,
    remaining_amount: 0,
    buckets: ageBuckets.map((b) => ({ ...b, amount: 0, count: 0 })),
  };

  for (const summary of Object.values(partnerSummary) as Loose[]) {
    totalSummary.total_amount += summary.total_amount;
    totalSummary.remaining_amount += summary.remaining_amount;
    for (let i = 0; i < summary.buckets.length; i++) {
      totalSummary.buckets[i].amount += summary.buckets[i].amount;
      totalSummary.buckets[i].count += summary.buckets[i].count;
    }
  }

  return successResponse({
    type,
    asOfDate,
    partnerList: Object.values(partnerSummary),
    total: totalSummary,
    ageBuckets: ageBuckets.map((b) => b.label),
  });
});

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';
import { CalcParamService } from '@/lib/calc-param-service';

import { withPermission } from '@/lib/api-permissions';
export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const workOrderId = searchParams.get('work_order_id');
  const workOrderNo = searchParams.get('work_order_no');
  const startDate = searchParams.get('start_date');
  const endDate = searchParams.get('end_date');
  const varianceType = searchParams.get('variance_type') || 'all';
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '20');

  let where = 'WHERE wo.deleted = 0';
  const params: Loose[] = [];

  if (workOrderId) {
    where += ' AND wo.id = ?';
    params.push(parseInt(workOrderId));
  }
  if (workOrderNo) {
    where += ' AND wo.work_order_no LIKE ?';
    params.push(`%${workOrderNo}%`);
  }
  if (startDate) {
    where += ' AND wo.create_time >= ?';
    params.push(startDate);
  }
  if (endDate) {
    where += ' AND wo.create_time <= ?';
    params.push(endDate + ' 23:59:59');
  }

  const workOrders: Loose = await query(
    `
    SELECT
      wo.id,
      wo.work_order_no,
      wo.product_name,
      wo.quantity as plan_qty,
      wo.status,
      wo.create_time,
      soi.unit_price as sale_unit_price,
      soi.total_price as sale_total_price
    FROM prod_work_order wo
    LEFT JOIN sales_order_item soi ON wo.order_id = soi.order_id
    ${where}
    ORDER BY wo.create_time DESC
    LIMIT ? OFFSET ?
  `,
    [...params, pageSize, (page - 1) * pageSize]
  );

  const countResult: Loose = await query(
    `
    SELECT COUNT(*) as total FROM prod_work_order wo ${where}
  `,
    params
  );
  const total = countResult[0]?.total || 0;

  const varianceDetails: Loose[] = [];

  for (const wo of workOrders) {
    const materialCostRows: Loose = await query(
      `
      SELECT
        COALESCE(SUM(wr.completed_qty * bom.unit_price), 0) as standard_material_cost,
        COALESCE(SUM(tr.quantity * tr.unit_price), 0) as actual_material_cost
      FROM prd_work_report wr
      LEFT JOIN prod_work_order_item woi ON wr.work_order_id = woi.id
      LEFT JOIN (
        SELECT material_id, unit_price FROM prod_work_order_item WHERE work_order_id = ?
      ) bom ON 1=1
      LEFT JOIN inv_inventory_transaction tr ON tr.source_no = wo.work_order_no AND tr.trans_type = 'out'
      WHERE wr.work_order_id = ? AND wr.deleted = 0
    `,
      [wo.id, wo.id]
    );

    const laborCostRows: Loose = await query(
      `
      SELECT
        COALESCE(SUM(wr.work_hours), 0) as actual_work_hours,
        COALESCE(SUM(wr.qualified_qty), 0) as total_qualified
      FROM prd_work_report wr
      WHERE wr.work_order_id = ? AND wr.deleted = 0
    `,
      [wo.id]
    );

    const standardLaborRate = await CalcParamService.getDecimal('cost.standard_labor_rate', 50);
    const materialCostRatio = await CalcParamService.getDecimal('cost.material_cost_ratio', 0.45);
    const standardEfficiency = await CalcParamService.getDecimal(
      'cost.standard_efficiency_per_hour',
      500
    );
    const overheadRate = await CalcParamService.getDecimal('cost.overhead_rate', 0.15);

    const standardMaterialUnitCost = Number(wo.sale_unit_price || 0) * materialCostRatio;

    const actualMaterialCost = Number(materialCostRows[0]?.actual_material_cost || 0);
    const standardMaterialCost = Number(wo.plan_qty || 0) * standardMaterialUnitCost;
    const materialVariance = standardMaterialCost - Math.abs(actualMaterialCost);

    const actualWorkHours = Number(laborCostRows[0]?.actual_work_hours || 0);
    const standardWorkHours = Number(wo.plan_qty || 0) / standardEfficiency;
    const standardLaborCost = standardWorkHours * standardLaborRate;
    const actualLaborCost = actualWorkHours * standardLaborRate;
    const laborVariance = standardLaborCost - actualLaborCost;

    const standardOverheadCost = standardMaterialCost * overheadRate;
    const actualOverheadCost = Math.abs(actualMaterialCost) * overheadRate;
    const overheadVariance = standardOverheadCost - actualOverheadCost;

    const totalStandardCost = standardMaterialCost + standardLaborCost + standardOverheadCost;
    const totalActualCost = Math.abs(actualMaterialCost) + actualLaborCost + actualOverheadCost;
    const totalVariance = totalStandardCost - totalActualCost;

    const scrapRows: Loose = await query(
      `
      SELECT
        COALESCE(SUM(scrap_qty), 0) as total_scrap,
        COALESCE(SUM(completed_qty), 0) as total_completed
      FROM prd_work_report
      WHERE work_order_id = ? AND deleted = 0
    `,
      [wo.id]
    );

    const totalScrap = Number(scrapRows[0]?.total_scrap || 0);
    const totalCompleted = Number(scrapRows[0]?.total_completed || 0);
    const scrapRate = totalCompleted > 0 ? (totalScrap / (totalCompleted + totalScrap)) * 100 : 0;

    const detail: Loose = {
      work_order_id: wo.id,
      work_order_no: wo.work_order_no,
      product_name: wo.product_name,
      plan_qty: Number(wo.plan_qty || 0),
      status: wo.status,
      standard_cost: {
        material: Math.round(standardMaterialCost * 100) / 100,
        labor: Math.round(standardLaborCost * 100) / 100,
        overhead: Math.round(standardOverheadCost * 100) / 100,
        total: Math.round(totalStandardCost * 100) / 100,
      },
      actual_cost: {
        material: Math.round(Math.abs(actualMaterialCost) * 100) / 100,
        labor: Math.round(actualLaborCost * 100) / 100,
        overhead: Math.round(actualOverheadCost * 100) / 100,
        total: Math.round(totalActualCost * 100) / 100,
      },
      variance: {
        material: Math.round(materialVariance * 100) / 100,
        labor: Math.round(laborVariance * 100) / 100,
        overhead: Math.round(overheadVariance * 100) / 100,
        total: Math.round(totalVariance * 100) / 100,
        material_pct:
          standardMaterialCost > 0
            ? Math.round((materialVariance / standardMaterialCost) * 10000) / 100
            : 0,
        labor_pct:
          standardLaborCost > 0 ? Math.round((laborVariance / standardLaborCost) * 10000) / 100 : 0,
        total_pct:
          totalStandardCost > 0 ? Math.round((totalVariance / totalStandardCost) * 10000) / 100 : 0,
      },
      scrap_analysis: {
        total_scrap: totalScrap,
        total_completed: totalCompleted,
        scrap_rate: Math.round(scrapRate * 100) / 100,
        scrap_cost: Math.round(totalScrap * standardMaterialUnitCost * 100) / 100,
      },
      variance_reason: classifyVarianceReason(materialVariance, laborVariance, scrapRate),
    };

    if (
      varianceType === 'all' ||
      (varianceType === 'favorable' && totalVariance > 0) ||
      (varianceType === 'unfavorable' && totalVariance < 0) ||
      (varianceType === 'material' && Math.abs(materialVariance) > 0) ||
      (varianceType === 'labor' && Math.abs(laborVariance) > 0)
    ) {
      varianceDetails.push(detail);
    }
  }

  const summaryResult: Loose = await query(`
    SELECT
      COALESCE(SUM(wr.completed_qty), 0) as total_completed_qty,
      COALESCE(SUM(wr.scrap_qty), 0) as total_scrap_qty,
      COALESCE(SUM(wr.work_hours), 0) as total_work_hours,
      COUNT(DISTINCT wr.work_order_id) as total_work_orders
    FROM prd_work_report wr
    WHERE wr.deleted = 0
  `);

  const overallSummary = {
    total_work_orders: Number(summaryResult[0]?.total_work_orders || 0),
    total_completed_qty: Number(summaryResult[0]?.total_completed_qty || 0),
    total_scrap_qty: Number(summaryResult[0]?.total_scrap_qty || 0),
    total_work_hours: Number(summaryResult[0]?.total_work_hours || 0),
    overall_scrap_rate:
      Number(summaryResult[0]?.total_completed_qty || 0) > 0
        ? Math.round(
            (Number(summaryResult[0]?.total_scrap_qty || 0) /
              (Number(summaryResult[0]?.total_completed_qty || 0) +
                Number(summaryResult[0]?.total_scrap_qty || 0))) *
              10000
          ) / 100
        : 0,
  };

  return successResponse({
    list: varianceDetails,
    total,
    page,
    pageSize,
    summary: overallSummary,
  });
});

function classifyVarianceReason(
  materialVariance: number,
  laborVariance: number,
  scrapRate: number
): string[] {
  const reasons: string[] = [];
  if (materialVariance < -100) reasons.push('材料超耗');
  if (materialVariance > 100) reasons.push('材料节约');
  if (laborVariance < -50) reasons.push('工时超支');
  if (laborVariance > 50) reasons.push('效率提升');
  if (scrapRate > 5) reasons.push('废品率偏高');
  if (scrapRate > 10) reasons.push('质量异常');
  if (reasons.length === 0) reasons.push('正常偏差');
  return reasons;
}

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';

import { withPermission } from '@/lib/api-permissions';
export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '20');
  const keyword = searchParams.get('keyword') || '';
  const costType = searchParams.get('cost_type') || '';

  let where = 'WHERE deleted = 0';
  const params: Loose[] = [];

  if (keyword) {
    where += ' AND (cost_no LIKE ? OR source_no LIKE ? OR description LIKE ?)';
    const like = `%${keyword}%`;
    params.push(like, like, like);
  }
  if (costType) {
    where += ' AND cost_type = ?';
    params.push(costType);
  }

  const totalRows: Loose = await query(
    `SELECT COUNT(*) as total FROM fin_cost_record ${where}`,
    params
  );
  const total = totalRows[0]?.total || 0;

  const rows: Loose = await query(
    `SELECT * FROM fin_cost_record ${where} ORDER BY cost_date DESC, id DESC LIMIT ? OFFSET ?`,
    [...params, pageSize, (page - 1) * pageSize]
  );

  const costSummary: Loose = await query(`
    SELECT
      COALESCE(SUM(CASE WHEN cost_type = 'material' THEN amount ELSE 0 END), 0) as material,
      COALESCE(SUM(CASE WHEN cost_type = 'labor' THEN amount ELSE 0 END), 0) as labor,
      COALESCE(SUM(CASE WHEN cost_type = 'overhead' THEN amount ELSE 0 END), 0) as overhead,
      COALESCE(SUM(CASE WHEN cost_type = 'outsource' THEN amount ELSE 0 END), 0) as outsource,
      COALESCE(SUM(amount), 0) as total
    FROM fin_cost_record WHERE deleted = 0
  `);

  return successResponse({
    list: rows,
    total,
    page,
    pageSize,
    cost_summary: costSummary[0] || { material: 0, labor: 0, overhead: 0, outsource: 0, total: 0 },
  });
});

