import { getDrizzleDb } from '@/lib/db';
import { eq, and, inArray } from 'drizzle-orm';
import { hrSalaryCalculation, sysEmployee } from '@/lib/db/schema';

const db = getDrizzleDb();

export const POST = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { employeeIds, month } = body;

  if (!Array.isArray(employeeIds) || employeeIds.length === 0) {
    return errorResponse('缺少员工ID列表', 400, 400);
  }
  if (!month || !/^\d{4}-\d{2}$/.test(month)) {
    return errorResponse('月份格式错误 (YYYY-MM)', 400, 400);
  }

  const calculations = await db.select()
    .from(hrSalaryCalculation)
    .where(and(
      eq(hrSalaryCalculation.calcMonth, month),
      inArray(hrSalaryCalculation.employeeId, employeeIds),
    ));

  if (calculations.length === 0) {
    return errorResponse('未找到符合条件的薪资计算结果', 404, 404);
  }

  const ids = calculations.map(c => c.id);
  const allConfirmed = calculations.every(c => c.status === 'confirmed' || c.status === 'paid');
  if (!allConfirmed) {
    const pendingNames = calculations
      .filter(c => c.status !== 'confirmed' && c.status !== 'paid')
      .map(c => c.employeeId)
      .join(', ');
    return errorResponse(`以下员工薪资尚未确认: ${pendingNames}`, 400, 400);
  }

  const alreadyPaid = calculations.filter(c => c.status === 'paid');
  if (alreadyPaid.length > 0) {
    return errorResponse(`员工 ${alreadyPaid.map(c => c.employeeId).join(', ')} 薪资已发放`, 400, 400);
  }

  const employees = await db.select({
    id: sysEmployee.id,
    name: sysEmployee.name,
    bankAccount: sysEmployee.bankAccount,
  })
    .from(sysEmployee)
    .where(inArray(sysEmployee.id, employeeIds));

  const employeeMap = new Map(employees.map(e => [e.id, e]));

  const voucherNo = `TR${month.replace('-', '')}${Date.now().toString().slice(-6)}`;
  let totalNetPay = 0;
  const records: { employeeName: string; bankAccount: string | null; netPay: number }[] = [];

  for (const calc of calculations) {
    const emp = employeeMap.get(calc.employeeId);
    const netPay = Number(calc.netPay);
    totalNetPay += netPay;
    records.push({
      employeeName: emp?.name || `员工ID:${calc.employeeId}`,
      bankAccount: emp?.bankAccount || null,
      netPay,
    });
  }

  await db.update(hrSalaryCalculation)
    .set({ status: 'paid' })
    .where(inArray(hrSalaryCalculation.id, ids));

  return successResponse({
    voucherNo,
    totalAmount: Number(totalNetPay.toFixed(2)),
    employeeCount: records.length,
    records,
  });
}, { errorMessage: '薪资转账生成失败' });

import { NextRequest } from 'next/server';
import { withPermission } from '@/lib/api-permissions';
import { successResponse, errorResponse } from '@/lib/api-response';
import { syncPieceWorkFromMes } from '@/lib/hr/piece-work-sync';
import { query } from '@/lib/db';

export const POST = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { records } = body;

  if (!Array.isArray(records) || records.length === 0) {
    return errorResponse('缺少计件记录数据', 400, 400);
  }

  if (records.length > 1000) {
    return errorResponse('单次同步记录数不能超过1000', 400, 400);
  }

  const result = await syncPieceWorkFromMes(records);
  return successResponse(result, `同步完成: ${result.synced}条成功, ${result.skipped}条跳过, ${result.errors.length}条失败`);
}, { errorMessage: 'MES计件同步失败' });

export const GET = withPermission(async (_request: NextRequest) => {
  const rows = await query(
    `SELECT * FROM hr_piece_work_detail WHERE sync_status > 0 ORDER BY create_time DESC LIMIT 50`
  );
  return successResponse(rows);
}, { errorMessage: '获取同步历史失败' });

import { NextRequest } from 'next/server';
import { withPermission } from '@/lib/api-permissions';
import { successResponse, errorResponse } from '@/lib/api-response';
import { getDrizzleDb } from '@/lib/db';
import { eq, and } from 'drizzle-orm';
import { hrPieceWorkDetail } from '@/lib/db/schema';

const db = getDrizzleDb();

export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const employeeId = searchParams.get('employeeId');
  const month = searchParams.get('month');
  const processCode = searchParams.get('processCode');

  if (!employeeId || !month) {
    return errorResponse('缺少员工ID或月份', 400, 400);
  }

  const empId = parseInt(employeeId);
  if (isNaN(empId) || empId < 1) {
    return errorResponse('员工ID格式不正确', 400, 400);
  }
  if (!/^\d{4}-\d{2}$/.test(month)) {
    return errorResponse('月份格式错误 (YYYY-MM)', 400, 400);
  }

  const [year, mon] = month.split('-');
  const _startDate = `${year}-${mon}-01`;
  const _endDate = `${year}-${mon}-31`;

  const conditions = [
    eq(hrPieceWorkDetail.employeeId, empId),
    and(
      eq(hrPieceWorkDetail.syncStatus, 1),
    ),
  ];

  if (processCode) {
    conditions.push(eq(hrPieceWorkDetail.processCode, processCode));
  }

  const details = await db.select({
    quantity: hrPieceWorkDetail.quantity,
    defectiveQuantity: hrPieceWorkDetail.defectiveQuantity,
    processCode: hrPieceWorkDetail.processCode,
    workDate: hrPieceWorkDetail.workDate,
  })
    .from(hrPieceWorkDetail)
    .where(and(...conditions));

  const totalQuantity = details.reduce((s, d) => s + (d.quantity ?? 0), 0);
  const totalDefective = details.reduce((s, d) => s + (d.defectiveQuantity ?? 0), 0);
  const defectRate = totalQuantity > 0 ? totalDefective / totalQuantity : 0;

  return successResponse({
    employeeId: empId,
    month,
    processCode: processCode || null,
    totalQuantity,
    totalDefective,
    defectRate: Number((defectRate * 100).toFixed(2)),
    recordCount: details.length,
    details,
  });
}, { errorMessage: '查询缺陷率失败' });

import { NextRequest } from 'next/server';
import { withPermission } from '@/lib/api-permissions';
import { successResponse, errorResponse } from '@/lib/api-response';
import { calculateMonthlySalary, batchCalculateSalary } from '@/lib/hr/salary-engine';
import { SalaryCalculationRepository } from '@/domain/hr/infrastructure/SalaryCalculationRepository';
import { getDrizzleDb } from '@/lib/db';
import { sysEmployee } from '@/lib/db/schema';
import { eq } from 'drizzle-orm';
import { logger } from '@/lib/logger';

const db = getDrizzleDb();
const calcRepo = new SalaryCalculationRepository();

/**
 * POST /api/hr/salary/calculate
 * Body: { employeeId: number, month: string, options?: SalaryEngineOptions }
 * 单员工薪资计算
 */
export const POST = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { employeeId, month, options } = body;

  if (!employeeId || !month) {
    return errorResponse('缺少员工ID或计算月份', 400, 400);
  }
  if (!/^\d{4}-\d{2}$/.test(month)) {
    return errorResponse('月份格式错误 (YYYY-MM)', 400, 400);
  }

  const result = await calculateMonthlySalary(employeeId, month, options || {});
  return successResponse(result);
}, { errorMessage: '薪资计算失败' });

/**
 * PUT /api/hr/salary/calculate
 * Body: { employeeIds: number[], month: string }
 * 批量薪资计算
 */
export const PUT = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { employeeIds, month, options } = body;

  if (!month) {
    return errorResponse('缺少计算月份', 400, 400);
  }

  let targetIds = employeeIds;
  if (!targetIds?.length) {
    const employees = await db.select({ id: sysEmployee.id }).from(sysEmployee)
      .where(eq(sysEmployee.status, 1));
    targetIds = employees.map(e => e.id);
    logger.debug(`[BatchSalaryCalc] 自动获取员工列表: ${targetIds.length} 人`);
  }

  if (!targetIds.length) {
    return errorResponse('未找到任何员工', 400, 400);
  }

  const results = await batchCalculateSalary(targetIds, month, options || {});
  return successResponse({
    total: results.length,
    succeeded: results.length,
    results,
  });
}, { errorMessage: '批量薪资计算失败' });

/**
 * GET /api/hr/salary/calculate?employeeId=1&month=2026-07
 * 查询某个员工某月的计算结果
 */
export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const employeeId = parseInt(searchParams.get('employeeId') || '');
  const month = searchParams.get('month');

  if (!employeeId || !month) {
    return errorResponse('缺少员工ID或月份', 400, 400);
  }

  const calc = await calcRepo.findByEmployeeMonth(employeeId, month);
  if (!calc) {
    return errorResponse('未找到计算结果', 404, 404);
  }

  return successResponse(calc);
}, { errorMessage: '查询薪资计算结果失败' });

