﻿import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { CommonValidations } from '@/lib/validation';
import { successResponse, errorResponse } from '@/lib/api-response';

import { withPermission } from '@/lib/api-permissions';
export const GET = withPermission(
  async (request: NextRequest) => {
    const { searchParams } = new URL(request.url);
    const month = searchParams.get('month') || format(new Date(), 'yyyy-MM');
    const deptId = searchParams.get('deptId');
    const keyword = searchParams.get('keyword');
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');

    if (month && !/^\d{4}-\d{2}$/.test(month)) {
      return errorResponse('月份格式不正确，应为 yyyy-MM', 400, 400);
    }

    let sql = `
    SELECT 
      e.id,
      e.employee_no,
      e.name,
      e.gender,
      e.dept_id,
      e.dept_name,
      e.position,
      e.entry_date,
      e.status,
      s.id as salary_id,
      s.month,
      s.basic_salary,
      s.position_allowance,
      s.performance_bonus,
      s.overtime_pay,
      s.other_bonus,
      s.social_security,
      s.housing_fund,
      s.personal_tax,
      s.other_deduction,
      s.actual_salary,
      s.remark
    FROM sys_employee e
    LEFT JOIN sys_salary s ON e.id = s.employee_id AND s.month = ?
    WHERE e.status = 1
  `;

    let countSql = `SELECT COUNT(*) as total FROM sys_employee e WHERE e.status = 1`;
    const params: Loose[] = [month];
    const countParams: Loose[] = [];

    if (deptId) {
      const deptIdNum = parseInt(deptId);
      if (isNaN(deptIdNum) || deptIdNum < 1) {
        return errorResponse('部门ID格式不正确', 400, 400);
      }
      sql += ` AND e.dept_id = ?`;
      countSql += ` AND e.dept_id = ?`;
      params.push(deptIdNum);
      countParams.push(deptIdNum);
    }

    if (keyword) {
      if (keyword.length > 100) {
        return errorResponse('搜索关键词过长', 400, 400);
      }
      sql += ` AND (e.name LIKE ? OR e.employee_no LIKE ?)`;
      countSql += ` AND (e.name LIKE ? OR e.employee_no LIKE ?)`;
      params.push(`%${keyword}%`, `%${keyword}%`);
      countParams.push(`%${keyword}%`, `%${keyword}%`);
    }

    sql += ` ORDER BY e.dept_id, e.employee_no LIMIT ? OFFSET ?`;
    params.push(pageSize, (page - 1) * pageSize);

    const salaries = await query(sql, params);
    const countResult = await query(countSql, countParams);
    const total = (countResult as Loose[])[0]?.total || 0;

    return successResponse({
      list: salaries,
      total,
      page,
      pageSize,
    });
  },
  { errorMessage: '获取薪资列表失败' }
);

export const POST = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();

    const validation = CommonValidations.salary(body);
    if (!validation.valid) {
      return errorResponse(validation.errors.join(', '), 400, 400);
    }

    const {
      employeeId,
      month,
      basicSalary,
      positionAllowance,
      performanceBonus,
      overtimePay,
      otherBonus,
      socialSecurity,
      housingFund,
      personalTax,
      otherDeduction,
      remark,
    } = body;

    const [employee] = await query(`SELECT id FROM sys_employee WHERE id = ? AND status = 1`, [
      employeeId,
    ]);

    if (!employee) {
      return errorResponse('员工不存在或已停用', 400, 400);
    }

    const salaryFields = [
      { name: '基本工资', value: basicSalary },
      { name: '岗位津贴', value: positionAllowance },
      { name: '绩效奖金', value: performanceBonus },
      { name: '加班费', value: overtimePay },
      { name: '其他奖金', value: otherBonus },
      { name: '社保', value: socialSecurity },
      { name: '公积金', value: housingFund },
      { name: '个人所得税', value: personalTax },
      { name: '其他扣款', value: otherDeduction },
    ];

    for (const field of salaryFields) {
      if (
        field.value !== undefined &&
        field.value !== null &&
        (isNaN(field.value) || field.value < 0)
      ) {
        return errorResponse(`${field.name} 不能为负数`, 400, 400);
      }
    }

    if (remark && remark.length > 500) {
      return errorResponse('备注长度不能超过500个字符', 400, 400);
    }

    const totalIncome =
      Number(basicSalary || 0) +
      Number(positionAllowance || 0) +
      Number(performanceBonus || 0) +
      Number(overtimePay || 0) +
      Number(otherBonus || 0);
    const totalDeduction =
      Number(socialSecurity || 0) +
      Number(housingFund || 0) +
      Number(personalTax || 0) +
      Number(otherDeduction || 0);
    const actualSalary = totalIncome - totalDeduction;

    const [existing] = await query(
      `SELECT id FROM sys_salary WHERE employee_id = ? AND month = ?`,
      [employeeId, month]
    );

    if (existing) {
      await query(
        `UPDATE sys_salary SET
        basic_salary = ?,
        position_allowance = ?,
        performance_bonus = ?,
        overtime_pay = ?,
        other_bonus = ?,
        social_security = ?,
        housing_fund = ?,
        personal_tax = ?,
        other_deduction = ?,
        actual_salary = ?,
        remark = ?,
        update_time = NOW()
      WHERE id = ?`,
        [
          basicSalary || 0,
          positionAllowance || 0,
          performanceBonus || 0,
          overtimePay || 0,
          otherBonus || 0,
          socialSecurity || 0,
          housingFund || 0,
          personalTax || 0,
          otherDeduction || 0,
          actualSalary,
          remark || '',
          existing.id,
        ]
      );
    } else {
      await query(
        `INSERT INTO sys_salary (
        employee_id, month, basic_salary, position_allowance, performance_bonus,
        overtime_pay, other_bonus, social_security, housing_fund, personal_tax,
        other_deduction, actual_salary, remark, create_time
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())`,
        [
          employeeId,
          month,
          basicSalary || 0,
          positionAllowance || 0,
          performanceBonus || 0,
          overtimePay || 0,
          otherBonus || 0,
          socialSecurity || 0,
          housingFund || 0,
          personalTax || 0,
          otherDeduction || 0,
          actualSalary,
          remark || '',
        ]
      );
    }

    return successResponse(null, '薪资保存成功');
  },
  { errorMessage: '保存薪资失败' }
);

export const DELETE = withPermission(
  async (request: NextRequest) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return errorResponse('缺少记录ID', 400, 400);
    }

    const idNum = parseInt(id);
    if (isNaN(idNum) || idNum < 1) {
      return errorResponse('记录ID格式不正确', 400, 400);
    }

    const [existing] = await query(`SELECT id FROM sys_salary WHERE id = ?`, [idNum]);

    if (!existing) {
      return errorResponse('薪资记录不存在', 404, 404);
    }

    await query(`DELETE FROM sys_salary WHERE id = ?`, [idNum]);

    return successResponse(null, '薪资记录删除成功');
  },
  { errorMessage: '删除薪资失败' }
);

function format(date: Date, format: string): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  return format.replace('yyyy', String(year)).replace('MM', month);
}

import { NextRequest, NextResponse } from 'next/server';
import { query } from '@/lib/db';
import { withPermission } from '@/lib/api-permissions';

// 获取薪资统计
export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  try {
    const { searchParams } = new URL(request.url);
    const month = searchParams.get('month') || format(new Date(), 'yyyy-MM');

    // 员工总数
    const [employeeResult] = await query(
      `SELECT COUNT(*) as count FROM sys_employee WHERE status = 1`
    );

    // 已发薪人数
    const [paidResult] = await query(
      `SELECT COUNT(DISTINCT employee_id) as count FROM sys_salary WHERE month = ?`,
      [month]
    );

    // 薪资总额
    const [totalResult] = await query(
      `SELECT COALESCE(SUM(actual_salary), 0) as total FROM sys_salary WHERE month = ?`,
      [month]
    );

    // 平均工资
    const [avgResult] = await query(
      `SELECT COALESCE(AVG(actual_salary), 0) as avg FROM sys_salary WHERE month = ?`,
      [month]
    );

    // 最高工资
    const [maxResult] = await query(
      `SELECT COALESCE(MAX(actual_salary), 0) as max FROM sys_salary WHERE month = ?`,
      [month]
    );

    // 最低工资
    const [minResult] = await query(
      `SELECT COALESCE(MIN(actual_salary), 0) as min FROM sys_salary WHERE month = ?`,
      [month]
    );

    // 部门薪资分布
    const deptStats = await query(
      `SELECT 
        e.dept_name,
        COUNT(*) as count,
        COALESCE(SUM(s.actual_salary), 0) as total
      FROM sys_employee e
      LEFT JOIN sys_salary s ON e.id = s.employee_id AND s.month = ?
      WHERE e.status = 1
      GROUP BY e.dept_id, e.dept_name`,
      [month]
    );

    return NextResponse.json({
      success: true,
      data: {
        totalEmployees: employeeResult.count,
        paidEmployees: paidResult.count,
        totalSalary: totalResult.total,
        avgSalary: Math.round(avgResult.avg),
        maxSalary: maxResult.max,
        minSalary: minResult.min,
        deptStats,
      },
    });
  } catch {
    return NextResponse.json({ success: false, message: '获取薪资统计失败' }, { status: 500 });
  }
});

function format(date: Date, format: string): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  return format.replace('yyyy', String(year)).replace('MM', month);
}

import { NextRequest } from 'next/server';
import { getDrizzleDb } from '@/lib/db';
import { eq, and, desc, count, type SQLWrapper } from 'drizzle-orm';
import { hrSchedule, hrShift, sysEmployee } from '@/lib/db/schema';
import { withPermission } from '@/lib/api-permissions';
import { successResponse, errorResponse } from '@/lib/api-response';

const db = getDrizzleDb();

export const GET = withPermission(
  async (request: NextRequest) => {
    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');
    const employeeId = searchParams.get('employeeId');
    const scheduleDate = searchParams.get('scheduleDate');

    const conditions: SQLWrapper[] = [];
    if (employeeId) conditions.push(eq(hrSchedule.employeeId, Number(employeeId)));
    if (scheduleDate) conditions.push(eq(hrSchedule.scheduleDate, new Date(scheduleDate)));

    const [{ total }] = await db
      .select({ total: count() })
      .from(hrSchedule)
      .where(and(...conditions));
    const list = await db
      .select({
        id: hrSchedule.id,
        employeeId: hrSchedule.employeeId,
        employeeName: sysEmployee.name,
        shiftId: hrSchedule.shiftId,
        shiftName: hrShift.shiftName,
        startDate: hrSchedule.scheduleDate,
        endDate: hrSchedule.scheduleDate,
        status: hrSchedule.status,
      })
      .from(hrSchedule)
      .leftJoin(hrShift, eq(hrSchedule.shiftId, hrShift.id))
      .leftJoin(sysEmployee, eq(hrSchedule.employeeId, sysEmployee.id))
      .where(and(...conditions))
      .orderBy(desc(hrSchedule.scheduleDate))
      .limit(pageSize)
      .offset((page - 1) * pageSize);

    return successResponse({ list, total, page, pageSize });
  },
  { errorMessage: '获取排班列表失败' }
);

export const POST = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();
    const { employeeId, shiftId, startDate, endDate } = body;

    if (!employeeId || !shiftId || !startDate) {
      return errorResponse('缺少必填字段', 400, 400);
    }

    try {
      // 如果有结束日期，批量创建排班
      if (endDate) {
        const start = new Date(startDate);
        const end = new Date(endDate);
        const schedules = [];

        while (start <= end) {
          schedules.push({
            employeeId,
            shiftId,
            scheduleDate: new Date(start),
            scheduleType: 'normal',
            source: 'manual',
            status: 1,
          });
          start.setDate(start.getDate() + 1);
        }

        await db
          .insert(hrSchedule)
          .values(schedules)
          .onDuplicateKeyUpdate({
            set: {
              scheduleType: 'normal',
              source: 'manual',
            },
          });
      } else {
        await db
          .insert(hrSchedule)
          .values({
            employeeId,
            shiftId,
            scheduleDate: new Date(startDate),
            scheduleType: 'normal',
            source: 'manual',
            status: 1,
          })
          .onDuplicateKeyUpdate({
            set: {
              scheduleType: 'normal',
              source: 'manual',
            },
          });
      }

      return successResponse(null, '排班创建成功');
    } catch (error) {
      return errorResponse('排班创建失败', 500, 500);
    }
  },
  { errorMessage: '创建排班失败' }
);

