﻿import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import fs from 'fs';
import path from 'path';

import { withPermission } from '@/lib/api-permissions';
// 表状态接口
interface TableStatus {
  table: string;
  exists: boolean;
  error?: string;
}

// 执行结果接口
interface ExecutionResult {
  success: boolean;
  statement: string;
  message?: string;
}

// POST - 初始化库存相关表
export const POST = withPermission(
  async (_request: NextRequest) => {
    // 读取 SQL 文件
    const sqlFilePath = path.join(process.cwd(), 'database', 'inventory_tables.sql');

    // 检查文件是否存在
    if (!fs.existsSync(sqlFilePath)) {
      return errorResponse('SQL文件不存在', 404, 404);
    }

    const sqlContent = fs.readFileSync(sqlFilePath, 'utf-8');

    // 分割 SQL 语句（按分号分割，但忽略注释中的分号）
    const statements = sqlContent
      .split(';')
      .map((s) => s.trim())
      .filter((s) => s.length > 0 && !s.startsWith('--') && !s.startsWith('/*'));

    const results: ExecutionResult[] = [];
    const errors: string[] = [];

    for (const statement of statements) {
      try {
        // 跳过 CREATE DATABASE 和 USE 语句
        if (
          statement.toUpperCase().includes('CREATE DATABASE') ||
          statement.toUpperCase().includes('USE ')
        ) {
          continue;
        }

        await query(statement);
        results.push({
          success: true,
          statement: statement.substring(0, 50) + '...',
        });
      } catch (error) {
        // 忽略表已存在的错误
        if ((error as Error & { code?: string }).code === 'ER_TABLE_EXISTS_ERROR') {
          results.push({
            success: true,
            statement: statement.substring(0, 50) + '...',
            message: '表已存在，跳过',
          });
        } else {
          errors.push(`执行失败: ${statement.substring(0, 50)}... - ${(error as Error).message}`);
        }
      }
    }

    return successResponse(
      {
        results,
        errors: errors.length > 0 ? errors : undefined,
        totalStatements: statements.length,
        successCount: results.filter((r) => r.success).length,
        errorCount: errors.length,
      },
      '库存表初始化完成'
    );
  },
  { errorMessage: '初始化库存表失败' }
);

// GET - 检查表是否存在
export const GET = withPermission(
  async (_request: NextRequest) => {
    const tables = ['bas_material', 'inv_location', 'inv_inventory_batch'];
    const results: TableStatus[] = [];

    for (const table of tables) {
      try {
        await query(`SELECT 1 FROM ${table} LIMIT 1`);
        results.push({ table, exists: true });
      } catch (error) {
        if ((error as Error & { code?: string }).code === 'ER_NO_SUCH_TABLE') {
          results.push({ table, exists: false });
        } else {
          results.push({ table, exists: false, error: (error as Error).message });
        }
      }
    }

    const allExist = results.every((r) => r.exists);

    return successResponse({
      tables: results,
      allExist,
      ready: allExist,
    });
  },
  { errorMessage: '检查表状态失败' }
);

import { NextRequest } from 'next/server';
import { transaction } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { logger } from '@/lib/logger';
export const POST = withPermission(async (_request: NextRequest) => {
  const startTime = Date.now();
  logger.info('[MENU_INIT] ==================== 菜单初始化开始 ====================');
  logger.info(`[MENU_INIT] 时间: ${new Date().toISOString()}`);

  try {
    const result = await transaction(async (conn) => {
      const results: string[] = [];
      logger.info('[MENU_INIT] 步骤1: 开始处理顶级菜单...');

      const topLevelMenus = [
        { menu_name: '看板中心', menu_code: 'dashboard_center', icon: 'BarChart3', sort_order: 1 },
        { menu_name: '业务部', menu_code: 'orders', icon: 'ShoppingCart', sort_order: 2 },
        { menu_name: '工程技术部', menu_code: 'engineering', icon: 'Wrench', sort_order: 3 },
        { menu_name: '生产部', menu_code: 'production', icon: 'Factory', sort_order: 4 },
        { menu_name: '仓库管理', menu_code: 'warehouse', icon: 'Warehouse', sort_order: 5 },
        { menu_name: '采购部', menu_code: 'purchase', icon: 'ShoppingBag', sort_order: 6 },
        { menu_name: '品质部', menu_code: 'quality', icon: 'ShieldCheck', sort_order: 7 },
        { menu_name: '财务管理', menu_code: 'finance', icon: 'Banknote', sort_order: 8 },
        { menu_name: '人事行政部', menu_code: 'hr', icon: 'Users', sort_order: 9 },
        { menu_name: '系统设置', menu_code: 'settings', icon: 'Settings', sort_order: 10 },
      ];

      for (const menu of topLevelMenus) {
        const [existing]: Loose = await conn.execute(
          'SELECT id, parent_id FROM sys_menu WHERE menu_code = ?',
          [menu.menu_code]
        );
        if (existing && existing.length > 0) {
          const existingMenu = existing[0];
          if (existingMenu.parent_id === 0) {
            await conn.execute(
              'UPDATE sys_menu SET menu_name = ?, icon = ?, sort_order = ?, path = ? WHERE menu_code = ?',
              [
                menu.menu_name,
                menu.icon,
                menu.sort_order,
                menu.menu_code === 'dashboard_center' ? '/dashboard_center' : `/${menu.menu_code}`,
                menu.menu_code,
              ]
            );
            results.push(`${menu.menu_code}: 已更新`);
          } else {
            await conn.execute('DELETE FROM sys_role_menu WHERE menu_id = ?', [existingMenu.id]);
            await conn.execute('DELETE FROM sys_menu WHERE id = ?', [existingMenu.id]);
            await conn.execute(
              'INSERT INTO sys_menu (parent_id, menu_name, menu_code, menu_type, icon, path, component, permission, sort_order, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
              [
                0,
                menu.menu_name,
                menu.menu_code,
                1,
                menu.icon,
                menu.menu_code === 'dashboard_center' ? '/dashboard_center' : `/${menu.menu_code}`,
                null,
                `${menu.menu_code}:*`,
                menu.sort_order,
                1,
              ]
            );
            results.push(`${menu.menu_code}: 重复菜单已删除并重建为顶级菜单`);
          }
        } else {
          await conn.execute(
            'INSERT INTO sys_menu (parent_id, menu_name, menu_code, menu_type, icon, path, component, permission, sort_order, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
            [
              0,
              menu.menu_name,
              menu.menu_code,
              1,
              menu.icon,
              menu.menu_code === 'dashboard_center' ? '/dashboard_center' : `/${menu.menu_code}`,
              null,
              `${menu.menu_code}:*`,
              menu.sort_order,
              1,
            ]
          );
          results.push(`${menu.menu_code}: 创建成功`);
        }
      }
      logger.info(`[MENU_INIT] 步骤1完成: 顶级菜单处理完毕, 数量: ${topLevelMenus.length}`);

      const menuMigrations: { from: string; to: string; new_name?: string }[] = [
        { from: 'dashboard', to: 'dashboard_center', new_name: '看板中心' },
        { from: 'sample', to: 'engineering' },
        { from: 'prepress', to: 'engineering' },
        { from: 'plm', to: 'engineering' },
        { from: 'dcprint', to: 'production' },
        { from: 'equipment', to: 'production' },
        { from: 'base_data', to: 'settings' },
        { from: 'outsource', to: 'purchase' },
        { from: 'qrcode', to: 'quality' },
        { from: 'crm', to: 'orders' },
        { from: 'srm', to: 'purchase' },
      ];

      for (const mig of menuMigrations) {
        const [fromMenu]: Loose = await conn.execute(
          'SELECT id FROM sys_menu WHERE menu_code = ?',
          [mig.from]
        );
        const [toMenu]: Loose = await conn.execute('SELECT id FROM sys_menu WHERE menu_code = ?', [
          mig.to,
        ]);

        if (fromMenu && fromMenu.length > 0 && toMenu && toMenu.length > 0) {
          const fromId = fromMenu[0].id;
          const toId = toMenu[0].id;

          await conn.execute(
            'UPDATE sys_menu SET parent_id = ? WHERE parent_id = ? AND menu_type = 2',
            [toId, fromId]
          );

          if (mig.new_name) {
            await conn.execute('UPDATE sys_menu SET menu_name = ? WHERE id = ?', [
              mig.new_name,
              toId,
            ]);
          }

          await conn.execute('DELETE FROM sys_role_menu WHERE menu_id = ?', [fromId]);
          await conn.execute('DELETE FROM sys_menu WHERE id = ?', [fromId]);
          results.push(`${mig.from} -> ${mig.to}: 合并完成`);
        } else if (fromMenu && fromMenu.length > 0 && (!toMenu || toMenu.length === 0)) {
          if (mig.new_name) {
            await conn.execute('UPDATE sys_menu SET menu_name = ?, menu_code = ? WHERE id = ?', [
              mig.new_name,
              mig.to,
              fromMenu[0].id,
            ]);
          }
          results.push(`${mig.from}: 重命名为 ${mig.to}`);
        } else {
          results.push(`${mig.from} -> ${mig.to}: 无需迁移`);
        }
      }
      logger.info(`[MENU_INIT] 步骤2完成: 菜单迁移处理完毕, 迁移数: ${menuMigrations.length}`);

      const duplicateDeletes = [
        'dashboard',
        'finance_main',
        'settings_users',
        'settings_logs',
        'orders_sample',
        'dcprint_cards',
        'dcprint_screen_plate',
        'dcprint_die',
        'base_data_material_category',
      ];

      for (const code of duplicateDeletes) {
        const [dup]: Loose = await conn.execute('SELECT id FROM sys_menu WHERE menu_code = ?', [
          code,
        ]);
        if (dup && dup.length > 0) {
          await conn.execute('DELETE FROM sys_role_menu WHERE menu_id = ?', [dup[0].id]);
          await conn.execute('DELETE FROM sys_menu WHERE id = ?', [dup[0].id]);
          results.push(`${code}: 已删除重复菜单`);
        }
      }
      logger.info('[MENU_INIT] 步骤3完成: 重复菜单删除完毕');

      const [pathDups]: Loose = await conn.execute(
        `SELECT m1.id, m1.menu_code, m1.menu_name, m1.path
       FROM sys_menu m1
       JOIN sys_menu m2 ON m1.path = m2.path AND m1.id > m2.id AND m1.path IS NOT NULL AND m1.path != ''
       WHERE m1.status = 1 AND m1.menu_type = 2`
      );
      for (const dup of pathDups) {
        await conn.execute('DELETE FROM sys_role_menu WHERE menu_id = ?', [dup.id]);
        await conn.execute('DELETE FROM sys_menu WHERE id = ?', [dup.id]);
        results.push(`${dup.menu_code}(${dup.menu_name}): 路径重复删除, path=${dup.path}`);
      }
      logger.info('[MENU_INIT] 步骤4完成: 路径重复菜单删除完毕, 删除数:', pathDups.length || 0);

      const moveMenusToEngineering = ['dcprint_ink', 'dcprint_process_cards', 'dcprint_labels'];

      const [engMenu]: Loose = await conn.execute(
        "SELECT id FROM sys_menu WHERE menu_code = 'engineering' AND parent_id = 0"
      );
      if (engMenu && engMenu.length > 0) {
        const engId = engMenu[0].id;
        for (const code of moveMenusToEngineering) {
          const [menuItem]: Loose = await conn.execute(
            'SELECT id FROM sys_menu WHERE menu_code = ?',
            [code]
          );
          if (menuItem && menuItem.length > 0) {
            await conn.execute('UPDATE sys_menu SET parent_id = ? WHERE id = ?', [
              engId,
              menuItem[0].id,
            ]);
            results.push(`${code}: 已移至工程技术部`);
          }
        }
      }
      logger.info('[MENU_INIT] 步骤5完成: 菜单移动完毕');

      logger.info('[MENU_INIT] 步骤6: 开始处理二级菜单项...');
      const newMenus = [
        {
          parent_code: 'dashboard_center',
          menu_name: '总览看板',
          menu_code: 'dashboard_main',
          menu_type: 2,
          icon: null,
          path: '/dashboard',
