                parentId,
                menu.menu_name,
                menu.menu_code,
                menu.menu_type,
                menu.icon,
                menu.path,
                menu.component,
                menu.permission,
                menu.sort_order,
                1,
                1,
              ]
            );
            results.push(`${menu.menu_code}: 创建成功(含is_visible)`);
          } catch (_insertErr) {
            try {
              await conn.execute(
                'INSERT INTO sys_menu (parent_id, menu_name, menu_code, menu_type, icon, path, component, permission, sort_order, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
