                  parentId,
                  menu.menu_name,
                  menu.menu_code,
                  menu.menu_type,
                  menu.icon,
                  menu.path,
                  menu.component,
                  menu.permission,
                  menu.sort_order,
                  1,
                ]
              );
              results.push(`${menu.menu_code}: 创建成功`);
            } catch (insertErr2) {
              results.push(`${menu.menu_code}: 创建失败 - ${(insertErr2 as Error).message}`);
            }
          }
        }
      }
      logger.info(`[MENU_INIT] 步骤6完成: 二级菜单项处理完毕, 总数: ${newMenus.length}`);

      logger.info('[MENU_INIT] 步骤7: 开始更新系统管理员菜单权限...');
      const [roles]: Loose = await conn.execute(
        "SELECT id FROM sys_role WHERE role_code = 'super_admin' LIMIT 1"
      );
      if (roles && roles.length > 0) {
        const adminRoleId = roles[0].id;

        const [allMenus]: Loose = await conn.execute('SELECT id FROM sys_menu WHERE status = 1');
        for (const menu of allMenus) {
          const [existing]: Loose = await conn.execute(
            'SELECT id FROM sys_role_menu WHERE role_id = ? AND menu_id = ?',
            [adminRoleId, menu.id]
          );
          if (!existing || existing.length === 0) {
            await conn.execute('INSERT INTO sys_role_menu (role_id, menu_id) VALUES (?, ?)', [
              adminRoleId,
              menu.id,
            ]);
          }
        }
        results.push('系统管理员菜单权限已更新');
      }
      logger.info('[MENU_INIT] 步骤7完成: 系统管理员菜单权限更新完毕');

      return results;
    });

    const endTime = Date.now();
    logger.info('[MENU_INIT] ==================== 菜单初始化完成 ====================');
    logger.info(`[MENU_INIT] 耗时: ${(endTime - startTime) / 1000} 秒`);
    logger.info(`[MENU_INIT] 结果记录数: ${result.length}`);

    return successResponse(result, '菜单优化初始化成功');
  } catch (error) {
    const endTime = Date.now();
    logger.error('[MENU_INIT] ==================== 菜单初始化失败 ====================');
    logger.error(`[MENU_INIT] 耗时: ${(endTime - startTime) / 1000} 秒`);
    logger.error(`[MENU_INIT] 错误: ${error}`);

    return errorResponse('菜单初始化失败: ' + (error as Error).message, 500);
  }
});

import { NextRequest } from 'next/server';
import { transaction } from '@/lib/db';
import { successResponse } from '@/lib/api-response';

import { withPermission } from '@/lib/api-permissions';
export const POST = withPermission(async (_request: NextRequest) => {
  const result = await transaction(async (conn) => {
    const results: string[] = [];

    const migrations: { table: string; column: string; definition: string; after?: string }[] = [
      {
        table: 'inv_trace_record',
        column: 'deleted',
        definition: "TINYINT DEFAULT 0 COMMENT '软删除: 0-否, 1-是'",
        after: 'remark',
      },
      {
        table: 'inv_material_label',
        column: 'mix_remark',
        definition: "VARCHAR(500) COMMENT '混料备注'",
        after: 'color_code',
      },
      {
        table: 'inv_material_label',
        column: 'label_type',
        definition: "TINYINT DEFAULT 1 COMMENT '标签类型: 1-原材料, 2-分切子批, 3-余料'",
        after: 'is_cut',
      },
      {
        table: 'inv_material_label',
        column: 'remaining_width',
        definition: "DECIMAL(18,2) COMMENT '剩余宽幅（余料）'",
        after: 'label_type',
      },
      {
        table: 'inv_material_label',
        column: 'remaining_length',
        definition: "DECIMAL(18,2) COMMENT '剩余长度（余料）'",
        after: 'remaining_width',
      },
      {
        table: 'prd_process_card',
        column: 'lock_status',
        definition: "TINYINT DEFAULT 0 COMMENT '锁住状态: 0-未锁, 1-已锁'",
        after: 'burdening_status',
      },
      {
        table: 'sys_user',
        column: 'first_login',
        definition: "TINYINT DEFAULT 1 COMMENT '首次登录: 0-否, 1-是'",
        after: 'status',
      },
      {
        table: 'sys_user',
        column: 'pwd_update_time',
        definition: "DATETIME COMMENT '密码更新时间'",
        after: 'first_login',
      },
      {
        table: 'prd_standard_card',
        column: 'mold_type',
        definition: "VARCHAR(100) DEFAULT '' COMMENT '模号/种类'",
        after: 'material_type',
      },
      {
        table: 'prd_standard_card',
        column: 'etch_mold',
        definition: "VARCHAR(100) DEFAULT '' COMMENT '腐蚀刀模'",
        after: 'back_mylar_mold',
      },
      {
        table: 'prd_standard_card',
        column: 'storage_location',
        definition: "VARCHAR(100) DEFAULT '' COMMENT '存放位置'",
        after: 'etch_mold',
      },
      {
        table: 'prd_standard_card',
        column: 'extra_field',
        definition: "VARCHAR(100) DEFAULT '' COMMENT '额外字段'",
        after: 'storage_location',
      },
    ];

    for (const migration of migrations) {
      try {
        const [columns]: Loose = await conn.execute(
          `SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ?`,
          [migration.table, migration.column]
        );

        if (columns && columns.length > 0) {
          results.push(`${migration.table}.${migration.column}: 已存在，跳过`);
          continue;
        }

        const afterClause = migration.after ? ` AFTER \`${migration.after}\`` : '';
        await conn.execute(
          `ALTER TABLE \`${migration.table}\` ADD COLUMN \`${migration.column}\` ${migration.definition}${afterClause}`
        );
        results.push(`${migration.table}.${migration.column}: 添加成功`);
      } catch (err) {
        results.push(
          `${migration.table}.${migration.column}: 添加失败 - ${(err as Error).message}`
        );
      }
    }

    const createTables: { name: string; sql: string }[] = [
      {
        name: 'bom_header',
        sql: `CREATE TABLE IF NOT EXISTS bom_header (
          id INT AUTO_INCREMENT PRIMARY KEY,
          bom_no VARCHAR(50) NOT NULL COMMENT 'BOM编号',
          product_id INT COMMENT '产品ID',
          product_code VARCHAR(50) COMMENT '产品编码',
          product_name VARCHAR(200) COMMENT '产品名称',
          product_spec VARCHAR(200) COMMENT '产品规格',
          version VARCHAR(20) DEFAULT '1.0' COMMENT '版本号',
          is_default TINYINT DEFAULT 1 COMMENT '是否默认BOM',
          status INT DEFAULT 10 COMMENT '状态: 10-草稿 20-已审核 30-已发布 90-已停用',
          unit VARCHAR(20) COMMENT '单位',
          base_qty DECIMAL(12,2) DEFAULT 1 COMMENT '基本数量',
          total_material_count INT DEFAULT 0 COMMENT '物料总数',
          total_cost DECIMAL(12,2) DEFAULT 0 COMMENT '总成本',
          remark VARCHAR(500) COMMENT '备注',
          deleted TINYINT DEFAULT 0 COMMENT '软删除',
          create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
          update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
          UNIQUE KEY uk_bom_no (bom_no)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='BOM头表'`,
      },
      {
        name: 'bom_line',
        sql: `CREATE TABLE IF NOT EXISTS bom_line (
          id INT AUTO_INCREMENT PRIMARY KEY,
          bom_id INT NOT NULL COMMENT 'BOM头ID',
          line_no INT NOT NULL COMMENT '行号',
          material_id INT COMMENT '物料ID',
          material_code VARCHAR(50) COMMENT '物料编码',
          material_name VARCHAR(200) COMMENT '物料名称',
          material_spec VARCHAR(200) COMMENT '物料规格',
          material_unit VARCHAR(20) COMMENT '物料单位',
          usage_qty DECIMAL(12,4) NOT NULL DEFAULT 0 COMMENT '用量',
          loss_rate DECIMAL(5,2) DEFAULT 0 COMMENT '损耗率',
          unit_cost DECIMAL(12,2) DEFAULT 0 COMMENT '单价',
          total_cost DECIMAL(12,2) DEFAULT 0 COMMENT '总成本',
          remark VARCHAR(500) COMMENT '备注',
          create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
          update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
          KEY idx_bom_id (bom_id)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='BOM行表'`,
      },
    ];

    for (const table of createTables) {
      try {
        const [rows]: Loose = await conn.execute(
          `SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ?`,
          [table.name]
        );
        if (rows && rows.length > 0) {
          results.push(`${table.name}: 表已存在，跳过`);
        } else {
          await conn.execute(table.sql);
          results.push(`${table.name}: 表创建成功`);
        }
      } catch (err) {
        results.push(`${table.name}: 创建失败 - ${(err as Error).message}`);
      }
    }

    const indexMigrations: { table: string; indexName: string; definition: string }[] = [
      {
        table: 'inv_trace_record',
        indexName: 'idx_deleted',
        definition: 'idx_deleted (deleted)',
      },
    ];

    for (const idxMigration of indexMigrations) {
      try {
        const [indexes]: Loose = await conn.execute(
          `SELECT INDEX_NAME FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND INDEX_NAME = ?`,
          [idxMigration.table, idxMigration.indexName]
        );

        if (indexes && indexes.length > 0) {
          results.push(`${idxMigration.table}.${idxMigration.indexName}: 索引已存在，跳过`);
          continue;
        }

        await conn.execute(
          `ALTER TABLE \`${idxMigration.table}\` ADD INDEX ${idxMigration.definition}`
        );
        results.push(`${idxMigration.table}.${idxMigration.indexName}: 索引添加成功`);
      } catch (err) {
        results.push(
          `${idxMigration.table}.${idxMigration.indexName}: 索引添加失败 - ${(err as Error).message}`
        );
      }
    }

    return results;
  });

  return successResponse(result, '数据库迁移完成');
});

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';

// 辅助函数：检查列是否存在
async function columnExists(tableName: string, columnName: string): Promise<boolean> {
  const result = await query(
    `SELECT 1 FROM information_schema.COLUMNS 
     WHERE TABLE_SCHEMA = DATABASE() 
     AND TABLE_NAME = ? 
     AND COLUMN_NAME = ?`,
    [tableName, columnName]
  );
  return (result as Loose[]).length > 0;
}

// 辅助函数：安全地添加列
async function addColumnSafe(tableName: string, columnDef: string) {
  try {
    await query(`ALTER TABLE ${tableName} ADD COLUMN ${columnDef}`);
  } catch (e) {
    if ((e as Error & { code?: string }).code === 'ER_DUP_FIELDNAME') {
      // 列已存在，忽略错误
      return;
    }
    throw e;
  }
}

export async function GET(_request: NextRequest) {
  try {
    const results: string[] = [];

    // 检查并创建采购单主表
    const poTableExists = await query(
      `SELECT 1 FROM information_schema.TABLES 
       WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'pur_purchase_order'`
    );

    if ((poTableExists as Loose[]).length === 0) {
      await query(`
        CREATE TABLE pur_purchase_order (
          id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT '主键ID',
          po_no VARCHAR(50) NOT NULL COMMENT '采购单号',
          supplier_id INT UNSIGNED DEFAULT NULL COMMENT '供应商ID',
          supplier_name VARCHAR(100) NOT NULL COMMENT '供应商名称',
          supplier_code VARCHAR(50) DEFAULT NULL COMMENT '供应商编码',
          order_date DATE NOT NULL COMMENT '订单日期',
          delivery_date DATE DEFAULT NULL COMMENT '预计交货日期',
          currency VARCHAR(10) DEFAULT 'CNY' COMMENT '币种',
          exchange_rate DECIMAL(10,4) DEFAULT 1.0000 COMMENT '汇率',
          total_amount DECIMAL(14,2) DEFAULT 0 COMMENT '订单总金额',
          total_quantity DECIMAL(14,3) DEFAULT 0 COMMENT '订单总数量',
          tax_rate DECIMAL(5,2) DEFAULT 13.00 COMMENT '税率%',
          tax_amount DECIMAL(14,2) DEFAULT 0 COMMENT '税额',
          grand_total DECIMAL(14,2) DEFAULT 0 COMMENT '含税总金额',
          status TINYINT UNSIGNED DEFAULT 10 COMMENT '状态: 10-草稿,20-待审批,30-已审批,40-部分收货,50-已完成,90-已关闭',
          over_receipt_tolerance DECIMAL(5,2) DEFAULT 5.00 COMMENT '超收容差率%',
          payment_terms VARCHAR(100) DEFAULT NULL COMMENT '付款条款',
          delivery_address TEXT DEFAULT NULL COMMENT '送货地址',
          contact_person VARCHAR(50) DEFAULT NULL COMMENT '联系人',
          contact_phone VARCHAR(50) DEFAULT NULL COMMENT '联系电话',
          remark TEXT DEFAULT NULL COMMENT '备注',
          create_by INT UNSIGNED DEFAULT NULL COMMENT '创建人ID',
          create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
          update_by INT UNSIGNED DEFAULT NULL COMMENT '更新人ID',
          update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
          audit_by INT UNSIGNED DEFAULT NULL COMMENT '审批人ID',
          audit_time DATETIME DEFAULT NULL COMMENT '审批时间',
          close_by INT UNSIGNED DEFAULT NULL COMMENT '关闭人ID',
          close_time DATETIME DEFAULT NULL COMMENT '关闭时间',
          close_reason VARCHAR(200) DEFAULT NULL COMMENT '关闭原因',
          deleted TINYINT(1) DEFAULT 0 COMMENT '是否删除',
          UNIQUE KEY uk_po_no (po_no),
          INDEX idx_supplier (supplier_id),
          INDEX idx_status (status),
          INDEX idx_order_date (order_date),
          INDEX idx_delivery_date (delivery_date),
          INDEX idx_create_time (create_time)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购单主表'
      `);
      results.push('✅ 创建表: pur_purchase_order');
    } else {
      results.push('✓ 表已存在: pur_purchase_order');
    }

    // 检查并创建采购单行表
    const poLineTableExists = await query(
      `SELECT 1 FROM information_schema.TABLES 
       WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'pur_purchase_order_line'`
    );

    if ((poLineTableExists as Loose[]).length === 0) {
      await query(`
        CREATE TABLE pur_purchase_order_line (
          id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT '主键ID',
          po_id INT UNSIGNED NOT NULL COMMENT '采购单ID',
          line_no INT UNSIGNED NOT NULL COMMENT '行号',
          material_id INT UNSIGNED DEFAULT NULL COMMENT '物料ID',
          material_code VARCHAR(50) NOT NULL COMMENT '物料编码',
          material_name VARCHAR(200) NOT NULL COMMENT '物料名称',
          material_spec VARCHAR(500) DEFAULT NULL COMMENT '物料规格',
          unit VARCHAR(20) DEFAULT '件' COMMENT '单位',
          order_qty DECIMAL(14,3) NOT NULL DEFAULT 0 COMMENT '订购数量',
          received_qty DECIMAL(14,3) DEFAULT 0 COMMENT '累计入库数量',
          returned_qty DECIMAL(14,3) DEFAULT 0 COMMENT '累计退货数量',
          unit_price DECIMAL(14,4) NOT NULL DEFAULT 0 COMMENT '单价',
          amount DECIMAL(14,2) DEFAULT 0 COMMENT '金额',
          tax_rate DECIMAL(5,2) DEFAULT 13.00 COMMENT '税率%',
          tax_amount DECIMAL(14,2) DEFAULT 0 COMMENT '税额',
          line_total DECIMAL(14,2) DEFAULT 0 COMMENT '行合计',
          require_date DATE DEFAULT NULL COMMENT '需求日期',
          closed_flag TINYINT(1) DEFAULT 0 COMMENT '行关闭标志',
          closed_reason VARCHAR(200) DEFAULT NULL COMMENT '关闭原因',
          remark TEXT DEFAULT NULL COMMENT '备注',
          create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
          update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
          UNIQUE KEY uk_po_line (po_id, line_no),
          INDEX idx_material (material_id),
          INDEX idx_material_code (material_code),
          INDEX idx_require_date (require_date),
          FOREIGN KEY (po_id) REFERENCES pur_purchase_order(id) ON DELETE CASCADE
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购单行表'
      `);
      results.push('✅ 创建表: pur_purchase_order_line');
    } else {
      results.push('✓ 表已存在: pur_purchase_order_line');
    }

    // 检查并创建库存事务表
    const transTableExists = await query(
      `SELECT 1 FROM information_schema.TABLES 
       WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'inv_inventory_transaction'`
    );

    if ((transTableExists as Loose[]).length === 0) {
      await query(`
        CREATE TABLE inv_inventory_transaction (
          id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT '主键ID',
          trans_no VARCHAR(50) NOT NULL COMMENT '事务单号',
          trans_type ENUM('in', 'out', 'transfer', 'adjust', 'return') NOT NULL COMMENT '事务类型',
          source_type ENUM('grn', 'delivery', 'transfer', 'adjust', 'production') DEFAULT NULL COMMENT '来源类型',
          source_id INT UNSIGNED DEFAULT NULL COMMENT '来源单据ID',
          source_line_id INT UNSIGNED DEFAULT NULL COMMENT '来源单据行ID',
          material_id INT UNSIGNED DEFAULT NULL COMMENT '物料ID',
          material_code VARCHAR(50) NOT NULL COMMENT '物料编码',
          batch_no VARCHAR(50) DEFAULT NULL COMMENT '批次号',
          warehouse_id INT UNSIGNED DEFAULT NULL COMMENT '仓库ID',
          location_id INT UNSIGNED DEFAULT NULL COMMENT '库位ID',
          quantity DECIMAL(14,3) NOT NULL DEFAULT 0 COMMENT '数量',
          unit_cost DECIMAL(14,4) DEFAULT 0 COMMENT '单位成本',
          total_cost DECIMAL(14,2) DEFAULT 0 COMMENT '总成本',
          unit_price DECIMAL(14,4) DEFAULT 0 COMMENT '单价',
          total_amount DECIMAL(14,2) DEFAULT 0 COMMENT '总金额',
          account_dr VARCHAR(50) DEFAULT NULL COMMENT '借方科目',
          account_cr VARCHAR(50) DEFAULT NULL COMMENT '贷方科目',
          reference_no VARCHAR(100) DEFAULT NULL COMMENT '参考单号',
          remark TEXT DEFAULT NULL COMMENT '备注',
          create_by INT UNSIGNED DEFAULT NULL COMMENT '创建人ID',
          create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
          UNIQUE KEY uk_trans_no (trans_no),
          INDEX idx_trans_type (trans_type),
          INDEX idx_source (source_type, source_id),
          INDEX idx_material (material_id),
          INDEX idx_batch (batch_no),
          INDEX idx_warehouse (warehouse_id),
          INDEX idx_create_time (create_time)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='库存事务表'
      `);
      results.push('✅ 创建表: inv_inventory_transaction');
    } else {
      results.push('✓ 表已存在: inv_inventory_transaction');
    }

    // 检查并创建退货单表
    const rtvTableExists = await query(
      `SELECT 1 FROM information_schema.TABLES 
       WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'pur_return_order'`
    );

    if ((rtvTableExists as Loose[]).length === 0) {
      await query(`
        CREATE TABLE pur_return_order (
          id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT '主键ID',
          rtv_no VARCHAR(50) NOT NULL COMMENT '退货单号',
          po_id INT UNSIGNED NOT NULL COMMENT '关联采购单ID',
          po_no VARCHAR(50) NOT NULL COMMENT '采购单号',
          grn_id INT UNSIGNED DEFAULT NULL COMMENT '关联入库单ID',
          supplier_id INT UNSIGNED DEFAULT NULL COMMENT '供应商ID',
          supplier_name VARCHAR(100) NOT NULL COMMENT '供应商名称',
          return_date DATE NOT NULL COMMENT '退货日期',
          total_qty DECIMAL(14,3) DEFAULT 0 COMMENT '退货总数量',
          total_amount DECIMAL(14,2) DEFAULT 0 COMMENT '退货总金额',
          status TINYINT UNSIGNED DEFAULT 10 COMMENT '状态: 10-草稿,20-待审批,30-已审批,40-已出库,90-已取消',
          return_reason VARCHAR(200) NOT NULL COMMENT '退货原因',
          return_type ENUM('qc_fail', 'damage', 'wrong_item', 'over_order', 'other') DEFAULT 'qc_fail' COMMENT '退货类型',
          remark TEXT DEFAULT NULL COMMENT '备注',
          create_by INT UNSIGNED DEFAULT NULL COMMENT '创建人ID',
          create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
          update_by INT UNSIGNED DEFAULT NULL COMMENT '更新人ID',
          update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
          audit_by INT UNSIGNED DEFAULT NULL COMMENT '审批人ID',
          audit_time DATETIME DEFAULT NULL COMMENT '审批时间',
          deleted TINYINT(1) DEFAULT 0 COMMENT '是否删除',
          UNIQUE KEY uk_rtv_no (rtv_no),
          INDEX idx_po_id (po_id),
          INDEX idx_grn_id (grn_id),
          INDEX idx_status (status),
          INDEX idx_return_date (return_date)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='退货单主表'
      `);
      results.push('✅ 创建表: pur_return_order');
    } else {
      results.push('✓ 表已存在: pur_return_order');
    }

    // 检查并创建供应商表
    const supplierTableExists = await query(
      `SELECT 1 FROM information_schema.TABLES 
       WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'pur_supplier'`
    );

    if ((supplierTableExists as Loose[]).length === 0) {
      await query(`
        CREATE TABLE pur_supplier (
          id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT '主键ID',
          supplier_code VARCHAR(50) NOT NULL COMMENT '供应商编码',
          supplier_name VARCHAR(100) NOT NULL COMMENT '供应商名称',
          supplier_type ENUM('material', 'service', 'outsourcing', 'other') DEFAULT 'material' COMMENT '供应商类型',
          contact_person VARCHAR(50) DEFAULT NULL COMMENT '联系人',
          contact_phone VARCHAR(50) DEFAULT NULL COMMENT '联系电话',
          email VARCHAR(100) DEFAULT NULL COMMENT '邮箱',
          address TEXT DEFAULT NULL COMMENT '地址',
          payment_terms VARCHAR(100) DEFAULT NULL COMMENT '付款条款',
          tax_rate DECIMAL(5,2) DEFAULT 13.00 COMMENT '默认税率%',
          over_receipt_tolerance DECIMAL(5,2) DEFAULT 5.00 COMMENT '超收容差率%',
          currency VARCHAR(10) DEFAULT 'CNY' COMMENT '币种',
          status TINYINT(1) DEFAULT 1 COMMENT '状态: 1-启用, 0-禁用',
          remark TEXT DEFAULT NULL COMMENT '备注',
          create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
          update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
          deleted TINYINT(1) DEFAULT 0 COMMENT '是否删除',
          UNIQUE KEY uk_supplier_code (supplier_code),
          INDEX idx_supplier_name (supplier_name),
          INDEX idx_status (status)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='供应商表'
      `);
      results.push('✅ 创建表: pur_supplier');
    } else {
      results.push('✓ 表已存在: pur_supplier');
    }

    // 修改现有入库单表，添加PO关联字段
    const inboundColumns = [
      { name: 'po_id', def: "po_id INT UNSIGNED DEFAULT NULL COMMENT '关联采购单ID'" },
      { name: 'po_no', def: "po_no VARCHAR(50) DEFAULT NULL COMMENT '采购单号'" },
      {
        name: 'grn_type',
        def: "grn_type ENUM('po', 'blind', 'return') DEFAULT 'po' COMMENT '入库类型'",
      },
      { name: 'asn_no', def: "asn_no VARCHAR(50) DEFAULT NULL COMMENT '到货通知单号'" },
      {
        name: 'delivery_no',
        def: "delivery_no VARCHAR(100) DEFAULT NULL COMMENT '送货单号/快递单号'",
      },
      {
        name: 'qc_status',
        def: "qc_status ENUM('pending', 'pass', 'fail', 'partial') DEFAULT 'pending' COMMENT '质检状态'",
      },
      { name: 'qc_remark', def: "qc_remark TEXT DEFAULT NULL COMMENT '质检备注'" },
      { name: 'post_time', def: "post_time DATETIME DEFAULT NULL COMMENT '过账时间'" },
      { name: 'post_by', def: "post_by INT UNSIGNED DEFAULT NULL COMMENT '过账人ID'" },
    ];

    let inboundUpdated = false;
    for (const col of inboundColumns) {
      if (!(await columnExists('inv_inbound_order', col.name))) {
        await addColumnSafe('inv_inbound_order', col.def);
        inboundUpdated = true;
      }
    }

    // 添加索引
    try {
      await query(`CREATE INDEX idx_po_id ON inv_inbound_order(po_id)`);
    } catch {
      /* 索引可能已存在 */
    }
    try {
      await query(`CREATE INDEX idx_po_no ON inv_inbound_order(po_no)`);
    } catch {
      /* 索引可能已存在 */
    }
    try {
      await query(`CREATE INDEX idx_grn_type ON inv_inbound_order(grn_type)`);
    } catch {
      /* 索引可能已存在 */
    }

    if (inboundUpdated) {
      results.push('✅ 更新表: inv_inbound_order (添加PO关联字段)');
    } else {
      results.push('✓ 表已更新: inv_inbound_order');
    }

    // 修改现有入库明细表，添加PO关联字段
    const itemColumns = [
      { name: 'po_line_id', def: "po_line_id INT UNSIGNED DEFAULT NULL COMMENT '关联采购单行ID'" },
      { name: 'line_no', def: "line_no INT UNSIGNED DEFAULT NULL COMMENT '行号'" },
      { name: 'accepted_qty', def: "accepted_qty DECIMAL(14,3) DEFAULT 0 COMMENT '合格数量'" },
      { name: 'rejected_qty', def: "rejected_qty DECIMAL(14,3) DEFAULT 0 COMMENT '不良数量'" },
      {
        name: 'qc_result',
        def: "qc_result ENUM('pending', 'pass', 'fail', 'partial') DEFAULT 'pending' COMMENT '质检结果'",
      },
      {
        name: 'qc_inspector_id',
        def: "qc_inspector_id INT UNSIGNED DEFAULT NULL COMMENT '质检员ID'",
      },
      { name: 'qc_time', def: "qc_time DATETIME DEFAULT NULL COMMENT '质检时间'" },
      {
        name: 'supplier_batch_no',
        def: "supplier_batch_no VARCHAR(100) DEFAULT NULL COMMENT '供应商批次号'",
      },
      { name: 'warehouse_id', def: "warehouse_id INT UNSIGNED DEFAULT NULL COMMENT '仓库ID'" },
      { name: 'location_id', def: "location_id INT UNSIGNED DEFAULT NULL COMMENT '库位ID'" },
      {
        name: 'putaway_status',
        def: "putaway_status ENUM('pending', 'done') DEFAULT 'pending' COMMENT '上架状态'",
      },
    ];

    let itemUpdated = false;
    for (const col of itemColumns) {
      if (!(await columnExists('inv_inbound_item', col.name))) {
        await addColumnSafe('inv_inbound_item', col.def);
        itemUpdated = true;
      }
    }

    if (itemUpdated) {
      results.push('✅ 更新表: inv_inbound_item (添加PO关联字段)');
    } else {
      results.push('✓ 表已更新: inv_inbound_item');
    }

    // 插入测试数据
    const supplierCount = await query(
      `SELECT COUNT(*) as count FROM pur_supplier WHERE deleted = 0`
    );
    if ((supplierCount as Loose[])[0].count === 0) {
      await query(`
        INSERT INTO pur_supplier (supplier_code, supplier_name, supplier_type, contact_person, contact_phone, over_receipt_tolerance) VALUES
        ('SUP001', 'ABC造纸厂', 'material', '张经理', '13800138001', 5.00),
        ('SUP002', 'XYZ包装材料', 'material', '李经理', '13800138002', 10.00),
        ('SUP003', '3M中国', 'material', '王经理', '13800138003', 0.00)
      `);
      results.push('✅ 插入测试数据: 3个供应商');
    }

    const poCount = await query(
      `SELECT COUNT(*) as count FROM pur_purchase_order WHERE deleted = 0`
    );
    if ((poCount as Loose[])[0].count === 0) {
      // 创建测试采购单
      await query(`
        INSERT INTO pur_purchase_order 
        (po_no, supplier_id, supplier_name, supplier_code, order_date, delivery_date, 
         total_amount, total_quantity, status, over_receipt_tolerance, remark)
        SELECT 
          'PO20250101001',
          id,
          supplier_name,
          supplier_code,
          '2025-01-01',
          '2025-01-15',
          50000.00,
          1000,
          30,
          over_receipt_tolerance,
          '测试采购单'
        FROM pur_supplier WHERE supplier_code = 'SUP001'
      `);

      // 创建采购单行
      await query(`
        INSERT INTO pur_purchase_order_line 
        (po_id, line_no, material_code, material_name, material_spec, unit, order_qty, unit_price, amount, require_date)
        SELECT 
          id, 1, 'MAT001', '白色卷纸', '100M×1.5M, 80g', '卷', 500, 50.00, 25000.00, '2025-01-15'
        FROM pur_purchase_order WHERE po_no = 'PO20250101001'
      `);

      await query(`
        INSERT INTO pur_purchase_order_line 
        (po_id, line_no, material_code, material_name, material_spec, unit, order_qty, unit_price, amount, require_date)
        SELECT 
          id, 2, 'MAT002', '3M胶带', '3M7533, 50mm×50m', '卷', 1000, 25.00, 25000.00, '2025-01-15'
        FROM pur_purchase_order WHERE po_no = 'PO20250101001'
      `);

      results.push('✅ 插入测试数据: 1个采购单(2行)');
    }

    return successResponse({
      message: '采购单与入库单逻辑关系表初始化完成',
      details: results,
    });
  } catch (error) {
    return errorResponse(`初始化失败: ${(error as Error).message}`, 500, 500);
  }
}

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';

// 创建产品管理相关表
export async function GET(_request: NextRequest) {
  try {
    const results: string[] = [];

    // 检查表是否已存在
    const tables = await query(`
      SELECT TABLE_NAME 
      FROM information_schema.TABLES 
      WHERE TABLE_SCHEMA = DATABASE() 
      AND TABLE_NAME IN ('mdm_product', 'mdm_product_category', 'mdm_product_bom', 'mdm_product_route')
    `);

    const existingTables = (tables as Loose[]).map((t) => t.TABLE_NAME);

    // 1. 创建产品主表
    if (!existingTables.includes('mdm_product')) {
      await query(`
        CREATE TABLE IF NOT EXISTS mdm_product (
          id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT '主键ID',
          product_code VARCHAR(50) NOT NULL COMMENT '产品编码',
          product_name VARCHAR(100) NOT NULL COMMENT '产品名称',
          short_name VARCHAR(50) DEFAULT NULL COMMENT '产品简称',
          specification TEXT COMMENT '规格参数',
          unit VARCHAR(20) DEFAULT '件' COMMENT '单位',
          category_id INT UNSIGNED DEFAULT NULL COMMENT '产品分类ID',
          category_name VARCHAR(50) DEFAULT NULL COMMENT '产品分类名称',
          customer_id INT UNSIGNED DEFAULT NULL COMMENT '关联客户ID',
          customer_name VARCHAR(100) DEFAULT NULL COMMENT '关联客户名称',
          bom_version VARCHAR(20) DEFAULT 'V1.0' COMMENT 'BOM版本',
          description TEXT COMMENT '产品描述',
          status ENUM('active', 'inactive', 'discontinued') DEFAULT 'active' COMMENT '状态',
          cost_price DECIMAL(12,2) DEFAULT 0 COMMENT '成本价',
          sale_price DECIMAL(12,2) DEFAULT 0 COMMENT '销售价',
          min_stock DECIMAL(12,3) DEFAULT 0 COMMENT '最低库存',
          max_stock DECIMAL(12,3) DEFAULT 0 COMMENT '最高库存',
          safety_stock DECIMAL(12,3) DEFAULT 0 COMMENT '安全库存',
          create_by INT UNSIGNED DEFAULT NULL COMMENT '创建人ID',
          create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
          update_by INT UNSIGNED DEFAULT NULL COMMENT '更新人ID',
          update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
          deleted TINYINT(1) DEFAULT 0 COMMENT '是否删除',
          UNIQUE KEY uk_product_code (product_code),
          INDEX idx_category (category_id),
          INDEX idx_customer (customer_id),
          INDEX idx_status (status),
          INDEX idx_create_time (create_time)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='产品主表'
      `);
      results.push('✅ 创建表: mdm_product');
    } else {
      results.push('✓ 表已存在: mdm_product');
    }

    // 2. 创建产品分类表
    if (!existingTables.includes('mdm_product_category')) {
      await query(`
        CREATE TABLE IF NOT EXISTS mdm_product_category (
          id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT '主键ID',
          category_code VARCHAR(50) NOT NULL COMMENT '分类编码',
          category_name VARCHAR(100) NOT NULL COMMENT '分类名称',
          parent_id INT UNSIGNED DEFAULT 0 COMMENT '父分类ID',
          level TINYINT UNSIGNED DEFAULT 1 COMMENT '层级',
          sort_order INT DEFAULT 0 COMMENT '排序号',
          description TEXT COMMENT '分类描述',
          status TINYINT(1) DEFAULT 1 COMMENT '状态',
          create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
          update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
          deleted TINYINT(1) DEFAULT 0 COMMENT '是否删除',
          UNIQUE KEY uk_category_code (category_code),
          INDEX idx_parent (parent_id),
          INDEX idx_status (status)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='产品分类表'
      `);
      results.push('✅ 创建表: mdm_product_category');
    } else {
      results.push('✓ 表已存在: mdm_product_category');
    }

    // 3. 创建产品BOM表
    if (!existingTables.includes('mdm_product_bom')) {
      await query(`
        CREATE TABLE IF NOT EXISTS mdm_product_bom (
          id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT '主键ID',
          product_id INT UNSIGNED NOT NULL COMMENT '产品ID',
          version VARCHAR(20) DEFAULT 'V1.0' COMMENT 'BOM版本',
          material_id INT UNSIGNED NOT NULL COMMENT '物料ID',
          material_code VARCHAR(50) NOT NULL COMMENT '物料编码',
          material_name VARCHAR(100) NOT NULL COMMENT '物料名称',
          specification VARCHAR(200) DEFAULT NULL COMMENT '规格',
          unit VARCHAR(20) DEFAULT '件' COMMENT '单位',
          quantity DECIMAL(12,3) DEFAULT 1 COMMENT '用量',
          loss_rate DECIMAL(5,2) DEFAULT 0 COMMENT '损耗率(%)',
          sort_order INT DEFAULT 0 COMMENT '排序号',
          remark TEXT COMMENT '备注',
          is_key_material TINYINT(1) DEFAULT 0 COMMENT '是否关键物料',
          create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
          update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
          deleted TINYINT(1) DEFAULT 0 COMMENT '是否删除',
          INDEX idx_product (product_id),
          INDEX idx_version (version),
          INDEX idx_material (material_id)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='产品BOM表'
      `);
      results.push('✅ 创建表: mdm_product_bom');
    } else {
      results.push('✓ 表已存在: mdm_product_bom');
