        ('P005', '复合食品膜', '食品复合膜', '厚度0.15mm,多层复合,食品级', '㎡', 5, '复合膜', NULL, '通用', 'V1.5', '多层复合食品包装膜，高阻隔性', 'active', 5.00, 8.00, 800, 8000, 1500),
