import { NextRequest } from 'next/server';
import { transaction } from '@/lib/db';
import { successResponse } from '@/lib/api-response';

import { withPermission } from '@/lib/api-permissions';
export const POST = withPermission(async (_request: NextRequest) => {
  const result = await transaction(async (conn) => {
    const stats: Record<string, number> = {};

    const isEmpty = async (table: string): Promise<boolean> => {
      const [rows]: Loose = await conn.execute(`SELECT COUNT(*) as cnt FROM \`${table}\``);
      return rows[0].cnt === 0;
    };

    const [existingWarehouses]: Loose = await conn.execute(
      'SELECT id, warehouse_code, warehouse_name FROM inv_warehouse WHERE deleted = 0 OR deleted IS NULL LIMIT 10'
    );
    const [existingSuppliers]: Loose = await conn.execute(
      'SELECT id, supplier_code, supplier_name FROM pur_supplier LIMIT 10'
    );
    const [existingCustomers]: Loose = await conn.execute(
      'SELECT id, customer_code, customer_name FROM crm_customer LIMIT 10'
    );
    const [existingMaterials]: Loose = await conn.execute(
      'SELECT id, material_code, material_name, specification, unit, purchase_price, sale_price, material_type FROM inv_material LIMIT 20'
    );
    const [existingEquipment]: Loose = await conn.execute(
      'SELECT id, equipment_code, equipment_name FROM eqp_equipment LIMIT 10'
    );
    const [existingWorkOrders]: Loose = await conn.execute(
      'SELECT id, order_no FROM prod_work_order LIMIT 10'
    );
    const [_existingDieTemplates]: Loose = await conn.execute(
      'SELECT id, template_code, template_name FROM prd_die_template LIMIT 10'
    );
    const [_existingProcessRoutes]: Loose = await conn.execute(
      'SELECT id, route_code, route_name FROM prd_process_route LIMIT 10'
    );
    const [_existingBoms]: Loose = await conn.execute(
      'SELECT id, bom_name, product_id FROM prd_bom LIMIT 10'
    );
    const [_existingBomDetails]: Loose = await conn.execute(
      'SELECT id, bom_id, material_id FROM prd_bom_detail LIMIT 20'
    );
    const [existingBomLines]: Loose = await conn.execute(
      'SELECT id, bom_id, material_id, material_code, material_name FROM bom_line LIMIT 20'
    );
    const [existingProducts]: Loose = await conn.execute(
      'SELECT id, product_code, product_name FROM mdm_product LIMIT 10'
    );
    const [existingLocations]: Loose = await conn.execute(
      'SELECT id, location_code, location_name FROM inv_location LIMIT 10'
    );
    const [_existingUsers]: Loose = await conn.execute('SELECT id, username FROM sys_user LIMIT 10');
    const [existingVehicles]: Loose = await conn.execute(
      'SELECT id, vehicle_no FROM delivery_vehicle LIMIT 10'
    );

    const wh = existingWarehouses[0] || { id: 1 };
    const sup = existingSuppliers[0] || { id: 1, supplier_name: '默认供应商' };
    const cust = existingCustomers[0] || { id: 1, customer_name: '默认客户' };
    const mat = existingMaterials[0] || {
      id: 1,
      material_code: 'MAT001',
      material_name: '默认物料',
      specification: '默认规格',
      unit: '张',
    };
    const eq = existingEquipment[0] || {
      id: 1,
      equipment_code: 'EQP001',
      equipment_name: '默认设备',
    };
    const wo = existingWorkOrders[0] || { id: 1, order_no: 'WO001' };
    const prod = existingProducts[0] || { id: 1, product_code: 'PRD001', product_name: '默认产品' };

    // ===== base_ink =====
    if (await isEmpty('base_ink')) {
      for (let i = 1; i <= 10; i++) {
        const inkTypes = ['溶剂型', 'UV型', '水性', '导电型', '绝缘型'];
        const colors = [
          '黑色',
          '白色',
          '红色',
          '蓝色',
          '绿色',
          '黄色',
          '银色',
          '金色',
          '透明',
          '灰色',
        ];
        const s = existingSuppliers[(i - 1) % existingSuppliers.length] || sup;
        await conn.execute(
          `INSERT INTO base_ink (ink_code, ink_name, color_code, color_name, ink_type, supplier_id, supplier_name, specification, unit, unit_price, stock_qty, min_stock, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)`,
          [
            `INK00${i}`,
            `丝印油墨-${colors[i - 1]}`,
            `C${String(i).padStart(3, '0')}`,
            colors[i - 1],
            inkTypes[(i - 1) % inkTypes.length],
            s.id,
            s.supplier_name || `供应商${i}`,
            `SK-${1000 + i}`,
            'kg',
            80 + i * 10,
            50 + i * 5,
            10,
          ]
        );
      }
      stats.base_ink = 10;
    }

    // ===== bom_alternative =====
    if ((await isEmpty('bom_alternative')) && existingBomLines.length > 0) {
      for (let i = 1; i <= 10; i++) {
        const bl = existingBomLines[(i - 1) % existingBomLines.length];
        const altMat = existingMaterials[(i + 2) % existingMaterials.length] || mat;
        await conn.execute(
          `INSERT INTO bom_alternative (bom_id, bom_line_id, priority, material_id, material_code, material_name, conversion_rate, is_enabled) VALUES (?, ?, ?, ?, ?, ?, ?, 1)`,
          [
            bl.bom_id,
            bl.id,
            (i % 3) + 1,
            altMat.id,
            altMat.material_code,
            altMat.material_name,
            1.0,
          ]
        );
      }
      stats.bom_alternative = 10;
    }

    // ===== crm_customer_analysis =====
    if (await isEmpty('crm_customer_analysis')) {
      for (let i = 1; i <= 10; i++) {
        const c = existingCustomers[(i - 1) % existingCustomers.length] || cust;
        const levels = ['A', 'A', 'B', 'B', 'C', 'A', 'B', 'C', 'A', 'B'];
        await conn.execute(
          `INSERT INTO crm_customer_analysis (customer_id, customer_name, analysis_period, period_start, period_end, order_count, order_amount, delivery_count, return_count, complaint_count, on_time_rate, satisfaction_score, customer_level, growth_rate) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          [
            c.id,
            c.customer_name || `客户${i}`,
            '2026-Q1',
            '2026-01-01',
            '2026-03-31',
            5 + i,
            50000 + i * 10000,
            4 + i,
            i % 3,
            i % 4,
            90 + i * 0.5,
            4.0 + (i % 3) * 0.3,
            levels[i - 1],
            5 + i * 2,
          ]
        );
      }
      stats.crm_customer_analysis = 10;
    }

    // ===== crm_follow_record =====
    const followTypes = ['电话', '拜访', '邮件', '微信', '会议'];
    if (await isEmpty('crm_follow_record')) {
      for (let i = 1; i <= 10; i++) {
        const c = existingCustomers[(i - 1) % existingCustomers.length] || cust;
        await conn.execute(
          `INSERT INTO crm_follow_record (customer_id, customer_name, follow_type, follow_content, contact_name, salesman_name, next_follow_date, opportunity, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1)`,
          [
            c.id,
            c.customer_name || `客户${i}`,
            followTypes[(i - 1) % 5],
            `第${i}次跟进，讨论新项目合作方案`,
            `联系人${i}`,
            `销售员${String.fromCharCode(65 + (i % 5))}`,
            '2026-05-01',
            `新项目机会-${i}`,
          ]
        );
      }
      stats.crm_follow_record = 10;
    }

    // ===== delivery_vehicle_cost =====
    if ((await isEmpty('delivery_vehicle_cost')) && existingVehicles.length > 0) {
      for (let i = 1; i <= 10; i++) {
        const v = existingVehicles[(i - 1) % existingVehicles.length];
        const costTypes = ['加油', '过路费', '保险', '维修', '年检'];
        await conn.execute(
          `INSERT INTO delivery_vehicle_cost (vehicle_id, cost_date, cost_type, amount, mileage, fuel_volume, unit_price, location, operator) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          [
            v.id,
            `2026-04-${String(i).padStart(2, '0')}`,
            costTypes[(i - 1) % 5],
            200 + i * 50,
            1000 + i * 200,
            i % 2 === 0 ? 50 + i * 5 : null,
            i % 2 === 0 ? 7.5 : null,
