            wh.manager_id,
            wh.contact_phone,
            wh.status,
            wh.remark,
          ]
        );
      }
    });

    // 获取最终数据
    const finalData = await query<Warehouse>(`
    SELECT w.*, c.name as category_name
    FROM inv_warehouse w
    LEFT JOIN sys_warehouse_category c ON w.category_id = c.id
    WHERE w.deleted = 0
