import { withPermission } from '@/lib/api-permissions';
class InventoryError extends Error {
  type: 'notFound' | 'conflict' | 'insufficient';
  constructor(message: string, type: 'notFound' | 'conflict' | 'insufficient') {
    super(message);
    this.type = type;
  }
}

function handleInventoryError(error: unknown) {
  if (error instanceof InventoryError) {
    if (error.type === 'notFound') return commonErrors.notFound(error.message);
    return errorResponse(error.message, 409, 409);
  }
  throw error;
}

function calculateAlertLevel(availableQty: number, safetyStock?: number): string {
  if (availableQty <= 0) return 'critical';
  if (safetyStock && availableQty < safetyStock) return 'warning';
  if (availableQty < 10) return 'warning';
  return 'normal';
}

export const GET = withPermission(
  async (request: NextRequest) => {
    const { searchParams } = new URL(request.url);
    const warehouseId = searchParams.get('warehouseId');
    const status = searchParams.get('status');
    const keyword = searchParams.get('keyword');
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');

    let sql = `
    SELECT
      ib.id,
      ib.batch_no,
      ib.material_id,
      ib.material_name,
      m.specification as material_spec,
      m.material_code,
      ib.warehouse_id,
      ib.warehouse_name,
      ib.quantity,
      ib.available_qty,
      ib.locked_qty,
      ib.unit,
      ib.unit_price,
      ib.status,
      ib.produce_date,
      ib.expire_date,
      ib.inbound_date,
      ib.create_time,
      m.safety_stock
    FROM inv_inventory_batch ib
    LEFT JOIN inv_material m ON ib.material_id = m.id
    WHERE ib.deleted = 0
  `;
    const values: Loose[] = [];

    if (warehouseId && warehouseId !== 'all') {
      sql += ' AND ib.warehouse_id = ?';
      values.push(parseInt(warehouseId));
    }

    if (status && status !== 'all') {
      sql += ' AND ib.status = ?';
      values.push(status);
    }

    if (keyword) {
      sql += ' AND (ib.batch_no LIKE ? OR ib.material_name LIKE ? OR m.material_code LIKE ?)';
      const likeKeyword = `%${keyword}%`;
      values.push(likeKeyword, likeKeyword, likeKeyword);
    }

    let countSql = `SELECT COUNT(*) as total FROM inv_inventory_batch ib LEFT JOIN inv_material m ON ib.material_id = m.id WHERE ib.deleted = 0`;
    const countValues: Loose[] = [];

    if (warehouseId && warehouseId !== 'all') {
      countSql += ' AND ib.warehouse_id = ?';
      countValues.push(parseInt(warehouseId));
    }

    if (status && status !== 'all') {
      countSql += ' AND ib.status = ?';
      countValues.push(status);
    }

    if (keyword) {
      countSql += ' AND (ib.batch_no LIKE ? OR ib.material_name LIKE ? OR m.material_code LIKE ?)';
      const likeKeyword = `%${keyword}%`;
      countValues.push(likeKeyword, likeKeyword, likeKeyword);
    }

    const countResult = await query(countSql, countValues);
    const total = (countResult as Loose[])[0]?.total || 0;

    sql += ' ORDER BY ib.create_time DESC';
    sql += ' LIMIT ? OFFSET ?';
    values.push(pageSize, (page - 1) * pageSize);

    const data = await query(sql, values);

    const processedData = (data as Loose[]).map((item) => ({
      ...item,
      alertLevel: calculateAlertLevel(
        parseFloat(item.available_qty) || 0,
        item.safety_stock ? parseFloat(item.safety_stock) : undefined
      ),
    }));

    return successResponse({
      list: processedData,
      total,
      page,
      pageSize,
    });
  },
  { errorMessage: '获取库存列表失败' }
);

export const POST = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();
    const { action, batchNo, quantity, warehouseId, materialId, sourceType, sourceNo } = body;

    const validation = validateRequestBody(body, ['action', 'quantity']);
    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    if (action === 'inbound') {
      const inboundValidation = validateRequestBody(body, ['warehouseId', 'materialId']);
      if (!inboundValidation.valid) {
        return errorResponse(
          `入库操作缺少必填字段: ${inboundValidation.missing.join(', ')}`,
          400,
          400
        );
      }

      const material = await queryOne<Loose>(
        'SELECT id, material_name, material_code, unit, purchase_price FROM inv_material WHERE id = ? AND deleted = 0',
        [materialId]
      );
      if (!material) {
        return commonErrors.notFound('物料不存在');
      }

      const warehouse = await queryOne<Loose>(
        'SELECT id, warehouse_name FROM inv_warehouse WHERE id = ? AND deleted = 0',
        [warehouseId]
      );
      if (!warehouse) {
        return commonErrors.notFound('仓库不存在');
      }

      const batchNoNew = generateBatchNo('B');
      const transNo = generateTransNo('IN');

      const batchId = await transaction(async (conn) => {
        await conn.execute(
          `INSERT INTO inv_inventory_batch (batch_no, material_id, material_name, warehouse_id, warehouse_name, quantity, available_qty, locked_qty, unit, unit_price, inbound_date, status, create_time)
         VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, ?, CURDATE(), 'normal', NOW())`,
          [
            batchNoNew,
            materialId,
            material.material_name,
            warehouseId,
            warehouse.warehouse_name,
            quantity,
            quantity,
            material.unit || '个',
            material.purchase_price || 0,
          ]
        );

        const [idRows]: Loose = await conn.execute('SELECT LAST_INSERT_ID() as id');
        const newBatchId = idRows[0].id;

        await conn.execute(
          `INSERT INTO inv_inventory_transaction (trans_no, trans_type, source_type, material_id, material_code, batch_no, warehouse_id, quantity, unit_cost, total_cost, remark, create_time)
         VALUES (?, 'in', ?, ?, ?, ?, ?, ?, ?, ?, '入库操作', NOW())`,
          [
            transNo,
            sourceType || 'manual',
            materialId,
            material.material_code,
            batchNoNew,
            warehouseId,
            quantity,
            material.purchase_price || 0,
            quantity * (material.purchase_price || 0),
          ]
        );

        await conn.execute(
          `INSERT INTO inv_inventory_log (warehouse_id, material_id, batch_no, trans_type, quantity, before_qty, after_qty, unit, source_type, source_no, create_time)
         VALUES (?, ?, ?, 'in', ?, 0, ?, ?, ?, ?, NOW())`,
          [
            warehouseId,
            materialId,
            batchNoNew,
            quantity,
            quantity,
            material.unit || '个',
            sourceType || 'manual',
            sourceNo || transNo,
          ]
        );

        return newBatchId;
      });

      await logOperation({
        title: '库存入库',
        oper_type: 'inventory',
        oper_method: 'POST',
        oper_url: '/api/inventory',
        oper_param: JSON.stringify({
          action: 'inbound',
          batchNo: batchNoNew,
          quantity,
          warehouseId,
          materialId,
        }),
        oper_result: '入库成功',
        status: 1,
      });

      return successResponse(
        {
          transNo,
          batchNo: batchNoNew,
          batchId,
          quantity,
          warehouseId,
          materialId,
        },
        '入库成功'
      );
    } else if (action === 'outbound') {
      const outboundValidation = validateRequestBody(body, ['quantity']);
      if (!outboundValidation.valid) {
        return errorResponse(
          `出库操作缺少必填字段: ${outboundValidation.missing.join(', ')}`,
          400,
          400
        );
      }

      if (quantity <= 0) {
        return errorResponse('出库数量必须大于0', 400, 400);
      }

      const transNo = generateTransNo('OUT');

      try {
        if (batchNo) {
          const specifiedBatchValidation = validateRequestBody(body, ['batchNo']);
          if (!specifiedBatchValidation.valid) {
            return errorResponse(
              `指定批次出库缺少必填字段: ${specifiedBatchValidation.missing.join(', ')}`,
              400,
              400
            );
          }

          const result = await transaction(async (conn) => {
            const [batchRows]: Loose = await conn.execute(
              'SELECT id, batch_no, material_id, material_name, warehouse_id, available_qty, quantity, unit, unit_price, version FROM inv_inventory_batch WHERE batch_no = ? AND deleted = 0 FOR UPDATE',
              [batchNo]
            );

            if (!batchRows || batchRows.length === 0) {
              throw new InventoryError('库存批次不存在', 'notFound');
            }

            const batch = batchRows[0];

            if (parseFloat(batch.available_qty) < quantity) {
              throw new InventoryError('可用库存不足', 'insufficient');
            }

            const [fifoBatches]: Loose = await conn.query(
              `SELECT id, batch_no FROM inv_inventory_batch
             WHERE material_id = ? AND warehouse_id = ? AND available_qty > 0 AND deleted = 0 AND status = 'normal'
             ORDER BY
               CASE
                 WHEN expire_date IS NOT NULL AND DATEDIFF(expire_date, CURDATE()) <= 30 THEN 0
                 WHEN expire_date IS NOT NULL AND DATEDIFF(expire_date, CURDATE()) <= 60 THEN 1
                 ELSE 2
               END,
               inbound_date ASC, expire_date ASC, id ASC
             LIMIT 1`,
              [batch.material_id, batch.warehouse_id]
            );

            const isFifoRecommended = fifoBatches.length > 0 && fifoBatches[0].batch_no === batchNo;

            const newAvailableQty = parseFloat(batch.available_qty) - quantity;
            const newQuantity = parseFloat(batch.quantity) - quantity;

            const [updateResult]: Loose = await conn.execute(
              'UPDATE inv_inventory_batch SET available_qty = ?, quantity = ?, version = version + 1, update_time = NOW() WHERE id = ? AND version = ? AND deleted = 0',
              [newAvailableQty, newQuantity, batch.id, batch.version]
            );

            if (updateResult.affectedRows === 0) {
              throw new InventoryError('库存已被修改，请重试', 'conflict');
            }

            await conn.execute(
              `INSERT INTO inv_inventory_transaction (trans_no, trans_type, source_type, material_id, batch_no, warehouse_id, quantity, unit_cost, total_cost, remark, create_time)
             VALUES (?, 'out', ?, ?, ?, ?, ?, ?, ?, ?, NOW())`,
              [
                transNo,
                sourceType || 'manual',
                batch.material_id,
                batchNo,
                batch.warehouse_id,
                quantity,
                batch.unit_price,
                quantity * parseFloat(batch.unit_price || 0),
                isFifoRecommended ? '指定批次出库(FIFO推荐)' : '指定批次出库(非FIFO推荐-手动覆盖)',
              ]
            );

            await conn.execute(
              `INSERT INTO inv_inventory_log (warehouse_id, material_id, batch_no, trans_type, quantity, before_qty, after_qty, unit, source_type, source_no, create_time)
             VALUES (?, ?, ?, 'out', ?, ?, ?, ?, ?, ?, NOW())`,
              [
                batch.warehouse_id,
                batch.material_id,
                batchNo,
                quantity,
                batch.available_qty,
                newAvailableQty,
                batch.unit,
                sourceType || 'manual',
                sourceNo || transNo,
              ]
            );

            try {
              await conn.execute(
                `INSERT INTO inv_outbound_batch_allocation (
                source_type, source_id, source_no, warehouse_id,
                material_id, batch_id, batch_no, allocated_qty, unit_cost, total_cost,
                fifo_mode, operator_id, operator_name
              ) VALUES ('inventory_out', 0, ?, ?, ?, ?, ?, ?, ?, ?, 'specified_batch', NULL, NULL)`,
                [
                  transNo,
                  batch.warehouse_id,
                  batch.material_id,
                  batch.id,
                  batchNo,
                  quantity,
                  parseFloat(batch.unit_price) || 0,
                  quantity * (parseFloat(batch.unit_price) || 0),
                ]
              );
            } catch {}

            return { batchNo, quantity, batch, isFifoRecommended };
          });

          await logOperation({
            title: '库存出库-指定批次',
            oper_type: 'inventory',
            oper_method: 'POST',
            oper_url: '/api/inventory',
            oper_param: JSON.stringify({
              action: 'outbound',
              batchNo,
              quantity,
              fifoRecommended: result.isFifoRecommended,
            }),
            oper_result: result.isFifoRecommended
              ? '指定批次出库成功(FIFO推荐批次)'
              : '指定批次出库成功(非FIFO推荐批次-手动覆盖)',
            status: 1,
          });

          return successResponse(
            {
              transNo,
              batchNo: result.batchNo,
              quantity,
              fifoRecommended: result.isFifoRecommended,
              warning: result.isFifoRecommended
                ? undefined
                : '当前出库批次不是FIFO推荐批次，存在过期物料风险',
              operatedAt: new Date().toISOString(),
            },
            '出库成功'
          );
        } else {
          const fifoValidation = validateRequestBody(body, ['materialId', 'warehouseId']);
          if (!fifoValidation.valid) {
            return errorResponse(
              `FIFO出库缺少必填字段: ${fifoValidation.missing.join(', ')}，或指定batchNo`,
              400,
              400
            );
          }

          const material = await queryOne<Loose>(
            'SELECT id, material_name, material_code, unit FROM inv_material WHERE id = ? AND deleted = 0',
            [materialId]
          );
          if (!material) {
            return commonErrors.notFound('物料不存在');
          }

          const warehouse = await queryOne<Loose>(
            'SELECT id, warehouse_name, warehouse_code FROM inv_warehouse WHERE id = ? AND deleted = 0',
            [warehouseId]
          );
          if (!warehouse) {
            return commonErrors.notFound('仓库不存在');
          }

          const result = await transaction(async (conn) => {
            const allocation = await allocateFIFO(conn, materialId, warehouseId, quantity);

            if (allocation.shortage > 0) {
              throw new InventoryError(
                `物料 ${material.material_name} 库存不足: 需要 ${quantity}, 可用 ${allocation.total_available}, 缺少 ${allocation.shortage}`,
                'insufficient'
              );
            }

            const { deductionDetails, totalCost } = await executeFIFODeductionWithRetry(
              conn,
              allocation,
              {
                sourceType: 'inventory_out',
                sourceId: 0,
                sourceNo: transNo,
                warehouseId,
                warehouseCode: warehouse.warehouse_code || '',
                operatorId: null,
                operatorName: null,
              }
            );

            for (const detail of deductionDetails) {
              await conn.execute(
                `INSERT INTO inv_inventory_log (warehouse_id, material_id, batch_no, trans_type, quantity, before_qty, after_qty, unit, source_type, source_no, create_time)
               VALUES (?, ?, ?, 'out', ?, ?, ?, ?, ?, ?, NOW())`,
                [
                  warehouseId,
                  materialId,
                  detail.batch_no,
                  detail.deducted_qty,
                  detail.available_qty_before || 0,
                  (detail.available_qty_before || 0) - detail.deducted_qty,
                  material.unit || '个',
                  sourceType || 'fifo',
                  sourceNo || transNo,
                ]
              );
            }

            return { allocation, deductionDetails, totalCost };
          });

          await logOperation({
            title: '库存出库-FIFO',
            oper_type: 'inventory',
            oper_method: 'POST',
            oper_url: '/api/inventory',
            oper_param: JSON.stringify({
              action: 'outbound',
              materialId,
              warehouseId,
              quantity,
              fifoMode: true,
            }),
            oper_result: `FIFO出库成功，扣减${result.deductionDetails.length}个批次，总成本${result.totalCost.toFixed(2)}`,
            status: 1,
          });

          return successResponse(
            {
              transNo,
              materialId,
              warehouseId,
              quantity,
              allocatedQty: result.allocation.allocated_qty,
              fifoMode: true,
              batchDetails: result.deductionDetails.map((d: Loose) => ({
                batchNo: d.batch_no,
                deductedQty: d.deducted_qty,
                unitCost: d.unit_cost,
                lineCost: d.line_cost,
              })),
              totalCost: result.totalCost,
              operatedAt: new Date().toISOString(),
            },
            'FIFO出库成功'
          );
        }
      } catch (error) {
        return handleInventoryError(error);
      }
    } else if (action === 'transfer') {
      const transferValidation = validateRequestBody(body, ['batchNo', 'warehouseId']);
      if (!transferValidation.valid) {
        return errorResponse(
          `调拨操作缺少必填字段: ${transferValidation.missing.join(', ')}`,
          400,
          400
        );
      }

      const transNo = generateTransNo('TRF');

      try {
        const result = await transaction(async (conn) => {
          const [batchRows]: Loose = await conn.execute(
            'SELECT id, batch_no, material_id, material_name, warehouse_id, warehouse_name, available_qty, quantity, unit, unit_price, version FROM inv_inventory_batch WHERE batch_no = ? AND deleted = 0 FOR UPDATE',
            [batchNo]
          );

          if (!batchRows || batchRows.length === 0) {
            throw new InventoryError('库存批次不存在', 'notFound');
          }

          const batch = batchRows[0];

          const [warehouseRows]: Loose = await conn.execute(
            'SELECT id, warehouse_name FROM inv_warehouse WHERE id = ? AND deleted = 0 FOR UPDATE',
            [warehouseId]
          );

          if (!warehouseRows || warehouseRows.length === 0) {
            throw new InventoryError('目标仓库不存在', 'notFound');
          }

          const targetWarehouse = warehouseRows[0];
          const fromWarehouseId = batch.warehouse_id;
          const fromWarehouseName = batch.warehouse_name;

          const [updateResult]: Loose = await conn.execute(
            'UPDATE inv_inventory_batch SET warehouse_id = ?, warehouse_name = ?, version = version + 1, update_time = NOW() WHERE id = ? AND version = ? AND deleted = 0',
            [warehouseId, targetWarehouse.warehouse_name, batch.id, batch.version]
          );

          if (updateResult.affectedRows === 0) {
            throw new InventoryError('库存已被修改，请重试', 'conflict');
          }

          await conn.execute(
            `INSERT INTO inv_inventory_transaction (trans_no, trans_type, source_type, material_id, batch_no, warehouse_id, quantity, unit_cost, total_cost, remark, create_time)
           VALUES (?, 'transfer', ?, ?, ?, ?, ?, ?, ?, '调拨操作', NOW())`,
            [
              transNo,
              sourceType || 'manual',
              batch.material_id,
              batchNo,
              warehouseId,
              batch.quantity,
              batch.unit_price,
              parseFloat(batch.quantity) * parseFloat(batch.unit_price || 0),
            ]
          );

          await conn.execute(
            `INSERT INTO inv_inventory_log (warehouse_id, material_id, batch_no, trans_type, quantity, before_qty, after_qty, unit, source_type, source_no, create_time)
           VALUES (?, ?, ?, 'transfer', ?, ?, ?, ?, ?, ?, NOW())`,
            [
              fromWarehouseId,
              batch.material_id,
              batchNo,
              batch.quantity,
              batch.available_qty,
              batch.available_qty,
              batch.unit,
              sourceType || 'manual',
              sourceNo || transNo,
            ]
          );

          return {
            batchNo,
            quantity,
            fromWarehouseId,
            fromWarehouseName,
            toWarehouseId: warehouseId,
            toWarehouseName: targetWarehouse.warehouse_name,
          };
        });

        await logOperation({
          title: '库存调拨',
          oper_type: 'inventory',
          oper_method: 'POST',
          oper_url: '/api/inventory',
          oper_param: JSON.stringify({ action: 'transfer', batchNo, quantity, warehouseId }),
          oper_result: '调拨成功',
          status: 1,
        });

        return successResponse(result, '调拨成功');
      } catch (error) {
        return handleInventoryError(error);
      }
    }

    return commonErrors.badRequest('未知操作类型');
  },
  { errorMessage: '库存操作失败' }
);

﻿import { NextRequest } from 'next/server';
import { query, transaction } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';

import { withPermission } from '@/lib/api-permissions';
// 状态常量定义
const BIZ_ORDER_STATUS = {
  DRAFT: 10,
  CONFIRMED: 20,
  PART_PO: 30,
  PO_COMPLETE: 40,
  PART_RECEIVE: 50,
  COMPLETED: 60,
  CLOSED: 90,
} as const;

const _PR_STATUS = {
  DRAFT: 10,
  PENDING_APPROVAL: 20,
  APPROVED: 30,
  PART_PO: 40,
  PO_COMPLETE: 50,
  CANCELLED: 90,
} as const;

const _PO_STATUS = {
  DRAFT: 10,
  PENDING_APPROVAL: 20,
  APPROVED: 30,
  PART_RECEIVE: 40,
  COMPLETED: 50,
  CLOSED: 90,
} as const;

/**
 * 获取容差配置
 */
async function getToleranceConfig(materialId?: number, orderType: string = 'PURCHASE') {
  const config = await query(
    `SELECT over_delivery_tolerance, under_delivery_tolerance, action_on_exceed
     FROM order_tolerance_config
     WHERE (material_id = ? OR (material_id IS NULL AND is_default = 1))
     AND order_type = ?
     ORDER BY material_id IS NULL ASC
     LIMIT 1`,
    [materialId || null, orderType]
  );

  if ((config as Loose[]).length === 0) {
    return {
      over_delivery_tolerance: 5.0,
      under_delivery_tolerance: 5.0,
      action_on_exceed: 'WARNING',
    };
  }

  const c = (config as Loose[])[0];
  return {
    over_delivery_tolerance: c.over_delivery_tolerance,
    under_delivery_tolerance: c.under_delivery_tolerance,
    action_on_exceed: c.action_on_exceed,
  };
}

/**
 * 记录状态变更历史
 */
async function recordStatusHistory(
  orderType: string,
  orderId: number,
  orderNo: string,
  oldStatus: number,
  newStatus: number,
  triggerBy: string,
  operatorId?: number
) {
  await query(
    `INSERT INTO order_status_history 
     (order_type, order_id, order_no, old_status, new_status, trigger_by, operator_id, operate_time)
     VALUES (?, ?, ?, ?, ?, ?, ?, NOW())`,
    [orderType, orderId, orderNo, oldStatus, newStatus, triggerBy, operatorId]
  );
}

/**
 * 更新业务订单状态（根据勾稽数量）
 */
async function updateBizOrderStatus(orderId: number, triggerBy: string) {
  const order = await query(
    `SELECT id, order_no, status, req_qty, tolerance_percent
     FROM biz_order_header WHERE id = ? AND deleted = 0`,
    [orderId]
  );

  if ((order as Loose[]).length === 0) return;

  const orderData = (order as Loose[])[0];
  const oldStatus = orderData.status;

  // 计算汇总指标
  const lines = await query(
    `SELECT 
       SUM(req_qty) as total_req,
       SUM(ordered_qty) as total_ordered,
       SUM(received_qty) as total_received,
       SUM(consumed_qty) as total_consumed
     FROM biz_order_line WHERE order_id = ? AND deleted = 0`,
    [orderId]
  );

  const summary = (lines as Loose[])[0];
  const totalReq = summary.total_req || 0;
  const totalOrdered = summary.total_ordered || 0;
  const totalReceived = summary.total_received || 0;
  const totalConsumed = summary.total_consumed || 0;

  // 容差计算
  const tolerance = orderData.tolerance_percent || 5;
  const _maxReq = totalReq * (1 + tolerance / 100);

  let newStatus = oldStatus;

  // 状态推导逻辑
  if (totalConsumed >= totalReq) {
    newStatus = BIZ_ORDER_STATUS.COMPLETED;
  } else if (totalReceived > 0) {
    newStatus = BIZ_ORDER_STATUS.PART_RECEIVE;
  } else if (totalOrdered >= totalReq) {
    newStatus = BIZ_ORDER_STATUS.PO_COMPLETE;
  } else if (totalOrdered > 0) {
    newStatus = BIZ_ORDER_STATUS.PART_PO;
  }

  // 只允许向前推进（状态值增大）
  if (newStatus > oldStatus) {
    await query(`UPDATE biz_order_header SET status = ?, update_time = NOW() WHERE id = ?`, [
      newStatus,
      orderId,
    ]);

    await recordStatusHistory('BIZ', orderId, orderData.order_no, oldStatus, newStatus, triggerBy);

    return { orderId, oldStatus, newStatus, changed: true };
  }

  return { orderId, oldStatus, newStatus, changed: false };
}

/**
 * 创建PO时的数量勾稽校验
 * POST /api/linkage/validate/po-create
 */
export const POST = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();
    const { sourceOrderLineId, poQty, materialId } = body;

    if (!sourceOrderLineId || !poQty) {
      return errorResponse('缺少必要参数', 400, 400);
    }

    return await transaction(async (connection) => {
      // 1. 查询业务订单行信息（加锁）
      const [orderLineRows] = await connection.execute(
        `SELECT 
        bol.id, bol.order_id, bol.req_qty, bol.ordered_qty, 
        bol.is_strict_by_order, bol.closed_flag,
        boh.order_no, boh.status, boh.tolerance_percent
       FROM biz_order_line bol
       JOIN biz_order_header boh ON bol.order_id = boh.id
       WHERE bol.id = ? AND bol.deleted = 0 AND boh.deleted = 0
       FOR UPDATE`,
        [sourceOrderLineId]
      );

      const orderLine = (orderLineRows as Loose[])[0];
      if (!orderLine) {
        throw new Error('来源业务订单行不存在');
      }

      // 2. 检查业务订单状态
      if (orderLine.status < BIZ_ORDER_STATUS.CONFIRMED) {
        throw new Error('业务订单未确认，不允许创建采购订单');
      }

      if (orderLine.status >= BIZ_ORDER_STATUS.CLOSED) {
        throw new Error('业务订单已关闭');
      }

      if (orderLine.closed_flag) {
        throw new Error('业务订单行已关闭');
      }

      // 3. 计算剩余可采购数量
      const tolerance = orderLine.tolerance_percent || 5;
      const maxQty = orderLine.req_qty * (1 + tolerance / 100);
      const remainingQty = maxQty - orderLine.ordered_qty;

      // 4. 容差校验
      if (poQty > remainingQty) {
        const config = await getToleranceConfig(materialId);

        if (config.action_on_exceed === 'BLOCK') {
          throw new Error(
            `超量采购：申请数量${poQty}，剩余可采购${remainingQty.toFixed(2)}（含容差${tolerance}%）`
          );
        } else if (config.action_on_exceed === 'WARNING') {
          return successResponse(
            {
              valid: true,
              warning: true,
              message: `警告：申请数量${poQty}超过剩余可采购${remainingQty.toFixed(2)}`,
              max_allowed: remainingQty,
              req_qty: orderLine.req_qty,
              ordered_qty: orderLine.ordered_qty,
              tolerance,
            },
            '校验通过（有警告）'
          );
        }
      }

      return successResponse(
        {
          valid: true,
          warning: false,
          max_allowed: remainingQty,
          req_qty: orderLine.req_qty,
          ordered_qty: orderLine.ordered_qty,
          tolerance,
        },
        '校验通过'
      );
    });
  },
  { errorMessage: 'PO创建校验失败' }
);

/**
 * PO审批通过后反写业务订单
 * PUT /api/linkage/validate/po-approved
 */
export const PUT = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();
    const { poId, action } = body;

    if (!poId || !action) {
      return errorResponse('缺少必要参数', 400, 400);
    }

    return await transaction(async (connection) => {
      if (action === 'po_approved') {
        // PO审批通过，反写业务订单已订购数量
        const [poLines] = await connection.execute(
          `SELECT 
           id, source_order_id, source_order_line_id, order_qty
         FROM pur_purchase_order_line
         WHERE po_id = ? AND source_order_line_id IS NOT NULL`,
          [poId]
        );

        const updatedOrders = new Set<number>();

        for (const poLine of poLines as Loose[]) {
          // 更新业务订单行已订购数量
          await connection.execute(
            `UPDATE biz_order_line 
           SET ordered_qty = ordered_qty + ?,
               update_time = NOW()
           WHERE id = ?`,
            [poLine.order_qty, poLine.source_order_line_id]
          );

          updatedOrders.add(poLine.source_order_id);
        }

        // 更新业务订单状态
        const statusResults = [];
        for (const orderId of updatedOrders) {
          const result = await updateBizOrderStatus(orderId, 'PO_APPROVED');
          statusResults.push(result);
        }

        return successResponse(
          { updated_orders: Array.from(updatedOrders), status_results: statusResults },
          'PO审批通过，业务订单已更新'
        );
      }

      if (action === 'grn_posted') {
        const { grnId } = body;

        // 入库过账，更新业务订单收货数量
        const [grnItems] = await connection.execute(
          `SELECT 
           id, source_order_id, source_order_line_id, quantity
         FROM inv_inbound_item
         WHERE order_id = ? AND source_order_line_id IS NOT NULL`,
          [grnId]
        );

        const updatedOrders = new Set<number>();

        for (const item of grnItems as Loose[]) {
          // 更新业务订单行已收货数量
          await connection.execute(
            `UPDATE biz_order_line 
           SET received_qty = received_qty + ?,
               available_to_receive = available_to_receive + ?,
               update_time = NOW()
           WHERE id = ?`,
            [item.quantity, item.quantity, item.source_order_line_id]
          );

          // 更新采购单行已收货数量
          await connection.execute(
            `UPDATE pur_purchase_order_line 
           SET received_qty = received_qty + ?,
               update_time = NOW()
           WHERE id = (SELECT po_line_id FROM inv_inbound_item WHERE id = ?)`,
            [item.quantity, item.id]
          );

          updatedOrders.add(item.source_order_id);
        }

        // 更新业务订单状态
        const statusResults = [];
        for (const orderId of updatedOrders) {
          const result = await updateBizOrderStatus(orderId, 'GRN_POSTED');
          statusResults.push(result);
        }

        return successResponse(
          { updated_orders: Array.from(updatedOrders), status_results: statusResults },
          '入库过账成功，业务订单已更新'
        );
      }

      if (action === 'consumption') {
        const { orderLineId, qty, consumptionType, grnLineId } = body;

        // 消耗/扣减勾稽
        const [orderLineRows] = await connection.execute(
          `SELECT 
           bol.id, bol.order_id, bol.material_id, bol.material_code,
           bol.available_to_receive, bol.is_strict_by_order,
           boh.order_no
         FROM biz_order_line bol
         JOIN biz_order_header boh ON bol.order_id = boh.id
         WHERE bol.id = ? FOR UPDATE`,
          [orderLineId]
        );

        const orderLine = (orderLineRows as Loose[])[0];
        if (!orderLine) {
          throw new Error('业务订单行不存在');
        }

        // 严格按单采购的物料，检查专用库存
        if (orderLine.is_strict_by_order) {
          if (qty > orderLine.available_to_receive) {
            throw new Error(
              `物料${orderLine.material_code}为按单采购，专用库存${orderLine.available_to_receive}不足，需求${qty}`
            );
          }
        }

        // 扣减可用库存并记录消耗
        await connection.execute(
          `UPDATE biz_order_line 
         SET consumed_qty = consumed_qty + ?,
             available_to_receive = available_to_receive - ?,
             update_time = NOW()
         WHERE id = ?`,
          [qty, qty, orderLineId]
        );

        // 记录消耗关系
        await connection.execute(
          `INSERT INTO biz_consumption 
         (order_id, order_line_id, material_id, material_code, consumption_type, 
          consumption_qty, source_grn_line_id, create_time)
         VALUES (?, ?, ?, ?, ?, ?, ?, NOW())`,
          [
            orderLine.order_id,
            orderLineId,
            orderLine.material_id,
            orderLine.material_code,
            consumptionType,
            qty,
            grnLineId,
          ]
        );

        // 更新入库行消耗标记
        if (grnLineId) {
          await connection.execute(`UPDATE inv_inbound_item SET is_consumed = 1 WHERE id = ?`, [
            grnLineId,
          ]);
        }

        // 更新业务订单状态
        const result = await updateBizOrderStatus(orderLine.order_id, 'CONSUMPTION');

        return successResponse(
          { order_line_id: orderLineId, consumed_qty: qty, status_result: result },
          '消耗记录成功'
        );
      }

      return errorResponse('无效的操作类型', 400, 400);
    });
  },
  { errorMessage: '勾稽处理失败' }
);

/**
 * 获取业务订单履行跟踪
 * GET /api/linkage/validate?orderId={id}
 */
export const GET = withPermission(
  async (request: NextRequest) => {
    const { searchParams } = new URL(request.url);
    const orderId = searchParams.get('orderId');

    if (!orderId) {
      return errorResponse('业务订单ID不能为空', 400, 400);
    }

    // 查询业务订单信息
    const order = await query(
      `SELECT 
       id, order_no, order_type, customer_name, product_name,
       status, req_qty, delivery_date, tolerance_percent
     FROM biz_order_header
     WHERE id = ? AND deleted = 0`,
      [orderId]
    );

    if ((order as Loose[]).length === 0) {
      return errorResponse('业务订单不存在', 404, 404);
    }

    const orderData = (order as Loose[])[0];

    // 计算行级别汇总
    const lines = await query(
      `SELECT 
       SUM(req_qty) as total_req,
       SUM(ordered_qty) as total_ordered,
       SUM(received_qty) as total_received,
       SUM(consumed_qty) as total_consumed
     FROM biz_order_line WHERE order_id = ? AND deleted = 0`,
      [orderId]
    );

    const lineSummary = (lines as Loose[])[0];
    const totalReq = lineSummary.total_req || 0;
    const totalOrdered = lineSummary.total_ordered || 0;
    const totalReceived = lineSummary.total_received || 0;
    const totalConsumed = lineSummary.total_consumed || 0;

    // 计算差异
    const diffOrdered = totalOrdered - totalReq;
    const diffReceived = totalReceived - totalReq;
    const fulfillmentRate = totalReq > 0 ? ((totalConsumed / totalReq) * 100).toFixed(2) : 0;

    // 查询关联的PO信息
    const linkedPOs = await query(
      `SELECT 
       po.id, po.po_no, po.supplier_name, po.status,
       po.total_quantity, po.total_amount,
       pol.line_no, pol.material_code, pol.material_name,
       pol.order_qty, pol.received_qty, pol.unit_price
     FROM pur_purchase_order po
     JOIN pur_purchase_order_line pol ON po.id = pol.po_id
     WHERE pol.source_order_id = ? AND po.deleted = 0
     ORDER BY po.create_time DESC`,
      [orderId]
    );

    // 查询关联的入库信息
    const linkedGRNs = await query(
      `SELECT 
       io.id, io.order_no as grnNo, io.status, io.inbound_date,
       iio.material_name, iio.quantity, iio.batch_no,
       iio.is_consumed
     FROM inv_inbound_order io
     JOIN inv_inbound_item iio ON io.id = iio.order_id
     WHERE iio.source_order_id = ? AND io.deleted = 0
     ORDER BY io.inbound_date DESC`,
      [orderId]
    );

    // 查询状态变更历史
    const statusHistory = await query(
      `SELECT 
       old_status, new_status, trigger_by, operate_time
     FROM order_status_history
     WHERE order_type = 'BIZ' AND order_id = ?
     ORDER BY operate_time DESC`,
      [orderId]
    );

    return successResponse({
      order: orderData,
      summary: {
        req_qty: totalReq,
        ordered_qty: totalOrdered,
        received_qty: totalReceived,
        consumed_qty: totalConsumed,
        diff_ordered: diffOrdered,
        diff_received: diffReceived,
        fulfillment_rate: `${fulfillmentRate}%`,
      },
      linked_pos: linkedPOs,
      linked_grns: linkedGRNs,
      status_history: statusHistory,
    });
  },
  { errorMessage: '获取履行跟踪失败' }
);

﻿import { query, execute } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import type { NextRequest } from 'next/server';

import { withPermission } from '@/lib/api-permissions';
function generateLabelNo(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  const random = String(Math.floor(Math.random() * 10000)).padStart(4, '0');
  return `LBL-${year}${month}${day}-${random}`;
}

export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');
  const labelNo = searchParams.get('labelNo');
  const materialCode = searchParams.get('materialCode');
  const batchNo = searchParams.get('batchNo');
  const isCut = searchParams.get('isCut');

  if (id) {
    const rows = await query(
      `
      SELECT ml.*, w.warehouse_name, l.location_name
      FROM inv_material_label ml
      LEFT JOIN inv_warehouse w ON ml.warehouse_id = w.id
      LEFT JOIN inv_location l ON ml.location_id = l.id
      WHERE ml.id = ? AND ml.deleted = 0
    `,
      [id]
    );
    return successResponse((rows as Loose[])[0], '标签详情');
  }

  if (labelNo) {
    const rows = await query(
      `
      SELECT ml.*, w.warehouse_name, l.location_name
      FROM inv_material_label ml
      LEFT JOIN inv_warehouse w ON ml.warehouse_id = w.id
      LEFT JOIN inv_location l ON ml.location_id = l.id
      WHERE ml.label_no = ? AND ml.deleted = 0
    `,
      [labelNo]
    );
    return successResponse((rows as Loose[])[0], '标签详情');
  }

  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '20');
  const offset = (page - 1) * pageSize;

  let whereClause = 'ml.deleted = 0';
  const params: Loose[] = [];

  if (materialCode) {
    whereClause += ' AND ml.material_code = ?';
    params.push(materialCode);
  }
  if (batchNo) {
    whereClause += ' AND ml.batch_no = ?';
    params.push(batchNo);
  }
  if (isCut !== undefined) {
    whereClause += ' AND ml.is_cut = ?';
    params.push(isCut === 'true' ? 1 : 0);
  }

  const warehouseId = searchParams.get('warehouseId');
  if (warehouseId) {
    whereClause += ' AND ml.warehouse_id = ?';
    params.push(warehouseId);
  }

  const [rows, countResult] = await Promise.all([
    query(
      `
      SELECT ml.*, w.warehouse_name, l.location_name
      FROM inv_material_label ml
      LEFT JOIN inv_warehouse w ON ml.warehouse_id = w.id
      LEFT JOIN inv_location l ON ml.location_id = l.id
      WHERE ${whereClause}
      ORDER BY ml.create_time DESC
      LIMIT ? OFFSET ?
    `,
      [...params, pageSize, offset]
    ),
    query(`SELECT COUNT(*) as total FROM inv_material_label ml WHERE ${whereClause}`, params),
  ]);

  return successResponse(
    {
      list: rows,
      total: (countResult as Loose[])[0].total,
      page,
      pageSize,
    },
    '标签列表'
  );
});

export const POST = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { type } = body;

  if (type === 'cut') {
    return handleCut(body);
  }

  const {
    materialCode,
    materialName,
    specification,
    unit,
    batchNo,
    quantity,
    packageQty,
    width,
    lengthPerRoll,
    colorCode,
    mixRemark,
    warehouseId,
    locationId,
    isMainMaterial,
    remark,
    purchaseOrderNo,
    supplierName,
    receiveDate,
  } = body;

  if (!materialCode || !materialName || !quantity) {
    return errorResponse('缺少必要参数：materialCode, materialName, quantity', 400);
  }

  const labelNo = generateLabelNo();

  const result = await execute(
    `
    INSERT INTO inv_material_label (
      label_no, material_code, material_name, specification, unit,
      batch_no, quantity, package_qty, width, length_per_roll,
      color_code, mix_remark, warehouse_id, location_id,
      is_main_material, is_used, is_cut, parent_label_id,
      label_type, remaining_width, remaining_length, status,
      remark, purchase_order_no, supplier_name, receive_date
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, NULL, 1, ?, ?, 1, ?, ?, ?, ?)
  `,
    [
      labelNo,
      materialCode,
      materialName,
      specification ?? null,
      unit ?? null,
      batchNo ?? null,
      quantity,
      packageQty ?? null,
      width ?? null,
      lengthPerRoll ?? null,
      colorCode ?? null,
      mixRemark ?? null,
      warehouseId ?? null,
      locationId ?? null,
      isMainMaterial ? 1 : 0,
      width ?? null,
      lengthPerRoll ?? null,
      remark ?? null,
      purchaseOrderNo ?? null,
      supplierName ?? null,
      receiveDate ?? null,
    ]
  );

  return successResponse({ id: (result as Loose).insertId, labelNo }, '标签创建成功');
});

async function handleCut(body: Loose) {
  const { parentLabelId, cutWidths, operatorName: _operatorName } = body;

  if (!parentLabelId || !cutWidths || !Array.isArray(cutWidths) || cutWidths.length === 0) {
    return errorResponse('缺少必要参数', 400);
  }

  const parentLabel = await query(
    `
    SELECT * FROM inv_material_label WHERE id = ? AND deleted = 0
  `,
    [parentLabelId]
  );

  const parent = (parentLabel as Loose[])[0];

  if (!parent) {
    return errorResponse('父标签不存在', 404);
  }

  if (parent.is_cut === 1) {
    return errorResponse('该标签已被分切', 400);
  }

  const totalCutWidth = cutWidths.reduce((sum: number, w: number) => sum + w, 0);

  if (totalCutWidth > parent.width) {
    return errorResponse(`分切总宽度 ${totalCutWidth} 超过原宽度 ${parent.width}`, 400);
  }

  const newLabels: Loose[] = [];

  for (const cutWidth of cutWidths) {
    const newLabelNo = generateLabelNo();
    const ratio = cutWidth / parent.width;
    const newQuantity = Math.floor(parent.quantity * ratio);

    const result = await execute(
      `
      INSERT INTO inv_material_label (
        label_no, material_code, material_name, specification, unit,
        batch_no, quantity, package_qty, width, length_per_roll,
        color_code, mix_remark, warehouse_id, location_id,
        is_main_material, is_used, is_cut, parent_label_id,
        label_type, remaining_width, remaining_length, status,
        remark, purchase_order_no, supplier_name, receive_date
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, ?, 2, ?, ?, 1, ?, ?, ?, ?)
    `,
      [
        newLabelNo,
        parent.material_code,
        parent.material_name,
        parent.specification,
        parent.unit,
        parent.batch_no,
        newQuantity,
        parent.package_qty ? parent.package_qty * ratio : null,
        cutWidth,
        parent.length_per_roll ?? null,
        parent.color_code ?? null,
        parent.mix_remark ?? null,
        parent.warehouse_id ?? null,
        parent.location_id ?? null,
        parent.is_main_material,
        parentLabelId,
        cutWidth,
        parent.length_per_roll ?? null,
        `分切自 ${parent.label_no}`,
        parent.purchase_order_no ?? null,
        parent.supplier_name ?? null,
        parent.receive_date ?? null,
      ]
    );

    newLabels.push({
      id: (result as Loose).insertId,
      labelNo: newLabelNo,
      width: cutWidth,
      quantity: newQuantity,
    });
  }

  await execute(
    `
    UPDATE inv_material_label
    SET is_cut = 1, remaining_width = width - ?, remaining_length = 0, update_time = NOW()
    WHERE id = ?
  `,
    [totalCutWidth, parentLabelId]
  );

  return successResponse(
    {
      parentLabelId,
      newLabels,
      remainingWidth: parent.width - totalCutWidth,
    },
    '分切成功'
  );
}

export const PUT = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { id } = body;

  if (!id) {
    return errorResponse('缺少标签ID', 400);
  }

  const updateFields: string[] = [];
  const params: Loose[] = [];

  const fieldMap: Record<string, string> = {
    warehouseId: 'warehouse_id',
    locationId: 'location_id',
    isUsed: 'is_used',
    remark: 'remark',
    status: 'status',
  };

  for (const [key, col] of Object.entries(fieldMap)) {
    if (body[key] !== undefined) {
      updateFields.push(`${col} = ?`);
      params.push(body[key]);
    }
  }

  if (updateFields.length === 0) {
    return errorResponse('没有需要更新的字段', 400);
  }

  updateFields.push('update_time = NOW()');
  params.push(id);

  await execute(`UPDATE inv_material_label SET ${updateFields.join(', ')} WHERE id = ?`, params);

  return successResponse(null, '标签更新成功');
});

export const DELETE = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');

  if (!id) {
    return errorResponse('缺少标签ID', 400);
  }

  await execute('UPDATE inv_material_label SET deleted = 1, update_time = NOW() WHERE id = ?', [
    id,
  ]);

  return successResponse(null, '标签删除成功');
});

import { NextRequest, NextResponse } from 'next/server';
import { UserInfo } from '@/lib/api-auth';
import { withPermission } from '@/lib/api-permissions';
import { MaterialLifecycleService } from '@/application/services/MaterialLifecycleService';

const service = new MaterialLifecycleService();

async function getHandler(request: NextRequest, _user: UserInfo) {
  const { searchParams } = new URL(request.url);
  const action = searchParams.get('action');

  try {
    switch (action) {
      case 'stats':
        const stats = await service.getStats();
        return NextResponse.json({ code: 200, data: stats });

      case 'expiry':
        const daysAhead = searchParams.get('days') ? parseInt(searchParams.get('days')!) : 30;
        const warnings = await service.getExpiryWarnings(daysAhead);
        return NextResponse.json({ code: 200, data: warnings });

      case 'stock':
        const analysis = await service.getStockAnalysis();
        return NextResponse.json({ code: 200, data: analysis });

      case 'batches':
        const materialId = searchParams.get('materialId');
        if (!materialId) {
          return NextResponse.json({ code: 400, message: '缺少物料ID' }, { status: 400 });
        }
        const batches = await service.getBatchList(parseInt(materialId));
        return NextResponse.json({ code: 200, data: batches });

      case 'consume':
        const consumePage = searchParams.get('page') ? parseInt(searchParams.get('page')!) : 1;
        const consumePageSize = searchParams.get('pageSize')
          ? parseInt(searchParams.get('pageSize')!)
          : 20;
        const consumeMaterialId = searchParams.get('materialId')
          ? parseInt(searchParams.get('materialId')!)
          : undefined;
        const consumeWorkOrderId = searchParams.get('workOrderId')
          ? parseInt(searchParams.get('workOrderId')!)
          : undefined;
        const consumeLog = await service.getConsumeLog(
          consumeMaterialId,
          consumeWorkOrderId,
          consumePage,
          consumePageSize
        );
        return NextResponse.json({
          code: 200,
          data: {
            list: consumeLog.list,
            total: consumeLog.total,
            page: consumePage,
            pageSize: consumePageSize,
          },
        });

      case 'adjustment':
        const adjPage = searchParams.get('page') ? parseInt(searchParams.get('page')!) : 1;
        const adjPageSize = searchParams.get('pageSize')
          ? parseInt(searchParams.get('pageSize')!)
          : 20;
        const adjMaterialId = searchParams.get('materialId')
          ? parseInt(searchParams.get('materialId')!)
          : undefined;
        const adjustmentLog = await service.getAdjustmentLog(adjMaterialId, adjPage, adjPageSize);
        return NextResponse.json({
          code: 200,
          data: {
            list: adjustmentLog.list,
            total: adjustmentLog.total,
            page: adjPage,
            pageSize: adjPageSize,
          },
        });

      case 'expiry-check':
        const checkResult = await service.runExpiryCheck();
        return NextResponse.json({ code: 200, data: checkResult });

      default:
        return NextResponse.json({ code: 400, message: '无效的操作' }, { status: 400 });
    }
  } catch (error) {
    return NextResponse.json(
      {
        code: 500,
        message: (error as Error).message || '查询失败',
      },
      { status: 500 }
    );
  }
}

async function postHandler(request: NextRequest, user: UserInfo) {
  try {
    const body = await request.json();
    const { action } = body;

    switch (action) {
      case 'consume':
        if (!body.materialId || !body.consumeQty || !body.consumeType) {
          return NextResponse.json({ code: 400, message: '缺少必要参数' }, { status: 400 });
        }
        const consumeId = await service.recordConsumption({
          materialId: body.materialId,
          batchId: body.batchId,
          consumeQty: body.consumeQty,
          consumeType: body.consumeType,
          workOrderId: body.workOrderId,
          workOrderNo: body.workOrderNo,
          sourceType: body.sourceType,
          sourceId: body.sourceId,
          sourceNo: body.sourceNo,
          operatorId: user.userId,
          remark: body.remark,
        });
        return NextResponse.json({ code: 200, message: '消耗记录成功', data: { id: consumeId } });

      case 'adjustment':
        if (!body.materialId || !body.afterQty || !body.adjustmentType || !body.reason) {
          return NextResponse.json({ code: 400, message: '缺少必要参数' }, { status: 400 });
        }
        const adjustmentId = await service.createAdjustment({
          materialId: body.materialId,
          batchId: body.batchId,
          adjustmentType: body.adjustmentType,
          afterQty: body.afterQty,
          reason: body.reason,
          operatorId: user.userId,
        });
        return NextResponse.json({
          code: 200,
          message: '调整单创建成功',
          data: { id: adjustmentId },
        });

      case 'approve':
        if (!body.adjustmentId) {
          return NextResponse.json({ code: 400, message: '缺少调整单ID' }, { status: 400 });
        }
        await service.approveAdjustment(body.adjustmentId, user.userId);
        return NextResponse.json({ code: 200, message: '审核通过' });

      default:
        return NextResponse.json({ code: 400, message: '无效的操作' }, { status: 400 });
    }
  } catch (error) {
    return NextResponse.json(
      {
        code: 500,
        message: (error as Error).message || '操作失败',
      },
      { status: 500 }
    );
  }
}

