// 构建菜单树
function buildMenuTree(menus: Loose[], parentId: number = 0): Loose[] {
  return menus
    .filter((menu) => (menu.parent_id ?? 0) === parentId)
    .sort((a, b) => a.sort_order - b.sort_order)
    .map((menu) => ({
      ...menu,
      children: buildMenuTree(menus, menu.id),
    }));
}

// 获取菜单列表
export const GET = withPermission(async (request: NextRequest, _userInfo: UserInfo) => {
  try {
    const { searchParams } = new URL(request.url);
    const status = searchParams.get('status');

    let sql = `
      SELECT 
        id,
        menu_name,
        menu_code,
        parent_id,
        path,
        icon,
        sort_order,
        status,
        permission,
        component,
        is_cache as keep_alive,
        is_visible as hidden,
        create_time,
        update_time
      FROM sys_menu
      WHERE status = 1
    `;
    const params: Loose[] = [];

    if (status !== null && status !== '') {
      sql += ' AND status = ?';
      params.push(parseInt(status));
    }

    sql += ' ORDER BY sort_order ASC';

    const menus = await query(sql, params);

    // 构建树形结构
    const menuTree = buildMenuTree(menus as Loose[]);

    return successResponse(menuTree, '获取菜单列表成功');
  } catch {
    return errorResponse('获取菜单列表失败', 500);
  }
});

import { NextRequest } from 'next/server';
import { transaction } from '@/lib/db';
import { successResponse, errorResponse, commonErrors } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { jwtVerify } from 'jose';
import { secureLog } from '@/lib/logger';
import { getSecretKey } from '@/lib/auth';

// 验证JWT Token
async function verifyToken(token: string) {
  try {
    const { payload } = await jwtVerify(token, new TextEncoder().encode(getSecretKey()));
    return payload;
  } catch {
    return null;
  }
}

// POST - 保存菜单排序
export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    // 获取token
    const authHeader = request.headers.get('authorization');
    secureLog('debug', 'Menu sort auth', { hasAuth: !!authHeader });
    const token = authHeader?.replace('Bearer ', '');

    if (!token) {
      return commonErrors.unauthorized('未登录');
    }

    const payload = await verifyToken(token);
    secureLog('debug', 'Menu sort token verified', { userId: payload?.userId });
    if (!payload) {
      return commonErrors.unauthorized('登录已过期');
    }

    const body = await request.json();
    const { orders } = body;

    if (!Array.isArray(orders)) {
      return commonErrors.badRequest('参数错误，orders必须是数组');
    }

    // 验证每个排序项
    for (const item of orders) {
      if (!item.id || typeof item.sort_order !== 'number') {
        return errorResponse('排序项格式不正确，需要id和sort_order字段', 400, 400);
      }
    }

    // 使用事务更新排序
    await transaction(async (connection) => {
      for (const item of orders) {
        // 检查菜单是否存在
        const [menuResult]: Loose = await connection.execute(
          'SELECT id FROM sys_menu WHERE id = ?',
          [item.id]
        );

        if (menuResult.length > 0) {
          await connection.execute('UPDATE sys_menu SET sort_order = ? WHERE id = ?', [
            item.sort_order,
            item.id,
          ]);
        }
      }
    });

    return successResponse(null, '菜单排序已保存');
  },
  { logTitle: '保存菜单排序' }
);

