﻿import { NextRequest } from 'next/server';
import { query, queryOne } from '@/lib/db';
import { successResponse, errorResponse, commonErrors } from '@/lib/api-response';
import { generateDocumentNo } from '@/lib/document-numbering';

import { withPermission } from '@/lib/api-permissions';
// GET - 获取订单列表/详情
export const GET = withPermission(
  async (request: NextRequest) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    const status = searchParams.get('status');
    const keyword = searchParams.get('keyword');

    if (id) {
      // 获取单个订单详情
      const orders = await query(
        `SELECT so.*, c.customer_name FROM sal_order so LEFT JOIN crm_customer c ON so.customer_id = c.id WHERE so.order_no = ? AND so.deleted = 0`,
        [id]
      );

      if (!orders || (orders as Loose[]).length === 0) {
        return commonErrors.notFound('订单不存在');
      }

      const order = (orders as Loose[])[0];

      // 获取订单明细
      let items = await query('SELECT * FROM sal_order_item WHERE order_id = ?', [order.id]);

      if (!items || (items as Loose[]).length === 0) {
        items = await query(
          `SELECT od.material_id, m.material_name, od.quantity, od.unit, od.unit_price, od.total_amount as total_price
         FROM sal_order_detail od
         LEFT JOIN inv_material m ON od.material_id = m.id
         WHERE od.order_id = ?`,
          [order.id]
        );
      }

      const orderData = {
        id: order.id,
        order_no: order.order_no,
        customer_id: order.customer_id,
        customer_name: order.customer_name,
        order_date: order.order_date,
        delivery_date: order.delivery_date,
        status: order.status,
        total_amount: parseFloat(order.total_amount),
        total_with_tax: order.total_with_tax ? parseFloat(order.total_with_tax) : undefined,
        items: (items as Loose[]).map((item: Loose) => ({
          material_name: item.material_name || '',
          quantity: parseFloat(item.quantity),
          unit: item.unit || '',
          unit_price: parseFloat(item.unit_price),
          total_price: parseFloat(item.total_price || item.total_amount || 0),
        })),
        remark: order.remark,
        create_time: order.create_time,
        update_time: order.update_time,
      };

      return successResponse(orderData);
    }

    // 获取订单列表
    let sql = `SELECT so.*, c.customer_name FROM sal_order so LEFT JOIN crm_customer c ON so.customer_id = c.id WHERE so.deleted = 0`;
    const params: Loose[] = [];

    if (status && status !== 'all') {
      sql += ' AND so.status = ?';
      params.push(status);
    }

    if (keyword) {
      sql += ' AND (so.order_no LIKE ? OR c.customer_name LIKE ?)';
      params.push(`%${keyword}%`, `%${keyword}%`);
    }

    sql += ' ORDER BY so.create_time DESC';

    const orders = await query(sql, params);

    const orderList = await Promise.all(
      (orders as Loose[]).map(async (order: Loose) => {
        let items = await query('SELECT * FROM sal_order_item WHERE order_id = ?', [order.id]);

        if (!items || (items as Loose[]).length === 0) {
          items = await query(
            `SELECT od.material_id, m.material_name, od.quantity, od.unit, od.unit_price, od.total_amount as total_price
           FROM sal_order_detail od
           LEFT JOIN inv_material m ON od.material_id = m.id
           WHERE od.order_id = ?`,
            [order.id]
          );
        }

        return {
          id: order.id,
          order_no: order.order_no,
          customer_id: order.customer_id,
          customer_name: order.customer_name,
          order_date: order.order_date,
          delivery_date: order.delivery_date,
          status: order.status,
          total_amount: parseFloat(order.total_amount),
          total_with_tax: order.total_with_tax ? parseFloat(order.total_with_tax) : undefined,
          items: (items as Loose[]).map((item: Loose) => ({
            material_name: item.material_name || '',
            quantity: parseFloat(item.quantity),
            unit: item.unit || '',
            unit_price: parseFloat(item.unit_price),
            total_price: parseFloat(item.total_price || item.total_amount || 0),
          })),
          remark: order.remark,
          create_time: order.create_time,
          update_time: order.update_time,
        };
      })
    );

    return successResponse({
      list: orderList,
      total: orderList.length,
    });
  },
  { errorMessage: '获取订单失败' }
);

// POST - 创建订单
export const POST = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();

    const { customer_id, customer_name, delivery_date, items, remark } = body;

    const finalCustomerId = customer_id || null;
    let finalCustomerName = customer_name || '';

    if (!finalCustomerName && finalCustomerId) {
      const customer = await queryOne(
        'SELECT customer_name FROM crm_customer WHERE id = ? AND deleted = 0',
        [finalCustomerId]
      );
      if (customer) {
        finalCustomerName = (customer as Loose).customer_name;
      }
    }

    if (!finalCustomerName) {
      return errorResponse('客户信息不能为空', 400, 400);
    }

    if (!Array.isArray(items) || items.length === 0) {
      return errorResponse('订单项不能为空', 400, 400);
    }

    for (const item of items) {
      if (!item.material_name || !item.quantity || !item.unit_price) {
        return errorResponse('订单项缺少必填字段(物料名称、数量、单价)', 400, 400);
      }
      if (item.quantity <= 0) {
        return errorResponse('订单数量必须大于0', 400, 400);
      }
      if (item.unit_price < 0) {
        return errorResponse('单价不能为负数', 400, 400);
      }
    }

    const total_amount = items.reduce(
      (sum: number, item: Loose) => sum + item.quantity * item.unit_price,
      0
    );

    const orderNo = await generateDocumentNo('sales_order');

    const orderResult = await query(
      `INSERT INTO sal_order (order_no, customer_id, order_date, delivery_date, total_amount, status, remark, create_time) 
     VALUES (?, ?, CURDATE(), ?, ?, 1, ?, NOW())`,
      [orderNo, finalCustomerId, delivery_date, total_amount, remark || '']
    );

    const orderId = (orderResult as Loose).insertId;

    for (const item of items) {
      await query(
        `INSERT INTO sal_order_item (order_id, material_name, quantity, unit, unit_price, total_price, create_time) 
       VALUES (?, ?, ?, ?, ?, ?, NOW())`,
        [
          orderId,
          item.material_name,
          item.quantity,
          item.unit,
          item.unit_price,
          item.quantity * item.unit_price,
        ]
      );
    }

    return successResponse({ id: orderId, order_no: orderNo }, '订单创建成功');
  },
  { errorMessage: '创建订单失败' }
);

// PUT - 更新订单
export const PUT = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();
    const { id, status, ...updateData } = body;

    if (!id) {
      return errorResponse('订单ID不能为空', 400, 400);
    }

    const orders = await query('SELECT * FROM sal_order WHERE id = ? AND deleted = 0', [id]);

    if (!orders || (orders as Loose[]).length === 0) {
      return commonErrors.notFound('订单不存在');
    }

    const order = (orders as Loose[])[0];

    if (order.status === 'completed' || order.status === 'cancelled') {
      return errorResponse('已完成的订单不能修改', 400, 400);
    }

    const updateFields: string[] = [];
    const updateParams: Loose[] = [];

    if (status) {
      updateFields.push('status = ?');
      updateParams.push(status);
    }

    if (updateData.delivery_date) {
      updateFields.push('delivery_date = ?');
      updateParams.push(updateData.delivery_date);
    }

    if (updateData.remark !== undefined) {
      updateFields.push('remark = ?');
      updateParams.push(updateData.remark);
    }

    if (updateFields.length > 0) {
      updateParams.push(order.id);
      await query(
        `UPDATE sal_order SET ${updateFields.join(', ')}, update_time = NOW() WHERE id = ?`,
        updateParams
      );
    }

    return successResponse({ id, status, ...updateData }, '订单更新成功');
  },
  { errorMessage: '更新订单失败' }
);

// DELETE - 删除订单
export const DELETE = withPermission(
  async (request: NextRequest) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return errorResponse('订单ID不能为空', 400, 400);
    }

    // 查询订单
    const orders = await query('SELECT * FROM sal_order WHERE id = ? AND deleted = 0', [id]);

    if (!orders || (orders as Loose[]).length === 0) {
      return commonErrors.notFound('订单不存在');
    }

    const order = (orders as Loose[])[0];

    if (order.status === 'completed') {
      return errorResponse('已完成的订单不能删除', 400, 400);
    }

    await query('UPDATE sal_order SET deleted = 1, update_time = NOW() WHERE id = ?', [order.id]);

    return successResponse(null, '订单删除成功');
  },
  { errorMessage: '删除订单失败' }
);

﻿import { NextRequest } from 'next/server';
import { query, execute, queryOne, transaction } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { UserInfo } from '@/lib/api-auth';
import { withPermission } from '@/lib/api-permissions';
import { getDomainEventOutbox } from '@/infrastructure/event-bus/DomainEventOutboxFactory';
import {
  SalesOrderApprovedEvent,
  SalesOrderSubmittedEvent,
} from '@/domain/sales/events/SalesOrderEvents';
import { secureLog } from '@/lib/logger';

export const GET = withPermission(async (request: NextRequest, _user: UserInfo) => {
  const { searchParams } = new URL(request.url);
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '20');
  const keyword = searchParams.get('keyword');
  const status = searchParams.get('status');

  let whereClause = 'WHERE so.deleted = 0';
  const params: Loose[] = [];

  if (keyword) {
    whereClause += ' AND (so.order_no LIKE ? OR c.customer_name LIKE ?)';
    params.push(`%${keyword}%`, `%${keyword}%`);
  }

  if (status) {
    whereClause += ' AND so.status = ?';
    params.push(parseInt(status));
  }

  const totalRows: Loose = await query(
    `SELECT COUNT(*) as total FROM sal_order so LEFT JOIN crm_customer c ON so.customer_id = c.id ${whereClause}`,
    params
  );
  const total = totalRows[0]?.total || 0;

  const rows: Loose[] = await query(
    `SELECT so.*, c.customer_name
     FROM sal_order so
     LEFT JOIN crm_customer c ON so.customer_id = c.id
     ${whereClause}
     ORDER BY so.create_time DESC
     LIMIT ? OFFSET ?`,
    [...params, pageSize, (page - 1) * pageSize]
  );

  const list = (rows as Loose[]).map((order: Loose) => ({
    id: order.id,
    order_no: order.order_no,
    order_date: order.order_date,
    customer_id: order.customer_id,
    customer_name: order.customer_name,
    contact_name: order.contact_name,
    contact_phone: order.contact_phone,
    delivery_address: order.delivery_address,
    total_amount: parseFloat(order.total_amount || '0'),
    total_with_tax: parseFloat(order.total_with_tax || '0'),
    currency: order.currency || 'CNY',
    exchange_rate: parseFloat(order.exchange_rate || '1'),
    base_currency: order.base_currency || 'CNY',
    base_total_amount: parseFloat(order.base_total_amount || '0'),
    base_tax_amount: parseFloat(order.base_tax_amount || '0'),
    base_grand_total: parseFloat(order.base_grand_total || '0'),
    status: order.status,
    remark: order.remark,
    create_time: order.create_time,
  }));

  return successResponse({ list, total, page, pageSize });
});

export const POST = withPermission(
  async (request: NextRequest, user: UserInfo) => {
    const body = await request.json();
    const {
      customer_id,
      customer_name: _customer_name,
      order_date,
      delivery_date,
      items,
      remark,
      payment_terms,
      contract_no,
      currency,
    } = body;

    if (!customer_id || !items || items.length === 0) {
      return errorResponse('客户和订单明细不能为空', 400, 400);
    }

    const order_no = 'SO' + Date.now();

    const result: Loose = await execute(
      `INSERT INTO sal_order (
      order_no, customer_id, order_date, delivery_date, status,
      salesman_id, payment_terms, contract_no, remark,
      currency, create_by, create_time, update_time, deleted
    ) VALUES (?, ?, ?, ?, 1, ?, ?, ?, ?, ?, ?, NOW(), NOW(), 0)`,
      [
        order_no,
        customer_id,
        order_date || new Date().toISOString().slice(0, 10),
        delivery_date || null,
        user.userId,
        payment_terms || null,
        contract_no || null,
        remark || null,
        currency || null,
        user.userId,
      ]
    );

    const orderId = result.insertId;

    let totalAmount = 0;
    for (const item of items) {
      const amount = (item.quantity || 0) * (item.unit_price || 0);
      totalAmount += amount;

      await execute(
        `INSERT INTO sal_order_item (
        order_id, material_id, material_code, material_name,
        quantity, unit_price, amount, unit, remark, create_time, deleted
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), 0)`,
        [
          orderId,
          item.material_id,
          item.material_code || '',
          item.material_name || '',
          item.quantity,
          item.unit_price || 0,
          amount,
          item.unit || '',
          item.remark || null,
        ]
      );
    }

    await execute(`UPDATE sal_order SET total_amount = ?, total_with_tax = ? WHERE id = ?`, [
      totalAmount,
      totalAmount * 1.13,
      orderId,
    ]);

    return successResponse({ id: orderId, order_no, status: 'draft' }, '销售订单创建成功');
  },
  { logTitle: '创建销售订单', logType: 'business' }
);

export const PUT = withPermission(
  async (request: NextRequest, user: UserInfo) => {
    const body = await request.json();
    const { id, action } = body;

    if (!id) {
      return errorResponse('订单ID不能为空', 400, 400);
    }

    if (body.currency !== undefined) {
      return errorResponse('币种创建后不可修改', 400, 400);
    }
    if (body.exchange_rate !== undefined) {
      return errorResponse('汇率创建后不可修改', 400, 400);
    }

    const order: Loose = await queryOne('SELECT * FROM sal_order WHERE id = ? AND deleted = 0', [
      id,
    ]);

    if (!order) {
      return errorResponse('订单不存在', 404, 404);
    }

    switch (action) {
      case 'submit':
        if (order.status !== 1) {
          return errorResponse('只有草稿状态的订单可以提交', 400, 400);
        }

        await transaction(async (conn) => {
          await conn.execute('UPDATE sal_order SET status = 2, update_time = NOW() WHERE id = ?', [
            id,
          ]);
          await getDomainEventOutbox().saveEvents(conn, 'SalesOrder', id, [
            new SalesOrderSubmittedEvent({
              orderId: order.id,
              orderNo: order.order_no,
            }),
          ]);
        });

        secureLog('info', 'Sales order submitted', { orderId: id, orderNo: order.order_no });

        return successResponse({ status: 2 }, '订单已提交');

      case 'approve':
        if (order.status !== 2) {
          return errorResponse('只有已提交的订单可以审核', 400, 400);
        }

        const lines: Loose[] = await query(
          'SELECT * FROM sal_order_item WHERE order_id = ? AND deleted = 0',
          [id]
        );

        await transaction(async (conn) => {
          await conn.execute(
            'UPDATE sal_order SET status = 3, audit_by = ?, audit_time = NOW(), update_time = NOW() WHERE id = ?',
            [user.userId, id]
          );
          await getDomainEventOutbox().saveEvents(conn, 'SalesOrder', id, [
            new SalesOrderApprovedEvent({
              orderId: order.id,
              orderNo: order.order_no,
              customerId: order.customer_id,
              customerName: order.customer_name,
              lines: lines.map((l) => ({
                materialId: l.material_id,
                materialCode: l.material_code,
                materialName: l.material_name,
                orderQty: l.quantity,
                unitPrice: parseFloat(l.unit_price),
                remainingQty: l.quantity,
              })),
              totalAmount: parseFloat(order.total_amount),
            }),
          ]);
        });

        secureLog('info', 'Sales order approved, work order creation triggered', {
          orderId: id,
          orderNo: order.order_no,
          lineCount: lines.length,
        });

        return successResponse({ status: 3 }, '订单已审核，生产工单生成中');

      case 'reject':
        if (order.status !== 2) {
          return errorResponse('只有已提交的订单可以驳回', 400, 400);
        }

        await execute('UPDATE sal_order SET status = 1, update_time = NOW() WHERE id = ?', [id]);

        return successResponse({ status: 1 }, '订单已驳回');

      default:
        return errorResponse('未知操作', 400, 400);
    }
  },
  { logTitle: '更新销售订单状态', logType: 'business' }
);

