import { withPermission } from '@/lib/api-permissions';
import { successResponse, errorResponse } from '@/lib/api-response';

const db = getDrizzleDb();

const tableMap: Record<string, any> = {
  group: orgGroup,
  legal_entity: orgLegalEntity,
  factory: orgFactory,
  workshop: orgWorkshop,
  team: orgTeam,
  position: orgPosition,
};

const parentKeyMap: Record<string, string> = {
  legal_entity: 'groupId',
  factory: 'legalEntityId',
  workshop: 'factoryId',
  team: 'workshopId',
  position: 'teamId',
};

export const POST = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { type, parentId, code, name, sortOrder, remark } = body;
  if (!type || !code || !name) return errorResponse('缺少必填字段', 400);
  if (!tableMap[type]) return errorResponse('无效的节点类型', 400);

  const table = tableMap[type];
  const insertData: Record<string, any> = { code, name, sortOrder: sortOrder || 0, remark: remark || null };
  if (type !== 'group' && parentId) {
    const parentKey = parentKeyMap[type];
    insertData[parentKey] = parentId;
  }

  const result = await db.insert(table).values(insertData);
  return successResponse({ id: Number(result[0].insertId) });
}, { errorMessage: '创建组织节点失败' });

export const PUT = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { id, type, code, name, sortOrder, status, remark, ...extra } = body;
  if (!id || !type) return errorResponse('缺少ID或类型', 400);
  if (!tableMap[type]) return errorResponse('无效的节点类型', 400);

  const table = tableMap[type];
  const setData: Record<string, any> = {};
  if (code !== undefined) setData.code = code;
  if (name !== undefined) setData.name = name;
  if (sortOrder !== undefined) setData.sortOrder = sortOrder;
  if (status !== undefined) setData.status = status;
  if (remark !== undefined) setData.remark = remark;

  // Entity-specific fields
  if (type === 'factory' && extra.address !== undefined) setData.address = extra.address;
  if (type === 'factory' && extra.contactPerson !== undefined) setData.contactPerson = extra.contactPerson;
  if (type === 'factory' && extra.contactPhone !== undefined) setData.contactPhone = extra.contactPhone;
  if (type === 'workshop' && extra.managerName !== undefined) setData.managerName = extra.managerName;
  if (type === 'team' && extra.teamLeader !== undefined) setData.teamLeader = extra.teamLeader;
  if (type === 'position' && extra.skillLevel !== undefined) setData.skillLevel = extra.skillLevel;
  if (type === 'position' && extra.baseSalaryRange !== undefined) setData.baseSalaryRange = extra.baseSalaryRange;
  if (type === 'legal_entity' && extra.taxId !== undefined) setData.taxId = extra.taxId;
  if (type === 'legal_entity' && extra.legalPerson !== undefined) setData.legalPerson = extra.legalPerson;

  if (Object.keys(setData).length === 0) return errorResponse('没有需要更新的字段', 400);

  await db.update(table).set(setData).where(eq(table.id, id));
  return successResponse(null);
}, { errorMessage: '更新组织节点失败' });

export const DELETE = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const id = parseInt(searchParams.get('id') || '');
  const type = searchParams.get('type');
  if (!id || !type) return errorResponse('缺少ID或类型', 400);
  if (!tableMap[type]) return errorResponse('无效的节点类型', 400);

  const table = tableMap[type];
  await db.update(table).set({ deleted: 1 }).where(eq(table.id, id));
  return successResponse(null);
}, { errorMessage: '删除组织节点失败' });

﻿import { NextRequest } from 'next/server';
import { query, execute, queryOne } from '@/lib/db';
import {
  successResponse,
  errorResponse,
  commonErrors,
  validateRequestBody,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

interface Department {
  id?: number;
  dept_code: string;
  dept_name: string;
  parent_id?: number;
  leader_id?: number;
  sort_order?: number;
  status?: number;
  create_time?: string;
  update_time?: string;
}

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const keyword = searchParams.get('keyword') || '';
  const status = searchParams.get('status');
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '20');

  let where = 'WHERE deleted = 0';
  const values: Loose[] = [];

  if (keyword) {
    where += ' AND (dept_name LIKE ? OR dept_code LIKE ?)';
    values.push(`%${keyword}%`, `%${keyword}%`);
  }

  if (status !== undefined && status !== null && status !== '') {
    where += ' AND status = ?';
    values.push(parseInt(status));
  }

  const countResult = await query(`SELECT COUNT(*) as total FROM sys_department ${where}`, values);
  const total = (countResult as Loose[])[0]?.total || 0;

  const departments = await query<Department>(
    `SELECT id, dept_code, dept_name, parent_id, leader_id, sort_order, status, phone, email, create_time, update_time FROM sys_department ${where} ORDER BY sort_order ASC, id ASC LIMIT ? OFFSET ?`,
    [...values, pageSize, (page - 1) * pageSize]
  );

  return successResponse({
    list: departments,
    total,
    page,
    pageSize,
  });
});

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body: Department = await request.json();

    const validation = validateRequestBody(body, ['dept_code', 'dept_name']);
    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    const existing = await queryOne<{ id: number }>(
      'SELECT id FROM sys_department WHERE dept_code = ? AND deleted = 0',
      [body.dept_code]
    );

    if (existing) {
      return errorResponse('部门编码已存在', 409, 409);
    }

    const result = await execute(
      `INSERT INTO sys_department (dept_code, dept_name, parent_id, leader_id, sort_order, status) VALUES (?, ?, ?, ?, ?, ?)`,
      [
        body.dept_code,
        body.dept_name,
        body.parent_id ?? 0,
        body.leader_id ?? null,
        body.sort_order ?? 0,
        body.status ?? 1,
      ]
    );

    return successResponse({ id: result.insertId }, '部门创建成功');
  },
  { logTitle: '创建部门' }
);

export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body: Department = await request.json();
    const { id } = body;

    if (!id) {
      return commonErrors.badRequest('部门ID不能为空');
    }

    const validation = validateRequestBody(body, ['dept_code', 'dept_name']);
    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    const existingDept = await queryOne<{ id: number }>(
      'SELECT id FROM sys_department WHERE id = ? AND deleted = 0',
      [id]
    );

    if (!existingDept) {
      return commonErrors.notFound('部门不存在');
    }

    const codeExists = await queryOne<{ id: number }>(
      'SELECT id FROM sys_department WHERE dept_code = ? AND id != ? AND deleted = 0',
      [body.dept_code, id]
    );

    if (codeExists) {
      return errorResponse('部门编码已存在', 409, 409);
    }

    const result = await execute(
      `UPDATE sys_department SET dept_code = ?, dept_name = ?, parent_id = ?, leader_id = ?, sort_order = ?, status = ? WHERE id = ? AND deleted = 0`,
      [
        body.dept_code,
        body.dept_name,
        body.parent_id ?? 0,
        body.leader_id ?? null,
        body.sort_order ?? 0,
        body.status ?? 1,
        id,
      ]
    );

    if (result.affectedRows === 0) {
      return commonErrors.notFound('部门不存在');
    }

    return successResponse(null, '部门更新成功');
  },
  { logTitle: '更新部门' }
);

export const DELETE = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return commonErrors.badRequest('部门ID不能为空');
    }

    const deptId = parseInt(id);

    const existingDept = await queryOne<{ id: number }>(
      'SELECT id FROM sys_department WHERE id = ? AND deleted = 0',
      [deptId]
    );

    if (!existingDept) {
      return commonErrors.notFound('部门不存在');
    }

    const hasChildren = await queryOne<{ count: number }>(
      'SELECT COUNT(*) as count FROM sys_department WHERE parent_id = ? AND deleted = 0',
      [deptId]
    );

    if (hasChildren && hasChildren.count > 0) {
      return errorResponse('该部门下有子部门，无法删除', 409, 409);
    }

    const hasEmployees = await queryOne<{ count: number }>(
      'SELECT COUNT(*) as count FROM sys_employee WHERE dept_id = ?',
      [deptId]
    );

    if (hasEmployees && hasEmployees.count > 0) {
      return errorResponse('该部门下有员工，无法删除', 409, 409);
    }

    await execute('UPDATE sys_department SET deleted = 1 WHERE id = ?', [deptId]);

    return successResponse(null, '部门删除成功');
  },
  { logTitle: '删除部门' }
);

import { NextRequest } from 'next/server';
import { execute, queryOne, transaction, queryPaginated } from '@/lib/db';
import {
  successResponse,
  paginatedResponse,
  errorResponse,
  commonErrors,
  validateRequestBody,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

// 员工数据接口
interface Employee {
  id?: number;
  employee_no: string;
  name: string;
  gender?: number;
  age?: number;
  id_card?: string;
  phone?: string;
  email?: string;
  dept_id?: number;
  dept_name?: string;
  section?: string;
  role_id?: number;
  role_name?: string;
  position?: string;
  entry_date?: string;
  birth_date?: string;
  native_place?: string;
  home_address?: string;
  current_address?: string;
  birth_month?: string;
  id_card_expiry?: string;
  education?: string;
  remark?: string;
  status?: number;
  photo?: string;
  create_time?: string;
  update_time?: string;
}

// 构建查询条件
function buildQueryConditions(params: {
  keyword?: string;
  dept_id?: string;
  role_id?: string;
  status?: string;
}): { sql: string; countSql: string; values: Loose[] } {
  let sql = 'SELECT * FROM sys_employee WHERE 1=1';
  let countSql = 'SELECT COUNT(*) as total FROM sys_employee WHERE 1=1';
  const values: Loose[] = [];

  if (params.keyword) {
    const condition = ' AND (name LIKE ? OR employee_no LIKE ? OR phone LIKE ?)';
    sql += condition;
    countSql += condition;
    const likeKeyword = `%${params.keyword}%`;
    values.push(likeKeyword, likeKeyword, likeKeyword);
  }

  if (params.dept_id) {
    const condition = ' AND dept_id = ?';
    sql += condition;
    countSql += condition;
    values.push(parseInt(params.dept_id));
  }

  if (params.role_id) {
    const condition = ' AND role_id = ?';
    sql += condition;
    countSql += condition;
    values.push(parseInt(params.role_id));
  }

  if (params.status !== undefined && params.status !== null && params.status !== '') {
    const condition = ' AND status = ?';
    sql += condition;
    countSql += condition;
    values.push(parseInt(params.status));
  }

  sql += ' ORDER BY id DESC';

  return { sql, countSql, values };
}

// GET - 获取员工列表或单个员工
export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');
  const keyword = searchParams.get('keyword') || '';
  const dept_id = searchParams.get('dept_id');
  const role_id = searchParams.get('role_id');
  const status = searchParams.get('status');
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '10');

  // 查询单个员工
  if (id) {
    const employee = await queryOne<Employee>('SELECT * FROM sys_employee WHERE id = ?', [
      parseInt(id),
    ]);

    if (!employee) {
      return commonErrors.notFound('员工不存在');
    }

    return successResponse(employee);
  }

  // 构建查询条件
  const { sql, countSql, values } = buildQueryConditions({
    keyword: keyword || undefined,
    dept_id: dept_id ?? undefined,
    role_id: role_id ?? undefined,
    status: status ?? undefined,
  });

  // 使用分页查询工具
  const result = await queryPaginated<Employee>(sql, countSql, values, {
    page,
    pageSize,
  });

  return paginatedResponse(result.data, result.pagination);
});

