// DELETE - 删除员工（软删除）
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return commonErrors.badRequest('员工ID不能为空');
    }

    const employeeId = parseInt(id);

    // 检查员工是否存在
    const existingEmployee = await queryOne<{ id: number }>(
      'SELECT id FROM sys_employee WHERE id = ?',
      [employeeId]
    );

    if (!existingEmployee) {
      return commonErrors.notFound('员工不存在');
    }

    // 使用事务软删除
    await transaction(async (connection) => {
      await connection.execute('UPDATE sys_employee SET status = 0 WHERE id = ?', [employeeId]);
    });

    return successResponse(null, '员工删除成功');
  },
  { logTitle: '删除员工' }
);

﻿import { NextRequest } from 'next/server';
import { query, execute, queryOne, transaction } from '@/lib/db';
import {
  successResponse,
  errorResponse,
  commonErrors,
  validateRequestBody,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

// 菜单数据接口
interface Menu {
  id?: number;
  parent_id?: number;
  menu_name: string;
  menu_code: string;
  menu_type?: number;
  icon?: string;
  path?: string;
  component?: string;
  permission?: string;
  sort_order?: number;
  is_visible?: number;
  status?: number;
  create_time?: string;
  update_time?: string;
}

// GET - 获取所有菜单
export const GET = withPermission(async (_request: NextRequest, _userInfo) => {
  const menus = await query<Menu>(`
    SELECT
      id, parent_id, menu_name, menu_code, menu_type, icon,
      path, component, permission, sort_order, is_visible, status,
      create_time, update_time
    FROM sys_menu
    WHERE status = 1
    ORDER BY sort_order ASC, id ASC
  `);

  return successResponse(menus);
});

// POST - 创建菜单
export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body: Menu = await request.json();

    // 验证必填字段
    const validation = validateRequestBody(body, ['menu_name', 'menu_code']);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    // 检查菜单编码是否已存在
    const existing = await queryOne<{ id: number }>('SELECT id FROM sys_menu WHERE menu_code = ?', [
      body.menu_code,
    ]);

    if (existing) {
      return errorResponse('菜单编码已存在', 409, 409);
    }

    const result = await execute(
      `INSERT INTO sys_menu (
      parent_id, menu_name, menu_code, menu_type, icon, path,
      component, permission, sort_order, is_visible, status
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)`,
      [
        body.parent_id ?? 0,
        body.menu_name,
        body.menu_code,
        body.menu_type ?? 1,
        body.icon ?? null,
        body.path ?? null,
        body.component ?? null,
        body.permission ?? null,
        body.sort_order ?? 0,
        body.is_visible ?? 1,
      ]
    );

    return successResponse({ id: result.insertId }, '菜单创建成功');
  },
  { logTitle: '创建菜单' }
);

// PUT - 更新菜单
export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body: Menu = await request.json();
    const { id } = body;

    if (!id) {
      return commonErrors.badRequest('菜单ID不能为空');
    }

    // 验证必填字段
    const validation = validateRequestBody(body, ['menu_name', 'menu_code']);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    // 检查菜单是否存在
    const existingMenu = await queryOne<{ id: number }>('SELECT id FROM sys_menu WHERE id = ?', [
      id,
    ]);

    if (!existingMenu) {
      return commonErrors.notFound('菜单不存在');
    }

    // 检查编码是否已被其他菜单使用
    const codeExists = await queryOne<{ id: number }>(
      'SELECT id FROM sys_menu WHERE menu_code = ? AND id != ?',
      [body.menu_code, id]
    );

    if (codeExists) {
      return errorResponse('菜单编码已存在', 409, 409);
    }

    const result = await execute(
      `UPDATE sys_menu SET
      parent_id = ?, menu_name = ?, menu_code = ?, menu_type = ?,
      icon = ?, path = ?, component = ?, permission = ?,
      sort_order = ?, is_visible = ?, status = ?
    WHERE id = ?`,
      [
        body.parent_id ?? 0,
        body.menu_name,
        body.menu_code,
        body.menu_type ?? 1,
        body.icon ?? null,
        body.path ?? null,
        body.component ?? null,
        body.permission ?? null,
        body.sort_order ?? 0,
        body.is_visible ?? 1,
        body.status ?? 1,
        id,
      ]
    );

    if (result.affectedRows === 0) {
      return commonErrors.notFound('菜单不存在');
    }

    return successResponse(null, '菜单更新成功');
  },
  { logTitle: '更新菜单' }
);

// DELETE - 删除菜单
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return commonErrors.badRequest('菜单ID不能为空');
    }

    const menuId = parseInt(id);

    // 检查菜单是否存在
    const existingMenu = await queryOne<{ id: number }>('SELECT id FROM sys_menu WHERE id = ?', [
      menuId,
    ]);

    if (!existingMenu) {
      return commonErrors.notFound('菜单不存在');
    }

    // 检查是否有子菜单
    const hasChildren = await queryOne<{ count: number }>(
      'SELECT COUNT(*) as count FROM sys_menu WHERE parent_id = ?',
      [menuId]
    );

    if (hasChildren && hasChildren.count > 0) {
      return errorResponse('请先删除子菜单', 409, 409);
    }

    // 使用事务删除菜单和关联的角色权限
    await transaction(async (connection) => {
      // 删除角色菜单关联
      await connection.execute('DELETE FROM sys_role_menu WHERE menu_id = ?', [menuId]);

      // 删除菜单
      await connection.execute('DELETE FROM sys_menu WHERE id = ?', [menuId]);
    });

    return successResponse(null, '菜单删除成功');
  },
  { logTitle: '删除菜单' }
);

﻿import { NextRequest } from 'next/server';
import { query, execute, queryOne } from '@/lib/db';
import {
  successResponse,
  errorResponse,
  commonErrors,
  validateRequestBody,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

// 角色数据接口
interface Role {
  id?: number;
  role_code: string;
  role_name: string;
  description?: string;
  data_scope?: number;
  status?: number;
  permissions?: string | string[];
  create_time?: string;
  update_time?: string;
}

// 构建查询条件
function buildQueryConditions(params: { keyword: string; status: string | null }): {
  sql: string;
  values: Loose[];
} {
  let sql = `
    SELECT
      id, role_code, role_name, description, data_scope, status, permissions,
      create_time, update_time
    FROM sys_role
    WHERE deleted = 0
  `;
  const values: Loose[] = [];

  if (params.keyword) {
    sql += ' AND (role_name LIKE ? OR role_code LIKE ?)';
    const likeKeyword = `%${params.keyword}%`;
    values.push(likeKeyword, likeKeyword);
  }

  if (params.status !== undefined && params.status !== null && params.status !== '') {
    sql += ' AND status = ?';
    values.push(parseInt(params.status));
  }

  sql += ' ORDER BY id ASC';

  return { sql, values };
}

// 格式化角色数据
function formatRole(role: Loose): Role {
  let permissions: string[] = [];
  if (role.permissions) {
    try {
      if (typeof role.permissions === 'string') {
        // 尝试解析JSON字符串
        const parsed = JSON.parse(role.permissions);
        permissions = Array.isArray(parsed) ? parsed : [parsed];
      } else if (Array.isArray(role.permissions)) {
        // 如果已经是数组
        permissions = role.permissions;
      }
    } catch {
      // 如果不是JSON，可能是逗号分隔的字符串
      if (typeof role.permissions === 'string') {
        permissions = role.permissions.split(',').filter((p: string) => p.trim());
      }
    }
  }
  return {
    ...role,
    code: role.role_code,
    name: role.role_name,
    permissions,
  };
}

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const keyword = searchParams.get('keyword') || '';
  const status = searchParams.get('status');
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '20');

  const { sql, values } = buildQueryConditions({
    keyword,
    status,
  });

  let countSql = `SELECT COUNT(*) as total FROM sys_role WHERE deleted = 0`;
  const countValues: Loose[] = [];

  if (keyword) {
    countSql += ' AND (role_name LIKE ? OR role_code LIKE ?)';
    countValues.push(`%${keyword}%`, `%${keyword}%`);
  }

  if (status !== undefined && status !== null && status !== '') {
    countSql += ' AND status = ?';
    countValues.push(parseInt(status));
  }

  const countResult = await query(countSql, countValues);
  const total = (countResult as Loose[])[0]?.total || 0;

  const paginatedSql = `${sql} LIMIT ? OFFSET ?`;
  const paginatedValues = [...values, pageSize, (page - 1) * pageSize];

  const roles = await query<Role>(paginatedSql, paginatedValues);
  const formattedRoles = (roles as Loose[]).map(formatRole);

  return successResponse({
    list: formattedRoles,
    total,
    page,
    pageSize,
  });
});

// POST - 创建角色
export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body: Role = await request.json();

    // 验证必填字段
    const validation = validateRequestBody(body, ['role_code', 'role_name']);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    // 检查编码是否已存在
    const existing = await queryOne<{ id: number }>(
      'SELECT id FROM sys_role WHERE role_code = ? AND deleted = 0',
      [body.role_code]
    );

    if (existing) {
      return errorResponse('角色编码已存在', 409, 409);
    }

    const permissions =
      typeof body.permissions === 'object' ? JSON.stringify(body.permissions) : body.permissions;

    const result = await execute(
      `INSERT INTO sys_role (role_code, role_name, description, data_scope, status, permissions)
     VALUES (?, ?, ?, ?, ?, ?)`,
      [
        body.role_code,
        body.role_name,
        body.description ?? null,
        body.data_scope ?? 1,
        body.status ?? 1,
        permissions ?? null,
      ]
    );

    return successResponse({ id: result.insertId }, '角色创建成功');
