﻿import { NextRequest } from 'next/server';
import { query, execute, transaction } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const issueNo = searchParams.get('issueNo') || '';
  const outsourceOrderNo = searchParams.get('outsourceOrderNo') || '';
  const status = searchParams.get('status') || '';

  let where = 'WHERE i.deleted = 0';
  const params: Loose[] = [];
  if (issueNo) {
    where += ' AND i.issue_no LIKE ?';
    params.push('%' + issueNo + '%');
  }
  if (outsourceOrderNo) {
    where += ' AND i.outsource_order_no LIKE ?';
    params.push('%' + outsourceOrderNo + '%');
  }
  if (status) {
    where += ' AND i.status = ?';
    params.push(Number(status));
  }

  const totalRows: Loose = await query(
    'SELECT COUNT(*) as total FROM outsource_issue i ' + where,
    params
  );
  const total = totalRows[0]?.total || 0;
  const rows: Loose = await query(
    'SELECT i.*, w.warehouse_name FROM outsource_issue i LEFT JOIN inv_warehouse w ON i.warehouse_id = w.id ' +
      where +
      ' ORDER BY i.create_time DESC LIMIT ? OFFSET ?',
    [...params, pageSize, (page - 1) * pageSize]
  );

  for (const row of rows) {
    const items: Loose = await query('SELECT * FROM outsource_issue_item WHERE issue_id = ?', [
      row.id,
    ]);
    row.items = items;
  }

  return successResponse({ list: rows, total, page, pageSize });
});

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const {
      outsource_order_id,
      outsource_order_no,
      warehouse_id,
      issue_date,
      operator_name,
      remark,
      items,
    } = body;

    if (!outsource_order_id) return errorResponse('委外订单不能为空', 400, 400);
    if (!warehouse_id) return errorResponse('仓库不能为空', 400, 400);

    const now = new Date();
    const issueNo =
      'OI' +
      now.getFullYear() +
      String(now.getMonth() + 1).padStart(2, '0') +
      String(now.getDate()).padStart(2, '0') +
      String(Math.floor(Math.random() * 10000)).padStart(4, '0');

    const result: Loose = await execute(
      `INSERT INTO outsource_issue (issue_no, outsource_order_id, outsource_order_no, warehouse_id, issue_date, status, operator_name, remark)
     VALUES (?, ?, ?, ?, ?, 1, ?, ?)`,
      [
        issueNo,
        outsource_order_id,
        outsource_order_no || null,
        warehouse_id,
        issue_date || null,
        operator_name || null,
        remark || null,
      ]
    );

    if (items && Array.isArray(items)) {
      for (const item of items) {
        await execute(
          'INSERT INTO outsource_issue_item (issue_id, material_id, material_code, material_name, quantity, unit, batch_no) VALUES (?, ?, ?, ?, ?, ?, ?)',
