  const pageSize = parseInt(searchParams.get('pageSize') || '20');

  let sql = `SELECT * FROM prd_die_template WHERE deleted = 0`;
  const values: Loose[] = [];

  if (keyword) {
    sql += ' AND (template_code LIKE ? OR template_name LIKE ? OR qr_code LIKE ?)';
    const like = `%${keyword}%`;
    values.push(like, like, like);
