import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { transaction } from '@/lib/db';
import {
  explodeBOM,
  calculateTimeBuckets,
  calculateNetRequirements,
  runFullMRP,
} from '@/lib/mrp-engine';

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { work_order_ids, warehouse_id, auto_generate_pr = false } = body;

    if (!work_order_ids || !Array.isArray(work_order_ids) || work_order_ids.length === 0) {
      return errorResponse('请提供工单ID列表', 400, 400);
    }

    const result = await transaction(async (conn) => {
      return await runFullMRP(
        conn,
        work_order_ids,
        warehouse_id || 1,
        null,
        'system',
        auto_generate_pr
      );
    });

    return successResponse(result);
  },
  { logTitle: '运行MRP', logType: 'business' }
);

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const action = searchParams.get('action');

  if (action === 'bom-explode') {
    const productId = parseInt(searchParams.get('product_id') || '0');
    const quantity = parseFloat(searchParams.get('quantity') || '1');
    if (!productId) return errorResponse('请提供产品ID', 400, 400);
    const result = await transaction(async (conn) => {
      return await explodeBOM(conn, productId, quantity);
    });
    return successResponse(result);
  }

  if (action === 'time-buckets') {
    const materialId = parseInt(searchParams.get('material_id') || '0');
    const warehouseId = parseInt(searchParams.get('warehouse_id') || '1');
    const startDate = searchParams.get('start_date') || new Date().toISOString().slice(0, 10);
    const endDate =
      searchParams.get('end_date') ||
      new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10);
    const bucketSize = (searchParams.get('bucket_size') || 'week') as 'day' | 'week' | 'month';
    if (!materialId) return errorResponse('请提供物料ID', 400, 400);
    const result = await transaction(async (conn) => {
      return await calculateTimeBuckets(
        conn,
        materialId,
        warehouseId,
        startDate,
        endDate,
        bucketSize
      );
    });
    return successResponse(result);
  }

  if (action === 'net-requirements') {
    const idsStr = searchParams.get('work_order_ids') || '';
    const warehouseId = parseInt(searchParams.get('warehouse_id') || '1');
    const workOrderIds = idsStr
      .split(',')
      .map(Number)
      .filter((n) => n > 0);
    if (workOrderIds.length === 0) return errorResponse('请提供工单ID列表', 400, 400);
    const result = await transaction(async (conn) => {
      return await calculateNetRequirements(conn, workOrderIds, warehouseId);
    });
    return successResponse(result);
  }

  return errorResponse('未知操作', 400, 400);
});

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const pageSize = parseInt(searchParams.get('pageSize') || '20');
  const page = parseInt(searchParams.get('page') || '1');
  const keyword = searchParams.get('keyword');
  const status = searchParams.get('status');

  let sql = `
    SELECT wo.*
    FROM prod_work_order wo
    WHERE wo.deleted = 0
  `;
  const values: Loose[] = [];

  if (keyword) {
    sql += ` AND (wo.work_order_no LIKE ? OR wo.product_name LIKE ?)`;
    const likeKeyword = `%${keyword}%`;
    values.push(likeKeyword, likeKeyword);
  }

  if (status) {
    sql += ` AND wo.status = ?`;
    values.push(status);
  }

  sql += ` ORDER BY wo.create_time DESC LIMIT ? OFFSET ?`;
  values.push(pageSize, (page - 1) * pageSize);

  const orders = await query(sql, values);

  const result = (orders as Loose[]).map((order: Loose) => ({
    id: order.id,
    work_order_no: order.work_order_no,
    order_id: order.sales_order_id,
    order_no: order.order_no,
    product_name: order.product_name,
    plan_qty: parseFloat(order.plan_qty || '0'),
    unit: order.unit,
    status: order.status,
    priority: order.priority,
    plan_start_date: order.plan_start_date,
    plan_end_date: order.plan_end_date,
    actual_start_date: order.actual_start_date,
    actual_end_date: order.actual_end_date,
    remark: order.remark,
    create_time: order.create_time,
    update_time: order.update_time,
  }));

  let countSql = `SELECT COUNT(*) as total FROM prod_work_order wo WHERE wo.deleted = 0`;
  const countValues: Loose[] = [];
  if (keyword) {
    countSql += ` AND (wo.work_order_no LIKE ? OR wo.product_name LIKE ?)`;
    countValues.push(`%${keyword}%`, `%${keyword}%`);
  }
  if (status) {
    countSql += ` AND wo.status = ?`;
    countValues.push(status);
  }
  const countResult = await query(countSql, countValues);
  const total = (countResult as Loose[])[0]?.total || 0;

  return successResponse({
    list: result,
    total,
    page,
    pageSize,
  });
});

import { NextRequest } from 'next/server';
