﻿import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const startDate = searchParams.get('startDate');
  const endDate = searchParams.get('endDate');

  // 1. 获取各车间设备数量与总产能
  const equipmentRows: Loose = await query(
    `SELECT 
      workshop,
      equipment_type,
      COUNT(*) as equipment_count,
      SUM(capacity_per_hour) as total_capacity_per_hour
    FROM eqp_equipment
    WHERE deleted = 0 AND status = 'available'
    GROUP BY workshop, equipment_type
    ORDER BY workshop`
  );

  // 2. 获取排程占用情况
  let scheduleFilter = '';
  const scheduleParams: Loose[] = [];
  if (startDate && endDate) {
    scheduleFilter = ' AND planned_start >= ? AND planned_end <= ?';
    scheduleParams.push(startDate, endDate);
  }

  const scheduleRows: Loose = await query(
    `SELECT 
      workshop,
      COUNT(*) as schedule_count,
      COALESCE(SUM(planned_qty), 0) as total_planned_qty,
      COALESCE(SUM(completed_qty), 0) as total_completed_qty,
      COALESCE(SUM(TIMESTAMPDIFF(HOUR, planned_start, planned_end)), 0) as total_planned_hours
    FROM prd_schedule
    WHERE deleted = 0 AND status IN (2, 3) ${scheduleFilter}
    GROUP BY workshop`,
    scheduleParams
  );

  // 3. 按设备统计占用
  const equipmentUsageRows: Loose = await query(
    `SELECT 
      e.id as equipment_id,
      e.equipment_name,
      e.equipment_type,
      e.workshop,
      e.capacity_per_hour,
      COUNT(sd.id) as schedule_count,
      COALESCE(SUM(TIMESTAMPDIFF(HOUR, sd.planned_start, sd.planned_end)), 0) as used_hours
    FROM eqp_equipment e
    LEFT JOIN prd_schedule_detail sd ON e.id = sd.equipment_id 
      AND sd.status IN (2, 3) ${scheduleFilter ? 'AND sd.planned_start >= ? AND sd.planned_end <= ?' : ''}
    WHERE e.deleted = 0 AND e.status = 'available'
    GROUP BY e.id, e.equipment_name, e.equipment_type, e.workshop, e.capacity_per_hour
    ORDER BY e.workshop, e.equipment_type`,
    scheduleFilter ? [startDate, endDate] : []
  );

  // 4. 组装车间级产能数据
  const workshopMap = new Map();

  for (const row of equipmentRows) {
    const key = row.workshop;
    if (!workshopMap.has(key)) {
      workshopMap.set(key, {
        workshop: row.workshop,
        equipmentCount: 0,
        totalCapacity: 0,
        usedCapacity: 0,
        availableCapacity: 0,
        utilizationRate: 0,
      });
    }
    const item = workshopMap.get(key);
    item.equipmentCount += row.equipment_count;
    // 假设每天8小时，计算日产能
    item.totalCapacity += row.total_capacity_per_hour * 8;
  }

  // 计算已用产能（基于排程小时数）
  for (const row of scheduleRows) {
    const item = workshopMap.get(row.workshop);
    if (item) {
      // 已用产能 = 已排程小时数 * 平均产能
      item.usedCapacity = row.total_planned_hours * 100; // 简化计算
      item.availableCapacity = Math.max(0, item.totalCapacity - item.usedCapacity);
      item.utilizationRate =
        item.totalCapacity > 0 ? Math.round((item.usedCapacity / item.totalCapacity) * 100) : 0;
    }
  }

  // 设备级利用率
  const equipmentUtilization = equipmentUsageRows.map((row: Loose) => {
    const dailyCapacity = row.capacity_per_hour * 8;
    const utilizationRate = dailyCapacity > 0 ? Math.round((row.used_hours / 8) * 100) : 0;
    return {
      equipmentId: row.equipment_id,
      equipmentName: row.equipment_name,
      equipmentType: row.equipment_type,
      workshop: row.workshop,
      capacityPerHour: row.capacity_per_hour,
      scheduleCount: row.schedule_count,
      usedHours: row.used_hours,
      utilizationRate: Math.min(100, utilizationRate),
    };
  });

  const capacityData = Array.from(workshopMap.values());

  return successResponse(
    {
      workshopCapacity: capacityData,
      equipmentUtilization,
      summary: {
        totalEquipment: equipmentRows.reduce((sum: number, r: Loose) => sum + r.equipment_count, 0),
        totalWorkshops: workshopMap.size,
        avgUtilization:
          capacityData.length > 0
            ? Math.round(
                capacityData.reduce((sum: number, c: Loose) => sum + c.utilizationRate, 0) /
                  capacityData.length
              )
            : 0,
      },
    },
    '获取产能分析成功'
  );
});

import { NextRequest } from 'next/server';
import { query, execute, transaction } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { autoSchedule, getCapacityLoad, type SchedulingResult } from '@/lib/production-scheduling';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);

  // 自动排产：基于优先级评分 + 物料可用性 + 日期冲突检测，生成排产建议
  if (searchParams.get('action') === 'auto-schedule') {
    const workOrderIds = searchParams
      .get('work_order_ids')
      ?.split(',')
      .map(Number)
      .filter((n) => Number.isFinite(n) && n > 0);
    const warehouseId = Number(searchParams.get('warehouse_id') || 0);
    const startDate = searchParams.get('start_date') || undefined;

    const results = await autoSchedule({
      workOrderIds: workOrderIds?.length ? workOrderIds : undefined,
      warehouseId: warehouseId || undefined,
      startDate,
    });

    return successResponse({
      scheduled_count: results.length,
      ready_count: results.filter((r) => r.material_ready).length,
      shortage_count: results.filter((r) => !r.material_ready).length,
      results,
    });
  }

  // 产能负荷：按日期范围查询各工作日的排产负荷
  if (searchParams.get('action') === 'capacity-load') {
    const startDate = searchParams.get('start_date') || new Date().toISOString().slice(0, 10);
    const endDate =
      searchParams.get('end_date') ||
      new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10);

    const results = await getCapacityLoad({ startDate, endDate });
    return successResponse({
      date_range: { start: startDate, end: endDate },
      total_working_days: results.length,
      overloaded_days: results.filter((r) => r.loadPercentage > 100).length,
      results,
    });
  }

  if (searchParams.get('action') === 'stats') {
    const statsRows: Loose = await query(
      `SELECT 
        COUNT(*) as total,
        SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END) as pending,
        SUM(CASE WHEN status = 2 THEN 1 ELSE 0 END) as scheduled,
        SUM(CASE WHEN status = 3 THEN 1 ELSE 0 END) as producing,
        SUM(CASE WHEN status = 4 THEN 1 ELSE 0 END) as completed,
        SUM(CASE WHEN status = 5 THEN 1 ELSE 0 END) as cancelled,
        COALESCE(SUM(planned_qty), 0) as total_planned_qty,
        COALESCE(SUM(completed_qty), 0) as total_completed_qty
      FROM prd_schedule WHERE deleted = 0`
    );
    return successResponse(statsRows[0]);
  }

  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const workshop = searchParams.get('workshop') || '';
  const status = searchParams.get('status') || '';

  let where = 'WHERE deleted = 0';
  const params: Loose[] = [];
  if (workshop) {
    where += ' AND workshop = ?';
    params.push(workshop);
  }
  if (status !== '') {
    where += ' AND status = ?';
    params.push(Number(status));
  }

  const totalRows: Loose = await query(
    'SELECT COUNT(*) as total FROM prd_schedule ' + where,
    params
  );
  const total = totalRows[0]?.total || 0;
  const rows: Loose = await query(
    'SELECT * FROM prd_schedule ' +
      where +
      ' ORDER BY planned_start ASC, priority ASC LIMIT ? OFFSET ?',
    [...params, pageSize, (page - 1) * pageSize]
  );
  return successResponse({ list: rows, total, page, pageSize });
});

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();

    // 应用排产建议：将 autoSchedule 的结果写回工单的计划日期
    if (body.action === 'apply-schedule') {
      const { scheduling_results } = body as {
        action: string;
        scheduling_results: SchedulingResult[];
      };

      if (!Array.isArray(scheduling_results) || scheduling_results.length === 0) {
        return errorResponse('排产结果不能为空', 400, 400);
      }

      const updated = await transaction(async (connection) => {
        let count = 0;
        for (const result of scheduling_results) {
          await connection.execute(
            `UPDATE prod_work_order
           SET plan_start_date = ?, plan_end_date = ?, status = 'released', update_time = NOW()
           WHERE id = ? AND deleted = 0 AND status IN ('pending', 'confirmed')`,
            [result.suggested_start_date, result.suggested_end_date, result.work_order_id]
          );
          count++;
        }
        return count;
      });

      return successResponse(
        { updated_count: updated },
        `排产结果应用成功，共更新 ${updated} 个工单`
      );
    }

    const {
      order_id,
      order_no,
      product_id,
      product_code,
      product_name,
      workshop,
      planned_qty,
      planned_start,
      planned_end,
      priority,
      scheduler,
      remark,
    } = body;

    if (!product_name) return errorResponse('产品名称不能为空', 400, 400);

    if (planned_start && planned_end && workshop) {
      const conflicts: Loose = await query(
        `SELECT id, schedule_no, product_name, planned_start, planned_end 
       FROM prd_schedule 
       WHERE workshop = ? AND deleted = 0 AND status IN (1, 2, 3)
       AND planned_start < ? AND planned_end > ?`,
        [workshop, planned_end, planned_start]
      );
      if (conflicts.length > 0) {
        return errorResponse(
          `排产冲突: 车间 ${workshop} 在 ${planned_start} ~ ${planned_end} 已有 ${conflicts.length} 个排产计划`,
          409,
          409
        );
      }
    }

    const now = new Date();
    const scheduleNo =
      'PS' +
      now.getFullYear() +
      String(now.getMonth() + 1).padStart(2, '0') +
      String(now.getDate()).padStart(2, '0') +
      String(Math.floor(Math.random() * 10000)).padStart(4, '0');

    const result: Loose = await execute(
      `INSERT INTO prd_schedule (schedule_no, order_id, order_no, product_id, product_code, product_name, workshop, planned_qty, planned_start, planned_end, priority, scheduler, remark)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        scheduleNo,
        order_id || null,
        order_no || null,
        product_id || null,
        product_code || null,
        product_name,
        workshop || 'die_cut',
        planned_qty || 0,
        planned_start || null,
        planned_end || null,
        priority || 2,
        scheduler || null,
        remark || null,
      ]
    );

    const scheduleId = result.insertId;

    // 如果指定了工单ID，同步更新工单状态和计划日期
    const workOrderId = body.work_order_id;
    if (workOrderId && scheduleId) {
      await execute(
        `UPDATE prod_work_order
         SET status = 'released', plan_start_date = ?, plan_end_date = ?, update_time = NOW()
         WHERE id = ? AND deleted = 0 AND status = 'pending'`,
        [planned_start || null, planned_end || null, workOrderId]
      );
      // 更新排产记录的工单关联
      await execute('UPDATE prd_schedule SET work_order_id = ? WHERE id = ?', [
        workOrderId,
        scheduleId,
      ]);
    }

    return successResponse({ id: scheduleId, schedule_no: scheduleNo }, '排产计划创建成功');
  },
  { logTitle: '创建排产计划', logType: 'business' }
);

export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { id, ...fields } = body;
    if (!id) return errorResponse('ID不能为空', 400, 400);

    const updateFields: string[] = [];
    const updateValues: Loose[] = [];
    const allowedFields = [
      'workshop',
      'planned_qty',
      'completed_qty',
      'planned_start',
      'planned_end',
      'actual_start',
      'actual_end',
      'priority',
      'status',
      'scheduler',
      'remark',
    ];
    for (const field of allowedFields) {
      if (fields[field] !== undefined) {
        updateFields.push(`${field} = ?`);
        updateValues.push(fields[field]);
      }
    }
    if (updateFields.length > 0) {
      await execute(
        `UPDATE prd_schedule SET ${updateFields.join(', ')} WHERE id = ? AND deleted = 0`,
        [...updateValues, id]
      );
    }
    return successResponse(null, '更新成功');
  },
  { logTitle: '更新排产计划', logType: 'business' }
);

export const DELETE = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    if (!id) return errorResponse('ID不能为空', 400, 400);

    // 查询排产记录，判断是否需要回退工单状态
    const schedule: Loose = await query(
      'SELECT work_order_id, status FROM prd_schedule WHERE id = ? AND deleted = 0',
      [id]
    );

    if (schedule.length > 0 && schedule[0].work_order_id && schedule[0].status === 2) {
      // 状态为2（已排产）的排产被删除时，回退工单状态为 pending
      await execute(
        `UPDATE prod_work_order
         SET status = 'pending', plan_start_date = NULL, plan_end_date = NULL, update_time = NOW()
         WHERE id = ? AND deleted = 0 AND status = 'released'`,
        [schedule[0].work_order_id]
      );
    }

    await execute('UPDATE prd_schedule SET deleted = 1 WHERE id = ?', [id]);
    return successResponse(null, '删除成功');
  },
  { logTitle: '删除排产计划', logType: 'business' }
);

import { NextRequest, NextResponse } from 'next/server';
import { query } from '@/lib/db';

// 获取生产排程统计信息
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const startDate = searchParams.get('startDate');
    const endDate = searchParams.get('endDate');

    let dateFilter = '';
    const params: Loose[] = [];

    if (startDate && endDate) {
      dateFilter = ' AND work_order_date BETWEEN ? AND ?';
      params.push(startDate, endDate);
    }

    // 总排程数
    const [totalResult] = await query(
      `SELECT COUNT(*) as count FROM prd_process_card WHERE deleted = 0${dateFilter}`,
      params
    );

    // 待排产数量
    const [pendingResult] = await query(
      `SELECT COUNT(*) as count FROM prd_process_card WHERE deleted = 0 AND burdening_status = 0${dateFilter}`,
      params
    );

    // 已排产数量
    const [scheduledResult] = await query(
      `SELECT COUNT(*) as count FROM prd_process_card WHERE deleted = 0 AND burdening_status = 1${dateFilter}`,
      params
    );

    // 生产中数量
    const [producingResult] = await query(
      `SELECT COUNT(*) as count FROM prd_process_card WHERE deleted = 0 AND burdening_status = 2${dateFilter}`,
      params
    );

    // 已完成数量
    const [completedResult] = await query(
      `SELECT COUNT(*) as count FROM prd_process_card WHERE deleted = 0 AND burdening_status = 3${dateFilter}`,
      params
    );

    // 计划总产量
    const [planQtyResult] = await query(
      `SELECT COALESCE(SUM(plan_qty), 0) as total FROM prd_process_card WHERE deleted = 0${dateFilter}`,
      params
    );

    // 按日期统计
    const dailyStats = await query(
      `SELECT 
        work_order_date as date,
        COUNT(*) as count,
        SUM(plan_qty) as planQty
      FROM prd_process_card 
      WHERE deleted = 0${dateFilter}
      GROUP BY work_order_date 
      ORDER BY work_order_date DESC 
      LIMIT 30`,
      params
    );

    return NextResponse.json({
      success: true,
      data: {
        total: totalResult.count,
        pending: pendingResult.count,
        scheduled: scheduledResult.count,
        producing: producingResult.count,
        completed: completedResult.count,
        planQty: planQtyResult.total,
        dailyStats,
      },
    });
  } catch {
    return NextResponse.json({ success: false, message: '获取排程统计失败' }, { status: 500 });
  }
}

import { NextRequest } from 'next/server';
import { query, transaction } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const sn = searchParams.get('sn');
  const batchNo = searchParams.get('batchNo');
  const workorderNo = searchParams.get('workorderNo');

  if (!sn && !batchNo && !workorderNo) {
    return errorResponse('请提供至少一个查询参数: sn, batchNo, workorderNo', 400, 400);
  }

  let traceLinks: Loose[] = [];

  if (sn) {
    traceLinks = await buildTraceChain(sn);
  } else if (batchNo) {
    const rows: Loose = await query(
      'SELECT sn FROM prd_product_trace_link WHERE material_batch = ? AND deleted = 0',
      [batchNo]
    );
    if (rows.length > 0) {
      traceLinks = await buildTraceChain(rows[0].sn);
    }
  } else if (workorderNo) {
    const rows: Loose = await query(
      'SELECT sn FROM prd_product_trace_link WHERE workorder_no = ? AND deleted = 0',
      [workorderNo]
    );
    if (rows.length > 0) {
      traceLinks = await buildTraceChain(rows[0].sn);
    }
  }

  return successResponse({
    traceLinks,
    totalLinks: traceLinks.length,
  });
});

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const {
      sn,
      parent_sn,
      material_batch,
      workorder_id,
      workorder_no,
      material_id,
      material_code,
      material_name,
      supplier_id,
      supplier_name,
      inbound_date,
      inbound_no,
      inspection_id,
      inspection_result,
      trace_level,
      trace_type,
    } = body;

    if (!sn) {
      return errorResponse('缺少必填字段: sn', 400, 400);
    }

    const result = await transaction(async (conn) => {
      const [existing]: Loose = await conn.execute(
        'SELECT id FROM prd_product_trace_link WHERE sn = ? AND material_batch = ? AND deleted = 0',
        [sn, material_batch || '']
      );

      if (existing.length > 0) {
        await conn.execute(
          `UPDATE prd_product_trace_link SET
          parent_sn = ?, workorder_id = ?, workorder_no = ?,
          material_id = ?, material_code = ?, material_name = ?,
          supplier_id = ?, supplier_name = ?,
          inbound_date = ?, inbound_no = ?,
          inspection_id = ?, inspection_result = ?,
          trace_level = ?, trace_type = ?
        WHERE id = ?`,
          [
            parent_sn || null,
            workorder_id || null,
            workorder_no || null,
            material_id || null,
            material_code || null,
            material_name || null,
            supplier_id || null,
            supplier_name || null,
            inbound_date || null,
            inbound_no || null,
            inspection_id || null,
            inspection_result || null,
            trace_level || 1,
            trace_type || 'product',
            existing[0].id,
          ]
        );
        return { id: existing[0].id, sn, updated: true };
      }

      const [insertResult]: Loose = await conn.execute(
        `INSERT INTO prd_product_trace_link (sn, parent_sn, material_batch, workorder_id, workorder_no, material_id, material_code, material_name, supplier_id, supplier_name, inbound_date, inbound_no, inspection_id, inspection_result, trace_level, trace_type)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          sn,
          parent_sn || null,
          material_batch || null,
          workorder_id || null,
          workorder_no || null,
          material_id || null,
          material_code || null,
          material_name || null,
          supplier_id || null,
          supplier_name || null,
          inbound_date || null,
          inbound_no || null,
          inspection_id || null,
          inspection_result || null,
          trace_level || 1,
          trace_type || 'product',
        ]
      );

      return { id: insertResult.insertId, sn, updated: false };
    });

    return successResponse(result, '追溯链记录创建成功');
  },
  { logTitle: '创建追溯链记录', logType: 'business' }
);

async function buildTraceChain(startSn: string): Promise<Loose[]> {
  const chain: Loose[] = [];
  const visited = new Set<string>();

  async function traverse(sn: string, level: number) {
    if (visited.has(sn)) return;
    visited.add(sn);

    const links: Loose = await query(
      'SELECT * FROM prd_product_trace_link WHERE sn = ? AND deleted = 0',
      [sn]
    );

    for (const link of links) {
      chain.push({
        level,
        sn: link.sn,
        parentSn: link.parent_sn,
        materialBatch: link.material_batch,
        workorderId: link.workorder_id,
        workorderNo: link.workorder_no,
        materialId: link.material_id,
        materialCode: link.material_code,
        materialName: link.material_name,
        supplierId: link.supplier_id,
        supplierName: link.supplier_name,
        inboundDate: link.inbound_date,
        inboundNo: link.inbound_no,
        inspectionId: link.inspection_id,
        inspectionResult: link.inspection_result,
        traceType: link.trace_type,
      });

      if (link.parent_sn) {
        await traverse(link.parent_sn, level + 1);
      }

      const childLinks: Loose = await query(
        'SELECT sn FROM prd_product_trace_link WHERE parent_sn = ? AND deleted = 0',
        [sn]
      );
      for (const child of childLinks) {
        await traverse(child.sn, level - 1);
      }
    }
  }

  await traverse(startSn, 0);
  return chain.sort((a, b) => a.level - b.level);
}

