// 获取产品列表
export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const keyword = searchParams.get('keyword') || '';
  const categoryId = searchParams.get('categoryId') || '';
  const status = searchParams.get('status') || '';
  const customerId = searchParams.get('customerId') || '';
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '10');

  // 基础查询SQL
  let sql = `
    SELECT
      p.id,
      p.product_code,
      p.product_name,
      p.short_name,
      p.specification,
      p.unit,
      p.category_id,
      p.category_name,
      p.customer_id,
      p.customer_name,
      p.bom_version,
      p.description,
      p.status,
      p.cost_price,
      p.sale_price,
      p.min_stock,
      p.max_stock,
      p.safety_stock,
      p.create_time,
      p.update_time
    FROM mdm_product p
    WHERE p.deleted = 0
  `;

  let countSql = `SELECT COUNT(*) as total FROM mdm_product p WHERE p.deleted = 0`;
  const params: Loose[] = [];

  if (keyword) {
    const keywordCondition = ` AND (p.product_code LIKE ? OR p.product_name LIKE ? OR p.short_name LIKE ?)`;
    sql += keywordCondition;
    countSql += keywordCondition;
    params.push(`%${keyword}%`, `%${keyword}%`, `%${keyword}%`);
  }

  if (categoryId) {
    sql += ` AND p.category_id = ?`;
    countSql += ` AND p.category_id = ?`;
    params.push(categoryId);
  }

  if (status) {
    sql += ` AND p.status = ?`;
    countSql += ` AND p.status = ?`;
    params.push(status);
  }

  if (customerId) {
    sql += ` AND p.customer_id = ?`;
    countSql += ` AND p.customer_id = ?`;
    params.push(customerId);
  }

  sql += ` ORDER BY p.create_time DESC`;

  // 使用分页查询工具
  const result = await queryPaginated(sql, countSql, params, { page, pageSize });

  return paginatedResponse(result.data, result.pagination);
});

