export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();

    // 验证必填字段
    const validation = validateRequestBody(body, ['productCode', 'productName', 'categoryId']);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    const {
      product_code,
      product_name,
      short_name,
      specification,
      unit,
      category_id,
      category_name,
      customer_id,
      customer_name,
      bom_version,
      description,
      cost_price,
      sale_price,
      min_stock,
      max_stock,
      safety_stock,
    } = body;

    const existingProducts = await query(
      'SELECT id FROM mdm_product WHERE product_code = ? AND deleted = 0',
      [product_code]
    );

    if ((existingProducts as Loose[]).length > 0) {
      return errorResponse('产品编码已存在', 400, 400);
    }

    const result = await query(
      `INSERT INTO mdm_product 
     (product_code, product_name, short_name, specification, unit, category_id, category_name, 
      customer_id, customer_name, bom_version, description, status, cost_price, sale_price, 
      min_stock, max_stock, safety_stock, create_time) 
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, ?, ?, ?, NOW())`,
      [
        product_code,
        product_name,
        short_name || '',
        specification || '',
        unit || '件',
        category_id,
        category_name || '',
        customer_id || null,
        customer_name || '',
        bom_version || 'V1.0',
        description || '',
        cost_price || 0,
        sale_price || 0,
        min_stock || 0,
        max_stock || 0,
        safety_stock || 0,
      ]
    );

    const insertId = (result as Loose).insertId;

    return successResponse({ id: insertId, product_code }, '产品创建成功');
  },
  { logTitle: '创建产品' }
);

// 更新产品
export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { id, ...updateData } = body;

    if (!id) {
      return errorResponse('产品ID不能为空', 400, 400);
    }

    // 查询产品
    const products = await query('SELECT * FROM mdm_product WHERE id = ? AND deleted = 0', [id]);

    if (!products || (products as Loose[]).length === 0) {
      return commonErrors.notFound('产品不存在');
    }

    const updateFields: string[] = [];
    const updateParams: Loose[] = [];

    const fieldMapping: { [key: string]: string } = {
      product_name: 'product_name',
      short_name: 'short_name',
      specification: 'specification',
      unit: 'unit',
      category_id: 'category_id',
      category_name: 'category_name',
      customer_id: 'customer_id',
      customer_name: 'customer_name',
      bom_version: 'bom_version',
      description: 'description',
      status: 'status',
      cost_price: 'cost_price',
      sale_price: 'sale_price',
      min_stock: 'min_stock',
      max_stock: 'max_stock',
      safety_stock: 'safety_stock',
    };

    for (const [key, value] of Object.entries(updateData)) {
      if (fieldMapping[key] && value !== undefined) {
        updateFields.push(`${fieldMapping[key]} = ?`);
        updateParams.push(value);
      }
    }

    if (updateFields.length === 0) {
      return errorResponse('没有要更新的字段', 400, 400);
    }

    updateParams.push(id);
    await query(
      `UPDATE mdm_product SET ${updateFields.join(', ')}, update_time = NOW() WHERE id = ?`,
      updateParams
    );

    return successResponse({ id }, '产品更新成功');
  },
  { logTitle: '更新产品' }
);

