    // 更新终检记录
    await query(
      `UPDATE qc_final_inspection 
     SET final_result = ?, qualified_qty = ?, defect_qty = ?, inspector = ?, remark = ?, updated_at = NOW()
     WHERE id = ?`,
      [finalResult, qualifiedQty, defectQty, inspector, remark, id]
    );

    // 更新流程卡状态
    if (finalResult === 'pass') {
      await query(
        `UPDATE prd_process_card SET burdening_status = 3, update_time = NOW() WHERE id = ?`,
        [id]
      );
    }

    return successResponse(null, '终检结果更新成功');
  },
  { logTitle: '更新终检记录', logType: 'business' }
);

import { NextRequest, NextResponse } from 'next/server';
import { query } from '@/lib/db';

// 获取终检统计
export async function GET(_request: NextRequest) {
  try {
    // 待终检数量（生产中的）
    const [pendingResult] = await query(
      `SELECT COUNT(*) as count FROM prd_process_card WHERE deleted = 0 AND burdening_status = 2`
    );

    // 终检中数量
    const [inspectingResult] = await query(
      `SELECT COUNT(*) as count FROM prd_process_card WHERE deleted = 0 AND burdening_status = 2`
    );

    // 终检合格数量
    const [passedResult] = await query(
      `SELECT COUNT(*) as count FROM prd_process_card WHERE deleted = 0 AND burdening_status = 3`
    );

    // 今日终检数量
    const [todayResult] = await query(
      `SELECT COUNT(*) as count 
       FROM inv_trace_record 
       WHERE trace_type = 9 AND DATE(create_time) = CURDATE()`
    );

    // 本周终检数量
    const [weekResult] = await query(
      `SELECT COUNT(*) as count 
       FROM inv_trace_record 
       WHERE trace_type = 9 AND create_time >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)`
    );

    // 合格率统计
    const [passRateResult] = await query(
      `SELECT 
        COUNT(*) as total,
        SUM(CASE WHEN burdening_status = 3 THEN 1 ELSE 0 END) as passed
      FROM prd_process_card 
      WHERE deleted = 0 AND burdening_status >= 2`
    );

    const passRate =
      passRateResult.total > 0
        ? Math.round((passRateResult.passed / passRateResult.total) * 100)
        : 0;

    return NextResponse.json({
      success: true,
      data: {
        pending: pendingResult.count,
        inspecting: inspectingResult.count,
        passed: passedResult.count,
        today: todayResult.count,
        week: weekResult.count,
        passRate,
      },
    });
  } catch {
    return NextResponse.json({ success: false, message: '获取终检统计失败' }, { status: 500 });
  }
}

import { NextRequest } from 'next/server';
import { query, execute, transaction, queryPaginated } from '@/lib/db';
import {
  successResponse,
  paginatedResponse,
  errorResponse,
  commonErrors,
  validateRequestBody,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

// 获取进料检验列表
export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const keyword = searchParams.get('keyword') || '';
  const status = searchParams.get('status') || '';
  const startDate = searchParams.get('startDate') || '';
  const endDate = searchParams.get('endDate') || '';
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '10');

  // 基础查询SQL
  let sql = `
    SELECT
      i.id,
      i.inspection_no as inspectionNo,
      i.inspection_date as inspectionDate,
      i.supplier_name as supplierName,
      i.material_code as materialCode,
      i.material_name as materialName,
      i.specification,
      i.batch_no as batchNo,
      i.quantity,
      i.unit,
      i.inspection_type as inspectionType,
      i.inspection_result as inspectionResult,
      i.inspector_name as inspectorName,
      i.remark,
      i.create_time as createTime
    FROM qc_incoming_inspection i
    WHERE i.deleted = 0
  `;

  let countSql = `SELECT COUNT(*) as total FROM qc_incoming_inspection i WHERE i.deleted = 0`;
  const params: Loose[] = [];

  if (keyword) {
    const keywordCondition = ` AND (i.inspection_no LIKE ? OR i.supplier_name LIKE ? OR i.material_name LIKE ? OR i.batch_no LIKE ?)`;
    sql += keywordCondition;
    countSql += keywordCondition;
    params.push(`%${keyword}%`, `%${keyword}%`, `%${keyword}%`, `%${keyword}%`);
  }

  if (status) {
    sql += ` AND i.inspection_result = ?`;
    countSql += ` AND i.inspection_result = ?`;
    params.push(status);
  }

  if (startDate) {
    sql += ` AND i.inspection_date >= ?`;
    countSql += ` AND i.inspection_date >= ?`;
    params.push(startDate);
  }

  if (endDate) {
    sql += ` AND i.inspection_date <= ?`;
    countSql += ` AND i.inspection_date <= ?`;
    params.push(endDate);
  }

  sql += ` ORDER BY i.create_time DESC`;

  // 使用分页查询工具
  const result = await queryPaginated(sql, countSql, params, { page, pageSize });

  // 获取每个检验单的明细
  if (result.data.length > 0) {
    const inspectionIds = result.data.map((i: Loose) => i.id);
    const placeholders = inspectionIds.map(() => '?').join(',');

    const items = await query(
      `SELECT
        id,
        inspection_id as inspectionId,
        item_name as itemName,
        standard,
        actual_value as actualValue,
        result,
        remark as itemRemark
      FROM qc_incoming_inspection_item
      WHERE inspection_id IN (${placeholders}) AND deleted = 0`,
      inspectionIds
    );

    // 将明细分组到对应的检验单
    const itemsMap = new Map();
    for (const item of items as Loose[]) {
      if (!itemsMap.has(item.inspectionId)) {
        itemsMap.set(item.inspectionId, []);
      }
      itemsMap.get(item.inspectionId).push(item);
    }

    for (const inspection of result.data as Loose[]) {
      inspection.items = itemsMap.get(inspection.id) || [];
    }
  }

  return paginatedResponse(result.data, result.pagination);
});

// 创建进料检验单
export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();

    // 验证必填字段
    const validation = validateRequestBody(body, [
      'inspectionDate',
      'supplierName',
      'materialCode',
      'materialName',
      'specification',
      'batchNo',
      'quantity',
      'unit',
      'inspectionType',
      'inspectionResult',
      'inspectorName',
    ]);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    const {
      inspectionDate,
      supplierName,
      materialCode,
      materialName,
      specification,
      batchNo,
      quantity,
      unit,
      inspectionType,
      inspectionResult,
      inspectorName,
      remark,
      items,
    } = body;

    // 使用事务确保数据一致性
    const result = await transaction(async (connection) => {
      // 生成检验单号
      const date = new Date();
      const dateStr = date.toISOString().slice(0, 10).replace(/-/g, '');
      const [maxInspection] = await connection.query(
        `SELECT MAX(inspection_no) as maxNo FROM qc_incoming_inspection WHERE inspection_no LIKE ?`,
        [`IQC${dateStr}%`]
      );
      const maxNo = (maxInspection as Loose[])[0]?.maxNo;
      const seq = maxNo ? String(parseInt(maxNo.slice(-3)) + 1).padStart(3, '0') : '001';
      const inspectionNo = `IQC${dateStr}${seq}`;

      // 插入检验单主表
      const [insertResult] = (await connection.execute(
        `INSERT INTO qc_incoming_inspection (
        inspection_no, inspection_date, supplier_name,
        material_code, material_name, specification,
        batch_no, quantity, unit, inspection_type,
        inspection_result, inspector_name, remark
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          inspectionNo,
          inspectionDate,
          supplierName,
          materialCode,
          materialName,
          specification,
          batchNo,
          quantity,
          unit,
          inspectionType,
          inspectionResult,
          inspectorName,
          remark,
        ]
      )) as [Loose[], Loose];

      const inspectionId = (insertResult as Loose).insertId;

      // 批量插入检验单明细
      if (items && items.length > 0) {
        const itemValues = items.map((item: Loose) => [
          inspectionId,
          inspectionNo,
          item.itemName,
          item.standard,
          item.actualValue,
          item.result,
          item.itemRemark,
        ]);

        await connection.query(
          `INSERT INTO qc_incoming_inspection_item (
          inspection_id, inspection_no, item_name,
          standard, actual_value, result, remark
        ) VALUES ?`,
          [itemValues]
        );
      }

      return { id: inspectionId, inspectionNo, inspectionResult };
    });

    if (result.inspectionResult === 'qualified' || result.inspectionResult === '合格') {
      await transaction(async (conn) => {
        await conn.execute(
          `UPDATE inv_inventory_batch SET status = 'normal', freeze_reason = NULL, inspection_id = ? WHERE batch_no = ? AND deleted = 0`,
          [result.id, batchNo]
        );
        await conn.execute(
          `UPDATE inv_inbound_order o INNER JOIN qrcode_record q ON o.order_no = q.ref_no SET o.inspection_status = 1, o.inspection_id = ? WHERE q.batch_no = ? AND q.qr_type = 'material' AND q.deleted = 0 AND o.deleted = 0`,
          [result.id, batchNo]
        );
      }).catch(() => {});
    } else if (result.inspectionResult === 'unqualified' || result.inspectionResult === '不合格') {
      await transaction(async (conn) => {
        await conn.execute(
          `UPDATE inv_inventory_batch SET status = 'frozen', freeze_reason = '进料检验不合格', inspection_id = ? WHERE batch_no = ? AND deleted = 0`,
          [result.id, batchNo]
        );
        await conn.execute(
          `UPDATE inv_inbound_order o INNER JOIN qrcode_record q ON o.order_no = q.ref_no SET o.inspection_status = 2, o.inspection_id = ? WHERE q.batch_no = ? AND q.qr_type = 'material' AND q.deleted = 0 AND o.deleted = 0`,
          [result.id, batchNo]
        );
      }).catch(() => {});
    }

    return successResponse(result, '进料检验单创建成功');
  },
  { logTitle: '创建进料检验单', logType: 'business' }
);

// 更新进料检验单
export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { id, ...updateData } = body;

    if (!id) {
      return commonErrors.badRequest('检验单ID不能为空');
    }

    // 检查检验单是否存在
    const [inspection] = await query<{ id: number }>(
      'SELECT id FROM qc_incoming_inspection WHERE id = ? AND deleted = 0',
      [id]
    );

    if (!inspection) {
      return commonErrors.notFound('检验单不存在');
    }

    await execute(
      `UPDATE qc_incoming_inspection SET
      inspection_date = ?,
      supplier_name = ?,
      material_code = ?,
      material_name = ?,
      specification = ?,
      batch_no = ?,
      quantity = ?,
      unit = ?,
      inspection_type = ?,
      inspection_result = ?,
      inspector_name = ?,
      remark = ?
    WHERE id = ?`,
      [
        updateData.inspectionDate,
        updateData.supplierName,
        updateData.materialCode,
        updateData.materialName,
        updateData.specification,
        updateData.batchNo,
        updateData.quantity,
        updateData.unit,
        updateData.inspectionType,
        updateData.inspectionResult,
        updateData.inspectorName,
        updateData.remark,
        id,
      ]
    );

    if (updateData.inspectionResult === 'qualified' || updateData.inspectionResult === '合格') {
      await transaction(async (conn) => {
        await conn.execute(
          `UPDATE inv_inventory_batch SET status = 'normal', freeze_reason = NULL, inspection_id = ? WHERE batch_no = ? AND deleted = 0`,
          [id, updateData.batchNo]
        );
        await conn.execute(
          `UPDATE inv_inbound_order o INNER JOIN qrcode_record q ON o.order_no = q.ref_no SET o.inspection_status = 1, o.inspection_id = ? WHERE q.batch_no = ? AND q.qr_type = 'material' AND q.deleted = 0 AND o.deleted = 0`,
          [id, updateData.batchNo]
        );
      }).catch(() => {});
    } else if (
      updateData.inspectionResult === 'unqualified' ||
      updateData.inspectionResult === '不合格'
    ) {
      await transaction(async (conn) => {
        await conn.execute(
          `UPDATE inv_inventory_batch SET status = 'frozen', freeze_reason = '进料检验不合格', inspection_id = ? WHERE batch_no = ? AND deleted = 0`,
          [id, updateData.batchNo]
        );
        await conn.execute(
          `UPDATE inv_inbound_order o INNER JOIN qrcode_record q ON o.order_no = q.ref_no SET o.inspection_status = 2, o.inspection_id = ? WHERE q.batch_no = ? AND q.qr_type = 'material' AND q.deleted = 0 AND o.deleted = 0`,
          [id, updateData.batchNo]
        );
      }).catch(() => {});
    }

    // 更新检验单明细
    if (updateData.items && updateData.items.length > 0) {
      // 先删除原有的明细
      await execute('UPDATE qc_incoming_inspection_item SET deleted = 1 WHERE inspection_id = ?', [
        id,
      ]);

      // 插入新的明细
      const itemValues = updateData.items.map((item: Loose) => [
        id,
        updateData.inspectionNo,
        item.itemName,
        item.standard,
        item.actualValue,
        item.result,
        item.itemRemark,
      ]);

      await execute(
        `INSERT INTO qc_incoming_inspection_item (
        inspection_id, inspection_no, item_name,
        standard, actual_value, result, remark
      ) VALUES ?`,
        [itemValues]
      );
    }

    return successResponse(null, '进料检验单更新成功');
  },
  { logTitle: '更新进料检验单', logType: 'business' }
);

// 删除进料检验单（软删除）
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return commonErrors.badRequest('检验单ID不能为空');
    }

    // 检查检验单是否存在
    const [inspection] = await query<{ id: number }>(
      'SELECT id FROM qc_incoming_inspection WHERE id = ? AND deleted = 0',
      [id]
    );

    if (!inspection) {
      return commonErrors.notFound('检验单不存在');
    }

    // 使用事务同时更新主表和明细表
    await transaction(async (connection) => {
      await connection.execute('UPDATE qc_incoming_inspection SET deleted = 1 WHERE id = ?', [id]);
      await connection.execute(
        'UPDATE qc_incoming_inspection_item SET deleted = 1 WHERE inspection_id = ?',
        [id]
      );
    });

    return successResponse(null, '进料检验单删除成功');
  },
  { logTitle: '删除进料检验单', logType: 'business' }
);

import { NextRequest } from 'next/server';
import { query, execute } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { AQLService } from '@/lib/aql-service';

export const POST = withPermission(async (request: NextRequest, userInfo) => {
  const { materialId, materialName, batchNo, lotSize, inspectionType, inspectionId } =
    await request.json();

  if (!materialId || !batchNo || !lotSize) {
    return errorResponse('缺少必填参数: materialId, batchNo, lotSize', 400, 400);
  }

  // 1. Query AQL sampling plan
  const aql = new AQLService();
  const plan = await aql.getSamplingPlan(Number(lotSize));

  if (!plan) {
    return errorResponse(`未找到批量 ${lotSize} 对应的 AQL 抽样方案`, 400, 400);
  }

  // 2. Generate lab test number
  const seqResult = await query<{ seq: number }>(
    `SELECT COALESCE(MAX(CAST(SUBSTRING(lab_test_no, 10) AS UNSIGNED)), 0) + 1 as seq
     FROM qms_lab_test WHERE lab_test_no LIKE CONCAT('LAB-', DATE_FORMAT(NOW(), '%Y%m%d'), '%')`
  );
  const seq = seqResult[0]?.seq || 1;
  const labTestNo = `LAB-${new Date().toISOString().slice(0, 10).replace(/-/g, '')}-${String(seq).padStart(4, '0')}`;

  // 3. Insert lab test record
  const result = await execute(
    `INSERT INTO qms_lab_test (lab_test_no, material_id, material_name, batch_no, inspection_type,
       sample_size, accept_qty, reject_qty, aql_level, inspection_standard, status,
       inspection_id, create_by, create_time, update_time, deleted)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?, NOW(), NOW(), 0)`,
    [
      labTestNo,
      Number(materialId),
      materialName || null,
      batchNo,
      inspectionType || 'incoming',
      plan.sampleSize,
      plan.acceptQty,
      plan.rejectQty,
      plan.aqlLevel,
      'GB/T 2828.1',
      inspectionId || null,
      userInfo.userId,
    ]
  );

  return successResponse({
    labTestNo,
    sampleSize: plan.sampleSize,
    acceptQty: plan.acceptQty,
    rejectQty: plan.rejectQty,
    aqlLevel: plan.aqlLevel,
    insertId: result.insertId,
  });
});

﻿import { NextRequest } from 'next/server';
import { query, execute } from '@/lib/db';
