export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const testNo = searchParams.get('testNo') || '';
  const productName = searchParams.get('productName') || '';
  const testType = searchParams.get('testType') || '';
  const status = searchParams.get('status') || '';

  let where = 'WHERE deleted = 0';
  const params: Loose[] = [];
  if (testNo) {
    where += ' AND test_no LIKE ?';
    params.push('%' + testNo + '%');
  }
  if (productName) {
    where += ' AND product_name LIKE ?';
    params.push('%' + productName + '%');
  }
  if (testType) {
    where += ' AND test_type = ?';
    params.push(testType);
  }
  if (status !== '') {
    where += ' AND status = ?';
    params.push(Number(status));
  }

  const totalRows: Loose = await query(
    'SELECT COUNT(*) as total FROM qms_lab_test ' + where,
    params
  );
  const total = totalRows[0]?.total || 0;
  const rows: Loose = await query(
    'SELECT * FROM qms_lab_test ' + where + ' ORDER BY create_time DESC LIMIT ? OFFSET ?',
    [...params, pageSize, (page - 1) * pageSize]
  );
  return successResponse({ list: rows, total, page, pageSize });
});

