export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const auditNo = searchParams.get('auditNo') || '';
  const supplierName = searchParams.get('supplierName') || '';
  const auditType = searchParams.get('auditType') || '';
  const status = searchParams.get('status') || '';

  let where = 'WHERE deleted = 0';
  const params: Loose[] = [];
  if (auditNo) {
    where += ' AND audit_no LIKE ?';
    params.push('%' + auditNo + '%');
  }
  if (supplierName) {
    where += ' AND supplier_name LIKE ?';
    params.push('%' + supplierName + '%');
  }
  if (auditType) {
    where += ' AND audit_type = ?';
    params.push(auditType);
  }
  if (status !== '') {
    where += ' AND status = ?';
    params.push(Number(status));
  }

  const totalRows: Loose = await query(
    'SELECT COUNT(*) as total FROM qms_supplier_audit ' + where,
    params
  );
  const total = totalRows[0]?.total || 0;
  const rows: Loose = await query(
    'SELECT * FROM qms_supplier_audit ' + where + ' ORDER BY create_time DESC LIMIT ? OFFSET ?',
    [...params, pageSize, (page - 1) * pageSize]
  );
  return successResponse({ list: rows, total, page, pageSize });
});

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const {
      supplier_id,
      supplier_name,
      audit_type,
      audit_date,
      auditor,
      audit_scope,
      quality_system_score,
      delivery_score,
      price_score,
      service_score,
      total_score,
      audit_result,
      improvement_items,
      follow_up_date,
      remark,
    } = body;

    if (!supplier_name) return errorResponse('供应商名称不能为空', 400, 400);

    const now = new Date();
    const auditNo =
      'SA' +
      now.getFullYear() +
      String(now.getMonth() + 1).padStart(2, '0') +
      String(now.getDate()).padStart(2, '0') +
      String(Math.floor(Math.random() * 10000)).padStart(4, '0');

    const result: Loose = await execute(
      `INSERT INTO qms_supplier_audit (audit_no, supplier_id, supplier_name, audit_type, audit_date, auditor, audit_scope, quality_system_score, delivery_score, price_score, service_score, total_score, audit_result, improvement_items, follow_up_date, remark)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        auditNo,
        supplier_id || null,
        supplier_name,
        audit_type || 'initial',
        audit_date || null,
        auditor || null,
        audit_scope || null,
        quality_system_score || 0,
        delivery_score || 0,
        price_score || 0,
        service_score || 0,
        total_score || 0,
        audit_result || 'pending',
        improvement_items || null,
        follow_up_date || null,
        remark || null,
      ]
    );

    return successResponse({ id: result.insertId, audit_no: auditNo }, '供应商审核记录创建成功');
  },
  { logTitle: '创建供应商审核记录', logType: 'business' }
);

