import { NextRequest, NextResponse } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UnqualifiedApplicationService } from '@/application/services/UnqualifiedApplicationService';
import { MysqlUnqualifiedRepository } from '@/infrastructure/repositories/MysqlUnqualifiedRepository';
import {
  DomainError,
  NotFoundError,
  VersionConflictError,
} from '@/domain/shared/DomainTypes';

const service = new UnqualifiedApplicationService(new MysqlUnqualifiedRepository());

function isHandleMethodValue(value: unknown): value is 'rework' | 'scrap' | 'concession' | 'return' {
  return value === 'rework' || value === 'scrap' || value === 'concession' || value === 'return';
}

function domainErrorToResponse(e: DomainError): NextResponse {
  if (e instanceof NotFoundError) {
    return errorResponse(e.message, 404);
  }
  if (e instanceof VersionConflictError) {
    return errorResponse(e.message, 409);
  }
  return errorResponse(e.message, 422);
}

export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const status = searchParams.get('status') || 'all';
  const keyword = searchParams.get('keyword') || searchParams.get('handleNo') || '';
  const handleType = searchParams.get('handleType')
    ? Number(searchParams.get('handleType'))
    : undefined;
  const handleStatus = searchParams.get('handleStatus')
    ? Number(searchParams.get('handleStatus'))
    : undefined;
  const startDate = searchParams.get('startDate') || undefined;
  const endDate = searchParams.get('endDate') || undefined;

  const result = await service.listRecords(status, { page, pageSize }, {
    keyword: keyword || undefined,
    handleType,
    handleStatus,
    startDate,
    endDate,
  });

  const list = result.data.map((record) => ({
    id: record.id,
    unqualified_no: record.unqualifiedNo,
    handle_no: record.handleNo,
    inspection_id: record.inspectionId,
    source_type: record.sourceType,
    source_no: record.sourceNo,
    material_id: record.materialId,
    material_code: record.materialCode,
    material_name: record.materialName,
    quantity: record.quantity,
    defect_type: record.defectType,
    defect_desc: record.defectDesc,
    handle_type: record.handleType?.toDbCode() ?? null,
    handle_status: record.status.toDbCode(),
    handle_result: record.handleResult ?? null,
    responsible_dept: record.responsibleDept,
    responsible_person: record.responsiblePerson,
    cost_amount: record.costAmount,
    handler: record.handler,
    handle_date: record.handleDate,
    remark: record.remark,
    create_time: record.createTime,
    update_time: record.updateTime,
    create_by: record.createBy,
    update_by: record.updateBy,
  }));

  return successResponse({
    list,
    total: result.pagination.total,
    page: result.pagination.page,
    pageSize: result.pagination.pageSize,
    totalPages: result.pagination.totalPages,
  });
}, { logTitle: '查询不合格品列表' });

export const POST = withPermission(async (request: NextRequest, userInfo) => {
  try {
    const body = await request.json();
    const {
      inspection_id,
      source_type,
      source_no,
      material_id,
      material_code,
      material_name,
      quantity,
      defect_type,
      defect_desc,
      handle_type,
      responsible_dept,
      responsible_person,
      remark,
    } = body;

    if (!inspection_id || inspection_id <= 0) {
      return errorResponse('检验单ID不能为空', 400);
    }
    if (quantity === undefined || quantity <= 0) {
      return errorResponse('不合格数量必须大于0', 400);
    }
    if (handle_type !== undefined && !isHandleMethodValue(handle_type)) {
      return errorResponse('处理方式无效（应为 rework/scrap/concession/return）', 400);
    }

    const result = await service.createRecord({
      inspectionId: Number(inspection_id),
      sourceType: source_type,
      sourceNo: source_no,
      materialId: material_id ? Number(material_id) : undefined,
      materialCode: material_code,
      materialName: material_name,
      quantity: Number(quantity),
      defectType: defect_type,
      defectDesc: defect_desc,
      handleType: handle_type,
      responsibleDept: responsible_dept,
      responsiblePerson: responsible_person,
      remark,
      createBy: userInfo.userId,
    });

    return successResponse(
      {
        id: result.id,
        unqualified_no: result.unqualifiedNo,
        handle_no: result.handleNo,
      },
      '不合格品记录创建成功'
    );
  } catch (e) {
    if (e instanceof DomainError) return domainErrorToResponse(e);
    throw e;
  }
}, { logTitle: '创建不合格品记录', logType: 'business' });

export const PUT = withPermission(async (request: NextRequest, userInfo) => {
  try {
    const body = await request.json();
    const { action, id } = body;

    if (!id) {
      return errorResponse('缺少 id', 400);
    }
    if (action === 'start') {
      const { handle_type, responsible_dept, responsible_person } = body;
      if (!isHandleMethodValue(handle_type)) {
        return errorResponse('处理方式无效（应为 rework/scrap/concession/return）', 400);
      }
      if (!responsible_dept || !responsible_dept.trim()) {
        return errorResponse('责任部门不能为空', 400);
      }
      if (!responsible_person || !responsible_person.trim()) {
        return errorResponse('责任人不能为空', 400);
      }

      const result = await service.startHandle({
        id: Number(id),
        handleType: handle_type,
        responsibleDept: responsible_dept,
        responsiblePerson: responsible_person,
        updateBy: userInfo.userId,
      });

      return successResponse(result, '已开始处理');
    }

    if (action === 'complete') {
      const { handler, handle_result, cost_amount } = body;
      if (!handler || !handler.trim()) {
        return errorResponse('处理人不能为空', 400);
      }
      if (handle_result !== 1 && handle_result !== 2) {
        return errorResponse('处理结果必须为: 1-合格 或 2-不合格', 400);
      }
      if (cost_amount === undefined || cost_amount < 0) {
        return errorResponse('损失金额不能为负数', 400);
      }

      const result = await service.completeHandle({
        id: Number(id),
        handler,
        handleResult: Number(handle_result),
        costAmount: Number(cost_amount),
        updateBy: userInfo.userId,
      });

      return successResponse(result, '处理完成');
    }

    return errorResponse('action 必须为 start 或 complete', 400);
  } catch (e) {
    if (e instanceof DomainError) return domainErrorToResponse(e);
    throw e;
  }
}, { logTitle: '更新不合格品处理状态', logType: 'business' });

export const DELETE = withPermission(async (request: NextRequest) => {
  try {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    if (!id) return errorResponse('缺少 id', 400);

    await service.deleteRecord(Number(id));
    return successResponse(null, '删除成功');
  } catch (e) {
    if (e instanceof DomainError) return domainErrorToResponse(e);
    throw e;
  }
}, { logTitle: '删除不合格品记录', logType: 'business' });

﻿import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

/**
 * 报表仪表盘 - 核心指标汇总
 */
export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const period = searchParams.get('period') || '30'; // 天数

  const days = parseInt(period);
  const startDate = new Date();
  startDate.setDate(startDate.getDate() - days);
  const startDateStr = startDate.toISOString().split('T')[0];

  // 1. 订单指标
  const orderStats: Loose = await query(
    `SELECT
      COUNT(*) as total_orders,
      SUM(CASE WHEN status >= 3 THEN 1 ELSE 0 END) as completed_orders,
      SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END) as pending_orders,
      COALESCE(SUM(total_amount), 0) as total_amount,
      COALESCE(SUM(CASE WHEN status >= 3 THEN total_amount ELSE 0 END), 0) as completed_amount
    FROM sales_order
    WHERE deleted = 0 AND order_date >= ?`,
    [startDateStr]
  );

  // 2. 生产指标
  const productionStats: Loose = await query(
    `SELECT
      COUNT(*) as total_work_orders,
      SUM(CASE WHEN status >= 3 THEN 1 ELSE 0 END) as completed_work_orders,
      SUM(CASE WHEN status = 2 THEN 1 ELSE 0 END) as in_progress_work_orders,
      COALESCE(SUM(plan_qty), 0) as total_plan_qty,
      COALESCE(SUM(completed_qty), 0) as total_completed_qty
    FROM prd_work_order
    WHERE deleted = 0 AND work_order_date >= ?`,
    [startDateStr]
  );

  // 3. 库存指标
  const inventoryStats: Loose = await query(
    `SELECT
      COUNT(DISTINCT material_id) as material_count,
      COALESCE(SUM(quantity), 0) as total_stock,
      COALESCE(SUM(locked_qty), 0) as total_locked,
      COALESCE(SUM(available_qty), 0) as total_available,
      COUNT(CASE WHEN available_qty <= 0 THEN 1 END) as zero_stock_count,
      COUNT(CASE WHEN available_qty > 0 AND available_qty <= 10 THEN 1 END) as low_stock_count
    FROM inv_inventory
    WHERE deleted = 0`
  );

  // 4. 采购指标
  const purchaseStats: Loose = await query(
    `SELECT
      COUNT(*) as total_purchase_orders,
      SUM(CASE WHEN status >= 3 THEN 1 ELSE 0 END) as received_orders,
      COALESCE(SUM(total_amount), 0) as total_purchase_amount
    FROM purchase_order
    WHERE deleted = 0 AND order_date >= ?`,
    [startDateStr]
  );

  // 5. 财务指标（应收应付）
  const financeStats: Loose = await query(
    `SELECT
      COALESCE(SUM(CASE WHEN type = 'receivable' AND status = 1 THEN amount ELSE 0 END), 0) as pending_receivable,
      COALESCE(SUM(CASE WHEN type = 'payable' AND status = 1 THEN amount ELSE 0 END), 0) as pending_payable
    FROM finance_flow
    WHERE deleted = 0`
  );

  const orderRow = orderStats[0] || {};
  const productionRow = productionStats[0] || {};
  const inventoryRow = inventoryStats[0] || {};
  const purchaseRow = purchaseStats[0] || {};
  const financeRow = financeStats[0] || {};

  return successResponse(
    {
      period: `${days}天`,
      orderMetrics: {
        totalOrders: orderRow.total_orders || 0,
        completedOrders: orderRow.completed_orders || 0,
        pendingOrders: orderRow.pending_orders || 0,
        totalAmount: parseFloat(orderRow.total_amount) || 0,
        completedAmount: parseFloat(orderRow.completed_amount) || 0,
        completionRate:
          orderRow.total_orders > 0
            ? Math.round((orderRow.completed_orders / orderRow.total_orders) * 100)
            : 0,
      },
      productionMetrics: {
        totalWorkOrders: productionRow.total_work_orders || 0,
        completedWorkOrders: productionRow.completed_work_orders || 0,
        inProgressWorkOrders: productionRow.in_progress_work_orders || 0,
        totalPlanQty: parseFloat(productionRow.total_plan_qty) || 0,
        totalCompletedQty: parseFloat(productionRow.total_completed_qty) || 0,
        completionRate:
          productionRow.total_plan_qty > 0
            ? Math.round((productionRow.total_completed_qty / productionRow.total_plan_qty) * 100)
            : 0,
      },
      inventoryMetrics: {
        materialCount: inventoryRow.material_count || 0,
        totalStock: parseFloat(inventoryRow.total_stock) || 0,
        totalLocked: parseFloat(inventoryRow.total_locked) || 0,
        totalAvailable: parseFloat(inventoryRow.total_available) || 0,
        zeroStockCount: inventoryRow.zero_stock_count || 0,
        lowStockCount: inventoryRow.low_stock_count || 0,
      },
      purchaseMetrics: {
        totalPurchaseOrders: purchaseRow.total_purchase_orders || 0,
        receivedOrders: purchaseRow.received_orders || 0,
        totalPurchaseAmount: parseFloat(purchaseRow.total_purchase_amount) || 0,
      },
      financeMetrics: {
        pendingReceivable: parseFloat(financeRow.pending_receivable) || 0,
        pendingPayable: parseFloat(financeRow.pending_payable) || 0,
      },
    },
    '获取仪表盘数据成功'
  );
});

﻿import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

/**
 * 订单交付率报表
 * 按月/客户统计订单准时交付率
 */
export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const startDate = searchParams.get('startDate');
  const endDate = searchParams.get('endDate');
  const groupBy = searchParams.get('groupBy') || 'month'; // month, customer

  let dateFilter = '';
  const params: Loose[] = [];

  if (startDate && endDate) {
    dateFilter = ' AND so.order_date BETWEEN ? AND ?';
    params.push(startDate, endDate);
  }

  if (groupBy === 'month') {
    // 按月统计
    const rows: Loose = await query(
      `SELECT
        DATE_FORMAT(so.order_date, '%Y-%m') as month,
        COUNT(*) as total_orders,
        SUM(CASE WHEN so.status >= 3 THEN 1 ELSE 0 END) as completed_orders,
        SUM(CASE WHEN so.delivery_date >= so.actual_delivery_date THEN 1 ELSE 0 END) as on_time_orders,
        COALESCE(SUM(so.total_amount), 0) as total_amount,
        COALESCE(SUM(CASE WHEN so.status >= 3 THEN so.total_amount ELSE 0 END), 0) as completed_amount
      FROM sales_order so
      WHERE so.deleted = 0 ${dateFilter}
      GROUP BY DATE_FORMAT(so.order_date, '%Y-%m')
      ORDER BY month DESC`,
      params
    );

    const result = rows.map((row: Loose) => ({
      month: row.month,
      totalOrders: row.total_orders,
      completedOrders: row.completed_orders,
      onTimeOrders: row.on_time_orders || 0,
      totalAmount: parseFloat(row.total_amount),
      completedAmount: parseFloat(row.completed_amount),
      deliveryRate:
        row.total_orders > 0 ? Math.round((row.completed_orders / row.total_orders) * 100) : 0,
      onTimeRate:
        row.total_orders > 0 ? Math.round(((row.on_time_orders || 0) / row.total_orders) * 100) : 0,
    }));

    return successResponse(
      {
        list: result,
        summary: {
          totalOrders: result.reduce((sum: number, r: Loose) => sum + r.totalOrders, 0),
          completedOrders: result.reduce((sum: number, r: Loose) => sum + r.completedOrders, 0),
          avgDeliveryRate:
            result.length > 0
              ? Math.round(
                  result.reduce((sum: number, r: Loose) => sum + r.deliveryRate, 0) / result.length
                )
              : 0,
          avgOnTimeRate:
            result.length > 0
              ? Math.round(
                  result.reduce((sum: number, r: Loose) => sum + r.onTimeRate, 0) / result.length
                )
              : 0,
        },
      },
      '获取订单交付率报表成功'
    );
  } else {
    // 按客户统计
    const rows: Loose = await query(
      `SELECT
        so.customer_id,
        c.customer_name,
        COUNT(*) as total_orders,
        SUM(CASE WHEN so.status >= 3 THEN 1 ELSE 0 END) as completed_orders,
        SUM(CASE WHEN so.delivery_date >= so.actual_delivery_date THEN 1 ELSE 0 END) as on_time_orders,
        COALESCE(SUM(so.total_amount), 0) as total_amount
      FROM sales_order so
      LEFT JOIN customer c ON so.customer_id = c.id
      WHERE so.deleted = 0 ${dateFilter}
      GROUP BY so.customer_id, c.customer_name
      ORDER BY total_orders DESC
      LIMIT 50`,
      params
    );

    const result = rows.map((row: Loose) => ({
      customerId: row.customer_id,
      customerName: row.customer_name || '未知客户',
      totalOrders: row.total_orders,
      completedOrders: row.completed_orders,
      onTimeOrders: row.on_time_orders || 0,
      totalAmount: parseFloat(row.total_amount),
      deliveryRate:
        row.total_orders > 0 ? Math.round((row.completed_orders / row.total_orders) * 100) : 0,
      onTimeRate:
        row.total_orders > 0 ? Math.round(((row.on_time_orders || 0) / row.total_orders) * 100) : 0,
    }));

    return successResponse(
      {
        list: result,
        summary: {
          totalCustomers: result.length,
          totalOrders: result.reduce((sum: number, r: Loose) => sum + r.totalOrders, 0),
          avgDeliveryRate:
            result.length > 0
              ? Math.round(
                  result.reduce((sum: number, r: Loose) => sum + r.deliveryRate, 0) / result.length
                )
              : 0,
        },
      },
      '获取客户交付率报表成功'
    );
  }
});

