  );

  const expiredWarning = await query(
    `SELECT
      record_no, material_name, batch_no, open_time, expire_time,
      remaining_qty, unit
    FROM ink_opening_record
    WHERE deleted = 0 AND status = 1 AND expire_time < NOW()
    ORDER BY expire_time ASC
    LIMIT 20`
