import { NextRequest } from 'next/server';
import { escapeId } from 'mysql2';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

interface RuleViolation {
  table: string;
  field: string;
  current_value: string;
  expected_pattern: string;
  record_id: number;
  record_name: string;
  severity: 'error' | 'warning';
  message: string;
}

interface CategoryRuleConfig {
  code_pattern: string;
  code_pattern_desc: string;
  max_depth: number;
  status_values: number[];
  status_labels: Record<number, string>;
}

const CATEGORY_RULES: Record<string, CategoryRuleConfig> = {
  warehouse: {
    code_pattern: '^WH-CAT-\\d{3,}$',
    code_pattern_desc: 'WH-CAT-XXX（3位以上数字）',
    max_depth: 3,
    status_values: [0, 1],
    status_labels: { 0: '禁用', 1: '启用' },
  },
  material: {
    code_pattern: '^MAT-CAT-\\d{3,}$',
    code_pattern_desc: 'MAT-CAT-XXX（3位以上数字）',
    max_depth: 4,
    status_values: [0, 1],
    status_labels: { 0: '禁用', 1: '启用' },
  },
};

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const categoryType = searchParams.get('type') || 'all';
  const _autoFix = searchParams.get('autoFix') === 'true';

  const violations: RuleViolation[] = [];

  const typesToCheck =
    categoryType === 'all'
      ? Object.keys(CATEGORY_RULES)
      : [categoryType].filter((t) => t in CATEGORY_RULES);

  for (const type of typesToCheck) {
    const rules = CATEGORY_RULES[type];
    const tableName = type === 'warehouse' ? 'sys_warehouse_category' : 'inv_material_category';

    try {
      const rows = (await query(
        `SELECT id, code, name, status, parent_id FROM ${escapeId(tableName)} WHERE deleted = 0`
      )) as Loose[];

      const codeRegex = new RegExp(rules.code_pattern);

      for (const row of rows) {
        if (!codeRegex.test(row.code || '')) {
          violations.push({
            table: tableName,
            field: 'code',
            current_value: row.code || '',
            expected_pattern: rules.code_pattern_desc,
            record_id: row.id,
            record_name: row.name,
            severity: 'error',
            message: `编码"${row.code}"不符合规则${rules.code_pattern_desc}`,
          });
        }

        if (!rules.status_values.includes(row.status)) {
          violations.push({
            table: tableName,
            field: 'status',
            current_value: String(row.status),
            expected_pattern: rules.status_values.map((v) => rules.status_labels[v]).join('/'),
            record_id: row.id,
            record_name: row.name,
            severity: 'error',
            message: `状态值${row.status}不在合法范围${rules.status_values.join('/')}内`,
          });
        }
      }

      if (type === 'material' && rules.max_depth > 0) {
        const parentMap = new Map<number, number>();
        for (const row of rows) {
          if (row.parent_id) {
            parentMap.set(row.id, row.parent_id);
          }
        }

        const getDepth = (id: number, visited: Set<number> = new Set()): number => {
          if (visited.has(id)) return -1;
          visited.add(id);
          const parentId = parentMap.get(id);
          if (!parentId) return 1;
          const parentDepth = getDepth(parentId, visited);
          return parentDepth === -1 ? -1 : parentDepth + 1;
        };

        for (const row of rows) {
          if (row.parent_id) {
            const depth = getDepth(row.id);
            if (depth > rules.max_depth) {
              violations.push({
                table: tableName,
                field: 'parent_id',
                current_value: `层级深度${depth}`,
                expected_pattern: `最大${rules.max_depth}层`,
                record_id: row.id,
                record_name: row.name,
                severity: 'warning',
                message: `分类层级深度${depth}超过最大限制${rules.max_depth}`,
              });
            } else if (depth === -1) {
              violations.push({
                table: tableName,
                field: 'parent_id',
                current_value: '循环引用',
                expected_pattern: '无循环引用',
                record_id: row.id,
                record_name: row.name,
                severity: 'error',
                message: `分类存在循环引用`,
              });
            }
          }
        }
      }
    } catch {
      violations.push({
        table: tableName,
        field: 'table',
        current_value: '',
        expected_pattern: '表存在',
        record_id: 0,
        record_name: '',
        severity: 'warning',
        message: `表${tableName}不存在或查询失败`,
      });
    }
  }

  return successResponse({
    total: violations.length,
    errors: violations.filter((v) => v.severity === 'error').length,
    warnings: violations.filter((v) => v.severity === 'warning').length,
    violations,
    rules: CATEGORY_RULES,
  });
});

﻿import { NextRequest } from 'next/server';
import { query, execute } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { invalidateCache } from '@/lib/api-cache';

interface ChangeRequest {
  id?: number;
  module: string;
  config_key: string;
  old_value: string;
  new_value: string;
  change_type: 'create' | 'update' | 'delete';
  reason: string;
  applicant_id: number;
  applicant_name: string;
  status: 'pending' | 'approved' | 'rejected' | 'cancelled';
  approver_id?: number;
  approver_name?: string;
  approve_time?: string;
  create_time?: string;
}

const APPROVAL_REQUIRED_MODULES = ['单据编码规则', '审批规则', '仓库管理规则', '生产与品质规则'];

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const status = searchParams.get('status') || 'all';
  const moduleName = searchParams.get('module') || 'all';

  let sql = `SELECT * FROM sys_config_change_request WHERE 1=1`;
  const params: Loose[] = [];

  if (status !== 'all') {
    sql += ` AND status = ?`;
    params.push(status);
  }

  if (moduleName !== 'all') {
    sql += ` AND module = ?`;
    params.push(moduleName);
  }

  sql += ` ORDER BY create_time DESC`;

  try {
    const rows = await query(sql, params);
    return successResponse(rows);
  } catch {
    return successResponse([]);
  }
});

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body: ChangeRequest = await request.json();

    if (!body.module || !body.config_key || !body.new_value) {
      return errorResponse('模块、配置键和新值不能为空', 400);
    }

    const needsApproval = APPROVAL_REQUIRED_MODULES.includes(body.module);

    if (needsApproval) {
      try {
        await execute(
          `INSERT INTO sys_config_change_request
          (module, config_key, old_value, new_value, change_type, reason, applicant_id, applicant_name, status, create_time)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'pending', NOW())`,
          [
            body.module,
            body.config_key,
            body.old_value || '',
            body.new_value,
            body.change_type || 'update',
            body.reason || '',
            body.applicant_id || 0,
            body.applicant_name || '未知',
          ]
        );
      } catch {
        await execute(
          `CREATE TABLE IF NOT EXISTS sys_config_change_request (
          id INT AUTO_INCREMENT PRIMARY KEY,
          module VARCHAR(100) NOT NULL,
          config_key VARCHAR(200) NOT NULL,
          old_value TEXT,
          new_value TEXT NOT NULL,
          change_type VARCHAR(20) DEFAULT 'update',
          reason TEXT,
          applicant_id INT DEFAULT 0,
          applicant_name VARCHAR(100),
          status VARCHAR(20) DEFAULT 'pending',
          approver_id INT,
          approver_name VARCHAR(100),
          approve_time DATETIME,
          create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
          INDEX idx_status (status),
          INDEX idx_module (module)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`
        );

        await execute(
          `INSERT INTO sys_config_change_request
          (module, config_key, old_value, new_value, change_type, reason, applicant_id, applicant_name, status, create_time)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'pending', NOW())`,
          [
            body.module,
            body.config_key,
            body.old_value || '',
            body.new_value,
            body.change_type || 'update',
            body.reason || '',
            body.applicant_id || 0,
            body.applicant_name || '未知',
          ]
        );
      }

      return successResponse({ needsApproval: true }, '变更已提交，等待审批');
    }

    return successResponse({ needsApproval: false }, '变更无需审批，可直接生效');
  },
  { logTitle: '创建变更请求' }
);

export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { id, action, approver_id, approver_name } = body;

    if (!id || !action) {
      return errorResponse('变更请求ID和操作类型不能为空', 400);
    }

    if (!['approve', 'reject'].includes(action)) {
      return errorResponse('操作类型无效，仅支持approve/reject', 400);
    }

    const rows = (await query(
      `SELECT * FROM sys_config_change_request WHERE id = ? AND status = 'pending'`,
      [id]
    )) as Loose[];

    if (rows.length === 0) {
      return errorResponse('变更请求不存在或已处理', 404);
    }

    const changeRequest = rows[0];
    const newStatus = action === 'approve' ? 'approved' : 'rejected';

    await execute(
      `UPDATE sys_config_change_request
     SET status = ?, approver_id = ?, approver_name = ?, approve_time = NOW()
     WHERE id = ?`,
      [newStatus, approver_id || 0, approver_name || '未知', id]
    );

    if (action === 'approve') {
      try {
        await execute(
          `UPDATE sys_system_config SET config_value = ?, update_time = NOW()
         WHERE config_key = ?`,
          [changeRequest.new_value, changeRequest.config_key]
        );
        await invalidateCache('api:settings');
      } catch {
        // 配置表可能不存在，忽略
      }
    }

    return successResponse(
      { id, status: newStatus },
      action === 'approve' ? '变更已审批通过并生效' : '变更已驳回'
    );
  },
  { logTitle: '审批变更请求' }
);

