// 列表查询字段（基础字段）
const LIST_FIELDS = `
  id, card_no, customer_name, customer_code, product_name, version, status,
  print_type, material_type, glue_type, packing_type, mold_type,
  finished_size, tolerance, material_name, layout_type,
