// PUT - 更新标准卡
export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { id } = body;

    if (!id) {
      return commonErrors.badRequest('缺少标准卡ID');
    }

    // 检查标准卡是否存在
    const existingCard = await queryOne<{ id: number }>(
      'SELECT id FROM prd_standard_card WHERE id = ? AND deleted = 0',
      [id]
    );

    if (!existingCard) {
      return commonErrors.notFound('标准卡不存在');
    }

    // 检查标准卡编号唯一性（排除当前记录自身）
    if (body.card_no !== undefined && body.card_no !== '') {
      const cardNoToCheck = body.card_no;
      const duplicate = await queryOne<{ id: number }>(
        'SELECT id FROM prd_standard_card WHERE card_no = ? AND deleted = 0 AND id != ?',
        [cardNoToCheck, id]
      );
      if (duplicate) {
        return errorResponse('标准卡编号已存在', 409, 409);
      }
    }

    // 处理sequences字段
    let sequencesToStore = body.sequences;
    if (
      typeof sequencesToStore !== 'string' &&
      sequencesToStore !== null &&
      sequencesToStore !== undefined
    ) {
      sequencesToStore = JSON.stringify(sequencesToStore);
    }

    // 构建更新数据（过滤掉undefined值）
    const updateData: Loose = {};
    const fieldMappings: Record<string, string> = {
      card_no: 'card_no',
      version: 'version',
      status: 'status',
      customer_id: 'customer_id',
      customer_name: 'customer_name',
      customer_code: 'customer_code',
      product_name: 'product_name',
      date: 'date',
      document_code: 'document_code',
      finished_size: 'finished_size',
      tolerance: 'tolerance',
      material_name: 'material_name',
      material_type: 'material_type',
      layout_type: 'layout_type',
      spacing: 'spacing',
      spacing_value: 'spacing_value',
      sheet_width: 'sheet_width',
      sheet_length: 'sheet_length',
      core_type: 'core_type',
      paper_direction: 'paper_direction',
      roll_width: 'roll_width',
      paper_edge: 'paper_edge',
      standard_usage: 'standard_usage',
      jump_distance: 'jump_distance',
      process_flow1: 'process_flow1',
      process_flow2: 'process_flow2',
      print_type: 'print_type',
      first_jump_distance: 'first_jump_distance',
      sequences: 'sequences',
      film_manufacturer: 'film_manufacturer',
      film_code: 'film_code',
      film_size: 'film_size',
      process_method: 'process_method',
      stamping_method: 'stamping_method',
      mold_code: 'mold_code',
      back_mold_code: 'back_mold_code',
      layout_method: 'layout_method',
      layout_way: 'layout_way',
      jump_distance2: 'jump_distance2',
      mylar_material: 'mylar_material',
      mylar_specs: 'mylar_specs',
      mylar_layout: 'mylar_layout',
      mylar_jump: 'mylar_jump',
      adhesive_type: 'adhesive_type',
      adhesive_manufacturer: 'adhesive_manufacturer',
      adhesive_code: 'adhesive_code',
      adhesive_size: 'adhesive_size',
      adhesive_specs: 'adhesive_specs',
      dashed_knife: 'dashed_knife',
      slice_per_row: 'slice_per_row',
      slice_per_roll: 'slice_per_roll',
      slice_per_bundle: 'slice_per_bundle',
      slice_per_bag: 'slice_per_bag',
      slice_per_box: 'slice_per_box',
      packing_qty: 'packing_qty',
      back_knife_mold: 'back_knife_mold',
      back_mylar_mold: 'back_mylar_mold',
      release_paper_code: 'release_paper_code',
      release_paper_type: 'release_paper_type',
      release_paper_category: 'release_paper_category',
      release_paper_specs: 'release_paper_specs',
      padding_material: 'padding_material',
      packing_material: 'packing_material',
      special_color: 'special_color',
      color_formula: 'color_formula',
      file_path: 'file_path',
      sample_info: 'sample_info',
      notes: 'notes',
      glue_type: 'glue_type',
      packing_type: 'packing_type',
      mold_type: 'mold_type',
      etch_mold: 'etch_mold',
      storage_location: 'storage_location',
      extra_field: 'extra_field',
      creator: 'creator',
      reviewer: 'reviewer',
      factory_manager: 'factory_manager',
      quality_manager: 'quality_manager',
      sales: 'sales',
      approver: 'approver',
      creator_id: 'create_by',
      reviewer_id: 'reviewer_id',
    };

    // 处理传入的body字段
    // 注意：status 字段在编辑接口中一律忽略——状态流转只能通过独立的
    // /api/standard-cards/approve 接口进行，防止编辑已审核/已作废卡片时被重置为草稿。
    for (const [sourceField, targetField] of Object.entries(fieldMappings)) {
      if (sourceField === 'status') continue;
      if (body[sourceField] !== undefined) {
        if (sourceField === 'sequences') {
          let val = body[sourceField];
          if (typeof val !== 'string' && val !== null && val !== undefined) {
            val = JSON.stringify(val);
          }
          updateData[targetField] = val;
        } else if (sourceField === 'dashed_knife') {
          updateData[targetField] = body[sourceField] ? 1 : 0;
        } else {
          updateData[targetField] = body[sourceField];
        }
      }
    }

    // 特别处理sheetSpecs
    if (body.sheetSpecs) {
      if (body.sheetSpecs.width !== undefined) {
        updateData.sheet_width = body.sheetSpecs.width;
      }
      if (body.sheetSpecs.length !== undefined) {
        updateData.sheet_length = body.sheetSpecs.length;
      }
    }

    // 处理兼容字段
    if (body.customer !== undefined) {
      updateData.customer_name = body.customer;
    }

    // 更新时间
    updateData.update_time = new Date();

    // 保护逻辑（仅针对 sequences）：
    // 前端已按 diff 提交（只提交变更字段），显式提交的空字符串应视为用户主动清空，允许落库。
    // 但 sequences 为空数组或全空对象数组时拒绝更新，防止"空表单/加载失败误提交"整体清空印序。
    if (updateData.sequences !== undefined) {
      let seqVal: unknown = updateData.sequences;
      if (typeof seqVal === 'string') {
        try {
          seqVal = JSON.parse(seqVal);
        } catch {
          seqVal = null;
        }
      }
      const seqArray = Array.isArray(seqVal) ? seqVal : [];
      const isEmptySequences =
        seqArray.length === 0 ||
        seqArray.every(
          (s) =>
            typeof s !== 'object' ||
            s === null ||
            Object.values(s as Record<string, unknown>).every(
              (v) => v === '' || v === null || v === undefined
            )
        );
      if (isEmptySequences) {
        delete updateData.sequences;
      }
    }

    // 构建SQL
    if (Object.keys(updateData).length === 0) {
      return commonErrors.badRequest('没有要更新的字段');
    }

    const updateFields = Object.keys(updateData);
    const values = Object.values(updateData);
    const setClause = updateFields.map((field) => `${field} = ?`).join(', ');

    // 添加ID到参数末尾
    values.push(id);

    await execute(
      `UPDATE prd_standard_card SET ${setClause} WHERE id = ? AND deleted = 0`,
      values as import('@/lib/db').SqlValue[]
    );

    return successResponse(null, '标准卡更新成功');
  },
  { logTitle: '更新标准卡', logType: 'business' }
);

// DELETE - 删除标准卡（软删除，支持批量）
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return commonErrors.badRequest('缺少标准卡ID');
    }

    // 支持批量删除：id=1,2,3
    const ids = id.split(',').map((s) => parseInt(s.trim())).filter((n) => !isNaN(n) && n > 0);

    if (ids.length === 0) {
      return commonErrors.badRequest('缺少有效的标准卡ID');
    }

    if (ids.length === 1) {
      // 单条删除
      const cardId = ids[0];
      const existingCard = await queryOne<{ id: number }>(
        'SELECT id FROM prd_standard_card WHERE id = ? AND deleted = 0',
        [cardId]
      );
      if (!existingCard) {
        return commonErrors.notFound('标准卡不存在');
      }
      await execute('UPDATE prd_standard_card SET deleted = 1 WHERE id = ?', [cardId]);
      return successResponse(null, '标准卡删除成功');
    }

    // 批量删除
    const placeholders = ids.map(() => '?').join(', ');
    const existingRows = await query(
      `SELECT id FROM prd_standard_card WHERE id IN (${placeholders}) AND deleted = 0`,
      ids as unknown as import('@/lib/db').SqlValue[]
    );
    if (!existingRows || existingRows.length === 0) {
      return commonErrors.notFound('未找到可删除的标准卡');
    }
    await execute(
      `UPDATE prd_standard_card SET deleted = 1 WHERE id IN (${placeholders})`,
      ids as unknown as import('@/lib/db').SqlValue[]
    );
    return successResponse(
      { deletedCount: existingRows.length },
      `成功删除 ${existingRows.length} 条标准卡`
    );
  },
  { logTitle: '删除标准卡', logType: 'business' }
);

import { NextRequest } from 'next/server';
import { query, queryOne } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import {
  StandardCardType,
  ColorStandardItem,
  ProcessStandardItem,
  QualityStandardItem,
  StandardCard,
} from '../route';

// POST /api/standard-cards/scan - 扫码查看标准卡（设计文档 6.3 节）
export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { qr_code } = body;

    if (!qr_code) {
      return errorResponse('缺少二维码编码', 400, 400);
    }

    // 通过二维码查找关联的工单
    const qrRecord = await queryOne<Loose>(
      'SELECT * FROM qrcode_record WHERE qr_code = ? AND deleted = 0',
      [qr_code]
    );

    if (!qrRecord) {
      return errorResponse('未找到对应的二维码记录', 404, 404);
    }

    let workOrderNo = qrRecord.work_order_no;
    let workOrderId = qrRecord.work_order_id;

    // 如果没有直接关联工单，尝试通过 ref_no 查找
    if (!workOrderNo && qrRecord.ref_no) {
      const workOrder = await queryOne<{ work_order_no: string; id: number }>(
        'SELECT work_order_no, id FROM prd_work_order WHERE order_no = ? AND deleted = 0',
        [qrRecord.ref_no]
      );
      if (workOrder) {
        workOrderNo = workOrder.work_order_no;
        workOrderId = workOrder.id;
      }
    }

    if (!workOrderId) {
      return errorResponse('该二维码未关联生产工单', 404, 404);
    }

    // 查询工单关联的标准卡
    const cards = await query<StandardCard>(
      `SELECT sc.* FROM prd_standard_card sc
     LEFT JOIN prd_work_order wo ON wo.material_id = sc.material_id
     WHERE wo.id = ? AND sc.status = 3 AND sc.deleted = 0`,
      [workOrderId]
    );

    // 为每个标准卡加载明细数据
    const cardsWithItems: Loose[] = [];
    for (const card of cards) {
      let items: Loose[] = [];

      switch (card.type as StandardCardType) {
        case 'color':
          items = await query<ColorStandardItem>(
            'SELECT * FROM color_standard_items WHERE standard_card_id = ?',
            [card.id!]
          );
          break;
        case 'process':
          items = await query<ProcessStandardItem>(
            'SELECT * FROM process_standard_items WHERE standard_card_id = ?',
            [card.id!]
          );
          break;
        case 'quality':
          items = await query<QualityStandardItem>(
            'SELECT * FROM quality_standard_items WHERE standard_card_id = ?',
            [card.id!]
          );
          break;
        case 'comprehensive':
          // 综合类型：返回所有明细
          const colorItems = await query<ColorStandardItem>(
            'SELECT *, "color" as item_type FROM color_standard_items WHERE standard_card_id = ?',
            [card.id!]
          );
          const processItems = await query<ProcessStandardItem>(
            'SELECT *, "process" as item_type FROM process_standard_items WHERE standard_card_id = ?',
            [card.id!]
          );
          const qualityItems = await query<QualityStandardItem>(
            'SELECT *, "quality" as item_type FROM quality_standard_items WHERE standard_card_id = ?',
            [card.id!]
          );
          items = [...colorItems, ...processItems, ...qualityItems];
          break;
      }

      cardsWithItems.push({
        ...card,
        items,
      });
    }

    return successResponse({
      work_order_no: workOrderNo,
      standard_cards: cardsWithItems,
    });
  },
  { logTitle: '扫码查看标准卡', logType: 'business' }
);

import { NextRequest } from 'next/server';
import { successResponse, errorResponse, validateRequestBody } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';
import { query, execute } from '@/lib/db';

/**
 * 系统公告 API
 */

// 获取公告列表
export const GET = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const type = searchParams.get('type') || 'published';
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');

    let where = 'WHERE 1=1';
    const params: Loose[] = [];

    if (type === 'published') {
      where += ' AND a.status = ? AND (a.expire_time IS NULL OR a.expire_time > NOW())';
      params.push('published');
    } else if (type === 'draft') {
      where += ' AND a.status = ?';
      params.push('draft');
    } else if (type === 'all') {
      // 管理员查看所有
    }

    const countRows: Loose = await query(
      `SELECT COUNT(*) as total FROM sys_announcement a ${where}`,
      params
    );
    const total = countRows[0]?.total || 0;

    const rows: Loose = await query(
      `SELECT a.*, u.real_name as creator_name,
              (SELECT COUNT(*) FROM sys_announcement_read r WHERE r.announcement_id = a.id) as read_count,
              (SELECT COUNT(*) FROM sys_announcement_read r WHERE r.announcement_id = a.id AND r.user_id = ?) as is_read
       FROM sys_announcement a
       LEFT JOIN sys_user u ON a.create_by = u.id
       ${where}
       ORDER BY a.is_top DESC, a.priority DESC, a.publish_time DESC
       LIMIT ? OFFSET ?`,
      [userInfo.userId, ...params, pageSize, (page - 1) * pageSize]
    );

    return successResponse({ list: rows, total, page, pageSize });
  },
  { errorMessage: '操作失败' }
);

// 创建/发布公告
export const POST = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const body = await request.json();
    const validation = validateRequestBody(body, ['title', 'content']);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    const { title, content, type, priority, is_top, publish_time, expire_time, status } = body;

    const result: Loose = await execute(
      `INSERT INTO sys_announcement
       (title, content, type, priority, is_top, publish_time, expire_time, status, create_by, create_time, update_time)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW())`,
      [
        title,
        content,
        type || 'info',
        priority || 0,
        is_top ? 1 : 0,
        publish_time ||
          (status === 'published' ? new Date().toISOString().slice(0, 19).replace('T', ' ') : null),
        expire_time || null,
        status || 'draft',
        userInfo.userId,
      ]
    );

    return successResponse({ id: result.insertId }, '公告创建成功');
  },
  { errorMessage: '操作失败' }
);

// 更新公告
export const PUT = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const body = await request.json();
    const { id, action } = body;

    if (!id) {
      return errorResponse('公告ID不能为空', 400, 400);
    }

    if (action === 'publish') {
      await execute(
        `UPDATE sys_announcement SET status = 'published', publish_time = NOW(), update_time = NOW() WHERE id = ?`,
        [id]
      );
      return successResponse(null, '公告已发布');
    }

    if (action === 'read') {
      // 标记已读
      await execute(
        `INSERT IGNORE INTO sys_announcement_read (announcement_id, user_id, read_time) VALUES (?, ?, NOW())`,
        [id, userInfo.userId]
      );
      return successResponse(null, '已标记已读');
    }

    // 通用更新
    const { title, content, type, priority, is_top, expire_time, status } = body;
    const updates: string[] = [];
    const params: Loose[] = [];

    if (title !== undefined) {
      updates.push('title = ?');
      params.push(title);
    }
    if (content !== undefined) {
      updates.push('content = ?');
      params.push(content);
    }
    if (type !== undefined) {
      updates.push('type = ?');
      params.push(type);
    }
    if (priority !== undefined) {
      updates.push('priority = ?');
      params.push(priority);
    }
    if (is_top !== undefined) {
      updates.push('is_top = ?');
      params.push(is_top ? 1 : 0);
    }
    if (expire_time !== undefined) {
      updates.push('expire_time = ?');
      params.push(expire_time);
    }
    if (status !== undefined) {
      updates.push('status = ?');
      params.push(status);
    }

    if (updates.length === 0) {
      return errorResponse('没有需要更新的字段', 400, 400);
    }

    updates.push('update_time = NOW()');
    params.push(id);

    await execute(`UPDATE sys_announcement SET ${updates.join(', ')} WHERE id = ?`, params);

    return successResponse(null, '公告更新成功');
  },
  { errorMessage: '操作失败' }
);

// 删除公告
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return errorResponse('公告ID不能为空', 400, 400);
    }

    await execute('DELETE FROM sys_announcement_read WHERE announcement_id = ?', [Number(id)]);
    await execute('DELETE FROM sys_announcement WHERE id = ?', [Number(id)]);

    return successResponse(null, '公告已删除');
  },
  { errorMessage: '操作失败' }
);

