import { NextRequest } from 'next/server';
import { execute } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { config_key, config_value, config_name, description } = body;

    if (!config_key) {
      return errorResponse('缺少 config_key', 400, 400);
    }

    let sql = 'UPDATE sys_config SET config_value = ?';
    const params: Loose[] = [config_value];

    if (config_name !== undefined) {
      sql += ', config_name = ?';
      params.push(config_name);
    }

    if (description !== undefined) {
      sql += ', description = ?';
      params.push(description);
    }

    sql += ', update_time = NOW() WHERE config_key = ?';
    params.push(config_key);

    const result = await execute(sql, params);

    if (result.affectedRows === 0) {
      return errorResponse('配置项不存在', 404, 404);
    }

    return successResponse(null, '更新成功');
  },
  { logTitle: '更新系统配置', logType: 'system' }
);

import { NextRequest } from 'next/server';
import { execute, queryOne, query } from '@/lib/db';
import {
  successResponse,
  errorResponse,
  commonErrors,
  validateRequestBody,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';

// GET - 币种列表（含筛选）
export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const status = searchParams.get('status');
  const onlyActive = searchParams.get('active') === 'true';

  let sql = 'SELECT * FROM sys_currency WHERE deleted = 0';
  const values: Loose[] = [];

  if (onlyActive) {
    sql += ' AND status = 1';
  } else if (status !== undefined && status !== null && status !== '') {
    sql += ' AND status = ?';
    values.push(parseInt(status));
  }

  sql += ' ORDER BY sort ASC, id ASC';

  const rows = await query(sql, values);
  return successResponse(rows);
});

// POST - 新建币种
export const POST = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const body = await request.json();
    const validation = validateRequestBody(body, ['code', 'name']);
    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    // 检查 code 是否已存在
    const existing = await queryOne('SELECT id FROM sys_currency WHERE code = ?', [body.code]);
    if (existing) {
      return errorResponse('币种代码已存在', 409, 409);
    }

    const result = await execute(
      `INSERT INTO sys_currency (code, name, symbol, decimal_places, status, sort, create_by)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [
        body.code,
        body.name,
        body.symbol ?? null,
        body.decimal_places ?? 2,
        body.status ?? 1,
        body.sort ?? 0,
        userInfo.userId,
      ]
    );

    return successResponse({ id: result.insertId }, '币种创建成功');
  },
  { logTitle: '创建币种' }
);

// PUT - 更新币种
export const PUT = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const body = await request.json();
    const { id } = body;
    if (!id) {
      return commonErrors.badRequest('币种ID不能为空');
    }

    const existing = await queryOne('SELECT id FROM sys_currency WHERE id = ? AND deleted = 0', [
      id,
    ]);
    if (!existing) {
      return commonErrors.notFound('币种不存在');
    }

    if (!body.name) {
      return errorResponse('币种名称不能为空', 400, 400);
    }

    await execute(
      `UPDATE sys_currency SET name = ?, symbol = ?, decimal_places = ?, status = ?, sort = ?, update_by = ? WHERE id = ?`,
      [
        body.name,
        body.symbol ?? null,
        body.decimal_places ?? 2,
        body.status ?? 1,
        body.sort ?? 0,
        userInfo.userId,
        id,
      ]
    );

    return successResponse(null, '币种更新成功');
  },
  { logTitle: '更新币种' }
);

// DELETE - 删除币种（软删除）
export const DELETE = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    if (!id) {
      return commonErrors.badRequest('币种ID不能为空');
    }

    // 先获取币种 code
    const currency = await queryOne('SELECT code FROM sys_currency WHERE id = ? AND deleted = 0', [
      parseInt(id),
    ]);
    if (!currency) {
      return commonErrors.notFound('币种不存在');
    }
    // 检查引用：汇率记录或公司本位币
    const inUse = await queryOne(
      `SELECT 1 AS v FROM sys_exchange_rate WHERE from_currency = ? OR to_currency = ? LIMIT 1
       UNION
       SELECT 1 AS v FROM sys_company WHERE base_currency = ? LIMIT 1`,
      [currency.code, currency.code, currency.code]
    );
    if (inUse) {
      return errorResponse('该币种已被汇率记录或公司本位币引用，无法删除', 409, 409);
    }

    await execute('UPDATE sys_currency SET deleted = 1, update_by = ? WHERE id = ?', [
      userInfo.userId,
      parseInt(id),
    ]);
    return successResponse(null, '币种删除成功');
  },
  { logTitle: '删除币种' }
);

import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import {
  runAllFixes,
  fixRequestItemMaterialId,
  fixAttendanceEmpId,
  fixInventoryBatchConsistency,
  fixExpiredBatches,
  scanGhostData,
} from '@/lib/services/data-fix-tool';

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { fixType } = body;

    if (fixType === 'all') {
      const results = await runAllFixes();
      return successResponse(results, '脏数据修复完成');
    }

    switch (fixType) {
      case 'request_material_id':
        return successResponse(await fixRequestItemMaterialId(), '请购单物料ID修复完成');
      case 'attendance_emp_id':
        return successResponse(await fixAttendanceEmpId(), '考勤员工ID修复完成');
      case 'inventory_batch':
        return successResponse(await fixInventoryBatchConsistency(), '库存批次一致性修复完成');
      case 'expired_batches':
        return successResponse(await fixExpiredBatches(), '过期批次标记完成');
      default:
        return errorResponse('未知的修复类型', 400);
    }
  },
  { logTitle: '修复脏数据', logType: 'system' }
);

export const GET = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const mode = searchParams.get('mode') || 'scan';

    // GET 仅允许只读巡检，禁止触发任何数据修复（写操作），避免爬虫/预取误执行变更
    if (mode !== 'scan') {
      return errorResponse('巡检接口仅支持只读模式 (?mode=scan)，数据修复请改用 POST', 405);
    }

    const ghostResults = await scanGhostData();
    return successResponse(ghostResults, '幽灵数据巡检完成');
  },
  { logTitle: '巡检脏数据', logType: 'system' }
);

import { NextRequest } from 'next/server';
import { query, execute } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
