import { NextRequest } from 'next/server';
import { successResponse, errorResponse, validateRequestBody } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';
import { query, execute } from '@/lib/db';

/**
 * 字典管理 API
 *
 * 数据模型（与权威库结构 `database/vnerpdacahng_schema.sql` 一致，规范化模型）：
 * - sys_dict_type: id, dict_code(编码/唯一), dict_name, description, status, deleted
 * - sys_dict_data: id, dict_type_id(FK→sys_dict_type.id), dict_label, dict_value,
 *                  sort_order, status, remark, deleted
 *
 * 说明：前端以 `dict_type` 作为“字典类型编码”的逻辑字段名，本 API 负责在 `dict_type`(编码)
 * 与真实列 `dict_code` / `dict_type_id` 之间做映射，保持对前端契约不变。
 */

// 获取字典数据
export const GET = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const dictType = searchParams.get('dictType') || '';
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '100');

    if (dictType) {
      // 获取指定类型（编码）的字典数据
      const rows: Loose = await query(
        `SELECT d.id, d.dict_type_id, d.dict_label, d.dict_value, d.sort_order, d.status, d.remark,
                t.dict_code AS dict_type, t.dict_name
           FROM sys_dict_data d
           JOIN sys_dict_type t ON d.dict_type_id = t.id
          WHERE t.dict_code = ? AND d.status = 1 AND d.deleted = 0 AND t.deleted = 0
          ORDER BY d.sort_order`,
        [dictType]
      );
      return successResponse({ list: rows });
    }

    // 获取所有字典类型
    const countRows: Loose = await query(
      'SELECT COUNT(*) as total FROM sys_dict_type WHERE deleted = 0'
    );
    const total = countRows[0]?.total || 0;

    const types: Loose = await query(
      `SELECT id, dict_code AS dict_type, dict_name, description AS remark, status
         FROM sys_dict_type
        WHERE deleted = 0
        ORDER BY id
        LIMIT ? OFFSET ?`,
      [pageSize, (page - 1) * pageSize]
    );

    // 获取每个类型的数据项
    const result = [];
    for (const type of types) {
      const items: Loose = await query(
        `SELECT id, dict_type_id, dict_label, dict_value, sort_order, status, remark
           FROM sys_dict_data
          WHERE dict_type_id = ? AND deleted = 0
          ORDER BY sort_order`,
        [type.id]
      );
      // 为每个数据项补充 dict_type 编码字段，保持前端契约
      const itemsWithType = items.map((it: Loose) => ({ ...it, dict_type: type.dict_type }));
      result.push({ ...type, items: itemsWithType });
    }

    return successResponse({ list: result, total, page, pageSize });
  },
  { errorMessage: '操作失败' }
);

// 创建字典类型或数据
export const POST = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const body = await request.json();
    const { action } = body;

    if (action === 'create_type') {
      const validation = validateRequestBody(body, ['dict_name', 'dict_type']);
      if (!validation.valid) {
        return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
      }

      const existing: Loose = await query(
        'SELECT id FROM sys_dict_type WHERE dict_code = ? AND deleted = 0',
        [body.dict_type]
      );
      if (existing.length > 0) {
        return errorResponse('字典类型编码已存在', 400, 400);
      }

      const result: Loose = await execute(
        'INSERT INTO sys_dict_type (dict_name, dict_code, status, description) VALUES (?, ?, ?, ?)',
        [body.dict_name, body.dict_type, body.status ?? 1, body.remark || null]
      );

      return successResponse({ id: result.insertId }, '字典类型创建成功');
    }

    if (action === 'create_data') {
      const validation = validateRequestBody(body, ['dict_type', 'dict_label', 'dict_value']);
      if (!validation.valid) {
        return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
      }

      // 将字典类型编码解析为 dict_type_id
      const typeRows: Loose = await query(
        'SELECT id FROM sys_dict_type WHERE dict_code = ? AND deleted = 0',
        [body.dict_type]
      );
      if (typeRows.length === 0) {
        return errorResponse('字典类型不存在', 400, 400);
      }
      const dictTypeId = typeRows[0].id;

      const result: Loose = await execute(
        'INSERT INTO sys_dict_data (dict_type_id, dict_label, dict_value, sort_order, status, remark) VALUES (?, ?, ?, ?, ?, ?)',
        [
          dictTypeId,
          body.dict_label,
          body.dict_value,
          body.sort_order || 0,
          body.status ?? 1,
          body.remark || null,
        ]
      );

      return successResponse({ id: result.insertId }, '字典数据创建成功');
    }

    return errorResponse('无效的操作类型', 400, 400);
  },
  { errorMessage: '操作失败' }
);

// 更新字典
export const PUT = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const body = await request.json();
    const { action } = body;

    if (action === 'update_type') {
      if (!body.id) return errorResponse('ID不能为空', 400, 400);
      const updates: string[] = [];
      const params: Loose[] = [];
      if (body.dict_name !== undefined) {
        updates.push('dict_name = ?');
        params.push(body.dict_name);
      }
      // 前端以 dict_type 表示编码，映射到真实列 dict_code
      if (body.dict_type !== undefined) {
        updates.push('dict_code = ?');
        params.push(body.dict_type);
      }
      if (body.status !== undefined) {
        updates.push('status = ?');
        params.push(body.status);
      }
      // 前端以 remark 表示描述，映射到真实列 description
      if (body.remark !== undefined) {
        updates.push('description = ?');
        params.push(body.remark);
      }
      if (updates.length === 0) return errorResponse('没有需要更新的字段', 400, 400);
      updates.push('update_time = NOW()');
      params.push(body.id);
      await execute(
        `UPDATE sys_dict_type SET ${updates.join(', ')} WHERE id = ? AND deleted = 0`,
        params
      );
      return successResponse(null, '字典类型更新成功');
    }

    if (action === 'update_data') {
      if (!body.id) return errorResponse('ID不能为空', 400, 400);
      const updates: string[] = [];
      const params: Loose[] = [];
      if (body.dict_label !== undefined) {
        updates.push('dict_label = ?');
        params.push(body.dict_label);
      }
      if (body.dict_value !== undefined) {
        updates.push('dict_value = ?');
        params.push(body.dict_value);
      }
      if (body.sort_order !== undefined) {
        updates.push('sort_order = ?');
        params.push(body.sort_order);
      }
      if (body.status !== undefined) {
        updates.push('status = ?');
        params.push(body.status);
      }
      if (body.remark !== undefined) {
        updates.push('remark = ?');
        params.push(body.remark);
      }
      if (updates.length === 0) return errorResponse('没有需要更新的字段', 400, 400);
      updates.push('update_time = NOW()');
      params.push(body.id);
      await execute(
        `UPDATE sys_dict_data SET ${updates.join(', ')} WHERE id = ? AND deleted = 0`,
        params
      );
      return successResponse(null, '字典数据更新成功');
    }

    return errorResponse('无效的操作类型', 400, 400);
  },
  { errorMessage: '操作失败' }
);

// 删除字典（软删除）
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const action = searchParams.get('action');
    const id = searchParams.get('id');

    if (!id) return errorResponse('ID不能为空', 400, 400);

    if (action === 'delete_type') {
      // 先软删除该类型下的所有数据项，再软删除类型本身
      await execute(
        'UPDATE sys_dict_data SET deleted = 1, update_time = NOW() WHERE dict_type_id = ?',
        [Number(id)]
      );
      await execute('UPDATE sys_dict_type SET deleted = 1, update_time = NOW() WHERE id = ?', [
        Number(id),
      ]);
      return successResponse(null, '字典类型及数据已删除');
    }

    if (action === 'delete_data') {
      await execute('UPDATE sys_dict_data SET deleted = 1, update_time = NOW() WHERE id = ?', [
        Number(id),
      ]);
      return successResponse(null, '字典数据已删除');
    }

    return errorResponse('无效的操作类型', 400, 400);
  },
  { errorMessage: '操作失败' }
);

import { NextRequest } from 'next/server';
import { execute, queryOne, queryPaginated } from '@/lib/db';
import {
  successResponse,
  errorResponse,
  commonErrors,
  validateRequestBody,
  paginatedResponse,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { clearExchangeRateCache } from '@/application/services/CurrencyApplicationService';
import { UserInfo } from '@/lib/auth';

// GET - 汇率列表或最新汇率查询
export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const from = searchParams.get('from');
  const to = searchParams.get('to');
  const date = searchParams.get('date');
  const latest = searchParams.get('latest') === 'true';
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '20');

  // 查询最新汇率: /api/system/exchange-rate?from=USD&to=CNY&latest=true
  if (latest && from && to) {
    const rate = await queryOne(
      'SELECT * FROM sys_exchange_rate WHERE from_currency = ? AND to_currency = ? ORDER BY rate_date DESC LIMIT 1',
      [from, to]
    );
    if (!rate) {
      return successResponse(null, '未找到汇率记录');
    }
    return successResponse(rate);
  }

  // 查询指定日期汇率
  if (date && from && to) {
    const rate = await queryOne(
      'SELECT * FROM sys_exchange_rate WHERE from_currency = ? AND to_currency = ? AND rate_date = ? ORDER BY id DESC LIMIT 1',
      [from, to, date]
    );
    if (!rate) {
      return successResponse(null, '未找到指定日期的汇率记录');
    }
    return successResponse(rate);
  }

  // 分页列表
  let sql = 'SELECT * FROM sys_exchange_rate WHERE 1=1';
  let countSql = 'SELECT COUNT(*) as total FROM sys_exchange_rate WHERE 1=1';
  const values: Loose[] = [];

  if (from) {
    sql += ' AND from_currency = ?';
    countSql += ' AND from_currency = ?';
    values.push(from);
  }
  if (to) {
    sql += ' AND to_currency = ?';
    countSql += ' AND to_currency = ?';
    values.push(to);
  }

  sql += ' ORDER BY rate_date DESC, id DESC';

  const result = await queryPaginated(sql, countSql, values, { page, pageSize });
  return paginatedResponse(result.data, result.pagination);
});

// POST - 录入汇率
export const POST = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const body = await request.json();
    const validation = validateRequestBody(body, [
      'from_currency',
      'to_currency',
      'rate',
      'rate_date',
    ]);
    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    if (body.from_currency === body.to_currency) {
      return errorResponse('源币种和目标币种不能相同', 400, 400);
    }

    const rate = Number(body.rate);
    if (!Number.isFinite(rate) || rate <= 0) {
      return errorResponse('汇率必须大于 0', 400, 400);
    }

    const fromExists = await queryOne('SELECT 1 FROM sys_currency WHERE code = ? AND deleted = 0', [
      body.from_currency,
    ]);
    if (!fromExists) {
      return errorResponse('源币种不存在', 400, 400);
    }
    const toExists = await queryOne('SELECT 1 FROM sys_currency WHERE code = ? AND deleted = 0', [
      body.to_currency,
    ]);
    if (!toExists) {
      return errorResponse('目标币种不存在', 400, 400);
    }

    const result = await execute(
      `INSERT INTO sys_exchange_rate (from_currency, to_currency, rate, rate_date, source, remark, create_by)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [
        body.from_currency,
        body.to_currency,
        rate,
        body.rate_date,
        body.source ?? 'manual',
        body.remark ?? null,
        userInfo.userId,
      ]
    );

    clearExchangeRateCache();
    return successResponse({ id: result.insertId }, '汇率录入成功');
  },
  { logTitle: '录入汇率' }
);

// DELETE - 删除汇率记录
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    if (!id) {
      return commonErrors.badRequest('汇率记录ID不能为空');
    }

    await execute('DELETE FROM sys_exchange_rate WHERE id = ?', [parseInt(id)]);
    clearExchangeRateCache();
    return successResponse(null, '汇率记录删除成功');
  },
  { logTitle: '删除汇率' }
);

import { NextRequest, NextResponse } from 'next/server';
import { successResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';
import { query } from '@/lib/db';
import { getTranslator } from '@/lib/i18n-server';

/**
 * 操作日志导出 API
 * 支持CSV格式导出
 */

export const GET = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const userId = searchParams.get('userId') || '';
    const operation = searchParams.get('operation') || '';
    const moduleName = searchParams.get('module') || '';
    const businessType = searchParams.get('businessType') || '';
    const businessId = searchParams.get('businessId') || '';
    const startDate = searchParams.get('startDate') || '';
    const endDate = searchParams.get('endDate') || '';
    const format = searchParams.get('format') || 'csv';

    let where = 'WHERE 1=1';
    const params: Loose[] = [];

    if (userId) {
      where += ' AND l.user_id = ?';
      params.push(Number(userId));
    }
    if (operation) {
      where += ' AND l.operation LIKE ?';
      params.push(`%${operation}%`);
    }
    if (moduleName) {
      where += ' AND l.module = ?';
      params.push(moduleName);
    }
    if (businessType) {
      where += ' AND l.business_type = ?';
      params.push(businessType);
    }
    if (businessId) {
      where += ' AND l.business_id = ?';
      params.push(businessId);
    }
    if (startDate) {
      where += ' AND l.create_time >= ?';
      params.push(startDate + ' 00:00:00');
    }
    if (endDate) {
      where += ' AND l.create_time <= ?';
      params.push(endDate + ' 23:59:59');
    }

    const rows: Loose = await query(
      `SELECT l.*, u.real_name as operator_name
       FROM sys_operation_log l
       LEFT JOIN sys_user u ON l.user_id = u.id
       ${where}
       ORDER BY l.create_time DESC
       LIMIT 10000`,
      params
    );

    if (format === 'csv') {
      // 获取翻译函数
      const t = await getTranslator('Export');

      // 生成CSV表头
      const headers = [
        t('id'),
        t('operator'),
        t('operationType'),
        t('module'),
        t('businessType'),
        t('businessId'),
        t('ipAddress'),
        t('status'),
        t('description'),
        t('time'),
      ];

      const csvRows = rows.map((r: Loose) => [
        r.id,
        r.operator_name || r.username || '',
        r.operation || '',
        r.module || '',
        r.business_type || '',
        r.business_id || '',
        r.ip_address || '',
        r.status === 1 ? t('success') : t('failed'),
        (r.description || '').replace(/"/g, '""'),
        r.create_time || '',
      ]);

      const csvContent = [
        headers.join(','),
        ...csvRows.map((row: Loose[]) => row.map((v: Loose) => `"${v}"`).join(',')),
      ].join('\n');

      const bom = '\uFEFF';
      const csvBuffer = Buffer.from(bom + csvContent, 'utf-8');

      return new NextResponse(csvBuffer, {
        headers: {
          'Content-Type': 'text/csv; charset=utf-8',
          'Content-Disposition': `attachment; filename=operation_log_${new Date().toISOString().slice(0, 10)}.csv`,
        },
      });
    }

    return successResponse({ list: rows, total: rows.length });
  },
  { errorMessage: '操作失败' }
);

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';
