/**
 * 个人中心 API
 * GET - 获取个人信息
 * PUT - 更新个人信息 / 修改密码
 */

export const GET = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const rows: Loose = await query(
      `SELECT id, username, real_name, avatar, email, phone, department_id,
              last_login_time, last_login_ip, pwd_update_time
       FROM sys_user WHERE id = ? AND deleted = 0`,
      [userInfo.userId]
    );

    if (rows.length === 0) {
      return errorResponse('用户不存在', 404, 404);
    }

    const user = rows[0];
    return successResponse({
      id: user.id,
      username: user.username,
      realName: user.real_name,
      avatar: user.avatar,
      email: user.email,
      phone: user.phone,
      departmentId: user.department_id,
      lastLoginTime: user.last_login_time,
      lastLoginIp: user.last_login_ip,
      pwdUpdateTime: user.pwd_update_time,
    });
  },
  { errorMessage: '操作失败' }
);

export const PUT = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const body = await request.json();
    const { action } = body;

    // 修改密码
    if (action === 'password') {
      const { oldPassword, newPassword } = body;

      if (!oldPassword || !newPassword) {
        return errorResponse('请填写完整密码信息', 400, 400);
      }

      if (newPassword.length < 6) {
        return errorResponse('新密码长度不能少于6位', 400, 400);
      }

      const users: Loose = await query('SELECT password FROM sys_user WHERE id = ?', [
        userInfo.userId,
      ]);

      if (users.length === 0) {
        return errorResponse('用户不存在', 404, 404);
      }

      const isValid = await bcrypt.compare(oldPassword, users[0].password);
      if (!isValid) {
        return errorResponse('当前密码不正确', 400, 400);
      }

      const hashedPassword = await bcrypt.hash(newPassword, 10);
      await execute(
        'UPDATE sys_user SET password = ?, pwd_update_time = NOW(), first_login = 0, update_time = NOW() WHERE id = ?',
        [hashedPassword, userInfo.userId]
      );

      return successResponse(null, '密码修改成功');
    }

    // 更新基本信息
    const { realName, phone, email } = body;
    const updates: string[] = [];
    const params: Loose[] = [];

    if (realName !== undefined) {
      updates.push('real_name = ?');
      params.push(realName);
    }
    if (phone !== undefined) {
      updates.push('phone = ?');
      params.push(phone);
    }
    if (email !== undefined) {
      updates.push('email = ?');
      params.push(email);
    }

    if (updates.length === 0) {
      return errorResponse('没有需要更新的字段', 400, 400);
    }

    updates.push('update_time = NOW()');
    params.push(userInfo.userId);

    await execute(`UPDATE sys_user SET ${updates.join(', ')} WHERE id = ?`, params);

    return successResponse(null, '个人信息更新成功');
  },
  { errorMessage: '操作失败' }
);

import { NextRequest } from 'next/server';
import { query, execute } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';

export const GET = withPermission(async (request: NextRequest, _userInfo: UserInfo) => {
  const { searchParams } = new URL(request.url);
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '20');
  const withPermissions = searchParams.get('withPermissions') === 'true';

  const countResult: Loose = await query(
    'SELECT COUNT(*) as total FROM sys_role WHERE deleted = 0'
  );
  const total = countResult[0]?.total || 0;

  const rows: Loose = await query(
    `SELECT id, role_name, role_code, parent_id, inherit_mode, description, data_scope, status, permissions, create_time
     FROM sys_role WHERE deleted = 0 ORDER BY id LIMIT ? OFFSET ?`,
    [pageSize, (page - 1) * pageSize]
  );

  // 解析权限JSON
  const list = rows.map((row: Loose) => ({
    ...row,
    permissions:
      typeof row.permissions === 'string'
        ? JSON.parse(row.permissions || '[]')
        : row.permissions || [],
  }));

  // 如果需要继承权限，解析完整权限链
  if (withPermissions) {
    for (const role of list) {
      role.effectivePermissions = await resolveEffectivePermissions(role.id);
      role.parentRole = role.parent_id ? await getParentRoleName(role.parent_id) : null;
    }
  }

  return successResponse({ list, total, page, pageSize });
});

// 解析角色的有效权限（包含继承的权限）
async function resolveEffectivePermissions(
  roleId: number,
  visited = new Set<number>()
): Promise<string[]> {
  if (visited.has(roleId)) return []; // 防止循环继承
  visited.add(roleId);

  const role: Loose = await query(
    'SELECT id, parent_id, inherit_mode, permissions FROM sys_role WHERE id = ? AND deleted = 0',
    [roleId]
  );

  if (role.length === 0) return [];

  const currentPermissions =
    typeof role[0].permissions === 'string'
      ? JSON.parse(role[0].permissions || '[]')
      : role[0].permissions || [];

  if (!role[0].parent_id) {
    return currentPermissions;
  }

  const parentPermissions = await resolveEffectivePermissions(role[0].parent_id, visited);

  if (role[0].inherit_mode === 'override') {
    // 覆盖模式：仅使用自身权限
    return currentPermissions.length > 0 ? currentPermissions : parentPermissions;
  }

  // 合并模式：合并父权限和自身权限
  return [...new Set([...parentPermissions, ...currentPermissions])];
}

async function getParentRoleName(parentId: number): Promise<string | null> {
  const rows: Loose = await query('SELECT role_name FROM sys_role WHERE id = ? AND deleted = 0', [
    parentId,
  ]);
  return rows.length > 0 ? rows[0].role_name : null;
}

export const POST = withPermission(async (request: NextRequest, _userInfo: UserInfo) => {
  const body = await request.json();
  const {
    role_name,
    role_code,
    parent_id,
    inherit_mode,
    description,
    data_scope,
    status,
    permissions,
  } = body;

  if (!role_name || !role_code) return errorResponse('ROLE_NAME_CODE_REQUIRED', 400, 400);

  const existing: Loose = await query(
    'SELECT id FROM sys_role WHERE role_code = ? AND deleted = 0',
    [role_code]
  );
  if (existing.length > 0) return errorResponse('ROLE_CODE_EXISTS', 400, 400);

  // 验证父角色是否存在且不形成循环
  if (parent_id) {
    const parent: Loose = await query(
      'SELECT id, parent_id FROM sys_role WHERE id = ? AND deleted = 0',
      [parent_id]
    );
    if (parent.length === 0) return errorResponse('PARENT_ROLE_NOT_FOUND', 400, 400);
  }

  const result: Loose = await execute(
    'INSERT INTO sys_role (role_name, role_code, parent_id, inherit_mode, description, data_scope, status, permissions) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
    [
      role_name,
      role_code,
      parent_id || null,
      inherit_mode || 'merge',
      description || null,
      data_scope || 1,
      status ?? 1,
      JSON.stringify(permissions || []),
    ]
  );

  return successResponse({ id: result.insertId }, 'ROLE_CREATED');
});

export const PUT = withPermission(async (request: NextRequest, _userInfo: UserInfo) => {
  const body = await request.json();
  const {
    id,
    role_name,
    role_code,
    parent_id,
    inherit_mode,
    description,
    data_scope,
    status,
    permissions,
  } = body;

  if (!id) return errorResponse('ROLE_ID_REQUIRED', 400, 400);

  // 验证不形成循环继承
  if (parent_id !== undefined && parent_id !== null) {
    if (parent_id === id) return errorResponse('CANNOT_SET_SELF_AS_PARENT', 400, 400);
    // 检查父角色的祖先链中是否包含当前角色
    let checkId = parent_id;
    const visited = new Set<number>();
    while (checkId) {
      if (checkId === id) return errorResponse('CANNOT_FORM_CIRCULAR_INHERITANCE', 400, 400);
      if (visited.has(checkId)) break;
      visited.add(checkId);
      const parent: Loose = await query(
        'SELECT parent_id FROM sys_role WHERE id = ? AND deleted = 0',
        [checkId]
      );
      checkId = parent.length > 0 ? parent[0].parent_id : null;
    }
  }

  const fields: string[] = [];
  const values: Loose[] = [];
  if (role_name !== undefined) {
    fields.push('role_name = ?');
    values.push(role_name);
  }
  if (role_code !== undefined) {
    fields.push('role_code = ?');
    values.push(role_code);
  }
  if (parent_id !== undefined) {
    fields.push('parent_id = ?');
    values.push(parent_id);
  }
  if (inherit_mode !== undefined) {
    fields.push('inherit_mode = ?');
    values.push(inherit_mode);
  }
  if (description !== undefined) {
    fields.push('description = ?');
    values.push(description);
  }
  if (data_scope !== undefined) {
    fields.push('data_scope = ?');
    values.push(data_scope);
  }
  if (status !== undefined) {
    fields.push('status = ?');
    values.push(status);
  }
  if (permissions !== undefined) {
    fields.push('permissions = ?');
    values.push(JSON.stringify(permissions));
  }

  if (fields.length === 0) return errorResponse('NO_FIELDS_TO_UPDATE', 400, 400);

  values.push(id);
  await execute(`UPDATE sys_role SET ${fields.join(', ')} WHERE id = ? AND deleted = 0`, values);

  return successResponse(null, 'ROLE_UPDATED');
});

export const DELETE = withPermission(async (request: NextRequest, _userInfo: UserInfo) => {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');
  if (!id) return errorResponse('ROLE_ID_REQUIRED', 400, 400);

  // 检查是否有子角色
  const children: Loose = await query(
    'SELECT id FROM sys_role WHERE parent_id = ? AND deleted = 0',
    [Number(id)]
  );
  if (children.length > 0) return errorResponse('ROLE_HAS_CHILDREN', 400, 400);

  await execute('UPDATE sys_role SET deleted = 1 WHERE id = ?', [Number(id)]);
  return successResponse(null, 'ROLE_DELETED');
});

import { NextRequest } from 'next/server';
import {
  successResponse,
  paginatedResponse,
  errorResponse,
  validateRequestBody,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';
import { query, execute } from '@/lib/db';

// 获取定时任务列表
export const GET = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');
    const status = searchParams.get('status') || '';
    const taskGroup = searchParams.get('taskGroup') || '';

    let where = 'WHERE 1=1';
    const params: Loose[] = [];

    if (status) {
      where += ' AND status = ?';
      params.push(status);
    }
    if (taskGroup) {
      where += ' AND task_group = ?';
      params.push(taskGroup);
    }

    const countRows: Loose = await query(
      `SELECT COUNT(*) as total FROM sys_scheduled_task ${where}`,
      params
    );
    const total = countRows[0]?.total || 0;
    const totalPages = Math.ceil(total / pageSize);

    const rows: Loose = await query(
      `SELECT * FROM sys_scheduled_task ${where} ORDER BY id DESC LIMIT ? OFFSET ?`,
      [...params, pageSize, (page - 1) * pageSize]
    );

    return paginatedResponse(rows, { page, pageSize, total, totalPages });
  },
  { errorMessage: '操作失败' }
);

// 创建/更新定时任务
export const POST = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const body = await request.json();
    const validation = validateRequestBody(body, ['task_name', 'task_type', 'cron_expression']);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    const { task_name, task_type, cron_expression, task_group, description, config } = body;

    const result: Loose = await execute(
      `INSERT INTO sys_scheduled_task
       (task_name, task_type, task_group, cron_expression, description, config, status, create_by, create_time)
       VALUES (?, ?, ?, ?, ?, ?, 'active', ?, NOW())`,
      [
        task_name,
        task_type,
        task_group || 'default',
        cron_expression,
        description || null,
        config ? JSON.stringify(config) : null,
        userInfo.userId,
      ]
    );

    return successResponse({ id: result.insertId }, '定时任务创建成功');
  },
  { errorMessage: '操作失败' }
);

// 更新任务状态
export const PUT = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const body = await request.json();
    const { id, action } = body;

    if (!id || !action) {
      return errorResponse('参数不完整', 400, 400);
    }

    if (action === 'pause') {
      await execute('UPDATE sys_scheduled_task SET status = ? WHERE id = ?', ['paused', id]);
      return successResponse(null, '任务已暂停');
    }

    if (action === 'resume') {
      await execute('UPDATE sys_scheduled_task SET status = ? WHERE id = ?', ['active', id]);
      return successResponse(null, '任务已恢复');
    }

    if (action === 'execute') {
      // 手动触发执行
      const tasks: Loose = await query('SELECT * FROM sys_scheduled_task WHERE id = ?', [id]);
      if (tasks.length === 0) {
        return errorResponse('任务不存在', 404, 404);
      }

      const task = tasks[0];
      try {
        await execute(
          `INSERT INTO sys_task_execution_log
           (task_id, task_name, start_time, status)
           VALUES (?, ?, NOW(), 'running')`,
          [task.id, task.task_name]
        );

        // 根据任务类型执行对应逻辑
        let executionResult = '';
        if (task.task_type === 'inventory_alert') {
          executionResult = await executeInventoryAlert();
        } else if (task.task_type === 'data_cleanup') {
          executionResult = await executeDataCleanup(task.config);
        } else if (task.task_type === 'report_generation') {
          executionResult = await executeReportGeneration(task.config);
        } else {
          executionResult = `任务类型 ${task.task_type} 暂不支持自动执行`;
        }

        await execute(
          `UPDATE sys_task_execution_log SET end_time = NOW(), status = 'success', result = ? WHERE task_id = ? AND status = 'running'`,
          [executionResult, task.id]
        );

        await execute(
          'UPDATE sys_scheduled_task SET last_execute_time = NOW(), last_result = ? WHERE id = ?',
          [executionResult, id]
        );

        return successResponse({ result: executionResult }, '任务执行完成');
      } catch (error) {
        await execute(
          `UPDATE sys_task_execution_log SET end_time = NOW(), status = 'failed', result = ? WHERE task_id = ? AND status = 'running'`,
          [(error as Error).message, task.id]
        );
        return errorResponse(`任务执行失败: ${(error as Error).message}`, 500, 500);
      }
    }

    if (action === 'update') {
      const { task_name, cron_expression, description, config } = body;
      const updates: string[] = [];
      const params: Loose[] = [];

      if (task_name) {
        updates.push('task_name = ?');
        params.push(task_name);
      }
      if (cron_expression) {
        updates.push('cron_expression = ?');
        params.push(cron_expression);
      }
      if (description !== undefined) {
        updates.push('description = ?');
        params.push(description);
      }
      if (config) {
        updates.push('config = ?');
        params.push(JSON.stringify(config));
      }

      if (updates.length === 0) {
        return errorResponse('没有需要更新的字段', 400, 400);
      }

      params.push(id);
      await execute(`UPDATE sys_scheduled_task SET ${updates.join(', ')} WHERE id = ?`, params);
      return successResponse(null, '任务更新成功');
    }

    return errorResponse('不支持的操作', 400, 400);
  },
  { errorMessage: '操作失败' }
);

// 删除任务
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    if (!id) return errorResponse('任务ID不能为空', 400, 400);

    await execute('DELETE FROM sys_scheduled_task WHERE id = ?', [Number(id)]);
    return successResponse(null, '任务删除成功');
  },
  { errorMessage: '操作失败' }
);

// 任务执行逻辑
async function executeInventoryAlert(): Promise<string> {
  const alerts: Loose = await query(
    `SELECT s.material_id, m.material_name, s.quantity, w.warehouse_name
     FROM stock s
     LEFT JOIN materials m ON s.material_id = m.id
     LEFT JOIN warehouses w ON s.warehouse_id = w.id
     WHERE s.quantity <= 10`
  );
  return `库存预警检查完成，发现 ${alerts.length} 条低库存记录`;
}

async function executeDataCleanup(config: string | null): Promise<string> {
  let retentionDays = 180;
  if (config) {
    try {
      const cfg = JSON.parse(config);
      retentionDays = cfg.retentionDays || 180;
    } catch {
      /* use default */
    }
  }

  const result: Loose = await execute(
    `DELETE FROM sys_operation_log WHERE create_time < DATE_SUB(NOW(), INTERVAL ? DAY)`,
    [retentionDays]
  );
  return `数据清理完成，删除 ${result.affectedRows || 0} 条过期日志`;
}

async function executeReportGeneration(_config: string | null): Promise<string> {
  return '报表生成任务已触发（异步执行中）';
}

