﻿import { NextRequest } from 'next/server';
import { writeFile } from 'fs/promises';
import { mkdir } from 'fs/promises';
import { join } from 'path';
import { existsSync } from 'fs';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { validateUploadContent } from '@/lib/file-upload-security';

const UPLOAD_CONFIG = {
  maxSize: 50 * 1024 * 1024,
  allowedTypes: ['application/pdf'],
  allowedExtensions: ['pdf'],
  uploadDir: 'public/uploads/sop',
};

function generateUniqueFilename(originalName: string): string {
  const timestamp = Date.now();
  const random = Math.random().toString(36).substring(2, 8);
  const extension = originalName.split('.').pop()?.toLowerCase() || 'pdf';
  return `${timestamp}-${random}.${extension}`;
}

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const formData = await request.formData();
    const file = formData.get('file') as File;

    if (!file) {
      return errorResponse('未找到上传的文件', 400, 400);
    }

    const extension = file.name.split('.').pop()?.toLowerCase() || '';
    if (!UPLOAD_CONFIG.allowedExtensions.includes(extension)) {
      return errorResponse('只能上传PDF文件', 400, 400);
    }

    if (file.size > UPLOAD_CONFIG.maxSize) {
      return errorResponse(`文件大小不能超过 ${UPLOAD_CONFIG.maxSize / 1024 / 1024}MB`, 400, 400);
    }

    // 安全：读取内容后按魔数校验真实类型，拒绝伪装扩展名与 HTML/SVG 脚本内容
    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);
    const contentCheck = validateUploadContent(buffer, extension);
    if (!contentCheck.ok) {
      return errorResponse(contentCheck.message, 400, 400);
    }

    const filename = generateUniqueFilename(file.name);

    const uploadDir = join(process.cwd(), UPLOAD_CONFIG.uploadDir);
    if (!existsSync(uploadDir)) {
      await mkdir(uploadDir, { recursive: true });
    }

    const filePath = join(uploadDir, filename);
    await writeFile(filePath, buffer);

    const fileUrl = `/uploads/sop/${filename}`;

    return successResponse(
      {
        url: fileUrl,
        filename: filename,
        originalName: file.name,
        size: file.size,
        type: file.type,
      },
      '上传成功'
    );
  },
  { logTitle: '上传SOP文件' }
);

import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';
import { query, execute } from '@/lib/db';

/**
 * 库存预警推送 API
 *
 * 支持站内信、邮件推送库存预警通知
 * 可配置预警规则和推送方式
 */

// 获取预警推送配置
export const GET = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const type = searchParams.get('type') || 'config';

    if (type === 'config') {
      // 获取推送配置
      const configs: Loose = await query(
        'SELECT * FROM sys_config WHERE config_group = ? ORDER BY sort_order',
        ['inventory_alert']
      );
      return successResponse({ configs });
    }

    if (type === 'notifications') {
      // 获取预警通知列表
      const page = parseInt(searchParams.get('page') || '1');
      const pageSize = parseInt(searchParams.get('pageSize') || '20');
      const unreadOnly = searchParams.get('unread') === 'true';

      let where = 'WHERE n.type = ?';
      const params: Loose[] = ['inventory_alert'];

      if (unreadOnly) {
        where += ' AND n.is_read = 0';
      }

      // 优先显示当前用户的通知
      where += ' AND (n.user_id = ? OR n.user_id IS NULL)';
      params.push(userInfo.userId);

      const countRows: Loose = await query(
        `SELECT COUNT(*) as total FROM sys_notification n ${where}`,
        params
      );
      const total = countRows[0]?.total || 0;

      const rows: Loose = await query(
        `SELECT n.* FROM sys_notification n ${where}
         ORDER BY n.create_time DESC
         LIMIT ? OFFSET ?`,
        [...params, pageSize, (page - 1) * pageSize]
      );

      return successResponse({ list: rows, total, page, pageSize });
    }

    if (type === 'rules') {
      // 获取预警规则
      const rules: Loose = await query(
        'SELECT * FROM inv_alert_rule WHERE deleted = 0 ORDER BY id'
      );
      return successResponse({ rules });
    }

    return errorResponse('无效的查询类型', 400, 400);
  },
  { errorMessage: '操作失败' }
);

// 创建/更新预警规则 或 手动触发推送
export const POST = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const body = await request.json();
    const { action } = body;

    if (action === 'push') {
      // 手动触发预警推送
      return await triggerAlertPush(userInfo);
    }

    if (action === 'create_rule') {
      // 创建预警规则
      const {
        rule_name,
        material_id,
        warehouse_id,
        alert_type,
        threshold,
        notify_method,
        notify_users,
      } = body;

      if (!rule_name || !alert_type || threshold === undefined) {
        return errorResponse('规则名称、预警类型和阈值不能为空', 400, 400);
      }

      const result: Loose = await execute(
        `INSERT INTO inv_alert_rule
         (rule_name, material_id, warehouse_id, alert_type, threshold, notify_method, notify_users, enabled, create_by, create_time, update_time)
         VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, NOW(), NOW())`,
        [
          rule_name,
          material_id || null,
          warehouse_id || null,
          alert_type,
          threshold,
          notify_method || 'in_app',
          notify_users || null,
          userInfo.userId,
        ]
      );

      return successResponse({ id: result.insertId }, '预警规则创建成功');
    }

    if (action === 'mark_read') {
      // 标记通知已读
      const { notification_ids } = body;
      if (!notification_ids || !Array.isArray(notification_ids)) {
        return errorResponse('通知ID列表不能为空', 400, 400);
      }
      await execute(
        `UPDATE sys_notification SET is_read = 1, read_time = NOW() WHERE id IN (${notification_ids.map(() => '?').join(',')})`,
        notification_ids
      );
      return successResponse(null, '已标记为已读');
    }

    return errorResponse('无效的操作类型', 400, 400);
  },
  { errorMessage: '操作失败' }
);

// 更新预警规则
export const PUT = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const body = await request.json();
    const { id, rule_name, alert_type, threshold, notify_method, notify_users, enabled } = body;

    if (!id) {
      return errorResponse('规则ID不能为空', 400, 400);
    }

    const updates: string[] = [];
    const params: Loose[] = [];

    if (rule_name !== undefined) {
      updates.push('rule_name = ?');
      params.push(rule_name);
    }
    if (alert_type !== undefined) {
      updates.push('alert_type = ?');
      params.push(alert_type);
    }
    if (threshold !== undefined) {
      updates.push('threshold = ?');
      params.push(threshold);
    }
    if (notify_method !== undefined) {
      updates.push('notify_method = ?');
      params.push(notify_method);
    }
    if (notify_users !== undefined) {
      updates.push('notify_users = ?');
      params.push(notify_users);
    }
    if (enabled !== undefined) {
      updates.push('enabled = ?');
      params.push(enabled ? 1 : 0);
    }

    if (updates.length === 0) {
      return errorResponse('没有需要更新的字段', 400, 400);
    }

    updates.push('update_time = NOW()');
    params.push(id);

    await execute(`UPDATE inv_alert_rule SET ${updates.join(', ')} WHERE id = ?`, params);

    return successResponse(null, '预警规则更新成功');
  },
  { errorMessage: '操作失败' }
);

// 触发预警推送
async function triggerAlertPush(userInfo: UserInfo) {
  // 查询所有低于安全库存的物料
  const alerts: Loose = await query(
    `SELECT s.material_id, s.warehouse_id, s.quantity, m.material_name, m.material_code, m.safety_stock, m.unit,
            w.warehouse_name
     FROM stock s
     LEFT JOIN materials m ON s.material_id = m.id
     LEFT JOIN warehouses w ON s.warehouse_id = w.id
     WHERE s.quantity <= COALESCE(m.safety_stock, 0) AND s.quantity >= 0 AND m.safety_stock > 0`
  );

  if (alerts.length === 0) {
    return successResponse({ alertCount: 0 }, '当前无库存预警');
  }

  // 获取需要通知的用户（仓库管理员和系统管理员）
  const notifyUsers: Loose = await query(
    `SELECT u.id, u.real_name, u.email FROM sys_user u
     WHERE u.status = 1 AND (u.role_id IN (SELECT id FROM sys_role WHERE role_key IN ('admin', 'warehouse_manager')) OR u.id = ?)`,
    [userInfo.userId]
  );

  let pushCount = 0;

  for (const alert of alerts) {
    const title = `库存预警：${alert.material_name} 库存不足`;
    const content = `物料 ${alert.material_code}(${alert.material_name}) 在仓库 ${alert.warehouse_name} 的当前库存为 ${alert.quantity} ${alert.unit || ''}，低于安全库存 ${alert.safety_stock} ${alert.unit || ''}，请及时补货。`;

    for (const user of notifyUsers) {
      await execute(
        `INSERT INTO sys_notification (type, title, content, user_id, is_read, create_time)
         VALUES (?, ?, ?, ?, 0, NOW())`,
        ['inventory_alert', title, content, user.id]
      );
      pushCount++;
    }
  }

  return successResponse(
    {
      alertCount: alerts.length,
      pushCount,
      alerts: alerts.map((a: Loose) => ({
        material_code: a.material_code,
        material_name: a.material_name,
        warehouse_name: a.warehouse_name,
        quantity: a.quantity,
        safety_stock: a.safety_stock,
        unit: a.unit,
      })),
    },
    `已推送 ${alerts.length} 条库存预警`
  );
}

﻿import { NextRequest } from 'next/server';
import { query, transaction } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';

import { withPermission } from '@/lib/api-permissions';
// 获取批次库存列表
export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const materialKeyword = searchParams.get('materialKeyword') || '';
  const batchNo = searchParams.get('batchNo') || '';
  const warehouseId = searchParams.get('warehouseId') || '';
  const status = searchParams.get('status') || '';
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '20');

  let whereClause = 'WHERE 1=1';
  const params: Loose[] = [];

  if (materialKeyword) {
    whereClause += ' AND (bi.material_name LIKE ? OR bi.material_code LIKE ?)';
    params.push(`%${materialKeyword}%`, `%${materialKeyword}%`);
  }

  if (batchNo) {
    whereClause += ' AND bi.batch_no = ?';
    params.push(batchNo);
  }

  if (warehouseId) {
    whereClause += ' AND bi.warehouse_id = ?';
    params.push(warehouseId);
  }

  if (status) {
    whereClause += ' AND bi.status = ?';
    params.push(status);
  }

  const offset = (page - 1) * pageSize;
  const rows: Loose = await query(
    `SELECT bi.*, w.warehouse_name 
     FROM inv_batch_inventory bi
     LEFT JOIN inv_warehouse w ON bi.warehouse_id = w.id
     ${whereClause}
     ORDER BY bi.inbound_date ASC, bi.batch_no ASC
     LIMIT ? OFFSET ?`,
    [...params, pageSize, offset]
  );

  const countRows: Loose = await query(
    `SELECT COUNT(*) as total FROM inv_batch_inventory bi ${whereClause}`,
    params
  );

  return successResponse({
    list: rows,
    total: countRows[0].total,
    page,
    pageSize,
  });
});

// 获取可用批次列表（用于出库时选择）
export const POST = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { material_id, warehouse_id, required_qty } = body;

  if (!material_id) {
    return errorResponse('物料ID不能为空', 400, 400);
  }

  let whereClause = 'WHERE bi.material_id = ? AND bi.available_quantity > 0 AND bi.status = 1';
  const params: Loose[] = [material_id];

  if (warehouse_id) {
    whereClause += ' AND bi.warehouse_id = ?';
    params.push(warehouse_id);
  }

  // 按入库日期升序（先进先出）
  const rows: Loose = await query(
    `SELECT bi.*, w.warehouse_name 
     FROM inv_batch_inventory bi
     LEFT JOIN inv_warehouse w ON bi.warehouse_id = w.id
     ${whereClause}
     ORDER BY bi.inbound_date ASC, bi.batch_no ASC`,
    params
  );

  // 计算自动分配方案（先进先出）
  let remaining = required_qty || 0;
  const allocationPlan: Loose[] = [];

  if (required_qty) {
    for (const batch of rows) {
      if (remaining <= 0) break;
      const allocateQty = Math.min(remaining, parseFloat(batch.available_quantity));
      allocationPlan.push({
        batch_inventory_id: batch.id,
        batch_no: batch.batch_no,
        warehouse_id: batch.warehouse_id,
        warehouse_name: batch.warehouse_name,
        allocate_qty: allocateQty,
        available_qty: batch.available_quantity,
      });
      remaining -= allocateQty;
    }
  }

  return successResponse({
    batches: rows,
    allocation_plan: allocationPlan,
    total_available: rows.reduce(
      (sum: number, b: Loose) => sum + parseFloat(b.available_quantity),
      0
    ),
    shortage: remaining > 0 ? remaining : 0,
  });
});

// 入库操作（新增批次库存）
export const PUT = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { inbound_no, warehouse_id, inbound_date, items, remark } = body;

  if (!items || !Array.isArray(items) || items.length === 0) {
    return errorResponse('入库明细不能为空', 400, 400);
  }

  return await transaction(async (conn) => {
    // 1. 创建入库单
    const [orderResult]: Loose = await conn.execute(
      `INSERT INTO inv_production_inbound (inbound_no, warehouse_id, inbound_date, qc_status, status, operator_name, remark) 
       VALUES (?, ?, ?, 1, 2, '系统', ?)`,
      [
        inbound_no || `IN${Date.now()}`,
        warehouse_id,
        inbound_date || new Date().toISOString().split('T')[0],
        remark || '',
      ]
    );
    const inboundId = orderResult.insertId;

    // 2. 处理每个入库明细
    for (const item of items) {
      const {
        material_id,
        material_code,
        material_name,
        specification,
        unit,
        quantity,
        batch_no,
        supplier_id,
        supplier_name,
      } = item;

      // 生成批次号（如果没有提供）
      const finalBatchNo =
        batch_no ||
        `B${Date.now().toString().slice(-8)}${Math.random().toString(36).substring(2, 5).toUpperCase()}`;

      // 2a. 插入入库明细
      await conn.execute(
        `INSERT INTO inv_production_inbound_item (inbound_id, material_id, material_code, material_name, quantity, unit, batch_no, remaining_qty, remark) 
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          inboundId,
          material_id,
          material_code,
          material_name,
          quantity,
          unit,
          finalBatchNo,
          quantity,
          remark || '',
        ]
      );

      // 2b. 检查批次库存是否已存在
      const [existing]: Loose = await conn.execute(
        `SELECT id, inbound_quantity, available_quantity FROM inv_batch_inventory 
         WHERE batch_no = ? AND material_id = ? AND warehouse_id = ?`,
        [finalBatchNo, material_id, warehouse_id]
      );

      if (existing.length > 0) {
        // 更新已有批次
        await conn.execute(
          `UPDATE inv_batch_inventory 
           SET inbound_quantity = inbound_quantity + ?, 
               available_quantity = available_quantity + ?,
               status = 1
           WHERE id = ?`,
          [quantity, quantity, existing[0].id]
        );
      } else {
        // 创建新批次
        await conn.execute(
          `INSERT INTO inv_batch_inventory (batch_no, material_id, material_code, material_name, specification, unit, warehouse_id, inbound_no, inbound_date, inbound_quantity, outbound_quantity, available_quantity, supplier_id, supplier_name, qc_status, status) 
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, ?, 1, 1)`,
          [
            finalBatchNo,
            material_id,
            material_code,
            material_name,
            specification || '',
            unit,
            warehouse_id,
            inbound_no,
            inbound_date,
            quantity,
            quantity,
            supplier_id || null,
            supplier_name || '',
          ]
        );
      }

      // 2c. 更新总库存表
      await conn.execute(
        `INSERT INTO inv_inventory (warehouse_id, material_id, material_code, material_name, total_qty, available_qty, unit, update_time) 
         VALUES (?, ?, ?, ?, ?, ?, ?, NOW())
         ON DUPLICATE KEY UPDATE 
           total_qty = total_qty + VALUES(total_qty),
           available_qty = available_qty + VALUES(available_qty),
           update_time = NOW()`,
        [warehouse_id, material_id, material_code, material_name, quantity, quantity, unit]
      );
    }

    return successResponse({ inbound_id: inboundId, inbound_no }, '入库成功，批次库存已更新');
  });
});

// 出库操作（扣减批次库存）
export const PATCH = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { outbound_no, customer_id, customer_name, warehouse_id, outbound_date, items, remark } =
    body;

  if (!items || !Array.isArray(items) || items.length === 0) {
    return errorResponse('出库明细不能为空', 400, 400);
  }

  return await transaction(async (conn) => {
    // 1. 创建出库单
    const [orderResult]: Loose = await conn.execute(
      `INSERT INTO inv_sales_outbound (outbound_no, customer_id, customer_name, warehouse_id, outbound_date, status, remark) 
       VALUES (?, ?, ?, ?, ?, 2, ?)`,
      [
        outbound_no || `SO${Date.now()}`,
        customer_id || null,
        customer_name || '',
        warehouse_id,
        outbound_date || new Date().toISOString().split('T')[0],
        remark || '',
      ]
    );
    const outboundId = orderResult.insertId;

    // 2. 处理每个出库明细
    for (const item of items) {
      const {
        material_id,
        material_code,
        material_name,
        unit,
        quantity,
        batch_inventory_id,
        batch_no,
        remark: itemRemark,
      } = item;

      let targetBatchId = batch_inventory_id;
      let targetBatchNo = batch_no;

      // 如果没有指定批次，自动按先进先出分配
      if (!targetBatchId) {
        const [availableBatches]: Loose = await conn.execute(
          `SELECT id, batch_no, available_quantity FROM inv_batch_inventory 
           WHERE material_id = ? AND warehouse_id = ? AND available_quantity > 0 AND status = 1
           ORDER BY inbound_date ASC, batch_no ASC`,
          [material_id, warehouse_id]
        );

        if (availableBatches.length === 0) {
          return errorResponse(`物料 ${material_name} 无可用库存`, 400, 400);
        }

        // 找到第一个有足够库存的批次
        for (const batch of availableBatches) {
          if (parseFloat(batch.available_quantity) >= quantity) {
            targetBatchId = batch.id;
            targetBatchNo = batch.batch_no;
            break;
          }
        }

        if (!targetBatchId) {
          // 如果单个批次库存不足，使用第一个批次（部分出库）
          targetBatchId = availableBatches[0].id;
          targetBatchNo = availableBatches[0].batch_no;
        }
      }

      // 3. 校验批次库存
      const [batch]: Loose = await conn.execute(
        `SELECT id, batch_no, material_code, material_name, available_quantity, unit 
         FROM inv_batch_inventory WHERE id = ? FOR UPDATE`,
        [targetBatchId]
      );

      if (batch.length === 0) {
        return errorResponse(`批次库存不存在`, 400, 400);
      }

      const availableQty = parseFloat(batch[0].available_quantity);
      if (availableQty < quantity) {
        return errorResponse(
          `批次 ${batch[0].batch_no} 可用库存不足：可用 ${availableQty} ${batch[0].unit}，需要 ${quantity} ${unit || batch[0].unit}`,
          400,
          400
        );
      }

      // 4. 扣减批次库存
      await conn.execute(
        `UPDATE inv_batch_inventory 
         SET outbound_quantity = outbound_quantity + ?, 
             available_quantity = available_quantity - ?,
             status = CASE WHEN (available_quantity - ?) <= 0 THEN 2 ELSE status END
         WHERE id = ?`,
        [quantity, quantity, quantity, targetBatchId]
      );

      // 5. 插入出库明细
      await conn.execute(
        `INSERT INTO inv_sales_outbound_item (outbound_id, material_id, material_code, material_name, quantity, unit, batch_no, batch_inventory_id, remark) 
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          outboundId,
          material_id,
          material_code,
          material_name,
          quantity,
          unit || batch[0].unit,
          targetBatchNo,
          targetBatchId,
          itemRemark || '',
        ]
      );

      // 6. 更新总库存表
      await conn.execute(
        `UPDATE inv_inventory 
         SET total_qty = total_qty - ?, 
             available_qty = available_qty - ?,
             update_time = NOW()
         WHERE warehouse_id = ? AND material_id = ?`,
        [quantity, quantity, warehouse_id, material_id]
      );
    }

    return successResponse({ outbound_id: outboundId, outbound_no }, '出库成功，批次库存已扣减');
  });
});

import { NextRequest } from 'next/server';
import {
  successResponse,
  paginatedResponse,
  errorResponse,
  validateRequestBody,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';
import { query, execute } from '@/lib/db';

/**
 * 批次/序列号管理 API
 *
 * 支持按批次管理物料，实现保质期预警、序列号追溯
 */

// 获取批次列表
export const GET = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const materialId = searchParams.get('materialId');
    const warehouseId = searchParams.get('warehouseId');
    const batchNo = searchParams.get('batchNo') || '';
    const serialNo = searchParams.get('serialNo') || '';
    const expiryWarning = searchParams.get('expiryWarning') === 'true';
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');

    let where = 'WHERE b.deleted = 0';
    const params: Loose[] = [];

    if (materialId) {
      where += ' AND b.material_id = ?';
      params.push(Number(materialId));
    }
    if (warehouseId) {
      where += ' AND b.warehouse_id = ?';
      params.push(Number(warehouseId));
    }
    if (batchNo) {
      where += ' AND b.batch_no LIKE ?';
      params.push(`%${batchNo}%`);
    }
    if (serialNo) {
      where += ' AND b.serial_no LIKE ?';
      params.push(`%${serialNo}%`);
    }
    if (expiryWarning) {
      // 查询即将过期的批次（30天内）
      where +=
        ' AND b.expire_date IS NOT NULL AND b.expire_date <= DATE_ADD(NOW(), INTERVAL 30 DAY) AND b.expire_date > NOW() AND b.quantity > 0';
    }

    const countRows: Loose = await query(
      `SELECT COUNT(*) as total FROM inv_inventory_batch b ${where}`,
      params
    );
    const total = countRows[0]?.total || 0;
    const totalPages = Math.ceil(total / pageSize);

    const rows: Loose = await query(
      `SELECT b.*, m.material_name, m.material_code, m.specification, m.unit,
              w.warehouse_name
       FROM inv_inventory_batch b
       LEFT JOIN inv_material m ON b.material_id = m.id
       LEFT JOIN inv_warehouse w ON b.warehouse_id = w.id
       ${where}
       ORDER BY b.id DESC
       LIMIT ? OFFSET ?`,
      [...params, pageSize, (page - 1) * pageSize]
    );

    return paginatedResponse(rows, { page, pageSize, total, totalPages });
  },
  { errorMessage: '操作失败' }
);

// 创建批次/序列号记录
export const POST = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const body = await request.json();
    const validation = validateRequestBody(body, [
      'material_id',
      'warehouse_id',
      'batch_no',
      'quantity',
    ]);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    const {
      material_id,
      warehouse_id,
      batch_no,
      serial_no,
      quantity,
      unit_price,
      cost_price,
      production_date,
      expiry_date,
      supplier_id,
      supplier_name,
      remark,
    } = body;

    // 检查批次是否已存在
    const existing: Loose = await query(
      'SELECT id, quantity FROM inv_inventory_batch WHERE material_id = ? AND warehouse_id = ? AND batch_no = ?',
      [material_id, warehouse_id, batch_no]
    );

    if (existing.length > 0) {
      // 批次已存在，增加数量
      const newQty = Number(existing[0].quantity) + Number(quantity);
      const newCostPrice = cost_price
        ? (Number(existing[0].quantity) * Number(existing[0].cost_price || 0) +
            Number(quantity) * Number(cost_price)) /
          newQty
        : existing[0].cost_price;

      await execute(
        `UPDATE inv_inventory_batch SET quantity = ?, cost_price = ?, update_time = NOW()
         WHERE id = ?`,
        [newQty, newCostPrice, existing[0].id]
      );

      return successResponse({ id: existing[0].id }, '批次数量已更新');
    }

    // 创建新批次
    const result: Loose = await execute(
      `INSERT INTO inv_inventory_batch
       (material_id, warehouse_id, batch_no, serial_no, quantity, available_qty,
        unit_price, cost_price, produce_date, expire_date,
        supplier_id, supplier_name, remark, create_time, update_time)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW())`,
      [
        material_id,
        warehouse_id,
        batch_no,
        serial_no || null,
        quantity,
        quantity,
        unit_price || 0,
        cost_price || 0,
        production_date || null,
        expiry_date || null,
        supplier_id || null,
        supplier_name || null,
        remark || null,
      ]
    );

    return successResponse({ id: result.insertId }, '批次创建成功');
  },
  { errorMessage: '操作失败' }
);

// 更新批次信息
export const PUT = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const body = await request.json();
    const { id, action } = body;

    if (!id) {
      return errorResponse('批次ID不能为空', 400, 400);
    }

    if (action === 'freeze') {
      // 冻结批次
      await execute('UPDATE inv_inventory_batch SET available_qty = 0, status = ? WHERE id = ?', [
        'frozen',
        id,
      ]);
      return successResponse(null, '批次已冻结');
    }

    if (action === 'unfreeze') {
      // 解冻批次
      const batch: Loose = await query('SELECT quantity FROM inv_inventory_batch WHERE id = ?', [
        id,
      ]);
      if (batch.length === 0) {
        return errorResponse('批次不存在', 404, 404);
      }
      await execute('UPDATE inv_inventory_batch SET available_qty = ?, status = ? WHERE id = ?', [
        batch[0].quantity,
        'active',
        id,
      ]);
      return successResponse(null, '批次已解冻');
    }

    // 通用更新
    const { production_date, expiry_date, remark } = body;
    const updates: string[] = [];
    const params: Loose[] = [];

    if (production_date !== undefined) {
      updates.push('produce_date = ?');
      params.push(production_date);
    }
    if (expiry_date !== undefined) {
      updates.push('expire_date = ?');
      params.push(expiry_date);
    }
    if (remark !== undefined) {
      updates.push('remark = ?');
      params.push(remark);
    }

    if (updates.length === 0) {
      return errorResponse('没有需要更新的字段', 400, 400);
    }

    updates.push('update_time = NOW()');
    params.push(id);

    await execute(`UPDATE inv_inventory_batch SET ${updates.join(', ')} WHERE id = ?`, params);

    return successResponse(null, '批次信息更新成功');
  },
  { errorMessage: '操作失败' }
);

﻿import { NextRequest } from 'next/server';
