      business_no: string;
      warehouse_name: string;
      operator_name: string;
      remark: string;
      create_time: string;
      document?: {
        type: string;
        id?: number;
        no?: string;
        status?: string;
        details?: Loose;
      };
    }> = [];

    const OPERATION_TYPE_LABELS = OPERATION_TYPE_LABEL;

    for (const log of logRows) {
      const entry: Loose = {
        log_id: log.id,
        operation_type: log.operation_type,
        operation_type_label:
          OPERATION_TYPE_LABELS[log.operation_type] || `类型${log.operation_type}`,
        operation_qty: parseFloat(log.operation_qty),
        before_qty: parseFloat(log.before_qty),
        after_qty: parseFloat(log.after_qty),
        business_type: log.business_type,
        business_no: log.business_no,
        warehouse_name: log.warehouse_name || '',
        operator_name: log.operator_name || '',
        remark: log.remark || '',
        create_time: log.create_time,
      };

      try {
        if (log.business_type === 'inbound_order' || log.business_type === 'inbound') {
          const [order]: Loose = await query(
            `SELECT o.id, o.order_no, o.status, o.supplier_name, o.inbound_date, o.total_amount,
                  o.warehouse_id
           FROM inv_inbound_order o
           WHERE o.order_no = ? AND o.deleted = 0`,
            [log.business_no]
          );
          if (order) {
            entry.document = {
              type: 'inbound',
              id: order.id,
              no: order.order_no,
              status: order.status,
              details: {
                supplier_name: order.supplier_name,
                inbound_date: order.inbound_date,
                total_amount: parseFloat(order.total_amount),
              },
            };
          }
        } else if (log.business_type === 'outbound_order' || log.business_type === 'outbound') {
          const [order]: Loose = await query(
            `SELECT o.id, o.order_no, o.status, o.outbound_type, o.customer_name,
                  o.work_order_no, o.total_amount, o.order_date
           FROM inv_outbound_order o
           WHERE o.order_no = ? AND o.deleted = 0`,
            [log.business_no]
          );
          if (order) {
            entry.document = {
              type: 'outbound',
              id: order.id,
              no: order.order_no,
              status: order.status,
              details: {
                outbound_type: order.outbound_type,
                customer_name: order.customer_name,
                work_order_no: order.work_order_no,
                total_amount: parseFloat(order.total_amount),
                order_date: order.order_date,
              },
            };
          }
        } else if (log.business_type === 'transfer' || log.business_type === 'transfer_order') {
          const [order]: Loose = await query(
            `SELECT t.id, t.transfer_no, t.status, t.type,
                  t.from_warehouse_id, t.to_warehouse_id,
                  fw.warehouse_name as from_warehouse_name,
                  tw.warehouse_name as to_warehouse_name,
                  t.total_qty, t.total_amount
           FROM inv_transfer_order t
           LEFT JOIN inv_warehouse fw ON t.from_warehouse_id = fw.id
           LEFT JOIN inv_warehouse tw ON t.to_warehouse_id = tw.id
           WHERE t.transfer_no = ? AND t.deleted = 0`,
            [log.business_no]
          );
          if (order) {
            entry.document = {
              type: 'transfer',
              id: order.id,
              no: order.transfer_no,
              status: order.status,
              details: {
                transfer_type: order.type,
                from_warehouse_name: order.from_warehouse_name,
                to_warehouse_name: order.to_warehouse_name,
                total_qty: parseFloat(order.total_qty),
                total_amount: parseFloat(order.total_amount),
              },
            };
          }
        } else if (
          log.business_type === 'stocktaking' ||
          log.business_type === 'stocktaking_order'
        ) {
          const [order]: Loose = await query(
            `SELECT s.id, s.check_no, s.status, s.type, s.warehouse_name,
                  s.diff_items, s.total_diff_amount
           FROM inv_stocktaking s
           WHERE s.check_no = ? AND s.deleted = 0`,
            [log.business_no]
          );
          if (order) {
            entry.document = {
              type: 'stocktaking',
              id: order.id,
              no: order.check_no,
              status: order.status,
              details: {
                stocktaking_type: order.type,
                warehouse_name: order.warehouse_name,
                diff_items: order.diff_items,
                total_diff_amount: parseFloat(order.total_diff_amount),
              },
            };
          }
        } else if (log.business_type === 'stock_adjust' || log.business_type === 'adjust') {
          const [order]: Loose = await query(
            `SELECT a.id, a.adjust_no, a.status, a.adjust_type, a.total_amount
           FROM inv_stock_adjust a
           WHERE a.adjust_no = ? AND a.deleted = 0`,
            [log.business_no]
          );
          if (order) {
            entry.document = {
              type: 'stock_adjust',
              id: order.id,
              no: order.adjust_no,
              status: order.status,
              details: {
                adjust_type: order.adjust_type,
                total_amount: parseFloat(order.total_amount),
              },
            };
          }
        }
      } catch {
        // If document lookup fails, continue without document details
      }

      traceChain.push(entry);
    }

    const totalIn = logRows
      .filter((l: Loose) => l.operation_type === 1)
      .reduce((sum: number, l: Loose) => sum + parseFloat(l.operation_qty), 0);
    const totalOut = logRows
      .filter((l: Loose) => l.operation_type === 2)
      .reduce((sum: number, l: Loose) => sum + parseFloat(l.operation_qty), 0);

    return successResponse({
      batch: {
        batch_no: batchSnapshot.batch_no,
        material_id: batchSnapshot.material_id,
        material_code: batchSnapshot.material_code,
        material_name: batchSnapshot.material_name,
        warehouse_id: batchSnapshot.warehouse_id,
        location: batchSnapshot.location,
        quantity: parseFloat(batchSnapshot.quantity),
        available_qty: parseFloat(batchSnapshot.available_qty),
        locked_qty: parseFloat(batchSnapshot.locked_qty),
        unit_cost: parseFloat(batchSnapshot.unit_cost || batchSnapshot.unit_price || 0),
        inbound_date: batchSnapshot.inbound_date,
        produce_date: batchSnapshot.produce_date,
        expire_date: batchSnapshot.expire_date,
        status: batchSnapshot.status,
        create_time: batchSnapshot.create_time,
        update_time: batchSnapshot.update_time,
      },
      trace_chain: traceChain,
      summary: {
        total_records: traceChain.length,
        total_in: totalIn,
        total_out: totalOut,
        net_change: totalIn - totalOut,
      },
    });
  },
  { errorMessage: '批次追溯查询失败' }
);

import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api-response';
import { UserInfo } from '@/lib/api-auth';
import { withPermission } from '@/lib/api-permissions';
import { query, execute } from '@/lib/db';

/**
 * 移动加权平均成本核算 API
 *
 * 移动加权平均法：每次入库后重新计算平均成本
 * 公式：新平均成本 = (原库存金额 + 本次入库金额) / (原库存数量 + 本次入库数量)
 */

// 获取物料成本信息
export const GET = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const materialId = searchParams.get('materialId');
    const warehouseId = searchParams.get('warehouseId');
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');

    if (materialId) {
      // 查询指定物料的成本信息
      const rows: Loose = await query(
        `SELECT s.*, m.material_name, m.material_code, m.material_spec, m.unit,
                w.warehouse_name
         FROM stock s
         LEFT JOIN materials m ON s.material_id = m.id
         LEFT JOIN warehouses w ON s.warehouse_id = w.id
         WHERE s.material_id = ? ${warehouseId ? 'AND s.warehouse_id = ?' : ''}
         ORDER BY s.warehouse_id`,
        warehouseId ? [Number(materialId), Number(warehouseId)] : [Number(materialId)]
      );

      // 查询成本变动历史
      const history: Loose = await query(
        `SELECT sm.*, m.material_name, m.material_code
         FROM stock_movement sm
         LEFT JOIN materials m ON sm.material_id = m.id
         WHERE sm.material_id = ?
         AND sm.movement_type IN ('purchase_inbound', 'sales_return', 'production_inbound', 'transfer_in')
         ORDER BY sm.create_time DESC
         LIMIT 20`,
        [Number(materialId)]
      );

      return successResponse({ stock: rows, costHistory: history });
    }

    // 查询所有物料的成本汇总
    const countRows: Loose = await query(
      `SELECT COUNT(DISTINCT s.material_id) as total
       FROM stock s
       WHERE s.quantity > 0`
    );
    const total = countRows[0]?.total || 0;

    const rows: Loose = await query(
      `SELECT s.material_id, m.material_name, m.material_code, m.material_spec, m.unit,
              SUM(s.quantity) as total_quantity,
              SUM(s.quantity * s.cost_price) as total_cost_amount,
              AVG(s.cost_price) as avg_cost_price,
              MIN(s.cost_price) as min_cost_price,
              MAX(s.cost_price) as max_cost_price,
              COUNT(DISTINCT s.warehouse_id) as warehouse_count
       FROM stock s
       LEFT JOIN materials m ON s.material_id = m.id
       WHERE s.quantity > 0
       GROUP BY s.material_id, m.material_name, m.material_code, m.material_spec, m.unit
       ORDER BY total_cost_amount DESC
       LIMIT ? OFFSET ?`,
      [pageSize, (page - 1) * pageSize]
    );

    return successResponse({
      list: rows,
      total,
      page,
      pageSize,
    });
  },
  { errorMessage: '操作失败' }
);

// 手动触发成本重算
export const POST = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const body = await request.json();
    const { materialId, warehouseId } = body;

    if (!materialId) {
      return errorResponse('物料ID不能为空', 400, 400);
    }

    // 基于历史入库记录重新计算移动加权平均成本
    const movements: Loose = await query(
      `SELECT sm.movement_type, sm.quantity, sm.unit_price, sm.create_time
       FROM stock_movement sm
       WHERE sm.material_id = ?
       ${warehouseId ? 'AND sm.warehouse_id = ?' : ''}
       AND sm.movement_type IN ('purchase_inbound', 'sales_return', 'production_inbound', 'transfer_in')
       ORDER BY sm.create_time ASC`,
      warehouseId ? [Number(materialId), Number(warehouseId)] : [Number(materialId)]
    );

    if (movements.length === 0) {
      return errorResponse('没有找到入库记录，无法计算成本', 400, 400);
    }

    // 模拟移动加权平均计算
    let totalQty = 0;
    let totalAmount = 0;
    let currentCostPrice = 0;

    for (const movement of movements) {
      const qty = Number(movement.quantity);
      const price = Number(movement.unit_price || 0);

      if (qty > 0) {
        // 入库：重新计算加权平均
        totalAmount += qty * price;
        totalQty += qty;
        currentCostPrice = totalQty > 0 ? totalAmount / totalQty : 0;
      } else {
        // 出库：按当前成本价减少
        totalQty += qty; // qty is negative
        totalAmount += qty * currentCostPrice;
      }
    }

    // 更新库存成本价
    if (warehouseId) {
      await execute(
        'UPDATE stock SET cost_price = ?, update_time = NOW() WHERE material_id = ? AND warehouse_id = ?',
        [currentCostPrice, Number(materialId), Number(warehouseId)]
      );
    } else {
      await execute('UPDATE stock SET cost_price = ?, update_time = NOW() WHERE material_id = ?', [
        currentCostPrice,
        Number(materialId),
      ]);
    }

    return successResponse(
      {
        materialId,
        warehouseId,
        costPrice: currentCostPrice,
        totalQuantity: totalQty,
        totalCostAmount: totalAmount,
        movementCount: movements.length,
      },
      '成本重算完成'
    );
  },
  { errorMessage: '操作失败' }
);

import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
