export const GET = withPermission(
  async () => {
    const mode = await getFIFOMode();
    return successResponse({
      mode,
      modes: FIFO_MODE,
      modeLabel: mode === 'off' ? '关闭' : mode === 'hint' ? '提示' : '强制',
    });
  },
  { errorMessage: '获取FIFO配置失败' }
);

export const PUT = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();
    const { mode } = body;

    if (!mode || !Object.values(FIFO_MODE).includes(mode)) {
      return errorResponse('无效的FIFO模式, 可选: off/hint/force', 400, 400);
    }

    await setFIFOMode(mode);
    return successResponse({ mode }, 'FIFO管控模式已更新');
  },
  { errorMessage: '更新FIFO配置失败' }
);

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';

import { withPermission } from '@/lib/api-permissions';
function computeExpiryWeight(expireDate: string | null): number {
  if (!expireDate) return 0;
  const now = new Date();
  const exp = new Date(expireDate);
  const daysToExpire = Math.ceil((exp.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
  if (daysToExpire <= 0) return 100;
  if (daysToExpire <= 7) return 90;
  if (daysToExpire <= 15) return 70;
  if (daysToExpire <= 30) return 50;
  if (daysToExpire <= 60) return 30;
  if (daysToExpire <= 90) return 15;
  return 0;
}

function computeCompatibilityScore(
  batch: Loose,
  workOrderNo?: string,
  pantoneCode?: string
): number {
  let score = 0;
  if (batch.material_code && pantoneCode) {
    if (batch.material_code.includes(pantoneCode)) score += 50;
  }
  if (batch.batch_no && workOrderNo) {
    const woPrefix = workOrderNo.replace(/[^A-Z]/g, '').slice(0, 3);
    if (batch.batch_no.includes(woPrefix)) score += 20;
  }
  return score;
}

function computeOverrideRiskScore(batch: Loose): number {
  const expiryWeight = computeExpiryWeight(batch.expire_date);
  const availableQty = Number(batch.available_qty || 0);
  let risk = 0;
  if (expiryWeight >= 90) risk += 40;
  else if (expiryWeight >= 70) risk += 25;
  else if (expiryWeight >= 50) risk += 10;
  if (availableQty <= 0) risk += 30;
  if (batch.status === 'frozen') risk += 50;
  return Math.min(100, risk);
}

export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const materialId = searchParams.get('materialId');
  const warehouseId = searchParams.get('warehouseId');
  const requiredQty = Number(searchParams.get('requiredQty') || 0);
  const workOrderNo = searchParams.get('workOrderNo') || undefined;
  const pantoneCode = searchParams.get('pantoneCode') || undefined;
  const minPackageQty = Number(searchParams.get('minPackageQty') || 0);

  if (!materialId || !warehouseId) {
    return errorResponse('缺少必填参数: materialId, warehouseId', 400, 400);
  }

  const batchRows: Loose = await query(
    `
    SELECT
      ib.id,
      ib.batch_no,
      ib.material_id,
      ib.material_code,
      ib.material_name,
      ib.available_qty,
      ib.unit_price,
      ib.inbound_date,
      ib.expire_date,
      ib.status,
      ib.produce_date,
      ib.unit,
      CASE
        WHEN ib.expire_date IS NOT NULL AND ib.expire_date < CURDATE() THEN 'EXPIRED'
        WHEN ib.status = 'frozen' THEN 'FROZEN'
        WHEN ib.status = 'expired' THEN 'EXPIRED'
        WHEN ib.available_qty <= 0 THEN 'EMPTY'
        ELSE 'AVAILABLE'
      END as fifo_status,
      (ib.available_qty * ib.unit_price) as batch_value,
      CASE
        WHEN ib.expire_date IS NULL THEN 9999
        ELSE DATEDIFF(ib.expire_date, CURDATE())
      END as days_to_expire
    FROM inv_inventory_batch ib
    WHERE ib.material_id = ? AND ib.warehouse_id = ? AND ib.deleted = 0
    ORDER BY
      CASE
        WHEN ib.status = 'normal' AND (ib.expire_date IS NULL OR ib.expire_date >= CURDATE()) THEN 0
        WHEN ib.status = 'frozen' THEN 2
        ELSE 1
      END,
      CASE
        WHEN ib.expire_date IS NOT NULL AND DATEDIFF(ib.expire_date, CURDATE()) <= 30 THEN 0
        WHEN ib.expire_date IS NOT NULL AND DATEDIFF(ib.expire_date, CURDATE()) <= 60 THEN 1
        ELSE 2
      END,
      ib.inbound_date ASC,
      ib.expire_date ASC,
      ib.id ASC
  `,
    [materialId, warehouseId]
  );

  const availableBatches = batchRows
    .filter((b: Loose) => b.fifo_status === 'AVAILABLE')
    .map((b: Loose) => {
      const expiryWeight = computeExpiryWeight(b.expire_date);
      const compatibilityScore = computeCompatibilityScore(b, workOrderNo, pantoneCode);
      const overrideRiskScore = computeOverrideRiskScore(b);
      return {
        ...b,
        expiry_weight: expiryWeight,
        compatibility_score: compatibilityScore,
        override_risk_score: overrideRiskScore,
        is_near_expiry: expiryWeight >= 50,
        is_urgent_expiry: expiryWeight >= 70,
      };
    })
    .sort((a: Loose, b: Loose) => {
      if (a.is_urgent_expiry && !b.is_urgent_expiry) return -1;
      if (!a.is_urgent_expiry && b.is_urgent_expiry) return 1;
      if (a.compatibility_score !== b.compatibility_score)
        return b.compatibility_score - a.compatibility_score;
      return new Date(a.inbound_date).getTime() - new Date(b.inbound_date).getTime();
    });

  const frozenBatches = batchRows.filter((b: Loose) => b.fifo_status === 'FROZEN');
  const expiredBatches = batchRows.filter((b: Loose) => b.fifo_status === 'EXPIRED');

  const recommendedBatches: Loose[] = [];
  let totalAvailable = 0;
  let remainingQty = requiredQty;

  for (const batch of availableBatches) {
    totalAvailable += Number(batch.available_qty);
    if (remainingQty > 0) {
      let allocQty = Math.min(remainingQty, Number(batch.available_qty));

      if (
        minPackageQty > 0 &&
        allocQty < minPackageQty &&
        remainingQty <= Number(batch.available_qty)
      ) {
        allocQty = Math.min(
          Math.ceil(remainingQty / minPackageQty) * minPackageQty,
          Number(batch.available_qty)
        );
      }

      recommendedBatches.push({
        ...batch,
        allocated_qty: allocQty,
        is_fifo_recommended: true,
        allocation_reason: batch.is_urgent_expiry
          ? '即将过期优先出库'
          : batch.compatibility_score > 0
            ? '兼容性匹配优先'
            : 'FIFO标准先进先出',
      });
      remainingQty -= allocQty;
    }
  }

  const alternativeBatches = availableBatches
    .filter((b: Loose) => !recommendedBatches.some((r: Loose) => r.id === b.id))
    .slice(0, 5)
    .map((b: Loose) => ({
      batch_no: b.batch_no,
      available_qty: Number(b.available_qty),
      unit_price: Number(b.unit_price),
      expire_date: b.expire_date,
      compatibility_score: b.compatibility_score,
      override_risk_score: b.override_risk_score,
    }));

  const totalRecommendedQty = recommendedBatches.reduce(
    (sum: number, b: Loose) => sum + Number(b.allocated_qty),
    0
  );
  const totalRecommendedCost = recommendedBatches.reduce(
    (sum: number, b: Loose) => sum + Number(b.allocated_qty) * Number(b.unit_price),
    0
  );
  const avgCost = totalRecommendedQty > 0 ? totalRecommendedCost / totalRecommendedQty : 0;

  const firstBatch = availableBatches.length > 0 ? availableBatches[0] : null;

  const nearExpiryBatches = availableBatches.filter((b: Loose) => b.is_near_expiry);
  const nearExpiryValue = nearExpiryBatches.reduce(
    (sum: number, b: Loose) => sum + Number(b.available_qty) * Number(b.unit_price),
    0
  );

  const overrideLogs: Loose = await query(
    `
    SELECT id, source_type, source_no, recommended_batch, actual_batch, reason, approval_status, create_time
    FROM inv_fifo_override_log
    WHERE material_id = ? AND deleted = 0
    ORDER BY create_time DESC
    LIMIT 5
  `,
    [materialId]
  );

  return successResponse({
    materialId: Number(materialId),
    warehouseId: Number(warehouseId),
    requiredQty,
    totalAvailable,
    isSufficient: totalAvailable >= requiredQty,
    shortage: totalAvailable < requiredQty ? requiredQty - totalAvailable : 0,
    fifoRecommendation: firstBatch
      ? {
          batchNo: firstBatch.batch_no,
          availableQty: Number(firstBatch.available_qty),
          unitPrice: Number(firstBatch.unit_price),
          inboundDate: firstBatch.inbound_date,
          expireDate: firstBatch.expire_date,
          compatibilityScore: firstBatch.compatibility_score,
          overrideRiskScore: firstBatch.override_risk_score,
          allocationReason: firstBatch.is_urgent_expiry
            ? '即将过期优先出库'
            : firstBatch.compatibility_score > 0
              ? '兼容性匹配优先'
              : 'FIFO标准先进先出',
        }
      : null,
    recommendedBatches,
    alternativeBatches,
    totalRecommendedQty,
    totalRecommendedCost: Math.round(totalRecommendedCost * 100) / 100,
    avgCost: Math.round(avgCost * 10000) / 10000,
    availableBatches,
    frozenBatches,
    expiredBatches,
    nearExpiryWarning: {
      count: nearExpiryBatches.length,
      totalValue: Math.round(nearExpiryValue * 100) / 100,
      batches: nearExpiryBatches.map((b: Loose) => ({
        batch_no: b.batch_no,
        available_qty: Number(b.available_qty),
        days_to_expire: b.days_to_expire,
        batch_value: Math.round(Number(b.available_qty) * Number(b.unit_price) * 100) / 100,
      })),
    },
    recentOverrides: overrideLogs,
  });
});

import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';
import { query, execute } from '@/lib/db';
import { logger, generateTraceId } from '@/lib/logger';

/**
 * 库存冻结/解冻 API
 *
 * 支持按物料+仓库维度冻结库存，防止超卖
 * 冻结的库存不参与可用库存计算
 */

// 获取冻结记录列表
export const GET = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const materialId = searchParams.get('materialId');
    const warehouseId = searchParams.get('warehouseId');
    const freezeType = searchParams.get('freezeType') || '';
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');

    let where = 'WHERE f.status = ?';
    const params: Loose[] = ['active'];

    if (materialId) {
      where += ' AND f.material_id = ?';
      params.push(Number(materialId));
    }
    if (warehouseId) {
      where += ' AND f.warehouse_id = ?';
      params.push(Number(warehouseId));
    }
    if (freezeType) {
      where += ' AND f.freeze_type = ?';
      params.push(freezeType);
    }

    const countRows: Loose = await query(
      `SELECT COUNT(*) as total FROM inv_stock_freeze f ${where}`,
      params
    );
    const total = countRows[0]?.total || 0;

    const rows: Loose = await query(
      `SELECT f.*, m.material_name, m.material_code, m.unit,
              w.warehouse_name, u.real_name as operator_name
       FROM inv_stock_freeze f
       LEFT JOIN materials m ON f.material_id = m.id
       LEFT JOIN warehouses w ON f.warehouse_id = w.id
       LEFT JOIN sys_user u ON f.create_by = u.id
       ${where}
       ORDER BY f.create_time DESC
       LIMIT ? OFFSET ?`,
      [...params, pageSize, (page - 1) * pageSize]
    );

    return successResponse({ list: rows, total, page, pageSize });
  },
  { errorMessage: '操作失败' }
);

// 创建冻结记录
export const POST = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const traceId = generateTraceId();
    const ctx = { module: 'freeze', action: 'create', userId: userInfo.userId, traceId };

    const body = await request.json();
    const {
      material_id,
      warehouse_id,
      freeze_quantity,
      freeze_type,
      reason,
      source_type,
      source_id,
    } = body;

    logger.stepStart(ctx, '库存冻结', { material_id, warehouse_id, freeze_quantity, freeze_type });

    if (!material_id || !warehouse_id || !freeze_quantity) {
      logger.branch(ctx, '参数校验', '必填参数完整性', false, {
        material_id,
        warehouse_id,
        freeze_quantity,
      });
      return errorResponse('物料ID、仓库ID和冻结数量不能为空', 400, 400);
    }

    if (freeze_quantity <= 0) {
      logger.branch(ctx, '参数校验', '冻结数量>0', false, { freeze_quantity });
      return errorResponse('冻结数量必须大于0', 400, 400);
    }

    logger.branch(ctx, '参数校验', '必填参数完整性', true);

    // 检查可用库存
    logger.stepStart(ctx, '查询库存', { material_id, warehouse_id });
    const stock: Loose = await query(
      'SELECT quantity, frozen_qty FROM stock WHERE material_id = ? AND warehouse_id = ?',
      [material_id, warehouse_id]
    );
    logger.db(ctx, 'SELECT', 'stock', { material_id, warehouse_id, rows: stock.length });

    if (stock.length === 0) {
      logger.branch(ctx, '库存检查', '库存记录存在', false);
      return errorResponse('库存记录不存在', 404, 404);
    }

    const availableQty = Number(stock[0].quantity) - Number(stock[0].frozen_qty || 0);
    logger.info(ctx, `可用库存: ${availableQty}, 请求冻结: ${freeze_quantity}`);

    if (availableQty < freeze_quantity) {
      logger.branch(ctx, '库存检查', '可用库存>=冻结数量', false, {
        availableQty,
        freeze_quantity,
      });
      return errorResponse(`可用库存不足，当前可用: ${availableQty}`, 400, 400);
    }
    logger.branch(ctx, '库存检查', '可用库存>=冻结数量', true);

    // 创建冻结记录
    const result: Loose = await execute(
      `INSERT INTO inv_stock_freeze
       (material_id, warehouse_id, freeze_quantity, freeze_type, reason,
        source_type, source_id, status, create_by, create_time, update_time)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'active', ?, NOW(), NOW())`,
      [
        material_id,
        warehouse_id,
        freeze_quantity,
        freeze_type || 'manual',
        reason || null,
        source_type || null,
        source_id || null,
        userInfo.userId,
      ]
    );
    logger.db(ctx, 'INSERT', 'inv_stock_freeze', { insertId: result.insertId });

    // 更新库存冻结数量
    await execute(
      'UPDATE stock SET frozen_qty = COALESCE(frozen_qty, 0) + ?, update_time = NOW() WHERE material_id = ? AND warehouse_id = ?',
      [freeze_quantity, material_id, warehouse_id]
    );
    logger.db(ctx, 'UPDATE', 'stock', { material_id, warehouse_id, freeze_quantity });

    logger.stepEnd(ctx, '库存冻结', { insertId: result.insertId });
    return successResponse({ id: result.insertId }, '库存冻结成功');
  },
  { errorMessage: '操作失败' }
);

// 解冻
export const PUT = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const traceId = generateTraceId();
    const ctx = { module: 'freeze', action: 'unfreeze', userId: userInfo.userId, traceId };

    const body = await request.json();
    const { id, action } = body;

    logger.stepStart(ctx, '库存解冻', { id, action });

    if (!id) {
      logger.branch(ctx, '参数校验', 'ID非空', false);
      return errorResponse('冻结记录ID不能为空', 400, 400);
    }

    if (action === 'unfreeze') {
      logger.branch(ctx, '操作类型', '完全解冻', true);
      const freeze: Loose = await query(
        'SELECT * FROM inv_stock_freeze WHERE id = ? AND status = ?',
        [id, 'active']
      );
      logger.db(ctx, 'SELECT', 'inv_stock_freeze', { id, rows: freeze.length });

      if (freeze.length === 0) {
        logger.branch(ctx, '记录检查', '冻结记录存在且活跃', false);
        return errorResponse('冻结记录不存在或已解冻', 404, 404);
      }

      const record = freeze[0];
      logger.info(
        ctx,
        `解冻记录: 物料=${record.material_id}, 仓库=${record.warehouse_id}, 数量=${record.freeze_quantity}`
      );

      // 更新冻结记录状态
      await execute(
        `UPDATE inv_stock_freeze SET status = 'released', release_time = NOW(), release_by = ?, update_time = NOW() WHERE id = ?`,
        [userInfo.userId, id]
      );
      logger.db(ctx, 'UPDATE', 'inv_stock_freeze', { id, status: 'released' });

      // 减少库存冻结数量
      await execute(
        'UPDATE stock SET frozen_qty = GREATEST(COALESCE(frozen_qty, 0) - ?, 0), update_time = NOW() WHERE material_id = ? AND warehouse_id = ?',
        [record.freeze_quantity, record.material_id, record.warehouse_id]
      );
      logger.db(ctx, 'UPDATE', 'stock', {
        material_id: record.material_id,
        warehouse_id: record.warehouse_id,
        unfreeze_qty: record.freeze_quantity,
      });

      logger.stepEnd(ctx, '完全解冻');
      return successResponse(null, '库存已解冻');
    }

    if (action === 'partial_unfreeze') {
      logger.branch(ctx, '操作类型', '部分解冻', true);
      const { unfreeze_quantity } = body;
      if (!unfreeze_quantity || unfreeze_quantity <= 0) {
        logger.branch(ctx, '参数校验', '解冻数量>0', false, { unfreeze_quantity });
        return errorResponse('解冻数量必须大于0', 400, 400);
      }

      const freeze: Loose = await query(
        'SELECT * FROM inv_stock_freeze WHERE id = ? AND status = ?',
        [id, 'active']
      );
      logger.db(ctx, 'SELECT', 'inv_stock_freeze', { id, rows: freeze.length });

      if (freeze.length === 0) {
        logger.branch(ctx, '记录检查', '冻结记录存在且活跃', false);
        return errorResponse('冻结记录不存在或已解冻', 404, 404);
      }

      const record = freeze[0];
      if (unfreeze_quantity > Number(record.freeze_quantity)) {
        logger.branch(ctx, '数量校验', '解冻数量<=冻结数量', false, {
          unfreeze_quantity,
          freeze_quantity: record.freeze_quantity,
        });
        return errorResponse('解冻数量不能超过冻结数量', 400, 400);
      }

      const remainQty = Number(record.freeze_quantity) - unfreeze_quantity;
      logger.info(
        ctx,
        `部分解冻: 原冻结=${record.freeze_quantity}, 本次解冻=${unfreeze_quantity}, 剩余=${remainQty}`
      );

      if (remainQty <= 0) {
        logger.branch(ctx, '剩余判断', '剩余<=0→完全解冻', true);
        await execute(
          `UPDATE inv_stock_freeze SET status = 'released', release_time = NOW(), release_by = ?, update_time = NOW() WHERE id = ?`,
          [userInfo.userId, id]
        );
      } else {
        logger.branch(ctx, '剩余判断', '剩余>0→更新冻结数量', true);
        await execute(
          `UPDATE inv_stock_freeze SET freeze_quantity = ?, update_time = NOW() WHERE id = ?`,
          [remainQty, id]
        );
      }

      // 减少库存冻结数量
      await execute(
        'UPDATE stock SET frozen_qty = GREATEST(COALESCE(frozen_qty, 0) - ?, 0), update_time = NOW() WHERE material_id = ? AND warehouse_id = ?',
        [unfreeze_quantity, record.material_id, record.warehouse_id]
      );
      logger.db(ctx, 'UPDATE', 'stock', {
        material_id: record.material_id,
        warehouse_id: record.warehouse_id,
        unfreeze_qty: unfreeze_quantity,
      });

      logger.stepEnd(ctx, '部分解冻', { remainQty });
      return successResponse(null, remainQty > 0 ? '部分解冻成功' : '库存已解冻');
    }

    logger.branch(ctx, '操作类型', '有效操作(unfreeze/partial_unfreeze)', false, { action });
    return errorResponse('无效的操作类型', 400, 400);
  },
  { errorMessage: '操作失败' }
);

import { errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

export const POST = withPermission(async () => {
  return errorResponse('此接口已废弃，请使用 PUT /api/warehouse/inbound?action=approve', 410, 410);
});

import { NextRequest } from 'next/server';
import { query, execute, queryOne, transaction } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';

import { withPermission } from '@/lib/api-permissions';
// 生成单号
function generateRecordNo(): string {
  const date = new Date();
  const dateStr = date.toISOString().slice(0, 10).replace(/-/g, '');
  const random = Math.floor(Math.random() * 10000)
    .toString()
    .padStart(4, '0');
  return `CUT${dateStr}${random}`;
}

// 生成标签号
function generateLabelNo(): string {
  const date = new Date();
  const dateStr = date.toISOString().slice(0, 10).replace(/-/g, '');
  const random = Math.floor(Math.random() * 10000)
    .toString()
    .padStart(4, '0');
  return `LBL${dateStr}${random}`;
}

// GET - 获取分切记录列表 / 校验单个标签（?labelNo=xxx）
export const GET = withPermission(
  async (request: NextRequest) => {
    const { searchParams } = new URL(request.url);
    const labelNo = searchParams.get('labelNo');

    // 如果提供 labelNo，执行单标签校验
    if (labelNo) {
      const label = await queryOne<Loose>(
        `SELECT * FROM inv_material_label WHERE label_no = ? AND deleted = 0`,
        [labelNo]
      );

      if (!label) {
        return errorResponse('码不存在', 404, 404);
      }

      if (label.is_cut === 1) {
        return errorResponse('物料已分切', 400, 400);
      }

      if (label.is_used === 1) {
        return errorResponse('物料已使用', 400, 400);
      }

      if (label.label_type !== 1) {
        return errorResponse('非母材请在采购进货中作业', 400, 400);
      }

      const currentQty = parseFloat(label.quantity) || 0;
      if (currentQty <= 0) {
        return errorResponse('该标签库存量为零或负数，无法分切', 400, 400);
      }

      return successResponse({
        id: label.id,
        labelNo: label.label_no,
        materialName: label.material_name,
        materialCode: label.material_code,
        specification: label.specification,
        quantity: label.quantity,
        unit: label.unit,
        width: label.width,
        supplierName: label.supplier_name,
        batchNo: label.batch_no,
        purchaseOrderNo: label.purchase_order_no,
        labelType: label.label_type,
        isUsed: label.is_used,
        isCut: label.is_cut,
      });
    }

    // 否则返回分页分切记录列表
    const keyword = searchParams.get('keyword') || '';
    const sourceLabelNoQ = searchParams.get('sourceLabelNo') || '';
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');

    let whereClause = '';
    const params: Loose[] = [];

    if (keyword) {
      whereClause += `WHERE (r.record_no LIKE ? OR r.source_label_no LIKE ?)`;
      params.push(`%${keyword}%`, `%${keyword}%`);
    }

    if (sourceLabelNoQ) {
      if (whereClause) {
        whereClause += ` AND r.source_label_no = ?`;
      } else {
        whereClause += `WHERE r.source_label_no = ?`;
      }
      params.push(sourceLabelNoQ);
    }

    const result = await queryPaginated(
      `SELECT
      r.id,
      r.record_no as recordNo,
      r.source_label_id as sourceLabelId,
      r.source_label_no as sourceLabelNo,
      r.cut_width_str as cutWidthStr,
      r.original_width as originalWidth,
      r.cut_total_width as cutTotalWidth,
      r.remain_width as remainWidth,
      r.operator_id as operatorId,
      r.operator_name as operatorName,
      r.cut_time as cutTime,
      r.remark,
      r.status,
      r.create_time as createTime,
      l.material_code as materialCode,
      l.material_name as materialName,
      l.specification
    FROM inv_cutting_record r
    LEFT JOIN inv_material_label l ON r.source_label_id = l.id
    ${whereClause}
    ORDER BY r.cut_time DESC`,
      `SELECT COUNT(*) as total FROM inv_cutting_record r ${whereClause}`,
      params || [],
      { page, pageSize }
    );

    return successResponse(result);
  },
  { errorMessage: '操作失败' }
);

// POST - 执行分切操作
export const POST = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();

    const {
      sourceLabelId,
      sourceLabelNo,
      cutWidthStr,
      operatorId,
      operatorName,
      remark,
      materialCode,
      materialName,
      specification,
      quantity,
      unit,
      supplierName,
      batchNo,
      orderNo,
      originalWidth,
    } = body;

    if (!cutWidthStr) {
      return errorResponse('缺少必填字段: cutWidthStr', 400, 400);
    }
    const finalOperatorId = operatorId || '1';
    const finalOperatorName = operatorName || '系统管理员';

    let sourceLabel: Loose = null;

    if (sourceLabelId && !isNaN(Number(sourceLabelId))) {
      sourceLabel = await queryOne<Loose>(
        `SELECT * FROM inv_material_label WHERE id = ? AND deleted = 0`,
        [sourceLabelId]
      );
    }

    if (!sourceLabel) {
      const labelNoToFind = sourceLabelNo || `${orderNo}-1`;
      sourceLabel = await queryOne<Loose>(
        `SELECT * FROM inv_material_label WHERE label_no = ? AND deleted = 0`,
        [labelNoToFind]
      );
    }

    if (!sourceLabel) {
      return errorResponse('码不存在', 404, 404);
    }

    if (sourceLabel.is_cut === 1) {
      return errorResponse('物料已分切', 400, 400);
    }

    if (sourceLabel.is_used === 1) {
      return errorResponse('物料已使用', 400, 400);
    }

    // 仅 label_type=1（原材料/母材）允许分切
    if (sourceLabel.label_type !== 1) {
      return errorResponse('非母材请在采购进货中作业', 400, 400);
    }

    const currentQty = parseFloat(sourceLabel.quantity) || 0;
    if (currentQty <= 0) {
      return errorResponse('该标签库存量为零或负数，无法分切', 400, 400);
    }

    const cutWidths = cutWidthStr.split('+').map((w: string) => parseFloat(w.trim()));

    for (const width of cutWidths) {
      if (isNaN(width) || width <= 0) {
        return errorResponse(
          '分切宽幅格式不正确，请使用数字+数字的格式，如：300+400+300',
          400,
          400
        );
      }
    }

    const originalW =
      parseFloat(sourceLabel.width) ||
      originalWidth ||
      parseSpecWidth(sourceLabel.specification) ||
      0;
    const cutTotalWidth = cutWidths.reduce((sum: number, w: number) => sum + w, 0);
    const remainWidth = originalW - cutTotalWidth;

    if (cutTotalWidth > originalW) {
      return errorResponse(
        `分切后的宽幅总和【${cutTotalWidth}】不能大于原宽幅【${originalW}】`,
        400,
        400
      );
    }

    // 库存校验（按数量）：现有库存是否满足分切后剩余 >= 0
    if (currentQty < cutTotalWidth) {
      return errorResponse('库存不足，现有库存无法满足分切需求', 400, 400);
    }

    const recordNo = generateRecordNo();

    const result = await transaction(async (conn) => {
      const recordResult = await conn.execute(
        `INSERT INTO inv_cutting_record (
        record_no, source_label_id, source_label_no, cut_width_str,
        original_width, cut_total_width, remain_width,
        operator_id, operator_name, remark, status, deleted
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', 0)`,
        [
          recordNo,
          sourceLabel.id,
          sourceLabel.label_no,
          cutWidthStr,
          originalW,
          cutTotalWidth,
          remainWidth,
          finalOperatorId,
          finalOperatorName,
          remark,
        ]
      );

      const recordId = (recordResult as Loose).insertId;

      await conn.execute(`UPDATE inv_material_label SET is_cut = 1, status = 'cut' WHERE id = ?`, [
        sourceLabel.id,
      ]);

      const newLabels = [];
      const originalSpec = sourceLabel.specification || '';

      for (let i = 0; i < cutWidths.length; i++) {
        const newLabelNo = generateLabelNo();
        const cutWidth = cutWidths[i];

        let newSpec = originalSpec;
        const specMatch = originalSpec.match(
          /^(\d+(?:\.\d+)?)\s*[×xX*]\s*(\d+(?:\.\d+)?)\s*(mm|m)?$/i
        );
        if (specMatch) {
          const origLength = specMatch[2];
          const unitStr = specMatch[3] || 'mm';
          newSpec = `${cutWidth}×${origLength}${unitStr}`;
        } else {
          newSpec = `${cutWidth}mm`;
        }

        const cutQty =
          originalW > 0
            ? Math.round(parseFloat(sourceLabel.quantity) * (cutWidth / originalW) * 100) / 100
            : parseFloat(sourceLabel.quantity);

        const qrCode = JSON.stringify({
          ID: newLabelNo,
          TYPE: '2',
          PARENT: sourceLabel.label_no,
        });

        const labelResult = await conn.execute(
          `INSERT INTO inv_material_label (
          label_no, qr_code, purchase_order_no, supplier_name, receive_date,
          material_code, material_name, specification, unit, batch_no,
          quantity, width, length_per_roll, remark,
          warehouse_id, location_id, is_main_material, is_used, is_cut,
          parent_label_id, label_type, status, deleted
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, 0, ?, 2, 'active', 0)`,
          [
            newLabelNo,
            qrCode,
            sourceLabel.purchase_order_no,
            sourceLabel.supplier_name,
            sourceLabel.receive_date,
            sourceLabel.material_code,
            sourceLabel.material_name,
            newSpec,
            sourceLabel.unit,
            sourceLabel.batch_no,
            cutQty,
            cutWidth,
            sourceLabel.length_per_roll,
            `分切${i + 1}: ${cutWidth}mm`,
            sourceLabel.warehouse_id,
            sourceLabel.location_id,
            sourceLabel.is_main_material,
            sourceLabel.id,
          ]
        );

        const newLabelId = (labelResult as Loose).insertId;

        await conn.execute(
          `INSERT INTO inv_cutting_detail (record_id, new_label_id, new_label_no, cut_width, sequence)
         VALUES (?, ?, ?, ?, ?)`,
          [recordId, newLabelId, newLabelNo, cutWidth, i + 1]
        );

        newLabels.push({
          id: newLabelId,
          labelNo: newLabelNo,
          cutWidth,
          newSpec,
          cutQty,
          sequence: i + 1,
        });
      }

      if (remainWidth > 0) {
        const remLabelNo = generateLabelNo();
        let remSpec = originalSpec;
        const specMatch = originalSpec.match(
          /^(\d+(?:\.\d+)?)\s*[×xX*]\s*(\d+(?:\.\d+)?)\s*(mm|m)?$/i
        );
        if (specMatch) {
          const origLength = specMatch[2];
          const unitStr = specMatch[3] || 'mm';
          remSpec = `${remainWidth}×${origLength}${unitStr}`;
        } else {
          remSpec = `${remainWidth}mm`;
        }
        const remQty =
          originalW > 0
            ? Math.round(parseFloat(sourceLabel.quantity) * (remainWidth / originalW) * 100) / 100
            : 0;

        const remQrCode = JSON.stringify({
          ID: remLabelNo,
          TYPE: '3',
          PARENT: sourceLabel.label_no,
        });

        const remLabelResult = await conn.execute(
          `INSERT INTO inv_material_label (
          label_no, qr_code, purchase_order_no, supplier_name, receive_date,
          material_code, material_name, specification, unit, batch_no,
          quantity, width, remaining_width, length_per_roll, remark,
          warehouse_id, location_id, is_main_material, is_used, is_cut,
          parent_label_id, label_type, status, deleted
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, 0, ?, 3, 'active', 0)`,
          [
            remLabelNo,
            remQrCode,
            sourceLabel.purchase_order_no,
            sourceLabel.supplier_name,
            sourceLabel.receive_date,
            sourceLabel.material_code,
            `余料${sourceLabel.material_name}`,
            remSpec,
            sourceLabel.unit,
            sourceLabel.batch_no,
            remQty,
            remainWidth,
            remainWidth,
            sourceLabel.length_per_roll,
            `余料: ${remainWidth}mm`,
            sourceLabel.warehouse_id,
            sourceLabel.location_id,
            sourceLabel.id,
          ]
        );

        const remLabelId = (remLabelResult as Loose).insertId;
        newLabels.push({
          id: remLabelId,
          labelNo: remLabelNo,
          cutWidth: remainWidth,
          newSpec: remSpec,
          cutQty: remQty,
          sequence: cutWidths.length + 1,
          isRemainder: true,
        });
      }

      return {
        recordId,
        recordNo,
        originalWidth: originalW,
        cutTotalWidth,
        remainWidth,
        newLabels,
      };
    });

    return successResponse(result, '分切操作成功');
  },
  { errorMessage: '分切操作失败' }
);

function parseSpecWidth(spec: string): number | null {
  if (!spec) return null;
  const match = spec.match(/^(\d+(?:\.\d+)?)\s*[×xX*]\s*(\d+(?:\.\d+)?)\s*(mm|m)?$/i);
  if (match) return parseFloat(match[1]);
  return null;
}

// 辅助函数：分页查询
async function queryPaginated(
  sql: string,
  countSql: string,
  params: Loose[],
  pagination: { page: number; pageSize: number }
) {
  const { page, pageSize } = pagination;
  const offset = (page - 1) * pageSize;

  try {
    const [data, countResult] = await Promise.all([
      query<Loose[]>(`${sql} LIMIT ? OFFSET ?`, [...(params || []), pageSize, offset]),
      queryOne<{ total: number }>(countSql, params || []),
    ]);

    return {
      list: data || [],
      pagination: {
        page,
        pageSize,
        total: countResult?.total || 0,
      },
    };
  } catch {
