    const history = [];
    history.push({
      event: 'IN',
      time: order.create_time,
      detail: `入库单 ${order.order_no}`,
    });

    if (order.status === 'approved' || order.status === 'completed') {
      history.push({
        event: 'AUDIT',
        time: order.update_time || order.create_time,
        detail: '审核通过',
      });
    }

