// 库存调整（统一入口）
export const POST = withPermission(async (request: NextRequest, _userInfo) => {
  const body = await request.json();
  const {
    materialId,
    warehouseId,
    batchNo,
    quantity,
    operationType,
    businessType,
    businessNo,
