import { NextRequest, NextResponse } from 'next/server';
import { successResponse } from '@/lib/api-response';
import { UserInfo } from '@/lib/api-auth';
import { withPermission } from '@/lib/api-permissions';
import { query } from '@/lib/db';
import { getTranslator } from '@/lib/i18n-server';

/**
 * 库存流水导出 API
 *
 * 支持导出库存变动记录为CSV格式
 */

export const GET = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const materialId = searchParams.get('materialId');
    const warehouseId = searchParams.get('warehouseId');
    const movementType = searchParams.get('movementType') || '';
    const startDate = searchParams.get('startDate') || '';
    const endDate = searchParams.get('endDate') || '';
    const format = searchParams.get('format') || 'csv';

    let where = 'WHERE 1=1';
    const params: Loose[] = [];

    if (materialId) {
      where += ' AND sm.material_id = ?';
      params.push(Number(materialId));
    }
    if (warehouseId) {
      where += ' AND sm.warehouse_id = ?';
      params.push(Number(warehouseId));
    }
    if (movementType) {
      where += ' AND sm.movement_type = ?';
      params.push(movementType);
    }
    if (startDate) {
      where += ' AND sm.create_time >= ?';
      params.push(startDate + ' 00:00:00');
    }
    if (endDate) {
      where += ' AND sm.create_time <= ?';
      params.push(endDate + ' 23:59:59');
    }

    const rows: Loose = await query(
      `SELECT sm.id, sm.movement_type, sm.quantity, sm.unit_price,
              sm.source_type, sm.source_no, sm.remark, sm.create_time,
              m.material_code, m.material_name, m.unit,
              w.warehouse_name,
              u.real_name as operator_name
       FROM stock_movement sm
       LEFT JOIN materials m ON sm.material_id = m.id
       LEFT JOIN warehouses w ON sm.warehouse_id = w.id
       LEFT JOIN sys_user u ON sm.operator_id = u.id
       ${where}
       ORDER BY sm.create_time DESC
       LIMIT 10000`,
      params
    );

    if (format === 'csv') {
      // 获取翻译函数
      const t = await getTranslator('Export');

      // 生成CSV表头
      const headers = [
        t('id'),
        t('materialCode'),
        t('materialName'),
        t('warehouse'),
        t('movementType'),
        t('quantity'),
        t('unit'),
        t('unitPrice'),
        t('sourceType'),
        t('sourceNo'),
        t('operator'),
        t('remark'),
        t('time'),
      ];

      // 变动类型映射
      const typeMap: Record<string, string> = {
        purchase_inbound: t('movementTypePurchaseInbound'),
        sales_outbound: t('movementTypeSalesOutbound'),
        transfer_in: t('movementTypeTransferIn'),
        transfer_out: t('movementTypeTransferOut'),
        sales_return: t('movementTypeSalesReturn'),
        purchase_return: t('movementTypePurchaseReturn'),
        production_inbound: t('movementTypeProductionInbound'),
        stock_gain: t('movementTypeStockGain'),
        stock_loss: t('movementTypeStockLoss'),
        adjustment: t('movementTypeAdjustment'),
      };

      const csvRows = rows.map((r: Loose) => [
        r.id,
        r.material_code || '',
        r.material_name || '',
        r.warehouse_name || '',
        typeMap[r.movement_type] || r.movement_type,
        r.quantity,
        r.unit || '',
        r.unit_price || 0,
        r.source_type || '',
        r.source_no || '',
        r.operator_name || '',
        (r.remark || '').replace(/"/g, '""'),
        r.create_time,
      ]);

      const csvContent = [
        headers.join(','),
        ...csvRows.map((row: Loose[]) => row.map((v: Loose) => `"${v}"`).join(',')),
      ].join('\n');

      const bom = '\uFEFF';
      const csvBuffer = Buffer.from(bom + csvContent, 'utf-8');

      return new NextResponse(csvBuffer, {
        headers: {
          'Content-Type': 'text/csv; charset=utf-8',
          'Content-Disposition': `attachment; filename=inventory_log_${new Date().toISOString().slice(0, 10)}.csv`,
        },
      });
    }

    return successResponse({ list: rows, total: rows.length });
  },
  { errorMessage: '操作失败' }
);

import { NextRequest } from 'next/server';
import { query } from '@/lib/db';
import { successResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { logger, generateTraceId } from '@/lib/logger';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const traceId = generateTraceId();
  const ctx = { module: 'inventory', action: 'list', traceId };

  const { searchParams } = new URL(request.url);
  const pageSize = parseInt(searchParams.get('pageSize') || '100');
  const page = parseInt(searchParams.get('page') || '1');
  const keyword = searchParams.get('keyword');
  const categoryId = searchParams.get('categoryId');
  const warehouseId = searchParams.get('warehouseId');
  const lowStock = searchParams.get('lowStock');

  logger.stepStart(ctx, '查询库存列表', {
    keyword,
    categoryId,
    warehouseId,
    lowStock,
    page,
    pageSize,
  });

  let sql = `
    SELECT m.*, w.warehouse_name, mc.category_name,
           COALESCE(ib.stock_qty, 0) as stock_qty
    FROM inv_material m
    LEFT JOIN inv_warehouse w ON m.warehouse_id = w.id
    LEFT JOIN inv_material_category mc ON m.category_id = mc.id
    LEFT JOIN (
      SELECT material_id, COALESCE(SUM(available_qty), 0) as stock_qty
      FROM inv_inventory_batch
      WHERE deleted = 0
      GROUP BY material_id
    ) ib ON m.id = ib.material_id
    WHERE m.deleted = 0
  `;
  const values: Loose[] = [];

  if (keyword) {
    logger.branch(ctx, '筛选条件', '关键词搜索', true, { keyword });
    sql += ` AND (m.material_code LIKE ? OR m.material_name LIKE ?)`;
    const likeKeyword = `%${keyword}%`;
    values.push(likeKeyword, likeKeyword);
  }

  if (categoryId) {
    logger.branch(ctx, '筛选条件', '分类筛选', true, { categoryId });
    sql += ` AND m.category_id = ?`;
    values.push(parseInt(categoryId));
  }

  if (warehouseId) {
    logger.branch(ctx, '筛选条件', '仓库筛选', true, { warehouseId });
    sql += ` AND m.warehouse_id = ?`;
    values.push(parseInt(warehouseId));
  }

  if (lowStock === 'true') {
    logger.branch(ctx, '筛选条件', '低库存筛选', true);
    sql += ` AND m.safety_stock > 0 AND COALESCE(ib.stock_qty, 0) <= m.safety_stock`;
  }

  sql += ` ORDER BY m.create_time DESC LIMIT ? OFFSET ?`;
  values.push(pageSize, (page - 1) * pageSize);

  const materials = await query(sql, values);

  const result = (materials as Loose[]).map((item: Loose) => ({
    id: item.id,
    material_code: item.material_code,
    material_name: item.material_name,
    specification: item.specification,
    category_id: item.category_id,
    category_name: item.category_name,
    material_type: item.material_type,
    unit: item.unit,
    barcode: item.barcode,
    brand: item.brand,
    safety_stock: parseFloat(item.safety_stock || '0'),
    max_stock: parseFloat(item.max_stock || '0'),
    min_stock: parseFloat(item.min_stock || '0'),
    stock_qty: parseFloat(item.stock_qty || '0'),
    quantity: parseFloat(item.stock_qty || '0'),
    min_quantity: parseFloat(item.min_stock || item.safety_stock || '0'),
    purchase_price: parseFloat(item.purchase_price || '0'),
    sale_price: parseFloat(item.sale_price || '0'),
    cost_price: parseFloat(item.cost_price || '0'),
    warehouse_id: item.warehouse_id,
    warehouse_name: item.warehouse_name,
    shelf_life: item.shelf_life,
    warning_days: item.warning_days,
    status: item.status,
    remark: item.remark,
    create_time: item.create_time,
    update_time: item.update_time,
  }));

  let countSql = `SELECT COUNT(*) as total FROM inv_material m LEFT JOIN (
    SELECT material_id, COALESCE(SUM(available_qty), 0) as stock_qty
    FROM inv_inventory_batch
    WHERE deleted = 0
    GROUP BY material_id
  ) ib ON m.id = ib.material_id WHERE m.deleted = 0`;
  const countValues: Loose[] = [];
  if (keyword) {
    countSql += ` AND (m.material_code LIKE ? OR m.material_name LIKE ?)`;
    countValues.push(`%${keyword}%`, `%${keyword}%`);
  }
  if (categoryId) {
    countSql += ` AND m.category_id = ?`;
    countValues.push(parseInt(categoryId));
  }
  if (warehouseId) {
    countSql += ` AND m.warehouse_id = ?`;
    countValues.push(parseInt(warehouseId));
  }
  if (lowStock === 'true') {
    countSql += ` AND m.safety_stock > 0 AND COALESCE(ib.stock_qty, 0) <= m.safety_stock`;
  }
  const countResult = await query(countSql, countValues);
  const total = (countResult as Loose[])[0]?.total || 0;

  logger.stepEnd(ctx, '查询库存列表', { total, page, pageSize });
  return successResponse({
    list: result,
    total,
    page,
    pageSize,
  });
});

