  split_out: '分切出库',
};

const BASE_COLUMNS = [
  { key: 'materialCode', header: '物料编码', width: 15 },
  { key: 'materialName', header: '物料名称', width: 20 },
  { key: 'specDisplay', header: '规格', width: 15 },
  { key: 'unit', header: '单位', width: 8 },
  { key: 'categoryName', header: '分类', width: 12 },
  { key: 'supplierName', header: '供应商', width: 15 },
  { key: 'warehouseName', header: '仓库', width: 12 },
];

function getDateColumnKey(day: number, opKey: string, field: 'qty' | 'amount'): string {
  return `d${day}_${opKey}_${field}`;
}

export const GET = withPermission(
  async (request: NextRequest) => {
    const { searchParams } = new URL(request.url);
    const year = parseInt(searchParams.get('year') || String(new Date().getFullYear()));
    const month = parseInt(searchParams.get('month') || String(new Date().getMonth() + 1));
    const viewMode = searchParams.get('viewMode') || 'all';
    const keyword = searchParams.get('keyword') || '';
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');
    const exportFlag = searchParams.get('export') === '1';

    const monthStr = `${year}-${String(month).padStart(2, '0')}`;
    const daysInMonth = new Date(year, month, 0).getDate();

    let whereClause = `WHERE DATE_FORMAT(l.create_time, '%Y-%m') = ?`;
    const queryParams: (string | number)[] = [monthStr];

    if (viewMode === 'large') {
      whereClause += ` AND (l.batch_type IS NULL OR l.batch_type = 0)`;
    } else if (viewMode === 'small') {
      whereClause += ` AND l.batch_type = 1`;
    }

    const dailySql = `
      SELECT
        m.id as material_id,
        m.material_code,
        m.material_name,
        m.specification,
        m.width,
        m.length,
        m.unit_mark,
        COALESCE(l.unit, m.unit) as unit,
        mc.name as category_name,
        s.supplier_name,
        w.warehouse_name,
        DATE_FORMAT(l.create_time, '%d') as day_num,
        l.business_type,
        l.operation_type,
        l.operation_qty,
        l.unit_price,
        l.batch_type,
        l.batch_no,
        l.warehouse_id
      FROM inv_inventory_log l
      LEFT JOIN inv_material m ON l.material_id = m.id
      LEFT JOIN inv_material_category mc ON m.category_id = mc.id
      LEFT JOIN pur_supplier s ON l.supplier_id = s.id
      LEFT JOIN inv_warehouse w ON l.warehouse_id = w.id
      ${whereClause}
      ORDER BY m.material_code, l.create_time
    `;

    const rows = (await query(dailySql, queryParams)) as Loose[];

    const grouped: Record<string, Loose> = {};
    for (const row of rows) {
      const key = `${row.material_id}_${row.warehouse_id || 0}`;
      if (!grouped[key]) {
        const w = parseFloat(row.width) || 0;
        const l = parseFloat(row.length) || 0;
        let specDisplay = row.specification || '';
        if (viewMode === 'large' && w > 0) {
          specDisplay = l > 0 ? `${w}*${l}` : `${w}`;
        } else if (viewMode === 'small' && w > 0) {
          specDisplay = `${w}`;
        }

        grouped[key] = {
          material_id: row.material_id,
          materialCode: row.material_code || '',
          materialName: row.material_name || '',
          specification: row.specification || '',
          specDisplay,
          unit: row.unit || '',
          width: w,
          length: l,
          categoryName: row.category_name || '',
          supplierName: row.supplier_name || '',
          warehouseName: row.warehouse_name || '',
          warehouseId: row.warehouse_id,
        };
      }

      const day = parseInt(row.day_num);
      if (day < 1 || day > 31) continue;

      const opType = parseInt(row.operation_type) || 0;
      const opKey = OP_TYPE_MAP[opType] || 'other';
      const qty = parseFloat(row.operation_qty) || 0;
      const price = parseFloat(row.unit_price) || 0;
      const amount = Math.abs(qty * price);

      const qtyKey = getDateColumnKey(day, opKey, 'qty');
      const amtKey = getDateColumnKey(day, opKey, 'amount');

      grouped[key][qtyKey] = (grouped[key][qtyKey] || 0) + Math.abs(qty);
      grouped[key][amtKey] = (grouped[key][amtKey] || 0) + amount;
    }

    let result = Object.values(grouped);

    if (keyword) {
      const kw = keyword.toLowerCase();
      result = result.filter(
        (r) =>
          (r.materialCode || '').toLowerCase().includes(kw) ||
          (r.materialName || '').toLowerCase().includes(kw)
      );
    }

    if (exportFlag) {
      const colDefs: ReportColumnDef[] = [
        {
          header: '基础信息',
          children: BASE_COLUMNS.map((c) => ({
            key: c.key,
            header: c.header,
            width: c.width,
          })),
        },
      ];

      const opKeys = Object.keys(OP_LABEL_CN);
      for (let day = 1; day <= daysInMonth; day++) {
        const dayChildren: ReportColumnDef['children'] = [];
        for (const opKey of opKeys) {
          const label = OP_LABEL_CN[opKey] || opKey;
          dayChildren.push(
            {
              key: getDateColumnKey(day, opKey, 'qty'),
              header: `${day}日${label}数量`,
              width: 12,
              formatter: (v) => String(v ?? '0'),
            },
            {
              key: getDateColumnKey(day, opKey, 'amount'),
              header: `${day}日${label}金额`,
              width: 12,
              formatter: (v) => String(v ?? '0'),
            }
          );
        }
        colDefs.push({ header: `${day}日`, children: dayChildren });
      }

      const buffer = exportReportToExcel({
        fileName: `库存月报_${year}${String(month).padStart(2, '0')}`,
        sheetName: `${year}年${month}月`,
        columnDefs: colDefs,
        data: result as Record<string, unknown>[],
        title: `库存月报 ${year}年${month}月`,
        freezeRow: 2,
        freezeCol: 1,
      });

      return new NextResponse(new Uint8Array(buffer), {
        headers: {
          'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          'Content-Disposition': `attachment; filename="inventory_report_${year}${String(month).padStart(2, '0')}.xlsx"`,
        },
      });
    }

    const total = result.length;
    const offset = (page - 1) * pageSize;
    const paged = result.slice(offset, offset + pageSize);

    return successResponse({ list: paged, total, page, pageSize });
  },
  { errorMessage: '获取库存月报失败' }
);

import { NextRequest } from 'next/server';
import { transaction } from '@/lib/db';
import { successResponse, errorResponse, logOperation } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { WarehouseStateMachine } from '@/domain/warehouse/value-objects/WarehouseStateMachine';
import {
  allocateFIFO,
  executeFIFODeductionWithRetry,
  executeSpecifiedBatchDeduction,
} from '@/lib/fifo-allocation';
import { logger } from '@/lib/logger';

export const POST = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();
    const { id, operatorId, operatorName, remark } = body;

    logger.debug(
      `[OUTBOUND] Confirm outbound request received - id: ${id}, operatorId: ${operatorId}, operatorName: ${operatorName}`
    );

    if (!id) {
      return errorResponse('出库单ID不能为空', 400);
    }

    const deductionDetails: Loose[] = [];

    await transaction(async (connection) => {
      logger.debug(`[OUTBOUND] Starting transaction for outbound order: ${id}`);

      const [orderRows]: Loose = await connection.execute(
        `SELECT id, order_no, status, warehouse_id, warehouse_code, warehouse_name, version
       FROM inv_outbound_order WHERE id = ? AND deleted = 0 FOR UPDATE`,
        [id]
      );

      if (!orderRows || orderRows.length === 0) {
        throw new Error('NOT_FOUND:出库单不存在');
      }

      const orderRow = orderRows[0];
      logger.debug(
        `[OUTBOUND] Found order: id=${orderRow.id}, order_no=${orderRow.order_no}, status=${orderRow.status}, warehouse_id=${orderRow.warehouse_id}`
      );

      if (!WarehouseStateMachine.canConfirmOutbound(orderRow.status)) {
        throw new Error(
          `BAD_REQUEST:当前状态【${WarehouseStateMachine.getOutboundStatusLabel(orderRow.status)}】不允许确认`
        );
      }

      const [itemRows]: Loose = await connection.execute(
        `SELECT id, material_id, material_name, batch_no, quantity, unit
       FROM inv_outbound_item WHERE order_id = ? AND deleted = 0`,
        [id]
      );

      logger.debug(`[OUTBOUND] Found ${itemRows.length} items for order: ${id}`);

      if (!itemRows || itemRows.length === 0) {
        throw new Error('BAD_REQUEST:出库单没有明细，不能确认');
      }

      for (const item of itemRows) {
        const requiredQty = parseFloat(String(item.quantity));
        logger.debug(
          `[OUTBOUND] Processing item: id=${item.id}, material_id=${item.material_id}, material_name=${item.material_name}, qty=${requiredQty}, batch_no=${item.batch_no}`
        );

        if (item.batch_no) {
          logger.debug(
            `[OUTBOUND] Using specified batch deduction for item ${item.id}, batch_no=${item.batch_no}`
          );
          const { deductionDetail } = await executeSpecifiedBatchDeduction(connection, {
            batchNo: item.batch_no,
            materialId: item.material_id,
            materialCode: '',
            materialName: item.material_name,
            warehouseId: orderRow.warehouse_id,
            warehouseCode: orderRow.warehouse_code,
            requiredQty,
            sourceType: 'outbound_order',
            sourceId: id,
            sourceNo: orderRow.order_no,
            operatorId: operatorId || null,
            operatorName: operatorName || null,
          });
          deductionDetails.push(deductionDetail);
          logger.debug(
            `[OUTBOUND] Specified batch deduction completed - batch_no=${item.batch_no}, deducted_qty=${deductionDetail.deducted_qty}`
          );
        } else {
          logger.debug(
            `[OUTBOUND] Using FIFO allocation for item ${item.id}, material_id=${item.material_id}, requiredQty=${requiredQty}`
          );
          const allocation = await allocateFIFO(
            connection,
            item.material_id,
            orderRow.warehouse_id,
            requiredQty
          );

          logger.debug(
            `[OUTBOUND] FIFO allocation result - allocated_qty=${allocation.allocated_qty}, shortage=${allocation.shortage}, total_available=${allocation.total_available}`
          );

          if (allocation.shortage > 0) {
            throw new Error(
              `物料 ${item.material_name} 库存不足: 需要 ${requiredQty}, 可用 ${allocation.total_available}, 缺少 ${allocation.shortage}`
            );
          }

          logger.debug(
            `[OUTBOUND] Executing FIFO deduction with ${allocation.allocations.length} allocations`
          );
          const { deductionDetails: fifoDetails } = await executeFIFODeductionWithRetry(
            connection,
            allocation,
            {
              sourceType: 'outbound_order',
              sourceId: id,
              sourceNo: orderRow.order_no,
              warehouseId: orderRow.warehouse_id,
              warehouseCode: orderRow.warehouse_code,
              operatorId: operatorId || null,
              operatorName: operatorName || null,
            }
          );

          deductionDetails.push(...fifoDetails);
          logger.debug(
            `[OUTBOUND] FIFO deduction completed - ${fifoDetails.length} batches deducted`
          );

          const batchNos = allocation.allocations.map((a: Loose) => a.batch_no).join(',');
          await connection.execute(`UPDATE inv_outbound_item SET batch_no = ? WHERE id = ?`, [
            batchNos,
            item.id,
          ]);
          logger.debug(`[OUTBOUND] Updated item ${item.id} with batch_no: ${batchNos}`);
        }

        const [invResult]: Loose = await connection.execute(
          `UPDATE inv_inventory SET
          quantity = quantity - ?,
          available_qty = available_qty - ?,
          update_time = NOW()
        WHERE material_id = ? AND warehouse_id = ?`,
          [requiredQty, requiredQty, item.material_id, orderRow.warehouse_id]
        );
        if (invResult.affectedRows === 0) {
          throw new Error(
            `物料 ${item.material_name} 在仓库 ${orderRow.warehouse_code} 的库存记录不存在，无法扣减`
          );
        }
        logger.debug(
          `[OUTBOUND] Updated inv_inventory - material_id=${item.material_id}, warehouse_id=${orderRow.warehouse_id}, deducted_qty=${requiredQty}`
        );
      }

      const [orderUpdateResult]: Loose = await connection.execute(
        `UPDATE inv_outbound_order SET
        status = 'completed',
        audit_status = 1,
        auditor_id = ?,
        auditor_name = ?,
        audit_time = NOW(),
        audit_remark = ?,
        version = version + 1,
        update_time = NOW()
      WHERE id = ? AND version = ?`,
        [operatorId, operatorName, remark || '', id, orderRow.version]
      );
      if (orderUpdateResult.affectedRows === 0) {
        throw new Error(`出库单版本冲突，可能已被其他操作修改，请刷新后重试`);
      }

      // 自动生成应收单（如果出库单关联了客户）
      const [orderInfo]: Loose = await connection.execute(
        `SELECT customer_id, customer_name, total_amount, sales_order_no FROM inv_outbound_order WHERE id = ?`,
        [id]
      );

      if (orderInfo && orderInfo.length > 0 && orderInfo[0].customer_id) {
        const customer = orderInfo[0];
        const receivableNo = 'AR' + Date.now();
        const dueDate = new Date();
        dueDate.setDate(dueDate.getDate() + 30); // 默认30天账期

        await connection.execute(
          `INSERT INTO fin_receivable (
          receivable_no, customer_id, customer_name, amount, received_amount,
          status, source_type, source_no, source_id,
          due_date, remark, create_time, update_time, deleted
        ) VALUES (?, ?, ?, ?, 0, 1, 'outbound_order', ?, ?, ?, ?, NOW(), NOW(), 0)`,
          [
            receivableNo,
            customer.customer_id,
            customer.customer_name,
            customer.total_amount || 0,
            orderRow.order_no,
            id,
            dueDate.toISOString().split('T')[0],
            `销售出库自动生成 - ${orderRow.order_no}`,
          ]
        );
      }

      // 更新销售订单累计出库数量（如果关联了销售订单）
      if (orderInfo && orderInfo.length > 0 && orderInfo[0].sales_order_no) {
        const salesOrderNo = orderInfo[0].sales_order_no;

        const totalOutQty = itemRows.reduce(
          (sum: number, item: Loose) => sum + parseFloat(String(item.qty)),
          0
        );

        await connection.execute(
          `UPDATE sales_order SET
          total_out_quantity = COALESCE(total_out_quantity, 0) + ?,
          update_time = NOW()
        WHERE order_no = ?`,
          [totalOutQty, salesOrderNo]
        );

        // 检查是否全部出库完成
        const [soItems]: Loose = await connection.execute(
          `SELECT SUM(quantity) as total_qty FROM sales_order_item WHERE sales_order_id = (SELECT id FROM sales_order WHERE order_no = ?)`,
          [salesOrderNo]
        );
        const [soOutbound]: Loose = await connection.execute(
          `SELECT COALESCE(total_out_quantity, 0) as total_out FROM sales_order WHERE order_no = ?`,
          [salesOrderNo]
        );

        if (soItems[0]?.total_qty && soOutbound[0]?.total_out >= soItems[0].total_qty) {
          await connection.execute(
            `UPDATE sales_order SET status = 3, update_time = NOW() WHERE order_no = ? AND status != 9`,
            [salesOrderNo]
          );
        } else if (soOutbound[0]?.total_out > 0) {
          await connection.execute(
            `UPDATE sales_order SET status = 2, update_time = NOW() WHERE order_no = ? AND status = 1`,
            [salesOrderNo]
          );
        }
      }
    }).catch((error) => {
      const msg = error instanceof Error ? error.message : String(error);
      if (msg.startsWith('NOT_FOUND:')) return errorResponse(msg.slice(10), 404);
      if (msg.startsWith('BAD_REQUEST:')) return errorResponse(msg.slice(12), 400);
      throw error;
    });

    await logOperation({
      title: '确认出库',
      oper_name: operatorName,
      oper_type: 'warehouse',
      oper_method: 'POST',
      oper_url: '/api/warehouse/outbound/confirm',
      oper_param: JSON.stringify({ id, operatorId }),
      oper_result: `出库单确认成功，扣减${deductionDetails.length}个批次`,
      status: 1,
    });

    return successResponse(
      {
        orderId: id,
        deductionDetails,
        totalDeductedBatches: deductionDetails.length,
      },
      '出库单确认成功，库存已按先进先出扣减'
    );
  },
  { errorMessage: '确认出库失败' }
);

export const PUT = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();
    const { id, operatorId, operatorName, remark } = body;

    if (!id) {
      return errorResponse('出库单ID不能为空', 400);
    }

    let orderNo = '';

    await transaction(async (connection) => {
      const [orderRows]: Loose = await connection.execute(
        `SELECT id, order_no, status, warehouse_id, version
       FROM inv_outbound_order WHERE id = ? AND deleted = 0 FOR UPDATE`,
        [id]
      );

      if (!orderRows || orderRows.length === 0) {
        throw new Error('NOT_FOUND:出库单不存在');
      }

      const order = orderRows[0];
      orderNo = order.order_no;

      if (!WarehouseStateMachine.canTransitionOutbound(order.status, 'pending')) {
        throw new Error(
          `BAD_REQUEST:${WarehouseStateMachine.getTransitionError('outbound', order.status, 'pending')}`
        );
      }

      const [itemRows]: Loose = await connection.execute(
        `SELECT material_id, batch_no, quantity FROM inv_outbound_item WHERE order_id = ? AND deleted = 0`,
        [id]
      );

      for (const item of itemRows || []) {
        const batchNos = item.batch_no
          ? item.batch_no
              .split(',')
              .map((b: string) => b.trim())
              .filter(Boolean)
          : [];

        if (batchNos.length <= 1) {
          const [updateResult]: Loose = await connection.execute(
            `UPDATE inv_inventory_batch SET
            quantity = quantity + ?,
            available_qty = available_qty + ?,
            version = version + 1,
            update_time = NOW()
          WHERE batch_no = ? AND material_id = ? AND warehouse_id = ?`,
            [item.quantity, item.quantity, item.batch_no, item.material_id, order.warehouse_id]
          );

          if (updateResult.affectedRows === 0) {
            throw new Error(`库存恢复失败，可能已被其他操作修改: ${item.batch_no}`);
          }
        } else {
          const [allocations]: Loose = await connection.execute(
            `SELECT batch_no, allocated_qty FROM inv_outbound_batch_allocation
           WHERE source_id = ? AND material_id = ? AND source_type = 'outbound_order'
           ORDER BY batch_no`,
            [id, item.material_id]
          );

          if (allocations && allocations.length > 0) {
            for (const alloc of allocations) {
              await connection.execute(
                `UPDATE inv_inventory_batch SET
                quantity = quantity + ?,
                available_qty = available_qty + ?,
                version = version + 1,
                update_time = NOW()
              WHERE batch_no = ? AND material_id = ? AND warehouse_id = ?`,
                [
                  alloc.allocated_qty,
                  alloc.allocated_qty,
                  alloc.batch_no,
                  item.material_id,
                  order.warehouse_id,
                ]
              );
            }
          } else {
            const qtyPerBatch = item.quantity / batchNos.length;
            for (const bNo of batchNos) {
              await connection.execute(
                `UPDATE inv_inventory_batch SET
                quantity = quantity + ?,
                available_qty = available_qty + ?,
                version = version + 1,
                update_time = NOW()
              WHERE batch_no = ? AND material_id = ? AND warehouse_id = ?`,
                [qtyPerBatch, qtyPerBatch, bNo, item.material_id, order.warehouse_id]
              );
            }
          }
        }

        await connection.execute(
          `UPDATE inv_inventory SET
          quantity = quantity + ?,
          available_qty = available_qty + ?,
          update_time = NOW()
        WHERE material_id = ? AND warehouse_id = ?`,
          [item.quantity, item.quantity, item.material_id, order.warehouse_id]
        );

        await connection.execute(
          `INSERT INTO inv_inventory_transaction (
          trans_no, trans_type, batch_no, material_id,
          warehouse_id, quantity, source_type, source_no,
          operated_by, operated_at, remark
        ) VALUES (?, 'outbound_cancel', ?, ?, ?, ?, 'outbound_order', ?, ?, NOW(), ?)`,
          [
            `OUTC${Date.now()}${item.material_id}`,
            item.batch_no,
            item.material_id,
            order.warehouse_id,
            item.quantity,
            order.order_no,
            operatorId,
            `撤销出库: ${remark || ''}`,
          ]
        );
      }

      await connection.execute(
        `UPDATE inv_outbound_order SET
        status = 'pending',
        audit_status = 0,
        auditor_id = NULL,
        auditor_name = NULL,
        audit_time = NULL,
        version = version + 1,
        audit_remark = ?,
        update_time = NOW()
      WHERE id = ? AND version = ?`,
        [`撤销出库: ${remark || ''} 操作人: ${operatorName || ''}`, id, order.version]
      );
    }).catch((error) => {
      const msg = error instanceof Error ? error.message : String(error);
      if (msg.startsWith('NOT_FOUND:')) return errorResponse(msg.slice(10), 404);
      if (msg.startsWith('BAD_REQUEST:')) return errorResponse(msg.slice(12), 400);
      throw error;
    });

    await logOperation({
      title: '撤销出库',
      oper_name: operatorName,
      oper_type: 'warehouse',
      oper_method: 'PUT',
      oper_url: '/api/warehouse/outbound/confirm',
      oper_param: JSON.stringify({ id, operatorId }),
      oper_result: `出库单 ${orderNo} 撤销成功，库存已恢复`,
      status: 1,
    });

    return successResponse(
      { orderId: id, orderNo, status: 'pending' },
      '出库单撤销成功，库存已恢复'
    );
  },
  { errorMessage: '撤销出库失败' }
);

import { NextRequest } from 'next/server';
import { query, transaction } from '@/lib/db';
import { successResponse, errorResponse, logOperation } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { allocateFIFO, planFIFOAllocation } from '@/lib/fifo-allocation';

interface FIFOAllocationItem {
  batch_id: number;
  batch_no: string;
  material_id: number;
  material_code: string;
  material_name: string;
  allocate_qty: number;
  available_qty_before: number;
  unit_cost: number;
  inbound_date: string;
}

interface FIFOAllocationResult {
  material_id: number;
  material_code: string;
  material_name: string;
  required_qty: number;
  total_available: number;
  allocated_qty: number;
  shortage: number;
  allocations: FIFOAllocationItem[];
}

export const GET = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const materialId = searchParams.get('materialId');
    const warehouseId = searchParams.get('warehouseId');
    const requiredQty = parseFloat(searchParams.get('requiredQty') || '0');

    if (!materialId || !warehouseId) {
      return errorResponse('materialId 和 warehouseId 不能为空', 400, 400);
    }

    const batches = await query(
      `SELECT 
        id, batch_no, material_id, material_code, material_name,
        quantity, available_qty, locked_qty, unit, unit_price,
        inbound_date, produce_date, expire_date, status
      FROM inv_inventory_batch 
      WHERE material_id = ? AND warehouse_id = ? AND available_qty > 0 AND deleted = 0 AND status = 1
      ORDER BY
        CASE WHEN split_flag = 2 THEN 0 ELSE 1 END ASC,
        CASE WHEN opened_at IS NOT NULL THEN 0 ELSE 1 END ASC,
        expire_date ASC,
        inbound_date ASC,
        id ASC`,
      [materialId, warehouseId]
    );

    const totalAvailable = (batches as Loose[]).reduce(
      (sum, b) => sum + parseFloat(b.available_qty),
      0
    );

    const allocationPlan: FIFOAllocationItem[] = [];
    let shortage = 0;

    if (requiredQty > 0) {
      const allocation = await planFIFOAllocation(
        { query },
        parseInt(materialId),
        parseInt(warehouseId),
        requiredQty
      );

      allocationPlan.push(
        ...allocation.allocations.map((a) => ({
          batch_id: a.batch_id,
          batch_no: a.batch_no,
          material_id: a.material_id,
          material_code: a.material_code,
          material_name: a.material_name,
          allocate_qty: a.allocate_qty,
          available_qty_before: a.available_qty_before,
          unit_cost: a.unit_cost,
          inbound_date: a.inbound_date,
        }))
      );
      shortage = allocation.shortage;
    }

    return successResponse({
      batches,
      total_available: totalAvailable,
      allocation_plan: allocationPlan,
      shortage,
      can_fulfill: shortage === 0,
    });
  },
  { errorMessage: '获取FIFO分配方案失败' }
);

export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const {
      warehouseId,
      warehouseCode,
      warehouseName,
      items,
      operatorId,
      operatorName,
      remark,
      outboundType,
    } = body;

    if (!warehouseId || !items || !Array.isArray(items) || items.length === 0) {
      return errorResponse('warehouseId 和 items 不能为空', 400, 400);
    }

    return await transaction(async (conn) => {
      const date = new Date();
      const dateStr = date.toISOString().slice(0, 10).replace(/-/g, '');
      const [maxOrder]: Loose = await conn.query(
        `SELECT MAX(order_no) as maxNo FROM inv_outbound_order WHERE order_no LIKE ?`,
        [`CK${dateStr}%`]
      );
      const maxNo = maxOrder[0]?.maxNo;
      const seq = maxNo ? String(parseInt(maxNo.slice(-3)) + 1).padStart(3, '0') : '001';
      const orderNo = `CK${dateStr}${seq}`;

      const allAllocations: FIFOAllocationResult[] = [];
      const allOutboundItems: Loose[] = [];

      for (const item of items) {
        const {
          material_id,
          material_code,
          material_name,
          qty,
          unit: _unit,
          batch_no,
          batch_id,
        } = item;
        const requiredQty = parseFloat(qty);

        if (batch_id || batch_no) {
          const [batch]: Loose = await conn.query(
            `SELECT id, batch_no, material_id, material_code, material_name, available_qty, unit_price, inbound_date, unit
           FROM inv_inventory_batch 
           WHERE id = ? OR batch_no = ?
           FOR UPDATE`,
            [batch_id || 0, batch_no || '']
          );

          if (batch.length === 0) {
            throw new Error(`指定批次不存在: ${batch_no || batch_id}`);
          }

          const batchData = batch[0];
          const availableQty = parseFloat(batchData.available_qty);

          if (availableQty < requiredQty) {
            throw new Error(
              `批次 ${batchData.batch_no} 库存不足: 可用 ${availableQty}, 需要 ${requiredQty}`
            );
          }

          allAllocations.push({
            material_id: batchData.material_id,
            material_code: batchData.material_code,
            material_name: batchData.material_name,
            required_qty: requiredQty,
            total_available: availableQty,
            allocated_qty: requiredQty,
            shortage: 0,
            allocations: [
              {
                batch_id: batchData.id,
                batch_no: batchData.batch_no,
                material_id: batchData.material_id,
                material_code: batchData.material_code,
                material_name: batchData.material_name,
                allocate_qty: requiredQty,
                available_qty_before: availableQty,
                unit_cost: parseFloat(batchData.unit_price) || 0,
                inbound_date: batchData.inbound_date,
              },
            ],
          });
        } else {
          const allocation = await allocateFIFO(conn, material_id, warehouseId, requiredQty);
          if (allocation.shortage > 0) {
            throw new Error(
              `物料 ${material_name || material_code} 库存不足: 需要 ${requiredQty}, 可用 ${allocation.total_available}, 缺少 ${allocation.shortage}`
            );
          }
          allAllocations.push(allocation);
        }
      }

      let totalQty = 0;
      let totalAmount = 0;

      for (const allocation of allAllocations) {
        for (const alloc of allocation.allocations) {
          const amount = alloc.allocate_qty * alloc.unit_cost;

          const [lockResult]: Loose = await conn.execute(
            `UPDATE inv_inventory_batch SET
              locked_qty = locked_qty + ?,
              available_qty = available_qty - ?
            WHERE id = ? AND available_qty >= ?`,
            [alloc.allocate_qty, alloc.allocate_qty, alloc.batch_id, alloc.allocate_qty]
          );

          if (lockResult.affectedRows === 0) {
            throw new Error(`批次 ${alloc.batch_no} 库存(可用量)不足或已被其他单据锁定，无法预留`);
          }

          allOutboundItems.push({
            material_id: alloc.material_id,
            material_code: alloc.material_code,
            material_name: alloc.material_name,
            batch_no: alloc.batch_no,
            batch_id: alloc.batch_id,
            qty: alloc.allocate_qty,
            unit_cost: alloc.unit_cost,
            amount,
          });
          totalQty += alloc.allocate_qty;
          totalAmount += amount;
        }
      }

      const [orderResult]: Loose = await conn.execute(
        `INSERT INTO inv_outbound_order (
        order_no, order_date, outbound_type,
        warehouse_id, warehouse_code, warehouse_name,
        total_qty, total_amount, remark, operator_id, operator_name, status
      ) VALUES (?, CURDATE(), ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending')`,
        [
          orderNo,
          outboundType || 'production',
          warehouseId,
          warehouseCode || '',
          warehouseName || '',
          totalQty,
          totalAmount,
          remark || '',
          operatorId,
          operatorName,
        ]
      );

      const orderId = orderResult.insertId;

      for (const obItem of allOutboundItems) {
        await conn.execute(
          `INSERT INTO inv_outbound_item (
          order_id, material_id, material_name, material_spec,
          quantity, unit, unit_price, amount, batch_no, remark
        ) VALUES (?, ?, ?, '', ?, ?, ?, ?, ?, ?)`,
          [
            orderId,
            obItem.material_id,
            obItem.material_name,
            obItem.qty,
            obItem.unit || '个',
            obItem.unit_cost,
            obItem.amount,
            obItem.batch_no,
            `FIFO出库-批次${obItem.batch_no}`,
          ]
        );
      }

      const result = {
        orderId,
        orderNo,
        allocations: allAllocations,
        totalQty,
        totalAmount,
        outboundItemCount: allOutboundItems.length,
      };

      await logOperation({
        title: 'FIFO出库',
        oper_name: operatorName,
        oper_type: 'warehouse',
        oper_method: 'POST',
        oper_url: '/api/warehouse/outbound/fifo',
        oper_param: JSON.stringify({ warehouseId, outboundType, totalQty, totalAmount }),
        oper_result: `FIFO出库单 ${orderNo} 创建成功，共${allOutboundItems.length}项`,
        status: 1,
      });

      return successResponse(result, 'FIFO出库单创建成功');
    });
  },
  { errorMessage: 'FIFO出库失败' }
);

export const PATCH = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { orderId, operatorId, operatorName, remark } = body;

    if (!orderId) {
      return errorResponse('orderId 不能为空', 400, 400);
    }

    return await transaction(async (conn) => {
      const [orders]: Loose = await conn.execute(
        `SELECT id, order_no, status, warehouse_id, warehouse_code, version FROM inv_outbound_order WHERE id = ? AND deleted = 0 FOR UPDATE`,
        [orderId]
      );

      if (orders.length === 0) {
        throw new Error('出库单不存在');
      }

      const order = orders[0];

      if (order.status === 'completed') {
        throw new Error('出库单已完成，不能重复确认');
      }

      const [items]: Loose = await conn.execute(
        `SELECT id, material_id, material_name, quantity, unit, batch_no FROM inv_outbound_item WHERE order_id = ? AND deleted = 0`,
        [orderId]
      );

      if (items.length === 0) {
        throw new Error('出库单没有明细');
      }

      const deductionDetails: Loose[] = [];

      for (const item of items) {
        const requiredQty = parseFloat(item.quantity);

        const [batchRows]: Loose = await conn.execute(
          `SELECT id, batch_no, locked_qty, quantity, unit_price, version FROM inv_inventory_batch
           WHERE batch_no = ? AND material_id = ? AND warehouse_id = ? AND deleted = 0
           FOR UPDATE`,
          [item.batch_no, item.material_id, order.warehouse_id]
        );

        if (batchRows.length === 0) {
          throw new Error(`批次 ${item.batch_no} 不存在`);
        }

        const batch = batchRows[0];
        const lockedQty = parseFloat(batch.locked_qty || 0);
        if (lockedQty < requiredQty) {
          throw new Error(
            `批次 ${item.batch_no} 预留锁定不足: 锁定 ${lockedQty}, 需要 ${requiredQty}（可用量已由建单时预留）`
          );
        }

        const [deductResult]: Loose = await conn.execute(
          `UPDATE inv_inventory_batch SET
            locked_qty = locked_qty - ?,
            quantity = quantity - ?,
            version = version + 1,
            update_time = NOW()
          WHERE id = ? AND locked_qty >= ? AND version = ?`,
          [requiredQty, requiredQty, batch.id, requiredQty, batch.version]
        );

        if (deductResult.affectedRows === 0) {
          throw new Error(`批次 ${item.batch_no} 扣减失败，可能已被其他操作修改，请刷新后重试`);
        }

        const [currentInv]: Loose = await conn.query(
          'SELECT quantity FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0',
          [item.material_id, order.warehouse_id]
        );
        const beforeQty = currentInv.length > 0 ? parseFloat(currentInv[0].quantity) : 0;
        const afterQty = beforeQty - requiredQty;

        await conn.execute(
          `INSERT INTO inv_inventory_log (
            material_id, warehouse_id, batch_no, operation_type, operation_qty,
            before_qty, after_qty, business_type, business_no, remark, operator_id, create_time
          ) VALUES (?, ?, ?, 2, ?, ?, ?, ?, ?, ?, ?, NOW())`,
          [
            item.material_id,
            order.warehouse_id,
            item.batch_no,
            requiredQty,
            beforeQty,
            afterQty,
            'outbound_order',
            order.order_no,
            `FIFO出库确认-批次${item.batch_no}`,
            operatorId || null,
          ]
        );

        deductionDetails.push({
          batch_id: batch.id,
          batch_no: item.batch_no,
          material_id: item.material_id,
          deducted_qty: requiredQty,
          unit_cost: parseFloat(batch.unit_price) || 0,
        });
      }

      const [orderUpdateResult]: Loose = await conn.execute(
        `UPDATE inv_outbound_order SET
        status = 'completed',
        audit_status = 1,
        auditor_id = ?,
        auditor_name = ?,
        audit_time = NOW(),
        audit_remark = ?,
        version = version + 1,
        update_time = NOW()
      WHERE id = ? AND version = ?`,
        [operatorId, operatorName, remark || '', orderId, order.version]
      );
      if (orderUpdateResult.affectedRows === 0) {
        throw new Error('出库单版本冲突，可能已被其他操作修改，请刷新后重试');
      }

      const result = {
        orderId,
        orderNo: order.order_no,
        status: 'completed',
        deductionDetails,
        totalDeductedBatches: deductionDetails.length,
      };

      await logOperation({
        title: 'FIFO出库确认',
        oper_name: operatorName,
        oper_type: 'warehouse',
        oper_method: 'PATCH',
        oper_url: '/api/warehouse/outbound/fifo',
        oper_param: JSON.stringify({ orderId, operatorId }),
        oper_result: `FIFO出库单 ${order.order_no} 确认成功，扣减${deductionDetails.length}个批次`,
        status: 1,
      });

      return successResponse(result, 'FIFO出库确认成功，库存已按先进先出扣减');
    });
  },
  { errorMessage: 'FIFO出库确认失败' }
);

﻿import { NextRequest } from 'next/server';
import { query, execute, transaction, queryPaginated } from '@/lib/db';
import {
  successResponse,
  paginatedResponse,
  errorResponse,
  commonErrors,
  validateRequestBody,
  logOperation,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { generateDocumentNo } from '@/lib/document-numbering';
import {
  WarehouseStateMachine,
  OutboundStatus,
} from '@/domain/warehouse/value-objects/WarehouseStateMachine';

// 获取出库单列表
export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const keyword = searchParams.get('keyword') || '';
  const status = searchParams.get('status') || '';
  const startDate = searchParams.get('startDate') || '';
  const endDate = searchParams.get('endDate') || '';
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '10');

  // 基础查询SQL
  let sql = `
    SELECT
      o.id,
      o.order_no as orderNo,
      o.order_date as orderDate,
      o.outbound_type as outboundType,
      o.warehouse_code as warehouseCode,
      o.warehouse_name as warehouseName,
      o.total_qty as totalQty,
      o.total_amount as totalAmount,
      o.currency,
      o.exchange_rate as exchangeRate,
      o.base_total_amount as baseTotalAmount,
      o.status,
      o.remark,
      o.operator_name as operatorName,
      o.audit_status as auditStatus,
      o.auditor_name as auditorName,
      o.audit_time as auditTime,
      o.create_time as createTime
    FROM inv_outbound_order o
    WHERE o.deleted = 0
  `;

  let countSql = `SELECT COUNT(*) as total FROM inv_outbound_order o WHERE o.deleted = 0`;
  const params: Loose[] = [];

  if (keyword) {
    const keywordCondition = ` AND (o.order_no LIKE ? OR o.remark LIKE ?)`;
    sql += keywordCondition;
    countSql += keywordCondition;
    params.push(`%${keyword}%`, `%${keyword}%`);
  }

  if (status) {
    sql += ` AND o.status = ?`;
    countSql += ` AND o.status = ?`;
    params.push(status);
  }

  if (startDate) {
    sql += ` AND o.order_date >= ?`;
    countSql += ` AND o.order_date >= ?`;
    params.push(startDate);
  }

  if (endDate) {
    sql += ` AND o.order_date <= ?`;
    countSql += ` AND o.order_date <= ?`;
    params.push(endDate);
  }

  sql += ` ORDER BY o.create_time DESC`;

  // 使用分页查询工具
  const result = await queryPaginated(sql, countSql, params, { page, pageSize });

  // 获取每个订单的明细（使用IN查询优化N+1问题）
  if (result.data.length > 0) {
    const orderIds = result.data.map((o: Loose) => o.id);
    const placeholders = orderIds.map(() => '?').join(',');

    const items = await query(
      `SELECT
        id,
        order_id as orderId,
        material_id,
        material_name as materialName,
        material_spec as specification,
        quantity as qty,
        unit,
        unit_price,
        amount,
        base_unit_price as baseUnitPrice,
        base_amount as baseAmount,
        batch_no as batchNo,
        remark
      FROM inv_outbound_item
      WHERE order_id IN (${placeholders})`,
      orderIds
    );

    // 将明细分组到对应的订单
    const itemsMap = new Map();
    for (const item of items as Loose[]) {
      if (!itemsMap.has(item.orderId)) {
        itemsMap.set(item.orderId, []);
      }
      itemsMap.get(item.orderId).push(item);
    }

    for (const order of result.data as Loose[]) {
      order.items = itemsMap.get(order.id) || [];
    }
  }

  return paginatedResponse(result.data, result.pagination);
});

// 创建出库单
export const POST = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();

    // 验证必填字段
    const validation = validateRequestBody(body, [
      'orderDate',
      'warehouseId',
      'warehouseCode',
      'warehouseName',
      'items',
      'operatorId',
      'operatorName',
    ]);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    const {
      orderDate,
      outboundType,
      warehouseId,
      warehouseCode,
      warehouseName,
      remark,
      items,
      operatorId,
      operatorName,
      currency,
    } = body;

    const orderNo = await generateDocumentNo('outbound');

    // 使用事务确保数据一致性
    const result = await transaction(async (connection) => {
      // 计算总金额
      const totalQty = items.reduce(
        (sum: number, item: Loose) => sum + (parseFloat(item.qty) || 0),
        0
      );
      const totalAmount = items.reduce(
        (sum: number, item: Loose) =>
          sum + (parseFloat(item.qty) || 0) * (parseFloat(item.unitPrice) || 0),
        0
      );

      // 插入出库单主表
      const [orderResult] = await connection.execute(
        `INSERT INTO inv_outbound_order (
        order_no, order_date, outbound_type,
        warehouse_id, warehouse_code, warehouse_name,
        total_qty, total_amount, currency, remark, operator_id, operator_name, status
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending')`,
        [
          orderNo,
          orderDate,
          outboundType,
          warehouseId,
          warehouseCode,
          warehouseName,
          totalQty,
          totalAmount,
          currency || null,
          remark,
          operatorId,
          operatorName,
        ]
      );

      const orderId = (orderResult as Loose).insertId;

      // 批量插入出库单明细
      if (items.length > 0) {
        const itemValues = items.map((item: Loose) => [
          orderId,
          item.materialId,
          item.materialName,
          item.specification || '',
          item.qty,
          item.unit || '个',
          item.unitPrice || 0,
          (parseFloat(item.qty) || 0) * (parseFloat(item.unitPrice) || 0),
          item.batchNo || '',
          item.remark || '',
        ]);

        await connection.query(
          `INSERT INTO inv_outbound_item (
          order_id, material_id, material_name,
          material_spec, quantity, unit, unit_price, amount,
          batch_no, remark
        ) VALUES ?`,
          [itemValues]
        );
      }

      return { id: orderId, orderNo };
    });

    await logOperation({
      title: '创建出库单',
      oper_type: 'warehouse',
      oper_method: 'POST',
      oper_url: '/api/warehouse/outbound',
      oper_param: JSON.stringify({
        orderNo: result.orderNo,
        warehouseCode,
        warehouseName,
        operatorName,
      }),
      oper_result: `出库单 ${result.orderNo} 创建成功`,
      status: 1,
    });

    return successResponse(result, '出库单创建成功');
  },
  { errorMessage: '创建出库单失败' }
);

// 更新出库单
export const PUT = withPermission(
  async (request: NextRequest, _userInfo) => {
    const body = await request.json();
    const { id, ...updateData } = body;

    if (!id) {
      return commonErrors.badRequest('出库单ID不能为空');
    }

    // 检查出库单状态
    const [order] = await query<{ status: OutboundStatus }>(
      'SELECT status FROM inv_outbound_order WHERE id = ? AND deleted = 0',
      [id]
    );

    if (!order) {
      return commonErrors.notFound('出库单不存在');
    }

    // 使用状态机检查是否允许编辑
    if (!WarehouseStateMachine.canEditOutbound(order.status)) {
      return errorResponse(
        `当前状态【${WarehouseStateMachine.getOutboundStatusLabel(order.status)}】不允许修改`,
        400,
        400
      );
    }

    await execute(
      `UPDATE inv_outbound_order SET
      order_date = ?,
      outbound_type = ?,
      warehouse_id = ?,
      warehouse_code = ?,
      warehouse_name = ?,
      remark = ?,
      update_time = NOW()
    WHERE id = ?`,
      [
        updateData.orderDate,
        updateData.outboundType,
        updateData.warehouseId,
        updateData.warehouseCode,
        updateData.warehouseName,
        updateData.remark,
        id,
      ]
    );

    return successResponse(null, '出库单更新成功');
  },
  { logTitle: '更新出库单', logType: 'business' }
);

// 删除出库单（软删除）
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return commonErrors.badRequest('出库单ID不能为空');
    }

    // 检查出库单状态
    const [order] = await query<{ status: OutboundStatus }>(
      'SELECT status FROM inv_outbound_order WHERE id = ? AND deleted = 0',
      [id]
    );

    if (!order) {
      return commonErrors.notFound('出库单不存在');
    }

    // 使用状态机检查是否允许删除
    if (!WarehouseStateMachine.canDeleteOutbound(order.status)) {
      return errorResponse(
        `当前状态【${WarehouseStateMachine.getOutboundStatusLabel(order.status)}】不允许删除`,
        400,
        400
      );
    }

    // 使用事务同时更新主表和明细表
    await transaction(async (connection) => {
      await connection.execute(
        'UPDATE inv_outbound_order SET deleted = 1, update_time = NOW() WHERE id = ?',
        [id]
      );
      await connection.execute('UPDATE inv_outbound_item SET deleted = 1 WHERE order_id = ?', [id]);
    });

    await logOperation({
      title: '删除出库单',
      oper_type: 'warehouse',
      oper_method: 'DELETE',
      oper_url: '/api/warehouse/outbound',
      oper_param: JSON.stringify({ id }),
      oper_result: `出库单 ${id} 删除成功`,
      status: 1,
    });

    return successResponse(null, '出库单删除成功');
  },
  { errorMessage: '删除出库单失败' }
);

import { NextRequest, NextResponse } from 'next/server';
import { query, execute, transaction } from '@/lib/db';
import { successResponse, errorResponse, logOperation } from '@/lib/api-response';
import { randomUUID } from 'crypto';

import { withPermission } from '@/lib/api-permissions';
import { FinishOrderApprovedEvent } from '@/domain/production/events/FinishOrderEvents';
import { getDomainEventOutbox } from '@/infrastructure/event-bus/DomainEventOutboxFactory';
export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const inboundNo = searchParams.get('inboundNo') || '';
  const status = searchParams.get('status') || '';
  const workOrderNo = searchParams.get('workOrderNo') || '';

  let where = 'WHERE p.deleted = 0';
  const params: Loose[] = [];
  if (inboundNo) {
    where += ' AND p.inbound_no LIKE ?';
    params.push('%' + inboundNo + '%');
  }
  if (status) {
    where += ' AND p.status = ?';
    params.push(Number(status));
  }
  if (workOrderNo) {
    where += ' AND p.work_order_no LIKE ?';
    params.push('%' + workOrderNo + '%');
  }

  const totalRows: Loose = await query(
    'SELECT COUNT(*) as total FROM inv_production_inbound p ' + where,
    params
  );
  const total = totalRows[0]?.total || 0;
  const rows: Loose = await query(
    'SELECT p.*, w.warehouse_name FROM inv_production_inbound p LEFT JOIN inv_warehouse w ON p.warehouse_id = w.id ' +
      where +
      ' ORDER BY p.create_time DESC LIMIT ? OFFSET ?',
    [...params, pageSize, (page - 1) * pageSize]
  );

  for (const row of rows) {
    const items: Loose = await query(
      'SELECT * FROM inv_production_inbound_item WHERE inbound_id = ?',
      [row.id]
    );
    row.items = items;
  }

  return successResponse({ list: rows, total, page, pageSize });
});

export const POST = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const {
    work_order_id,
    work_order_no,
    warehouse_id,
    inbound_date,
    operator_name,
    qc_status,
    remark,
    items,
  } = body;

  if (!warehouse_id) {
    return errorResponse('仓库ID不能为空', 400, 400);
  }
  if (!items || !Array.isArray(items) || items.length === 0) {
    return errorResponse('入库明细不能为空', 400, 400);
  }

  const now = new Date();
  const inboundNo =
    'PI' +
    now.getFullYear() +
    String(now.getMonth() + 1).padStart(2, '0') +
    String(now.getDate()).padStart(2, '0') +
    String(Math.floor(Math.random() * 10000)).padStart(4, '0');

  const result: Loose = await transaction(async (conn) => {
    if (work_order_id) {
      const [woRows]: Loose = await conn.execute(
        'SELECT id, order_no, status, plan_qty, completed_qty FROM prod_work_order WHERE id = ? AND deleted = 0 FOR UPDATE',
        [work_order_id]
      );
      if (woRows.length === 0) {
        throw new Error('工单不存在');
      }
      const wo = woRows[0];
      if (wo.status < 20) {
        throw new Error('工单未审核，不能入库');
      }
      if (wo.status >= 90) {
        throw new Error('工单已关闭，不能入库');
      }
    }

    const [orderResult]: Loose = await conn.execute(
      'INSERT INTO inv_production_inbound (inbound_no, work_order_id, work_order_no, warehouse_id, inbound_date, operator_name, qc_status, status, remark) VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?)',
      [
        inboundNo,
        work_order_id || null,
        work_order_no || null,
        warehouse_id,
        inbound_date,
        operator_name || null,
        qc_status || 'pending',
        remark || null,
      ]
    );
    const inboundId = orderResult.insertId;

    for (const item of items) {
      await conn.execute(
        'INSERT INTO inv_production_inbound_item (inbound_id, material_id, material_code, material_name, quantity, unit, batch_no) VALUES (?, ?, ?, ?, ?, ?, ?)',
        [
          inboundId,
          item.material_id,
          item.material_code || null,
          item.material_name || null,
          item.quantity,
          item.unit || null,
          item.batch_no || null,
        ]
      );
    }

    return { id: inboundId, inbound_no: inboundNo };
  });

  return successResponse(result, '生产入库单创建成功');
});

export const PUT = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { id, action, status, qc_status, remark } = body;

  if (!id) {
    return errorResponse('入库单ID不能为空', 400, 400);
  }

  if (action === 'post') {
    const result = await transaction(async (conn) => {
      const [inboundRows]: Loose = await conn.execute(
        'SELECT id, inbound_no, work_order_id, work_order_no, warehouse_id, status, qc_status FROM inv_production_inbound WHERE id = ? AND deleted = 0 FOR UPDATE',
        [id]
      );

      if (inboundRows.length === 0) {
        throw new Error('入库单不存在');
      }

      const inbound = inboundRows[0];

      if (inbound.status >= 3) {
        throw new Error('入库单已完成或已取消，不能重复过账');
      }

      if (inbound.qc_status === 'fail') {
        throw new Error('质检不合格，不能入库');
      }

      const [itemRows]: Loose = await conn.execute(
        'SELECT * FROM inv_production_inbound_item WHERE inbound_id = ?',
        [id]
      );

      for (const item of itemRows) {
        const [existing]: Loose = await conn.execute(
          'SELECT id, quantity FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.material_id, inbound.warehouse_id]
        );

        if (existing.length > 0) {
          await conn.execute(
            'UPDATE inv_inventory SET quantity = quantity + ?, update_time = NOW() WHERE id = ?',
            [item.quantity, existing[0].id]
          );
        } else {
          await conn.execute(
            'INSERT INTO inv_inventory (material_id, material_code, material_name, warehouse_id, quantity, unit, batch_no) VALUES (?, ?, ?, ?, ?, ?, ?)',
            [
              item.material_id,
              item.material_code,
              item.material_name,
              inbound.warehouse_id,
              item.quantity,
              item.unit,
              item.batch_no || null,
            ]
          );
        }

        const transNo = 'TRX' + Date.now() + String(item.id).slice(-4);
        const [matRows]: Loose = await conn.execute(
          'SELECT material_code FROM mdm_material WHERE id = ?',
          [item.material_id]
        );
        const matCode = matRows.length > 0 ? matRows[0].material_code : '';

        await conn.execute(
          'INSERT INTO inv_inventory_transaction (trans_no, trans_type, source_type, source_id, material_id, material_code, batch_no, warehouse_id, quantity, unit_price, total_amount, account_dr, account_cr, create_time) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())',
          [
            transNo,
            'in',
            'production_inbound',
            id,
            item.material_id,
            matCode,
            item.batch_no || '',
            inbound.warehouse_id,
            item.quantity,
            0,
            0,
            '成品库存',
            '生产成本',
          ]
        );
      }

      await conn.execute(
        "UPDATE inv_production_inbound SET status = 3, qc_status = COALESCE(qc_status, 'pass'), update_time = NOW() WHERE id = ?",
        [id]
      );

      if (inbound.work_order_id) {
        const totalQty = itemRows.reduce(
          (sum: number, item: Loose) => sum + Number(item.quantity || 0),
          0
        );

        await conn.execute(
          'UPDATE prod_work_order SET completed_qty = completed_qty + ? WHERE id = ? AND deleted = 0',
          [totalQty, inbound.work_order_id]
        );

        const [woRows]: Loose = await conn.execute(
          'SELECT plan_qty, completed_qty, status FROM prod_work_order WHERE id = ?',
          [inbound.work_order_id]
        );

        if (woRows.length > 0) {
          const wo = woRows[0];
          if (Number(wo.completed_qty) >= Number(wo.plan_qty) && wo.status < 50) {
            await conn.execute('UPDATE prod_work_order SET status = 50 WHERE id = ?', [
              inbound.work_order_id,
            ]);
          } else if (Number(wo.completed_qty) > 0 && wo.status < 40) {
            await conn.execute('UPDATE prod_work_order SET status = 40 WHERE id = ?', [
              inbound.work_order_id,
            ]);
          }
        }
      }

      // T206: Publish FinishOrderApprovedEvent for downstream handlers (finance, etc.)
      const totalQualifiedQty = itemRows.reduce(
        (sum: number, item: Loose) => sum + Number(item.quantity || 0),
        0
      );
      await getDomainEventOutbox().saveEvents(conn, 'ProductionInbound', id, [
        new FinishOrderApprovedEvent({
          finishOrderId: id,
          finishNo: inbound.inbound_no,
          workOrderId: inbound.work_order_id || 0,
          workOrderNo: inbound.work_order_no || '',
          productName: itemRows[0]?.material_name || '',
          qualifiedQty: totalQualifiedQty,
          defectiveQty: 0,
          warehouseId: inbound.warehouse_id,
          userId: 0,
        }),
      ]);

      return { id, status: 3 };
    });

    const [outboundRows]: Loose = await query(
      'SELECT id, inbound_no, work_order_id, work_order_no, warehouse_id, qc_status FROM inv_production_inbound WHERE id = ? AND deleted = 0',
      [id]
    );
    const inboundInfo = outboundRows[0];

    if (inboundInfo) {
      const prodItems: Loose = await query(
        'SELECT * FROM inv_production_inbound_item WHERE inbound_id = ?',
        [id]
      );

      for (const item of prodItems as Loose[]) {
        const qrCode = 'PR-' + randomUUID().replace(/-/g, '').substring(0, 16);
        await execute(
          `INSERT INTO qrcode_record (qr_code, qr_type, ref_id, ref_no, material_id, material_code, material_name, quantity, unit, warehouse_id, work_order_id, work_order_no, production_date, status, extra_data)
           VALUES (?, 'product', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)`,
          [
            qrCode,
            id,
            inboundInfo.inbound_no,
            item.material_id || null,
            item.material_code || null,
            item.material_name || '',
            item.quantity || 0,
            item.unit || '',
            inboundInfo.warehouse_id || null,
            inboundInfo.work_order_id || null,
            inboundInfo.work_order_no || null,
            new Date().toISOString().slice(0, 10),
            JSON.stringify({
              inbound_no: inboundInfo.inbound_no,
              qc_status: inboundInfo.qc_status,
            }),
          ]
        );
      }

      await logOperation({
        title: '生产入库过账',
        oper_type: '入库',
        oper_method: 'PUT',
        oper_url: '/api/warehouse/production-inbound',
        oper_param: JSON.stringify({ id, action: 'post' }),
        oper_result: `生产入库 ${inboundInfo.inbound_no} 过账成功，已生成 ${(prodItems as Loose[]).length} 个成品二维码`,
      });
    }

    return successResponse(result, '入库过账成功');
  }

  if (action === 'qc') {
    const { qc_results } = body;
    if (!qc_results) {
      return errorResponse('质检结果不能为空', 400, 400);
    }

    const hasFail = qc_results.some((q: Loose) => q.result === 'fail');
    const newQcStatus = hasFail ? 'fail' : 'pass';

    await execute('UPDATE inv_production_inbound SET qc_status = ? WHERE id = ? AND deleted = 0', [
      newQcStatus,
      id,
    ]);

    if (hasFail) {
      const [itemRows]: Loose = await query(
        'SELECT * FROM inv_production_inbound_item WHERE inbound_id = ?',
        [id]
      );

      for (const item of itemRows) {
        const qcResult = qc_results.find((q: Loose) => q.item_id === item.id);
        if (qcResult && qcResult.result === 'fail') {
          const now = new Date();
          const handleNo =
            'QH' +
            now.getFullYear() +
            String(now.getMonth() + 1).padStart(2, '0') +
            String(now.getDate()).padStart(2, '0') +
            String(Math.floor(Math.random() * 10000)).padStart(4, '0');
          await execute(
            'INSERT INTO qc_unqualified (handle_no, inspection_id, material_id, material_code, material_name, quantity, handle_type, handle_status, remark) VALUES (?, ?, ?, ?, ?, ?, 1, 1, ?)',
            [
              handleNo,
              id,
              item.material_id,
              item.material_code,
              item.material_name,
              item.quantity,
              '生产入库质检不合格，自动生成',
            ]
          );
        }
      }
    }

    return successResponse({ id, qc_status: newQcStatus }, '质检完成');
  }

  if (status !== undefined)
    await execute('UPDATE inv_production_inbound SET status = ? WHERE id = ? AND deleted = 0', [
      status,
      id,
    ]);
  if (qc_status !== undefined)
    await execute('UPDATE inv_production_inbound SET qc_status = ? WHERE id = ? AND deleted = 0', [
      qc_status,
      id,
    ]);
  if (remark !== undefined)
    await execute('UPDATE inv_production_inbound SET remark = ? WHERE id = ? AND deleted = 0', [
      remark,
      id,
    ]);
  return successResponse(null, '更新成功');
});

export const DELETE = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');
  if (!id) return NextResponse.json({ success: false, message: '缺少id' }, { status: 400 });

  const inbound: Loose = await query(
    'SELECT status FROM inv_production_inbound WHERE id = ? AND deleted = 0',
    [Number(id)]
  );
  if (inbound.length === 0) {
    return errorResponse('入库单不存在', 404, 404);
  }
  if (inbound[0].status >= 3) {
    return errorResponse('已完成的入库单不能删除', 400, 400);
  }

  await execute('UPDATE inv_production_inbound SET deleted = 1 WHERE id = ?', [Number(id)]);
  return successResponse(null, '删除成功');
});

import { NextRequest } from 'next/server';
import mysql from 'mysql2/promise';
import { query, queryOne, transaction } from '@/lib/db';
import {
  successResponse,
  errorResponse,
  commonErrors,
  validateRequestBody,
  logOperation,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';

// 仓库类型映射
const warehouseTypeMap: { [key: string]: number } = {
  raw: 1,
  finished: 2,
  semi: 3,
  scrap: 4,
  other: 5,
};

const warehouseTypeReverseMap: { [key: number]: string } = {
  1: 'raw',
  2: 'finished',
  3: 'semi',
  4: 'scrap',
  5: 'other',
};

// 仓库数据接口
interface Warehouse {
  id?: number;
  code: string;
  name: string;
  type: string;
  address?: string;
  remark?: string;
  status: string | number;
  createTime?: string;
  updateTime?: string;
}

// 构建查询条件
function buildQueryConditions(params: {
  keyword?: string;
  type?: string;
  status?: string;
  categoryId?: string;
}): { sql: string; values: Loose[] } {
  let sql = `
    SELECT
      id,
      warehouse_code as code,
      warehouse_name as name,
      warehouse_type,
      category_id,
      address,
      remark,
      status,
      create_time as createTime,
      update_time as updateTime
    FROM inv_warehouse
    WHERE deleted = 0
  `;
  const values: Loose[] = [];

  if (params.keyword) {
    sql += ` AND (warehouse_code LIKE ? OR warehouse_name LIKE ?)`;
    const likeKeyword = `%${params.keyword}%`;
    values.push(likeKeyword, likeKeyword);
  }

  if (params.type) {
    sql += ` AND warehouse_type = ?`;
    values.push(warehouseTypeMap[params.type] || 1);
  }

  if (params.categoryId) {
    sql += ` AND category_id = ?`;
    values.push(parseInt(params.categoryId));
  }

  if (params.status !== undefined && params.status !== '') {
    const statusNum = parseInt(params.status);
    if (!isNaN(statusNum)) {
      sql += ` AND status = ?`;
      values.push(statusNum);
    } else if (params.status === 'active') {
      sql += ` AND status = 1`;
    } else if (params.status === 'inactive') {
      sql += ` AND status = 0`;
    }
  }

  sql += ` ORDER BY create_time DESC`;

  return { sql, values };
}

// 格式化仓库数据
function formatWarehouse(warehouse: Loose): Warehouse {
  return {
    ...warehouse,
    type: warehouseTypeReverseMap[warehouse.warehouse_type] || 'other',
    status: warehouse.status === 1 ? 'active' : 'inactive',
  };
}

export const GET = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const keyword = searchParams.get('keyword') || '';
    const type = searchParams.get('type') || '';
    const status = searchParams.get('status') || '';
    const categoryId = searchParams.get('category_id') || '';
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');

    const { sql, values } = buildQueryConditions({
      keyword,
      type,
      status,
      categoryId,
    });

    let countSql = `SELECT COUNT(*) as total FROM inv_warehouse WHERE deleted = 0`;
    const countValues: Loose[] = [];
    if (keyword) {
      countSql += ` AND (warehouse_code LIKE ? OR warehouse_name LIKE ?)`;
      countValues.push(`%${keyword}%`, `%${keyword}%`);
    }
    if (type) {
      countSql += ` AND warehouse_type = ?`;
      countValues.push(warehouseTypeMap[type] || 1);
    }
    if (categoryId) {
      countSql += ` AND category_id = ?`;
      countValues.push(parseInt(categoryId));
    }
    if (status !== undefined && status !== '') {
      const statusNum = parseInt(status);
      if (!isNaN(statusNum)) {
        countSql += ` AND status = ?`;
        countValues.push(statusNum);
      } else if (status === 'active') {
        countSql += ` AND status = 1`;
      } else if (status === 'inactive') {
        countSql += ` AND status = 0`;
      }
    }

    const countResult = await query(countSql, countValues);
    const total = (countResult as Loose[])[0]?.total || 0;

    const paginatedSql = `${sql} LIMIT ? OFFSET ?`;
    const paginatedValues = [...values, pageSize, (page - 1) * pageSize];

    const warehouses = await query(paginatedSql, paginatedValues);
    const formattedWarehouses = (warehouses as Loose[]).map(formatWarehouse);

    // 支持 all=true 参数，直接返回数组（用于下拉选择等场景）
    const fetchAll = searchParams.get('all') === 'true';
    if (fetchAll) {
      const allWarehouses = await query(sql, values);
      const formattedAll = (allWarehouses as Loose[]).map(formatWarehouse);
      return successResponse(formattedAll);
    }

    return successResponse({
      list: formattedWarehouses,
      total,
      page,
      pageSize,
    });
  },
  { errorMessage: '获取仓库列表失败' }
);

// POST - 创建仓库
export const POST = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const body: Warehouse = await request.json();

    // 验证必填字段
    const validation = validateRequestBody(body, ['code', 'name', 'type']);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    // 检查编码是否已存在
    const existing = await queryOne<{ id: number }>(
      'SELECT id FROM inv_warehouse WHERE warehouse_code = ? AND deleted = 0',
      [body.code]
    );

    if (existing) {
      return errorResponse('仓库编码已存在', 409, 409);
    }

    // 使用事务创建仓库并记录日志
    const result = await transaction(async (connection) => {
      const [insertResult] = await (connection as Loose).execute(
        `INSERT INTO inv_warehouse (
          warehouse_code, warehouse_name, warehouse_type,
          address, remark, status
        ) VALUES (?, ?, ?, ?, ?, ?)`,
        [
          body.code,
          body.name,
          warehouseTypeMap[body.type] || 5,
          body.address,
          body.remark,
          body.status === 'active' ? 1 : 0,
        ]
      );

      const warehouseId = (insertResult as mysql.ResultSetHeader).insertId;

      // 记录操作日志
      await connection.execute(
        `INSERT INTO inv_warehouse_log (warehouse_id, operation_type, operation_content)
       VALUES (?, 'create', ?)`,
        [warehouseId, `创建仓库: ${body.name}`]
      );

      return { id: warehouseId };
    });

    await logOperation({
      title: '创建仓库',
      oper_type: 'warehouse',
      oper_method: 'POST',
      oper_url: '/api/warehouse',
      oper_param: JSON.stringify({ code: body.code, name: body.name, type: body.type }),
      oper_result: `仓库 ${body.name} 创建成功`,
      status: 1,
    });

    return successResponse(result, '仓库创建成功');
  },
  { errorMessage: '创建仓库失败' }
);

// PUT - 更新仓库
export const PUT = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const body: Warehouse = await request.json();
    const { id } = body;

    if (!id) {
      return commonErrors.badRequest('仓库ID不能为空');
    }

    // 验证必填字段
    const validation = validateRequestBody(body, ['code', 'name', 'type']);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    // 检查编码是否被其他仓库使用
    const codeExists = await queryOne<{ id: number }>(
      'SELECT id FROM inv_warehouse WHERE warehouse_code = ? AND id != ? AND deleted = 0',
      [body.code, id]
    );

    if (codeExists) {
      return errorResponse('仓库编码已存在', 409, 409);
    }

    // 使用事务更新仓库并记录日志
    await transaction(async (connection) => {
      const [updateResult] = await (connection as Loose).execute(
        `UPDATE inv_warehouse SET
        warehouse_code = ?,
        warehouse_name = ?,
        warehouse_type = ?,
        address = ?,
        remark = ?,
        status = ?
      WHERE id = ? AND deleted = 0`,
        [
          body.code,
          body.name,
          warehouseTypeMap[body.type] || 5,
          body.address,
          body.remark,
          body.status === 'active' ? 1 : 0,
          id,
        ]
      );

      if ((updateResult as mysql.ResultSetHeader).affectedRows === 0) {
        throw new Error('仓库不存在或已被删除');
      }

      // 记录操作日志
      await connection.execute(
        `INSERT INTO inv_warehouse_log (warehouse_id, operation_type, operation_content)
       VALUES (?, 'update', ?)`,
        [id, `更新仓库: ${body.name}`]
      );
    });

    await logOperation({
      title: '更新仓库',
      oper_type: 'warehouse',
      oper_method: 'PUT',
      oper_url: '/api/warehouse',
      oper_param: JSON.stringify({ id, code: body.code, name: body.name, type: body.type }),
      oper_result: `仓库 ${body.name} 更新成功`,
      status: 1,
    });

    return successResponse(null, '仓库更新成功');
  },
  { errorMessage: '更新仓库失败' }
);

// DELETE - 删除仓库（软删除）
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return commonErrors.badRequest('仓库ID不能为空');
    }

    const warehouseId = parseInt(id);

    // 使用事务软删除并记录日志
    const warehouseName = await transaction(async (connection) => {
      const [rows] = await connection.query(
        'SELECT warehouse_name as name FROM inv_warehouse WHERE id = ? AND deleted = 0',
        [warehouseId]
      );

      if ((rows as Loose[]).length === 0) {
        throw new Error('仓库不存在或已被删除');
      }

      const name = (rows as Loose[])[0].name;

      await connection.execute('UPDATE inv_warehouse SET deleted = 1 WHERE id = ?', [warehouseId]);

      await connection.execute(
        `INSERT INTO inv_warehouse_log (warehouse_id, operation_type, operation_content)
       VALUES (?, 'delete', ?)`,
        [warehouseId, `删除仓库: ${name}`]
      );

      return name;
    });

    await logOperation({
      title: '删除仓库',
      oper_type: 'warehouse',
      oper_method: 'DELETE',
      oper_url: '/api/warehouse',
      oper_param: JSON.stringify({ id: warehouseId }),
      oper_result: `仓库 ${warehouseName} 删除成功`,
      status: 1,
    });

    return successResponse(null, '仓库删除成功');
  },
  { errorMessage: '删除仓库失败' }
);

import { NextRequest, NextResponse } from 'next/server';
import { query, queryOne, execute, transaction } from '@/lib/db';
import { successResponse, errorResponse, logOperation } from '@/lib/api-response';
import { randomUUID } from 'crypto';

import { withPermission } from '@/lib/api-permissions';
export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const outboundNo = searchParams.get('outboundNo') || '';
  const status = searchParams.get('status') || '';
  const orderNo = searchParams.get('orderNo') || '';

  let where = 'WHERE s.deleted = 0';
  const params: Loose[] = [];
  if (outboundNo) {
    where += ' AND s.outbound_no LIKE ?';
    params.push('%' + outboundNo + '%');
  }
  if (status) {
    where += ' AND s.status = ?';
    params.push(Number(status));
  }
  if (orderNo) {
    where += ' AND s.order_no LIKE ?';
    params.push('%' + orderNo + '%');
  }

  const totalRows: Loose = await query(
    'SELECT COUNT(*) as total FROM inv_sales_outbound s ' + where,
    params
  );
  const total = totalRows[0]?.total || 0;
  const rows: Loose = await query(
    'SELECT s.*, w.warehouse_name FROM inv_sales_outbound s LEFT JOIN inv_warehouse w ON s.warehouse_id = w.id ' +
      where +
      ' ORDER BY s.create_time DESC LIMIT ? OFFSET ?',
    [...params, pageSize, (page - 1) * pageSize]
  );

  for (const row of rows) {
    const items: Loose = await query(
      'SELECT * FROM inv_sales_outbound_item WHERE outbound_id = ?',
      [row.id]
    );
    row.items = items;
  }

  return successResponse({ list: rows, total, page, pageSize });
});

export const POST = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const {
    order_id,
    order_no,
    customer_id,
    customer_name,
    warehouse_id,
    outbound_date,
    delivery_person,
    remark,
    items,
  } = body;

  if (!warehouse_id) {
    return errorResponse('仓库ID不能为空', 400, 400);
  }
  if (!items || !Array.isArray(items) || items.length === 0) {
    return errorResponse('出库明细不能为空', 400, 400);
  }

  const now = new Date();
  const outboundNo =
    'SO' +
    now.getFullYear() +
    String(now.getMonth() + 1).padStart(2, '0') +
    String(now.getDate()).padStart(2, '0') +
    String(Math.floor(Math.random() * 10000)).padStart(4, '0');

  const result: Loose = await transaction(async (conn) => {
    if (order_id) {
      const [orderRows]: Loose = await conn.execute(
        'SELECT id, order_no, status, total_amount FROM sales_order WHERE id = ? AND deleted = 0 FOR UPDATE',
        [order_id]
      );
      if (orderRows.length === 0) {
        throw new Error('销售订单不存在');
      }
      if (orderRows[0].status < 20) {
        throw new Error('销售订单未审核，不能出库');
      }
      if (orderRows[0].status >= 90) {
        throw new Error('销售订单已关闭，不能出库');
      }
    }

    for (const item of items) {
      if (!item.material_id || !item.quantity || Number(item.quantity) <= 0) {
        throw new Error(`物料 ${item.material_name || item.material_id} 出库数量必须大于0`);
      }

      const [invRows]: Loose = await conn.execute(
        'SELECT id, quantity, material_code, material_name FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
        [item.material_id, warehouse_id]
      );

      if (invRows.length === 0) {
        throw new Error(`物料 ${item.material_name || item.material_id} 在该仓库无库存`);
      }

      if (Number(invRows[0].quantity) < Number(item.quantity)) {
        throw new Error(
          `物料 ${item.material_name || item.material_id} 库存不足: 可用 ${invRows[0].quantity}, 需出 ${item.quantity}`
        );
      }
    }

    const [orderResult]: Loose = await conn.execute(
      'INSERT INTO inv_sales_outbound (outbound_no, order_id, order_no, customer_id, customer_name, warehouse_id, outbound_date, delivery_person, status, remark) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?)',
      [
        outboundNo,
        order_id || null,
        order_no || null,
        customer_id || null,
        customer_name || null,
        warehouse_id,
        outbound_date,
        delivery_person || null,
        remark || null,
      ]
    );
    const outboundId = orderResult.insertId;

    for (const item of items) {
      await conn.execute(
        'INSERT INTO inv_sales_outbound_item (outbound_id, material_id, material_code, material_name, quantity, unit, batch_no) VALUES (?, ?, ?, ?, ?, ?, ?)',
        [
          outboundId,
          item.material_id,
          item.material_code || null,
          item.material_name || null,
          item.quantity,
          item.unit || null,
          item.batch_no || null,
        ]
      );
    }

    return { id: outboundId, outbound_no: outboundNo };
  });

  return successResponse(result, '销售出库单创建成功');
});

export const PUT = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { id, action, status, remark } = body;

  if (!id) {
    return errorResponse('出库单ID不能为空', 400, 400);
  }

  if (action === 'post') {
    const result = await transaction(async (conn) => {
      const [outboundRows]: Loose = await conn.execute(
        'SELECT id, outbound_no, order_id, order_no, customer_id, customer_name, warehouse_id, status FROM inv_sales_outbound WHERE id = ? AND deleted = 0 FOR UPDATE',
        [id]
      );

      if (outboundRows.length === 0) {
        throw new Error('出库单不存在');
      }

      const outbound = outboundRows[0];

      if (outbound.status >= 3) {
        throw new Error('出库单已完成或已取消，不能重复过账');
      }

      const [itemRows]: Loose = await conn.execute(
        'SELECT * FROM inv_sales_outbound_item WHERE outbound_id = ?',
        [id]
      );

      for (const item of itemRows) {
        const [invRows]: Loose = await conn.execute(
          'SELECT id, quantity FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.material_id, outbound.warehouse_id]
        );

        if (invRows.length === 0) {
          throw new Error(`物料 ${item.material_name} 库存记录不存在`);
        }

        const inv = invRows[0];
        if (Number(inv.quantity) < Number(item.quantity)) {
          throw new Error(
            `物料 ${item.material_name} 库存不足: 可用 ${inv.quantity}, 需出 ${item.quantity}`
          );
        }

        await conn.execute(
          'UPDATE inv_inventory SET quantity = quantity - ?, update_time = NOW() WHERE id = ?',
          [item.quantity, inv.id]
        );

        const [batchRows]: Loose = await conn.execute(
          `SELECT id, batch_no, available_qty, unit_price, inbound_date
           FROM inv_inventory_batch
           WHERE material_id = ? AND warehouse_id = ? AND available_qty > 0 AND deleted = 0 AND status = 'normal'
           ORDER BY inbound_date ASC, id ASC
           FOR UPDATE`,
          [item.material_id, outbound.warehouse_id]
        );

        let remainingQty = Number(item.quantity);
        let totalCost = 0;
        const fifoRecommended = batchRows.length > 0 ? batchRows[0].batch_no : null;
        const usedBatch = item.batch_no || null;

        if (usedBatch && fifoRecommended && usedBatch !== fifoRecommended) {
          try {
            await conn.execute(
              `INSERT INTO inv_fifo_override_log (source_type, source_id, source_no, material_id, material_name, recommended_batch, actual_batch, reason, operator_name, approval_status)
               VALUES ('sales_outbound', ?, ?, ?, ?, ?, ?, '手动指定批次', ?, 0)`,
              [
                id,
                outbound.outbound_no,
                item.material_id,
                item.material_name || '',
                fifoRecommended,
                usedBatch,
                outbound.delivery_person || '',
              ]
            );
          } catch {}
        }

        for (const batch of batchRows) {
          if (remainingQty <= 0) break;
          const batchAvail = Number(batch.available_qty);
          const deductQty = Math.min(remainingQty, batchAvail);
          const batchCost = deductQty * Number(batch.unit_price || 0);

          await conn.execute(
            'UPDATE inv_inventory_batch SET available_qty = available_qty - ? WHERE id = ?',
            [deductQty, batch.id]
          );

          totalCost += batchCost;
          remainingQty -= deductQty;
        }

        const avgCost = Number(item.quantity) > 0 ? totalCost / Number(item.quantity) : 0;
        const transNo = 'TRX' + Date.now() + String(item.id).slice(-4);
        const [matRows]: Loose = await conn.execute(
          'SELECT material_code FROM mdm_material WHERE id = ?',
          [item.material_id]
        );
        const matCode = matRows.length > 0 ? matRows[0].material_code : '';

        await conn.execute(
          'INSERT INTO inv_inventory_transaction (trans_no, trans_type, source_type, source_id, material_id, material_code, batch_no, warehouse_id, quantity, unit_price, total_amount, account_dr, account_cr, create_time) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())',
          [
            transNo,
            'out',
            'sales_outbound',
            id,
            item.material_id,
            matCode,
            item.batch_no || '',
            outbound.warehouse_id,
            -item.quantity,
            avgCost,
            totalCost,
            '应收账款',
            '成品库存',
          ]
        );

        try {
          const voucherNo = 'FV' + Date.now() + String(item.id).slice(-4);
          await conn.execute(
            `INSERT INTO fin_voucher (voucher_no, voucher_date, source_type, source_id, source_no, debit_account, credit_account, amount, cost_price, quantity, batch_no, material_id, material_name, warehouse_id)
             VALUES (?, CURDATE(), 'sales_outbound', ?, ?, '应收账款', '成品库存', ?, ?, ?, ?, ?, ?, ?)`,
            [
              voucherNo,
              id,
              outbound.outbound_no,
              totalCost,
              avgCost,
              item.quantity,
              item.batch_no || '',
              item.material_id,
              item.material_name || '',
              outbound.warehouse_id,
            ]
          );
        } catch {}
      }

      await conn.execute(
        'UPDATE inv_sales_outbound SET status = 3, finance_posted = 1, update_time = NOW() WHERE id = ?',
        [id]
      );

      if (outbound.order_id) {
        const _totalOutQty = itemRows.reduce(
          (sum: number, item: Loose) => sum + Number(item.quantity || 0),
          0
        );

        const [soItemRows]: Loose = await conn.execute(
          'SELECT id, material_id, quantity, delivered_qty FROM sales_order_item WHERE order_id = ?',
          [outbound.order_id]
        );

        for (const soItem of soItemRows) {
          const matchedOutItems = itemRows.filter(
            (i: Loose) => i.material_id === soItem.material_id
          );
          const outQty = matchedOutItems.reduce(
            (sum: number, i: Loose) => sum + Number(i.quantity || 0),
            0
          );
          if (outQty > 0) {
            await conn.execute(
              'UPDATE sales_order_item SET delivered_qty = COALESCE(delivered_qty, 0) + ? WHERE id = ?',
              [outQty, soItem.id]
            );
          }
        }

        const [updatedSoItems]: Loose = await conn.execute(
          'SELECT quantity, COALESCE(delivered_qty, 0) as delivered_qty FROM sales_order_item WHERE order_id = ?',
          [outbound.order_id]
        );

        const allDelivered = updatedSoItems.every(
          (item: Loose) => Number(item.delivered_qty) >= Number(item.quantity)
        );
        const anyDelivered = updatedSoItems.some((item: Loose) => Number(item.delivered_qty) > 0);

        if (allDelivered) {
          await conn.execute('UPDATE sales_order SET status = 50 WHERE id = ? AND deleted = 0', [
            outbound.order_id,
          ]);
        } else if (anyDelivered) {
          await conn.execute(
            'UPDATE sales_order SET status = 40 WHERE id = ? AND status < 40 AND deleted = 0',
            [outbound.order_id]
          );
        }
      }

      return { id, status: 3 };
    });

    const qrCode = 'SH-' + randomUUID().replace(/-/g, '').substring(0, 16);
    const outboundInfo: Loose = await queryOne(
      'SELECT * FROM inv_sales_outbound WHERE id = ? AND deleted = 0',
      [id]
    );
    if (outboundInfo) {
      await execute(
        `INSERT INTO qrcode_record (qr_code, qr_type, ref_id, ref_no, customer_id, customer_name, warehouse_id, status, extra_data)
         VALUES (?, 'shipment', ?, ?, ?, ?, ?, 1, ?)`,
        [
          qrCode,
          id,
          outboundInfo.outbound_no,
          outboundInfo.customer_id || null,
          outboundInfo.customer_name || '',
          outboundInfo.warehouse_id || null,
          JSON.stringify({
            outbound_no: outboundInfo.outbound_no,
            order_no: outboundInfo.order_no,
          }),
        ]
      );
    }

    await logOperation({
      title: '销售出库过账',
      oper_type: '出库',
      oper_method: 'PUT',
      oper_url: '/api/warehouse/sales-outbound',
      oper_param: JSON.stringify({ id, action: 'post' }),
      oper_result: `出库单过账成功，已生成出货二维码 ${qrCode}`,
    });

    return successResponse(result, '出库过账成功');
  }

  if (status !== undefined)
    await execute('UPDATE inv_sales_outbound SET status = ? WHERE id = ? AND deleted = 0', [
      status,
      id,
    ]);
  if (remark !== undefined)
    await execute('UPDATE inv_sales_outbound SET remark = ? WHERE id = ? AND deleted = 0', [
      remark,
      id,
    ]);
  return successResponse(null, '更新成功');
});

export const DELETE = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');
  if (!id) return NextResponse.json({ success: false, message: '缺少id' }, { status: 400 });

  const outbound: Loose = await query(
    'SELECT status FROM inv_sales_outbound WHERE id = ? AND deleted = 0',
    [Number(id)]
  );
  if (outbound.length === 0) {
    return errorResponse('出库单不存在', 404, 404);
  }
  if (outbound[0].status >= 3) {
    return errorResponse('已完成的出库单不能删除', 400, 400);
  }

  await execute('UPDATE inv_sales_outbound SET deleted = 1 WHERE id = ?', [Number(id)]);
  return successResponse(null, '删除成功');
});

import { NextRequest } from 'next/server';
import { query, transaction, execute } from '@/lib/db';
import {
  successResponse,
  paginatedResponse,
  errorResponse,
  logOperation,
} from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { getEventBus } from '@/infrastructure/event-bus/EventBus';
import { SplitOrderAuditedEvent } from '@/domain/cutting/events/SplitOrderEvents';
import Decimal from 'decimal.js';

export const GET = withPermission(
  async (request: NextRequest) => {
    const { searchParams } = new URL(request.url);
    const keyword = searchParams.get('keyword') || '';
    const status = searchParams.get('status') || '';
    const startDate = searchParams.get('startDate') || '';
    const endDate = searchParams.get('endDate') || '';
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '10');

    let where = 'WHERE s.deleted = 0';
    const params: (string | number)[] = [];

    if (status) {
      where += ' AND s.status = ?';
      params.push(parseInt(status));
    }
    if (keyword) {
      where += ' AND (s.split_no LIKE ? OR m.material_name LIKE ? OR m.material_code LIKE ?)';
      const kw = `%${keyword}%`;
      params.push(kw, kw, kw);
    }
    if (startDate) {
      where += ' AND s.split_date >= ?';
      params.push(startDate);
    }
    if (endDate) {
      where += ' AND s.split_date <= ?';
      params.push(endDate);
    }

    const countResult = await query(
      `SELECT COUNT(*) as total FROM split_order s LEFT JOIN inv_material m ON s.material_id = m.id ${where}`,
      params
    );
    const total = (countResult as Loose[])[0]?.total || 0;

    const offset = (page - 1) * pageSize;
    const rows = await query(
      `SELECT s.*, m.material_code, m.specification,
        (SELECT COUNT(*) FROM split_order_detail WHERE split_id = s.id) as detail_count
      FROM split_order s
      LEFT JOIN inv_material m ON s.material_id = m.id
      ${where}
      ORDER BY s.create_time DESC
      LIMIT ? OFFSET ?`,
      [...params, pageSize, offset]
    );

    const totalPages = Math.ceil(total / pageSize);
    return paginatedResponse(rows || [], { page, pageSize, total, totalPages });
  },
  { errorMessage: '获取分切单列表失败' }
);

export const POST = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();
    const { parentBatchId, warehouseId, remark, details, operatorId, operatorName } = body;

    if (!parentBatchId || !details || !Array.isArray(details) || details.length === 0) {
      return errorResponse('母料批次和分切明细不能为空', 400, 400);
    }

    return await transaction(async (conn) => {
      const [parentBatch]: Loose = await conn.query(
        `SELECT id, batch_no, material_id, material_name, available_qty, quantity, unit_price, width, length, unit
         FROM inv_inventory_batch WHERE id = ? AND deleted = 0 FOR UPDATE`,
        [parentBatchId]
      );

      if (!parentBatch || parentBatch.length === 0) {
        throw new Error('母料批次不存在');
      }

      const batch = parentBatch[0];
      const availableQty = parseFloat(batch.available_qty);
      let totalOutQty = new Decimal(0);
      let totalWasteQty = new Decimal(0);

      for (const d of details) {
        const qty = new Decimal(d.totalQty || 0);
        if (d.isWaste) {
          totalWasteQty = totalWasteQty.plus(qty);
        } else {
          totalOutQty = totalOutQty.plus(qty);
        }
      }

      const totalQty = totalOutQty.plus(totalWasteQty);

      if (totalQty.greaterThan(availableQty)) {
        throw new Error(`分切总数(${totalQty.toNumber()})超过母料可用量(${availableQty})`);
      }

      const date = new Date();
      const dateStr = date.toISOString().slice(0, 10).replace(/-/g, '');
      const [maxOrder]: Loose = await conn.query(
        `SELECT MAX(split_no) as maxNo FROM split_order WHERE split_no LIKE ?`,
        [`FJ${dateStr}%`]
      );
      const maxNo = (maxOrder as Loose[])[0]?.maxNo;
      const seq = maxNo ? String(parseInt(maxNo.slice(-4)) + 1).padStart(4, '0') : '0001';
      const splitNo = `FJ${dateStr}${seq}`;

      const [orderResult]: Loose = await conn.execute(
        `INSERT INTO split_order (
          split_no, split_date, parent_batch_id, material_id, material_name,
          warehouse_id, out_qty, total_waste, status, remark,
          operator_id, operator_name, create_by
        ) VALUES (?, CURDATE(), ?, ?, ?, ?, ?, ?, 0, ?, ?, ?, ?)`,
        [
          splitNo,
          parentBatchId,
          batch.material_id,
          batch.material_name,
          warehouseId,
          totalOutQty.toNumber(),
          totalWasteQty.toNumber(),
          remark || '',
          operatorId || null,
          operatorName || '',
          operatorId || null,
        ]
      );

      const splitId = (orderResult as { insertId: number }).insertId;

      for (const d of details) {
        await conn.execute(
          `INSERT INTO split_order_detail (
            split_id, pieces, qty_per_piece, total_qty, width, is_waste, remark
          ) VALUES (?, ?, ?, ?, ?, ?, ?)`,
          [
            splitId,
            d.pieces || 1,
            d.qtyPerPiece || 0,
            d.totalQty || 0,
            d.width || 0,
            d.isWaste ? 1 : 0,
            d.remark || '',
          ]
        );
      }

      await logOperation({
        title: '创建分切单',
        oper_name: operatorName,
        oper_type: 'warehouse',
        oper_method: 'POST',
        oper_url: '/api/warehouse/split-order',
        oper_param: JSON.stringify({ parentBatchId, splitNo, totalQty: totalQty.toNumber() }),
        oper_result: `分切单 ${splitNo} 创建成功`,
        status: 1,
      });

      return successResponse({ splitId, splitNo }, '分切单创建成功');
    });
  },
  { errorMessage: '创建分切单失败' }
);

export const PATCH = withPermission(
  async (request: NextRequest) => {
    const body = await request.json();
    const { splitId, action, operatorId, operatorName } = body;

    if (!splitId) {
      return errorResponse('splitId不能为空', 400, 400);
    }

    return await transaction(async (conn) => {
      const [orders]: Loose = await conn.query(
        `SELECT s.*, ib.available_qty, ib.quantity, ib.unit_price, ib.unit, ib.width, ib.length,
          ib.material_id, ib.material_name, ib.warehouse_id, ib.batch_type,
          m.material_code, m.width as m_width
        FROM split_order s
        JOIN inv_inventory_batch ib ON s.parent_batch_id = ib.id
        LEFT JOIN inv_material m ON s.material_id = m.id
        WHERE s.id = ? AND s.deleted = 0 FOR UPDATE`,
        [splitId]
      );

      if (!orders || orders.length === 0) {
        throw new Error('分切单不存在');
      }

      const order = orders[0];

      if (action === 'audit') {
        if (order.status !== 0) {
          throw new Error('分切单状态不正确，只能审核草稿状态的分切单');
        }

        const [details]: Loose = await conn.query(
          `SELECT * FROM split_order_detail WHERE split_id = ?`,
          [splitId]
        );

        if (!details || details.length === 0) {
          throw new Error('分切单没有明细');
        }

        const parentAvailableQty = parseFloat(order.available_qty);
        let totalOutQty = new Decimal(0);
        let totalWasteQty = new Decimal(0);

        for (const d of details) {
          const qty = new Decimal(d.total_qty);
          if (d.is_waste) {
            totalWasteQty = totalWasteQty.plus(qty);
          } else {
            totalOutQty = totalOutQty.plus(qty);
          }
        }

        const totalQty = totalOutQty.plus(totalWasteQty);

        if (totalQty.greaterThan(new Decimal(parentAvailableQty))) {
          throw new Error(
            `分切总数(${totalQty.toNumber()})超过母料可用量(${parentAvailableQty}), 请调整明细`
          );
        }

        const totalCostDecimal = new Decimal(order.out_qty || 0).times(order.unit_price || 0);
        const childBatchIds: number[] = [];
        const parentBatchId = order.parent_batch_id;
        const warehouseId = order.warehouse_id;

        for (const d of details) {
          if (d.is_waste) continue;

          const childWidth = parseFloat(d.width) || parseFloat(order.m_width || order.width) || 0;

          const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
          const [maxChildBatch]: Loose = await conn.query(
            `SELECT MAX(batch_no) as maxNo FROM inv_inventory_batch WHERE batch_no LIKE ?`,
            [`SC${dateStr}%`]
          );
          const maxChildNo = (maxChildBatch as Loose[])[0]?.maxNo;
          const childSeq = maxChildNo
            ? String(parseInt(maxChildNo.slice(-4)) + 1).padStart(4, '0')
            : '0001';
          const childBatchNo = `SC${dateStr}${childSeq}`;

          const pieceCost = totalCostDecimal.times(new Decimal(d.total_qty)).div(totalOutQty);

          const [batchResult]: Loose = await conn.execute(
            `INSERT INTO inv_inventory_batch (
              batch_no, material_id, material_code, material_name,
              warehouse_id, quantity, available_qty, locked_qty,
              unit, unit_price, width, batch_type, parent_batch_id,
              inbound_date, produce_date, status, create_by
            ) VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, ?, ?, 1, ?, CURDATE(), CURDATE(), 1, ?)`,
            [
              childBatchNo,
              order.material_id,
              order.material_code || '',
              order.material_name,
              warehouseId,
              d.total_qty,
              d.total_qty,
              order.unit || '米',
              pieceCost.toNumber(),
              childWidth,
              parentBatchId,
              operatorId || null,
            ]
          );

          const childBatchId = (batchResult as { insertId: number }).insertId;
          childBatchIds.push(childBatchId);

          await conn.execute(
            `UPDATE split_order_detail SET child_batch_id = ?, child_batch_no = ?, allocated_cost = ? WHERE id = ?`,
            [childBatchId, childBatchNo, pieceCost.toNumber(), d.id]
          );
        }

        const parentCost = new Decimal(order.out_qty || 0).times(order.unit_price || 0);

        await conn.execute(
          `UPDATE inv_inventory_batch SET
            quantity = quantity - ?,
            available_qty = available_qty - ?,
            version = version + 1,
            update_time = NOW()
          WHERE id = ? AND version = ?`,
          [totalQty.toNumber(), totalQty.toNumber(), parentBatchId, order.version]
        );

        await conn.execute(
          `INSERT INTO inv_inventory_log (material_id, warehouse_id, batch_no, operation_type,
            operation_qty, before_qty, after_qty, business_type, business_no, remark, operator_id, create_time)
          SELECT ?, ?, ?, 2, ?, ?, ?, 'split_order', ?, ?, ?, NOW()`,
          [
            order.material_id,
            warehouseId,
            order.batch_no || '',
            totalQty.toNumber(),
            parentAvailableQty,
            parentAvailableQty - totalQty.toNumber(),
            order.split_no,
            `分切出库-${order.split_no}`,
            operatorId,
          ]
        );

        if (totalWasteQty.greaterThan(0)) {
          const wasteCost = totalCostDecimal.times(totalWasteQty).div(totalQty);
          await conn.execute(
            `INSERT INTO inv_inventory_log (material_id, warehouse_id, batch_no, operation_type,
              operation_qty, before_qty, after_qty, business_type, business_no, remark, operator_id, create_time)
            VALUES (?, ?, ?, 3, ?, 0, ?, 'split_order', ?, ?, ?, NOW())`,
            [
              order.material_id,
              warehouseId,
              order.batch_no || '',
              totalWasteQty.toNumber(),
              totalWasteQty.negated().toNumber(),
              order.split_no,
              `分切损耗-${order.split_no}(${totalWasteQty.toNumber()})`,
              operatorId,
            ]
          );
        }

        for (const d of details) {
          if (d.is_waste) continue;
          await conn.execute(
            `INSERT INTO inv_inventory_log (material_id, warehouse_id, batch_no, operation_type,
              operation_qty, before_qty, after_qty, business_type, business_no, remark, operator_id, create_time)
            VALUES (?, ?, ?, 1, ?, 0, ?, 'split_order', ?, ?, ?, NOW())`,
            [
              order.material_id,
              warehouseId,
              d.child_batch_no || '',
              d.total_qty,
              d.total_qty,
              order.split_no,
              `分切入库-${order.split_no}`,
              operatorId,
            ]
          );
        }

        const now = new Date();
        await conn.execute(
          `UPDATE split_order SET status = 1, total_cost = ?,
            audit_time = ?, auditor_id = ?, auditor_name = ?,
            version = version + 1, update_time = NOW()
          WHERE id = ? AND version = ?`,
          [totalCostDecimal.toNumber(), now, operatorId, operatorName || '', splitId, order.version]
        );

        const eventBus = getEventBus();
        await eventBus.publish(
          new SplitOrderAuditedEvent({
            splitId,
            splitNo: order.split_no,
            parentBatchId,
            materialId: order.material_id,
            warehouseId,
            childBatchIds,
            totalCost: totalCostDecimal.toNumber(),
            auditorId: operatorId,
            auditorName: operatorName || '',
          })
        );

        await logOperation({
          title: '审核分切单',
          oper_name: operatorName,
          oper_type: 'warehouse',
          oper_method: 'PATCH',
          oper_url: '/api/warehouse/split-order',
          oper_param: JSON.stringify({ splitId, action: 'audit' }),
          oper_result: `分切单 ${order.split_no} 审核通过`,
          status: 1,
        });

        return successResponse(
          {
            splitId,
            splitNo: order.split_no,
            status: 1,
            childBatchIds,
            childCount: childBatchIds.length,
            totalCost: totalCostDecimal.toNumber(),
            wasteQty: totalWasteQty.toNumber(),
          },
          '分切单审核通过，库存已更新'
        );
      }

      if (action === 'void') {
        if (order.status !== 0) {
          throw new Error('只能作废草稿状态的分切单');
        }

        await conn.execute(
          `UPDATE split_order SET status = 3, version = version + 1, update_time = NOW() WHERE id = ? AND version = ?`,
          [splitId, order.version]
        );

        return successResponse(null, '分切单已作废');
      }

      throw new Error(`不支持的操作: ${action}`);
    });
  },
  { errorMessage: '操作分切单失败' }
);

﻿import { NextRequest, NextResponse } from 'next/server';
import { query, execute } from '@/lib/db';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { secureLog } from '@/lib/logger';

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const adjustNo = searchParams.get('adjustNo') || '';
  const adjustType = searchParams.get('adjustType') || '';

  let where = 'WHERE a.deleted = 0';
  const params: Loose[] = [];
  if (adjustNo) {
    where += ' AND a.adjust_no LIKE ?';
    params.push('%' + adjustNo + '%');
  }
  if (adjustType) {
    where += ' AND a.adjust_type = ?';
    params.push(Number(adjustType));
  }

  const totalRows: Loose = await query(
    'SELECT COUNT(*) as total FROM inv_stock_adjust a ' + where,
    params
  );
  const total = totalRows[0]?.total || 0;
  const rows: Loose = await query(
    'SELECT a.*, w.warehouse_name FROM inv_stock_adjust a LEFT JOIN inv_warehouse w ON a.warehouse_id = w.id ' +
      where +
      ' ORDER BY a.create_time DESC LIMIT ? OFFSET ?',
    [...params, pageSize, (page - 1) * pageSize]
  );
  return successResponse({ list: rows, total, page, pageSize });
});

export const POST = withPermission(async (request: NextRequest, _userInfo) => {
  const body = await request.json();
  const { warehouse_id, adjust_date, adjust_type, operator_name, remark, items } = body;
  const now = new Date();
  const adjustNo =
    'TZ' +
    now.getFullYear() +
    String(now.getMonth() + 1).padStart(2, '0') +
    String(now.getDate()).padStart(2, '0') +
    String(Math.floor(Math.random() * 10000)).padStart(4, '0');

  const result: Loose = await execute(
    'INSERT INTO inv_stock_adjust (adjust_no, warehouse_id, adjust_date, adjust_type, operator_name, remark) VALUES (?, ?, ?, ?, ?, ?)',
    [adjustNo, warehouse_id, adjust_date, adjust_type || 1, operator_name || null, remark || null]
  );

  if (items && Array.isArray(items)) {
    for (const item of items) {
      await execute(
        'INSERT INTO inv_stock_adjust_item (adjust_id, material_id, material_code, material_name, before_qty, adjust_qty, after_qty, unit, batch_no) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
        [
          result.insertId,
          item.material_id,
          item.material_code || null,
          item.material_name || null,
          item.before_qty || 0,
          item.adjust_qty || 0,
          item.after_qty || 0,
          item.unit || null,
          item.batch_no || null,
        ]
      );
    }
  }
  return successResponse({ id: result.insertId, adjust_no: adjustNo }, '调整单创建成功');
});

export const PUT = withPermission(async (request: NextRequest, _userInfo) => {
  const body = await request.json();
  const { id, status, remark, expectedStatus } = body;

  // 状态变更采用乐观锁：前端传入 expectedStatus（当前状态），UPDATE 带 status 条件
  // 防止多人同时审批同一调整单导致重复扣减库存
  if (status !== undefined) {
    if (expectedStatus === undefined) {
      return errorResponse('缺少 expectedStatus 参数（当前状态）', 400, 400);
    }

    secureLog('debug', 'stock-adjust 状态变更（乐观锁）', {
      operation: 'updateStockAdjustStatus',
      id,
      targetStatus: status,
      expectedStatus,
    });

    const result: Loose = await execute(
      'UPDATE inv_stock_adjust SET status = ?, update_time = NOW() WHERE id = ? AND deleted = 0 AND status = ?',
      [status, id, expectedStatus]
    );

    secureLog('debug', 'stock-adjust UPDATE 结果', {
      operation: 'updateStockAdjustStatus',
      id,
      affectedRows: result.affectedRows,
      expectedStatus,
      targetStatus: status,
    });

    if (result.affectedRows === 0) {
      secureLog('warn', '乐观锁并发冲突', {
        operation: 'updateStockAdjustStatus',
        id,
        expectedStatus,
        targetStatus: status,
      });
      return errorResponse('并发冲突: 调整单状态已被其他操作变更，请刷新后重试', 409, 409);
    }
  }

  if (remark !== undefined)
    await execute('UPDATE inv_stock_adjust SET remark = ? WHERE id = ? AND deleted = 0', [
      remark,
      id,
    ]);
  return successResponse(null, '更新成功');
});

export const DELETE = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');
  if (!id) return NextResponse.json({ success: false, message: '缺少id' }, { status: 400 });
  await execute('UPDATE inv_stock_adjust SET deleted = 1 WHERE id = ?', [Number(id)]);
  return successResponse(null, '删除成功');
});

import { NextRequest } from 'next/server';
import { query, queryOne } from '@/lib/db';
import { successResponse, commonErrors } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { SPLIT_FLAG_LABEL, STOCKTAKING_ITEM_STATUS_LABEL } from '@/lib/status-labels';

const SPLIT_FLAG_MAP = SPLIT_FLAG_LABEL;
const STATUS_MAP = STOCKTAKING_ITEM_STATUS_LABEL;

export const GET = withPermission(
  async (request: NextRequest, userInfo, { params }: { params: Promise<{ id: string }> }) => {
    const resolvedParams = await params;
    const checkId = parseInt(resolvedParams.id);

    const check: Loose = await queryOne(
      `SELECT * FROM inventory_checks WHERE id = ? AND deleted = 0`,
      [checkId]
    );

    if (!check) {
      return commonErrors.notFound('盘点单不存在');
    }

    const items: Loose[] = await query(
      `SELECT ici.*,
            m.material_name,
            m.unit
     FROM inventory_check_items ici
     LEFT JOIN bas_material m ON ici.material_id = m.id
     WHERE ici.check_id = ?
     ORDER BY ici.id`,
      [checkId]
    );

    return successResponse(
      items.map((item: Loose) => ({
        ...item,
        split_flag_name: SPLIT_FLAG_MAP[item.split_flag] || '未知',
