  }
);

import { NextRequest } from 'next/server';
import { execute, queryOne } from '@/lib/db';
import { successResponse, errorResponse, commonErrors } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { SPLIT_FLAG_LABEL, STOCKTAKING_STATUS_LABEL } from '@/lib/status-labels';

const SPLIT_FLAG_MAP = SPLIT_FLAG_LABEL;

export const POST = withPermission(
  async (request: NextRequest, userInfo, { params }: { params: Promise<{ id: string }> }) => {
    const resolvedParams = await params;
    const checkId = parseInt(resolvedParams.id);
    const body = await request.json();
    const { qr_code, actual_quantity } = body;

    if (!qr_code) {
      return errorResponse('请扫描二维码', 400, 400);
    }

    if (actual_quantity === undefined || actual_quantity === null) {
      return errorResponse('请输入实际数量', 400, 400);
    }

    const check: Loose = await queryOne(
      `SELECT * FROM inventory_checks WHERE id = ? AND deleted = 0`,
      [checkId]
    );

    if (!check) {
      return commonErrors.notFound('盘点单不存在');
    }

    if (check.status !== 1) {
      return errorResponse(`当前状态为"${STOCKTAKING_STATUS_LABEL[check.status]}"，不能执行盘点操作`, 400, 400);
    }

    // 库存记录直接取自 qrcode_record（其本身携带 material_name/batch_no/location 等字段），
    // 不再依赖遗留幽灵表 wh_inventory（权威 schema 中已无建表定义）。
    const inventoryItem: Loose = await queryOne(
      `SELECT qr_code, material_name, batch_no, location AS warehouse_location
     FROM qrcode_record
     WHERE qr_code = ? AND deleted = 0`,
      [qr_code]
    );

    if (!inventoryItem) {
      return errorResponse('未找到对应的库存记录', 404, 404);
    }

    const checkItem: Loose = await queryOne(
      `SELECT * FROM inventory_check_items
     WHERE check_id = ? AND qr_code = ?`,
      [checkId, qr_code]
    );

    if (!checkItem) {
      return errorResponse('该物料不在本次盘点范围内', 400, 400);
    }

    const difference = actual_quantity - checkItem.book_quantity;

    let split_flag = 0;
    let parent_qr_code = null;

    const splitInfo: Loose = await queryOne(
      `SELECT * FROM material_splits WHERE child_qr_code = ?`,
      [qr_code]
    );

    if (splitInfo) {
      split_flag = 1;
      parent_qr_code = splitInfo.parent_qr_code;
    }

    await execute(
      `UPDATE inventory_check_items
     SET actual_quantity = ?,
         difference = ?,
         status = 1,
         updated_at = NOW()
     WHERE id = ?`,
      [actual_quantity, difference, checkItem.id]
    );

    const stats: Loose = await queryOne(
      `SELECT
      COUNT(CASE WHEN status = 1 THEN 1 END) as checked_count,
      COUNT(*) as total_count
     FROM inventory_check_items
     WHERE check_id = ?`,
      [checkId]
    );

    return successResponse(
      {
        material_name: inventoryItem.material_name,
        batch_no: inventoryItem.batch_no,
        split_flag: SPLIT_FLAG_MAP[split_flag] || '整料',
        parent_qr_code: parent_qr_code,
        warehouse_location: inventoryItem.warehouse_location,
        book_quantity: checkItem.book_quantity,
        actual_quantity: actual_quantity,
        difference: difference,
        progress: Math.round((stats.checked_count / stats.total_count) * 100),
      },
      '扫码盘点成功'
    );
  }
);

import { NextRequest } from 'next/server';
import { query, queryOne } from '@/lib/db';
import { successResponse, errorResponse, commonErrors } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';

export const GET = withPermission(
  async (request: NextRequest, userInfo, { params }: { params: Promise<{ id: string }> }) => {
    const resolvedParams = await params;
    const checkId = parseInt(resolvedParams.id);
    const { searchParams } = new URL(request.url);
    const parentQrCode = searchParams.get('parent_qr_code');

    if (!parentQrCode) {
      return errorResponse('缺少父二维码参数', 400, 400);
    }

    const check: Loose = await queryOne(
      `SELECT * FROM inventory_checks WHERE id = ? AND deleted = 0`,
      [checkId]
    );

    if (!check) {
      return commonErrors.notFound('盘点单不存在');
    }

    const parentItem: Loose[] = await query(
      `SELECT ici.*,
            m.material_name,
            m.unit
     FROM inventory_check_items ici
     LEFT JOIN bas_material m ON ici.material_id = m.id
     WHERE ici.check_id = ?
       AND ici.qr_code = ?`,
      [checkId, parentQrCode]
    );

    if (parentItem.length === 0) {
      return errorResponse('未找到整料盘点记录', 404, 404);
    }

    const smallItems: Loose[] = await query(
      `SELECT ici.*
     FROM inventory_check_items ici
     WHERE ici.check_id = ?
       AND ici.parent_qr_code = ?
       AND ici.split_flag = 1
     ORDER BY ici.id`,
      [checkId, parentQrCode]
    );

    let totalSmallBookQty = 0;
    let totalSmallActualQty = 0;

    for (const item of smallItems) {
      totalSmallBookQty += item.book_quantity || 0;
      totalSmallActualQty += item.actual_quantity || 0;
    }

    return successResponse({
      parent_qr_code: parentQrCode,
      material_name: parentItem[0].material_name,
      batch_no: parentItem[0].batch_no,
      unit: parentItem[0].unit,
      whole_material_book_qty: parentItem[0].book_quantity,
      whole_material_actual_qty: parentItem[0].actual_quantity,
      split_small_qty: smallItems.length,
      total_small_book_qty: totalSmallBookQty,
      total_small_actual_qty: totalSmallActualQty,
      difference:
        (parentItem[0].actual_quantity || 0) +
        totalSmallActualQty -
        (parentItem[0].book_quantity || 0) -
        totalSmallBookQty,
      small_materials: smallItems.map((item) => ({
        qr_code: item.qr_code,
        batch_no: item.batch_no,
        book_quantity: item.book_quantity,
        actual_quantity: item.actual_quantity,
        difference: item.difference,
        status: item.status,
      })),
    });
  }
);

import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';
import { query, execute } from '@/lib/db';

/**
 * 盘点差异处理 API
 *
 * 盘点单审核后，差异需要经过审批才能调整库存
 * 流程：盘点完成 → 差异确认 → 差异审批 → 库存调整
 */

// 获取待处理的盘点差异
export const GET = withPermission(async (request: NextRequest, _userInfo: UserInfo) => {
  const { searchParams } = new URL(request.url);
  const type = searchParams.get('type') || 'pending';
  const page = parseInt(searchParams.get('page') || '1');
  const pageSize = parseInt(searchParams.get('pageSize') || '20');

  let where = 'WHERE si.difference != 0';
  const params: Loose[] = [];

  if (type === 'pending') {
    where += ' AND si.diff_status = ?';
    params.push('pending');
  } else if (type === 'approved') {
    where += ' AND si.diff_status = ?';
    params.push('approved');
  } else if (type === 'processed') {
    where += ' AND si.diff_status = ?';
    params.push('processed');
  }

  const countRows: Loose = await query(
    `SELECT COUNT(*) as total FROM inv_stocktaking_item si ${where}`,
    params
  );
  const total = countRows[0]?.total || 0;

  const rows: Loose = await query(
    `SELECT si.*, m.material_name, m.material_code, m.unit,
              s.taking_no, s.warehouse_id, w.warehouse_name,
              u1.real_name as checker_name,
              u2.real_name as approver_name
       FROM inv_stocktaking_item si
       LEFT JOIN materials m ON si.material_id = m.id
       LEFT JOIN inv_stocktaking s ON si.check_id = s.id
       LEFT JOIN warehouses w ON s.warehouse_id = w.id
       LEFT JOIN sys_user u1 ON si.check_by = u1.id
       LEFT JOIN sys_user u2 ON si.diff_approver = u2.id
       ${where}
       ORDER BY si.diff_status ASC, ABS(si.difference) DESC
       LIMIT ? OFFSET ?`,
    [...params, pageSize, (page - 1) * pageSize]
  );

  // 统计
  const summary: Loose = await query(
    `SELECT 
         COUNT(CASE WHEN diff_status = 'pending' THEN 1 END) as pending_count,
         COUNT(CASE WHEN diff_status = 'approved' THEN 1 END) as approved_count,
         COUNT(CASE WHEN diff_status = 'processed' THEN 1 END) as processed_count,
         SUM(CASE WHEN diff_status = 'pending' AND difference > 0 THEN difference ELSE 0 END) as pending_gain,
         SUM(CASE WHEN diff_status = 'pending' AND difference < 0 THEN ABS(difference) ELSE 0 END) as pending_loss
       FROM inv_stocktaking_item
       WHERE difference != 0`
  );

  return successResponse({
    list: rows,
    total,
    page,
    pageSize,
    summary: summary[0] || {},
  });
});

// 差异审批/处理
export const POST = withPermission(
  async (request: NextRequest, userInfo: UserInfo) => {
    const body = await request.json();
    const { action } = body;

    if (action === 'approve') {
      // 审批差异
      const { item_ids, reason } = body;
      if (!item_ids || !Array.isArray(item_ids) || item_ids.length === 0) {
        return errorResponse('请选择需要审批的差异项', 400, 400);
      }

      for (const itemId of item_ids) {
        const item: Loose = await query(
          'SELECT * FROM inv_stocktaking_item WHERE id = ? AND diff_status = ?',
          [itemId, 'pending']
        );

        if (item.length === 0) continue;

        await execute(
          `UPDATE inv_stocktaking_item 
           SET diff_status = 'approved', diff_approver = ?, diff_approve_time = NOW(),
               diff_reason = COALESCE(?, diff_reason), update_time = NOW()
           WHERE id = ?`,
          [userInfo.userId, reason || null, itemId]
        );
      }

      return successResponse(null, `已审批 ${item_ids.length} 项差异`);
    }

    if (action === 'process') {
      // 处理已审批的差异（调整库存）
      const { item_ids } = body;
      if (!item_ids || !Array.isArray(item_ids) || item_ids.length === 0) {
        return errorResponse('请选择需要处理的差异项', 400, 400);
      }

      let processedCount = 0;

      for (const itemId of item_ids) {
        const items: Loose = await query(
          `SELECT si.*, s.warehouse_id FROM inv_stocktaking_item si
           LEFT JOIN inv_stocktaking s ON si.check_id = s.id
           WHERE si.id = ? AND si.diff_status = 'approved'`,
          [itemId]
        );

        if (items.length === 0) continue;

        const item = items[0];
        const difference = Number(item.difference);

        // 调整库存
        if (difference > 0) {
          // 盘盈：增加库存
          await execute(
            `UPDATE stock SET quantity = quantity + ?, update_time = NOW() 
             WHERE material_id = ? AND warehouse_id = ?`,
            [difference, item.material_id, item.warehouse_id]
          );
        } else {
          // 盘亏：减少库存
          await execute(
            `UPDATE stock SET quantity = GREATEST(quantity + ?, 0), update_time = NOW() 
             WHERE material_id = ? AND warehouse_id = ?`,
            [difference, item.material_id, item.warehouse_id]
          );
        }

        // 记录库存变动
        await execute(
          `INSERT INTO stock_movement (material_id, warehouse_id, movement_type, quantity, unit_price, source_type, source_no, operator_id, create_time)
           VALUES (?, ?, ?, ?, 0, 'stocktaking', ?, ?, NOW())`,
          [
            item.material_id,
            item.warehouse_id,
            difference > 0 ? 'stock_gain' : 'stock_loss',
            Math.abs(difference),
            item.taking_no || '',
            userInfo.userId,
          ]
        );

        // 更新差异状态
        await execute(
          `UPDATE inv_stocktaking_item SET diff_status = 'processed', process_time = NOW(), update_time = NOW() WHERE id = ?`,
          [itemId]
        );

        processedCount++;
      }

      return successResponse({ processedCount }, `已处理 ${processedCount} 项差异`);
    }

    if (action === 'reject') {
      // 驳回差异
      const { item_ids, reason } = body;
      if (!item_ids || !Array.isArray(item_ids)) {
        return errorResponse('请选择需要驳回的差异项', 400, 400);
      }

      for (const itemId of item_ids) {
        await execute(
          `UPDATE inv_stocktaking_item 
           SET diff_status = 'rejected', diff_reason = ?, update_time = NOW()
           WHERE id = ? AND diff_status = 'pending'`,
          [reason || '驳回', itemId]
        );
      }

      return successResponse(null, `已驳回 ${item_ids.length} 项差异`);
    }

    return errorResponse('无效的操作类型', 400, 400);
  },
  { errorMessage: '操作失败' }
);

﻿import { NextRequest } from 'next/server';
import { query, execute, queryOne, transaction } from '@/lib/db';
import { successResponse, errorResponse, commonErrors } from '@/lib/api-response';
import { getIcPrefix, generateDocNo, getConfig } from '@/lib/global-config';

import { withPermission } from '@/lib/api-permissions';
import { STOCKTAKING_TYPE_LABEL, STOCKTAKING_STATUS_LABEL } from '@/lib/status-labels';

const TYPE_MAP = STOCKTAKING_TYPE_LABEL;
const STATUS_MAP = STOCKTAKING_STATUS_LABEL;

function generateCheckNo(): string {
  return generateDocNo(getIcPrefix());
}

export const GET = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const checkNo = searchParams.get('checkNo') || '';
  const status = searchParams.get('status') !== '' ? Number(searchParams.get('status')) : undefined;
  const type = searchParams.get('type') !== '' ? Number(searchParams.get('type')) : undefined;

  let where = 'WHERE s.deleted = 0';
  const params: Loose[] = [];

  if (checkNo) {
    where += ' AND s.taking_no LIKE ?';
    params.push(`%${checkNo}%`);
  }
  if (status !== undefined) {
    where += ' AND s.status = ?';
    params.push(status);
  }
  if (type !== undefined) {
    where += ' AND s.taking_type = ?';
    params.push(type);
  }

  const totalRows: Loose = await query(
    `SELECT COUNT(*) as total FROM inv_stocktaking s ${where}`,
    params
  );
  const total = totalRows[0]?.total || 0;

  const rows: Loose[] = await query(
    `SELECT s.*, w.warehouse_name,
            u1.real_name as checker_name,
            u2.real_name as approver_name
     FROM inv_stocktaking s
     LEFT JOIN inv_warehouse w ON s.warehouse_id = w.id
     LEFT JOIN sys_user u1 ON s.operator_id = u1.id
     LEFT JOIN sys_user u2 ON s.create_by = u2.id
     ${where}
     ORDER BY s.create_time DESC
     LIMIT ? OFFSET ?`,
    [...params, pageSize, (page - 1) * pageSize]
  );

  return successResponse({
    list: rows.map((row: Loose) => ({
      ...row,
      check_no: row.taking_no,
      type_name: TYPE_MAP[row.taking_type] || '未知',
      status_name: STATUS_MAP[row.status] || '未知',
    })),
    total,
    page,
    pageSize,
  });
});

export const POST = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { type = 1, warehouse_id, checker_id, remark } = body;

  if (!warehouse_id) {
    return errorResponse('SELECT_WAREHOUSE', 400, 400);
  }

  if (![1, 2, 3, 4].includes(type)) {
    return errorResponse('INVALID_STOCKTAKING_TYPE', 400, 400);
  }

  const _now = new Date();
  const checkNo = generateCheckNo();

  const result: Loose = await execute(
    `INSERT INTO inv_stocktaking (
      taking_no, taking_type, warehouse_id, status,
      taking_date, operator_id, remark, create_time, update_time
    ) VALUES (?, ?, ?, 1, NOW(), ?, ?, NOW(), NOW())`,
    [checkNo, type, warehouse_id, checker_id || null, remark || null]
  );

  const checkId = result.insertId;

  await execute(`UPDATE inv_inventory SET stocktaking_flag = 1 WHERE warehouse_id = ?`, [
    warehouse_id,
  ]);

  const inventoryItems: Loose[] = await query(
    `SELECT
      i.id as inventory_id,
      i.material_id,
      i.batch_no,
      i.quantity as system_qty,
      m.material_name,
      m.unit
    FROM inv_inventory i
    LEFT JOIN bas_material m ON i.material_id = m.id
    WHERE i.warehouse_id = ?
      AND i.quantity > 0
      AND i.deleted = 0`,
    [warehouse_id]
  );

  for (const item of inventoryItems) {
    await execute(
      `INSERT INTO inv_stocktaking_item (
        taking_id, material_id, material_code, material_name,
        system_qty, actual_qty, diff_qty, unit, batch_no
      ) VALUES (?, ?, ?, ?, ?, 0, 0, ?, ?)`,
      [
        checkId,
        item.material_id,
        item.material_code || null,
        item.material_name,
        item.system_qty,
        item.unit,
        item.batch_no || null,
      ]
    );
  }

  await execute(`UPDATE inv_stocktaking SET total_items = ? WHERE id = ?`, [
    inventoryItems.length,
    checkId,
  ]);

  return successResponse(
    {
      id: checkId,
      check_no: checkNo,
      status: 1,
      item_count: inventoryItems.length,
      locked: true,
    },
    '盘点单生成成功，库存已锁定'
  );
});

export const PUT = withPermission(async (request: NextRequest) => {
  const body = await request.json();
  const { id, action, approver_id, items } = body;

  const check: Loose = await queryOne(
    `SELECT * FROM inv_stocktaking WHERE id = ? AND deleted = 0`,
    [id]
  );

  if (!check) {
    return commonErrors.notFound('盘点单不存在');
  }

  switch (action) {
    case 'submit':
      if (check.status !== 1) {
        return errorResponse('ONLY_IN_PROGRESS_CAN_SUBMIT', 400, 400);
      }

      const uncheckedCount: Loose = await queryOne(
        `SELECT COUNT(*) as count FROM inv_stocktaking_item
         WHERE taking_id = ? AND actual_qty = 0`,
        [id]
      );

      if (uncheckedCount.count > 0) {
        return errorResponse(`盘点项目未完成，还有 ${uncheckedCount.count} 项未盘点`, 400, 400);
      }

      const _diffStats: Loose = await queryOne(
        `SELECT
          COUNT(*) as diff_items,
          COALESCE(SUM(ABS(diff_qty)), 0) as diff_amount
         FROM inv_stocktaking_item
         WHERE taking_id = ? AND diff_qty != 0`,
        [id]
      );

      await execute(
        `UPDATE inv_stocktaking
         SET status = 2,
             update_time = NOW()
         WHERE id = ?`,
        [id]
      );

      return successResponse(null, 'STOCKTAKING_SUBMITTED');

    case 'approve':
      if (check.status !== 2) {
        return errorResponse('ONLY_PENDING_APPROVAL_CAN_APPROVE', 400, 400);
      }

      if (!approver_id) {
        return errorResponse('APPROVER_REQUIRED', 400, 400);
      }

      const _stocktakingThreshold = Number(getConfig('stocktaking_diff_threshold') || 100);

      // 使用事务保护盘点审批操作，确保数据一致性
      await transaction(async (conn) => {
        const diffItems: Loose[] = await conn
          .execute(`SELECT * FROM inv_stocktaking_item WHERE taking_id = ? AND diff_qty != 0`, [id])
          .then(([rows]) => rows as Loose[]);

        for (const item of diffItems) {
          // 检查是否会产生负库存
          const currentStock: Loose = await conn
            .execute(
              `SELECT quantity FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0`,
              [item.material_id, check.warehouse_id]
            )
            .then(([rows]) => (rows as Loose[])[0]);

          if (currentStock && currentStock.quantity + item.diff_qty < 0) {
            throw new Error(`物料ID ${item.material_id} 盘点后将产生负库存，请检查盘点数据`);
          }

          // 更新库存
          await conn.execute(
            `UPDATE inv_inventory SET quantity = quantity + ?, update_time = NOW() WHERE material_id = ? AND warehouse_id = ? AND deleted = 0`,
            [item.diff_qty, item.material_id, check.warehouse_id]
          );

          // 记录库存流水
          await conn.execute(
            `INSERT INTO inv_inventory_log (material_id, warehouse_id, change_qty, change_type, ref_no, ref_id, create_time)
             VALUES (?, ?, ?, 'STOCKTAKING', ?, ?, NOW())`,
            [item.material_id, check.warehouse_id, item.diff_qty, check.taking_no, id]
          );
        }

        // 更新盘点单状态
        await conn.execute(
          `UPDATE inv_stocktaking SET status = 3, approver_id = ?, update_time = NOW() WHERE id = ?`,
          [approver_id, id]
        );

        // 解锁库存
        await conn.execute(`UPDATE inv_inventory SET stocktaking_flag = 0 WHERE warehouse_id = ?`, [
          check.warehouse_id,
        ]);
      });

      return successResponse(null, 'STOCKTAKING_APPROVED');

    case 'reject':
      if (check.status !== 2) {
        return errorResponse('ONLY_PENDING_APPROVAL_CAN_REJECT', 400, 400);
      }

      await execute(`UPDATE inv_stocktaking SET status = 1, update_time = NOW() WHERE id = ?`, [
        id,
      ]);

      return successResponse(null, 'STOCKTAKING_REJECTED');

    case 'cancel':
      if (![1].includes(check.status)) {
        return errorResponse('ONLY_IN_PROGRESS_CAN_CANCEL', 400, 400);
      }

      await execute(`UPDATE inv_stocktaking SET status = 4, update_time = NOW() WHERE id = ?`, [
        id,
      ]);

      await execute(`UPDATE inv_inventory SET stocktaking_flag = 0 WHERE warehouse_id = ?`, [
        check.warehouse_id,
      ]);

      return successResponse(null, 'STOCKTAKING_CANCELLED');

    case 'update_items':
      if (!items || !Array.isArray(items)) {
        return errorResponse('STOCKTAKING_ITEMS_REQUIRED', 400, 400);
      }

      for (const item of items) {
        const { id: itemId, actual_quantity, difference_reason } = item;

        const checkItem: Loose = await queryOne(
          `SELECT * FROM inv_stocktaking_item WHERE id = ? AND taking_id = ?`,
          [itemId, id]
        );

        if (!checkItem) continue;

        const diff_qty = actual_quantity - checkItem.system_qty;

        await execute(
          `UPDATE inv_stocktaking_item
           SET actual_qty = ?,
               diff_qty = ?,
               remark = ?
           WHERE id = ?`,
          [actual_quantity, diff_qty, difference_reason || null, itemId]
        );
      }

      const stats: Loose = await queryOne(
        `SELECT
          COUNT(CASE WHEN actual_qty > 0 THEN 1 END) as checked_count,
          COUNT(*) as total_count
         FROM inv_stocktaking_item
         WHERE taking_id = ?`,
        [id]
      );

      return successResponse(
        {
          checked_count: stats.checked_count,
          total_count: stats.total_count,
          progress: Math.round((stats.checked_count / stats.total_count) * 100),
        },
        '盘点数据更新成功'
      );

    default:
      return errorResponse('INVALID_OPERATION_TYPE', 400, 400);
  }
});

export const DELETE = withPermission(async (request: NextRequest) => {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');

  if (!id) {
    return errorResponse('ID_PARAM_REQUIRED', 400, 400);
  }

  const check: Loose = await queryOne(
    `SELECT * FROM inv_stocktaking WHERE id = ? AND deleted = 0`,
    [Number(id)]
  );

  if (!check) {
    return commonErrors.notFound('盘点单不存在');
  }

  if (![4].includes(check.status)) {
    return errorResponse('ONLY_CANCELLED_CAN_DELETE', 400, 400);
  }

  await execute(`UPDATE inv_stocktaking SET deleted = 1, update_time = NOW() WHERE id = ?`, [
    Number(id),
  ]);

  await execute(`UPDATE inv_inventory SET stocktaking_flag = 0 WHERE warehouse_id = ?`, [
    check.warehouse_id,
  ]);

  return successResponse(null, 'STOCKTAKING_DELETED');
});

import { NextRequest } from 'next/server';
import { execute, queryOne } from '@/lib/db';
import { successResponse, errorResponse, commonErrors } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { getTrPrefix, generateDocNo } from '@/lib/global-config';

export const POST = withPermission(
  async (request: NextRequest, userInfo, { params }: { params: Promise<{ id: string }> }) => {
    const resolvedParams = await params;
    const transferId = parseInt(resolvedParams.id);
    const body = await request.json();
    const { items } = body;

    if (!items || !Array.isArray(items) || items.length === 0) {
      return errorResponse('缺少入库明细数据', 400, 400);
    }

    const transfer: Loose = await queryOne(`SELECT * FROM transfers WHERE id = ? AND deleted = 0`, [
      transferId,
    ]);

    if (!transfer) {
      return commonErrors.notFound('调拨单不存在');
    }

    if (transfer.status !== 2) {
      const statusMap: Record<number, string> = {
        0: '草稿',
        1: '待审批',
        2: '已出库',
        3: '已入库',
        4: '已取消',
      };
      return errorResponse(
        `当前状态为"${statusMap[transfer.status]}"，不能执行入库操作（需要先完成出库）`,
        400,
        400
      );
    }

    let totalInQty = 0;

    for (const item of items) {
      const { material_id, qr_code, quantity } = item;

      if (!qr_code && !material_id) {
        return errorResponse('每项必须提供二维码或物料ID', 400, 400);
      }

      if (!quantity || quantity <= 0) {
        return errorResponse('入库数量必须大于0', 400, 400);
      }

      const targetQrCode = qr_code || `${transfer.transfer_no}-${Date.now()}`;

      const existingInventory: Loose = await queryOne(
        `SELECT * FROM inv_inventory
       WHERE warehouse_id = ?
         AND material_id = ?
         AND qr_code = ?
         AND deleted = 0`,
        [transfer.to_warehouse_id, material_id || 0, targetQrCode]
      );

      if (existingInventory) {
        await execute(
          `UPDATE inv_inventory
         SET quantity = quantity + ?,
             updated_at = NOW()
         WHERE id = ?`,
          [quantity, existingInventory.id]
        );
      } else {
        const batchNo = generateDocNo(getTrPrefix());

        await execute(
          `INSERT INTO inv_inventory (
          warehouse_id, material_id, qr_code, batch_no,
          quantity, warehouse_location, inbound_date,
          created_at, updated_at, deleted
        ) VALUES (?, ?, ?, ?, ?, ?, NOW(), NOW(), NOW(), 0)`,
          [
            transfer.to_warehouse_id,
            material_id || 0,
            targetQrCode,
            batchNo,
            quantity,
            transfer.to_location || null,
          ]
        );
      }

      await execute(
        `UPDATE transfer_items
       SET in_quantity = COALESCE(in_quantity, 0) + ?
       WHERE transfer_id = ? AND material_id = ?`,
        [quantity, transferId, material_id || 0]
      );

      totalInQty += parseFloat(quantity);
    }

    const allItemsIn: Loose = await queryOne(
      `SELECT
      SUM(CASE WHEN in_quantity >= quantity THEN 1 ELSE 0 END) as complete_count,
      COUNT(*) as total_count
     FROM transfer_items
     WHERE transfer_id = ?`,
      [transferId]
    );

    let newStatus = 2;
    if (allItemsIn.complete_count === allItemsIn.total_count) {
      newStatus = 3;
    }

    await execute(
      `UPDATE transfers
     SET status = ?, in_time = NOW(), update_time = NOW()
     WHERE id = ?`,
      [newStatus, transferId]
    );

    return successResponse(
      {
        transfer_no: transfer.transfer_no,
        status: newStatus,
        in_time: new Date().toISOString(),
        in_quantity: totalInQty,
        progress: {
          complete_count: allItemsIn.complete_count,
          total_count: allItemsIn.total_count,
        },
      },
      newStatus === 3 ? '调拨入库完成' : '部分入库成功'
    );
  }
);

