import { TRANSFER_TYPE_LABEL, TRANSFER_STATUS_LABEL } from '@/lib/status-labels';

const TYPE_MAP = TRANSFER_TYPE_LABEL;
const STATUS_MAP = TRANSFER_STATUS_LABEL;

function generateTransferNo(): string {
