}

export const GET = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const page = Number(searchParams.get('page') || 1);
  const pageSize = Number(searchParams.get('pageSize') || 20);
  const transferNo = searchParams.get('transferNo') || '';
  const status = searchParams.get('status') !== '' ? Number(searchParams.get('status')) : undefined;

  let where = 'WHERE t.deleted = 0';
  const params: Loose[] = [];

  if (transferNo) {
    where += ' AND t.transfer_no LIKE ?';
    params.push(`%${transferNo}%`);
  }
  if (status !== undefined) {
    where += ' AND t.status = ?';
    params.push(status);
  }

  const totalRows: Loose = await query(
    `SELECT COUNT(*) as total FROM inv_transfer_order t ${where}`,
    params
  );
  const total = totalRows[0]?.total || 0;

  const rows: Loose[] = await query(
    `SELECT t.*,
            w1.warehouse_name as from_warehouse_name,
            w2.warehouse_name as to_warehouse_name,
            u1.real_name as operator_name
     FROM inv_transfer_order t
     LEFT JOIN inv_warehouse w1 ON t.from_warehouse_id = w1.id
     LEFT JOIN inv_warehouse w2 ON t.to_warehouse_id = w2.id
     LEFT JOIN sys_user u1 ON t.operator_id = u1.id
     ${where}
     ORDER BY t.create_time DESC
     LIMIT ? OFFSET ?`,
    [...params, pageSize, (page - 1) * pageSize]
  );

  return successResponse({
    list: rows.map((row: Loose) => ({
      ...row,
      type_name: TYPE_MAP[row.type] || '未知',
      status_name: STATUS_MAP[row.status] || '未知',
    })),
    total,
    page,
    pageSize,
  });
});

export const POST = withPermission(async (request: NextRequest, _userInfo) => {
  const body = await request.json();
  const {
    type = 1,
    from_warehouse_id,
    to_warehouse_id,
    from_location,
    to_location,
    operator_id,
    remark,
    items,
  } = body;

  if (!from_warehouse_id) {
    return errorResponse('请选择调出仓库', 400, 400);
  }

  if (!to_warehouse_id) {
    return errorResponse('请选择调入仓库', 400, 400);
  }

  if (![1, 2].includes(type)) {
    return errorResponse('调拨类型无效（1=库位调拨，2=仓库调拨）', 400, 400);
  }

  if (type === 1 && from_warehouse_id !== to_warehouse_id) {
    return errorResponse('库位调拨必须在同一仓库内进行', 400, 400);
  }

  if (!from_location && type === 1) {
    return errorResponse('请选择调出库位', 400, 400);
  }

  if (!to_location && type === 1) {
    return errorResponse('请选择调入库位', 400, 400);
  }

  const transferNo = generateTransferNo();

  const result: Loose = await execute(
    `INSERT INTO inv_transfer_order (
      transfer_no, type, from_warehouse_id, to_warehouse_id,
      from_location, to_location, status, operator_id,
      remark, create_time, update_time
    ) VALUES (?, ?, ?, ?, ?, ?, 0, ?, ?, NOW(), NOW())`,
    [
      transferNo,
      type,
      from_warehouse_id,
      to_warehouse_id,
      from_location || null,
      to_location || null,
      operator_id || null,
      remark || null,
    ]
  );

  const transferId = result.insertId;

  if (items && Array.isArray(items)) {
    for (const item of items) {
      if (!item.material_id || !item.quantity) continue;

      await execute(
        `INSERT INTO inv_transfer_item (
          transfer_id, material_id, quantity,
          unit, batch_no
        ) VALUES (?, ?, ?, ?, ?)`,
        [transferId, item.material_id, item.quantity, item.unit || null, item.batch_no || null]
      );
    }
  }

  return successResponse(
    {
      id: transferId,
      transfer_no: transferNo,
      status: 0,
    },
    '调拨单创建成功'
  );
});

export const PUT = withPermission(async (request: NextRequest, _userInfo) => {
  const body = await request.json();
  const { id, action, approver_id } = body;

  const transfer: Loose = await queryOne(
    `SELECT * FROM inv_transfer_order WHERE id = ? AND deleted = 0`,
    [id]
  );

  if (!transfer) {
    return commonErrors.notFound('调拨单不存在');
  }

  switch (action) {
    case 'submit':
      // 提交审批：草稿→待审批
      if (transfer.status !== 0) {
        return errorResponse('只有草稿状态的调拨单才能提交审批', 400, 400);
      }
      await execute(`UPDATE inv_transfer_order SET status = 1, update_time = NOW() WHERE id = ?`, [
        id,
      ]);
      return successResponse(null, '调拨单已提交审批');

    case 'approve':
      if (transfer.status !== 1) {
        return errorResponse('只有待审批的调拨单才能审批', 400, 400);
      }

      if (!approver_id) {
        return errorResponse('请指定审批人', 400, 400);
      }

      await execute(
        `UPDATE inv_transfer_order
         SET status = 2, approver_id = ?, update_time = NOW()
         WHERE id = ?`,
        [approver_id, id]
      );

      return successResponse(null, '调拨单审批通过');

    case 'reject':
      if (transfer.status !== 1) {
        return errorResponse('只有待审批的调拨单才能驳回', 400, 400);
      }

      await execute(`UPDATE inv_transfer_order SET status = 4, update_time = NOW() WHERE id = ?`, [
        id,
      ]);

      return successResponse(null, '调拨单已驳回');

    case 'cancel':
      if (![0, 1].includes(transfer.status)) {
        return errorResponse('只能取消草稿或待审批的调拨单', 400, 400);
      }

      await execute(`UPDATE inv_transfer_order SET status = 4, update_time = NOW() WHERE id = ?`, [
        id,
      ]);

      return successResponse(null, '调拨单已取消');

    default:
      return errorResponse('无效的操作类型', 400, 400);
  }
});

export const DELETE = withPermission(async (request: NextRequest, _userInfo) => {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');

  if (!id) {
    return errorResponse('缺少ID参数', 400, 400);
  }

  const transfer: Loose = await queryOne(
    `SELECT * FROM inv_transfer_order WHERE id = ? AND deleted = 0`,
    [Number(id)]
  );

  if (!transfer) {
    return commonErrors.notFound('调拨单不存在');
  }

  if (![0, 4].includes(transfer.status)) {
    return errorResponse('只能删除草稿或已取消的调拨单', 400, 400);
  }

  await execute(`UPDATE inv_transfer_order SET deleted = 1, update_time = NOW() WHERE id = ?`, [
    Number(id),
  ]);

  return successResponse(null, '调拨单删除成功');
});

import { NextRequest } from 'next/server';
import { successResponse, errorResponse, validateRequestBody } from '@/lib/api-response';
import { withPermission } from '@/lib/api-permissions';
import { UserInfo } from '@/lib/auth';
import { query, execute } from '@/lib/db';

/**
 * 多单位换算 API
 *
 * 支持物料的多单位管理，实现"箱→个"、"吨→公斤"等换算
 * 换算关系：1 大单位 = N 小单位
 */

// 获取单位换算列表
export const GET = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const materialId = searchParams.get('materialId');
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');

    let where = 'WHERE 1=1';
    const params: Loose[] = [];

    if (materialId) {
      where += ' AND u.material_id = ?';
      params.push(Number(materialId));
    }

    const countRows: Loose = await query(
      `SELECT COUNT(*) as total FROM inv_unit_conversion u ${where}`,
      params
    );
    const total = countRows[0]?.total || 0;

    const rows: Loose = await query(
      `SELECT u.*, m.material_name, m.material_code, m.unit as base_unit
       FROM inv_unit_conversion u
       LEFT JOIN materials m ON u.material_id = m.id
       ${where}
       ORDER BY u.material_id, u.ratio DESC
       LIMIT ? OFFSET ?`,
      [...params, pageSize, (page - 1) * pageSize]
    );

    return successResponse({ list: rows, total, page, pageSize });
  },
  { errorMessage: '操作失败' }
);

// 创建/更新单位换算
export const POST = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const body = await request.json();
    const validation = validateRequestBody(body, ['material_id', 'from_unit', 'to_unit', 'ratio']);

    if (!validation.valid) {
      return errorResponse(`缺少必填字段: ${validation.missing.join(', ')}`, 400, 400);
    }

    const { material_id, from_unit, to_unit, ratio, is_default } = body;

    if (ratio <= 0) {
      return errorResponse('换算比例必须大于0', 400, 400);
    }

    // 检查是否已存在相同换算
    const existing: Loose = await query(
      'SELECT id FROM inv_unit_conversion WHERE material_id = ? AND from_unit = ? AND to_unit = ?',
      [material_id, from_unit, to_unit]
    );

    if (existing.length > 0) {
      // 更新
      await execute(
        'UPDATE inv_unit_conversion SET ratio = ?, is_default = ?, update_time = NOW() WHERE id = ?',
        [ratio, is_default ? 1 : 0, existing[0].id]
      );
      return successResponse({ id: existing[0].id }, '换算关系已更新');
    }

    // 创建
    const result: Loose = await execute(
      `INSERT INTO inv_unit_conversion
       (material_id, from_unit, to_unit, ratio, is_default, create_time, update_time)
       VALUES (?, ?, ?, ?, ?, NOW(), NOW())`,
      [material_id, from_unit, to_unit, ratio, is_default ? 1 : 0]
    );

    return successResponse({ id: result.insertId }, '换算关系创建成功');
  },
  { errorMessage: '操作失败' }
);

// 删除换算关系
export const DELETE = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return errorResponse('缺少ID参数', 400, 400);
    }

    await execute('DELETE FROM inv_unit_conversion WHERE id = ?', [Number(id)]);
    return successResponse(null, '换算关系已删除');
  },
  { errorMessage: '操作失败' }
);

// 单位换算计算
export const PUT = withPermission(
  async (request: NextRequest, _userInfo: UserInfo) => {
    const body = await request.json();
    const { material_id, from_unit, to_unit, quantity } = body;

    if (!material_id || !from_unit || !to_unit || !quantity) {
      return errorResponse('物料ID、源单位、目标单位和数量不能为空', 400, 400);
    }

    // 查找换算关系
    const conversions: Loose = await query(
      'SELECT * FROM inv_unit_conversion WHERE material_id = ? AND ((from_unit = ? AND to_unit = ?) OR (from_unit = ? AND to_unit = ?))',
      [material_id, from_unit, to_unit, to_unit, from_unit]
    );

    if (conversions.length === 0) {
      return errorResponse('未找到对应的单位换算关系', 404, 404);
    }

    const conv = conversions[0];
    let resultQty: number;

    if (conv.from_unit === from_unit && conv.to_unit === to_unit) {
      // 正向换算：from_unit → to_unit
      resultQty = Number(quantity) * Number(conv.ratio);
    } else {
      // 反向换算：to_unit → from_unit
      resultQty = Number(quantity) / Number(conv.ratio);
    }

    return successResponse(
      {
        material_id,
        from_unit,
        to_unit,
        from_quantity: Number(quantity),
        to_quantity: resultQty,
        ratio: Number(conv.ratio),
      },
      '换算完成'
    );
  },
  { errorMessage: '操作失败' }
);

