    // 油墨配方版本事件
    eventBus.subscribe(
      'inkFormulaVersion.activated',
      new IdempotentHandler(new FormulaVersionActivatedHandler())
    );
    eventBus.subscribe('inkFormulaVersion.activated', new AuditLogHandler());
