    eventBus.subscribe('saga.compensate.validate_report', sagaCompHandler);
    eventBus.subscribe('saga.compensate.update_workorder_progress', sagaCompHandler);
    eventBus.subscribe('saga.compensate.hr_piece_record', sagaCompHandler);
    eventBus.subscribe('saga.failed', sagaCompHandler);
    eventBus.subscribe('saga.completed', sagaCompHandler);
    eventBus.subscribe('saga.compensated', sagaCompHandler);

    // 标准卡事件 — BOM 展开缓存失效
    eventBus.subscribe('StandardCardConfirmed', new CacheInvalidationHandler());
    eventBus.subscribe('StandardCardObsoleted', new CacheInvalidationHandler());

    this.initialized = true;
    secureLog('info', 'Event registry initialized', {
      inboundApprovedHandlers: eventBus.getHandlerCount('inbound.approved'),
      purchaseReceivedHandlers: eventBus.getHandlerCount('purchase.received'),
      salesShippedHandlers: eventBus.getHandlerCount('sales.shipped'),
      deliveryShippedHandlers: eventBus.getHandlerCount('delivery.shipped'),
      returnOrderCompletedHandlers: eventBus.getHandlerCount('return_order.completed'),
      reconciliationWrittenOffHandlers: eventBus.getHandlerCount('reconciliation.written_off'),
      purchaseReturnCompletedHandlers: eventBus.getHandlerCount('purchase_return.completed'),
      purchaseReconWrittenOffHandlers: eventBus.getHandlerCount(
        'purchase_reconciliation.written_off'
      ),
      workorderCompletedHandlers: eventBus.getHandlerCount('workorder.completed'),
      qualityUnqualifiedCompletedHandlers: eventBus.getHandlerCount(
        'quality.unqualified.completed'
      ),
    });
  }

  static reset(): void {
    this.initialized = false;
  }
}

/**
 * 函数式注册入口（向后兼容）。
 * 调用类版 initialize 后返回全局 EventBus 单例，供 API 路由与 OutboxPoller 使用。
 *
 * 同时惰性启动 OutboxPoller + StreamConsumer（仅 EVENT_BUS_TYPE=db 时）。
 * 采用 require() 延迟加载以规避 EventRegistry ↔ AppInitializer ↔ OutboxPoller 循环依赖。
 * instrumentation.ts（Edge 打包）不再导入 AppInitializer，从而避免 crypto/stream 模块解析失败。
 */
let applicationInitialized = false;

export function registerEventHandlers(): EventBus {
  EventRegistry.initialize();

  if (!applicationInitialized) {
    applicationInitialized = true;
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const { initializeApplication } = require('./AppInitializer');
      initializeApplication();
    } catch (error) {
      secureLog('error', 'Failed to auto-initialize application (OutboxPoller/StreamConsumer)', {
        error: String(error),
      });
    }
  }

  return getEventBus();
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { DeliveryCancelledEvent } from '@/domain/sales/events/DeliveryEvents';
import { transaction } from '@/lib/db';
import { logger, secureLog } from '@/lib/logger';
import type { RowDataPacket } from 'mysql2';

interface DeliveryDetailRow {
  id: number;
  order_detail_id: number | null;
  quantity: number;
  material_id: number;
}

export class DeliveryCancelledHandler implements EventHandler<DeliveryCancelledEvent> {
  async handle(event: DeliveryCancelledEvent): Promise<void> {
    const { deliveryId, deliveryNo, orderId, reason } = event.payload;
    const ctx = { module: 'delivery-cancelled', action: 'rollback', deliveryId, deliveryNo };
    let phase = 'init';

    try {
      await transaction(async (conn) => {
        phase = 'load_delivery_details';
        const [detailRows] = await conn.execute<RowDataPacket[]>(
          'SELECT id, order_detail_id, quantity, material_id FROM sal_delivery_detail WHERE delivery_id = ? AND deleted = 0',
          [deliveryId]
        );

        if (!detailRows || detailRows.length === 0) {
          logger.warn(ctx, '发货单明细不存在，跳过回滚', { deliveryId, deliveryNo });
          return;
        }

        const details = detailRows as unknown as DeliveryDetailRow[];
        logger.info(ctx, '发货单明细加载完成', {
          deliveryId,
          detailCount: details.length,
        });

        phase = 'rollback_delivered_qty';
        for (const detail of details) {
          if (detail.order_detail_id) {
            await conn.execute(
              'UPDATE sal_order_detail SET delivered_qty = GREATEST(0, delivered_qty - ?) WHERE id = ?',
              [detail.quantity, detail.order_detail_id]
            );
            logger.info(ctx, '回滚订单明细已发货数量', {
              orderDetailId: detail.order_detail_id,
              rollbackQty: detail.quantity,
            });
          }
        }

        phase = 'check_order_status';
        if (orderId) {
          const [orderStatusRows] = await conn.execute<RowDataPacket[]>(
            'SELECT id, status FROM sal_order WHERE id = ?',
            [orderId]
          );

          if (orderStatusRows && orderStatusRows.length > 0) {
            const currentStatus = orderStatusRows[0].status;
            if (currentStatus === 3 || currentStatus === 4) {
              const [totalDelivered] = await conn.execute<RowDataPacket[]>(
                `SELECT SUM(delivered_qty) as total_delivered
                 FROM sal_order_detail
                 WHERE order_id = ? AND deleted = 0`,
                [orderId]
              );

              const totalDeliveredQty = Number(totalDelivered[0]?.total_delivered || 0);
              if (totalDeliveredQty === 0) {
                await conn.execute(
                  'UPDATE sal_order SET status = 2, update_time = NOW() WHERE id = ?',
                  [orderId]
                );
                logger.info(ctx, '订单状态恢复为已审核', { orderId });
              } else {
                await conn.execute(
                  'UPDATE sal_order SET status = 3, update_time = NOW() WHERE id = ?',
                  [orderId]
                );
                logger.info(ctx, '订单状态恢复为部分发货', { orderId });
              }
            }
          }
        }

        // T403: 发货单作废时联动软删对应应收单（按 source_no = 发货单号）
        // 仅处理销售发货来源（source_type=1），避免误删退货红字应收
        if (deliveryNo) {
          const [receivableRows] = await conn.execute<RowDataPacket[]>(
            `SELECT id, receivable_no FROM fin_receivable
             WHERE source_no = ? AND source_type = 1 AND deleted = 0`,
            [deliveryNo]
          );
          if (receivableRows.length > 0) {
            await conn.execute(
              `UPDATE fin_receivable SET deleted = 1, update_time = NOW()
               WHERE source_no = ? AND source_type = 1 AND deleted = 0`,
              [deliveryNo]
            );
            logger.info(ctx, '应收单联动软删完成 (T403)', {
              deliveryNo,
              count: receivableRows.length,
              receivableNos: receivableRows.map((r) => r.receivable_no),
            });
          }
        }
      });

      secureLog('info', 'Delivery cancelled and order quantities rolled back', {
        deliveryNo,
        orderId,
        reason,
      });
    } catch (err) {
      logger.error(ctx, `DeliveryCancelled 失败 [phase=${phase}]`, {
        error: err instanceof Error ? err.message : String(err),
        deliveryNo,
        orderId,
      });
      throw err;
    }
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { DeliveryShippedEvent } from '@/domain/sales/events/DeliveryEvents';
import { transaction } from '@/lib/db';
import { logger, secureLog } from '@/lib/logger';

export class DeliveryReceivableHandler implements EventHandler<DeliveryShippedEvent> {
  async handle(event: DeliveryShippedEvent): Promise<void> {
    const { deliveryId, deliveryNo, orderId: _orderId, customerId, totalAmount } = event.payload;
    const ctx = { module: 'delivery-receivable', action: 'create', deliveryId, deliveryNo };
    let phase = 'init';

    if (totalAmount <= 0) {
      logger.info(ctx, '跳过：发货金额为 0', { deliveryNo });
      return;
    }

    try {
      let created = false;
      await transaction(async (conn) => {
        phase = 'check_duplicate';
        const receivableNo = 'AR' + Date.now();
        logger.info(ctx, '开始处理应收账款创建', { receivableNo, customerId, totalAmount });
        const [existing]: Loose = await conn.execute(
          'SELECT id FROM fin_receivable WHERE source_no = ? AND deleted = 0 LIMIT 1',
          [deliveryNo]
        );
        if (existing && existing.length > 0) {
          secureLog('info', 'Receivable already exists for delivery, skip', {
            deliveryNo,
            deliveryId,
          });
          logger.info(ctx, `跳过：应收账款已存在`, { deliveryNo, existingId: existing[0].id });
          return;
        }
        logger.info(ctx, '无重复记录，准备创建应收账款', { deliveryNo, receivableNo });

        phase = 'insert_receivable';
        const insertParams = [
          receivableNo,
          customerId,
          deliveryNo,
          totalAmount,
          totalAmount,
          `Sales delivery ${deliveryNo} auto-generated`,
        ];
        logger.info(ctx, 'INSERT fin_receivable 参数详情', {
          paramCount: insertParams.length,
          params: insertParams,
        });
        await conn.execute(
          `INSERT INTO fin_receivable
           (receivable_no, customer_id, source_type, source_no, amount, received_amount, balance, status, due_date, remark, create_time)
           VALUES (?, ?, 1, ?, ?, 0, ?, 1, DATE_ADD(CURDATE(), INTERVAL 30 DAY), ?, NOW())`,
          insertParams
        );
        created = true;
        logger.info(ctx, `应收账款创建完成`, {
          receivableNo,
          customerId,
          deliveryNo,
          totalAmount,
        });
      });

      if (created) {
        secureLog('info', 'Receivable created for delivery shipment', { deliveryNo, totalAmount });
        logger.info(ctx, '应收账款流程成功结束', { deliveryNo, totalAmount });
      } else {
        logger.info(ctx, '应收账款流程跳过（未创建）', { deliveryNo });
      }
    } catch (err) {
      logger.error(ctx, `DeliveryReceivable 失败 [phase=${phase}]`, {
        error: err instanceof Error ? err.message : String(err),
        deliveryNo,
        totalAmount,
      });
      throw err;
    }
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { DeliveryShippedEvent } from '@/domain/sales/events/DeliveryEvents';
import { transaction } from '@/lib/db';
import { logger, secureLog } from '@/lib/logger';
import type { RowDataPacket } from 'mysql2';

/**
 * 处理 DeliveryShippedEvent：发货出库时扣减库存和批次可用量，记录库存交易流水，
 * 并更新销售订单状态（已审核→部分发货→全部发货）。
 */
export class DeliveryShippedHandler implements EventHandler<DeliveryShippedEvent> {
  async handle(event: DeliveryShippedEvent): Promise<void> {
    const { deliveryId, deliveryNo, orderId, warehouseId, shippedItems } = event.payload;
    const ctx = { module: 'delivery-shipped', action: 'inventory', deliveryId, deliveryNo };

    await transaction(async (conn) => {
      for (const item of shippedItems) {
        const [existingInv]: Loose = await conn.execute(
          'SELECT id, quantity FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.materialId, warehouseId]
        );

        if (existingInv.length > 0) {
          const currentQty = parseFloat(existingInv[0].quantity);
          if (currentQty < item.quantity) {
            throw new Error(
              `物料${item.materialName}库存不足: 当前${currentQty}, 需要出库${item.quantity}`
            );
          }
          await conn.execute(
            'UPDATE inv_inventory SET quantity = quantity - ?, update_time = NOW() WHERE id = ?',
            [item.quantity, existingInv[0].id]
          );
        }

        const [existingBatch]: Loose = await conn.execute(
          'SELECT id, available_qty, quantity FROM inv_inventory_batch WHERE batch_no = ? AND material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.batchNo, item.materialId, warehouseId]
        );

        if (existingBatch.length > 0) {
          const newAvailableQty = parseFloat(existingBatch[0].available_qty) - item.quantity;
          const newQty = parseFloat(existingBatch[0].quantity) - item.quantity;
          if (newAvailableQty <= 0 || newQty <= 0) {
            await conn.execute(
              'UPDATE inv_inventory_batch SET deleted = 1, update_time = NOW() WHERE id = ?',
              [existingBatch[0].id]
            );
          } else {
            await conn.execute(
              'UPDATE inv_inventory_batch SET available_qty = available_qty - ?, quantity = quantity - ?, update_time = NOW() WHERE id = ?',
              [item.quantity, item.quantity, existingBatch[0].id]
            );
          }
        }

        const transNo = 'TRX' + Date.now() + String(item.materialId).slice(-4);
        await conn.execute(
          `INSERT INTO inv_inventory_transaction (trans_no, trans_type, source_type, source_id, material_id, material_code, batch_no, warehouse_id, quantity, unit_price, total_amount, create_time)
           VALUES (?, 'out', 'sales_delivery', ?, ?, ?, ?, ?, ?, ?, ?, NOW())`,
          [
            transNo,
            deliveryId,
            item.materialId,
            item.materialCode,
            item.batchNo,
            warehouseId,
            item.quantity,
            item.unitPrice,
            item.quantity * item.unitPrice,
          ]
        );

        if (item.orderDetailId) {
          await conn.execute(
            `UPDATE sal_order_detail SET delivered_qty = delivered_qty + ? WHERE id = ?`,
            [item.quantity, item.orderDetailId]
          );
        }
      }

      if (orderId) {
        const [orderStatusRows] = await conn.execute<RowDataPacket[]>(
          'SELECT id, status FROM sal_order WHERE id = ?',
          [orderId]
        );

        if (orderStatusRows && orderStatusRows.length > 0) {
          const currentStatus = orderStatusRows[0].status;
          if (currentStatus === 2) {
            await conn.execute(
              'UPDATE sal_order SET status = 3, update_time = NOW() WHERE id = ?',
              [orderId]
            );
            logger.info(ctx, '订单状态更新为部分发货', { orderId });
          }

          const [totalDelivered] = await conn.execute<RowDataPacket[]>(
            `SELECT SUM(delivered_qty) as total_delivered
             FROM sal_order_detail
             WHERE order_id = ? AND deleted = 0`,
            [orderId]
          );

          const [orderTotal] = await conn.execute<RowDataPacket[]>(
            `SELECT SUM(quantity) as order_total
             FROM sal_order_detail
             WHERE order_id = ? AND deleted = 0`,
            [orderId]
          );

          const deliveredQty = Number(totalDelivered[0]?.total_delivered || 0);
          const orderTotalQty = Number(orderTotal[0]?.order_total || 0);

          if (deliveredQty >= orderTotalQty && orderTotalQty > 0) {
            await conn.execute(
              'UPDATE sal_order SET status = 4, update_time = NOW() WHERE id = ?',
              [orderId]
            );
            logger.info(ctx, '订单状态更新为全部发货', { orderId });
          }
        }
      }
    });

    secureLog('info', 'Inventory deducted for delivery shipment', {
      deliveryNo,
      orderId,
      itemCount: shippedItems.length,
    });
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { InboundOrderApprovedEvent } from '@/domain/warehouse/events/InboundOrderEvents';
import { WorkOrderCompletedEvent } from '@/domain/production/events/WorkOrderEvents';
import { transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';

type FinanceEvent = InboundOrderApprovedEvent | WorkOrderCompletedEvent;

export class FinanceVoucherHandler implements EventHandler<FinanceEvent> {
  async handle(event: FinanceEvent): Promise<void> {
    let inboundNo: string | undefined;
    let totalAmount = 0;
    let supplierId: number | undefined;
    let sourceType = 1;
    let remark = '';

    if (event.eventType === 'inbound.approved') {
      const payload = (event as InboundOrderApprovedEvent).payload;
      inboundNo = payload.inboundNo;
      totalAmount = payload.totalAmount;
      supplierId = payload.supplierId;
      sourceType = 1;
      remark = `采购入库单 ${inboundNo} 自动生成`;
    } else if (event.eventType === 'workorder.completed') {
      const payload = (event as WorkOrderCompletedEvent).payload;
      inboundNo = payload.workOrderNo;
      totalAmount = 0;
      supplierId = undefined;
      sourceType = 2;
      remark = `生产工单 ${inboundNo} 完工`;
    }

    if (totalAmount <= 0 || !inboundNo) return;

    let created = false;
    await transaction(async (conn) => {
      // 幂等校验：同一 source_no 仅生成一条应付单，避免重复审核导致重复记账（T301）
      const [existing]: Loose = await conn.execute(
        'SELECT id FROM fin_payable WHERE source_no = ? AND deleted = 0 LIMIT 1',
        [inboundNo]
      );
      if (existing && existing.length > 0) {
        secureLog('info', 'Payable already exists for source, skip', {
          inboundNo,
          sourceType,
          existingId: existing[0].id,
        });
        return;
      }

      const payableNo = 'AP' + Date.now();
      await conn.execute(
        `INSERT INTO fin_payable
         (payable_no, supplier_id, source_type, source_no, amount, paid_amount, balance, status, due_date, remark, create_time)
         VALUES (?, ?, ?, ?, ?, 0, ?, 1, DATE_ADD(CURDATE(), INTERVAL 30 DAY), ?, NOW())`,
        [payableNo, supplierId || null, sourceType, inboundNo, totalAmount, totalAmount, remark]
      );
      created = true;
    });

    if (created) {
      secureLog('info', 'Payable created', {
        inboundNo,
        totalAmount,
        supplierId,
        sourceType,
      });
    }
  }
}

import { transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';
import type { DomainEvent } from '@/domain/shared/DomainTypes';
import type { RowDataPacket, ResultSetHeader } from 'mysql2';

/**
 * 完工入库单审核后的库存联动处理器
 * 监听：prod.finish.approved
 * 功能：增加成品库存，回写工单完工数量
 *
 * 幂等性：通过 INSERT IGNORE + 唯一索引 uk_inv_txn_source (source_type, source_id)
 * 防止 XAUTOCLAIM 重投递导致的重复处理（TOCTOU 竞态）。
 * 事务保证 INSERT IGNORE + 库存 UPDATE + 流水 INSERT 三步原子性。
 */
export class FinishOrderInventoryHandler {
  async handle(event: DomainEvent): Promise<void> {
    const { finishOrderId, workOrderId, productName, qualifiedQty, warehouseId } =
      event.payload as {
        finishOrderId: number;
        finishNo: string;
        workOrderId: number;
        workOrderNo: string;
        productName: string;
        qualifiedQty: number;
        defectiveQty: number;
        warehouseId: number;
        userId: number;
      };

    secureLog('info', 'FinishOrderInventoryHandler: processing finish order approval', {
      finishOrderId,
      workOrderId,
      qualifiedQty,
      warehouseId,
    });

    await transaction(async (conn) => {
      // 获取工单的产品信息
      const [woRows] = await conn.execute<RowDataPacket[]>(
        'SELECT product_id, product_code, product_name FROM prod_work_order WHERE id = ? AND deleted = 0',
        [workOrderId]
      );
      const wo = woRows[0];
      if (!wo) {
        secureLog('warn', 'FinishOrderInventoryHandler: work order not found', { workOrderId });
        return;
      }

      const productId = wo.product_id || wo.productId;
      const productCode = wo.product_code || wo.productCode;

      const transNo = `FN${Date.now()}`;

      // Idempotency: INSERT IGNORE into inv_inventory_transaction, guarded by unique index
      // uk_inv_txn_source (source_type, source_id).
      // - affectedRows === 0 → already processed, skip (idempotent)
      // - affectedRows === 1 → first time, continue with inventory update
      const [txnResult] = await conn.execute<ResultSetHeader>(
        `INSERT IGNORE INTO inv_inventory_transaction
         (trans_no, trans_type, source_type, source_id, material_id, warehouse_id, quantity, create_time)
         VALUES (?, 'in', 'prod_finish', ?, ?, ?, ?, NOW())`,
        [transNo, finishOrderId, productId, warehouseId, qualifiedQty]
      );

      if (txnResult.affectedRows === 0) {
        secureLog('info', 'FinishOrderInventoryHandler: already processed, skipping', {
          finishOrderId,
        });
        return;
      }

      // 增加成品库存
      const [existing] = await conn.execute<RowDataPacket[]>(
        'SELECT id FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0',
        [productId, warehouseId]
      );

      if (existing.length > 0) {
        await conn.execute(
          `UPDATE inv_inventory SET quantity = quantity + ?,
           available_qty = available_qty + ?, update_time = NOW()
           WHERE material_id = ? AND warehouse_id = ? AND deleted = 0`,
          [qualifiedQty, qualifiedQty, productId, warehouseId]
        );
      } else {
        await conn.execute(
          `INSERT INTO inv_inventory
           (material_id, material_code, material_name, warehouse_id, quantity, available_qty, unit, create_time)
           VALUES (?, ?, ?, ?, ?, ?, '件', NOW())`,
          [productId, productCode, productName, warehouseId, qualifiedQty, qualifiedQty]
        );
      }
    });
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { InboundOrderUnapprovedEvent } from '@/domain/warehouse/events/InboundOrderEvents';
import { transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';
import { InventoryCostService } from '@/application/services/InventoryCostService';
import type { RowDataPacket } from 'mysql2';

const costService = new InventoryCostService();

/** 入库单行类型 */
interface InboundRow {
  warehouse_id: number;
}

/** 入库明细行类型 */
interface InboundItemRow {
  material_id: number;
  material_name: string;
  quantity: string | number;
  batch_no: string | null;
  unit_price: string | number;
}

/** 库存行类型 */
interface InventoryRow {
  id: number;
  quantity: string | number;
}

/** 库存批次行类型 */
interface InventoryBatchRow {
  id: number;
  available_qty: string | number;
  quantity: string | number;
}

export class InventoryRollbackHandler implements EventHandler<InboundOrderUnapprovedEvent> {
  async handle(event: InboundOrderUnapprovedEvent): Promise<void> {
    const { inboundId, inboundNo } = event.payload;

    await transaction(async (conn) => {
      // Fetch inbound order details from database
      const [inboundRows] = await conn.execute<RowDataPacket[]>(
        'SELECT warehouse_id FROM inv_inbound_order WHERE id = ? AND deleted = 0 LIMIT 1',
        [inboundId]
      );

      if (inboundRows.length === 0) {
        secureLog('warn', 'Inbound order not found for rollback', { inboundId });
        return;
      }

      const warehouseId = (inboundRows[0] as unknown as InboundRow).warehouse_id;

      // Fetch inbound items
      const [itemRows] = await conn.execute<RowDataPacket[]>(
        'SELECT material_id, material_name, quantity, batch_no, unit_price FROM inv_inbound_item WHERE order_id = ? AND deleted = 0',
        [inboundId]
      );

      const items = (itemRows as unknown[] as InboundItemRow[]).map((row) => ({
        materialId: row.material_id,
        materialName: row.material_name,
        quantity: Number(row.quantity),
        batchNo: row.batch_no,
        unitPrice: Number(row.unit_price) || 0,
      }));

      const sortedItems = [...items].sort((a, b) => a.materialId - b.materialId);

      for (const item of sortedItems) {
        const [existingInv] = await conn.execute<RowDataPacket[]>(
          'SELECT id, quantity FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.materialId, warehouseId]
        );

        if (existingInv.length > 0) {
          const invRow = existingInv[0] as unknown as InventoryRow;
          const newQty = parseFloat(String(invRow.quantity)) - item.quantity;
          if (newQty <= 0) {
            await conn.execute(
              'UPDATE inv_inventory SET quantity = 0, update_time = NOW() WHERE id = ?',
              [invRow.id]
            );
          } else {
            await conn.execute(
              'UPDATE inv_inventory SET quantity = quantity - ?, update_time = NOW() WHERE id = ?',
              [item.quantity, invRow.id]
            );
          }
          if (item.unitPrice > 0) {
            await costService.onInboundRollback(conn, invRow.id, item.quantity, item.unitPrice);
          }
        }

        const [existingBatch] = await conn.execute<RowDataPacket[]>(
          'SELECT id, available_qty, quantity FROM inv_inventory_batch WHERE batch_no = ? AND material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.batchNo, item.materialId, warehouseId]
        );

        if (existingBatch.length > 0) {
          const batchRow = existingBatch[0] as unknown as InventoryBatchRow;
          const newAvailableQty = parseFloat(String(batchRow.available_qty)) - item.quantity;
          const newQty = parseFloat(String(batchRow.quantity)) - item.quantity;
          if (newAvailableQty <= 0 || newQty <= 0) {
            await conn.execute(
              'UPDATE inv_inventory_batch SET deleted = 1, update_time = NOW() WHERE id = ?',
              [batchRow.id]
            );
          } else {
            await conn.execute(
              'UPDATE inv_inventory_batch SET available_qty = available_qty - ?, quantity = quantity - ?, update_time = NOW() WHERE id = ?',
              [item.quantity, item.quantity, batchRow.id]
            );
          }
        }
      }

      // T403: 入库单作废时联动软删对应应付单（按 source_no = 入库单号）
      // 仅处理采购入库类型（order_type='purchase'），避免误删其他来源应付
      if (inboundNo) {
        const [payableRows] = await conn.execute<RowDataPacket[]>(
          `SELECT id, payable_no FROM fin_payable
           WHERE source_no = ? AND source_type = 1 AND deleted = 0`,
          [inboundNo]
        );
        if (payableRows.length > 0) {
          await conn.execute(
            `UPDATE fin_payable SET deleted = 1, update_time = NOW()
             WHERE source_no = ? AND source_type = 1 AND deleted = 0`,
            [inboundNo]
          );
          secureLog('info', 'Payables soft-deleted on inbound void (T403)', {
            inboundNo,
            count: payableRows.length,
            payableNos: payableRows.map((r) => r.payable_no),
          });
        }
      }
    });

    secureLog('info', 'Inventory rolled back for unapproved inbound order', {
      orderNo: inboundNo,
    });
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { MaterialReturnApprovedEvent } from '@/domain/production/events/PickOrderEvents';
import { transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';
import { InventoryCostService } from '@/application/services/InventoryCostService';

const costService = new InventoryCostService();

export class MaterialReturnInventoryHandler implements EventHandler<MaterialReturnApprovedEvent> {
  async handle(event: MaterialReturnApprovedEvent): Promise<void> {
    const { returnId, returnNo, warehouseId, items } = event.payload;

    await transaction(async (conn) => {
      for (const item of items) {
        const [existingInv]: Loose = await conn.execute(
          'SELECT id, quantity FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.materialId, warehouseId]
        );

        if (existingInv.length > 0) {
          const invRow = existingInv[0] as { id: number };
          await conn.execute(
            'UPDATE inv_inventory SET quantity = quantity + ?, available_qty = available_qty + ?, update_time = NOW() WHERE id = ?',
            [item.quantity, item.quantity, invRow.id]
          );
          if (item.unitPrice && item.unitPrice > 0) {
            await costService.onInbound(conn, invRow.id, item.quantity, item.unitPrice);
          }
        } else {
          const [newInv] = await conn.execute(
            `INSERT INTO inv_inventory (material_id, material_code, material_name, warehouse_id, quantity, available_qty, unit, create_time)
             VALUES (?, ?, ?, ?, ?, ?, ?, NOW())`,
            [
              item.materialId,
              item.materialCode || null,
              item.materialName,
              warehouseId,
              item.quantity,
              item.quantity,
              item.unit || '件',
            ]
          );
          const newInvId = (newInv as unknown as { insertId: number }).insertId;
          if (item.unitPrice && item.unitPrice > 0) {
            await costService.onInbound(conn, newInvId, item.quantity, item.unitPrice);
          }
        }

        if (item.batchNo) {
          const [existingBatch]: Loose = await conn.execute(
            'SELECT id, available_qty, quantity FROM inv_inventory_batch WHERE batch_no = ? AND material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
            [item.batchNo, item.materialId, warehouseId]
          );

          if (existingBatch.length > 0) {
            await conn.execute(
              'UPDATE inv_inventory_batch SET available_qty = available_qty + ?, quantity = quantity + ?, update_time = NOW() WHERE id = ?',
              [item.quantity, item.quantity, existingBatch[0].id]
            );
          } else {
            await conn.execute(
              `INSERT INTO inv_inventory_batch (batch_no, material_id, material_name, warehouse_id, available_qty, quantity, unit_price, inbound_date, status, create_time)
               VALUES (?, ?, ?, ?, ?, ?, 0, CURDATE(), 1, NOW())`,
              [
                item.batchNo,
                item.materialId,
                item.materialName,
                warehouseId,
                item.quantity,
                item.quantity,
              ]
            );
          }
        }

        const transNo = 'TRX' + Date.now() + String(item.materialId).slice(-4);
        await conn.execute(
          `INSERT INTO inv_inventory_transaction (trans_no, trans_type, source_type, source_id, material_id, material_code, batch_no, warehouse_id, quantity, unit_price, total_amount, create_time)
           VALUES (?, 'in', 'material_return', ?, ?, ?, ?, ?, ?, 0, 0, NOW())`,
          [
            transNo,
            returnId,
            item.materialId,
            item.materialCode,
            item.batchNo,
            warehouseId,
            item.quantity,
          ]
        );
      }
    });

    secureLog('info', 'Inventory increased for material return', {
      returnNo,
      itemCount: items.length,
    });
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { OutboundOrderApprovedEvent } from '@/domain/warehouse/events/OutboundOrderEvents';
import { transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';
import { InventoryCostService } from '@/application/services/InventoryCostService';

const costService = new InventoryCostService();

export class OutboundInventoryHandler implements EventHandler<OutboundOrderApprovedEvent> {
  async handle(event: OutboundOrderApprovedEvent): Promise<void> {
    const { outboundId, outboundNo, warehouseId, items } = event.payload;

    await transaction(async (conn) => {
      for (const item of items) {
        const [existingInv]: Loose = await conn.execute(
          'SELECT id, quantity, available_qty FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.materialId, warehouseId]
        );

        if (existingInv.length > 0) {
          const currentQty = parseFloat(existingInv[0].quantity);
          if (currentQty < item.quantity) {
            throw new Error(
              `物料${item.materialName}库存不足: 当前${currentQty}, 需要出库${item.quantity}`
            );
          }
          await conn.execute(
            'UPDATE inv_inventory SET quantity = quantity - ?, available_qty = available_qty - ?, update_time = NOW() WHERE id = ?',
            [item.quantity, item.quantity, existingInv[0].id]
          );
        }

        const [existingBatch]: Loose = await conn.execute(
          'SELECT id, available_qty, quantity FROM inv_inventory_batch WHERE batch_no = ? AND material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.batchNo, item.materialId, warehouseId]
        );

        if (existingBatch.length > 0) {
          const newAvailableQty = parseFloat(existingBatch[0].available_qty) - item.quantity;
          const newQty = parseFloat(existingBatch[0].quantity) - item.quantity;
          if (newAvailableQty <= 0 || newQty <= 0) {
            await conn.execute(
              'UPDATE inv_inventory_batch SET deleted = 1, update_time = NOW() WHERE id = ?',
              [existingBatch[0].id]
            );
          } else {
            await conn.execute(
              'UPDATE inv_inventory_batch SET available_qty = available_qty - ?, quantity = quantity - ?, update_time = NOW() WHERE id = ?',
              [item.quantity, item.quantity, existingBatch[0].id]
            );
          }
        }

        const transNo = 'TRX' + Date.now() + String(item.materialId).slice(-4);

        let unitCost = item.unitPrice || 0;
        let totalCost = item.quantity * unitCost;
        if (existingInv.length > 0) {
          const invRow = existingInv[0] as { id: number };
          const costResult = await costService.getOutboundCost(conn, invRow.id, item.quantity);
          if (costResult) {
            unitCost = costResult.unitCost;
            totalCost = costResult.totalCost;
          }
        }

        await conn.execute(
          `INSERT INTO inv_inventory_transaction (trans_no, trans_type, source_type, source_id, material_id, material_code, batch_no, warehouse_id, quantity, unit_price, total_amount, create_time)
           VALUES (?, 'out', 'outbound', ?, ?, ?, ?, ?, ?, ?, ?, NOW())`,
          [
            transNo,
            outboundId,
            item.materialId,
            item.materialCode,
            item.batchNo,
            warehouseId,
            item.quantity,
            unitCost,
            totalCost,
          ]
        );
      }
    });

    secureLog('info', 'Inventory deducted for outbound order', {
      outboundNo,
      itemCount: items.length,
    });
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { OutboundOrderApprovedEvent } from '@/domain/warehouse/events/OutboundOrderEvents';
import { transaction } from '@/lib/db';
import { logger, secureLog } from '@/lib/logger';

export class OutboundReceivableHandler implements EventHandler<OutboundOrderApprovedEvent> {
  async handle(event: OutboundOrderApprovedEvent): Promise<void> {
    const { outboundNo, customerId, customerName, totalAmount } = event.payload;
    const ctx = { module: 'outbound-receivable', action: 'create', outboundNo };
    let phase = 'init';

    if (totalAmount <= 0 || !customerId) {
      logger.info(ctx, '跳过：金额为0或无客户', { outboundNo, totalAmount, customerId });
      return;
    }

    try {
      let created = false;
      await transaction(async (conn) => {
        phase = 'check_duplicate';
        const [existing]: Loose = await conn.execute(
          'SELECT id FROM fin_receivable WHERE source_no = ? AND deleted = 0 LIMIT 1',
          [outboundNo]
        );
        if (existing && existing.length > 0) {
          secureLog('info', 'Receivable already exists for outbound order, skip', { outboundNo });
          logger.info(ctx, `跳过：应收账款已存在`, { outboundNo, existingId: existing[0].id });
          return;
        }

        phase = 'insert_receivable';
        const receivableNo = 'AR' + Date.now();
        await conn.execute(
          `INSERT INTO fin_receivable
           (receivable_no, customer_id, customer_name, source_type, source_no, amount, received_amount, balance, status, due_date, remark, create_time)
           VALUES (?, ?, ?, 1, ?, ?, 0, ?, 1, DATE_ADD(CURDATE(), INTERVAL 30 DAY), ?, NOW())`,
          [
            receivableNo,
            customerId,
            customerName || null,
            outboundNo,
            totalAmount,
            totalAmount,
            `出库单 ${outboundNo} 自动生成`,
          ]
        );
        created = true;
        logger.info(ctx, `应收账款创建完成`, {
          receivableNo,
          customerId,
          customerName,
          outboundNo,
          totalAmount,
        });
      });

      if (created) {
        secureLog('info', 'Receivable created for outbound order', { outboundNo, totalAmount });
      }
    } catch (err) {
      logger.error(ctx, `OutboundReceivable 失败 [phase=${phase}]`, {
        error: err instanceof Error ? err.message : String(err),
        outboundNo,
        totalAmount,
      });
      throw err;
    }
  }
}

import { transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';
import type { DomainEvent } from '@/domain/shared/DomainTypes';

export class PickOrderInventoryHandler {
  async handle(event: DomainEvent): Promise<void> {
    const { pickOrderId, items } = event.payload as {
      pickOrderId: number;
      items: Array<{
        materialId: number;
        quantity: number;
        batchNo: string;
        warehouseId: number;
      }>;
    };

    secureLog('info', 'PickOrderInventoryHandler: processing pick order approval', {
      pickOrderId,
      itemCount: items.length,
    });

    await transaction(async (conn) => {
      for (const item of items) {
        const transNo = `PK${Date.now()}${String(item.materialId).slice(-4)}`;

        const [result] = await conn.execute<any>(
          `UPDATE inv_inventory SET quantity = GREATEST(quantity - ?, 0),
           available_qty = GREATEST(available_qty - ?, 0), update_time = NOW()
           WHERE material_id = ? AND warehouse_id = ? AND deleted = 0`,
          [item.quantity, item.quantity, item.materialId, item.warehouseId]
        );

        if (result.affectedRows > 0) {
          await conn.execute(
            `INSERT INTO inv_inventory_transaction
             (trans_no, trans_type, source_type, source_id, material_id, batch_no, warehouse_id, quantity, create_time)
             VALUES (?, 'out', 'prod_pick', ?, ?, ?, ?, ?, NOW())`,
            [transNo, pickOrderId, item.materialId, item.batchNo, item.warehouseId, item.quantity]
          );
        }
      }
    });
  }
}

import { transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';
import type { DomainEvent } from '@/domain/shared/DomainTypes';

/**
 * 生产 → 财务联动处理器
 * 监听：workorder.closed
 * 功能：自动生成成本凭证
 */
export class ProductionFinanceHandler {
  async handle(event: DomainEvent): Promise<void> {
    const { workOrderId, workOrderNo } = event.payload as {
      workOrderId: number;
      workOrderNo: string;
    };

    secureLog('info', 'ProductionFinanceHandler: work order closed', {
      workOrderId,
      workOrderNo,
    });

    // 获取工单成本数据
    const [wo] = await transaction(async (conn) => {
      const [rows] = await conn.execute<any>(
        `SELECT total_material_cost, total_labor_cost, total_tool_cost,
                total_overhead_cost, unit_cost, finished_qty
         FROM prod_work_order WHERE id = ? AND deleted = 0`,
        [workOrderId]
      );
      return [rows?.[0]];
    });
    if (!wo) return;

    const totalCost =
      Number(wo.total_material_cost || 0) +
      Number(wo.total_labor_cost || 0) +
      Number(wo.total_tool_cost || 0) +
      Number(wo.total_overhead_cost || 0);

    // 生成成本凭证记录（使用 fin_receivable 表记录生产成本）
    const voucherNo = `COST${workOrderNo}${Date.now().toString().slice(-6)}`;
    await transaction(async (conn) => {
      await conn.execute(
        `INSERT INTO fin_receivable
         (receivable_no, source_type, source_no, amount, due_date, status, remark, create_time)
         VALUES (?, 3, ?, ?, NOW(), 1, ?, NOW())`,
        [voucherNo, workOrderNo, totalCost, `工单${workOrderNo}成本归集`]
      );
    });

    secureLog('info', 'ProductionFinanceHandler: cost voucher created', {
      workOrderNo,
      totalCost,
      voucherNo,
    });
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { InboundOrderApprovedEvent } from '@/domain/warehouse/events/InboundOrderEvents';
import { transaction } from '@/lib/db';
import { logger, secureLog } from '@/lib/logger';
import type { RowDataPacket } from 'mysql2';

interface PurchaseLineRow {
  id: number;
  line_no: number;
  material_id: number;
  order_qty: number;
  received_qty: number;
}

export class PurchaseInboundSyncHandler implements EventHandler<InboundOrderApprovedEvent> {
  async handle(event: InboundOrderApprovedEvent): Promise<void> {
    const { inboundId, inboundNo, poId, items } = event.payload;
    const ctx = { module: 'purchase-inbound', action: 'sync', inboundId, poId };
    let phase = 'init';

    if (!poId) {
      logger.info(ctx, '跳过：无采购订单关联', { inboundNo });
      return;
    }

    try {
      await transaction(async (conn) => {
        phase = 'load_po_lines';
        const [lineRows] = await conn.execute<RowDataPacket[]>(
          'SELECT id, line_no, material_id, order_qty, received_qty FROM pur_purchase_order_line WHERE po_id = ? FOR UPDATE',
          [poId]
        );

        if (!lineRows || lineRows.length === 0) {
          secureLog('warn', 'Purchase order lines not found for inbound sync', { poId, inboundNo });
          logger.warn(ctx, `采购订单行不存在 [phase=${phase}]`, { poId, inboundNo });
          return;
        }

        const lines = lineRows as unknown as PurchaseLineRow[];
        logger.info(ctx, '采购订单行加载完成', {
          poId,
          lineCount: lines.length,
          inboundItemCount: items.length,
        });
        let allFullyReceived = true;

        phase = 'update_received_qty';
        for (const item of items) {
          const line = lines.find((l) => l.material_id === item.materialId);
          if (!line) {
            secureLog('warn', 'Matching PO line not found for material', {
              poId,
              materialId: item.materialId,
              inboundNo,
            });
            logger.warn(ctx, '入库明细未匹配到采购行，跳过', {
              materialId: item.materialId,
              inboundQty: item.quantity,
            });
            continue;
          }

          const newReceivedQty = Number(line.received_qty) + item.quantity;
          logger.info(ctx, '准备更新采购行已收量', {
            lineId: line.id,
            materialId: item.materialId,
            oldReceived: Number(line.received_qty),
            inboundQty: item.quantity,
            newReceived: newReceivedQty,
            orderQty: Number(line.order_qty),
            paramCount: 2,
          });
          await conn.execute(
            'UPDATE pur_purchase_order_line SET received_qty = ?, update_time = NOW() WHERE id = ?',
            [newReceivedQty, line.id]
          );
          logger.info(ctx, `采购行已收量更新`, {
            lineId: line.id,
            materialId: item.materialId,
            oldReceived: Number(line.received_qty),
            inboundQty: item.quantity,
            newReceived: newReceivedQty,
            orderQty: Number(line.order_qty),
          });

          if (newReceivedQty < Number(line.order_qty)) {
            allFullyReceived = false;
          }
        }

        const notFullyReceivedLines: Array<{
          lineId: number;
          materialId: number;
          received: number;
          ordered: number;
        }> = [];
        for (const line of lines) {
          const notMatched = !items.some((i) => i.materialId === line.material_id);
          if (notMatched && Number(line.received_qty) < Number(line.order_qty)) {
            allFullyReceived = false;
            notFullyReceivedLines.push({
              lineId: line.id,
              materialId: line.material_id,
              received: Number(line.received_qty),
              ordered: Number(line.order_qty),
            });
          }
        }

        phase = 'update_po_status';
        const newStatus = allFullyReceived ? 50 : 40;
        logger.info(ctx, 'PO 状态决策', {
          poId,
          allFullyReceived,
          newStatus,
          notFullyReceivedLines: notFullyReceivedLines.length ? notFullyReceivedLines : undefined,
        });
        await conn.execute(
          'UPDATE pur_purchase_order SET status = ?, update_time = NOW() WHERE id = ? AND status IN (30, 40)',
          [newStatus, poId]
        );

        logger.info(ctx, `采购订单状态更新完成`, {
          poId,
          inboundNo,
          newStatus,
          allFullyReceived,
          itemCount: items.length,
        });
        secureLog('info', 'Purchase order synced from inbound approval', {
          poId,
          inboundNo,
          newStatus,
          allFullyReceived,
        });
      });
    } catch (err) {
      logger.error(ctx, `PurchaseInboundSync 失败 [phase=${phase}]`, {
        error: err instanceof Error ? err.message : String(err),
        inboundNo,
        poId,
      });
      throw err;
    }
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { PurchaseOrderReceivedEvent } from '@/domain/purchase/events/PurchaseOrderEvents';
import { transaction } from '@/lib/db';
import { logger, secureLog } from '@/lib/logger';

export class PurchasePayableHandler implements EventHandler<PurchaseOrderReceivedEvent> {
  async handle(event: PurchaseOrderReceivedEvent): Promise<void> {
    const { orderId, orderNo, supplierId, supplierName, receivedItems, totalReceivedAmount } =
      event.payload;
    const ctx = { module: 'purchase-payable', action: 'create', orderId, orderNo };
    let phase = 'init';

    if (totalReceivedAmount <= 0) {
      logger.info(ctx, '跳过：总收货金额为 0', { orderNo });
      return;
    }

    try {
      await transaction(async (conn) => {
        const periodCode = new Date().toISOString().slice(0, 7).replace('-', '');

        phase = 'insert_vouchers';
        for (const item of receivedItems) {
          const totalItemAmount = item.quantity * item.unitPrice;

          const voucherNo = 'FV' + Date.now() + String(item.materialId).slice(-4);
          await conn.execute(
            `INSERT INTO fin_voucher (voucher_no, period_code, voucher_date, voucher_type, source_type, source_id, source_no, total_debit, total_credit, total_amount, status, summary, create_time)
             VALUES (?, ?, CURDATE(), 2, 'purchase', ?, ?, ?, ?, ?, 0, ?, NOW())`,
            [
              voucherNo,
              periodCode,
              orderId,
              orderNo,
              totalItemAmount,
              totalItemAmount,
              totalItemAmount,
              `Purchase inbound ${orderNo} material ${item.materialName} qty ${item.quantity} batch ${item.batchNo}`,
            ]
          );
          logger.info(ctx, `凭证创建`, {
            voucherNo,
            materialId: item.materialId,
            materialName: item.materialName,
            quantity: item.quantity,
            unitPrice: item.unitPrice,
            totalItemAmount,
          });
        }

        phase = 'lookup_supplier';
        const [supplierRows]: Loose = await conn.execute(
          'SELECT id FROM pur_supplier WHERE id = ? AND deleted = 0 LIMIT 1',
          [supplierId]
        );
        const dbSupplierId = supplierRows.length > 0 ? supplierRows[0].id : null;
        if (supplierRows.length === 0) {
          logger.warn(ctx, `供应商不存在，应付账款将无关联供应商`, { supplierId, supplierName });
        }

        phase = 'insert_payable';
        const payableNo = 'AP' + Date.now();
        await conn.execute(
          `INSERT INTO fin_payable (payable_no, supplier_id, source_type, source_no, amount, paid_amount, balance, status, due_date, remark, create_time)
           VALUES (?, ?, 1, ?, ?, 0, ?, 1, DATE_ADD(CURDATE(), INTERVAL 30 DAY), ?, NOW())`,
          [
            payableNo,
            dbSupplierId,
            orderNo,
            totalReceivedAmount,
            totalReceivedAmount,
            `Purchase order ${orderNo} inbound auto-generated`,
          ]
        );
        logger.info(ctx, `应付账款创建完成`, {
          payableNo,
          supplierId: dbSupplierId,
          orderNo,
          totalReceivedAmount,
          voucherCount: receivedItems.length,
        });
      });

      secureLog('info', 'Payable created for purchase received', {
        orderNo,
        totalReceivedAmount,
      });
    } catch (err) {
      logger.error(ctx, `PurchasePayable 失败 [phase=${phase}]`, {
        error: err instanceof Error ? err.message : String(err),
        orderNo,
        totalReceivedAmount,
      });
      throw err;
    }
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { PurchaseOrderReceivedEvent } from '@/domain/purchase/events/PurchaseOrderEvents';
import { transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';

export class PurchaseReceivedHandler implements EventHandler<PurchaseOrderReceivedEvent> {
  async handle(event: PurchaseOrderReceivedEvent): Promise<void> {
    const { orderId, orderNo, receivedItems, totalReceivedAmount } = event.payload;

    await transaction(async (conn) => {
      for (const item of receivedItems) {
        const [existingInv]: Loose = await conn.execute(
          'SELECT id, quantity FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.materialId, item.warehouseId]
        );

        if (existingInv.length > 0) {
          await conn.execute(
            'UPDATE inv_inventory SET quantity = quantity + ?, update_time = NOW() WHERE id = ?',
            [item.quantity, existingInv[0].id]
          );
        } else {
          await conn.execute(
            `INSERT INTO inv_inventory (material_id, material_code, material_name, warehouse_id, quantity, unit, create_time)
             VALUES (?, ?, ?, ?, ?, '件', NOW())`,
            [item.materialId, item.materialCode, item.materialName, item.warehouseId, item.quantity]
          );
        }

        const [existingBatch]: Loose = await conn.execute(
          'SELECT id, available_qty, quantity FROM inv_inventory_batch WHERE batch_no = ? AND material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.batchNo, item.materialId, item.warehouseId]
        );

        if (existingBatch.length > 0) {
          await conn.execute(
            'UPDATE inv_inventory_batch SET available_qty = available_qty + ?, quantity = quantity + ?, update_time = NOW() WHERE id = ?',
            [item.quantity, item.quantity, existingBatch[0].id]
          );
        } else {
          await conn.execute(
            `INSERT INTO inv_inventory_batch (batch_no, material_id, material_name, warehouse_id, available_qty, quantity, unit_price, inbound_date, status, create_time)
             VALUES (?, ?, ?, ?, ?, ?, ?, CURDATE(), 1, NOW())`,
            [
              item.batchNo,
              item.materialId,
              item.materialName,
              item.warehouseId,
              item.quantity,
              item.quantity,
              item.unitPrice,
            ]
          );
        }

        const transNo = 'TRX' + Date.now() + String(item.materialId).slice(-4);
        await conn.execute(
          `INSERT INTO inv_inventory_transaction (trans_no, trans_type, source_type, source_id, material_id, material_code, batch_no, warehouse_id, quantity, unit_price, total_amount, create_time)
           VALUES (?, 'in', 'purchase', ?, ?, ?, ?, ?, ?, ?, ?, NOW())`,
          [
            transNo,
            orderId,
            item.materialId,
            item.materialCode,
            item.batchNo,
            item.warehouseId,
            item.quantity,
            item.unitPrice,
            item.quantity * item.unitPrice,
          ]
        );
      }
    });

    secureLog('info', 'Inventory updated for purchase received', {
      orderNo,
      itemCount: receivedItems.length,
      totalReceivedAmount,
    });
  }
}

import { EventHandler } from '@/infrastructure/event-bus/EventBus';
import { PurchaseReconciliationWrittenOffEvent } from '@/domain/purchase/events/PurchaseReconciliationEvents';
import { transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';

/**
 * 处理采购对账核销完成事件：
 * 1. 更新每张应付单的 paid_amount / balance / status
 * 2. 全额核销的应付单状态变为 3（已结清）
 * 3. 部分核销的应付单状态变为 2（部分付款）
 */
export class PurchaseReconciliationWrittenOffHandler implements EventHandler<PurchaseReconciliationWrittenOffEvent> {
  async handle(event: PurchaseReconciliationWrittenOffEvent): Promise<void> {
    const { reconciliationId, reconciliationNo, supplierId, totalWriteOffAmount, writeOffRecords } =
      event.payload;

    secureLog('info', '采购对账核销完成，更新应付单状态', {
      reconciliationId,
      reconciliationNo,
      supplierId,
      totalWriteOffAmount,
      payableCount: writeOffRecords.length,
    });

    await transaction(async (conn) => {
      for (const record of writeOffRecords) {
        // SELECT ... FOR UPDATE 锁定应付单行，防止并发核销导致 paid_amount/balance 丢失更新
        const [payableRow]: Loose[] = await conn.execute(
          `SELECT id, payable_no, amount, paid_amount, balance, status
           FROM fin_payable
           WHERE id = ?
           FOR UPDATE`,
          [record.payableId]
        );

        if (!payableRow || payableRow.length === 0) {
          secureLog('warn', '应付单不存在或已删除，跳过', {
            payableId: record.payableId,
            reconciliationNo,
          });
          continue;
        }

        const payable = payableRow[0];
        const currentPaid = Number(payable.paid_amount || 0);
        const currentBalance = Number(payable.balance || 0);

        let writeOffAmount = Number(record.amount);
        // 透支保护：并发核销可能导致应付单余额不足，截断为当前余额
        if (writeOffAmount > currentBalance && currentBalance > 0) {
          secureLog('warn', '核销金额超过应付单当前余额，截断为余额', {
            payableId: record.payableId,
            requestedAmount: writeOffAmount,
            currentBalance,
          });
          writeOffAmount = currentBalance;
        } else if (currentBalance <= 0) {
          secureLog('warn', '应付单余额已为0，跳过核销', {
            payableId: record.payableId,
            requestedAmount: writeOffAmount,
          });
          continue;
        }

        const newPaidAmount = Math.round((currentPaid + writeOffAmount) * 100) / 100;
        const newBalance = Math.round((currentBalance - writeOffAmount) * 100) / 100;

        let newStatus = Number(payable.status);
        if (newBalance <= 0.001) {
          newStatus = 3; // 已结清
        } else if (newPaidAmount > 0) {
          newStatus = 2; // 部分付款
        }

        await conn.execute(
          `UPDATE fin_payable
           SET paid_amount = ?, balance = ?, status = ?, update_time = NOW()
           WHERE id = ?`,
          [newPaidAmount, newBalance, newStatus, record.payableId]
        );

        secureLog('info', '更新应付单核销状态', {
          payableId: record.payableId,
          payableNo: payable.payable_no,
          writeOffAmount,
          newPaidAmount,
          newBalance,
          newStatus,
        });
      }
    });

    secureLog('info', '采购对账核销完成处理结束', {
      reconciliationId,
      reconciliationNo,
      processedCount: writeOffRecords.length,
    });
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { ReconciliationWrittenOffEvent } from '@/domain/sales/events/ReconciliationEvents';
import { transaction } from '@/lib/db';
import { logger, secureLog } from '@/lib/logger';

/**
 * 处理销售对账核销完成事件：
 * 1. 更新每张应收单的 received_amount / balance / status
 * 2. 全额核销的应收单状态变为 3（已结清）
 * 3. 部分核销的应收单状态变为 2（部分收款）
 *
 * T306: 修复此前仅记录日志、未实际更新 fin_receivable 的缺陷。
 * 镜像 PurchaseReconciliationWrittenOffHandler 的实现模式（FOR UPDATE 锁 + 透支保护）。
 */
export class ReconciliationWriteOffHandler implements EventHandler<ReconciliationWrittenOffEvent> {
  async handle(event: ReconciliationWrittenOffEvent): Promise<void> {
    const { reconciliationId, reconciliationNo, customerId, totalWriteOffAmount, writeOffRecords } =
      event.payload;
    const ctx = {
      module: 'reconciliation-writeoff',
      action: 'sync',
      reconciliationId,
      reconciliationNo,
    };

    if (!writeOffRecords || writeOffRecords.length === 0) {
      logger.info(ctx, '跳过：无核销记录', { reconciliationNo });
      return;
    }

    secureLog('info', 'Reconciliation write-off started', {
      reconciliationNo,
      customerId,
      totalWriteOffAmount,
      recordCount: writeOffRecords.length,
    });

    await transaction(async (conn) => {
      for (const record of writeOffRecords) {
        // SELECT ... FOR UPDATE 锁定应收单行，防止并发核销导致 received_amount/balance 丢失更新
        const [receivableRow]: Loose = await conn.execute(
          `SELECT id, receivable_no, amount, received_amount, balance, status
           FROM fin_receivable
           WHERE id = ?
           FOR UPDATE`,
          [record.receivableId]
        );

        if (!receivableRow || receivableRow.length === 0) {
          secureLog('warn', '应收单不存在或已删除，跳过', {
            receivableId: record.receivableId,
            reconciliationNo,
          });
          continue;
        }

        const receivable = receivableRow[0];
        const currentReceived = Number(receivable.received_amount || 0);
        const currentBalance = Number(receivable.balance || 0);

        let writeOffAmount = Number(record.amount);
        // 透支保护：并发核销可能导致应收单余额不足，截断为当前余额
        if (writeOffAmount > currentBalance && currentBalance > 0) {
          secureLog('warn', '核销金额超过应收单当前余额，截断为余额', {
            receivableId: record.receivableId,
            requestedAmount: writeOffAmount,
            currentBalance,
          });
          writeOffAmount = currentBalance;
        } else if (currentBalance <= 0) {
          secureLog('warn', '应收单余额已为0，跳过核销', {
            receivableId: record.receivableId,
            requestedAmount: writeOffAmount,
          });
          continue;
        }

        const newReceivedAmount = Math.round((currentReceived + writeOffAmount) * 100) / 100;
        const newBalance = Math.round((currentBalance - writeOffAmount) * 100) / 100;

        let newStatus = Number(receivable.status);
        if (newBalance <= 0.001) {
          newStatus = 3; // 已结清
        } else if (newReceivedAmount > 0) {
          newStatus = 2; // 部分收款
        }

        await conn.execute(
          `UPDATE fin_receivable
           SET received_amount = ?, balance = ?, status = ?, update_time = NOW()
           WHERE id = ?`,
          [newReceivedAmount, newBalance, newStatus, record.receivableId]
        );

        secureLog('info', '更新应收单核销状态', {
          receivableId: record.receivableId,
          receivableNo: receivable.receivable_no,
          writeOffAmount,
          newReceivedAmount,
          newBalance,
          newStatus,
        });
      }
    });

    secureLog('info', 'Reconciliation write-off completed', {
      reconciliationId,
      reconciliationNo,
      processedCount: writeOffRecords.length,
    });

    logger.info(ctx, '对账核销完成，应收单已同步更新', {
      reconciliationNo,
      totalWriteOffAmount,
      recordCount: writeOffRecords.length,
    });
  }
}

import { execute } from '@/lib/db';
import { secureLog } from '@/lib/logger';
import type { DomainEvent } from '@/domain/shared/DomainTypes';

/**
 * 退料单审核后的库存联动处理器
 * 监听：prod.return.approved
 * 功能：增加原材料库存（退库）
 */
export class ReturnOrderInventoryHandler {
  async handle(event: DomainEvent): Promise<void> {
    const { returnOrderId, items } = event.payload as {
      returnOrderId: number;
      items: Array<{
        materialId: number;
        quantity: number;
        batchNo: string;
        warehouseId: number;
      }>;
    };

    secureLog('info', 'ReturnOrderInventoryHandler: processing return order approval', {
      returnOrderId,
      itemCount: items.length,
    });

    for (const item of items) {
      const transNo = `RT${Date.now()}${String(item.materialId).slice(-4)}`;

      const existing = await execute(
        'SELECT id FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0',
        [item.materialId, item.warehouseId]
      );

      if ((existing as any).length > 0) {
        await execute(
          `UPDATE inv_inventory SET quantity = quantity + ?,
           available_qty = available_qty + ?, update_time = NOW()
           WHERE material_id = ? AND warehouse_id = ? AND deleted = 0`,
          [item.quantity, item.quantity, item.materialId, item.warehouseId]
        );
      } else {
        await execute(
          `INSERT INTO inv_inventory
           (material_id, warehouse_id, quantity, available_qty, unit, create_time)
           VALUES (?, ?, ?, ?, '件', NOW())`,
          [item.materialId, item.warehouseId, item.quantity, item.quantity]
        );
      }

      await execute(
        `INSERT INTO inv_inventory_transaction
         (trans_no, trans_type, source_type, source_id, material_id, batch_no, warehouse_id, quantity, create_time)
         VALUES (?, 'in', 'prod_return', ?, ?, ?, ?, ?, NOW())`,
        [transNo, returnOrderId, item.materialId, item.batchNo, item.warehouseId, item.quantity]
      );
    }
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { SalesOrderShippedEvent } from '@/domain/sales/events/SalesOrderEvents';
import { transaction } from '@/lib/db';
import { logger, secureLog } from '@/lib/logger';

export class SalesReceivableHandler implements EventHandler<SalesOrderShippedEvent> {
  async handle(event: SalesOrderShippedEvent): Promise<void> {
    const { orderId, orderNo, customerId, totalShippedAmount } = event.payload;
    const ctx = { module: 'sales-receivable', action: 'create', orderId, orderNo };
    let phase = 'init';

    if (totalShippedAmount <= 0) {
      logger.info(ctx, '跳过：出库金额为 0', { orderNo });
      return;
    }

    try {
      let created = false;
      await transaction(async (conn) => {
        phase = 'check_duplicate';
        const receivableNo = 'AR' + Date.now();
        logger.info(ctx, '开始处理应收账款创建', { receivableNo, customerId, totalShippedAmount });
        const [existing]: Loose = await conn.execute(
          'SELECT id FROM fin_receivable WHERE source_no = ? AND deleted = 0 LIMIT 1',
          [orderNo]
        );
        if (existing && existing.length > 0) {
          secureLog('info', 'Receivable already exists for sales order, skip', {
            orderNo,
            orderId,
          });
          logger.info(ctx, `跳过：应收账款已存在`, { orderNo, existingId: existing[0].id });
          return;
        }
        logger.info(ctx, '无重复记录，准备创建应收账款', { orderNo, receivableNo });

        phase = 'insert_receivable';
        const insertParams = [
          receivableNo,
          customerId,
          orderNo,
          totalShippedAmount,
          totalShippedAmount,
          `Sales order ${orderNo} outbound auto-generated`,
        ];
        logger.info(ctx, 'INSERT fin_receivable 参数详情', {
          paramCount: insertParams.length,
          params: insertParams,
        });
        await conn.execute(
          `INSERT INTO fin_receivable
           (receivable_no, customer_id, source_type, source_no, amount, received_amount, balance, status, due_date, remark, create_time)
           VALUES (?, ?, 1, ?, ?, 0, ?, 1, DATE_ADD(CURDATE(), INTERVAL 30 DAY), ?, NOW())`,
          insertParams
        );
        created = true;
        logger.info(ctx, `应收账款创建完成`, {
          receivableNo,
          customerId,
          orderNo,
          totalShippedAmount,
        });
      });

      if (created) {
        secureLog('info', 'Receivable created for sales shipment', { orderNo, totalShippedAmount });
        logger.info(ctx, '应收账款流程成功结束', { orderNo, totalShippedAmount });
      } else {
        logger.info(ctx, '应收账款流程跳过（未创建）', { orderNo });
      }
    } catch (err) {
      logger.error(ctx, `SalesReceivable 失败 [phase=${phase}]`, {
        error: err instanceof Error ? err.message : String(err),
        orderNo,
        totalShippedAmount,
      });
      throw err;
    }
  }
}

import { EventHandler } from '../../infrastructure/event-bus/EventBus';
import { SalesOrderShippedEvent } from '@/domain/sales/events/SalesOrderEvents';
import { transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';

export class SalesShippedHandler implements EventHandler<SalesOrderShippedEvent> {
  async handle(event: SalesOrderShippedEvent): Promise<void> {
    const { orderId, orderNo, shippedItems } = event.payload;

    await transaction(async (conn) => {
      for (const item of shippedItems) {
        const [existingInv]: Loose = await conn.execute(
          'SELECT id, quantity FROM inv_inventory WHERE material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.materialId, item.warehouseId]
        );

        if (existingInv.length > 0) {
          const currentQty = parseFloat(existingInv[0].quantity);
          if (currentQty < item.quantity) {
            throw new Error(
              `物料${item.materialName}库存不足: 当前${currentQty}, 需要出库${item.quantity}`
            );
          }
          await conn.execute(
            'UPDATE inv_inventory SET quantity = quantity - ?, update_time = NOW() WHERE id = ?',
            [item.quantity, existingInv[0].id]
          );
        }

        const [existingBatch]: Loose = await conn.execute(
          'SELECT id, available_qty, quantity FROM inv_inventory_batch WHERE batch_no = ? AND material_id = ? AND warehouse_id = ? AND deleted = 0 FOR UPDATE',
          [item.batchNo, item.materialId, item.warehouseId]
        );

        if (existingBatch.length > 0) {
          const newAvailableQty = parseFloat(existingBatch[0].available_qty) - item.quantity;
          const newQty = parseFloat(existingBatch[0].quantity) - item.quantity;
          if (newAvailableQty <= 0 || newQty <= 0) {
            await conn.execute(
              'UPDATE inv_inventory_batch SET deleted = 1, update_time = NOW() WHERE id = ?',
              [existingBatch[0].id]
            );
          } else {
            await conn.execute(
              'UPDATE inv_inventory_batch SET available_qty = available_qty - ?, quantity = quantity - ?, update_time = NOW() WHERE id = ?',
              [item.quantity, item.quantity, existingBatch[0].id]
            );
          }
        }

        const transNo = 'TRX' + Date.now() + String(item.materialId).slice(-4);
        await conn.execute(
          `INSERT INTO inv_inventory_transaction (trans_no, trans_type, source_type, source_id, material_id, material_code, batch_no, warehouse_id, quantity, unit_price, total_amount, create_time)
           VALUES (?, 'out', 'sales', ?, ?, ?, ?, ?, ?, ?, ?, NOW())`,
          [
            transNo,
            orderId,
            item.materialId,
            item.materialCode,
            item.batchNo,
            item.warehouseId,
            item.quantity,
            item.unitPrice,
            item.quantity * item.unitPrice,
          ]
        );
      }
    });

    secureLog('info', 'Inventory deducted for sales shipment', {
      orderNo,
      itemCount: shippedItems.length,
    });
  }
}

import { EventHandler } from '@/infrastructure/event-bus/EventBus';
import { SalesOrderApprovedEvent } from '@/domain/sales/events/SalesOrderEvents';
import { WorkOrderCreatedEvent } from '@/domain/production/events/WorkOrderEvents';
import { query, transaction } from '@/lib/db';
import { getDomainEventOutbox } from '@/infrastructure/event-bus/DomainEventOutboxFactory';
import { secureLog } from '@/lib/logger';

export interface MaterialRequirementItem {
  materialId: number;
  materialCode: string;
  materialName: string;
  requiredQty: number;
  unit: string;
}

export interface WorkOrderCreationResult {
  workOrderId: number;
  workOrderNo: string;
  productName: string;
  plannedQty: number;
  materialCount: number;
}

export class SalesToWorkOrderHandler implements EventHandler<SalesOrderApprovedEvent> {
  async handle(event: SalesOrderApprovedEvent): Promise<void> {
    const {
      orderId,
      orderNo,
      customerId,
      customerName,
      lines,
      totalAmount: _totalAmount,
    } = event.payload;

    secureLog('info', 'Sales order approved, processing work order creation', {
      orderId,
      orderNo,
      lineCount: lines.length,
    });

    const workOrders: WorkOrderCreationResult[] = [];

    for (const line of lines) {
      try {
        const result = await this.createWorkOrderFromSalesLine({
          orderId,
          orderNo,
          customerId,
          customerName,
          materialId: line.materialId,
          materialCode: line.materialCode,
          materialName: line.materialName,
          requiredQty: line.orderQty,
          unitPrice: line.unitPrice,
        });

        if (result) {
          workOrders.push(result);
        }
      } catch (error) {
        secureLog('error', 'Failed to create work order from sales line', {
          orderNo,
          materialCode: line.materialCode,
          error: String(error),
        });
      }
    }

    secureLog('info', 'Work order creation completed', {
      orderNo,
      totalWorkOrders: workOrders.length,
      workOrders: workOrders.map((wo) => ({
        workOrderNo: wo.workOrderNo,
        productName: wo.productName,
      })),
    });
  }

  private async createWorkOrderFromSalesLine(params: {
    orderId: number;
    orderNo: string;
    customerId: number;
    customerName: string;
    materialId: number;
    materialCode: string;
    materialName: string;
    requiredQty: number;
    unitPrice: number;
  }): Promise<WorkOrderCreationResult | null> {
    const { orderId, orderNo, materialId, materialName, requiredQty } = params;

    const workOrderNo = this.generateWorkOrderNo();
    const today = new Date().toISOString().slice(0, 10);
    const endDate = this.calculateEndDate(requiredQty);

    const materialRequirements = await this.getMaterialRequirements(materialId, requiredQty);

    const workOrderId = await transaction(async (conn) => {
      const [result] = await conn.execute(
        `INSERT INTO prd_work_order (
          work_order_no, work_order_date, sales_order_id, material_id,
          plan_qty, completed_qty, unit,
          plan_start_date, plan_end_date,
          priority, status, remark, create_by
        ) VALUES (?, ?, ?, ?, ?, 0, ?, ?, ?, 2, 1, ?, ?)`,
        [
          workOrderNo,
          today,
          orderId,
          materialId,
          requiredQty,
          '件',
          today,
          endDate,
          `由销售订单 ${orderNo} 生成`,
          0,
        ]
      );

      const woId = (result as Loose).insertId;

      await getDomainEventOutbox().saveEvents(conn, 'WorkOrder', woId, [
        new WorkOrderCreatedEvent({
          workOrderId: woId,
          workOrderNo,
          productId: materialId,
          productName: materialName,
          plannedQty: requiredQty,
        }),
      ]);

      return woId;
    });

    return {
      workOrderId,
      workOrderNo,
      productName: materialName,
      plannedQty: requiredQty,
      materialCount: materialRequirements.length,
    };
  }

  private generateWorkOrderNo(): string {
    const date = new Date();
    const dateStr = date.toISOString().slice(0, 10).replace(/-/g, '');
    return `WO${dateStr}${String(date.getTime()).slice(-6)}`;
  }

  private async getMaterialRequirements(
    productId: number,
    plannedQty: number
  ): Promise<MaterialRequirementItem[]> {
    const bomRows = (await query(
      `SELECT bd.material_id, m.material_code, m.material_name, bd.quantity, bd.unit
       FROM prd_bom_detail bd
       LEFT JOIN inv_material m ON m.id = bd.material_id
       WHERE bd.bom_id IN (SELECT id FROM prd_bom WHERE product_id = ? AND status = 1)`,
      [productId]
    )) as Loose[];

    if (bomRows.length === 0) {
      return [];
    }

    return bomRows.map((row) => ({
      materialId: row.material_id,
      materialCode: row.material_code,
      materialName: row.material_name,
      requiredQty: row.quantity * plannedQty,
      unit: row.unit || '件',
    }));
  }

  private calculateEndDate(plannedQty: number): string {
    const days = Math.ceil(plannedQty / 100);
    const endDate = new Date();
    endDate.setDate(endDate.getDate() + Math.min(days, 30));
    return endDate.toISOString().slice(0, 10);
  }
}

