import { EventHandler } from '@/infrastructure/event-bus/EventBus';
import { WorkOrderCompletedEvent } from '@/domain/production/events/WorkOrderEvents';
import { transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';
import { InventoryCostService } from '@/application/services/InventoryCostService';

const costService = new InventoryCostService();

/**
 * 处理工单完工事件：成品入库（增加库存）
 * - inv_inventory.quantity / available_qty 增加（不存在则创建）
 * - inv_inventory_batch 创建新批次
 * - inv_inventory_transaction 记录入库流水
 */
export class WorkOrderCompletedHandler implements EventHandler<WorkOrderCompletedEvent> {
  async handle(event: WorkOrderCompletedEvent): Promise<void> {
    const { workOrderId, workOrderNo, productId, productName, completedQty, warehouseId } =
      event.payload;

    if (completedQty <= 0) return;

    const batchNo = `WO${workOrderNo}${Date.now().toString().slice(-6)}`;
    const today = new Date().toISOString().slice(0, 10);

    await transaction(async (conn) => {
      const [invRows] = await conn.execute(
        `SELECT id, quantity, available_qty, unit
         FROM inv_inventory
         WHERE material_id = ? AND warehouse_id = ?
         FOR UPDATE`,
        [productId, warehouseId]
      ) as any;

      let materialCode = '';
      let unit = '件';

      const [matRows] = await conn.execute(
        `SELECT material_code, unit FROM inv_material WHERE id = ?`,
        [productId]
      ) as any;
      if (matRows.length > 0) {
        materialCode = matRows[0].material_code || '';
        unit = matRows[0].unit || '件';
      }

      if (invRows.length > 0) {
        const inv = invRows[0];
        await conn.execute(
          `UPDATE inv_inventory
           SET quantity = quantity + ?, available_qty = available_qty + ?, update_time = NOW()
           WHERE id = ?`,
          [completedQty, completedQty, inv.id]
        );
        unit = inv.unit || unit;
      } else {
        const [newInv] = await conn.execute(
          `INSERT INTO inv_inventory
             (material_id, material_code, material_name, warehouse_id, quantity, available_qty, unit, create_time)
           VALUES (?, ?, ?, ?, ?, ?, ?, NOW())`,
          [productId, materialCode, productName, warehouseId, completedQty, completedQty, unit]
        );
        const newInvId = (newInv as unknown as { insertId: number }).insertId;
        await costService.onInbound(conn, newInvId, completedQty, 0);
      }

      await conn.execute(
        `INSERT INTO inv_inventory_batch
           (material_id, material_name, batch_no, quantity, available_qty, warehouse_id, inbound_date, status, create_time)
         VALUES (?, ?, ?, ?, ?, ?, ?, 1, NOW())`,
        [productId, productName, batchNo, completedQty, completedQty, warehouseId, today]
      );

      const transNo = 'TRX' + Date.now() + String(productId).slice(-4);
      await conn.execute(
        `INSERT INTO inv_inventory_transaction
           (trans_no, trans_type, source_type, source_id, material_id, material_code, batch_no, warehouse_id, quantity, create_time)
         VALUES (?, 'in', 'workorder_completion', ?, ?, ?, ?, ?, ?, NOW())`,
        [transNo, workOrderId, productId, materialCode, batchNo, warehouseId, completedQty]
      );
    });

    secureLog('info', '工单完工入库完成', {
      workOrderNo,
      workOrderId,
      productId,
      productName,
      completedQty,
      warehouseId,
      batchNo,
    });
  }
}

import { EventHandler } from '@/infrastructure/event-bus/EventBus';
import { WorkOrderMaterialIssuedEvent } from '@/domain/production/events/WorkOrderEvents';
import { transaction } from '@/lib/db';
import { logger, secureLog } from '@/lib/logger';

/**
 * 处理工单领料事件：扣减库存
 * - inv_inventory.quantity / available_qty 减少
 * - inv_inventory_batch.available_qty / quantity 减少
 * - inv_inventory_transaction 记录出库流水
 */
export class WorkOrderMaterialIssuedHandler implements EventHandler<WorkOrderMaterialIssuedEvent> {
  async handle(event: WorkOrderMaterialIssuedEvent): Promise<void> {
    const { workOrderId, workOrderNo, issuedItems } = event.payload;
    const ctx = { module: 'work-order-issue', action: 'deduct', workOrderId, workOrderNo };
    let phase = 'init';

    if (!issuedItems || issuedItems.length === 0) {
      logger.info(ctx, '跳过：无领料明细', { workOrderNo });
      return;
    }

    try {
      await transaction(async (conn) => {
        for (const item of issuedItems) {
          phase = 'load_inventory';
          const [invRows] = await conn.execute(
            `SELECT id, quantity, available_qty
             FROM inv_inventory
             WHERE material_id = ? AND warehouse_id = ? AND deleted = 0
             FOR UPDATE`,
            [item.materialId, item.warehouseId]
          ) as any;

          if (invRows.length === 0) {
            secureLog('warn', '领料失败：库存记录不存在，跳过', {
              workOrderNo,
              materialId: item.materialId,
              warehouseId: item.warehouseId,
            });
            logger.warn(ctx, `库存记录不存在，跳过 [phase=${phase}]`, {
              materialId: item.materialId,
              materialName: item.materialName,
              warehouseId: item.warehouseId,
            });
            continue;
          }

          const inv = invRows[0];
          const currentQty = Number(inv.quantity || 0);

          if (currentQty < item.quantity) {
            throw new Error(
              `物料${item.materialName}库存不足: 当前${currentQty}, 需领${item.quantity}`
            );
          }

          phase = 'update_inventory';
          await conn.execute(
            `UPDATE inv_inventory
             SET quantity = quantity - ?, available_qty = available_qty - ?, update_time = NOW()
             WHERE id = ?`,
            [item.quantity, item.quantity, inv.id]
          );
          logger.info(ctx, `库存扣减`, {
            inventoryId: inv.id,
            materialId: item.materialId,
            materialName: item.materialName,
            deductQty: item.quantity,
            oldQty: currentQty,
            newQty: currentQty - item.quantity,
          });

          if (item.batchNo) {
            phase = 'update_batch';
            const [batchRows] = await conn.execute(
              `SELECT id, available_qty, quantity
               FROM inv_inventory_batch
               WHERE batch_no = ? AND material_id = ? AND warehouse_id = ?
               FOR UPDATE`,
              [item.batchNo, item.materialId, item.warehouseId]
            ) as any;

            if (batchRows.length > 0) {
              const batch = batchRows[0];
              const newAvail = Number(batch.available_qty || 0) - item.quantity;
              const newQty = Number(batch.quantity || 0) - item.quantity;

              if (newAvail <= 0 || newQty <= 0) {
                await conn.execute(
                  `UPDATE inv_inventory_batch SET available_qty = 0, quantity = 0, status = 3, update_time = NOW() WHERE id = ?`,
                  [batch.id]
                );
                logger.info(ctx, `批次清零`, { batchId: batch.id, batchNo: item.batchNo });
              } else {
                await conn.execute(
                  `UPDATE inv_inventory_batch SET available_qty = available_qty - ?, quantity = quantity - ?, update_time = NOW() WHERE id = ?`,
                  [item.quantity, item.quantity, batch.id]
                );
                logger.info(ctx, `批次扣减`, {
                  batchId: batch.id,
                  batchNo: item.batchNo,
                  deductQty: item.quantity,
                });
              }
            }
          }

          phase = 'insert_transaction';
          const transNo = 'TRX' + Date.now() + String(item.materialId).slice(-4);
          await conn.execute(
            `INSERT INTO inv_inventory_transaction
               (trans_no, trans_type, source_type, source_id, material_id, material_code, batch_no, warehouse_id, quantity, create_time)
             VALUES (?, 'out', 'material_issue', ?, ?, ?, ?, ?, ?, NOW())`,
            [
              transNo,
              workOrderId,
              item.materialId,
              item.materialCode,
              item.batchNo || '',
              item.warehouseId,
              -item.quantity,
            ]
          );
          logger.info(ctx, `出库流水记录`, {
            transNo,
            materialId: item.materialId,
            quantity: -item.quantity,
          });
        }
      });

      secureLog('info', '工单领料库存扣减完成', {
        workOrderNo,
        workOrderId,
        itemCount: issuedItems.length,
      });
      logger.info(ctx, `领料完成`, { workOrderNo, itemCount: issuedItems.length });
    } catch (err) {
      logger.error(ctx, `WorkOrderMaterialIssued 失败 [phase=${phase}]`, {
        error: err instanceof Error ? err.message : String(err),
        workOrderNo,
        issuedItems,
      });
      throw err;
    }
  }
}

import type { ICurrencyService } from '@/domain/shared/CurrencyService';
import { Money } from '@/domain/shared/value-objects/Money';
import { NotFoundError } from '@/domain/shared/DomainTypes';
import { logger } from '@/lib/logger';

// 内存缓存（无 Redis 时降级使用；多实例部署需替换为 Redis 实现）
const memoryCache = new Map<string, { value: number; expiresAt: number }>();
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 分钟

export class CurrencyApplicationService {
  constructor(private currencyService: ICurrencyService) {}

  /**
   * 获取最新汇率，带缓存（TTL 5分钟）
   * 无 Redis 时降级为内存缓存
   */
  async getLatestRate(from: string, to: string): Promise<number> {
    if (from === to) return 1;

    const cacheKey = `rate:${from}:${to}`;
    const cached = memoryCache.get(cacheKey);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    const rate = await this.currencyService.getLatestRate(from, to);
    if (!rate) {
      throw new NotFoundError(`汇率未配置: ${from}→${to}，请先在汇率管理中录入`);
    }

    memoryCache.set(cacheKey, { value: rate.rate, expiresAt: Date.now() + CACHE_TTL_MS });
    return rate.rate;
  }

  /**
   * 换算金额为本位币
   */
  async convertToBaseCurrency(money: Money, baseCurrency: string): Promise<Money> {
    if (money.currency === baseCurrency) return money;

    const rate = await this.getLatestRate(money.currency, baseCurrency);
    const target = await this.currencyService.getCurrency(baseCurrency);
    if (!target) {
      throw new NotFoundError(`本位币 ${baseCurrency} 未配置`);
    }
    const decimalPlaces = target.decimalPlaces;

    logger.info({ module: 'Currency', action: 'convertToBaseCurrency' }, '汇率换算', {
      from: money.currency,
      to: baseCurrency,
      rate,
      amount: money.amount,
    });

    return money.convertTo(rate, baseCurrency, decimalPlaces);
  }

  /**
   * 清除汇率缓存（录入新汇率后调用）
   */
  clearCache(): void {
    memoryCache.clear();
  }
}

/**
 * 清除汇率缓存（供 API 路由在录入/删除汇率后调用）
 */
export function clearExchangeRateCache(): void {
  memoryCache.clear();
}

import { IInboundOrderRepository } from '@/domain/warehouse/repositories/IInboundOrderRepository';
import { InboundOrder, InboundOrderProps } from '@/domain/warehouse/aggregates/InboundOrder';
import { IPurchaseOrderRepository } from '@/domain/purchase/repositories/IPurchaseOrderRepository';
import { DomainError, NotFoundError, VersionConflictError } from '@/domain/shared/DomainTypes';
import { CurrencyApplicationService } from './CurrencyApplicationService';
import { CurrencySnapshot } from '@/domain/shared/value-objects/CurrencySnapshot';
import { Money } from '@/domain/shared/value-objects/Money';
import { getSystemConfig } from '@/lib/system-config';
import { getDomainEventOutbox } from '@/infrastructure/event-bus/DomainEventOutboxFactory';
import { query, transaction } from '@/lib/db';
import type { ResultSetHeader } from 'mysql2/promise';

export interface CreateInboundFromPOParams {
  poId: number;
  warehouseId: number;
  items: Array<{
    lineNo: number;
    materialId: number;
    materialCode?: string;
    materialName: string;
    materialSpec?: string;
    unit: string;
    batchNo: string;
    quantity: number;
    unitPrice: number;
    warehouseLocation?: string;
    produceDate?: string;
  }>;
}

export class InboundApplicationService {
  constructor(
    private readonly orderRepo: IInboundOrderRepository,
    private readonly currencyService: CurrencyApplicationService,
    private readonly purchaseRepo?: IPurchaseOrderRepository
  ) {}

  async getOrderById(id: number): Promise<InboundOrder> {
    const order = await this.orderRepo.findById(id);
    if (!order) {
      throw new NotFoundError('入库单不存在');
    }
    return order;
  }

  async listOrders(
    status: string,
    page: number,
    pageSize: number,
    filters?: { keyword?: string; startDate?: string; endDate?: string }
  ) {
    return this.orderRepo.findByStatus(status, { page, pageSize }, filters);
  }

  async createOrder(props: InboundOrderProps): Promise<{ id: number; orderNo: string }> {
    const baseCurrency = await getSystemConfig('finance.base_currency', 'CNY');
    const currency = props.currency || 'CNY';
    let exchangeRate = props.exchangeRate || 1.0;
    if (currency !== baseCurrency) {
      exchangeRate = await this.currencyService.getLatestRate(currency, baseCurrency);
    }

    const computedTotalAmount = props.items.reduce(
      (sum, item) => sum + item.quantity * item.unitPrice,
      0
    );
    const snapshot = CurrencySnapshot.create(currency, exchangeRate, baseCurrency);
    const baseTotalAmount =
      Math.round(snapshot.convert(Money.create(computedTotalAmount, currency)).amount * 100) / 100;

    const order = InboundOrder.create({
      ...props,
      currency,
      exchangeRate,
      baseCurrency,
      baseTotalAmount,
    });
    const result = await this.orderRepo.save(order);

    if (order.id) {
      await this.persistAndPublishEvents(order.id, order);
    }

    return result;
  }

  async createInboundFromPO(
    params: CreateInboundFromPOParams
  ): Promise<{ id: number; orderNo: string }> {
    if (!this.purchaseRepo) {
      throw new DomainError('采购单仓储未注入，无法从采购单创建入库单');
    }

    const purchaseOrder = await this.purchaseRepo.findById(params.poId);
    if (!purchaseOrder) {
      throw new NotFoundError('采购单不存在');
    }

    const status = purchaseOrder.status.value;
    if (status !== 'approved' && status !== 'partially_received') {
      throw new DomainError(`采购单当前状态"${purchaseOrder.status.label()}"不允许创建入库单`);
    }

    for (const item of params.items) {
      const line = purchaseOrder.lines.find((l) => l.lineNo === item.lineNo);
      if (!line) {
        throw new DomainError(`采购单行号${item.lineNo}不存在`);
      }
      if (item.materialId !== line.materialId) {
        throw new DomainError(
          `行号${item.lineNo}物料ID不匹配: 采购单${line.materialId} vs 入库${item.materialId}`
        );
      }
      if (item.quantity > line.remainingQty) {
        throw new DomainError(
          `行号${item.lineNo}入库数量${item.quantity}超过剩余可收数量${line.remainingQty}`
        );
      }
    }

    const baseCurrency = await getSystemConfig('finance.base_currency', 'CNY');
    const currency = purchaseOrder.currency || 'CNY';
    let exchangeRate = purchaseOrder.exchangeRate || 1.0;
    if (currency !== baseCurrency) {
      exchangeRate = await this.currencyService.getLatestRate(currency, baseCurrency);
    }

    const computedTotalAmount = params.items.reduce(
      (sum, item) => sum + item.quantity * item.unitPrice,
      0
    );
    const snapshot = CurrencySnapshot.create(currency, exchangeRate, baseCurrency);
    const baseTotalAmount =
      Math.round(snapshot.convert(Money.create(computedTotalAmount, currency)).amount * 100) / 100;

    const props: InboundOrderProps = {
      warehouseId: params.warehouseId,
      supplierId: purchaseOrder.supplierId,
      supplierName: purchaseOrder.supplierName,
      poId: purchaseOrder.id,
      poNo: purchaseOrder.orderNo,
      orderType: 'purchase',
      currency,
      exchangeRate,
      baseCurrency,
      baseTotalAmount,
      items: params.items.map((item) => ({
        materialId: item.materialId,
        materialCode: item.materialCode || '',
        materialName: item.materialName,
        materialSpec: item.materialSpec,
        batchNo: item.batchNo,
        quantity: item.quantity,
        unit: item.unit,
        unitPrice: item.unitPrice,
        warehouseLocation: item.warehouseLocation,
        produceDate: item.produceDate,
      })),
    };

    const order = InboundOrder.create(props);
    const result = await this.orderRepo.save(order);

    if (order.id) {
      await this.persistAndPublishEvents(order.id, order);
    }

    return result;
  }

  async approveOrder(id: number): Promise<{ id: number; status: string }> {
    const order = await this.getOrderById(id);

    const warehouseRows = await query('SELECT warehouse_name FROM inv_warehouse WHERE id = ?', [
      order.warehouseId,
    ]);
    const warehouseName = warehouseRows?.[0]?.warehouse_name || '';

    const previousStatus = order.status.value;

    if (previousStatus === 'draft') {
      order.submit();
    }

    order.approve(warehouseName);

    await transaction(async (conn) => {
      const whereStatus = previousStatus === 'completed' ? 'approved' : previousStatus;
      const [result] = (await conn.execute(
        "UPDATE inv_inbound_order SET status = 'approved', update_time = NOW() WHERE id = ? AND status = ?",
        [id, whereStatus]
      )) as [ResultSetHeader, any];
      if (result.affectedRows === 0) {
        throw new VersionConflictError();
      }

      await conn.execute(
        "UPDATE inv_inbound_order SET qc_status = 'pass', update_time = NOW() WHERE id = ?",
        [id]
      );

      const events = order.getDomainEvents();
      await getDomainEventOutbox().saveEvents(conn, 'InboundOrder', id, events);
    });

    order.clearDomainEvents();

    return { id, status: 'completed' };
  }

  async submitOrder(id: number): Promise<{ id: number; status: string }> {
    const order = await this.getOrderById(id);

    const previousStatus = order.status.value;
    order.submit();

    const updated = await this.orderRepo.updateStatus(id, 'pending', previousStatus);
    if (!updated) {
      throw new VersionConflictError();
    }

    await this.persistAndPublishEvents(id, order);

    return { id, status: 'pending' };
  }

  async cancelOrder(id: number): Promise<{ id: number; status: string }> {
    const order = await this.getOrderById(id);

    const previousStatus = order.status.value;
    order.cancel();

    const updated = await this.orderRepo.updateStatus(id, 'cancelled', previousStatus);
    if (!updated) {
      throw new VersionConflictError();
    }

    await this.persistAndPublishEvents(id, order);

    return { id, status: 'cancelled' };
  }

  async deleteOrder(id: number): Promise<void> {
    const order = await this.getOrderById(id);

    if (!order.canDelete()) {
      throw new DomainError('当前状态的入库单不能删除');
    }

    await this.orderRepo.softDelete(id);
  }

  async unapproveOrder(id: number): Promise<{ id: number; status: string }> {
    const order = await this.getOrderById(id);

    const previousStatus = order.status.value;
    order.unapprove();

    const updated = await this.orderRepo.updateStatus(id, 'pending', previousStatus);
    if (!updated) {
      throw new VersionConflictError();
    }

    await this.persistAndPublishEvents(id, order);

    return { id, status: 'pending' };
  }

  private async persistAndPublishEvents(aggregateId: number, order: InboundOrder): Promise<void> {
    const events = order.getDomainEvents();
    if (events.length === 0) return;

    await transaction(async (conn) => {
      await getDomainEventOutbox().saveEvents(conn, 'InboundOrder', aggregateId, events);
    });

    order.clearDomainEvents();
  }
}

