    await this.persistAndPublishEvents(id, report);
  }

  async cancelWorkReport(id: number, reason: string, userId: number): Promise<void> {
    const report = await this.loadWorkReport(id);
    report.cancel(reason, userId);
    await this.workReportRepo!.update(report);
    await this.persistAndPublishEvents(id, report);
  }

  async listWorkReports(filters: Record<string, unknown>, page = 1, pageSize = 20) {
    return this.workReportRepo!.findByFilters(filters as WorkReportFilters, page, pageSize);
  }

  // ==================== 完工入库单 ====================

  async createFinishOrder(props: FinishOrderProps): Promise<{ id: number; finishNo: string }> {
    const finishNo = props.finishNo || (await generateDocumentNo('finish_inbound'));
    const order = FinishOrder.create({ ...props, finishNo });
    const id = await this.finishOrderRepo!.save(order);
    if (id) await this.persistAndPublishEvents(id, order);
    return { id, finishNo };
  }

  async approveFinishOrder(id: number, userId: number): Promise<void> {
    const order = await this.loadFinishOrder(id);
    const wo = await this.workOrderRepo.findById(order.workOrderId);
    order.approve(userId, wo?.workOrderNo || '', wo?.productName || '');
    await this.finishOrderRepo!.update(order);
    await this.persistAndPublishEvents(id, order);
  }

  async cancelFinishOrder(id: number, reason: string, userId: number): Promise<void> {
    const order = await this.loadFinishOrder(id);
    order.cancel(reason, userId);
    await this.finishOrderRepo!.update(order);
    await this.persistAndPublishEvents(id, order);
  }

  async listFinishOrders(filters: Record<string, unknown>, page = 1, pageSize = 20) {
    return this.finishOrderRepo!.findByFilters(filters as FinishOrderFilters, page, pageSize);
  }

  // ==================== 成本核算 ====================

  async calculateWorkOrderCosts(workOrderId: number): Promise<void> {
    // 材料成本 = SUM(领料金额) - SUM(退料金额)
    const materialCostResult = await query(
      `SELECT COALESCE(SUM(pi.line_amount), 0) as total_material,
              COALESCE((SELECT SUM(ri.line_amount) FROM prd_return_order_item ri
                JOIN prd_return_order ro ON ri.return_order_id = ro.id
                WHERE ro.work_order_id = ? AND ro.status = 2 AND ro.deleted = 0), 0) as total_return`,
      [workOrderId]
    );
    const materialCost =
      Number(materialCostResult[0]?.total_material || 0) -
      Number(materialCostResult[0]?.total_return || 0);

    // 人工成本 = SUM(报工工时 × 费率)  — 默认 50 元/小时
    const laborCostResult = await query(
      `SELECT COALESCE(SUM(wr.work_hours), 0) * 50 as total_labor
       FROM prd_work_report wr
       WHERE wr.work_order_id = ? AND wr.status = 2 AND wr.deleted = 0`,
      [workOrderId]
    );
    const laborCost = Number(laborCostResult[0]?.total_labor || 0);

    // 工装成本 = SUM(工装使用记录中的分摊成本)
    const toolCostResult = await query(
      `SELECT COALESCE(SUM(tu.amortized_cost), 0) as total_tool
       FROM dcprint_tool_usage tu
       WHERE tu.work_order_id = ?`,
      [workOrderId]
    );
    const toolCost = Number(toolCostResult[0]?.total_tool || 0);

    // 制造费用 = 材料成本 × 50%（可配置）
    const overheadRate = 0.5;
    const overheadCost = materialCost * overheadRate;

    // 合格数量
    const qtyResult = await query(
      'SELECT COALESCE(SUM(qualified_qty), 0) as total_qty FROM prd_finish_order WHERE work_order_id = ? AND status = 2 AND deleted = 0',
      [workOrderId]
    );
    const totalQty = Number(qtyResult[0]?.total_qty || 0);
    const totalCost = materialCost + laborCost + toolCost + overheadCost;
    const unitCost = totalQty > 0 ? totalCost / totalQty : 0;

    await execute(
      `UPDATE prod_work_order SET
       total_material_cost = ?, total_labor_cost = ?, total_tool_cost = ?,
       total_overhead_cost = ?, unit_cost = ?, update_time = NOW()
       WHERE id = ?`,
      [materialCost, laborCost, toolCost, overheadCost, unitCost, workOrderId]
    );
  }

  // ==================== 工具方法 ====================

  private async loadPickOrder(id: number): Promise<PickOrder> {
    const po = await this.pickOrderRepo!.findById(id);
    if (!po) throw new NotFoundError('领料单不存在');
    return po;
  }

  private async loadWorkReport(id: number): Promise<WorkReport> {
    const report = await this.workReportRepo!.findById(id);
    if (!report) throw new NotFoundError('报工单不存在');
    return report;
  }

  private async loadFinishOrder(id: number): Promise<FinishOrder> {
    const order = await this.finishOrderRepo!.findById(id);
    if (!order) throw new NotFoundError('完工入库单不存在');
    return order;
  }

  private statusToDbCode(status: string): number {
    const map: Record<string, number> = {
      draft: 1,
      approved: 2,
      picking: 3,
      in_progress: 4,
      completed: 5,
      closed: 6,
      cancelled: 7,
    };
    return map[status] || 1;
  }

  private async persistAndPublishEvents(
    aggregateId: number,
    aggregate: { getDomainEvents(): unknown[]; clearDomainEvents(): void }
  ): Promise<void> {
    const events = aggregate.getDomainEvents ? aggregate.getDomainEvents() : [];
    if (events.length === 0) return;
    await transaction(async (conn) => {
      const aggregateType = aggregate.constructor.name;
      await getDomainEventOutbox().saveEvents(
        conn,
        aggregateType,
        aggregateId,
        events as DomainEvent[]
      );
    });
    if (aggregate.clearDomainEvents) aggregate.clearDomainEvents();
  }
}

import { IPurchaseOrderRepository } from '@/domain/purchase/repositories/IPurchaseOrderRepository';
import { PurchaseOrder, PurchaseOrderProps } from '@/domain/purchase/aggregates/PurchaseOrder';
import { PurchaseOrderStatus } from '@/domain/purchase/value-objects/PurchaseOrderStatus';
import { DomainError, NotFoundError, VersionConflictError } from '@/domain/shared/DomainTypes';
import { getDomainEventOutbox } from '@/infrastructure/event-bus/DomainEventOutboxFactory';
import { query, transaction } from '@/lib/db';
import {
  getSystemConfig,
  getSystemConfigBoolean,
  getSystemConfigNumber,
} from '@/lib/system-config';
import { CurrencyApplicationService } from './CurrencyApplicationService';
import { CurrencySnapshot } from '@/domain/shared/value-objects/CurrencySnapshot';
import { Money } from '@/domain/shared/value-objects/Money';
import type { ResultSetHeader } from 'mysql2/promise';

export class PurchaseApplicationService {
  constructor(
    private readonly orderRepo: IPurchaseOrderRepository,
    private readonly currencyService: CurrencyApplicationService
  ) {}

  async getOrderById(id: number): Promise<PurchaseOrder> {
    const order = await this.orderRepo.findById(id);
    if (!order) {
      throw new NotFoundError('采购单不存在');
    }
    return order;
  }

  async listOrders(
    status: string,
    page: number,
    pageSize: number,
    filters?: { keyword?: string; supplierId?: number; startDate?: string; endDate?: string }
  ) {
    return this.orderRepo.findByStatus(status, { page, pageSize }, filters);
  }

  async createOrder(props: PurchaseOrderProps): Promise<{ id: number; orderNo: string }> {
    // 采购允差比例：未指定时使用系统配置默认值
    let effectiveProps = props;
    if (!props.overReceiptTolerance) {
      const tolerance = await getSystemConfigNumber('purchase.tolerance_ratio', 0);
      if (tolerance > 0) {
        effectiveProps = { ...props, overReceiptTolerance: tolerance };
      }
    }

    // 财务默认税率/币种（未指定时使用系统配置）
    if (!effectiveProps.taxRate) {
      const taxRate = await getSystemConfigNumber('finance.tax_rate', 13);
      effectiveProps = { ...effectiveProps, taxRate };
    }
    if (!effectiveProps.currency) {
      const currency = await getSystemConfig('finance.default_currency', 'CNY');
      if (currency) effectiveProps = { ...effectiveProps, currency };
    }

    // 明细行税率默认继承表头税率
    effectiveProps = {
      ...effectiveProps,
      lines: effectiveProps.lines.map((l) => ({
        ...l,
        taxRate: l.taxRate ?? effectiveProps.taxRate,
      })),
    };

    // 采购价格上限控制：单价超过该物料历史最高采购价时拦截
    const priceControl = await getSystemConfigBoolean('purchase.price_control', false);
    if (priceControl) {
      for (const line of effectiveProps.lines) {
        const maxPrice = await this.getHistoricalMaxPrice(line.materialId);
        if (maxPrice !== null && (line.unitPrice || 0) > maxPrice) {
          throw new DomainError(
            `物料「${line.materialName || line.materialCode}」采购单价 ${line.unitPrice} 超过历史最高价 ${maxPrice}，已被价格上限控制拦截`
          );
        }
      }
    }

    // 多币种换算为本位币
    const baseCurrency = await getSystemConfig('finance.base_currency', 'CNY');
    let exchangeRate = effectiveProps.exchangeRate || 1.0;
    if (effectiveProps.currency && effectiveProps.currency !== baseCurrency) {
      exchangeRate = await this.currencyService.getLatestRate(
        effectiveProps.currency,
        baseCurrency
      );
    }

    const snapshot = CurrencySnapshot.create(
      effectiveProps.currency || 'CNY',
      exchangeRate,
      baseCurrency
    );

    const baseCurrencyDecimalPlaces = 2;
    effectiveProps = {
      ...effectiveProps,
      exchangeRate,
      lines: effectiveProps.lines.map((line) => {
        const originalUnitPrice = line.unitPrice || 0;
        const originalAmount = (line.orderQty || 0) * originalUnitPrice;
        const originalTaxAmount =
          (originalAmount * (line.taxRate ?? effectiveProps.taxRate ?? 13)) / 100;
        const originalLineTotal = originalAmount + originalTaxAmount;

        return {
          ...line,
          baseUnitPrice: snapshot.convert(
            Money.create(originalUnitPrice, snapshot.currency),
            baseCurrencyDecimalPlaces
          ).amount,
          baseAmount: snapshot.convert(
            Money.create(originalAmount, snapshot.currency),
            baseCurrencyDecimalPlaces
          ).amount,
          baseTaxAmount: snapshot.convert(
            Money.create(originalTaxAmount, snapshot.currency),
            baseCurrencyDecimalPlaces
          ).amount,
          baseLineTotal: snapshot.convert(
            Money.create(originalLineTotal, snapshot.currency),
            baseCurrencyDecimalPlaces
          ).amount,
        };
      }),
    };

    const baseTotalAmount = effectiveProps.lines.reduce((sum, l) => sum + (l.baseAmount || 0), 0);
    const baseTaxAmount = effectiveProps.lines.reduce((sum, l) => sum + (l.baseTaxAmount || 0), 0);
    const baseGrandTotal = baseTotalAmount + baseTaxAmount;

    effectiveProps = {
      ...effectiveProps,
      baseCurrency,
      baseTotalAmount: Math.round(baseTotalAmount * 100) / 100,
      baseTaxAmount: Math.round(baseTaxAmount * 100) / 100,
      baseGrandTotal: Math.round(baseGrandTotal * 100) / 100,
    };

    const order = PurchaseOrder.create(effectiveProps);
    const result = await this.orderRepo.save(order);

    if (result.id) {
      // 采购审批金额阈值：订单总额超过阈值时自动提交进入审批流
      const threshold = await getSystemConfigNumber('purchase.approval_threshold', 0);
      if (threshold > 0 && order.totalAmount > threshold) {
        order.submit();
        const updated = await this.orderRepo.updateStatus(result.id, 'submitted', 'draft');
        if (!updated) {
          throw new VersionConflictError();
        }
      }
      await this.persistAndPublishEvents(result.id, order);
    }

    return result;
  }

  /**
   * 查询某物料的历史最高采购单价，用于价格上限控制校验。
   * 无历史记录或查询失败时返回 null（不拦截）。
   */
  private async getHistoricalMaxPrice(materialId: number): Promise<number | null> {
    if (!materialId) return null;
    try {
      const rows = await query(
        'SELECT MAX(unit_price) AS max_price FROM pur_purchase_order_line WHERE material_id = ?',
        [materialId]
      );
      const max = rows[0]?.max_price;
      return max === null || max === undefined ? null : Number(max);
    } catch {
      return null;
    }
  }

  async submitOrder(id: number): Promise<{ id: number; status: string }> {
    const order = await this.getOrderById(id);

    const previousStatus = order.status.value;
    order.submit();

    const updated = await this.orderRepo.updateStatus(id, 'submitted', previousStatus);
    if (!updated) {
      throw new VersionConflictError();
    }

    await this.persistAndPublishEvents(id, order);

    return { id, status: 'submitted' };
  }

  async approveOrder(id: number, auditBy: number): Promise<{ id: number; status: string }> {
    const order = await this.getOrderById(id);

    const previousStatus = order.status.value;
    order.approve(auditBy);

    await transaction(async (conn) => {
      const [result] = (await conn.execute(
        'UPDATE pur_purchase_order SET status = ?, audit_by = ?, audit_time = NOW(), update_time = NOW() WHERE id = ? AND status = ?',
        [order.status.toDbCode(), auditBy, id, PurchaseOrderStatus.from(previousStatus).toDbCode()]
      )) as [ResultSetHeader, any];
      if (result.affectedRows === 0) {
        throw new VersionConflictError();
      }

      const events = order.getDomainEvents();
      await getDomainEventOutbox().saveEvents(conn, 'PurchaseOrder', id, events);
    });

    order.clearDomainEvents();

    return { id, status: 'approved' };
  }

  /**
   * @deprecated 收货功能已迁移至入库单模块。
   * 请使用 POST /api/warehouse/inbound/from-po 从采购单创建入库单，
   * 再通过 PUT /api/warehouse/inbound?action=approve 审核入库单完成收货。
   */
  async receiveGoods(
    _id: number,
    _lineReceives: Array<{ lineNo: number; quantity: number; batchNo: string; warehouseId: number }>
  ): Promise<{ id: number; status: string }> {
    throw new DomainError(
      '收货功能已迁移至入库单流程，请使用 POST /api/warehouse/inbound/from-po 创建入库单'
    );
  }

  async closeOrder(id: number): Promise<{ id: number; status: string }> {
    const order = await this.getOrderById(id);

    const previousStatus = order.status.value;
    order.close();

    const updated = await this.orderRepo.updateStatus(id, 'closed', previousStatus);
    if (!updated) {
      throw new VersionConflictError();
    }

    await this.persistAndPublishEvents(id, order);

    return { id, status: 'closed' };
  }

  async deleteOrder(id: number): Promise<void> {
    const order = await this.getOrderById(id);

    if (!order.canDelete()) {
      throw new DomainError('当前状态的采购单不能删除');
    }

    await this.orderRepo.softDelete(id);
  }

  private async persistAndPublishEvents(aggregateId: number, order: PurchaseOrder): Promise<void> {
    const events = order.getDomainEvents();
    if (events.length === 0) return;

    await transaction(async (conn) => {
      await getDomainEventOutbox().saveEvents(conn, 'PurchaseOrder', aggregateId, events);
    });

    order.clearDomainEvents();
  }
}

import { QRCode, QR_TYPE, type QRCodeProps } from '@/domain/trace/QRCode';
import type {
  IQRCodeRepository,
  TraceTimelineItem,
} from '@/domain/trace/repositories/IQRCodeRepository';
import { DomainError, NotFoundError } from '@/domain/shared/DomainTypes';
import { getDomainEventOutbox } from '@/infrastructure/event-bus/DomainEventOutboxFactory';
import { transaction, execute } from '@/lib/db';
import {
  QRCodeGeneratedEvent,
  QRCodeSplitEvent,
  QRCodeScannedEvent,
} from '@/domain/trace/events/QRCodeEvents';

export interface SplitInput {
  quantity: number;
}

export class QRCodeApplicationService {
  constructor(private readonly qrCodeRepo: IQRCodeRepository) {}

  async generateBatchQr(props: {
    qrType?: string;
    batchNo?: string | null;
    quantity: number;
    count: number;
    materialId?: number | null;
    materialCode?: string | null;
    materialName?: string | null;
    unit?: string | null;
    warehouseId?: number | null;
    warehouseName?: string | null;
    refId?: number | null;
    refNo?: string | null;
  }): Promise<{ ids: number[]; qrCodes: string[] }> {
    if (props.count <= 0) throw new DomainError('生成数量必须大于0');
    if (props.quantity <= 0) throw new DomainError('数量必须大于0');

    const qrType = props.qrType || QR_TYPE.MATERIAL;
    const qrCodes: QRCode[] = [];
    for (let i = 0; i < props.count; i++) {
      const qrCodeValue = `${props.batchNo || 'QR'}-${Date.now()}-${i}`;
      qrCodes.push(
        QRCode.create({
          qrCode: qrCodeValue,
          qrType,
          batchNo: props.batchNo ?? null,
          quantity: props.quantity,
          materialId: props.materialId ?? null,
          materialCode: props.materialCode ?? null,
          materialName: props.materialName ?? null,
          unit: props.unit ?? null,
          warehouseId: props.warehouseId ?? null,
          warehouseName: props.warehouseName ?? null,
          refId: props.refId ?? null,
          refNo: props.refNo ?? null,
        })
      );
    }

    const ids = await this.qrCodeRepo.createBatch(qrCodes);

    for (let i = 0; i < ids.length; i++) {
      const event = new QRCodeGeneratedEvent({
        qrId: ids[i],
        qrCode: qrCodes[i].qrCode,
        materialId: props.materialId ?? null,
        batchNo: props.batchNo ?? null,
        quantity: props.quantity,
        qrType,
        count: props.count,
      });
      await transaction(async (conn) => {
        await getDomainEventOutbox().saveEvents(conn, 'QRCode', ids[i], [event]);
      });
    }

    return {
      ids,
      qrCodes: qrCodes.map((q) => q.qrCode),
    };
  }

  async splitParentQr(
    parentQrCode: string,
    splits: SplitInput[]
  ): Promise<{ childIds: number[]; childCodes: string[] }> {
    const parent = await this.qrCodeRepo.findByContent(parentQrCode);
    if (!parent) throw new NotFoundError('父二维码不存在');
    if (parent.status !== 1) throw new DomainError('父二维码已失效');

    const totalQuantity = splits.reduce((sum, s) => sum + s.quantity, 0);
    if (totalQuantity > parent.quantity) throw new DomainError('拆分总量超过父码剩余数量');

    const childIds: number[] = [];
    const childCodes: string[] = [];

    await transaction(async (conn) => {
      let childIndex = 1;
      for (const split of splits) {
        const childQr = parent.split(split.quantity, splits.length, childIndex);
        const [result] = (await conn.execute(
          `INSERT INTO qrcode_record (qr_code, qr_type, parent_qr_code, split_flag, split_index, batch_no, material_id, material_code, material_name, quantity, unit, warehouse_id, status, create_time, update_time)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, NOW(), NOW())`,
          [
            childQr.qrCode,
            QR_TYPE.SPLIT,
            parent.qrCode,
            1,
            childIndex,
            parent.batchNo,
            parent.materialId,
            parent.materialCode,
            parent.materialName,
            split.quantity,
            parent.unit,
            parent.warehouseId,
          ]
        )) as unknown as [{ insertId: number }];
        childIds.push(Number(result.insertId));
        childCodes.push(childQr.qrCode);
        childIndex++;
      }

      const remaining = (parent.quantity ?? 0) - (totalQuantity ?? 0);
      await conn.execute(
        'UPDATE qrcode_record SET quantity = ?, update_time = NOW() WHERE id = ?',
        [remaining, parent.id!] as any
      );

      const splitEvent = new QRCodeSplitEvent({
        parentQrId: parent.id!,
        parentQrCode: parent.qrCode,
        childQrIds: childIds,
        childQrCodes: childCodes,
        splitCount: splits.length,
      });
      await getDomainEventOutbox().saveEvents(conn, 'QRCode', parent.id!, [splitEvent]);
    });

    return { childIds, childCodes };
  }

  async recordScan(qrCode: string, operator: string, location: string): Promise<void> {
    const qr = await this.qrCodeRepo.findByContent(qrCode);
    if (!qr) throw new NotFoundError('二维码不存在');

    await transaction(async (conn) => {
      await conn.execute(
        `INSERT INTO qrcode_scan_log (qr_code, qr_type, scan_type, operator_name, scan_result, scan_message, create_time)
         VALUES (?, ?, ?, ?, 'success', ?, NOW())`,
        [qrCode, qr.qrType, 'trace', operator, `扫码位置: ${location}`]
      );

      await conn.execute(
        'UPDATE qrcode_record SET scan_count = scan_count + 1, last_scan_time = NOW() WHERE id = ?',
        [qr.id!]
      );

      const event = new QRCodeScannedEvent({
        qrId: qr.id!,
        qrCode: qr.qrCode,
        operator,
        location,
      });
      await getDomainEventOutbox().saveEvents(conn, 'QRCode', qr.id!, [event]);
    });
  }

  async getTraceTimeline(qrCode: string): Promise<TraceTimelineItem[]> {
    const qr = await this.qrCodeRepo.findByContent(qrCode);
    if (!qr) throw new NotFoundError('二维码不存在');
    return this.qrCodeRepo.queryTraceTimeline(qrCode);
  }

  async recordPrint(
    qrId: number,
    templateId: number | null,
    operator: string,
    paperType: string,
    printCount: number = 1
  ): Promise<void> {
    const qr = await this.qrCodeRepo.findById(qrId);
    if (!qr) throw new NotFoundError('二维码不存在');
    await execute(
      `INSERT INTO print_log (qr_id, template_id, print_time, operator, paper_type, print_count)
       VALUES (?, ?, NOW(), ?, ?, ?)`,
      [qrId, templateId, operator, paperType, printCount]
    );
    await execute(
      'UPDATE qrcode_record SET print_count = print_count + ?, last_print_time = NOW() WHERE id = ?',
      [printCount, qrId]
    );
  }
}

import { IReturnOrderRepository } from '@/domain/sales/repositories/IReturnOrderRepository';
import { IInboundOrderRepository } from '@/domain/warehouse/repositories/IInboundOrderRepository';
import { IReceivableRepository } from '@/domain/finance/repositories/IReceivableRepository';
import { ISalesOrderRepository } from '@/domain/sales/repositories/ISalesOrderRepository';
import {
  ReturnOrder,
  ReturnOrderProps,
  InboundResult,
  ReceivableResult,
} from '@/domain/sales/aggregates/ReturnOrder';
import { InboundOrder, InboundOrderProps } from '@/domain/warehouse/aggregates/InboundOrder';
import { InboundItemProps } from '@/domain/warehouse/entities/InboundItem';
import { Receivable, ReceivableProps } from '@/domain/finance/aggregates/Receivable';
import { DomainError, NotFoundError } from '@/domain/shared/DomainTypes';
import { DomainEvent } from '@/domain/shared/DomainEvent';
import { CurrencyApplicationService } from './CurrencyApplicationService';
import { CurrencySnapshot } from '@/domain/shared/value-objects/CurrencySnapshot';
import { Money } from '@/domain/shared/value-objects/Money';
import { getSystemConfig } from '@/lib/system-config';
import { getDomainEventOutbox } from '@/infrastructure/event-bus/DomainEventOutboxFactory';
import { transaction, query } from '@/lib/db';

// 应收单来源类型：1-销售订单, 2-手工录入, 3-退货红字
const RECEIVABLE_SOURCE_TYPE_RETURN = 3;
// 入库单类型：sales_return 表示退货入库
const INBOUND_ORDER_TYPE_RETURN = 'sales_return';

export class ReturnOrderApplicationService {
  constructor(
    private readonly returnRepo: IReturnOrderRepository,
    private readonly inboundRepo: IInboundOrderRepository,
    private readonly receivableRepo: IReceivableRepository,
    private readonly orderRepo: ISalesOrderRepository,
    private readonly currencyService: CurrencyApplicationService
  ) {}

  async getReturnById(id: number): Promise<ReturnOrder> {
    const ret = await this.returnRepo.findById(id);
    if (!ret) throw new NotFoundError('退货单不存在');
    return ret;
  }

  async createReturn(props: ReturnOrderProps): Promise<{ id: number; returnNo: string }> {
    let effectiveProps = { ...props };

    if (effectiveProps.orderId) {
      const order = await this.orderRepo.findById(effectiveProps.orderId);
      if (order) {
        if (!effectiveProps.currency) effectiveProps.currency = order.currency;
        if (!effectiveProps.exchangeRate) effectiveProps.exchangeRate = order.exchangeRate;
        if (!effectiveProps.baseCurrency) effectiveProps.baseCurrency = order.baseCurrency;
      }
    }

    const baseCurrency =
      effectiveProps.baseCurrency || (await getSystemConfig('finance.base_currency', 'CNY'));
    const currency = effectiveProps.currency || 'CNY';
    let exchangeRate = effectiveProps.exchangeRate || 1.0;
    if (currency !== baseCurrency) {
      exchangeRate = await this.currencyService.getLatestRate(currency, baseCurrency);
    }

    const snapshot = CurrencySnapshot.create(currency, exchangeRate, baseCurrency);
    const decimalPlaces = 2;

    effectiveProps = {
      ...effectiveProps,
      exchangeRate,
      baseCurrency,
      lines: effectiveProps.lines.map((line) => {
        const originalAmount = (line.quantity || 0) * (line.unitPrice || 0);
        return {
          ...line,
          baseUnitPrice: snapshot.convert(
            Money.create(line.unitPrice || 0, currency),
            decimalPlaces
          ).amount,
          baseAmount: snapshot.convert(Money.create(originalAmount, currency), decimalPlaces)
            .amount,
        };
      }),
    };

    const baseTotalAmount = effectiveProps.lines.reduce((sum, l) => sum + (l.baseAmount || 0), 0);
    effectiveProps.baseTotalAmount = Math.round(baseTotalAmount * 100) / 100;

    const ret = ReturnOrder.create(effectiveProps);
    const id = await this.returnRepo.save(ret);
    await this.persistAndPublishEvents('ReturnOrder', id, ret);
    return { id, returnNo: ret.returnNo };
  }

  async approveReturn(id: number, approveBy: number): Promise<{ status: number }> {
    const ret = await this.getReturnById(id);

    // T204: 审核前校验退货数量不得超过累计已发货量
    await this.validateReturnQuantitiesAgainstShipped(ret);

    ret.approve(approveBy);

    await this.returnRepo.updateApproval(id, ret.status.value, ret.approveBy!, ret.approveTime!);
    await this.persistAndPublishEvents('ReturnOrder', id, ret);
    return { status: ret.status.value };
  }

  /**
   * 从 sal_order_detail 拉取 delivered_qty 聚合数据，
   * 调用聚合根的领域校验方法 validateAgainstShippedQuantities。
   *
   * 数据获取在应用层，规则判定在领域层，保持 DDD 分层规范。
   * 与 PurchaseReturnApplicationService.validateReturnQuantitiesAgainstReceived 对称（T204 复用 T104 模板）。
   *
   * 注：sal_order_detail 当前未维护 returned_qty 列，已退数量暂以 0 计；
   * 后续若新增 returned_qty 列，可在此处补充 SUM 查询并传入 alreadyReturned map。
   */
  private async validateReturnQuantitiesAgainstShipped(ret: ReturnOrder): Promise<void> {
    interface LineQtyRow {
      material_id: number;
      delivered_qty: number | string | null;
    }
    const rows = await query<LineQtyRow>(
      'SELECT material_id, delivered_qty FROM sal_order_detail WHERE order_id = ?',
      [ret.orderId]
    );

    if (!rows || rows.length === 0) {
      // 销售单无明细行：所有退货均不合法
      const shippedMap = new Map<number, number>();
      ret.validateAgainstShippedQuantities(shippedMap);
      return;
    }

    const shippedMap = new Map<number, number>();
    for (const row of rows) {
      const mid = Number(row.material_id);
      // 同一物料在多行的情况：累加 delivered_qty
      shippedMap.set(mid, (shippedMap.get(mid) ?? 0) + Number(row.delivered_qty || 0));
    }
    ret.validateAgainstShippedQuantities(shippedMap);
  }

  async completeReturn(
    id: number,
    completeBy: number
  ): Promise<{
    status: number;
    inboundOrderId: number;
    inboundOrderNo: string;
    receivableId: number;
    receivableNo: string;
  }> {
    const ret = await this.getReturnById(id);
    if (!ret.status.canComplete()) {
      throw new DomainError(`当前状态"${ret.status.label}"不允许完成`);
    }

    // 预创建退货入库单（异步）
    const inboundResult = await this.createInboundForReturn(ret);

    // 预创建红字应收单（异步）
    const receivableResult = await this.createReceivableForReturn(ret);

    // 调用聚合 complete，传同步回调返回预创建结果
    ret.complete(
      completeBy,
      () => inboundResult,
      () => receivableResult
    );

    // 持久化退货单状态变更
    await this.returnRepo.updateCompletion(
      id,
      ret.status.value,
      ret.completeBy!,
      ret.completeTime!,
      inboundResult.inboundOrderId,
      inboundResult.inboundOrderNo,
      receivableResult.receivableId,
      receivableResult.receivableNo
    );

    await this.persistAndPublishEvents('ReturnOrder', id, ret);
    return {
      status: ret.status.value,
      inboundOrderId: inboundResult.inboundOrderId,
      inboundOrderNo: inboundResult.inboundOrderNo,
      receivableId: receivableResult.receivableId,
      receivableNo: receivableResult.receivableNo,
    };
  }

  async cancelReturn(id: number, reason?: string): Promise<{ status: number }> {
    const ret = await this.getReturnById(id);
    ret.cancel(reason);

    await this.returnRepo.updateStatus(id, ret.status.value);
    await this.persistAndPublishEvents('ReturnOrder', id, ret);
    return { status: ret.status.value };
  }

  async listReturnsByStatus(status: number): Promise<ReturnOrder[]> {
    return this.returnRepo.findByStatus(status);
  }

  async listReturnsByOrder(orderId: number): Promise<ReturnOrder[]> {
    return this.returnRepo.findByOrderId(orderId);
  }

  async listReturnsByCustomer(customerId: number): Promise<ReturnOrder[]> {
    return this.returnRepo.findByCustomerId(customerId);
  }

  async deleteReturn(id: number): Promise<void> {
    const ret = await this.getReturnById(id);
    if (!ret.canDelete()) {
      throw new DomainError('仅待审核状态的退货单可删除');
    }
    await this.returnRepo.softDelete(id);
  }

  private async createInboundForReturn(ret: ReturnOrder): Promise<InboundResult> {
    const warehouseRows = await query('SELECT warehouse_name FROM inv_warehouse WHERE id = ?', [
      ret.warehouseId,
    ]);
    const warehouseName = warehouseRows?.[0]?.warehouse_name || '';

    const items: InboundItemProps[] = ret.lines.map((line) => ({
      materialId: line.materialId,
      materialCode: line.materialCode,
      materialName: line.materialName,
      materialSpec: line.materialSpec,
      batchNo: line.batchNo || '',
      quantity: line.quantity,
      unit: line.unit,
      unitPrice: line.unitPrice,
    }));

    const inboundProps: InboundOrderProps = {
      warehouseId: ret.warehouseId,
      warehouseName,
      supplierName: ret.customerName || `客户${ret.customerId}`,
      orderType: INBOUND_ORDER_TYPE_RETURN,
      inboundDate: ret.returnDate,
      remark: `退货入库：${ret.returnNo}`,
      operatorId: ret.createBy,
      items,
    };

    const inboundOrder = InboundOrder.create(inboundProps);
    const { id: inboundId, orderNo: inboundOrderNo } = await this.inboundRepo.save(inboundOrder);
    await this.persistAndPublishEvents('InboundOrder', inboundId, inboundOrder);

    return {
      inboundOrderId: inboundId,
      inboundOrderNo,
    };
  }

  private async createReceivableForReturn(ret: ReturnOrder): Promise<ReceivableResult> {
    const receivableProps: ReceivableProps = {
      sourceType: RECEIVABLE_SOURCE_TYPE_RETURN,
      sourceId: ret.id,
      sourceNo: ret.returnNo,
      customerId: ret.customerId,
      customerName: ret.customerName,
      // T305: 红字应收使用负数金额，冲减客户应收余额
      amount: -ret.totalAmount,
      remark: `退货红字应收：${ret.returnNo}`,
    };

    const receivable = Receivable.createRedLetter(receivableProps);
    const receivableId = await this.receivableRepo.save(receivable);
    await this.persistAndPublishEvents('Receivable', receivableId, receivable);

    return {
      receivableId,
      receivableNo: receivable.receivableNo,
    };
  }

  private async persistAndPublishEvents(
    aggregateType: string,
    aggregateId: number,
    aggregate: { getDomainEvents(): DomainEvent[]; clearDomainEvents(): void }
  ): Promise<void> {
    const events = aggregate.getDomainEvents();
    if (events.length === 0) return;

    await transaction(async (conn) => {
      await getDomainEventOutbox().saveEvents(conn, aggregateType, aggregateId, events);
    });

    aggregate.clearDomainEvents();
  }
}

import { ISalesOrderRepository } from '@/domain/sales/repositories/ISalesOrderRepository';
import { SalesOrder, SalesOrderProps } from '@/domain/sales/aggregates/SalesOrder';
import { SalesOrderStatus } from '@/domain/sales/value-objects/SalesOrderStatus';
import { DomainError, NotFoundError, VersionConflictError } from '@/domain/shared/DomainTypes';
import { CurrencyApplicationService } from './CurrencyApplicationService';
import { CurrencySnapshot } from '@/domain/shared/value-objects/CurrencySnapshot';
import { Money } from '@/domain/shared/value-objects/Money';
import { getDomainEventOutbox } from '@/infrastructure/event-bus/DomainEventOutboxFactory';
import { transaction } from '@/lib/db';
import { InventoryValidationService } from '@/application/services/InventoryValidationService';
import {
  getSystemConfig,
  getSystemConfigBoolean,
  getSystemConfigNumber,
} from '@/lib/system-config';
import type { ResultSetHeader } from 'mysql2/promise';

export class SalesApplicationService {
  constructor(
    private readonly orderRepo: ISalesOrderRepository,
    private readonly currencyService: CurrencyApplicationService
  ) {}

  async getOrderById(id: number): Promise<SalesOrder> {
    const order = await this.orderRepo.findById(id);
    if (!order) throw new NotFoundError('销售单不存在');
    return order;
  }

  async listOrders(
    status: string,
    page: number,
    pageSize: number,
    filters?: { keyword?: string; customerId?: number; startDate?: string; endDate?: string }
  ) {
    return this.orderRepo.findByStatus(status, { page, pageSize }, filters);
  }

  async createOrder(props: SalesOrderProps): Promise<{ id: number; orderNo: string }> {
    let effectiveProps = props;
    // 财务默认税率/币种（未指定时使用系统配置）
    if (!props.taxRate) {
      const taxRate = await getSystemConfigNumber('finance.tax_rate', 13);
      effectiveProps = { ...effectiveProps, taxRate };
    }
    if (!props.currency) {
      const currency = await getSystemConfig('finance.default_currency', 'CNY');
      if (currency) effectiveProps = { ...effectiveProps, currency };
    }

    // 明细行税率默认继承表头税率
    effectiveProps = {
      ...effectiveProps,
      lines: effectiveProps.lines.map((l) => ({
        ...l,
        taxRate: l.taxRate ?? effectiveProps.taxRate,
      })),
    };

    const baseCurrency = await getSystemConfig('finance.base_currency', 'CNY');
    let exchangeRate = effectiveProps.exchangeRate || 1.0;
    if (effectiveProps.currency && effectiveProps.currency !== baseCurrency) {
      exchangeRate = await this.currencyService.getLatestRate(
        effectiveProps.currency,
        baseCurrency
      );
    }

    const snapshot = CurrencySnapshot.create(
      effectiveProps.currency || 'CNY',
      exchangeRate,
      baseCurrency
    );

    const baseCurrencyDecimalPlaces = 2;
    effectiveProps = {
      ...effectiveProps,
      exchangeRate,
      lines: effectiveProps.lines.map((line) => {
        const originalUnitPrice = line.unitPrice || 0;
        const originalAmount = (line.orderQty || 0) * originalUnitPrice;
        const originalTaxAmount =
          (originalAmount * (line.taxRate ?? effectiveProps.taxRate ?? 13)) / 100;
        const originalLineTotal = originalAmount + originalTaxAmount;

        return {
          ...line,
          baseUnitPrice: snapshot.convert(
            Money.create(originalUnitPrice, snapshot.currency),
            baseCurrencyDecimalPlaces
          ).amount,
          baseAmount: snapshot.convert(
            Money.create(originalAmount, snapshot.currency),
            baseCurrencyDecimalPlaces
          ).amount,
          baseTaxAmount: snapshot.convert(
            Money.create(originalTaxAmount, snapshot.currency),
            baseCurrencyDecimalPlaces
          ).amount,
          baseLineTotal: snapshot.convert(
            Money.create(originalLineTotal, snapshot.currency),
            baseCurrencyDecimalPlaces
          ).amount,
        };
      }),
    };

    const baseTotalAmount = effectiveProps.lines.reduce((sum, l) => sum + (l.baseAmount || 0), 0);
    const baseTaxAmount = effectiveProps.lines.reduce((sum, l) => sum + (l.baseTaxAmount || 0), 0);
    const baseGrandTotal = baseTotalAmount + baseTaxAmount;

    effectiveProps = {
      ...effectiveProps,
      baseCurrency,
      baseTotalAmount: Math.round(baseTotalAmount * 100) / 100,
      baseTaxAmount: Math.round(baseTaxAmount * 100) / 100,
      baseGrandTotal: Math.round(baseGrandTotal * 100) / 100,
    };

    const order = SalesOrder.create(effectiveProps);

    // 订单最低金额校验
    const minAmount = await getSystemConfigNumber('order.min_amount', 0);
    if (minAmount > 0 && order.totalAmount < minAmount) {
      throw new DomainError(
        `订单金额 ${order.totalAmount} 低于最低订单金额 ${minAmount}，无法创建`
      );
    }

    const result = await this.orderRepo.save(order);
    if (result.id) await this.persistAndPublishEvents(result.id, order);
    return result;
  }

  async submitOrder(id: number): Promise<{ id: number; status: string }> {
    const order = await this.getOrderById(id);
    const previousStatus = order.status.value;
    order.submit();
    const updated = await this.orderRepo.updateStatus(id, 'submitted', previousStatus);
    if (!updated) throw new VersionConflictError();
    await this.persistAndPublishEvents(id, order);

    // 订单自动审核
    const autoApprove = await getSystemConfigBoolean('order.auto_approve', false);
    if (autoApprove) {
      try {
        return await this.approveOrder(id, order.createBy || 0);
      } catch {
        // 自动审核失败（如状态不允许）则保持已提交状态
      }
    }
    return { id, status: 'submitted' };
  }

  async approveOrder(id: number, auditBy: number): Promise<{ id: number; status: string }> {
    const order = await this.getOrderById(id);
    const previousStatus = order.status.value;
    order.approve(auditBy);

    await transaction(async (conn) => {
      const [result] = (await conn.execute(
        'UPDATE sal_order SET status = ?, audit_by = ?, audit_time = NOW(), update_time = NOW() WHERE id = ? AND status = ?',
        [order.status.toDbCode(), auditBy, id, SalesOrderStatus.from(previousStatus).toDbCode()]
      )) as [ResultSetHeader, any];
      if (result.affectedRows === 0) throw new VersionConflictError();
      await getDomainEventOutbox().saveEvents(conn, 'SalesOrder', id, order.getDomainEvents());
    });

    order.clearDomainEvents();
    return { id, status: 'approved' };
  }

  async shipGoods(
    id: number,
    lineShipments: Array<{ lineNo: number; quantity: number; batchNo: string; warehouseId: number }>
  ): Promise<{ id: number; status: string }> {
    const order = await this.getOrderById(id);

    for (const shipment of lineShipments) {
      const line = order.lines.find((l) => l.lineNo === shipment.lineNo);
      if (!line) throw new DomainError(`行号${shipment.lineNo}不存在`);
      const check = await InventoryValidationService.checkStock(
        line.materialId,
        shipment.warehouseId,
        shipment.quantity
      );
      if (!check.sufficient) throw new DomainError(check.message || '库存不足');
    }

    const previousStatus = order.status.value;
    order.ship(lineShipments);

    await transaction(async (conn) => {
      const currentDbStatus = SalesOrderStatus.from(previousStatus).toDbCode();
      const [result] = (await conn.execute(
        'UPDATE sal_order SET status = ?, update_time = NOW() WHERE id = ? AND status = ?',
        [order.status.toDbCode(), id, currentDbStatus]
      )) as [ResultSetHeader, any];
      if (result.affectedRows === 0) throw new VersionConflictError();

      for (const line of order.lines) {
        if (line.id) {
          await conn.execute(
            'UPDATE sal_order_detail SET shipped_qty = ? WHERE order_id = ? AND id = ?',
            [line.shippedQty, id, line.id]
          );
        }
      }

      await getDomainEventOutbox().saveEvents(conn, 'SalesOrder', id, order.getDomainEvents());
    });

    order.clearDomainEvents();
    return { id, status: order.status.value };
  }

  async closeOrder(id: number): Promise<{ id: number; status: string }> {
    const order = await this.getOrderById(id);
    const previousStatus = order.status.value;
    order.close();
    const updated = await this.orderRepo.updateStatus(id, 'closed', previousStatus);
    if (!updated) throw new VersionConflictError();
    await this.persistAndPublishEvents(id, order);
    return { id, status: 'closed' };
  }

  async deleteOrder(id: number): Promise<void> {
    const order = await this.getOrderById(id);
    if (!order.canDelete()) throw new DomainError('当前状态的销售单不能删除');
    await this.orderRepo.softDelete(id);
  }

  private async persistAndPublishEvents(aggregateId: number, order: SalesOrder): Promise<void> {
    const events = order.getDomainEvents();
    if (events.length === 0) return;
    await transaction(async (conn) => {
      await getDomainEventOutbox().saveEvents(conn, 'SalesOrder', aggregateId, events);
    });
    order.clearDomainEvents();
  }
}

