        <circle
          cx={cx}
          cy={cy}
          r="5"
          fill="rgba(0,0,0,0.5)"
          stroke="rgba(255,255,255,0.1)"
          strokeWidth="1"
        />
        <circle cx={cx - 1} cy={cy - 1} r="1.5" fill="rgba(255,255,255,0.12)" />

        <ellipse
          cx={cx}
          cy={cy - r * 0.3}
          rx={r * 0.4}
          ry={r * 0.15}
          fill="rgba(255,255,255,0.03)"
        />

        <text
          x={cx}
          y={cy + 22}
          textAnchor="middle"
          fill="white"
          fontSize="18"
          fontWeight="bold"
          fontFamily="monospace"
        >
          {Math.round(displayVal)}
        </text>
        <text
          x={cx}
          y={cy + 34}
          textAnchor="middle"
          fill="rgba(255,255,255,0.4)"
          fontSize="9"
