  base: number;
  piece: number;
  overtime: number;
  performance: number;
  insurance: number;
}

interface LaborCostChartProps {
  data: LaborCostData[];
}

const colors = {
  base: '#22c55e',
  piece: '#3b82f6',
  overtime: '#f97316',
  performance: '#a855f7',
