    width: 60,
    height: 40,
    fields: ['qrCode', 'materialName', 'batchNo', 'quantity', 'unit', 'supplier'],
  },
  {
    type: 'small',
    nameKey: 'labelSmall',
    width: 50,
    height: 30,
    fields: ['qrCode', 'materialName', 'quantity', 'parentBatch'],
  },
  {
    type: 'finished',
    nameKey: 'labelFinished',
    width: 80,
    height: 60,
    fields: ['qrCode', 'productName', 'workOrderNo', 'quantity', 'date', 'quality'],
  },
  {
    type: 'shipping',
    nameKey: 'labelShipping',
    width: 100,
    height: 80,
    fields: ['qrCode', 'orderNo', 'customerName', 'quantity', 'address', 'date'],
  },
  {
    type: 'workorder',
    nameKey: 'labelWorkorder',
    width: 100,
    height: 80,
    fields: ['qrCode', 'workOrderNo', 'productName', 'quantity', 'processFlow', 'planDate'],
  },
  {
    type: 'ink',
    nameKey: 'labelInk',
    width: 60,
    height: 40,
    fields: ['qrCode', 'inkName', 'batchNo', 'quantity', 'color', 'expiryDate'],
  },
];

interface PrintData {
  materialName?: string;
  batchNo?: string;
  quantity?: number;
  unit?: string;
  supplier?: string;
  productName?: string;
  workOrderNo?: string;
  date?: string;
  quality?: string;
  customerName?: string;
  orderNo?: string;
  address?: string;
  inkName?: string;
  color?: string;
  expiryDate?: string;
  parentBatch?: string;
  processFlow?: string;
  planDate?: string;
}

interface QRCodePrinterProps {
  qrCode: string;
  labelType?: LabelType;
  printData?: PrintData;
  showDialog?: boolean;
  onDialogChange?: (open: boolean) => void;
  onPrintSuccess?: (result: Loose) => void;
  variant?: 'default' | 'outline' | 'ghost';
  size?: 'default' | 'sm' | 'lg' | 'icon';
  icon?: 'print' | 'preview' | 'both';
}

export function QRCodePrinter({
  qrCode,
  labelType = 'material',
  printData = {},
  showDialog: externalShowDialog,
  onDialogChange,
  onPrintSuccess,
  variant = 'outline',
  size = 'sm',
  icon = 'both',
}: QRCodePrinterProps) {
  const { toast } = useToast();
  const t = useTranslations('QRCode');
  const tc = useTranslations('Common');
  const [internalShowDialog, setInternalShowDialog] = useState(false);
  const [showPreview, setShowPreview] = useState(false);
  const [isPrinting, setIsPrinting] = useState(false);
  const [selectedLabel, setSelectedLabel] = useState<LabelTemplate>(
    labelTemplates.find((tpl) => tpl.type === labelType) || labelTemplates[0]
  );
  const [copies, setCopies] = useState(1);

  const showDialog = externalShowDialog ?? internalShowDialog;
  const setShowDialog = (open: boolean) => {
    if (onDialogChange) {
      onDialogChange(open);
    } else {
      setInternalShowDialog(open);
    }
  };

  const handlePrint = async () => {
    const ctx = { module: 'qrcode', action: 'print' };
    logger.stepStart(ctx, 'handlePrint', {
      qr_code: qrCode,
      label_type: selectedLabel.type,
      copies,
    });

    setIsPrinting(true);
    try {
      const payload = {
        qr_code: qrCode,
        label_type: selectedLabel.type,
        label_spec: `L-${selectedLabel.width}x${selectedLabel.height}`,
        copies,
        data: printData,
      };
      logger.info(ctx, '调用打印接口', { payload });
      const res = await fetch('/api/qrcode/print', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const result = await res.json();

      if (result.success) {
        logger.stepEnd(ctx, 'handlePrint', { result: result.data });
        toast({ title: t('printJobSent'), description: t('printCopiesSent', { count: copies }) });
        onPrintSuccess?.(result.data);
        setShowDialog(false);
      } else {
        logger.warn(ctx, '打印接口返回失败', { message: result.message });
        toast({ title: t('printFailed'), description: result.message, variant: 'destructive' });
      }
    } catch (error) {
      logger.error(ctx, '打印异常', {
        error: error instanceof Error ? error.message : String(error),
      });
      toast({
        title: t('printFailed'),
        description: t('printServiceError'),
        variant: 'destructive',
      });
    } finally {
      setIsPrinting(false);
    }
  };

  const renderLabelPreview = () => {
    const template = selectedLabel;
    const scale = 2;
    const width = template.width * scale * 3;
    const height = template.height * scale * 3;

    return (
      <div
        className="bg-white border-2 border-dashed border-gray-300 rounded shadow-sm"
        style={{ width, height, padding: '12px' }}
      >
        <div className="flex gap-3 h-full">
          <div className="flex-shrink-0 flex items-center">
            <QRCodeSVG value={qrCode} size={Math.min(width * 0.35, 80)} level="H" />
          </div>
          <div className="flex-1 flex flex-col justify-center text-xs space-y-1 overflow-hidden">
            <div className="font-bold text-sm truncate">
              {printData.materialName || printData.productName || t('defaultMaterialName')}
            </div>
            <div className="font-mono text-[10px] text-gray-500 truncate">{qrCode}</div>
            {template.fields.includes('batchNo') && printData.batchNo && (
              <div className="truncate">
                {tc('batch')}: {printData.batchNo}
              </div>
            )}
            {template.fields.includes('quantity') && printData.quantity && (
              <div className="truncate">
                {tc('quantity')}: {printData.quantity} {printData.unit || ''}
              </div>
            )}
            {template.fields.includes('supplier') && printData.supplier && (
              <div className="truncate">
                {tc('supplier')}: {printData.supplier}
              </div>
            )}
            {template.fields.includes('workOrderNo') && printData.workOrderNo && (
              <div className="truncate">
                {tc('workOrder')}: {printData.workOrderNo}
              </div>
            )}
            {template.fields.includes('quality') && printData.quality && (
              <div className="truncate">
                {t('quality')}: {printData.quality}
              </div>
            )}
            {template.fields.includes('date') && printData.date && (
              <div className="truncate">
                {tc('date')}: {printData.date}
              </div>
            )}
          </div>
        </div>
      </div>
    );
  };

  return (
    <>
      {icon === 'print' && (
        <Button variant={variant} size={size} onClick={() => setShowDialog(true)}>
          <Printer className="h-4 w-4 mr-1" />
          {tc('print')}
        </Button>
      )}
      {icon === 'preview' && (
        <Button variant={variant} size={size} onClick={() => setShowPreview(true)}>
          <Eye className="h-4 w-4 mr-1" />
          {tc('preview')}
        </Button>
      )}
      {icon === 'both' && (
        <div className="flex gap-2">
          <Button variant={variant} size={size} onClick={() => setShowPreview(true)}>
            <Eye className="h-4 w-4 mr-1" />
            {tc('preview')}
          </Button>
          <Button variant={variant} size={size} onClick={() => setShowDialog(true)}>
            <Printer className="h-4 w-4 mr-1" />
            {tc('print')}
          </Button>
        </div>
      )}

      {/* 预览对话框 */}
      <Dialog open={showPreview} onOpenChange={setShowPreview}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>
              {t('labelPreview')} - {t(selectedLabel.nameKey)}
            </DialogTitle>
          </DialogHeader>
          <div className="flex justify-center py-4">{renderLabelPreview()}</div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowPreview(false)}>
              {tc('close')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* 打印配置对话框 */}
      <Dialog open={showDialog} onOpenChange={setShowDialog}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{t('printConfig')}</DialogTitle>
          </DialogHeader>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label>{t('labelTemplate')}</Label>
              <Select
                value={selectedLabel.type}
                onValueChange={(v) => {
                  const ctx = { module: 'qrcode', action: 'select_template' };
                  const template = labelTemplates.find((tpl) => tpl.type === v);
                  if (template) {
                    logger.branch(ctx, 'select_template', `type=${v}`, true, { template });
                    setSelectedLabel(template);
                  } else {
                    logger.warn(ctx, '未找到匹配模板', { type: v });
                  }
                }}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {labelTemplates.map((tpl) => (
                    <SelectItem key={tpl.type} value={tpl.type}>
                      {t(tpl.nameKey)} ({tpl.width}x{tpl.height}mm)
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>{t('printCopies')}</Label>
              <Input
                type="number"
                min={1}
                max={100}
                value={copies}
                onChange={(e) => setCopies(Number(e.target.value))}
              />
            </div>
          </div>

          <div className="border-2 border-dashed rounded-lg p-4 bg-muted/30">
            <div className="text-sm text-muted-foreground mb-2">
              {t('labelPreview')} ({selectedLabel.width}x{selectedLabel.height}mm)
            </div>
            <div className="flex justify-center">{renderLabelPreview()}</div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowDialog(false)}>
              {tc('cancel')}
            </Button>
            <Button onClick={handlePrint} disabled={isPrinting}>
              {isPrinting && <Loader2 className="h-4 w-4 mr-1 animate-spin" />}
              <Printer className="h-4 w-4 mr-1" />
              {t('confirmPrint')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

'use client';

import { useState, useRef, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  ScanLine,
  Camera,
  Keyboard,
  X,
  CheckCircle2,
  AlertCircle,
  History,
  Loader2,
} from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { useLocale } from 'next-intl';

type ScanMode = 'inbound' | 'outbound' | 'feed' | 'query' | 'verify';

interface ScanHistoryItem {
  qrCode: string;
  time: string;
  success: boolean;
  message?: string;
}

interface QRCodeScannerProps {
  placeholder?: string;
  onScan: (qrCode: string) => Promise<void> | void;
  validate?: (qrCode: string) => Promise<boolean | { valid: boolean; message?: string }>;
  scanMode?: ScanMode;
  autoFocus?: boolean;
  showHistory?: boolean;
  showCamera?: boolean;
  inputOnly?: boolean;
  disabled?: boolean;
  className?: string;
}

export function QRCodeScanner({
  placeholder = '扫描或输入二维码...',
  onScan,
  validate,
  scanMode = 'query',
  autoFocus = true,
  showHistory = true,
  showCamera = true,
  inputOnly = false,
  disabled = false,
  className = '',
}: QRCodeScannerProps) {
  const { toast } = useToast();
  const locale = useLocale();
  const [mode, setMode] = useState<'manual' | 'camera'>('manual');
  const [inputValue, setInputValue] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [history, setHistory] = useState<ScanHistoryItem[]>([]);
  const [lastResult, setLastResult] = useState<{ success: boolean; message?: string } | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (autoFocus && inputRef.current) {
      inputRef.current.focus();
    }
  }, [autoFocus]);

  const processScan = async (qrCode: string) => {
    if (!qrCode || qrCode.trim() === '') return;

    const trimmedCode = qrCode.trim();
    setIsProcessing(true);
    setLastResult(null);

    try {
      // 验证二维码
      if (validate) {
        const validationResult = await validate(trimmedCode);
        const isValid =
          typeof validationResult === 'boolean' ? validationResult : validationResult.valid;
        const message = typeof validationResult === 'object' ? validationResult.message : undefined;

        if (!isValid) {
          setLastResult({ success: false, message: message || '验证失败' });
          setHistory((prev) => [
            {
              qrCode: trimmedCode,
              time: new Date().toISOString(),
              success: false,
              message: message || '验证失败',
            },
            ...prev.slice(0, 19),
          ]);
          toast({
            title: '验证失败',
            description: message || '二维码验证不通过',
            variant: 'destructive',
          });
          setIsProcessing(false);
          return;
        }
      }

      // 执行扫描回调
      await onScan(trimmedCode);

      setLastResult({ success: true });
      setHistory((prev) => [
        {
          qrCode: trimmedCode,
          time: new Date().toISOString(),
          success: true,
        },
        ...prev.slice(0, 19),
      ]);

      toast({ title: '扫描成功', description: trimmedCode });

      // 清空输入
      setInputValue('');
    } catch (error) {
      setLastResult({ success: false, message: (error as Error).message || '处理失败' });
      setHistory((prev) => [
        {
          qrCode: trimmedCode,
          time: new Date().toISOString(),
          success: false,
          message: (error as Error).message || '处理失败',
        },
        ...prev.slice(0, 19),
      ]);
      toast({
        title: '扫描失败',
        description: (error as Error).message || '请重试',
        variant: 'destructive',
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && inputValue.trim()) {
      e.preventDefault();
      processScan(inputValue);
    }
  };

  const handleClearHistory = () => {
    setHistory([]);
  };

  const getModeLabel = () => {
    switch (scanMode) {
      case 'inbound':
        return '扫码入库';
      case 'outbound':
        return '扫码出库';
      case 'feed':
        return '扫码投料';
      case 'query':
        return '扫码查询';
      case 'verify':
        return '扫码验证';
      default:
        return '扫码';
    }
  };

  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base flex items-center gap-2">
            <ScanLine className="h-5 w-5" />
            {getModeLabel()}
          </CardTitle>
          {!inputOnly && showCamera && (
            <div className="flex gap-1">
              <Button
                variant={mode === 'manual' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setMode('manual')}
              >
                <Keyboard className="h-4 w-4" />
              </Button>
              <Button
                variant={mode === 'camera' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setMode('camera')}
                disabled
              >
                <Camera className="h-4 w-4" />
              </Button>
            </div>
          )}
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* 输入区域 */}
        <div className="flex gap-2">
          <div className="relative flex-1">
            <Input
              ref={inputRef}
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={placeholder}
              disabled={disabled || isProcessing}
              className="font-mono"
            />
            {inputValue && (
              <Button
                variant="ghost"
                size="sm"
                className="absolute right-1 top-1/2 -translate-y-1/2 h-6 w-6 p-0"
                onClick={() => setInputValue('')}
              >
                <X className="h-4 w-4" />
              </Button>
            )}
          </div>
          <Button
            onClick={() => processScan(inputValue)}
            disabled={disabled || isProcessing || !inputValue.trim()}
          >
            {isProcessing ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <>
                <ScanLine className="h-4 w-4 mr-1" />
                确认
              </>
            )}
          </Button>
        </div>

        {/* 扫描结果提示 */}
        {lastResult && (
          <div
            className={`flex items-center gap-2 p-3 rounded-lg ${
              lastResult.success ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
            }`}
          >
            {lastResult.success ? (
              <CheckCircle2 className="h-5 w-5" />
            ) : (
              <AlertCircle className="h-5 w-5" />
            )}
            <span className="text-sm font-medium">
              {lastResult.success ? '验证成功' : lastResult.message}
            </span>
          </div>
        )}

        {/* 历史记录 */}
        {showHistory && history.length > 0 && (
          <div className="border-t pt-3">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <History className="h-4 w-4" />
                <span>
                  {'扫描历史'}
                  {history.length})
                </span>
              </div>
              <Button variant="ghost" size="sm" onClick={handleClearHistory}>
                清空
              </Button>
            </div>
            <div className="space-y-1 max-h-32 overflow-y-auto">
              {history.slice(0, 5).map((item, index) => (
                <div
                  key={index}
                  className={`flex items-center justify-between text-xs p-2 rounded ${
                    item.success ? 'bg-green-50' : 'bg-red-50'
                  }`}
                >
                  <div className="flex items-center gap-2">
                    {item.success ? (
                      <CheckCircle2 className="h-3 w-3 text-green-500" />
                    ) : (
                      <AlertCircle className="h-3 w-3 text-red-500" />
                    )}
                    <span className="font-mono">{item.qrCode}</span>
                  </div>
                  <span className="text-muted-foreground">
                    {new Date(item.time).toLocaleTimeString(locale)}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Search, ScanLine, List } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { QRCodeTypeLabels, QRCodeStatusLabels } from './qr-code-types';
import type { QRCodeRecord } from './qr-code-types';

interface QRCodeSearchProps {
  onSelect?: (qrCode: string, record: QRCodeRecord) => void;
  onTrace?: (qrCode: string) => void;
  showResult?: boolean;
  singleSelect?: boolean;
  className?: string;
}

export function QRCodeSearch({
  onSelect,
  onTrace,
  showResult = true,
  singleSelect = false,
  className = '',
}: QRCodeSearchProps) {
  const { toast } = useToast();
  const [searchType, setSearchType] = useState<'qr_code' | 'ref_no' | 'batch_no' | 'material'>(
    'qr_code'
  );
  const [keyword, setKeyword] = useState('');
  const [results, setResults] = useState<QRCodeRecord[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [selectedQRCode, setSelectedQRCode] = useState<string | null>(null);

  const handleSearch = async () => {
    if (!keyword.trim()) {
      toast({ title: '请输入搜索关键词', variant: 'destructive' });
      return;
    }

    setIsSearching(true);
    setHasSearched(true);
    setSelectedQRCode(null);

    try {
      const params = new URLSearchParams();

      switch (searchType) {
        case 'qr_code':
          params.set('qr_code', keyword);
          break;
        case 'ref_no':
          params.set('ref_no', keyword);
          break;
        case 'batch_no':
          params.set('batch_no', keyword);
          break;
        case 'material':
          params.set('keyword', keyword);
          break;
      }

      const res = await fetch('/api/qrcode?' + params);
      const result = await res.json();

      if (result.success) {
        setResults(result.data?.list || []);
        if (result.data?.list?.length === 0) {
          toast({ title: '未找到相关记录' });
        }
      } else {
        toast({ title: '搜索失败', description: result.message, variant: 'destructive' });
      }
    } catch {
      toast({ title: '搜索失败', variant: 'destructive' });
    } finally {
      setIsSearching(false);
    }
  };

  const handleSelect = (record: QRCodeRecord) => {
    if (singleSelect) {
      setSelectedQRCode(record.qr_code);
    }
    onSelect?.(record.qr_code, record);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <CardTitle className="text-base flex items-center gap-2">
          <Search className="h-5 w-5" />
          二维码查询
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* 搜索区域 */}
        <div className="flex gap-2">
          <div className="flex gap-1">
            <Button
              variant={searchType === 'qr_code' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setSearchType('qr_code')}
            >
              <ScanLine className="h-4 w-4 mr-1" />
              二维码
            </Button>
            <Button
              variant={searchType === 'ref_no' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setSearchType('ref_no')}
            >
              单号
            </Button>
            <Button
              variant={searchType === 'batch_no' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setSearchType('batch_no')}
            >
              批次
            </Button>
            <Button
              variant={searchType === 'material' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setSearchType('material')}
            >
              <List className="h-4 w-4 mr-1" />
              物料
            </Button>
          </div>
        </div>

        <div className="flex gap-2">
          <Input
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={
              searchType === 'qr_code'
                ? '输入二维码编码搜索...'
                : searchType === 'ref_no'
                  ? '输入单号搜索...'
                  : searchType === 'batch_no'
                    ? '输入批次号搜索...'
                    : '输入物料名称或编码搜索...'
            }
            className="flex-1"
          />
          <Button onClick={handleSearch} disabled={isSearching}>
            {isSearching ? '搜索中...' : '搜索'}
          </Button>
        </div>

        {/* 搜索结果 */}
        {showResult && hasSearched && (
          <div className="border rounded-lg">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-12">选择</TableHead>
                  <TableHead>二维码编码</TableHead>
                  <TableHead>类型</TableHead>
                  <TableHead>关联单号</TableHead>
                  <TableHead>物料名称</TableHead>
                  <TableHead>数量</TableHead>
                  <TableHead>状态</TableHead>
                  <TableHead>操作</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {results.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={8} className="text-center py-8 text-muted-foreground">
                      未找到相关记录
                    </TableCell>
                  </TableRow>
                ) : (
                  results.map((record) => (
                    <TableRow
                      key={record.id}
                      className={selectedQRCode === record.qr_code ? 'bg-muted' : ''}
                    >
                      <TableCell>
                        <input
                          type="radio"
                          name="qrcode-select"
                          checked={selectedQRCode === record.qr_code}
                          onChange={() => handleSelect(record)}
                        />
                      </TableCell>
                      <TableCell className="font-mono text-xs">{record.qr_code}</TableCell>
                      <TableCell>
                        <Badge variant="outline">
                          {QRCodeTypeLabels[record.qr_type] || record.qr_type}
                        </Badge>
                      </TableCell>
                      <TableCell className="font-mono text-sm">{record.ref_no || '-'}</TableCell>
                      <TableCell>{record.material_name || '-'}</TableCell>
                      <TableCell>
                        {record.quantity} {record.unit || ''}
                      </TableCell>
                      <TableCell>
                        <Badge variant={QRCodeStatusLabels[record.status]?.variant}>
                          {QRCodeStatusLabels[record.status]?.label || '未知'}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          {onTrace && (
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => onTrace(record.qr_code)}
                            >
                              追溯
                            </Button>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

