'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { QRCodeSVG } from 'qrcode.react';
import {
  Search,
  Package,
  Truck,
  Factory,
  CheckCircle2,
  Clock,
  User,
  Loader2,
  Box,
  Layers,
  ScanLine,
} from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { useLocale, useTranslations } from 'next-intl';
import type { TraceData } from './qr-code-types';

interface QRCodeTraceProps {
  qrCode?: string;
  showDialog?: boolean;
  onDialogChange?: (open: boolean) => void;
  initialQRCode?: string;
}

const eventIcons: Record<string, Loose> = {
  原材料入库: Package,
  小料拆分: Layers,
  生产领料: Box,
  投料: ScanLine,
  生产报工: Factory,
  成品入库: Package,
  销售发货: Truck,
  质检: CheckCircle2,
  默认: Clock,
};

const eventColors: Record<string, string> = {
  原材料入库: 'bg-blue-500',
  小料拆分: 'bg-purple-500',
  生产领料: 'bg-orange-500',
  投料: 'bg-yellow-500',
  生产报工: 'bg-green-500',
  成品入库: 'bg-green-600',
  销售发货: 'bg-teal-500',
  质检: 'bg-emerald-500',
};

export function QRCodeTrace({
  qrCode: initialQRCode,
  showDialog: externalShowDialog,
  onDialogChange,
  initialQRCode: propQRCode,
}: QRCodeTraceProps) {
  const { toast } = useToast();
  const locale = useLocale();
  const t = useTranslations('QRCode');
  const tc = useTranslations('Common');

  const typeMap: Record<string, string> = {
    material: t('rawMaterial'),
    product: t('finished'),
    workorder: tc('workOrder'),
    ink: t('ink'),
    screen_plate: t('screen'),
    die: t('blade'),
    shipment: t('shipment'),
    ink_open: t('inkOpen'),
    ink_mixed: t('inkMixed'),
  };

  const statusMap: Record<
    number,
    { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline' }
  > = {
    1: { label: t('valid'), variant: 'default' },
    2: { label: t('used'), variant: 'secondary' },
    3: { label: t('expired'), variant: 'outline' },
    9: { label: t('void'), variant: 'destructive' },
  };
  const [internalShowDialog, setInternalShowDialog] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [traceData, setTraceData] = useState<TraceData | null>(null);
  const [inputQRCode, setInputQRCode] = useState(propQRCode || initialQRCode || '');

  const showDialog = externalShowDialog ?? internalShowDialog;
  const setShowDialog = (open: boolean) => {
    if (onDialogChange) {
      onDialogChange(open);
    } else {
      setInternalShowDialog(open);
    }
  };

  const qrCode = propQRCode || initialQRCode || inputQRCode;

  const handleTrace = async () => {
    if (!qrCode) {
      toast({ title: t('enterQrCode'), variant: 'destructive' });
      return;
    }

    setIsLoading(true);
    try {
      const params = new URLSearchParams({ qr_code: qrCode });
      const res = await fetch('/api/qrcode/trace?' + params);
      const result = await res.json();

      if (result.success) {
        setTraceData(result.data);
        if (!result.data?.timeline?.length) {
          toast({ title: t('noTraceFound') });
        }
      } else {
        toast({ title: t('queryFailed'), description: result.message, variant: 'destructive' });
      }
    } catch {
      toast({ title: t('queryFailed'), variant: 'destructive' });
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleTrace();
    }
  };

  useEffect(() => {
    if (qrCode && showDialog) {
      handleTrace();
    }
  }, [qrCode, showDialog]);

  const renderTimeline = () => {
    if (!traceData?.timeline?.length) {
      return (
        <div className="text-center py-12 text-muted-foreground">
          <Clock className="h-12 w-12 mx-auto mb-3 opacity-50" />
          <p>{t('noTraceRecords')}</p>
        </div>
      );
    }

    return (
      <div className="space-y-0">
        {traceData.timeline.map((event, index) => {
          const IconComponent = eventIcons[event.event] || eventIcons['默认'];
          const colorClass = eventColors[event.event] || 'bg-gray-500';

          return (
            <div key={index} className="flex gap-4">
              {/* 时间线节点 */}
              <div className="flex flex-col items-center">
                <div
                  className={`h-10 w-10 rounded-full ${colorClass} flex items-center justify-center text-white`}
                >
                  <IconComponent className="h-5 w-5" />
                </div>
                {index < traceData.timeline.length - 1 && <div className="w-0.5 h-16 bg-border" />}
              </div>

              {/* 时间线内容 */}
              <div className="flex-1 pb-6">
                <div className="bg-muted/50 rounded-lg p-3">
                  <div className="flex items-center justify-between mb-2">
                    <span className="font-medium">{event.event}</span>
                    <span className="text-xs text-muted-foreground">
                      {new Date(event.time).toLocaleString(locale)}
                    </span>
                  </div>
                  <div className="flex items-center gap-4 text-xs text-muted-foreground">
                    <span className="flex items-center gap-1">
                      <User className="h-3 w-3" />
                      {event.operator}
                    </span>
                    <span
                      className={`flex items-center gap-1 ${event.result === 'success' ? 'text-green-600' : 'text-red-600'}`}
                    >
                      {event.result === 'success' ? (
                        <CheckCircle2 className="h-3 w-3" />
                      ) : (
                        <Clock className="h-3 w-3" />
                      )}
                      {event.result === 'success' ? t('success') : t('fail')}
                    </span>
                  </div>
                  {event.message && (
                    <div className="mt-2 text-sm text-muted-foreground">{event.message}</div>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <>
      {!showDialog && (
        <Button variant="outline" size="sm" onClick={() => setShowDialog(true)}>
          <Search className="h-4 w-4 mr-1" />
          {t('traceQuery')}
        </Button>
      )}

      <Dialog open={showDialog} onOpenChange={setShowDialog}>
        <DialogContent className="max-w-4xl max-h-[85vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{t('qrTraceQuery')}</DialogTitle>
          </DialogHeader>

          {/* 搜索区域 */}
          <div className="flex gap-2 mb-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                value={inputQRCode}
                onChange={(e) => setInputQRCode(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder={t('traceInputPlaceholder')}
                className="pl-10 font-mono"
              />
            </div>
            <Button onClick={handleTrace} disabled={isLoading}>
              {isLoading && <Loader2 className="h-4 w-4 mr-1 animate-spin" />}
              {tc('search')}
            </Button>
          </div>

          {traceData ? (
            <Tabs defaultValue="timeline">
              <TabsList className="w-full">
                <TabsTrigger value="timeline">{t('traceTimeline')}</TabsTrigger>
                <TabsTrigger value="info">{t('basicInfo')}</TabsTrigger>
                <TabsTrigger value="related">{t('relatedRecords')}</TabsTrigger>
                <TabsTrigger value="inventory">{t('inventoryInfo')}</TabsTrigger>
              </TabsList>

              {/* 时间线视图 */}
              <TabsContent value="timeline" className="mt-4">
                <Card>
                  <CardHeader className="pb-2">
                    <div className="flex items-center justify-between">
                      <CardTitle className="text-base">{t('traceLink')}</CardTitle>
                      <div className="flex items-center gap-2">
                        <QRCodeSVG value={qrCode} size={60} level="H" />
                        <div className="text-sm">
                          <div className="font-mono font-medium">{qrCode}</div>
                          <Badge variant="outline" className="mt-1">
                            {typeMap[traceData.record?.qr_type as Loose] ||
                              traceData.record?.qr_type}
                          </Badge>
                        </div>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent>{renderTimeline()}</CardContent>
                </Card>
              </TabsContent>

              {/* 基本信息 */}
              <TabsContent value="info" className="mt-4">
                {traceData.record ? (
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-3">
                      <div className="text-sm">
                        <span className="text-muted-foreground">{t('qrCodeLabel')}：</span>
                        <span className="font-mono">{traceData.record.qr_code}</span>
                      </div>
                      <div className="text-sm">
                        <span className="text-muted-foreground">{tc('type')}：</span>
                        <Badge variant="outline">
                          {typeMap[traceData.record.qr_type as Loose] || traceData.record.qr_type}
                        </Badge>
                      </div>
                      <div className="text-sm">
                        <span className="text-muted-foreground">{tc('status')}：</span>
                        <Badge variant={statusMap[traceData.record.status as Loose]?.variant}>
                          {statusMap[traceData.record.status as Loose]?.label}
                        </Badge>
                      </div>
                      <div className="text-sm">
                        <span className="text-muted-foreground">{t('refNo')}：</span>
                        {traceData.record.ref_no || '-'}
                      </div>
                      <div className="text-sm">
                        <span className="text-muted-foreground">{tc('batchNo')}：</span>
                        {traceData.record.batch_no || '-'}
                      </div>
                    </div>
                    <div className="space-y-3">
                      <div className="text-sm">
                        <span className="text-muted-foreground">{t('materialName')}：</span>
                        {traceData.record.material_name || '-'}
                      </div>
                      <div className="text-sm">
                        <span className="text-muted-foreground">{tc('specification')}：</span>
                        {traceData.record.specification || '-'}
                      </div>
                      <div className="text-sm">
                        <span className="text-muted-foreground">{tc('quantity')}：</span>
                        {traceData.record.quantity} {traceData.record.unit || ''}
                      </div>
                      <div className="text-sm">
                        <span className="text-muted-foreground">{tc('warehouse')}：</span>
                        {traceData.record.warehouse_name || '-'}
                      </div>
                      <div className="text-sm">
                        <span className="text-muted-foreground">{tc('supplier')}：</span>
                        {traceData.record.supplier_name || '-'}
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="text-center py-8 text-muted-foreground">{t('noBasicInfo')}</div>
                )}
              </TabsContent>

              {/* 关联记录 */}
              <TabsContent value="related" className="mt-4">
                {traceData.related_records?.length ? (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>{t('qrCodeLabel')}</TableHead>
                        <TableHead>{tc('type')}</TableHead>
                        <TableHead>{tc('orderNo')}</TableHead>
                        <TableHead>{tc('material')}</TableHead>
                        <TableHead>{tc('quantity')}</TableHead>
                        <TableHead>{tc('status')}</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {traceData.related_records.map((record, i) => (
                        <TableRow key={i}>
                          <TableCell className="font-mono text-xs">{record.qr_code}</TableCell>
                          <TableCell>
                            <Badge variant="outline">
                              {typeMap[record.qr_type as Loose] || record.qr_type}
                            </Badge>
                          </TableCell>
                          <TableCell className="font-mono text-sm">
                            {record.ref_no || '-'}
                          </TableCell>
                          <TableCell>{record.material_name || '-'}</TableCell>
                          <TableCell>{record.quantity}</TableCell>
                          <TableCell>
                            <Badge variant={statusMap[record.status as Loose]?.variant}>
                              {statusMap[record.status as Loose]?.label}
                            </Badge>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                ) : (
                  <div className="text-center py-8 text-muted-foreground">
                    {t('noRelatedRecords')}
                  </div>
                )}
              </TabsContent>

              {/* 库存信息 */}
              <TabsContent value="inventory" className="mt-4">
                {traceData.inventory?.length ? (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>{tc('warehouse')}</TableHead>
                        <TableHead>{tc('materialCode')}</TableHead>
                        <TableHead>{t('materialName')}</TableHead>
                        <TableHead className="text-right">{t('inventoryQty')}</TableHead>
                        <TableHead>{tc('unit')}</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {traceData.inventory.map((inv, i) => (
                        <TableRow key={i}>
                          <TableCell>{inv.warehouse_name || '-'}</TableCell>
                          <TableCell className="font-mono text-sm">{inv.material_code}</TableCell>
                          <TableCell>{inv.material_name}</TableCell>
                          <TableCell className="text-right">{inv.quantity}</TableCell>
                          <TableCell>{inv.unit}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                ) : (
                  <div className="text-center py-8 text-muted-foreground">
                    {t('noInventoryInfo')}
                  </div>
                )}
              </TabsContent>
            </Tabs>
          ) : (
            <div className="text-center py-12 text-muted-foreground">
              <Search className="h-12 w-12 mx-auto mb-3 opacity-50" />
              <p>{t('enterQrCodeToTrace')}</p>
            </div>
          )}

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowDialog(false)}>
              {tc('close')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { QRCodeSVG } from 'qrcode.react';
import { Eye, Download, Copy, ExternalLink, Loader2 } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { QRCodeTypeLabels, QRCodeStatusLabels } from './qr-code-types';
import type { QRCodeRecord } from './qr-code-types';

interface QRCodeViewerProps {
  qrCode: string;
  showDialog?: boolean;
  onDialogChange?: (open: boolean) => void;
  onTrace?: (qrCode: string) => void;
}

export function QRCodeViewer({
  qrCode,
  showDialog: externalShowDialog,
  onDialogChange,
  onTrace,
}: QRCodeViewerProps) {
  const { toast } = useToast();
  const [internalShowDialog, setInternalShowDialog] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [record, setRecord] = useState<QRCodeRecord | null>(null);

  const showDialog = externalShowDialog ?? internalShowDialog;
  const setShowDialog = (open: boolean) => {
    if (onDialogChange) {
      onDialogChange(open);
    } else {
      setInternalShowDialog(open);
    }
    if (open && qrCode) {
      fetchQRCodeInfo();
    }
  };

  const fetchQRCodeInfo = async () => {
    setIsLoading(true);
    try {
      const params = new URLSearchParams({ qr_code: qrCode });
      const res = await fetch('/api/qrcode/trace?' + params);
      const result = await res.json();

      if (result.success && result.data?.record) {
        setRecord(result.data.record);
      }
    } catch {
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({ title: '已复制到剪贴板' });
  };

  const handleDownload = () => {
    const canvas = document.createElement('canvas');
    const svg = document.querySelector(
      `#qrcode-${qrCode.replace(/[^a-zA-Z0-9]/g, '')} svg`
    ) as SVGElement;
    if (!svg) return;

    const svgData = new XMLSerializer().serializeToString(svg);
    const img = new Image();
    img.onload = () => {
      canvas.width = 200;
      canvas.height = 200;
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(img, 0, 0);
      const link = document.createElement('a');
      link.download = `${qrCode}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    };
    img.src = 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svgData)));
  };

  return (
    <>
      <Button variant="outline" size="sm" onClick={() => setShowDialog(true)}>
        <Eye className="h-4 w-4 mr-1" />
        查看
      </Button>

      <Dialog open={showDialog} onOpenChange={setShowDialog}>
        <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>二维码详情</DialogTitle>
          </DialogHeader>

          {isLoading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : (
            <div className="grid grid-cols-3 gap-6">
              {/* 二维码展示 */}
              <div className="col-span-1 flex flex-col items-center">
                <div className="bg-white p-4 rounded-lg shadow-sm border">
                  <div id={`qrcode-${qrCode.replace(/[^a-zA-Z0-9]/g, '')}`}>
                    <QRCodeSVG value={qrCode} size={160} level="H" includeMargin />
                  </div>
                </div>
                <p className="mt-3 font-mono text-sm font-medium break-all text-center">{qrCode}</p>
                <div className="flex gap-2 mt-3">
                  <Button variant="outline" size="sm" onClick={() => handleCopy(qrCode)}>
                    <Copy className="h-4 w-4" />
                  </Button>
                  <Button variant="outline" size="sm" onClick={handleDownload}>
                    <Download className="h-4 w-4" />
                  </Button>
                </div>
              </div>

              {/* 信息展示 */}
              <div className="col-span-2">
                <Tabs defaultValue="info">
                  <TabsList className="w-full">
                    <TabsTrigger value="info">基本信息</TabsTrigger>
                    <TabsTrigger value="extend">扩展信息</TabsTrigger>
                  </TabsList>

                  <TabsContent value="info" className="space-y-3 mt-4">
                    {record ? (
                      <>
                        <div className="grid grid-cols-2 gap-3 text-sm">
                          <div>
                            <span className="text-muted-foreground">类型：</span>
                            <Badge variant="outline">
                              {QRCodeTypeLabels[record.qr_type] || record.qr_type}
                            </Badge>
                          </div>
                          <div>
                            <span className="text-muted-foreground">状态：</span>
                            <Badge variant={QRCodeStatusLabels[record.status]?.variant}>
                              {QRCodeStatusLabels[record.status]?.label || '未知'}
                            </Badge>
                          </div>
                          <div>
                            <span className="text-muted-foreground">关联单号：</span>
                            <span className="font-mono">{record.ref_no || '-'}</span>
                          </div>
                          <div>
                            <span className="text-muted-foreground">批次号：</span>
                            <span>{record.batch_no || '-'}</span>
                          </div>
                          <div>
                            <span className="text-muted-foreground">物料名称：</span>
                            <span>{record.material_name || '-'}</span>
                          </div>
                          <div>
                            <span className="text-muted-foreground">规格：</span>
                            <span>{record.specification || '-'}</span>
                          </div>
                          <div>
                            <span className="text-muted-foreground">数量：</span>
                            <span>
                              {record.quantity} {record.unit || ''}
                            </span>
                          </div>
                          <div>
                            <span className="text-muted-foreground">仓库：</span>
                            <span>{record.warehouse_name || '-'}</span>
                          </div>
                          <div>
                            <span className="text-muted-foreground">供应商：</span>
                            <span>{record.supplier_name || '-'}</span>
                          </div>
                          <div>
                            <span className="text-muted-foreground">客户：</span>
                            <span>{record.customer_name || '-'}</span>
                          </div>
                        </div>
                      </>
                    ) : (
                      <div className="text-center py-8 text-muted-foreground">暂无详细信息</div>
                    )}
                  </TabsContent>

                  <TabsContent value="extend" className="space-y-3 mt-4">
                    {record ? (
                      <div className="grid grid-cols-2 gap-3 text-sm">
                        <div>
                          <span className="text-muted-foreground">工单编号：</span>
                          <span>{record.work_order_no || '-'}</span>
                        </div>
                        <div>
                          <span className="text-muted-foreground">生产日期：</span>
                          <span>{record.production_date?.slice(0, 10) || '-'}</span>
                        </div>
                        <div>
                          <span className="text-muted-foreground">有效期：</span>
                          <span>{record.expiry_date?.slice(0, 10) || '-'}</span>
                        </div>
                        <div>
                          <span className="text-muted-foreground">打印次数：</span>
                          <span>{record.print_count}</span>
                        </div>
                        <div>
                          <span className="text-muted-foreground">扫描次数：</span>
                          <span>{record.scan_count}</span>
                        </div>
                        <div>
                          <span className="text-muted-foreground">创建时间：</span>
                          <span>{record.create_time?.slice(0, 19).replace('T', ' ') || '-'}</span>
                        </div>
                        {record.remark && (
                          <div className="col-span-2">
                            <span className="text-muted-foreground">备注：</span>
                            <span>{record.remark}</span>
                          </div>
                        )}
                      </div>
                    ) : (
                      <div className="text-center py-8 text-muted-foreground">暂无扩展信息</div>
                    )}
                  </TabsContent>
                </Tabs>
              </div>
            </div>
          )}

          <DialogFooter>
            {onTrace && (
              <Button
                variant="outline"
                onClick={() => {
                  setShowDialog(false);
                  onTrace(qrCode);
                }}
              >
                <ExternalLink className="h-4 w-4 mr-1" />
                追溯
              </Button>
            )}
            <Button variant="outline" onClick={() => setShowDialog(false)}>
              关闭
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

'use client';

export type QRCodeType =
  | 'material' // 原材料
  | 'product' // 成品
  | 'workorder' // 工单
  | 'ink' // 油墨
  | 'screen_plate' // 网版
  | 'die' // 刀具
  | 'shipment' // 发货
  | 'ink_open' // 开罐
  | 'ink_mixed'; // 调色

export type SplitFlag = 0 | 1 | 2; // 0=整料, 1=小料, 2=余料

export type QRCodeStatus =
  | 1 // 有效
  | 2 // 已使用
  | 3 // 已失效
  | 9; // 已作废

export interface QRCodeRecord {
  id: number;
  qr_code: string;
  qr_type: QRCodeType;
  ref_id: number | null;
  ref_no: string | null;
  batch_no: string | null;
  material_id: number | null;
  material_code: string | null;
  material_name: string | null;
  specification: string | null;
  quantity: number | null;
  unit: string | null;
  warehouse_name: string | null;
  supplier_name: string | null;
  customer_name: string | null;
  work_order_no: string | null;
  production_date: string | null;
  expiry_date: string | null;
  print_count: number;
  scan_count: number;
  status: QRCodeStatus;
  create_time: string;
  remark: string | null;
}

export interface QRCodeGenerateParams {
  qr_type: QRCodeType;
  ref_id?: number;
  ref_no?: string;
  batch_no?: string;
  material_code?: string;
  material_name?: string;
  specification?: string;
  quantity?: number;
  unit?: string;
  warehouse_name?: string;
  supplier_name?: string;
  customer_name?: string;
  work_order_no?: string;
  production_date?: string;
  expiry_date?: string;
  remark?: string;
}

export interface QRCodePrintParams {
  qr_code: string;
  label_type: 'material' | 'small' | 'finished' | 'shipping' | 'workorder' | 'ink';
  label_spec?: string;
  printer_id?: number;
  copies?: number;
  data?: Record<string, any>;
}

export interface TraceEvent {
  event: string;
  time: string;
  operator: string;
  result: 'success' | 'fail';
  message?: string;
}

export interface TraceData {
  record: QRCodeRecord | null;
  order: Record<string, any> | null;
  timeline: TraceEvent[];
  related_records: QRCodeRecord[];
  inventory: Record<string, any>[];
}

export const QRCodeTypeLabels: Record<string, string> = {
  material: '原料',
  product: '成品',
  workorder: '工单',
  ink: '油墨',
  screen_plate: '网版',
  die: '刀具',
  shipment: '出货',
  ink_open: '开罐',
  ink_mixed: '调色',
};

export const QRCodeStatusLabels: Record<
  number,
  { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline' }
> = {
  1: { label: '有效', variant: 'default' },
  2: { label: '已使用', variant: 'secondary' },
  3: { label: '已失效', variant: 'outline' },
  9: { label: '已作废', variant: 'destructive' },
};

