'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Moon, Sun, Monitor } from 'lucide-react';
import { useTranslations } from 'next-intl';

type Theme = 'light' | 'dark' | 'system';

export function ThemeToggle() {
  const t = useTranslations('Theme');
  const [theme, setTheme] = useState<Theme>('light');
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    // 从 localStorage 读取主题设置
    const savedTheme = localStorage.getItem('theme') as Theme;
    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    }
  }, []);

  const applyTheme = (newTheme: Theme) => {
    const root = document.documentElement;

    if (newTheme === 'dark') {
      root.classList.add('dark');
    } else if (newTheme === 'light') {
      root.classList.remove('dark');
    } else {
      // system
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      if (prefersDark) {
        root.classList.add('dark');
      } else {
        root.classList.remove('dark');
      }
    }
  };

  const handleThemeChange = (newTheme: Theme) => {
    setTheme(newTheme);
    localStorage.setItem('theme', newTheme);
    applyTheme(newTheme);
  };

  // 监听系统主题变化
  useEffect(() => {
    if (theme === 'system') {
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handleChange = () => applyTheme('system');
      mediaQuery.addEventListener('change', handleChange);
      return () => mediaQuery.removeEventListener('change', handleChange);
    }
  }, [theme]);

  if (!mounted) {
    return (
      <Button variant="ghost" size="icon" className="w-9 h-9" suppressHydrationWarning>
        <Sun className="h-4 w-4" />
        <span className="sr-only">Theme</span>
      </Button>
    );
  }

  const getIcon = () => {
    switch (theme) {
      case 'dark':
        return <Moon className="h-4 w-4" />;
      case 'system':
        return <Monitor className="h-4 w-4" />;
      default:
        return <Sun className="h-4 w-4" />;
    }
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="icon" className="w-9 h-9">
          {getIcon()}
          <span className="sr-only">{t('toggle')}</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuItem onClick={() => handleThemeChange('light')}>
          <Sun className="h-4 w-4 mr-2" />
          {t('light')}
          {theme === 'light' && <span className="ml-auto text-primary">✓</span>}
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => handleThemeChange('dark')}>
          <Moon className="h-4 w-4 mr-2" />
          {t('dark')}
          {theme === 'dark' && <span className="ml-auto text-primary">✓</span>}
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => handleThemeChange('system')}>
          <Monitor className="h-4 w-4 mr-2" />
          {t('system')}
          {theme === 'system' && <span className="ml-auto text-primary">✓</span>}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { SlidersHorizontal, X, Search } from 'lucide-react';

export interface FilterField {
  key: string;
  label: string;
  type: 'text' | 'select' | 'date' | 'dateRange';
  options?: { label: string; value: string }[];
  placeholder?: string;
}

export interface ActiveFilter {
  key: string;
  label: string;
  value: string;
  displayValue: string;
}

interface AdvancedSearchProps {
  fields: FilterField[];
  onSearch: (filters: Record<string, string>) => void;
  onReset: () => void;
  activeFilters?: ActiveFilter[];
  onRemoveFilter?: (key: string) => void;
  className?: string;
}

export function AdvancedSearch({
  fields,
  onSearch,
  onReset,
  activeFilters = [],
  onRemoveFilter,
  className = '',
}: AdvancedSearchProps) {
  const [open, setOpen] = useState(false);
  const [filters, setFilters] = useState<Record<string, string>>({});

  const handleFieldChange = useCallback((key: string, value: string) => {
    setFilters((prev) => ({ ...prev, [key]: value }));
  }, []);

  const handleSearch = useCallback(() => {
    onSearch(filters);
    setOpen(false);
  }, [filters, onSearch]);

  const handleReset = useCallback(() => {
    setFilters({});
    onReset();
  }, [onReset]);

  const activeCount = activeFilters.length;

  return (
    <div className={`flex items-center gap-2 ${className}`}>
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button variant="outline" size="sm" className="gap-1">
            <SlidersHorizontal className="h-3.5 w-3.5" />
            高级搜索
            {activeCount > 0 && (
              <Badge variant="secondary" className="ml-1 h-5 px-1.5 text-xs">
                {activeCount}
              </Badge>
            )}
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-[400px] p-4" align="start">
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="font-medium text-sm">筛选条件</h4>
              <Button variant="ghost" size="sm" className="h-6 text-xs" onClick={handleReset}>
                重置
              </Button>
            </div>
            <div className="space-y-3 max-h-[400px] overflow-y-auto">
              {fields.map((field) => (
                <div key={field.key} className="space-y-1">
                  <Label className="text-xs">{field.label}</Label>
                  {field.type === 'text' && (
                    <Input
                      placeholder={field.placeholder || `输入${field.label}`}
                      value={filters[field.key] || ''}
                      onChange={(e) => handleFieldChange(field.key, e.target.value)}
                      className="h-8 text-sm"
                    />
                  )}
                  {field.type === 'select' && field.options && (
                    <Select
                      value={filters[field.key] || ''}
                      onValueChange={(v) => handleFieldChange(field.key, v === '__all__' ? '' : v)}
                    >
                      <SelectTrigger className="h-8 text-sm">
                        <SelectValue placeholder={field.placeholder || `选择${field.label}`} />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="__all__">全部</SelectItem>
                        {field.options.map((opt) => (
                          <SelectItem key={opt.value} value={opt.value}>
                            {opt.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  )}
                  {field.type === 'date' && (
                    <Input
                      type="date"
                      value={filters[field.key] || ''}
                      onChange={(e) => handleFieldChange(field.key, e.target.value)}
                      className="h-8 text-sm"
                    />
                  )}
                </div>
              ))}
            </div>
            <div className="flex justify-end gap-2 pt-2 border-t">
              <Button variant="outline" size="sm" onClick={() => setOpen(false)}>
                取消
              </Button>
              <Button size="sm" onClick={handleSearch}>
                <Search className="h-3 w-3 mr-1" />
                搜索
              </Button>
            </div>
          </div>
        </PopoverContent>
      </Popover>

      {/* 活跃筛选标签 */}
      {activeFilters.length > 0 && (
        <div className="flex items-center gap-1 flex-wrap">
          {activeFilters.map((filter) => (
            <Badge key={filter.key} variant="secondary" className="gap-1 text-xs pr-1">
              {filter.label}: {filter.displayValue}
              <button
                onClick={() => onRemoveFilter?.(filter.key)}
                className="ml-0.5 hover:bg-muted rounded-full p-0.5"
              >
                <X className="h-2.5 w-2.5" />
              </button>
            </Badge>
          ))}
          <Button
            variant="ghost"
            size="sm"
            className="h-6 text-xs text-muted-foreground"
            onClick={handleReset}
          >
            清除全部
          </Button>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { MoreHorizontal, X } from 'lucide-react';

export interface BatchAction {
  key: string;
  label: string;
  icon?: React.ReactNode;
  variant?: 'default' | 'destructive';
  onClick: (ids: (string | number)[]) => void | Promise<void>;
  confirm?: string;
  requireAllSameStatus?: string; // 要求所有选中项状态相同
}

interface BatchToolbarProps {
  selectedIds: (string | number)[];
  totalItems: number;
  onSelectAll: () => void;
  onClearSelection: () => void;
  actions: BatchAction[];
  className?: string;
}

export function BatchToolbar({
  selectedIds,
  totalItems,
  onSelectAll,
  onClearSelection,
  actions,
  className = '',
}: BatchToolbarProps) {
  const [loading, setLoading] = useState(false);

  const handleAction = useCallback(
    async (action: BatchAction) => {
      if (action.confirm && !confirm(action.confirm)) return;
      setLoading(true);
      try {
        await action.onClick(selectedIds);
      } finally {
        setLoading(false);
      }
    },
    [selectedIds]
  );

  if (selectedIds.length === 0) return null;

  return (
    <div className={`flex items-center gap-2 p-2 bg-muted/50 rounded-lg border ${className}`}>
      <Checkbox
        checked={selectedIds.length === totalItems && totalItems > 0}
        onCheckedChange={(checked) => {
          if (checked) onSelectAll();
          else onClearSelection();
        }}
      />
      <span className="text-sm text-muted-foreground">
        已选
        <strong className="text-foreground">{selectedIds.length}</strong> / {totalItems}项
      </span>
      <Button variant="ghost" size="sm" className="h-6 text-xs" onClick={onClearSelection}>
        <X className="h-3 w-3 mr-0.5" />
        取消选择
      </Button>
      <div className="flex-1" />
      <div className="flex items-center gap-1">
        {actions.slice(0, 3).map((action) => (
          <Button
            key={action.key}
            size="sm"
            variant={action.variant === 'destructive' ? 'destructive' : 'outline'}
            className="h-7 text-xs gap-1"
            onClick={() => handleAction(action)}
            disabled={loading}
          >
            {action.icon}
            {action.label}
          </Button>
        ))}
        {actions.length > 3 && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button size="sm" variant="outline" className="h-7" disabled={loading}>
                <MoreHorizontal className="h-3 w-3" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              {actions.slice(3).map((action) => (
                <DropdownMenuItem
                  key={action.key}
                  onClick={() => handleAction(action)}
                  className={action.variant === 'destructive' ? 'text-destructive' : ''}
                >
                  {action.icon}
                  {action.label}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        )}
      </div>
    </div>
  );
}

