'use client';

import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useRef,
  ReactNode,
} from 'react';

interface Role {
  id?: number;
  role_code: string;
  role_name?: string;
}

interface User {
  id: number;
  username: string;
  realName: string;
  avatar?: string;
  email?: string;
  phone?: string;
  departmentId?: number;
  departmentName?: string;
  roles: Role[];
  permissions: string[];
}

interface Menu {
  id: number;
  name: string;
  code: string;
  type: number;
  icon?: string;
  path?: string;
  children?: Menu[];
  sort_order?: number;
}

interface AuthState {
  user: User | null;
  menus: Menu[];
  permissions: string[];
  isAuthenticated: boolean;
  isLoading: boolean;
}

/**
 * 服务端 SSR 预取的初始认证数据。
 * 由 layout.tsx 在服务端调用 MenuService 获取后，作为 prop 注入 AuthProvider。
 * 存在时跳过客户端首次 fetch（仍可后台静默刷新），从根源上消除菜单 SSR 不同步 / 闪烁。
 */
export interface InitialAuthData {
  menus: Menu[];
  permissions: string[];
}

interface AuthContextType extends AuthState {
  isHydrated: boolean;
  login: (
    username: string,
    password: string,
    rememberMe?: boolean
  ) => Promise<{ success: boolean; message?: string }>;
  logout: () => void;
  register: (data: Record<string, unknown>) => Promise<unknown>;
  hasPermission: (permission: string) => boolean;
  hasAnyPermission: (perms: string[]) => boolean;
  hasRole: (roleCode: string) => boolean;
}

const AuthContext = createContext<AuthContextType | null>(null);

/** localStorage key for menu cache */
const MENU_CACHE_KEY = 'cached_menus';
const MENU_CACHE_TS_KEY = 'cached_menus_ts';
/** 菜单缓存有效期：30 分钟 */
const MENU_CACHE_TTL = 30 * 60 * 1000;

/** 从 localStorage 读取缓存的菜单数据 */
function _loadCachedMenus(): { menus: Menu[]; permissions: string[] } | null {
  try {
    const ts = localStorage.getItem(MENU_CACHE_TS_KEY);
    if (!ts) return null;
    // 缓存过期检查
    if (Date.now() - parseInt(ts, 10) > MENU_CACHE_TTL) {
      localStorage.removeItem(MENU_CACHE_KEY);
      localStorage.removeItem(MENU_CACHE_TS_KEY);
      return null;
    }
    const raw = localStorage.getItem(MENU_CACHE_KEY);
    if (!raw) return null;
    const data = JSON.parse(raw);
    if (Array.isArray(data?.menus)) {
      return {
        menus: data.menus,
        permissions: Array.isArray(data.permissions) ? data.permissions : [],
      };
    }
  } catch {
    // 缓存数据损坏，清除
    localStorage.removeItem(MENU_CACHE_KEY);
    localStorage.removeItem(MENU_CACHE_TS_KEY);
  }
  return null;
}

/** 将菜单数据缓存到 localStorage */
function saveCachedMenus(menus: Menu[], permissions: string[]) {
  try {
    localStorage.setItem(MENU_CACHE_KEY, JSON.stringify({ menus, permissions }));
    localStorage.setItem(MENU_CACHE_TS_KEY, String(Date.now()));
  } catch {
    // localStorage 满了或不可用，静默忽略
  }
}

export function AuthProvider({
  children,
  initialAuth,
}: {
  children: ReactNode;
  initialAuth?: InitialAuthData | null;
}) {
  // SSR 注入了 initialAuth 时，初值直接使用服务端菜单：
  //   - menus / permissions 来自服务端预取（SSR 与首帧客户端完全一致，无水合差异）
  //   - isLoading = false（无需等首次 fetch）
  //   - user / isAuthenticated 仍由 useEffect 从 localStorage 恢复（避免 SSR 读取 localStorage）
  // 无 initialAuth 时（未登录 / SSR 预取失败）：保持原有行为，isLoading=true 显示骨架屏。
  const [state, setState] = useState<AuthState>({
    user: null,
    menus: initialAuth?.menus ?? [],
    permissions: initialAuth?.permissions ?? [],
    isAuthenticated: false,
    isLoading: !(initialAuth && initialAuth.menus.length > 0),
  });

  const [isHydrated, setIsHydrated] = useState(false);

  useEffect(() => {
    setIsHydrated(true);
  }, []);

  const authChecked = useRef(false);
  const menusLoadedRef = useRef(false);
  const abortControllerRef = useRef<AbortController | null>(null);
  const menusCountRef = useRef(0);
  /** 后台刷新标记：避免重复触发 */
  const _backgroundRefreshDone = useRef(false);
  /** 缓存 initialAuth 引用，供 useEffect 中判断是否跳过首次 fetch */
  const initialAuthRef = useRef<InitialAuthData | null | undefined>(initialAuth);

  const fetchMenus = useCallback(
    async (token: string, force: boolean = false, clearOnAuthError: boolean = true) => {
      if (!force && menusLoadedRef.current && menusCountRef.current > 0) {
        return;
      }

      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
      abortControllerRef.current = new AbortController();

      try {
        const response = await fetch('/api/auth/menus', {
          headers: { Authorization: `Bearer ${token}` },
          signal: abortControllerRef.current.signal,
        });

        if (!response.ok) {
          if (response.status === 401) {
            if (clearOnAuthError) {
              localStorage.removeItem('token');
              localStorage.removeItem('user');
              localStorage.removeItem('refreshToken');
              localStorage.removeItem('userId');
              localStorage.removeItem(MENU_CACHE_KEY);
              localStorage.removeItem(MENU_CACHE_TS_KEY);
              sessionStorage.removeItem('token');
              sessionStorage.removeItem('user');
              sessionStorage.removeItem('refreshToken');
              sessionStorage.removeItem('userId');
              menusLoadedRef.current = false;
              menusCountRef.current = 0;
              setState({
                user: null,
                menus: [],
                permissions: [],
                isAuthenticated: false,
                isLoading: false,
              });
            } else {
              setState((prev) => ({ ...prev, isLoading: false }));
            }
          } else {
            setState((prev) => ({ ...prev, isLoading: false }));
          }
          return;
        }

        const contentType = response.headers.get('content-type') || '';
        if (!contentType.includes('application/json')) {
          setState((prev) => ({ ...prev, isLoading: false }));
          return;
        }

        const result = await response.json();
        if (result.success) {
          menusLoadedRef.current = true;
          const menus = Array.isArray(result.data?.menus) ? result.data.menus : [];
          const permissions = Array.isArray(result.data?.permissions)
            ? result.data.permissions
            : [];
          menusCountRef.current = menus.length;

          // 持久化菜单缓存到 localStorage
          saveCachedMenus(menus, permissions);

          setState((prev) => ({
            ...prev,
            menus: menus,
            permissions: permissions,
            isLoading: false,
          }));
        }
      } catch (error: unknown) {
        if (error instanceof Error && error.name === 'AbortError') {
          return;
        }
        setState((prev) => ({ ...prev, isLoading: false }));
      }
    },
    []
  );

  useEffect(() => {
    if (authChecked.current) return;
    authChecked.current = true;

    const initAuth = async () => {
      const token = localStorage.getItem('token') || sessionStorage.getItem('token');
      const userStr = localStorage.getItem('user') || sessionStorage.getItem('user');

      if (token && userStr) {
        try {
          const user = JSON.parse(userStr);

          // SSR 已注入 initialAuth：直接采用服务端菜单，跳过首次 fetch。
          // 仅恢复 user / isAuthenticated（这些字段 SSR 阶段无法从 localStorage 读取），
          // 仍触发后台静默刷新，保证菜单最终与服务端一致；同时持久化到 localStorage 作降级缓存。
          const ssrInitial = initialAuthRef.current;
          if (ssrInitial && ssrInitial.menus.length > 0) {
            setState({
              user,
              menus: ssrInitial.menus,
              permissions: ssrInitial.permissions,
              isAuthenticated: true,
              isLoading: false,
            });
            menusLoadedRef.current = true;
            menusCountRef.current = ssrInitial.menus.length;
            saveCachedMenus(ssrInitial.menus, ssrInitial.permissions);
            // 后台静默刷新，不清除认证状态
            fetchMenus(token, true, false).catch(() => {});
            return;
          }

          // 无 SSR 数据时，保持 isLoading=true 直到服务端 API 返回
          // 确保服务端和客户端初始渲染一致，避免 hydration mismatch
          setState({
            user,
            menus: [],
            permissions: [],
            isAuthenticated: true,
            isLoading: true,
          });

          // 等待 API 返回菜单数据
          await fetchMenus(token);
        } catch {
          setState((prev) => ({ ...prev, isLoading: false }));
        }
      } else {
        setState((prev) => ({ ...prev, isLoading: false }));
      }
    };

    initAuth();

    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
      // React StrictMode 双调用：cleanup 重置标记，使第二次 invoke 能重新初始化。
      // 生产环境 cleanup 仅在卸载时执行，effect 不会再运行，无副作用。
      authChecked.current = false;
    };
  }, [fetchMenus]);

  const login = useCallback(
    async (username: string, password: string, rememberMe: boolean = true) => {
      try {
        const response = await fetch('/api/auth/login', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ username, password }),
        });

        const result = await response.json();

        if (result.success) {
          const storage = rememberMe ? localStorage : sessionStorage;
          storage.setItem('token', result.data.token);
          storage.setItem('user', JSON.stringify(result.data.user));
          // 存 refreshToken + userId 供 authFetch 无感刷新使用
          storage.setItem('refreshToken', result.data.refreshToken);
          storage.setItem('userId', String(result.data.user.id));

          menusLoadedRef.current = false;
          menusCountRef.current = 0;
          setState({
            user: result.data.user,
            menus: [],
            permissions: result.data.user.permissions || [],
            isAuthenticated: true,
            isLoading: true,
          });

          fetchMenus(result.data.token, true, false).catch((_e) => {});
          return { success: true };
        } else {
          return { success: false, message: result.message };
        }
      } catch {
        return { success: false, message: '登录失败' };
      }
    },
    [fetchMenus]
  );

  const logout = useCallback(async () => {
    // 调用登出 API：清除 httpOnly cookie（access_token + refresh_token）+ 将 token 加入黑名单
    // 必须在清除 localStorage 之前调用，因为 authFetch 需要从 localStorage 读取 token。
    // 使用 authFetch 以携带 Authorization header + CSRF token；API 失败也继续清除本地状态
    // （cookie 会在 24h 后自然过期，不影响安全性）。
    try {
      const { authFetch } = await import('@/lib/auth-fetch');
      await authFetch('/api/auth/logout', { method: 'POST' });
    } catch {
      // ignore：网络错误等，继续清除本地状态
    }

    localStorage.removeItem('token');
    localStorage.removeItem('user');
    localStorage.removeItem('refreshToken');
    localStorage.removeItem('userId');
    localStorage.removeItem(MENU_CACHE_KEY);
    localStorage.removeItem(MENU_CACHE_TS_KEY);
    sessionStorage.removeItem('token');
    sessionStorage.removeItem('user');
    sessionStorage.removeItem('refreshToken');
    sessionStorage.removeItem('userId');
    menusLoadedRef.current = false;
    menusCountRef.current = 0;
    authChecked.current = false;
    setState({
      user: null,
      menus: [],
      permissions: [],
      isAuthenticated: false,
      isLoading: false,
    });
    if (typeof window !== 'undefined') {
      // 使用整页跳转而非 router.push：确保所有客户端状态被完全重置，
      // 且 SSR layout.tsx 重新执行（此时 access_token cookie 已被清除，prefetchMenus 返回 null）
      window.location.href = '/login';
    }
  }, []);

  const register = useCallback(async (data: Record<string, unknown>) => {
    try {
      const response = await fetch('/api/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      });
      return await response.json();
    } catch {
      return { success: false, message: '注册失败' };
    }
  }, []);

  const hasPermission = useCallback(
    (permission: string): boolean => {
      const { permissions, user } = state;
      if (user?.roles?.some((r) => r.role_code === 'super_admin')) {
        return true;
      }
      return permissions.includes(permission) || permissions.includes('*');
    },
    [state.permissions, state.user]
  );

  const hasAnyPermission = useCallback(
    (perms: string[]): boolean => {
      return perms.some((p) => hasPermission(p));
    },
    [hasPermission]
  );

  const hasRole = useCallback(
    (roleCode: string): boolean => {
      return state.user?.roles?.some((r) => r.role_code === roleCode) || false;
    },
    [state.user]
  );

  return (
    <AuthContext.Provider
      value={{
        ...state,
        isHydrated,
        login,
        logout,
        register,
        hasPermission,
        hasAnyPermission,
        hasRole,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

/**
 * 油墨配方版本聚合根
 *
 * 封装核心业务规则：
 * - 状态流转：草稿→已生效→已作废
 * - 版本号生成：复用时次版本号+1，重大调整主版本号+1
 * - 一键复用：复制源版本全部明细与工艺参数
 * - 成本快照：生效瞬间固化成本
 * - 明细校验：比例合法性、物料编码非空
 *
 * 依据: docs/油墨配方版本管理完整落地方案.md 第一、三节
 */
import { FormulaStatus, canTransition, isEditable } from '../value-objects/FormulaStatus';
import { FormulaItemVO, FormulaItemProps } from '../value-objects/FormulaItemVO';
import { DomainError, DomainEvent, InvalidTransitionError } from '@/domain/shared/DomainTypes';
import {
  FormulaVersionActivatedEvent,
  FormulaVersionCancelledEvent,
} from '../events/FormulaVersionEvents';

export interface InkFormulaVersionProps {
  id?: number;
  colorId: number;
  versionNo: string;
  versionName?: string | null;
  status: FormulaStatus;
  changeReason?: string | null;
  sourceVersionId?: number | null;
  processNote?: string | null;
  totalWeight?: number | null;
  unit?: string;
  shelfLifeHours?: number;

  // 成本快照
  theoreticalCost?: number | null;
  costSnapshotTime?: Date | null;
  costCalcStatus?: number;
  costWarning?: string | null;

  // 审计字段
  activateBy?: number | null;
  activateTime?: Date | null;
  cancelBy?: number | null;
  cancelReason?: string | null;
  cancelTime?: Date | null;
  createBy?: number | null;
  createTime?: Date | null;
  updateBy?: number | null;
  updateTime?: Date | null;

  items?: FormulaItemVO[];
}

export interface CostSnapshotResult {
  totalCost: number;
  itemCosts: { itemId?: number; materialCode: string; unitCost: number; itemCost: number }[];
  status: number; // 0-未计算 1-完成 2-部分缺失
  warning: string | null;
}

export class InkFormulaVersion {
  readonly id?: number;
  private _colorId: number;
  private _versionNo: string;
  private _versionName: string | null;
  private _status: FormulaStatus;
  private _changeReason: string | null;
  private _sourceVersionId: number | null;
  private _processNote: string | null;
  private _totalWeight: number | null;
  private _unit: string;
  private _shelfLifeHours: number;

  private _theoreticalCost: number | null;
  private _costSnapshotTime: Date | null;
  private _costCalcStatus: number;
  private _costWarning: string | null;

  private _activateBy: number | null;
  private _activateTime: Date | null;
  private _cancelBy: number | null;
  private _cancelReason: string | null;
  private _cancelTime: Date | null;
  private _createBy: number | null;
  private _createTime: Date | null;
  private _updateBy: number | null;
  private _updateTime: Date | null;

  private _items: FormulaItemVO[];
  private _domainEvents: DomainEvent[] = [];

  constructor(props: InkFormulaVersionProps) {
    this.validateCreation(props);
    this.id = props.id;
    this._colorId = props.colorId;
    this._versionNo = props.versionNo;
    this._versionName = props.versionName ?? null;
    this._status = props.status;
    this._changeReason = props.changeReason ?? null;
    this._sourceVersionId = props.sourceVersionId ?? null;
    this._processNote = props.processNote ?? null;
    this._totalWeight = props.totalWeight ?? null;
    this._unit = props.unit ?? 'kg';
    this._shelfLifeHours = props.shelfLifeHours ?? 168;
    this._theoreticalCost = props.theoreticalCost ?? null;
    this._costSnapshotTime = props.costSnapshotTime ?? null;
    this._costCalcStatus = props.costCalcStatus ?? 0;
    this._costWarning = props.costWarning ?? null;
    this._activateBy = props.activateBy ?? null;
    this._activateTime = props.activateTime ?? null;
    this._cancelBy = props.cancelBy ?? null;
    this._cancelReason = props.cancelReason ?? null;
    this._cancelTime = props.cancelTime ?? null;
    this._createBy = props.createBy ?? null;
    this._createTime = props.createTime ?? null;
    this._updateBy = props.updateBy ?? null;
    this._updateTime = props.updateTime ?? null;
    this._items = props.items ?? [];
  }

  private validateCreation(props: InkFormulaVersionProps): void {
    if (!props.colorId || props.colorId <= 0) {
      throw new DomainError('色号ID不能为空');
    }
    if (!props.versionNo || props.versionNo.trim() === '') {
      throw new DomainError('版本号不能为空');
    }
    if (!props.versionNo.match(/^V\d+\.\d+$/)) {
      throw new DomainError(`版本号格式不合法: ${props.versionNo}，应为 V主.次 格式`);
    }
  }

  // ===== Getters =====

  get colorId(): number {
    return this._colorId;
  }
  get versionNo(): string {
    return this._versionNo;
  }
  get versionName(): string | null {
    return this._versionName;
  }
  get status(): FormulaStatus {
    return this._status;
  }
  get changeReason(): string | null {
    return this._changeReason;
  }
  get sourceVersionId(): number | null {
    return this._sourceVersionId;
  }
  get processNote(): string | null {
    return this._processNote;
  }
  get totalWeight(): number | null {
    return this._totalWeight;
  }
  get unit(): string {
    return this._unit;
  }
  get shelfLifeHours(): number {
    return this._shelfLifeHours;
  }
  get theoreticalCost(): number | null {
    return this._theoreticalCost;
  }
  get costSnapshotTime(): Date | null {
    return this._costSnapshotTime;
  }
  get costCalcStatus(): number {
    return this._costCalcStatus;
  }
  get costWarning(): string | null {
    return this._costWarning;
  }
  get activateBy(): number | null {
    return this._activateBy;
  }
  get activateTime(): Date | null {
    return this._activateTime;
  }
  get cancelBy(): number | null {
    return this._cancelBy;
  }
  get cancelReason(): string | null {
    return this._cancelReason;
  }
  get cancelTime(): Date | null {
    return this._cancelTime;
  }
  get createBy(): number | null {
    return this._createBy;
  }
  get createTime(): Date | null {
    return this._createTime;
  }
  get updateBy(): number | null {
    return this._updateBy;
  }
  get updateTime(): Date | null {
    return this._updateTime;
  }
  get items(): FormulaItemVO[] {
    return [...this._items];
  }

  // ===== 领域事件 =====

  getDomainEvents(): DomainEvent[] {
    return [...this._domainEvents];
  }

  clearDomainEvents(): void {
    this._domainEvents = [];
  }

  // ===== 状态判断 =====

  get isDraft(): boolean {
    return this._status === FormulaStatus.DRAFT;
  }
  get isActive(): boolean {
    return this._status === FormulaStatus.ACTIVE;
  }
  get isCancelled(): boolean {
    return this._status === FormulaStatus.CANCELLED;
  }
  get canEdit(): boolean {
    return isEditable(this._status);
  }
  get canDelete(): boolean {
    return this._status !== FormulaStatus.ACTIVE;
  }

  // ===== 状态流转 =====

  /** 版本生效：草稿 → 已生效 */
  activate(operatorId: number): void {
    if (!canTransition(this._status, FormulaStatus.ACTIVE)) {
      throw new InvalidTransitionError(getStatusLabel(this._status), '已生效');
    }
    this._status = FormulaStatus.ACTIVE;
    this._activateBy = operatorId;
    this._activateTime = new Date();
    this._updateBy = operatorId;

    // T101: 触发配方生效事件
    if (this.id) {
      this._domainEvents.push(
        new FormulaVersionActivatedEvent({
          versionId: this.id,
          colorId: this._colorId,
          versionNo: this._versionNo,
          activatedBy: operatorId,
          theoreticalCost: this._theoreticalCost,
        })
      );
    }
  }

  /** 版本作废：已生效 → 已作废 */
  cancel(operatorId: number, reason: string): void {
    if (!canTransition(this._status, FormulaStatus.CANCELLED)) {
      throw new InvalidTransitionError(getStatusLabel(this._status), '已作废');
    }
    if (!reason || reason.trim() === '') {
      throw new DomainError('作废原因不能为空');
    }
    this._status = FormulaStatus.CANCELLED;
    this._cancelBy = operatorId;
    this._cancelReason = reason;
    this._cancelTime = new Date();
    this._updateBy = operatorId;

    // T101: 触发配方作废事件
    if (this.id) {
      this._domainEvents.push(
        new FormulaVersionCancelledEvent({
          versionId: this.id,
          colorId: this._colorId,
          versionNo: this._versionNo,
          cancelledBy: operatorId,
          reason,
        })
      );
    }
  }

  // ===== 明细操作 =====

  /** 更新明细（仅草稿可操作） */
  updateItems(newItems: FormulaItemProps[]): void {
    if (!this.canEdit) {
      throw new DomainError('只有草稿版本可以修改明细');
    }
    this._items = newItems.map((item, index) => {
      const props = { ...item };
      if (props.sort === undefined) props.sort = index + 1;
      return new FormulaItemVO(props);
    });
    // 明细变更后重置成本状态
    this._costCalcStatus = 0;
    this._costWarning = null;
  }

  /** 更新基础信息（仅草稿可操作） */
  updateBaseInfo(data: {
    versionName?: string | null;
    changeReason?: string | null;
    processNote?: string | null;
    totalWeight?: number | null;
    unit?: string;
    shelfLifeHours?: number;
  }): void {
    if (!this.canEdit) {
      throw new DomainError('只有草稿版本可以编辑');
    }
    if (data.versionName !== undefined) this._versionName = data.versionName;
    if (data.changeReason !== undefined) this._changeReason = data.changeReason;
    if (data.processNote !== undefined) this._processNote = data.processNote;
    if (data.totalWeight !== undefined) this._totalWeight = data.totalWeight;
    if (data.unit !== undefined) this._unit = data.unit;
    if (data.shelfLifeHours !== undefined) this._shelfLifeHours = data.shelfLifeHours;
  }

  // ===== 成本快照 =====

  /** 固化成本快照（生效时调用） */
  snapshotCost(costResult: CostSnapshotResult): void {
    this._theoreticalCost = costResult.totalCost;
    this._costSnapshotTime = new Date();
    this._costCalcStatus = costResult.status;
    this._costWarning = costResult.warning;

    // 更新明细的快照成本
    this._items = this._items.map((item) => {
      const costInfo = costResult.itemCosts.find((c) => c.materialCode === item.materialCode);
      if (costInfo) {
        return new FormulaItemVO({
          ...item.toProps(),
          snapshotUnitCost: costInfo.unitCost,
        });
      }
      return item;
    });
  }

  // ===== 版本号生成 =====

  /**
   * 生成下一个版本号
   * @param current 当前版本号 (如 V1.2)
   * @param majorBump 是否主版本号升级
   * @returns 新版本号 (如 V1.3 或 V2.0)
   */
  static generateNextVersionNo(current: string, majorBump = false): string {
    const match = current.match(/^V(\d+)\.(\d+)$/);
    if (!match) {
      return 'V1.0';
    }
    const major = parseInt(match[1], 10);
    const minor = parseInt(match[2], 10);
    if (majorBump) {
      return `V${major + 1}.0`;
    }
    return `V${major}.${minor + 1}`;
  }

  /**
   * 根据已有版本列表生成新版本号
   * 如果有色号下已有版本，取最新版本号 +1
   */
  static generateVersionNo(existingVersionNos: string[]): string {
    if (existingVersionNos.length === 0) {
      return 'V1.0';
    }
    // 取最后一个版本号
    const last = existingVersionNos[existingVersionNos.length - 1];
    return this.generateNextVersionNo(last, false);
  }

  // ===== 工厂方法 =====

  /** 创建草稿版本 */
  static createDraft(
    colorId: number,
    baseInfo: {
      versionNo: string;
      versionName?: string | null;
      changeReason?: string | null;
      processNote?: string | null;
      totalWeight?: number | null;
      unit?: string;
      shelfLifeHours?: number;
    },
    items: FormulaItemProps[],
    operatorId: number
  ): InkFormulaVersion {
    return new InkFormulaVersion({
      colorId,
      versionNo: baseInfo.versionNo,
      versionName: baseInfo.versionName ?? null,
      status: FormulaStatus.DRAFT,
      changeReason: baseInfo.changeReason ?? null,
      processNote: baseInfo.processNote ?? null,
      totalWeight: baseInfo.totalWeight ?? null,
      unit: baseInfo.unit ?? 'kg',
      shelfLifeHours: baseInfo.shelfLifeHours ?? 168,
      costCalcStatus: 0,
      createBy: operatorId,
      updateBy: operatorId,
      items: items.map((item, index) => {
        const props = { ...item };
        if (props.sort === undefined) props.sort = index + 1;
        return new FormulaItemVO(props);
      }),
    });
  }

  /** 一键复用：从源版本创建草稿 */
  static duplicateFrom(
    source: InkFormulaVersion,
    options: {
      versionName?: string | null;
      changeReason?: string | null;
      majorVersion?: boolean;
    },
    operatorId: number
  ): InkFormulaVersion {
    const newVersionNo = this.generateNextVersionNo(
      source.versionNo,
      options.majorVersion ?? false
    );

    return new InkFormulaVersion({
      colorId: source.colorId,
      versionNo: newVersionNo,
      versionName: options.versionName ?? `复制自 ${source.versionNo}`,
      status: FormulaStatus.DRAFT,
      changeReason: options.changeReason ?? `从 ${source.versionNo} 一键复用`,
      sourceVersionId: source.id ?? null,
      processNote: source.processNote,
      totalWeight: source.totalWeight,
      unit: source.unit,
      shelfLifeHours: source.shelfLifeHours,
      costCalcStatus: 0,
      createBy: operatorId,
      updateBy: operatorId,
      items: source.items.map((item) => {
        const props = item.toProps();
        // 复用时清除 id 和快照成本
        return new FormulaItemVO({
          ...props,
          id: undefined,
          versionId: undefined,
          snapshotUnitCost: null,
        });
      }),
    });
  }

  /** 从数据库行重建聚合根 */
  static fromRow(row: Record<string, unknown>, items?: FormulaItemVO[]): InkFormulaVersion {
    return new InkFormulaVersion({
      id: row.id as number | undefined,
      colorId: row.color_id as number,
      versionNo: row.version_no as string,
      versionName: row.version_name as string | null | undefined,
      status: row.status as FormulaStatus,
      changeReason: row.change_reason as string | null | undefined,
      sourceVersionId: row.source_version_id as number | null | undefined,
      processNote: row.process_note as string | null | undefined,
      totalWeight: row.total_weight != null ? Number(row.total_weight) : null,
      unit: row.unit as string | undefined,
      shelfLifeHours: row.shelf_life_hours as number | undefined,
      theoreticalCost: row.theoretical_cost != null ? Number(row.theoretical_cost) : null,
      costSnapshotTime: row.cost_snapshot_time
        ? new Date(row.cost_snapshot_time as string | number)
        : null,
      costCalcStatus: (row.cost_calc_status as number) ?? 0,
      costWarning: row.cost_warning as string | null | undefined,
      activateBy: row.activate_by as number | null | undefined,
      activateTime: row.activate_time ? new Date(row.activate_time as string | number) : null,
      cancelBy: row.cancel_by as number | null | undefined,
      cancelReason: row.cancel_reason as string | null | undefined,
      cancelTime: row.cancel_time ? new Date(row.cancel_time as string | number) : null,
      createBy: row.create_by as number | null | undefined,
      createTime: row.create_time ? new Date(row.create_time as string | number) : null,
      updateBy: row.update_by as number | null | undefined,
      updateTime: row.update_time ? new Date(row.update_time as string | number) : null,
      items,
    });
  }

  /** 转为属性对象 */
  toProps(): InkFormulaVersionProps {
    return {
      id: this.id,
      colorId: this._colorId,
      versionNo: this._versionNo,
      versionName: this._versionName,
      status: this._status,
      changeReason: this._changeReason,
      sourceVersionId: this._sourceVersionId,
      processNote: this._processNote,
      totalWeight: this._totalWeight,
      unit: this._unit,
      shelfLifeHours: this._shelfLifeHours,
      theoreticalCost: this._theoreticalCost,
      costSnapshotTime: this._costSnapshotTime,
      costCalcStatus: this._costCalcStatus,
      costWarning: this._costWarning,
      activateBy: this._activateBy,
      activateTime: this._activateTime,
      cancelBy: this._cancelBy,
      cancelReason: this._cancelReason,
      cancelTime: this._cancelTime,
      createBy: this._createBy,
      createTime: this._createTime,
      updateBy: this._updateBy,
      updateTime: this._updateTime,
      items: [...this._items],
    };
  }
}

