    return this.value === 4;
  }

  isTerminal(): boolean {
    return this.value === 9;
  }

  isWrittenOff(): boolean {
    return this.value === 4;
  }

  get label(): string {
    return STATUS_LABELS[this.value] || String(this.value);
  }

  equals(other: PurchaseReconciliationStatus): boolean {
    return this.value === other.value;
  }
}

