      props.id,
      props.sampleOrderId,
      props.productName || '',
      props.materialNo || '',
      props.quantity || 0,
      props.unit || 'pcs',
      props.warehouseId,
      props.status || 'available',
      props.sentTo || '',
      props.sentDate || '',
      props.remark || '',
      props.createTime,
      props.updateTime,
      props.deleted || 0
    );
  }

