'use client';

import { useState, useEffect, useCallback } from 'react';

export function useNetworkStatus() {
  const [isOnline, setIsOnline] = useState(() => {
    if (typeof navigator !== 'undefined') {
      return navigator.onLine;
    }
    return true;
  });

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  return { isOnline, isOffline: !isOnline };
}

export function useOfflineScanSync(
  onSync?: (
    items: Array<{ qrCode: string; scanType: string; payload: Record<string, unknown> }>
  ) => Promise<void>
) {
  const { isOnline } = useNetworkStatus();
  const [syncing, setSyncing] = useState(false);
  const [pendingCount, setPendingCount] = useState(0);

  const refreshCount = useCallback(async () => {
    try {
      const { getAllPendingScans } = await import('@/lib/offline-scan-queue');
      const items = await getAllPendingScans();
      setPendingCount(items.filter((i) => i.status === 'pending' || i.status === 'failed').length);
    } catch {
      // ignore
    }
  }, []);

  useEffect(() => {
    refreshCount();
  }, [refreshCount]);

  const syncPending = useCallback(async () => {
    if (!isOnline || syncing) return;
    setSyncing(true);
    try {
      const { getAllPendingScans, markScanDone, markScanFailed, removeScan } =
        await import('@/lib/offline-scan-queue');
      const pending = await getAllPendingScans();
      const items = pending.filter((i) => i.status === 'pending' || i.status === 'failed');

      for (const item of items) {
        try {
          if (onSync) {
            await onSync([{ qrCode: item.qrCode, scanType: item.scanType, payload: item.payload }]);
          }
          if (item.id !== undefined) {
            await markScanDone(item.id);
          }
        } catch (err) {
          if (item.id !== undefined) {
            await markScanFailed(item.id, (err as Error).message);
          }
        }
      }
      await refreshCount();
    } finally {
      setSyncing(false);
    }
  }, [isOnline, syncing, onSync, refreshCount]);

  return { isOnline, syncing, pendingCount, syncPending, refreshCount };
}

import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { authFetch } from '@/lib/auth-fetch';

export function useCompanyName() {
  const tc = useTranslations('Common');
  const [companyName, setCompanyName] = useState(tc('companyName'));
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;

    const fetchWithRetry = async (url: string, retries = 2): Promise<Response | null> => {
      for (let i = 0; i <= retries; i++) {
        try {
          const res = await authFetch(url);
          if (res.status === 401) return null;
          if (res.ok && res.headers.get('content-type')?.includes('application/json')) {
            return res;
          }
          if (i < retries) {
            await new Promise((r) => setTimeout(r, 500 * (i + 1)));
          }
        } catch {
          if (i < retries) {
            await new Promise((r) => setTimeout(r, 500 * (i + 1)));
          }
        }
      }
      return null;
    };

    const fetchCompanyName = async () => {
      try {
        const configRes = await fetchWithRetry('/api/system/config?pageSize=200');
        if (configRes) {
          const configData = await configRes.json();
          if (!cancelled && configData.success && configData.data?.list) {
            const companyNameConfig =
              configData.data.list.find(
                (item: { config_key: string; config_value: string }) =>
                  item.config_key === 'company.name'
              )?.config_value ||
              configData.data.list.find(
                (item: { config_key: string; config_value: string }) =>
                  item.config_key === 'company_name'
              )?.config_value;
            const companyShortName = configData.data.list.find(
              (item: { config_key: string; config_value: string }) =>
                item.config_key === 'company_short_name'
            )?.config_value;
            if (companyNameConfig) {
              setCompanyName(companyNameConfig);
              return;
            } else if (companyShortName) {
              setCompanyName(companyShortName);
              return;
            }
          }
        }

        const orgRes = await fetchWithRetry('/api/organization?type=company');
        if (orgRes) {
          const orgData = await orgRes.json();
          if (!cancelled && orgData.success && orgData.data) {
            if (orgData.data.full_name) {
              setCompanyName(orgData.data.full_name);
              return;
            }
            if (orgData.data.short_name) {
              setCompanyName(orgData.data.short_name);
              return;
            }
          }
        }
      } catch {
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    fetchCompanyName();

    return () => {
      cancelled = true;
    };
  }, []);

  return { companyName, loading };
}

