'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { useToast } from '@/hooks/use-toast';
import { authFetch } from '@/lib/auth-fetch';
import { CardData, Customer, PrintSequence } from '@/domain/sample/standard-card/types';
import {
  createEmptyData,
  mapApiDataToCardData,
  mapCardDataToApiPayload,
} from '@/domain/sample/standard-card/utils';

interface UseStandardCardFormOptions {
  mode: 'card' | 'v2';
}

export function useStandardCardForm({ mode }: UseStandardCardFormOptions) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { toast } = useToast();

  const editId = searchParams.get('id');
  const isEditMode = !!editId;

  const [data, setData] = useState<CardData>(createEmptyData);
  const [loading, setLoading] = useState(isEditMode);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [savedCardId, setSavedCardId] = useState<number | null>(null);

  const [customers, setCustomers] = useState<Customer[]>([]);
  const [customerSearch, setCustomerSearch] = useState('');
  const [showCustomerDropdown, setShowCustomerDropdown] = useState(false);
  // 编辑模式下保存一份原始 API 数据，用于 diff 提交（只提交变更字段，
  // 避免全量提交把未回填/用户未改动的字段覆盖为空）
  const originalApiRef = useRef<Loose | null>(null);

  const fetchCustomers = useCallback(async () => {
    try {
      const response = await authFetch('/api/customers?page=1&pageSize=999');
      const result = await response.json();
      let list: Customer[] = [];
      if (result.success && Array.isArray(result.data)) {
        list = result.data.map((item: Record<string, unknown>) => ({
          id: item.id as number,
          customerCode: (item.customer_code as string) || '',
          customerName: (item.customer_name as string) || '',
          shortName: (item.short_name as string) || '',
        }));
      } else if (result.success && result.data?.list && Array.isArray(result.data.list)) {
        list = result.data.list.map((item: Record<string, unknown>) => ({
          id: item.id as number,
          customerCode: (item.customer_code as string) || '',
          customerName: (item.customer_name as string) || '',
          shortName: (item.short_name as string) || '',
        }));
      }
      setCustomers(list);
    } catch {
      // ignore
    }
  }, []);

  useEffect(() => {
    fetchCustomers();
  }, [fetchCustomers]);

  const loadData = useCallback(async (id: string) => {
    try {
      setLoading(true);
      const response = await authFetch(`/api/standard-cards?id=${id}`);
      const result = await response.json();
      const apiData = Array.isArray(result.data) ? result.data[0] : result.data;
      if (result.success && apiData) {
        // 保存原始 API 数据快照（diff 基准）；加载失败时保持 null，禁止保存
        originalApiRef.current = apiData as Loose;
        setData(mapApiDataToCardData(apiData));
      } else {
        setError(result.message || '加载失败');
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : '加载数据失败');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (editId) {
      loadData(editId);
    }
  }, [editId, loadData]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (!target.closest('.customer-dropdown-container')) {
        setShowCustomerDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const updateField = <K extends keyof CardData>(field: K, value: CardData[K]) => {
    setData((prev) => ({ ...prev, [field]: value }));
  };

  const updateSequence = (index: number, field: keyof PrintSequence, value: string) => {
    setData((prev) => ({
      ...prev,
      sequences: prev.sequences.map((seq, i) => (i === index ? { ...seq, [field]: value } : seq)),
    }));
  };

  const handleToggleMultiValue = (
    field: 'coreType' | 'printType' | 'processMethod',
    value: string
  ) => {
    setData((prev) => {
      const arr = prev[field] ? prev[field].split(',').filter(Boolean) : [];
      const idx = arr.indexOf(value);
      if (idx >= 0) {
        arr.splice(idx, 1);
      } else {
        arr.push(value);
      }
      return { ...prev, [field]: arr.join(',') };
    });
  };

  const handleSelectCustomer = (customer: Customer) => {
    updateField('customer', customer.customerName);
    updateField('customerCode', customer.customerCode);
    setCustomerSearch('');
    setShowCustomerDropdown(false);
  };

  const filteredCustomers = customers.filter(
    (c) =>
      c.customerName.toLowerCase().includes(customerSearch.toLowerCase()) ||
      c.customerCode.toLowerCase().includes(customerSearch.toLowerCase())
  );

  const filteredCustomersLimited = filteredCustomers.slice(0, 20);

  const validate = (): string | null => {
    if (!data.customer) return '请选择客户';
    if (!data.customerCode) return '请输入客户料号';
    if (!data.productName) return '请输入品名';
    return null;
  };

  const handleSave = async (): Promise<number | null> => {
    // 编辑模式下数据未加载完成或加载失败时禁止保存：
    // 此时表单为空，直接提交会把已有数据（如印序 sequences）整体清空覆盖。
    if (isEditMode && loading) {
      toast({ title: '数据仍在加载中，请稍候再保存', variant: 'destructive' });
      return null;
    }
    if (isEditMode && error) {
      toast({ title: '数据加载失败，无法保存（请刷新后重试）', variant: 'destructive' });
      return null;
    }

    const validationError = validate();
    if (validationError) {
      toast({ title: validationError, variant: 'destructive' });
      return null;
    }

    // 编辑模式下提交前做二次保护：若当前表单核心字段全空（说明数据未成功回填），拒绝保存
    if (isEditMode && !data.customer && !data.productName && !data.cardNo) {
      toast({ title: '表单数据为空，拒绝保存，防止覆盖已有数据', variant: 'destructive' });
      return null;
    }

    try {
      setSaving(true);

      let saveData = mapCardDataToApiPayload(data, isEditMode, editId || undefined);

      // 编辑模式下做 diff 提交：仅提交与原始数据不同的字段。
      // 未变更的字段不提交 → 后端不会更新它们 → 杜绝"未回填字段被空值覆盖"；
      // 用户显式清空的字段（值变为空字符串）会提交空值 → 后端应允许清空。
      if (isEditMode && originalApiRef.current) {
        const diff: Record<string, unknown> = {};
        for (const [key, newValue] of Object.entries(saveData)) {
          if (key === 'id') continue;
          const oldValue = (originalApiRef.current as Record<string, unknown>)[key];
          if (!looseEqual(newValue, oldValue)) {
            diff[key] = newValue;
          }
        }
        saveData = { id: parseInt(editId || '0'), ...diff };
      }

      const url = '/api/standard-cards';
      const method = isEditMode ? 'PUT' : 'POST';

      const response = await authFetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(saveData),
      });

      const result = await response.json();

      if (!result.success) {
        toast({ title: result.message || '保存失败', variant: 'destructive' });
        return null;
      }

      const newId = result.data?.id || parseInt(editId || '0');
      toast({ title: isEditMode ? '标准卡更新成功' : '标准卡保存成功' });
      setSavedCardId(newId);

      if (!isEditMode && newId) {
        router.push(`/sample/standard-card?id=${newId}&edit=true&mode=${mode}`);
      }

      return newId;
    } catch (e) {
      console.error('[StandardCard:Save] 异常:', e instanceof Error ? e.message : e, e);
      toast({ title: '保存失败，请检查网络连接', variant: 'destructive' });
      return null;
    } finally {
      setSaving(false);
    }
  };

  const handleSaveAndPreview = async () => {
    const savedId = await handleSave();
    const id = savedId || (editId ? parseInt(editId) : null);
    if (id) {
      router.push(`/sample/standard-card/print?id=${id}`);
    }
  };

  return {
    data,
    setData,
    loading,
    saving,
    error,
    savedCardId,
    customers,
    customerSearch,
    setCustomerSearch,
    showCustomerDropdown,
    setShowCustomerDropdown,
    filteredCustomers: filteredCustomersLimited,
    isEditMode,
    editId,
    updateField,
    updateSequence,
    handleToggleMultiValue,
    handleSelectCustomer,
    handleSave,
    handleSaveAndPreview,
  };
}

/**
 * 宽松相等比较（用于 diff 提交判断字段是否变化）：
 * - null / undefined / 空字符串视为等价（数据库 NULL 与 '' 的差异不视为内容变化）
 * - sequences 等 JSON 字符串按解析后的值比较，避免键顺序差异导致误判
 */
function looseEqual(a: unknown, b: unknown): boolean {
  const normalize = (v: unknown): unknown => {
    if (v === null || v === undefined) return null;
    if (typeof v === 'string') {
      if (v === '') return null;
      // 尝试解析 JSON（如 sequences），解析失败按原字符串处理
      if (v.startsWith('[') || v.startsWith('{')) {
        try {
          return JSON.parse(v);
        } catch {
          return v;
        }
      }
      return v;
    }
    if (Array.isArray(v)) {
      return v.map((item) => normalize(item));
    }
    if (typeof v === 'object') {
      const obj = v as Record<string, unknown>;
      const result: Record<string, unknown> = {};
      for (const [k, val] of Object.entries(obj)) {
        result[k] = normalize(val);
      }
      return result;
    }
    return v;
  };
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

import { getRequestConfig } from 'next-intl/server';
import type { IntlError } from 'next-intl';
import { locales, defaultLocale } from './locales';

const seenMissingKeys = new Set<string>();

export default getRequestConfig(async ({ requestLocale }) => {
  let locale = await requestLocale;

  if (!locale || !locales.includes(locale as (typeof locales)[number])) {
    locale = defaultLocale;
  }

  let messages;
  try {
    messages = (await import(`../../messages/${locale}.json`)).default;
  } catch {
    messages = (await import(`../../messages/${defaultLocale}.json`)).default;
  }

  return {
    locale,
    messages,
    onError(error: IntlError) {
      const msg = error.message;

      const missingMatch = msg.match(/Could not resolve ['"]([^'"]+)['"] in ['"]([^'"]+)['"]/);
      if (missingMatch) {
        const [, key, namespace] = missingMatch;
        const uniqueKey = `${locale}:${namespace}.${key}`;
        if (seenMissingKeys.has(uniqueKey)) return;
        seenMissingKeys.add(uniqueKey);
        console.warn(
          `[i18n] Missing translation key: "${namespace}.${key}" (locale: ${locale}). ` +
            `Run: node scripts/debug-perf/diagnose_i18n_keys.mjs to find all missing keys.`
        );
      } else if (msg.includes('INVALID_MESSAGE')) {
        console.warn(`[i18n] Message format error (locale: ${locale}): ${msg}`);
      }
    },
    getMessageFallback({ namespace, key }) {
      const fullKey = namespace ? `${namespace}.${key}` : key;
      return fullKey;
    },
  };
});

import { execute, query } from '@/lib/db';
import { DomainEvent } from '@/domain/shared/DomainTypes';
import type { PoolConnection } from 'mysql2/promise';

export class DomainEventOutbox {
  static async saveEvents(
    conn: PoolConnection,
    aggregateType: string,
    aggregateId: number,
    events: DomainEvent[]
  ): Promise<void> {
    for (const event of events) {
      await conn.execute(
        `INSERT INTO domain_event_outbox (event_type, aggregate_type, aggregate_id, payload, status, create_time)
         VALUES (?, ?, ?, ?, 'pending', NOW())`,
        [event.eventType, aggregateType, aggregateId, JSON.stringify(event)]
      );
    }
  }

  static async fetchPendingEvents(limit: number = 50): Promise<Record<string, any>[]> {
    // 1.4 指数退避：仅查询 next_execute_at 已到期或为 NULL 的待处理事件
    const rows = await query<Record<string, any>>(
      `SELECT * FROM domain_event_outbox
       WHERE status = 'pending'
         AND (next_execute_at IS NULL OR next_execute_at <= NOW())
       ORDER BY create_time ASC LIMIT ?`,
      [limit]
    );
    return rows;
  }

  static async markAsProcessed(id: number): Promise<void> {
    await execute(
      `UPDATE domain_event_outbox SET status = 'processed', processed_at = NOW() WHERE id = ?`,
      [id]
    );
  }

  /**
   * 标记事件失败（指数退避：1s/3s/9s）
   * - 状态保持 pending（待重试语义），由 next_execute_at 控制下次执行时间
   * - retry_count 递增，达到 MAX_RETRY_COUNT 后由 OutboxPoller 调用 markAsDeadLetter
   * - 兼容旧调用方签名，向后兼容
   *
   * 注：CASE 表达式中的 retry_count 引用原值（未递增前），通过子查询读取避免被同 SET 的赋值影响
   */
  static async markAsFailed(id: number, error: string): Promise<void> {
    const errorMessage = error.substring(0, 500);
    await execute(
      `UPDATE domain_event_outbox o
       JOIN (SELECT retry_count AS old_retry FROM domain_event_outbox WHERE id = ?) t
       SET o.status = 'pending',
           o.error_message = ?,
           o.retry_count = t.old_retry + 1,
           o.next_execute_at = CASE
             WHEN t.old_retry + 1 = 1 THEN DATE_ADD(NOW(), INTERVAL 1 SECOND)
             WHEN t.old_retry + 1 = 2 THEN DATE_ADD(NOW(), INTERVAL 3 SECOND)
             WHEN t.old_retry + 1 = 3 THEN DATE_ADD(NOW(), INTERVAL 9 SECOND)
             ELSE DATE_ADD(NOW(), INTERVAL 9 SECOND)
           END
       WHERE o.id = ?`,
      [id, errorMessage, id]
    );
  }

  static async markForRetry(id: number): Promise<void> {
    if (id === 0) {
      await execute(
        `UPDATE domain_event_outbox SET status = 'pending', error_message = NULL WHERE status = 'failed' AND retry_count < 3`
      );
      return;
    }
    await execute(
      `UPDATE domain_event_outbox SET status = 'pending', error_message = NULL WHERE id = ? AND retry_count < 3`,
      [id]
    );
  }

  /**
   * 标记事件为死信（重试次数超限时由 OutboxPoller 调用）
   * - 状态变为 dead_letter，不再被 fetchPendingEvents 消费
   * - retry_count 不递增（已达上限，保留实际重试次数便于排查）
   * - 完整错误栈写入 error_message（截断 2000 字符，覆盖大多数错误栈且远小于 TEXT 上限）
   */
  static async markAsDeadLetter(id: number, errorStack: string): Promise<void> {
    await execute(
      `UPDATE domain_event_outbox
       SET status = 'dead_letter', error_message = ?
       WHERE id = ?`,
      [errorStack.substring(0, 2000), id]
    );
  }
}

/* eslint-disable @typescript-eslint/no-unused-vars */
import type { PoolConnection } from 'mysql2/promise';
import type { DomainEvent } from '@/domain/shared/DomainTypes';
import type {
  IDomainEventOutboxRepository,
  EventOutboxRecord,
} from '@/infrastructure/event-bus/types/IDomainEventOutboxRepository';

/**
 * 内存模式领域事件 Outbox（no-op 实现）
 *
 * 用于 EVENT_BUS_TYPE=memory 模式：
 * - 事件不持久化到数据库（saveEvents 直接 return）
 * - fetchPendingEvents 永远返回空数组
 * - 所有状态更新方法均为 no-op
 *
 * 设计目标：让 ApplicationService 在 memory 模式下完全不依赖数据库表，
 * 切换 EVENT_BUS_TYPE=memory 即可禁用 Outbox 持久化能力，零运行时开销。
 *
 * no-op 接口实现的参数必然未使用，参数名保留以提高可读性，故文件级禁用 no-unused-vars。
 */
export class MemoryDomainEventOutbox implements IDomainEventOutboxRepository {
  async saveEvents(
    _conn: PoolConnection,
    _aggregateType: string,
    _aggregateId: number,
    _events: DomainEvent[]
  ): Promise<void> {
    // no-op: memory 模式不持久化事件
  }

  async fetchPendingEvents(_limit?: number): Promise<EventOutboxRecord[]> {
    return [];
  }

  async claimPendingEvents(_limit?: number): Promise<EventOutboxRecord[]> {
    return [];
  }

  async markAsProcessed(_id: number): Promise<void> {
    // no-op
  }

  async markAsFailed(_id: number, _error: string): Promise<void> {
    // no-op
  }

  async markAsDeadLetter(_id: number, _error: string): Promise<void> {
    // no-op
  }

  async markForRetry(_id: number): Promise<void> {
    // no-op
  }

  async reclaimStaleDispatching(_timeoutMinutes: number): Promise<number> {
    return 0;
  }
}

import { registerEventHandlers } from '@/application/EventRegistry';
import { getDomainEventOutbox } from './DomainEventOutboxFactory';
import { getRedisClientIfAvailable } from '@/infrastructure/cache/CacheManager';
import { StreamPublisher } from './StreamPublisher';
import { IdempotencyGuard } from './IdempotencyGuard';
import { secureLog } from '@/lib/logger';

const POLL_INTERVAL_MS = 5000;
const MAX_RETRY_COUNT = 3;
const BATCH_SIZE = 50;
const RECLAIM_INTERVAL_MS = 60000;
const CLEANUP_INTERVAL_MS = 24 * 60 * 60 * 1000;
const CLEANUP_OLDER_THAN_DAYS = 30;

/**
 * dispatching 状态超时阈值（分钟）
 *
 * OutboxPoller 在 claimPendingEvents 后崩溃会导致事件卡在 'dispatching'。
 * 超过此阈值的事件会被 reclaimStaleDispatching 重置为 'pending'，使其可被重新消费。
 * 可通过 IDEMPOTENCY_DISPATCHING_TIMEOUT_MINUTES 环境变量配置，默认 10 分钟。
 */
const DISPATCHING_TIMEOUT_MINUTES = (() => {
  const raw = Number.parseInt(process.env.IDEMPOTENCY_DISPATCHING_TIMEOUT_MINUTES || '', 10);
  return Number.isFinite(raw) && raw > 0 ? raw : 10;
})();

let cachedStreamPublisher: StreamPublisher | null | undefined;

function getStreamPublisher(): StreamPublisher | null {
  if (cachedStreamPublisher !== undefined) {
    return cachedStreamPublisher;
  }
  const redis = getRedisClientIfAvailable();
  cachedStreamPublisher = redis ? new StreamPublisher(redis) : null;
  if (cachedStreamPublisher) {
    secureLog('info', 'OutboxPoller: Stream mode enabled (Redis available)');
  }
  return cachedStreamPublisher;
}

export function __resetStreamPublisherForTest(): void {
  cachedStreamPublisher = undefined;
}

/**
 * 类型安全地从 unknown 错误中提取 message 和 stack
 * 替代 error: any 的不安全访问，避免 ESLint no-explicit-any 警告
 */
function extractErrorInfo(error: unknown): { message: string; stack: string } {
  if (error instanceof Error) {
    return {
      message: error.message,
      stack: error.stack || error.message,
    };
  }
  const message = String(error);
  return { message, stack: message };
}

let polling = false;
let pollTimer: ReturnType<typeof setInterval> | null = null;
let reclaimTimer: ReturnType<typeof setInterval> | null = null;
let cleanupTimer: ReturnType<typeof setInterval> | null = null;

export class OutboxPoller {
  static async poll(): Promise<{ processed: number; failed: number; retried: number }> {
    if (polling) {
      return { processed: 0, failed: 0, retried: 0 };
    }

    polling = true;
    let processed = 0;
    let failed = 0;
    let retried = 0;

    try {
      // 1.4 移除 markForRetry(0) 批量重置：失败事件按 next_execute_at 自然到期重试
      // 由 markAsFailed 设置 next_execute_at 实现指数退避（1s/3s/9s）
      const eventBus = registerEventHandlers();
      const outbox = getDomainEventOutbox();
      const streamPublisher = getStreamPublisher();

      const pendingEvents = await outbox.claimPendingEvents(BATCH_SIZE);

      secureLog('debug', 'OutboxPoller: claimed pending events', {
        count: pendingEvents.length,
        eventIds: pendingEvents.map((e) => e.id),
        mode: streamPublisher ? 'stream' : 'memory',
      });

      for (const row of pendingEvents) {
        if (streamPublisher) {
          // Stream 模式：XADD 投递到 Redis Stream，消费端由 StreamConsumer 处理
          // XADD 成功即视为"已安全投递"，markAsProcessed 关闭 outbox 侧
          // 消费端失败由 Stream pending list + XAUTOCLAIM + IdempotentHandler 保证
          try {
            const streamMessageId = await streamPublisher.publish({
              id: row.id,
              eventType: row.eventType,
              aggregateType: row.aggregateType,
              aggregateId: row.aggregateId,
              occurredAt: row.createdAt,
              payload: typeof row.payload === 'string' ? row.payload : JSON.stringify(row.payload),
            });
            secureLog('debug', 'OutboxPoller: event XADD to stream', {
              eventId: row.id,
              streamMessageId,
              eventType: row.eventType,
            });
          } catch (publishError: unknown) {
            // XADD 失败：事件未入 Stream，走重试/死信流程
            const { message: errorMessage, stack: errorStack } = extractErrorInfo(publishError);
            const retryCount = row.retryCount || 0;
            if (retryCount >= MAX_RETRY_COUNT) {
              await outbox.markAsDeadLetter(row.id, errorStack);
              failed++;
              secureLog('error', 'Outbox event marked as dead letter (XADD failed)', {
                eventId: row.id,
                eventType: row.eventType,
                retryCount,
                error: errorMessage,
              });
            } else {
              await outbox.markAsFailed(row.id, errorMessage);
              retried++;
              secureLog('warn', 'Outbox event XADD failed, will retry', {
                eventId: row.id,
                eventType: row.eventType,
                retryCount: retryCount + 1,
                nextExecuteAt: `+${retryCount + 1 === 1 ? 1 : retryCount + 1 === 2 ? 3 : 9}s`,
                error: errorMessage,
              });
            }
            continue;
          }

          // XADD 成功，关闭 outbox 侧
          // markAsProcessed 失败不触发重试：事件已在 Stream 中，
          // 消费端由 IdempotentHandler 保证幂等，outbox 残留记录由 reclaimStaleDispatching 清理
          try {
            await outbox.markAsProcessed(row.id);
            secureLog('debug', 'OutboxPoller: event marked as processed', { eventId: row.id });
            processed++;
          } catch (markError: unknown) {
            const { message: markErrorMsg } = extractErrorInfo(markError);
            secureLog('warn', 'OutboxPoller: markAsProcessed failed after XADD success (event already in stream)', {
              eventId: row.id,
              error: markErrorMsg,
              note: 'Event remains in stream, consumer will process it; outbox record will be reclaimed by reclaimStaleDispatching',
            });
            processed++; // XADD 成功，outbox 侧仍计为 processed
          }
        } else {
          // 内存模式：直接 publish 到 InMemoryEventBus（开发降级，无 Redis 时使用）
          const payload =
            typeof row.payload === 'string' ? JSON.parse(row.payload) : row.payload;

          try {
            await eventBus.publish({
              eventType: row.eventType,
              aggregateType: row.aggregateType ?? undefined,
              aggregateId: row.aggregateId ?? undefined,
              occurredAt: row.createdAt,
              ...payload,
              id: row.id,
            });
            secureLog('debug', 'OutboxPoller: event published (memory mode)', {
              eventId: row.id,
              eventType: row.eventType,
            });
          } catch (publishError: unknown) {
            // 内存模式 publish 失败：走重试/死信流程
            const { message: errorMessage, stack: errorStack } = extractErrorInfo(publishError);
            const retryCount = row.retryCount || 0;
            if (retryCount >= MAX_RETRY_COUNT) {
              await outbox.markAsDeadLetter(row.id, errorStack);
              failed++;
              secureLog('error', 'Outbox event marked as dead letter (publish failed)', {
                eventId: row.id,
                eventType: row.eventType,
                retryCount,
                error: errorMessage,
              });
            } else {
              await outbox.markAsFailed(row.id, errorMessage);
              retried++;
              secureLog('warn', 'Outbox event publish failed, will retry', {
                eventId: row.id,
                eventType: row.eventType,
                retryCount: retryCount + 1,
                nextExecuteAt: `+${retryCount + 1 === 1 ? 1 : retryCount + 1 === 2 ? 3 : 9}s`,
                error: errorMessage,
              });
            }
            continue;
          }

          try {
            await outbox.markAsProcessed(row.id);
            secureLog('debug', 'OutboxPoller: event marked as processed', { eventId: row.id });
          } catch (markError: unknown) {
            const { message: markErrorMsg } = extractErrorInfo(markError);
            secureLog('warn', 'OutboxPoller: markAsProcessed failed in memory mode', {
              eventId: row.id,
              error: markErrorMsg,
            });
          }
          processed++;
        }
      }
    } catch (error: unknown) {
      const { message } = extractErrorInfo(error);
      secureLog('error', 'Outbox poller error', { error: message });
    } finally {
      polling = false;
    }

    return { processed, failed, retried };
  }

  static start(): void {
    if (pollTimer) return;

    secureLog('info', 'Outbox poller starting', {
      intervalMs: POLL_INTERVAL_MS,
      reclaimIntervalMs: RECLAIM_INTERVAL_MS,
      cleanupIntervalMs: CLEANUP_INTERVAL_MS,
      dispatchingTimeoutMinutes: DISPATCHING_TIMEOUT_MINUTES,
    });

    pollTimer = setInterval(async () => {
      try {
        const result = await OutboxPoller.poll();
        if (result.processed > 0 || result.failed > 0 || result.retried > 0) {
          secureLog('info', 'Outbox poll cycle', {
            ...result,
            mode: getStreamPublisher() ? 'stream' : 'memory',
          });
        }
      } catch (error: unknown) {
        const { message } = extractErrorInfo(error);
        secureLog('error', 'Outbox poller interval error', { error: message });
      }
    }, POLL_INTERVAL_MS);

    // 定时回收崩溃残留记录（两类）
    // 1. sys_event_processed 中过期的 'processing' 记录（IdempotencyGuard 侧）
    // 2. domain_event_outbox 中卡在 'dispatching' 的事件（OutboxPoller 崩溃恢复）
    reclaimTimer = setInterval(async () => {
      try {
        await IdempotencyGuard.reclaimStaleProcessing();
      } catch (error: unknown) {
        const { message } = extractErrorInfo(error);
        secureLog('warn', 'OutboxPoller: reclaim stale processing error', { error: message });
      }
      try {
        const outbox = getDomainEventOutbox();
        await outbox.reclaimStaleDispatching(DISPATCHING_TIMEOUT_MINUTES);
      } catch (error: unknown) {
        const { message } = extractErrorInfo(error);
        secureLog('warn', 'OutboxPoller: reclaim stale dispatching error', { error: message });
      }
    }, RECLAIM_INTERVAL_MS);

    // 每天清理 30 天前的已处理记录（表膨胀控制）
    cleanupTimer = setInterval(async () => {
      try {
        await IdempotencyGuard.cleanupOlderThan(CLEANUP_OLDER_THAN_DAYS);
      } catch (error: unknown) {
        const { message } = extractErrorInfo(error);
        secureLog('warn', 'OutboxPoller: cleanup old records error', { error: message });
      }
    }, CLEANUP_INTERVAL_MS);

    if (pollTimer.unref) {
      pollTimer.unref();
    }
    if (reclaimTimer.unref) {
      reclaimTimer.unref();
    }
    if (cleanupTimer.unref) {
      cleanupTimer.unref();
    }
  }

  static stop(): void {
    if (pollTimer) {
      clearInterval(pollTimer);
      pollTimer = null;
    }
    if (reclaimTimer) {
      clearInterval(reclaimTimer);
      reclaimTimer = null;
    }
    if (cleanupTimer) {
      clearInterval(cleanupTimer);
      cleanupTimer = null;
    }
    if (pollTimer === null && reclaimTimer === null && cleanupTimer === null) {
      secureLog('info', 'Outbox poller stopped');
    }
  }

  static isRunning(): boolean {
    return pollTimer !== null;
  }
}

import type { Redis } from 'ioredis';
import { registerEventHandlers } from '@/application/EventRegistry';
import { secureLog } from '@/lib/logger';

const STREAM_KEY = 'erp:domain-events';
const GROUP = 'erp-consumers';
const CONSUMER_NAME = `consumer-${process.pid}`;
const BLOCK_MS = 5000;
const BATCH_SIZE = 50;
const RECLAIM_INTERVAL_MS = 60000;
const ERROR_BACKOFF_MS = 1000;

/**
 * 消息空闲超时阈值（毫秒）
 *
 * 超过此时间未被 ACK 的消息会被 XAUTOCLAIM 重新分配给当前消费者。
 * 此值必须大于 handler 的最大执行时间，否则正在执行的 handler 会被中断，
 * 导致消息被重复投递且可能因 IdempotentHandler 跳过执行而丢失。
 *
 * 可通过 STREAM_RECLAIM_IDLE_MS 环境变量配置，默认 60000（60 秒）。
 * 建议设置为 handler 最大执行时间的 1.5~2 倍。
 */
const RECLAIM_IDLE_MS = (() => {
  const raw = Number.parseInt(process.env.STREAM_RECLAIM_IDLE_MS || '', 10);
  return Number.isFinite(raw) && raw > 0 ? raw : 60000;
})();

function fieldsToObject(fields: unknown[]): Record<string, string> {
  const obj: Record<string, string> = {};
  for (let i = 0; i < fields.length; i += 2) {
    const key = String(fields[i]);
    const value = fields[i + 1];
    obj[key] = value === null || value === undefined ? '' : String(value);
  }
  return obj;
}

/**
 * Redis Stream 事件消费者
 *
 * 通过消费者组 (XREADGROUP) 从 Stream 拉取事件，分发到 InMemoryEventBus。
 *
 * 流程：
 * - OutboxPoller claim 事件 → XADD 到 Stream → markAsProcessed（outbox 侧完成）
 * - StreamConsumer XREADGROUP → eventBus.publish（含 IdempotentHandler 幂等保护）→ XACK
 *
 * 故障恢复：
 * - 消费失败不 ACK，消息保留在 pending list
 * - 定期 XAUTOCLAIM 回收 idle > 30s 的遗留消息（死消费者遗留）
 * - 幂等性由 IdempotentHandler 保证，重投递不会重复执行副作用
 *
 * 注意：不调用 outbox.markAsProcessed — OutboxPoller 在 XADD 成功后已标记。
 */
export class StreamConsumer {
  private running = false;
  private reclaimTimer: ReturnType<typeof setInterval> | null = null;

  constructor(private readonly redis: Redis) {}

  async start(): Promise<void> {
    if (this.running) return;
    this.running = true;

    await this.ensureGroup();
    secureLog('info', 'StreamConsumer started', { consumer: CONSUMER_NAME });

    this.startConsumeLoop();

    this.reclaimTimer = setInterval(() => {
      this.reclaimStaleMessages().catch((err) => {
        secureLog('warn', 'StreamConsumer: reclaim tick failed', { error: String(err) });
      });
    }, RECLAIM_INTERVAL_MS);
    if (this.reclaimTimer.unref) {
      this.reclaimTimer.unref();
    }
  }

  /**
   * 启动消费循环，异常退出时自动重启（带退避）
   *
   * consumeLoop 内部已有 try-catch 处理单次迭代错误，但如果循环本身
   * 意外退出（如 catch 块内部抛错），此处的包装会自动重启，
   * 避免 this.running=true 但实际不消费的静默死亡场景。
   */
  private startConsumeLoop(): void {
    this.consumeLoop().catch((err) => {
      secureLog('error', 'StreamConsumer: consumeLoop exited unexpectedly, will restart', {
        error: String(err),
        consumer: CONSUMER_NAME,
      });
      if (this.running) {
        setTimeout(() => {
          if (this.running) {
            secureLog('info', 'StreamConsumer: restarting consumeLoop', { consumer: CONSUMER_NAME });
            this.startConsumeLoop();
          }
        }, ERROR_BACKOFF_MS);
      }
    });
  }

  private async ensureGroup(): Promise<void> {
    try {
      await this.redis.xgroup('CREATE', STREAM_KEY, GROUP, '$', 'MKSTREAM');
      secureLog('info', 'StreamConsumer: consumer group created', { group: GROUP });
    } catch (err) {
      const e = err as Error;
      if (e.message?.includes('BUSYGROUP')) {
        secureLog('debug', 'StreamConsumer: consumer group already exists (BUSYGROUP)', {
          group: GROUP,
        });
        return;
      }
      throw err;
    }
  }

  private async consumeLoop(): Promise<void> {
    while (this.running) {
      try {
        const results = (await this.redis.xreadgroup(
          'GROUP',
          GROUP,
          CONSUMER_NAME,
          'COUNT',
          BATCH_SIZE,
          'BLOCK',
          BLOCK_MS,
          'STREAMS',
          STREAM_KEY,
          '>'
        )) as unknown;

        if (!results || !Array.isArray(results) || results.length === 0) {
          continue;
        }

        const eventBus = registerEventHandlers();

        for (const entry of results as [string, [string, unknown[]][]][]) {
          const messages = entry[1];
          secureLog('debug', 'StreamConsumer: batch received from XREADGROUP', {
            stream: entry[0],
            count: messages.length,
            messageIds: messages.map((m) => m[0]),
            consumer: CONSUMER_NAME,
          });
          for (const [messageId, fields] of messages) {
            await this.processMessage(messageId, fields, eventBus);
          }
        }
      } catch (error) {
        secureLog('error', 'StreamConsumer loop error', { error: String(error) });
        await new Promise((r) => setTimeout(r, ERROR_BACKOFF_MS));
      }
    }
  }

  private async processMessage(
    messageId: string,
    fields: unknown[],
    eventBus: ReturnType<typeof registerEventHandlers>
  ): Promise<void> {
    const data = fieldsToObject(fields);
    let eventId: number | undefined;

    try {
      eventId = Number(data.eventId);

      // eventId 损坏校验：NaN/0/非正数表示 Stream 消息格式异常
      // ACK 掉这条消息避免无限重投，同时记录 error 供排查
      if (!Number.isFinite(eventId) || eventId <= 0) {
        secureLog('error', 'StreamConsumer: invalid eventId in stream message, ACKing to skip', {
          messageId,
          rawEventId: data.eventId,
          eventType: data.eventType,
          consumer: CONSUMER_NAME,
        });
        await this.redis.xack(STREAM_KEY, GROUP, messageId);
        return;
      }

      // JSON.parse 畸形 payload 是不可恢复错误（非瞬时故障）
      // ACK 掉避免 XAUTOCLAIM 无限重投递，与 NaN eventId 处理方式一致
      let payload: Record<string, unknown>;
      try {
        payload = JSON.parse(data.payload || '{}');
      } catch (parseError) {
        secureLog('error', 'StreamConsumer: invalid JSON payload, ACKing to skip', {
          messageId,
          eventId,
          eventType: data.eventType,
          rawPayload: data.payload?.substring(0, 200),
          error: parseError instanceof Error ? parseError.message : String(parseError),
          consumer: CONSUMER_NAME,
        });
        await this.redis.xack(STREAM_KEY, GROUP, messageId);
        return;
      }

      secureLog('debug', 'StreamConsumer: processing message', {
        messageId,
        eventId,
        eventType: data.eventType,
        consumer: CONSUMER_NAME,
      });

      await eventBus.publish({
        id: eventId,
        eventType: data.eventType,
        aggregateType: data.aggregateType || undefined,
        aggregateId: data.aggregateId ? Number(data.aggregateId) : undefined,
        occurredAt: data.occurredAt ? new Date(data.occurredAt) : new Date(),
        payload,
      });

      secureLog('debug', 'StreamConsumer: event published to bus, now XACK', {
        messageId,
        eventId,
        eventType: data.eventType,
      });

      await this.redis.xack(STREAM_KEY, GROUP, messageId);

      secureLog('debug', 'StreamConsumer: message ACKed', {
        messageId,
        eventId,
        eventType: data.eventType,
      });
    } catch (error) {
      secureLog('error', 'StreamConsumer: process message failed, will retry via pending list', {
        messageId,
        eventId,
        eventType: data.eventType,
        consumer: CONSUMER_NAME,
        error: String(error),
        note: 'Message not ACKed — XAUTOCLAIM will redeliver after idle timeout',
      });
    }
  }

  /**
   * 回收死消费者遗留的未 ACK 消息
   * idle 超过 RECLAIM_IDLE_MS 的 pending 消息会被重新分配给当前消费者
   */
  private async reclaimStaleMessages(): Promise<void> {
    try {
      const result = (await this.redis.xautoclaim(
        STREAM_KEY,
        GROUP,
        CONSUMER_NAME,
        RECLAIM_IDLE_MS,
        '0',
        'COUNT',
        BATCH_SIZE
      )) as unknown;

      if (!Array.isArray(result) || result.length < 2) {
        secureLog('debug', 'StreamConsumer: reclaim returned no messages');
        return;
      }

      const messages = result[1] as [string, unknown[]][];
      if (!messages || messages.length === 0) {
        secureLog('debug', 'StreamConsumer: reclaim returned no messages');
        return;
      }

      secureLog('info', 'StreamConsumer: reclaimed stale messages from pending list', {
        count: messages.length,
        messageIds: messages.map((m) => m[0]),
        consumer: CONSUMER_NAME,
        idleThresholdMs: RECLAIM_IDLE_MS,
      });

      const eventBus = registerEventHandlers();
      for (const [messageId, fields] of messages) {
        const data = fieldsToObject(fields);
        secureLog('debug', 'StreamConsumer: reprocessing reclaimed message', {
          messageId,
          eventId: data.eventId,
          eventType: data.eventType,
        });
        await this.processMessage(messageId, fields, eventBus);
      }
    } catch (error) {
      secureLog('warn', 'StreamConsumer: reclaim error', { error: String(error) });
    }
  }

  stop(): void {
    this.running = false;
    if (this.reclaimTimer) {
      clearInterval(this.reclaimTimer);
      this.reclaimTimer = null;
    }
    secureLog('info', 'StreamConsumer stopped', { consumer: CONSUMER_NAME });
  }

  isRunning(): boolean {
    return this.running;
  }
}

import { query } from '@/lib/db';
import { secureLog } from '@/lib/logger';

export interface DeadlockInfo {
  id: number;
  timestamp: string;
  victimQuery: string;
  deadlockJson: string;
}

export interface InnoDBStatus {
  deadlocks: DeadlockInfo[];
  lockWaitCount: number;
  avgLockWaitTime: number;
}

export interface LongTransaction {
  id: number;
  startTime: string;
  duration: number;
  state: string;
  query: string;
  tablesLocked: string[];
}

export interface MonitorResult {
  innodbStatus: InnoDBStatus;
  longTransactions: LongTransaction[];
  alerts: string[];
}

export class DeadlockMonitor {
  static async checkDeadlocks(): Promise<MonitorResult> {
    const result: MonitorResult = {
      innodbStatus: { deadlocks: [], lockWaitCount: 0, avgLockWaitTime: 0 },
      longTransactions: [],
      alerts: [],
    };

    try {
      const statusRows = await query<any>('SHOW ENGINE INNODB STATUS');
      const statusText = statusRows[0]?.Status || '';

      const deadlockMatch = statusText.match(/LATEST DETECTED DEADLOCK[\s\S]*?TRANSACTIONS/);
      if (deadlockMatch) {
        result.alerts.push('检测到最近发生死锁，请检查 InnoDB 状态');
        secureLog('warn', 'Deadlock detected in InnoDB status', {
          snippet: deadlockMatch[0].substring(0, 500),
        });
      }

      const lockWaitMatch = statusText.match(/LOCK WAIT (\d+) lock struct\(s\)/);
      if (lockWaitMatch) {
        result.innodbStatus.lockWaitCount = parseInt(lockWaitMatch[1]);
        if (result.innodbStatus.lockWaitCount > 5) {
          result.alerts.push(`当前有${result.innodbStatus.lockWaitCount}个锁等待，可能存在锁竞争`);
        }
      }
    } catch (error) {
      secureLog('error', 'Failed to check InnoDB status', { error: (error as Error)?.message });
    }

    try {
      const longTxRows = await query<any>(
        `SELECT
          trx_id as id,
          trx_started as startTime,
          TIMESTAMPDIFF(SECOND, trx_started, NOW()) as duration,
          trx_state as state,
          trx_query as query,
          trx_tables_locked as tablesLocked
         FROM information_schema.innodb_trx
         WHERE TIMESTAMPDIFF(SECOND, trx_started, NOW()) > 30
         ORDER BY duration DESC
         LIMIT 10`
      );

      result.longTransactions = longTxRows.map((row) => ({
        id: row.id,
        startTime: row.startTime,
        duration: row.duration,
        state: row.state,
        query: row.query?.substring(0, 200) || '',
        tablesLocked: row.tablesLocked ? String(row.tablesLocked).split(',') : [],
      }));

      if (result.longTransactions.length > 0) {
        result.alerts.push(
          `发现${result.longTransactions.length}个超过30秒的长事务，最长${Math.max(...result.longTransactions.map((t) => t.duration))}秒`
        );
        secureLog('warn', 'Long running transactions detected', {
          count: result.longTransactions.length,
          maxDuration: Math.max(...result.longTransactions.map((t) => t.duration)),
        });
      }
    } catch (error) {
      secureLog('error', 'Failed to check long transactions', { error: (error as Error)?.message });
    }

    try {
      const deadlockHistory = await query<any>(
        `SELECT * FROM mysql.deadlocks ORDER BY id DESC LIMIT 5`
      );
      result.innodbStatus.deadlocks = deadlockHistory.map((row) => ({
        id: row.id,
        timestamp: row.timestamp,
        victimQuery: row.victim_query?.substring(0, 200) || '',
        deadlockJson: row.deadlock_json?.substring(0, 500) || '',
      }));
    } catch {
      // mysql.deadlocks table may not exist in all MySQL configurations
    }

    return result;
  }

  static async killLongTransaction(trxId: number): Promise<boolean> {
    try {
      const trxRows = await query<any>(
        `SELECT trx_mysql_thread_id FROM information_schema.innodb_trx WHERE trx_id = ?`,
        [trxId]
      );
      if (trxRows.length === 0) {
        return false;
      }
      const threadId = trxRows[0].trx_mysql_thread_id;
      await query(`KILL ?`, [threadId]);
      secureLog('warn', 'Killed long transaction', { trxId, threadId });
      return true;
    } catch (error) {
      secureLog('error', 'Failed to kill transaction', { trxId, error: (error as Error)?.message });
      return false;
    }
  }
}

/**
 * 物料成本提供者 — 对接库存模块物料成本表
 *
 * 成本取值优先级：
 * 1. 库存模块移动加权平均成本（inv_material.weighted_avg_cost）
 * 2. base_ink 表的计划价（base_ink.unit_price）
 * 3. 标记为缺失（0）
 *
 * 依据: docs/油墨配方版本管理完整落地方案.md 第七节
 */
import { query } from '@/lib/db';
import { IMaterialCostProvider } from '@/domain/dcprint/services/FormulaCostService';

export class MaterialCostProvider implements IMaterialCostProvider {
  /**
   * 批量获取物料单位成本
   * 查询优先级：inv_material.weighted_avg_cost → base_ink.unit_price
   */
  async getBatchCosts(materialIds: number[]): Promise<Map<number, number>> {
    const costMap = new Map<number, number>();
    if (!materialIds || materialIds.length === 0) return costMap;

    // 优先尝试从库存模块获取移动加权平均成本
    try {
      const invCosts = await query<any>(
        `SELECT id, weighted_avg_cost FROM inv_material WHERE id IN (${materialIds.map(() => '?').join(',')}) AND deleted = 0 AND weighted_avg_cost IS NOT NULL AND weighted_avg_cost > 0`,
        materialIds
      );
      for (const row of invCosts) {
        costMap.set(row.id, Number(row.weighted_avg_cost) || 0);
      }
    } catch {
      // inv_material 表可能不存在或无此字段，忽略错误降级
    }

    // 对未获取到成本的物料，从 base_ink 表获取计划价
    const missingIds = materialIds.filter((id) => !costMap.has(id));
    if (missingIds.length > 0) {
      try {
        const baseInkCosts = await query<any>(
          `SELECT id, unit_price FROM base_ink WHERE id IN (${missingIds.map(() => '?').join(',')})`,
          missingIds
        );
        for (const row of baseInkCosts) {
          costMap.set(row.id, Number(row.unit_price) || 0);
        }
      } catch {
        // base_ink 表可能不存在，忽略
      }
    }

    return costMap;
  }
}

/**
 * DrizzleSalesOrderRepository
 *
 * Drizzle ORM 实现的销售订单仓储，对应 ISalesOrderRepository 接口。
 * 字段映射以 database/vnerpdacahng_schema.sql 实际 DDL 为准（与 src/lib/db/schema.ts 一致）。
 *
 * 已知架构缺口（不在此仓储修复范围）：
 *   - SalesOrder 聚合期望 customerName/totalQuantity/warehouseId/auditBy/auditTime 字段，
 *     但 sal_order 实际表无对应列。本仓储用合理默认值填充以保持聚合并发兼容。
 *   - SalesOrderLine 期望 materialCode/specification/shippedQty，但 sal_order_detail 无对应列
 *     （仅有 deliveredQty）。本仓储将 shippedQty 映射为 deliveredQty，其余用空串/0 填充。
 *   - 历史 MysqlSalesOrderRepository 查询了 customer_name/total_qty/shipped_qty/audit_by/audit_time
 *     等不存在的列，运行时会抛 SQL 错误——本仓储修复了该问题。
 *
 * 接入方式：通过 RepositoryRegistry.getSalesOrderRepository() 获取实例，
 *   默认 REPOSITORY_IMPL=mysql 时不会被调用。
 */

import { eq, and, like, or, gte, lte, desc, inArray, count } from 'drizzle-orm';
import { getDrizzleDb } from '@/lib/db';
import { salOrder, salOrderDetail } from '@/lib/db/schema';
import { transaction } from '@/lib/db';
import { ISalesOrderRepository } from '@/domain/sales/repositories/ISalesOrderRepository';
import { SalesOrder, SalesOrderProps } from '@/domain/sales/aggregates/SalesOrder';
import { SalesOrderStatus, SalesStatus } from '@/domain/sales/value-objects/SalesOrderStatus';
import { generateDocumentNo } from '@/lib/document-numbering';
import type { ResultSetHeader } from 'mysql2/promise';

type SalOrderRow = typeof salOrder.$inferSelect;
type SalOrderDetailRow = typeof salOrderDetail.$inferSelect;

interface PaginatedResult<T> {
  data: T[];
  pagination: {
    page: number;
    pageSize: number;
    total: number;
    totalPages: number;
  };
}

// SQL 日志辅助：记录方法名、表名、查询条件、SQL 描述、参数、结果、耗时
// table/conditions 字段便于后续按表名和条件维度做性能分析（如 grep 聚合慢查询）
function logOp(
  method: string,
  table: string,
  conditions: string,
  sqlDesc: string,
  _params: unknown,
  _result: unknown,
  durationMs: number
) {
  // 调试日志：生产环境关闭，且绝不打印 PARAMS/RESULT（含客户联系方式等 PII）
  if (process.env.NODE_ENV === 'production') return;
  console.debug(
    `[DrizzleSalesRepo] ${method} (${durationMs}ms) TABLE: ${table} CONDITIONS: ${conditions} SQL: ${sqlDesc}`
  );
}

function nowMs() {
  return Date.now();
}

export class DrizzleSalesOrderRepository implements ISalesOrderRepository {
  /**
   * findById - 按 ID 查询单个销售订单 + 明细
   */
  async findById(id: number): Promise<SalesOrder | null> {
    const t0 = nowMs();
    const sqlDesc = `SELECT * FROM sal_order WHERE id=${id} AND deleted=0 LIMIT 1`;
    const order = await getDrizzleDb().query.salOrder.findFirst({
      where: and(eq(salOrder.id, id), eq(salOrder.deleted, 0)),
    });

    if (!order) {
      logOp(
        'findById',
        'sal_order',
        `id=${id} AND deleted=0`,
        sqlDesc,
        { id },
        'null (not found)',
        nowMs() - t0
      );
      return null;
    }

    const detailsSqlDesc = `SELECT * FROM sal_order_detail WHERE order_id=${id} AND deleted=0 ORDER BY id`;
    const details = await getDrizzleDb().query.salOrderDetail.findMany({
      where: and(eq(salOrderDetail.orderId, id), eq(salOrderDetail.deleted, 0)),
      orderBy: (t) => t.id,
    });

    const result = SalesOrder.reconstitute(this.mapToProps(order, details));
    logOp(
      'findById',
      'sal_order + sal_order_detail',
      `id=${id} AND deleted=0`,
      `${sqlDesc}; ${detailsSqlDesc}`,
      { id },
      `order+${details.length} details`,
      nowMs() - t0
    );
    return result;
  }

  /**
   * findByStatus - 分页列表 + 动态过滤 + 批量加载明细
   */
  async findByStatus(
    status: string,
    pagination: { page: number; pageSize: number },
    filters?: { keyword?: string; customerId?: number; startDate?: string; endDate?: string }
  ): Promise<PaginatedResult<SalesOrder>> {
    const t0 = nowMs();
    const conditions = [eq(salOrder.deleted, 0)];

    if (status && status !== 'all') {
      const dbCode = SalesOrderStatus.from(status).toDbCode();
      conditions.push(eq(salOrder.status, dbCode));
    }

    if (filters?.keyword) {
      const kw = `%${filters.keyword}%`;
      conditions.push(or(like(salOrder.orderNo, kw), like(salOrder.contactName, kw))!);
    }

    if (filters?.customerId) {
      conditions.push(eq(salOrder.customerId, filters.customerId));
    }

    if (filters?.startDate) {
      conditions.push(gte(salOrder.orderDate, new Date(filters.startDate)));
    }
    if (filters?.endDate) {
      conditions.push(lte(salOrder.orderDate, new Date(filters.endDate)));
    }

    const where = and(...conditions);

    const totalRow = await getDrizzleDb().select({ total: count() }).from(salOrder).where(where);
    const total = totalRow[0]?.total ?? 0;

    const orders = await getDrizzleDb()
      .select()
      .from(salOrder)
      .where(where)
      .orderBy(desc(salOrder.createTime))
      .limit(pagination.pageSize)
      .offset((pagination.page - 1) * pagination.pageSize);

    if (orders.length === 0) {
      logOp(
        'findByStatus',
        'sal_order',
        `deleted=0 AND status=${status} LIMIT ${pagination.pageSize} OFFSET ${(pagination.page - 1) * pagination.pageSize}`,
        `SELECT * FROM sal_order WHERE deleted=0 AND status=${status} LIMIT ${pagination.pageSize} OFFSET ${(pagination.page - 1) * pagination.pageSize}`,
        { status, pagination, filters },
        '0 rows (empty)',
        nowMs() - t0
      );
      return {
        data: [],
        pagination: {
          page: pagination.page,
          pageSize: pagination.pageSize,
          total: 0,
          totalPages: 0,
        },
      };
    }

    const orderIds = orders.map((o) => o.id);
    const allDetails = await getDrizzleDb().query.salOrderDetail.findMany({
      where: and(inArray(salOrderDetail.orderId, orderIds), eq(salOrderDetail.deleted, 0)),
      orderBy: (t) => t.id,
    });

    const detailsMap = new Map<number, SalOrderDetailRow[]>();
    for (const d of allDetails) {
      const list = detailsMap.get(d.orderId) ?? [];
      list.push(d);
      detailsMap.set(d.orderId, list);
    }

    const data = orders.map((o) =>
      SalesOrder.reconstitute(this.mapToProps(o, detailsMap.get(o.id) ?? []))
    );

    logOp(
      'findByStatus',
      'sal_order + sal_order_detail',
      `deleted=0 AND status=${status} LIMIT ${pagination.pageSize} OFFSET ${(pagination.page - 1) * pagination.pageSize}`,
      `SELECT * FROM sal_order WHERE deleted=0 AND status=${status} LIMIT ${pagination.pageSize} OFFSET ${(pagination.page - 1) * pagination.pageSize}; SELECT * FROM sal_order_detail WHERE order_id IN (${orderIds.join(',')})`,
      { status, pagination, filters },
      `${orders.length} orders, ${allDetails.length} details, total=${total}`,
      nowMs() - t0
    );

    return {
      data,
      pagination: {
        page: pagination.page,
        pageSize: pagination.pageSize,
        total,
        totalPages: Math.ceil(total / pagination.pageSize),
      },
    };
  }

  /**
   * save - 事务插入主表 + 批量插入明细
   * 沿用 DrizzleInboundOrderRepository 模式：transaction 包装 + conn.execute raw SQL
   */
  async save(order: SalesOrder): Promise<{ id: number; orderNo: string }> {
    const t0 = nowMs();
    const orderNo = await generateDocumentNo('sales_order');

    const result = await transaction(async (conn) => {
      const orderSql = `INSERT INTO sal_order (order_no, order_date, customer_id, contact_name, ..., status, remark, create_by, create_time) VALUES (?, ?, ?, ..., NOW())`;
      const orderParams = [
        orderNo,
        order.orderDate || null,
        order.customerId,
        order.customerName || null,
        null,
        null,
        null,
        order.totalAmount,
        0,
        order.totalAmount,
        0,
        'CNY',
        1.0,
        null,
        order.deliveryDate || null,
        null,
        order.status.toDbCode(),
        order.remark || null,
        order.createBy || null,
      ];

      const [orderResult] = await conn.execute(
        `INSERT INTO sal_order
         (order_no, order_date, customer_id, contact_name, contact_phone, delivery_address,
          salesman_id, total_amount, tax_amount, total_with_tax, discount_amount,
          currency, exchange_rate, payment_terms, delivery_date, contract_no,
          status, remark, create_by, create_time)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())`,
        orderParams
      );
      const orderId = (orderResult as ResultSetHeader).insertId;

      for (const line of order.lines) {
        const lineParams = [
          orderId,
          line.materialId,
          line.materialName || null,
          line.orderQty,
          line.unit || null,
          line.unitPrice,
          0,
          line.amount,
          0,
          line.amount,
          line.shippedQty || 0,
          null,
          line.remark || null,
        ];
        await conn.execute(
          `INSERT INTO sal_order_detail
           (order_id, material_id, material_name, quantity, unit, unit_price,
            tax_rate, amount, tax_amount, total_amount, delivered_qty, delivery_date, remark, create_time)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())`,
          lineParams
        );
      }

      return { id: orderId, orderNo };
    });

    logOp(
      'save',
      'sal_order (INSERT) + sal_order_detail (INSERT)',
      'N/A (new row)',
      `INSERT INTO sal_order (...) + ${order.lines.length} detail inserts (in transaction)`,
      { orderNo, customerId: order.customerId, lineCount: order.lines.length },
      result,
      nowMs() - t0
    );
    return result;
  }

  /**
   * updateStatus - 乐观锁 UPDATE
   */
  async updateStatus(id: number, status: string, currentStatus: string): Promise<boolean> {
    const t0 = nowMs();
    const dbStatus = SalesOrderStatus.from(status).toDbCode();
    const dbCurrentStatus = SalesOrderStatus.from(currentStatus).toDbCode();

    const result = await getDrizzleDb()
      .update(salOrder)
      .set({ status: dbStatus, updateTime: new Date() })
      .where(and(eq(salOrder.id, id), eq(salOrder.status, dbCurrentStatus)));

    const affected = (result[0] as ResultSetHeader)?.affectedRows > 0;
    logOp(
      'updateStatus',
      'sal_order (UPDATE)',
      `id=${id} AND status=${dbCurrentStatus} (optimistic lock)`,
      `UPDATE sal_order SET status=${dbStatus}, update_time=NOW() WHERE id=${id} AND status=${dbCurrentStatus} (optimistic lock)`,
      { id, status, currentStatus },
      `affected=${affected}`,
      nowMs() - t0
    );
    return affected;
  }

  /**
   * updateShippedQty - 更新明细已发货数量（映射到 delivered_qty 列）
   */
  async updateShippedQty(lineId: number, shippedQty: number): Promise<void> {
    const t0 = nowMs();
    await getDrizzleDb()
      .update(salOrderDetail)
      .set({ deliveredQty: shippedQty.toString() })
      .where(eq(salOrderDetail.id, lineId));
    logOp(
      'updateShippedQty',
      'sal_order_detail (UPDATE)',
      `id=${lineId}`,
      `UPDATE sal_order_detail SET delivered_qty=${shippedQty} WHERE id=${lineId}`,
      { lineId, shippedQty },
      'done',
      nowMs() - t0
    );
  }

  /**
   * updateAuditInfo - 更新审核信息
   * 注意：sal_order 表无 audit_by/audit_time 列，此方法为接口兼容保留，
   * 实际无操作。如需审核追踪，应通过领域事件或新增列实现。
   */
  async updateAuditInfo(id: number, auditBy: number, auditTime: string): Promise<void> {
    const t0 = nowMs();
    await getDrizzleDb()
      .update(salOrder)
      .set({ updateTime: new Date() })
      .where(eq(salOrder.id, id));
    logOp(
      'updateAuditInfo',
      'sal_order (UPDATE)',
      `id=${id}`,
      `UPDATE sal_order SET update_time=NOW() WHERE id=${id} (NOTE: sal_order has no audit_by/audit_time columns; no-op for audit fields)`,
      { id, auditBy, auditTime },
      'done',
      nowMs() - t0
    );
  }

  /**
   * softDelete - 软删除
   */
  async softDelete(id: number): Promise<void> {
    const t0 = nowMs();
    await getDrizzleDb()
      .update(salOrder)
      .set({ deleted: 1, updateTime: new Date() })
      .where(eq(salOrder.id, id));
    logOp(
      'softDelete',
      'sal_order (UPDATE)',
      `id=${id}`,
      `UPDATE sal_order SET deleted=true, update_time=NOW() WHERE id=${id}`,
      { id },
      'done',
      nowMs() - t0
    );
  }

  /**
   * mapToProps - DB 行映射到 SalesOrderProps
   * 处理 SalesOrder 聚合与实际 DB 表的字段缺口
   */
  private mapToProps(order: SalOrderRow, details: SalOrderDetailRow[]): SalesOrderProps {
    let statusValue: SalesStatus;
    try {
      statusValue = SalesOrderStatus.fromDbCode(order.status ?? 0).value;
    } catch {
      statusValue = 'draft';
    }

    return {
      id: order.id,
      orderNo: order.orderNo,
      status: statusValue,
      customerId: order.customerId,
      customerName: order.contactName ?? '',
      orderDate: order.orderDate ? String(order.orderDate) : '',
      deliveryDate: order.deliveryDate ? String(order.deliveryDate) : '',
      totalAmount: order.totalAmount ? Number(order.totalAmount) : 0,
      totalQuantity: details.reduce((sum, d) => sum + Number(d.quantity ?? 0), 0),
      warehouseId: 1,
      remark: order.remark ?? '',
      createBy: order.createBy ?? undefined,
      auditBy: undefined,
      auditTime: undefined,
      lines: details.map((d, index) => ({
        id: d.id,
        orderId: d.orderId,
        lineNo: index + 1,
        materialId: d.materialId,
        materialCode: '',
        materialName: d.materialName ?? '',
        specification: '',
        unit: d.unit ?? '件',
        orderQty: Number(d.quantity ?? 0),
        shippedQty: Number(d.deliveredQty ?? 0),
        unitPrice: Number(d.unitPrice ?? 0),
        amount: Number(d.amount ?? 0),
        remark: d.remark ?? undefined,
      })),
      createTime: order.createTime ? String(order.createTime) : undefined,
      updateTime: order.updateTime ? String(order.updateTime) : undefined,
    };
  }
}

import { query, execute, queryOne, type SqlValue } from '@/lib/db';
import { IDieRepository } from '@/domain/prepress/repositories/IDieRepository';
import { Die, DieStatusValue } from '@/domain/prepress/aggregates/Die';

export class MysqlDieRepository implements IDieRepository {
  async getById(id: number): Promise<Die | null> {
    const rows = await query('SELECT * FROM prd_die_template WHERE id = ? AND deleted = 0', [id]);
    if (!rows || rows.length === 0) return null;
    return Die.fromRow(rows[0] as Record<string, unknown>);
  }

  async getByCode(code: string): Promise<Die | null> {
    const rows = await query(
      'SELECT * FROM prd_die_template WHERE template_code = ? AND deleted = 0',
      [code]
    );
    if (!rows || rows.length === 0) return null;
    return Die.fromRow(rows[0] as Record<string, unknown>);
  }

  async existsByCode(code: string, excludeId?: number): Promise<boolean> {
    let sql = 'SELECT id FROM prd_die_template WHERE template_code = ? AND deleted = 0';
    const params: SqlValue[] = [code];
    if (excludeId) {
      sql += ' AND id != ?';
      params.push(excludeId);
    }
    const row = await queryOne(sql, params);
    return !!row;
  }

  async findAll(params?: {
    keyword?: string;
    templateType?: number;
    assetType?: string;
    dieStatus?: DieStatusValue;
    status?: number;
    page?: number;
    pageSize?: number;
  }): Promise<{ list: Die[]; total: number }> {
    let where = 'WHERE deleted = 0';
    const values: SqlValue[] = [];

    if (params?.keyword) {
      where += ' AND (template_code LIKE ? OR template_name LIKE ? OR qr_code LIKE ?)';
      const kw = `%${params.keyword}%`;
      values.push(kw, kw, kw);
    }
    if (params?.templateType) {
      where += ' AND template_type = ?';
      values.push(params.templateType);
    }
    if (params?.assetType) {
      where += ' AND asset_type = ?';
      values.push(params.assetType);
    }
    if (params?.dieStatus) {
      where += ' AND die_status = ?';
      values.push(params.dieStatus);
    }
    if (params?.status) {
      where += ' AND status = ?';
      values.push(params.status);
    }

    const page = params?.page || 1;
    const pageSize = params?.pageSize || 20;

    const countResult = await queryOne(
      `SELECT COUNT(*) as total FROM prd_die_template ${where}`,
      values
    );
    const total = ((countResult as Record<string, unknown>)?.total as number) || 0;

    const rows = await query(
      `SELECT * FROM prd_die_template ${where} ORDER BY id ASC LIMIT ? OFFSET ?`,
      [...values, pageSize, (page - 1) * pageSize]
    );

    return {
      list: (rows as Record<string, unknown>[]).map((r) => Die.fromRow(r)),
      total,
    };
  }

  async findWarningList(): Promise<Die[]> {
    const rows = await query(
      `SELECT * FROM prd_die_template WHERE deleted = 0 AND (
        die_status IN ('maintenance_needed', 're_rule_needed') OR
        (current_usage >= warning_usage AND status = 1) OR
        (cumulative_impressions >= max_impressions * warning_threshold / 100 AND max_impressions > 0)
      )`
    );
    return (rows as Record<string, unknown>[]).map((r) => Die.fromRow(r));
  }

  async getDashboardStats(): Promise<Record<string, unknown>> {
    const row = await queryOne(
      `SELECT
        COUNT(*) as total_count,
        SUM(CASE WHEN die_status = 'available' OR status = 1 THEN 1 ELSE 0 END) as available_count,
        SUM(CASE WHEN die_status = 'maintenance_needed' OR status = 2 THEN 1 ELSE 0 END) as warning_count,
        SUM(CASE WHEN die_status = 're_rule_needed' OR status = 3 THEN 1 ELSE 0 END) as locked_count,
        SUM(CASE WHEN die_status = 'scrap' OR status = 4 THEN 1 ELSE 0 END) as scrap_count,
        SUM(CASE WHEN maintenance_interval > 0 AND (cumulative_impressions - last_maintenance_impressions) >= maintenance_interval THEN 1 ELSE 0 END) as maintenance_due_count
      FROM prd_die_template WHERE deleted = 0`
    );
    return (row as Record<string, unknown>) || {};
  }

  async getTypeStats(): Promise<Record<string, unknown>[]> {
    const rows = await query(
      `SELECT template_type, asset_type, COUNT(*) as count,
        AVG(CASE WHEN max_impressions > 0 THEN cumulative_impressions / max_impressions * 100 ELSE 0 END) as avg_usage_pct,
        SUM(CASE WHEN die_status = 'maintenance_needed' THEN 1 ELSE 0 END) as maintenance_needed_count,
        SUM(CASE WHEN die_status = 're_rule_needed' THEN 1 ELSE 0 END) as re_rule_needed_count,
        SUM(CASE WHEN die_status = 'scrap' THEN 1 ELSE 0 END) as scrap_count
      FROM prd_die_template WHERE deleted = 0 GROUP BY template_type, asset_type`
    );
    return rows as Record<string, unknown>[];
  }

  async save(die: Die): Promise<number> {
    const row = die.toRow();
    const cols = Object.keys(row).join(', ');
    const placeholders = Object.keys(row)
      .map(() => '?')
      .join(', ');
    const values = Object.values(row);

    const result = await execute(
      `INSERT INTO prd_die_template (${cols}, create_time, update_time) VALUES (${placeholders}, NOW(), NOW())`,
      values as SqlValue[]
    );
    return result.insertId;
  }

  async update(die: Die): Promise<void> {
    const row = die.toRow();
    const setClause = Object.keys(row)
      .map((k) => `${k} = ?`)
      .join(', ');
    const values = Object.values(row);
    await execute(`UPDATE prd_die_template SET ${setClause} WHERE id = ? AND deleted = 0`, [
      ...values,
      die.id,
    ] as SqlValue[]);
  }

  async softDelete(id: number): Promise<void> {
    await execute('UPDATE prd_die_template SET deleted = 1 WHERE id = ?', [id]);
  }
}

import { execute, query, getPool } from '@/lib/db';
import type { PoolConnection, RowDataPacket } from 'mysql2/promise';
import type { DomainEvent } from '@/domain/shared/DomainTypes';
import type {
  IDomainEventOutboxRepository,
  EventOutboxRecord,
} from '@/infrastructure/event-bus/types/IDomainEventOutboxRepository';
import { secureLog } from '@/lib/logger';

/**
 * MySQL 实现的领域事件持久化仓储
 *
 * 与原 DomainEventOutbox.ts 静态方法行为对齐，新增：
 * - markAsDeadLetter 方法（1.5 任务使用）
 * - fetchPendingEvents 加入 next_execute_at 过滤（1.4 任务指数退避使用）
 * - 返回值类型严格化为 EventOutboxRecord
 *
 * 兼容性：原 DomainEventOutbox 静态类保持运行，本类供 1.6 任务依赖注入切换使用。
 */
interface EventOutboxRow {
  id: number;
  event_type: string;
  aggregate_type: string;
  aggregate_id: number;
  payload: string | Buffer;
  status: string;
  retry_count: number;
  error_message: string | null;
  next_execute_at: Date | null;
  create_time: Date;
  processed_at: Date | null;
}

export class MysqlDomainEventOutboxRepository implements IDomainEventOutboxRepository {
  /**
   * 在外部事务连接内保存事件
   * 与原 DomainEventOutbox.saveEvents 行为完全一致，保证向后兼容
   */
  async saveEvents(
    conn: PoolConnection,
    aggregateType: string,
    aggregateId: number,
    events: DomainEvent[]
  ): Promise<void> {
    for (const event of events) {
      await conn.execute(
        `INSERT INTO domain_event_outbox (event_type, aggregate_type, aggregate_id, payload, status, create_time)
         VALUES (?, ?, ?, ?, 'pending', NOW())`,
        [event.eventType, aggregateType, aggregateId, JSON.stringify(event)]
      );
    }
  }

  /**
   * 查询待执行事件
   * 加入 next_execute_at 过滤：仅返回到期或无延迟的事件（1.4 指数退避）
   * 原实现未过滤 next_execute_at，本实现向后兼容（NULL 视为立即可执行）
   */
  async fetchPendingEvents(limit: number = 50): Promise<EventOutboxRecord[]> {
    const rows = await query(
      `SELECT id, event_type, aggregate_type, aggregate_id, payload, status,
              retry_count, error_message, next_execute_at, create_time, processed_at
       FROM domain_event_outbox
       WHERE status = 'pending'
         AND (next_execute_at IS NULL OR next_execute_at <= NOW())
       ORDER BY create_time ASC
       LIMIT ?`,
      [limit]
    );
    return rows.map(this.toRecord);
  }

  /**
   * 原子 claim 待执行事件（多实例安全）
   *
   * 使用 SELECT FOR UPDATE SKIP LOCKED 在事务内选取 pending 事件，
   * 同事务内将其状态改为 dispatching 并记录 claimed_at。
   * MySQL 8.0+ 的 SKIP LOCKED 跳过已被其他事务锁定的行，避免重复消费。
   */
  async claimPendingEvents(limit: number = 50): Promise<EventOutboxRecord[]> {
    const conn = await getPool().getConnection();
    try {
      await conn.beginTransaction();

      const [rows] = (await conn.query(
        `SELECT id, event_type, aggregate_type, aggregate_id, payload, status,
                retry_count, error_message, next_execute_at, create_time, processed_at
         FROM domain_event_outbox
         WHERE status = 'pending'
           AND (next_execute_at IS NULL OR next_execute_at <= NOW())
         ORDER BY create_time ASC
         LIMIT ?
         FOR UPDATE SKIP LOCKED`,
        [limit]
      )) as [RowDataPacket[], RowDataPacket];

      if (rows.length === 0) {
        await conn.commit();
        return [];
      }

      const ids = rows.map((r) => r.id);
      await conn.query(
        `UPDATE domain_event_outbox
         SET status = 'dispatching', claimed_at = NOW()
         WHERE id IN (${ids.map(() => '?').join(',')})`,
        ids
      );

      await conn.commit();
      return rows.map((r: RowDataPacket) => this.toRecord(r as EventOutboxRow));
    } catch (err) {
      await conn.rollback();
      throw err;
    } finally {
      conn.release();
    }
  }

  async markAsProcessed(id: number): Promise<void> {
    await execute(
      `UPDATE domain_event_outbox
       SET status = 'processed', processed_at = NOW(), dispatched_at = NOW()
       WHERE id = ?`,
      [id]
    );
  }

  /**
   * 标记失败（指数退避：1s/3s/9s）
   * 与 DomainEventOutbox.markAsFailed 行为对齐：状态保持 pending，设置 next_execute_at
   * 通过 JOIN 子查询读取原 retry_count，避免同 SET 内赋值对 CASE 求值的影响
   */
  async markAsFailed(id: number, error: string): Promise<void> {
    const errorMessage = error.substring(0, 500);
    await execute(
      `UPDATE domain_event_outbox o
       JOIN (SELECT retry_count AS old_retry FROM domain_event_outbox WHERE id = ?) t
       SET o.status = 'pending',
           o.error_message = ?,
           o.retry_count = t.old_retry + 1,
           o.next_execute_at = CASE
             WHEN t.old_retry + 1 = 1 THEN DATE_ADD(NOW(), INTERVAL 1 SECOND)
             WHEN t.old_retry + 1 = 2 THEN DATE_ADD(NOW(), INTERVAL 3 SECOND)
             WHEN t.old_retry + 1 = 3 THEN DATE_ADD(NOW(), INTERVAL 9 SECOND)
             ELSE DATE_ADD(NOW(), INTERVAL 9 SECOND)
           END
       WHERE o.id = ?`,
      [id, errorMessage, id]
    );
  }

  /**
   * 标记死信（1.5 任务实现）
   * 完整错误栈写入 error_message（截断 2000 字符，覆盖大多数错误栈且远小于 TEXT 上限）
   */
  async markAsDeadLetter(id: number, error: string): Promise<void> {
    await execute(
      `UPDATE domain_event_outbox
       SET status = 'dead_letter', error_message = ?
       WHERE id = ?`,
      [error.substring(0, 2000), id]
    );
    secureLog('error', 'Event marked as dead letter', {
      eventId: id,
      error: error.substring(0, 200),
    });
  }

  /**
   * 重置失败事件为待处理（手动重试入口）
   * 1.4 改造：清理 next_execute_at，让事件立即可被消费
   * id=0 批量重置所有 retry_count < 3 的事件
   */
  async markForRetry(id: number): Promise<void> {
    if (id === 0) {
      await execute(
        `UPDATE domain_event_outbox
         SET status = 'pending', error_message = NULL, next_execute_at = NULL
         WHERE status = 'pending' AND retry_count > 0 AND retry_count < 3`
      );
      return;
    }
    await execute(
      `UPDATE domain_event_outbox
       SET status = 'pending', error_message = NULL, next_execute_at = NULL
       WHERE id = ? AND retry_count < 3`,
      [id]
    );
  }

  /**
   * 回收卡在 'dispatching' 状态的事件（崩溃恢复）
   *
   * OutboxPoller 在 claimPendingEvents 后崩溃会导致事件卡在 'dispatching'。
   * 此方法将超过 timeout 分钟的 dispatching 事件重置为 pending，使其可被重新消费。
   * 幂等操作：多实例并发调用不会冲突，UPDATE 是行级原子的。
   */
  async reclaimStaleDispatching(timeoutMinutes: number): Promise<number> {
    const result = await execute(
      `UPDATE domain_event_outbox
       SET status = 'pending', claimed_at = NULL
       WHERE status = 'dispatching'
         AND claimed_at < DATE_SUB(NOW(), INTERVAL ? MINUTE)`,
      [timeoutMinutes]
    );
    const reset = result.affectedRows;
    if (reset > 0) {
      secureLog('warn', 'MysqlDomainEventOutbox: reclaimed stale dispatching events', {
        count: reset,
        timeoutMinutes,
      });
    }
    return reset;
  }

  // 将数据库行映射为 EventOutboxRecord
  private toRecord(row: EventOutboxRow): EventOutboxRecord {
    return {
      id: row.id,
      eventType: row.event_type,
      aggregateType: row.aggregate_type,
      aggregateId: row.aggregate_id,
      payload: typeof row.payload === 'string' ? row.payload : JSON.stringify(row.payload),
      status: row.status as EventOutboxRecord['status'],
      retryCount: row.retry_count || 0,
      errorMessage: row.error_message,
      nextExecuteAt: row.next_execute_at ? new Date(row.next_execute_at) : null,
      createdAt: row.create_time ? new Date(row.create_time) : new Date(),
      processedAt: row.processed_at ? new Date(row.processed_at) : null,
    };
  }
}

