import { IWorkOrderRepository } from '@/domain/production/repositories/IWorkOrderRepository';
import { WorkOrder, WorkOrderProps } from '@/domain/production/aggregates/WorkOrder';
import { WorkOrderStatusVO } from '@/domain/production/value-objects/WorkOrderStatus';
import { query, execute, transaction, queryPaginated } from '@/lib/db';
import type { ResultSetHeader } from 'mysql2/promise';
import { generateDocumentNo } from '@/lib/document-numbering';

interface WorkOrderRow {
  id: number;
  work_order_no: string;
  status: number;
  product_id: number;
  product_name: string;
  product_code: string;
  order_type: number;
  process_id: number | null;
  process_name: string | null;
  warehouse_id: number;
  planned_qty: number;
  completed_qty: number;
  planned_start_date: Date | null;
  planned_end_date: Date | null;
  actual_start_date: Date | null;
  actual_end_date: Date | null;
  remark: string;
  create_by: number | null;
  create_time: Date;
  update_time: Date | null;
  deleted: number;
}

interface WorkOrderMaterialRow {
  id: number;
  work_order_id: number;
  material_id: number;
  material_code: string;
  material_name: string;
  specification: string;
  unit: string;
  required_qty: number;
  issued_qty: number;
  returned_qty: number;
  warehouse_id: number;
}

export class MysqlWorkOrderRepository implements IWorkOrderRepository {
  async findById(id: number): Promise<WorkOrder | null> {
    const orders = await query('SELECT * FROM prod_work_order WHERE id = ? AND deleted = 0', [id]);
    if (!orders || orders.length === 0) return null;

    const order = orders[0];
    const materials = await query(
      'SELECT * FROM prod_work_order_material WHERE work_order_id = ? AND deleted = 0 ORDER BY id ASC',
      [id]
    );

    return WorkOrder.reconstitute(this.mapToProps(order, materials));
  }

  async findByWorkOrderNo(workOrderNo: string): Promise<WorkOrder | null> {
    const orders = await query(
      'SELECT * FROM prod_work_order WHERE work_order_no = ? AND deleted = 0',
      [workOrderNo]
    );
    if (!orders || orders.length === 0) return null;

    const order = orders[0];
    const materials = await query(
      'SELECT * FROM prod_work_order_material WHERE work_order_id = ? AND deleted = 0 ORDER BY id ASC',
      [order.id]
    );

    return WorkOrder.reconstitute(this.mapToProps(order, materials));
  }

  async findByStatus(
    status: string,
    pagination: { page: number; pageSize: number },
    filters?: { keyword?: string; productId?: number }
  ) {
    let sql = 'SELECT o.* FROM prod_work_order o WHERE o.deleted = 0';
    let countSql = 'SELECT COUNT(*) as total FROM prod_work_order o WHERE o.deleted = 0';
    const params: (string | number)[] = [];

    if (status && status !== 'all') {
      const dbCode = WorkOrderStatusVO.from(status).toDbCode();
      sql += ' AND o.status = ?';
      countSql += ' AND o.status = ?';
      params.push(dbCode);
    }

    if (filters?.keyword) {
      sql += ' AND (o.work_order_no LIKE ? OR o.product_name LIKE ?)';
      countSql += ' AND (o.work_order_no LIKE ? OR o.product_name LIKE ?)';
      params.push(`%${filters.keyword}%`, `%${filters.keyword}%`);
    }

    if (filters?.productId) {
      sql += ' AND o.product_id = ?';
      countSql += ' AND o.product_id = ?';
      params.push(filters.productId);
    }

    sql += ' ORDER BY o.create_time DESC';
    const result = await queryPaginated(sql, countSql, params, pagination);

    return {
      data: result.data.map((o: WorkOrderRow) => WorkOrder.reconstitute(this.mapToProps(o, []))),
      pagination: result.pagination,
    };
  }

  async save(order: WorkOrder): Promise<{ id: number; workOrderNo: string }> {
    const workOrderNo = await generateDocumentNo('work_order');

    return await transaction(async (conn) => {
      const [result] = (await conn.execute(
        `INSERT INTO prod_work_order (work_order_no, product_id, product_name, product_code, planned_qty, completed_qty,
          order_type, process_id, process_name, warehouse_id, planned_start_date, planned_end_date, status, remark, create_by, create_time)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())`,
        [
          workOrderNo,
          order.productId,
          order.productName,
          order.productCode,
          order.plannedQty,
          order.completedQty,
          order.orderType || 0,
          order.processId || null,
          order.processName || null,
          order.warehouseId,
          order.plannedStartDate || null,
          order.plannedEndDate || null,
          order.status.toDbCode(),
          order.remark,
          order.createBy || null,
        ]
      )) as unknown as [ResultSetHeader];

      const orderId = result.insertId;

      for (const mr of order.materialRequirements) {
        await conn.execute(
          `INSERT INTO prod_work_order_material (work_order_id, material_id, material_code, material_name, specification, unit, required_qty, issued_qty, returned_qty, warehouse_id, create_time)
           VALUES (?, ?, ?, ?, ?, ?, ?, 0, 0, ?, NOW())`,
          [
            orderId,
            mr.materialId,
            mr.materialCode,
            mr.materialName,
            mr.specification,
            mr.unit,
            mr.requiredQty,
            mr.warehouseId,
          ]
        );
      }

      return { id: orderId, workOrderNo };
    });
  }

  async updateStatus(id: number, status: string, currentStatus: string): Promise<boolean> {
    const dbStatus = WorkOrderStatusVO.from(status).toDbCode();
    const dbCurrentStatus = WorkOrderStatusVO.from(currentStatus).toDbCode();
    const result = await execute(
      'UPDATE prod_work_order SET status = ?, update_time = NOW() WHERE id = ? AND status = ?',
      [dbStatus, id, dbCurrentStatus]
    );
    return result.affectedRows > 0;
  }

  async softDelete(id: number): Promise<void> {
    await execute('UPDATE prod_work_order SET deleted = 1, update_time = NOW() WHERE id = ?', [id]);
  }

  private mapToProps(order: WorkOrderRow, materials: WorkOrderMaterialRow[]): WorkOrderProps {
    return {
      id: order.id,
      workOrderNo: order.work_order_no,
      status: WorkOrderStatusVO.fromDbCode(order.status).value,
      productId: order.product_id,
      productName: order.product_name || '',
      productCode: order.product_code || '',
      orderType: order.order_type || 0,
      plannedQty: order.planned_qty,
      completedQty: order.completed_qty || 0,
      processId: order.process_id ?? undefined,
      processName: order.process_name ?? undefined,
      warehouseId: order.warehouse_id || 1,
      plannedStartDate: order.planned_start_date
        ? typeof order.planned_start_date === 'string'
          ? order.planned_start_date
          : order.planned_start_date.toISOString()
        : undefined,
      plannedEndDate: order.planned_end_date
        ? typeof order.planned_end_date === 'string'
          ? order.planned_end_date
          : order.planned_end_date.toISOString()
        : undefined,
      actualStartDate: order.actual_start_date
        ? typeof order.actual_start_date === 'string'
          ? order.actual_start_date
          : order.actual_start_date.toISOString()
        : undefined,
      actualEndDate: order.actual_end_date
        ? typeof order.actual_end_date === 'string'
          ? order.actual_end_date
          : order.actual_end_date.toISOString()
        : undefined,
      remark: order.remark || '',
      createBy: order.create_by ?? undefined,
      materialRequirements: (materials || []).map((m: WorkOrderMaterialRow) => ({
        id: m.id,
        materialId: m.material_id,
        materialCode: m.material_code || '',
        materialName: m.material_name || '',
        specification: m.specification || '',
        unit: m.unit || '件',
        requiredQty: m.required_qty,
        issuedQty: m.issued_qty || 0,
        returnedQty: m.returned_qty || 0,
        warehouseId: m.warehouse_id || 1,
      })),
      createTime:
        typeof order.create_time === 'string' ? order.create_time : order.create_time.toISOString(),
      updateTime: order.update_time
        ? typeof order.update_time === 'string'
          ? order.update_time
          : order.update_time.toISOString()
        : undefined,
    };
  }
}

import { query, execute } from '@/lib/db';
import { WorkReport, WorkReportProps } from '@/domain/production/aggregates/WorkReport';
import {
  IWorkReportRepository,
  WorkReportFilters,
} from '@/domain/production/repositories/IWorkReportRepository';

interface WorkReportRow {
  id: number;
  report_no: string;
  work_order_id: number;
  process_name: string;
  equipment_id: number | null;
  equipment_name: string;
  shift: string;
  operator_name: string;
  qualified_qty: number;
  defective_qty: number;
  defect_reason: string | null;
  work_hours: number;
  report_date: string;
  status: number;
  create_by: number | null;
  create_time: Date;
  update_time: Date | null;
}

export class MysqlWorkReportRepository implements IWorkReportRepository {
  async findById(id: number): Promise<WorkReport | null> {
    const rows = await query('SELECT * FROM prd_work_report WHERE id = ? AND deleted = 0', [id]);
    if (!rows || rows.length === 0) return null;
    return this.mapToEntity(rows[0]);
  }

  async findByReportNo(reportNo: string): Promise<WorkReport | null> {
    const rows = await query('SELECT * FROM prd_work_report WHERE report_no = ? AND deleted = 0', [
      reportNo,
    ]);
    if (!rows || rows.length === 0) return null;
    return this.mapToEntity(rows[0]);
  }

  async findByWorkOrderId(workOrderId: number): Promise<WorkReport[]> {
    const rows = await query(
      'SELECT * FROM prd_work_report WHERE work_order_id = ? AND deleted = 0 ORDER BY id DESC',
      [workOrderId]
    );
    return rows.map((r: WorkReportRow) => this.mapToEntity(r));
  }

  async findByFilters(
    filters: WorkReportFilters,
    page = 1,
    pageSize = 20
  ): Promise<{ list: WorkReport[]; total: number }> {
    const conditions: string[] = ['wr.deleted = 0'];
    const params: (string | number | null)[] = [];

    if (filters.workOrderId) {
      conditions.push('wr.work_order_id = ?');
      params.push(filters.workOrderId);
    }
    if (filters.status) {
      conditions.push('wr.status = ?');
      params.push(filters.status);
    }
    if (filters.processName) {
      conditions.push('wr.process_name = ?');
      params.push(filters.processName);
    }
    if (filters.dateFrom) {
      conditions.push('wr.report_date >= ?');
      params.push(filters.dateFrom);
    }
    if (filters.dateTo) {
      conditions.push('wr.report_date <= ?');
      params.push(filters.dateTo);
    }

    const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
    const offset = (page - 1) * pageSize;

    const countResult = await query(
      `SELECT COUNT(*) as total FROM prd_work_report wr ${where}`,
      params
    );
    const total = Number(countResult[0]?.total || 0);
    const rows = await query(
      `SELECT wr.* FROM prd_work_report wr ${where} ORDER BY wr.id DESC LIMIT ? OFFSET ?`,
      [...params, pageSize, offset]
    );

    const list = rows.map((r: WorkReportRow) => this.mapToEntity(r));
    return { list, total };
  }

  async save(report: WorkReport): Promise<number> {
    const result = await execute(
      `INSERT INTO prd_work_report (report_no, work_order_id, process_name, equipment_id, equipment_name, shift, operator_name, qualified_qty, defective_qty, defect_reason, work_hours, report_date, status, create_by, create_time)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, NOW())`,
      [
        report.reportNo,
        report.workOrderId,
        report.processName,
        report.equipmentId || null,
        report.equipmentName,
        report.shift,
        report.operatorName,
        report.qualifiedQty,
        report.defectiveQty,
        report.defectReason,
        report.workHours,
        report.reportDate,
        report.createBy,
      ]
    );
    return (result as { insertId: number }).insertId;
  }

  async update(report: WorkReport): Promise<void> {
    const statusMap: Record<string, number> = { draft: 1, approved: 2, cancelled: 3 };
    const statusCode = statusMap[report.status] || 1;

    await execute(
      `UPDATE prd_work_report SET status = ?, operator_name = ?, qualified_qty = ?, defective_qty = ?, defect_reason = ?, work_hours = ?, update_time = NOW() WHERE id = ?`,
      [
        statusCode,
        report.operatorName,
        report.qualifiedQty,
        report.defectiveQty,
        report.defectReason,
        report.workHours,
        report.id,
      ]
    );
  }

  async softDelete(id: number): Promise<void> {
    await execute('UPDATE prd_work_report SET deleted = 1, update_time = NOW() WHERE id = ?', [id]);
  }

  private mapToEntity(row: WorkReportRow): WorkReport {
    const props: WorkReportProps = {
      id: row.id,
      reportNo: row.report_no,
      workOrderId: row.work_order_id,
      processName: row.process_name,
      equipmentId: row.equipment_id ?? undefined,
      equipmentName: row.equipment_name,
      shift: row.shift,
      operatorName: row.operator_name,
      qualifiedQty: Number(row.qualified_qty || 0),
      defectiveQty: Number(row.defective_qty || 0),
      defectReason: row.defect_reason ?? undefined,
      workHours: Number(row.work_hours || 0),
      reportDate: row.report_date,
      createBy: row.create_by ?? undefined,
      createTime:
        typeof row.create_time === 'string' ? row.create_time : row.create_time.toISOString(),
      updateTime: row.update_time
        ? typeof row.update_time === 'string'
          ? row.update_time
          : row.update_time.toISOString()
        : undefined,
    };
    return WorkReport.reconstitute(props);
  }
}

/**
 * PrintStandardCardRepository
 * --------------------------------------------------------------------------
 * 适配层：将领域实体 StandardCard 映射到「live 的 print 取向单表」 prd_standard_card。
 *
 * 背景（P1-17 / 统一修复）：
 * 项目历史上存在两套互不兼容的 prd_standard_card schema：
 *   - print 取向单表（update_standard_card.sql / vnerpdacahng_schema.sql，column: card_no / status TINYINT 1-4 / FK crm_customer）—— 由整个前端驱动，是 live 权威表；
 *   - 模块化 DDD 设计（standard_card_migration.sql，column: code / is_current / status VARCHAR 枚举）—— 仅被 /api/standard-card/action 状态流转端点依赖。
 * 原 MysqlStandardCardRepository 按模块化 schema 读写（is_current/is_obsolete/is_locked/status 字符串），对 live print 表必然报“未知列/类型不符”。
 *
 * 本仓库让状态流转端点直接操作 live print 表：
 *   - 保留领域状态机（StandardCard.submit/approve/...）做合法性校验；
 *   - 仅持久化 print 表真实存在的列；
 *   - status 在 领域枚举 <-> TINYINT 之间映射（见下）。
 */
import { db } from '@/lib/db';
import { StandardCard } from '@/domain/standard-card/aggregates/StandardCard';
import { StandardCardStatus } from '@/domain/standard-card/value-objects/StandardCardStatus';
import {
  StandardCardType,
} from '@/domain/standard-card/value-objects/StandardCardType';

/** 领域状态枚举 -> print 表 TINYINT（1-草稿 2-待审核 3-已启用 4-已归档 5-已作废） */
const STATUS_TO_INT: Record<StandardCardStatus, number> = {
  [StandardCardStatus.DRAFT]: 1,
  [StandardCardStatus.AUDITING]: 2,
  [StandardCardStatus.APPROVED]: 3,
  [StandardCardStatus.CONFIRMED]: 4,
  [StandardCardStatus.OBSOLETE]: 5,
};

/** print 表 TINYINT -> 领域状态枚举（容错：未知值回退为 DRAFT） */
const INT_TO_STATUS: Record<number, StandardCardStatus> = {
  1: StandardCardStatus.DRAFT,
  2: StandardCardStatus.AUDITING,
  3: StandardCardStatus.APPROVED,
  4: StandardCardStatus.CONFIRMED,
  5: StandardCardStatus.OBSOLETE,
};

export class PrintStandardCardRepository {
  /**
   * 读取单条标准卡并构建领域实体。
   * 注意：print 表没有 material_id / is_current / is_locked 列，这里做兼容处理：
   *   - isLocked 仅在「已归档(CONFIRMED=4)」时视为 true，以允许基于已确认卡创建新版本；
   *   - name 在 print 表恒为 NULL（print 表单用 product_name），构造实体时回退避免校验报错。
   */
  async findById(id: number): Promise<StandardCard | null> {
    const rows = await db.query(
      `SELECT id, card_no, name, type, customer_id, customer_name, product_name, version, status, create_by, update_by
       FROM prd_standard_card WHERE id = ? AND deleted = 0`,
      [id]
    );
    if (rows.length === 0) return null;
    const row = rows[0] as Record<string, any>;
    const statusInt = Number(row.status);
    return new StandardCard({
      id: row.id,
      code: row.card_no,
      version: row.version || '1.0',
      // print 表 name 恒为空，回退保证领域实体可构造
      name: row.name || row.product_name || row.card_no || '标准卡',
      type: (row.type || 'process') as StandardCardType,
      materialId: undefined,
      customerId: row.customer_id ?? undefined,
      customerName: row.customer_name ?? undefined,
      status: INT_TO_STATUS[statusInt] ?? StandardCardStatus.DRAFT,
      isCurrent: false,
      isObsolete: statusInt === 5,
      isLocked: statusInt === 4,
      createUser: row.create_by ?? undefined,
    });
  }

  /**
   * 持久化一次状态流转。仅写 print 表真实存在的列。
   * 作废(OBSOLETE)时额外写 obsolete_reason / obsolete_by / obsolete_at（依赖迁移 072 增加的列）。
   */
  async transition(card: StandardCard, userId: number, reason?: string): Promise<void> {
    const statusInt = STATUS_TO_INT[card.status] ?? 1;
    const params: any[] = [statusInt, userId];
    let sql =
      'UPDATE prd_standard_card SET status = ?, update_by = ?, update_time = NOW()';
    if (card.status === StandardCardStatus.OBSOLETE) {
      sql += ', obsolete_reason = ?, obsolete_by = ?, obsolete_at = NOW()';
      params.push(reason ?? '', userId);
    }
    sql += ' WHERE id = ? AND deleted = 0';
    params.push(card.id!);
    await db.execute(sql, params as any);
  }

  /**
   * 克隆一张新版本标准卡（仅写 print 表真实存在的列；product_name 等不在领域模型中，留空待后续编辑）。
   * 返回新行 id。
   */
  async saveNewVersion(
    card: StandardCard,
    originalCardNo: string,
    userId: number
  ): Promise<number> {
    const newCardNo = `${originalCardNo}-V${card.version}`;
    const result = await db.insert('prd_standard_card', {
      card_no: newCardNo,
      name: card.name,
      type: card.type,
      customer_id: card.customerId ?? null,
      customer_name: '',
      product_name: '',
      version: card.version,
      status: 1,
      create_by: userId,
      update_by: userId,
    });
    return result.insertId;
  }
}

import { getDrizzleDb } from '@/lib/db';
import { sagaLog as sagaLogTable } from '@/lib/db/schema';
import { eq, and, lt } from 'drizzle-orm';

export type SagaStatus = 'pending' | 'executing' | 'success' | 'compensating' | 'compensated' | 'failed';

export type SagaStepStatus = 'pending' | 'success' | 'failed' | 'compensating' | 'compensated';

export interface SagaStep {
  name: string;
  status: SagaStepStatus;
  errorMessage?: string;
  completedAt?: Date;
}

export interface SagaLogRecord {
  id: number;
  sagaId: string;
  sagaType: string;
  status: SagaStatus;
  payload: Record<string, unknown>;
  steps: SagaStep[];
  errorMessage?: string;
  createdAt: Date;
  updatedAt: Date;
}

const db = getDrizzleDb();

export class SagaLogRepository {
  async create(
    sagaId: string,
    sagaType: string,
    payload: Record<string, unknown>
  ): Promise<SagaLogRecord> {
    const result = await db
      .insert(sagaLogTable)
      .values({
        sagaId,
        sagaType,
        status: 'pending',
        payload: JSON.stringify(payload),
        steps: JSON.stringify([]),
      });

    const insertedId = Number(result[0].insertId);
    const [record] = await db.select().from(sagaLogTable).where(eq(sagaLogTable.id, insertedId));
    return this.mapToRecord(record);
  }

  async get(sagaId: string): Promise<SagaLogRecord | null> {
    const result = await db
      .select()
      .from(sagaLogTable)
      .where(eq(sagaLogTable.sagaId, sagaId));

    return result.length > 0 ? this.mapToRecord(result[0]) : null;
  }

  async updateStatus(sagaId: string, status: SagaStatus): Promise<void> {
    await db
      .update(sagaLogTable)
      .set({ status, updatedAt: new Date() })
      .where(eq(sagaLogTable.sagaId, sagaId));
  }

  async updateStatusWithError(sagaId: string, status: SagaStatus, errorMessage: string): Promise<void> {
    await db
      .update(sagaLogTable)
      .set({ status, errorMessage, updatedAt: new Date() })
      .where(eq(sagaLogTable.sagaId, sagaId));
  }

  async addStep(sagaId: string, stepName: string): Promise<void> {
    const record = await this.get(sagaId);
    if (!record) return;

    const newStep: SagaStep = { name: stepName, status: 'pending' };
    const updatedSteps = [...record.steps, newStep];

    await db
      .update(sagaLogTable)
      .set({ steps: JSON.stringify(updatedSteps), updatedAt: new Date() })
      .where(eq(sagaLogTable.sagaId, sagaId));
  }

  async updateStepStatus(sagaId: string, stepName: string, status: SagaStepStatus, errorMessage?: string): Promise<void> {
    const record = await this.get(sagaId);
    if (!record) return;

    const updatedSteps = record.steps.map((step) =>
      step.name === stepName
        ? { ...step, status, errorMessage, completedAt: new Date() }
        : step
    );

    await db
      .update(sagaLogTable)
      .set({ steps: JSON.stringify(updatedSteps), updatedAt: new Date() })
      .where(eq(sagaLogTable.sagaId, sagaId));
  }

  async getStepsByStatus(sagaId: string, status: SagaStepStatus): Promise<SagaStep[]> {
    const record = await this.get(sagaId);
    if (!record) return [];
    return record.steps.filter((step) => step.status === status);
  }

  async findPendingSagas(sagaType?: string): Promise<SagaLogRecord[]> {
    if (sagaType) {
      const results = await db
        .select()
        .from(sagaLogTable)
        .where(and(eq(sagaLogTable.status, 'pending'), eq(sagaLogTable.sagaType, sagaType)));
      return results.map((r) => this.mapToRecord(r));
    }

    const results = await db.select().from(sagaLogTable).where(eq(sagaLogTable.status, 'pending'));
    return results.map((r) => this.mapToRecord(r));
  }

  async findAll(sagaType?: string, status?: SagaStatus): Promise<SagaLogRecord[]> {
    let query = db.select().from(sagaLogTable);

    if (sagaType) {
      query = query.where(eq(sagaLogTable.sagaType, sagaType)) as typeof query;
    }

    if (status) {
      query = query.where(eq(sagaLogTable.status, status)) as typeof query;
    }

    const results = await query.orderBy(sagaLogTable.createdAt);
    return results.map((r) => this.mapToRecord(r));
  }

  async cleanUpOldSagas(daysToKeep: number = 30): Promise<void> {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - daysToKeep);

    await db
      .delete(sagaLogTable)
      .where(
        and(
          eq(sagaLogTable.status, 'success'),
          lt(sagaLogTable.createdAt, cutoffDate)
        )
      );

    await db
      .delete(sagaLogTable)
      .where(
        and(
          eq(sagaLogTable.status, 'compensated'),
          lt(sagaLogTable.createdAt, cutoffDate)
        )
      );
  }

  private mapToRecord(raw: typeof sagaLogTable.$inferSelect): SagaLogRecord {
    return {
      id: raw.id,
      sagaId: raw.sagaId,
      sagaType: raw.sagaType,
      status: raw.status as SagaStatus,
      payload: typeof raw.payload === 'string' ? JSON.parse(raw.payload) : {},
      steps: typeof raw.steps === 'string' ? JSON.parse(raw.steps) : [],
      errorMessage: raw.errorMessage || undefined,
      createdAt: raw.createdAt || new Date(),
      updatedAt: raw.updatedAt || new Date(),
    };
  }
}

import { execute, query } from '@/lib/db';
import { secureLog } from '@/lib/logger';

export interface BatchExpiryResult {
  expiredBatches: number;
  expiredInkOpenings: number;
  warningBatches: number;
  warningInkOpenings: number;
}

export class BatchExpiryScheduler {
  static async markExpiredBatches(): Promise<BatchExpiryResult> {
    const result: BatchExpiryResult = {
      expiredBatches: 0,
      expiredInkOpenings: 0,
      warningBatches: 0,
      warningInkOpenings: 0,
    };

    try {
      const batchResult = await execute(
        `UPDATE inv_inventory_batch
         SET status = 'expired'
         WHERE status = 'normal'
         AND expire_date IS NOT NULL
         AND expire_date < CURDATE()
         AND deleted = 0`
      );
      result.expiredBatches = batchResult.affectedRows || 0;

      if (result.expiredBatches > 0) {
        secureLog('info', 'Auto-marked expired inventory batches', {
          count: result.expiredBatches,
        });
      }
    } catch (error) {
      secureLog('error', 'Failed to mark expired inventory batches', {
        error: (error as Error)?.message,
      });
    }

    try {
      const inkResult = await execute(
        `UPDATE ink_opening_record
         SET status = 2
         WHERE status = 1
         AND expire_time < NOW()
         AND deleted = 0`
      );
      result.expiredInkOpenings = inkResult.affectedRows || 0;

      if (result.expiredInkOpenings > 0) {
        secureLog('info', 'Auto-marked expired ink opening records', {
          count: result.expiredInkOpenings,
        });
      }
    } catch (error) {
      secureLog('error', 'Failed to mark expired ink opening records', {
        error: (error as Error)?.message,
      });
    }

    try {
      const warningBatches = await query<any>(
        `SELECT id, batch_no, material_code, material_name, expire_date
         FROM inv_inventory_batch
         WHERE status = 'normal'
         AND expire_date IS NOT NULL
         AND expire_date >= CURDATE()
         AND expire_date <= DATE_ADD(CURDATE(), INTERVAL 7 DAY)
         AND deleted = 0`
      );
      result.warningBatches = warningBatches.length;

      if (result.warningBatches > 0) {
        secureLog('warn', 'Inventory batches expiring within 7 days', {
          count: result.warningBatches,
          batches: warningBatches.slice(0, 10).map((b) => ({
            id: b.id,
            batchNo: b.batch_no,
            materialCode: b.material_code,
            expireDate: b.expire_date,
          })),
        });
      }
    } catch (error) {
      secureLog('error', 'Failed to check batch expiry warnings', {
        error: (error as Error)?.message,
      });
    }

    try {
      const warningInk = await query<any>(
        `SELECT id, record_no, material_name, expire_time
         FROM ink_opening_record
         WHERE status = 1
         AND expire_time >= NOW()
         AND expire_time <= DATE_ADD(NOW(), INTERVAL 24 HOUR)
         AND deleted = 0`
      );
      result.warningInkOpenings = warningInk.length;

      if (result.warningInkOpenings > 0) {
        secureLog('warn', 'Ink openings expiring within 24 hours', {
          count: result.warningInkOpenings,
          records: warningInk.slice(0, 10).map((r) => ({
            id: r.id,
            recordNo: r.record_no,
            materialName: r.material_name,
            expireTime: r.expire_time,
          })),
        });
      }
    } catch (error) {
      secureLog('error', 'Failed to check ink expiry warnings', {
        error: (error as Error)?.message,
      });
    }

    return result;
  }
}

import { transaction, query } from '@/lib/db';
import { secureLog } from '@/lib/logger';

export type VoucherSource =
  | 'sales_outbound' // 销售出库
  | 'purchase_inbound' // 采购入库
  | 'production_inbound' // 生产入库
  | 'material_issue' // 生产领料
  | 'material_return' // 材料退回
  | 'stock_adjust' // 库存调整
  | 'cost_allocation'; // 成本分摊

export interface VoucherLine {
  debit_account: string; // 借方科目
  credit_account: string; // 贷方科目
  amount: number; // 金额
  description?: string; // 摘要
}

export interface VoucherData {
  voucher_no: string;
  voucher_date: string;
  source_type: VoucherSource;
  source_id: number;
  source_no: string;
  lines: VoucherLine[];
  total_amount: number;
  remark?: string;
  operator_id?: number;
  operator_name?: string;
}

export interface VoucherResult {
  success: boolean;
  voucher_id?: number;
  voucher_no?: string;
  error?: string;
}

const _VOUCHER_SOURCE_LABELS: Record<VoucherSource, string> = {
  sales_outbound: '销售出库',
  purchase_inbound: '采购入库',
  production_inbound: '生产入库',
  material_issue: '生产领料',
  material_return: '材料退回',
  stock_adjust: '库存调整',
  cost_allocation: '成本分摊',
};

export class FinanceVoucherHandler {
  static async generateSalesOutboundVoucher(
    outboundId: number,
    outboundNo: string,
    items: Array<{
      material_id: number;
      material_name: string;
      quantity: number;
      total_cost: number;
      avg_cost: number;
      batch_no?: string;
    }>,
    customerId?: number,
    customerName?: string,
    _warehouseId?: number
  ): Promise<VoucherResult> {
    try {
      const voucherNo = await this.generateVoucherNo('FV');
      const lines: VoucherLine[] = [];
      let totalAmount = 0;

      for (const item of items) {
        if (item.total_cost > 0) {
          lines.push({
            debit_account: '应收账款',
            credit_account: '成品库存',
            amount: item.total_cost,
            description: `${outboundNo} - ${item.material_name} × ${item.quantity}`,
          });
          totalAmount += item.total_cost;
        }
      }

      if (lines.length === 0) {
        return { success: false, error: '无有效凭证行项' };
      }

      return await this.createVoucher({
        voucher_no: voucherNo,
        voucher_date: new Date().toISOString().split('T')[0],
        source_type: 'sales_outbound',
        source_id: outboundId,
        source_no: outboundNo,
        lines,
        total_amount: totalAmount,
        remark: `销售出库 - ${customerName || ''}`,
      });
    } catch (error) {
      secureLog('error', '生成销售出库凭证失败', { error: (error as Error).message, outboundId });
      return { success: false, error: (error as Error).message };
    }
  }

  static async generatePurchaseInboundVoucher(
    inboundId: number,
    inboundNo: string,
    items: Array<{
      material_id: number;
      material_name: string;
      quantity: number;
      unit_price: number;
      total_amount: number;
    }>,
    supplierId?: number,
    supplierName?: string
  ): Promise<VoucherResult> {
    try {
      const voucherNo = await this.generateVoucherNo('FV');
      const lines: VoucherLine[] = [];
      let totalAmount = 0;

      for (const item of items) {
        if (item.total_amount > 0) {
          lines.push({
            debit_account: '原材料库存',
            credit_account: '应付账款',
            amount: item.total_amount,
            description: `${inboundNo} - ${item.material_name} × ${item.quantity}`,
          });
          totalAmount += item.total_amount;
        }
      }

      if (lines.length === 0) {
        return { success: false, error: '无有效凭证行项' };
      }

      return await this.createVoucher({
        voucher_no: voucherNo,
        voucher_date: new Date().toISOString().split('T')[0],
        source_type: 'purchase_inbound',
        source_id: inboundId,
        source_no: inboundNo,
        lines,
        total_amount: totalAmount,
        remark: `采购入库 - ${supplierName || ''}`,
      });
    } catch (error) {
      secureLog('error', '生成采购入库凭证失败', { error: (error as Error).message, inboundId });
      return { success: false, error: (error as Error).message };
    }
  }

  static async generateProductionInboundVoucher(
    inboundId: number,
    inboundNo: string,
    workOrderId: number,
    workOrderNo: string,
    items: Array<{
      product_id: number;
      product_name: string;
      quantity: number;
      standard_cost: number;
      actual_cost: number;
    }>
  ): Promise<VoucherResult> {
    try {
      const voucherNo = await this.generateVoucherNo('FV');
      const lines: VoucherLine[] = [];
      let totalStandardCost = 0;
      let totalActualCost = 0;

      for (const item of items) {
        if (item.actual_cost > 0) {
          lines.push({
            debit_account: '成品库存',
            credit_account: '生产成本',
            amount: item.actual_cost,
            description: `${workOrderNo} - ${item.product_name} × ${item.quantity}`,
          });
          totalStandardCost += item.standard_cost * item.quantity;
          totalActualCost += item.actual_cost;
        }
      }

      if (totalActualCost > totalStandardCost && totalStandardCost > 0) {
        const variance = totalActualCost - totalStandardCost;
        lines.push({
          debit_account: '成本差异',
          credit_account: '生产成本',
          amount: variance,
          description: `${workOrderNo} - 成本超支差异`,
        });
      }

      if (lines.length === 0) {
        return { success: false, error: '无有效凭证行项' };
      }

      return await this.createVoucher({
        voucher_no: voucherNo,
        voucher_date: new Date().toISOString().split('T')[0],
        source_type: 'production_inbound',
        source_id: inboundId,
        source_no: inboundNo,
        lines,
        total_amount: totalActualCost,
        remark: `生产入库 - 工单${workOrderNo}`,
      });
    } catch (error) {
      secureLog('error', '生成生产入库凭证失败', { error: (error as Error).message, inboundId });
      return { success: false, error: (error as Error).message };
    }
  }

  static async generateMaterialIssueVoucher(
    issueId: number,
    issueNo: string,
    workOrderId: number,
    workOrderNo: string,
    items: Array<{
      material_id: number;
      material_name: string;
