    } catch (error) {
      secureLog('error', '生成领料凭证失败', { error: (error as Error).message, issueId });
      return { success: false, error: (error as Error).message };
    }
  }

  private static async createVoucher(data: VoucherData): Promise<VoucherResult> {
    return await transaction(async (conn) => {
      const [existing]: Loose = await conn.execute(
        `SELECT id FROM fin_voucher WHERE source_type = ? AND source_id = ? AND deleted = 0`,
        [data.source_type, data.source_id]
      );

      if (existing && existing.length > 0) {
        return {
          success: false,
          error: `该业务已存在凭证（ID: ${existing[0].id}），请勿重复生成`,
        };
      }

      const [result]: Loose = await conn.execute(
        `INSERT INTO fin_voucher (
          voucher_no, voucher_date, source_type, source_id, source_no,
          total_amount, status, remark, create_time
        ) VALUES (?, ?, ?, ?, ?, ?, 1, ?, NOW())`,
        [
          data.voucher_no,
          data.voucher_date,
          data.source_type,
          data.source_id,
          data.source_no,
          data.total_amount,
          data.remark || '',
        ]
      );

      const voucherId = result.insertId;

      for (let i = 0; i < data.lines.length; i++) {
        const line = data.lines[i];
        await conn.execute(
          `INSERT INTO fin_voucher_line (
            voucher_id, line_no, debit_account, credit_account, 
            amount, description, create_time
          ) VALUES (?, ?, ?, ?, ?, ?, NOW())`,
          [
            voucherId,
            i + 1,
            line.debit_account,
            line.credit_account,
            line.amount,
            line.description || '',
          ]
        );
      }

      secureLog('info', '财务凭证生成成功', {
        voucherId,
        voucherNo: data.voucher_no,
        sourceType: data.source_type,
        sourceId: data.source_id,
        totalAmount: data.total_amount,
        lineCount: data.lines.length,
      });

      return {
        success: true,
        voucher_id: voucherId,
        voucher_no: data.voucher_no,
      };
    });
  }

  private static async generateVoucherNo(prefix: string): Promise<string> {
    const today = new Date();
    const dateStr =
      today.getFullYear().toString() +
      String(today.getMonth() + 1).padStart(2, '0') +
      String(today.getDate()).padStart(2, '0');

    const [rows]: Loose = await query(
      `SELECT COALESCE(MAX(CAST(SUBSTRING(voucher_no, 9) AS UNSIGNED)), 0) as max_no 
       FROM fin_voucher WHERE voucher_no LIKE ?`,
      [`${prefix}${dateStr}%`]
    );

    const nextNo = (rows[0]?.max_no || 0) + 1;
    return `${prefix}${dateStr}${String(nextNo).padStart(4, '0')}`;
  }

  static async getVouchersBySource(sourceType: VoucherSource, sourceId: number): Promise<Loose[]> {
    const rows: Loose = await query(
      `SELECT v.*, 
              GROUP_CONCAT(
                CONCAT(
                  vl.line_no, '|', 
                  vl.debit_account, '|', 
                  vl.credit_account, '|', 
                  vl.amount, '|',
                  COALESCE(vl.description, '')
                ) 
                SEPARATOR ';;'
              ) as lines_data
       FROM fin_voucher v
       LEFT JOIN fin_voucher_line vl ON v.id = vl.voucher_id
       WHERE v.source_type = ? AND v.source_id = ? AND v.deleted = 0
       GROUP BY v.id
       ORDER BY v.create_time DESC`,
      [sourceType, sourceId]
    );

    return rows.map((row: Loose) => ({
      ...row,
      lines: row.lines_data
        ? row.lines_data.split(';;').map((lineStr: string) => {
            const parts = lineStr.split('|');
            return {
              line_no: parseInt(parts[0]),
              debit_account: parts[1],
              credit_account: parts[2],
              amount: parseFloat(parts[3]),
              description: parts[4] || '',
            };
          })
        : [],
      lines_data: undefined,
    }));
  }

  static async reverseVoucher(
    voucherId: number,
    reason: string,
    _operatorName: string
  ): Promise<VoucherResult> {
    try {
      const [voucherRows]: Loose = await query(
        `SELECT * FROM fin_voucher WHERE id = ? AND deleted = 0`,
        [voucherId]
      );

      if (!voucherRows || voucherRows.length === 0) {
        return { success: false, error: '凭证不存在' };
      }

      const voucher = voucherRows[0];
      if (voucher.status === 3) {
        return { success: false, error: '凭证已审核，无法冲销' };
      }

      const [lineRows]: Loose = await query(`SELECT * FROM fin_voucher_line WHERE voucher_id = ?`, [
        voucherId,
      ]);

      const reversedLines: VoucherLine[] = lineRows.map((line: Loose) => ({
        debit_account: line.credit_account,
        credit_account: line.debit_account,
        amount: line.amount,
        description: `冲销原凭证${voucher.voucher_no}: ${line.description || ''}`,
      }));

      const reverseVoucherNo = await this.generateVoucherNo('RV');

      return await this.createVoucher({
        voucher_no: reverseVoucherNo,
        voucher_date: new Date().toISOString().split('T')[0],
        source_type: voucher.source_type as VoucherSource,
        source_id: voucher.source_id,
        source_no: `${voucher.source_no}[冲销]`,
        lines: reversedLines,
        total_amount: voucher.total_amount,
        remark: `冲销原凭证${voucher.voucher_no} - 原因：${reason}`,
      });
    } catch (error) {
      secureLog('error', '冲销凭证失败', { error: (error as Error).message, voucherId });
      return { success: false, error: (error as Error).message };
    }
  }
}

/**
 * @module api-auth
 * @description API 路由认证辅助模块，提供 Token 验证、权限检查、资源访问控制等核心认证功能，
 * 以及 `withAuth`、`withAuthAndErrorHandler` 等高阶包装器，用于在 Next.js API 路由中
 * 统一处理认证、权限和错误处理逻辑。
 */
import { NextRequest, NextResponse } from 'next/server';
import {
  extractToken,
  verifyToken,
  getUserInfo,
  hasPermission,
  validateResourceAccess,
  UserInfo,
} from './auth';
import { errorResponse } from './api-response';
import { isTokenRevoked, isUserTokensRevoked } from './token-blacklist';

/** 用户信息类型，从 auth 模块 re-export 以方便外部直接引用 */
export type { UserInfo } from './auth';

/** Next.js 动态路由上下文类型（替代 any） */
export interface RouteContext {
  params: Promise<Record<string, string>>;
}

/**
 * 路由处理器上下文类型
 *
 * 保留 any 以兼容调用方对动态路由参数的解构，例如：
 * `(request, userInfo, { params }: { params: Promise<{ id: string }> }) => ...`
 * 调用方可显式使用 `RouteContext` 替代 any 以获得更严格的类型检查。
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type RouteHandlerContext = any;

/**
 * 首次登录强制改密白名单
 *
 * 用户首次登录（firstLogin=true）时，系统会拦截所有 API 请求并返回 403，
 * 仅允许白名单中的路由正常访问。白名单包含修改密码、登出、获取用户信息、刷新令牌等
 * 必须在首次登录状态下可执行的操作。
 */
export const FIRST_LOGIN_WHITELIST = [
  '/api/auth/change-password',
  '/api/auth/logout',
  '/api/auth/user-info',
  '/api/auth/refresh',
];

/**
 * 检查首次登录状态并拦截非白名单请求
 *
 * 当用户处于首次登录状态（userInfo.firstLogin=true）时，除白名单路由外
 * 所有 API 请求将被拦截，返回 403 状态码和 `passwordExpired: true` 标记，
 * 强制用户先修改密码后才能正常使用系统。
 *
 * @param request - Next.js 请求对象，用于获取请求路径
 * @param userInfo - 当前用户信息，包含 firstLogin 标记
 * @returns 若需要拦截则返回 403 响应，否则返回 null 表示无需拦截
 */
function checkFirstLogin(request: NextRequest, userInfo: UserInfo): NextResponse | null {
  if (userInfo.firstLogin) {
    const { pathname } = new URL(request.url);
    if (!FIRST_LOGIN_WHITELIST.some((p) => pathname.startsWith(p))) {
      return NextResponse.json(
        {
          code: 403,
          success: false,
          message: '无权限访问',
          data: null,
          passwordExpired: true,
        },
        { status: 403 }
      );
    }
  }
  return null;
}

/**
 * 需要认证的 API 路由包装器
 *
 * 对 Next.js API 路由处理器进行认证包装，依次执行以下流程：
 * 1. 提取并验证 Token → 2. 检查 Token 黑名单 → 3. 检查用户级 Token 撤销 →
 * 4. 获取用户完整信息 → 5. 首次登录改密拦截 → 6. 权限检查（可选）→
 * 7. 资源访问权限检查（可选，防止横向越权）→ 8. 执行业务处理器
 *
 * 不包含 try/catch 错误处理，若业务处理器抛出异常将直接向上传播。
 * 如需自动错误捕获，请使用 `withAuthAndErrorHandler`。
 *
 * @param handler - 业务处理器函数，接收认证后的请求、用户信息和上下文
 * @param options - 可选配置
 * @param options.permission - 需要检查的权限标识，如 `'warehouse:view'`
 * @param options.resourceType - 资源类型，用于资源级访问控制，支持 `'order'`、`'workorder'`、`'inbound'`、`'outbound'`
 * @param options.resourceIdParam - 资源 ID 的 URL 查询参数名，与 resourceType 配合使用防止横向越权
 * @returns 包装后的 Next.js API 路由处理函数
 */
export function withAuth(
  handler: (
    request: NextRequest,
    userInfo: UserInfo,
    context?: RouteHandlerContext
  ) => Promise<NextResponse>,
  options?: {
    permission?: string;
    resourceType?: 'order' | 'workorder' | 'inbound' | 'outbound';
    resourceIdParam?: string;
  }
) {
  return async (request: NextRequest, context?: RouteHandlerContext): Promise<NextResponse> => {
    // 1. 提取Token
    const token = extractToken(request);
    if (!token) {
      return errorResponse('未提供认证令牌', 401);
    }

    // 2. 验证Token
    const tokenPayload = await verifyToken(token);
    if (!tokenPayload) {
      return errorResponse('认证令牌无效或已过期', 401);
    }

    // 2.5 检查Token是否已被撤销（黑名单）
    const tokenKey = `token:${tokenPayload.userId}:${token.slice(-20)}`;
    if (await isTokenRevoked(tokenKey)) {
      return errorResponse('认证令牌已失效，请重新登录', 401);
    }

    // 2.6 检查用户级 token 撤销（修改密码/账号锁定后旧 token 立即失效）
    if (tokenPayload.iat && (await isUserTokensRevoked(tokenPayload.userId, tokenPayload.iat))) {
      return errorResponse('登录状态已失效（账号已变更），请重新登录', 401);
    }

    // 3. 获取用户完整信息
    const userInfo = await getUserInfo(tokenPayload.userId);
    if (!userInfo) {
      return errorResponse('用户不存在或已被禁用', 401);
    }

    // 3.5 首次登录强制改密检查
    const firstLoginResponse = checkFirstLogin(request, userInfo);
    if (firstLoginResponse) return firstLoginResponse;

    // 4. 检查权限
    if (options?.permission && !hasPermission(userInfo, options.permission)) {
      return errorResponse('没有权限执行此操作', 403);
    }

    // 5. 检查资源访问权限（防止横向越权）
    if (options?.resourceType && options?.resourceIdParam) {
      const { searchParams } = new URL(request.url);
      const resourceId = searchParams.get(options.resourceIdParam);

      if (resourceId) {
        const hasAccess = await validateResourceAccess(userInfo, options.resourceType, resourceId);
        if (!hasAccess) {
          return errorResponse('没有权限访问此资源', 403);
        }
      }
    }

    // 6. 执行处理器
    return handler(request, userInfo, context);
  };
}

/**
 * 带认证和错误处理的 API 路由包装器
 *
 * 在 `withAuth` 的基础上增加了 try/catch 全局错误捕获，是 `withPermission` 的底层依赖。
 * 通过委托 `withAuth` 完成认证流程，避免逻辑重复（DRY）。
 *
 * 适用于需要认证且希望自动处理运行时异常的 API 路由。
 *
 * @param handler - 业务处理器函数，接收认证后的请求、用户信息和上下文
 * @param options - 可选配置
 * @param options.permission - 需要检查的权限标识
 * @param options.resourceType - 资源类型，用于资源级访问控制
 * @param options.resourceIdParam - 资源 ID 的 URL 查询参数名
 * @param options.errorMessage - 自定义的服务端错误提示消息，默认为 `'服务器内部错误'`
 * @returns 包装后的 Next.js API 路由处理函数，内部包含 try/catch 错误捕获
 */
export function withAuthAndErrorHandler(
  handler: (
    request: NextRequest,
    userInfo: UserInfo,
    context?: RouteHandlerContext
  ) => Promise<NextResponse>,
  options?: {
    permission?: string;
    resourceType?: 'order' | 'workorder' | 'inbound' | 'outbound';
    resourceIdParam?: string;
    errorMessage?: string;
  }
) {
  const authedHandler = withAuth(handler, options);
  return async (request: NextRequest, context?: RouteHandlerContext): Promise<NextResponse> => {
    try {
      return await authedHandler(request, context);
    } catch (error) {
      console.error(`[API Error] ${options?.errorMessage || '请求处理失败'}:`, error);
      return errorResponse(options?.errorMessage || '服务器内部错误', 500);
    }
  };
}

/**
 * 中间件形式的认证检查（用于 Next.js Middleware）
 *
 * 在 Next.js 中间件层进行轻量级认证验证，仅提取 Token 并验证后返回用户信息。
 * 不执行权限检查、资源访问控制或首次登录拦截，仅确认请求是否携带有效认证信息。
 * 适用于中间件层的路由守卫和预检查场景。
 *
 * @param request - Next.js 中间件请求对象
 * @returns 用户信息对象（认证有效时）或 null（无 Token 或 Token 无效时）
 */
export async function middlewareAuth(request: NextRequest): Promise<UserInfo | null> {
  const token = extractToken(request);
  if (!token) {
    return null;
  }

  const tokenPayload = await verifyToken(token);
  if (!tokenPayload) {
    return null;
  }

  return await getUserInfo(tokenPayload.userId);
}

'use client';

import { authFetch } from '@/lib/auth-fetch';

const API_BASE = '';

/**
 * 统一的API请求客户端，委托 authFetch 处理认证令牌、CSRF 和 401 无感刷新
 */
export class ApiClient {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  static async get<T = any>(url: string, params?: Record<string, string | number | boolean | null | undefined>): Promise<T> {
    const queryString = params
      ? '?' +
        new URLSearchParams(
          Object.entries(params)
            .filter(([, v]) => v != null)
            .map(([k, v]) => [k, String(v)])
        ).toString()
      : '';

    const response = await authFetch(`${API_BASE}${url}${queryString}`, {
      method: 'GET',
      credentials: 'include',
    });

    return this.handleResponse<T>(response);
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  static async post<T = any>(url: string, data?: unknown): Promise<T> {
    const response = await authFetch(`${API_BASE}${url}`, {
      method: 'POST',
      body: data ? JSON.stringify(data) : undefined,
      credentials: 'include',
    });

    return this.handleResponse<T>(response);
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  static async put<T = any>(url: string, data?: unknown): Promise<T> {
    const response = await authFetch(`${API_BASE}${url}`, {
      method: 'PUT',
      body: data ? JSON.stringify(data) : undefined,
      credentials: 'include',
    });

    return this.handleResponse<T>(response);
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  static async delete<T = any>(url: string, params?: Record<string, string | number | boolean | null | undefined>): Promise<T> {
    const queryString = params
      ? '?' + new URLSearchParams(
        Object.entries(params)
          .filter(([, v]) => v != null)
          .map(([k, v]) => [k, String(v)])
      ).toString()
      : '';

    const response = await authFetch(`${API_BASE}${url}${queryString}`, {
      method: 'DELETE',
      credentials: 'include',
    });

    return this.handleResponse<T>(response);
  }

  private static async handleResponse<T>(response: Response): Promise<T> {
    if (!response.ok) {
      if (response.status === 401) {
        // authFetch 刷新失败已触发 clearAuthAndRedirect，此处仅抛错中断调用方
        throw new Error('未登录或登录已过期');
      }

      let errorMsg = `请求失败: ${response.status}`;
      try {
        const errorData = await response.json();
        if (errorData.message) {
          errorMsg = errorData.message;
        }
      } catch {
        // 解析失败时用默认消息
      }
      throw new Error(errorMsg);
    }

    const contentType = response.headers.get('content-type');
    if (contentType && contentType.includes('application/json')) {
      return await response.json();
    }

    return null as T;
  }
}

export default ApiClient;

import { NextRequest, NextResponse } from 'next/server';
import { execute } from '@/lib/db';

export function sanitizeInput(input: string): string {
  return input
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

export function sanitizeObject<T>(obj: T): T {
  if (typeof obj === 'string') return sanitizeInput(obj) as T;
  if (obj instanceof Date) return (obj as Date).toISOString().slice(0, 10) as T;
  if (Array.isArray(obj)) return obj.map((item) => sanitizeObject(item)) as T;
  if (obj && typeof obj === 'object') {
    const sanitized: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(obj as Record<string, unknown>)) {
      sanitized[key] = sanitizeObject(value);
    }
    return sanitized as T;
  }
  return obj;
}

export interface ApiResponse<T = unknown> {
  code: number;
  success: boolean;
  message: string;
  data: T | null;
}

export interface PaginatedResponse<T = unknown> extends ApiResponse<{
  list: T[];
  total: number;
  page: number;
  pageSize: number;
}> {
  pagination: {
    page: number;
    pageSize: number;
    total: number;
    totalPages: number;
  };
}

export function successResponse<T>(
  data: T,
  message = '操作成功',
  code = 200
): NextResponse<ApiResponse<T>> {
  return NextResponse.json({
    code,
    success: true,
    message,
    data: sanitizeObject(data),
  });
}

export function paginatedResponse<T>(
  data: T[],
  pagination: { page: number; pageSize: number; total: number; totalPages: number },
  message = '查询成功'
): NextResponse<PaginatedResponse<T>> {
  return NextResponse.json({
    code: 200,
    success: true,
    message,
    data: {
      list: sanitizeObject(data),
      total: pagination.total,
      page: pagination.page,
      pageSize: pagination.pageSize,
    },
    pagination,
  });
}

export function errorResponse(
  message: string,
  code = 500,
  statusCode: number = code
): NextResponse<ApiResponse<null>> {
  return NextResponse.json(
    {
      code,
      success: false,
      message: sanitizeInput(message),
      data: null,
    },
    { status: statusCode }
  );
}

// 常见错误响应快捷方法
export const commonErrors = {
  unauthorized: (message = '未授权，请先登录') => errorResponse(message, 401, 401),
  forbidden: (message = '无权访问该资源') => errorResponse(message, 403, 403),
  notFound: (message = '资源不存在') => errorResponse(message, 404, 404),
  badRequest: (message = '请求参数错误') => errorResponse(message, 400, 400),
  conflict: (message = '资源冲突') => errorResponse(message, 409, 409),
  validationError: (message = '数据验证失败') => errorResponse(message, 422, 422),
  serverError: (message = '服务器内部错误') => errorResponse(message, 500, 500),
};

// 统一的API错误处理包装器
export function withErrorHandler<T extends (...args: unknown[]) => Promise<NextResponse>>(
  handler: T,
  errorMessage = '操作失败'
): T {
  return (async (...args: Parameters<T>): Promise<NextResponse> => {
    try {
      return await handler(...args);
    } catch (error) {
      // 生产环境不向客户端泄露底层异常信息（可能含 SQL/表结构等敏感细节）
      const message =
        process.env.NODE_ENV === 'production'
          ? errorMessage
          : error instanceof Error
            ? error.message
            : errorMessage;
      if (error instanceof Error) {
        console.error('[withErrorHandler]', error);
      }
      return errorResponse(message, 500, 500);
    }
  }) as T;
}

// 验证请求体
export function validateRequestBody<T extends object>(
  body: T,
  requiredFields: string[]
): { valid: boolean; missing: string[] } {
  const obj = body as Record<string, unknown>;
  const missing = requiredFields.filter((field) => {
    const value = obj[field];
    return value === undefined || value === null || value === '';
  });

  return {
    valid: missing.length === 0,
    missing,
  };
}

export async function logOperation(params: {
  title: string;
  oper_name?: string;
  oper_type: string;
  oper_method: string;
  oper_url: string;
  oper_ip?: string;
  oper_param?: string;
  oper_result?: string;
  status?: number;
}) {
  try {
    await execute(
      `INSERT INTO sys_operation_log (title, oper_name, oper_type, oper_method, oper_url, oper_ip, oper_param, oper_result, status)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        params.title,
