        params.oper_type,
        params.oper_method,
        params.oper_url,
        params.oper_ip || '',
        params.oper_param ? params.oper_param.substring(0, 2000) : null,
        params.oper_result ? params.oper_result.substring(0, 2000) : null,
        params.status ?? 1,
      ]
    );
  } catch {}
}

