/**
 * 生成审计报告数据
 */
export async function generateAuditReport(params: {
  startTime: string;
  endTime: string;
  module?: string;
}): Promise<{
  summary: {
    totalOperations: number;
    successCount: number;
    failCount: number;
    avgDuration: number;
    uniqueUsers: number;
  };
  moduleStats: Record<string, unknown>[];
  typeStats: Record<string, unknown>[];
  userStats: Record<string, unknown>[];
  dailyStats: Record<string, unknown>[];
}> {
  const { startTime, endTime, module } = params;

  let where = 'WHERE create_time >= ? AND create_time <= ?';
  const queryParams: SqlValue[] = [startTime, endTime];

  if (module) {
    where += ' AND module = ?';
    queryParams.push(module);
  }

  // 汇总统计
  const summaryRows = await query<{
    total_operations: number;
    success_count: number;
    fail_count: number;
    avg_duration: number;
    unique_users: number;
  }>(
    `SELECT
      COUNT(*) as total_operations,
      SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END) as success_count,
      SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END) as fail_count,
      AVG(duration_ms) as avg_duration,
      COUNT(DISTINCT user_id) as unique_users
    FROM sys_operate_log ${where}`,
    queryParams
  );

  const summary = summaryRows[0];

  // 模块统计
  const moduleStats = await query<Record<string, unknown>>(
    `SELECT
      module,
      COUNT(*) as count,
      SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END) as success,
      SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END) as fail
    FROM sys_operate_log ${where}
    GROUP BY module
    ORDER BY count DESC`,
    queryParams
  );

  // 类型统计
  const typeStats = await query<Record<string, unknown>>(
    `SELECT
      type,
      COUNT(*) as count,
      SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END) as success,
      SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END) as fail
    FROM sys_operate_log ${where}
    GROUP BY type
    ORDER BY count DESC`,
    queryParams
  );

  // 用户统计
  const userStats = await query<Record<string, unknown>>(
    `SELECT
      username,
      COUNT(*) as count,
      SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END) as success,
      SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END) as fail
    FROM sys_operate_log ${where}
    GROUP BY username
    ORDER BY count DESC
    LIMIT 20`,
    queryParams
  );

  // 每日统计
  const dailyStats = await query<Record<string, unknown>>(
    `SELECT
      DATE(create_time) as date,
      COUNT(*) as count,
      SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END) as success,
      SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END) as fail
    FROM sys_operate_log ${where}
    GROUP BY DATE(create_time)
    ORDER BY date`,
    queryParams
  );

  return {
    summary: {
      totalOperations: summary.total_operations || 0,
      successCount: summary.success_count || 0,
      failCount: summary.fail_count || 0,
      avgDuration: Math.round(summary.avg_duration || 0),
      uniqueUsers: summary.unique_users || 0,
    },
    moduleStats,
    typeStats,
    userStats,
    dailyStats,
  };
}

/**
 * VNERP API审计中间件
 * 功能：自动拦截所有API请求，记录操作日志
 * 使用方式：在API路由中使用 withAudit 包装处理器
 */

import { NextRequest, NextResponse } from 'next/server';
import { logOperation, setAuditUserContext, clearAuditUserContext } from '@/lib/audit-logger';
import { maskSensitiveData } from '@/lib/logger';

// ============================================================
// 模块映射（根据URL路径自动识别模块）
// ============================================================

const MODULE_MAPPING: Record<string, string> = {
  '/api/purchase': '采购管理',
  '/api/sales': '销售管理',
  '/api/warehouse': '库存管理',
  '/api/production': '生产管理',
  '/api/finance': '财务管理',
  '/api/quality': '质量管理',
  '/api/dcprint': '印前管理',
  '/api/hr': '人事管理',
  '/api/system': '系统管理',
  '/api/report': '报表中心',
  '/api/dashboard': '数据看板',
};

// ============================================================
// 操作类型映射（根据HTTP方法自动识别）
// ============================================================

const METHOD_TYPE_MAPPING: Record<string, string> = {
  GET: '查询',
  POST: '新增',
  PUT: '修改',
  PATCH: '修改',
  DELETE: '删除',
};

// ============================================================
// 需要记录详细请求/响应的模块（白名单）
// ============================================================

const DETAIL_LOG_MODULES = ['采购管理', '销售管理', '库存管理', '生产管理', '财务管理'];

// ============================================================
// 辅助函数
// ============================================================

function getModuleFromUrl(url: string): string {
  for (const [prefix, module] of Object.entries(MODULE_MAPPING)) {
    if (url.includes(prefix)) return module;
  }
  return '系统管理';
}

function getOperationType(method: string, url: string): string {
  // 根据URL中的action参数判断特殊操作
  if (url.includes('action=audit')) return '审核';
  if (url.includes('action=cancel')) return '作废';
  if (url.includes('action=approve')) return '审核';
  if (url.includes('action=reject')) return '反审';
  if (url.includes('action=import')) return '导入';
  if (url.includes('action=export')) return '导出';
  if (url.includes('action=print')) return '打印';
  if (url.includes('action=submit')) return '提交';

  return METHOD_TYPE_MAPPING[method] || method;
}

function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) return forwarded.split(',')[0].trim();

  const realIp = request.headers.get('x-real-ip');
  if (realIp) return realIp;

  return 'unknown';
}

function _truncateString(str: string, maxLength: number = 1000): string {
  if (!str || str.length <= maxLength) return str;
  return str.substring(0, maxLength) + '... [truncated]';
}

async function parseRequestBody(request: NextRequest): Promise<unknown> {
  try {
    const clonedRequest = request.clone();
    const contentType = request.headers.get('content-type') || '';

    if (contentType.includes('application/json')) {
      return await clonedRequest.json();
    }

    if (
      contentType.includes('application/x-www-form-urlencoded') ||
      contentType.includes('multipart/form-data')
    ) {
      const formData = await clonedRequest.formData();
      const obj: Record<string, unknown> = {};
      formData.forEach((value, key) => {
        obj[key] = value;
      });
      return obj;
    }

    return null;
  } catch {
    return null;
  }
}

// ============================================================
// 核心中间件函数
// ============================================================

export interface AuditOptions {
  module?: string;
  type?: string;
  title?: string;
  skipRequestBody?: boolean;
  skipResponseBody?: boolean;
  customContent?: string;
}

/**
 * 带审计日志的API处理器包装器
 * @param handler 原始API处理器
 * @param options 审计选项
 */
export function withAudit(
  handler: (request: NextRequest) => Promise<NextResponse>,
  options?: AuditOptions
) {
  return async (request: NextRequest): Promise<NextResponse> => {
    const startTime = Date.now();
    const url = request.url;
    const method = request.method;
    const moduleName = options?.module || getModuleFromUrl(url);
    const type = options?.type || getOperationType(method, url);

    // 设置用户上下文（从请求头或token中获取）
    const userId = request.headers.get('x-user-id');
    const username = request.headers.get('x-username');
    const ip = getClientIp(request);
    const userAgent = request.headers.get('user-agent') || 'unknown';

    setAuditUserContext(userId ? Number(userId) : undefined, username || undefined, ip, userAgent);

    // 解析请求参数
    let requestParam: unknown = null;
    if (!options?.skipRequestBody && ['POST', 'PUT', 'PATCH'].includes(method)) {
      requestParam = await parseRequestBody(request);
    }

    // 从URL查询参数中提取
    const { searchParams } = new URL(url);
    const queryParams: Record<string, string> = {};
    searchParams.forEach((value, key) => {
      queryParams[key] = value;
    });

    if (Object.keys(queryParams).length > 0 && !requestParam) {
      requestParam = queryParams;
    }

    let response: NextResponse;
    let responseData: unknown = null;
    let errorMsg = '';
    let status = 1;

    try {
      // 执行原始处理器
      response = await handler(request);

      // 尝试解析响应数据
      if (!options?.skipResponseBody) {
        try {
          const clonedResponse = response.clone();
          responseData = await clonedResponse.json();
        } catch {
          // 响应不是JSON格式，忽略
        }
      }

      // 判断操作是否成功
      if (responseData && typeof responseData === 'object') {
        const resp = responseData as { code?: number; message?: string; msg?: string };
        if (resp.code !== undefined && resp.code !== 200 && resp.code !== 0) {
          status = 0;
          errorMsg = resp.message || resp.msg || '操作失败';
        }
      }

      if (response.status >= 400) {
        status = 0;
      }
    } catch (error: unknown) {
      status = 0;
      errorMsg = error instanceof Error ? error.message : '服务器内部错误';

      // 重新抛出错误，让上层错误处理器处理
      throw error;
    } finally {
      const duration = Date.now() - startTime;

      // 只对关键操作记录详细日志
      const shouldLogDetail =
        DETAIL_LOG_MODULES.includes(moduleName) ||
        ['POST', 'PUT', 'DELETE', 'PATCH'].includes(method);

      if (shouldLogDetail) {
        await logOperation(
          {
            module: moduleName,
            type,
            title: options?.title || `${method} ${url.split('?')[0]}`,
            content: options?.customContent || `${moduleName} - ${type}操作`,
            requestUrl: url.split('?')[0],
            requestMethod: method,
            requestParam: requestParam ? maskSensitiveData(requestParam) : null,
            responseResult: responseData ? maskSensitiveData(responseData) : null,
            status,
            errorMsg,
            durationMs: duration,
          },
          request
        );
      }

      // 清除用户上下文
      clearAuditUserContext();
    }

    return response;
  };
}

/**
 * 简化的审计包装器（只记录关键信息）
 */
export function withAuditSimple(
  handler: (request: NextRequest) => Promise<NextResponse>,
  module: string,
  type: string,
  title?: string
) {
  return withAudit(handler, {
    module,
    type,
    title,
    skipRequestBody: true,
    skipResponseBody: true,
  });
}

// ============================================================
// 装饰器风格（用于类方法）
// ============================================================

/**
 * 审计日志装饰器（用于API路由中的特定方法）
 * 使用示例：
 * export const POST = auditRoute('采购管理', '新增采购单')(async (request) => { ... });
 */
export function auditRoute(module: string, type: string, title?: string) {
  return (handler: (request: NextRequest) => Promise<NextResponse>) => {
    return withAudit(handler, { module, type, title });
  };
}

// ============================================================
// 便捷方法：记录特定业务操作
// ============================================================

/**
 * 记录业务操作（手动调用）
 */
export async function recordBusinessOperation(
  request: NextRequest,
  module: string,
  type: string,
  content: string,
  data?: {
    beforeData?: Record<string, unknown>;
    afterData?: Record<string, unknown>;
