  );
}

/**
 * authFetch: 带认证令牌的 fetch 封装
 *
 * 401 无感刷新机制：
 * - 首个 401 触发 refresh，并发 401 复用同一 Promise（避免多次 refresh 互相覆盖）
 * - 刷新成功：更新本地 token 并重试原请求一次
 * - 刷新失败/无 refreshToken：清除登录态并跳转登录页
 *
 * 注意：refresh 请求本身不走 authFetch（避免死循环），直接用裸 fetch
 */

let refreshPromise: Promise<string | null> | null = null;

async function refreshAccessToken(): Promise<string | null> {
  if (refreshPromise) {
    return refreshPromise;
  }

  const refreshToken =
    localStorage.getItem('refreshToken') || sessionStorage.getItem('refreshToken');
  const userId = localStorage.getItem('userId') || sessionStorage.getItem('userId');
  if (!refreshToken || !userId) {
    return null;
  }

  const _startTime = Date.now();

  refreshPromise = (async () => {
    try {
      const res = await fetch('/api/auth/refresh', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ refreshToken, userId }),
      });
      if (!res.ok) {
        return null;
      }
      const json = await res.json();
      if (!json.success || !json.data?.token) {
        return null;
      }

      // Sync write to the storage where token originally lives (localStorage first, fallback sessionStorage)
      const useSession = !localStorage.getItem('token') && !!sessionStorage.getItem('token');
      const storage = useSession ? sessionStorage : localStorage;
      storage.setItem('token', json.data.token);
      if (json.data.refreshToken) {
        storage.setItem('refreshToken', json.data.refreshToken);
      }
      return json.data.token as string;
    } catch {
      return null;
    } finally {
      refreshPromise = null;
    }
  })();

  return refreshPromise;
}

function clearAuthAndRedirect(): void {
  localStorage.removeItem('token');
  localStorage.removeItem('refreshToken');
  localStorage.removeItem('userId');
  sessionStorage.removeItem('token');
  sessionStorage.removeItem('refreshToken');
  sessionStorage.removeItem('userId');
  if (typeof window !== 'undefined' && !window.location.pathname.endsWith('/login')) {
    window.location.href = '/login';
  }
}

export async function authFetch(url: string, options: RequestInit = {}): Promise<Response> {
  const token =
    typeof window !== 'undefined'
      ? localStorage.getItem('token') || sessionStorage.getItem('token')
      : null;

  // FormData 上传时不能手动设置 Content-Type，浏览器需自动生成 multipart boundary
  const isFormData = typeof FormData !== 'undefined' && options.body instanceof FormData;

  const headers: Record<string, string> = {
    ...(isFormData ? {} : { 'Content-Type': 'application/json' }),
    ...(options.headers as Record<string, string>),
  };

  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  // CSRF token：非安全方法需附带 X-CSRF-Token header（与 cookie 双重提交校验）
  if (typeof document !== 'undefined') {
    const csrfMatch = document.cookie.match(/(^| )csrf_token=([^;]+)/);
    if (csrfMatch) {
      headers['X-CSRF-Token'] = csrfMatch[2];
    }
  }

  const response = await fetch(url, { ...options, headers });

  // 401 and not the refresh endpoint itself: try silent refresh once
  if (
    response.status === 401 &&
    typeof window !== 'undefined' &&
    !url.includes('/api/auth/refresh')
  ) {
    const newToken = await refreshAccessToken();
    if (newToken) {
      const retryHeaders: Record<string, string> = {
        ...headers,
        Authorization: `Bearer ${newToken}`,
      };
      const retryResponse = await fetch(url, { ...options, headers: retryHeaders });
      return retryResponse;
    }
    clearAuthAndRedirect();
  }

  return response;
}

import { query } from './db';
import { getCacheManager } from '@/infrastructure/cache/CacheManager';
import { CacheGuard } from '@/infrastructure/cache/CacheGuard';

const BOM_CACHE_TTL_SECONDS = 600;

let bomCacheGuard: CacheGuard | null = null;
function getBomCacheGuard(): CacheGuard {
  if (!bomCacheGuard) {
    bomCacheGuard = new CacheGuard(getCacheManager());
  }
  return bomCacheGuard;
}

function bomCacheKey(productId: number, quantity: number): string {
  return `bom:expansion:${productId}:${quantity}`;
}

/**
 * BOM展开配置
 */
export interface BomExpansionConfig {
  maxDepth: number; // 最大递归深度，默认10
  enableCache: boolean; // 是否启用缓存，默认true
}

/**
 * BOM展开结果项
 */
export interface BomExpansionItem {
  materialId: number;
  materialCode: string;
  materialName: string;
  materialSpec?: string;
  unit: string;
  // 基础用量（不含损耗）
  baseQuantity: number;
  // 累计损耗率（百分比）
  accumulatedLossRate: number;
  // 实际需求量 = baseQuantity * (1 + accumulatedLossRate/100)
  actualQuantity: number;
  // BOM层级深度（0为顶层产品）
  level: number;
  // 父级路径（产品编码 -> 子件编码 -> ...）
  parentPath: string[];
  // 来源BOM ID
  sourceBomId: number;
  // 是否为叶子节点（最底层的原材料）
  isLeaf: boolean;
}

/**
 * BOM展开结果
 */
export interface BomExpansionResult {
  // 产品信息
  productId: number;
  productCode: string;
  productName: string;
  productSpec?: string;
  // 需求数量
  requiredQuantity: number;
  // 展开后的所有物料
  items: BomExpansionItem[];
  // 展开统计
  statistics: {
    totalMaterials: number; // 总物料种类数
    maxDepth: number; // 最大展开层级
    leafMaterials: number; // 叶子节点物料数
    intermediateMaterials: number; // 中间件物料数
  };
  // 循环引用警告
  circularReferenceWarnings?: string[];
}

/**
 * BOM节点（用于递归计算）
 */
interface _BomNode {
  id: number;
  code: string;
  name: string;
  spec?: string;
  unit: string;
  type: 'product' | 'material'; // 产品或物料
  bomId?: number; // 如果是产品，关联的BOM ID
}

/**
 * BOM明细行
 */
interface BomLine {
  materialId: number;
  materialCode: string;
  materialName: string;
  materialSpec?: string;
  unit: string;
  quantity: number; // 单位用量
  lossRate: number; // 损耗率（百分比）
  bomId: number;
}

/**
 * 获取产品的BOM明细
 */
async function getBomLines(productId: number): Promise<BomLine[]> {
  const sql = `
    SELECT 
      bl.material_id as materialId,
      bl.material_code as materialCode,
      bl.material_name as materialName,
      bl.material_spec as materialSpec,
      bl.unit,
      bl.consumption_qty as quantity,
      bl.loss_rate as lossRate,
      bh.id as bomId
    FROM bom_header bh
    INNER JOIN bom_line bl ON bh.id = bl.bom_id
    WHERE bh.product_id = ?
      AND bh.status = 30
      AND bh.deleted = 0
      AND bh.is_default = 1
    ORDER BY bl.line_no
  `;

  const rows = await query<BomLine>(sql, [productId]);
  return rows;
}

/**
 * 检查物料是否有BOM（是否为半成品）
 */
async function checkMaterialHasBom(
  materialId: number
): Promise<{ hasBom: boolean; bomId?: number }> {
  const sql = `
    SELECT bh.id as bomId
    FROM bom_header bh
    INNER JOIN products p ON bh.product_id = p.id
    INNER JOIN materials m ON m.code = p.code
    WHERE m.id = ?
      AND bh.status = 30
      AND bh.deleted = 0
      AND bh.is_default = 1
    LIMIT 1
  `;

  const rows = await query<{ bomId: number }>(sql, [materialId]);
  if (rows.length > 0) {
    return { hasBom: true, bomId: rows[0].bomId };
  }
  return { hasBom: false };
}

/**
 * 根据物料ID获取产品ID（如果物料对应一个产品）
 */
async function getProductIdByMaterialId(materialId: number): Promise<number | null> {
  const sql = `
    SELECT p.id as productId
    FROM products p
    INNER JOIN materials m ON m.code = p.code
    WHERE m.id = ?
    LIMIT 1
  `;

  const rows = await query<{ productId: number }>(sql, [materialId]);
  return rows.length > 0 ? rows[0].productId : null;
}

/**
 * 递归展开BOM
 */
async function expandBomRecursive(
  productId: number,
  productCode: string,
  productName: string,
  productSpec: string | undefined,
  requiredQuantity: number,
  accumulatedLossRate: number,
  currentDepth: number,
  parentPath: string[],
  config: BomExpansionConfig,
  visitedNodes: Set<string>,
  warnings: string[]
): Promise<BomExpansionItem[]> {
  const items: BomExpansionItem[] = [];

  // 深度限制检查
  if (currentDepth >= config.maxDepth) {
    warnings.push(`达到最大递归深度 ${config.maxDepth}，产品 ${productCode} 的展开已停止`);
    return items;
  }

  // 循环引用检查
  const nodeKey = `${productId}:${productCode}`;
  if (visitedNodes.has(nodeKey)) {
    warnings.push(`检测到循环引用：${[...parentPath, productCode].join(' -> ')}`);
    return items;
  }
  visitedNodes.add(nodeKey);

  // 获取BOM明细
  const bomLines = await getBomLines(productId);

  if (bomLines.length === 0) {
    // 没有BOM，说明是叶子节点
    return items;
  }

  // 递归展开每个物料
  for (const line of bomLines) {
    // 计算当前层的需求量（考虑父级累计损耗）
    // 父级需求 × 子件用量 × (1 + 父级累计损耗/100)
    const baseQuantity = requiredQuantity * line.quantity;

    // 子级损耗 = 父级损耗 + 子级自身损耗 × 父级用量
    // 实际计算：累计损耗率 = 父级累计损耗率 + 当前损耗率
    const currentAccumulatedLossRate = accumulatedLossRate + line.lossRate;

    // 实际需求量 = 基础用量 × (1 + 累计损耗率/100)
    const actualQuantity = baseQuantity * (1 + currentAccumulatedLossRate / 100);

    // 检查物料是否有BOM（是否为半成品）
    const { hasBom, bomId: _bomId } = await checkMaterialHasBom(line.materialId);

    // 获取对应的产品ID（如果有）
    const relatedProductId = await getProductIdByMaterialId(line.materialId);

    const currentItem: BomExpansionItem = {
      materialId: line.materialId,
      materialCode: line.materialCode,
      materialName: line.materialName,
      materialSpec: line.materialSpec,
      unit: line.unit,
      baseQuantity,
      accumulatedLossRate: currentAccumulatedLossRate,
      actualQuantity,
      level: currentDepth,
      parentPath: [...parentPath],
      sourceBomId: line.bomId,
      isLeaf: !hasBom,
    };

    if (hasBom && relatedProductId) {
      // 是半成品，继续递归展开
      const childItems = await expandBomRecursive(
        relatedProductId,
        line.materialCode,
        line.materialName,
        line.materialSpec,
        actualQuantity, // 使用实际需求量作为子级的需求数量
        currentAccumulatedLossRate, // 传递累计损耗率
        currentDepth + 1,
        [...parentPath, productCode],
        config,
        visitedNodes,
        warnings
      );

      // 标记为非叶子节点
      currentItem.isLeaf = false;
      items.push(currentItem);
      items.push(...childItems);
    } else {
      // 是原材料，叶子节点
      currentItem.isLeaf = true;
      items.push(currentItem);
    }
  }

  // 移除访问标记（允许其他路径访问此节点）
  visitedNodes.delete(nodeKey);

  return items;
}

/**
 * 合并相同的物料（按materialId分组，累加数量）
 */
function mergeMaterials(items: BomExpansionItem[]): BomExpansionItem[] {
  const materialMap = new Map<number, BomExpansionItem>();

  for (const item of items) {
    const existing = materialMap.get(item.materialId);
    if (existing) {
      // 累加数量
      existing.baseQuantity += item.baseQuantity;
      existing.actualQuantity += item.actualQuantity;
      // 取较大的损耗率
      existing.accumulatedLossRate = Math.max(
        existing.accumulatedLossRate,
        item.accumulatedLossRate
      );
      // 取较深的层级
      existing.level = Math.max(existing.level, item.level);
    } else {
      materialMap.set(item.materialId, { ...item });
    }
  }

  return Array.from(materialMap.values()).sort((a, b) => {
    // 按层级和物料编码排序
    if (a.level !== b.level) return a.level - b.level;
    return a.materialCode.localeCompare(b.materialCode);
  });
}

/**
 * 展开BOM - 主函数
 * @param productId 产品ID
 * @param quantity 需求数量
 * @param config 配置选项
 */
export async function expandBom(
  productId: number,
  quantity: number,
  config: Partial<BomExpansionConfig> = {}
): Promise<BomExpansionResult> {
  // 默认配置
  const finalConfig: BomExpansionConfig = {
    maxDepth: config.maxDepth || 10,
    enableCache: config.enableCache !== false,
  };

  const computeResult = async (): Promise<BomExpansionResult> => {
    // 获取产品信息
    const productSql = `
      SELECT
        id,
        code,
        name,
        specification
      FROM products
      WHERE id = ?
    `;
    const productRows = await query<{
      id: number;
      code: string;
      name: string;
      specification?: string;
    }>(productSql, [productId]);

    if (productRows.length === 0) {
      throw new Error(`产品不存在：ID ${productId}`);
    }

    const product = productRows[0];
    const warnings: string[] = [];
    const visitedNodes = new Set<string>();

    // 递归展开BOM
    const items = await expandBomRecursive(
      productId,
      product.code,
      product.name,
      product.specification,
      quantity,
      0, // 初始累计损耗率为0
      0, // 初始层级为0
      [], // 初始父级路径为空
      finalConfig,
      visitedNodes,
      warnings
    );

    // 合并相同物料
    const mergedItems = mergeMaterials(items);

    // 统计信息
    const statistics = {
      totalMaterials: mergedItems.length,
      maxDepth: Math.max(...mergedItems.map((i) => i.level), 0),
      leafMaterials: mergedItems.filter((i) => i.isLeaf).length,
      intermediateMaterials: mergedItems.filter((i) => !i.isLeaf).length,
    };

    return {
      productId: product.id,
      productCode: product.code,
      productName: product.name,
      productSpec: product.specification,
      requiredQuantity: quantity,
      items: mergedItems,
      statistics,
      circularReferenceWarnings: warnings.length > 0 ? warnings : undefined,
    };
  };

  if (!finalConfig.enableCache) {
    return computeResult();
  }

  return getBomCacheGuard().getOrLoad(
    bomCacheKey(productId, quantity),
    BOM_CACHE_TTL_SECONDS,
    computeResult
  );
}

/**
 * 批量展开多个产品的BOM
 * @param products 产品列表 [{ productId, quantity }]
 * @param config 配置选项
 */
export async function expandBomBatch(
  products: Array<{ productId: number; quantity: number }>,
  config: Partial<BomExpansionConfig> = {}
): Promise<BomExpansionResult[]> {
  const results: BomExpansionResult[] = [];

  for (const { productId, quantity } of products) {
    try {
      const result = await expandBom(productId, quantity, config);
      results.push(result);
    } catch (error) {
      throw error;
    }
  }

  return results;
}

/**
 * 合并多个BOM展开结果（用于汇总多个产品的物料需求）
 */
export function mergeExpansionResults(results: BomExpansionResult[]): {
  materials: Map<
    number,
    {
      materialCode: string;
      materialName: string;
      materialSpec?: string;
      unit: string;
      totalActualQuantity: number;
      sources: Array<{ productCode: string; quantity: number }>;
    }
  >;
} {
  const materialMap = new Map<
    number,
    {
      materialCode: string;
      materialName: string;
      materialSpec?: string;
      unit: string;
      totalActualQuantity: number;
      sources: Array<{ productCode: string; quantity: number }>;
    }
  >();

  for (const result of results) {
    for (const item of result.items) {
      // 只统计叶子节点（原材料）
      if (!item.isLeaf) continue;

      const existing = materialMap.get(item.materialId);
      if (existing) {
        existing.totalActualQuantity += item.actualQuantity;
        existing.sources.push({
          productCode: result.productCode,
          quantity: item.actualQuantity,
        });
      } else {
        materialMap.set(item.materialId, {
          materialCode: item.materialCode,
          materialName: item.materialName,
          materialSpec: item.materialSpec,
          unit: item.unit,
          totalActualQuantity: item.actualQuantity,
          sources: [
            {
              productCode: result.productCode,
              quantity: item.actualQuantity,
            },
          ],
        });
      }
    }
  }

  return { materials: materialMap };
}

/**
 * 清除缓存
 */
export async function clearBomExpansionCache(): Promise<void> {
  await getCacheManager().deletePattern('bom:expansion:*');
}

interface BomTreeNode {
  id: number;
  code: string;
  name: string;
  type: 'product' | 'material';
  quantity: number;
  lossRate: number;
  level: number;
  children: BomTreeNode[];
}

/**
 * 获取BOM展开的树形结构（用于前端展示）
 */
export async function getBomExpansionTree(
  productId: number,
  quantity: number,
  config: Partial<BomExpansionConfig> = {}
): Promise<{
  node: BomTreeNode;
  warnings?: string[];
}> {
  const warnings: string[] = [];
  const visitedNodes = new Set<string>();

  async function buildTree(
    pid: number,
    pcode: string,
    pname: string,
    pquantity: number,
    plossRate: number,
    level: number,
    path: string[]
  ): Promise<BomTreeNode> {
    // 深度和循环检查
    if (level >= (config.maxDepth || 10)) {
      warnings.push(`达到最大递归深度，产品 ${pcode} 的展开已停止`);
      return {
        id: pid,
        code: pcode,
        name: pname,
        type: 'product' as const,
        quantity: pquantity,
        lossRate: plossRate,
        level,
        children: [] as BomTreeNode[],
      };
    }

    const nodeKey = `${pid}:${pcode}`;
    if (visitedNodes.has(nodeKey)) {
      warnings.push(`检测到循环引用：${[...path, pcode].join(' -> ')}`);
      return {
        id: pid,
        code: pcode,
        name: pname,
        type: 'product' as const,
        quantity: pquantity,
        lossRate: plossRate,
        level,
        children: [] as BomTreeNode[],
      };
    }
    visitedNodes.add(nodeKey);

    const bomLines = await getBomLines(pid);
    const children: BomTreeNode[] = [];

    for (const line of bomLines) {
      const baseQty = pquantity * line.quantity;
      const accLossRate = plossRate + line.lossRate;
      const actualQty = baseQty * (1 + accLossRate / 100);

      const { hasBom } = await checkMaterialHasBom(line.materialId);
      const relatedProductId = await getProductIdByMaterialId(line.materialId);

      if (hasBom && relatedProductId) {
        const childTree = await buildTree(
          relatedProductId,
          line.materialCode,
          line.materialName,
          actualQty,
          accLossRate,
          level + 1,
          [...path, pcode]
        );
        children.push(childTree);
      } else {
        children.push({
          id: line.materialId,
          code: line.materialCode,
          name: line.materialName,
          type: 'material' as const,
          quantity: actualQty,
          lossRate: accLossRate,
          level: level + 1,
          children: [],
        });
      }
    }

    visitedNodes.delete(nodeKey);

    return {
      id: pid,
      code: pcode,
      name: pname,
      type: 'product',
      quantity: pquantity,
      lossRate: plossRate,
      level,
      children,
    };
  }

  // 获取产品信息
  const productSql = `SELECT id, code, name FROM products WHERE id = ?`;
  const productRows = await query<{ id: number; code: string; name: string }>(productSql, [
    productId,
  ]);

  if (productRows.length === 0) {
    throw new Error(`产品不存在：ID ${productId}`);
  }

  const product = productRows[0];
  const node = await buildTree(product.id, product.code, product.name, quantity, 0, 0, []);

  return {
    node,
    warnings: warnings.length > 0 ? warnings : undefined,
  };
}

import type { PoolConnection, RowDataPacket } from 'mysql2/promise';

export interface CuttingInput {
  id: string;
  width: number;
  height: number;
  quantity: number;
  label: string;
  rotate: boolean;
}

export interface CuttingResult {
  input_id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  rotated: boolean;
  sheet_index: number;
}

export interface SheetLayout {
  sheet_index: number;
  sheet_width: number;
  sheet_height: number;
  cuts: CuttingResult[];
  utilized_area: number;
  total_area: number;
  utilization_rate: number;
  waste_area: number;
}

export interface CuttingOptimizationResult {
  sheets: SheetLayout[];
  total_sheets: number;
  overall_utilization: number;
  total_waste: number;
  unplaced_items: { input_id: string; remaining_qty: number }[];
}

interface FreeRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

function splitFreeRect(rect: FreeRect, pw: number, ph: number, kerf: number): FreeRect[] {
  const result: FreeRect[] = [];
  const rightW = rect.width - pw;
  const bottomH = rect.height - ph;

  if (rightW <= 0 && bottomH <= 0) {
    return result;
  }

  if (rightW <= 0) {
    const h = bottomH - kerf;
    if (h > 0) {
      result.push({ x: rect.x, y: rect.y + ph + kerf, width: rect.width, height: h });
    }
    return result;
  }

  if (bottomH <= 0) {
    result.push({ x: rect.x + pw, y: rect.y, width: rightW, height: rect.height });
    return result;
  }

  const horizRightArea = rightW * ph;
  const horizBottomH = bottomH - kerf;
  const horizBottomArea = rect.width * (horizBottomH > 0 ? horizBottomH : 0);
  const horizMinArea = Math.min(horizRightArea, horizBottomArea);

  const vertBelowArea = pw * bottomH;
  const vertRightW = rightW - kerf;
  const vertRightArea = (vertRightW > 0 ? vertRightW : 0) * rect.height;
  const vertMinArea = Math.min(vertBelowArea, vertRightArea);

  if (horizMinArea >= vertMinArea) {
    result.push({ x: rect.x + pw, y: rect.y, width: rightW, height: ph });
    if (horizBottomH > 0) {
      result.push({ x: rect.x, y: rect.y + ph + kerf, width: rect.width, height: horizBottomH });
    }
  } else {
    result.push({ x: rect.x, y: rect.y + ph, width: pw, height: bottomH });
    if (vertRightW > 0) {
      result.push({ x: rect.x + pw + kerf, y: rect.y, width: vertRightW, height: rect.height });
    }
  }

  return result;
}

export function guillotineCut(
  inputs: CuttingInput[],
  sheetWidth: number,
  sheetHeight: number,
  kerfWidth: number = 2,
  allowRotation: boolean = true
): CuttingOptimizationResult {
  const sorted = [...inputs].sort((a, b) => b.width * b.height - a.width * a.height);

  const sheets: SheetLayout[] = [];
  const freeRectsList: FreeRect[][] = [];
  const unplacedItems: { input_id: string; remaining_qty: number }[] = [];

  for (const input of sorted) {
    let remaining = input.quantity;

    while (remaining > 0) {
      let bestSheet = -1;
      let bestRectIdx = -1;
      let bestRotated = false;
      let bestScore = Infinity;

      for (let s = 0; s < sheets.length; s++) {
        for (let r = 0; r < freeRectsList[s].length; r++) {
          const rect = freeRectsList[s][r];

          if (input.width <= rect.width && input.height <= rect.height) {
            const score = rect.width * rect.height - input.width * input.height;
            if (score < bestScore) {
              bestScore = score;
              bestSheet = s;
              bestRectIdx = r;
              bestRotated = false;
            }
          }

          if (
            allowRotation &&
            input.rotate &&
            input.height <= rect.width &&
            input.width <= rect.height
          ) {
            const score = rect.width * rect.height - input.height * input.width;
            if (score < bestScore) {
              bestScore = score;
              bestSheet = s;
              bestRectIdx = r;
              bestRotated = true;
            }
          }
        }
      }

      if (bestSheet >= 0) {
        const rect = freeRectsList[bestSheet][bestRectIdx];
        const pw = bestRotated ? input.height : input.width;
        const ph = bestRotated ? input.width : input.height;

        sheets[bestSheet].cuts.push({
          input_id: input.id,
          x: rect.x,
          y: rect.y,
          width: pw,
          height: ph,
          rotated: bestRotated,
          sheet_index: bestSheet,
        });

        freeRectsList[bestSheet].splice(bestRectIdx, 1);
        const newFreeRects = splitFreeRect(rect, pw, ph, kerfWidth);
        freeRectsList[bestSheet].push(...newFreeRects);

        remaining--;
      } else {
        const sheetIndex = sheets.length;
        const newSheet: SheetLayout = {
          sheet_index: sheetIndex,
          sheet_width: sheetWidth,
          sheet_height: sheetHeight,
          cuts: [],
          utilized_area: 0,
          total_area: sheetWidth * sheetHeight,
          utilization_rate: 0,
          waste_area: sheetWidth * sheetHeight,
        };
        const initialFreeRect: FreeRect = {
          x: 0,
          y: 0,
          width: sheetWidth,
          height: sheetHeight,
        };

        let placed = false;

        if (input.width <= sheetWidth && input.height <= sheetHeight) {
          newSheet.cuts.push({
            input_id: input.id,
            x: 0,
            y: 0,
            width: input.width,
            height: input.height,
            rotated: false,
            sheet_index: sheetIndex,
          });
          const newFreeRects = splitFreeRect(initialFreeRect, input.width, input.height, kerfWidth);
          sheets.push(newSheet);
          freeRectsList.push(newFreeRects);
          placed = true;
          remaining--;
        } else if (
          allowRotation &&
          input.rotate &&
          input.height <= sheetWidth &&
          input.width <= sheetHeight
        ) {
          newSheet.cuts.push({
            input_id: input.id,
            x: 0,
            y: 0,
            width: input.height,
            height: input.width,
            rotated: true,
            sheet_index: sheetIndex,
          });
          const newFreeRects = splitFreeRect(initialFreeRect, input.height, input.width, kerfWidth);
          sheets.push(newSheet);
          freeRectsList.push(newFreeRects);
          placed = true;
          remaining--;
        } else {
          sheets.push(newSheet);
          freeRectsList.push([initialFreeRect]);
          break;
        }

        if (!placed) {
          break;
        }
      }
    }

    if (remaining > 0) {
      unplacedItems.push({ input_id: input.id, remaining_qty: remaining });
    }
  }

  let totalUtilized = 0;
  let totalArea = 0;
  for (const sheet of sheets) {
    sheet.utilized_area = sheet.cuts.reduce((sum, c) => sum + c.width * c.height, 0);
    sheet.waste_area = sheet.total_area - sheet.utilized_area;
    sheet.utilization_rate = sheet.total_area > 0 ? sheet.utilized_area / sheet.total_area : 0;
    totalUtilized += sheet.utilized_area;
    totalArea += sheet.total_area;
  }

  return {
    sheets,
    total_sheets: sheets.length,
    overall_utilization: totalArea > 0 ? totalUtilized / totalArea : 0,
    total_waste: totalArea - totalUtilized,
    unplaced_items: unplacedItems,
  };
}

export function calculateScrapRate(result: CuttingOptimizationResult): {
  perSheet: number[];
  overall: number;
} {
  const perSheet = result.sheets.map((sheet) => {
    if (sheet.total_area <= 0) return 0;
    return sheet.waste_area / sheet.total_area;
  });

  const totalWaste = result.sheets.reduce((sum, sheet) => sum + sheet.waste_area, 0);
  const totalArea = result.sheets.reduce((sum, sheet) => sum + sheet.total_area, 0);
  const overall = totalArea > 0 ? totalWaste / totalArea : 0;

  return { perSheet, overall };
}

export async function generateCuttingPlan(
  conn: PoolConnection,
  cuttingRecordId: number
): Promise<CuttingOptimizationResult> {
  const [records]: [RowDataPacket[], unknown] = await conn.query(
    `SELECT
      r.id,
      r.record_no,
      r.source_label_id,
      r.source_label_no,
      r.cut_width_str,
      r.original_width,
      r.remain_width,
      r.remark
    FROM inv_cutting_record r
    WHERE r.id = ? AND r.deleted = 0`,
    [cuttingRecordId]
  );

  if (!records || records.length === 0) {
    throw new Error(`分切记录不存在: ID=${cuttingRecordId}`);
  }

  const record = records[0];

  const [labels]: [RowDataPacket[], unknown] = await conn.query(
    `SELECT
      id,
      label_no,
      width,
      length_per_roll,
      specification,
      material_code,
      material_name
    FROM inv_material_label
    WHERE id = ? AND deleted = 0`,
    [record.source_label_id]
  );

  if (!labels || labels.length === 0) {
    throw new Error(`源标签不存在: label_id=${record.source_label_id}`);
  }

  const sourceLabel = labels[0];
  const sheetWidth = parseFloat(sourceLabel.width) || parseFloat(record.original_width) || 0;
  const sheetHeight =
    parseFloat(sourceLabel.length_per_roll) || parseSpecLength(sourceLabel.specification) || 1000;

  if (sheetWidth <= 0 || sheetHeight <= 0) {
    throw new Error('无法确定原材料尺寸，请检查标签宽幅和长度信息');
  }

  const [details]: [RowDataPacket[], unknown] = await conn.query(
    `SELECT
      d.id,
      d.new_label_no,
      d.cut_width,
      d.sequence
    FROM inv_cutting_detail d
    WHERE d.record_id = ?
    ORDER BY d.sequence`,
    [cuttingRecordId]
  );

  const inputs: CuttingInput[] = [];

  if (details && details.length > 0) {
    const widthCountMap = new Map<number, number>();
    for (const detail of details) {
      const w = parseFloat(detail.cut_width) || 0;
      if (w <= 0) continue;
      widthCountMap.set(w, (widthCountMap.get(w) || 0) + 1);
    }

    let seq = 0;
    for (const [w, qty] of widthCountMap) {
      inputs.push({
        id: `piece-${seq++}`,
        width: w,
        height: sheetHeight,
        quantity: qty,
        label: `${w}mm×${sheetHeight}mm`,
        rotate: false,
      });
    }
  } else if (record.cut_width_str) {
    const widths = record.cut_width_str
      .split('+')
      .map((s: string) => parseFloat(s.trim()))
      .filter((w: number) => w > 0);

    const widthCountMap = new Map<number, number>();
    for (const w of widths) {
      widthCountMap.set(w, (widthCountMap.get(w) || 0) + 1);
    }

    let seq = 0;
    for (const [w, qty] of widthCountMap) {
      inputs.push({
        id: `piece-${seq++}`,
        width: w,
        height: sheetHeight,
        quantity: qty,
        label: `${w}mm×${sheetHeight}mm`,
        rotate: false,
      });
    }
  }

  if (inputs.length === 0) {
    throw new Error('未找到分切目标尺寸数据');
  }

  const result = guillotineCut(inputs, sheetWidth, sheetHeight);

  const layoutJson = JSON.stringify({
    total_sheets: result.total_sheets,
    overall_utilization: result.overall_utilization,
    total_waste: result.total_waste,
    sheets: result.sheets.map((s) => ({
      sheet_index: s.sheet_index,
      utilization_rate: s.utilization_rate,
      cuts: s.cuts,
    })),
    unplaced_items: result.unplaced_items,
  });

  const existingRemark = record.remark || '';
  const newRemark = existingRemark
    ? `${existingRemark} [LAYOUT:${layoutJson}]`
    : `[LAYOUT:${layoutJson}]`;

  await conn.execute(`UPDATE inv_cutting_record SET remark = ? WHERE id = ?`, [
    newRemark,
    cuttingRecordId,
  ]);

  return result;
}

function parseSpecLength(spec: string): number {
  if (!spec) return 0;
  const match = spec.match(/(\d+(?:\.\d+)?)\s*[×xX*]\s*(\d+(?:\.\d+)?)\s*(mm|m)?/i);
  if (match) {
    const length = parseFloat(match[2]);
    const unit = match[3]?.toLowerCase();
    if (unit === 'm') return length * 1000;
    return length;
  }
  return 0;
}

/**
 * VNERP 数据变更对比工具
 * 功能：比较对象/数组的前后差异，生成审计可用的变更记录
 * 原则：所有修改留底，关键字段必须记录前后值
