  try {
    const rows: Loose = await query(
      'SELECT config_key, config_value FROM sys_config WHERE deleted = 0 AND config_key IN (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [
        'sales_order_prefix',
        'purchase_order_prefix',
        'work_order_prefix',
        'sample_prefix',
        'purchase_request_prefix',
        'inbound_prefix',
        'outbound_prefix',
        'transfer_prefix',
        'stocktaking_prefix',
        'receivable_prefix',
        'payable_prefix',
        'voucher_prefix',
        'receipt_prefix',
        'payment_prefix',
        'delivery_prefix',
        'return_prefix',
        'reconciliation_prefix',
        'serial_length',
        'order.prefix',
        'purchase.prefix',
        'inbound.prefix',
        'outbound.prefix',
      ]
    );
    const configs: Record<string, string> = {};
    rows.forEach((row: Loose) => {
      configs[row.config_key] = row.config_value;
    });
    // 命名空间前缀配置（系统配置中心）覆盖对应的扁平前缀字段
