  BATCH_EXPIRED: '批次已过期',
  COST_CALCULATION_ERROR: '成本计算错误',

  // 系统相关
  INTERNAL_ERROR: '系统内部错误，请稍后重试',
  DATABASE_ERROR: '数据库操作失败，请稍后重试',
  NETWORK_ERROR: '网络连接失败，请检查网络',
  RATE_LIMITED: '操作过于频繁，请稍后再试',
  SERVICE_UNAVAILABLE: '服务暂时不可用，请稍后重试',
};

// HTTP状态码到友好消息的映射
const HTTP_ERROR_MESSAGES: Record<number, string> = {
  400: '请求参数错误，请检查输入',
  401: '登录已过期，请重新登录',
  403: '您没有权限执行此操作',
  404: '请求的资源不存在',
  409: '数据冲突，请刷新后重试',
  422: '数据验证失败，请检查输入',
  429: '操作过于频繁，请稍后再试',
  500: '服务器内部错误，请稍后重试',
  502: '服务暂时不可用，请稍后重试',
  503: '服务维护中，请稍后重试',
};

export interface AppError {
  code?: string;
  message?: string;
  status?: number;
  details?: Loose;
}

/**
 * 将后端错误转换为用户友好的提示信息
 */
export function getErrorMessage(error: unknown): string {
  // 网络错误
  if (error instanceof TypeError && error.message === 'Failed to fetch') {
    return '网络连接失败，请检查网络设置';
  }

  // Response对象
  if (error instanceof Response) {
    return HTTP_ERROR_MESSAGES[error.status] || `请求失败 (${error.status})`;
  }

  // 自定义错误对象
  if (error && typeof error === 'object') {
    const err = error as AppError;

    // 优先使用错误码映射
    if (err.code && ERROR_MESSAGES[err.code]) {
      return ERROR_MESSAGES[err.code];
    }

    // HTTP状态码映射
    if (err.status && HTTP_ERROR_MESSAGES[err.status]) {
      return HTTP_ERROR_MESSAGES[err.status];
    }

    // 直接使用错误消息（但过滤掉技术性信息）
    if (err.message) {
      // 过滤掉SQL错误、堆栈信息等技术性内容
      if (err.message.includes('SQL') || err.message.includes('ER_')) {
        return '数据库操作失败，请联系管理员';
      }
      if (err.message.includes('ECONNREFUSED') || err.message.includes('ETIMEDOUT')) {
        return '网络连接失败，请稍后重试';
      }
      if (err.message.includes('jwt') || err.message.includes('token')) {
        return '登录已过期，请重新登录';
      }
      // 如果消息看起来是用户友好的，直接返回
      if (err.message.length < 100 && !err.message.includes('{') && !err.message.includes('at ')) {
        return err.message;
      }
    }
  }

  // 字符串错误
  if (typeof error === 'string') {
    if (error.length < 100) return error;
  }

  return '操作失败，请稍后重试';
}

/**
 * 处理API响应，统一错误处理
 */
export async function handleApiResponse<T = Loose>(
  response: Response,
  options?: {
    onSuccess?: (data: T) => void;
    onError?: (message: string) => void;
    showToast?: boolean;
  }
): Promise<{ success: boolean; data?: T; message?: string }> {
  try {
    const result = await response.json();

    if (result.success) {
      options?.onSuccess?.(result.data);
      return { success: true, data: result.data };
    }

    const message = getErrorMessage({
      code: result.code,
      message: result.message,
      status: response.status,
    });

    options?.onError?.(message);
    return { success: false, message };
  } catch (e) {
    const message = getErrorMessage(e);
    options?.onError?.(message);
    return { success: false, message };
  }
}

import * as XLSX from '@e965/xlsx';
import { secureLog } from '@/lib/logger';

export interface ReportColumnGroup {
  header: string;
  children: ReportColumnLeaf[];
}

export interface ReportColumnLeaf {
  key: string;
  header: string;
  width?: number;
  formatter?: (value: unknown, row: Record<string, unknown>) => string;
}

export type ReportColumnDef = ReportColumnGroup;

export interface ReportExportOptions {
  fileName: string;
  sheetName?: string;
  columnDefs: ReportColumnDef[];
  data: Record<string, unknown>[];
  title?: string;
  freezeRow?: number;
  freezeCol?: number;
}

function getLeafColumns(defs: ReportColumnDef[]): ReportColumnLeaf[] {
  return defs.flatMap((g) => g.children);
}

export function exportReportToExcel(options: ReportExportOptions): Buffer {
  const workbook = XLSX.utils.book_new();
  const wsData: unknown[][] = [];
  const { columnDefs, data, title } = options;

  if (title) wsData.push([title]);

  const topHeaders = columnDefs.map((g) => g.header);
  const subHeaders = columnDefs.flatMap((g) => g.children.map((c) => c.header));

  wsData.push(topHeaders);
  wsData.push(subHeaders);

  const leafCols = getLeafColumns(columnDefs);
  for (const row of data) {
    const rowData = leafCols.map((col) => {
      if (col.formatter) return col.formatter(row[col.key], row);
      return row[col.key] ?? '';
    });
    wsData.push(rowData);
  }

  const colCount = topHeaders.length;
  const rowCount = wsData.length;

  const ws = XLSX.utils.aoa_to_sheet(wsData);
  const merges: XLSX.Range[] = [];

  const titleOffset = title ? 1 : 0;

  for (let i = 0; i < colCount; i++) {
    const group = columnDefs[i];
    const childCount = group.children.length;
    if (childCount > 1) {
      const startCol = subHeaders.indexOf(group.children[0].header);
      const endCol = startCol + childCount - 1;
      merges.push({
        s: { r: titleOffset, c: startCol },
        e: { r: titleOffset, c: endCol },
      });
    }
  }

  if (title && colCount > 0) {
    merges.push({ s: { r: 0, c: 0 }, e: { r: 0, c: colCount - 1 } });
  }

  ws['!merges'] = merges;
  ws['!cols'] = leafCols.map((c) => ({ wch: c.width ?? 15 }));
  ws['!freeze'] = { xSplit: options.freezeCol ?? 0, ySplit: options.freezeRow ?? 2 };

  XLSX.utils.book_append_sheet(workbook, ws, options.sheetName ?? 'Report');

  const buffer = XLSX.write(workbook, { type: 'buffer', bookType: 'xlsx' });

  secureLog('info', 'Report Excel exported', {
    fileName: options.fileName,
    rowCount: data.length,
  });

  return buffer as Buffer;
}

import * as XLSX from '@e965/xlsx';
import { ZodSchema, z } from 'zod';
import { secureLog } from '@/lib/logger';

export interface ExportColumn {
  key: string;
  header: string;
  width?: number;
  formatter?: (value: Loose, row: Loose) => string;
}

export interface ExportOptions {
  fileName: string;
  sheetName?: string;
  columns: ExportColumn[];
  data: Loose[];
  title?: string;
  author?: string;
}

export interface ImportValidationError {
  row: number;
  field: string;
  message: string;
  value: Loose;
}

export interface ImportResult<T> {
  success: boolean;
  data: T[];
  errors: ImportValidationError[];
  totalRows: number;
  validRows: number;
  invalidRows: number;
}

export interface ImportTemplate {
  sheetName: string;
  headers: string[];
  sampleData?: Loose[];
  validationRules?: Record<
    string,
    {
      required?: boolean;
      type?: 'string' | 'number' | 'date' | 'boolean';
      min?: number;
      max?: number;
      pattern?: string;
      enum?: string[];
      custom?: (value: Loose) => boolean | string;
    }
  >;
}

export class ExcelExportService {
  static exportToExcel(options: ExportOptions): Buffer {
    const workbook = XLSX.utils.book_new();
    const worksheetData: Loose[][] = [];

    if (options.title) {
      worksheetData.push([options.title]);
      worksheetData.push([]);
    }

    const headers = options.columns.map((col) => col.header);
    worksheetData.push(headers);

    for (const row of options.data) {
      const rowData = options.columns.map((col) => {
        const value = row[col.key];
        if (col.formatter) {
          return col.formatter(value, row);
        }
        return value ?? '';
      });
      worksheetData.push(rowData);
    }

    const worksheet = XLSX.utils.aoa_to_sheet(worksheetData);

    if (options.columns.length > 0) {
      worksheet['!cols'] = options.columns.map((col) => ({
        wch: col.width || 15,
      }));
    }

    XLSX.utils.book_append_sheet(workbook, worksheet, options.sheetName || 'Sheet1');

    const buffer = XLSX.write(workbook, {
      type: 'buffer',
      bookType: 'xlsx',
    });

    secureLog('info', 'Excel exported', {
      fileName: options.fileName,
      rowCount: options.data.length,
    });

    return buffer as Buffer;
  }

  static exportToCSV(options: Omit<ExportOptions, 'fileName'>): string {
    const worksheetData: Loose[][] = [];

    if (options.title) {
      worksheetData.push([options.title]);
      worksheetData.push([]);
    }

    const headers = options.columns.map((col) => col.header);
    worksheetData.push(headers);

    for (const row of options.data) {
      const rowData = options.columns.map((col) => {
        const value = row[col.key];
        if (col.formatter) {
          return col.formatter(value, row);
        }
        return value ?? '';
      });
      worksheetData.push(rowData);
    }

    const csv = XLSX.utils.sheet_to_csv(XLSX.utils.aoa_to_sheet(worksheetData));

    secureLog('info', 'CSV exported', {
      rowCount: options.data.length,
    });

    return csv;
  }

  static generateTemplate(template: ImportTemplate): Buffer {
    const workbook = XLSX.utils.book_new();
    const worksheetData: Loose[][] = [];

    // 注意: 模板生成时无法获取locale,这些文本需要在调用时传入翻译后的文本
    worksheetData.push([template.sheetName + ' - Import Template']);
    worksheetData.push(['Note: Columns marked with * are required']);
    worksheetData.push([]);

    const headers = template.headers.map((h, index) => {
      const rule = template.validationRules?.[index.toString()];
      if (rule?.required) {
        return h + ' *';
      }
      return h;
    });
    worksheetData.push(headers);

    if (template.sampleData && template.sampleData.length > 0) {
      worksheetData.push([]);
      worksheetData.push(['Sample Data:']);
      for (const sample of template.sampleData) {
        worksheetData.push(Object.values(sample));
      }
    }

    worksheetData.push([]);
    worksheetData.push(['Instructions:']);
    worksheetData.push(['1. Columns with * are required']);
    worksheetData.push(['2. Date format: YYYY-MM-DD']);
    worksheetData.push(['3. Number format: No commas']);

    const worksheet = XLSX.utils.aoa_to_sheet(worksheetData);
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Template');

    const buffer = XLSX.write(workbook, {
      type: 'buffer',
      bookType: 'xlsx',
    });

    return buffer as Buffer;
  }
}

export class ExcelImportService {
  static parseExcelFile(buffer: Buffer): Loose[] {
    const workbook = XLSX.read(buffer, { type: 'buffer' });
    const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
    const data = XLSX.utils.sheet_to_json(firstSheet, { defval: '' });
    return data;
  }

  static async importWithValidation<T>(
    buffer: Buffer,
    schema: ZodSchema<T>,
    options?: {
      skipEmptyRows?: boolean;
      headerRow?: number;
    }
  ): Promise<ImportResult<T>> {
    const data = this.parseExcelFile(buffer);

    const errors: ImportValidationError[] = [];
    const validData: T[] = [];
    const skipEmpty = options?.skipEmptyRows ?? true;
    const headerRow = options?.headerRow ?? 2;

    for (let i = headerRow; i < data.length; i++) {
      const row = data[i] as Loose;
      const rowNumber = i + 1;

      if (skipEmpty && this.isEmptyRow(row)) {
        continue;
      }

      const result = schema.safeParse(row);

      if (!result.success) {
        for (const issue of result.error.issues) {
          errors.push({
            row: rowNumber,
            field: issue.path.join('.'),
            message: issue.message,
            value: (row as Loose)[issue.path[0] as string],
          });
        }
      } else {
        validData.push(result.data);
      }
    }

    return {
      success: errors.length === 0,
      data: validData,
      errors,
      totalRows: data.length - headerRow,
      validRows: validData.length,
      invalidRows: errors.length > 0 ? Math.ceil(errors.length / 3) : 0,
    };
  }

  static validateAgainstTemplate(data: Loose[], template: ImportTemplate): ImportValidationError[] {
    const errors: ImportValidationError[] = [];

    for (let i = 0; i < data.length; i++) {
      const row = data[i] as Loose;
      const rowNumber = i + 2;

      for (const [fieldKey, rules] of Object.entries(template.validationRules || {})) {
        const fieldIndex = parseInt(fieldKey);
        const headerName = template.headers[fieldIndex];
        const value = row[headerName];

        if (rules.required && (value === undefined || value === null || value === '')) {
          errors.push({
            row: rowNumber,
            field: headerName,
            message: 'Required field cannot be empty',
            value,
          });
          continue;
        }

        if (value === undefined || value === null || value === '') {
          continue;
        }

        if (rules.type === 'number') {
          const numValue = typeof value === 'number' ? value : parseFloat(value);
          if (isNaN(numValue)) {
            errors.push({
              row: rowNumber,
              field: headerName,
              message: 'Must be a valid number',
              value,
            });
          } else {
            if (rules.min !== undefined && numValue < rules.min) {
              errors.push({
                row: rowNumber,
                field: headerName,
                message: `Cannot be less than ${rules.min}`,
                value,
              });
            }
            if (rules.max !== undefined && numValue > rules.max) {
              errors.push({
                row: rowNumber,
                field: headerName,
                message: `Cannot be greater than ${rules.max}`,
                value,
              });
            }
          }
        }

        if (rules.type === 'date') {
          const dateValue = new Date(value);
          if (isNaN(dateValue.getTime())) {
            errors.push({
              row: rowNumber,
              field: headerName,
              message: 'Invalid date format, please use YYYY-MM-DD',
              value,
            });
          }
        }

        if (rules.type === 'string' && typeof value !== 'string') {
          errors.push({
            row: rowNumber,
            field: headerName,
            message: 'Must be text',
            value,
          });
        }

        if (rules.pattern) {
          const regex = new RegExp(rules.pattern);
          if (!regex.test(String(value))) {
            errors.push({
              row: rowNumber,
              field: headerName,
              message: 'Invalid format',
              value,
            });
          }
        }

        if (rules.enum && rules.enum.length > 0) {
          if (!rules.enum.includes(String(value))) {
            errors.push({
              row: rowNumber,
              field: headerName,
              message: `Value must be one of: ${rules.enum.join(', ')}`,
              value,
            });
          }
        }

        if (rules.custom) {
          const customResult = rules.custom(value);
          if (customResult !== true && typeof customResult === 'string') {
            errors.push({
              row: rowNumber,
              field: headerName,
              message: customResult,
              value,
            });
          }
        }
      }
    }

    return errors;
  }

  private static isEmptyRow(row: Loose): boolean {
    return Object.values(row).every(
      (value) => value === undefined || value === null || value === ''
    );
  }
}

