  } catch (error) {
    secureLog('error', '应付单生成失败', { error: (error as Error).message, purchaseOrderId });
    return { success: false, message: `生成失败: ${(error as Error).message}` };
  }
}

/**
 * 录入付款
 */
export async function recordPayment(
  payableId: number,
  amount: number,
  paymentMethod: string,
  paymentDate: string,
  bankAccount?: string,
  referenceNo?: string,
  operatorId?: number
): Promise<{ success: boolean; message: string }> {
  try {
    const result = await transaction(async (conn) => {
      const [payRows]: Loose = await conn.execute(`SELECT * FROM fin_payable WHERE id = ?`, [
        payableId,
      ]);

      if (payRows.length === 0) {
        throw new Error('应付单不存在');
      }

      const payable = payRows[0];
      const currentPaid = parseFloat(payable.paid_amount) || 0;
      const totalAmount = parseFloat(payable.amount);
      const newPaid = currentPaid + amount;

      if (newPaid > totalAmount) {
        throw new Error('付款金额不能超过应付金额');
      }

      const paymentNo = generateDocNo('PY');
      await conn.execute(
        `INSERT INTO fin_payment_record (
          payment_no, payable_id, supplier_id, amount,
          payment_date, payment_method, bank_account, reference_no, handler_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          paymentNo,
          payableId,
          payable.supplier_id,
          amount,
          paymentDate,
          paymentMethod,
          bankAccount || '',
          referenceNo || '',
          operatorId || null,
        ]
      );

      const balance = totalAmount - newPaid;
      const status = balance <= 0 ? 3 : 2;

      await conn.execute(
        `UPDATE fin_payable SET
          paid_amount = ?,
          balance = ?,
          status = ?,
          update_time = NOW()
        WHERE id = ?`,
        [newPaid, balance, status, payableId]
      );

      return { paymentNo, newPaid, balance };
    });

    secureLog('info', '付款录入成功', { payableId, amount, paymentNo: result.paymentNo });

    return {
      success: true,
      message: `付款录入成功，已付${result.newPaid}，余额${result.balance}`,
    };
  } catch (error) {
    secureLog('error', '付款录入失败', { error: (error as Error).message, payableId });
    return { success: false, message: `录入失败: ${(error as Error).message}` };
  }
}

