export function generateDocNo(prefix: string): string {
  const now = new Date();
  const dateStr =
    now.getFullYear() +
    String(now.getMonth() + 1).padStart(2, '0') +
    String(now.getDate()).padStart(2, '0');
  const serialLen = getSerialNumberLength();
  const maxSerial = Math.pow(10, serialLen);
  const random = String(Math.floor(Math.random() * (maxSerial - 1)) + 1).padStart(serialLen, '0');
  return `${prefix}${dateStr}${random}`;
}

/**
 * @module global-export-service
 * @description 全局统一导出服务 — 支持 Excel/PDF/Word/CSV/Print 五种格式。
 *   前端通用，无需后端配合。所有表格页面统一调用本服务。
 *
 *   支持的导出格式:
 *   - Excel (.xlsx) — 基于 SheetJS (xlsx)
 *   - PDF (.pdf) — 基于 jsPDF + autoTable
 *   - Word (.docx) — 基于 docx 库
 *   - CSV (.csv) — 原生实现，带 BOM
 *   - Print — 浏览器原生打印
 *
 *   使用方式:
 *   ```ts
 *   GlobalExportService.export({
 *     format: 'excel',
 *     filename: '销售订单列表',
 *     title: '销售订单列表',
 *     columns: [
 *       { key: 'orderNo', label: '订单号', width: 20 },
 *       { key: 'customer', label: '客户', width: 30 },
 *     ],
 *     data: [
 *       { orderNo: 'SO-001', customer: '客户A' },
 *     ],
 *   });
 *   ```
 */

import * as XLSX from '@e965/xlsx';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import {
  Document,
  Packer,
  Paragraph,
  Table,
  TableCell,
  TableRow,
  TextRun,
  HeadingLevel,
  AlignmentType,
  WidthType,
} from 'docx';
import { saveAs } from 'file-saver';

// ──────────────────────────────────────────────
// 类型定义
// ──────────────────────────────────────────────

export type ExportFormat = 'excel' | 'pdf' | 'word' | 'csv' | 'print';

export interface ExportColumn {
  /** 数据键 */
  key: string;
  /** 列标题 */
  label: string;
  /** 列宽（Excel 列宽 / PDF 列宽百分比） */
  width?: number;
  /** 值格式化函数 */
  formatter?: (value: Loose, row: Loose) => string | number;
}

export interface ExportOptions {
  /** 导出格式 */
  format: ExportFormat;
  /** 文件名（不含扩展名） */
  filename: string;
  /** 报表标题（显示在文档顶部） */
  title?: string;
  /** 列定义 */
  columns: ExportColumn[];
  /** 数据行 */
  data: Record<string, Loose>[];
  /** 副标题/描述 */
  subtitle?: string;
  /** 是否横向（仅 PDF） */
  landscape?: boolean;
  /** 页脚信息 */
  footer?: string;
  /** 导出时间（默认当前时间） */
  exportTime?: Date;
}

// ──────────────────────────────────────────────
// 服务实现
// ──────────────────────────────────────────────

class GlobalExportServiceClass {
  /**
   * 统一导出入口
   */
  async export(options: ExportOptions): Promise<void> {
    switch (options.format) {
      case 'excel':
        return this.exportToExcel(options);
      case 'pdf':
        return this.exportToPDF(options);
      case 'word':
        return this.exportToWord(options);
      case 'csv':
        return this.exportToCSV(options);
      case 'print':
        return this.print(options);
      default:
        throw new Error(`不支持的导出格式: ${options.format}`);
    }
  }

  // ─── Excel 导出 ───

  async exportToExcel(options: ExportOptions): Promise<void> {
    const { filename, title, columns, data, exportTime } = options;
    const now = exportTime || new Date();

    // 构建工作表数据
    const header = columns.map((c) => c.label);
    const rows = data.map((row) =>
      columns.map((col) => {
        const rawValue = row[col.key];
        if (col.formatter) return col.formatter(rawValue, row);
        return rawValue ?? '';
      })
    );

    // 添加标题行和导出时间
    const sheetData: (string | number)[][] = [];
    if (title) {
      sheetData.push([title]);
      sheetData.push([`导出时间: ${now.toLocaleString('zh-CN')}`]);
      sheetData.push([]);
    }
    sheetData.push(header);
    sheetData.push(...rows);

    const ws = XLSX.utils.aoa_to_sheet(sheetData);

    // 设置列宽
    ws['!cols'] = columns.map((c) => ({ wch: c.width || 15 }));

    // 合并标题行
    if (title) {
      ws['!merges'] = [
        { s: { r: 0, c: 0 }, e: { r: 0, c: columns.length - 1 } },
        { s: { r: 1, c: 0 }, e: { r: 1, c: columns.length - 1 } },
      ];
    }

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Sheet1');

    const buffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([buffer], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    });
    saveAs(blob, `${filename}.xlsx`);
  }

  // ─── PDF 导出 ───

  async exportToPDF(options: ExportOptions): Promise<void> {
    const { filename, title, columns, data, subtitle, landscape, footer, exportTime } = options;
    const now = exportTime || new Date();

    const doc = new jsPDF({
      orientation: landscape ? 'landscape' : 'portrait',
      unit: 'mm',
      format: 'a4',
    });

    // 设置中文字体（使用 jsPDF 内置的 Helvetica 作为 fallback）
    // 注: 完整中文支持需嵌入中文字体文件，此处用英文标题 + 中文数据

    // 标题
    if (title) {
      doc.setFontSize(16);
      doc.text(title, 14, 15);
    }

    // 副标题/导出时间
    doc.setFontSize(9);
    doc.setTextColor(128);
    const subtitleText = subtitle
      ? `${subtitle}  |  ${now.toLocaleString('zh-CN')}`
      : `Export: ${now.toLocaleString('zh-CN')}`;
    doc.text(subtitleText, 14, title ? 21 : 15);
    doc.setTextColor(0);

    // 表格
    const head = [columns.map((c) => c.label)];
    const body = data.map((row) =>
      columns.map((col) => {
        const rawValue = row[col.key];
        if (col.formatter) return String(col.formatter(rawValue, row));
        return String(rawValue ?? '');
      })
    );

    autoTable(doc, {
      head,
      body,
      startY: title ? 25 : 19,
      styles: {
        fontSize: 8,
        cellPadding: 1.5,
        overflow: 'linebreak',
      },
      headStyles: {
        fillColor: [37, 99, 235],
        textColor: 255,
        fontStyle: 'bold',
      },
      alternateRowStyles: {
        fillColor: [245, 247, 250],
      },
      columnStyles: columns.reduce(
        (acc, col, idx) => {
          if (col.width) {
            acc[idx] = { cellWidth: col.width };
          }
          return acc;
        },
        {} as Record<number, { cellWidth: number }>
      ),
    });

    // 页脚
    const finalY = (doc as Loose).lastAutoTable?.finalY || 25;
    if (footer) {
      doc.setFontSize(8);
      doc.setTextColor(128);
      doc.text(footer, 14, finalY + 10);
    }

    // 页码
    const pageCount = doc.getNumberOfPages();
    for (let i = 1; i <= pageCount; i++) {
      doc.setPage(i);
      doc.setFontSize(8);
      doc.setTextColor(128);
      doc.text(
        `Page ${i} / ${pageCount}`,
        doc.internal.pageSize.getWidth() - 30,
        doc.internal.pageSize.getHeight() - 8
      );
    }

    doc.save(`${filename}.pdf`);
  }

  // ─── Word 导出 ───

  async exportToWord(options: ExportOptions): Promise<void> {
    const { filename, title, columns, data, subtitle, exportTime } = options;
    const now = exportTime || new Date();

    // 标题段落
    const children: (Paragraph | Table)[] = [];

    if (title) {
      children.push(
        new Paragraph({
          text: title,
          heading: HeadingLevel.HEADING_1,
          alignment: AlignmentType.CENTER,
        })
      );
    }

    children.push(
      new Paragraph({
        children: [
          new TextRun({
            text: subtitle
              ? `${subtitle}  |  导出时间: ${now.toLocaleString('zh-CN')}`
              : `导出时间: ${now.toLocaleString('zh-CN')}`,
            size: 18,
            color: '808080',
          }),
        ],
        alignment: AlignmentType.RIGHT,
      })
    );

    children.push(new Paragraph({ text: '' })); // 空行

    // 表格
    const headerRow = new TableRow({
      tableHeader: true,
      children: columns.map(
        (col) =>
          new TableCell({
            children: [
              new Paragraph({
                children: [new TextRun({ text: col.label, bold: true, size: 20 })],
                alignment: AlignmentType.CENTER,
              }),
            ],
            shading: { fill: '2563EB' },
          })
      ),
    });

    const dataRows = data.map(
      (row) =>
        new TableRow({
          children: columns.map((col) => {
            const rawValue = row[col.key];
            const displayValue = col.formatter
              ? String(col.formatter(rawValue, row))
              : String(rawValue ?? '');
            return new TableCell({
              children: [
                new Paragraph({
                  children: [new TextRun({ text: displayValue, size: 20 })],
                }),
              ],
            });
          }),
        })
    );

    const table = new Table({
      rows: [headerRow, ...dataRows],
      width: { size: 100, type: WidthType.PERCENTAGE },
    });

    children.push(table);

    if (options.footer) {
      children.push(new Paragraph({ text: '' }));
      children.push(
        new Paragraph({
          children: [new TextRun({ text: options.footer, size: 16, color: '808080' })],
        })
      );
    }

    const doc = new Document({
      sections: [{ children }],
    });

    const blob = await Packer.toBlob(doc);
    saveAs(blob, `${filename}.docx`);
  }

  // ─── CSV 导出 ───

  async exportToCSV(options: ExportOptions): Promise<void> {
    const { filename, columns, data, exportTime } = options;
    const _now = exportTime || new Date();

    const header = columns.map((c) => this.escapeCSV(c.label)).join(',');
    const rows = data.map((row) =>
      columns
        .map((col) => {
          const rawValue = row[col.key];
          const value = col.formatter ? col.formatter(rawValue, row) : (rawValue ?? '');
          return this.escapeCSV(String(value));
        })
        .join(',')
    );

    // BOM + 内容
    const csv = '\uFEFF' + [header, ...rows].join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    saveAs(blob, `${filename}.csv`);
  }

  // ─── 打印 ───

  async print(options: ExportOptions): Promise<void> {
    const { title, columns, data, subtitle, exportTime } = options;
    const now = exportTime || new Date();

    const printWindow = window.open('', '_blank', 'width=1024,height=768');
    if (!printWindow) {
      alert('请允许弹出窗口以使用打印功能');
      return;
    }

    const head = columns.map((c) => `<th>${c.label}</th>`).join('');
    const body = data
      .map(
        (row) =>
          `<tr>${columns
            .map((col) => {
              const rawValue = row[col.key];
              const value = col.formatter ? col.formatter(rawValue, row) : (rawValue ?? '');
              return `<td>${value}</td>`;
            })
            .join('')}</tr>`
      )
      .join('');

    printWindow.document.write(`
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="utf-8">
        <title>${title || '打印'}</title>
        <style>
          @page { size: A4; margin: 15mm; }
          body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; color: #1a1a2e; }
          h1 { font-size: 18px; text-align: center; margin-bottom: 5px; }
          .meta { text-align: right; font-size: 11px; color: #64748b; margin-bottom: 15px; }
          table { width: 100%; border-collapse: collapse; font-size: 12px; }
          th { background: #2563EB; color: #fff; padding: 6px 8px; text-align: left; font-weight: 600; }
          td { padding: 5px 8px; border-bottom: 1px solid #e2e8f0; }
          tr:nth-child(even) td { background: #f8fafc; }
          .footer { margin-top: 20px; font-size: 10px; color: #94a3b8; text-align: center; }
        </style>
      </head>
      <body>
        ${title ? `<h1>${title}</h1>` : ''}
        <div class="meta">${subtitle ? `${subtitle} | ` : ''}导出时间: ${now.toLocaleString('zh-CN')}</div>
        <table>
          <thead><tr>${head}</tr></thead>
          <tbody>${body}</tbody>
        </table>
        ${options.footer ? `<div class="footer">${options.footer}</div>` : ''}
      </body>
      </html>
    `);
    printWindow.document.close();
    printWindow.focus();
    setTimeout(() => {
      printWindow.print();
    }, 500);
  }

  // ─── 工具方法 ───

  private escapeCSV(value: string): string {
    if (value.includes(',') || value.includes('"') || value.includes('\n')) {
      return `"${value.replace(/"/g, '""')}"`;
    }
    return value;
  }
}

export const GlobalExportService = new GlobalExportServiceClass();

/**
 * @module global-import-service
 * @description 全局统一导入服务 — 支持 Excel/CSV 文件解析、Zod 校验、错误报告。
 *   前端通用，配合 <GlobalImportDialog> 组件使用。
 *
 *   使用方式:
 *   ```ts
 *   const result = await GlobalImportService.parseAndValidate(file, {
 *     columns: [
 *       { key: 'materialCode', label: '物料编码', required: true },
 *       { key: 'materialName', label: '物料名称', required: true },
 *       { key: 'quantity', label: '数量', type: 'number', required: true },
 *     ],
 *     onValidate: (row) => {
 *       if (row.quantity <= 0) return '数量必须大于0';
 *       return null;
 *     },
 *   });
 *   // result.validRows, result.invalidRows, result.errors
 *   ```
 */

import * as XLSX from '@e965/xlsx';

// ──────────────────────────────────────────────
// 类型定义
// ──────────────────────────────────────────────

export interface ImportColumn {
  /** 数据键 */
  key: string;
  /** 列标题（用于匹配 Excel 列头） */
  label: string;
  /** 是否必填 */
  required?: boolean;
  /** 值类型 */
  type?: 'string' | 'number' | 'date';
  /** 默认值 */
  defaultValue?: Loose;
}

export interface ImportOptions {
  /** 列定义 */
  columns: ImportColumn[];
  /** 自定义校验函数（返回错误消息或 null） */
  onValidate?: (row: Record<string, Loose>, rowIndex: number) => string | null;
  /** 跳过空行 */
  skipEmptyRows?: boolean;
  /** 最大行数 */
  maxRows?: number;
}

export interface ImportRowResult {
  row: Record<string, Loose>;
  rowIndex: number;
  valid: boolean;
  errors: string[];
}

export interface ImportResult {
  /** 有效行 */
  validRows: Record<string, Loose>[];
  /** 无效行 */
  invalidRows: ImportRowResult[];
  /** 总行数 */
  totalRows: number;
  /** 有效行数 */
  validCount: number;
  /** 无效行数 */
  invalidCount: number;
  /** 是否有错误 */
  hasErrors: boolean;
}

export interface ImportTemplateOptions {
  /** 模板文件名 */
  filename: string;
  /** 列定义 */
  columns: ImportColumn[];
  /** 示例数据 */
  sampleData?: Record<string, Loose>[];
  /** 模板说明 */
  description?: string;
}

// ──────────────────────────────────────────────
// 服务实现
// ──────────────────────────────────────────────

class GlobalImportServiceClass {
  /**
   * 解析 Excel/CSV 文件并校验
   */
  async parseAndValidate(file: File, options: ImportOptions): Promise<ImportResult> {
    const buffer = await file.arrayBuffer();
    const workbook = XLSX.read(buffer, { type: 'array' });
    const sheetName = workbook.SheetNames[0];
    const sheet = workbook.Sheets[sheetName];

    // 转为 JSON，使用列标题作为 key
    const rawData: Record<string, Loose>[] = XLSX.utils.sheet_to_json(sheet, {
      defval: '',
      raw: false,
    });

    return this.validateData(rawData, options);
  }

  /**
   * 校验已解析的数据
   */
  validateData(rawData: Record<string, Loose>[], options: ImportOptions): ImportResult {
    const { columns, onValidate, skipEmptyRows = true, maxRows = 10000 } = options;

    // 列标题 → 列定义的映射（支持模糊匹配）
    const labelToColumn = new Map<string, ImportColumn>();
    for (const col of columns) {
      labelToColumn.set(col.label, col);
      labelToColumn.set(col.key, col);
      // 去空格匹配
      labelToColumn.set(col.label.trim(), col);
    }

    const validRows: Record<string, Loose>[] = [];
    const invalidRows: ImportRowResult[] = [];
    const totalRows = Math.min(rawData.length, maxRows);

    for (let i = 0; i < totalRows; i++) {
      const rawRow = rawData[i];

      // 跳过空行
      if (skipEmptyRows && this.isEmptyRow(rawRow)) {
        continue;
      }

      // 映射列
      const mappedRow: Record<string, Loose> = {};
      const errors: string[] = [];

      for (const col of columns) {
        let value: Loose = '';

        // 尝试匹配列标题
        for (const [label, colDef] of labelToColumn.entries()) {
          if (colDef.key === col.key && rawRow[label] !== undefined && rawRow[label] !== '') {
            value = rawRow[label];
            break;
          }
        }

        // 类型转换
        if (col.type === 'number') {
          value = value === '' || value === null ? null : parseFloat(value);
          if (isNaN(value as number)) value = null;
        } else if (col.type === 'date') {
          if (value) {
            const date = new Date(value);
            value = isNaN(date.getTime()) ? value : date.toISOString().slice(0, 10);
          }
        }

        // 默认值
        if (
          (value === null || value === '' || value === undefined) &&
          col.defaultValue !== undefined
        ) {
          value = col.defaultValue;
        }

        // 必填校验
        if (col.required && (value === null || value === '' || value === undefined)) {
          errors.push(`列"${col.label}"不能为空`);
        }

        mappedRow[col.key] = value;
      }

      // 自定义校验
      if (onValidate) {
        const customError = onValidate(mappedRow, i);
        if (customError) {
          errors.push(customError);
        }
      }

      if (errors.length > 0) {
        invalidRows.push({ row: mappedRow, rowIndex: i + 1, valid: false, errors });
      } else {
        validRows.push(mappedRow);
      }
    }

    return {
      validRows,
      invalidRows,
      totalRows,
      validCount: validRows.length,
      invalidCount: invalidRows.length,
      hasErrors: invalidRows.length > 0,
    };
  }

  /**
   * 生成导入模板
   */
  async downloadTemplate(options: ImportTemplateOptions): Promise<void> {
    const { filename, columns, sampleData, description } = options;

    const header = columns.map((c) => c.label);
    const sheetData: (string | number)[][] = [];

    if (description) {
      sheetData.push([description]);
      sheetData.push([]);
    }

    sheetData.push(header);

    // 添加示例数据
    if (sampleData && sampleData.length > 0) {
      for (const sample of sampleData) {
        sheetData.push(columns.map((col) => sample[col.key] ?? ''));
      }
    }

    // 添加说明行
    sheetData.push([]);
    sheetData.push(['字段说明:']);
    for (const col of columns) {
      const req = col.required ? ' (必填)' : ' (选填)';
      const type = col.type ? ` [${col.type}]` : '';
      sheetData.push([`${col.label}${req}${type}`]);
    }

    const ws = XLSX.utils.aoa_to_sheet(sheetData);
    ws['!cols'] = columns.map(() => ({ wch: 20 }));

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, '导入模板');

    const buffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([buffer], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    });

    const { saveAs } = await import('file-saver');
    saveAs(blob, `${filename}_导入模板.xlsx`);
  }

  /**
   * 检查是否为空行
   */
  private isEmptyRow(row: Record<string, Loose>): boolean {
    return Object.values(row).every((v) => v === '' || v === null || v === undefined);
  }
}

export const GlobalImportService = new GlobalImportServiceClass();

export interface PerformanceResult {
  baseAmount: number;
  kpiScore: number;
  qualityRate: number;
  scoreCoefficient: number;
  finalAmount: number;
}

interface KpiDimension {
  name: string;
  weight: number;    // 权重 %
  score: number;     // 得分 0-100
}

const DEFAULT_DIMENSIONS: KpiDimension[] = [
  { name: '产量达成率', weight: 40, score: 0 },
  { name: '质量合格率', weight: 30, score: 0 },
  { name: '设备稼动率', weight: 15, score: 0 },
  { name: '5S现场管理', weight: 15, score: 0 },
];

/**
 * 计算绩效奖金
 * @param baseAmount 绩效基数
 * @param dimensions 各维度评分（使用默认维度及权重）
 * @param qualityRate 质量达标率 (0-1)
 */
export function calculatePerformanceBonus(
  baseAmount: number,
  dimensions: KpiDimension[] = DEFAULT_DIMENSIONS,
  qualityRate: number = 1
): PerformanceResult {
  const totalWeight = dimensions.reduce((s, d) => s + d.weight, 0);
  const weightedScore = dimensions.reduce(
    (s, d) => s + (d.score * d.weight) / totalWeight,
    0
  );
  const scoreCoefficient = weightedScore / 100;
  const finalAmount = baseAmount * scoreCoefficient * qualityRate;

  return {
    baseAmount,
    kpiScore: weightedScore,
    qualityRate,
    scoreCoefficient,
    finalAmount: Math.round(finalAmount * 100) / 100,
  };
}

/**
 * 综合KPI评分（带行业默认权重）
 */
export function calculateKpiScore(
  productionRate: number,   // 产量达成率 0-1
  qualityRate: number,      // 质量合格率 0-1
  equipmentRate: number,    // 设备稼动率 0-1
  siteScore: number         // 5S评分 0-100
): number {
  return (
    productionRate * 100 * 0.4 +
    qualityRate * 100 * 0.3 +
    equipmentRate * 100 * 0.15 +
    siteScore * 0.15
  );
}

import { headers } from 'next/headers';

// 支持的语言列表
export const locales = ['en', 'zh-CN', 'zh-TW', 'vi'] as const;
export type Locale = (typeof locales)[number];

// 默认语言
export const defaultLocale: Locale = 'zh-CN';

/**
 * 从请求头获取语言设置
 */
export async function getLocaleFromHeader(): Promise<Locale> {
  try {
    const headersList = await headers();
    const acceptLanguage = headersList.get('accept-language') || '';

    // 解析 Accept-Language 头
    const languages = acceptLanguage.split(',').map((lang) => {
      const [code] = lang.trim().split(';');
      return code.trim().substring(0, 5); // 取前5个字符,如 zh-CN
    });

    // 查找匹配的语言
    for (const lang of languages) {
      if (locales.includes(lang as Locale)) {
        return lang as Locale;
      }
      // 处理简写,如 zh -> zh-CN
      if (lang === 'zh') {
        return 'zh-CN';
      }
    }

    return defaultLocale;
  } catch {
    return defaultLocale;
  }
}

/**
 * 加载指定语言的翻译文件
 */
export async function getTranslations(locale: Locale) {
  try {
    const messages = (await import(`../../messages/${locale}.json`)).default;
    return messages;
  } catch {
    // 如果加载失败,返回默认语言
    const messages = (await import(`../../messages/${defaultLocale}.json`)).default;
    return messages;
  }
}

/**
 * 获取翻译函数
 */
export async function getTranslator(namespace?: string) {
  const locale = await getLocaleFromHeader();
  const messages = await getTranslations(locale);

  return (key: string, params?: Record<string, Loose>): string => {
    const fullKey = namespace ? `${namespace}.${key}` : key;
    const keys = fullKey.split('.');

    let value: Loose = messages;
    for (const k of keys) {
      value = value?.[k];
      if (value === undefined) {
        // 如果找不到翻译,返回键名
        return fullKey;
      }
    }

    if (typeof value !== 'string') {
      return fullKey;
    }

    // 处理插值参数
    if (params) {
      return Object.entries(params).reduce(
        (str, [k, v]) => str.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v)),
        value
      );
    }

    return value;
  };
}

/**
 * 导出专用的翻译辅助函数
 */
export async function getExportTranslator() {
  return getTranslator('Export');
}

import { query, transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';
import { logInventoryChange } from './audit-logger';
import type mysql from 'mysql2/promise';

export interface InventoryAdjustment {
  materialId: number;
  warehouseId: number;
  batchNo?: string;
  quantity: number; // 正数增加，负数减少
  operationType: 'inbound' | 'outbound' | 'adjust' | 'transfer' | 'scrap';
  businessType: string;
  businessNo: string;
  remark?: string;
  operatorId?: number;
}

export interface InventoryCheckResult {
  success: boolean;
  message: string;
  currentStock?: number;
  availableStock?: number;
}

/**
 * 检查库存是否充足（防止负库存）
 * @param conn - 可选事务连接；传入时在事务内读取（读到未提交数据），否则使用独立查询
 */
export async function checkInventoryAvailability(
  materialId: number,
  warehouseId: number,
  requiredQty: number,
  batchNo?: string,
  conn?: mysql.PoolConnection
): Promise<InventoryCheckResult> {
  try {
    let sql = `
      SELECT quantity, locked_qty, available_qty
      FROM inv_inventory
      WHERE material_id = ? AND warehouse_id = ? AND deleted = 0
    `;
    const params: Loose[] = [materialId, warehouseId];

    if (batchNo) {
      sql += ' AND batch_no = ?';
      params.push(batchNo);
    }

    let rows: Loose;
    if (conn) {
      const [result] = await conn.execute(sql, params);
      rows = result as Loose;
    } else {
      rows = await query(sql, params);
    }

    if (rows.length === 0) {
      return {
        success: false,
        message: `物料ID ${materialId} 在仓库 ${warehouseId} 无库存记录`,
        currentStock: 0,
        availableStock: 0,
      };
    }

    const stock = rows[0];
    const availableQty = parseFloat(stock.available_qty || '0');

    if (availableQty < requiredQty) {
      return {
        success: false,
        message: `库存不足: 可用 ${availableQty}, 需要 ${requiredQty}`,
        currentStock: parseFloat(stock.quantity || '0'),
        availableStock: availableQty,
      };
    }

    return {
      success: true,
      message: '库存充足',
      currentStock: parseFloat(stock.quantity || '0'),
      availableStock: availableQty,
    };
  } catch (error) {
    secureLog('error', '库存检查失败', {
      error: (error as Error).message,
      materialId,
      warehouseId,
    });
    return {
      success: false,
      message: '库存检查异常，请稍后重试',
    };
  }
}

/**
 * 调整库存（统一入口）
 * 每次调整自动记录库存流水
 * @param conn - 可选事务连接；传入时复用外层事务（不自行 begin/commit，回滚随外层），
 *   否则独立开启事务。解决嵌套事务导致"外层回滚但库存已扣"的问题。
 */
export async function adjustInventory(
  adjustment: InventoryAdjustment,
  conn?: mysql.PoolConnection
): Promise<InventoryCheckResult> {
  const {
    materialId,
    warehouseId,
    batchNo = '',
    quantity,
    operationType,
    businessType,
    businessNo,
    remark = '',
    operatorId,
  } = adjustment;

  // 出库时检查库存
  if (quantity < 0) {
    const checkResult = await checkInventoryAvailability(
      materialId,
      warehouseId,
      Math.abs(quantity),
      batchNo || undefined,
      conn
    );
    if (!checkResult.success) {
      return checkResult;
    }
  }

  try {
    // 若外层已传入事务连接，直接复用（不自行 begin/commit，回滚随外层）；
    // 否则独立开启事务（保持向后兼容）。
    const runInTransaction = <T,>(
      cb: (c: mysql.PoolConnection) => Promise<T>
    ): Promise<T> => (conn ? cb(conn) : transaction(cb));

    const result = await runInTransaction(async (txConn) => {
      // 1. 获取当前库存
      let selectSql = `
        SELECT id, quantity, locked_qty, available_qty, version
        FROM inv_inventory
        WHERE material_id = ? AND warehouse_id = ? AND deleted = 0
      `;
      const selectParams: Loose[] = [materialId, warehouseId];

      if (batchNo) {
        selectSql += ' AND batch_no = ?';
        selectParams.push(batchNo);
      } else {
        selectSql += ' AND (batch_no IS NULL OR batch_no = "")';
      }

      const [inventoryRows]: Loose = await txConn.execute(selectSql, selectParams);

      let inventoryId: number;
      let beforeQty: number;
      let beforeLockedQty: number;
      let beforeAvailableQty: number;

      if (inventoryRows.length === 0) {
        // 库存记录不存在，入库时创建
        if (quantity < 0) {
          throw new Error('库存记录不存在，无法出库');
        }

        secureLog('info', 'adjustInventory 创建新库存记录', {
          operation: 'adjustInventory',
          materialId,
          warehouseId,
          batchNo,
          initialQty: quantity,
          businessNo,
        });

        const [insertResult]: Loose = await txConn.execute(
          `INSERT INTO inv_inventory (
            material_id, warehouse_id, batch_no, quantity, locked_qty, available_qty
          ) VALUES (?, ?, ?, ?, 0, ?)`,
          [materialId, warehouseId, batchNo || null, quantity, quantity]
        );
        inventoryId = insertResult.insertId;
        beforeQty = 0;
        beforeLockedQty = 0;
        beforeAvailableQty = 0;
      } else {
        const inv = inventoryRows[0];
        inventoryId = inv.id;
        beforeQty = parseFloat(inv.quantity || '0');
        beforeLockedQty = parseFloat(inv.locked_qty || '0');
        beforeAvailableQty = parseFloat(inv.available_qty || '0');
        const currentVersion = parseInt(inv.version || '1', 10);

        // 读取到的库存状态（用于排查并发问题）
        secureLog('debug', 'adjustInventory 读取当前库存', {
          operation: 'adjustInventory',
          materialId,
          warehouseId,
          batchNo,
          inventoryId,
          currentVersion,
          beforeQty,
          beforeLockedQty,
          beforeAvailableQty,
          adjustQty: quantity,
          businessNo,
        });

        // 计算新库存
        const newQty = beforeQty + quantity;
        const newAvailableQty = beforeAvailableQty + quantity;

        if (newQty < 0) {
          throw new Error(`库存不足: 当前 ${beforeQty}, 调整 ${quantity}, 结果 ${newQty}`);
        }
        if (newAvailableQty < 0) {
          throw new Error(`可用库存不足: 当前可用 ${beforeAvailableQty}, 调整 ${quantity}`);
        }

        // 更新库存（乐观锁：带 version 条件，自增 version）
        secureLog('debug', 'adjustInventory 执行 UPDATE', {
          operation: 'adjustInventory',
          inventoryId,
          expectedVersion: currentVersion,
          beforeQty,
          newQty,
          beforeAvailableQty,
          newAvailableQty,
          businessNo,
        });

        const [updateResult]: Loose = await txConn.execute(
          `UPDATE inv_inventory SET
            quantity = ?,
            available_qty = ?,
            version = version + 1,
            update_time = NOW()
          WHERE id = ? AND version = ?`,
          [newQty, newAvailableQty, inventoryId, currentVersion]
        );

        secureLog('debug', 'adjustInventory UPDATE 结果', {
          operation: 'adjustInventory',
          inventoryId,
          affectedRows: updateResult.affectedRows,
          expectedVersion: currentVersion,
          newVersion: currentVersion + 1,
          businessNo,
        });

        // 乐观锁冲突检测：affectedRows=0 表示 version 已被其他事务修改
        if (updateResult.affectedRows === 0) {
          secureLog('warn', '乐观锁并发冲突', {
            operation: 'adjustInventory',
            materialId,
            warehouseId,
            batchNo,
            inventoryId,
            expectedVersion: currentVersion,
            beforeQty,
            beforeAvailableQty,
            adjustQty: quantity,
            businessNo,
          });
          throw new Error('并发冲突: 库存已被其他事务修改，请重试');
        }
      }

      // 2. 记录库存流水（不可修改、不可删除）
      const afterQty = beforeQty + quantity;
      const operationTypeMap: Record<string, number> = {
        inbound: 1,
        outbound: 2,
        adjust: 3,
        transfer: 4,
        scrap: 5,
      };

      await txConn.execute(
        `INSERT INTO inv_inventory_log (
          material_id, warehouse_id, batch_no, operation_type, operation_qty,
          before_qty, after_qty, business_type, business_no, remark, operator_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          materialId,
          warehouseId,
          batchNo || null,
          operationTypeMap[operationType] || 3,
          Math.abs(quantity),
          beforeQty,
          afterQty,
          businessType,
          businessNo,
          remark,
          operatorId || null,
        ]
      );

      return {
        inventoryId,
        beforeQty,
        afterQty,
        adjustmentQty: quantity,
      };
    });

    // 记录审计日志
    await logInventoryChange({
      materialId,
      warehouseId,
      batchNo,
      operationType,
      quantity: Math.abs(quantity),
      beforeQty: result.beforeQty,
      afterQty: result.afterQty,
      businessType,
      businessNo,
      operatorId,
    });

    // 检查负库存预警
    if (result.afterQty < 0) {
      secureLog('warn', '负库存预警', {
        materialId,
        warehouseId,
        afterQty: result.afterQty,
        businessNo,
      });
    }

    return {
      success: true,
      message: `库存调整成功: ${result.beforeQty} → ${result.afterQty}`,
      currentStock: result.afterQty,
      availableStock: result.afterQty,
    };
  } catch (error) {
    secureLog('error', '库存调整失败', {
      error: (error as Error).message,
      materialId,
      warehouseId,
      quantity,
      businessNo,
    });
    return {
      success: false,
      message: '库存调整失败，请稍后重试',
    };
  }
}

/**
 * 锁定库存（预留）
 */
export async function lockInventory(
  materialId: number,
  warehouseId: number,
  lockQty: number,
  businessNo: string,
  operatorId?: number
): Promise<InventoryCheckResult> {
  try {
    const checkResult = await checkInventoryAvailability(materialId, warehouseId, lockQty);
    if (!checkResult.success) {
      return checkResult;
    }

    await transaction(async (conn) => {
      const [rows]: Loose = await conn.execute(
        `SELECT id, quantity, locked_qty, available_qty, version
         FROM inv_inventory
         WHERE material_id = ? AND warehouse_id = ? AND deleted = 0`,
        [materialId, warehouseId]
      );

      if (rows.length === 0) {
        throw new Error('库存记录不存在');
      }

      const inv = rows[0];
      const currentLocked = parseFloat(inv.locked_qty || '0');
      const currentAvailable = parseFloat(inv.available_qty || '0');
      const currentVersion = parseInt(inv.version || '1', 10);
      const newLocked = currentLocked + lockQty;
      const newAvailable = currentAvailable - lockQty;

      // 读取到的库存状态（用于排查并发问题）
      secureLog('debug', 'lockInventory 读取当前库存', {
        operation: 'lockInventory',
        materialId,
        warehouseId,
        inventoryId: inv.id,
        currentVersion,
        currentLocked,
        currentAvailable,
        lockQty,
        newLocked,
        newAvailable,
        businessNo,
      });

      if (newAvailable < 0) {
        throw new Error(`可用库存不足，无法锁定: 可用 ${currentAvailable}, 需锁定 ${lockQty}`);
      }

      // 更新库存（乐观锁：带 version 条件，自增 version）
      secureLog('debug', 'lockInventory 执行 UPDATE', {
        operation: 'lockInventory',
        inventoryId: inv.id,
        expectedVersion: currentVersion,
        newLocked,
        newAvailable,
        businessNo,
      });

      const [lockUpdateResult]: Loose = await conn.execute(
        `UPDATE inv_inventory SET
          locked_qty = ?,
          available_qty = ?,
          version = version + 1,
          update_time = NOW()
        WHERE id = ? AND version = ?`,
        [newLocked, newAvailable, inv.id, currentVersion]
      );

      secureLog('debug', 'lockInventory UPDATE 结果', {
        operation: 'lockInventory',
        inventoryId: inv.id,
        affectedRows: lockUpdateResult.affectedRows,
        expectedVersion: currentVersion,
        newVersion: currentVersion + 1,
        businessNo,
      });

      if (lockUpdateResult.affectedRows === 0) {
        secureLog('warn', '乐观锁并发冲突', {
          operation: 'lockInventory',
          materialId,
          warehouseId,
          inventoryId: inv.id,
          expectedVersion: currentVersion,
          currentLocked,
          currentAvailable,
          lockQty,
          businessNo,
        });
        throw new Error('并发冲突: 库存已被其他事务修改，请重试');
      }

      // 记录锁定流水
      await conn.execute(
        `INSERT INTO inv_inventory_log (
          material_id, warehouse_id, operation_type, operation_qty,
          before_qty, after_qty, business_type, business_no, remark, operator_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          materialId,
          warehouseId,
          6, // 6-锁定
          lockQty,
          currentAvailable,
          newAvailable,
          '库存锁定',
          businessNo,
          `锁定库存: ${lockQty}`,
          operatorId || null,
        ]
      );
    });

    return {
      success: true,
      message: `库存锁定成功: ${lockQty}`,
    };
  } catch (error) {
    secureLog('error', '库存锁定失败', {
      error: (error as Error).message,
      materialId,
      warehouseId,
      lockQty,
      businessNo,
    });
    return {
      success: false,
      message: '库存锁定失败，请稍后重试',
    };
  }
}

/**
 * 解锁库存（释放预留）
 */
export async function unlockInventory(
  materialId: number,
  warehouseId: number,
  unlockQty: number,
  businessNo: string,
  operatorId?: number
): Promise<InventoryCheckResult> {
  try {
    await transaction(async (conn) => {
      const [rows]: Loose = await conn.execute(
        `SELECT id, quantity, locked_qty, available_qty, version
         FROM inv_inventory
         WHERE material_id = ? AND warehouse_id = ? AND deleted = 0`,
        [materialId, warehouseId]
      );

      if (rows.length === 0) {
        throw new Error('库存记录不存在');
      }

      const inv = rows[0];
      const currentLocked = parseFloat(inv.locked_qty || '0');
      const currentAvailable = parseFloat(inv.available_qty || '0');
      const currentVersion = parseInt(inv.version || '1', 10);
      const newLocked = Math.max(0, currentLocked - unlockQty);
      const newAvailable = currentAvailable + (currentLocked - newLocked);

      // 读取到的库存状态（用于排查并发问题）
      secureLog('debug', 'unlockInventory 读取当前库存', {
        operation: 'unlockInventory',
        materialId,
        warehouseId,
        inventoryId: inv.id,
        currentVersion,
        currentLocked,
        currentAvailable,
        unlockQty,
        newLocked,
        newAvailable,
        businessNo,
      });

      // 更新库存（乐观锁：带 version 条件，自增 version）
      secureLog('debug', 'unlockInventory 执行 UPDATE', {
        operation: 'unlockInventory',
        inventoryId: inv.id,
        expectedVersion: currentVersion,
        newLocked,
        newAvailable,
        businessNo,
      });

      const [unlockUpdateResult]: Loose = await conn.execute(
        `UPDATE inv_inventory SET
          locked_qty = ?,
          available_qty = ?,
          version = version + 1,
          update_time = NOW()
        WHERE id = ? AND version = ?`,
        [newLocked, newAvailable, inv.id, currentVersion]
      );

      secureLog('debug', 'unlockInventory UPDATE 结果', {
        operation: 'unlockInventory',
        inventoryId: inv.id,
        affectedRows: unlockUpdateResult.affectedRows,
        expectedVersion: currentVersion,
        newVersion: currentVersion + 1,
        businessNo,
      });

      if (unlockUpdateResult.affectedRows === 0) {
        secureLog('warn', '乐观锁并发冲突', {
          operation: 'unlockInventory',
          materialId,
          warehouseId,
          inventoryId: inv.id,
          expectedVersion: currentVersion,
          currentLocked,
          currentAvailable,
          unlockQty,
          businessNo,
        });
        throw new Error('并发冲突: 库存已被其他事务修改，请重试');
      }

      // 记录解锁流水
      await conn.execute(
        `INSERT INTO inv_inventory_log (
          material_id, warehouse_id, operation_type, operation_qty,
          before_qty, after_qty, business_type, business_no, remark, operator_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          materialId,
          warehouseId,
          7, // 7-解锁
          unlockQty,
          currentAvailable,
          newAvailable,
          '库存解锁',
          businessNo,
          `解锁库存: ${unlockQty}`,
          operatorId || null,
        ]
      );
    });

    return {
      success: true,
      message: `库存解锁成功: ${unlockQty}`,
    };
  } catch (error) {
    secureLog('error', '库存解锁失败', {
      error: (error as Error).message,
      materialId,
      warehouseId,
      unlockQty,
      businessNo,
    });
    return {
      success: false,
      message: '库存解锁失败，请稍后重试',
    };
  }
}

/**
 * 获取负库存预警列表
 */
export async function getNegativeStockWarnings(): Promise<Loose[]> {
  const rows: Loose = await query(
    `SELECT
      i.id,
      i.material_id,
      m.material_code,
      m.material_name,
      m.specification,
      i.warehouse_id,
      w.warehouse_name,
      i.quantity,
      i.available_qty,
      i.locked_qty,
      m.safety_stock,
      m.min_stock
    FROM inv_inventory i
    LEFT JOIN inv_material m ON i.material_id = m.id
    LEFT JOIN inv_warehouse w ON i.warehouse_id = w.id
    WHERE i.deleted = 0 AND m.deleted = 0
      AND (i.quantity < 0 OR i.available_qty < 0 OR i.available_qty <= m.safety_stock)
    ORDER BY i.available_qty ASC`
  );

  return rows.map((row: Loose) => ({
    ...row,
    warningType:
      row.quantity < 0 ? 'negative' : row.available_qty < 0 ? 'negative_available' : 'low_stock',
    warningLevel: row.quantity < 0 ? 'critical' : row.available_qty < 0 ? 'critical' : 'warning',
  }));
}

/**
 * 获取库存流水
 */
export async function getInventoryLogs(
  materialId?: number,
  warehouseId?: number,
  operationType?: number,
  startDate?: string,
  endDate?: string,
  page: number = 1,
  pageSize: number = 50
): Promise<{ list: Loose[]; total: number }> {
  let sql = `
    SELECT
      l.*,
      m.material_code,
      m.material_name,
      w.warehouse_name,
      u.username as operator_name
    FROM inv_inventory_log l
    LEFT JOIN inv_material m ON l.material_id = m.id
    LEFT JOIN inv_warehouse w ON l.warehouse_id = w.id
    LEFT JOIN sys_user u ON l.operator_id = u.id
    WHERE 1=1
  `;
  const params: Loose[] = [];

  if (materialId) {
    sql += ' AND l.material_id = ?';
    params.push(materialId);
  }
  if (warehouseId) {
    sql += ' AND l.warehouse_id = ?';
    params.push(warehouseId);
  }
  if (operationType) {
    sql += ' AND l.operation_type = ?';
    params.push(operationType);
  }
  if (startDate) {
    sql += ' AND l.create_time >= ?';
    params.push(startDate);
  }
  if (endDate) {
    sql += ' AND l.create_time <= ?';
    params.push(endDate);
  }

  const countSql = sql.replace(/SELECT.*?FROM/, 'SELECT COUNT(*) as total FROM');
  const countResult: Loose = await query(countSql, params);
  const total = countResult[0]?.total || 0;

  sql += ' ORDER BY l.create_time DESC LIMIT ? OFFSET ?';
  params.push(pageSize, (page - 1) * pageSize);

  const rows: Loose = await query(sql, params);

  const operationTypeLabels: Record<number, string> = {
    1: '入库',
    2: '出库',
    3: '盘点调整',
    4: '调拨',
    5: '报废',
    6: '锁定',
    7: '解锁',
  };

  return {
    list: rows.map((row: Loose) => ({
      ...row,
      operation_type_label: operationTypeLabels[row.operation_type] || '未知',
    })),
    total,
  };
}

