/**
 * 计算经济订购批量（EOQ）
 *
 * 使用经典的 EOQ 公式：EOQ = sqrt(2 × 年需求 × 订购成本 / 单位持有成本)
 * 其中单位持有成本 = 单价 × 持有成本率
 *
 * @param annualDemand - 年需求量
 * @param orderingCost - 每次订购成本
 * @param holdingCostRate - 持有成本率（小数，如 0.2 表示 20%）
 * @param unitPrice - 物料单价
 * @returns 经济订购批量，若任何参数 ≤ 0 则返回 0
 */
export function calculateEOQ(
  annualDemand: number,
  orderingCost: number,
  holdingCostRate: number,
  unitPrice: number
): number {
  if (annualDemand <= 0 || orderingCost <= 0 || holdingCostRate <= 0 || unitPrice <= 0) {
    return 0;
  }
  const holdingCost = unitPrice * holdingCostRate;
  return Math.sqrt((2 * annualDemand * orderingCost) / holdingCost);
}

/**
 * 应用批量化规则调整订单数量
 *
 * 支持四种策略：
 * - lot_for_lot：按需订购，不做调整
 * - fixed：按固定批量向上取整
 * - eoq：按经济订购批量向上取整
 * - period_supply：按需订购（周期内合并由上游处理）
 *
 * @param netRequirement - 净需求数量
 * @param lotSizing - 批量化策略类型
 * @param fixedLotSize - 固定批量大小
 * @param eoq - 经济订购批量
 * @param periodSupplyDays - 供应周期天数（暂未使用）
 * @returns 调整后的计划订单数量，净需求 ≤ 0 时返回 0
 */
export function applyLotSizing(
  netRequirement: number,
  lotSizing: LotSizingType,
  fixedLotSize: number = 0,
  eoq: number = 0,
  _periodSupplyDays: number = 0
): number {
  if (netRequirement <= 0) return 0;

  switch (lotSizing) {
    case 'lot_for_lot':
      return netRequirement;

    case 'fixed':
      if (fixedLotSize <= 0) return netRequirement;
      return Math.ceil(netRequirement / fixedLotSize) * fixedLotSize;

    case 'eoq':
      if (eoq <= 0) return netRequirement;
      return Math.ceil(netRequirement / eoq) * eoq;

    case 'period_supply':
      return netRequirement;

    default:
      return netRequirement;
  }
}

/**
 * 计算安全库存量
 *
 * 支持三种策略：
 * - none：不使用安全库存，返回 0
 * - fixed：使用固定的安全库存值
 * - days_of_coverage：按日均需求 × 覆盖天数计算
 *
 * @param policy - 安全库存策略
 * @param fixedSafetyStock - 固定安全库存量（policy 为 'fixed' 时使用）
 * @param dailyAvgDemand - 日均需求量
 * @param daysOfCoverage - 覆盖天数（policy 为 'days_of_coverage' 时使用）
 * @returns 计算得到的安全库存量
 */
export function calculateSafetyStock(
  policy: 'fixed' | 'days_of_coverage' | 'none',
  fixedSafetyStock: number,
  dailyAvgDemand: number,
  daysOfCoverage: number
): number {
  switch (policy) {
    case 'none':
      return 0;
    case 'fixed':
      return fixedSafetyStock || 0;
    case 'days_of_coverage':
      return Math.round(dailyAvgDemand * daysOfCoverage * 10000) / 10000;
    default:
      return 0;
  }
}

/**
 * 生成时间分段日期列表
 *
 * 从起始日期开始，按 day/week/month 粒度将时间范围划分为等长分段，
 * 每个分段包含一个标识日期和该段内的所有日期。
 *
 * @param startDate - 起始日期（YYYY-MM-DD）
 * @param days - 时间范围总天数
 * @param bucketSize - 分段粒度：'day' | 'week' | 'month'
 * @returns 时间分段数组，每项包含标识日期、起止日期和段内所有日期
 */
export function generateBucketDates(
  startDate: string,
  days: number,
  bucketSize: BucketSize
): { bucketDate: string; start: Date; end: Date; dates: string[] }[] {
  const buckets: { bucketDate: string; start: Date; end: Date; dates: string[] }[] = [];
  const start = new Date(startDate + 'T00:00:00');
  const end = new Date(start);
  end.setDate(end.getDate() + days - 1);

  let current = new Date(start);

  while (current <= end) {
    const bucketStart = new Date(current);
    let bucketEnd: Date;
    const dates: string[] = [];

    switch (bucketSize) {
      case 'day':
        bucketEnd = new Date(current);
        dates.push(formatDateStr(current));
        current.setDate(current.getDate() + 1);
        break;

      case 'week': {
        const dayOfWeek = current.getDay();
        const daysToAdd = dayOfWeek === 0 ? 0 : 7 - dayOfWeek;
        bucketEnd = new Date(current);
        bucketEnd.setDate(bucketEnd.getDate() + daysToAdd);
        if (bucketEnd > end) bucketEnd = new Date(end);
        for (let d = new Date(bucketStart); d <= bucketEnd; d.setDate(d.getDate() + 1)) {
          dates.push(formatDateStr(d));
        }
        current = new Date(bucketEnd);
        current.setDate(current.getDate() + 1);
        break;
      }

      case 'month': {
        const year = current.getFullYear();
        const month = current.getMonth();
        bucketEnd = new Date(year, month + 1, 0);
        if (bucketEnd > end) bucketEnd = new Date(end);
        for (let d = new Date(bucketStart); d <= bucketEnd; d.setDate(d.getDate() + 1)) {
          dates.push(formatDateStr(d));
        }
        current = new Date(bucketEnd);
        current.setDate(current.getDate() + 1);
        break;
      }

      default:
        bucketEnd = new Date(current);
        dates.push(formatDateStr(current));
        current.setDate(current.getDate() + 1);
    }

    buckets.push({
      bucketDate: formatDateStr(bucketStart),
      start: bucketStart,
      end: bucketEnd,
      dates,
    });
  }

  return buckets;
}

/**
 * MRP 计算引擎 V2
 *
 * 面向对象的 MRP 计算引擎，支持完整的物料需求计划流程：
 * 1. 收集毛需求（销售订单）
 * 2. 多层级 BOM 展开，逐级传递依赖需求
 * 3. 时间分段供需平衡计算
 * 4. 产能负荷分析
 *
 * 使用方式：
 * ```typescript
 * const engine = new MRPEngine({ horizonDays: 90, bucketSize: 'week' });
 * const result = await engine.run({
 *   runType: 'full',
 *   planStartDate: '2024-01-01',
 *   warehouseId: 1,
 *   productIds: [101, 102]
 * });
 * ```
 */
export class MRPEngine {
  private config: MRPConfig;
  private conn: PoolConnection | null;
  private warnings: string[] = [];

  /**
   * 创建 MRP 引擎实例
   *
   * @param config - 可选，部分 MRP 配置参数，未指定的使用默认值
   * @param conn - 可选，外部数据库连接，不传则 run 时自动获取
   */
  constructor(config?: Partial<MRPConfig>, conn?: PoolConnection) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.conn = conn || null;
  }

  /**
   * 执行 MRP 计算
   *
   * 完整执行一次 MRP 运算，包括：
   * 1. 生成运行编号
   * 2. 收集销售订单毛需求
   * 3. 多层级物料展开，逐级计算供需平衡
   * 4. 产能负荷分析
   * 5. 汇总统计（计划订单数、采购申请数、工单数）
   *
   * @param params - MRP 运行参数
   * @returns MRP 运行完整结果，包含物料分析、产能负荷和警告信息
   */
  async run(params: MRPRunParams): Promise<MRPRunResult> {
    const startTime = new Date();
    this.warnings = [];

    const conn = this.conn || (await getConnection());
    const isExternalConn = !!this.conn;

    try {
      const planStartDate = params.planStartDate || formatDateStr(new Date());
      const horizonDays = this.config.horizonDays;
      const endDate = new Date(planStartDate + 'T00:00:00');
      endDate.setDate(endDate.getDate() + horizonDays - 1);
      const planEndDate = formatDateStr(endDate);

      const runNo = await generateDocumentNo('mrp_run');

      const demands = await this.collectGrossRequirements(
        conn,
        planStartDate,
        planEndDate,
        params.productIds
      );

      const productIds = [...new Set(demands.map((d) => d.materialId))];

      const materials = await this.processAllMaterials(
        conn,
        demands,
        planStartDate,
        horizonDays,
        params.warehouseId
      );

      const capacityLoads = await this.calculateCapacityRequired(
        conn,
        materials,
        planStartDate,
        horizonDays
      );

      let plannedOrderCount = 0;
      let purchaseReqCount = 0;
      let workOrderCount = 0;

      for (const m of materials) {
        for (const b of m.buckets) {
          if (b.plannedOrderRelease > 0) {
            plannedOrderCount++;
            if (b.actionType === 'produce') {
              workOrderCount++;
            } else if (b.actionType === 'purchase') {
              purchaseReqCount++;
            }
          }
        }
      }

      return {
        runId: 0,
        runNo,
        status: 'completed',
        materialCount: materials.length,
        productCount: productIds.length,
        plannedOrderCount,
        purchaseReqCount,
        workOrderCount,
        materials,
        capacityLoads,
        warnings: this.warnings,
        startTime,
        endTime: new Date(),
      };
    } finally {
      if (!isExternalConn && conn && conn.release) {
        conn.release();
      }
    }
  }

  private async collectGrossRequirements(
    conn: PoolConnection,
    startDate: string,
    endDate: string,
    productIds?: number[]
  ): Promise<
    {
      materialId: number;
      materialCode: string;
      materialName: string;
      quantity: number;
      dueDate: string;
      sourceType: string;
      sourceId: number;
      sourceNo: string;
    }[]
  > {
    const demands: {
      materialId: number;
      materialCode: string;
      materialName: string;
      quantity: number;
      dueDate: string;
      sourceType: string;
      sourceId: number;
      sourceNo: string;
    }[] = [];

    let sql = `
      SELECT 
        so.id as source_id,
        so.order_no as source_no,
        sod.product_id as material_id,
        im.material_code,
        im.material_name,
        sod.quantity,
        so.delivery_date as due_date
      FROM sal_order so
      INNER JOIN sal_order_detail sod ON sod.order_id = so.id
      INNER JOIN inv_material im ON im.id = sod.product_id
      WHERE so.deleted = 0
        AND sod.deleted = 0
        AND so.status IN (1, 2)
        AND so.delivery_date BETWEEN ? AND ?
    `;

    const params: (string | number)[] = [startDate, endDate];

    if (productIds && productIds.length > 0) {
      sql += ` AND sod.product_id IN (${productIds.map(() => '?').join(',')})`;
      params.push(...productIds);
    }

    sql += ` ORDER BY so.delivery_date`;

    const [rows] = await conn.query<GrossRequirementRow[]>(sql, params);

    for (const row of rows) {
      demands.push({
        materialId: Number(row.material_id),
        materialCode: row.material_code || '',
        materialName: row.material_name || '',
        quantity: Number(row.quantity || 0),
        dueDate: formatDateStr(row.due_date),
        sourceType: 'sales_order',
        sourceId: Number(row.source_id),
        sourceNo: row.source_no || '',
      });
    }

    secureLog('info', `MRP收集需求完成`, {
      demandCount: demands.length,
      dateRange: `${startDate} ~ ${endDate}`,
    });

    return demands;
  }

  private async processAllMaterials(
    conn: PoolConnection,
    demands: { materialId: number; quantity: number; dueDate: string }[],
    startDate: string,
    horizonDays: number,
    warehouseId?: number
  ): Promise<MRPMaterialResult[]> {
    const materialMap = new Map<number, MRPMaterialResult>();
    const processed = new Set<number>();

    const demandMap = new Map<number, Map<string, number>>();
    for (const d of demands) {
      if (!demandMap.has(d.materialId)) {
        demandMap.set(d.materialId, new Map());
      }
      const dateMap = demandMap.get(d.materialId)!;
      dateMap.set(d.dueDate, (dateMap.get(d.dueDate) || 0) + d.quantity);
    }

    const productIds = [...demandMap.keys()];
    const queue = [...productIds];
    const levelMap = new Map<number, number>();
    for (const pid of productIds) {
      levelMap.set(pid, 0);
    }

    while (queue.length > 0) {
      const materialId = queue.shift()!;

      if (processed.has(materialId)) continue;
      processed.add(materialId);

      const materialInfo = await this.getMaterialInfo(conn, materialId);
      if (!materialInfo) {
        this.warnings.push(`物料ID ${materialId} 不存在，跳过`);
        continue;
      }

      const demandDates = demandMap.get(materialId) || new Map();
      const buckets = await this.calculateMaterialBuckets(
        conn,
        materialId,
        materialInfo,
        demandDates,
        startDate,
        horizonDays,
        warehouseId
      );

      // 外购物料标记为 purchase，自制件标记为 produce 后续展开子件
      const isPurchase = materialInfo.material_type === 'purchase';
      const actionType: MRPActionType = isPurchase ? 'purchase' : 'produce';

      for (const bucket of buckets) {
        bucket.actionType = actionType;
      }

      const materialResult: MRPMaterialResult = {
        materialId,
        materialCode: materialInfo.material_code,
        materialName: materialInfo.material_name,
        materialType: isPurchase
          ? 'material'
          : materialInfo.material_type === 'semi'
            ? 'semi'
            : 'product',
        unit: materialInfo.unit,
        safetyStock: Number(materialInfo.safety_stock || 0),
        leadTimeDays: Number(
          materialInfo.lead_time_days ||
            (await CalcParamService.getInt('mrp.default_lead_time_days', 7))
        ),
        lotSizing: this.config.defaultLotSizing,
        fixedLotSize: this.config.defaultFixedLotSize,
        buckets,
        totalGross: buckets.reduce((s, b) => s + b.grossRequirement, 0),
        totalNet: buckets.reduce((s, b) => s + b.netRequirement, 0),
        totalPlanned: buckets.reduce((s, b) => s + b.plannedOrderReceipt, 0),
        endOnHand: buckets.length > 0 ? buckets[buckets.length - 1].onHandInventory : 0,
      };

      materialMap.set(materialId, materialResult);

      // 自制件需要展开 BOM，将计划下达量作为下级子件的毛需求
      if (!isPurchase) {
        const children = await this.getBOMChildren(conn, materialId);
        for (const child of children) {
          if (!processed.has(child.material_id)) {
            queue.push(child.material_id);
          }

          const childDemandMap = demandMap.get(child.material_id) || new Map();
          for (const bucket of buckets) {
            if (bucket.plannedOrderRelease > 0) {
              // 子件毛需求 = 计划下达量 × 单位用量 × (1 + 损耗率/100)
              const childQty =
                bucket.plannedOrderRelease * child.consumption_qty * (1 + child.loss_rate / 100);
              childDemandMap.set(
                bucket.bucketDate,
                (childDemandMap.get(bucket.bucketDate) || 0) + childQty
              );
            }
          }
          demandMap.set(child.material_id, childDemandMap);
        }
      }
    }

    return Array.from(materialMap.values()).sort((a, b) =>
      a.materialCode.localeCompare(b.materialCode)
    );
  }

  private async calculateMaterialBuckets(
    conn: PoolConnection,
    materialId: number,
    materialInfo: MaterialInfoRow,
    demandDates: Map<string, number>,
    startDate: string,
    horizonDays: number,
    warehouseId?: number
  ): Promise<MRPTimeBucket[]> {
    const buckets = generateBucketDates(startDate, horizonDays, this.config.bucketSize);
    const result: MRPTimeBucket[] = [];

    const safetyStock = calculateSafetyStock(
      this.config.safetyStockPolicy,
      Number(materialInfo.safety_stock || 0),
      this.calculateAvgDailyDemand(demandDates, horizonDays),
      this.config.defaultSafetyStockDays
    );

    const currentOnHand = await this.getCurrentInventory(conn, materialId, warehouseId);

    const scheduledReceipts = await this.getScheduledReceipts(
      conn,
      materialId,
      startDate,
      horizonDays,
      warehouseId
    );

    const leadTimeDays = Number(
      materialInfo.lead_time_days ||
        (await CalcParamService.getInt('mrp.default_lead_time_days', 7))
    );
    const lotSizing = materialInfo.lot_sizing || this.config.defaultLotSizing;
    const fixedLotSize = Number(materialInfo.fixed_lot_size || this.config.defaultFixedLotSize);

    // 滚动在手库存 = 当前库存 - 安全库存
    let runningOnHand = currentOnHand - safetyStock;

    for (const bucket of buckets) {
      let grossReq = 0;
      let schedReceipt = 0;

      // 汇总该分段内所有日期的毛需求和计划收货
      for (const d of bucket.dates) {
        grossReq += demandDates.get(d) || 0;
        schedReceipt += scheduledReceipts.get(d) || 0;
      }

      // 计划前在手库存 = 滚动手在 + 计划收货 - 毛需求
      const projectedOnHandBefore = runningOnHand + schedReceipt - grossReq;

      let netReq = 0;
      let plannedReceipt = 0;

      // 若计划前在手库存为负，则产生净需求，需应用批量化规则
      if (projectedOnHandBefore < 0) {
        netReq = Math.abs(projectedOnHandBefore);
        plannedReceipt = applyLotSizing(netReq, lotSizing, fixedLotSize);
      }

      const onHandAfter = runningOnHand + schedReceipt - grossReq + plannedReceipt;

      result.push({
        bucketDate: bucket.bucketDate,
        grossRequirement: round4(grossReq),
        scheduledReceipt: round4(schedReceipt),
        onHandInventory: round4(Math.max(0, onHandAfter + safetyStock)),
        netRequirement: round4(netReq),
        plannedOrderReceipt: round4(plannedReceipt),
        plannedOrderRelease: 0,
      });

      runningOnHand = onHandAfter;
    }

    // 根据提前期前移计划订单：接收日期的时间分段 -> 释放日期的时间分段
    for (let i = 0; i < result.length; i++) {
      if (result[i].plannedOrderReceipt > 0) {
        const releaseBucketIdx = this.findReleaseBucketIndex(i, leadTimeDays, buckets);
        if (releaseBucketIdx >= 0) {
          result[releaseBucketIdx].plannedOrderRelease = result[i].plannedOrderReceipt;
        } else {
          result[0].plannedOrderRelease += result[i].plannedOrderReceipt;
          this.warnings.push(
            `物料 ${materialInfo.material_code} 计划产出日期 ${result[i].bucketDate} 提前期 ${leadTimeDays} 天超出计划开始日期，提前期不足`
          );
        }
      }
    }

    return result;
  }

  private findReleaseBucketIndex(
    receiptBucketIdx: number,
    leadTimeDays: number,
    buckets: { bucketDate: string; start: Date; end: Date; dates: string[] }[]
  ): number {
    if (receiptBucketIdx < 0) return -1;

    const receiptDate = new Date(buckets[receiptBucketIdx].bucketDate + 'T00:00:00');
    const releaseDate = new Date(receiptDate);
    releaseDate.setDate(releaseDate.getDate() - leadTimeDays);

    for (let i = 0; i < buckets.length; i++) {
      if (releaseDate >= buckets[i].start && releaseDate <= buckets[i].end) {
        return i;
      }
      if (releaseDate < buckets[i].start) {
        return i - 1;
      }
    }

    return -1;
  }

  private async getMaterialInfo(
    conn: PoolConnection,
    materialId: number
  ): Promise<MaterialInfoRow | null> {
    const [rows] = await conn.query<MaterialInfoRow[]>(
      `SELECT 
         im.id, im.material_code, im.material_name, im.unit, 
         im.safety_stock, im.lead_time_days, im.material_type,
         im.purchase_price, im.order_cost, im.holding_cost_rate,
         im.lot_sizing, im.fixed_lot_size, im.eoq,
         im.period_supply_days
       FROM inv_material im 
       WHERE im.id = ? AND im.deleted = 0`,
      [materialId]
    );
    return rows.length > 0 ? rows[0] : null;
  }

  private async getCurrentInventory(
    conn: PoolConnection,
    materialId: number,
    warehouseId?: number
  ): Promise<number> {
    let sql = `SELECT COALESCE(SUM(available_qty), 0) as total
               FROM inv_inventory
               WHERE material_id = ? AND deleted = 0`;
    const params: (string | number)[] = [materialId];

    if (warehouseId) {
      sql += ` AND warehouse_id = ?`;
      params.push(warehouseId);
    }

    const [rows] = await conn.query<InventoryTotalRow[]>(sql, params);
    return Number(rows.length > 0 ? rows[0].total || 0 : 0);
  }

  private async getScheduledReceipts(
    conn: PoolConnection,
    materialId: number,
    startDate: string,
    horizonDays: number,
    _warehouseId?: number
  ): Promise<Map<string, number>> {
    const receiptMap = new Map<string, number>();

    const endDate = new Date(startDate + 'T00:00:00');
    endDate.setDate(endDate.getDate() + horizonDays - 1);
    const endDateStr = formatDateStr(endDate);

    if (this.config.considerInTransit) {
      const poSql = `
        SELECT DATE(po.delivery_date) as receipt_date,
               COALESCE(SUM(pol.order_qty - pol.received_qty), 0) as qty
        FROM pur_purchase_order po
        INNER JOIN pur_purchase_order_line pol ON pol.po_id = po.id
        WHERE pol.material_id = ?
          AND po.deleted = 0
          AND po.status IN (20, 30)
          AND po.delivery_date BETWEEN ? AND ?
          AND pol.order_qty > pol.received_qty
        GROUP BY DATE(po.delivery_date)
      `;
      const [poRows] = await conn.query<ScheduledReceiptRow[]>(poSql, [
        materialId,
        startDate,
        endDateStr,
      ]);
      for (const row of poRows) {
        const d = formatDateStr(row.receipt_date);
        receiptMap.set(d, (receiptMap.get(d) || 0) + Number(row.qty || 0));
      }
    }

    if (this.config.considerWorkInProcess) {
      const woSql = `
        SELECT DATE(wo.plan_finish_date) as receipt_date,
               COALESCE(SUM(wo.quantity - wo.finished_qty), 0) as qty
        FROM prod_work_order wo
        WHERE wo.product_id = ?
          AND wo.deleted = 0
          AND wo.status IN (1, 2, 3)
          AND wo.plan_finish_date BETWEEN ? AND ?
          AND wo.quantity > wo.finished_qty
        GROUP BY DATE(wo.plan_finish_date)
      `;
      const [woRows] = await conn.query<ScheduledReceiptRow[]>(woSql, [
        materialId,
        startDate,
        endDateStr,
      ]);
      for (const row of woRows) {
        const d = formatDateStr(row.receipt_date);
        receiptMap.set(d, (receiptMap.get(d) || 0) + Number(row.qty || 0));
      }
    }

    return receiptMap;
  }

  private async getBOMChildren(
    conn: PoolConnection,
    productId: number
  ): Promise<{ material_id: number; consumption_qty: number; loss_rate: number }[]> {
    const [rows] = await conn.query<BomChildRow[]>(
      `SELECT bl.material_id, bl.consumption_qty, bl.loss_rate
       FROM bom_header bh
       INNER JOIN bom_line bl ON bl.bom_id = bh.id
       WHERE bh.product_id = ? 
         AND bh.status = 30 
         AND bh.deleted = 0
         AND bl.deleted = 0
       ORDER BY bh.is_default DESC, bh.version DESC
       LIMIT 100`,
      [productId]
    );
    return rows.map((r) => ({
      material_id: Number(r.material_id),
      consumption_qty: Number(r.consumption_qty || 0),
      loss_rate: Number(r.loss_rate || 0),
    }));
  }

  private calculateAvgDailyDemand(demandDates: Map<string, number>, horizonDays: number): number {
    let total = 0;
    for (const qty of demandDates.values()) {
      total += qty;
    }
    return horizonDays > 0 ? total / horizonDays : 0;
  }

  /**
   * 计算产能负荷需求
   *
   * 遍历所有非采购物料（产品/半成品）的计划订单，根据工艺路线计算各工位中心的
   * 标准工时需求。负荷率 = 需求工时 / 标准产能，负荷率 > 1 表示超负荷。
   *
   * @param conn - 数据库连接
   * @param materials - 所有物料的 MRP 分析结果
   * @param startDate - 计算起始日期
   * @param horizonDays - 计算范围天数
   * @returns 各工作中心按日期汇总的产能负荷分析
   */
  async calculateCapacityRequired(
    conn: PoolConnection,
    materials: MRPMaterialResult[],
    startDate: string,
    horizonDays: number
  ): Promise<CapacityLoad[]> {
    const capacityMap = new Map<string, CapacityLoad>();
    const _buckets = generateBucketDates(startDate, horizonDays, this.config.bucketSize);

    const productMaterials = materials.filter((m) => m.materialType !== 'material');

    for (const m of productMaterials) {
      for (const bucket of m.buckets) {
        if (bucket.plannedOrderRelease <= 0) continue;

        const [processRows] = await conn.query<ProcessRouteCapacityRow[]>(
          `SELECT pr.work_center_id, wc.work_center_code, wc.work_center_name,
                  pr.standard_hours, wc.daily_capacity
           FROM pro_process_route pr
           INNER JOIN pro_work_center wc ON wc.id = pr.work_center_id
           WHERE pr.product_id = ? AND pr.status = 1
           ORDER BY pr.seq_no`,
          [m.materialId]
        );

        for (const pr of processRows) {
          // 需求工时 = 计划生产数量 × 标准工时
          const requiredHours = bucket.plannedOrderRelease * Number(pr.standard_hours || 0);
          const key = `${pr.work_center_id}_${bucket.bucketDate}`;

          if (!capacityMap.has(key)) {
            capacityMap.set(key, {
              workCenterId: Number(pr.work_center_id),
              workCenterCode: pr.work_center_code || '',
              workCenterName: pr.work_center_name || '',
              capacityDate: bucket.bucketDate,
              standardCapacity: Number(pr.daily_capacity || 8),
              requiredCapacity: 0,
              loadRate: 0,
              isOverloaded: false,
            });
          }

          const entry = capacityMap.get(key)!;
          entry.requiredCapacity += requiredHours;
          // 负荷率 = 需求工时 / 标准产能
          entry.loadRate =
            entry.standardCapacity > 0 ? entry.requiredCapacity / entry.standardCapacity : 0;
          // 负荷率 > 1 表示超负荷
          entry.isOverloaded = entry.loadRate > 1;
        }
      }
    }

    return Array.from(capacityMap.values()).sort((a, b) => {
      if (a.workCenterCode !== b.workCenterCode) {
        return a.workCenterCode.localeCompare(b.workCenterCode);
      }
      return a.capacityDate.localeCompare(b.capacityDate);
    });
  }
}

/**
 * 将 Date 或日期字符串格式化为 YYYY-MM-DD 格式
 *
 * @param d - Date 对象或日期字符串
 * @returns YYYY-MM-DD 格式的日期字符串
 */
function formatDateStr(d: Date | string): string {
  if (typeof d === 'string') {
    return d.substring(0, 10);
  }
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * 四舍五入保留 4 位小数
 *
 * @param v - 要舍入的数值
 * @returns 保留 4 位小数的数值
 */
function round4(v: number): number {
  return Math.round(v * 10000) / 10000;
}

export { formatDateStr, round4 };

/**
 * @module MRP 引擎
 * @description MRP（物料需求计划）核心计算引擎。负责执行 BOM 展开、时间分段计算、净需求分析、
 * 计划订单生成以及自动生成采购申请等完整 MRP 运算流程。该模块是 ERP 系统中生产计划与物料控制
 * 的关键组件，输入工单编号和仓库信息，输出物料供需平衡的完整计算报告。
 */

import { CalcParamService } from '@/lib/calc-param-service';

/**
 * 表示 BOM 树中的一个节点，用于存储展开后的物料清单结构
 */
export interface BOMNode {
  /** 物料 ID */
  material_id: number;
  /** 物料编码 */
  material_code: string;
  /** 物料名称 */
  material_name: string;
  /** 需求数量（已考虑损耗率） */
  quantity: number;
  /** 计量单位 */
  unit: string;
  /** BOM 层级，0 为顶层产品 */
  level: number;
  /** BOM 路径，用 '>' 分隔各层级物料 ID，用于环检测 */
  path: string;
  /** 是否为叶节点（无下级 BOM） */
  is_leaf: boolean;
  /** 采购/生产提前期（天） */
  lead_time_days: number;
  /** 损耗率（0~1 之间的小数） */
  scrap_rate: number;
  /** 子 BOM 节点列表 */
  children?: BOMNode[];
}

interface StackItem {
  material_id: number;
  material_code: string;
  material_name: string;
  quantity: number;
  unit: string;
  level: number;
  path: string;
  parent_node: BOMNode | null;
  parent_qty: number;
}

interface BOMRow {
  id: number;
  material_id: number;
  version: string;
  status: number;
  is_default: number;
}

interface BOMLineRow {
  id: number;
  bom_id: number;
  material_id: number;
  quantity: number;
  unit: string;
  loss_rate: number;
}

interface _MaterialInfoRow {
  id: number;
  material_code: string;
  material_name: string;
  unit: string;
  safety_stock: number;
  purchase_price: number;
  default_supplier_id: number | null;
  lead_time_days: number | null;
}

/**
 * 展开 BOM（物料清单）树
 *
 * 使用迭代栈（非递归）方式从上往下展开指定产品的 BOM 结构。
 * 算法流程：
 * 1. 查询产品基础信息，创建根节点
 * 2. 使用栈进行广度优先遍历，逐层查询每个物料的 BOM 明细
 * 3. 计算子物料数量时考虑损耗率：grossQty = parentQty × quantity × (1 + scrapRate)
 * 4. 通过 path 路径和 visited 集合防止循环引用和无限递归
 * 5. 最多展开 maxDepth 层
 *
 * @param conn - 数据库连接对象
 * @param productId - 产品/物料 ID
 * @param quantity - 顶层产品的需求数量
 * @param maxDepth - 最大展开深度，默认 10 层
 * @returns BOM 树的根节点，包含完整的父子层级结构
 */
export async function explodeBOM(
  conn: Loose,
  productId: number,
  quantity: number,
  maxDepth: number = 10
): Promise<BOMNode> {
  const productRows: Loose = await conn.query(
    `SELECT id, material_code, material_name, unit FROM inv_material WHERE id = ? AND deleted = 0`,
    [productId]
  );

  let productCode = '';
  let productName = '';
  let productUnit = '件';

  if (productRows.length > 0) {
    productCode = productRows[0].material_code || '';
    productName = productRows[0].material_name || '';
    productUnit = productRows[0].unit || '件';
  }

  const defaultLeadTime = await CalcParamService.getInt('mrp.default_lead_time_days', 7);
  const leadTimeRows: Loose = await conn.query(
    `SELECT id FROM inv_material WHERE id = ? AND deleted = 0`,
    [productId]
  );
  const rootLeadTime = leadTimeRows.length > 0 ? defaultLeadTime : defaultLeadTime;

  const root: BOMNode = {
    material_id: productId,
    material_code: productCode,
    material_name: productName,
    quantity: quantity,
    unit: productUnit,
    level: 0,
    path: String(productId),
    is_leaf: true,
    lead_time_days: rootLeadTime,
    scrap_rate: 0,
    children: [],
  };

  const stack: StackItem[] = [
    {
      material_id: productId,
      material_code: productCode,
      material_name: productName,
      quantity: quantity,
      unit: productUnit,
      level: 0,
      path: String(productId),
      parent_node: root,
      parent_qty: quantity,
    },
  ];

  const visited = new Set<string>();

  while (stack.length > 0) {
    const item = stack.pop()!;

    if (item.level >= maxDepth) {
      continue;
    }

    const visitKey = `${item.material_id}:${item.path}`;
    if (visited.has(visitKey)) {
      continue;
    }
    visited.add(visitKey);

    const bomRows: BOMRow[] = await conn.query(
      `SELECT id, material_id, version, status, is_default
       FROM prd_bom
       WHERE material_id = ? AND status = 1
       ORDER BY is_default DESC, version DESC
       LIMIT 1`,
      [item.material_id]
    );

    if (!bomRows || bomRows.length === 0) {
      continue;
    }

    const bom = bomRows[0];
    if (item.parent_node) {
      item.parent_node.is_leaf = false;
    }

    const lines: BOMLineRow[] = await conn.query(
      `SELECT bd.id, bd.bom_id, bd.material_id, bd.quantity, bd.unit, bd.loss_rate,
              m.material_code, m.material_name
       FROM prd_bom_detail bd
       LEFT JOIN inv_material m ON m.id = bd.material_id
       WHERE bd.bom_id = ?`,
      [bom.id]
    );

    for (const line of lines) {
      // 计算损耗率（百分比转小数）和考虑损耗后的毛需求数量
      const scrapRate = Number(line.loss_rate || 0) / 100;
      const grossQty = item.parent_qty * Number(line.quantity) * (1 + scrapRate);

      const childPath = `${item.path}>${line.material_id}`;

      const childCircularKey = `${line.material_id}:${childPath}`;

      const matInfoRows: Loose = await conn.query(
        `SELECT id, material_code, material_name FROM inv_material WHERE id = ?`,
        [line.material_id]
      );
      const childLeadTime = defaultLeadTime;
      const childCode = matInfoRows.length > 0 ? matInfoRows[0].material_code || '' : '';
      const childName = matInfoRows.length > 0 ? matInfoRows[0].material_name || '' : '';

      const childNode: BOMNode = {
        material_id: line.material_id,
        material_code: childCode,
        material_name: childName,
        quantity: Math.round(grossQty * 10000) / 10000,
        unit: line.unit || '件',
        level: item.level + 1,
        path: childPath,
        is_leaf: true,
        lead_time_days: childLeadTime,
        scrap_rate: scrapRate,
        children: [],
      };

      if (item.parent_node) {
        if (!item.parent_node.children) {
          item.parent_node.children = [];
        }
        item.parent_node.children.push(childNode);
      }

      if (!visited.has(childCircularKey) && item.level + 1 < maxDepth) {
        stack.push({
          material_id: line.material_id,
          material_code: childCode,
          material_name: childName,
          quantity: grossQty,
          unit: line.unit || '件',
          level: item.level + 1,
          path: childPath,
          parent_node: childNode,
          parent_qty: grossQty,
        });
      }
    }
  }

  return root;
}

/**
 * 表示一个时间分段（时区）内的 MRP 供需数据
 */
export interface TimeBucket {
  date: string;
  gross_requirement: number;
  scheduled_receipt: number;
  on_hand: number;
  net_requirement: number;
  planned_order_release: number;
  planned_order_receipt: number;
}

/**
 * 计算指定物料的时间分段供需平衡
 *
 * 按 day/week/month 粒度将时间范围划分为多个分段，逐段计算 MRP 核心指标。
 * 计算逻辑：
 * 1. 获取物料提前期和当前库存
 * 2. 收集工单需求（gross requirement）和在途采购收货（scheduled receipt）
 * 3. 逐段滚动计算：在手库存 = max(0, 上期库存 + 计划收货 - 毛需求)
 * 4. 净需求 = max(0, 毛需求 - 在手库存 - 计划收货)
 * 5. 根据提前期前移计划订单下达日期
 *
 * @param conn - 数据库连接对象
 * @param materialId - 物料 ID
 * @param warehouseId - 仓库 ID
 * @param startDate - 计算起始日期（YYYY-MM-DD）
 * @param endDate - 计算结束日期（YYYY-MM-DD）
 * @param bucketSize - 时间分段粒度：'day' | 'week' | 'month'，默认 'week'
 * @returns 各时间分段的 MRP 计算明细数组
 */
export async function calculateTimeBuckets(
  conn: Loose,
  materialId: number,
  warehouseId: number,
  startDate: string,
  endDate: string,
  bucketSize: 'day' | 'week' | 'month' = 'week'
): Promise<TimeBucket[]> {
  const buckets = generateBucketDates(startDate, endDate, bucketSize);

  if (buckets.length === 0) {
    return [];
  }

  const defaultLeadTime = await CalcParamService.getInt('mrp.default_lead_time_days', 7);
  const _matInfoRows: Loose = await conn.query(
    `SELECT id FROM inv_material WHERE id = ? AND deleted = 0`,
    [materialId]
  );
  const leadTimeDays = defaultLeadTime;

  const invRows: Loose = await conn.query(
    `SELECT COALESCE(SUM(available_qty), 0) as total_available
     FROM inv_inventory
     WHERE material_id = ? AND warehouse_id = ? AND deleted = 0`,
    [materialId, warehouseId]
  );
  const currentOnHand = Number(invRows.length > 0 ? invRows[0].total_available : 0);

  const requirementRows: Loose = await conn.query(
    `SELECT
       DATE(wo.plan_start_date) as req_date,
       COALESCE(SUM(bd.quantity * wo.plan_qty * (1 + bd.loss_rate / 100)), 0) as total_req
     FROM prd_work_order wo
     INNER JOIN prd_bom b ON b.material_id = wo.material_id AND b.status = 1
     INNER JOIN prd_bom_detail bd ON bd.bom_id = b.id AND bd.material_id = ?
     WHERE wo.plan_start_date IS NOT NULL
       AND wo.status IN (1, 2)
       AND wo.plan_start_date >= ?
       AND wo.plan_start_date <= ?
     GROUP BY DATE(wo.plan_start_date)`,
    [materialId, startDate, endDate]
  );

  const requirementMap = new Map<string, number>();
  for (const row of requirementRows) {
    const dateStr =
      typeof row.req_date === 'string'
        ? row.req_date.substring(0, 10)
        : String(row.req_date).substring(0, 10);
    requirementMap.set(dateStr, Number(row.total_req));
  }

  const receiptRows: Loose = await conn.query(
    `SELECT
       DATE(po.delivery_date) as receipt_date,
       COALESCE(SUM(pol.order_qty - pol.received_qty), 0) as total_receipt
     FROM pur_purchase_order po
     INNER JOIN pur_purchase_order_line pol ON pol.po_id = po.id
     WHERE pol.material_id = ?
       AND po.deleted = 0
       AND po.status IN (20, 30, 40)
       AND po.delivery_date IS NOT NULL
       AND po.delivery_date >= ?
       AND po.delivery_date <= ?
       AND pol.order_qty > pol.received_qty
     GROUP BY DATE(po.delivery_date)`,
    [materialId, startDate, endDate]
  );

  const receiptMap = new Map<string, number>();
  for (const row of receiptRows) {
    const dateStr =
      typeof row.receipt_date === 'string'
        ? row.receipt_date.substring(0, 10)
        : String(row.receipt_date).substring(0, 10);
    receiptMap.set(dateStr, Number(row.total_receipt));
  }

  const result: TimeBucket[] = [];
  let runningOnHand = currentOnHand;

  for (const bucket of buckets) {
    let grossReq = 0;
    let schedReceipt = 0;

    // 汇总该分段内所有日期的毛需求和计划收货
    for (const d of bucket.dates) {
      const dStr = formatDateStr(d);
      grossReq += requirementMap.get(dStr) || 0;
      schedReceipt += receiptMap.get(dStr) || 0;
    }

    // 预计在手库存 = max(0, 滚动手在 + 计划收货 - 毛需求)
    const onHand = Math.max(0, runningOnHand + schedReceipt - grossReq);
    // 净需求 = max(0, 毛需求 - 在手库存 - 计划收货)
    const netReq = Math.max(0, grossReq - runningOnHand - schedReceipt);

    let plannedRelease = 0;
    let plannedReceipt = 0;

    if (netReq > 0) {
      plannedReceipt = netReq;
      plannedRelease = netReq;
    }

    result.push({
      date: bucket.label,
      gross_requirement: Math.round(grossReq * 10000) / 10000,
      scheduled_receipt: Math.round(schedReceipt * 10000) / 10000,
      on_hand: Math.round(onHand * 10000) / 10000,
      net_requirement: Math.round(netReq * 10000) / 10000,
      planned_order_release: Math.round(plannedRelease * 10000) / 10000,
      planned_order_receipt: Math.round(plannedReceipt * 10000) / 10000,
    });

    runningOnHand = onHand;
  }

  // 根据提前期前移计划订单：接收日期的时间分段 -> 释放日期的时间分段
  for (let i = 0; i < result.length; i++) {
    if (result[i].planned_order_receipt > 0) {
      const releaseBucketIdx = i - Math.ceil(leadTimeDays / getBucketDays(bucketSize));
      if (releaseBucketIdx >= 0) {
        result[releaseBucketIdx].planned_order_release = result[i].planned_order_receipt;
        result[i].planned_order_release = 0;
      }
    }
  }

  return result;
}

function getBucketDays(bucketSize: 'day' | 'week' | 'month'): number {
  switch (bucketSize) {
    case 'day':
      return 1;
    case 'week':
      return 7;
    case 'month':
      return 30;
  }
}

interface BucketDates {
  label: string;
  dates: Date[];
}

function generateBucketDates(
  startDate: string,
  endDate: string,
  bucketSize: 'day' | 'week' | 'month'
): BucketDates[] {
  const start = new Date(startDate + 'T00:00:00');
  const end = new Date(endDate + 'T00:00:00');
  const buckets: BucketDates[] = [];

  if (start > end) {
    return buckets;
  }

  let current = new Date(start);

  while (current <= end) {
    const bucketStart = new Date(current);
    let bucketEnd: Date;

    switch (bucketSize) {
      case 'day':
        bucketEnd = new Date(current);
        current.setDate(current.getDate() + 1);
        break;
      case 'week': {
        const dayOfWeek = current.getDay();
        const daysToSunday = dayOfWeek === 0 ? 0 : 7 - dayOfWeek;
        bucketEnd = new Date(current);
        bucketEnd.setDate(bucketEnd.getDate() + daysToSunday);
        if (bucketEnd > end) bucketEnd = new Date(end);
        current.setDate(current.getDate() + daysToSunday + 1);
        break;
      }
      case 'month': {
        bucketEnd = new Date(current.getFullYear(), current.getMonth() + 1, 0);
        if (bucketEnd > end) bucketEnd = new Date(end);
        current = new Date(current.getFullYear(), current.getMonth() + 1, 1);
        break;
      }
    }

    const dates: Date[] = [];
    for (let d = new Date(bucketStart); d <= bucketEnd; d.setDate(d.getDate() + 1)) {
      dates.push(new Date(d));
    }

    buckets.push({
      label: formatDateStr(bucketStart),
      dates,
    });
  }

  return buckets;
}

function formatDateStr(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function addDays(dateStr: string, days: number): string {
  const d = new Date(dateStr + 'T00:00:00');
  d.setDate(d.getDate() + days);
  return formatDateStr(d);
}

/**
 * 表示单个物料的净需求分析结果
 */
export interface NetRequirement {
  material_id: number;
  material_code: string;
  material_name: string;
  unit: string;
  gross_requirement: number;
  on_hand_qty: number;
  allocated_qty: number;
  in_transit_qty: number;
  safety_stock: number;
  net_requirement: number;
  lead_time_days: number;
  suggested_order_date: string;
  suggested_delivery_date: string;
  suggested_order_qty: number;
  shortage_warning: boolean;
}

/**
 * 计算工单的净需求
 *
 * 针对指定的工单列表，展开每个工单产品的 BOM 树，汇总所有叶子物料的毛需求量，
 * 再结合库存、已分配量、在途量和安全库存计算每个物料的净需求。
 *
 * 净需求公式：netReq = max(0, grossRequirement - onHandQty + allocatedQty - inTransitQty + safetyStock)
 *
 * @param conn - 数据库连接对象
 * @param workOrderIds - 工单 ID 数组
 * @param warehouseId - 仓库 ID
 * @returns 各物料的净需求分析结果数组，按物料聚合汇总
 */
export async function calculateNetRequirements(
  conn: Loose,
  workOrderIds: number[],
  warehouseId: number
): Promise<NetRequirement[]> {
  if (!workOrderIds || workOrderIds.length === 0) {
    return [];
  }

  const placeholders = workOrderIds.map(() => '?').join(',');

  const workOrders: Loose = await conn.query(
    `SELECT wo.id, wo.work_order_no, wo.plan_qty, wo.plan_start_date, wo.material_id
     FROM prd_work_order wo
     WHERE wo.id IN (${placeholders})`,
    workOrderIds
  );

  if (!workOrders || workOrders.length === 0) {
    return [];
  }

  const materialRequirements = new Map<
    number,
    {
      total_qty: number;
      unit: string;
      material_code: string;
      material_name: string;
      earliest_start_date: string;
      work_order_ids: number[];
    }
  >();

  for (const wo of workOrders) {
    if (!wo.material_id) continue;
    const bomTree = await explodeBOM(conn, wo.material_id, Number(wo.plan_qty || 0));

    const leafMaterials = collectLeafMaterials(bomTree);

    for (const leaf of leafMaterials) {
      const existing = materialRequirements.get(leaf.material_id);
      if (existing) {
        existing.total_qty += leaf.quantity;
        if (wo.plan_start_date) {
          if (!existing.earliest_start_date || wo.plan_start_date < existing.earliest_start_date) {
            existing.earliest_start_date = wo.plan_start_date.substring(0, 10);
          }
        }
        if (!existing.work_order_ids.includes(wo.id)) {
          existing.work_order_ids.push(wo.id);
        }
      } else {
        materialRequirements.set(leaf.material_id, {
          total_qty: leaf.quantity,
          unit: leaf.unit,
          material_code: leaf.material_code,
          material_name: leaf.material_name,
          earliest_start_date: wo.plan_start_date
            ? wo.plan_start_date.substring(0, 10)
            : formatDateStr(new Date()),
          work_order_ids: [wo.id],
        });
      }
    }
  }

  const results: NetRequirement[] = [];
  const materialReqEntries = Array.from(materialRequirements.entries());

  for (const entry of materialReqEntries) {
    const materialId = entry[0];
    const req = entry[1];
    const invRows: Loose = await conn.query(
      `SELECT COALESCE(SUM(available_qty), 0) as total_available
       FROM inv_inventory
       WHERE material_id = ? AND warehouse_id = ? AND deleted = 0`,
      [materialId, warehouseId]
    );
    const onHandQty = Number(invRows.length > 0 ? invRows[0].total_available : 0);

    const allocatedRows: Loose = await conn.query(
      `SELECT COALESCE(SUM(mii.issued_qty), 0) as total_allocated
       FROM prd_material_issue_item mii
       INNER JOIN prd_material_issue mi ON mi.id = mii.issue_id
       WHERE mii.material_id = ?
         AND mi.warehouse_id = ?
         AND mi.deleted = 0
         AND mi.status IN (1, 2)`,
      [materialId, warehouseId]
    );
    const allocatedQty = Number(allocatedRows.length > 0 ? allocatedRows[0].total_allocated : 0);

    const inTransitRows: Loose = await conn.query(
      `SELECT COALESCE(SUM(pol.order_qty - pol.received_qty), 0) as total_in_transit
       FROM pur_purchase_order_line pol
       INNER JOIN pur_purchase_order po ON po.id = pol.po_id
       WHERE pol.material_id = ?
         AND po.deleted = 0
         AND po.status IN (30, 40)
         AND pol.order_qty > pol.received_qty`,
      [materialId]
    );
    const inTransitQty = Number(inTransitRows.length > 0 ? inTransitRows[0].total_in_transit : 0);

    const defaultLeadTime = await CalcParamService.getInt('mrp.default_lead_time_days', 7);
    const matInfoRows: Loose = await conn.query(
      `SELECT id, material_code, material_name, unit, safety_stock, purchase_price
       FROM inv_material WHERE id = ? AND deleted = 0`,
      [materialId]
    );

    let safetyStock = 0;
    let leadTimeDays = defaultLeadTime;
    let materialCode = req.material_code;
    let materialName = req.material_name;
    let unit = req.unit;

    if (matInfoRows && matInfoRows.length > 0) {
      const matInfo = matInfoRows[0];
      safetyStock = Number(matInfo.safety_stock || 0);
      leadTimeDays = defaultLeadTime;
      materialCode = matInfo.material_code || materialCode;
      materialName = matInfo.material_name || materialName;
      unit = matInfo.unit || unit;
    }

    const netReq = Math.max(
      0,
      req.total_qty - onHandQty + allocatedQty - inTransitQty + safetyStock
    );

    const earliestDate = req.earliest_start_date || formatDateStr(new Date());
    const suggestedOrderDate = addDays(earliestDate, -leadTimeDays);
    const suggestedDeliveryDate = earliestDate;

    const shortageWarning = onHandQty < safetyStock;

    results.push({
      material_id: materialId,
      material_code: materialCode,
      material_name: materialName,
      unit: unit,
      gross_requirement: Math.round(req.total_qty * 10000) / 10000,
      on_hand_qty: Math.round(onHandQty * 10000) / 10000,
      allocated_qty: Math.round(allocatedQty * 10000) / 10000,
      in_transit_qty: Math.round(inTransitQty * 10000) / 10000,
      safety_stock: Math.round(safetyStock * 10000) / 10000,
      net_requirement: Math.round(netReq * 10000) / 10000,
      lead_time_days: leadTimeDays,
      suggested_order_date: suggestedOrderDate,
      suggested_delivery_date: suggestedDeliveryDate,
      suggested_order_qty: Math.round(netReq * 10000) / 10000,
      shortage_warning: shortageWarning,
    });
  }

  return results;
}

function collectLeafMaterials(node: BOMNode): Array<{
  material_id: number;
  material_code: string;
  material_name: string;
  quantity: number;
  unit: string;
}> {
  const leaves: Array<{
    material_id: number;
    material_code: string;
    material_name: string;
    quantity: number;
    unit: string;
  }> = [];

  if (node.is_leaf) {
    leaves.push({
      material_id: node.material_id,
      material_code: node.material_code,
      material_name: node.material_name,
      quantity: node.quantity,
      unit: node.unit,
    });
  }

  if (node.children && node.children.length > 0) {
    for (const child of node.children) {
      const childLeaves = collectLeafMaterials(child);
      leaves.push(...childLeaves);
    }
  }

  return leaves;
}

/**
 * 表示 MRP 计算生成的计划订单
 */
export interface PlannedOrder {
  material_id: number;
  material_code: string;
  material_name: string;
  unit: string;
  quantity: number;
  required_date: string;
  order_date: string;
  source_type: 'mrp';
  source_ids: number[];
  priority: 'urgent' | 'normal' | 'low';
}

/**
 * 根据净需求生成计划订单
 *
 * 将净需求计算结果转化为计划订单。按物料聚合净需求量，根据需求日期距离今天的天数
 * 自动设置优先级：
 * - 距今天 ≤3 天：紧急（urgent）
 * - 距今天 ≤14 天：正常（normal）
 * - 其他：低（low）
 *
 * @param conn - 数据库连接对象
 * @param workOrderIds - 工单 ID 数组
 * @param warehouseId - 仓库 ID
 * @returns 按物料聚合的计划订单数组
 */
export async function generatePlannedOrders(
  conn: Loose,
  workOrderIds: number[],
  warehouseId: number
): Promise<PlannedOrder[]> {
  const netRequirements = await calculateNetRequirements(conn, workOrderIds, warehouseId);

  const positiveReqs = netRequirements.filter((r) => r.net_requirement > 0);

  const orderMap = new Map<number, PlannedOrder>();

  for (const req of positiveReqs) {
    const existing = orderMap.get(req.material_id);
    if (existing) {
      existing.quantity += req.suggested_order_qty;
      existing.source_ids = Array.from(new Set(existing.source_ids.concat(workOrderIds)));
      if (req.suggested_delivery_date < existing.required_date) {
        existing.required_date = req.suggested_delivery_date;
        existing.order_date = req.suggested_order_date;
      }
    } else {
      const now = new Date();
      const todayStr = formatDateStr(now);
      const requiredDate = req.suggested_delivery_date || todayStr;
      const daysUntilRequired = Math.ceil(
        (new Date(requiredDate + 'T00:00:00').getTime() - now.getTime()) / (1000 * 60 * 60 * 24)
      );

      let priority: 'urgent' | 'normal' | 'low';
      if (daysUntilRequired <= 3) {
        priority = 'urgent';
      } else if (daysUntilRequired <= 14) {
        priority = 'normal';
      } else {
        priority = 'low';
      }

      const woIds = netRequirements
        .filter((r) => r.material_id === req.material_id)
        .flatMap((_r) => {
          return workOrderIds;
        });
      const uniqueWoIds = Array.from(new Set(woIds));

      orderMap.set(req.material_id, {
        material_id: req.material_id,
        material_code: req.material_code,
        material_name: req.material_name,
        unit: req.unit,
        quantity: req.suggested_order_qty,
        required_date: requiredDate,
        order_date: req.suggested_order_date,
        source_type: 'mrp',
        source_ids: uniqueWoIds,
        priority,
      });
    }
  }

  return Array.from(orderMap.values());
}

/**
 * 根据 MRP 计划订单自动生成采购申请
 *
 * 将计划订单按供应商分组，为每组创建一条采购申请（pur_request），
 * 并为每个物料创建采购申请明细行（pur_request_item）。
 * 采购申请编号格式：PR + 日期 + 4位随机数。
 *
 * @param conn - 数据库连接对象
 * @param plannedOrders - 计划订单数组
 * @param operatorId - 操作人 ID
 * @param operatorName - 操作人名称
 * @returns 生成的采购申请列表，每项包含申请编号和物料项数
 */
export async function generatePurchaseRequestsFromMRP(
  conn: Loose,
  plannedOrders: PlannedOrder[],
  operatorId: number | null,
  _operatorName: string
): Promise<{ request_no: string; item_count: number }[]> {
  if (!plannedOrders || plannedOrders.length === 0) {
    return [];
  }

  const materialIds = plannedOrders.map((o) => o.material_id);
  const matPlaceholders = materialIds.map(() => '?').join(',');

  const supplierMap = new Map<number | null, PlannedOrder[]>();

  const matSupplierRows: Loose = await conn.query(
    `SELECT id, material_code, material_name
     FROM inv_material
     WHERE id IN (${matPlaceholders})`,
    materialIds
  );

  const matSupplierLookup = new Map<number, number | null>();
  for (const row of matSupplierRows) {
    matSupplierLookup.set(row.id, null);
  }

  for (const order of plannedOrders) {
    const supplierId = matSupplierLookup.get(order.material_id) || null;
    const group = supplierMap.get(supplierId) || [];
    group.push(order);
    supplierMap.set(supplierId, group);
  }

  const results: { request_no: string; item_count: number }[] = [];
  const supplierEntries = Array.from(supplierMap.entries());

  for (const entry of supplierEntries) {
    const supplierId = entry[0];
    const orders = entry[1];
    const now = new Date();
    const dateStr = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}`;
    const randomDigits = String(Math.floor(Math.random() * 10000)).padStart(4, '0');
    const requestNo = `PR${dateStr}${randomDigits}`;

    let supplierName = '';
    if (supplierId) {
      const suppRows: Loose = await conn.query(
        `SELECT supplier_name FROM pur_supplier WHERE id = ? AND deleted = 0`,
        [supplierId]
      );
      if (suppRows.length > 0) {
        supplierName = suppRows[0].supplier_name || '';
      }
    }

    const [headerResult]: Loose = await conn.execute(
      `INSERT INTO pur_request
       (request_no, request_dept_id, requester_id, supplier_id, supplier_name, expected_date, status, source_type, create_by, create_time)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'mrp', ?, NOW())`,
      [
        requestNo,
        null,
        operatorId,
        supplierId,
        supplierName,
        orders.length > 0 ? orders[0].required_date : null,
        0,
        operatorId,
      ]
    );

    const requestId = headerResult.insertId;
    let lineNo = 1;

    for (const order of orders) {
      let suggestedPrice = 0;

      const priceRows: Loose = await conn.query(
        `SELECT purchase_price FROM inv_material WHERE id = ? AND deleted = 0`,
        [order.material_id]
      );
      if (priceRows.length > 0) {
        suggestedPrice = Number(priceRows[0].purchase_price || 0);
      }

      await conn.execute(
        `INSERT INTO pur_request_item
         (request_id, line_no, material_id, material_code, material_name, material_spec, quantity, price, amount, unit, required_date, status)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          requestId,
          lineNo++,
          order.material_id,
          order.material_code,
          order.material_name,
          '',
          order.quantity,
          suggestedPrice,
          Math.round(order.quantity * suggestedPrice * 100) / 100,
          order.unit,
          order.required_date,
          0,
        ]
      );
    }

    results.push({
      request_no: requestNo,
      item_count: orders.length,
    });
  }

  return results;
}

/**
 * 运行完整的 MRP 计算流程
 *
 * 这是 MRP 引擎的入口函数，串联执行以下完整流程：
 * 1. BOM 展开：对每个工单产品展开 BOM 树
 * 2. 净需求计算：汇总叶子物料需求，结合库存计算缺口
 * 3. 计划订单生成：将净需求转化为计划订单
 * 4. （可选）自动生成采购申请：根据计划订单创建采购申请
 * 5. 汇总统计：总物料数、短缺数、计划数量、计划金额
 *
 * @param conn - 数据库连接对象
 * @param workOrderIds - 工单 ID 数组
 * @param warehouseId - 仓库 ID
 * @param operatorId - 操作人 ID
 * @param operatorName - 操作人名称
 * @param autoGeneratePR - 是否自动生成采购申请，默认 false
 * @returns MRP 完整计算结果，包含 BOM 树、净需求、计划订单、采购申请（可选）和汇总统计
 */
export async function runFullMRP(
  conn: Loose,
  workOrderIds: number[],
  warehouseId: number,
  operatorId: number | null,
  operatorName: string,
  autoGeneratePR: boolean = false
): Promise<{
  bom_tree: BOMNode;
  net_requirements: NetRequirement[];
  planned_orders: PlannedOrder[];
  purchase_requests?: { request_no: string; item_count: number }[];
  summary: {
    total_materials: number;
    total_shortages: number;
    total_planned_qty: number;
    total_planned_amount: number;
  };
}> {
  if (!workOrderIds || workOrderIds.length === 0) {
    return {
      bom_tree: {
        material_id: 0,
        material_code: '',
        material_name: '',
        quantity: 0,
        unit: '',
        level: 0,
        path: '',
        is_leaf: true,
        lead_time_days: await CalcParamService.getInt('mrp.default_lead_time_days', 7),
        scrap_rate: 0,
        children: [],
      },
      net_requirements: [],
      planned_orders: [],
      summary: {
        total_materials: 0,
        total_shortages: 0,
        total_planned_qty: 0,
        total_planned_amount: 0,
      },
    };
  }

  const placeholders = workOrderIds.map(() => '?').join(',');
  const workOrders: Loose = await conn.query(
    `SELECT wo.id, wo.plan_qty, wo.material_id
     FROM prd_work_order wo
     WHERE wo.id IN (${placeholders})`,
    workOrderIds
  );

  const combinedBomTree: BOMNode = {
    material_id: 0,
    material_code: 'MRP_ROOT',
    material_name: 'MRP计算根节点',
    quantity: 0,
    unit: '',
    level: -1,
    path: 'MRP_ROOT',
    is_leaf: false,
    lead_time_days: 0,
    scrap_rate: 0,
    children: [],
  };

  for (const wo of workOrders) {
    if (!wo.material_id) continue;
    const bomTree = await explodeBOM(conn, wo.material_id, Number(wo.plan_qty || 0));
    if (combinedBomTree.children) {
      combinedBomTree.children.push(bomTree);
    }
  }

  const netRequirements = await calculateNetRequirements(conn, workOrderIds, warehouseId);

  const plannedOrders = await generatePlannedOrders(conn, workOrderIds, warehouseId);

  let purchaseRequests: { request_no: string; item_count: number }[] | undefined;
  if (autoGeneratePR && plannedOrders.length > 0) {
    purchaseRequests = await generatePurchaseRequestsFromMRP(
      conn,
      plannedOrders,
      operatorId,
      operatorName
    );
  }

  const totalShortages = netRequirements.filter((r) => r.shortage_warning).length;

  let totalPlannedAmount = 0;
  for (const order of plannedOrders) {
    const priceRows: Loose = await conn.query(
      `SELECT purchase_price FROM inv_material WHERE id = ? AND deleted = 0`,
      [order.material_id]
    );
    const price = priceRows.length > 0 ? Number(priceRows[0].purchase_price || 0) : 0;
    totalPlannedAmount += order.quantity * price;
  }

  return {
    bom_tree: combinedBomTree,
    net_requirements: netRequirements,
    planned_orders: plannedOrders,
    purchase_requests: purchaseRequests,
    summary: {
      total_materials: netRequirements.length,
      total_shortages: totalShortages,
      total_planned_qty:
        Math.round(plannedOrders.reduce((sum, o) => sum + o.quantity, 0) * 10000) / 10000,
      total_planned_amount: Math.round(totalPlannedAmount * 100) / 100,
    },
  };
}

/**
 * 多色套印工艺核心模块
 * 丝网印刷特色支持：色序管理、网版匹配、油墨消耗计算
 */

import { query, execute, transaction } from '@/lib/db';
import { secureLog } from '@/lib/logger';
import { CalcParamService } from '@/lib/calc-param-service';

// ============================================================
// 类型定义
// ============================================================

export interface ColorSequence {
  seqNo: number;
  colorName: string;
  colorCode?: string;
  screenPlateId?: number;
  screenPlateCode?: string;
  inkFormulaId?: number;
  inkFormulaName?: string;
  meshCount?: number; // 网目数
  estimatedDurationHours: number;
  equipmentTypeRequired: string;
  dependsOnSeq?: number; // 依赖前序色序号
  dryingTimeMinutes?: number; // 干燥时间
  setupTimeMinutes?: number; // 准备时间
}

export interface InkConsumption {
  inkFormulaId: number;
  inkName: string;
  colorName: string;
  theoreticalConsumption: number; // 理论消耗(g)
  actualConsumption: number; // 实际消耗(g，含损耗)
  unitPrice: number; // 单价
  totalCost: number; // 总成本
  coverageArea: number; // 覆盖面积(cm²)
  inkThickness: number; // 油墨厚度(μm)
  lossRate: number; // 损耗率
}

export interface MultiColorWorkOrder {
  workOrderId: number;
  workOrderNo: string;
  productName: string;
  planQty: number;
  colorSequences: ColorSequence[];
  printArea: number; // 印刷面积 cm²
  substrateType: string; // 承印材料类型
  totalColors: number;
}

// ============================================================
// 油墨消耗计算
// ============================================================

/**
 * 计算油墨消耗量
 * 公式：消耗量(g) = 印刷面积(cm²) × 油墨厚度(μm) × 油墨密度(g/cm³) × 数量 × (1 + 损耗率)
 */
export function calculateInkConsumption(
  printArea: number, // cm²
  inkThickness: number, // μm (微米)
  inkDensity: number, // g/cm³
  quantity: number,
  lossRate?: number // 损耗率，默认从 sys_calc_param 读取（默认 0.15）
): number {
  const effectiveLossRate =
    lossRate ?? CalcParamService.getCachedDecimal('printing.default_loss_rate', 0.15);
  // 厚度转换: μm → cm (1μm = 0.0001cm)
  const thicknessCm = inkThickness * 0.0001;
  // 体积 = 面积 × 厚度
  const volume = printArea * thicknessCm;
  // 质量 = 体积 × 密度
  const mass = volume * inkDensity;
  // 总消耗 = 单件质量 × 数量 × (1 + 损耗率)
  const totalConsumption = mass * quantity * (1 + effectiveLossRate);
  return Math.round(totalConsumption * 100) / 100;
}

/**
 * 获取油墨配方信息
 */
export async function getInkFormula(inkFormulaId: number): Promise<Loose> {
  const rows: Loose = await query(
    `SELECT id, formula_name, formula_code, ink_type, color_name, color_code,
            ink_density, default_thickness, default_loss_rate, unit_price, unit
     FROM prd_ink_formula
     WHERE id = ? AND deleted = 0`,
    [inkFormulaId]
  );
  return rows[0] || null;
}

/**
 * 计算多色套印油墨消耗明细
 */
export async function calculateMultiColorInkConsumption(
  workOrder: MultiColorWorkOrder
): Promise<InkConsumption[]> {
  const results: InkConsumption[] = [];

  for (const seq of workOrder.colorSequences) {
    if (!seq.inkFormulaId) continue;

    const formula = await getInkFormula(seq.inkFormulaId);
    if (!formula) {
      secureLog('warn', '油墨配方不存在', { inkFormulaId: seq.inkFormulaId, seqNo: seq.seqNo });
      continue;
    }

    const inkDensity = formula.ink_density || 1.2; // 默认密度 g/cm³
    const inkThickness = formula.default_thickness || 15; // 默认厚度 μm
    const lossRate =
      formula.default_loss_rate ??
      CalcParamService.getCachedDecimal('printing.default_loss_rate', 0.15);
    const unitPrice = formula.unit_price || 0;

    const theoreticalConsumption = calculateInkConsumption(
      workOrder.printArea,
      inkThickness,
      inkDensity,
      workOrder.planQty,
      0 // 理论值不含损耗
    );

    const actualConsumption = calculateInkConsumption(
      workOrder.printArea,
      inkThickness,
      inkDensity,
      workOrder.planQty,
      lossRate
    );

    results.push({
      inkFormulaId: seq.inkFormulaId,
      inkName: formula.formula_name,
      colorName: seq.colorName,
      theoreticalConsumption,
      actualConsumption,
      unitPrice,
      totalCost: Math.round(actualConsumption * unitPrice * 100) / 100,
      coverageArea: workOrder.printArea * workOrder.planQty,
      inkThickness,
      lossRate,
    });
  }

  return results;
}

// ============================================================
// 网版匹配与管理
// ============================================================

/**
 * 查找合适的网版
 */
export async function findSuitableScreenPlate(
  colorName: string,
  meshCount?: number,
  customerId?: number
): Promise<Loose[]> {
  let sql = `
    SELECT id, plate_code, plate_name, plate_type, mesh_count, size_spec,
           customer_id, product_name, remaining_count, status
    FROM prd_screen_plate
    WHERE deleted = 0 AND status = 1
      AND (remaining_count > 0 OR remaining_count IS NULL)
  `;
  const params: Loose[] = [];

  if (colorName) {
    sql += ` AND (plate_name LIKE ? OR product_name LIKE ?)`;
    params.push(`%${colorName}%`, `%${colorName}%`);
  }

  if (meshCount) {
    sql += ` AND mesh_count = ?`;
    params.push(meshCount);
  }

  if (customerId) {
    sql += ` AND (customer_id = ? OR customer_id IS NULL)`;
    params.push(customerId);
  }

  sql += ` ORDER BY 
    CASE WHEN customer_id = ? THEN 0 ELSE 1 END,
    remaining_count DESC,
    create_time DESC`;
  params.push(customerId || 0);

  const rows: Loose = await query(sql, params);
  return rows;
}

/**
 * 更新网版使用次数
 */
export async function updateScreenPlateUsage(
  plateId: number,
  usedCount: number = 1
): Promise<boolean> {
  try {
    await execute(
      `UPDATE prd_screen_plate SET
        used_count = COALESCE(used_count, 0) + ?,
        remaining_count = GREATEST(0, COALESCE(remaining_count, 0) - ?),
        update_time = NOW()
      WHERE id = ?`,
      [usedCount, usedCount, plateId]
    );
    return true;
  } catch (error) {
    secureLog('error', '更新网版使用次数失败', { error: (error as Error).message, plateId });
    return false;
  }
}

