/**
 * 获取工单色序详情（含网版、油墨信息）
 */
export async function getWorkOrderColorSequencesDetail(workOrderId: number): Promise<Loose[]> {
  const rows: Loose = await query(
    `SELECT
      cs.*,
      sp.plate_code as screen_plate_code,
      sp.plate_name as screen_plate_name,
      sp.mesh_count,
      sp.remaining_count as plate_remaining,
      if.formula_name as ink_formula_name,
      if.color_code as ink_color_code,
      if.ink_density,
      if.default_thickness,
      if.unit_price as ink_unit_price
    FROM prd_work_order_color_seq cs
    LEFT JOIN prd_screen_plate sp ON cs.screen_plate_id = sp.id
    LEFT JOIN prd_ink_formula if ON cs.ink_formula_id = if.id
    WHERE cs.work_order_id = ?
    ORDER BY cs.seq_no`,
    [workOrderId]
  );

  return rows;
}

/**
 * 计算工单总油墨成本
 */
export async function calculateWorkOrderInkCost(
  workOrderId: number,
  printArea: number,
  planQty: number
): Promise<{ totalCost: number; details: InkConsumption[] }> {
  const colorSeqs = await getWorkOrderColorSequencesDetail(workOrderId);

  const workOrder: MultiColorWorkOrder = {
    workOrderId,
    workOrderNo: '',
    productName: '',
    planQty,
    colorSequences: colorSeqs.map((cs: Loose) => ({
      seqNo: cs.seq_no,
      colorName: cs.color_name,
      inkFormulaId: cs.ink_formula_id,
      estimatedDurationHours: cs.estimated_duration_hours,
      equipmentTypeRequired: cs.equipment_type_required,
    })),
    printArea,
    substrateType: 'paper',
    totalColors: colorSeqs.length,
  };

  const details = await calculateMultiColorInkConsumption(workOrder);
  const totalCost = details.reduce((sum, d) => sum + d.totalCost, 0);

  return { totalCost, details };
}

const DB_NAME = 'dcprint-offline-scan';
const STORE_NAME = 'pending-scans';
const DB_VERSION = 1;

function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
        store.createIndex('qrCode', 'qrCode', { unique: false });
        store.createIndex('status', 'status', { unique: false });
        store.createIndex('createdAt', 'createdAt', { unique: false });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export interface OfflineScanItem {
  id?: number;
  qrCode: string;
  scanType: string;
  payload: Record<string, unknown>;
  status: 'pending' | 'syncing' | 'done' | 'failed';
  attempts: number;
  maxAttempts: number;
  error?: string;
  createdAt: number;
  updatedAt: number;
}

export async function enqueueScan(
  item: Omit<OfflineScanItem, 'id' | 'status' | 'attempts' | 'createdAt' | 'updatedAt'>
): Promise<number> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const record: OfflineScanItem = {
      ...item,
      status: 'pending',
      attempts: 0,
      maxAttempts: item.maxAttempts ?? 3,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };
    const req = store.add(record);
    req.onsuccess = () => resolve(req.result as number);
    req.onerror = () => reject(req.error);
  });
}

export async function getAllPendingScans(): Promise<OfflineScanItem[]> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const results: OfflineScanItem[] = [];
    const req = store.openCursor();
    req.onsuccess = () => {
      const cursor = req.result;
      if (cursor) {
        results.push(cursor.value);
        cursor.continue();
      } else {
        resolve(results);
      }
    };
    req.onerror = () => reject(req.error);
  });
}

export async function markScanDone(id: number): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const getReq = store.get(id);
    getReq.onsuccess = () => {
      const record = getReq.result;
      if (record) {
        record.status = 'done';
        record.updatedAt = Date.now();
        const putReq = store.put(record);
        putReq.onsuccess = () => resolve();
        putReq.onerror = () => reject(putReq.error);
      } else {
        resolve();
      }
    };
    getReq.onerror = () => reject(getReq.error);
  });
}

export async function markScanFailed(id: number, error: string): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const getReq = store.get(id);
    getReq.onsuccess = () => {
      const record = getReq.result;
      if (record) {
        record.attempts += 1;
        record.error = error;
        record.updatedAt = Date.now();
        if (record.attempts >= record.maxAttempts) {
          record.status = 'failed';
        } else {
          record.status = 'pending';
        }
        const putReq = store.put(record);
        putReq.onsuccess = () => resolve();
        putReq.onerror = () => reject(putReq.error);
      } else {
        resolve();
      }
    };
    getReq.onerror = () => reject(getReq.error);
  });
}

export async function removeScan(id: number): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const req = tx.objectStore(STORE_NAME).delete(id);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

export async function clearDoneScans(): Promise<void> {
  const db = await openDB();
  const all = await getAllPendingScans();
  const tx = db.transaction(STORE_NAME, 'readwrite');
  const store = tx.objectStore(STORE_NAME);
  for (const item of all) {
    if (item.status === 'done' || item.status === 'failed') {
      const id = item.id;
      if (id !== undefined) {
        store.delete(id);
      }
    }
  }
  return new Promise((resolve, reject) => {
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

interface QueryOptimization {
  useIndex: string[];
  forceIndex?: string;
  queryTimeout?: number;
  maxRows?: number;
}

interface ConnectionPoolConfig {
  max: number;
  min: number;
  idleTimeout: number;
  connectionLimit: number;
}

export const DB_OPTIMIZATION_CONFIG: ConnectionPoolConfig = {
  max: 20,
  min: 5,
  idleTimeout: 30000,
  connectionLimit: 50,
};

export const QUERY_TIMEOUTS = {
  FAST: 5000,
  NORMAL: 15000,
  SLOW: 30000,
  REPORT: 60000,
} as const;

export const INDEX_RECOMMENDATIONS: Record<string, QueryOptimization> = {
  orders: {
    useIndex: ['idx_orders_customer_id', 'idx_orders_status', 'idx_orders_date'],
    queryTimeout: QUERY_TIMEOUTS.NORMAL,
  },
  customers: {
    useIndex: ['idx_customers_code', 'idx_customers_name'],
    queryTimeout: QUERY_TIMEOUTS.FAST,
  },
  inventory: {
    useIndex: ['idx_inventory_material_id', 'idx_inventory_warehouse_id', 'idx_inventory_quantity'],
    queryTimeout: QUERY_TIMEOUTS.FAST,
  },
  production_orders: {
    useIndex: ['idx_production_status', 'idx_production_date', 'idx_production_product'],
    queryTimeout: QUERY_TIMEOUTS.NORMAL,
  },
  finance_transactions: {
    useIndex: ['idx_finance_date', 'idx_finance_type', 'idx_finance_account'],
    queryTimeout: QUERY_TIMEOUTS.SLOW,
  },
};

export function buildOptimizedQuery(
  baseQuery: string,
  table: string,
  conditions: Record<string, unknown>
): { query: string; params: unknown[] } {
  const optimization = INDEX_RECOMMENDATIONS[table];
  const params: unknown[] = [];
  const whereClauses: string[] = [];

  for (const [key, value] of Object.entries(conditions)) {
    if (value !== undefined && value !== null) {
      if (Array.isArray(value)) {
        if (value.length > 0) {
          whereClauses.push(`${key} IN (${value.map(() => '?').join(',')})`);
          params.push(...value);
        } else {
          whereClauses.push('1 = 0');
        }
      } else {
        whereClauses.push(`${key} = ?`);
        params.push(value);
      }
    }
  }

  let query = baseQuery;

  if (optimization?.forceIndex) {
    query = query.replace(/FROM\s+(\w+)/i, `FROM $1 FORCE INDEX (${optimization.forceIndex})`);
  }

  if (whereClauses.length > 0) {
    const whereClause = whereClauses.join(' AND ');
    query = query.includes('WHERE')
      ? query.replace(/WHERE/i, `WHERE ${whereClause} AND`)
      : `${query} WHERE ${whereClause}`;
  }

  return { query, params };
}

export class QueryAnalyzer {
  private slowQueries: Array<{
    query: string;
    duration: number;
    timestamp: Date;
  }> = [];

  private readonly SLOW_QUERY_THRESHOLD = 1000;

  logQuery(query: string, duration: number): void {
    if (duration > this.SLOW_QUERY_THRESHOLD) {
      this.slowQueries.push({
        query: query.substring(0, 200),
        duration,
        timestamp: new Date(),
      });

      if (this.slowQueries.length > 100) {
        this.slowQueries = this.slowQueries.slice(-50);
      }
    }
  }

  getSlowQueries(): typeof this.slowQueries {
    return [...this.slowQueries];
  }

  getSlowQueryStats(): {
    total: number;
    averageDuration: number;
    maxDuration: number;
  } {
    if (this.slowQueries.length === 0) {
      return { total: 0, averageDuration: 0, maxDuration: 0 };
    }

    const durations = this.slowQueries.map((q) => q.duration);
    return {
      total: this.slowQueries.length,
      averageDuration: durations.reduce((a, b) => a + b, 0) / durations.length,
      maxDuration: Math.max(...durations),
    };
  }
}

export const queryAnalyzer = new QueryAnalyzer();

export async function withQueryOptimization<T>(
  query: string,
  executor: () => Promise<T>,
  _table?: string
): Promise<T> {
  const startTime = Date.now();

  try {
    const result = await executor();
    const duration = Date.now() - startTime;

    queryAnalyzer.logQuery(query, duration);

    return result;
  } catch (error) {
    const duration = Date.now() - startTime;
    queryAnalyzer.logQuery(query, duration);
    throw error;
  }
}

export const READ_REPLICA_CONFIG = {
  enabled: false,
  host: process.env.DB_READ_HOST || process.env.DB_HOST,
  port: parseInt(process.env.DB_READ_PORT || process.env.DB_PORT || '3306'),
};

export function shouldUseReadReplica(query: string): boolean {
  if (!READ_REPLICA_CONFIG.enabled) return false;

  const upperQuery = query.toUpperCase().trim();
  return upperQuery.startsWith('SELECT') && !upperQuery.includes('FOR UPDATE');
}

type JobStatus = 'pending' | 'running' | 'done' | 'failed';

interface PrintJob<T = unknown> {
  id: string;
  payload: T;
  status: JobStatus;
  attempts: number;
  maxAttempts: number;
  error?: string;
  createdAt: number;
  startedAt?: number;
  finishedAt?: number;
}

interface PrintQueueOptions<T = unknown> {
  concurrency: number;
  maxAttempts: number;
  onRun: (job: PrintJob<T>) => Promise<void>;
  onError?: (job: PrintJob<T>, error: Error) => void;
}

export class PrintJobQueue<T = unknown> {
  private queue: PrintJob<T>[] = [];
  private running = 0;
  private options: Required<Pick<PrintQueueOptions<T>, 'onError'>> &
    Omit<PrintQueueOptions<T>, 'onError'>;

  constructor(options: PrintQueueOptions<T>) {
    this.options = {
      concurrency: options.concurrency ?? 2,
      maxAttempts: options.maxAttempts ?? 3,
      onRun: options.onRun,
      onError: options.onError ?? (() => {}),
    };
  }

  enqueue(payload: T): string {
    const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const job: PrintJob<T> = {
      id,
      payload,
      status: 'pending',
      attempts: 0,
      maxAttempts: this.options.maxAttempts,
      createdAt: Date.now(),
    };
    this.queue.push(job);
    this.drain();
    return id;
  }

  enqueueBatch(payloads: T[]): string[] {
    return payloads.map((p) => this.enqueue(p));
  }

  private async drain() {
    while (this.running < this.options.concurrency && this.queue.length > 0) {
      const job = this.queue.shift()!;
      this.running++;
      job.status = 'running';
      job.attempts += 1;
      job.startedAt = Date.now();

      try {
        await this.options.onRun(job);
        job.status = 'done';
        job.finishedAt = Date.now();
      } catch (error) {
        job.error = (error as Error).message;
        if (job.attempts < job.maxAttempts) {
          job.status = 'pending';
          this.queue.push(job);
        } else {
          job.status = 'failed';
          job.finishedAt = Date.now();
          this.options.onError(job, error as Error);
        }
      } finally {
        this.running--;
        this.drain();
      }
    }
  }

  get pending() {
    return this.queue.filter((j) => j.status === 'pending').length;
  }

  get runningCount() {
    return this.running;
  }

  get stats() {
    const all = this.queue;
    return {
      pending: all.filter((j) => j.status === 'pending').length,
      running: this.running,
      failed: all.filter((j) => j.status === 'failed').length,
      total: all.length,
    };
  }

  reset() {
    this.queue = [];
    this.running = 0;
  }
}

export const labelPrintQueue = new PrintJobQueue<unknown>({
  concurrency: 2,
  maxAttempts: 3,
  onRun: async (job) => {
    await new Promise((resolve) => setTimeout(resolve, 300));
  },
  onError(job: PrintJob<unknown>, error: Error) {
    console.error(`[PrintQueue] job=${job.id} failed:`, error.message);
  },
});

export interface ProductionJob {
  jobId: number;
  workOrderId: number;
  machineId: number;
  duration: number;
  dueDate: Date;
  priority: number;
  setupTime: number;
}

export interface ScheduledItem {
  job: ProductionJob;
  startTime: Date;
  endTime: Date;
}

export interface Schedule {
  jobs: ScheduledItem[];
  makespan: number;
  lateness: number;
  cost: number;
}

export class GeneticScheduler {
  private populationSize = 100;
  private generations = 50;
  private mutationRate = 0.15;
  private crossoverRate = 0.8;

  constructor(
    private jobs: ProductionJob[],
    private machines: { id: number; capacity: number }[]
  ) {}

  private initializePopulation(): number[][] {
    const population: number[][] = [];
    for (let i = 0; i < this.populationSize; i++) {
      const chromosome = [...Array(this.jobs.length).keys()];
      for (let j = chromosome.length - 1; j > 0; j--) {
        const k = Math.floor(Math.random() * (j + 1));
        [chromosome[j], chromosome[k]] = [chromosome[k], chromosome[j]];
      }
      population.push(chromosome);
    }
    return population;
  }

  private constructSchedule(chromosome: number[]): Schedule {
    const schedule: ScheduledItem[] = [];
    const machineEndTimes = new Map<number, Date>(this.machines.map((m) => [m.id, new Date()]));

    for (const jobIdx of chromosome) {
      const job = this.jobs[jobIdx];
      const machineStart = machineEndTimes.get(job.machineId) || new Date();
      const startTime = new Date(machineStart.getTime());
      const endTime = new Date(startTime.getTime() + (job.duration + job.setupTime) * 60000);
      schedule.push({ job, startTime, endTime });
      machineEndTimes.set(job.machineId, endTime);
    }

    const makespan =
      Math.max(...Array.from(machineEndTimes.values()).map((d) => d.getTime())) -
      new Date().getTime();
    let lateness = 0;
    for (const item of schedule) {
      if (item.endTime > item.job.dueDate) lateness++;
    }
    const cost = schedule.reduce((sum, item) => sum + item.job.setupTime * 50, 0);

    return { jobs: schedule, makespan, lateness, cost };
  }

  private evaluateFitness(chromosome: number[]): number {
    const schedule = this.constructSchedule(chromosome);
    return (
      0.4 * (schedule.makespan / 3600) + 0.35 * schedule.lateness * 1000 + 0.25 * schedule.cost
    );
  }

  private selectParent(population: number[][], fitnesses: number[]): number[] {
    const maxFitness = Math.max(...fitnesses);
    const weights = fitnesses.map((f) => maxFitness - f + 1);
    const totalWeight = weights.reduce((a, b) => a + b, 0);
    let random = Math.random() * totalWeight;
    for (let i = 0; i < population.length; i++) {
      random -= weights[i];
      if (random <= 0) return population[i];
    }
    return population[0];
  }

  private crossover(parent1: number[], parent2: number[]): number[] {
    const size = parent1.length;
    const cut1 = Math.floor(Math.random() * size);
    const cut2 = Math.floor(Math.random() * size);
    const [start, end] = cut1 < cut2 ? [cut1, cut2] : [cut2, cut1];
    const child: number[] = Array(size).fill(-1);
    for (let i = start; i < end; i++) child[i] = parent1[i];
    let pos = end;
    for (let i = 0; i < size; i++) {
      const gene = parent2[i];
      if (!child.includes(gene)) {
        if (pos >= size) pos = 0;
        child[pos] = gene;
        pos++;
      }
    }
    return child;
  }

  private mutate(chromosome: number[]): number[] {
    if (Math.random() > this.mutationRate) return chromosome;
    const idx1 = Math.floor(Math.random() * chromosome.length);
    const idx2 = Math.floor(Math.random() * chromosome.length);
    const mutated = [...chromosome];
    [mutated[idx1], mutated[idx2]] = [mutated[idx2], mutated[idx1]];
    return mutated;
  }

  async optimize(): Promise<Schedule> {
    let population = this.initializePopulation();
    let bestSchedule: Schedule | null = null;
    let bestFitness = Infinity;

    for (let gen = 0; gen < this.generations; gen++) {
      const fitnesses = population.map((chr) => this.evaluateFitness(chr));
      for (let i = 0; i < fitnesses.length; i++) {
        if (fitnesses[i] < bestFitness) {
          bestFitness = fitnesses[i];
          bestSchedule = this.constructSchedule(population[i]);
        }
      }
      const newPopulation: number[][] = [];
      const eliteSize = Math.ceil(this.populationSize * 0.1);
      const sortedIdx = [...Array(population.length).keys()].sort(
        (a, b) => fitnesses[a] - fitnesses[b]
      );
      for (let i = 0; i < eliteSize; i++) newPopulation.push([...population[sortedIdx[i]]]);
      while (newPopulation.length < this.populationSize) {
        if (Math.random() < this.crossoverRate) {
          const parent1 = this.selectParent(population, fitnesses);
          const parent2 = this.selectParent(population, fitnesses);
          newPopulation.push(this.mutate(this.crossover(parent1, parent2)));
        } else {
          newPopulation.push(this.mutate([...this.selectParent(population, fitnesses)]));
        }
      }
      population = newPopulation;
    }
    return bestSchedule || this.constructSchedule(population[0]);
  }
}

/**
 * @module 生产排程增强模块
 * @description 提供基于颜色工序依赖关系的生产排程功能，支持设备自动匹配、时间槽查找、优先级排序和甘特图数据生成。
 *   排程算法按顺序为每个工单的每道颜色工序分配合适的设备，考虑设备类型匹配、可用时间槽、工序依赖关系和工单优先级。
