  /** 设备名称 */
  equipment_name: string;
  /** 日期 */
  date: string;
  /** 开始小时（0-23） */
  hour_start: number;
  /** 结束小时（0-23） */
  hour_end: number;
  /** 可用产能 */
  available_capacity: number;
  /** 已排程的工单列表 */
  scheduled_orders: Array<{
    /** 工单 ID */
    work_order_id: number;
    /** 工单编号 */
    work_order_no: string;
    /** 颜色工序序号 */
