import { transaction } from '@/lib/db';
import { generateDocumentNo } from '@/lib/document-numbering';
import { PurBizStatus, PoStatus } from '@/lib/enum-status';

export interface ConvertResult {
  poId: number;
  poCode: string;
  lineCount: number;
  totalAmount: number;
}

export async function convertRequestToPurchaseOrder(requestId: number): Promise<ConvertResult> {
  return await transaction(async (conn) => {
    const [requestRows]: Loose = await conn.execute(
      `SELECT id, request_no, request_dept_id, requester_id, supplier_id, supplier_name, expected_date, status
       FROM pur_request WHERE id = ? AND deleted = 0`,
      [requestId]
    );

    if (!requestRows || requestRows.length === 0) {
      throw new Error('请购单不存在');
    }

    const request = requestRows[0];

    if (Number(request.status) !== PurBizStatus.APPROVED) {
      throw new Error(`请购单状态不是"已审批"，无法转采购。当前状态: ${request.status}`);
    }

    const [items]: Loose = await conn.execute(
      `SELECT id, line_no, material_id, material_code, material_name, material_spec, quantity, price, amount, unit
       FROM pur_request_item WHERE request_id = ? AND deleted = 0 ORDER BY line_no`,
      [requestId]
    );

    if (!items || items.length === 0) {
      throw new Error('请购单无物料明细');
    }

    const itemsWithoutMaterialId = items.filter((i: Loose) => !i.material_id);
    if (itemsWithoutMaterialId.length > 0) {
      throw new Error(`存在 ${itemsWithoutMaterialId.length} 条明细缺少物料ID，请先完善物料信息`);
    }

    const poCode = await generateDocumentNo('purchase_order');
    const totalAmount = items.reduce((sum: number, i: Loose) => sum + Number(i.amount || 0), 0);

    const [poResult]: Loose = await conn.execute(
      `INSERT INTO pur_order_std (po_code, request_id, supplier_id, supplier_name, order_date, delivery_date, total_amount, status, create_by)
       VALUES (?, ?, ?, ?, CURDATE(), ?, ?, ?, ?)`,
      [
        poCode,
        requestId,
        request.supplier_id || 0,
        request.supplier_name || '',
        request.expected_date || null,
        totalAmount,
        PoStatus.DRAFT,
        request.requester_id || null,
      ]
    );

    const poId = poResult.insertId;

    for (const item of items) {
      await conn.execute(
        `INSERT INTO pur_order_line_std (po_id, line_no, material_id, material_code, material_name, material_spec, order_qty, price, amount)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          poId,
          item.line_no,
          item.material_id,
          item.material_code,
          item.material_name,
          item.material_spec || '',
          item.quantity,
          item.price || 0,
          item.amount || 0,
        ]
      );
    }

    await conn.execute(`UPDATE pur_request SET status = ? WHERE id = ?`, [
      PurBizStatus.CONVERT_PO,
      requestId,
    ]);

    return {
      poId,
      poCode,
      lineCount: items.length,
      totalAmount,
    };
  });
}

export async function batchConvertRequestToPurchaseOrder(
  requestIds: number[]
): Promise<ConvertResult[]> {
  const results: ConvertResult[] = [];
  for (const id of requestIds) {
    try {
      const result = await convertRequestToPurchaseOrder(id);
      results.push(result);
    } catch (_e) {}
  }
  return results;
}

import { transaction } from '@/lib/db';
import { generateDocumentNo } from '@/lib/document-numbering';

export interface WorkOrderResult {
  workOrderId: number;
  workOrderNo: string;
  materialReqCount: number;
}

export async function createWorkOrderFromSalesOrder(
  salesOrderId: number
): Promise<WorkOrderResult> {
  return await transaction(async (conn) => {
    const [salesRows]: Loose = await conn.execute(
      `SELECT id, order_no, customer_id, total_amount FROM sal_order WHERE id = ? AND deleted = 0`,
      [salesOrderId]
    );

    if (!salesRows || salesRows.length === 0) {
      throw new Error('销售订单不存在');
    }

    const _salesOrder = salesRows[0];

    const [orderItems]: Loose = await conn.execute(
      `SELECT material_id, material_name, quantity FROM sal_order_detail WHERE order_id = ? AND deleted = 0 LIMIT 1`,
      [salesOrderId]
    );

    if (!orderItems || orderItems.length === 0) {
      throw new Error('销售订单无物料明细，无法创建工单');
    }

    const orderItem = orderItems[0];
    const productId = orderItem.material_id;

    if (!productId) {
      throw new Error('销售订单缺少产品ID，无法查找BOM');
    }

    const [bomRows]: Loose = await conn.execute(
      `SELECT id, bom_code, version FROM prd_bom_std WHERE product_id = ? AND status = 1 AND deleted = 0 LIMIT 1`,
      [productId]
    );

    if (!bomRows || bomRows.length === 0) {
      throw new Error(`产品(ID:${productId})未维护生效的BOM，无法创建工单`);
    }

    const bom = bomRows[0];
    const workOrderNo = await generateDocumentNo('work_order');

    const [woResult]: Loose = await conn.execute(
      `INSERT INTO prod_work_order (work_order_no, sales_order_id, product_id, product_name, bom_id, plan_qty, status, create_time)
       VALUES (?, ?, ?, ?, ?, ?, 0, NOW())`,
      [
        workOrderNo,
        salesOrderId,
        productId,
        orderItem.material_name || '',
        bom.id,
        orderItem.quantity,
      ]
    );

    const workOrderId = woResult.insertId;

    const [bomLines]: Loose = await conn.execute(
      `SELECT material_id, material_code, material_name, consumption_qty, waste_rate
       FROM prd_bom_line_std WHERE bom_id = ? AND deleted = 0`,
      [bom.id]
    );

    let materialReqCount = 0;
    for (const line of bomLines) {
      const wasteMultiplier = 1 + Number(line.waste_rate || 0) / 100;
      const requiredQty =
        Number(line.consumption_qty) * Number(orderItem.quantity) * wasteMultiplier;

      await conn.execute(
        `INSERT INTO prod_work_order_material_req (work_order_id, material_id, material_code, material_name, required_qty, unit)
         VALUES (?, ?, ?, ?, ?, (SELECT unit FROM inv_material_std WHERE id = ? LIMIT 1))`,
        [
          workOrderId,
          line.material_id,
          line.material_code,
          line.material_name,
          requiredQty,
          line.material_id,
        ]
      );
      materialReqCount++;
    }

    return {
      workOrderId,
      workOrderNo,
      materialReqCount,
    };
  });
}

/**
 * VNERP 软删除与单据作废工具
 * 功能：实现单据不可物理删除，只能作废的企业级审计要求
 * 原则：数据一旦产生，永久留存
 */

